    def __hash__(self):
        return hash((self.id, self.full_identity))
    @staticmethod
    def generate_id(email, full_identity, hostname):
        """Generate identifier for Person."""
        if email:
            return f"mailto:{email}"
        id = full_identity or str(uuid.uuid4().hex)
        id = quote(id, safe="")
