import pytest
from dictator.validators.replace import (
    FragmentReplace,
    AutoFragmentReplace,
    FragmentError,
)
from dictator.validators.lists import SubListValidator
from dictator.config import validate_config
def test_fragment_replace():
    """Test manual fragment replacement."""
    TEST_CONFIG = {
        "my_key": "my_value",
        "my_other_key": "REPLACETHIS_dontreplace",
    }
    TEST_REQ = {
        "my_key": str,
        "my_other_key": FragmentReplace({"REPLACETHIS": "my_key"}),
    }
    return validate_config(TEST_CONFIG, TEST_REQ)
def test_auto_fragment_replace():
    """Test automatic fragment replacement."""
    TEST_CONFIG = {
        "my_key": "my_value",
        "my_other_key": "${my_key}_dontreplace",
    }
    TEST_REQ = {"my_key": str, "my_other_key": AutoFragmentReplace()}
    return validate_config(TEST_CONFIG, TEST_REQ)
def test_parent_fragment_replace():
    """Test auto replacement with value from parent config."""
    TEST_CONFIG = {
        "my_key": "my_value",
        "other_keys": [{"my_other_key": "${..my_key}_blabla"}],
    }
    TEST_REQ = {
        "my_key": str,
        "other_keys": SubListValidator(
            {"my_other_key": AutoFragmentReplace()}
        ),
    }
    return validate_config(TEST_CONFIG, TEST_REQ)
def test_toplevel_fragment_replace():
    """Test auto replacement with value from toplevel config."""
    TEST_CONFIG = {
        "my_key": "my_value",
        "other_keys": [{"my_other_key": "${:my_key}_blabla"}],
    }
    TEST_REQ = {
        "my_key": str,
        "other_keys": SubListValidator(
            {"my_other_key": AutoFragmentReplace()}
        ),
    }
    return validate_config(TEST_CONFIG, TEST_REQ)
def test_fragment_replace_fail():
    """Test fragment replacement failure."""
    TEST_CONFIG = {
        "my_key": "my_value",
        "my_other_key": "${my_key2}_dontreplace",
    }
    TEST_REQ = {"my_key": str, "my_other_key": AutoFragmentReplace()}
    with pytest.raises(FragmentError):
        validate_config(TEST_CONFIG, TEST_REQ)
    return validate_config(TEST_CONFIG, TEST_REQ, my_key2="bla")
def test_fragment_key():
    """Test fragments which access keys."""
    TEST_CONFIG = {
        "my_key": {"foo": "bar"},
        "my_other_key": "${my_key::foo}_dontreplace",
    }
    TEST_CONFIG_2 = {
        "my_key": {"foo": "bar"},
        "my_other_key": "${:my_key::foo}_dontreplace",
    }
    TEST_REQ = {"my_key": dict, "my_other_key": AutoFragmentReplace()}
    validate_config(TEST_CONFIG, TEST_REQ)
    return validate_config(TEST_CONFIG_2, TEST_REQ)
if __name__ == "__main__":
    print(test_fragment_replace())
    print(test_auto_fragment_replace())
    print(test_parent_fragment_replace())
    print(test_fragment_replace_fail())
    print(test_toplevel_fragment_replace())
    print(test_fragment_key())

from voluptuous import Schema, Required, Optional, Invalid
from cloud99 import ACTOR_CLASSES
from cloud99.logging_setup import LOGGER
def validate_openrc(openrc):
    openrc_schema = Schema({
        Required("auth_url"): str,
        Required("username"): str,
        Required("password"): str,
        Required("region_name"): str,
        Required("tenant_name"): str,
        Required("https_cacert"): str,
        Optional("https_insecure"): bool,
    })
    LOGGER.debug("Validating openrc config")
    openrc_schema(openrc)
def validate_inventory(inventory):
    inventory_schema = Schema({
        Required("ip_or_hostname"): str,
        Required("username"): str,
        Required("password"): str,
        Required("role"): str,
    })
    LOGGER.debug("Validating inventory config")
    for host, config in inventory.items():
        inventory_schema(config)
def validate_disruptors(disruptors):
    _validate("disruptors", disruptors)
def validate_loaders(loaders):
    _validate("loaders", loaders)
def validate_monitors(monitors):
    _validate("monitors", monitors)
def _validate(ent_type, ent_list):
    LOGGER.debug("Validating {0} config".format(ent_type))
    for entity in ent_list:
        if type(entity) == str:
            continue
        for class_name, config in entity.items():
            actor_class = ACTOR_CLASSES.get(class_name, None)
            if not actor_class:
                raise Invalid("Unknown {0} {1}".format(ent_type, class_name))
            actor_class.schema(config)
validate = Schema({
    Required("openrc"): validate_openrc,
    Required("inventory"): validate_inventory,
    Required("disruptors"): validate_disruptors,
    Required("loaders"): validate_loaders,
    Required("monitors"): validate_monitors,
})

Utility functions for interacting with the Wistia API.
"""
from __future__ import annotations
from requests import HTTPError
from .api_data import WistiaDataApi
from .config import WistiaConfig
from .errors import NoSuchProject
from .log import LOG
from .models import (Container, Project, Video,
                     Customizations, Plugin, CaptionsV1)
class WistiaHelper:
    """
    Helper class for interacting with Wistia API and Wistia videos, which
    further simplifies any calls. This assumes that :class:`WistiaApi` has
    been configured as needed with the API token.
    """
    @staticmethod
    def is_archived_video(video_name: str) -> bool:
        """
        Check if this is an archived video which is automatically created by
        Wistia.
        In that case, we shouldn't order captions for it, since it's a copy of
        a video that was replaced with new media.
        Source: https://wistia.com/learn/product-updates/improved-library-management-tools  # noqa: E501
        """
        return '[Archived' in video_name and video_name[-1] == ']'
    @classmethod
    def video_exists(cls, video_id: str) -> bool:
        """
        Check if a video exists on Wistia.
        """
        status = WistiaDataApi.session().head(
            WistiaConfig.MEDIAS_SHOW_URL.format(media_id=video_id)
        ).status_code
        return not (status == 404)
    @classmethod
    def update_video_name(
        cls,
        video_id: str,
        video_title: str
    ) -> Video:
        """Update the title for a Wistia video."""
        return WistiaDataApi.update_video(video_id, video_title)
    @classmethod
    def has_captions_enabled(cls, video_id: str) -> bool:
        """
        Check if a video has captions available in the player settings.
        :return: A boolean indicating if the video player has captions
          available.
        """
        customizations = WistiaDataApi.get_customizations(video_id)
        return customizations.plugin.captions_v1.on is True
    @classmethod
    def enable_captions(
        cls,
        video_id: str,
        on_by_default: bool = False
    ):
        """
        Enable captions on a Wistia video.
        """
        data = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    on_by_default=on_by_default,
                    on=True
                )
            )
        )
        return WistiaDataApi.update_customizations(video_id, data)
    @classmethod
    def enable_ad(cls, video_id: str):
        """
        Enable audio descriptions on a Wistia video.
        """
        data = Customizations(audio_description_is_required=True)
        return WistiaDataApi.update_customizations(video_id, data)
    @classmethod
    def enable_captions_and_ad(
        cls,
        video_id: str,
        on_by_default: bool = False
    ):
        """
        Enable captions and AD on a Wistia video.
        """
        data = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    on_by_default=on_by_default,
                    on=True
                )
            ),
            audio_description_is_required=True
        )
        return WistiaDataApi.update_customizations(video_id, data)
    @classmethod
    def disable_captions_and_ad(
        cls,
        video_id: str,
        on_by_default: bool = False
    ):
        """
        Disable captions and AD on a Wistia video.
        """
        data = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    on_by_default=on_by_default,
                    on=False
                )
            ),
            audio_description_is_required=False
        )
        return WistiaDataApi.update_customizations(video_id, data)
    @classmethod
    def customize_video_on_wistia(
        cls,
        video_id: str,
        player_color: str
    ):
        """Set commonly used customization options for a media on Wistia."""
        customizations = {'playerColor': player_color}
        r = WistiaDataApi.session().put(
            WistiaConfig.CUSTOMIZATION_URL.format(media_id=video_id),
            json=customizations
        )
        try:
            r.raise_for_status()
        except HTTPError:
            LOG.error('Wistia Customizations API. status=%d text=%s',
                      r.status_code, r.text)
            raise
        LOG.info('[%s] Wistia: Customize Video success', r.elapsed)
        return r.json()
    @classmethod
    def project_details(
        cls,
        project_id: str,
        projects: Container[Project] | None = None
    ) -> Project:
        """Retrieve details on a Wistia project.
        The optional parameter `projects` contains info on all projects in
        the Wistia account, such as a response from the `Projects:list` API.
        :raises NoSuchProject: If the project doesn't exist on Wistia
        """
        if not projects:
            projects = WistiaDataApi.list_all_projects()
        for p in projects:
            if p.hashed_id == project_id:
                project = p
                break
        else:
            raise NoSuchProject(project_id)
        return project

from pathlib import Path
from tempfile import TemporaryDirectory
from typing import TYPE_CHECKING
try:
    from azure.core.exceptions import ResourceNotFoundError
except ImportError:
    pass
from ..cloudpath import CloudPath, NoStatError, register_path_class
if TYPE_CHECKING:
    from .azblobclient import AzureBlobClient
@register_path_class("azure")
class AzureBlobPath(CloudPath):
    """Class for representing and operating on Azure Blob Storage URIs, in the style of the Python
    standard library's [`pathlib` module](https://docs.python.org/3/library/pathlib.html).
    Instances represent a path in Blob Storage with filesystem path semantics, and convenient
    methods allow for basic operations like joining, reading, writing, iterating over contents,
    etc. This class almost entirely mimics the [`pathlib.Path`](https://docs.python.org/3/library/pathlib.html#pathlib.Path)
    interface, so most familiar properties and methods should be available and behave in the
    expected way.
    The [`AzureBlobClient`](../azblobclient/) class handles authentication with Azure. If a
    client instance is not explicitly specified on `AzureBlobPath` instantiation, a default client
    is used. See `AzureBlobClient`'s documentation for more details.
    """
    cloud_prefix: str = "az://"
    client: "AzureBlobClient"
    @property
    def drive(self) -> str:
        return self.container
    def is_dir(self) -> bool:
        return self.client._is_file_or_dir(self) == "dir"
    def is_file(self) -> bool:
        return self.client._is_file_or_dir(self) == "file"
    def mkdir(self, parents=False, exist_ok=False):
        # not possible to make empty directory on blob storage
        pass
    def touch(self):
        if self.exists():
            self.client._move_file(self, self)
        else:
            tf = TemporaryDirectory()
            p = Path(tf.name) / "empty"
            p.touch()
            self.client._upload_file(p, self)
            tf.cleanup()
    def stat(self):
        try:
            meta = self.client._get_metadata(self)
        except ResourceNotFoundError:
            raise NoStatError(
                f"No stats available for {self}; it may be a directory or not exist."
            )
        return os.stat_result(
            (
                None,  # mode
                None,  # ino
                self.cloud_prefix,  # dev,
                None,  # nlink,
                None,  # uid,
                None,  # gid,
                meta.get("size", 0),  # size,
                None,  # atime,
                meta.get("last_modified", 0).timestamp(),  # mtime,
                None,  # ctime,
            )
        )
    @property
    def container(self) -> str:
        return self._no_prefix.split("/", 1)[0]
    @property
    def blob(self) -> str:
        key = self._no_prefix_no_drive
