            CompilerSetting.from_jsonable_dict(config, bs) for bs in d["bad_settings"]
        ]
        good_settings = [
            CompilerSetting.from_jsonable_dict(config, gs) for gs in d["good_settings"]
        ]
        return bad_settings, good_settings
