class LimitOptions(BaseAwsOptions, BaseOptions):
    services: List[str]
    threshold: str
    # pylint: disable=too-many-arguments
    def __init__(
        self,
        verbose: bool,
        filters: List[Filterable],
        session,
        region_name,
