from __future__ import annotations
import typing as t
T = t.TypeVar("T")
def optional(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
) -> t.Optional[T]:
    """Get a value safely from the given dict using the given key.
    If the value is not found or is None, return it anyway.
    :raises: ValueError
    """
    if parser is None:
        value = dict_.get(key)
    else:
        value = parser(dict_, key)
    if value is not None and not isinstance(value, expect):
        raise ValueError(
            f"{dict_}: {repr(key)}: {repr(value)}: invalid type {type(value)}, expecting {expect}"
        )
    return t.cast(T, value)
def required(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
    default: t.Optional[T] = None,
    default_factory: t.Optional[t.Callable[[], T]] = None,
) -> T:
    """Get a value safely from the given dict using the given key.
    If the value is not found or is None, raise value error.
    :raises: ValueError
    """
    value: t.Optional[T] = optional(dict_, key, expect, parser=parser)
    if value is None:
        if default is not None:
            return default
        if default_factory is not None:
            return default_factory()
        raise ValueError(f"{dict_}: {repr(key)}: value is required")
    return value
def flatten_dict(d: t.Dict[t.Any, t.Any]) -> t.Dict[str, object]:
    """Flatten a nested dictionary.
    :param dist d: The nested dictionary to flatten.
    :rtype: dict
    :example:
    .. code-block:: python
        flatten_dict({"a": 1, "b": {"c": 2, "d": {"e": 3, "f": 4}}})
        # {
        #     "a": 1,
        #     "b:c": 2,
        #     "b:d:e": 3,
        #     "b:d:f": 4,
        # }
    """
    def items() -> t.Iterable[t.Tuple[str, object]]:
        for key, value in d.items():
            if not isinstance(key, str):
                raise ValueError(f"{key}: expected {str}, but got {type(key)}")
            if isinstance(value, dict):
                for subkey, subvalue in flatten_dict(value).items():
                    if not isinstance(subkey, str):
                        raise ValueError(
                            f"{subkey}: expected {str}, but got {type(subkey)}"
                        )
                    yield key + ":" + subkey, subvalue
            else:
                yield key, value
    return dict(items())
def unflatten_dict(d: t.Dict[object, object]) -> t.Dict[object, object]:
    """Convert a flattened dict back to nested dict.
    :param dict d: The flattened dict to convert.
    :rtype: dict
    :example:
    .. code-block:: python
        unflatten_dict({"a": 1, "b:c": 2, "b:d:e": 3, "b:d:f": 4})
        # {
        #   "a": 1,
        #   "b": {"c": 2, "d": {"e": 3, "f": 4}},
        # }
    """
    dict_: t.Dict[object, object] = {}
    for k, v in d.items():
        if not isinstance(k, str):
            raise ValueError(f"{k}: expected {str}, but got {type(k)}")
        if ":" in k:
            _dict: t.Union[object, t.Dict[object, object]] = dict_
            fields = k.split(":")
            count = len(fields)
            for i in range(count):
                field = fields[i]
                if not isinstance(_dict, dict):
                    continue
                if field not in _dict:
                    _dict[field] = v if i == (count - 1) else {}
                _dict = _dict[field]
        else:
            dict_[k] = v
    return dict_

from enum import Enum
from inspect import signature
from typing import List, Set, Optional, Union, Pattern, Type, Callable
class _SectionPatternRegisterer(type):
    def __init__(cls, name, bases, attrs):
        cls._patterns = []
        for key, val in attrs.items():
            properties = getattr(val, '_prop', None)
            if properties is not None:
                cls._patterns.append({'func': val, 'name': properties['name']})
def section_pattern(name: Optional[str] = None):
    if not (name is None or isinstance(name, str)):
        raise ValueError(f'name must be str but {type(name)} was given.')
    def _body(func: Callable[[str], Optional[Union[str, int]]]):
        nonlocal name
        n_params = len(signature(func).parameters)
        if n_params != 1:
            raise TypeError(
                '@section_pattern() must receive a function with 1 argument.')
        if name is None:
            name = func.__name__
        func._prop = {'name': name}
        return func
    return _body
def register_section_pattern(name: str, patterns: List[Pattern[str]], convert_fun: Callable[[str], int]):
    def _body(cls: Type[BaseSectionNumber]):
        nonlocal patterns, name, convert_fun
        if not issubclass(cls, BaseSectionNumber):
            raise TypeError(
                '@register_section_pattern may only be used on a class inheriting BaseSectionNumber')
        for pattern in patterns:
            def _extract_section_number_factory(pattern):
                # use factory pattern to embed pattern into _extract_section_number
                def _extract_section_number(text: str):
                    m = pattern.match(text)
                    return None if m is None else convert_fun(m.group('num'))
                return _extract_section_number
            extract_section_number = _extract_section_number_factory(pattern)
            extract_section_number._prop = {'name': name}
            cls._patterns.append(
                {'func': extract_section_number,
                 'name': name,
                 'pattern': pattern})
        return cls
    return _body
class BaseSectionNumber(object, metaclass=_SectionPatternRegisterer):
    def __init__(self, section_number_type: str, number: Union[int, str]):
        if not isinstance(section_number_type, str):
            raise TypeError(f'section_number_type must be str but {type(section_number_type)} was given.')
        if not isinstance(number, (int, str)):
            raise TypeError(f'number must be int or str but {type(number)} was given.')
        self.section_number_type: str = section_number_type
        self.number: Optional[int] = number
    def __eq__(self, other):
        return (type(self) == type(other) and
                self.number == other.number and
                self.section_number_type == other.section_number_type)
    @classmethod
    def extract_section_number(cls, text: str) -> List['BaseSectionNumber']:
        text = text.strip()
        candidates = []
        for pattern in cls._patterns:
            section_number = pattern['func'](text)
            if section_number is not None:
                candidates.append(cls(pattern['name'], section_number))
        return candidates
    def is_next_of(self, other: 'BaseSectionNumber') -> bool:
        return other.next() == self
    def next(self) -> 'BaseSectionNumber':
        if isinstance(self.number, str):
            # bullet points
            return self
        else:
            # Numbered list
            return type(self)(self.section_number_type, self.number + 1)
    @staticmethod
    def is_any_next_of(following_section_numbers: Set['BaseSectionNumber'],
                       section_numbers: Set['BaseSectionNumber']) -> bool:
        for s1 in section_numbers:
            for s2 in following_section_numbers:
                if s2.is_next_of(s1):
                    return True
        return False
    def __repr__(self):
        return f'{str(type(self))[:-1]} type={self.section_number_type}, number={self.number}>'
class NumberedListState(Enum):
    NO_NUM = 0
    CONSECUTIVE = 1
    DOWN = 2
    UP = 3
    UNKNOWN = 4
class MultiLevelNumberedList(object):
    def __init__(self):
        self._numbered_list: List[BaseSectionNumber] = []
    def try_append(self, candidates: Set[BaseSectionNumber]) -> NumberedListState:
        if len(candidates) == 0:
            return NumberedListState.NO_NUM
        for i, section_number_pre in enumerate(self._numbered_list[::-1]):
            for section_number in candidates:
                if section_number.is_next_of(section_number_pre):
                    self._numbered_list = self._numbered_list[:-i-1]
                    self._numbered_list.append(section_number)
                    if i == 0:
                        return NumberedListState.CONSECUTIVE
                    else:
                        return NumberedListState.UP
        # No valid continuation found... check if it is a new level
        for section_number in candidates:
            if isinstance(section_number.number, str) or section_number.number <= 1:
                self._numbered_list.append(section_number)
                return NumberedListState.DOWN
        return NumberedListState.UNKNOWN

from collections import defaultdict
import pytz
def get_now_with_tz() -> datetime.datetime:
    """Returns the current datetime (timezone aware)"""
    return datetime.datetime.now(tz=datetime.timezone.utc)
def localize_datetime(obj: datetime.datetime) -> datetime.datetime:
    """Returns a timezone aware object, localized to the system timezone"""
    return obj.astimezone()
def get_datetime_from_bungie_entry(string: str) -> datetime.datetime:
    """Converts the bungie string to a utc datetime obj"""
    return add_utc_tz(datetime.datetime.strptime(string, "%Y-%m-%dT%H:%M:%SZ"))
def add_utc_tz(obj: datetime.datetime) -> datetime.datetime:
    """Returns a timezone aware object, localized to utc"""
    return pytz.utc.localize(obj)
def defaultdictify(d: dict):
    """Converts a dictionary to a defaultdict. Returns a defaultdict"""
    if isinstance(d, dict):
        return defaultdict(lambda: None, {k: defaultdictify(v) for k, v in d.items()})
    elif isinstance(d, list):
        return [defaultdictify(e) for e in d]
    else:
        return d

class RequirementInfo:
    """
    Class to wrap pkg_resources.Requirement and represent package requirement information.
    https://setuptools.pypa.io/en/latest/pkg_resources.html#requirement-objects
    """
    ANY_VERSION = 'Any'
    _requirement = None
    def __init__(self, requirement: Optional = None):
        self._requirement = requirement
    @property
    def specifier(self) -> str:
        """Return required package version"""
        return str(self._requirement.specifier) if self._requirement.specifier else self.ANY_VERSION
    def __eq__(self, other: 'RequirementInfo') -> bool:
        """Compare two RequirementInfo objects"""
        return self._requirement == other._requirement

import click
import pandas
from dateutil import parser as dp

from pathlib import Path
from sketchy.utils import SketchySimulator, MutuallyExclusiveOption


@click.command()
@click.option(
    "--fastx",
    "-f",
    type=Path,
    help="Path to Fast{a,q} input file used in evaluation",
    default=None,
    required=True,
    cls=MutuallyExclusiveOption,
    mutually_exclusive=["index"]
)
@click.option(
    "--index",
    "-i",
    type=Path,
    help="Path to input file read index from `sketchy utils fx-sort`",
    default=None,
    required=False,
    cls=MutuallyExclusiveOption,
    mutually_exclusive=["fastx"]
)
@click.option(
    "--evaluation",
    "-e",
    type=Path,
    help="Path to evaluation file from `sketchy evaluate`",
    default=None,
    required=True,
)
def fx_time(fastx, evaluation, index):

    """ Experimental: compute time to prediction from evaluation output and input reads """

    sim = SketchySimulator(
        fastx=fastx, fastx_index=index
    )

    if index:
        fx = sim.fastx_index
    else:
        fx = sim.get_run_index()

    feature_predictions = pandas.read_csv(
        evaluation, sep='\t', names=['feature', 'prediction', 'first', 'stable']
    )

    for i, row in feature_predictions.iterrows():
        first_delta, stable_delta = compute_feature_time_delta(fx, row)
        print(
            f"{row['feature']}\t{row['prediction']}\t{row['first']}\t"
            f"{first_delta}\t{row['stable']}\t{stable_delta}"
        )


def compute_feature_time_delta(fx, row):

    try:
        first = int(
            row['first']
        )-1
        first_feature = fx.iloc[first]
    except (TypeError, KeyError, ValueError):
        first_feature = None

    try:
        stable = int(
            row['stable']
        ) - 1
        stable_feature = fx.iloc[stable]
    except (TypeError, KeyError, ValueError):
        stable_feature = None

    first_read = fx.iloc[0]

    if first_feature is not None:
        first_feature_delta = \
            dp.parse(first_feature.start_time) - dp.parse(first_read.start_time)
    else:
        first_feature_delta = None

    if stable_feature is not None:
        stable_feature_delta = \
            dp.parse(stable_feature.start_time) - dp.parse(first_read.start_time)
    else:
        stable_feature_delta = None

    return first_feature_delta, stable_feature_delta

def parse_rule(rule: str) -> Tuple[str, List[Tuple[int, str]]]:
    outer, contents = rule.split(" bags contain ")
    bags = [c.rsplit(maxsplit=1)[0].split(maxsplit=1) for c in contents.split(", ") if c != "no other bags."]
    bags = [(int(count), color) for count, color in bags]
    return outer, bags
with open("inputs/day07.txt", 'r') as f:
    rules: Dict[str, List[Tuple[int, str]]] = {k: v for k, v in (parse_rule(r) for r in f.read().splitlines())}
    def find_shiny_gold(start: str) -> bool:
        return start in rules and any(color == "shiny gold" or find_shiny_gold(color) for _, color in rules[start])
    def count_in_bag(start: str) -> int:
        return 1 + sum((count_in_bag(color) * count) for count, color in rules[start])
    part_a = sum(find_shiny_gold(bag) for bag in rules)
    print(f"part a: {part_a}")
    part_b = count_in_bag("shiny gold") - 1  # took me way to long to fix this off by 1
    print(f"part b: {part_b}")

