import six
def _safe_parse(content, split=': '):
  """Safely parse a 'key: value' list of strings from a command."""
  values = {}
  for l in content.splitlines():
    if not l:
      continue
    parts = l.split(split, 2)
    if len(parts) != 2:
      continue
    if six.PY2:
      parts = map(unicode, parts)
    values.setdefault(parts[0].strip(), parts[1])
  return values
