from __future__ import annotations
from typing import TYPE_CHECKING, List, Optional, Union, overload
if TYPE_CHECKING:
    from typing import Literal
class _InvalidResponseException(ValueError):
    pass
def query_yes_no(
    question: str,
    default: bool = True,
):
    """Query for a yes/no response on the CLI.
    Args:
        question (str): Question to ask.
        default (bool, optional): Default response. Defaults to True.
    Returns:
        bool: The response. 
    """
    if default is None:
        prompt = " [y/n] "
    elif default:
        prompt = " [Y/n] "
    else:
        prompt = " [y/N] "
    while True:
        choice = input(question + prompt).lower()
        if default is not None and choice == '':
            return default
        if "yes".startswith(choice.lower()):
            return True
        if "no".startswith(choice.lower()):
            return False
        print("Please respond with 'yes' or 'no' (or 'y' or 'n').")
def query_with_default(
    name: str,
    default_response: Optional[str] = None,
) -> str:
    """Query for a string response on the CLI.
    Args:
        question (str): Question to ask.
        default_response (Optional[str], optional):
            Default response. Set to None to require a response.
    Returns:
        str: The response.
    """
    default_response_pren = f" [{default_response}]" if default_response is not None else ""
    while True:
        try:
            response = input(f"{name}{default_response_pren}: ")
            if response.strip() == "":
                if default_response is None:
                    raise _InvalidResponseException("A response is required.")
                response = default_response
            return response
        except _InvalidResponseException as e:
            print(e.args[0])
def _parse_response(response: str, options: List[str]):
    option_lower_to_options = {x.lower(): x for x in options}
    try:
        response_num = int(response)
    except ValueError:
        response_val = response
    else:
        if response_num <= 0 or response_num > len(options):
            raise _InvalidResponseException(f"Value {response_num} is not a valid option")
        response_val = options[response_num - 1]
    if response_val.lower() in option_lower_to_options:
        return option_lower_to_options[response_val.lower()]
    raise _InvalidResponseException(f"Value {response_val} is not a valid option")
@overload
def query_with_options(name: str, options: List[str], default_response: Optional[str],
                       multiple_ok: Literal[False]) -> str:
    ...
@overload
def query_with_options(name: str, options: List[str], default_response: Optional[str],
                       multiple_ok: Literal[True]) -> List[str]:
    ...
def query_with_options(
    name: str,
    options: List[str],
    default_response: Optional[str],
    multiple_ok: bool,
) -> Union[str, List[str]]:
    """Interactively queries the user to select from a list of options.
    Args:
        name (str): Prompt for the user.
        options (List[str]): List of options.
        default_response (Optional[str]):
            Default response. Set to `None` to require a response.
        multiple_ok (bool):
            Whether the user can specify multiple options
            via a comma-seperated response.
    Returns:
        The response, or if ``multiple_ok`` is True, a list of responses.
    """
    default_response_pren = f" [{default_response}]" if default_response is not None else ""
    while True:
        try:
            print()
            print(name)
            print()
            for count, option in enumerate(options):
                print(f"{count + 1}): {option}")
            print()
            if multiple_ok:
                helptext = "Enter a number, value, or comma seperated numbers"
            else:
                helptext = "Enter a number or value"
            response = input(f"{helptext}{default_response_pren}: ").strip()
            if response == "":
                if default_response is None:
                    raise _InvalidResponseException("A response is required.")
                return [default_response] if multiple_ok else default_response
            if multiple_ok:
                responses = response.split(",")
                ans: List[str] = []
                for x in responses:
                    ans.append(_parse_response(x, options))
                return ans
            else:
                return _parse_response(response, options)
        except _InvalidResponseException as e:
            print(e.args[0])
            # try again in the while loop

from dataclasses import dataclass
from datetime import datetime
from typing import Union
from qiskit_experiments.exceptions import CalibrationError
@dataclass
class ParameterValue:
    """A data class to store parameter values."""
    # Value assumed by the parameter
    value: Union[int, float, complex] = None
    # Data time when the value of the parameter was generated
    date_time: datetime = datetime.fromtimestamp(0)
    # A bool indicating if the parameter is valid
    valid: bool = True
    # The experiment from which the value of this parameter was generated.
    exp_id: str = None
    # The group of calibrations to which this parameter belongs
    group: str = "default"
    def __post_init__(self):
        """
        Ensure that the variables in self have the proper types. This allows
        us to give strings to self.__init__ as input which is useful when loading
        serialized parameter values.
        """
        if isinstance(self.valid, str):
            if self.valid == "True":
                self.valid = True
            else:
                self.valid = False
        if isinstance(self.value, str):
            self.value = self._validated_value(self.value)
        if isinstance(self.date_time, str):
            base_fmt = "%Y-%m-%d %H:%M:%S.%f"
            zone_fmts = ["%z", "", "Z"]
            for time_zone in zone_fmts:
                date_format = base_fmt + time_zone
                try:
                    self.date_time = datetime.strptime(self.date_time, date_format)
                    break
                except ValueError:
                    pass
            else:
                formats = list(base_fmt + zone for zone in zone_fmts)
                raise CalibrationError(
                    f"Cannot parse {self.date_time} in either of {formats} formats."
                )
        if not isinstance(self.value, (int, float, complex)):
            raise CalibrationError(f"Values {self.value} must be int, float or complex.")
        if not isinstance(self.date_time, datetime):
            raise CalibrationError(f"Datetime {self.date_time} must be a datetime.")
        if not isinstance(self.valid, bool):
            raise CalibrationError(f"Valid {self.valid} is not a boolean.")
        if self.exp_id and not isinstance(self.exp_id, str):
            raise CalibrationError(f"Experiment id {self.exp_id} is not a string.")
        if not isinstance(self.group, str):
            raise CalibrationError(f"Group {self.group} is not a string.")
    @staticmethod
    def _validated_value(value: str) -> Union[int, float, complex]:
        """
        Convert the string representation of value to the correct type.
        Args:
            value: The string to convert to either an int, float, or complex.
        Returns:
            value converted to either int, float, or complex.
        Raises:
            CalibrationError: If the conversion fails.
        """
        try:
            return int(value)
        except ValueError:
            pass
        try:
            return float(value)
        except ValueError:
            pass
        try:
            return complex(value)
        except ValueError as val_err:
            raise CalibrationError(
                f"Could not convert {value} to int, float, or complex."
            ) from val_err

import functools
import logging
import pickle
import numpy as np
import torch
import torch.distributed as dist
_LOCAL_PROCESS_GROUP = None
def get_world_size() -> int:
    if not dist.is_available():
        return 1
    if not dist.is_initialized():
        return 1
    return dist.get_world_size()
def get_rank() -> int:
    if not dist.is_available():
        return 0
    if not dist.is_initialized():
        return 0
    return dist.get_rank()
def get_local_rank() -> int:
    if not dist.is_available():
        return 0
    if not dist.is_initialized():
        return 0
    assert _LOCAL_PROCESS_GROUP is not None
    return dist.get_rank(group=_LOCAL_PROCESS_GROUP)
def get_local_size() -> int:
    if not dist.is_available():
        return 1
    if not dist.is_initialized():
        return 1
    return dist.get_world_size(group=_LOCAL_PROCESS_GROUP)
def is_main_process() -> bool:
    return get_rank() == 0
def synchronize():
    if not dist.is_available():
        return
    if not dist.is_initialized():
        return
    world_size = dist.get_world_size()
    if world_size == 1:
        return
    dist.barrier()
@functools.lru_cache()
def _get_global_gloo_group():
    if dist.get_backend() == "nccl":
        return dist.new_group(backend="gloo")
    else:
        return dist.group.WORLD
def _serialize_to_tensor(data, group):
    backend = dist.get_backend(group)
    assert backend in ["gloo", "nccl"]
    device = torch.device("cpu" if backend == "gloo" else "cuda")
    buffer = pickle.dumps(data)
    if len(buffer) > 1024 ** 3:
        logger = logging.getLogger(__name__)
        logger.warning(
            "Rank {} trying to all-gather {:.2f} GB of data on device {}".format(
                get_rank(),
                len(buffer) / (1024 ** 3),
                device
            )
        )
    storage = torch.ByteStorage.from_buffer(buffer)
    tensor = torch.ByteTensor(storage).to(device=device)
    return tensor
def _pad_to_largest_tensor(tensor, group):
    world_size = dist.get_world_size(group=group)
    assert world_size >= 1, \
        "comm.gather/all_gather must be called from ranks within the given group!"
    local_size = torch.tensor([tensor.numel()], dtype=torch.int64, device=tensor.device)
    size_list = [
        torch.zeros([1], dtype=torch.int64, device=tensor.device) for _ in range(world_size)
    ]
    dist.all_gather(size_list, local_size, group=group)
    size_list = [int(size.item()) for size in size_list]
    max_size = max(size_list)
    if local_size != max_size:
        padding = torch.zeros((max_size - local_size,), dtype=torch.uint8, device=tensor.device)
        tensor = torch.cat((tensor, padding), dim=0)
    return size_list, tensor
def all_gather(data, group=None):
    if get_world_size() == 1:
        return [data]
    if group is None:
        group = _get_global_gloo_group()
    if dist.get_world_size(group) == 1:
        return [data]
    tensor = _serialize_to_tensor(data, group)
    size_list, tensor = _pad_to_largest_tensor(tensor, group)
    max_size = max(size_list)
    tensor_list = [
        torch.empty((max_size,), dtype=torch.uint8, device=tensor.device) for _ in size_list
    ]
    dist.all_gather(tensor_list, tensor, group=group)
    data_list = []
    for size, tensor in zip(size_list, tensor_list):
        buffer = tensor.cpu().numpy().tobytes()[:size]
        data_list.append(pickle.loads(buffer))
    return data_list
def gather(data, dst=0, group=None):
    if get_world_size() == 1:
        return [data]
    if group is None:
        group = _get_global_gloo_group()
    if dist.get_world_size(group=group) == 1:
        return [data]
    rank = dist.get_rank(group=group)
    tensor = _serialize_to_tensor(data, group)
    size_list, tensor = _pad_to_largest_tensor(tensor, group)
    if rank == dst:
        max_size = max(size_list)
        tensor_list = [
            torch.empty((max_size,), dtype=torch.uint8, device=tensor.device) for _ in size_list
        ]
        dist.gather(tensor, tensor_list, dst=dst, group=group)
        data_list = []
        for size, tensor in zip(size_list, tensor_list):
            buffer = tensor.cpu().numpy().tobytes()[:size]
            data_list.append(pickle.loads(buffer))
        return data_list
    else:
        dist.gather(tensor, [], dst=dst, group=group)
        return []
def shared_random_seed():
    ints = np.random.randint(2 ** 31)
    all_ints = all_gather(ints)
    return all_ints[0]
def reduce_dict(input_dict, average=True):
    world_size = get_world_size()
    if world_size < 2:
        return input_dict
    with torch.no_grad():
        names = []
        values = []
        for k in sorted(input_dict.keys()):
            names.append(k)
            values.append(input_dict[k])
        values = torch.stack(values, dim=0)
        dist.reduce(values, dst=0)
        if dist.get_rank() == 0 and average:
            values /= world_size
        reduced_dict = {k: v for k, v in zip(names, values)}
    return reduced_dict

