from .errors import ConfigurationError
from docker.utils.ports import build_port_bindings
class ServicePort(namedtuple('_ServicePort', 'target published protocol mode external_ip')):
    def __new__(cls, target, published, *args, **kwargs):
        try:
            if target:
                target = int(target)
        except ValueError:
            raise ConfigurationError('Invalid target port: {}'.format(target))
        if published:
            if isinstance(published, str) and '-' in published:  # "x-y:z" format
                a, b = published.split('-', 1)
                if not a.isdigit() or not b.isdigit():
                    raise ConfigurationError('Invalid published port: {}'.format(published))
            else:
                try:
                    published = int(published)
                except ValueError:
                    raise ConfigurationError('Invalid published port: {}'.format(published))
        return super().__new__(
            cls, target, published, *args, **kwargs
        )
    @classmethod
    def parse(cls, spec):
        if isinstance(spec, cls):
            # When extending a service with ports, the port definitions have already been parsed
            return [spec]
        if not isinstance(spec, dict):
            result = []
            try:
                for k, v in build_port_bindings([spec]).items():
                    if '/' in k:
                        target, proto = k.split('/', 1)
                    else:
                        target, proto = (k, None)
                    for pub in v:
                        if pub is None:
                            result.append(
                                cls(target, None, proto, None, None)
                            )
                        elif isinstance(pub, tuple):
                            result.append(
                                cls(target, pub[1], proto, None, pub[0])
                            )
                        else:
                            result.append(
                                cls(target, pub, proto, None, None)
                            )
            except ValueError as e:
                raise ConfigurationError(str(e))
            return result
        return [cls(
            spec.get('target'),
            spec.get('published'),
            spec.get('protocol'),
            spec.get('mode'),
            None
        )]
    @property
    def merge_field(self):
        return (self.target, self.published, self.external_ip, self.protocol)
    def repr(self):
        return {
            k: v for k, v in zip(self._fields, self) if v is not None
        }
    def legacy_repr(self):
        return normalize_port_dict(self.repr())
def normalize_port_dict(port):
    return '{external_ip}{has_ext_ip}{published}{is_pub}{target}/{protocol}'.format(
        published=port.get('published', ''),
        is_pub=(':' if port.get('published') is not None or port.get('external_ip') else ''),
        target=port.get('target'),
        protocol=port.get('protocol', 'tcp'),
        external_ip=port.get('external_ip', ''),
        has_ext_ip=(':' if port.get('external_ip') else ''),
    )

filepath_data = f"input/{day}.txt"
filepath_example = f"input/{day}-example.txt"
def data_from_file(filename: str) -> tuple[list[str], list[list[list[str]]]]:
    boards: list[list[list[str]]] = []
    with open(filename) as f:
        drawn_numbers_line = f.readline().strip()
        drawn_numbers: list[str] = drawn_numbers_line.split(",")
        board: list[list[str]] = []
        board_row_index = 0
        for line in f:
            board_row_index += 1
            if board_row_index == 1:
                continue
            board.append(line.split())
            if board_row_index == 6:
                boards.append(board)
                board = []
                board_row_index = 0
                continue
    return drawn_numbers, boards
def get_input_data() -> tuple[list[str], list[list[list[str]]]]:
    return data_from_file(filepath_data)
def get_example_data() -> tuple[list[str], list[list[list[str]]]]:
    return data_from_file(filepath_example)
def draw_number(
    drawn_number: str, boards: list[list[list[str]]], last_winning_board_mode: bool = False
) -> tuple[int, list[list[list[str]]]]:
    board_idxs_to_ignore: list[int] = []
    for board_idx, board in enumerate(boards):
        for row_idx, row in enumerate(board):
            if board_idx in board_idxs_to_ignore:
                continue
            for column_idx, number in enumerate(row):
                if board_idx in board_idxs_to_ignore:
                    continue
                if number == drawn_number:
                    boards[board_idx][row_idx][column_idx] = "x"
                    if has_board_won(board, column_idx, row_idx):
                        is_last_winning_board_mode_and_last_board = last_winning_board_mode and len(boards) == 1
                        if not last_winning_board_mode or is_last_winning_board_mode_and_last_board:
                            return calc_score_of_board(board, int(drawn_number)), boards
                        else:  # last_winning_board_mode but there is more than one board left
                            board_idxs_to_ignore.append(board_idx)
    board_idxs_to_ignore = list(set(board_idxs_to_ignore))
    board_idxs_to_ignore.sort(reverse=True)
    for board_idx in board_idxs_to_ignore:
        del boards[board_idx]
    return 0, boards
def has_board_won(board: list[list[str]], column_idx: int, row_idx: int) -> bool:
    won_horizontal = True
    for n in range(0, 5):
        if board[row_idx][n] != "x":
            won_horizontal = False
            break
    won_vertical = True
    for n in range(0, 5):
        if board[n][column_idx] != "x":
            won_vertical = False
            break
    return won_horizontal or won_vertical
def calc_score_of_board(board: list[list[str]], last_drawn: int) -> int:
    sum = 0
    for row in board:
        for n in row:
            if n != "x":
                sum += int(n)
    return sum * last_drawn
def calc_score_of_winning_board(
    drawn_numbers: list[str], boards: list[list[list[str]]], last_winning_board_mode: bool = False
) -> int:
    boards_left = boards
    for n in drawn_numbers:
        score, boards_left = draw_number(n, boards_left, last_winning_board_mode)
        if score > 0:
            return score
    return 0
if __name__ == "__main__":
    print(day)
    drawn_numbers, boards = get_input_data()
    part1 = calc_score_of_winning_board(drawn_numbers, boards)
    print(f"Part 1: {part1}")
    drawn_numbers, boards = get_input_data()
    part2 = calc_score_of_winning_board(drawn_numbers, boards, last_winning_board_mode=True)
    print(f"Part 2: {part2}")
    print()

from urllib.request import urlopen, URLError
def pytest_terminal_summary(terminalreporter, exitstatus=None): # pylint: disable=unused-argument
    _add_patterns()
    tr = terminalreporter
    passes = len(tr.stats.get('passed', []))
    fails = len(tr.stats.get('failed', []))
    skips = len(tr.stats.get('deselected', []))
    errors = len(tr.stats.get('error', []))
    if (passes or skips) and not (fails or errors):
        _pattern('pytest-success')
    else:
        _pattern('pytest-failure')
def _add_patterns():
    _blink('pattern/add?pname=pytest-success&pattern=3,%2300ff00,1.5,%23000000,0.5')
    _blink('pattern/add?pname=pytest-failure&pattern=1,%23ff0000,0.3,1,%23ff0000,0.3,2,%23000000,0.1,0,%23ff0000,0.3,2,%23ff0000,0.3,1,%23000000,0.1,0')
def _pattern(name):
    _blink('pattern/play?pname={}'.format(name))
def _blink(command):
    try:
        urlopen('http://localhost:8934/blink1/{}'.format(command))
    except URLError as e:
        pass

