    ).build()
    df = Regions(
        LevelKind.city,
        [
            make_region('Los Angeles', 'Los Angeles', '1', []),
            make_region('New York', 'New York', '2', []),
            make_region('Las Vegas', 'Las Vegas', '3', []),
            make_region('Los Angeles', 'Los Angeles', '1', []),
        ]
    ).centroids()
