class Win32Console(_Console):
    def __init__(self) -> None:
        self._range_height = 0
        self._fill_char = ' '
        self._executor = None
        self._output = None
        self._saved_output_mode = None
        self._buffer_info = _ConsoleScreenBufferInfo()
        self._input_handler = None
        self._input_future = None
        self._executor = _Executor(max_workers=1)
        input_ = _CreateFileW('CONIN$', 0xc0000000, 0x3,
                              _byref(_SecurityAttributes(None, True)),
                              3, 0x80, None)
        self._output = _CreateFileW('CONOUT$', 0xc0000000, 0x3,
                                    _byref(_SecurityAttributes(None, True)),
                                    3, 0x80, None)
        mode = _DWORD()
        _GetConsoleMode(self._output, _byref(mode))
        self._saved_output_mode = mode.value
        _SetConsoleMode(self._output, self._saved_output_mode | 0x0018)
        self._update_buffer_info()
        self._input_handler = _ConsoleInputHandler(input_, close=True)
        loop = _asyncio.get_event_loop()
        self._input_future = loop.run_in_executor(self._executor,
                                                  self._input_handler.handle)
    def __del__(self) -> None:
        self.close(timeout=0)
    # noinspection PyBroadException
    def close(self, timeout: float = 0.1) -> None:
        input_future, self._input_future = self._input_future, None
        input_handler, self._input_handler = self._input_handler, None
        output, self._output = self._output, None
        executor, self._executor = self._executor, None
        self._buffer_info = None
        if input_future is not None:
            try:
                input_future.cancel()
            except Exception:
                _log.exception("unable to cancel input handler during cleanup")
        if input_handler is not None:
            try:
                input_handler.shutdown()
            except Exception:
                _log.exception(
                    "unable to shutdown input handler during cleanup"
                )
        if (self._saved_output_mode is not None and
                output is not None and output != _INVALID_HANDLE_VALUE.value):
            try:
                _SetConsoleMode(output, self._saved_output_mode)
            except Exception:
                _log.exception(
                    "unable to reset console output mode during cleanup"
                )
        if executor is not None:
            try:
                executor.shutdown(wait=False)
            except Exception:
                _log.exception("unable to shutdown executor during cleanup")
    def _update_buffer_info(self) -> None:
        _GetConsoleScreenBufferInfo(self._output, _byref(self._buffer_info))
    def print(self, s: str, flush: bool = False) -> None:
        print(s, flush=flush)
    def get_width(self) -> int:
        return self._buffer_info.dwSize.X
    def get_height(self) -> int:
        window = self._buffer_info.srWindow
        return window.Bottom - window.Top + 1
    def get_colors(self) -> int:
        return 16
    def request_size(self, height: int) -> int:
        if height < 0:
            raise ValueError("n cannot be negative")
        max_y = self._buffer_info.dwSize.Y - 1
        max_height = min(max_y, max(self._buffer_info.srWindow.Bottom -
                                    self._buffer_info.srWindow.Top, 3))
        if height > max_height:
            height = max_height
        if height == self._range_height:
            return height
        max_x = self._buffer_info.dwSize.X - 1
        y = self._buffer_info.dwCursorPosition.Y
        missing_lines = (height - self._range_height) - (max_y - y)
        if missing_lines > 0:
            _ScrollConsoleScreenBufferW(
                    self._output, _SMALL_RECT(0, 0, max_x, y - 1), None,
                    _Coord(0, -missing_lines),
                    _CharInfo(self._fill_char, self._buffer_info.wAttributes)
            )
            self._range_height += missing_lines
            if self._range_height == height:
                return height
        delta = height - self._range_height
        if delta < 0:
            y += delta
        scroll_region = _SMALL_RECT(0, y, max_x, max_y)
        _ScrollConsoleScreenBufferW(
                self._output, scroll_region, scroll_region,
                _Coord(0, y + delta),
                _CharInfo(self._fill_char, self._buffer_info.wAttributes)
        )
        self._range_height += delta
        self._buffer_info.dwCursorPosition.Y += delta
        _SetConsoleCursorPosition(self._output,
                                  self._buffer_info.dwCursorPosition)
        assert self._range_height == height
        return height
    def line_at(self, y: int, text: str, tail: int = 0) -> None:
        y += self._buffer_info.dwCursorPosition.Y - self._range_height
        n = len(text)
        written = _DWORD()
        _WriteConsoleOutputCharacterW(self._output, text, n, _Coord(0, y),
                                      _byref(written))
        if tail <= 0:
            return
        _FillConsoleOutputCharacterW(self._output, self._fill_char, tail,
                                     _Coord(n, y), _byref(written))
    def register_input_callback(self, callback: _Callable) -> _Any:
        return self._input_handler.register_callback(callback)
    def unregister_input_callback(self, token: _Any) -> None:
        self._input_handler.unregister_callback(token)
class _ConsoleInputHandler:
    def __init__(self, handle, close=False) -> None:
        self._handle = handle
        self._close = close
        self._saved_mode = None
        self._callback = None
        self._callback_lock = None
        self._shutdown_signal = None
        mode = _DWORD()
        _GetConsoleMode(self._handle, _byref(mode))
        self._saved_mode = mode.value
        _SetConsoleMode(self._handle, self._saved_mode & ~0x0007 | 0x0018)
        self._callback_lock = _threading.Lock()
        self._shutdown_signal = _threading.Event()
    # noinspection PyBroadException
    def __del__(self) -> None:
        handle, self._handle = self._handle, None
        saved_mode, self._saved_mode = self._saved_mode, None
        if handle is not None and handle != _INVALID_HANDLE_VALUE.value:
            try:
                _FlushConsoleInputBuffer(handle)
            except Exception:
                _log.exception(
                    "unable to flush console input buffer during cleanup"
                )
            if saved_mode is not None:
                try:
                    _SetConsoleMode(handle, saved_mode)
                except Exception:
                    _log.exception(
                        "unable to reset console input mode during cleanup"
                    )
            if self._close:
                try:
                    _CloseHandle(handle)
                except Exception:
                    _log.exception(
                        "unable to close console input handle during cleanup"
                    )
    def shutdown(self) -> None:
        self._shutdown_signal.set()
        input_record = _InputRecord(EventType=0x1, KeyEvent=_KeyEventRecord(
            wVirtualKeyCode=0xff,
            wVirtualScanCode=0xffff,
        ))
        written = _DWORD()
        _WriteConsoleInputW(self._handle, input_record, 1, _byref(written))
    def handle(self) -> None:
        # noinspection PyTypeChecker,PyCallingNonCallable
        buffer = (_InputRecord * 100)()
        read = _DWORD()
        while not self._shutdown_signal.is_set():
            _ReadConsoleInputW(self._handle, buffer, len(buffer), _byref(read))
            if self._shutdown_signal.is_set():
                break
            for input_record in buffer[:read.value]:
                if input_record.EventType != 0x0001:
                    continue
                key_event = input_record.KeyEvent
                if not key_event.bKeyDown:
                    continue
                vk = key_event.wVirtualKeyCode
                if vk == 0x1b:
                    event = _events.QuitEvent()
                elif vk == 0x26:
                    event = _events.UpNavEvent()
                elif vk == 0x28:
                    event = _events.DownNavEvent()
                else:
                    continue
                with self._callback_lock:
                    if self._callback is None:
                        continue
                    loop, callback = self._callback
                loop.call_soon_threadsafe(callback, event)
    def register_callback(self, callback: _Callable) -> _Any:
        pair = _asyncio.get_running_loop(), callback
        with self._callback_lock:
            if self._callback is not None:
                raise NotImplementedError("cannot register multiple callbacks")
            self._callback = pair
        return hash(pair)
    def unregister_callback(self, token: _Any) -> None:
        with self._callback_lock:
            if self._callback is None:
                raise ValueError("no callback has been registered")
            if hash(self._callback) != token:
                raise ValueError("token mismatch")
            self._callback = None

from __future__ import unicode_literals
from ipaddress import ip_address
from flask import has_request_context, request, session
from sqlalchemy.ext.associationproxy import association_proxy
from sqlalchemy.ext.declarative import declared_attr
from indico.core.db import db
from indico.core.db.sqlalchemy import PyIPNetwork
from indico.core.db.sqlalchemy.principals import PrincipalType
from indico.util.string import format_repr, return_ascii
class IPNetworkGroup(db.Model):
    __tablename__ = 'ip_network_groups'
    principal_type = PrincipalType.network
    principal_order = 1
    is_group = False
    is_network = True
    is_single_person = False
    is_event_role = False
    is_category_role = False
    is_registration_form = False
    @declared_attr
    def __table_args__(cls):
        return (db.Index('ix_uq_ip_network_groups_name_lower', db.func.lower(cls.name), unique=True),
                {'schema': 'indico'})
    id = db.Column(
        db.Integer,
        primary_key=True
    )
    name = db.Column(
        db.String,
        nullable=False
    )
    description = db.Column(
        db.Text,
        nullable=False,
        default=''
    )
    #: Whether the network group is hidden in ACL forms
    hidden = db.Column(
        db.Boolean,
        nullable=False,
        default=False
    )
    #: Grants all IPs in the network group read access to all attachments
    attachment_access_override = db.Column(
        db.Boolean,
        nullable=False,
        default=False
    )
    _networks = db.relationship(
        'IPNetwork',
        lazy=False,
        cascade='all, delete-orphan',
        collection_class=set,
        backref=db.backref(
            'group',
            lazy=True
        )
    )
    networks = association_proxy('_networks', 'network', creator=lambda v: IPNetwork(network=v))
    # relationship backrefs:
    # - in_category_acls (CategoryPrincipal.ip_network_group)
    # - in_event_acls (EventPrincipal.ip_network_group)
    @return_ascii
    def __repr__(self):
        return format_repr(self, 'id', 'name', hidden=False, attachment_access_override=False)
    def __contains__(self, user):
        # This method is called via ``user in principal`` during ACL checks.
        # We have to take the IP from the request so if there's no request
        # (e.g. in the shell) we never grant IP-based access; same if we check
        # for a different user than the one from the current session.
        if not has_request_context() or not request.remote_addr:
            return False
        if session.user != user:
            return False
        return self.contains_ip(unicode(request.remote_addr))
    def contains_ip(self, ip):
        ip = ip_address(ip)
        return any(ip in network for network in self.networks)
    @property
    def locator(self):
        return {'network_group_id': self.id}
class IPNetwork(db.Model):
    __tablename__ = 'ip_networks'
    __table_args__ = {'schema': 'indico'}
    group_id = db.Column(
        db.Integer,
        db.ForeignKey('indico.ip_network_groups.id'),
        primary_key=True,
        autoincrement=False
    )
    network = db.Column(
        PyIPNetwork,
        primary_key=True,
        nullable=False
    )
    # relationship backrefs:
    # - group (IPNetworkGroup._networks)
    @return_ascii
    def __repr__(self):
        return format_repr(self, 'group_id', 'network')

class PermissionChecker(object):
    def __init__(self, self_bot: DBBot):
        self.self_bot = self_bot
    async def check_notice_permission(self, group_id: int) -> bool:
        res = await DBBotGroup(group_id=group_id, self_bot=self.self_bot).permission_notice()
        if res.result == 1:
            return True
        else:
            return False
    async def check_command_permission(self, group_id: int) -> bool:
        res = await DBBotGroup(group_id=group_id, self_bot=self.self_bot).permission_command()
        if res.result == 1:
            return True
        else:
            return False
    async def check_permission_level(self, group_id: int, level: int) -> bool:
        res = await DBBotGroup(group_id=group_id, self_bot=self.self_bot).permission_level()
        if res.result >= level:
            return True
        else:
            return False
    async def check_auth_node(self, auth_id: int, auth_type: str, auth_node: str) -> int:
        auth = DBAuth(self_bot=self.self_bot, auth_id=auth_id, auth_type=auth_type, auth_node=auth_node)
        tag_res = await auth.tags_info()
        allow_tag = tag_res.result[0]
        deny_tag = tag_res.result[1]
        if allow_tag == 1 and deny_tag == 0:
            return 1
        elif allow_tag == -2 and deny_tag == -2:
            return 0
        else:
            return -1
    async def check_friend_private_permission(self, user_id: int) -> bool:
        res = await DBFriend(user_id=user_id, self_bot=self.self_bot).get_private_permission()
        if res.error:
            return False
        elif res.result == 1:
            return True
        else:
            return False
__all__ = [
    'PermissionChecker'
]

from persistence import yaml
from persistence import termtables
from util import util
from cerberus import Validator
import collections
import datetime
import os
def load():
    """return a list of finish times"""
    finish = yaml.load("finish.yaml")
    finish = validate(finish)

    # primary key check
    idCounter = collections.Counter(map(lambda x: x["id"], finish))
    for i in idCounter:
        if idCounter[i] > 1:
            raise Exception("Finish file result for id " + str(i) + " defined " + str(idCounter[i]) + " times")
    return tuple(finish)
def validate(raw):
    schema = {
        "aux": {
            "type": "list",
            "minlength": 1,
            "schema": {
                "type": "dict",
                "schema": {
                    "id": {
                        "type": "integer"
                    },
                    "time": {
                        "type": "string",
                        "regex": "^[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9]$"
                    }
                }
            }
        }
    }
    v = Validator(schema, require_all=True)
    d = {"aux": raw}
    if not v.validate(d):
        print(v.errors)
        raise Exception("Finish file does not validate")
    return v.document["aux"]
def dump(start, encoding_print):
    """write results"""
    o = dict()
    o["name"] = start["name"]
    o["date"] = start["date"]
    o["races"] = list()
    for race in start["evals"]:
        r = dict()
        r["name"] = race["name"]
        r["desc"] = race["desc"]
        r["sex"] = race["sex"]
        r["distance"] = race["distance"]
        r["athletes"] = list()
        first_one = race["athletes"][0] if len(race["athletes"]) > 0 and hasattr(race["athletes"][0], "time") else None
        for athlete in race["athletes"]:
            a = dict()
            a["rank"] = athlete.rank if hasattr(athlete, "rank") else ""
            a["rank_sokol"] = athlete.rank_sokol if hasattr(athlete, "rank_sokol") else ""
            a["name"] = athlete.name
            a["surname"] = athlete.surname
            a["born"] = athlete.born
            a["club"] = athlete.club.abb15 if athlete.club is not None else ""
            a["start"] = athlete.start
            a["finish"] = athlete.finish.strftime("%H:%M:%S") if hasattr(athlete, "finish") and athlete.finish is not None else ""
            a["time"] = util.format_delta(athlete.time) if hasattr(athlete, "time") and athlete.time is not None else ""
            a["diff"] = util.format_delta(athlete.time - first_one.time) if hasattr(athlete, "time") and first_one is not None else ""
            r["athletes"].append(a)
        o["races"].append(r)

    yaml.dump(o, "results.yaml")
    termtables.dump_finish(o, "results.txt", encoding_print)

from sqlalchemy.orm import joinedload
from collections import defaultdict
from baselayer.app.access import auth_or_token
from ...base import BaseHandler
from ....models import DBSession, Obj, Source
default_prefs = {'maxNumSources': 5}
class RecentSourcesHandler(BaseHandler):
    @classmethod
    def get_recent_source_ids(self, current_user):
        user_prefs = getattr(current_user, 'preferences', None) or {}
        recent_sources_prefs = user_prefs.get('recentSources', {})
        recent_sources_prefs = {**default_prefs, **recent_sources_prefs}
        max_num_sources = int(recent_sources_prefs['maxNumSources'])
        query_results = (
            DBSession()
            .query(Source)
            .filter(
                Source.obj_id.in_(
                    DBSession()
                    .query(Source.obj_id)
                    .filter(
                        Source.group_id.in_(
                            [g.id for g in current_user.accessible_groups]
                        )
                    )
                    .filter(Source.active.is_(True))
                )
            )
            .order_by(desc('created_at'))
            .distinct(Source.obj_id, Source.created_at)
            .limit(max_num_sources)
            .all()
        )
        ids = map(lambda src: src.obj_id, query_results)
        return ids
    @auth_or_token
    def get(self):
        query_results = RecentSourcesHandler.get_recent_source_ids(self.current_user)
        sources = []
        sources_seen = defaultdict(lambda: 1)
        for obj_id in query_results:
            # The recency_index is how current a source row was saved for a given
            # object. If recency_index = 0, this is the most recent time a source
            # was saved; recency_index = 1 is the second-latest time the source
            # was saved, etc.
            recency_index = 0
            if obj_id in sources_seen:
                recency_index = sources_seen[obj_id]
                sources_seen[obj_id] += 1
            s = Source.get_obj_if_owned_by(  # Returns Source.obj
                obj_id,
                self.current_user,
                options=[joinedload(Source.obj).joinedload(Obj.thumbnails)],
            )
            # Get the entry in the Source table to get the accurate saved_at time
            source_entry = (
                Source.query.filter(Source.obj_id == obj_id)
                .order_by(desc('created_at'))
                .offset(recency_index)
                .first()
            )
            public_url = first_thumbnail_public_url(s.thumbnails)
            sources.append(
                {
                    'obj_id': s.id,
                    'ra': s.ra,
                    'dec': s.dec,
                    'created_at': source_entry.created_at,
                    'public_url': public_url,
                    'classifications': s.classifications,
                    'recency_index': recency_index,
                }
            )
        for source in sources:
            num_times_seen = sources_seen[source["obj_id"]]
            # If this source was saved multiple times recently, and this is not
            # the oldest instance of an object being saved (highest recency_index)
            if num_times_seen > 1 and source["recency_index"] != num_times_seen - 1:
                source["resaved"] = True
            else:
                source["resaved"] = False
            # Delete bookkeeping recency_index key
            del source["recency_index"]
        return self.success(data=sources)
def first_thumbnail_public_url(thumbnails):
    urls = [t.public_url for t in sorted(thumbnails, key=lambda t: tIndex(t.type))]
    return urls[0] if urls else ""
def tIndex(t):
    thumbnail_order = ['new', 'ref', 'sub', 'sdss', 'dr8']
    return thumbnail_order.index(t) if t in thumbnail_order else len(thumbnail_order)

from typing import Union, Callable
from .type import Type
class InvalidModule(Exception):
    """ Thrown when module is malformed. """
class MetaModule(type):
    """ MetaModule:
        Ensures Module classes are well formed and provides convenience methods
    """
    def __new__(cls, name, bases, dct):
        if 'DOC_URI' not in dct:
            raise InvalidModule('DOC_URI missing from module definition')
        if 'PROTOCOL' not in dct:
            raise InvalidModule("PROTOCOL missing from module definition")
        if 'VERSION' not in dct:
            raise InvalidModule('VERSION missing from module definition')
        return type.__new__(cls, name, bases, dct)
class Module(metaclass=MetaModule):  # pylint: disable=too-few-public-methods
    """ Base Module class """
    DOC_URI = None
    PROTOCOL = None
    VERSION = None
    def __init__(self):
        self._routes = None
    def type(
            self,
            name: str,
            doc_uri: str = None,
            protocol: str = None,
            version: str = None
                ):
        """ Build a type string for this module. """
        doc_uri = doc_uri if doc_uri is not None else self.DOC_URI
        protocol = protocol if protocol is not None else self.PROTOCOL
        version = version if version is not None else self.VERSION
        if doc_uri is None:
            raise TypeError('doc_uri must be str')
        if protocol is None:
            raise TypeError('protocol must be str')
        if version is None:
            raise TypeError('version must be str')
        return Type(doc_uri, protocol, version, name)
    def _find_routes(self):
        found = {}
        for key in dir(self):
            if key == 'routes' or key.startswith('__'):
                continue
            val = getattr(self, key)
            if hasattr(val, 'handler_for'):
                msg_type = val.handler_for
                if isinstance(msg_type, PartialType):
                    msg_type = msg_type.complete(self)
                found[msg_type] = val
        return found
    @property
    def routes(self):
        """ Get the routes statically defined for this module and
            save in instance.
        """
        if self._routes is None:
            self._routes = self._find_routes()
        return self._routes
class PartialType():
    """ Class containing the type information of a route before having the
        context of the module as is the case when statically defining routes in
        a module definition.
    """
    __slots__ = (
        'doc_uri',
        'protocol',
        'version',
        'name'
    )
    def __init__(
            self,
            name: str,
            doc_uri: str = None,
            protocol: str = None,
            version: str = None
                ):
        self.name = name
        self.version = version
        self.protocol = protocol
        self.doc_uri = doc_uri
    def complete(self, mod: Module) -> Type:
        """ Return a complete type given the module context. """
        doc_uri = self.doc_uri if self.doc_uri else type(mod).DOC_URI
        protocol = self.protocol if self.protocol else type(mod).PROTOCOL
        version = self.version if self.version else type(mod).VERSION
        if doc_uri is None:
            raise TypeError('doc_uri must be str')
        if protocol is None:
            raise TypeError('protocol must be str')
        if version is None:
            raise TypeError('version must be str')
        return Type(doc_uri, protocol, version, self.name)
def route(*args, **kwargs):
    """ Route definition decorator
        if just @route is used, type_or_func is the decorated function
        if @route(type) is used, type_or_func is the type string.
    """
    if args:
        type_or_func: Union[Callable, str, Type] = args[0]
        if callable(type_or_func):
            func = type_or_func
            func.handler_for = PartialType(func.__name__)
            return func
        if isinstance(type_or_func, str):
            msg_type = type_or_func
            def _route(func):
                func.handler_for = Type.from_str(msg_type)
                return func
            return _route
        if isinstance(type_or_func, Type):
            msg_type = type_or_func
            def _route(func):
                func.handler_for = msg_type
                return func
            return _route
    if kwargs:
        def _route(func):
            name = kwargs.get('name', func.__name__)
            del kwargs['name']
            func.handler_for = PartialType(name, **kwargs)
            return func
        return _route
    raise ValueError(
        'Expecting @route before a function or @route(msg_type) '
        'before a function!'
    )

from discord.embeds import Embed
from discord.ext import commands
import youtube_dl
import asyncio
import pafy
import discord
import datetime

class music(commands.Cog):
    def __init__(self,client):
        self.client = client
        self.song_queue = {}

        self.setup()

    def setup(self):
        for guild in self.client.guilds:
            self.song_queue[guild.id] = []

    async def check_queue(self, ctx):
        if len(self.song_queue[ctx.guild.id]) > 0:
            ctx.voice_client.stop()
            await self.play_song(ctx,self.song_queue[ctx.guild.id][0])
            self.song_queue[ctx.guild.id].pop(0)

    async def search_song(self, amount, song, get_url=False):
        info = await self.client.loop.run_in_executor(None, lambda: youtube_dl.YoutubeDL({"format" : "bestaudio", "quiet": True}).extract_info(f'ytsearch{amount}:{song}', download=False, ie_key="YoutubeSearch"))
        if len(info["entries"]) == 0: return None

        return [entry["webpage_url"] for entry in info ["entries"]] if get_url else info

    async def play_song(self, ctx, song):
        url = pafy.new(song).getbestaudio().url
        ctx.voice_client.play(discord.PCMVolumeTransformer(discord.FFmpegPCMAudio(url)), after=lambda error: self.client.loop.create_task(self.check_queue(ctx)))
        ctx.voice_client.source.volume = 0.5

    @commands.command(
        name="join",
        description='Joins voice channel.',
        usage="join",
        aliases=['j']
    )
    async def join(self,ctx):
        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")

        voice_channel = ctx.author.voice.channel
        if ctx.voice_client is None:
            await voice_channel.connect()
            await ctx.send(f"Successfully Connected to **{voice_channel}**.")
        else:
            if len(ctx.voice_client.channel.members) == 1:
                ctx.voice_client.stop()
                await ctx.voice_client.move_to(voice_channel)
                await ctx.send(f"Successfully Connected to **{voice_channel}**.")
            else:
                await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="disconnect",
        description='Leaves voice channel.',
        usage="disconnect",
        aliases=['dc']
        )
    async def disconnect(self,ctx):
        voice = ctx.voice_client

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")
        elif ctx.voice_client is None:
            await ctx.send("I'm not in a voice channel.")
        else:
            if ctx.author.voice.channel == voice.channel:
                ctx.voice_client.stop()
                await ctx.voice_client.disconnect()
                await ctx.send(f"Successfully Disconnected from **{voice.channel}**.")
            else:
                if len(ctx.voice_client.channel.members) == 1:
                    ctx.voice_client.stop()
                    await ctx.voice_client.disconnect()
                    await ctx.send(f"Successfully Disconnected from **{voice.channel}**.")
                else:
                    await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="play",
        description='Plays song from url into voice channel.',
        usage='play [url/song_name]',
        aliases=['p']
        )
    async def play(self,ctx,*,song=None):
        voice = ctx.voice_client

        if song is None:
            await ctx.send("Please include a song to play.")

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")

        if not ("youtube.com/watch?" in song or "https://youtu.be/" in song):
            result = await self.search_song(1, song, get_url=True)

            if result is None:
                return await ctx.send("Couldn't find entered song.")

            song = result[0]

        voice_channel = ctx.author.voice.channel
        if ctx.voice_client is None:
            await voice_channel.connect()
            await self.play_song(ctx, song)
            await ctx.send(f"Now playing {song}")
        else:
            if ctx.voice_client.source is not None:
                if ctx.author.voice.channel == voice.channel:
                    queue_len = len(self.song_queue[ctx.guild.id])

                    if queue_len < 10:
                        self.song_queue[ctx.guild.id].append(song)
                        return await ctx.send("Song has been added to queue.")
                    else:
                        return await ctx.send("I can only queue up to 10 songs, please wait for the current song to finish.")
                else:
                    if len(ctx.voice_client.channel.members) == 1:
                        ctx.voice_client.stop()
                        await ctx.voice_client.move_to(voice_channel)
                        await self.play_song(ctx, song)
                        await ctx.send(f"Now playing {song}")
                    else:
                        return await ctx.send("Someone else is already listening to music in different channel.")

            if ctx.author.voice.channel == voice.channel:
                await self.play_song(ctx, song)
                await ctx.send(f"Now playing {song}")
            else:
                if len(ctx.voice_client.channel.members) == 1:
                    ctx.voice_client.stop()
                    await ctx.voice_client.move_to(voice_channel)
                    await self.play_song(ctx, song)
                    await ctx.send(f"Now playing {song}")
                else:
                    await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="queue",
        description="Shows all songs in queue.",
        usage='queue',
        aliases=['q']
    )
    async def queue(self,ctx):
        if len(self.song_queue[ctx.guild.id]) == 0:
            return await ctx.send("There is currently so songs in queue.")

        embed=discord.Embed(title="Song Queue",description="",timestamp=datetime.datetime.utcnow(),color=0x86242a)
        embed.set_footer(text=f"Requested by {ctx.author}",icon_url=ctx.author.avatar_url)
        embed.set_thumbnail(url=self.client.user.avatar_url)
        i = 1
        for url in self.song_queue[ctx.guild.id]:
            embed.description += f"{i}) {url}\n"

            i += 1

        await ctx.send(embed=embed)

    @commands.command(
        name="skip",
        description="Skips current song.",
        usage='skip'
    )
    async def skip(self,ctx):
        voice = ctx.voice_client

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")
        elif ctx.voice_client is None:
            await ctx.send("I'm not in a voice channel.")
        else:
            if ctx.author.voice.channel == voice.channel:
                poll_message = await ctx.send("Skip current song? 80% of the voice channel must vote to skip. Voting ends in 15 seconds.")

                poll_id = poll_message.id

                await poll_message.add_reaction(u"\u2705")
                await poll_message.add_reaction(u"\U0001F6AB")

                await asyncio.sleep(15)

                poll_msg = await ctx.channel.fetch_message(poll_id)

                votes = {u"\u2705": 0, u"\U0001F6AB": 0}
                reacted = []

                for reaction in poll_msg.reactions:
                    if reaction.emoji in [u"\u2705", u"\U0001F6AB"]:
                        async for user in reaction.users():
                            if user.voice.channel.id == ctx.voice_client.channel.id and user.id not in reacted and not user.bot:
                                votes[reaction.emoji] += 1

                                reacted.append(user.id)

                skip = False

                if votes[u"\u2705"] > 0:
                    if votes[u"\U0001F6AB"] == 0 or votes [u"\u2705"] / (votes[u"\u2705"]) > 0.79:
                        skip = True
                        await ctx.send("Voted song has been skipped.")

                if not skip:
                    await ctx.send("Voted song has not been skipped.")

                await poll_message.clear_reactions()

                if skip:
                    ctx.voice_client.stop()
                    await self.check_queue(ctx)
            else:
                await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="pause",
        description='Pauses current song.',
        usage="pause"
    )
    async def pause(self,ctx):
        voice = ctx.voice_client

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")
        elif ctx.voice_client is None:
            await ctx.send("I'm not in a voice channel.")
        else:
            if ctx.author.voice.channel == voice.channel:
                if ctx.voice_client.is_playing():
                    ctx.voice_client.pause()
                    await ctx.send("Successfully Paused the song.")
                elif ctx.voice_client.is_paused():
                    await ctx.send("I'm already paused.")
                else:
                    await ctx.send("Nothing is playing.")
            else:
                await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="resume",
        description='Resumes current song.',
        usage="resume"
    )
    async def resume(self,ctx):
        voice = ctx.voice_client

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")
        elif ctx.voice_client is None:
            await ctx.send("I'm not in a voice channel.")
        else:
            if ctx.author.voice.channel == voice.channel:
                if ctx.voice_client.is_paused():
                    ctx.voice_client.resume()
                    await ctx.send("Successfully Resumed the song.")
                elif ctx.voice_client.is_playing():
                    await ctx.send("Music is already playing.")
                else:
                    await ctx.send("Nothing is playing.")
            else:
                await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="stop",
        description='Stops current song.',
        usage="stop"
    )
    async def stop(self,ctx):
        voice = ctx.voice_client

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")
        elif ctx.voice_client is None:
            await ctx.send("I'm not in a voice channel.")
        else:
            if ctx.author.voice.channel == voice.channel:
                if ctx.voice_client.is_playing() or ctx.voice_client.is_paused():
                    ctx.voice_client.stop()
                    await ctx.send("Successfully Stopped the song.")
                else:
                    await ctx.send("Nothing is playing.")
            else:
                await ctx.send("Someone else is already listening to music in different channel.")
        
def setup(client):
    client.add_cog(music(client))

