def checksum(tensor):
    with torch.no_grad():
        if tensor.dtype == torch.half:
            return torch.mean(tensor * tensor).sum().item()
        else:
            return 0
def is_a_view(x, y):
    return (
        x.storage().data_ptr() == y.storage().data_ptr()
        and x.storage_offset() == y.storage_offset()
        and x.numel() == y.numel()
