class Handler(BaseHTTPRequestHandler):
    """Simple HTTP handler for JWKS and tokens."""
    def do_GET(self) -> None:
        """Handle GET requests."""
        if self.path == "/.well-known/jwks.json":
            self._json_response(JWKS)
        elif self.path == "/tokens":
            self._json_response(TOKENS)
        elif self.path == "/health":
            self._json_response({"status": "ok"})
        else:
            self.send_error(404)
    def _json_response(self, data: dict) -> None:
        """Send JSON response."""
        body = json.dumps(data).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)
    def log_message(self, format: str, *args: Any) -> None:
        """Suppress request logging."""
if __name__ == "__main__":
    server = HTTPServer(("0.0.0.0", 8000), Handler)
    print("Mock JWKS server on :8000")
    server.serve_forever()

import json
import sys
def qinglite_login(mobile, code):
    url = "https://www.qinglite.cn/api/interface/user/user_mobile/login"
    payload = {
        "mobile": mobile,
        "code": code,
        "prefix": "+86",
        "act": 1,
        "app_type": "openclaw",
        "post_type": "ajax"
    }
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
    }
    try:
        response = requests.post(url, json=payload, headers=headers)
        response.raise_for_status()  # Raise an exception for HTTP errors
        response_json = response.json()
        if response_json.get("code") in [10000, 20000] and "token" in response_json.get("data", {}):
            token = response_json["data"]["token"]
            print(f"Login successful. Token: {token}")
            return token
        else:
            print(f"Login failed: {response_json.get('msg', 'Unknown error')}")
            return None
    except requests.exceptions.RequestException as e:
        print(f"Request error: {e}")
        return None
    except json.JSONDecodeError:
        print(f"Failed to decode JSON from response: {response.text}")
        return None
def qinglite_publish(token, title, content, post_type, media=""):
    url = "https://www.qinglite.cn/api/interface/content/news/create"
    payload = {
        "title": title,
        "content": content,
        "type": post_type,
        "media": media,
        "token": token,
        "app_type": "openclaw"
    }
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
    }
    try:
        response = requests.post(url, json=payload, headers=headers)
        response.raise_for_status()  # Raise an exception for HTTP errors
        response_json = response.json()
        if response_json.get("code") in [10000, 20000]:
            print(f"Publish successful: {response_json.get('msg', 'Success')}")
            return True
        else:
            print(f"Publish failed: {response_json.get('msg', 'Unknown error')}")
            return False
    except requests.exceptions.RequestException as e:
        print(f"Request error: {e}")
        return False
    except json.JSONDecodeError:
        print(f"Failed to decode JSON from response: {response.text}")
        return False
if __name__ == "__main__":
    action = sys.argv[1]
    if action == "login":
        if len(sys.argv) != 4:
            print("Usage: python qinglite_platform.py login <mobile> <code>")
            sys.exit(1)
        mobile = sys.argv[2]
        code = sys.argv[3]
        qinglite_login(mobile, code)
    elif action == "publish":
        if len(sys.argv) < 6 or len(sys.argv) > 7:
            print("Usage: python qinglite_platform.py publish <token> <title> <content> <type> [media]")
            sys.exit(1)
        token = sys.argv[2]
        title = sys.argv[3]
        content = sys.argv[4]
        post_type = int(sys.argv[5])
        media = sys.argv[6] if len(sys.argv) == 7 else ""
        qinglite_publish(token, title, content, post_type, media)
    else:
        print("Invalid action. Use 'login' or 'publish'.")
        sys.exit(1)

import logging
import time
from datetime import date, timedelta
from .base import Collector, CollectorResult
from .. import thinkbroadband
log = logging.getLogger("docsis.collector.bqm")
class BQMCollector(Collector):
    """Fetches the BQM quality graph PNG once per day.
    Uses time-of-day scheduling instead of interval-based polling.
    If collect_time is before 12:00, the graph is stored as yesterday's date
    (the 24h image represents the previous day). Otherwise stored as today.
    """
    name = "bqm"
    def __init__(self, config_mgr, storage, poll_interval=86400):
        super().__init__(poll_interval)
        self._config_mgr = config_mgr
        self._storage = storage
        self._last_date = None
    def is_enabled(self) -> bool:
        return self._config_mgr.is_bqm_configured()
    def should_poll(self) -> bool:
        """True if configured time has passed today and not yet collected."""
        today = time.strftime("%Y-%m-%d")
        if today == self._last_date:
            return False
        target = self._config_mgr.get("bqm_collect_time") or "02:00"
        now_hm = time.strftime("%H:%M")
        return now_hm >= target
    def collect(self) -> CollectorResult:
        today = time.strftime("%Y-%m-%d")
        if today == self._last_date:
            return CollectorResult(source=self.name, data={"skipped": True})
        url = self._config_mgr.get("bqm_url")
        image = thinkbroadband.fetch_graph(url)
        if image:
            collect_time = self._config_mgr.get("bqm_collect_time") or "02:00"
            if collect_time < "12:00":
                graph_date = (date.today() - timedelta(days=1)).isoformat()
            else:
                graph_date = date.today().isoformat()
            self._storage.save_bqm_graph(image, graph_date=graph_date)
            self._last_date = today
            return CollectorResult(source=self.name)
        return CollectorResult(
            source=self.name, success=False, error="Failed to fetch BQM graph"
        )

import re
from collections import defaultdict
from rich.text import Text
from scripts.use_pickled import console, epstein_files
from epstein_files.output.rich import highlighter, print_subtitle_panel
from epstein_files.util.helpers.data_helpers import sort_dict
INDENT = '  '
GUID_REGEX = re.compile(r'[-\d\w]{36}')
class JsonStats:
    key_count = defaultdict(int)
    list_count = 0
    def count_obj(self, obj: object, height: int = 0):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == 'bannerType' and v == 'any':
                    continue
                self.count_obj(v, height + 1)
                if not GUID_REGEX.match(k):
                    self.key_count[k] += 1
                if isinstance(v, str) and self.is_interesting_key(k):
                    if k != 'URL' or not v.startswith('asset:'):
                        key_value = Text(INDENT * height).append(k, style='cyan').append(': ').append(f'"{v}"')
                        console.print(highlighter(key_value))
        elif isinstance(obj, list):
            self.list_count += 1
            for item in obj:
                self.count_obj(item, height + 1)
    def is_interesting_key(self, key: str) -> bool:
        if 'Color' in key or 'Alignment' in key:
            return False
        elif key.startswith("text") and key != 'text':
            return False
        elif key.startswith('font') or key.startswith('ignore') or 'color' in key.lower() or key.startswith('thumbnail'):
            return False
        elif key in ['bottom', 'classification', 'fillMode', 'identifier', 'layout', 'role', 'style', 'top', 'type', 'weightLabel', 'width']:
            return False
        elif key.lower().endswith('height') or key.endswith('Identifier'):
            return False
        elif not self.should_count(key):
            return False
        return True
    def should_count(self, key: str) -> bool:
        if GUID_REGEX.match(key):
            return False
        elif key.startswith('call-to-action') or key.startswith('icon'):
            return False
        elif key in ['familyName']:
            return False
        return True
stats = JsonStats()
for json_file in epstein_files.json_files:
    stats.count_obj(json_file.json_data())
console.line(4)
print_subtitle_panel("Counts of Keys in JSON data")
for (key, count) in sort_dict(stats.key_count):
    console.print(f"{key}: {count}")
console.print(f"\n\nFound {stats.list_count} lists.\n")

import json
import sys
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from datetime import datetime
PLANNING_FILES = ['task_plan.md', 'progress.md', 'findings.md']
def get_project_dir(project_path: str) -> Path:
    """Convert project path to Claude's storage path format."""
    sanitized = project_path.replace('/', '-')
    if not sanitized.startswith('-'):
        sanitized = '-' + sanitized
    sanitized = sanitized.replace('_', '-')
    return Path.home() / '.claude' / 'projects' / sanitized
def get_sessions_sorted(project_dir: Path) -> List[Path]:
    """Get all session files sorted by modification time (newest first)."""
    sessions = list(project_dir.glob('*.jsonl'))
    main_sessions = [s for s in sessions if not s.name.startswith('agent-')]
    return sorted(main_sessions, key=lambda p: p.stat().st_mtime, reverse=True)
def parse_session_messages(session_file: Path) -> List[Dict]:
    """Parse all messages from a session file, preserving order."""
    messages = []
    with open(session_file, 'r') as f:
        for line_num, line in enumerate(f):
            try:
                data = json.loads(line)
                data['_line_num'] = line_num
                messages.append(data)
            except json.JSONDecodeError:
                pass
    return messages
def find_last_planning_update(messages: List[Dict]) -> Tuple[int, Optional[str]]:
    """
    Find the last time a planning file was written/edited.
    Returns (line_number, filename) or (-1, None) if not found.
    """
    last_update_line = -1
    last_update_file = None
    for msg in messages:
        msg_type = msg.get('type')
        if msg_type == 'assistant':
            content = msg.get('message', {}).get('content', [])
            if isinstance(content, list):
                for item in content:
                    if item.get('type') == 'tool_use':
                        tool_name = item.get('name', '')
                        tool_input = item.get('input', {})
                        if tool_name in ('Write', 'Edit'):
                            file_path = tool_input.get('file_path', '')
                            for pf in PLANNING_FILES:
                                if file_path.endswith(pf):
                                    last_update_line = msg['_line_num']
                                    last_update_file = pf
    return last_update_line, last_update_file
def extract_messages_after(messages: List[Dict], after_line: int) -> List[Dict]:
    """Extract conversation messages after a certain line number."""
    result = []
    for msg in messages:
        if msg['_line_num'] <= after_line:
            continue
        msg_type = msg.get('type')
        is_meta = msg.get('isMeta', False)
        if msg_type == 'user' and not is_meta:
            content = msg.get('message', {}).get('content', '')
            if isinstance(content, list):
                for item in content:
                    if isinstance(item, dict) and item.get('type') == 'text':
                        content = item.get('text', '')
                        break
                else:
                    content = ''
            if content and isinstance(content, str):
                if content.startswith(('<local-command', '<command-', '<task-notification')):
                    continue
                if len(content) > 20:
                    result.append({'role': 'user', 'content': content, 'line': msg['_line_num']})
        elif msg_type == 'assistant':
            msg_content = msg.get('message', {}).get('content', '')
            text_content = ''
            tool_uses = []
            if isinstance(msg_content, str):
                text_content = msg_content
            elif isinstance(msg_content, list):
                for item in msg_content:
                    if item.get('type') == 'text':
                        text_content = item.get('text', '')
                    elif item.get('type') == 'tool_use':
                        tool_name = item.get('name', '')
                        tool_input = item.get('input', {})
                        if tool_name == 'Edit':
                            tool_uses.append(f"Edit: {tool_input.get('file_path', 'unknown')}")
                        elif tool_name == 'Write':
                            tool_uses.append(f"Write: {tool_input.get('file_path', 'unknown')}")
                        elif tool_name == 'Bash':
                            cmd = tool_input.get('command', '')[:80]
                            tool_uses.append(f"Bash: {cmd}")
                        else:
                            tool_uses.append(f"{tool_name}")
            if text_content or tool_uses:
                result.append({
                    'role': 'assistant',
                    'content': text_content[:600] if text_content else '',
                    'tools': tool_uses,
                    'line': msg['_line_num']
                })
    return result
def main():
    project_path = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    project_dir = get_project_dir(project_path)
    # Check if planning files exist (indicates active task)
    has_planning_files = any(
        Path(project_path, f).exists() for f in PLANNING_FILES
    )
    if not project_dir.exists():
        # No previous sessions, nothing to catch up on
        return
    sessions = get_sessions_sorted(project_dir)
    if len(sessions) < 1:
        return
    # Find a substantial previous session
    target_session = None
    for session in sessions:
        if session.stat().st_size > 5000:
            target_session = session
            break
    if not target_session:
        return
    messages = parse_session_messages(target_session)
    last_update_line, last_update_file = find_last_planning_update(messages)
    # Only output if there's unsynced content
    if last_update_line < 0:
        messages_after = extract_messages_after(messages, len(messages) - 30)
    else:
        messages_after = extract_messages_after(messages, last_update_line)
    if not messages_after:
        return
    # Output catchup report
    print("\n[planning-with-files] SESSION CATCHUP DETECTED")
    print(f"Previous session: {target_session.stem}")
    if last_update_line >= 0:
        print(f"Last planning update: {last_update_file} at message #{last_update_line}")
        print(f"Unsynced messages: {len(messages_after)}")
    else:
        print("No planning file updates found in previous session")
    print("\n--- UNSYNCED CONTEXT ---")
    for msg in messages_after[-15:]:  # Last 15 messages
        if msg['role'] == 'user':
            print(f"USER: {msg['content'][:300]}")
        else:
            if msg.get('content'):
                print(f"CLAUDE: {msg['content'][:300]}")
            if msg.get('tools'):
                print(f"  Tools: {', '.join(msg['tools'][:4])}")
    print("\n--- RECOMMENDED ---")
    print("1. Run: git diff --stat")
    print("2. Read: task_plan.md, progress.md, findings.md")
    print("3. Update planning files based on above context")
    print("4. Continue with task")
if __name__ == '__main__':
    main()

from typing import Dict
import torch
from megatron.bridge.models.conversion.param_mapping import AutoMapping, GatedMLPMapping
from megatron.bridge.models.conversion.utils import get_module_and_param_from_name
from megatron.bridge.utils.common_utils import extract_expert_number_from_param
def _select_expert_weight(hf_weights: torch.Tensor, expert_idx: int) -> torch.Tensor:
    if hf_weights.ndim >= 3:
        return hf_weights[expert_idx]
    return hf_weights
def _align_weight_to_shape(weight: torch.Tensor, target_shape: torch.Size, name: str) -> torch.Tensor:
    if tuple(weight.shape) == tuple(target_shape):
        return weight
    if weight.ndim == 2 and tuple(weight.t().shape) == tuple(target_shape):
        return weight.t().contiguous()
    raise ValueError(f"Unexpected {name} shape {tuple(weight.shape)}; expected {tuple(target_shape)}.")
class _LooseGatedMLPMapping(GatedMLPMapping):
    def _validate_patterns(self, *args, **kwargs):
        # Allow mismatched wildcard counts for fused expert mappings.
        pass
class GLMExpertGateUpProjMapping(AutoMapping):
    """Mapping for fused expert gate+up projection weights."""
    def __init__(self, megatron_param: str, hf_param: str, permute_dims=None):
        super().__init__(megatron_param, hf_param, permute_dims)
        self._gated_mapping = _LooseGatedMLPMapping(
            megatron_param=self.megatron_param,
            gate=f"{self.hf_param}.gate",
            up=f"{self.hf_param}.up",
        )
    def hf_to_megatron(self, hf_weights: torch.Tensor, megatron_module: torch.nn.Module) -> torch.Tensor:
        global_expert_number = extract_expert_number_from_param(self.megatron_param)
        expert_weight = _select_expert_weight(hf_weights, global_expert_number)
        normalized_param = self._normalize_expert_param_name(self.megatron_param)
        _, target_param = get_module_and_param_from_name(megatron_module, normalized_param)
        target_shape = target_param.shape
        gate_target_shape = (target_shape[0] // 2, target_shape[1])
        if target_shape[0] % 2 != 0:
            raise ValueError(f"Expected even fused dim for {self.megatron_param}, got {target_shape}.")
        if expert_weight.ndim == 3 and expert_weight.shape[0] == 2:
            gate = _align_weight_to_shape(expert_weight[0], gate_target_shape, "gate")
            up = _align_weight_to_shape(expert_weight[1], gate_target_shape, "up")
        else:
            expert_weight = _align_weight_to_shape(expert_weight, target_shape, "gate_up")
            gate, up = torch.chunk(expert_weight, 2, dim=0)
        return self._gated_mapping.hf_to_megatron({"gate": gate, "up": up}, megatron_module)
    def megatron_to_hf(
        self, megatron_weights: torch.Tensor, megatron_module: torch.nn.Module
    ) -> Dict[str, torch.Tensor]:
        converted = self._gated_mapping.megatron_to_hf(megatron_weights, megatron_module)
        if not converted:
            return {}
        fused: Dict[str, torch.Tensor] = {}
        for name, tensor in converted.items():
            if not name.endswith(".gate"):
                continue
            base_name = name[: -len(".gate")]
            up_tensor = converted.get(f"{base_name}.up")
            if up_tensor is None:
                continue
            concat_dim = 0 if tensor.ndim == 2 else 1
            fused[base_name] = torch.cat([tensor, up_tensor], dim=concat_dim)
        return fused
    def _validate_patterns(self, *args, **kwargs):
        # Allow number of wildcards to mismatch in this mapping.
        pass
class GLMExpertDownProjMapping(AutoMapping):
    """Mapping for fused expert down projection weights."""
    def __init__(self, megatron_param: str, hf_param: str, permute_dims=None):
        super().__init__(megatron_param, hf_param, permute_dims)
    def hf_to_megatron(self, hf_weights: torch.Tensor, megatron_module: torch.nn.Module) -> torch.Tensor:
        global_expert_number = extract_expert_number_from_param(self.megatron_param)
        expert_weight = _select_expert_weight(hf_weights, global_expert_number)
        normalized_param = self._normalize_expert_param_name(self.megatron_param)
        _, target_param = get_module_and_param_from_name(megatron_module, normalized_param)
        expert_weight = _align_weight_to_shape(expert_weight, target_param.shape, "down_proj")
        return super().hf_to_megatron(expert_weight, megatron_module)
    def _validate_patterns(self, *args, **kwargs):
        # Allow number of wildcards to mismatch in this mapping.
        pass

import os
import torch
import torch.distributed as dist
logger = logging.getLogger(__name__)
def _get_rank():
    return dist.get_rank() if dist.is_initialized() else 0
class Replay:
    def __init__(self):
        self.forward_index = 0
        self.backward_index = 0
        self.top_indices_list: list[torch.Tensor] = []
    def record(self, top_indices: torch.Tensor):
        buf = torch.empty_like(top_indices, device="cpu", pin_memory=True)
        buf.copy_(top_indices)
        self.top_indices_list.append(buf)
    def pop_forward(self) -> torch.Tensor:
        if self.forward_index >= len(self.top_indices_list):
            shapes = [
                t.shape if isinstance(t, torch.Tensor) else f"non-tensor({type(t)})" for t in self.top_indices_list
            ]
            raise IndexError(
                f"pop_forward out of range: forward_index={self.forward_index}, "
                f"len(top_indices_list)={len(self.top_indices_list)}, shapes={shapes}"
            )
        top_indices = self.top_indices_list[self.forward_index]
        self.forward_index += 1
        return top_indices.to(torch.cuda.current_device())
    def pop_backward(self) -> torch.Tensor:
        top_indices = self.top_indices_list[self.backward_index]
        self.backward_index += 1
        return top_indices.to(torch.cuda.current_device())
    def clear(self):
        self.forward_index = 0
        self.backward_index = 0
        self.top_indices_list = []
    def clear_forward(self):
        self.forward_index = 0
class BaseReplayManager:
    name: str = ""
    filename: str = ""
    def __init__(self):
        self.replays: list[Replay] = []
        self.current: Replay | None = None
        self.enabled = False
        self.stage = "fallthrough"
    def create_replay(self) -> Replay:
        replay = Replay()
        self.replays.append(replay)
        return replay
    def set_current(self, replay: Replay):
        self.current = replay
    def get_current(self) -> Replay | None:
        return self.current
    def clear_all(self):
        for replay in self.replays:
            replay.clear()
    def clear_all_forward(self):
        for replay in self.replays:
            replay.clear_forward()
    def get_topk_fn(self, old_topk_fn, return_probs):
        manager = self
        def _get_replay_result(top_indices, scores, topk, *args, **kwargs):
            assert (
                top_indices.shape[0] == scores.shape[0]
            ), f"rank {_get_rank()}: replay n_tokens {top_indices.shape[0]} does not match scores n_tokens {scores.shape[0]}"
            assert (
                top_indices.shape[1] == topk
            ), f"replay topk does not match expected topk, replay topk {top_indices.shape[1]}, topk {topk}"
            if self.enable_check_replay_result:
                self.check_replay_result(old_topk_fn, scores, topk, top_indices, *args, **kwargs)
            padding_mask = top_indices == -1
            if padding_mask.any():
                top_indices[padding_mask] = (
                    torch.arange(padding_mask.sum(), device=top_indices.device, dtype=top_indices.dtype)
                    % scores.shape[1]
                )
            if return_probs:
                return scores.gather(1, top_indices), top_indices
            else:
                return top_indices
        def new_topk_fn(scores, topk, *args, **kwargs):
            if not manager.enabled:
                return old_topk_fn(scores, topk, *args, **kwargs)
            stage = manager.stage
            replay = manager.get_current()
            if stage == "fallthrough":
                return old_topk_fn(scores, topk, *args, **kwargs)
            elif stage == "record":
                result = old_topk_fn(scores, topk, *args, **kwargs)
                if return_probs:
                    probs, top_indices = result
                else:
                    top_indices = result
                replay.record(top_indices)
                return result
            elif stage == "replay_forward":
                return _get_replay_result(replay.pop_forward(), scores, topk, *args, **kwargs)
            elif stage == "replay_backward":
                return _get_replay_result(replay.pop_backward(), scores, topk, *args, **kwargs)
            else:
                return old_topk_fn(scores, topk, *args, **kwargs)
        return new_topk_fn
    def register_to_module(self, module, attr_name: str):
        if not self.enabled:
            return
        replay = self.create_replay()
        setattr(module, attr_name, replay)
        manager = self
        def pre_forward_hook(*args, **kwargs):
            manager.set_current(replay)
        module.register_forward_pre_hook(pre_forward_hook)
    def check_replay_result(self, old_topk_fn, scores, topk, top_indices, *args, **kwargs):
        """
        CI checker for R3. Only enable when enable_check_replay_result=True.
        Calculate the overlapping between training engine's computed routing result
        and replay routing result.
        If mismatch token count > n_tokens * replay_check_threshold, raise error.
        """
        orig_top_indices = old_topk_fn(scores, topk, *args, **kwargs)
        if isinstance(orig_top_indices, tuple):
            _, orig_top_indices = orig_top_indices
        orig_flat = orig_top_indices.view(-1, orig_top_indices.shape[-1])  # [n_tokens, topk]
        replay_flat = top_indices.view(-1, top_indices.shape[-1])
        # [n_tokens, topk_orig, 1] == [n_tokens, 1, topk_replay] -> [n_tokens, topk_orig, topk_replay]
        matches = orig_flat.unsqueeze(2) == replay_flat.unsqueeze(1)
        # Mask out -1 (padding) matches
        matches &= (orig_flat != -1).unsqueeze(2) & (replay_flat != -1).unsqueeze(1)
        has_overlap = matches.any(dim=(1, 2))  # [n_tokens]
        is_padding = (replay_flat == -1).all(dim=1)
        is_mismatch = ~has_overlap & ~is_padding
        mismatch_count = is_mismatch.sum().item()
        if mismatch_count == 0:
            return
        threshold = float(os.environ.get("MILES_TEST_R3_THRESHOLD", self.replay_check_threshold))
        mismatch_threshold = threshold * orig_flat.shape[0]
        mismatch_indices = is_mismatch.nonzero(as_tuple=False).squeeze(1)
        for idx in mismatch_indices:
            i = idx.item()
            lines = []
            for j in range(max(0, i - 3), min(len(orig_flat), i + 4)):
                marker = " <<<" if j == i else ""
                lines.append(f"  token {j}: orig={orig_flat[j].tolist()}, replay={replay_flat[j].tolist()}{marker}")
            logger.warning(
                f"Replay check (rank {_get_rank()}, stage {self.stage}): "
                f"token {i} zero overlap, topk={topk}\n" + "\n".join(lines)
            )
        if mismatch_count > mismatch_threshold:
            raise AssertionError(f"R3 mismatch tokens ({mismatch_count}) > threshold ({mismatch_threshold:.0f})")
class RoutingReplayManager(BaseReplayManager):
    name = "routing"
    filename = "routing_replay.pt"
