from blankly.exchanges.orders.futures.futures_order import FuturesOrder
class FuturesExchangeInterface(ABCBaseExchangeInterface, abc.ABC):
    exchange_name: str
    def __init__(self,
                 exchange_name,
                 authenticated_api,
                 preferences_path=None):
        self.exchange_name = exchange_name
        self.calls = authenticated_api
        self.user_preferences = utils.load_user_preferences(preferences_path)
        self.exchange_properties = None
        self.available_currencies = {}
        if self.user_preferences['settings']['test_connectivity_on_auth']:
            self.init_exchange()
    @staticmethod
    def to_blankly_symbol(symbol: str):
        return symbol
    @staticmethod
    def to_exchange_symbol(symbol: str):
        return symbol
    def get_exchange_type(self) -> str:
        """Returns the exchange type (ex. 'binance', 'coinbase', 'alpaca')"""
        return self.exchange_name
    @abc.abstractmethod
    def init_exchange(self):
        """Initializes the exchange"""
        pass
    @abc.abstractmethod
    def get_products(self, symbol: str = None) -> dict:
        """Returns a list of all products traded on this exchange"""
        pass
    @abc.abstractmethod
    def get_account(self, symbol: str = None) -> dict:
        """Returns account information, or information for only one `symbol` if one is given."""
        pass
    # TODO this metohd name might need to change to get_position ?
    @abc.abstractmethod
    def get_position(self, symbol: str = None) -> Optional[dict]:
        """Returns position information, or information for only one `symbol` if one is given"""
        pass
    @abc.abstractmethod
    def market_order(self,
                     symbol: str,
                     side: Side,
                     size: float,
                     position: PositionMode = None,
                     reduce_only: bool = None) -> FuturesOrder:
        """Places a market order"""
        pass
    @abc.abstractmethod
    def limit_order(self,
                    symbol: str,
                    side: Side,
                    price: float,
                    size: float,
                    position: PositionMode = None,
                    reduce_only: bool = None,
                    time_in_force: TimeInForce = None) -> FuturesOrder:
        """Places a limit order"""
        pass
    @abc.abstractmethod
    def take_profit_order(self,
                          symbol: str,
                          side: Side,
                          price: float,
                          size: float,
                          position: PositionMode = None) -> FuturesOrder:
        """Place a take-profit order for a position"""
        pass
    @abc.abstractmethod
    def stop_loss_order(self,
                        symbol: str,
                        side: Side,
                        price: float,
                        size: float,
                        position: PositionMode = None) -> FuturesOrder:
        """Place a stop-loss order for a position"""
        pass
    @abc.abstractmethod
    def set_hedge_mode(self, hedge_mode: HedgeMode):
        pass
    @abc.abstractmethod
    def get_hedge_mode(self):
        pass
    @abc.abstractmethod
    def set_leverage(self, leverage: float, symbol: str = None):
        pass
    @abc.abstractmethod
    def get_leverage(self, symbol: str = None) -> float:
        pass
    @abc.abstractmethod
    def set_margin_type(self, symbol: str, type: MarginType):
        pass
    @abc.abstractmethod
    def get_margin_type(self, symbol: str):
        pass
    @abc.abstractmethod
    def cancel_order(self, symbol: str, order_id: int) -> FuturesOrder:
        """Cancels an order"""
        pass
    @abc.abstractmethod
    def get_open_orders(self, symbol: str = None) -> List[FuturesOrder]:
        """Returns all currently open orders, filtered by `symbol` if one is provided."""
        pass
    @abc.abstractmethod
    def get_order(self, symbol: str, order_id: int) -> FuturesOrder:
        """Returns information for the order corresponding to `order_id`"""
        pass
    @abc.abstractmethod
    def get_price(self, symbol: str) -> float:
        """Returns the current price of an asset"""
        pass
    @property
    def account(self) -> dict:
        """Account information"""
        return self.get_account()
    @property
    def positions(self) -> dict:
        """Position information"""
        return self.get_position()
    @property
    def orders(self) -> list:
        """All currently open orders"""
        return self.get_open_orders()
    @property
    def cash(self) -> float:
        """The amount of cash in a portfolio. The currency for 'cash' is set in settings.json"""
        using_setting = self.user_preferences['settings'][
            self.exchange_name]['cash']
        return self.get_account(using_setting)['available']
    @abc.abstractmethod
    def get_funding_rate_history(self, symbol: str, epoch_start: int,
                                 epoch_stop: int) -> list:
        """
        Get the funding rate history between `epoch_start` and `epoch_end`.
        Returns a list of {'rate': int, 'time': int}
        """
        pass
    @abc.abstractmethod
    def get_funding_rate(self, symbol: str) -> float:
        pass
    @abc.abstractmethod
    def get_maker_fee(self) -> float:
        pass
    @abc.abstractmethod
    def get_taker_fee(self) -> float:
        pass
    @abc.abstractmethod
    def get_funding_rate_resolution(self) -> int:
        pass
    @property
    def should_auto_trunc(self):
        return self.user_preferences['settings'].get('auto_truncate', False)

from dataclasses import dataclass, field, fields
from datetime import datetime
from typing import Self
from rich.text import Text
from epstein_files.documents.emails.constants import FALLBACK_TIMESTAMP
from epstein_files.output.epstein_highlighter import highlighter
from epstein_files.output.highlight_config import get_style_for_name
from epstein_files.output.rich import TEXT_LINK
from epstein_files.people.names import (ANTHONY_SCARAMUCCI, JEFFREY_EPSTEIN, STEVE_BANNON,
     UNKNOWN, Name, extract_last_name)
from epstein_files.util.constant.strings import TIMESTAMP_DIM
from epstein_files.util.helpers.data_helpers import AMERICAN_DATE_FORMAT
from epstein_files.util.logging import logger
EPSTEIN_TEXTERS = ['e:', 'e:redacted@example.invalid']
PHONE_NUMBER_REGEX = re.compile(r'^[\d+]+.*')
UNCERTAIN_SUFFIX = ' (?)'
DISPLAY_LAST_NAME_ONLY = [
    ANTHONY_SCARAMUCCI,
    JEFFREY_EPSTEIN,
    STEVE_BANNON,
]
@dataclass(kw_only=True)
class TextMessage:
    """Class representing a single iMessage text message."""
    author: [redacted]
    author_str: str = ''
    is_id_confirmed: bool = False
    text: str
    timestamp_str: str
    def __post_init__(self):
        self.author = JEFFREY_EPSTEIN if self.author in EPSTEIN_TEXTERS else self.author
        if not self.author:
            self.author_str = UNKNOWN
        elif self.author in DISPLAY_LAST_NAME_ONLY and not self.author_str:
            self.author_str = extract_last_name(self.author)
        else:
            self.author_str = self.author_str or self.author
        if not self.is_id_confirmed and self.author is not None and self.author != JEFFREY_EPSTEIN:
            self.author_str += UNCERTAIN_SUFFIX
        if self.is_link():
            self.text = self.text.replace('\n', '').replace(' ', '_')
        else:
            self.text = self.text.replace('\n', ' ')
    @property
    def timestamp_sort_key(self) -> datetime:
        try:
            return self.parse_timestamp()
        except Exception as e:
            return FALLBACK_TIMESTAMP
    def is_link(self) -> bool:
        return self.text.startswith('http')
    def parse_timestamp(self) -> datetime:
        return datetime.strptime(self.timestamp_str, AMERICAN_DATE_FORMAT)
    def timestamp_txt(self) -> Text:
        from epstein_files.util.env import site_config
        try:
            timestamp_str = site_config.format_text_msg_time(self.parse_timestamp())
        except Exception as e:
            logger.info(f"Failed to parse timestamp for {self}")
            timestamp_str = self.timestamp_str
        return Text(f"[{timestamp_str}]", style=TIMESTAMP_DIM)
    def _message(self) -> Text:
        if self.is_link():
            return Text.from_markup(f"[link={self.text}]{self.text}[/link]", style=TEXT_LINK)
        else:
            return highlighter(self.text)
    def __eq__(self, other: Self):
        return self.author == other.author and \
               self.text == other.text and \
               self.timestamp_str == other.timestamp_str and \
               self.author_str == other.author_str
    def __rich__(self) -> Text:
        timestamp_txt = self.timestamp_txt().append(' ')
        author_style = get_style_for_name(self.author_str if self.author_str.startswith('+') else self.author)
        author_txt = Text(self.author_str, style=author_style)
        return Text('').append(timestamp_txt).append(author_txt).append(': ', style='dim').append(self._message())
    def __repr__(self) -> str:
        props = []
        add_prop = lambda k, v: props.append(f"{k}={v}")
        for _field in sorted(fields(self), key=lambda f: f.name):
            key = _field.name
            value = getattr(self, key)
            if key == 'author_str' and self.author and self.author_str.startswith(value):
                continue
            elif isinstance(value, str):
                add_prop(key, f'"{value}"')
            else:
                add_prop(key, value)
        return f"{type(self).__name__}(" + ', '.join(props) + f')'

import logging
import os
from flask import Blueprint, jsonify, request
from app.web import get_config_manager, get_module_loader, require_auth
log = logging.getLogger("docsis.modules")
modules_bp = Blueprint("modules_bp", __name__)
def _serialize_module(mod):
    """Convert ModuleInfo to JSON-safe dict."""
    return {
        "id": mod.id,
        "name": mod.name,
        "description": mod.description,
        "version": mod.version,
        "author": mod.author,
        "type": mod.type,
        "enabled": mod.enabled,
        "builtin": mod.builtin,
        "error": mod.error,
        "homepage": mod.homepage,
        "is_threshold": "thresholds" in mod.contributes,
        "is_theme": mod.type == "theme",
    }
@modules_bp.route("/api/modules")
@require_auth
def api_modules_list():
    """List all discovered modules with metadata and status."""
    loader = get_module_loader()
    if not loader:
        return jsonify([])
    modules = loader.get_modules()
    return jsonify([_serialize_module(m) for m in modules])
@modules_bp.route("/api/modules/<module_id>/enable", methods=["POST"])
@require_auth
def api_module_enable(module_id):
    """Enable a disabled module (persisted, requires restart)."""
    loader = get_module_loader()
    if not loader:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500
    module = next((m for m in loader.get_modules() if m.id == module_id), None)
    if not module:
        return jsonify({"success": False, "error": f"Module '{module_id}' not found"}), 404
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"success": False, "error": "Config not initialized"}), 500
    disabled_raw = config_mgr.get("disabled_modules", "")
    disabled_set = {s.strip() for s in disabled_raw.split(",") if s.strip()}
    # Mutual exclusion: if enabling a threshold module, disable the currently active one
    if "thresholds" in module.contributes:
        for m in loader.get_threshold_modules():
            if m.id != module_id and m.id not in disabled_set:
                disabled_set.add(m.id)
                log.info("Auto-disabled threshold module '%s' (mutual exclusion)", m.id)
    # Mutual exclusion: if enabling a theme, disable others and set active_theme
    if module.type == "theme":
        for m in loader.get_theme_modules():
            if m.id != module_id and m.id not in disabled_set:
                disabled_set.add(m.id)
                log.info("Auto-disabled theme module '%s' (mutual exclusion)", m.id)
    disabled_set.discard(module_id)
    updates = {"disabled_modules": ",".join(sorted(disabled_set))}
    if module.type == "theme":
        updates["active_theme"] = module_id
    config_mgr.save(updates)
    log.info("Module '%s' enabled (restart required)", module_id)
    return jsonify({"success": True, "restart_required": True})
@modules_bp.route("/api/modules/<module_id>/disable", methods=["POST"])
@require_auth
def api_module_disable(module_id):
    """Disable a module (persisted, requires restart)."""
    loader = get_module_loader()
    if not loader:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500
    module = next((m for m in loader.get_modules() if m.id == module_id), None)
    if not module:
        return jsonify({"success": False, "error": f"Module '{module_id}' not found"}), 404
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"success": False, "error": "Config not initialized"}), 500
    # Block disabling the last active theme module
    if module.type == "theme":
        disabled_raw = config_mgr.get("disabled_modules", "")
        disabled_set_check = {s.strip() for s in disabled_raw.split(",") if s.strip()}
        active_themes = [
            m for m in loader.get_theme_modules()
            if m.id not in disabled_set_check and m.id != module_id
        ]
        if not active_themes:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active theme. Enable a different theme first.",
            }), 409
    # Block disabling the last active threshold module
    if "thresholds" in module.contributes:
        disabled_raw = config_mgr.get("disabled_modules", "")
        disabled_set = {s.strip() for s in disabled_raw.split(",") if s.strip()}
        active_thresholds = [
            m for m in loader.get_threshold_modules()
            if m.id not in disabled_set and m.id != module_id
        ]
        if not active_thresholds:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active threshold profile. Enable a different one first.",
            }), 409
    disabled_raw = config_mgr.get("disabled_modules", "")
    disabled_set = {s.strip() for s in disabled_raw.split(",") if s.strip()}
    disabled_set.add(module_id)
    config_mgr.save({"disabled_modules": ",".join(sorted(disabled_set))})
    log.info("Module '%s' disabled (restart required)", module_id)
    return jsonify({"success": True, "restart_required": True})
@modules_bp.route("/api/themes")
@require_auth
def api_themes_list():
    """List all theme modules with their CSS variable data."""
    loader = get_module_loader()
    if not loader:
        return jsonify([])
    themes = loader.get_theme_modules()
    result = []
    for m in themes:
