    elif model_args.model_name_or_path:
        tokenizer = AutoTokenizer.from_pretrained(
            model_args.model_name_or_path, cache_dir=model_args.cache_dir, use_fast=model_args.use_fast_tokenizer
        )
    else:
        raise ValueError(
            "You are instantiating a new tokenizer from scratch. This is not supported by this script. "
            "You can do it from another script, save it, and load it from here, using --tokenizer_name."
        )
    if training_args.do_train:
        column_names = dataset["train"].column_names
    else:
        column_names = dataset["validation"].column_names
    text_column_name = "text" if "text" in column_names else column_names[0]
    # since this will be pickled to avoid _LazyModule error in Hasher force logger loading before tokenize_function
    tok_logger = transformers.utils.logging.get_logger("transformers.tokenization_utils_base")
    def tokenize_function(examples):
        with CaptureLogger(tok_logger) as cl:
            output = tokenizer(examples[text_column_name])
        # clm input could be much much longer than block_size
        if "Token indices sequence length is longer than the" in cl.out:
            tok_logger.warning(
                "^^^^^^^^^^^^^^^^ Please ignore the warning above - this long input will be chunked into smaller bits"
                " before being passed to the model."
            )
        return output
    tokenized_datasets = dataset.map(
        tokenize_function,
        batched=True,
        num_proc=data_args.preprocessing_num_workers,
        remove_columns=column_names,
        load_from_cache_file=not data_args.overwrite_cache,
    )
    if data_args.block_size is None:
        block_size = tokenizer.model_max_length
        if block_size > config.max_position_embeddings:
            logger.warning(
                f"The tokenizer picked seems to have a very large `model_max_length` ({tokenizer.model_max_length}). "
                f"Using block_size={min(1024, config.max_position_embeddings)} instead. You can change that default value by passing --block_size xxx."
            )
            block_size = min(1024, config.max_position_embeddings)
    else:
        if data_args.block_size > tokenizer.model_max_length:
            logger.warning(
                f"The block_size passed ({data_args.block_size}) is larger than the maximum length for the model "
                f"({tokenizer.model_max_length}). Using block_size={tokenizer.model_max_length}."
            )
        block_size = min(data_args.block_size, tokenizer.model_max_length)
    # Main data processing function that will concatenate all texts from our dataset and generate chunks of block_size.
    def group_texts(examples):
        # Concatenate all texts.
        concatenated_examples = {k: list(chain(*examples[k])) for k in examples.keys()}
        total_length = len(concatenated_examples[list(examples.keys())[0]])
        # We drop the small remainder, we could add padding if the model supported it instead of this drop, you can
        # customize this part to your needs.
        if total_length >= block_size:
            total_length = (total_length // block_size) * block_size
        # Split by chunks of max_len.
        result = {
            k: [t[i : i + block_size] for i in range(0, total_length, block_size)]
            for k, t in concatenated_examples.items()
        }
        result["labels"] = result["input_ids"].copy()
        return result
    # Note that with `batched=True`, this map processes 1,000 texts together, so group_texts throws away a remainder
    # for each of those groups of 1,000 texts. You can adjust that batch_size here but a higher value might be slower
    # to preprocess.
    #
    # To speed up this part, we use multiprocessing. See the documentation of the map method for more information:
    # https://huggingface.co/docs/datasets/process#map
    lm_datasets = tokenized_datasets.map(
        group_texts,
        batched=True,
        num_proc=data_args.preprocessing_num_workers,
        load_from_cache_file=not data_args.overwrite_cache,
    )
    if training_args.do_train:
        if "train" not in tokenized_datasets:
            raise ValueError("--do_train requires a train dataset")
        train_dataset = lm_datasets["train"]
        if data_args.max_train_samples is not None:
            max_train_samples = min(len(train_dataset), data_args.max_train_samples)
            train_dataset = train_dataset.select(range(max_train_samples))
    if training_args.do_eval:
        if "validation" not in tokenized_datasets:
            raise ValueError("--do_eval requires a validation dataset")
        eval_dataset = lm_datasets["validation"]
        if data_args.max_eval_samples is not None:
            max_eval_samples = min(len(eval_dataset), data_args.max_eval_samples)
            eval_dataset = eval_dataset.select(range(max_eval_samples))
    # Enable tensorboard only on the master node
    has_tensorboard = is_tensorboard_available()
    if has_tensorboard and jax.process_index() == 0:
        try:
            from flax.metrics.tensorboard import SummaryWriter
            summary_writer = SummaryWriter(log_dir=Path(training_args.output_dir))
        except ImportError as ie:
            has_tensorboard = False
            logger.warning(
                f"Unable to display metrics through TensorBoard because some package are not installed: {ie}"
            )
    else:
        logger.warning(
            "Unable to display metrics through TensorBoard because the package is not installed: "
            "Please run pip install tensorboard to enable."
        )
    # Initialize our training
    rng = jax.random.PRNGKey(training_args.seed)
    rng, dropout_rng = jax.random.split(rng)
    # Store some constant
    num_epochs = int(training_args.num_train_epochs)
    train_batch_size = int(training_args.per_device_train_batch_size) * jax.device_count()
    eval_batch_size = int(training_args.per_device_eval_batch_size) * jax.device_count()
    steps_per_epoch = len(train_dataset) // train_batch_size
    total_train_steps = steps_per_epoch * num_epochs
    # TODO: weights should be initialized in pjitted fun, this won't work for REALLY large models
    # TODO: when loading from pre-trained model we need to make sure the vocab is divisible by num_partitions
    # GPT2's vocab is odd, we need to resize it for fine-tuning
    model = FlaxAutoModelForCausalLM.from_pretrained(
        model_args.model_name_or_path, seed=training_args.seed, dtype=getattr(jnp, model_args.dtype)
    )
    # Create learning rate schedule
    linear_decay_lr_schedule_fn = create_learning_rate_fn(
        len(train_dataset),
        train_batch_size,
        training_args.num_train_epochs,
        training_args.warmup_steps,
        training_args.learning_rate,
    )
    optimizer = optax.adamw(
        learning_rate=linear_decay_lr_schedule_fn,
        b1=training_args.adam_beta1,
        b2=training_args.adam_beta2,
        eps=training_args.adam_epsilon,
        weight_decay=training_args.weight_decay,
    )
    def get_initial_state(params):
        state = optimizer.init(params)
        return tuple(state), params
    # Get PartitionSpec for model params
    param_spec = set_partitions(unfreeze(model.params))
    # Get the PyTree for opt_state, we don't actually initialize the opt_state yet.
    params_shapes = jax.tree_util.tree_map(lambda x: x.shape, model.params)
    state_shapes = jax.eval_shape(get_initial_state, params_shapes)
    # get PartitionSpec for opt_state, this is very specific to adamw
    # TODO: optax returns different state for different optimizers, how can we handle this generically ?
    # or maybe we don't since in our examples we just use adamw or adafactor
    def get_opt_spec(x):
        if isinstance(x, dict):
            return param_spec
        return None
    opt_state_spec, param_spec = jax.tree_util.tree_map(
        get_opt_spec, state_shapes, is_leaf=lambda x: isinstance(x, (dict, optax.EmptyState))
    )
    # pjit the get_initial_state function to shard params and init
    # optimizer state in sharded way
    p_get_initial_state = pjit(
        get_initial_state,
        in_axis_resources=None,
        out_axis_resources=(opt_state_spec, param_spec),
    )
    # hack: move the inital params to CPU to free up device memory
    # TODO: allow loading weights on CPU in pre-trained model
    model.params = jax.tree_util.tree_map(lambda x: np.asarray(x), model.params)
    # mesh defination
    mesh_devices = np.array(jax.devices()).reshape(1, jax.local_device_count())
    # actually initialize the opt_state
    with mesh(mesh_devices, ("dp", "mp")):
        opt_state, params = p_get_initial_state(freeze(model.params))
    # cross-entropy with z loss
    def loss_fn(logits, labels, z_loss=0):
        shift_logits = logits[..., :-1, :]
        shift_labels = labels[..., 1:]
        shift_labels = onehot(shift_labels, shift_logits.shape[-1])
        shift_logits = shift_logits - jax.lax.stop_gradient(shift_logits.max(axis=-1, keepdims=True))
        log_z = jnp.log(jnp.sum(jnp.exp(shift_logits), axis=-1, keepdims=True))
        log_softmax = shift_logits - log_z
        loss = -jnp.sum(shift_labels * log_softmax, axis=-1)
        loss += (1e-4 * jnp.square(log_z.squeeze(-1))) * z_loss
        return loss.mean()
    # Define gradient update step fn
    # TODO: try to use TrainState instead of passing params and opt_state individually
    def train_step(params, opt_state, dropout_rng, batch, step):
        dropout_rng, new_dropout_rng = jax.random.split(dropout_rng)
        def compute_loss(params):
            labels = batch.pop("labels")
            logits = model(**batch, params=params, dropout_rng=dropout_rng, train=True)[0]
            loss = loss_fn(logits, labels, z_loss=1.0)
            return loss
        grad_fn = jax.value_and_grad(compute_loss)
        loss, grads = grad_fn(params)
        updates, new_opt_state = optimizer.update(grads, opt_state, params)
        new_params = optax.apply_updates(params, updates)
        metrics = {"loss": loss, "learning_rate": linear_decay_lr_schedule_fn(step)}
        return new_params, tuple(new_opt_state), new_dropout_rng, metrics, step + 1
    # Define eval fn
    def eval_step(input_ids, labels, params):
        logits = model(input_ids=input_ids, params=params, train=False)[0]
        loss = loss_fn(logits, labels)
        # metrics
        return {"loss": loss}
    p_train_step = pjit(
        train_step,
        in_axis_resources=(param_spec, opt_state_spec, None, None, None),
        out_axis_resources=(param_spec, opt_state_spec, None, None, None),
        donate_argnums=(0, 1),
    )
    p_eval_step = pjit(
        eval_step,
        in_axis_resources=(None, None, param_spec),
        out_axis_resources=None,
    )
    logger.info("***** Running training *****")
    logger.info(f"  Num examples = {len(train_dataset)}")
    logger.info(f"  Num Epochs = {num_epochs}")
    logger.info(f"  Instantaneous batch size per device = {training_args.per_device_train_batch_size}")
    logger.info(f"  Total train batch size (w. parallel & distributed) = {train_batch_size}")
    logger.info(f"  Total optimization steps = {total_train_steps}")
    train_time = 0
    train_metrics = []
    epochs = tqdm(range(num_epochs), desc=f"Epoch ... (1/{num_epochs})", position=0)
    global_step = 0
    # we are not doing 2D parallelism (yet!), this just does model parallelism
    with mesh(mesh_devices, ("dp", "mp")):
        for _ in epochs:
            # ======================== Training ================================
            train_start = time.time()
            # Create sampling rng
            rng, input_rng = jax.random.split(rng)
            # Generate an epoch by shuffling sampling indices from the train dataset
            train_metrics = []
            train_loader = data_loader(input_rng, train_dataset, train_batch_size, shuffle=True)
            steps_per_epoch = len(train_dataset) // train_batch_size
            # train
            for _ in tqdm(range(steps_per_epoch), desc="Training...", position=1, leave=False):
                batch = next(train_loader)
                params, opt_state, dropout_rng, train_metric, global_step = p_train_step(
                    params,
                    opt_state,
                    dropout_rng,
                    batch,
                    global_step,
                )
                train_metrics.append(train_metric)
                cur_step = global_step
                if cur_step % training_args.logging_steps == 0 and cur_step > 0:
                    # Save metrics
                    train_time += time.time() - train_start
                    if has_tensorboard and jax.process_index() == 0:
                        write_train_metric(summary_writer, train_metrics, train_time, cur_step)
                    epochs.write(
                        f"Step... ({cur_step} | Loss: {train_metric['loss']}, Learning Rate:"
                        f" {train_metric['learning_rate']})"
                    )
                    train_metrics = []
                if cur_step % training_args.eval_steps == 0 and cur_step > 0:
                    # ======================== Evaluating ==============================
                    eval_metrics = []
                    eval_loader = data_loader(input_rng, eval_dataset, eval_batch_size)
                    eval_steps = len(eval_dataset) // eval_batch_size
                    for _ in tqdm(range(eval_steps), desc="Evaluating...", position=2, leave=False):
                        batch = next(eval_loader)
                        metrics = p_eval_step(batch["input_ids"], batch["labels"], params)
                        eval_metrics.append(metrics)
                    # normalize eval metrics
                    eval_metrics = stack_forest(eval_metrics)
                    eval_metrics = jax.tree_util.tree_map(jnp.mean, eval_metrics)
                    try:
                        eval_metrics["perplexity"] = math.exp(eval_metrics["loss"])
                    except OverflowError:
                        eval_metrics["perplexity"] = float("inf")
                    logger.info(
                        f"Step... ({cur_step} | Eval loss: {eval_metrics['loss']} | Eval Perplexity:"
                        f" {eval_metrics['perplexity']}"
                    )
                if cur_step % training_args.save_steps == 0 and cur_step > 0:
                    # save checkpoint after each epoch and push checkpoint to the hub
                    if jax.process_index() == 0:
                        params = jax.device_get(params)
                        model.save_pretrained(
                            training_args.output_dir,
                            params=params,
                            push_to_hub=training_args.push_to_hub,
                            commit_message=f"Saving weights and logs of step {cur_step}",
                        )
if __name__ == "__main__":
    main()

import json
import logging
import logging.config
import os
import pathlib
from functools import cache
from weathergen.common.config import _load_private_conf
LOGGING_CONFIG = """
{
    "version": 1,
    "disable_existing_loggers": false,
    "formatters": {
        "custom": {
            "class": "weathergen.common.logger.ColoredRelPathFormatter",
            "format": \
                "%(asctime)s %(process)d %(filename)s:%(lineno)d : %(levelname)-8s : %(message)s"
        }
    },
    "handlers": {
        "stdout": {
            "class": "logging.StreamHandler",
            "level": "INFO",
            "formatter": "custom",
            "stream": "ext://sys.stdout"
        },
        "stderr": {
            "class": "logging.StreamHandler",
            "level": "ERROR",
            "formatter": "custom",
            "stream": "ext://sys.stderr"
        },
        "logfile": {
            "class": "logging.FileHandler",
            "level": "DEBUG",
            "formatter": "custom",
            "filename": "log.txt",
            "mode": "w"
        },
        "errorfile": {
            "class": "logging.FileHandler",
            "level": "ERROR",
            "formatter": "custom",
            "filename": "error.txt",
            "mode": "w"
        }
    },
    "root": {
        "level": "DEBUG",
        "handlers": [
            "stderr",
            "stdout",
            "logfile",
            "errorfile"
        ]
    }
}
"""
class ColoredRelPathFormatter(logging.Formatter):
    COLOR_CODES = {
        logging.CRITICAL: "\033[1;35m",  # bright/bold magenta
        logging.ERROR: "\033[1;31m",  # bright/bold red
        logging.WARNING: "\033[1;33m",  # bright/bold yellow
        logging.INFO: "\033[0;37m",  # white / light gray
        logging.DEBUG: "\033[1;30m",  # bright/bold dark gray
    }
    RESET_CODE = "\033[0m"
    def __init__(self, color, *args, **kwargs):
        super(ColoredRelPathFormatter, self).__init__(*args, **kwargs)
        self.color = color
        self.root_path = pathlib.Path(__file__).parent.parent.parent.resolve()
    def format(self, record, *args, **kwargs):
        if self.color and record.levelno in self.COLOR_CODES:
            record.color_on = self.COLOR_CODES[record.levelno]
            record.color_off = self.RESET_CODE
        else:
            record.color_on = ""
            record.color_off = ""
        record.pathname = os.path.relpath(record.pathname, self.root_path)
        return super(ColoredRelPathFormatter, self).format(record, *args, **kwargs)
@cache
def init_loggers(run_id=None, logging_config=None):
    """
    Initialize the logger for the package and set output streams/files.
    WARNING: this function resets all the logging handlers.
    This function follows a singleton pattern, it will only operate once per process
    and will be a no-op if called again.
    Valid arguments for streams: tuple of
      sys.stdout, sys.stderr : standard out and err streams
      null : /dev/null
      string/pathlib.Path : specifies path and outfile to be used for stream
    Limitation: Using the same stream in a non-contiguous manner across logging levels, e.g.
                the same file for CRITICAL and WARNING but a different than for ERROR is currently
                not supported
    """
    # Get current time
    # Shelved until decided how to change logging directory structure
    # now = datetime.now()
    # timestamp = now.strftime("%Y-%m-%d-%H%M")
    # output_dir = f"./output/{timestamp}-{run_id}"
    output_dir = ""
    if run_id is not None:
        output_dir = f"./output/{run_id}"
    # load the structure for logging config
    if logging_config is None:
        logging_config = json.loads(LOGGING_CONFIG)
        if run_id is None:
            del logging_config["handlers"]["logfile"]
            del logging_config["handlers"]["errorfile"]
            del logging_config["root"]["handlers"][2:]
    for _, handler in logging_config["handlers"].items():
        for k, v in handler.items():
            if k == "formatter":
                handler[k] = v
            elif k == "filename":
                filename = f"{output_dir}/{run_id}-{v}"
                ofile = pathlib.Path(filename)
                # make sure the path is independent of path where job is launched
                if not ofile.is_absolute():
                    work_dir = pathlib.Path(_load_private_conf().get("path_shared_working_dir"))
                    ofile = work_dir / ofile
                pathlib.Path(ofile.parent).mkdir(parents=True, exist_ok=True)
                handler[k] = ofile
            else:
                continue
    # make sure the parent directory exists
    logging.config.dictConfig(logging_config)
    if output_dir:
        logging.info(f"Logging set up. Logs are in {output_dir}")
    else:
        logging.info("Logging set up. No log files created.")

from __future__ import annotations
import torch
from prettytable import PrettyTable
from typing import TYPE_CHECKING
from collections.abc import Sequence
import isaaclab.sim as sim_utils
import isaaclab.utils.math as math_utils
from isaaclab.assets import Articulation
from isaaclab.managers import ManagerBase, ManagerTermBase
from isaaclab.markers import VisualizationMarkers, VisualizationMarkersCfg
from .animation_manager_cfg import AnimationTermCfg
from .motion_data_manager import MotionDataTerm
if TYPE_CHECKING:
    from robolab.tasks.manager_based.amp.animation_env import AnimationEnv
class AnimationTerm(ManagerTermBase):
    cfg: AnimationTermCfg
    _env: AnimationEnv

    def __init__(self, cfg: AnimationTermCfg, env: AnimationEnv):
        super().__init__(cfg, env)

        if cfg.num_steps_to_use > 0:
            self.step_indices = torch.arange(0, cfg.num_steps_to_use, dtype=torch.long, device=env.device)
        elif cfg.num_steps_to_use < 0:
            self.step_indices = torch.arange(cfg.num_steps_to_use + 1, 1, dtype=torch.long, device=env.device)
        else:
            raise ValueError("num_steps_to_use cannot be zero.")

        # Get motion data term
        self.motion_data_term: MotionDataTerm = env.motion_data_manager.get_term(cfg.motion_data_term)

        # create buffers
        self.num_steps = len(self.step_indices)
        for component in cfg.motion_data_components:
            buffer_shape = (self.num_envs, self.num_steps)
            if component in ["root_pos_w", "root_vel_w", "root_vel_b", "root_ang_vel_w", "root_ang_vel_b"]:
                buffer_shape += (3,)
            elif component == "root_quat":
                buffer_shape += (4,)
            elif component in ["dof_pos", "dof_vel"]:
                num_dofs = self.motion_data_term.num_dofs
                buffer_shape += (num_dofs,)
            elif component == "key_body_pos_b":
                num_key_bodies = self.motion_data_term.num_key_bodies
                buffer_shape += (num_key_bodies, 3)
            else:
                raise ValueError(f"Unknown motion data component: {component}")
            setattr(self, f"{component}_buffer", torch.zeros(buffer_shape, device=env.device, dtype=torch.float32))
        # motion ids for each env
        self.motion_ids = torch.zeros(self.num_envs, device=env.device, dtype=torch.long)
        self.motion_fetch_time = torch.zeros((self.num_envs, self.num_steps), device=env.device, dtype=torch.float32)
        self.motion_durations = torch.zeros(self.num_envs, device=env.device, dtype=torch.float32)
        self.reset(torch.arange(self.num_envs))
        self._fetch_motion_data()

        if self.cfg.enable_visualization:
            self.vis_root_offset = torch.tensor(self.cfg.vis_root_offset, device=env.device, dtype=torch.float32).unsqueeze(0)  # (1, 3)

            marker_cfg = VisualizationMarkersCfg(
                prim_path="/Visuals/KeyBodyVisualizerFromTerm",
                markers={
                    "red_sphere": sim_utils.SphereCfg(
                        radius=0.03, 
                        visual_material=sim_utils.PreviewSurfaceCfg(diffuse_color=(1.0, 0.0, 0.0))
                    ),
                }
            )
            self.key_body_marker: VisualizationMarkers = VisualizationMarkers(marker_cfg)
    def reset(self, env_ids: Sequence[int] | None = None):
        if env_ids is None:
            return

        # resample motion ids for the reset envs
        self.motion_ids[env_ids] = self.motion_data_term.sample_motions(len(env_ids))
        self.motion_durations[env_ids] = self.motion_data_term.get_motion_durations(self.motion_ids[env_ids])

        truncate_time = self.num_steps * self._env.step_dt
        if self.cfg.random_initialize:
            # random start time
            if self.cfg.num_steps_to_use > 0:
                self.motion_fetch_time[env_ids, 0] = self.motion_data_term.sample_times(self.motion_ids[env_ids], truncate_time_end=truncate_time)
            else:
                self.motion_fetch_time[env_ids, 0] = self.motion_data_term.sample_times(self.motion_ids[env_ids], truncate_time_start=truncate_time)
        else:
            # start from beginning
            self.motion_fetch_time[env_ids, 0] = 0.0
        if self.num_steps > 1:
            self.motion_fetch_time[env_ids, 1:] = self.motion_fetch_time[env_ids, 0:1] + self.step_indices[1:].float() * self._env.step_dt
        self._fetch_motion_data(env_ids)
    def update(self, dt: float):
        if self.cfg.random_fetch:
            if self.cfg.num_steps_to_use > 0:
                self.motion_fetch_time[:, 0] = self.motion_data_term.sample_times(self.motion_ids, truncate_time_end=self.num_steps * dt)
            else: 
                self.motion_fetch_time[:, 0] = self.motion_data_term.sample_times(self.motion_ids, truncate_time_start=self.num_steps * dt)

            if self.num_steps > 1:
                self.motion_fetch_time[:, 1:] = self.motion_fetch_time[:, 0:1] + self.step_indices[1:].float() * dt

        self._fetch_motion_data()

        # Advance time
        if not self.cfg.random_fetch:
            self.motion_fetch_time += dt # only effective when random_fetch is False

        if self.cfg.enable_visualization:
            self._visualize()

    def _fetch_motion_data(self, env_ids: Sequence[int] | None = None):
        if env_ids is None:
            env_ids = torch.arange(self.num_envs, device=self._env.device)

        # Flatten for batch processing
        num_queries = len(env_ids) * self.num_steps
        motion_times_flat = self.motion_fetch_time[env_ids].reshape(-1)
        motion_ids_flat = self.motion_ids[env_ids].repeat_interleave(self.num_steps)

        # Sanity check
        assert motion_times_flat.shape[0] == num_queries
        assert motion_ids_flat.shape[0] == num_queries

        # Fetch motion data
        motion_data_dict = self.motion_data_term.get_motion_state(
            motion_ids=motion_ids_flat,
            motion_times=motion_times_flat
        )

        # Reshape and store in buffers
        for component in self.cfg.motion_data_components:
            if component in motion_data_dict:
                buffer_name = f"{component}_buffer"
                data = motion_data_dict[component]
                # Reshape: (num_envs * num_steps, *) -> (num_envs, num_steps, *)
                data_reshaped = data.view(len(env_ids), self.num_steps, *data.shape[1:])
                getattr(self, buffer_name)[env_ids, :, :] = data_reshaped

    def _visualize(self):
        # try to get the 'robot_anim' articulation
        robot_anim: Articulation = self._env.scene["robot_anim"]
        if robot_anim is None:
            print("[WARNING] AnimationTerm visualization: 'robot_anim' not found in the scene.")
            return

        # check if some necessary buffers are available
        if not hasattr(self, "root_pos_w_buffer") or not hasattr(self, "root_quat_buffer") or not hasattr(self, "dof_pos_buffer"):
            print("[WARNING] AnimationTerm visualization: 'root_pos_w_buffer' or 'root_quat_buffer' or 'dof_pos_buffer' not found.")
            return

        root_pos_w = self.root_pos_w_buffer[:, 0, :]  # (num_envs, 3)
        root_quat = self.root_quat_buffer[:, 0, :]    # (num_envs, 4)
        dof_pos = self.dof_pos_buffer[:, 0, :]        # (num_envs, num_dofs)

        root_states = robot_anim.data.default_root_state.clone()
        root_states[:, :3] = root_pos_w + self._env.scene.env_origins[:, :3] + self.vis_root_offset
        root_states[:, 3:7] = root_quat
        root_states[:, 7:10] = 0.0  # zero linear velocity
        root_states[:, 10:13] = 0.0  # zero angular velocity
        robot_anim.write_root_state_to_sim(root_states)

        joint_pos = robot_anim.data.default_joint_pos.clone()
        joint_pos[:, :] = dof_pos
        joint_vel = torch.zeros_like(robot_anim.data.default_joint_vel)
        robot_anim.write_joint_state_to_sim(joint_pos, joint_vel)

        key_body_pos_b = self.key_body_pos_b_buffer[:, 0, :, :]  # (num_envs, num_key_bodies, 3)
        num_key_bodies = key_body_pos_b.shape[1]
        key_body_pos_w = root_states[:, :3].unsqueeze(1) + math_utils.quat_apply(
            root_quat.unsqueeze(1).expand(-1, num_key_bodies, -1),
            key_body_pos_b
        )
        self.key_body_marker.visualize(
            translations=key_body_pos_w.reshape(-1, 3)
        )

    # Some helper functions
    def get_root_pos_w(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_pos_w_buffer"):
            raise AttributeError("root_pos_w_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_pos_w_buffer
        return self.root_pos_w_buffer[env_ids, :, :]

    def get_root_quat(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_quat_buffer"):
