    with pytest.raises(KeyError):
        precollator(sample)
def test_denormalize(precollator):
    sample = {
        "pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]]),
        "unchanged": torch.tensor([[7.0, 8.0], [9.0, 10.0]]),
    }
    normalized_sample = precollator(sample)
    denormalized_sample = {}
    for key, value in normalized_sample.items():
        new_key, new_value = precollator.inverse(key=key, value=value)
        assert new_key == key
        denormalized_sample[key] = new_value
    assert torch.equal(denormalized_sample["pressure"], sample["pressure"])
    assert torch.equal(denormalized_sample["unchanged"], sample["unchanged"])
def test_logscale():
    precollator = MomentNormalizationSampleProcessor(
        item="pressure",
        logmean=[0.0, 0.0],
        logstd=[1.0, 1.0],
        logscale=True,
    )
    sample = {"pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}
    normalized_sample = precollator(sample)
    assert torch.equal(normalized_sample["pressure"], to_logscale(sample["pressure"]))
    denormalized_sample = {}
    for key, value in normalized_sample.items():
        new_key, new_value = precollator.inverse(key=key, value=value)
        assert new_key == key
        denormalized_sample[key] = new_value
    assert torch.allclose(denormalized_sample["pressure"], sample["pressure"])
def test_denormalize_noop(precollator):
    og_sample = {"unchanged": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}
    denormalized_sample = {}
    for key, value in og_sample.items():
        new_key, new_value = precollator.inverse(key=key, value=value)
        assert new_key == key
        denormalized_sample[key] = new_value
    assert torch.equal(denormalized_sample["unchanged"], og_sample["unchanged"])

from typing import Optional
import jax
from flax import nnx
from tpu_inference.layers.jax import JaxModule
from tpu_inference.layers.jax.quantization import QuantizeMethodBase
from tpu_inference.layers.jax.quantization.configs import QuantizationConfig
class JaxEmbed(nnx.Embed, JaxModule):
    """Embedding layer for JAX."""
    def __init__(self,
                 *args,
                 quant_config: Optional[QuantizationConfig] = None,
                 prefix: str = "",
                 **kwargs):
        nnx.Embed.__init__(self, *args, **kwargs)
        # For compatibility. HF model use 'weight' as name suffix, we alias `self.embedding` to
        # `self.weight` such that `named_parameters()` can match the names in HF models.
        self.weight = self.embedding
        delattr(self, 'embedding')
        if hasattr(self.weight, "out_sharding"):
            self.weight.set_metadata('sharding', self.weight.out_sharding)
        self.quant_method = None
        if quant_config is not None:
            quant_method = quant_config.get_quant_method(self, prefix=prefix)
            if quant_method is not None:
                self.quant_method = quant_method
                assert isinstance(quant_method, QuantizeMethodBase)
                quant_method.create_weights_jax(self)
    def __getattr__(self, name: str):
        if name == "embedding":
            # nnx.Embed needs to access self.embedding
            return self.weight
    def __call__(self, x) -> jax.Array:
        if self.quant_method is None:
            return super().__call__(x)
        return self.quant_method.apply_jax(self, x)
    def decode(self, x: jax.Array) -> jax.Array:
        return jax.numpy.dot(x, self.weight.value.T)

import asyncio
from typing import Optional
import click
from storage.service import chat as chat_service
from storage.service.user import get_cli_user_id
from yagent.config import config
@click.command()
@click.option('--chat-id', '-c', help='ID of the chat to share')
@click.option('--latest', '-l', is_flag=True, help='Share the latest chat')
@click.option('--message-id', '-m', help='Share up to a specific message ID')
@click.option('--push', '-p', is_flag=True, help='Generate HTML and push to S3 (legacy)')
def share(chat_id: Optional[str], latest: bool, message_id: Optional[str], push: bool):
    """Share a chat conversation.
    Use --latest/-l to share your most recent chat.
    Use --chat-id/-c to share a specific chat ID.
    Use --push/-p to generate HTML and push to S3 (legacy behavior).
    """
    user_id = get_cli_user_id()
    # Handle --latest flag
    if latest:
        chats = asyncio.run(chat_service.list_chats(user_id, limit=1))
        if not chats:
            click.echo("Error: No chats found to share")
            raise click.Abort()
        chat_id = chats[0].chat_id
    elif not chat_id:
        raise click.Abort("Error: Chat ID is required for sharing")
    try:
        if push:
            # Legacy: generate HTML and push to S3
            tmp_file = asyncio.run(chat_service.generate_share_html(chat_id))
            if not config["s3_bucket"] or not config["cloudfront_distribution_id"]:
                click.echo("Error: S3 bucket and CloudFront distribution ID must be configured")
                click.echo("Please set S3_BUCKET and CLOUDFRONT_DISTRIBUTION_ID environment variables")
                raise click.Abort()
            os.system(f'open "{tmp_file}"')
            os.system(f'aws s3 cp "{tmp_file}" s3://{config["s3_bucket"]}/chat/{chat_id}.html > /dev/null')
            os.system(f'aws cloudfront create-invalidation --distribution-id {config["cloudfront_distribution_id"]} --paths "/chat/{chat_id}.html" > /dev/null')
            click.echo(f'https://{config["s3_bucket"]}/chat/{chat_id}.html')
        else:
            # Default: create DB share
            share_id = asyncio.run(chat_service.create_share(user_id, chat_id, message_id))
            click.echo(share_id)
    except ValueError as e:
        click.echo(f"Error: {str(e)}")
        raise click.Abort()

