    def __init__(
        self,
        parent,
        ignore_index=-100,
        audio_token_index=0,
        seq_length=7,
        feat_seq_length=60,
        text_config={
            "model_type": "qwen2",
            "intermediate_size": 36,
            "initializer_range": 0.02,
            "hidden_size": 32,
            "max_position_embeddings": 52,
            "num_hidden_layers": 2,
