from datetime import date, timedelta
from enum import StrEnum
from statgpt.app.schemas.query_builder import ChainState
from statgpt.app.services.chat_facade import VersionedDataSet
from statgpt.common.data.base import DataSetQuery, DimensionQuery, QueryOperator
from statgpt.common.utils.timer import debug_timer
_log = logging.getLogger(__name__)
class FrequencyEnum(StrEnum):
    ANNUAL = 'A'
    QUARTERLY = 'Q'
    MONTHLY = 'M'
    WEEKLY = 'W'
    DAILY = 'D'
    @classmethod
    def ordered_values(cls) -> list[str]:
        return [cls.ANNUAL, cls.QUARTERLY, cls.MONTHLY, cls.WEEKLY, cls.DAILY]
def _date_time_query_to_values(date_time_query: DimensionQuery) -> tuple[str | None, str | None]:
    if date_time_query.operator == QueryOperator.BETWEEN:
        # Validate that we have at least 2 values for BETWEEN operator
        if len(date_time_query.values) < 2:
            _log.warning(f"BETWEEN operator requires 2 values, got {len(date_time_query.values)}")
            # Return first value as start if available
            return date_time_query.values[0] if date_time_query.values else None, None
        return date_time_query.values[0], date_time_query.values[1]
    elif date_time_query.operator == QueryOperator.GREATER_THAN_OR_EQUALS:
        return date_time_query.values[0] if date_time_query.values else None, None
    elif date_time_query.operator == QueryOperator.LESS_THAN_OR_EQUALS:
        return None, date_time_query.values[0] if date_time_query.values else None
    _log.warning(f"Unsupported date time operator: {date_time_query.operator}")
    return None, None
def _frequency_query_to_value(frequency_query: DimensionQuery) -> str | None:
    if frequency_query.operator not in [QueryOperator.IN, QueryOperator.ALL]:
        _log.warning(f"Unsupported frequency operator: {frequency_query.operator}")
        return None
    for freq in FrequencyEnum.ordered_values():
        if freq in frequency_query.values:
            return freq
    _log.warning(f"Unsupported frequency values: {frequency_query.values}")
    return None
def _adjust_start_date(value: str, frequency: FrequencyEnum) -> str:
    try:
        dt = date.fromisoformat(value)
    except ValueError:
        _log.warning(f"Invalid date format was passed to _adjust_start_date: {value}")
        return value
    if frequency == FrequencyEnum.ANNUAL:
        return dt.replace(month=1, day=1).isoformat()
    elif frequency == FrequencyEnum.QUARTERLY:
        quarter = (dt.month - 1) // 3 + 1
        month = (quarter - 1) * 3 + 1
        return dt.replace(month=month, day=1).isoformat()
    elif frequency == FrequencyEnum.MONTHLY:
        return dt.replace(day=1).isoformat()
    elif frequency == FrequencyEnum.WEEKLY:
        start_of_week = dt - timedelta(days=dt.weekday())
        return start_of_week.isoformat()
    elif frequency == FrequencyEnum.DAILY:
        return value
    else:
        _log.warning(f"Unsupported frequency: {frequency}")
        return value
def _adjust_end_date(value: str, frequency: FrequencyEnum) -> str:
    try:
        dt = date.fromisoformat(value)
    except ValueError:
        _log.warning(f"Invalid date format was passed to _adjust_end_date: {value}")
        return value
    if frequency == FrequencyEnum.ANNUAL:
        return dt.replace(month=12, day=31).isoformat()
    elif frequency == FrequencyEnum.QUARTERLY:
        quarter = (dt.month - 1) // 3 + 1
        month = quarter * 3
        if month == 12:
            # December - get last day directly
            last_day = 31
        else:
            last_day = (dt.replace(month=month + 1, day=1) - timedelta(days=1)).day
        return dt.replace(month=month, day=last_day).isoformat()
    elif frequency == FrequencyEnum.MONTHLY:
        if dt.month == 12:
            # December - get last day directly
            last_day = 31
        else:
            last_day = (dt.replace(month=dt.month + 1, day=1) - timedelta(days=1)).day
        return dt.replace(day=last_day).isoformat()
    elif frequency == FrequencyEnum.WEEKLY:
        end_of_week = dt + timedelta(days=(6 - dt.weekday()))
        return end_of_week.isoformat()
    elif frequency == FrequencyEnum.DAILY:
        return value
    else:
        _log.warning(f"Unsupported frequency: {frequency}")
        return value
def _expand_time_range_query(dataset: VersionedDataSet, query: DataSetQuery) -> DataSetQuery:
    date_time_dimension = dataset.data.get_time_dimension()
    frequency_dimension = dataset.data.get_frequency_dimension()
    date_time_query = next(
        (q for q in query.dimensions_queries if q.dimension_id == date_time_dimension.entity_id),
        None,
    )
    frequency_query = next(
        (q for q in query.dimensions_queries if q.dimension_id == frequency_dimension.entity_id),
        None,
    )
    if not date_time_query or not frequency_query:
        return query
    frequency = _frequency_query_to_value(frequency_query)
    if not frequency:
        return query
    start_date, end_date = _date_time_query_to_values(date_time_query)
    if start_date:
        start_date = _adjust_start_date(start_date, FrequencyEnum(frequency))
    if end_date:
        end_date = _adjust_end_date(end_date, FrequencyEnum(frequency))
    new_date_time_query = DimensionQuery(
        dimension_id=date_time_query.dimension_id,
        operator=date_time_query.operator,
        values=[v for v in [start_date, end_date] if v is not None],
        is_default=date_time_query.is_default,
    )
    return DataSetQuery(
        is_valid=query.is_valid,
        dimensions_queries=[
            *(
                q
                for q in query.dimensions_queries
                if q.dimension_id != date_time_dimension.entity_id
            ),
            new_date_time_query,
        ],
    )
def expand_time_range(inputs: dict) -> dict[str, DataSetQuery]:
    with debug_timer("_expand_time_range"):
        chain_state = ChainState(**inputs)
        result = {}
        for dataset_id, query in chain_state.dataset_queries.items():
            dataset = chain_state.datasets_dict[dataset_id]
            result[dataset_id] = _expand_time_range_query(dataset, query)
        return result

import os
import argparse
from typing import Optional
from cosmos_rl.dispatcher.data.packer.base import worker_entry_parser
from cosmos_rl.utils.logging import logger
from cosmos_rl.rollout.worker.llm_worker import LLMRolloutWorker
def run_rollout(args: Optional[argparse.Namespace] = None, **kwargs):
    # This means that args are not parsed in dataset entry script
    # So we need to parse the args manually
    assert os.environ.get("TP_EP_INTERCHANGABLE_WITH_DP_FUSED", "0").lower() in [
        "0",
        "false",
    ], "TP_EP_INTERCHANGABLE_WITH_DP_FUSED must be set to 0 for rollout"
    if args is None:
        parser = worker_entry_parser()
        try:
            args = parser.parse_args()
        except SystemExit as e:
            logger.error(
                "Error when parsing args. Did you use custom arguments in your script? If so, please check your custom script and pass `args` to this main function."
            )
            raise e
    is_wfm = os.environ.get("COSMOS_IS_WFM", "False").lower() == "true"
    if is_wfm:
        raise NotImplementedError(
            "WFM rollout is not supported with this entrance script yet."
        )
    else:
        rollout_worker = LLMRolloutWorker(**kwargs)
    rollout_worker.execute()
if __name__ == "__main__":
    run_rollout()

from collections.abc import Sequence
import torch
from noether.data.preprocessors.types import ScalarOrSequence
def to_tensor(data: ScalarOrSequence) -> torch.Tensor:
    """
    Helper function to convert input data to a PyTorch tensor if it is not already one.
    Args:
        data: The input data to convert. Can be a sequence of floats, a torch.Tensor, or None.
    Returns: The input data as a torch.Tensor if it was a sequence, the original tensor if it was already a torch.Tensor, or None if the input was None.
    Raises:
        TypeError: If the input data is of an unsupported type.
    """
    if isinstance(data, torch.Tensor):
        return data
    if isinstance(data, Sequence | float | int):
        try:
            return torch.tensor(data)
        except ValueError as e:
            raise ValueError(
                f"Failed to convert {data} to a tensor: {e} since dimensions are not compatible or data is wrong."
            ) from e
    else:
        raise TypeError(f"Unsupported data type: {type(data)}. Data must be a Sequence, torch.Tensor, or None.")

import re
from dashscope import Generation
def simplify_params_for_prompt(param_schema):
    props = param_schema.get("properties", {})
    required = set(param_schema.get("required", []))
    desc_lines = []
    for name, info in props.items():
        ptype = info.get("type", "unknown")
        is_required = name in required
        opt_text = " (required)" if is_required else " (optional, default: " + str(info.get("default", "N/A")) + ")"
        desc_lines.append(f"  - {name}: {ptype}{opt_text}")
    return "\n".join(desc_lines) if desc_lines else "  (no parameters)"
def build_prompt(content: str, functions: list) -> str:
    prompt = (
        "You are a precise function router. Given a user question and a list of available functions, "
        "select exactly one function that can best answer the question.\n\n"
        "Respond ONLY with a JSON object containing two keys:\n"
        '- "name": the function name as a string,\n'
        '- "arguments": a JSON STRING (not object) containing only the required parameter values inferred from the question.\n'
        "Do NOT include optional parameters that use default values unless explicitly mentioned.\n"
        "Do NOT output any other text, explanation, or markdown.\n\n"
        f'User question: "{content}"\n\n'
        "Available functions:\n"
    )
    for i, func in enumerate(functions, 1):
        name = func["name"]
        desc = func.get("description", "No description.")
        params_desc = simplify_params_for_prompt(func["parameters"])
        prompt += f"{i}. Function name: `{name}`\n   Description: {desc}\n   Parameters:\n{params_desc}\n\n"
    prompt += "Your response:"
    return prompt
def extract_and_stringify_arguments(text: str) -> dict:
    text = text.strip()
    outer_obj = None
    try:
        outer_obj = json.loads(text)
    except json.JSONDecodeError:
        match = re.search(r"```(?:json)?\s*({.*?})\s*```", text, re.DOTALL | re.IGNORECASE)
        if match:
            try:
                outer_obj = json.loads(match.group(1))
            except json.JSONDecodeError:
                print(f"Found invalid json format in pattern match: {match}")
    if outer_obj and isinstance(outer_obj, dict):
        name = outer_obj.get("name")
        args = outer_obj.get("arguments", {})
        if isinstance(args, str):
            try:
                json.loads(args)
                arguments_str = args
            except json.JSONDecodeError:
                arguments_str = "{}"
                print(f"Found invalid json format in arguments, set to {arguments_str}")
        elif isinstance(args, dict):
            arguments_str = json.dumps(args)
        else:
            arguments_str = "{}"
        return {"name": name, "arguments": arguments_str}
    return {"name": "", "arguments": "{}"}
def process_jsonl(input_path: str, output_path: str):
    with open(input_path, "r", encoding="utf-8") as fin, open(output_path, "w", encoding="utf-8") as fout:
        for line_num, line in enumerate(fin, 1):
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
                content = record["question"][0][0]["content"]
                functions = record["function"]
                prompt = build_prompt(content, functions)
                response = Generation.call(
                    model="qwen-max", messages=[{"role": "user", "content": prompt}], temperature=0.0
                )
                reply = response.output.text
                result = extract_and_stringify_arguments(reply)
                result = json.dumps(result, ensure_ascii=False)
                print(f"id {line_num}, result: {result}")
                fout.write(result + "\n")
                fout.flush()
            except Exception as e:
                print(f"Error on line {line_num}: {e}")
                fout.write('{"name": null, "arguments": "{}"}\n')
