def strip_path_pattern_function_js(path_pattern: str) -> str:
    path_len = len(path_pattern)
    return f"""
        function handler(event) {{
            var request = event.request;
            var uri = request.uri;
            if (uri === '{path_pattern}') {{
                request.uri = '/';
            }} else if (uri.substr(0, {path_len + 1}) === '{path_pattern}/') {{
                request.uri = uri.substr({path_len});
            }}
            return request;
        }}
        """.strip()
def set_custom_host_header(host: str) -> str:
    """Generate Lambda@Edge code to set a custom Host header for URL origins.
    This is necessary when proxying to external URLs that use virtual host routing.
    """
    # https://serverfault.com/a/888776
    return """
        'use strict';
        // force a specific Host header to be sent to the origin
        exports.handler = (event, context, callback) => {
            const request = event.Records[0].cf.request;
            request.headers.host[0].value = '{host}';
            return callback(null, request);
        };
        """.replace("{host}", host).strip()

import argparse, json, os, glob
from datetime import datetime
import yaml
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TASK_DIR = os.path.join(ROOT, 'control-plane', 'tasks')
EVENTS = os.path.join(ROOT, 'control-plane', 'logs', 'events.jsonl')
VALID = {'INBOX','CLAIMED','IN_PROGRESS','REVIEW','DONE','BLOCKED','FAILED'}
TRANSITIONS = {
    'INBOX': {'CLAIMED'},
    'CLAIMED': {'IN_PROGRESS','INBOX'},
    'IN_PROGRESS': {'REVIEW','BLOCKED','FAILED'},
    'REVIEW': {'DONE','BLOCKED','FAILED'},
    'DONE': set(),'BLOCKED': set(),'FAILED': set()
}
def now():
    return datetime.now().astimezone().isoformat()
def load(path):
    with open(path,'r',encoding='utf-8') as f:
        return yaml.safe_load(f)
def save(path,data):
    with open(path,'w',encoding='utf-8') as f:
        yaml.safe_dump(data,f,sort_keys=False,allow_unicode=True)
def event(rec):
    with open(EVENTS,'a',encoding='utf-8') as f:
        f.write(json.dumps(rec,ensure_ascii=False)+"\n")
def find(task_id):
    for p in glob.glob(os.path.join(TASK_DIR,'*.yaml')):
        d = load(p)
        if d.get('task_id') == task_id:
            return p,d
    raise SystemExit(f'task not found: {task_id}')
def cmd_list(_):
    rows=[]
    for p in sorted(glob.glob(os.path.join(TASK_DIR,'*.yaml'))):
        d=load(p)
        rows.append((d.get('task_id'),d.get('status'),d.get('owner'),os.path.basename(p)))
    for r in rows:
        print('\t'.join([str(x) for x in r]))
def cmd_transition(a):
    p,d=find(a.task_id)
    cur=d.get('status')
    nxt=a.to
    if nxt not in VALID:
        raise SystemExit('invalid target status')
    if nxt not in TRANSITIONS.get(cur,set()):
        raise SystemExit(f'invalid transition: {cur}->{nxt}')
    if nxt=='CLAIMED' and not a.actor:
        raise SystemExit('CLAIMED requires --actor owner')
    if cur=='IN_PROGRESS' and nxt=='REVIEW' and (a.actor and a.actor==d.get('owner')):
        raise SystemExit('self-review forbidden')
    d['status']=nxt
    d['updated_at']=now()
    if nxt=='CLAIMED':
        d['owner']=a.actor
        d['claimed_at']=now()
    save(p,d)
    event({'ts':now(),'type':'task_transition','task_id':a.task_id,'from':cur,'to':nxt,'actor':a.actor})
    print(f'{a.task_id}: {cur} -> {nxt}')
def main():
    ap=argparse.ArgumentParser()
    sp=ap.add_subparsers(required=True)
    l=sp.add_parser('list'); l.set_defaults(func=cmd_list)
    t=sp.add_parser('transition')
    t.add_argument('--task-id',required=True)
    t.add_argument('--to',required=True)
    t.add_argument('--actor',required=False)
    t.set_defaults(func=cmd_transition)
    a=ap.parse_args(); a.func(a)
if __name__=='__main__':
    main()

from diffusers.modular_pipelines import ModularPipelineBlocks, PipelineState
from diffusers.modular_pipelines.modular_pipeline_utils import (
    ComponentSpec,
    InputParam,
    OutputParam,
)
class PrepareContextFramesBlock(ModularPipelineBlocks):
    @property
    def expected_components(self) -> list[ComponentSpec]:
        return [
            ComponentSpec("generator", torch.nn.Module),
        ]
    @property
    def description(self) -> str:
        return "Prepare Context Frames block updates buffers tracking context frames used in KV cache recomputation"
    @property
    def inputs(self) -> list[InputParam]:
        return [
            InputParam(
                "latents",
                required=True,
                type_hint=torch.Tensor,
                description="Denoised latents",
            ),
            InputParam(
                "output_video",
                required=True,
                type_hint=torch.Tensor,
                description="Decoded video frames",
            ),
            InputParam(
                "current_start_frame",
                required=True,
                type_hint=int,
                description="Current starting frame index of current block",
            ),
            InputParam(
                "context_frame_buffer_max_size",
                type_hint=int,
                description="Max size of context frame buffer",
            ),
            InputParam(
                "decoded_frame_buffer_max_size",
                type_hint=int,
                description="Max size of decoded frame buffer",
            ),
            InputParam(
                "context_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of latent frames",
            ),
            InputParam(
                "decoded_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of decoded frames",
            ),
            InputParam(
                "first_context_frame",
                type_hint=torch.Tensor,
                description="First frame of first block",
            ),
        ]
    @property
    def intermediate_outputs(self) -> list[OutputParam]:
        return [
            OutputParam(
                "first_context_frame",
                type_hint=torch.Tensor,
                description="First frame of first block",
            ),
            OutputParam(
                "context_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of latent frames",
            ),
            OutputParam(
                "decoded_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of decoded frames",
            ),
        ]
    @torch.no_grad()
    def __call__(self, components, state: PipelineState) -> tuple[any, PipelineState]:
        block_state = self.get_block_state(state)
        if block_state.current_start_frame == 0:
            block_state.first_context_frame = block_state.latents[:, :1]
        if block_state.context_frame_buffer_max_size > 0:
            block_state.context_frame_buffer = torch.cat(
                [
                    block_state.context_frame_buffer,
                    block_state.latents.to(
                        block_state.context_frame_buffer.device,
                        block_state.context_frame_buffer.dtype,
                    ),
                ],
                dim=1,
            )[:, -block_state.context_frame_buffer_max_size :]
        if block_state.decoded_frame_buffer_max_size > 0:
            block_state.decoded_frame_buffer = torch.cat(
                [
                    block_state.decoded_frame_buffer,
                    block_state.output_video.to(
                        block_state.decoded_frame_buffer.device,
                        block_state.decoded_frame_buffer.dtype,
                    ),
                ],
                dim=1,
            )[:, -block_state.decoded_frame_buffer_max_size :]
        self.set_block_state(state, block_state)
        return components, state

