from aoc2021.util import print_solutions, import_strs
import timeit

# Define marker for marked cells
Mark = "M"

def part_1(inputs):
    called, boards = inputs

    # Iterate through each called number
    for target in called:
        # Check each board
        for board in boards:
            if mark_board(board, target) and check_board(board):
                return score_board(board) * target

    return None

def score_board(board):
    score = 0
    # Flatten the board and sum unmarked numbers
    for num in sum(board, []):
        if num != Mark:
            score += num
    return score

def mark_board(board, target):
    marked = False
    # Mark the target number on the board
    for row in board:
        for col_idx, num in enumerate(row):
            if num == target:
                row[col_idx] = Mark
                marked = True
    return marked

def check_board(board):
    cols = []

    # Build columns from rows
    for idx in range(len(board[0])):
        cols.append([row[idx] for row in board])

    # Check all rows and columns for complete marks
    for row in board + cols:
        if not list(filter(lambda n: n != Mark, row)):
            return True

    return False

def read_bingo(path):
    with open(path) as f:
        lines = f.readlines()

    # Parse first line for called numbers
    first_line = lines[0].strip()
    called = [int(d) for d in first_line.split(",")]

    # Remove first line
    lines.pop(0)

    board = []
    boards = []

    # Parse boards
    for line in lines:
        line = line.strip()

        # Empty line indicates end of current board
        if not line:
            if board:
                boards.append(board)
                board = []
            continue

        # Parse row numbers
        row = [int(d) for d in line.split(" ") if d]
        board.append(row)

    # Add last board if exists
    if board:
        boards.append(board)

    return (called, boards)

def part_2(inputs):
    called, boards = inputs
    last_score = None

    # Process each called number
    for target in called:
        # Remove already completed boards
        boards[:] = [b for b in boards if b]

        # Stop if no boards left
        if not boards:
            break

        # Process each remaining board
        for idx, board in enumerate(boards):
            # Debug output (can be removed)
            if score_board(board) == 148:
                print(board)

            # Mark and check if board wins
            if mark_board(board, target) and check_board(board):
                last_score = score_board(board) * target
                boards[idx] = None

    return last_score

def main():
    print_solutions(
        ["resources/day4-test.txt", "resources/day4.txt"],
        #["resources/day4-test.txt"],
        read_bingo,
        part_2
    )

if __name__ == "__main__":
    main()

import hashlib
from .utils import (
    detect_spatialite,
    detect_fts,
    escape_sqlite,
    get_all_foreign_keys,
    sqlite3
)

# Block size for hashing (1 MB)
HASH_BLOCK_SIZE = 1024 * 1024

def inspect_hash(path):
    # Calculate the hash of a database, efficiently.
    m = hashlib.sha256()
    with path.open("rb") as fp:
        while True:
            data = fp.read(HASH_BLOCK_SIZE)
            if not data:
                break
            m.update(data)
    return m.hexdigest()

def inspect_views(conn):
    # List views in a database.
    return [v[0] for v in conn.execute('select name from sqlite_master where type = "view"')]

def detect_label_column(column_names):
    """
    Detect the label column - which we display as the label for a joined column.
    If a table has two columns, one of which is ID, then label_column is the other one.
    """
    if (column_names and len(column_names) == 2 and "id" in column_names):
        return [c for c in column_names if c != "id"][0]
    return None

def detect_primary_keys(conn, table):
    # Figure out primary keys for a table.
    table_info_rows = [
        row
        for row in conn.execute(
            'PRAGMA table_info("{}")'.format(table)
        ).fetchall()
        if row[-1]
    ]
    table_info_rows.sort(key=lambda row: row[-1])
    return [str(r[1]) for r in table_info_rows]

def inspect_tables(conn, database_metadata):
    # List tables and their row counts, excluding uninteresting tables.
    tables = {}
    table_names = [
        r["name"]
        for r in conn.execute(
            'select * from sqlite_master where type="table"'
        )
    ]

    for table in table_names:
        table_metadata = database_metadata.get("tables", {}).get(
            table, {}
        )
        try:
            count = conn.execute(
                "select count(*) from {}".format(escape_sqlite(table))
            ).fetchone()[0]
        except sqlite3.OperationalError:
            # This can happen when running against a FTS virtual table
            # e.g. "select count(*) from some_fts;"
            count = 0

        column_names = [
            r[1]
            for r in conn.execute(
                "PRAGMA table_info({});".format(escape_sqlite(table))
            ).fetchall()
        ]

        tables[table] = {
            "name": table,
            "columns": column_names,
            "primary_keys": detect_primary_keys(conn, table),
            "count": count,
            "label_column": detect_label_column(column_names),
            "hidden": table_metadata.get("hidden") or False,
            "fts_table": detect_fts(conn, table),
        }

    foreign_keys = get_all_foreign_keys(conn)
    for table, info in foreign_keys.items():
        tables[table]["foreign_keys"] = info

    # Mark tables 'hidden' if they relate to FTS virtual tables
    hidden_tables = [
        r["name"]
        for r in conn.execute(
            """
                select name from sqlite_master
                where rootpage = 0
                and sql like '%VIRTUAL TABLE%USING FTS%'
            """
        )
    ]

    if detect_spatialite(conn):
        # Also hide Spatialite internal tables
        hidden_tables += [
            "ElementaryGeometries",
            "SpatialIndex",
            "geometry_columns",
            "spatial_ref_sys",
            "spatialite_history",
            "sql_statements_log",
            "sqlite_sequence",
            "views_geometry_columns",
            "virts_geometry_columns",
        ] + [
            r["name"]
            for r in conn.execute(
                """
                    select name from sqlite_master
                    where name like "idx_%"
                    and type = "table"
                """
            )
        ]

    for t in tables.keys():
        for hidden_table in hidden_tables:
            if t == hidden_table or t.startswith(hidden_table):
                tables[t]["hidden"] = True
                continue

    return tables

# Import necessary modules
import os
import subprocess
import tempfile
from typing import (
    Dict,
    Iterator,
)

class Repository(object):
    """Represents a git repository containing a python project."""

    def __init__(self, path: str) -> None:
        # Initialize dictionary to store file contents
        self.files = dict()  # type: Dict[str, str]

        try:
            with tempfile.TemporaryDirectory() as tempdir:
                # Clone the repository into temporary directory
                subprocess.run(['git', 'clone', path, tempdir])

                # Process each Python file in the repository
                for filename in self._get_files(tempdir):
                    try:
                        with open(filename, 'r') as fin:
                            self.files[filename] = fin.read()
                    except Exception as ex:
                        print(f'Unable to read from file {filename}: {ex}')
        except Exception as ex:
            print(f'Unable to create temporary directory: {ex}')

    def _get_files(self, tempdir: str) -> Iterator[str]:
        """Generator that yields all Python files in the given directory."""
        for dirpath, _, filenames in os.walk(tempdir):
            for filename in filenames:
                if filename.endswith('.py'):
                    yield os.path.join(dirpath, filename)

    @property
    def python_files(self) -> Dict[str, str]:
        """Returns dictionary mapping file paths to their contents."""
        return self.files

