from bson.binary import Binary
from typing import Union, Dict, Any, Optional, List
from ampel.types import StockId, ChannelId, StrictIterable, strict_iterable
from ampel.model.operator.AnyOf import AnyOf
from ampel.model.operator.AllOf import AllOf
from ampel.model.operator.OneOf import OneOf
from ampel.util.collections import check_seq_inner_type
from ampel.mongo.utils import maybe_match_array
from ampel.mongo.query.general import build_general_query


def build_stateless_query(
    stock: Optional[Union[StockId, StrictIterable[StockId]]] = None,
    channel: Optional[Union[ChannelId, Dict, AllOf[ChannelId], AnyOf[ChannelId], OneOf[ChannelId]]] = None,
    t2_subsel: Union[int, str, StrictIterable[Union[int, str]]] = None
) -> Dict[str, Any]:
    """
    | Builds a pymongo query dict aiming at loading transient t2 or compounds docs \
    | Stateless query: all avail compounds and t2docs (although possibly \
    constrained by parameter t2_subsel) are targeted.

    :param stock: (query can be performed on multiple ids at once)
    :param channel: see :obj:`QueryMatchSchema <ampel.query.QueryMatchSchema>` for details. \
    None (no criterium) means all channels are considered.
    :param t2_subsel: optional sub-selection of t2 records based on t2 class names. \
    -> only t2 records matching with the provided t2 class names will be returned. \
    If None (or empty iterable): all t2 docs associated with the matched transients will be targeted.
    """
    # Build base query using general query builder
    query = build_general_query(stock=stock, channel=channel)

    # Apply t2_subsel filter if provided
    if t2_subsel:
        query['unit'] = t2_subsel if isinstance(t2_subsel, (str, int)) else maybe_match_array(t2_subsel)

    return query


def build_statebound_t1_query(
    states: Union[str, bytes, Binary, StrictIterable[Union[str, bytes, Binary]]],
) -> Dict[str, Any]:
    """Builds a state-bound T1 query."""
    return {'_id': get_compound_match(states)}


def build_statebound_t2_query(
    stock: Optional[Union[StockId, StrictIterable[StockId]]],
    states: Union[str, bytes, Binary, StrictIterable[Union[str, bytes, Binary]]],
    channel: Optional[Union[ChannelId, Dict, AllOf[ChannelId], AnyOf[ChannelId], OneOf[ChannelId]]] = None,
    t2_subsel: Union[int, str, StrictIterable[Union[int, str]]] = None
) -> Dict[str, Any]:
    """
    See :func:`build_stateless_query <build_stateless_query>` docstring
    """
    # Build base query
    query = build_general_query(stock=stock, channel=channel)

    # Add state-based link constraint
    query['link'] = get_compound_match(states)

    # Apply t2_subsel filter if provided
    if t2_subsel:
        query['unit'] = t2_subsel if isinstance(t2_subsel, (str, int)) else maybe_match_array(t2_subsel)

    return query


def _to_binary(st: Union[str, bytes, Binary]) -> Binary:
    """Convert input to Binary format with validation."""
    if isinstance(st, str):
        if len(st) == 32:
            return Binary(bytes.fromhex(st), 0)
        else:
            raise ValueError("Provided state strings must have 32 characters")
    elif isinstance(st, bytes):
        if len(st) == 16:
            return Binary(st, 0)
        else:
            raise ValueError("Provided state bytes must have a length of 16")
    else:
        if st.subtype == 0:
            return st
        else:
            raise ValueError("Bson Binary states must have subtype 0")


def get_compound_match(
    states: Union[str, bytes, Binary, StrictIterable[Union[str, bytes, Binary]]],
) -> Union[Binary, Dict[str, List[Binary]]]:
    """
    :raises ValueError: if provided states parameter is invalid
    """
    # Single state was provided
    if isinstance(states, (str, bytes, Binary)):
        return _to_binary(states)
    # Multiple states were provided
    elif isinstance(states, strict_iterable):
        return {
            '$in': [_to_binary(st) for st in states]
        }
    else:
        raise ValueError(
            f"Type of provided state ({type(states)}) must be "
            f"bytes, str, bson.Binary or sequences of these"
        )

import enum
import logging
from typing import Any, Callable, Dict, Iterable, List, Optional, Tuple

from .schema_utils import JsonSchema, SchemaEnum

logger = logging.getLogger(__name__)


class DiscoveredEnums(object):
    def __init__(
        self,
        enums: Optional[SchemaEnum] = None,
        children: Optional[Dict[str, "DiscoveredEnums"]] = None,
    ) -> None:
        self.enums = enums
        self.children = children

    def __str__(self) -> str:
        def val_as_str(v):
            if v is None:
                return "null"
            elif isinstance(v, str):
                return f"'{v}'"
            else:
                return str(v)

        en = ""
        if self.enums:
            ens = [val_as_str(v) for v in self.enums]
            en = ", ".join(sorted(ens))

        ch = ""
        if self.children:
            chs = [f"{str(k)}->{str(v)}" for k, v in self.children.items()]
            ch = ",".join(chs)

        if en and ch:
            en = en + "; "

        return "<" + en + ch + ">"


def schemaToDiscoveredEnums(schema: JsonSchema) -> Optional[DiscoveredEnums]:
    """Given a schema, returns a positive enumeration set.
    This is very conservative, and even includes negated enum constants
    (since the assumption is that they may, in some contexts, be valid)
    """

    def combineDiscoveredEnums(
        combine: Callable[[Iterable[SchemaEnum]], Optional[SchemaEnum]],
        des: Iterable[Optional[DiscoveredEnums]],
    ) -> Optional[DiscoveredEnums]:
        enums: List[SchemaEnum] = []
        children: Dict[str, List[DiscoveredEnums]] = {}

        for de in des:
            if de is None:
                continue

            if de.enums is not None:
                enums.append(de.enums)

            if de.children is not None:
                for cn, cv in de.children.items():
                    if cv is None:
                        continue
                    if cn in children:
                        children[cn].append(cv)
                    else:
                        children[cn] = [cv]

        combined_enums: Optional[SchemaEnum] = None
        if enums:
            combined_enums = combine(enums)

        if not children:
            if combined_enums is None:
                return None
            else:
                return DiscoveredEnums(enums=combined_enums)
        else:
            combined_children: Dict[str, DiscoveredEnums] = {}
            for ccn, ccv in children.items():
                if not ccv:
                    continue
                ccvc = combineDiscoveredEnums(combine, ccv)
                if ccvc is not None:
                    combined_children[ccn] = ccvc

            return DiscoveredEnums(enums=combined_enums, children=combined_children)

    def joinDiscoveredEnums(
        des: Iterable[Optional[DiscoveredEnums]],
    ) -> Optional[DiscoveredEnums]:
        def op(args: Iterable[SchemaEnum]) -> Optional[SchemaEnum]:
            return set.union(*args)

        return combineDiscoveredEnums(op, des)

    def meetDiscoveredEnums(
        des: Tuple[Optional[DiscoveredEnums], ...]
    ) -> Optional[DiscoveredEnums]:
        def op(args: Iterable[SchemaEnum]) -> Optional[SchemaEnum]:
            return set.intersection(*args)

        return combineDiscoveredEnums(op, des)

    if schema is True or schema is False:
        return None

    if "enum" in schema:
        # TODO: we should validate the enum elements according to the schema, like schema2search_space does
        return DiscoveredEnums(enums=set(schema["enum"]))

    if "type" in schema:
        typ = schema["type"]
        if typ == "object" and "properties" in schema:
            props = schema["properties"]
            pret: Dict[str, DiscoveredEnums] = {}
            for p, s in props.items():
                pos = schemaToDiscoveredEnums(s)
                if pos is not None:
                    pret[p] = pos
            if pret:
                return DiscoveredEnums(children=pret)
            else:
                return None
        else:
            return None

    if "not" in schema:
        neg = schemaToDiscoveredEnums(schema["not"])
        return neg

    if "allOf" in schema:
        posl = [schemaToDiscoveredEnums(s) for s in schema["allOf"]]
        return joinDiscoveredEnums(posl)

    if "anyOf" in schema:
        posl = [schemaToDiscoveredEnums(s) for s in schema["anyOf"]]
        return joinDiscoveredEnums(posl)

    if "oneOf" in schema:
        posl = [schemaToDiscoveredEnums(s) for s in schema["oneOf"]]
        return joinDiscoveredEnums(posl)

    return None


def accumulateDiscoveredEnumsToPythonEnums(
    de: Optional[DiscoveredEnums], path: List[str], acc: Dict[str, enum.Enum]
) -> None:
    def withEnumValue(e: str) -> Tuple[str, Any]:
        if isinstance(e, str):
            return (e.replace("-", "_"), e)
        elif isinstance(e, (int, float, complex)):
            return ("num" + str(e), e)
        else:
            logger.info(
                f"Unknown type ({type(e)}) of enumeration constant {e}, not handling very well"
            )
            return (str(e), e)

    if de is None:
        return

    if de.enums is not None:
        ppath, _ = withEnumValue("_".join(path))
        epath = ".".join(path)
        vals = (withEnumValue(x) for x in de.enums if x is not None)
        # pyright does not currently understand this form
        acc[ppath] = enum.Enum(epath, vals)  # type: ignore

    if de.children is not None:
        for k in de.children:
            accumulateDiscoveredEnumsToPythonEnums(de.children[k], [k] + path, acc)


def discoveredEnumsToPythonEnums(de: Optional[DiscoveredEnums]) -> Dict[str, enum.Enum]:
    acc: Dict[str, enum.Enum] = {}
    accumulateDiscoveredEnumsToPythonEnums(de, [], acc)
    return acc


def schemaToPythonEnums(schema: JsonSchema) -> Dict[str, enum.Enum]:
    de = schemaToDiscoveredEnums(schema)
    enums = discoveredEnumsToPythonEnums(de)
    return enums


def addDictAsFields(obj: Any, d: Dict[str, Any], force=False) -> None:
    if d is None:
        return

    for k, v in d.items():
        if k == "":
            logger.warning(
                f"There was a top level enumeration specified, so it is not being added to {obj._name}"
            )
        elif hasattr(obj, k) and not force:
            logger.error(
                f"The object {obj._name} already has the field {k}.  This conflicts with our attempt at adding that key as an enumeration field"
            )
        else:
            setattr(obj, k, v)


def addSchemaEnumsAsFields(obj: Any, schema: JsonSchema, force=False) -> None:
    enums = schemaToPythonEnums(schema)
    addDictAsFields(obj, enums, force)

# Import necessary modules
import os
import xml.etree.ElementTree as ET
from pathlib import Path
from pprint import pprint
from typing import Dict, Optional

# Import custom module
from .abstract_commands import AbstractCommands

# Set up logger
_LOGGER = logging.getLogger(__name__)

class IRCommands:
    # Class variable to store IR commands
    ir_commands: Dict[str, bytes] = {}

    def __init__(self, filename: str, transpiler: AbstractCommands):
        self.transpiler = transpiler

        # Construct path to mapping file
        mapping_file = Path(os.getcwd(), f"usr/share/{filename}.xml")

        if mapping_file.exists():
            # Parse XML mapping file
            mapping_root = ET.parse(mapping_file).getroot()

            for elem in mapping_root.findall("remote/code"):
                name = elem.attrib["name"]
                ccf = elem.find("ccf")

                if ccf is not None and ccf.text is not None:
                    # Process hex data: swap byte order (little-endian conversion)
                    hex_snapshot = " ".join(
                        map(lambda x: x[2:4] + x[0:2], ccf.text.split(" "))
                    )
                    # Store as bytes
                    self.ir_commands[name] = bytes.fromhex(hex_snapshot)
                else:
                    _LOGGER.error("Unable to load ccf's from %s", mapping_file)
        else:
            raise FileExistsError(
                f"Configuration file not found, looking at {mapping_file}"
            )

    def get_state(self) -> Dict[str, str]:
        return self.transpiler.get_state()

    def resolve(self, name: str) -> Optional[bytes]:
        pprint(name)
        if name in self.ir_commands:
            return self.ir_commands[name]
        else:
            _LOGGER.error("Unknown signal: %s", name)
            return None

    def get(self, updates: dict) -> str:
        return self.transpiler.get_command_from_state(updates)

# Import necessary modules and types
from dataclasses import dataclass, field
import sys
from typing import (
    Any,
    Callable,
    Optional,
    Tuple,
    Union,
    Dict,
    ClassVar,
    Generic,
    TypeVar,
    Type,
    List,
)
from .composition import Compose
from .interface import Interface, implements, isimplementation

__all__ = ("match", "_")


def match(target: Any, *branches: MatchBranch) -> Any:
    """Match a target to patterns and evaluate expressions based on the first matching pattern.

    :param target: the target to perform branch checks on
    :param branches: the branches to check
    """
    # Validate all branches implement the required interface
    if not all(isimplementation(branch, _IMatchBranch) for branch in branches):
        raise TypeError("Custom branches must implement `_IMatchBranch` interface.")

    # Iterate through branches and find the first match
    for i, branch in enumerate(branches):
        check_result = branch.check(target)
        if check_result is not None:
            return branch.apply(check_result)

    # Return None if no branch matches
    return None


@dataclass
class _MatchBranchData:
    """MatchBranch data holder."""
    check_val: Any = field(init=False, default=None)
    func: Callable = field(init=False, default=lambda: None)


class _IMatchBranch(Interface):
    """MatchBranch interface."""
    def check(self, target: Any) -> Optional[Tuple]:
        ...


@implements(_IMatchBranch)
class MatchBranch(
    Compose(_MatchBranchData, "check_val", name="_mb")  # type: ignore
):
    """Match branch with no checks."""

    def __init_subclass__(cls, symbol: Optional[str] = None) -> None:
        if symbol is not None:
            setattr(MatchBranch, symbol, cls)

    def __init__(self, check_val: Any = None):
        super().__init__()
        self.check_val = check_val

    def __rshift__(self, result: Any) -> MatchBranch:
        setattr(self._mb, "func", result if callable(result) else (lambda: result))
        return self

    def check(self, target: Any) -> Optional[Tuple]:
        return tuple()

    def apply(self, args: Tuple) -> Any:
        return self._mb.func(*args)


_ = MatchBranch


@implements(_IMatchBranch)
class Literal(MatchBranch, symbol="l"):
    """Matching branch with a literal compare value."""
    check_val: Any

    def check(self, target: Any) -> Optional[Tuple]:
        if self.check_val == target:
            return tuple()
        return None


@implements(_IMatchBranch)
class Conditional(MatchBranch, symbol="c"):
    """Matching branch with a conditional."""
    check_val: Callable

    def check(self, target: Any) -> Optional[Tuple]:
        if self.check_val(target):
            return (target,)
        return None


@implements(_IMatchBranch)
class Struct(MatchBranch, symbol="s"):
    """Matching branch with 'struct' decomposition."""
    _type: type
    check_val: Tuple[Tuple, Dict]

    def __init__(self, *args, **kwargs):
        super().__init__()
        self.check_val = (args, kwargs)

    def __class_getitem__(cls, type_: type) -> Type[Struct]:
        return type(f"{type_.__name__}MatchBrach", (Struct,), {"_type": type_})

    def check(self, target: Any) -> Optional[Tuple]:
        if isinstance(target, self._type):
            args, kwargs = self.check_val
            try:
                if all(
                    getattr(target, attr) == val
                    if not callable(val)
                    else val(getattr(target, attr))
                    for attr, val in kwargs.items()
                ):
                    return tuple(getattr(target, attr) for attr in args)
            except AttributeError:
                ...
        return None

