import enum
from .device import _WiserDevice
from .rest_controller import _WiserRestController
from .schedule import _WiserSchedule

# Import constants for smart plug operations
from .const import (
    WISERSMARTPLUG,
    WISERDEVICE,
    TEXT_UNKNOWN,
    TEXT_AUTO,
    TEXT_MANUAL,
    TEXT_OFF,
    TEXT_ON,
    TEXT_NO_CHANGE
)


# Enum definitions for Smart Plug modes and away actions
class WiserSmartPlugModeEnum(enum.Enum):
    auto = TEXT_AUTO
    manual = TEXT_MANUAL


class WiserAwayActionEnum(enum.Enum):
    off = TEXT_OFF
    nochange = TEXT_NO_CHANGE


# Import logging module (assumed to be defined elsewhere)
import inspect


class _WiserSmartPlug(_WiserDevice):
    """Class representing a Wiser Smart Plug device"""

    def __init__(self, wiser_rest_controller: _WiserRestController, data: dict, device_type_data: dict, schedule: _WiserSchedule):
        # Initialize parent class
        super().__init__(data)

        # Store references to controller, device type data, and schedule
        self._wiser_rest_controller = wiser_rest_controller
        self._device_type_data = device_type_data
        self._schedule = schedule

        # Initialize device properties from provided data
        self._away_action = device_type_data.get("AwayAction", TEXT_UNKNOWN)
        self._mode = device_type_data.get("Mode", TEXT_UNKNOWN)
        self._name = device_type_data.get("Name", TEXT_UNKNOWN)
        self._device_lock_enabled = data.get("DeviceLockEnabled", False)
        self._output_state = device_type_data.get("OutputState", TEXT_OFF)

    def _send_command(self, cmd: dict, device_level: bool = False) -> bool:
        """
        Send control command to the smart plug

        param cmd: json command structure
        return: boolean - True if successful, False otherwise
        """
        # Determine endpoint based on command scope
        if device_level:
            result = self._wiser_rest_controller._send_command(WISERDEVICE.format(self.id), cmd)
        else:
            result = self._wiser_rest_controller._send_command(WISERSMARTPLUG.format(self.id), cmd)

        # Log success if command was sent successfully
        if result:
            _LOGGER.debug(
                "Wiser smart plug - {} command successful".format(
                    inspect.stack()[1].function
                )
            )
        return result

    def _validate_mode(self, mode: str) -> bool:
        """Check if the given mode is valid"""
        for available_mode in self.available_modes:
            if mode.casefold() == available_mode.casefold():
                return True
        return False

    def _validate_away_action(self, action: str) -> bool:
        """Check if the given away action is valid"""
        for available_action in self.available_away_mode_actions:
            if action.casefold() == available_action.casefold():
                return True
        return False

    @property
    def available_modes(self):
        """Return list of available modes"""
        return [mode.value for mode in WiserSmartPlugModeEnum]

    @property
    def available_away_mode_actions(self):
        """Return list of available away mode actions"""
        return [action.value for action in WiserAwayActionEnum]

    @property
    def away_mode_action(self) -> str:
        """Get or set the away action of the smart plug (off or no change)"""
        return WiserAwayActionEnum[self._away_action.lower()].value

    @away_mode_action.setter
    def away_mode_action(self, action: str):
        if self._validate_away_action(action):
            if self._send_command({"AwayAction": WiserAwayActionEnum[action.lower()].value}):
                self._away_action = WiserAwayActionEnum[action.lower()].value
        else:
            raise ValueError(f"{action} is not a valid Smart Plug away mode action.  Valid modes are {self.available_away_mode_actions}")

    @property
    def control_source(self) -> str:
        """Get the current control source of the smart plug"""
        return self._device_type_data.get("ControlSource", TEXT_UNKNOWN)

    @property
    def delivered_power(self) -> int:
        """Get the amount of energy delivered through the plug over time"""
        return self._device_type_data.get("CurrentSummationDelivered", -1)

    @property
    def device_lock_enabled(self) -> bool:
        """Get or set smart plug device lock"""
        return self._device_lock_enabled

    @device_lock_enabled.setter
    def device_lock_enabled(self, enable: bool):
        if self._send_command({"DeviceLockEnabled": enable}, True):
            self._device_lock_enabled = enable

    @property
    def instantaneous_power(self) -> int:
        """Get the amount of current through the plug at this moment"""
        return self._device_type_data.get("InstantaneousDemand", -1)

    @property
    def manual_state(self) -> str:
        """Get the current manual mode setting of the smart plug"""
        return self._device_type_data.get("ManualState", TEXT_UNKNOWN)

    @property
    def mode(self) -> str:
        """Get or set the current mode of the smart plug (Manual or Auto)"""
        return WiserSmartPlugModeEnum[self._mode.lower()].value

    @mode.setter
    def mode(self, mode: str):
        if self._validate_mode(mode):
            if self._send_command({"Mode": WiserSmartPlugModeEnum[mode.lower()].value}):
                self._mode = WiserSmartPlugModeEnum[mode.lower()].value
        else:
            raise ValueError(f"{mode} is not a valid Smart Plug mode.  Valid modes are {self.available_modes}")

    @property
    def name(self) -> str:
        """Get or set the name of the smart plug"""
        return self._name

    @name.setter
    def name(self, name: str):
        if self._send_command({"Name": name}):
            self._name = name

    @property
    def is_on(self) -> bool:
        """Get if the smart plug is on"""
        return True if self._output_state == TEXT_ON else False

    @property
    def room_id(self) -> int:
        """Get smart plug room id"""
        return self._device_type_data.get("RoomId", 0)

    @property
    def schedule(self):
        """Get the schedule of the smart plug"""
        return self._schedule

    @property
    def scheduled_state(self) -> str:
        """Get the current scheduled state of the smart plug"""
        return self._device_type_data.get("ScheduledState", TEXT_UNKNOWN)

    def turn_on(self) -> bool:
        """
        Turn on the smart plug
        return: boolean indicating success
        """
        result = self._send_command({"RequestOutput": TEXT_ON})
        if result:
            self._output_state = TEXT_ON
        return result

    def turn_off(self) -> bool:
        """
        Turn off the smart plug
        return: boolean indicating success
        """
        result = self._send_command({"RequestOutput": TEXT_OFF})
        if result:
            self._output_state = TEXT_OFF
        return result


class _WiserSmartPlugCollection(object):
    """Class holding all wiser smart plugs"""

    def __init__(self):
        self._smartplugs = []

    @property
    def all(self) -> list:
        return list(self._smartplugs)

    @property
    def available_modes(self):
        return [mode.value for mode in WiserSmartPlugModeEnum]

    @property
    def count(self) -> int:
        return len(self.all)

    def get_by_id(self, id: int) -> _WiserSmartPlug:
        """
        Gets a SmartPlug object from the SmartPlugs id

        param id: id of smart plug
        return: _WiserSmartPlug object or None if not found
        """
        try:
            return [smartplug for smartplug in self.all if smartplug.id == id][0]
        except IndexError:
            return None

# Type I clone - formatting changes only (whitespace, comments, line breaks)
from __future__ import annotations

import typing as t

T = t.TypeVar("T")


def optional(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
) -> t.Optional[T]:
    """Get a value safely from the given dict using the given key.
    If the value is not found or is None, return it anyway.
    :raises: ValueError
    """
    if parser is None:
        value = dict_.get(key)
    else:
        value = parser(dict_, key)

    # Check type if value is not None
    if value is not None and not isinstance(value, expect):
        raise ValueError(
            f"{dict_}: {repr(key)}: {repr(value)}: invalid type {type(value)}, expecting {expect}"
        )

    return t.cast(T, value)


def required(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
    default: t.Optional[T] = None,
    default_factory: t.Optional[t.Callable[[], T]] = None,
) -> T:
    """Get a value safely from the given dict using the given key.
    If the value is not found or is None, raise value error.
    :raises: ValueError
    """
    value: t.Optional[T] = optional(dict_, key, expect, parser=parser)

    if value is None:
        if default is not None:
            return default
        if default_factory is not None:
            return default_factory()
        raise ValueError(f"{dict_}: {repr(key)}: value is required")

    return value


def flatten_dict(d: t.Dict[t.Any, t.Any]) -> t.Dict[str, object]:
    """Flatten a nested dictionary.
    :param dist d: The nested dictionary to flatten.
    :rtype: dict
    :example:
    .. code-block:: python
        flatten_dict({"a": 1, "b": {"c": 2, "d": {"e": 3, "f": 4}}})
        # {
        #     "a": 1,
        #     "b:c": 2,
        #     "b:d:e": 3,
        #     "b:d:f": 4,
        # }
    """
    def items() -> t.Iterable[t.Tuple[str, object]]:
        for key, value in d.items():
            if not isinstance(key, str):
                raise ValueError(f"{key}: expected {str}, but got {type(key)}")
            if isinstance(value, dict):
                for subkey, subvalue in flatten_dict(value).items():
                    if not isinstance(subkey, str):
                        raise ValueError(
                            f"{subkey}: expected {str}, but got {type(subkey)}"
                        )
                    yield key + ":" + subkey, subvalue
            else:
                yield key, value

    return dict(items())


def unflatten_dict(d: t.Dict[object, object]) -> t.Dict[object, object]:
    """Convert a flattened dict back to nested dict.
    :param dict d: The flattened dict to convert.
    :rtype: dict
    :example:
    .. code-block:: python
        unflatten_dict({"a": 1, "b:c": 2, "b:d:e": 3, "b:d:f": 4})
        # {
        #   "a": 1,
        #   "b": {"c": 2, "d": {"e": 3, "f": 4}},
        # }
    """
    dict_: t.Dict[object, object] = {}

    for k, v in d.items():
        if not isinstance(k, str):
            raise ValueError(f"{k}: expected {str}, but got {type(k)}")

        if ":" in k:
            _dict: t.Union[object, t.Dict[object, object]] = dict_
            fields = k.split(":")
            count = len(fields)

            for i in range(count):
                field = fields[i]
                if not isinstance(_dict, dict):
                    continue
                if field not in _dict:
                    _dict[field] = v if i == (count - 1) else {}
                _dict = _dict[field]
        else:
            dict_[k] = v

    return dict_

# Import necessary modules
from enum import Enum
from inspect import signature
from typing import List, Set, Optional, Union, Pattern, Type, Callable

# Metaclass for registering section patterns
class _SectionPatternRegisterer(type):
    def __init__(cls, name, bases, attrs):
        cls._patterns = []
        for key, val in attrs.items():
            properties = getattr(val, '_prop', None)
            if properties is not None:
                cls._patterns.append({'func': val, 'name': properties['name']})

# Decorator for section pattern functions
def section_pattern(name: Optional[str] = None):
    if not (name is None or isinstance(name, str)):
        raise ValueError(f'name must be str but {type(name)} was given.')

    def _body(func: Callable[[str], Optional[Union[str, int]]]):
        nonlocal name
        n_params = len(signature(func).parameters)
        if n_params != 1:
            raise TypeError(
                '@section_pattern() must receive a function with 1 argument.')
        if name is None:
            name = func.__name__
        func._prop = {'name': name}
        return func

    return _body

# Decorator to register section patterns for BaseSectionNumber subclasses
def register_section_pattern(name: str, patterns: List[Pattern[str]], convert_fun: Callable[[str], int]):
    def _body(cls: Type[BaseSectionNumber]):
        nonlocal patterns, name, convert_fun
        if not issubclass(cls, BaseSectionNumber):
            raise TypeError(
                '@register_section_pattern may only be used on a class inheriting BaseSectionNumber')

        for pattern in patterns:
            def _extract_section_number_factory(pattern):
                # use factory pattern to embed pattern into _extract_section_number
                def _extract_section_number(text: str):
                    m = pattern.match(text)
                    return None if m is None else convert_fun(m.group('num'))
                return _extract_section_number

            extract_section_number = _extract_section_number_factory(pattern)
            extract_section_number._prop = {'name': name}
            cls._patterns.append(
                {'func': extract_section_number,
                 'name': name,
                 'pattern': pattern})

        return cls

    return _body

# Base class for section numbers
class BaseSectionNumber(object, metaclass=_SectionPatternRegisterer):
    def __init__(self, section_number_type: str, number: Union[int, str]):
        if not isinstance(section_number_type, str):
            raise TypeError(f'section_number_type must be str but {type(section_number_type)} was given.')
        if not isinstance(number, (int, str)):
            raise TypeError(f'number must be int or str but {type(number)} was given.')

        self.section_number_type: str = section_number_type
        self.number: Optional[int] = number

    def __eq__(self, other):
        return (type(self) == type(other) and
                self.number == other.number and
                self.section_number_type == other.section_number_type)

    @classmethod
    def extract_section_number(cls, text: str) -> List['BaseSectionNumber']:
        text = text.strip()
        candidates = []
        for pattern in cls._patterns:
            section_number = pattern['func'](text)
            if section_number is not None:
                candidates.append(cls(pattern['name'], section_number))
        return candidates

    def is_next_of(self, other: 'BaseSectionNumber') -> bool:
        return other.next() == self

    def next(self) -> 'BaseSectionNumber':
        if isinstance(self.number, str):
            # bullet points
            return self
        else:
            # Numbered list
            return type(self)(self.section_number_type, self.number + 1)

    @staticmethod
    def is_any_next_of(following_section_numbers: Set['BaseSectionNumber'],
                       section_numbers: Set['BaseSectionNumber']) -> bool:
        for s1 in section_numbers:
            for s2 in following_section_numbers:
                if s2.is_next_of(s1):
                    return True
        return False

    def __repr__(self):
        return f'{str(type(self))[:-1]} type={self.section_number_type}, number={self.number}>'

# Enum for numbered list states
class NumberedListState(Enum):
    NO_NUM = 0
    CONSECUTIVE = 1
    DOWN = 2
    UP = 3
    UNKNOWN = 4

# Multi-level numbered list manager
class MultiLevelNumberedList(object):
    def __init__(self):
        self._numbered_list: List[BaseSectionNumber] = []

    def try_append(self, candidates: Set[BaseSectionNumber]) -> NumberedListState:
        if len(candidates) == 0:
            return NumberedListState.NO_NUM

        for i, section_number_pre in enumerate(self._numbered_list[::-1]):
            for section_number in candidates:
                if section_number.is_next_of(section_number_pre):
                    self._numbered_list = self._numbered_list[:-i-1]
                    self._numbered_list.append(section_number)
                    if i == 0:
                        return NumberedListState.CONSECUTIVE
                    else:
                        return NumberedListState.UP

        # No valid continuation found... check if it is a new level
        for section_number in candidates:
            if isinstance(section_number.number, str) or section_number.number <= 1:
                self._numbered_list.append(section_number)
                return NumberedListState.DOWN

        return NumberedListState.UNKNOWN

