from enum import Enum
from typing import Dict, List, TypeVar

def locals_to_params(args: Dict) -> Dict:
    # Create a copy dictionary to store parameters
    copy = dict()

    # Iterate through all keys in the input dictionary
    for key in args:
        # Skip 'self' parameter
        if key == "self":
            continue

        # Only process non-None values
        if args[key] is not None:
            value = args[key]

            # Handle Enum types by storing their name
            if isinstance(value, Enum):
                copy[key] = value.name
            else:
                copy[key] = value

    return copy


""" Finds first dict in list of dicts containing field id with value equal to id"""
T = TypeVar("T")

def find_by_id(_id: str, item_list: List[Dict[str, T]], log_error=True) -> Dict[str, T]:
    from ..utils import logger

    # Define filter function to match item id
    def filter_fn(item):
        return item["id"] == _id

    try:
        # Filter and return first matching item
        filtered = filter(filter_fn, item_list)
        return next(filtered)
    except StopIteration:
        # Log error if no matching item found
        if log_error:
            logger.error(
                f"No item with correct id {_id}. Existing ids: {[item['id'] for item in item_list]}"
            )
        raise

