from typing import Any, Callable, Dict

def split_bool(param: Any) -> Dict[str, Any]:
    """
    Split query parameter into filter-bool parameters
    """
    # Handle empty or None input
    if not param:
        return {}

    # Handle boolean type directly
    if type(param) == bool:
        return dict(value=param)

    # Convert string to boolean based on common truthy values
    value = param.lower() in ["true", "yes", "on", "1"]
    return dict(value=value)


def split_comp(param: Any, convert: Callable[[str], Any] = str) -> Dict[str, Any]:
    """
    Split query parameter into filter-comp parameters
    """
    # Handle empty or None input
    if not param:
        return {}

    # If not a string, return as-is
    if type(param) != str:
        return dict(value=param)

    # If no colon separator, convert and return
    if ":" not in param:
        return dict(value=convert(param))

    # param = (not:)(oper:)value(:upper)
    parts = param.split(":")
    count = len(parts)

    # Check for negation prefix
    negate = parts[0] == "not"

    # Handle 4+ parts: not:oper:value:upper or oper:value:upper
    if count >= 4:
        return dict(
            negate=negate,
            oper=parts[1],
            value=convert(parts[2]),
            upper=convert(parts[3]),
        )
    elif count == 3:
        # Handle 3 parts with negation: not:oper:value
        if negate:
            return dict(negate=negate, oper=parts[1], value=convert(parts[2]))
        # Handle 3 parts without negation: oper:value:upper
        return dict(oper=parts[0], value=convert(parts[1]), upper=convert(parts[2]))

    # else count == 2 (and can't be 1)
    elif negate:
        return dict(negate=negate, value=convert(parts[1]))

    return dict(oper=parts[0], value=convert(parts[1]))


def split_in(param: Any, convert: Callable[[str], Any] = str) -> Dict[str, Any]:
    """
    Split query parameter into filter-in parameters
    """
    # Handle empty or None input
    if not param:
        return {}

    # If not a string, wrap in list
    if type(param) != str:
        return dict(values=[param])

    # Special case for null check
    if param == "is:null":
        return dict(is_null=True)

    # If no colon separator, split by comma
    if ":" not in param:
        return dict(values=list(map(convert, param.split(","))))

    # Handle colon-separated format: not:value1,value2
    parts = param.split(":")
    return dict(
        negate=(parts[0] == "not"), 
        values=list(map(convert, parts[1].split(",")))
    )


def split_str(param: Any) -> Dict[str, Any]:
    """
    Split query parameter into filter-str parameters
    """
    # Handle empty, None, or non-string input
    if not param or type(param) != str:
        return {}

    # If no colon separator, return simple value
    if ":" not in param:
        return dict(value=param)

    # param = (not:)(oper:)value
    parts = param.split(":")
    count = len(parts)

    # Check for negation prefix
    negate = parts[0] == "not"

    # Handle 3+ parts: not:oper:value
    if count >= 3:
        return dict(negate=negate, oper=parts[1], value=parts[2])

    # else count == 2 (and can't be 1)
    elif negate:
        return dict(negate=negate, value=parts[1])

    return dict(oper=parts[0], value=parts[1])

