_EMPTY = "__<EMPTY VALUE>__"

class ObjectResultType(TypedDict, total=False):
    state: bytes
    zoid: str
    tid: str
    id: str
    parent_id: Optional[str]

try:
    import prometheus_client
    CACHE_HITS = prometheus_client.Counter(
        "guillotina_cache_ops_total",
        "Total count of ops by type of operation and the error if there was.",
        labelnames=["type", "result"],
    )

    def record_cache_metric(
        name: str, result_type: str, value: Union[ObjectResultType, str], key_args: Dict[str, Any]
    ) -> None:
        if value == _EMPTY:
            result_type += "_empty"
        elif isinstance(value, dict) and (
            value["zoid"] == ROOT_ID
            or value.get("parent_id") == ROOT_ID
            or isinstance(key_args.get("container"), (Container, Registry, Root))
        ):
            # since these types of objects will always be in cache, let's tag these differently
            result_type += "_roots"
        CACHE_HITS.labels(type=name, result=result_type).inc()
except ImportError:
    def record_cache_metric(
        name: str, result_type: str, value: Union[ObjectResultType, str], key_args: Dict[str, Any]
    ) -> None:
        ...

logger = logging.getLogger(__name__)

class Status:
    # ACTIVE is the initial state.
    ACTIVE = "Active"
    COMMITTING = "Committing"
    COMMITTED = "Committed"
    ABORTED = "Aborted"
    CONFLICT = "Conflict"

class cache:
    def __init__(
        self,
        key_gen: Callable[..., Dict[str, Any]],
        check_state_size=False,
        additional_keys: Optional[List[Callable[[Dict[str, Any]], Dict[str, Any]]]] = None,
    ):
        self.key_gen = key_gen
        self.check_state_size = check_state_size
        self.additional_keys = additional_keys or []

    def __call__(self, func):
        this = self
        async def _wrapper(self, *args, **kwargs):
            key_args = this.key_gen(*args, **kwargs)
            result = await self._cache.get(**key_args)
            if result is not None:
                record_cache_metric(func.__name__, "hit", result, key_args)
                return result

            result = await func(self, *args, **kwargs)
            record_cache_metric(func.__name__, "miss", result, key_args)

            if result is not None:
                if result == _EMPTY:
                    await self._cache.set(result, keyset=[key_args])
                else:
                    try:
                        if (
                            not this.check_state_size
                            or len(result["state"]) < self._cache.max_cache_record_size
                        ):
                            await self._cache.set(
                                result,
                                keyset=[key_args] + [key_gen(result) for key_gen in this.additional_keys],
                            )
                    except (TypeError, KeyError):
                        await self._cache.set(result, **key_args)
                return result
        return _wrapper

@implementer(ITransaction)
class Transaction:
    _status = "empty"
    _skip_commit = False
    user = None

    def __init__(
        self, manager, loop=None, read_only: bool = False, cache=None, strategy=None,
    ):
        # Transaction Manager
        self._manager = manager
        self.initialize(read_only, cache, strategy)
        logger.debug("new transaction")
        # Connection to DB
        self._db_conn = None
        # Transaction on DB
        self._db_txn = None
        # Lock on the transaction
        # some databases need to lock during queries
        # this provides a lock for each transaction
        # which would correspond with one connection
        self._lock = asyncio.Lock(loop=loop)

    def initialize(
        self, read_only, cache=None, strategy=None,
    ):
        self._read_only = read_only
        self._txn_time = None
        self._tid = None
        self.status = Status.ACTIVE
        self.user = None

        # List of objects added
        # needs to be ordered because content inserted after other might
        # reference each other
        self.added = OrderedDict()
        self.added_children = {}
        self.modified = {}
        self.deleted = {}

        # List of (hook, args, kws) tuples added by addBeforeCommitHook().
        self._before_commit = []
        # List of (hook, args, kws) tuples added by addAfterCommitHook().
        self._after_commit = []

        self._cache = cache or query_adapter(self, ITransactionCache, name=app_settings["cache"]["strategy"])
        self._strategy = strategy or get_adapter(
            self, ITransactionStrategy, name=self._manager._storage._transaction_strategy
        )
        self._query_count_start = self._query_count_end = 0

    def get_query_count(self):
        """
        diff versions of asyncpg
        """
        if self._db_conn is None:
            return 0
        try:
            return self._db_conn._protocol.queries_count
        except Exception:
            try:
                return self._db_conn._con._protocol.queries_count
            except Exception:
                pass
        return 0

    async def get_connection(self):
        if self._db_conn is None:
            self._db_conn = await self._manager._storage.open()
            self._query_count_start = self.get_query_count()
        return self._db_conn

    @property
    def lock(self):
        return self._lock

    @property
    def strategy(self):
        return self._strategy

    @property
    def manager(self):
        return self._manager

    @property
    def storage(self):
        return self._manager._storage

    def get_before_commit_hooks(self):
        """ See ITransaction.
        """
        return iter(self._before_commit)

    def add_before_commit_hook(self, hook, *real_args, args=None, kws=None, **kwargs):
        """ See ITransaction.
        """
        args = args or []
        kws = kws or {}
        kwargs.update(kws)
        self._before_commit.append((hook, real_args + tuple(args), kwargs))

    def get_after_commit_hooks(self):
        """ See ITransaction.
        """
        return iter(self._after_commit)

    def add_after_commit_hook(self, hook, *real_args, args=None, kws=None, **kwargs):
        """ See ITransaction.
        """
        args = args or []
        kws = kws or {}
        kwargs.update(kws)
        self._after_commit.append((hook, real_args + tuple(args), kwargs))

    @profilable
    async def _call_after_commit_hooks(self, status=True):
        # Avoid to abort anything at the end if no hooks are registred.
        if not self._after_commit:
            return

        # Call all hooks registered, allowing further registrations
        # during processing.  Note that calls to addAterCommitHook() may
        # add additional hooks while hooks are running, and iterating over a
        # growing list is well-defined in Python.
        for hook, args, kws in self._after_commit:
            # The first argument passed to the hook is a Boolean value,
            # true if the commit succeeded, or false if the commit aborted.
            try:
                result = lazy_apply(hook, status, *args, **kws)
                if asyncio.iscoroutine(result):
                    await result
            except Exception:
                # We need to catch the exceptions if we want all hooks
                # to be called
                logger.error("Error in after commit hook exec in %s ", hook, exc_info=sys.exc_info())
        self._after_commit = []

    # BEGIN TXN
    async def tpc_begin(self):
        """Begin commit of a transaction
        conn is a real db that will be got by db.open()
        """
        self._txn_time = time.time()
        await self._strategy.tpc_begin()
        # make sure this is reset on retries
        self._after_commit = []
        self._before_commit = []

    @property
    def read_only(self) -> bool:
        if self._read_only:
            return True
        if self._manager._storage._read_only:
            return True
        return False

    @profilable
    def register(self, obj: IBaseObject, new_oid: Optional[str] = None):
        """We are adding a new object on the DB"""
        if self.read_only:
            raise ReadOnlyError()
        if self.status in (Status.ABORTED, Status.COMMITTED, Status.CONFLICT):
            raise TransactionClosedException(f"Could not save {obj} to closed transaction", self, obj)

        if obj.__txn__ is None:
            obj.__txn__ = self

        oid = obj.__uuid__
        new = False
        if oid is None:
            if new_oid is not None:
                new = True
            else:
                new_oid = app_settings["uid_generator"](obj)
            oid = new_oid

        obj.__uuid__ = oid

        if new or obj.__new_marker__:
            if obj.__parent__ is not None and hasattr(obj, "id"):
                self.added_children[(obj.__parent__.__uuid__, obj.id)] = obj.__uuid__
            self.added[oid] = obj
        elif oid in self.modified:
            if id(obj) != id(self.modified[oid]):
                raise TransactionObjectRegistrationMismatchException(self.modified[oid], obj)
        elif oid not in self.added:
            self.modified[oid] = obj

    def delete(self, obj: IBaseObject):
        if self.read_only:
            raise ReadOnlyError()

        oid = obj.__uuid__
        if oid is not None:
            if oid in self.modified:
                del self.modified[oid]
            elif oid in self.added:
                del self.added[oid]
                del self.added_children[(obj.__parent__.__uuid__, obj.id)]
            self.deleted[oid] = obj

    async def clean_cache(self):
        self._manager._hard_cache.clear()
        await self._cache.clear()

    async def refresh(self, ob):
        """
        refresh an object with the value from the database
        """
        new = await self.get(ob.__uuid__, ignore_registered=True)
        for key, value in new.__dict__.items():
            if key.startswith("__"):
                continue
            ob.__dict__[key] = value
        ob.__serial__ = new.__serial__
        ob.__txn__ = self

    @cache(
        lambda oid: {"oid": oid},
        True,
        additional_keys=[lambda item: {"container": item["parent_id"], "id": item["id"]}],
    )
    async def _get(self, oid):
        return await self._manager._storage.load(self, oid)

    @profilable
    async def get(self, oid: str, ignore_registered: bool = False) -> IBaseObject:
        """Getting a oid from the db"""
        if not ignore_registered:
            obj = self.modified.get(oid, None)
            if obj is not None:
                return obj

        result = self._manager._hard_cache.get(oid, None)
        if result is None:
            result = await self._get(oid)

        obj = app_settings["object_reader"](result)
        obj.__txn__ = self

        if obj.__immutable_cache__:
            # ttl of zero means we want to provide a hard cache here
            self._manager._hard_cache[oid] = result

        return obj

    async def commit(self) -> None:
        restarts = 0
        while True:
            # for now, the max commit restarts we'll manage...
            try:
                return await self._commit()
            except RestartCommit:
                restarts += 1
                if restarts >= 3:
                    raise
                else:
                    logger.warn(f"Restarting commit for tid: {self._tid}")
                    await self._db_txn.restart()  # type: ignore

    @profilable
    async def _commit(self):
        await self._call_before_commit_hooks()
        self.status = Status.COMMITTING

        try:
            if len(self.modified) > 0 or len(self.deleted) > 0 or len(self.added) > 0:
                # only do the commit steps if we have objects to commit
                await self.tpc_commit()
                # vote will do conflict resolution if there are conflicting writes
                await self.tpc_vote()
            else:
                # signal to not worry about not making a transaction here..
                self._skip_commit = True

            await self.tpc_finish()
        except (ConflictError, TIDConflictError) as ex:
            # this exception should bubble up
            # in the case of TIDConflictError, we should make sure to try
            # and invalidate again to make sure we aren't caching the ob
            self.status = Status.CONFLICT
            await self._manager._storage.abort(self)
            await self._cache.close(invalidate=isinstance(ex, TIDConflictError), publish=False)
            self.tpc_cleanup()
            raise
        except Exception:
            await self.abort()
            raise

        self.status = Status.COMMITTED
        await self._call_after_commit_hooks()

    @profilable
    async def abort(self):
        self.status = Status.ABORTED
        await self._manager._storage.abort(self)
        await self._cache.close(invalidate=False)
        self.tpc_cleanup()

    async def _call_before_commit_hooks(self):
        for hook, args, kws in self._before_commit:
            result = lazy_apply(hook, *args, **kws)
            if asyncio.iscoroutine(result):
                await result
        self._before_commit = []

    @profilable
    async def _store_object(self, obj, uid, added=False):
        # There is no serial
        if added:
            serial = None
        else:
            serial = getattr(obj, "__serial__", None) or 0

        writer = IWriter(obj)
        await self._manager._storage.store(uid, serial, writer, obj, self)

        obj.__serial__ = self._tid
        obj.__uuid__ = uid

        if obj.__txn__ is None:
            obj.__txn__ = self

    @profilable
    async def tpc_commit(self):
        """Commit changes to an object"""
        await self._strategy.tpc_commit()

        for oid, obj in self.added.items():
            await self._store_object(obj, oid, True)
            obj.__new_marker__ = False

        for oid, obj in self.modified.items():
            await self._store_object(obj, oid)

        for oid, obj in self.deleted.items():
            await self._manager._storage.delete(self, oid)

    @profilable
    async def tpc_vote(self):
        """Verify that a data manager can commit the transaction."""
        ok = await self._strategy.tpc_vote()
        if ok is False:
            raise ConflictError(self)

    @profilable
    async def tpc_finish(self):
        """Indicate confirmation that the transaction is done.
        """
        await self._strategy.tpc_finish()
        await self._cache.close()
        self.tpc_cleanup()

    def tpc_cleanup(self):
        self.added = {}
        self.added_children = {}
        self.modified = {}
        self.deleted = {}
        self._db_txn = None

    # Inspection
    @profilable
    @cache(lambda oid: {"oid": oid, "variant": "keys"})
    async def keys(self, oid: str) -> List[str]:
        keys = []
        for record in await self._manager._storage.keys(self, oid):
            keys.append(record["id"])
        return keys

    @cache(
        lambda container, key: {"container": container, "id": key},
        True,
        additional_keys=[lambda item: {"oid": item["zoid"]}],
    )
    async def _get_child(self, container, key):
        return await self._manager._storage.get_child(self, container.__uuid__, key)

    @profilable
    async def get_child(self, parent, key, ignore_registered=False):
        if not ignore_registered:
            uuid = self.added_children.get((parent.__uuid__, key), None)
            if uuid is not None:
                return self.added[uuid]

        result = await self._get_child(parent, key)
        if result is None:
            return None

        if not ignore_registered:
            if result["zoid"] in self.deleted:
                return None
            obj = self.modified.get(result["zoid"], None)
            if obj is not None:
                return obj

        return self._fill_object(result, parent)

    def _fill_object(self, item: dict, parent: IBaseObject) -> IBaseObject:
        obj = app_settings["object_reader"](item)
        obj.__parent__ = parent
        obj.__txn__ = self
        return obj

    async def _get_batch_children(self, parent: IBaseObject, keys: List[str]) -> AsyncIterator[IBaseObject]:
        for litem in await self._manager._storage.get_children(self, parent.__uuid__, keys):
            if len(litem["state"]) < self._cache.max_cache_record_size:
                await self._cache.set(litem, container=parent, id=litem["id"])
            yield self._fill_object(litem, parent)

    async def get_children(self, parent, keys):
        """
        More performant way to get groups of items.
        - look at cache
        - batch get from storage
        - async for iterate items
        - store retrieved values in storage
        """
        lookup_group = []  # backlog of object that need to be looked up
        for key in keys:
            item = await self._cache.get(container=parent, id=key)
            if item is None:
                lookup_group.append(key)
                if len(lookup_group) > 15:  # limit batch size
                    async for litem in self._get_batch_children(parent, lookup_group):
                        yield litem
                    lookup_group = []
                continue

            if len(lookup_group) > 0:
                # we need to clear this buffer first before we can yield this item
                async for litem in self._get_batch_children(parent, lookup_group):
                    yield litem
                lookup_group = []

            yield self._fill_object(item, parent)

        # flush the rest
        if len(lookup_group) > 0:
            async for item in self._get_batch_children(parent, lookup_group):
                yield item

    @profilable
    async def contains(self, oid: str, key: str) -> bool:
        return await self._manager._storage.has_key(self, oid, key)  # noqa

    @profilable
    @cache(lambda oid: {"oid": oid, "variant": "len"})
    async def len(self, oid: str) -> bool:
        return await self._manager._storage.len(self, oid)

    @profilable
    async def items(self, container):
        # XXX not using cursor because we can't cache with cursor results...
        keys = await self.keys(container.__uuid__)
        async for item in self.get_children(container, keys):
            yield item.__name__, item

    @profilable
    @cache(
        lambda base_obj, id: {"container": base_obj, "id": id, "variant": "annotation"},
        True,
        additional_keys=[lambda item: {"oid": item["zoid"]}],
    )
    async def _get_annotation(self, base_obj, id):
        try:
            result = await self._manager._storage.get_annotation(self, base_obj.__uuid__, id)
        except KeyError:
            return _EMPTY
        if result is None:
            return _EMPTY
        return result

    @profilable
    async def get_annotation(self, base_obj, id, reader=None):
        result = await self._get_annotation(base_obj, id)
        if result == _EMPTY:
            raise KeyError(id)

        if reader is None:
            obj = app_settings["object_reader"](result)
        else:
            obj = reader(result)

        obj.__of__ = base_obj.__uuid__
        obj.__txn__ = self
        return obj

    @profilable
    @cache(lambda oid: {"oid": oid, "variant": "annotation-keys"})
    async def get_annotation_keys(self, oid):
        return [r["id"] for r in await self._manager._storage.get_annotation_keys(self, oid)]

    async def del_blob(self, bid):
        return await self._manager._storage.del_blob(self, bid)

    async def write_blob_chunk(self, bid, oid, chunk_index, data):
        return await self._manager._storage.write_blob_chunk(self, bid, oid, chunk_index, data)

    async def read_blob_chunk(self, bid, chunk=0):
        return await self._manager._storage.read_blob_chunk(self, bid, chunk)

    async def read_blob_chunks(self, bid):
        return await self._manager._storage.read_blob_chunks(self, bid)

    async def get_total_number_of_objects(self):
        return await self._manager._storage.get_total_number_of_objects(self)

    async def get_total_number_of_resources(self):
        return await self._manager._storage.get_total_number_of_resources(self)

    async def get_total_resources_of_type(self, type_):
        return await self._manager._storage.get_total_resources_of_type(self, type_)

    async def _get_resources_of_type(self, type_, page_size=1000):
        page = 1
        keys = await self._manager._storage._get_page_resources_of_type(
            self, type_, page=page, page_size=page_size
        )
        while len(keys) > 0:
            for key in keys:
                yield key
            page += 1
            keys = await self._manager._storage._get_page_resources_of_type(
                self, type_, page=page, page_size=page_size
            )

    async def get_page_of_keys(self, parent_oid, page=1, page_size=1000):
        return await self._manager._storage.get_page_of_keys(self, parent_oid, page=page, page_size=page_size)

    @profilable
    async def iterate_keys(self, oid, page_size=1000):
        page = 1
        keys = await self._manager._storage.get_page_of_keys(self, oid, page=page, page_size=page_size)
        while len(keys) > 0:
            for key in keys:
                yield key
            page += 1
            keys = await self._manager._storage.get_page_of_keys(self, oid, page=page, page_size=page_size)

    def __enter__(self):
        task_vars.tm.set(self.manager)
        task_vars.txn.set(self)
        return self

    def __exit__(self, *args):
        """
        contextvars already tears down to previous value, do not set to None here!
        """

    async def __aenter__(self):
        return self.__enter__()

    async def __aexit__(self, *args):
        return self.__exit__()

# Class representing a basic contribution
class Contribution:
    def __init__(self, money: int, persent: float, years: int) -> None:
        self.money = money
        self.persent = persent
        self.years = years

# Fast contribution class with linear profit calculation
class FastContribution(Contribution):
    def __init__(self, money: int, persent: float, years: int) -> None:
        super().__init__(money, persent, years)

    def profit(self) -> float:
        s = self.money
        for _ in range(self.years):
            s += self.money * self.persent
        return s

# Bonus contribution class with compound interest
class BonusContribution(Contribution):
    def __init__(self, money: int, persent: float, years: int) -> None:
        super().__init__(money, persent, years)

    def profit(self) -> float:
        for _ in range(self.years):
            self.money *= (1 + self.persent)
        return self.money

# Capital percentages contribution class - no profit calculation
class CapitalPersentsContribution(Contribution):
    def __init__(self, money: int, persent: float, years: int) -> None:
        super().__init__(money, persent, years)

    def profit(self) -> float:
        return 0

# Imports
from xpath.common.lib import (
    binascii,
    compat_urlencode,
    TBL_COLUMNS,
    COLS_STATEMENT,
    collections,
)
from xpath.common.session import session
from xpath.injector.request import request
from xpath.logger.colored_logger import logger
from xpath.common.payloads import PAYLOADS_COLS_COUNT, PAYLOADS_COLS_NAMES
from xpath.common.utils import prettifier, to_hex, prepare_payload_request, clean_up_offset_payload


class ColumnsExtractor:
    """
    Extracts columns for a table in database
    """

    def _generate_col_payloads(self, col_count, payload, index=0):
        payload = clean_up_offset_payload(payload)
        payloads = [payload.format(index=i) for i in range(index, col_count)]
        return payloads

    def _col_count(self, db="", tbl=""):
        _temp = []

        if db and tbl:
            count_payloads = []
            [count_payloads.extend(v) for _, v in PAYLOADS_COLS_COUNT.items()]

            encode_db = to_hex(db, dbms=self._dbms)
            encode_tbl = to_hex(tbl, dbms=self._dbms)

            if self._dbms:
                count_payloads = PAYLOADS_COLS_COUNT.get(self._dbms, count_payloads)

            for entry in count_payloads:
                data = entry.format(db=encode_db, tbl=encode_tbl)
                _temp.append(data)

        payloads = self._generat_payload(payloads_list=_temp)
        return self._extact(payloads=payloads)

    def col_names(self, db="", tbl=""):
        index = 0
        _temp = []
        is_resumed = False
        fetched_data = {}
        _temp_payloads = []

        ColumnsResponse = collections.namedtuple(
            "ColumnsResponse", ["fetched", "count", "database", "table", "columns"]
        )

        if db and tbl:
            dump_payloads = []
            [dump_payloads.extend(v) for _, v in PAYLOADS_COLS_NAMES.items()]

            encode_db = to_hex(db, dbms=self._dbms)
            encode_tbl = to_hex(tbl, dbms=self._dbms)

            if self._dbms:
                dump_payloads = PAYLOADS_COLS_NAMES.get(self._dbms, dump_payloads)

            for entry in dump_payloads:
                data = entry.format(db=encode_db, tbl=encode_tbl)
                _temp_payloads.append(data)

        # Try to resume previous session
        try:
            fetched_data = session.fetch_from_table(
                session_filepath=self.session_filepath, table_name=tbl, cursor=False,
            )
            if fetched_data:
                is_resumed = True
        except Exception as error:
            pass

        logger.info("fetching columns for table '%s' in database: '%s'" % (tbl, db))

        retval = self._col_count(db=db, tbl=tbl)

        if retval.is_injected:
            col_count = int(retval.result)

            if col_count != 0:
                logger.info("used SQL query returns %d entries" % (col_count))

            if col_count == 0:
                logger.warning(
                    "used SQL query returns %d entries for table '%s' in database: '%s'"
                    % (col_count, tbl, db)
                )
                return ColumnsResponse(
                    fetched=False,
                    count=col_count,
                    database=db,
                    table=tbl,
                    columns=[],
                )

            # Resume from session if available
            if is_resumed:
                for entry in fetched_data:
                    name = entry.get("colname")
                    if name not in _temp:
                        _temp.append(name)
                    logger.info(f"resumed: '{name}'")
                    index += 1

            should_fetch = True
            if is_resumed:
                if len(fetched_data) == col_count:
                    should_fetch = False

            if should_fetch:
                payloads = self._generat_payload(payloads_list=_temp_payloads)
                retval = self._extact(payloads=payloads)

                if retval.is_injected:
                    payload = retval.payload
                    payloads = self._generate_col_payloads(
                        col_count=col_count, payload=payload, index=index
                    )

                    if not is_resumed:
                        session.generate_table(
                            session_filepath=self.session_filepath,
                            query=TBL_COLUMNS.format(name=tbl, tbl_name=tbl),
                        )

                    response_data = self._extract_cols(
                        payloads=payloads, database=db, table=tbl
                    )

                    if response_data.is_fetched:
                        _temp.extend(response_data.result)

                    self._pprint_columns(
                        cursor_or_list=_temp, field_names="", database=db, table=tbl,
                    )
                    return ColumnsResponse(
                        fetched=True,
                        count=col_count,
                        database=db,
                        table=tbl,
                        columns=_temp,
                    )

                if not retval.is_injected:
                    status_code = retval.status_code
                    error = retval.error
                    count = retval.payloads_count

                    if status_code not in [200, 0]:
                        message = f"{error} - {count} times"
                        logger.warning(
                            f"HTTP error codes detected during run:\n{message}"
                        )
                    else:
                        message = f"tested with '{count}' queries, unable to find working SQL query."
                        logger.critical(message)

            else:
                self._pprint_columns(
                    cursor_or_list=_temp, field_names="", database=db, table=tbl,
                )
                return ColumnsResponse(
                    fetched=True,
                    count=col_count,
                    database=db,
                    table=tbl,
                    columns=_temp,
                )

        if not retval.is_injected:
            status_code = retval.status_code
            error = retval.error
            count = retval.payloads_count

            if status_code not in [200, 0]:
                message = f"{error} - {count} times"
                logger.warning(f"HTTP error codes detected during run:\n{message}")
            else:
                message = (
                    f"tested with '{count}' queries, unable to find working SQL query."
                )
                logger.critical(message)

        return ColumnsResponse(
            fetched=False, count=0, database=db, table=tbl, columns=_temp,
        )

    def _pprint_columns(self, cursor_or_list, field_names, database="", table=""):
        obj = prettifier(cursor_or_list, field_names)
        data = obj.data
        entries = obj.entries

        logger.success(f"Database: {database}")
        logger.success(f"Table: {table}")
        logger.success(f"[{entries} columns]")
        logger.success(f"{data}")

    def _extract_cols(self, payloads, database="", table=""):
        _temp, index = [], 0
        Response = collections.namedtuple("Response", ["is_fetched", "result"])

        while index < len(payloads):
            payload = payloads[index]
            payload_request = prepare_payload_request(self, payload)
            url = payload_request.url
            data = payload_request.data
            regex = payload_request.regex
            headers = payload_request.headers

            try:
                response = request.inject_payload(
                    url=url, regex=regex, data=data, headers=headers, proxy=self._proxy
                )
            except KeyboardInterrupt:
                logger.warning(
                    "user aborted during enumeration. Xpath will display partial output"
                )
                break
            else:
                if response.ok:
                    result = response.result
                    logger.info("retrieved: '%s'" % (result))
                    _temp.append(result)

                    retval = session.dump(
                        session_filepath=self.session_filepath,
                        query=COLS_STATEMENT.format(tbl_name=table, colname=result),
                    )

            index += 1

        if _temp and len(_temp) > 0:
            _temp = list(set(_temp))
            resp = Response(is_fetched=True, result=_temp)
        else:
            resp = Response(is_fetched=False, result=_temp)

        return resp

# Import necessary modules
import logging

try:
    from collections.abc import Iterable
except ImportError:
    from collections import Iterable

import re
import six
from .trans_base import trans_comp_check_mdoe_base
from ..etl_util import cached, get_re_full_match, get_set_mode_if_skip_fn

__all__ = ['trans_comp_kv']
logger = logging.getLogger(__name__)


def trans_comp_kv(*args, **kwargs):
    # Handle event case: when first arg is dict or 'event' kwarg is dict
    if (args and isinstance(args[0], dict)) or ('event' in kwargs and isinstance(kwargs['event'], dict)):
        kv = kv_transformer()
        return kv(*args, **kwargs)
    else:
        return kv_transformer(*args, **kwargs)


class kv_transformer(trans_comp_check_mdoe_base):
    DEFAULT_SEP = u'='
    DEFAULT_QUOTE = u'"'

    @staticmethod
    @cached
    def _get_kv_ptn(sep, quote, escape):
        # Pattern for simple key-value without quotes
        p1 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)'

        if not escape:
            # Pattern with quotes but no escaping
            p2 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*([^{1}]*?)\s*{1}'
        else:
            # Pattern with quotes and escaping support
            p2 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*((?:[^{1}]|\\\\{1})*?[^\\\\]){1}'

        ps = u'|'.join([p1, p2]).format(sep, quote)
        logger.info(u"trans_comp_kv: get ptn: {0}".format(ps))
        return re.compile(ps)

    def __init__(self, prefix=None, suffix=None, sep=None, quote=None, escape=None, mode=None):
        super(kv_transformer, self).__init__(mode=mode)
        self.prefix = self._u("" if prefix is None else prefix)
        self.suffix = self._u("" if suffix is None else suffix)
        self.escape = False if escape is None else escape
        self.sep = self._u(self.DEFAULT_SEP if sep is None else sep)
        self.quote = self._u(self.DEFAULT_QUOTE if quote is None else quote)
        self.ptn = self._get_kv_ptn(self.sep, self.quote, self.escape)
        self.normalize = None

    def set(self, e, k, v, real_k=None, check_kw_name=False):
        """Override base to handle escape case: replace \" to " """
        if self.escape:
            v = v.strip().replace("\\" + self.quote, self.quote)
        return super(kv_transformer, self).set(e, k, v, real_k=real_k, check_kw_name=check_kw_name)

    def _extract_kv(self, event, value):
        # Decode binary strings to unicode
        if isinstance(value, six.binary_type):
            value = value.decode('utf8', 'ignore')

        r = self.ptn.findall(value)
        new_event = {}

        for k1, v1, k2, v2 in r:
            if k1:
                self.set(event, k1, v1, real_k=u"{0}{1}{2}".format(self.prefix, k1, self.suffix), check_kw_name=True)
            if k2:
                self.set(event, k2, v2, real_k=u"{0}{1}{2}".format(self.prefix, k2, self.suffix), check_kw_name=True)

        return new_event

    def __call__(self, event, inpt):
        inpt = self._u(inpt)

        # Handle string input as list
        if isinstance(inpt, (six.binary_type, six.text_type)):
            inpt = [inpt]

        if isinstance(inpt, Iterable):
            for i in inpt:
                if not isinstance(i, (six.binary_type, six.text_type)):
                    logger.error(u'trans_comp_lookup: type of input field "{0}" is unknown'.format(i))
                    continue

                if i not in event:
                    logger.info(u'trans_comp_lookup: event "{0}" doesn not contain field "{1}"'.format(event, i))
                    continue

                # Extract key-value pairs
                new_event = self._extract_kv(event, event[i])
                event.update(new_event)
        else:
            logger.error(u"trans_comp_lookup: unknown type of input field {0}".format(inpt))

        return event

import re
from os import path
from images import load as load_image
from medias import load as load_media
from utils import remove_invalid_chars, replace_bools


def parse(GAME_BASE_DIR, renpy, res):
    '''
    Parse all node to a useable format. The node Label named 'start' will be the
    node with id '0'.
    '''
    start_node = label_by_name(renpy, 'start')
    real_start = real_next(renpy, start_node)
    nexts = [real_start]

    while len(nexts) != 0:
        node = nexts[0]
        nexts = nexts[1:]

        if node and id(node) not in res['nodes']:
            nexts += parse_node(GAME_BASE_DIR, renpy, node, res)

    id_start = id(real_start)
    res['nodes'][0] = res['nodes'][id_start]
    del res['nodes'][id_start]


def label_by_name(renpy, name):
    for _key, node in renpy.game.script.namemap.iteritems():
        if isinstance(node, renpy.ast.Label) and node.name == name:
            return node


def show_unknown_node_warning(node):
    infos = node.diff_info() if hasattr(node, 'diff_info') else node
    print('[WARNING] unknown node %s: %s' % (type(node).__name__, infos))


# adds node converted to res['nodes']
# if node uses a sound, adds it to res['sounds']
# returns a list of nodes
def parse_node(GAME_BASE_DIR, renpy, node, res):
    if isinstance(node, renpy.ast.Menu):
        return menu_to_str(renpy, node, res)
    elif isinstance(node, renpy.ast.Say):
        return say_to_str(renpy, node, res)
    elif isinstance(node, renpy.ast.If):
        return if_to_str(renpy, node, res)
    elif isinstance(node, renpy.ast.Python):
        return python_to_str(GAME_BASE_DIR, renpy, node, res)
    elif isinstance(node, renpy.ast.Scene):
        return scene_to_str(GAME_BASE_DIR, renpy, node, res)
    elif isinstance(node, renpy.ast.Show):
        return show_to_str(GAME_BASE_DIR, renpy, node, res)
    elif isinstance(node, renpy.ast.Hide):
        return hide_to_str(renpy, node, res)
    elif isinstance(node, renpy.ast.UserStatement):
        return user_statement_to_str(GAME_BASE_DIR, renpy, node, res)
    else:
        show_unknown_node_warning(node)
        next = real_next(renpy, node.next)
        return [str(id(next))] if next else []


def real_next(renpy, node):
    while True:
        # known nodes
        if (isinstance(node, renpy.ast.Menu)
            or isinstance(node, renpy.ast.Say)
            or isinstance(node, renpy.ast.If)
            or isinstance(node, renpy.ast.Python)
            or isinstance(node, renpy.ast.Scene)
            or isinstance(node, renpy.ast.Show)
            or isinstance(node, renpy.ast.Hide)
                or isinstance(node, renpy.ast.UserStatement)):
            return node
        # don't keep jumps
        elif isinstance(node, renpy.ast.Jump):
            node = label_by_name(renpy, node.target)
        # ignore useless nodes
        elif (isinstance(node, renpy.ast.Label)
              or isinstance(node, renpy.ast.Translate)
              or isinstance(node, renpy.ast.EndTranslate)
              or isinstance(node, renpy.ast.Pass)
              or isinstance(node, renpy.ast.Return)
              or isinstance(node, renpy.ast.With)):
            node = node.next
        elif node != None:
            show_unknown_node_warning(node)
            break
        else:
            break


def menu_to_str(renpy, node, res):
    nexts = []
    menu_items = []
    display_texts = []

    for item in node.items:
        (text, cond, lnext) = item

        if lnext:
            next = real_next(renpy, lnext[0])
            res['nodes'][id(item)] = {
                'class_name': 'MenuItem',
                'arguments': [
                    text,
                    replace_bools(cond),
                    [str(id(next))] if next else []
                ]
            }
            nexts.append(next)
            menu_items.append(item)
        else:
            display_texts.append(text)

    id_menu_items = [str(id(menu_item)) for menu_item in menu_items]
    res['nodes'][id(node)] = {
        'class_name': 'Menu',
        'arguments': [
            '\n'.join(display_texts),
            id_menu_items
        ]
    }

    return nexts


def say_to_str(renpy, node, res):
    next = real_next(renpy, node.next)
    res['nodes'][id(node)] = {
        'class_name': 'Say',
        'arguments': [
            node.who,
            node.what,
            [str(id(next))] if next else []
        ]
    }
    return [next]


def if_to_str(renpy, node, res):
    else_found = False

    for if_block in node.entries:
        if if_block[0] == 'True':
            else_found = True

    if not else_found:
        node.entries.append(('true', [node.next]))

    nexts_of_blocks = []
    nexts_of_if = []

    for if_block in node.entries:
        (cond, block) = if_block
        id_if_block = id(if_block)
        next_of_block = real_next(renpy, block[0])

        res['nodes'][id_if_block] = {
            'class_name': 'IfBlock',
            'arguments': [
                replace_bools(cond),
                [str(id(next_of_block))] if next_of_block else []
            ]
        }
        nexts_of_blocks.append(next_of_block)
        nexts_of_if.append(str(id_if_block))

    res['nodes'][id(node)] = {
        'class_name': 'If',
        'arguments': [nexts_of_if],
    }

    return nexts_of_blocks


VIDEO = re.compile(r'^\s*renpy\.movie_cutscene\s*\((.+)\)\s*$')
PLAY = re.compile(r'^\s*renpy.sound\.play\s*\((.+)\)\s*$')
LOOP = re.compile(r'^\s*loop\s*=(.*)$')


def python_to_str(GAME_BASE_DIR, renpy, node, res):
    next = real_next(renpy, node.next)
    id_nexts = [str(id(next))] if next else []

    match = re.search(VIDEO, node.code.source)

    if match != None and len(match.groups()) == 1:  # it's a video
        file = match.group(1)[1:-1]
        vid_name = remove_invalid_chars(file)
        load_media(GAME_BASE_DIR, res, 'videos', vid_name, file)

        res['nodes'][id(node)] = {
            'class_name': 'Video',
            'arguments': [
                vid_name,
                [str(id(next))] if next else []
            ]
        }
    else:
        match = re.search(PLAY, node.code.source)

        if match != None and len(match.groups()) == 1:  # it's a sound play
            args = [arg.strip() for arg in match.group(1).split(',')]
            loop = find_map(get_loop, args[1:])
            play_to_str(GAME_BASE_DIR, node, id_nexts,
                        res, args[0][1:-1], 'sound', loop)
        else:
            res['nodes'][id(node)] = {
                'class_name': 'PyExpr',
                'arguments': [
                    replace_bools(node.code.source),
                    id_nexts
                ]
            }

    return [next]


def get_loop(arg):
    match = re.search(LOOP, arg)
    if arg != None and len(match.groups()) == 1:
        return match.group(1) == "True"


def find_map(f, coll):
    for x in coll:
        res = f(x)
        if res != None:
            return res


def scene_to_str(GAME_BASE_DIR, renpy, node, res):
    next = real_next(renpy, node.next)
    name = node.imspec[0][0]
    load_image(GAME_BASE_DIR, renpy, res, name, node.imspec)

    res['nodes'][id(node)] = {
        'class_name': 'Scene',
        'arguments': [
            name,
            [str(id(next))] if next else []
        ]
    }
    return [next]


def show_to_str(GAME_BASE_DIR, renpy, node, res):
    next = real_next(renpy, node.next)
    name = node.imspec[0][0]
    is_Movie = load_image(GAME_BASE_DIR, renpy, res, name, node.imspec)

    res['nodes'][id(node)] = {
        'class_name': 'ShowVideo' if is_Movie else 'Show',
        'arguments': [
            name,
            [str(id(next))] if next else []
        ]
    }
    return [next]


def hide_to_str(renpy, node, res):
    next = real_next(renpy, node.next)
    res['nodes'][id(node)] = {
        'class_name': 'Hide',
        'arguments': [
            node.imspec[0][0],
            [str(id(next))] if next else []
        ]
    }
    return [next]


WORD = re.compile(r'([\w.]+|".*?")')


def user_statement_to_str(GAME_BASE_DIR, renpy, node, res):
    cmd = re.findall(WORD, node.line)
    next = real_next(renpy, node.next)
    id_nexts = [str(id(next))] if next else []

    if cmd[0] == 'play' and len(cmd) >= 3:
        loop = 'loop' in cmd[3:] if len(cmd) >= 4 else False
        play_to_str(GAME_BASE_DIR, node, id_nexts,
                    res, cmd[2][1:-1], cmd[1], loop)
    elif cmd[0] == 'voice' and len(cmd) >= 2:
        play_to_str(GAME_BASE_DIR, node, id_nexts,
                    res, cmd[1][1:-1], 'voice', False)
    elif cmd[0] == 'stop' and len(cmd) >= 2:
        stop_to_str(cmd, node, id_nexts, res)
    elif cmd[0] == 'window' and len(cmd) >= 2:
        window_to_str(cmd, node, id_nexts, res)
    elif cmd[0] == 'pause' and len(cmd) >= 1:
        pause_to_str(cmd, node, id_nexts, res)
    else:
        print('[WARNING] unrecognized UserStatement: %s' % node.line)

    return [next]


VIDEO_EXTENSION = ['.webm', '.ogv']


def play_to_str(GAME_BASE_DIR, node, id_nexts, res, file, channel, loop):
    snd_name = remove_invalid_chars(file)
    _, ext = path.splitext(file)
    media_type = 'videos' if ext in VIDEO_EXTENSION else 'sounds'
    load_media(GAME_BASE_DIR, res, media_type, snd_name, file)

    res['nodes'][id(node)] = {
        'class_name': 'Play',
        'arguments': [
            channel,
            snd_name,
            loop,
            id_nexts
        ]
    }


def stop_to_str(cmd, node, id_nexts, res):
    channel = cmd[1]
    res['nodes'][id(node)] = {
        'class_name': 'Stop',
        'arguments': [
            channel,
            id_nexts
        ]
    }


def window_to_str(cmd, node, id_nexts, res):
    show = True if cmd[1] == 'show' else False if cmd[1] == 'hide' else None

    if isinstance(show, bool):
        res['nodes'][id(node)] = {
            'class_name': 'ShowWindow',
            'arguments': [
                show,
                id_nexts
            ]
        }
    else:
        print('[WARNING] unrecognized window option: %s' % cmd[1])


def pause_to_str(cmd, node, id_nexts, res):
    res['nodes'][id(node)] = {
        'class_name': 'Pause',
        'arguments': [
            id_nexts
        ]
    }

