# Define the transform function that filters keys with value 1
def transform(i: dict, o, m) -> list:
    # Return list of keys where value equals 1
    return [k for k, v in i.items() if v == 1]

# Test class for async framework operations
class TestFrameworkAsync(IsolatedAsyncioTestCase):

    # Test basic async process execution
    async def test_process_run_async_will_succeed(self):

        # Create a process with selector and chain configuration
        process = Process(
            selector=Selector(
                chains=[
                    AnyChain(
                        ordered_events=[
                            Transformer(fn=transform),
                        ],
                    ),
                ],
            ),
        )

        try:
            # Run the process asynchronously with test elements
            result = await process.run_async(
                elements=[
                    Element(input={"a": 0, "b": 1}),
                    Element(input={"c": 0, "y": 1}),
                    Element(input={"d": 1, "b": 0}),
                ]
            )

            # Verify outputs match expected values
            self.assertEqual(["b"], result.elements[0].output)
            self.assertEqual(["y"], result.elements[1].output)
            self.assertEqual(["d"], result.elements[2].output)

        except Exception as e:
            # Fail test if any exception occurs
            self.fail(e)

    # Test async process with timeout constraint
    async def test_process_run_async_with_timeout(self):
        # Generate character list for random input generation
        chars = list("abcdefghijklmno")

        # Create process with same configuration as before
        process = Process(
            selector=Selector(
                chains=[
                    AnyChain(
                        ordered_events=[
                            Transformer(fn=transform),
                        ],
                    ),
                ],
            ),
        )

        try:
            # Generate many random input elements
            elements = [
                Element(
                    input={
                        np.random.choice(chars): np.random.randint(0, 2) 
                        for _ in range(np.random.randint(1, 10))
                    },
                )
                for _ in range(10000)
            ]

            # Run with strict timeout (should trigger timeout error)
            await process.run_async(
                elements=elements,
                timeout=0.1,
            )

        except Exception as e:
            # Verify the exception is specifically a multiprocessing.TimeoutError
            self.assertEqual(type(e), multiprocessing.TimeoutError)

