@enum.unique
class ImportErrors(Enum):
    same_line = 'AZUL101 more than one symbol imported per line'
    not_joined = 'AZUL102 symbols from the same module imported in separate statements'
    statement_not_ordered = 'AZUL111 import statements are not correctly ordered'
    symbol_not_ordered = 'AZUL112 symbols in from import are not correctly ordered'
    not_wrapped = 'AZUL131 from import lacks parentheses'
    missing_breaks = 'AZUL132 missing newline between parentheses and imported symbols'
    no_trailing_comma = 'AZUL133 symbol in from import lacks trailing comma'
    unresolvable = 'AZUL141 cannot resolve import statement from project root'


@enum.unique
class ModuleType(enum.IntEnum):
    # Values determine sorting order and correspond to the ordering defined in
    # the contributing guide.
    python_runtime = 1
    external_dependency = 2
    internal = 3

    @classmethod
    def from_module_name(cls, module_name: str) -> 'ModuleType':
        """
        Infer module origin by inspecting the spec from its resolved name.
        A builtin module
        >>> ModuleType.from_module_name('sys')
        <ModuleType.python_runtime: 1>
        # A non-builtin standrad library module
        >>> ModuleType.from_module_name('os')
        <ModuleType.python_runtime: 1>
        # A downloaded external package
        >>> ModuleType.from_module_name('boto3')
        <ModuleType.external_dependency: 2>
        # A non-namespace internal module
        >>> ModuleType.from_module_name('azul.indexer')
        <ModuleType.internal: 3>
        # A non-namespace internal module outside the main src/ folder.
        # The flake8-import-order plugin struggles with these.
        >>> ModuleType.from_module_name('azul_test_case')
        <ModuleType.internal: 3>
        # A namespace internal module
        >>> ModuleType.from_module_name('lambdas.service')
        <ModuleType.internal: 3>
        """
        spec = importlib.util.find_spec(module_name)
        if spec is None:
            raise ImportError
        elif spec.origin is None and spec.submodule_search_locations is None:
            # Not every module included in the Python standard library is
            # considered "builtin." That term is reserved for modules such as
            # `sys` that are implemented in C and lack an associated .py file.
            assert module_name in sys.builtin_module_names, module_name
            return cls.python_runtime
        else:
            if spec.origin is None:
                # Namespace modules lack an __init__.py and represent their
                # location as a list of directories.
                path = one(spec.submodule_search_locations)
            else:
                path = spec.origin
            if 'site-packages' in path:
                # Assuming dependencies are installed in a virtual environment.
                # More specific path test would fail in travis.
                return cls.external_dependency
            elif path.startswith(config.project_root):
                return cls.internal
            else:
                # Assume any non-builtin module imported from outside the
                # project is part of the standard library. Python installation
                # locations can vary.
                return cls.python_runtime


EitherImport = Union[ast.Import, ast.ImportFrom]


@attr.s(auto_attribs=True, kw_only=True, frozen=True, order=True)
class ModuleOrderInfo:
    module_type: ModuleType
    module_name: str
    is_from_import: bool

    @classmethod
    def normalize_module(cls, node: EitherImport) -> Tuple[str, bool]:
        if isinstance(node, ast.Import):
            module_name = one(node.names).name
            is_from_import = False
        elif isinstance(node, ast.ImportFrom):
            module_name = node.module
            is_from_import = True
        else:
            assert False, type(node)
        return module_name, is_from_import

    @classmethod
    def from_ast(cls, node: EitherImport) -> 'ModuleOrderInfo':
        """
        >>> def from_stmt(src): return ModuleOrderInfo.from_ast(one(ast.parse(src).body))
        >>> from_stmt('import azul.indexer, azul.service')
        Traceback (most recent call last):
        ...
        ValueError: too many items in iterable (expected 1)
        >>> from_stmt('import does_not_exist')
        Traceback (most recent call last):
        ...
        ImportError
        >>> from_stmt('import azul.indexer')
        ModuleOrderInfo(module_type=<ModuleType.internal: 3>, module_name='azul.indexer', is_from_import=False)
        >>> from_stmt('from azul.indexer import BaseIndexer')
        ModuleOrderInfo(module_type=<ModuleType.internal: 3>, module_name='azul.indexer', is_from_import=True)
        >>> from_stmt('import itertools')
        ModuleOrderInfo(module_type=<ModuleType.python_runtime: 1>, module_name='itertools', is_from_import=False)
        >>> from_stmt('from more_itertools import one') #doctest: +NORMALIZE_WHITESPACE
        ModuleOrderInfo(module_type=<ModuleType.external_dependency: 2>, \
                        module_name='more_itertools', \
                        is_from_import=True)
        """
        module_name, is_from_import = cls.normalize_module(node)
        module_type = ModuleType.from_module_name(module_name)
        return cls(module_type=module_type,
                   module_name=module_name,
                   is_from_import=is_from_import)


@attr.s(auto_attribs=True, kw_only=True, frozen=True)
class OrderedImport:
    node: EitherImport
    order_info: ModuleOrderInfo

    @classmethod
    def from_ast(cls, node: EitherImport) -> 'OrderedImport':
        return cls(node=node, order_info=ModuleOrderInfo.from_ast(node))

    def is_correct_order(self, other: 'OrderedImport') -> bool:
        return (self.node.lineno <= other.node.lineno) == (self.order_info <= other.order_info)


@attr.s(auto_attribs=True, kw_only=True, frozen=True)
class ErrorInfo:
    line: int
    column: int
    msg: str

    @classmethod
    def from_ast(cls, node: EitherImport, err: ImportErrors):
        return cls(line=node.lineno,
                   column=node.col_offset,
                   msg=err.value)

    def to_flake8_tuple(self) -> tuple:
        # flake8 requires a fourth attribute but it's not used
        return *attr.astuple(self), None


class ImportVisitor(ast.NodeVisitor):
    expected_resolution_failures = {
        'pydevd',
        # FIXME: Remove hacky import of SupportsLessThan
        #        https://github.com/DataBiosphere/azul/issues/2783
        '_typeshed'
    }

    def __init__(self, file_name: str, file_tokens: Iterable[TokenInfo]):
        super().__init__()
        self.file_name = file_name
        self.line_tokens = defaultdict(list)
        for token_info in file_tokens:
            self.line_tokens[token_info.start[0]].append(token_info)
        for line_tokens in self.line_tokens.values():
            line_tokens.sort(key=lambda token_info: token_info.start[1])
        self.errors: List[ErrorInfo] = []
        self.visited_order_info: List[OrderedImport] = []

    def visit_Import(self, node: ast.Import) -> None:
        self.check_split_import(node)
        self.check_statement_order(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        self.check_joined_import(node)
        self.check_wrapping(node)
        self.check_symbol_order(node)
        self.check_statement_order(node)

    def check_split_import(self, node: EitherImport) -> None:
        if len(node.names) > 1:
            self._error(node, ImportErrors.same_line)

    def check_statement_order(self, node: EitherImport) -> None:
        try:
            ordered_import = OrderedImport.from_ast(node)
        except ValueError:
            # Some other formatting error prevents the correct order from being
            # determined
            pass
        except ImportError:
            module_name, _ = ModuleOrderInfo.normalize_module(node)
            if module_name not in self.expected_resolution_failures:
                self._error(node, ImportErrors.unresolvable)
        else:
            # The order in which NodeVisitor traverses the syntax tree is unspecified
            # so we can't be sure which nodes have already been visited.
            # To prevent a single out-of-order import from causing errors on every
            # other line, we only compare each import statement with one other statement.
            # To prevent the same line from being reported twice, the error is always
            # reported for the node we're currently visiting, regardless of whether it
            # comes first or second.
            pred = self._visited_predecessor(node)
            succ = self._visited_successor(node)
            if pred is not None and not self._is_correct_order(pred, ordered_import):
                self._error(node, ImportErrors.statement_not_ordered)
            elif succ is not None and not self._is_correct_order(ordered_import, succ):
                self._error(node, ImportErrors.statement_not_ordered)
            self.visited_order_info.append(ordered_import)

    def check_joined_import(self, node: ast.ImportFrom) -> None:
        for visited in self.visited_order_info:
            if (
                isinstance(visited.node, ast.ImportFrom)
                and visited.node.module == node.module
                and self._is_same_block(node, visited.node)
            ):
                self._error(node, ImportErrors.not_joined)
                break

    def check_wrapping(self, node: ast.ImportFrom) -> None:
        start_tokens = self._filtered_tokens(node.lineno)
        end_tokens = self._filtered_tokens(node.end_lineno)
        for i, t in enumerate(start_tokens):
            if t.string == '(':
                if i < len(start_tokens) - 1 or len(end_tokens) > 1:
                    self._error(node, ImportErrors.missing_breaks)
                break
        else:
            self._error(node, ImportErrors.not_wrapped)
        for i in range(node.lineno + 1, node.end_lineno):
            tokens = self._filtered_tokens(i)
            if not tokens:
                pass
            elif len(tokens) > 2 and (tokens[1].string != 'as' or len(tokens) > 4):
                self._error(node, ImportErrors.same_line)
            elif tokens[-1].string != ',':
                self._error(node, ImportErrors.no_trailing_comma)

    def check_symbol_order(self, node: ast.ImportFrom):
        for alias0, alias1 in zip(node.names, node.names[1:]):
            if alias0.name > alias1.name:
                self._error(node, ImportErrors.symbol_not_ordered)

    def _error(self, node: EitherImport, err: ImportErrors) -> None:
        self.errors.append(ErrorInfo.from_ast(node, err))

    def _is_correct_order(self,
                          import1: OrderedImport,
                          import2: OrderedImport
                          ) -> bool:
        return import1.is_correct_order(import2) or not self._is_same_block(import1.node, import2.node)

    def _is_same_block(self, node1: EitherImport, node2: EitherImport):
        if node1.col_offset != node2.col_offset:
            return False
        else:
            if node1.lineno > node2.lineno:
                node1, node2 = node2, node1
            # Local imports in different functions, for example
            # Check for dedent
            return not any(line_tokens and line_tokens[0].start[1] < node1.col_offset
                           for line_tokens in map(self._filtered_tokens,
                                                  range(node1.lineno, node2.lineno)))

    def _visited_successor(self, node: EitherImport) -> Optional[OrderedImport]:
        """
        Scan the list of previously visited nodes for the node with the lowest
        line number that is greater than the provided node's line number.
        """
        return min(filter(lambda t: t.node.lineno > node.lineno, self.visited_order_info),
                   key=lambda t: t.node.lineno,
                   default=None)

    def _visited_predecessor(self, node: EitherImport) -> Optional[OrderedImport]:
        """
        Scan the list of previously visited nodes for the node with the highest
        line number that is less than the provided node's line number.
        """
        return max(filter(lambda t: t.node.lineno < node.lineno, self.visited_order_info),
                   key=lambda t: t.node.lineno,
                   default=None)

    def _filtered_tokens(self, linenno):
        return [tokeninfo
                for tokeninfo in self.line_tokens[linenno]  # 1-based indexing for source code lines
                if tokeninfo.type not in (tokenize.COMMENT, tokenize.NEWLINE, tokenize.NL, tokenize.ENDMARKER)]


class AzulImports:
    name = 'azul_imports'
    version = 1.0

    # The constructor signature is subject to the restrictions documented at
    # https://flake8.pycqa.org/en/3.8.2/plugin-development/plugin-parameters.html#indicating-desired-data
    def __init__(self, tree, file_tokens, filename):
        self.tree = tree
        self.tokens = file_tokens
        self.file_name = filename

    def _run(self) -> List[ErrorInfo]:
        visitor = ImportVisitor(self.file_name, self.tokens)
        visitor.visit(self.tree)
        return visitor.errors

    def run(self) -> List[tuple]:
        return [err.to_flake8_tuple() for err in self._run()]

# Import necessary modules
from .errors import ConfigurationError
from docker.utils.ports import build_port_bindings

# Define ServicePort class
class ServicePort(namedtuple('_ServicePort', 'target published protocol mode external_ip')):
    def __new__(cls, target, published, *args, **kwargs):
        try:
            if target:
                target = int(target)
        except ValueError:
            raise ConfigurationError('Invalid target port: {}'.format(target))

        if published:
            if isinstance(published, str) and '-' in published:  # "x-y:z" format
                a, b = published.split('-', 1)
                if not a.isdigit() or not b.isdigit():
                    raise ConfigurationError('Invalid published port: {}'.format(published))
            else:
                try:
                    published = int(published)
                except ValueError:
                    raise ConfigurationError('Invalid published port: {}'.format(published))

        return super().__new__(
            cls, target, published, *args, **kwargs
        )

    @classmethod
    def parse(cls, spec):
        if isinstance(spec, cls):
            # When extending a service with ports, the port definitions have already been parsed
            return [spec]

        if not isinstance(spec, dict):
            result = []
            try:
                for k, v in build_port_bindings([spec]).items():
                    if '/' in k:
                        target, proto = k.split('/', 1)
                    else:
                        target, proto = (k, None)

                    for pub in v:
                        if pub is None:
                            result.append(
                                cls(target, None, proto, None, None)
                            )
                        elif isinstance(pub, tuple):
                            result.append(
                                cls(target, pub[1], proto, None, pub[0])
                            )
                        else:
                            result.append(
                                cls(target, pub, proto, None, None)
                            )
            except ValueError as e:
                raise ConfigurationError(str(e))

            return result

        return [cls(
            spec.get('target'),
            spec.get('published'),
            spec.get('protocol'),
            spec.get('mode'),
            None
        )]

    @property
    def merge_field(self):
        return (self.target, self.published, self.external_ip, self.protocol)

    def repr(self):
        return {
            k: v for k, v in zip(self._fields, self) if v is not None
        }

    def legacy_repr(self):
        return normalize_port_dict(self.repr())


def normalize_port_dict(port):
    return '{external_ip}{has_ext_ip}{published}{is_pub}{target}/{protocol}'.format(
        published=port.get('published', ''),
        is_pub=(':' if port.get('published') is not None or port.get('external_ip') else ''),
        target=port.get('target'),
        protocol=port.get('protocol', 'tcp'),
        external_ip=port.get('external_ip', ''),
        has_ext_ip=(':' if port.get('external_ip') else ''),
    )

# Liquidity Provider Client module
import os
from http import HTTPStatus
from typing import Optional, List
from urllib.parse import urljoin
from uuid import UUID
import requests

from diem_utils.types.liquidity.currency import CurrencyPair
from diem_utils.types.liquidity.lp import LPDetails
from diem_utils.types.liquidity.quote import QuoteData, QuoteId
from diem_utils.types.liquidity.settlement import DebtData
from diem_utils.types.liquidity.trade import TradeId, Direction, TradeData


class LpClient:
    def __init__(self, base_url=None):
        # Construct base URL from environment variables or defaults
        self._base_url = f"http://{os.getenv('LIQUIDITY_SERVICE_HOST', 'liquidity')}:{os.getenv('LIQUIDITY_SERVICE_PORT', 5000)}"

        if base_url:
            self._base_url = base_url

    def get_quote(self, pair: CurrencyPair, amount: int) -> QuoteData:
        data = {
            "base_currency": pair.base.value,
            "quote_currency": pair.quote.value,
            "amount": amount,
        }

        response = requests.post(url=urljoin(self._base_url, "quote"), json=data)
        raise_if_failed(response, f"Failed to get quote for {data}")

        return QuoteData.from_json(response.text)

    def lp_details(self) -> LPDetails:
        response = requests.get(url=urljoin(self._base_url, "details"))
        raise_if_failed(response, "Failed to get Liquidity Provider details")

        return LPDetails.from_json(response.text)

    def trade_info(self, trade_id: TradeId) -> TradeData:
        trade_id_str = str(trade_id)
        response = requests.get(url=urljoin(self._base_url, f"trade/{trade_id_str}"))
        raise_if_failed(response, f"Failed to get info for trade ID {trade_id_str}")

        return TradeData.from_json(response.text)

    def trade_and_execute(
        self,
        quote_id: QuoteId,
        direction: Direction,
        diem_deposit_address: Optional[str] = None,
        tx_version: Optional[int] = None,
    ) -> TradeId:
        request_body = {
            "quote_id": str(quote_id),
            "direction": direction.value,
        }

        if diem_deposit_address:
            request_body["diem_deposit_address"] = diem_deposit_address

        if tx_version:
            request_body["tx_version"] = tx_version

        response = requests.post(
            url=urljoin(self._base_url, "trade"), json=request_body
        )
        raise_if_failed(response, f"Failed to execute trade for {request_body}")

        return TradeId(UUID(response.json()["trade_id"]))

    def get_debt(self) -> List[DebtData]:
        response = requests.get(url=urljoin(self._base_url, "debt"))
        raise_if_failed(response, "Failed to retrieve debt")

        return [DebtData.from_dict(debt_dict) for debt_dict in response.json()["debts"]]

    def settle(self, debt_id, settlement_confirmation):
        response = requests.put(
            url=urljoin(self._base_url, f"debt/{debt_id}"),
            json={"settlement_confirmation": settlement_confirmation},
        )
        raise_if_failed(
            response,
            f"Failed to settle debt ID {debt_id}; "
            f"confirmation {settlement_confirmation}",
        )


def raise_if_failed(response, error_description):
    if response.status_code < 200 or response.status_code >= 300:
        raise LpError(f"{error_description} ({response.status_code})")


class LpError(Exception):
    pass

# Config flow for Airzone Local API integration
from __future__ import annotations

from typing import Any
import voluptuous as vol

from aioairzone.common import ConnectionOptions
from aioairzone.exceptions import InvalidHost
from aioairzone.localapi_device import AirzoneLocalApi
from aiohttp.client_exceptions import ClientConnectorError

from homeassistant import config_entries
from homeassistant.const import CONF_HOST, CONF_PORT
from homeassistant.data_entry_flow import FlowResult
from homeassistant.helpers import aiohttp_client

from .const import DEFAULT_LOCAL_API_PORT, DOMAIN


class ConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):
    """Handle config flow for an Airzone device."""

    async def async_step_user(
        self, user_input: dict[str, Any] | None = None
    ) -> FlowResult:
        """Handle the initial step."""
        errors = {}

        if user_input is not None:
            # Check for existing entries with same host and port
            self._async_abort_entries_match(
                {
                    CONF_HOST: user_input[CONF_HOST],
                    CONF_PORT: user_input[CONF_PORT],
                }
            )

            try:
                # Create Airzone API client and validate connection
                airzone = AirzoneLocalApi(
                    aiohttp_client.async_get_clientsession(self.hass),
                    ConnectionOptions(
                        user_input[CONF_HOST],
                        user_input[CONF_PORT],
                    ),
                )
                await airzone.validate_airzone()
            except (ClientConnectorError, InvalidHost):
                # Connection failed
                errors["base"] = "cannot_connect"
            else:
                # Success - create entry
                title = f"Airzone {user_input[CONF_HOST]}:{user_input[CONF_PORT]}"
                return self.async_create_entry(title=title, data=user_input)

        # Show form with input fields
        return self.async_show_form(
            step_id="user",
            data_schema=vol.Schema(
                {
                    vol.Required(CONF_HOST): str,
                    vol.Required(CONF_PORT, default=DEFAULT_LOCAL_API_PORT): int,
                }
            ),
            errors=errors,
        )

import abc
import vim
import logging
from functools import partial
import typing

from vimspector import utils


class Expandable:
  EXPANDED_BY_USER = 2
  EXPANDED_BY_US = 1
  COLLAPSED_BY_USER = 0
  COLLAPSED_BY_DEFAULT = None

  """Base for anything which might contain a hierarchy of values represented by
  a 'variablesReference' to be resolved by the 'variables' request. Records the
  current state expanded/collapsed. Implementations just implement
  VariablesReference to get the variables."""

  def __init__( self ):
    self.variables: typing.List[ 'Variable' ] = None
    # None is Falsy and represents collapsed _by default_. WHen set to False,
    # this means the user explicitly collapsed it. When True, the user expanded
    # it (or we expanded it by default).
    self.expanded: int = Expandable.COLLAPSED_BY_DEFAULT

  def IsExpanded( self ):
    return bool( self.expanded )

  def ShouldDrawDrillDown( self ):
    return self.IsExpanded() and self.variables is not None

  def IsExpandable( self ):
    return self.VariablesReference() > 0

  @abc.abstractmethod
  def VariablesReference( self ):
    assert False


class Scope( Expandable ):
  """Holds an expandable scope (a DAP scope dict), with expand/collapse state"""

  def __init__( self, scope: dict ):
    super().__init__()
    self.scope = scope

  def VariablesReference( self ):
    return self.scope.get( 'variablesReference', 0 )

  def Update( self, scope ):
    self.scope = scope


class WatchResult( Expandable ):
  """Holds the result of a Watch expression with expand/collapse."""

  def __init__( self, result: dict ):
    super().__init__()
    self.result = result
    # A new watch result is marked as changed
    self.changed = True

  def VariablesReference( self ):
    return self.result.get( 'variablesReference', 0 )

  def Update( self, result ):
    self.changed = False
    if self.result[ 'result' ] != result[ 'result' ]:
      self.changed = True
    self.result = result


class WatchFailure( WatchResult ):
  def __init__( self, reason ):
    super().__init__( { 'result': reason } )
    self.changed = True


class Variable( Expandable ):
  """Holds one level of an expanded value tree. Also itself expandable."""

  def __init__( self, variable: dict ):
    super().__init__()
    self.variable = variable
    # A new variable appearing is marked as changed
    self.changed = True

  def VariablesReference( self ):
    return self.variable.get( 'variablesReference', 0 )

  def Update( self, variable ):
    self.changed = False
    if self.variable[ 'value' ] != variable[ 'value' ]:
      self.changed = True
    self.variable = variable


class Watch:
  """Holds a user watch expression (DAP request) and the result (WatchResult)"""

  def __init__( self, expression: dict ):
    self.result: WatchResult
    self.line = None
    self.expression = expression
    self.result = None


class View:
  lines: typing.Dict[ int, Expandable ]
  draw: typing.Callable

  def __init__( self, win, lines, draw ):
    self.lines = lines
    self.draw = draw
    self.buf = win.buffer
    utils.SetUpUIWindow( win )


class VariablesView( object ):
  def __init__( self, variables_win, watches_win ):
    self._logger = logging.getLogger( __name__ )
    utils.SetUpLogging( self._logger )
    self._connection = None
    self._current_syntax = ''

    def AddExpandMappings():
      vim.command( 'nnoremap <silent> <buffer> <CR> '
                   ':<C-u>call vimspector#ExpandVariable()<CR>' )
      vim.command( 'nnoremap <silent> <buffer> <2-LeftMouse> '
                   ':<C-u>call vimspector#ExpandVariable()<CR>' )

    # Set up the "Variables" buffer in the variables_win
    self._scopes: typing.List[ Scope ] = []
    self._vars = View( variables_win, {}, self._DrawScopes )
    utils.SetUpHiddenBuffer( self._vars.buf, 'vimspector.Variables' )
    with utils.LetCurrentWindow( variables_win ):
      AddExpandMappings()

    # Set up the "Watches" buffer in the watches_win (and create a WinBar in
    # there)
    self._watches: typing.List[ Watch ] = []
    self._watch = View( watches_win, {}, self._DrawWatches )
    utils.SetUpPromptBuffer( self._watch.buf,
                             'vimspector.Watches',
                             'Expression: ',
                             'vimspector#AddWatchPrompt',
                             'vimspector#OmniFuncWatch' )
    with utils.LetCurrentWindow( watches_win ):
      AddExpandMappings()
      vim.command(
        'nnoremap <buffer> <DEL> :call vimspector#DeleteWatch()<CR>' )
      if utils.UseWinBar():
        vim.command( 'nnoremenu 1.1 WinBar.New '
                     ':call vimspector#AddWatch()<CR>' )
        vim.command( 'nnoremenu 1.2 WinBar.Expand/Collapse '
                     ':call vimspector#ExpandVariable()<CR>' )
        vim.command( 'nnoremenu 1.3 WinBar.Delete '
                     ':call vimspector#DeleteWatch()<CR>' )

    # Set the (global!) balloon expr if supported
    has_balloon      = int( vim.eval( "has( 'balloon_eval' )" ) )
    has_balloon_term = int( vim.eval( "has( 'balloon_eval_term' )" ) )
    self._oldoptions = {}
    if has_balloon or has_balloon_term:
      self._oldoptions = {
        'balloonexpr': vim.options[ 'balloonexpr' ],
        'balloondelay': vim.options[ 'balloondelay' ],
      }
      vim.options[ 'balloonexpr' ] = 'vimspector#internal#balloon#BalloonExpr()'
      vim.options[ 'balloondelay' ] = 250

    if has_balloon:
      self._oldoptions[ 'ballooneval' ] = vim.options[ 'ballooneval' ]
      vim.options[ 'ballooneval' ] = True

    if has_balloon_term:
      self._oldoptions[ 'balloonevalterm' ] = vim.options[ 'balloonevalterm' ]
      vim.options[ 'balloonevalterm' ] = True

    self._is_term = not bool( int( vim.eval( "has( 'gui_running' )" ) ) )

  def Clear( self ):
    with utils.ModifiableScratchBuffer( self._vars.buf ):
      utils.ClearBuffer( self._vars.buf )
    with utils.ModifiableScratchBuffer( self._watch.buf ):
      utils.ClearBuffer( self._watch.buf )
    self._current_syntax = ''

  def ConnectionUp( self, connection ):
    self._connection = connection

  def ConnectionClosed( self ):
    self.Clear()
    self._connection = None

  def Reset( self ):
    for k, v in self._oldoptions.items():
      vim.options[ k ] = v
    utils.CleanUpHiddenBuffer( self._vars.buf )
    utils.CleanUpHiddenBuffer( self._watch.buf )

  def LoadScopes( self, frame ):
    def scopes_consumer( message ):
      new_scopes = []
      expanded_some_scope = False
      for scope_body in message[ 'body' ][ 'scopes' ]:
        # Find it in the scopes list
        found = False
        for index, s in enumerate( self._scopes ):
          if s.scope[ 'name' ] == scope_body[ 'name' ]:
            found = True
            scope = s
            break
        if not found:
          scope = Scope( scope_body )
        else:
          scope.Update( scope_body )
        new_scopes.append( scope )
        # Expand the first non-expensive scope which is not manually collapsed
        if ( not expanded_some_scope
             and not scope.scope.get( 'expensive' )
             and scope.expanded is not Expandable.COLLAPSED_BY_USER ):
          scope.expanded = Expandable.EXPANDED_BY_US
          expanded_some_scope = True
        elif ( expanded_some_scope and scope.expanded is
               Expandable.EXPANDED_BY_US ):
          scope.expanded = Expandable.COLLAPSED_BY_DEFAULT
        if scope.IsExpanded():
          self._connection.DoRequest( partial( self._ConsumeVariables,
                                               self._DrawScopes,
                                               scope ), {
            'command': 'variables',
            'arguments': {
              'variablesReference': scope.VariablesReference(),
            },
          } )
      self._scopes = new_scopes
      self._DrawScopes()
    self._connection.DoRequest( scopes_consumer, {
      'command': 'scopes',
      'arguments': {
        'frameId': frame[ 'id' ]
      },
    } )

  def AddWatch( self, frame, expression ):
    watch = {
      'expression': expression,
      'context': 'watch',
    }
    if frame:
      watch[ 'frameId' ] = frame[ 'id' ]
    self._watches.append( Watch( watch ) )
    self.EvaluateWatches()

  def DeleteWatch( self ):
    if vim.current.buffer != self._watch.buf:
      utils.UserMessage( 'Not a watch buffer' )
      return
    current_line = vim.current.window.cursor[ 0 ]
    best_index = -1
    for index, watch in enumerate( self._watches ):
      if ( watch.line is not None
           and watch.line <= current_line
           and watch.line > best_index ):
        best_index = index
    if best_index >= 0:
      del self._watches[ best_index ]
      utils.UserMessage( 'Deleted' )
      self._DrawWatches()
      return
    utils.UserMessage( 'No watch found' )

  def EvaluateWatches( self ):
    for watch in self._watches:
      self._connection.DoRequest(
        partial( self._UpdateWatchExpression, watch ),
        {
          'command': 'evaluate',
          'arguments': watch.expression,
        },
        failure_handler = lambda reason, msg, watch=watch:
            self._WatchExpressionFailed( reason, watch ) )

  def _UpdateWatchExpression( self, watch: Watch, message: dict ):
    if watch.result is not None:
      watch.result.Update( message[ 'body' ] )
    else:
      watch.result = WatchResult( message[ 'body' ] )
    if ( watch.result.IsExpandable() and
         watch.result.IsExpanded() ):
      self._connection.DoRequest( partial( self._ConsumeVariables,
                                           self._watch.draw,
                                           watch.result ), {
        'command': 'variables',
        'arguments': {
          'variablesReference': watch.result.VariablesReference(),
        },
      } )
    self._DrawWatches()

  def _WatchExpressionFailed( self, reason: str, watch: Watch ):
    if watch.result is not None:
      # We already have a result for this watch. Wut ?
      return
    watch.result = WatchFailure( reason )
    self._DrawWatches()

  def ExpandVariable( self ):
    if vim.current.buffer == self._vars.buf:
      view = self._vars
    elif vim.current.buffer == self._watch.buf:
      view = self._watch
    else:
      return

    current_line = vim.current.window.cursor[ 0 ]
    if current_line not in view.lines:
      return

    variable = view.lines[ current_line ]
    if variable.IsExpanded():
      # Collapse
      variable.expanded = Expandable.COLLAPSED_BY_USER
      view.draw()
      return

    if not variable.IsExpandable():
      return

    variable.expanded = Expandable.EXPANDED_BY_USER
    self._connection.DoRequest( partial( self._ConsumeVariables,
                                         view.draw,
                                         variable ), {
      'command': 'variables',
      'arguments': {
        'variablesReference': variable.VariablesReference()
      },
    } )

  def _DrawVariables( self, view,  variables, indent ):
    assert indent > 0
    for variable in variables:
      line = utils.AppendToBuffer(
        view.buf,
        '{indent}{marker}{icon} {name} ({type_}): {value}'.format(
          # We borrow 1 space of indent to draw the change marker
          indent = ' ' * ( indent - 1 ),
          marker = '*' if variable.changed else ' ',
          icon = '+' if ( variable.IsExpandable()
                          and not variable.IsExpanded() ) else '-',
          name = variable.variable[ 'name' ],
          type_ = variable.variable.get( 'type', '' ),
          value = variable.variable.get( 'value',
                                         '<unknown>' ) ).split( '\n' ) )
      view.lines[ line ] = variable
      if variable.ShouldDrawDrillDown():
        self._DrawVariables( view, variable.variables, indent + 2 )

  def _DrawScopes( self ):
    # FIXME: The drawing is dumb and draws from scratch every time. This is
    # simple and works and makes sure the line-map is always correct.
    # However it is pretty inefficient.
    self._vars.lines.clear()
    with utils.RestoreCursorPosition():
      with utils.ModifiableScratchBuffer( self._vars.buf ):
        utils.ClearBuffer( self._vars.buf )
        for scope in self._scopes:
          self._DrawScope( 0, scope )

  def _DrawWatches( self ):
    # FIXME: The drawing is dumb and draws from scratch every time. This is
    # simple and works and makes sure the line-map is always correct.
    # However it is pretty inefficient.
    self._watch.lines.clear()
    with utils.RestoreCursorPosition():
      with utils.ModifiableScratchBuffer( self._watch.buf ):
        utils.ClearBuffer( self._watch.buf )
        utils.AppendToBuffer( self._watch.buf, 'Watches: ----' )
        for watch in self._watches:
          line = utils.AppendToBuffer( self._watch.buf,
                                       'Expression: '
                                       + watch.expression[ 'expression' ] )
          watch.line = line
          self._DrawWatchResult( 2, watch )

  def _DrawScope( self, indent, scope ):
    icon = '+' if scope.IsExpandable() and not scope.IsExpanded() else '-'
    line = utils.AppendToBuffer( self._vars.buf,
                                 '{0}{1} Scope: {2}'.format(
                                   ' ' * indent,
                                   icon,
                                   scope.scope[ 'name' ] ) )
    self._vars.lines[ line ] = scope
    if scope.ShouldDrawDrillDown():
      indent += 2
      self._DrawVariables( self._vars, scope.variables, indent )

  def _DrawWatchResult( self, indent, watch ):
    if not watch.result:
      return
    assert indent > 0
    icon = '+' if ( watch.result.IsExpandable() and
                    not watch.result.IsExpanded() ) else '-'
    line =  '{indent}{marker}{icon} Result: {result}'.format(
      # We borrow 1 space of indent to draw the change marker
      indent = ' ' * ( indent - 1 ),
      marker = '*' if watch.result.changed else ' ',
      icon = icon,
      result = watch.result.result.get( 'result', '<unknown>' ) )
    line = utils.AppendToBuffer( self._watch.buf, line.split( '\n' ) )
    self._watch.lines[ line ] = watch.result
    if watch.result.ShouldDrawDrillDown():
      indent = 4
      self._DrawVariables( self._watch, watch.result.variables, indent )

  def _ConsumeVariables( self, draw, parent, message ):
    new_variables = []
    for variable_body in message[ 'body' ][ 'variables' ]:
      if parent.variables is None:
        parent.variables = []
      # Find the variable in parent
      found = False
      for index, v in enumerate( parent.variables ):
        if v.variable[ 'name' ] == variable_body[ 'name' ]:
          variable = v
          found = True
          break
      if not found:
        variable = Variable( variable_body )
      else:
        variable.Update( variable_body )
      new_variables.append( variable )
      if variable.IsExpandable() and variable.IsExpanded():
        self._connection.DoRequest( partial( self._ConsumeVariables,
                                             draw,
                                             variable ), {
          'command': 'variables',
          'arguments': {
            'variablesReference': variable.VariablesReference()
          },
        } )
    parent.variables = new_variables
    draw()

  def ShowBalloon( self, frame, expression ):
    """Callback to display variable under cursor `:h ballonexpr`"""
    if not self._connection:
      return ''

    def handler( message ):
      # TODO: this result count be expandable, but we have no way to allow the
      # user to interact with the balloon to expand it, unless we use a popup
      # instead, but even then we don't really want to trap the cursor.
      body = message[ 'body' ]
      result = body[ 'result' ]
      if result is None:
        result = 'null'
      display = [
        'Type: ' + body.get( 'type', '<unknown>' ),
        'Value: ' + result
      ]
      utils.DisplayBaloon( self._is_term, display )

    def failure_handler( reason, message ):
      display = [ reason ]
      utils.DisplayBaloon( self._is_term, display )

    # Send async request
    self._connection.DoRequest( handler, {
      'command': 'evaluate',
      'arguments': {
        'expression': expression,
        'frameId': frame[ 'id' ],
        'context': 'hover',
      }
    }, failure_handler )
    # Return working (meanwhile)
    return '...'

  def SetSyntax( self, syntax ):
    self._current_syntax = utils.SetSyntax( self._current_syntax,
                                            syntax,
                                            self._vars.buf,
                                            self._watch.buf )


