if __name__ == "__main__":
    print("Testing PersonalityManager...")
    mgr = PersonalityManager()

    print(f"Current profile: {mgr.current_profile_name}")
    print("Available:", list(mgr.list_profiles().keys()))

    # Test switching
    mgr.set_profile("chaos")
