    mgr2 = PersonalityManager()
    print(f"Reloaded state, current is: {mgr2.current_profile_name}")

    # Reset to baseline
    mgr.set_profile("baseline")
    print("Reset to baseline.")

# Locust performance testing script for SOUL_SENSE_EXAM API
# Tests API performance under concurrent user load

from locust import HttpUser, task, between, events
from locust.runners import MasterRunner
import json
import random


class SoulSenseUser(HttpUser):
    """Simulated user behavior for load testing"""

    # Random wait time between 1 and 3 seconds
    wait_time = between(1, 3)

    def on_start(self):
        """Login on start"""
        # Disable SSL verification for local testing
        self.client.verify = False

        # Generate random username for test
        username = f"loadtest_{random.randint(1000, 9999)}"
        password = "REDACTED_CREDENTIAL"

        # Attempt registration first
        response = self.client.post(
            "/api/v1/auth/register",
            json={
                "username": username,
                "password": password,
                "email": f"{username}@example.com"
            }
        )

        if response.status_code == 201:
            # Registration successful - store auth token
            self.token = response.json()["access_token"]
            self.headers = {"Authorization": f"Bearer {self.token}"}
        else:
            # Registration failed - try login instead
            login_response = self.client.post(
                "/api/v1/auth/login",
                data={"username": username, "password": password}
            )

            if login_response.status_code == 200:
                # Login successful - store auth token
                self.token = login_response.json()["access_token"]
                self.headers = {"Authorization": f"Bearer {self.token}"}
            else:
                # Authentication failed - set empty headers
                self.headers = {}

    @task(3)
    def get_questions(self):
        """Fetch questions - high frequency task"""
        if hasattr(self, 'headers'):
            self.client.get(
                "/api/v1/questions?age=25&limit=10",
                headers=self.headers
            )

    @task(2)
    def get_journal_entries(self):
        """Fetch journal entries - medium frequency task"""
        if hasattr(self, 'headers'):
            self.client.get("/api/v1/journal", headers=self.headers)

    @task(1)
    def create_journal_entry(self):
        """Create journal entry - low frequency task"""
        if hasattr(self, 'headers'):
            moods = ["happy", "sad", "neutral", "excited", "grateful"]
            self.client.post(
                "/api/v1/journal",
                headers=self.headers,
                json={
                    "content": "Performance test entry",
                    "mood": random.choice(moods)
                }
            )

    @task(1)
    def get_user_profile(self):
        """Fetch user profile - low frequency task"""
        if hasattr(self, 'headers'):
            self.client.get("/api/v1/users/me", headers=self.headers)

    @task(1)
    def get_assessment_history(self):
        """Fetch assessment history - low frequency task"""
        if hasattr(self, 'headers'):
            self.client.get("/api/v1/assessments/history", headers=self.headers)


@events.test_stop.add_listener
def on_test_stop(environment, **kwargs):
    """Cleanup after test"""
    if isinstance(environment.runner, MasterRunner):
        print("Performance test completed")
        print(f"Total requests: {environment.runner.stats.total.num_requests}")
        print(f"Failures: {environment.runner.stats.total.num_failures}")
        print(f"Median response time: {environment.runner.stats.total.median_response_time}ms")
        print(f"Average response time: {environment.runner.stats.total.avg_response_time}ms")

# Test interrupt functionality for agent tool calls
from unittest.mock import ANY
import pytest
import json

from strands import Agent, tool
from strands.hooks import BeforeToolCallEvent, HookProvider
from strands.interrupt import Interrupt


@pytest.fixture
def interrupt_hook():
    class Hook(HookProvider):
        def register_hooks(self, registry):
            registry.add_callback(BeforeToolCallEvent, self.interrupt)

        def interrupt(self, event):
            # Skip interruption for weather_tool
            if event.tool_use["name"] == "weather_tool":
                return

            # Interrupt other tools for approval
            response = event.interrupt("test_interrupt", reason="need approval")
            if response != "APPROVE":
                event.cancel_tool = "tool rejected"

    return Hook()


@pytest.fixture
def time_tool():
    @tool(name="time_tool")
    def func():
        return "12:00"
    return func


@pytest.fixture
def weather_tool():
    @tool(name="weather_tool")
    def func():
        return "sunny"
    return func


@pytest.fixture
def agent(interrupt_hook, time_tool, weather_tool):
    return Agent(hooks=[interrupt_hook], tools=[time_tool, weather_tool])


def test_interrupt(agent):
    result = agent("What is the time and weather?")

    tru_stop_reason = result.stop_reason
    exp_stop_reason = "interrupt"
    assert tru_stop_reason == exp_stop_reason

    tru_interrupts = result.interrupts
    exp_interrupts = [
        Interrupt(
            id=ANY,
            name="test_interrupt",
            reason="need approval",
        ),
    ]
    assert tru_interrupts == exp_interrupts

    interrupt = result.interrupts[0]
    responses = [
        {
            "interruptResponse": {
                "interruptId": interrupt.id,
                "response": "APPROVE",
            },
        },
    ]

    result = agent(responses)

    tru_stop_reason = result.stop_reason
    exp_stop_reason = "end_turn"
    assert tru_stop_reason == exp_stop_reason

    result_message = json.dumps(result.message).lower()
    assert all(string in result_message for string in ["12:00", "sunny"])

    tru_tool_result_message = agent.messages[-2]
    exp_tool_result_message = {
        "role": "user",
        "content": [
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [
                        {"text": "sunny"},
                    ],
                },
            },
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [
                        {"text": "12:00"},
                    ],
                },
            },
        ],
    }
    assert tru_tool_result_message == exp_tool_result_message


def test_interrupt_reject(agent):
    result = agent("What is the time and weather?")

    tru_stop_reason = result.stop_reason
    exp_stop_reason = "interrupt"
    assert tru_stop_reason == exp_stop_reason

    interrupt = result.interrupts[0]
    responses = [
        {
            "interruptResponse": {
                "interruptId": interrupt.id,
                "response": "REJECT",
            },
        },
    ]

    result = agent(responses)

    tru_stop_reason = result.stop_reason
    exp_stop_reason = "end_turn"
    assert tru_stop_reason == exp_stop_reason

    tru_tool_result_message = agent.messages[-2]
    exp_tool_result_message = {
        "role": "user",
        "content": [
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [{"text": "sunny"}],
                },
            },
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "error",
                    "content": [{"text": "tool rejected"}],
                },
            },
        ],
    }
    assert tru_tool_result_message == exp_tool_result_message

import math
from typing import Tuple

import jax
from jax.sharding import NamedSharding
from jax.sharding import PartitionSpec as P


# TODO(xiang): move this to weight_utils.py
def shard_put(
    x: jax.Array,
    sharding_names: Tuple[str, ...] | P,
    mesh: jax.sharding.Mesh
) -> jax.Array:
    # Single device sharding requires this special handling
    # to avoid the recursive jit error.
    if math.prod(mesh.axis_sizes) == 1:
        return jax.device_put(x, mesh.devices.flatten()[0])

    return jax.device_put(x, NamedSharding(mesh, P(*sharding_names)))

