    def __post_init__(self):
        # Normalize Jeffrey Epstein's known senders
        self.author = JEFFREY_EPSTEIN if self.author in EPSTEIN_TEXTERS else self.author

        # Handle author string assignment
        if not self.author:
            self.author_str = UNKNOWN
        elif self.author in DISPLAY_LAST_NAME_ONLY and not self.author_str:
            self.author_str = extract_last_name(self.author)
        else:
            self.author_str = self.author_str or self.author

        # Add uncertainty marker if ID not confirmed and not Jeffrey
        if not self.is_id_confirmed and self.author is not None and self.author != JEFFREY_EPSTEIN:
            self.author_str += UNCERTAIN_SUFFIX

        # Clean up newlines based on link status
        if self.is_link():
            self.text = self.text.replace('\n', '').replace(' ', '_')
        else:
            self.text = self.text.replace('\n', ' ')

    @property
    def timestamp_sort_key(self) -> datetime:
        try:
            return self.parse_timestamp()
        except Exception as e:
            return FALLBACK_TIMESTAMP

    def is_link(self) -> bool:
        return self.text.startswith('http')

    def parse_timestamp(self) -> datetime:
        return datetime.strptime(self.timestamp_str, AMERICAN_DATE_FORMAT)

    def timestamp_txt(self) -> Text:
        from epstein_files.util.env import site_config
        try:
            timestamp_str = site_config.format_text_msg_time(self.parse_timestamp())
        except Exception as e:
            logger.info(f"Failed to parse timestamp for {self}")
            timestamp_str = self.timestamp_str
        return Text(f"[{timestamp_str}]", style=TIMESTAMP_DIM)

    def _message(self) -> Text:
        if self.is_link():
            return Text.from_markup(f"[link={self.text}]{self.text}[/link]", style=TEXT_LINK)
        else:
            return highlighter(self.text)

    def __eq__(self, other: Self):
        return (self.author == other.author and
                self.text == other.text and
                self.timestamp_str == other.timestamp_str and
                self.author_str == other.author_str)

    def __rich__(self) -> Text:
        timestamp_txt = self.timestamp_txt().append(' ')
        author_style = get_style_for_name(
            self.author_str if self.author_str.startswith('+') else self.author
        )
        author_txt = Text(self.author_str, style=author_style)
        return Text('').append(timestamp_txt).append(author_txt).append(': ', style='dim').append(self._message())

    def __repr__(self) -> str:
        props = []
        add_prop = lambda k, v: props.append(f"{k}={v}")

        for _field in sorted(fields(self), key=lambda f: f.name):
            key = _field.name
            value = getattr(self, key)

            # Skip redundant author_str if it matches the canonical name
            if key == 'author_str' and self.author and self.author_str.startswith(value):
                continue
            elif isinstance(value, str):
                add_prop(key, f'"{value}"')
            else:
                add_prop(key, value)

        return f"{type(self).__name__}(" + ', '.join(props) + ')'

# Import necessary modules
import logging
import os

from flask import Blueprint, jsonify, request

from app.web import get_config_manager, get_module_loader, require_auth

log = logging.getLogger("docsis.modules")

modules_bp = Blueprint("modules_bp", __name__)


def _serialize_module(mod):
    """
    Convert ModuleInfo to JSON-safe dict.
    """
    return {
        "id": mod.id,
        "name": mod.name,
        "description": mod.description,
        "version": mod.version,
        "author": mod.author,
        "type": mod.type,
        "enabled": mod.enabled,
        "builtin": mod.builtin,
        "error": mod.error,
        "homepage": mod.homepage,
        "is_threshold": "thresholds" in mod.contributes,
        "is_theme": mod.type == "theme",
    }


@modules_bp.route("/api/modules")
@require_auth
def api_modules_list():
    """List all discovered modules with metadata and status."""
    loader = get_module_loader()

    if not loader:
        return jsonify([])

    modules = loader.get_modules()

    return jsonify([_serialize_module(m) for m in modules])


@modules_bp.route("/api/modules/<module_id>/enable", methods=["POST"])
@require_auth
def api_module_enable(module_id):
    """Enable a disabled module (persisted, requires restart)."""
    loader = get_module_loader()

    if not loader:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500

    module = next((m for m in loader.get_modules() if m.id == module_id), None)

    if not module:
        return jsonify({"success": False, "error": f"Module '{module_id}' not found"}), 404

    config_mgr = get_config_manager()

    if not config_mgr:
        return jsonify({"success": False, "error": "Config not initialized"}), 500

    disabled_raw = config_mgr.get("disabled_modules", "")
    disabled_set = {s.strip() for s in disabled_raw.split(",") if s.strip()}

    # Mutual exclusion: if enabling a threshold module, disable the currently active one
    if "thresholds" in module.contributes:
        for m in loader.get_threshold_modules():
            if m.id != module_id and m.id not in disabled_set:
                disabled_set.add(m.id)
                log.info("Auto-disabled threshold module '%s' (mutual exclusion)", m.id)

    # Mutual exclusion: if enabling a theme, disable others and set active_theme
    if module.type == "theme":
        for m in loader.get_theme_modules():
            if m.id != module_id and m.id not in disabled_set:
                disabled_set.add(m.id)
                log.info("Auto-disabled theme module '%s' (mutual exclusion)", m.id)

    disabled_set.discard(module_id)
    updates = {"disabled_modules": ",".join(sorted(disabled_set))}

    if module.type == "theme":
        updates["active_theme"] = module_id

    config_mgr.save(updates)
    log.info("Module '%s' enabled (restart required)", module_id)

    return jsonify({"success": True, "restart_required": True})


@modules_bp.route("/api/modules/<module_id>/disable", methods=["POST"])
@require_auth
def api_module_disable(module_id):
    """Disable a module (persisted, requires restart)."""
    loader = get_module_loader()

    if not loader:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500

    module = next((m for m in loader.get_modules() if m.id == module_id), None)

    if not module:
        return jsonify({"success": False, "error": f"Module '{module_id}' not found"}), 404

    config_mgr = get_config_manager()

    if not config_mgr:
        return jsonify({"success": False, "error": "Config not initialized"}), 500

    # Block disabling the last active theme module
    if module.type == "theme":
        disabled_raw = config_mgr.get("disabled_modules", "")
        disabled_set_check = {s.strip() for s in disabled_raw.split(",") if s.strip()}

        active_themes = [
            m for m in loader.get_theme_modules()
            if m.id not in disabled_set_check and m.id != module_id
        ]

        if not active_themes:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active theme. Enable a different theme first.",
            }), 409

    # Block disabling the last active threshold module
    if "thresholds" in module.contributes:
        disabled_raw = config_mgr.get("disabled_modules", "")
        disabled_set = {s.strip() for s in disabled_raw.split(",") if s.strip()}

        active_thresholds = [
            m for m in loader.get_threshold_modules()
            if m.id not in disabled_set and m.id != module_id
        ]

        if not active_thresholds:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active threshold profile. Enable a different one first.",
            }), 409

    disabled_raw = config_mgr.get("disabled_modules", "")
    disabled_set = {s.strip() for s in disabled_raw.split(",") if s.strip()}
    disabled_set.add(module_id)

    config_mgr.save({"disabled_modules": ",".join(sorted(disabled_set))})
    log.info("Module '%s' disabled (restart required)", module_id)

    return jsonify({"success": True, "restart_required": True})


@modules_bp.route("/api/themes")
@require_auth
def api_themes_list():
    """List all theme modules with their CSS variable data."""
    loader = get_module_loader()

    if not loader:
        return jsonify([])

    themes = loader.get_theme_modules()
    result = []

    for m in themes:
        d = _serialize_module(m)
        d["theme_data"] = m.theme_data
        result.append(d)

    return jsonify(result)


@modules_bp.route("/api/themes/registry")
@require_auth
def api_themes_registry():
    """Fetch available themes from the remote registry."""
    config_mgr = get_config_manager()

    if not config_mgr:
        return jsonify([])

    registry_url = config_mgr.get(
        "theme_registry_url",
        "https://raw.githubusercontent.com/itsDNNS/docsight-themes/main/registry.json",
    )

    from app.theme_registry import fetch_registry
    themes = fetch_registry(registry_url)

    loader = get_module_loader()
    installed_ids = set()

    if loader:
        installed_ids = {m.id for m in loader.get_theme_modules()}

    available = [t for t in themes if t["id"] not in installed_ids]

    return jsonify(available)


@modules_bp.route("/api/themes/install", methods=["POST"])
@require_auth
def api_themes_install():
    """Install a theme from the registry."""
    data = request.get_json()

    if not data or "download_url" not in data or "id" not in data:
        return jsonify({"success": False, "error": "Missing download_url or id"}), 400

    theme_dir = os.path.join("/modules", data["id"].replace(".", "_"))

    from app.theme_registry import download_theme

    if download_theme(data["download_url"], theme_dir):
        return jsonify({"success": True, "restart_required": True})
    else:
        return jsonify({"success": False, "error": "Download failed"}), 500

# Import necessary modules
import typing as t
import re  # Added missing import for re.sub

from abc import ABC, abstractmethod
from pydantic import BaseModel as PydanticBaseModel
from pydantic import ConfigDict, alias_generators

from .enums import EntityType


class BaseModel(PydanticBaseModel):
    """Base Pydantic model with camelCase serialization for config files."""
    model_config = ConfigDict(
        alias_generator=alias_generators.to_camel,
        populate_by_name=True,
        extra='allow',
    )


class BaseEntity(ABC):
    @property
    @abstractmethod
    def entity_type(self) -> EntityType:
        pass

    @property
    @abstractmethod
    def entity_id(self) -> str:
        pass

    @property
    @abstractmethod
    def source_id(self) -> str:
        pass

    @property
    @abstractmethod
    def name(self) -> str:
        pass

    @property
    @abstractmethod
    def description(self) -> t.Optional[str]:
        pass

    def __str__(self):
        return f"{self.entity_type.value}={self.entity_id}({self.name})"

    def __repr__(self):
        return str(self)

    def get_file_name(self) -> str:
        # Sanitize entity_id to create a valid filename
        result = re.sub(r'\W+', '_', self.entity_id).lower()
        result = re.sub(r'(^_+)|(_+$)', '', result)
        return result

    # Below we implement __eq__ and __hash__ methods
    # to allow using any BaseEntity instances as dict keys and set items.
    def __eq__(self, other):
        if not isinstance(other, BaseEntity):
            return NotImplemented
        # Here, self and other could be different BaseEntity subclasses.
        # Thus we use both entity_id and entity_type to compare them.
        res = self.entity_id == other.entity_id and self.entity_type == other.entity_type
        return res

    def __hash__(self):
        return hash((self.entity_id, self.entity_type))

from dataclasses import fields
from miles.utils.types import Sample


def merge_samples(samples: list[Sample], tokenizer) -> Sample:
    acc = samples[0]
    for sample in samples[1:]:
        acc = _merge_sample_pair(acc, sample, tokenizer=tokenizer)
    return acc


def _merge_sample_pair(a: Sample, b: Sample, tokenizer) -> Sample:
    """Merge two samples generated from sibling inference engine calls."""
    a, b = deepcopy(a), deepcopy(b)

    def _merge_equal_value(field):
        x = getattr(a, field)
        y = getattr(b, field)
        assert x == y, f"{field} mismatch: a.{field}={x}, b.{field}={y}"
        return x

    def _fill_defaults(sample: Sample):
        if sample.loss_mask is None:
            sample.loss_mask = [1] * sample.response_length
        if sample.rollout_log_probs is None:
            sample.rollout_log_probs = [0.0] * sample.response_length

    _fill_defaults(a)
    _fill_defaults(b)

    obs_len = len(b.tokens) - len(a.tokens) - b.response_length
    obs_tokens = b.tokens[len(a.tokens): len(a.tokens) + obs_len]

    # TODO: is this acceptable?
    obs_text = tokenizer.decode(obs_tokens)

    try:
        a.validate()
        b.validate()

        assert _startswith(short=a.prompt, long=b.prompt), "b.prompt must start with a.prompt"
        assert _startswith(short=a.tokens, long=b.tokens), "b.tokens must start with a.tokens"
        assert obs_len > 0, f"obs_len must be > 0, got {obs_len}"

        if a.rollout_routed_experts is not None:
            assert a.rollout_routed_experts.shape[0] <= b.rollout_routed_experts.shape[0]

        assert a.status == Sample.Status.COMPLETED, f"a.status must be COMPLETED, got {a.status}"

        return _create_with_all_fields(
            Sample,
            group_index=_merge_equal_value("group_index"),
            index=_merge_equal_value("index"),
            prompt=b.prompt,
            tokens=b.tokens,
            multimodal_inputs=_merge_equal_value("multimodal_inputs"),
            multimodal_train_inputs=_merge_equal_value("multimodal_train_inputs"),
            response=a.response + obs_text + b.response,
            response_length=a.response_length + obs_len + b.response_length,
            label=_merge_equal_value("label"),
            reward=_merge_equal_value("reward"),
            loss_mask=a.loss_mask + [0] * obs_len + b.loss_mask,
            weight_versions=a.weight_versions + b.weight_versions,
            rollout_log_probs=a.rollout_log_probs + [0.0] * obs_len + b.rollout_log_probs,
            rollout_routed_experts=b.rollout_routed_experts,
            remove_sample=_merge_equal_value("remove_sample"),
            status=b.status,
            metadata=_merge_equal_value("metadata"),
            generate_function_path=_merge_equal_value("generate_function_path"),
            train_metadata=_merge_equal_value("train_metadata"),
            non_generation_time=_merge_equal_value("non_generation_time"),
            spec_info=_merge_spec_info(a.spec_info, b.spec_info),
            prefix_cache_info=_merge_prefix_cache_info(a.prefix_cache_info, b.prefix_cache_info),
        )
    except AssertionError as e:
        e.add_note(f"{a=} {b=}")
        raise


def _merge_spec_info(a: Sample.SpecInfo, b: Sample.SpecInfo) -> Sample.SpecInfo:
    def _merge_plus_value(field):
        return getattr(a, field) + getattr(b, field)

    return _create_with_all_fields(
        Sample.SpecInfo,
        spec_accept_token_num=_merge_plus_value("spec_accept_token_num"),
        spec_draft_token_num=_merge_plus_value("spec_draft_token_num"),
        spec_verify_ct=_merge_plus_value("spec_verify_ct"),
        completion_token_num=_merge_plus_value("completion_token_num"),
    )


def _merge_prefix_cache_info(a: Sample.PrefixCacheInfo, b: Sample.PrefixCacheInfo) -> Sample.PrefixCacheInfo:
    def _merge_plus_value(field):
        return getattr(a, field) + getattr(b, field)

    return _create_with_all_fields(
        Sample.PrefixCacheInfo,
        cached_tokens=_merge_plus_value("cached_tokens"),
        total_prompt_tokens=_merge_plus_value("total_prompt_tokens"),
    )


def _create_with_all_fields(cls, **kwargs):
    expected = {f.name for f in fields(cls)}
    actual = set(kwargs.keys())

    assert (
        expected == actual
    ), f"{cls.__name__} field mismatch. Missing: {expected - actual}, Extra: {actual - expected}"

    return cls(**kwargs)


def _startswith(*, short, long) -> bool:
    if isinstance(short, str) and isinstance(long, str):
        return long.startswith(short)
    if isinstance(short, list) and isinstance(long, list):
        return (len(long) >= len(short)) and (long[:len(short)] == short)
    raise NotImplementedError

# Smart Router State Compactor
import argparse
import json
import os
import time
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any

# Configuration
ROUTER_STATE_DIR = Path(os.environ.get(
    "ROUTER_STATE_DIR", 
    os.path.expanduser("~/.openclaw/router-state")
))
ROUTER_LOGS_DIR = Path(os.environ.get(
    "ROUTER_LOGS_DIR",
    os.path.expanduser("~/.openclaw/logs")
))

# Retention policies
CONFIG = {
    "circuit_breaker": {
        "max_age_hours": 1,           # Clear circuit state older than 1 hour
        "max_entries": 100,           # Keep max 100 circuit records
    },
    "routing_logs": {
        "max_age_days": 7,            # Compact logs older than 7 days
        "archive_after_days": 30,     # Archive logs older than 30 days
        "max_file_size_mb": 10,       # Rotate if file exceeds 10MB
    },
    "rate_limits": {
        "reset_window_hours": 24,     # Clear rate limit counters daily
    },
    "model_cache": {
        "max_age_minutes": 15,        # Refresh availability cache every 15 min
    },
}


class RouterCompactor:
    """Manages router state compaction and cleanup."""

    def __init__(self, dry_run: bool = False):
        self.dry_run = dry_run
        self.stats = {
            "circuit_breaker_cleaned": 0,
            "logs_compacted": 0,
            "logs_archived": 0,
            "rate_limits_reset": 0,
            "cache_entries_cleared": 0,
            "bytes_freed": 0,
        }

    def run_all(self) -> dict[str, Any]:
        """Run all compaction tasks."""
        self.compact_circuit_breaker()
        self.compact_routing_logs()
        self.reset_rate_limits()
        self.refresh_model_cache()
        return self.stats

    def compact_circuit_breaker(self) -> int:
        """
        Clean up stale circuit breaker state.

        Circuit breakers track model failures to prevent repeated calls to
        failing services. Old entries should be cleared to allow retry.
        """
        state_file = ROUTER_STATE_DIR / "circuit-breaker.json"

        if not state_file.exists():
            return 0

        try:
            with open(state_file, "r") as f:
                state = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        now = time.time()
        max_age_ms = CONFIG["circuit_breaker"]["max_age_hours"] * 3600 * 1000

        original_count = len(state.get("circuits", {}))

        # Filter out stale circuits
        active_circuits = {}
        for model, circuit in state.get("circuits", {}).items():
            last_failure = circuit.get("last_failure_ms", 0)
            if now * 1000 - last_failure < max_age_ms:
                active_circuits[model] = circuit
            else:
                self.stats["circuit_breaker_cleaned"] += 1

        # Enforce max entries (keep most recent)
        max_entries = CONFIG["circuit_breaker"]["max_entries"]
        if len(active_circuits) > max_entries:
            sorted_circuits = sorted(
                active_circuits.items(),
                key=lambda x: x[1].get("last_failure_ms", 0),
                reverse=True
            )
            active_circuits = dict(sorted_circuits[:max_entries])
            self.stats["circuit_breaker_cleaned"] += len(sorted_circuits) - max_entries

        if not self.dry_run and self.stats["circuit_breaker_cleaned"] > 0:
            state["circuits"] = active_circuits
            state["last_compaction"] = datetime.utcnow().isoformat()
            with open(state_file, "w") as f:
                json.dump(state, f, indent=2)

        return self.stats["circuit_breaker_cleaned"]

    def compact_routing_logs(self) -> tuple[int, int]:
        """
        Compact and archive routing decision logs.

        - Logs older than max_age_days: summarize to daily aggregates
        - Logs older than archive_after_days: move to archive
        - Large files: rotate
        """
        log_file = ROUTER_LOGS_DIR / "router-decisions.log"
        archive_dir = ROUTER_LOGS_DIR / "archive"

        if not log_file.exists():
            return 0, 0

        # Check file size
        file_size = log_file.stat().st_size
        max_size = CONFIG["routing_logs"]["max_file_size_mb"] * 1024 * 1024

        if file_size > max_size:
            self._rotate_log(log_file)

        # Read and parse log entries
        try:
            with open(log_file, "r") as f:
                lines = f.readlines()
        except IOError:
            return 0, 0

        now = datetime.utcnow()
        compact_threshold = now - timedelta(days=CONFIG["routing_logs"]["max_age_days"])
        archive_threshold = now - timedelta(days=CONFIG["routing_logs"]["archive_after_days"])

        kept_lines = []
        compacted_entries = []
        archived_entries = []

        for line in lines:
            try:
                entry = json.loads(line.strip())
                entry_time = datetime.fromisoformat(entry.get("timestamp", "").replace("Z", ""))

                if entry_time < archive_threshold:
                    archived_entries.append(entry)
                    self.stats["logs_archived"] += 1
                elif entry_time < compact_threshold:
                    compacted_entries.append(entry)
                    self.stats["logs_compacted"] += 1
                else:
                    kept_lines.append(line)
            except (json.JSONDecodeError, ValueError):
                kept_lines.append(line)  # Keep unparseable lines

        if not self.dry_run:
            # Write kept lines back
            if self.stats["logs_compacted"] > 0 or self.stats["logs_archived"] > 0:
                with open(log_file, "w") as f:
                    f.writelines(kept_lines)

            # Archive old entries
            if archived_entries:
                archive_dir.mkdir(parents=True, exist_ok=True)
                archive_file = archive_dir / f"router-decisions-{now.strftime('%Y%m')}.jsonl"
                with open(archive_file, "a") as f:
                    for entry in archived_entries:
                        f.write(json.dumps(entry) + "\n")

            # Write daily summaries for compacted entries
            if compacted_entries:
                self._write_daily_summaries(compacted_entries)

        self.stats["bytes_freed"] += file_size - (len("".join(kept_lines)))
        return self.stats["logs_compacted"], self.stats["logs_archived"]

    def _rotate_log(self, log_file: Path) -> None:
        """Rotate a log file by renaming with timestamp."""
        if self.dry_run:
            return

        timestamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        rotated = log_file.with_suffix(f".{timestamp}.log")
        log_file.rename(rotated)

    def _write_daily_summaries(self, entries: list[dict]) -> None:
        """Aggregate entries into daily summary files."""
        from collections import defaultdict

        daily_stats = defaultdict(lambda: {
            "total_requests": 0,
            "by_model": defaultdict(int),
            "by_intent": defaultdict(int),
            "fallbacks_triggered": 0,
        })

        for entry in entries:
            date = entry.get("timestamp", "")[:10]
            daily_stats[date]["total_requests"] += 1
            daily_stats[date]["by_model"][entry.get("model_used", "unknown")] += 1
            daily_stats[date]["by_intent"][entry.get("intent_detected", "unknown")] += 1
            if entry.get("fallback_triggered"):
                daily_stats[date]["fallbacks_triggered"] += 1

        summary_dir = ROUTER_LOGS_DIR / "summaries"
        summary_dir.mkdir(parents=True, exist_ok=True)

        for date, stats in daily_stats.items():
            summary_file = summary_dir / f"summary-{date}.json"
            # Merge with existing if present
            existing = {}
            if summary_file.exists():
                with open(summary_file, "r") as f:
                    existing = json.load(f)

            # Merge stats
            merged = {
                "date": date,
                "total_requests": existing.get("total_requests", 0) + stats["total_requests"],
                "by_model": {**existing.get("by_model", {}), **dict(stats["by_model"])},
                "by_intent": {**existing.get("by_intent", {}), **dict(stats["by_intent"])},
                "fallbacks_triggered": existing.get("fallbacks_triggered", 0) + stats["fallbacks_triggered"],
            }

            with open(summary_file, "w") as f:
                json.dump(merged, f, indent=2)

    def reset_rate_limits(self) -> int:
        """
        Reset expired rate limit counters.

        Rate limit state tracks per-user request counts. Old entries
        should be cleared to free memory and reset daily quotas.
        """
        state_file = ROUTER_STATE_DIR / "rate-limits.json"

        if not state_file.exists():
            return 0

        try:
            with open(state_file, "r") as f:
                state = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        now = time.time()
        window_seconds = CONFIG["rate_limits"]["reset_window_hours"] * 3600

        # Clear expired user entries
        active_users = {}
        for user_id, user_state in state.get("users", {}).items():
            last_request = user_state.get("last_request", 0)
            if now - last_request < window_seconds:
                # Filter out old timestamps from request lists
                user_state["requests"] = [
                    t for t in user_state.get("requests", [])
                    if now - t < 3600  # Keep last hour
                ]
                user_state["premium_requests"] = [
                    t for t in user_state.get("premium_requests", [])
                    if now - t < 3600
                ]
                active_users[user_id] = user_state
            else:
                self.stats["rate_limits_reset"] += 1

        if not self.dry_run and self.stats["rate_limits_reset"] > 0:
            state["users"] = active_users
            state["last_cleanup"] = datetime.utcnow().isoformat()
            with open(state_file, "w") as f:
                json.dump(state, f, indent=2)

        return self.stats["rate_limits_reset"]

    def refresh_model_cache(self) -> int:
        """
        Clear stale model availability cache entries.

        The router caches model availability to avoid repeated API checks.
        Stale cache can cause incorrect routing decisions.
        """
        cache_file = ROUTER_STATE_DIR / "model-availability.json"

        if not cache_file.exists():
            return 0

        try:
            with open(cache_file, "r") as f:
                cache = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        now = time.time()
        max_age_seconds = CONFIG["model_cache"]["max_age_minutes"] * 60

        active_entries = {}
        for model, entry in cache.get("models", {}).items():
            checked_at = entry.get("checked_at", 0)
            if now - checked_at < max_age_seconds:
                active_entries[model] = entry
            else:
                self.stats["cache_entries_cleared"] += 1

        if not self.dry_run and self.stats["cache_entries_cleared"] > 0:
            cache["models"] = active_entries
            cache["last_refresh"] = datetime.utcnow().isoformat()
            with open(cache_file, "w") as f:
                json.dump(cache, f, indent=2)

        return self.stats["cache_entries_cleared"]

    def get_status(self) -> dict[str, Any]:
        """Get current state of all router components."""
        status = {
            "state_dir": str(ROUTER_STATE_DIR),
            "logs_dir": str(ROUTER_LOGS_DIR),
            "components": {},
        }

        # Circuit breaker status
        cb_file = ROUTER_STATE_DIR / "circuit-breaker.json"
        if cb_file.exists():
            try:
                with open(cb_file, "r") as f:
                    cb_state = json.load(f)
                open_circuits = sum(
                    1 for c in cb_state.get("circuits", {}).values()
                    if c.get("state") == "open"
                )
                status["components"]["circuit_breaker"] = {
                    "total_circuits": len(cb_state.get("circuits", {})),
                    "open_circuits": open_circuits,
                    "last_compaction": cb_state.get("last_compaction"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["circuit_breaker"] = {"error": "Failed to read state"}
        else:
            status["components"]["circuit_breaker"] = {"status": "no state file"}

        # Rate limits status
        rl_file = ROUTER_STATE_DIR / "rate-limits.json"
        if rl_file.exists():
            try:
                with open(rl_file, "r") as f:
                    rl_state = json.load(f)
                status["components"]["rate_limits"] = {
                    "active_users": len(rl_state.get("users", {})),
                    "last_cleanup": rl_state.get("last_cleanup"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["rate_limits"] = {"error": "Failed to read state"}
        else:
            status["components"]["rate_limits"] = {"status": "no state file"}

        # Logs status
        log_file = ROUTER_LOGS_DIR / "router-decisions.log"
        if log_file.exists():
            file_size = log_file.stat().st_size
            status["components"]["routing_logs"] = {
                "file_size_kb": round(file_size / 1024, 2),
                "max_size_mb": CONFIG["routing_logs"]["max_file_size_mb"],
                "needs_rotation": file_size > CONFIG["routing_logs"]["max_file_size_mb"] * 1024 * 1024,
            }
        else:
            status["components"]["routing_logs"] = {"status": "no log file"}

        # Model cache status
        cache_file = ROUTER_STATE_DIR / "model-availability.json"
        if cache_file.exists():
            try:
                with open(cache_file, "r") as f:
                    cache = json.load(f)
                status["components"]["model_cache"] = {
                    "cached_models": len(cache.get("models", {})),
                    "last_refresh": cache.get("last_refresh"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["model_cache"] = {"error": "Failed to read cache"}
        else:
            status["components"]["model_cache"] = {"status": "no cache file"}

        return status


def main():
    parser = argparse.ArgumentParser(
        description="Smart Router State Compactor",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
    python compactor.py --status           # Show current state
    python compactor.py --all              # Run all compaction tasks
    python compactor.py --dry-run --all    # Preview changes without applying
    python compactor.py --circuit-breaker  # Clean circuit breaker only
    python compactor.py --logs             # Compact routing logs only
        """
    )

    parser.add_argument("--all", action="store_true", help="Run all compaction tasks")
    parser.add_argument("--circuit-breaker", action="store_true", help="Clean circuit breaker state")
    parser.add_argument("--logs", action="store_true", help="Compact routing logs")
    parser.add_argument("--rate-limits", action="store_true", help="Reset rate limit counters")
    parser.add_argument("--cache", action="store_true", help="Refresh model cache")
    parser.add_argument("--status", action="store_true", help="Show current state")
    parser.add_argument("--dry-run", action="store_true", help="Preview changes without applying")
    parser.add_argument("--json", action="store_true", help="Output as JSON")

    args = parser.parse_args()

    compactor = RouterCompactor(dry_run=args.dry_run)

    if args.status:
        status = compactor.get_status()
        if args.json:
            print(json.dumps(status, indent=2))
        else:
            print("Smart Router State Status")
            print("=" * 50)
            print(f"State directory: {status['state_dir']}")
            print(f"Logs directory:  {status['logs_dir']}")
            print()
            for component, info in status["components"].items():
                print(f"[{component}]")
                for key, value in info.items():
                    print(f"  {key}: {value}")
                print()
        return

    # Run requested tasks
    if args.all:
        compactor.run_all()
    else:
        if args.circuit_breaker:
            compactor.compact_circuit_breaker()
        if args.logs:
            compactor.compact_routing_logs()
        if args.rate_limits:
            compactor.reset_rate_limits()
        if args.cache:
            compactor.refresh_model_cache()

    # Output results
    if args.json:
        print(json.dumps(compactor.stats, indent=2))
    else:
        prefix = "[DRY RUN] " if args.dry_run else ""
        print(f"{prefix}Compaction complete:")
        print(f"  Circuit breaker entries cleaned: {compactor.stats['circuit_breaker_cleaned']}")
        print(f"  Log entries compacted:           {compactor.stats['logs_compacted']}")
        print(f"  Log entries archived:            {compactor.stats['logs_archived']}")
        print(f"  Rate limit counters reset:       {compactor.stats['rate_limits_reset']}")
        print(f"  Cache entries cleared:           {compactor.stats['cache_entries_cleared']}")
        if compactor.stats['bytes_freed'] > 0:
            print(f"  Bytes freed:                     {compactor.stats['bytes_freed']:,}")


if __name__ == "__main__":
    main()

