# https://stackoverflow.com/questions/33139531/preserve-empty-lines-with-nltks-punkt-tokenizer
class CustomLanguageVars(PunktLanguageVars):
    _period_context_fmt = r"""
        \S*                          # some word material
        %(SentEndChars)s             # a potential sentence ending
        \s*                       #  <-- THIS is what I changed
        (?=(?P<after_tok>
            %(NonWord)s              # either other punctuation
            |
            (?P<next_tok>\S+)     #  <-- Normally you would have \s+ here
        ))"""


class IdentitySplitter(object):
    def tokenize(self, *text):
        return text


def parquet_row_iterator(file_path, text_column, batch_size=10000):
    """Iterate over parquet file rows, yielding JSON-like strings for each row."""
    parquet_file = pq.ParquetFile(file_path)
    for batch in parquet_file.iter_batches(batch_size=batch_size, columns=[text_column]):
        for text_value in batch.column(text_column):
            # Convert to Python string and yield as JSON line
            yield json.dumps({"text": text_value.as_py()})


class Encoder(object):
    def __init__(self, args):
        self.args = args

    def initializer(self):
        # Use Encoder class as a container for global data
        Encoder.tokenizer = AutoTokenizer.from_pretrained(
            self.args.pretrained_model_name_or_path
        )
        if self.args.split_sentences:
            if not nltk_available:
                print("NLTK is not available to split sentences.")
                exit()
            if os.environ.get("NLTK_DATA"):
                library = os.path.join(
                    os.environ.get("NLTK_DATA"), "tokenizers", "punkt", f"{self.args.lang}.pickle"
                )
                url = f"file:{library}"
            else:
                library = os.path.join("tokenizers", "punkt", f"{self.args.lang}.pickle")
                url = f"nltk:{library}"
            splitter = nltk.load(url)
            if self.args.keep_newlines:
                # this prevents punkt from eating newlines after sentences
                Encoder.splitter = nltk.tokenize.punkt.PunktSentenceTokenizer(
                    train_text=splitter._params, lang_vars=CustomLanguageVars()
                )
            else:
                Encoder.splitter = splitter
        else:
            Encoder.splitter = IdentitySplitter()

    def split(self, json_line):
        data = json.loads(json_line)
        output = {}
        for key in self.args.json_keys:
            text = data[key]
            max_len = 1000000
            tokens_list = [
                Encoder.splitter.tokenize(text[i : i + max_len])
                for i in range(0, len(text), max_len)
            ]
            output[key] = [tokens for partial in tokens_list for tokens in partial]
        return json.dumps(output), len(json_line)

    def encode(self, json_line):
        data = json.loads(json_line)
        ids = {}
        lens = {}
        for key in self.args.json_keys:
            text = data[key]
            if isinstance(text, list):
                sentences = text
            else:
                sentences = [text]
            doc_ids = []
            sentence_lens = []
            for sentence in sentences:
                sentence_ids = Encoder.tokenizer(sentence).input_ids
                if len(sentence_ids) > 0:
                    doc_ids.extend(sentence_ids)
                    sentence_lens.append(len(sentence_ids))
            if len(doc_ids) > 0 and self.args.append_eod:
                doc_ids.append(Encoder.tokenizer.eos_token_id)
                sentence_lens[-1] += 1
            ids[key] = doc_ids
            lens[key] = sentence_lens
        return ids, lens, len(json_line)


class Partition(object):
    def __init__(self, args, workers):
        self.args = args
        self.workers = workers

    def print_processing_stats(self, count, proc_start, total_bytes_processed, source=None):
        if count % self.args.log_interval == 0:
            current = time.time()
            elapsed = current - proc_start
            mbs = total_bytes_processed / elapsed / 1024 / 1024
            source_msg = f" in {os.path.basename(source)}" if source else ""
            print(
                f"Processed {count} documents{source_msg}",
                f"({count / elapsed} docs/s, {mbs} MB/s).",
                file=sys.stderr,
            )

    def split_sentences(self, file_name):
        input_file_name, output_file_name = file_name
        print("Opening", input_file_name)
        fin = open(input_file_name, "r", encoding="utf-8")
        fout = open(output_file_name, "w")
        encoder = Encoder(self.args)
        pool = multiprocessing.Pool(self.workers, initializer=encoder.initializer)
        split_docs = pool.imap(encoder.split, fin, 32)
        proc_start = time.time()
        total_bytes_processed = 0
        for i, (doc, bytes_processed) in enumerate(split_docs, start=1):
            total_bytes_processed += bytes_processed
            fout.write(doc + "\n")
            self.print_processing_stats(i, proc_start, total_bytes_processed, source=input_file_name)
        fin.close()
        fout.close()

    def process_json_file(self, file_name):
        input_file_name, output_prefix = file_name
        print("Opening", input_file_name)
        fin = open(input_file_name, "r", encoding="utf-8")
        startup_start = time.time()
        encoder = Encoder(self.args)
        tokenizer = AutoTokenizer.from_pretrained(self.args.pretrained_model_name_or_path)
        pool = multiprocessing.Pool(self.workers, initializer=encoder.initializer)
        encoded_docs = pool.imap(encoder.encode, fin, 32)
        level = "document"
        if self.args.split_sentences:
            level = "sentence"
        output_bin_files = {}
        output_idx_files = {}
        builders = {}
        for key in self.args.json_keys:
            output_bin_files[key] = "{}_{}_{}.bin".format(output_prefix, key, level)
            output_idx_files[key] = "{}_{}_{}.idx".format(output_prefix, key, level)
            builders[key] = indexed_dataset.IndexedDatasetBuilder(
                output_bin_files[key],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )
        startup_end = time.time()
        proc_start = time.time()
        total_bytes_processed = 0
        print("Time to startup:", startup_end - startup_start)
        for i, (doc, sentence_lens, bytes_processed) in enumerate(encoded_docs, start=1):
            total_bytes_processed += bytes_processed
            for key in doc.keys():
                builders[key].add_document(doc[key], sentence_lens[key])
            self.print_processing_stats(i, proc_start, total_bytes_processed, source=input_file_name)
        fin.close()
        builders[key].finalize(output_idx_files[key])

    def process_parquet_file(self, file_name):
        input_file_name, output_prefix = file_name
        print("Opening parquet file:", input_file_name)
        startup_start = time.time()
        encoder = Encoder(self.args)
        tokenizer = AutoTokenizer.from_pretrained(self.args.pretrained_model_name_or_path)
        pool = multiprocessing.Pool(self.workers, initializer=encoder.initializer)
        # Create iterator over parquet rows
        row_iterator = parquet_row_iterator(
            input_file_name, self.args.text_column, batch_size=self.args.parquet_batch_size
        )
        encoded_docs = pool.imap(encoder.encode, row_iterator, 32)
        level = "document"
        if self.args.split_sentences:
            level = "sentence"
        output_bin_files = {}
        output_idx_files = {}
        builders = {}
        for key in self.args.json_keys:
            output_bin_files[key] = "{}_{}_{}.bin".format(output_prefix, key, level)
            output_idx_files[key] = "{}_{}_{}.idx".format(output_prefix, key, level)
            builders[key] = indexed_dataset.IndexedDatasetBuilder(
                output_bin_files[key],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )
        startup_end = time.time()
        proc_start = time.time()
        total_bytes_processed = 0
        print("Time to startup:", startup_end - startup_start)
        for i, (doc, sentence_lens, bytes_processed) in enumerate(encoded_docs, start=1):
            total_bytes_processed += bytes_processed
            for key in doc.keys():
                builders[key].add_document(doc[key], sentence_lens[key])
            self.print_processing_stats(i, proc_start, total_bytes_processed, source=input_file_name)
        pool.close()
        pool.join()
        builders[key].finalize(output_idx_files[key])


def get_args():
    parser = argparse.ArgumentParser()
    group = parser.add_argument_group(title="input data")
    group.add_argument("--input", type=str, required=True, help="Path to input JSON or Parquet file(s)")
    group.add_argument(
        "--json-keys", nargs="+", default=["text"], help="space separate listed of keys to extract from json"
    )
    group.add_argument(
        "--input-type",
        type=str,
        choices=["json", "parquet", "auto"],
        default="auto",
        help="Input file type. 'auto' detects from file extension (default: auto)",
    )
    group.add_argument(
        "--text-column",
        type=str,
        default="text",
        help="Column name containing text data in parquet files (default: text)",
    )
    group.add_argument(
        "--parquet-batch-size",
        type=int,
        default=10000,
        help="Batch size for reading parquet files (default: 10000)",
    )
    group.add_argument("--split-sentences", action="store_true", help="Split documents into sentences.")
    group.add_argument("--keep-newlines", action="store_true", help="Keep newlines between sentences when splitting.")
    group = parser.add_argument_group(title="tokenization process")
    group.add_argument("--append-eod", action="store_true", help="Append an <eod> token to the end of a document.")
    group.add_argument(
        "--lang", type=str, default="english", help="Language to use for NLTK-powered sentence splitting."
    )
    group = parser.add_argument_group(title="output data")
    group.add_argument("--output-prefix", type=str, required=True, help="Path to binary output file without suffix")
    group.add_argument(
        "--output-path",
        type=str,
        default=None,
        help=(
            "Directory to write outputs. If provided, this directory "
            "will be created if missing and used for all generated files. "
            "Overrides any directory component in --output-prefix."
        ),
    )
    group = parser.add_argument_group(title="runtime")
    group.add_argument(
        "--workers",
        type=int,
        required=True,
        help=("Number of worker processes to launch. Workers are divided across matched input files."),
    )
    group.add_argument("--log-interval", type=int, default=1000, help="Interval between progress updates")
    group.add_argument("--pretrained-model-name-or-path", type=str, required=True, help="Pretrained model name or path")
    args = parser.parse_args()
    return args


def detect_file_type(file_path):
    """Detect file type based on extension."""
    ext = os.path.splitext(file_path)[1].lower()
    if ext in [".parquet", ".pq"]:
        return "parquet"
    elif ext in [".json", ".jsonl"]:
        return "json"
    else:
        # Default to json for unknown extensions
        return "json"


def check_files_exist(in_ss_out_names, key, num_items):
    for i in range(num_items):
        if not os.path.exists(in_ss_out_names[i][key]):
            return False
    return True


def main():
    args = get_args()
    if args.split_sentences:
        if nltk_available:
            nltk.download("punkt", quiet=True, download_dir=os.environ.get("NLTK_DATA"))
        else:
            raise Exception("nltk library required for sentence splitting is not available.")

    # Ensure output directory exists if specified
    if args.output_path:
        os.makedirs(args.output_path, exist_ok=True)

    if glob.has_magic(args.input):
        in_file_names = glob.glob(args.input)
    else:
        in_file_names = [args.input]

    if len(in_file_names) == 0:
        print(f"No files matched input pattern: {args.input}")
        return

    # Determine file type
    if args.input_type == "auto":
        # Use the first file to detect type
        file_type = detect_file_type(in_file_names[0])
    else:
        file_type = args.input_type

    # Check parquet availability if needed
    if file_type == "parquet" and not parquet_available:
        raise Exception(
            "pyarrow library is required for parquet files but is not available. Install with: pip install pyarrow"
        )

    # For parquet files, sentence splitting is not supported (text is already in a single column)
    if file_type == "parquet" and args.split_sentences:
        print("Warning: Sentence splitting for parquet files is not currently supported. Ignoring --split-sentences.")
        args.split_sentences = False

    workers_per_file = max(1, args.workers // len(in_file_names))
    partition = Partition(args, workers_per_file)

    in_ss_out_names = []
    for idx, in_file in enumerate(in_file_names):
        file_name, extension = os.path.splitext(in_file)
        # Route intermediate and final outputs to the specified output path if provided
        if args.output_path:
            base_name = os.path.basename(file_name)
            sentence_split_file = os.path.join(args.output_path, base_name + "_ss" + extension)
            output_prefix = os.path.join(args.output_path, f"{os.path.basename(args.output_prefix)}_{idx}")
        else:
            sentence_split_file = file_name + "_ss" + extension
            output_prefix = f"{args.output_prefix}_{idx}"

        in_ss_out_names.append(
            {"partition": in_file, "sentence_split": sentence_split_file, "output_prefix": output_prefix}
        )

    if file_type == "json":
        # Optional sentence splitting per file (JSON only)
        split_sentences_present = check_files_exist(in_ss_out_names, "sentence_split", len(in_ss_out_names))
        if args.split_sentences and not split_sentences_present:
            processes = []
            for name in in_ss_out_names:
                p = multiprocessing.Process(
                    target=partition.split_sentences, args=((name["partition"], name["sentence_split"]),)
                )
                p.start()
                processes.append(p)
            for p in processes:
                p.join()

        # Encode each file independently
        processes = []
        input_key = "sentence_split" if args.split_sentences else "partition"
        for name in in_ss_out_names:
            p = multiprocessing.Process(
                target=partition.process_json_file, args=((name[input_key], name["output_prefix"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()
    else:
        # Parquet processing
        processes = []
        for name in in_ss_out_names:
            p = multiprocessing.Process(
                target=partition.process_parquet_file, args=((name["partition"], name["output_prefix"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()

    return


if __name__ == "__main__":
    main()

# Animation manager implementation for Isaac Lab
from __future__ import annotations

import torch
from prettytable import PrettyTable
from typing import TYPE_CHECKING
from collections.abc import Sequence

import isaaclab.sim as sim_utils
import isaaclab.utils.math as math_utils
from isaaclab.assets import Articulation
from isaaclab.managers import ManagerBase, ManagerTermBase
from isaaclab.markers import VisualizationMarkers, VisualizationMarkersCfg

from .animation_manager_cfg import AnimationTermCfg
from .motion_data_manager import MotionDataTerm

if TYPE_CHECKING:
    from robolab.tasks.manager_based.amp.animation_env import AnimationEnv


class AnimationTerm(ManagerTermBase):
    cfg: AnimationTermCfg
    _env: AnimationEnv

    def __init__(self, cfg: AnimationTermCfg, env: AnimationEnv):
        super().__init__(cfg, env)

        # Setup step indices based on configuration
        if cfg.num_steps_to_use > 0:
            self.step_indices = torch.arange(0, cfg.num_steps_to_use, dtype=torch.long, device=env.device)
        elif cfg.num_steps_to_use < 0:
            self.step_indices = torch.arange(cfg.num_steps_to_use + 1, 1, dtype=torch.long, device=env.device)
        else:
            raise ValueError("num_steps_to_use cannot be zero.")

        # Get motion data term reference
        self.motion_data_term: MotionDataTerm = env.motion_data_manager.get_term(cfg.motion_data_term)

        # Create buffers for different motion components
        self.num_steps = len(self.step_indices)
        for component in cfg.motion_data_components:
            buffer_shape = (self.num_envs, self.num_steps)

            # Adjust buffer shape based on component type
            if component in ["root_pos_w", "root_vel_w", "root_vel_b", "root_ang_vel_w", "root_ang_vel_b"]:
                buffer_shape += (3,)
            elif component == "root_quat":
                buffer_shape += (4,)
            elif component in ["dof_pos", "dof_vel"]:
                num_dofs = self.motion_data_term.num_dofs
                buffer_shape += (num_dofs,)
            elif component == "key_body_pos_b":
                num_key_bodies = self.motion_data_term.num_key_bodies
                buffer_shape += (num_key_bodies, 3)
            else:
                raise ValueError(f"Unknown motion data component: {component}")

            setattr(self, f"{component}_buffer", 
                    torch.zeros(buffer_shape, device=env.device, dtype=torch.float32))

        # Initialize motion tracking buffers
        self.motion_ids = torch.zeros(self.num_envs, device=env.device, dtype=torch.long)
        self.motion_fetch_time = torch.zeros((self.num_envs, self.num_steps), device=env.device, dtype=torch.float32)
        self.motion_durations = torch.zeros(self.num_envs, device=env.device, dtype=torch.float32)

        # Initial setup
        self.reset(torch.arange(self.num_envs))
        self._fetch_motion_data()

        # Visualization setup
        if self.cfg.enable_visualization:
            self.vis_root_offset = torch.tensor(self.cfg.vis_root_offset, device=env.device, dtype=torch.float32).unsqueeze(0)

            marker_cfg = VisualizationMarkersCfg(
                prim_path="/Visuals/KeyBodyVisualizerFromTerm",
                markers={
                    "red_sphere": sim_utils.SphereCfg(
                        radius=0.03, 
                        visual_material=sim_utils.PreviewSurfaceCfg(diffuse_color=(1.0, 0.0, 0.0))
                    ),
                }
            )
            self.key_body_marker: VisualizationMarkers = VisualizationMarkers(marker_cfg)

    def reset(self, env_ids: Sequence[int] | None = None):
        if env_ids is None:
            return

        # Resample motion IDs for reset environments
        self.motion_ids[env_ids] = self.motion_data_term.sample_motions(len(env_ids))
        self.motion_durations[env_ids] = self.motion_data_term.get_motion_durations(self.motion_ids[env_ids])

        truncate_time = self.num_steps * self._env.step_dt

        if self.cfg.random_initialize:
            # Random start time
            if self.cfg.num_steps_to_use > 0:
                self.motion_fetch_time[env_ids, 0] = self.motion_data_term.sample_times(
                    self.motion_ids[env_ids], 
                    truncate_time_end=truncate_time
                )
            else:
                self.motion_fetch_time[env_ids, 0] = self.motion_data_term.sample_times(
                    self.motion_ids[env_ids], 
                    truncate_time_start=truncate_time
                )
        else:
            # Start from beginning
            self.motion_fetch_time[env_ids, 0] = 0.0

        # Calculate subsequent fetch times
        if self.num_steps > 1:
            self.motion_fetch_time[env_ids, 1:] = (
                self.motion_fetch_time[env_ids, 0:1] + 
                self.step_indices[1:].float() * self._env.step_dt
            )

        self._fetch_motion_data(env_ids)

    def update(self, dt: float):
        if self.cfg.random_fetch:
            if self.cfg.num_steps_to_use > 0:
                self.motion_fetch_time[:, 0] = self.motion_data_term.sample_times(
                    self.motion_ids, 
                    truncate_time_end=self.num_steps * dt
                )
            else: 
                self.motion_fetch_time[:, 0] = self.motion_data_term.sample_times(
                    self.motion_ids, 
                    truncate_time_start=self.num_steps * dt
                )

            if self.num_steps > 1:
                self.motion_fetch_time[:, 1:] = (
                    self.motion_fetch_time[:, 0:1] + 
                    self.step_indices[1:].float() * dt
                )

        self._fetch_motion_data()

        # Advance time only when not randomly fetching
        if not self.cfg.random_fetch:
            self.motion_fetch_time += dt

        if self.cfg.enable_visualization:
            self._visualize()

    def _fetch_motion_data(self, env_ids: Sequence[int] | None = None):
        if env_ids is None:
            env_ids = torch.arange(self.num_envs, device=self._env.device)

        # Flatten for batch processing
        num_queries = len(env_ids) * self.num_steps
        motion_times_flat = self.motion_fetch_time[env_ids].reshape(-1)
        motion_ids_flat = self.motion_ids[env_ids].repeat_interleave(self.num_steps)

        # Sanity check
        assert motion_times_flat.shape[0] == num_queries
        assert motion_ids_flat.shape[0] == num_queries

        # Fetch motion data
        motion_data_dict = self.motion_data_term.get_motion_state(
            motion_ids=motion_ids_flat,
            motion_times=motion_times_flat
        )

        # Reshape and store in buffers
        for component in self.cfg.motion_data_components:
            if component in motion_data_dict:
                buffer_name = f"{component}_buffer"
                data = motion_data_dict[component]
                # Reshape: (num_envs * num_steps, *) -> (num_envs, num_steps, *)
                data_reshaped = data.view(len(env_ids), self.num_steps, *data.shape[1:])
                getattr(self, buffer_name)[env_ids, :, :] = data_reshaped

    def _visualize(self):
        # Try to get the 'robot_anim' articulation
        robot_anim: Articulation = self._env.scene["robot_anim"]
        if robot_anim is None:
            print("[WARNING] AnimationTerm visualization: 'robot_anim' not found in the scene.")
            return

        # Check if necessary buffers are available
        if not hasattr(self, "root_pos_w_buffer") or not hasattr(self, "root_quat_buffer") or not hasattr(self, "dof_pos_buffer"):
            print("[WARNING] AnimationTerm visualization: required buffers not found.")
            return

        root_pos_w = self.root_pos_w_buffer[:, 0, :]      # (num_envs, 3)
        root_quat = self.root_quat_buffer[:, 0, :]        # (num_envs, 4)
        dof_pos = self.dof_pos_buffer[:, 0, :]            # (num_envs, num_dofs)

        # Set root state
        root_states = robot_anim.data.default_root_state.clone()
        root_states[:, :3] = root_pos_w + self._env.scene.env_origins[:, :3] + self.vis_root_offset
        root_states[:, 3:7] = root_quat
        root_states[:, 7:10] = 0.0  # zero linear velocity
        root_states[:, 10:13] = 0.0  # zero angular velocity
        robot_anim.write_root_state_to_sim(root_states)

        # Set joint positions
        joint_pos = robot_anim.data.default_joint_pos.clone()
        joint_pos[:, :] = dof_pos
        joint_vel = torch.zeros_like(robot_anim.data.default_joint_vel)
        robot_anim.write_joint_state_to_sim(joint_pos, joint_vel)

        # Visualize key body positions
        key_body_pos_b = self.key_body_pos_b_buffer[:, 0, :, :]  # (num_envs, num_key_bodies, 3)
        num_key_bodies = key_body_pos_b.shape[1]
        key_body_pos_w = root_states[:, :3].unsqueeze(1) + math_utils.quat_apply(
            root_quat.unsqueeze(1).expand(-1, num_key_bodies, -1),
            key_body_pos_b
        )
        self.key_body_marker.visualize(
            translations=key_body_pos_w.reshape(-1, 3)
        )

    # Helper methods to access motion data
    def get_root_pos_w(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_pos_w_buffer"):
            raise AttributeError("root_pos_w_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_pos_w_buffer
        return self.root_pos_w_buffer[env_ids, :, :]

    def get_root_quat(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_quat_buffer"):
            raise AttributeError("root_quat_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_quat_buffer
        return self.root_quat_buffer[env_ids, :, :]

    def get_dof_pos(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "dof_pos_buffer"):
            raise AttributeError("dof_pos_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.dof_pos_buffer
        return self.dof_pos_buffer[env_ids, :, :]

    def get_dof_vel(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "dof_vel_buffer"):
            raise AttributeError("dof_vel_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.dof_vel_buffer
        return self.dof_vel_buffer[env_ids, :, :]

    def get_key_body_pos_b(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "key_body_pos_b_buffer"):
            raise AttributeError("key_body_pos_b_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.key_body_pos_b_buffer
        return self.key_body_pos_b_buffer[env_ids, :, :]

    def get_root_vel_w(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_vel_w_buffer"):
            raise AttributeError("root_vel_w_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_vel_w_buffer
        return self.root_vel_w_buffer[env_ids, :, :]

    def get_root_ang_vel_w(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_ang_vel_w_buffer"):
            raise AttributeError("root_ang_vel_w_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_ang_vel_w_buffer
        return self.root_ang_vel_w_buffer[env_ids, :, :]


class AnimationManager(ManagerBase):

    def __init__(self, cfg: object, env: AnimationEnv):
        if cfg is None:
            raise ValueError("AnimationManager configuration is required.")

        self._terms: dict[str, AnimationTerm] = {}
        self._term_cfgs: dict[str, AnimationTermCfg] = {}

        super().__init__(cfg, env)

    def __str__(self) -> str:
        """Returns: A string representation for animation data manager."""
        msg = f"<AnimationManager> contains {len(self._terms)} active terms.\n"

        # Create table for term information
        table = PrettyTable()
        table.title = "Animation Manager Terms"
        table.field_names = ["Index", "Term Name", "Motion Data Term", "Num Steps to Use", "Random Init", "Random Fetch"]
        for index, (term_name, term_cfg) in enumerate(self._term_cfgs.items()):
            table.add_row([
                index, 
                term_name,
                term_cfg.motion_data_term,
                term_cfg.num_steps_to_use,
                term_cfg.random_initialize,
                term_cfg.random_fetch
            ])
        msg += table.get_string()
        msg += "\n"

        return msg

    def update(self, dt: float):
        """Update all animation terms.
        Args:
            dt: The time step to update the animation terms.
        """
        for term in self._terms.values():
            term.update(dt)

    def reset(self, env_ids: Sequence[int] | None = None) -> dict[str, torch.Tensor]:
        if env_ids is None:
            return {}
        # Reset all terms
        for term in self._terms.values():
            term.reset(env_ids)
        return {}

    """
    Properties.
    """
    @property
    def active_terms(self) -> list[str]:
        """Name of active command terms."""
        return list(self._terms.keys())

    def get_term(self, term_name: str) -> AnimationTerm:
        """Get the animation data term by name."""
        if term_name not in self._terms:
            raise KeyError(f"Animation data term '{term_name}' not found.")
        return self._terms[term_name]

    """
    Helper functions.
    """
    def _prepare_terms(self):
        # Check if config is dict already
        if isinstance(self.cfg, dict):
            cfg_items = self.cfg.items()
        else:
            cfg_items = self.cfg.__dict__.items()

        # Iterate over all the terms
        for term_name, term_cfg in cfg_items:
            # Skip non-config entries
            if term_cfg is None:
                continue

            # Validate config type
            if not isinstance(term_cfg, AnimationTermCfg):
                raise TypeError(
                    f"Configuration for the term '{term_name}' is not of type AnimationTermCfg."
                    f" Received: '{type(term_cfg)}'."
                )

            # Create the action term
            term = AnimationTerm(term_cfg, self._env)

            # Add class to dict
            self._terms[term_name] = term
            self._term_cfgs[term_name] = term_cfg

