                "Install it with: pip install openai-agents[dapr]"
            ) from e

    raise AttributeError(f"module {__name__} has no attribute {name}")

import concurrent.futures
import os
import time
from typing import Dict, List, Optional, Set, Tuple

# Import local modules
from .common import log, progress, sha1_hex, get_proxy_connection_hash, get_v2rayn_connection_key
from .constants import (
    AVAILABLE_FILE,
    PING_WORKERS,
    ENABLE_STAGE2,
    ENABLE_STAGE3,
    STAGE3_MAX,
    STAGE3_WORKERS,
    EXISTING_PROXY_FAILURE_LIMIT,
)
from .grouping import write_grouped_outputs
from .io_ops import (
    ensure_dirs,
    load_streaks,
    read_lines,
    save_streaks,
