def wrap_with_sync(func, device):
    """Wrap function to include CUDA synchronization if needed."""
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        if device == "cuda":
            torch.cuda.synchronize()
        return result
    return wrapper


