def get_packed_modules_mapping(model_type: str) -> dict[str, list[str]]:
    """Get packed modules mapping for a model type.

    Args:
        model_type: The model type string (e.g., "deepseek_v3").

    Returns:
        Dictionary mapping fused module names to their component module names.
        Returns empty dict if model_type is not found.
    """
    return packed_modules_model_mapping.get(model_type, {})


def get_prefix_mapping(model_type: str) -> dict[str, str]:
    """Get prefix mapping for a model type.

    Args:
        model_type: The model type string (e.g., "qwen3_vl_moe").

    Returns:
        Dictionary mapping original prefixes to new prefixes.
        Returns empty dict if model_type is not found.
    """
    return QUANT_MODEL_PREFIX_MAPPINGS.get(model_type, {})


def get_linear_quant_type(
    quant_description: dict[str, Any], prefix: str, packed_modules_mapping: dict[str, Any]
) -> str | None:
    """Determine the quantization type for a linear layer.

    Args:
        quant_description: The quantization description dictionary.
        prefix: The layer prefix.
        packed_modules_mapping: Mapping for packed/fused modules.

    Returns:
        The quantization type string (e.g., "W8A8_DYNAMIC").
    """
    proj_name = prefix.split(".")[-1]

    if proj_name in packed_modules_mapping:
        quant_type = None
        shard_prefixes = [
            prefix.replace(proj_name, shard_proj_name) for shard_proj_name in packed_modules_mapping[proj_name]
        ]
        for shard_prefix in shard_prefixes:
            shard_quant_type = quant_description[shard_prefix + ".weight"]
            if quant_type is None:
                quant_type = shard_quant_type
            elif shard_quant_type != quant_type:
                raise ValueError(
                    f"Not all shards of {prefix} are quantized with same quant type."
                    f"Shard {proj_name} uses {shard_quant_type}, but another shard"
                    f"use {quant_type}. Please check quantization config."
                )
    else:
        quant_type = quant_description[prefix + ".weight"]

    return quant_type


def get_quant_type_for_layer(
    quant_description: dict[str, Any],
    prefix: str,
    layer_type: str,
    packed_modules_mapping: dict[str, Any] | None = None,
) -> str | None:
    """Determine the quantization type for a layer.

    Args:
        quant_description: The quantization description dictionary.
        prefix: The layer prefix.
        layer_type: The type of layer ("linear", "moe", "attention").
        packed_modules_mapping: Mapping for packed/fused modules.

    Returns:
        The quantization type string (e.g., "W8A8_DYNAMIC").
    """
    if packed_modules_mapping is None:
        packed_modules_mapping = dict()

    # Attention
    if layer_type == "attention" and "fa_quant_type" in quant_description:
        return quant_description["fa_quant_type"]

    # Linear / MoE
    return get_linear_quant_type(quant_description, prefix, packed_modules_mapping)


def create_scheme_for_layer(
    quant_description: dict[str, Any],
    prefix: str,
    layer_type: str,
    packed_modules_mapping: dict[str, Any] | None = None,
):
    """Create a quantization scheme instance for a layer.

    Args:
        quant_description: The quantization description dictionary.
        prefix: The layer prefix.
        layer_type: The type of layer ("linear", "moe", "attention").
        packed_modules_mapping: Mapping for packed/fused modules.

    Returns:
        An instance of the appropriate quantization scheme class.
    """
    logger.info_once("Using the vLLM Ascend modelslim Quantization now!")

    quant_type = get_quant_type_for_layer(quant_description, prefix, layer_type, packed_modules_mapping)
    if quant_type is None:
        raise ValueError(f"Could not determine quantization type for layer {prefix}.")

    # Use registry to get scheme class
    scheme_cls = get_scheme_class(quant_type, layer_type)
    if scheme_cls is not None:
        return scheme_cls()

    raise NotImplementedError(f"Currently, vLLM Ascend doesn't support {quant_type} for {layer_type}.")


@register_quantization_config(ASCEND_QUANTIZATION_METHOD)
class AscendModelSlimConfig(QuantizationConfig):
    """Config class for Ascend ModelSlim quantization.

    This class is a general class that parses quantization configs
    that are supported on Ascend hardware, specifically for models
    quantized using the ModelSlim tool.
    """

    def __init__(self, quant_config: dict[str, Any] | None = None):
        super().__init__()
        self.quant_description = quant_config if quant_config is not None else {}

        # TODO(whx): remove this adaptation after adding "shared_head"
        # to prefix of DeepSeekShareHead in vLLM.
        extra_quant_dict = {}
        for k in self.quant_description:
            if "shared_head" in k:
                new_k = k.replace(".shared_head.", ".")
                extra_quant_dict[new_k] = self.quant_description[k]
            if "weight_packed" in k:
                new_k = k.replace("weight_packed", "weight")
                extra_quant_dict[new_k] = self.quant_description[k]

        self.quant_description.update(extra_quant_dict)

    def __repr__(self) -> str:
        return "AscendModelSlimConfig:\n" + super().__repr__()

    @classmethod
    def get_name(cls) -> str:
        return ASCEND_QUANTIZATION_METHOD

    @classmethod
    def get_supported_act_dtypes(cls) -> list[torch.dtype]:
        return [torch.int8, torch.float16, torch.bfloat16]

    @classmethod
    def get_min_capability(cls) -> int:
        raise NotImplementedError('Ascend hardware dose not support "get_min_capability" feature.')

    @classmethod
    def get_config_filenames(cls) -> list[str]:
        # Return empty list so that vllm's get_quant_config() skips the
        # file-based lookup (which raises an unfriendly "Cannot find the
        # config file for ascend" error when the model is not quantized).
        # Instead, the config file is loaded in maybe_update_config(),
        # which can provide a user-friendly error message.
        return []

    @classmethod
    def from_config(cls, config: dict[str, Any]) -> "AscendModelSlimConfig":
        return cls(config)

    @classmethod
    def override_quantization_method(cls, hf_quant_cfg, user_quant) -> str | None:
        if hf_quant_cfg is not None:
            quant_method = hf_quant_cfg.get("quant_method", None)
            if not quant_method and torch.npu.is_available():
                return ASCEND_QUANTIZATION_METHOD
        return None

    def quant_prefix_mapper(self, model_type: str, prefix: str) -> str:
        # TODO (Levi-JQ): will be removed when QuantizationConfig.apply_vllm_mapper is implemented
        prefix_mapping = QUANT_MODEL_PREFIX_MAPPINGS.get(model_type)
        if prefix_mapping:
            hf_to_vllm_mapper = WeightsMapper(orig_to_new_prefix=prefix_mapping)
            return hf_to_vllm_mapper._map_name(prefix)
        return prefix

    def get_quant_method(self, layer: torch.nn.Module, prefix: str) -> Optional["QuantizeMethodBase"]:
        from .method_adapters import (
            AscendEmbeddingMethod,
            AscendFusedMoEMethod,
            AscendKVCacheMethod,
            AscendLinearMethod,
        )

        vllm_config = get_current_vllm_config()
        model_type = vllm_config.model_config.hf_config.model_type

        if model_type in ["minimax", "minimax_m2"]:
            # Adapt to Minimax architecture: update layer names to MoE convention
            prefix = prefix.replace("mlp", "block_sparse_moe")
            # Normalize the prefix by stripping specific expert indices (e.g., 'experts.0' -> 'experts')
            parts = prefix.split(".")
            if "experts" in parts and len(parts) > 2:
                exp_idx = parts.index("experts")
                if exp_idx + 1 < len(parts) and parts[exp_idx + 1].isdigit():
                    parts = parts[: exp_idx + 1]
                    prefix = ".".join(parts)

        if model_type in packed_modules_model_mapping:
            self.packed_modules_mapping = packed_modules_model_mapping[model_type]

        prefix = self.quant_prefix_mapper(model_type, prefix)

        from vllm.model_executor.layers.attention import Attention

        if model_type != "kimi_k2":
            if prefix.startswith("language_model"):
                prefix = prefix.split(".", 1)[-1]

        if isinstance(layer, LinearBase):
            if self.is_layer_skipped_ascend(prefix, self.packed_modules_mapping):
                # Delayed import to avoid circular import
                from vllm_ascend.ops.linear import AscendUnquantizedLinearMethod
                return AscendUnquantizedLinearMethod()

            scheme = create_scheme_for_layer(self.quant_description, prefix, "linear", self.packed_modules_mapping)
            return AscendLinearMethod(scheme)

        elif (
            isinstance(layer, Attention)
            and "fa_quant_type" in self.quant_description
            and self.quant_description["fa_quant_type"] is not None
        ):
            scheme = create_scheme_for_layer(self.quant_description, prefix, "attention", self.packed_modules_mapping)
            return AscendKVCacheMethod(scheme)

        elif isinstance(layer, FusedMoE):
            if self.is_layer_skipped_ascend(prefix, self.packed_modules_mapping):
                # Delayed import to avoid circular import
                from vllm_ascend.ops.fused_moe.fused_moe import AscendUnquantizedFusedMoEMethod
                return AscendUnquantizedFusedMoEMethod(layer.moe_config)

            scheme = create_scheme_for_layer(self.quant_description, prefix, "moe", self.packed_modules_mapping)
            return AscendFusedMoEMethod(scheme, layer.moe_config)

        elif isinstance(layer, VocabParallelEmbedding):
            if self.is_layer_skipped_ascend(prefix, self.packed_modules_mapping):
                return UnquantizedEmbeddingMethod()

            scheme = create_scheme_for_layer(self.quant_description, prefix, "linear", self.packed_modules_mapping)
            return AscendEmbeddingMethod(scheme)

        return None

    def is_layer_skipped_ascend(self, prefix: str, fused_mapping: Mapping[str, list[str]] = MappingProxyType({})):
        # adapted from vllm.model_executor.layers.quantization.utils.quant_utils.is_layer_skipped
        proj_name = prefix.split(".")[-1]

        if proj_name in fused_mapping:
            shard_prefixes = [
                prefix.replace(proj_name, shard_proj_name) for shard_proj_name in fused_mapping[proj_name]
            ]
            is_skipped = None
            for shard_prefix in shard_prefixes:
                is_shard_skipped = self.quant_description[shard_prefix + ".weight"] == "FLOAT"
                if is_skipped is None:
                    is_skipped = is_shard_skipped
                elif is_shard_skipped != is_skipped:
                    raise ValueError(
                        f"Detected some but not all shards of {prefix} "
                        "are quantized. All shards of fused layers "
                        "to have the same precision."
                    )
        else:
            is_skipped = any(
                key.startswith(prefix) and key.endswith(".weight") and value == "FLOAT"
                for key, value in self.quant_description.items()
            )

        assert is_skipped is not None
        return is_skipped

    def maybe_update_config(self, model_name: str) -> None:
        """Load the ModelSlim quantization config from model directory.

        This method is called by vllm after get_quant_config() returns
        successfully. Since we return an empty list from get_config_filenames()
        to bypass vllm's built-in file lookup, we do the actual config loading
        here and provide user-friendly error messages when the config is missing.

        Args:
            model_name: Path to the model directory or model name.
        """
        # If quant_description is already populated (e.g. from from_config()),
        # there is nothing to do.
        if self.quant_description:
            return

        # Try to find and load the ModelSlim config file
        if os.path.isdir(model_name):
            config_path = os.path.join(model_name, MODELSLIM_CONFIG_FILENAME)
            if os.path.isfile(config_path):
                with open(config_path) as f:
                    self.quant_description = json.load(f)
                self._apply_extra_quant_adaptations()
                return

            # Check if there are any json files at all to help diagnose
            json_files = glob.glob(os.path.join(model_name, "*.json"))
            json_names = [os.path.basename(f) for f in json_files]
        else:
            json_names = []

        # Config file not found - raise a friendly error message
        raise ValueError(
            "\n"
            + "=" * 80
            + "\n"
            + "ERROR: ModelSlim Quantization Config Not Found\n"
            + "=" * 80
            + "\n"
            + "\n"
            + f"You have enabled '--quantization {ASCEND_QUANTIZATION_METHOD}' "
            + "(ModelSlim quantization),\n"
            + f"but the model at '{model_name}' does not contain the required\n"
            + f"quantization config file ('{MODELSLIM_CONFIG_FILENAME}').\n"
            + "\n"
            + "This usually means the model weights are NOT quantized by "
            + "ModelSlim.\n"
            + "\n"
            + "Please choose one of the following solutions:\n"
            + "\n"
            + "  Solution 1: Remove the quantization option "
            + "(for float/unquantized models)\n"
            + "  "
            + "-" * 58
            + "\n"
            + f"    Remove '--quantization {ASCEND_QUANTIZATION_METHOD}' from "
            + "your command if you want to\n"
            + "    run the model with the original (float) weights.\n"
            + "\n"
            + "    Example:\n"
            + f"      vllm serve {model_name}\n"
            + "\n"
            + "  Solution 2: Quantize your model weights with ModelSlim first\n"
            + "  "
            + "-" * 58
            + "\n"
            + "    Use the ModelSlim tool to quantize your model weights "
            + "before deployment.\n"
            + "    After quantization, the model directory should contain "
            + f"'{MODELSLIM_CONFIG_FILENAME}'.\n"
            + "    For more information, please refer to:\n"
            + "    https://gitee.com/ascend/msit/tree/master/msmodelslim\n"
            + "\n"
            + (f"  (Found JSON files in model directory: {json_names})\n" if json_names else "")
            + "=" * 80
        )

    def _apply_extra_quant_adaptations(self) -> None:
        """Apply extra adaptations to the quant_description dict.

        This handles known key transformations such as shared_head and
        weight_packed mappings.
        """
        extra_quant_dict = {}
        for k in self.quant_description:
            if "shared_head" in k:
                new_k = k.replace(".shared_head.", ".")
                extra_quant_dict[new_k] = self.quant_description[k]
            if "weight_packed" in k:
                new_k = k.replace("weight_packed", "weight")
                extra_quant_dict[new_k] = self.quant_description[k]

        self.quant_description.update(extra_quant_dict)

    def get_scaled_act_names(self) -> list[str]:
        return []

# UTF-8 encoding prober implementation
from typing import Union
from .charsetprober import CharSetProber
from .codingstatemachine import CodingStateMachine
from .enums import MachineState, ProbingState
from .mbcssm import UTF8_SM_MODEL


class UTF8Prober(CharSetProber):
    # Probability for a single character
    ONE_CHAR_PROB = 0.5

    def __init__(self) -> None:
        super().__init__()
        self.coding_sm = CodingStateMachine(UTF8_SM_MODEL)
        self._num_mb_chars = 0
        self.reset()

    def reset(self) -> None:
        super().reset()
        self.coding_sm.reset()
        self._num_mb_chars = 0

    @property
    def charset_name(self) -> str:
        return "utf-8"

    @property
    def language(self) -> str:
        return ""

    def feed(self, byte_str: Union[bytes, bytearray]) -> ProbingState:
        for c in byte_str:
            coding_state = self.coding_sm.next_state(c)

            if coding_state == MachineState.ERROR:
                self._state = ProbingState.NOT_ME
                break

            if coding_state == MachineState.ITS_ME:
                self._state = ProbingState.FOUND_IT
                break

            if coding_state == MachineState.START:
                if self.coding_sm.get_current_charlen() >= 2:
                    self._num_mb_chars += 1

        if self.state == ProbingState.DETECTING:
            if self.get_confidence() > self.SHORTCUT_THRESHOLD:
                self._state = ProbingState.FOUND_IT

        return self.state

    def get_confidence(self) -> float:
        unlike = 0.99

        if self._num_mb_chars < 6:
            unlike *= self.ONE_CHAR_PROB ** self._num_mb_chars
            return 1.0 - unlike

        return unlike

# ZBV Greedy Pipeline Schedule Implementation
from typing import List
from ..scheduler_node import FuncType, SchedulerNode
from .base import VFoldScheduleAlgo

__all__ = [
    "ScheduleZBVGreedy",
]

class ScheduleZBVGreedy(VFoldScheduleAlgo):
    """ZBV Greedy Pipeline Schedule"""

    def __init__(self, pp_size, vpp_size, micro_batches, memory_config, offload=False):
        # Validate configuration requirements
        assert vpp_size == 2, "ZBV Greedy requires vpp_size == 2"
        assert memory_config in ["min", "half"], "Memory config must be 'min' or 'half'"

        super().__init__(pp_size, vpp_size, micro_batches)
        self.pp_group_size = pp_size
        self.mem_config = memory_config

        # Memory delta for different function types
        self.memory_delta = {
            FuncType.F: 1,
            FuncType.B: 0,
            FuncType.W: -1,
        }
        self.offload = offload

    def stable_pattern_v_half(self) -> List[List[int]]:
        """Generate stable pattern for half memory configuration"""
        interval = 3 if self.pp_size % 2 == 0 else 0
        schedule_patten = []

        for stage_idx in range(self.pp_size):
            # (func_type, chunk, start_time)
            schedule_patten.append(
                [
                    (FuncType.F, 0, stage_idx * 2),
                    (FuncType.F, 1, self.pp_size * 3 - stage_idx - 2),
                    (FuncType.B, 1, self.pp_size * 3 + interval + stage_idx * 2 - 1),
                    (FuncType.B, 0, self.pp_size * 6 + interval - stage_idx - 2),
                ]
            )
        return schedule_patten

    def stable_pattern_v_min(self) -> List[List[int]]:
        """Generate stable pattern for minimum memory configuration"""
        interval = 2 if self.pp_size % 3 == 0 else 0
        schedule_patten = []

        for pp_rank in range(self.pp_size):
            # (func_type, chunk, start_time)
            schedule_patten.append(
                [
                    (FuncType.F, 0, pp_rank),
                    (FuncType.F, 1, self.pp_size * 2 - pp_rank - 1),
                    (FuncType.B, 1, self.pp_size * 2 + interval + pp_rank),
                    (FuncType.B, 0, self.pp_size * 4 + interval - pp_rank - 1),
                ]
            )
        return schedule_patten

    def add_w_nodes(self, node_execute_time_map, time_step_compute_node):
        """Add weight update nodes to the schedule"""
        memory_footprint = [None for _ in range(self.pp_size)]

        for pp_rank in range(self.pp_size):
            node_execute_time_map[pp_rank][FuncType.W] = [
                [0 for _ in range(self.micro_batches)] for _ in range(2)
            ]
            w_nodes_queue = []
            max_time_step = max(time_step_compute_node[pp_rank].keys()) + 2
            memory_footprint[pp_rank] = [0 for _ in range(max_time_step + 1)]

            phase = "WARMUP"
            for time_step in range(max_time_step + 1):
                if time_step > 0:
                    memory_footprint[pp_rank][time_step] = memory_footprint[pp_rank][time_step - 1]

                if time_step in time_step_compute_node[pp_rank]:
                    node = time_step_compute_node[pp_rank][time_step]
                    if node.args is None:
                        node.args = {}
                    node.args["phase"] = phase

                    if node.func_type == FuncType.B:
                        w_nodes_queue.append(node)

                    assert node.func_type in [FuncType.F, FuncType.B]
                    memory_footprint[pp_rank][time_step] += self.memory_delta[node.func_type]

                    # Update execution phase
                    if node.mini_batch == 0 and node.func_type == FuncType.B and node.chunk == 0:
                        phase = "STEADY"
                    elif (
                        node.mini_batch == self.micro_batches - 1
                        and node.func_type == FuncType.F
                        and node.chunk == 1
                    ):
                        phase = "COOLDOWN"

                elif len(w_nodes_queue) > 0:
                    node = w_nodes_queue.pop(0)
                    w_node = SchedulerNode(
                        func_type=FuncType.W,
                        mini_batch=node.mini_batch,
                        chunk=node.chunk,
                        args={"phase": phase},
                    )
                    node_execute_time_map[pp_rank][FuncType.W][w_node.chunk][w_node.mini_batch] = time_step
                    time_step_compute_node[pp_rank][time_step] = w_node
                    memory_footprint[pp_rank][time_step] += self.memory_delta[FuncType.W]

        return node_execute_time_map, time_step_compute_node, memory_footprint

    def calculate_earlist_time(self, rank, node_execute_time_map, node):
        """Calculate earliest possible execution time for a node"""
        earliest_time = 0

        # Check previous microbatch completion
        if node.mini_batch > 0:
            earliest_time = max(
                earliest_time, node_execute_time_map[rank][node.func_type][node.chunk][node.mini_batch - 1]
            )

        # Weight update must wait for backward
        if node.func_type == FuncType.W:
            earliest_time = max(
                earliest_time, node_execute_time_map[rank][FuncType.B][node.chunk][node.mini_batch]
            )
            return earliest_time

        # Check dependencies from previous stage
        direction_info = self.direction_map(rank, node.chunk, node.func_type)
        prev_rank = direction_info["prev"][0]
        prev_chunk = direction_info["recv_from_chunk"]

        if prev_rank is not None:
            earliest_time = max(
                earliest_time, node_execute_time_map[prev_rank][node.func_type][prev_chunk][node.mini_batch]
            )
        elif node.func_type == FuncType.B:
            earliest_time = max(
                earliest_time, node_execute_time_map[rank][FuncType.F][node.chunk][node.mini_batch]
            )

        return earliest_time + 1

    def squeeze(
        self, node_execute_time_map, time_step_compute_node, memory_footprint, reorder_cooldown=False
    ):
        """Optimize schedule by squeezing operations to earlier time slots"""
        max_memory = max([max(memory_footprint[pp_rank]) for pp_rank in range(self.pp_size)])
        max_time_step = max([max(time_step_compute_node[pp_rank].keys()) for pp_rank in range(self.pp_size)])

        pending_w_nodes = [[] for _ in range(self.pp_size)]

        def greedy_pre_insert(pp_rank, node, time_step, earliest_time):
            for i in range(earliest_time, time_step + 1):
                if i not in time_step_compute_node[pp_rank]:
                    if not reorder_cooldown:
                        insert_succ = True
                        for j in range(i, time_step):
                            if memory_footprint[pp_rank][j] + self.memory_delta[node.func_type] > max_memory:
                                insert_succ = False
                                break
                        if not insert_succ:
                            continue
                        else:
                            for j in range(i, time_step):
                                memory_footprint[pp_rank][j] += self.memory_delta[node.func_type]
                            return i
                    else:
                        return i
            return time_step

        # Process all time steps
        for time_step in range(max_time_step + 1):
            for pp_rank in range(self.pp_size):
                if time_step in time_step_compute_node[pp_rank]:
                    node = time_step_compute_node[pp_rank][time_step]

                    if (
                        reorder_cooldown and node.args["phase"] != "COOLDOWN"
                    ):
                        continue

                    if node.func_type == FuncType.W and reorder_cooldown:
                        pending_w_nodes[pp_rank].append(node)
                        del time_step_compute_node[pp_rank][time_step]
                        continue

                    earlist_time = self.calculate_earlist_time(pp_rank, node_execute_time_map, node)
                    earlist_time = greedy_pre_insert(pp_rank, node, time_step, earlist_time)

                    time_step_compute_node[pp_rank][earlist_time] = node
                    node_execute_time_map[pp_rank][node.func_type][node.chunk][node.mini_batch] = earlist_time

                    if time_step != earlist_time:
                        del time_step_compute_node[pp_rank][time_step]

        # Handle pending weight update nodes
        for pp_rank in range(self.pp_size):
            for node in pending_w_nodes[pp_rank]:
                earlist_time = self.calculate_earlist_time(pp_rank, node_execute_time_map, node)
                for i in range(earlist_time, max_time_step + 1):
                    if i not in time_step_compute_node[pp_rank]:
                        time_step_compute_node[pp_rank][i] = node
                        node_execute_time_map[pp_rank][node.func_type][node.chunk][node.mini_batch] = i
                        break

        return node_execute_time_map, time_step_compute_node

    def schedule_from_pattern(
        self,
        schedule_patten,
        num_microbatches: int,
    ):
        """Create schedule from pattern with microbatch scheduling"""
        # Initialize data structures
        node_execute_time_map = [dict() for _ in range(self.pp_size)]
        time_step_compute_node = [dict() for _ in range(self.pp_size)]

        # Add compute nodes based on pattern
        for pp_rank in range(self.pp_size):
            for microbatch in range(num_microbatches):
                for func_type, chunk, start_time in schedule_patten[pp_rank]:
                    if func_type not in node_execute_time_map[pp_rank]:
                        node_execute_time_map[pp_rank][func_type] = [
                            [0 for _ in range(num_microbatches)] for _ in range(2)
                        ]

                    execute_time = start_time + 6 * microbatch
                    node_execute_time_map[pp_rank][func_type][chunk][microbatch] = execute_time

                    assert (
                        execute_time not in time_step_compute_node[pp_rank]
                    ), f"start_time {execute_time} already in time_step_compute_node[{pp_rank}]"

                    time_step_compute_node[pp_rank][execute_time] = SchedulerNode(
                        func_type=func_type, mini_batch=microbatch, chunk=chunk, args=None
                    )

        # Add weight update nodes and optimize schedule
        node_execute_time_map, time_step_compute_node, memory_footprint = self.add_w_nodes(
            node_execute_time_map, time_step_compute_node
        )

        # Squeeze warmup and cooldown phases
        node_execute_time_map, time_step_compute_node = self.squeeze(
            node_execute_time_map, time_step_compute_node, memory_footprint
        )
        node_execute_time_map, time_step_compute_node = self.squeeze(
            node_execute_time_map, time_step_compute_node, memory_footprint, True
        )

        return time_step_compute_node

    def generate_schedule_table(self):
        """Generate complete schedule table"""
        schedule_pattern_funcs = {
            "min": self.stable_pattern_v_min,
            "half": self.stable_pattern_v_half,
        }
        pattern_func = schedule_pattern_funcs[self.mem_config]

        time_step_compute_node = self.schedule_from_pattern(
            pattern_func(),
            self.micro_batches,
        )

        # Build schedule table
        self.time_step_nodes = [dict() for _ in range(self.pp_size)]
        for pp_rank in range(self.pp_size):
            for time_step in sorted(time_step_compute_node[pp_rank].keys()):
                compute_node = time_step_compute_node[pp_rank][time_step]
                self._insert_compute_node(
                    pp_rank, compute_node.mini_batch, compute_node.chunk, compute_node.func_type, time_step
                )

        schedule_table = self._calculate_schedule_table_by_time_step_nodes()

        if self.offload:
            schedule_table = self.add_offload_nodes_to_schedule_table(schedule_table)

        return schedule_table

if __name__ == "__main__":
    # Example usage
    schedule = ScheduleZBVGreedy(pp_size=4, vpp_size=2, micro_batches=16, memory_config="half")
    schedule_table = schedule.generate_schedule_table()
    schedule.print_schedule_table(schedule_table)

