class MultiDistillModelStruct(MultiModelStruct):
    def __init__(self, model_list, config, boundary_step_index=2):
        self.model = model_list  # [high_noise_model, low_noise_model]
        assert len(self.model) == 2, "MultiModelStruct only supports 2 models now."
        self.config = config
        self.boundary_step_index = boundary_step_index
        self.cur_model_index = -1

        logger.info(f"boundary step index: {self.boundary_step_index}")

    @ProfilingContext4DebugL2("Swtich models in infer_main costs")
    def get_current_model_index(self):
        if self.scheduler.step_index < self.boundary_step_index:
            logger.info(
                f"using - HIGH - noise model at step_index {self.scheduler.step_index + 1}"
            )
            #  self.scheduler.sample_guide_scale = self.config["sample_guide_scale"][0]

            if (
                self.config.get("cpu_offload", False)
                and self.config.get("offload_granularity", "block") == "model"
            ):
                if self.cur_model_index == -1:
                    self.to_cuda(model_index=0)
                elif self.cur_model_index == 1:  # 1 -> 0
                    self.offload_cpu(model_index=1)
                    self.to_cuda(model_index=0)

            self.cur_model_index = 0

        else:
            logger.info(
                f"using - LOW - noise model at step_index {self.scheduler.step_index + 1}"
            )
            # self.scheduler.sample_guide_scale = self.config["sample_guide_scale"][1]

            if (
                self.config.get("cpu_offload", False)
                and self.config.get("offload_granularity", "block") == "model"
            ):
                if self.cur_model_index == -1:
                    self.to_cuda(model_index=1)
                elif self.cur_model_index == 0:  # 0 -> 1
                    self.offload_cpu(model_index=0)
                    self.to_cuda(model_index=1)

            self.cur_model_index = 1

    def infer(self, inputs):
        self.get_current_model_index()

        if (
            not self.config.get("lazy_load", False)
            and not self.config.get("unload_modules", False)
        ):
            self.model[self.cur_model_index].infer(inputs)
        else:
            if self.model[self.cur_model_index] is not None:
                self.model[self.cur_model_index].infer(inputs)
            else:
                if self.cur_model_index == 0:
                    lora_configs = self.config.get("lora_configs")
                    high_model_kwargs = {
                        "model_path": self.high_noise_model_path,
                        "config": self.config,
                        "device": self.init_device,
                        "model_type": "wan2.2_moe_high_noise",
                    }

                    if not lora_configs:
                        high_noise_model = WanDistillModel(**high_model_kwargs)
                    else:
                        assert self.config.get("lora_dynamic_apply", False)
                        high_noise_model = build_wan_model_with_lora(
                            WanModel,
                            self.config,
                            high_model_kwargs,
                            lora_configs,
                            model_type="high_noise_model",
                        )

                    high_noise_model.set_scheduler(self.scheduler)
                    self.model[0] = high_noise_model
                    self.model[0].infer(inputs)

                elif self.cur_model_index == 1:
                    lora_configs = self.config.get("lora_configs")
                    low_model_kwargs = {
                        "model_path": self.low_noise_model_path,
                        "config": self.config,
                        "device": self.init_device,
                        "model_type": "wan2.2_moe_low_noise",
                    }

                    if not lora_configs:
                        low_noise_model = WanDistillModel(**low_model_kwargs)
                    else:
                        assert self.config.get("lora_dynamic_apply", False)
                        low_noise_model = build_wan_model_with_lora(
                            WanModel,
                            self.config,
                            low_model_kwargs,
                            lora_configs,
                            model_type="low_noise_model",
                        )

                    low_noise_model.set_scheduler(self.scheduler)
                    self.model[1] = low_noise_model
                    self.model[1].infer(inputs)


@RUNNER_REGISTER("wan2.2_moe_distill")
class Wan22MoeDistillRunner(WanDistillRunner):
    def __init__(self, config):
        super().__init__(config)

        # High noise model path setup
        if self.config.get("dit_quantized", False) and self.config.get(
            "high_noise_quantized_ckpt", None
        ):
            self.high_noise_model_path = self.config["high_noise_quantized_ckpt"]
        elif self.config.get("high_noise_original_ckpt", None):
            self.high_noise_model_path = self.config["high_noise_original_ckpt"]
        else:
            self.high_noise_model_path = os.path.join(
                self.config["model_path"], "high_noise_model"
            )
            if not os.path.isdir(self.high_noise_model_path):
                raise FileNotFoundError("High Noise Model does not find")

        # Low noise model path setup
        if self.config.get("dit_quantized", False) and self.config.get(
            "low_noise_quantized_ckpt", None
        ):
            self.low_noise_model_path = self.config["low_noise_quantized_ckpt"]
        elif (
            not self.config.get("dit_quantized", False)
            and self.config.get("low_noise_original_ckpt", None)
        ):
            self.low_noise_model_path = self.config["low_noise_original_ckpt"]
        else:
            self.low_noise_model_path = os.path.join(
                self.config["model_path"], "low_noise_model"
            )
            if not os.path.isdir(self.low_noise_model_path):
                raise FileNotFoundError("Low Noise Model does not find")

    def load_transformer(self):
        if (
            not self.config.get("lazy_load", False)
            and not self.config.get("unload_modules", False)
        ):
            lora_configs = self.config.get("lora_configs")

            high_model_kwargs = {
                "model_path": self.high_noise_model_path,
                "config": self.config,
                "device": self.init_device,
                "model_type": "wan2.2_moe_high_noise",
            }
            low_model_kwargs = {
                "model_path": self.low_noise_model_path,
                "config": self.config,
                "device": self.init_device,
                "model_type": "wan2.2_moe_low_noise",
            }

            if not lora_configs:
                high_noise_model = WanDistillModel(**high_model_kwargs)
                low_noise_model = WanDistillModel(**low_model_kwargs)
            else:
                high_noise_model = build_wan_model_with_lora(
                    WanModel,
                    self.config,
                    high_model_kwargs,
                    lora_configs,
                    model_type="high_noise_model",
                )
                low_noise_model = build_wan_model_with_lora(
                    WanModel,
                    self.config,
                    low_model_kwargs,
                    lora_configs,
                    model_type="low_noise_model",
                )

            return MultiDistillModelStruct(
                [high_noise_model, low_noise_model],
                self.config,
                self.config["boundary_step_index"],
            )
        else:
            model_struct = MultiDistillModelStruct(
                [None, None], self.config, self.config["boundary_step_index"]
            )
            model_struct.low_noise_model_path = self.low_noise_model_path
            model_struct.high_noise_model_path = self.high_noise_model_path
            model_struct.init_device = self.init_device

            return model_struct

    def init_scheduler(self):
        if self.config["feature_caching"] == "NoCaching":
            self.scheduler = Wan22StepDistillScheduler(self.config)
        else:
            raise NotImplementedError(
                f"Unsupported feature_caching type: {self.config['feature_caching']}"
            )

    def switch_lora(
        self,
        high_lora_path: str = None,
        high_lora_strength: float = 1.0,
        low_lora_path: str = None,
        low_lora_strength: float = 1.0,
    ):
        """
        Switch LoRA weights dynamically for Wan2.2 MoE Distill models.
        This method handles both high_noise_model and low_noise_model separately.

        Args:
            lora_path: Path to the LoRA safetensors file (for backward compatibility)
            strength: LoRA strength (default: 1.0) (for backward compatibility)
            high_lora_path: Path to the high_noise_model LoRA safetensors file
            high_lora_strength: High noise model LoRA strength (default: 1.0)
            low_lora_path: Path to the low_noise_model LoRA safetensors file
            low_lora_strength: Low noise model LoRA strength (default: 1.0)

        Returns:
            bool: True if LoRA was successfully switched, False otherwise
        """
        if not hasattr(self, "model") or self.model is None:
            logger.error("Model not loaded. Please load model first.")
            return False

        if high_lora_path is not None:
            if (
                self.model.model[0] is not None
                and hasattr(self.model.model[0], "_update_lora")
            ):
                logger.info(
                    f"Switching high_noise_model LoRA to: {high_lora_path} with strength={high_lora_strength}"
                )
                self.model.model[0]._update_lora(high_lora_path, high_lora_strength)

        if low_lora_path is not None:
            if (
                self.model.model[1] is not None
                and hasattr(self.model.model[1], "_update_lora")
            ):
                logger.info(
                    f"Switching low_noise_model LoRA to: {low_lora_path} with strength={low_lora_strength}"
                )
                self.model.model[1]._update_lora(low_lora_path, low_lora_strength)

        logger.info("LoRA switched successfully for Wan2.2 MoE Distill models")
        return True

from typing import Dict, List
import copy

# Converts a tool message to a user message using chat template logic
def convert_tool_to_user_message(tool_message, tokenizer, format="qwen"):
    # Only Qwen format is supported
    assert format == "qwen"

    if tool_message["role"] == "user":
        return tool_message
    elif tool_message["role"] == "tool" and len(tool_message["tool_calls"]) > 0:
        # Ensure exactly one tool call exists
        assert len(tool_message["tool_calls"]) == 1

        # Return a user message with the tool result as content
        return {
            "role": "user",
            "content": str(tool_message["tool_calls"][0]["result"]),
        }

# Removes specified fields from a dictionary (deep copy)
def remove_fields(d: Dict, fields: List[str]) -> Dict:
    d = copy.deepcopy(d)
    for field in fields:
        d.pop(field.strip(), None)
    return d

# Pipeline validation script
import json
import sys
import os
import glob
from datetime import datetime, date, timedelta, timezone


def file_modified_since(filepath, cutoff_dt):
    """Check if file was modified after cutoff."""
    if not os.path.exists(filepath):
        return False
    mtime = datetime.fromtimestamp(os.path.getmtime(filepath), tz=timezone.utc)
    return mtime > cutoff_dt


def last_modified(filepath):
    """Get human-readable last modified time."""
    if not os.path.exists(filepath):
        return 'DOES NOT EXIST'
    mtime = datetime.fromtimestamp(os.path.getmtime(filepath), tz=timezone.utc)
    return mtime.isoformat()


def count_significance(jsonl_path, sig_level):
    """Count entries with given significance in a JSONL file."""
    count = 0
    if not os.path.exists(jsonl_path):
        return 0
    with open(jsonl_path, encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
                if entry.get('significance') == sig_level:
                    count += 1
            except json.JSONDecodeError:
                pass
    return count


def count_unreflected(jsonl_path):
    """Count entries where reflected=false."""
    count = 0
    if not os.path.exists(jsonl_path):
        return 0
    with open(jsonl_path, encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
                if entry.get('reflected') is False:
                    count += 1
            except json.JSONDecodeError:
                pass
    return count


def validate(memory_dir, since_minutes=30):
    errors = []
    warnings = []
    findings = {}

    now = datetime.now(timezone.utc)
    cutoff = now - timedelta(minutes=since_minutes)
    today_str = date.today().isoformat()

    # ========================================
    # 1. Experience file exists and has content
    # ========================================
    exp_dir = os.path.join(memory_dir, 'experiences')
    today_file = os.path.join(exp_dir, f'{today_str}.jsonl')

    if not os.path.exists(today_file):
        errors.append({
            'check': 'experience_file',
            'message': f"Today's experience file does not exist: {today_file}. "
                       f"If the agent ran a heartbeat, it should have logged something."
        })
        findings['experience_file'] = 'MISSING'
    else:
        findings['experience_file'] = last_modified(today_file)
        if not file_modified_since(today_file, cutoff):
            warnings.append({
                'check': 'experience_file',
                'message': f"Experience file exists but wasn't modified in the last {since_minutes}m. "
                           f"Last modified: {last_modified(today_file)}"
            })

    # ========================================
    # 2. Notable/pivotal promotion to significant.jsonl
    # ========================================
    sig_file = os.path.join(memory_dir, 'significant', 'significant.jsonl')
    notable_count = count_significance(today_file, 'notable') if os.path.exists(today_file) else 0
    pivotal_count = count_significance(today_file, 'pivotal') if os.path.exists(today_file) else 0
    findings['notable_today'] = notable_count
    findings['pivotal_today'] = pivotal_count

    if (notable_count + pivotal_count) > 0 and not os.path.exists(sig_file):
        errors.append({
            'check': 'significant_promotion',
            'message': f"Found {notable_count} notable + {pivotal_count} pivotal experiences today "
                       f"but significant.jsonl does not exist. Notable/pivotal MUST be promoted."
        })

    # ========================================
    # 3. Reflection files exist if triggered
    # ========================================
    ref_dir = os.path.join(memory_dir, 'reflections')
    unreflected_notable = 0
    unreflected_pivotal = 0

    # Check across all experience files, not just today
    if os.path.isdir(exp_dir):
        for exp_file in glob.glob(os.path.join(exp_dir, '*.jsonl')):
            if os.path.exists(exp_file):
                with open(exp_file, encoding='utf-8', errors='replace') as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            entry = json.loads(line)
                            if entry.get('reflected') is False:
                                sig = entry.get('significance', '')
                                if sig == 'notable':
                                    unreflected_notable += 1
                                elif sig == 'pivotal':
                                    unreflected_pivotal += 1
                        except json.JSONDecodeError:
                            pass

    findings['unreflected_notable'] = unreflected_notable
    findings['unreflected_pivotal'] = unreflected_pivotal

    if unreflected_pivotal > 0:
        errors.append({
            'check': 'pivotal_reflection',
            'message': f"{unreflected_pivotal} pivotal experience(s) are unreflected. "
                       f"Pivotal experiences require IMMEDIATE reflection."
        })

    # Check if any reflection files exist at all
    if os.path.isdir(ref_dir):
        ref_files = glob.glob(os.path.join(ref_dir, 'REF-*.json'))
        findings['total_reflection_files'] = len(ref_files)
        recent_refs = [f for f in ref_files if file_modified_since(f, cutoff)]
        findings['recent_reflection_files'] = len(recent_refs)
    else:
        findings['total_reflection_files'] = 0
        findings['recent_reflection_files'] = 0
        if (notable_count + pivotal_count) > 0:
            warnings.append({
                'check': 'reflection_dir',
                'message': 'Reflections directory does not exist but notable/pivotal experiences were logged'
            })

    # ========================================
    # 4. State file updated
    # ========================================
    state_file = os.path.join(memory_dir, 'evoclaw-state.json')
    if not os.path.exists(state_file):
        errors.append({
            'check': 'state_file',
            'message': f"State file does not exist: {state_file}. Pipeline must update state every heartbeat."
        })
        findings['state_file'] = 'MISSING'
    else:
        findings['state_file'] = last_modified(state_file)
        if not file_modified_since(state_file, cutoff):
            warnings.append({
                'check': 'state_file',
                'message': f"State file wasn't modified in the last {since_minutes}m. "
                           f"Pipeline should update it every heartbeat. "
                           f"Last modified: {last_modified(state_file)}"
            })

    # ========================================
    # 5. If state says pending proposals, check file
    # ========================================
    if os.path.exists(state_file):
        try:
            with open(state_file) as f:
                state = json.load(f)
            pending = state.get('pending_proposals_count', 0)
            if pending > 0:
                pending_file = os.path.join(memory_dir, 'proposals', 'pending.jsonl')
                if not os.path.exists(pending_file):
                    errors.append({
                        'check': 'pending_proposals',
                        'message': f"State claims {pending} pending proposals but pending.jsonl doesn't exist"
                    })
            findings['claimed_pending'] = pending
        except (json.JSONDecodeError, IOError):
            pass

    # ========================================
    # Overall assessment
    # ========================================
    status = 'FAIL' if errors else 'PASS'
    return {
        'status': status,
        'file': memory_dir,
        'checked_at': now.isoformat(),
        'since_minutes': since_minutes,
        'errors': errors,
        'warnings': warnings,
        'findings': findings
    }


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: check_pipeline_ran.py <memory_dir> [--since-minutes 30]', file=sys.stderr)
        sys.exit(2)

    memory_dir = sys.argv[1]
    since = 30

    if '--since-minutes' in sys.argv:
        idx = sys.argv.index('--since-minutes')
        if idx + 1 < len(sys.argv):
            since = int(sys.argv[idx + 1])

    result = validate(memory_dir, since)
    print(json.dumps(result, indent=2))
    sys.exit(0 if result['status'] == 'PASS' else 1)

