# Calculate root and source directories 
base_dir = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
code_dir = os.path.join(base_dir, "jsonmodels")
test_dir = os.path.join(base_dir, "tests")

@pytest.mark.skipif(not tests.LINT, reason="No lint tests.")
def test_pep8_and_complexity():
    outcomes = []
    for filepath in _gather_files([code_dir, test_dir]):
        outcomes.append(subprocess.call(["flake8", filepath]))
    if any(outcomes):
        raise RuntimeError("Tests for PEP8 compliance and complexity have failed!")

@pytest.mark.skipif(
    not tests.LINT or not tests.CHECK_SPELLING, reason="No spelling check."
)
def test_docs():
    run("sphinx-build -b spelling -d docs/_build/doctress " "docs docs/build/spelling")

def _gather_files(paths):
    collected = []
    for path in paths:
        _traverse_recursively(path, collected)
    return collected

def _traverse_recursively(folder, output):
    for item in os.listdir(folder):
        if not re.search("^\\.", item):
            fullpath = os.path.join(folder, item)
            if re.search("\\.py$", item):
                output.append(fullpath)
            elif os.path.isdir(fullpath):
                _traverse_recursively(fullpath, output)

