class Manager:
    def __init__(self):
        super().__init__()
        self.occupied = False
        self.event_scheduler = uasyncio.get_event_loop()
        self.active = False

    @staticmethod
    def delay_hardware() -> bool:
        await uasyncio.sleep_ms(1)
        # hw: Actuator
        # return any([not hw.available for hw in self.get_hw_instances()])

    def activate(self):
        self.active = True
        print('{} activated'.format(self.__class__.__name__))

    def deactivate(self):
        self.active = False
        print('{} deactivated'.format(self.__class__.__name__))

    def set_status(self, status: bool):
        mapping = {True: self.activate,
                   False: self.deactivate}
        mapping[status]()

class BasicManager(Manager, Observer):
    def __init__(self, detector: ADCReader, device: Actuator):
        super().__init__()
        self.device = device
        self.first_detection = False
        detector.add_observer(self)

    def update(self, new_reading):
        self.event_scheduler.create_task(self.process(new_reading))

    def validate_conditions(self) -> bool:
        return (self.device.available or self.occupied) and self.active

    def clear_state(self):
        self.device.power_off()
        self.device.unlock()
        self.first_detection = False
        self.occupied = False

    def deactivate(self):
        self.active = False
        print('{} deactivated'.format(self.__class__.__name__))
        if self.occupied:
            self.clear_state()

    def initial_detection_actions(self):
        self.occupied = True
        self.device.lock()
        self.first_detection = True

    async def process(self, current_value):
        raise NotImplementedError

class HumidityManager(BasicManager):
    def __init__(self, detector: MoistureReader, sprayer: Pump, min_limit: int, max_limit: int,
                 active_duration: int, pause_interval: int):
        super().__init__(detector, sprayer)
        self.detector = detector
        self.min_limit = min_limit
        self.max_limit = max_limit
        self.active_duration = active_duration
        self.pause_interval = pause_interval
        self.device.power_off()

    def within_range(self, current_value) -> bool:
        return self.min_limit <= current_value <= self.max_limit

    def below_limit(self, current_value) -> bool:
        return current_value < self.min_limit

    def above_limit(self, current_value) -> bool:
        return current_value > self.max_limit

    async def spray(self):
        self.device.power_on()
        await uasyncio.sleep(self.active_duration)
        self.device.power_off()
        await uasyncio.sleep(self.pause_interval)

    async def process(self, current_value):
        if not self.validate_conditions():
            return

        if self.within_range(current_value):
            self.clear_state()
            return

        if not self.first_detection and self.below_limit(current_value):
            print('Humidity level {} < {} !'.format(current_value, self.min_limit))
            self.first_detection = True

        while not self.above_limit(self.detector.value):
            self.device.lock()
            await self.spray()

        self.clear_state()

class IlluminationManager(BasicManager):
    def __init__(self, detector: LightReader, lamp: LED, threshold: int):
        super().__init__(detector, lamp)
        self.threshold = threshold
        self.device.power_off()

    def lamp_intensity(self, light_level) -> int:
        margin = self.threshold - light_level
        return margin * 100 / self.threshold

    async def process(self, current_value):
        if not self.validate_conditions():
            return

        if current_value >= self.threshold:
            self.clear_state()
            return

        if not self.first_detection:
            print('Illumination level {} < {} !'.format(current_value, self.threshold))
            self.initial_detection_actions()

        self.device.percentage(self.lamp_intensity(current_value))

