from voluptuous import Schema, Required, Optional, Invalid
from cloud99 import ACTOR_CLASSES
from cloud99.logging_setup import LOGGER

def check_openrc(openrc_config):
    openrc_validation_schema = Schema({
        Required("auth_url"): str,
        Required("username"): str,
        Required("password"): str,
        Required("region_name"): str,
        Required("tenant_name"): str,
        Required("https_cacert"): str,
        Optional("https_insecure"): bool,
    })
    LOGGER.debug("Checking openrc configuration")
    openrc_validation_schema(openrc_config)

def check_inventory(inventory_data):
    inventory_validation_schema = Schema({
        Required("ip_or_hostname"): str,
        Required("username"): str,
        Required("password"): str,
        Required("role"): str,
    })
    LOGGER.debug("Checking inventory configuration")
    for server, settings in inventory_data.items():
        inventory_validation_schema(settings)

def check_disruptors(disruptor_list):
    _check("disruptors", disruptor_list)

def check_loaders(loader_list):
    _check("loaders", loader_list)

def check_monitors(monitor_list):
    _check("monitors", monitor_list)

def _check(entity_type, entity_list):
    LOGGER.debug("Checking {0} configuration".format(entity_type))
    for item in entity_list:
        if type(item) == str:
            continue
        for class_name, config in item.items():
            actor_class = ACTOR_CLASSES.get(class_name, None)
            if not actor_class:
                raise Invalid("Unknown {0} {1}".format(entity_type, class_name))
            actor_class.schema(config)

