# Utility functions for interacting with the Wistia API.
"""
from __future__ import annotations
from requests import HTTPError
from .api_data import WistiaDataApi
from .config import WistiaConfig
from .errors import NoSuchProject
from .log import LOG
from .models import (Container, Project, Video,
                     Customizations, Plugin, CaptionsV1)

class WistiaHelper:
    """
    Helper class for interacting with Wistia API and Wistia videos, which
    further simplifies any calls. This assumes that :class:`WistiaApi` has
    been configured as needed with the API token.
    """
    @staticmethod
    def is_archived_video(video_name: str) -> bool:
        """
        Check if this is an archived video which is automatically created by
        Wistia.
        In that case, we shouldn't order captions for it, since it's a copy of
        a video that was replaced with new media.
        Source: https://wistia.com/learn/product-updates/improved-library-management-tools  # noqa: E501
        """
        return '[Archived' in video_name and video_name.endswith(']')

    @classmethod
    def video_exists(cls, video_id: str) -> bool:
        """
        Check if a video exists on Wistia.
        """
        response = WistiaDataApi.session().head(
            WistiaConfig.MEDIAS_SHOW_URL.format(media_id=video_id)
        )
        return response.status_code != 404

    @classmethod
    def update_video_name(
        cls,
        video_id: str,
        video_title: str
    ) -> Video:
        """Update the title for a Wistia video."""
        return WistiaDataApi.update_video(video_id, video_title)

    @classmethod
    def has_captions_enabled(cls, video_id: str) -> bool:
        """
        Check if a video has captions available in the player settings.
        :return: A boolean indicating if the video player has captions
          available.
        """
        customizations = WistiaDataApi.get_customizations(video_id)
        return customizations.plugin.captions_v1.on is True

    @classmethod
    def enable_captions(
        cls,
        video_id: str,
        on_by_default: bool = False
    ):
        """
        Enable captions on a Wistia video.
        """
        data = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    on_by_default=on_by_default,
                    on=True
                )
            )
        )
        return WistiaDataApi.update_customizations(video_id, data)

    @classmethod
    def enable_ad(cls, video_id: str):
        """
        Enable audio descriptions on a Wistia video.
        """
        data = Customizations(audio_description_is_required=True)
        return WistiaDataApi.update_customizations(video_id, data)

    @classmethod
    def enable_captions_and_ad(
        cls,
        video_id: str,
        on_by_default: bool = False
    ):
        """
        Enable captions and AD on a Wistia video.
        """
        data = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    on_by_default=on_by_default,
                    on=True
                )
            ),
            audio_description_is_required=True
        )
        return WistiaDataApi.update_customizations(video_id, data)

    @classmethod
    def disable_captions_and_ad(
        cls,
        video_id: str,
        on_by_default: bool = False
    ):
        """
        Disable captions and AD on a Wistia video.
        """
        data = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    on_by_default=on_by_default,
                    on=False
                )
            ),
            audio_description_is_required=False
        )
        return WistiaDataApi.update_customizations(video_id, data)

    @classmethod
    def customize_video_on_wistia(
        cls,
        video_id: str,
        player_color: str
    ):
        """Set commonly used customization options for a media on Wistia."""
        customizations = {'playerColor': player_color}
        r = WistiaDataApi.session().put(
            WistiaConfig.CUSTOMIZATION_URL.format(media_id=video_id),
            json=customizations
        )
        try:
            r.raise_for_status()
        except HTTPError:
            LOG.error('Wistia Customizations API. status=%d text=%s',
                      r.status_code, r.text)
            raise
        LOG.info('[%s] Wistia: Customize Video success', r.elapsed)
        return r.json()

    @classmethod
    def project_details(
        cls,
        project_id: str,
        projects: Container[Project] | None = None
    ) -> Project:
        """Retrieve details on a Wistia project.
        The optional parameter `projects` contains info on all projects in
        the Wistia account, such as a response from the `Projects:list` API.
        :raises NoSuchProject: If the project doesn't exist on Wistia
        """
        if not projects:
            projects = WistiaDataApi.list_all_projects()

        found_project = None
        for p in projects:
            if p.hashed_id == project_id:
                found_project = p
                break

        if found_project is None:
            raise NoSuchProject(project_id)

        return found_project

# Azure Blob Storage path implementation
from pathlib import Path
from tempfile import TemporaryDirectory
from typing import TYPE_CHECKING

try:
    from azure.core.exceptions import ResourceNotFoundError
except ImportError:
    pass

from ..cloudpath import CloudPath, NoStatError, register_path_class

if TYPE_CHECKING:
    from .azblobclient import AzureBlobClient

@register_path_class("azure")
class AzureBlobPath(CloudPath):
    """Class for representing and operating on Azure Blob Storage URIs, following the style of 
    Python's standard library [`pathlib` module](https://docs.python.org/3/library/pathlib.html).

    Instances represent a path in Blob Storage with filesystem-like semantics and convenient 
    methods for basic operations like joining, reading, writing, iterating over contents, etc. 
    This class closely mimics the [`pathlib.Path`](https://docs.python.org/3/library/pathlib.html#pathlib.Path) 
    interface, so familiar properties and methods are available and behave as expected.

    The [`AzureBlobClient`](../azblobclient/) class manages Azure authentication. If no client 
    instance is explicitly provided during `AzureBlobPath` instantiation, a default client is used. 
    See `AzureBlobClient`'s documentation for more details.
    """
    cloud_prefix: str = "az://"
    client: "AzureBlobClient"

    @property
    def drive(self) -> str:
        return self.container

    def is_dir(self) -> bool:
        return self.client._is_file_or_dir(self) == "dir"

    def is_file(self) -> bool:
        return self.client._is_file_or_dir(self) == "file"

    def mkdir(self, parents=False, exist_ok=False):
        # Directory creation isn't supported directly in blob storage
        pass

    def touch(self):
        if self.exists():
            self.client._move_file(self, self)
        else:
            temp_dir = TemporaryDirectory()
            temp_file = Path(temp_dir.name) / "empty"
            temp_file.touch()
            self.client._upload_file(temp_file, self)
            temp_dir.cleanup()

    def stat(self):
        try:
            metadata = self.client._get_metadata(self)
        except ResourceNotFoundError:
            raise NoStatError(
                f"No stats available for {self}; it may be a directory or not exist."
            )
        return os.stat_result(
            (
                None,  # mode
                None,  # ino
                self.cloud_prefix,  # dev,
                None,  # nlink,
                None,  # uid,
                None,  # gid,
                metadata.get("size", 0),  # size,
                None,  # atime,
                metadata.get("last_modified", 0).timestamp(),  # mtime,
                None,  # ctime,
            )
        )

    @property
    def container(self) -> str:
        return self._no_prefix.split("/", 1)[0]

    @property
    def blob(self) -> str:
        key = self._no_prefix_no_drive
        # Remove leading slash if present (not needed for blob keys)
        if key.startswith("/"):
            key = key[1:]
        return key

    @property
    def etag(self):
        return self.client._get_metadata(self).get("etag", None)

    @property
    def md5(self) -> str:
        return self.client._get_metadata(self).get("content_settings", {}).get("content_md5", None)

