@main.command(name="run")
@click.argument("scenario-file", type=cli_module.File(), required=False)
@click.option("--auth", default="")
@click.option("--mailgun-api-key")
@click.option(
    "--notify-tasks",
    type=CliEnumChoice(TaskNotifyType),
    default=TaskNotifyType.NONE.value,
    help="Notify of task status via chosen method.",
)
@click.option(
    "--ui/--no-ui",
    "enable_ui",
    default=sys_module.stdout.isatty(),
    help="En-/disable console UI. [default: auto-detect]",
)
@key_password_options
@chain_option
@data_path_option
@click.pass_context
def run(
    ctx,
    chain,
    data_path,
    mailgun_api_key,
    auth,
    password,
    keystore_file,
    scenario_file,
    notify_tasks,
    enable_ui,
    password_file,
):
    """Execute a scenario as defined in scenario definition file.
    Calls :func:`exit` when done, with the following status codes:
        Exit code 1x
        There was a problem when starting up the SP, nodes, deploying tokens
        or setting up services. This points at an issue in the SP and of its
        components.
        Exit code 2x
        There was an error when parsing or evaluating the given scenario definition file.
        This may be a syntax- or logic-related issue.
        Exit code 3x
        There was an assertion error while executing the scenario. This points
        to an error in a `raiden` component (the client, services or contracts).
    """
    data_path = PathLib(data_path)
    scenario_file = PathLib(scenario_file.name).absolute()
    log_file_name = construct_log_file_name("run", data_path, scenario_file)
    configure_logging_for_subcommand(log_file_name)
    log.info("Scenario Player version:", version_info=get_full_spec())
    password = get_password(password, password_file)
    account = get_account(keystore_file, password)
    notify_tasks_callable = None
    if notify_tasks is TaskNotifyType.ROCKETCHAT:
        if "RC_WEBHOOK_URL" not in os_module.environ:
            cli_module.secho(
                "'--notify-tasks rocket-chat' requires env variable 'RC_WEBHOOK_URL' to be set.",
                fg="red",
            )
        notify_tasks_callable = post_task_state_to_rc
    log_buffer = None
    if enable_ui:
        log_buffer = attach_log_buf()
    # Dynamically import valid Task classes from sceanrio_player.tasks package.
    gather_tasks(sp_tasks)
    # Start our Services
    report: DictType[str, str] = dict()
    success = GEvent()
    success.clear()
    try:
        orchestrate(
            report,
            success,
            enable_ui,
            log_buffer,
            log_file_name,
            mailgun_api_key,
            ScenarioRunnerArgs(
                account, auth, chain, data_path, scenario_file, notify_tasks_callable
            ),
        )
    except ScenarioAssertionError as ex:
        log.error("Run finished", result="assertion errors")
        if hasattr(ex, "exit_code"):
            exit_code = ex.exit_code
        else:
            exit_code = 30
        report.update(dict(subject=f"Assertion mismatch in {scenario_file.name}", message=str(ex)))
        sys_module.exit(exit_code)
    except ScenarioError as ex:
        log.error("Run finished", result="scenario error", message=str(ex))
        if hasattr(ex, "exit_code"):
            exit_code = ex.exit_code
        else:
            exit_code = 20
        report.update(
            dict(subject=f"Invalid scenario {scenario_file.name}", message=tb_module.format_exc())
        )
        sys_module.exit(exit_code)
    except Exception as ex:
        log.exception("Exception while running scenario")
        if hasattr(ex, "exit_code"):
            exit_code = ex.exit_code  # type: ignore
        else:
            exit_code = 10
        report.update(
            dict(
                subject=f"Error running scenario {scenario_file.name}",
                message=tb_module.format_exc(),
            )
        )
        sys_module.exit(exit_code)
    else:
        success.set()
        exit_code = 0
        log.info("Run finished", result="success")
        report.update(dict(subject=f"Scenario successful {scenario_file.name}", message="Success"))
        log.info("Scenario player unwind complete")
        sys_module.exit(exit_code)

ScenarioRunnerArgs = NamedTupleType(
    "ScenarioRunnerArgs",
    ["account", "auth", "chain", "data_path", "scenario_file", "notify_tasks_callable"],
)

def orchestrate(
    report_container,
    success,
    enable_ui,
    log_buffer,
    log_file_name,
    mailgun_api_key,
    scenario_runner_args,
):
    # We need to fix the log stream early in case the UI is active
    with ServiceProcessManager():
        scenario_runner = ScenarioRunner(*scenario_runner_args)
        runner_manager = ScenarioRunnerManager(scenario_runner)
        with runner_manager as runner:
            if enable_ui:
                ui: AbstractContextManager = ScenarioUIManager(
                    runner, log_buffer, log_file_name, success
                )
            else:
                ui = nullcontext()
            log.info("Startup complete")
            with ui:
                runner.run_scenario()

class ScenarioUIManager:
    def __init__(self, runner, log_buffer, log_file_name, success):
        self.ui = ScenarioUI(runner, log_buffer, log_file_name)
        self.success = success

    def __enter__(self):
        self.ui_greenlet = self.ui.run()
        return self.success

    def __exit__(self, type, value, traceback):
        try:
            self.ui.set_success(self.success.is_set())
            log.warning("Press q to exit")
            while not self.ui_greenlet.dead:
                gevent_mod.sleep(1)
        finally:
            if self.ui_greenlet is not None and not self.ui_greenlet.dead:
                self.ui_greenlet.kill(UrwidExit)
                self.ui_greenlet.join()

class ServiceProcessManager:
    def __enter__(self):
        self.service_process = SvcProc()
        self.service_process.start()
        return self.service_process

    def __exit__(self, type, value, traceback):
        try:
            self.service_process.stop()
        except SvcProcErr:
            log.exception("ServiceProcessManager died")
        except Exception:
            log.exception("ServiceProcessManager died")
            self.service_process.kill()

class ScenarioRunnerManager:
    def __init__(self, scenario_runner: ScenarioRunner):
        self.scenario_runner = scenario_runner

    def __enter__(self):
        return self.scenario_runner

    def __exit__(self, type, value, traceback):
        try:
            self.scenario_runner.node_controller.stop()
        except MirakuruError:
            log.exception("ScenarioRunnerManager stop died")
        except Exception:
            log.exception("ScenarioRunnerManager stop died")
            self.scenario_runner.node_controller.kill()

