import triton

class _matrix_multiply(torch.autograd.Function):
    source_code = """
    __global__ void matmul(TYPE *A __noalias __readonly __aligned(16), 
                           TYPE *B __noalias __readonly __aligned(16), 
                           TYPE *C __noalias __aligned(16), 
                           float scale,
                           int rows_A __retune,
                           int cols_B __retune,
                           int shared_dim __retune,
                           int lda __multipleof(8), 
                           int ldb __multipleof(8), 
                           int ldc __multipleof(8)) {
      // initialization phase
      int block_i = get_program_id(0);
      int block_j = get_program_id(1);
      int block_k = get_program_id(2);
      int num_blocks_x = rows_A / TILE_M;
      int num_blocks_y = cols_B / TILE_N;
      int flat_idx = block_i + block_j * num_blocks_x;
      block_i = flat_idx / num_blocks_y;
      block_j = flat_idx % num_blocks_y;

      int row_indices[TILE_M] = block_i * TILE_M + 0 ... TILE_M;
      int col_indices[TILE_N] = block_j * TILE_N + 0 ... TILE_N;

      // partition the reduction dimension
      shared_dim      = shared_dim / BLOCK_K;
      int k_indices[TILE_K] = block_k * shared_dim + 0 ... TILE_K;

      // compute offsets for input matrices
      int offset_a[TILE_M, TILE_K] = k_indices[newaxis, :] * STRIDE_AK + row_indices[:, newaxis] * STRIDE_AM;
      int offset_b[TILE_K, TILE_N] = k_indices[:, newaxis] * STRIDE_BK + col_indices[newaxis, :] * STRIDE_BN;
      TYPE* ptr_a[TILE_M, TILE_K] = A + offset_a;
      TYPE* ptr_b[TILE_K, TILE_N] = B + offset_b;

      // load data with bounds checking
      bool valid_a[TILE_M, TILE_K] = k_indices[newaxis, :] < shared_dim;
      bool valid_b[TILE_K, TILE_N] = k_indices[:, newaxis] < shared_dim;
      TYPE data_a[TILE_M, TILE_K] = valid_a ? *ptr_a : 0;
      TYPE data_b[TILE_K, TILE_N] = valid_b ? *ptr_b : 0;

      // main computation loop
      float accumulator[TILE_M, TILE_N] = 0;
      for(int k = shared_dim; k > 0; k -= TILE_K){
        accumulator += data_a @ data_b;

        bool still_valid_a[TILE_M, TILE_K] = k > TILE_K;
        bool still_valid_b[TILE_K, TILE_N] = k > TILE_K;
        ptr_a += TILE_K * STRIDE_AK;
        ptr_b += TILE_K * STRIDE_BK;
        data_a = *?(still_valid_a)ptr_a;
        data_b = *?(still_valid_b)ptr_b;
      }

      accumulator = accumulator * scale;
      TYPE result[TILE_M, TILE_N] = accumulator;

      // final write-back
      int out_row[TILE_M] = get_program_id(0) * TILE_M + 0 ... TILE_M;
      int out_col[TILE_N] = get_program_id(1) * TILE_N + 0 ... TILE_N;
      int output_offset[TILE_M, TILE_N] = out_row[:, newaxis] * ldc + out_col[newaxis, :];
      TYPE* output_ptr[TILE_M, TILE_N] = C + output_offset;
      bool write_mask[TILE_M, TILE_N] = (out_row[:, newaxis] < rows_A) && (out_col[newaxis, :] < cols_B);

#if (BLOCK_K==1)
      *?(write_mask) output_ptr = result;
#else
      // handle partial accumulation using spin-locks
      int *lock_ptr   = locks + flat_idx;
      int *counter_ptr = lock_ptr + get_num_programs(0) * get_num_programs(1);

      for(int loop = 1; loop == 1; loop = atomic_cas(lock_ptr, 0, 1));
      int counter_val = *counter_ptr;
      if(counter_val == 0)
        *?(write_mask) output_ptr = result;
      else
        *?(write_mask) output_ptr = result + *?(write_mask)output_ptr;
      atomic_xchg(counter_ptr, (counter_val + 1) % BLOCK_K);
      atomic_xchg(lock_ptr, 0);
#endif
}
    """

    @staticmethod
    def forward(ctx, input_a, input_b):
        output = _matrix_multiply._execute(input_a, input_b)
        return output

    compiled_kernels = dict()

    @staticmethod
    def _execute(a_tensor, b_tensor):
        # compile kernel on-demand if not already done
        element_type = a_tensor.dtype
        if element_type not in _matrix_multiply.compiled_kernels:
            kernel_config = {
                'TYPE' : element_type,
                'STRIDE_AM': '1', 'STRIDE_AK': 'lda',
                'STRIDE_BN': '1', 'STRIDE_BK': 'ldb',
                'TILE_M'   : [64, 128],
                'TILE_N'   : [64, 128],
                'TILE_K'   : [8, 16],
                'BLOCK_K'  : [1]
            }
            _matrix_multiply.compiled_kernels[element_type] = triton.kernel(_matrix_multiply.source_code, num_warps=[4], defines=kernel_config)

        active_kernel = _matrix_multiply.compiled_kernels[element_type]

        # prepare output tensor
        M_rows, K_cols = a_tensor.shape
        K_cols2, N_cols = b_tensor.shape
        c_output = triton.empty([M_rows, N_cols], dtype=element_type)

        # configure grid
        grid_params = lambda options: [triton.cdiv(M_rows, options.d('TILE_M')), 
                                       triton.cdiv(N_cols, options.d('TILE_N'))]

        execution_time = active_kernel(a_tensor, b_tensor, c_output, 1., M_rows, N_cols, K_cols, 
                                      a_tensor.stride(0), b_tensor.stride(0), c_output.stride(0), 
                                      grid=grid_params, bench=100)

        # print performance metrics
        print(2*M_rows*N_cols*K_cols/(execution_time*1e-6)*1e-9)
        return c_output

matrix_multiply = _matrix_multiply.apply

# test execution
