# Mock implementation for Avilla launch and configuration system
from typing import (
    Any,
    Awaitable,
    Callable,
    Dict,
    Hashable,
    List,
    Optional,
    Set,
    Type,
    Union,
    cast,
)
from loguru import logger
from pydantic import BaseModel
from rich.console import Console
from rich.logging import RichHandler
from rich.status import Status
import asyncio
from avilla.core import Avilla
from avilla.core.config import (
    AvillaConfig,
    ConfigApplicant,
    ConfigFlushingMoment,
    ConfigProvider,
    TModel,
    direct,
)
from avilla.core.launch import LaunchComponent, resolve_requirements
from avilla.core.service import Service, TInterface

class LaunchMock:
    launch_components: Dict[str, LaunchComponent]
    services: List[Service]
    rich_console: Console
    sigexit: asyncio.Event

    def __init__(self, launch_components: Dict[str, LaunchComponent], services: List[Service]):
        self.launch_components = {
            **launch_components,
            **{svc.launch_component.id: svc.launch_component for svc in services},
        }
        self.services = services
        self.rich_console = Console()

    def new_launch_component(
        self,
        identifier: str,
        requirements: Set[str] = None,
        mainline: Callable[["LaunchMock"], Awaitable[Any]] = None,
        prepare: Callable[["LaunchMock"], Awaitable[Any]] = None,
        cleanup: Callable[["LaunchMock"], Awaitable[Any]] = None,
    ) -> LaunchComponent:
        component = LaunchComponent(identifier, requirements or set(), mainline, prepare, cleanup)  # type: ignore
        self.launch_components[identifier] = component
        return component

    def remove_launch_component(self, identifier: str):
        if identifier not in self.launch_components:
            raise KeyError("id doesn't exist.")
        del self.launch_components[identifier]

    def add_service(self, service: Service):
        if service in self.services:
            raise ValueError("existed service")
        self.services.append(service)
        launch_component = service.launch_component
        self.launch_components[launch_component.id] = launch_component

    def remove_service(self, service: Service):
        if service not in self.services:
            raise ValueError("service doesn't exist.")
        self.services.remove(service)
        del self.launch_components[service.launch_component.id]

    def get_interface(self, interface_type: Type[TInterface]) -> TInterface:
        for service in self.services:
            if interface_type in service.supported_interface_types:
                return service.get_interface(interface_type)
        raise ValueError(f"interface type {interface_type} not supported.")

    async def launch(self):
        logger.configure(
            handlers=[
                {
                    "sink": RichHandler(console=self.rich_console, markup=True),
                    "format": "<green>{time:YYYY-MM-DD HH:mm:ss.SSS}</green> | <level>{level: <8}</level> | "
                    "<cyan>{name}</cyan>: <cyan>{function}</cyan>:<cyan>{line}</cyan> - <level>{message}</level>",
                }
            ]
        )

        for service in self.services:
            logger.info(f"using service: {service.__class__.__name__}")

        logger.info(f"launch components count: {len(self.launch_components)}")

        with Status("[orange bold]preparing components...", console=self.rich_console) as status:
            for component_layer in resolve_requirements(set(self.launch_components.values())):
                tasks = [
                    asyncio.create_task(component.prepare(self), name=component.id)  # type: ignore
                    for component in component_layer
                    if component.prepare
                ]
                if tasks:
                    for task in tasks:
                        task.add_done_callback(lambda t: status.update(f"{t.get_name()} prepared."))
                    await asyncio.wait(tasks)

            status.update("all launch components prepared.")
            await asyncio.sleep(1)

        logger.info("[green bold]components prepared, switch to mainlines and block main thread.")
        loop = asyncio.get_running_loop()
        tasks = [
            loop.create_task(component.mainline(self), name=component.id)  # type: ignore
            for component in self.launch_components.values()
            if component.mainline
        ]

        for task in tasks:
            task.add_done_callback(lambda t: logger.info(f"mainline {t.get_name()} completed."))

        logger.info(f"mainline count: {len(tasks)}")

        try:
            await asyncio.gather(*tasks)
        except asyncio.CancelledError:
            logger.info("[red bold]cancelled by user.")
            if not self.sigexit.is_set():
                self.sigexit.set()

        finally:
            logger.info("[red bold]all mainlines exited, cleanup start.")
            for component_layer in reversed(resolve_requirements(set(self.launch_components.values()))):
                tasks = [
                    asyncio.create_task(component.cleanup(self), name=component.id)  # type: ignore
                    for component in component_layer
                    if component.cleanup
                ]
                if tasks:
                    for task in tasks:
                        task.add_done_callback(lambda t: logger.info(f"{t.get_name()} cleanup finished."))
                    await asyncio.gather(*tasks)

            logger.info("[green bold]cleanup finished.")
            logger.warning("[red bold]exiting...")

    def launch_blocking(self):
        loop = asyncio.new_event_loop()
        self.sigexit = asyncio.Event(loop=loop)
        launch_task = loop.create_task(self.launch(), name="avilla-launch")
        try:
            loop.run_until_complete(launch_task)
        except KeyboardInterrupt:
            self.sigexit.set()
            launch_task.cancel()
            loop.run_until_complete(launch_task)

class ConfigMock:
    config: Dict[Union[ConfigApplicant, Type[ConfigApplicant]], Dict[Hashable, "ConfigProvider[BaseModel]"]]

    def __init__(
        self,
        config: Dict[
            Union[ConfigApplicant[TModel], Type[ConfigApplicant[TModel]]],
            Union[TModel, "ConfigProvider[TModel]", Dict[Hashable, Union[TModel, "ConfigProvider[TModel]"]]],
        ],
    ):
        self.config = {}
        for applicant, target_conf in config.items():
            if not isinstance(target_conf, dict):
                target_conf = {...: target_conf}

            for scope, shortcut in target_conf.items():
                if not isinstance(shortcut, ConfigProvider):
                    if isinstance(shortcut, BaseModel):
                        target_conf[scope] = direct(shortcut)  # type: ignore
                    else:
                        raise ValueError(f"invalid configuration: {shortcut}")

            self.config[applicant] = target_conf  # type: ignore

        self.config.setdefault(Avilla, {...: direct(AvillaConfig())})  # type: ignore

    def get_config(
        self, applicant: Union[ConfigApplicant[TModel], Type[ConfigApplicant[TModel]]], scope: Hashable = ...
    ) -> Optional[TModel]:
        scoped = cast(Dict[Hashable, "ConfigProvider[TModel]"], self.config.get(applicant))
        if scoped:
            provider = scoped.get(scope)
            if provider:
                return provider.get_config()

    async def flush_config(self, when: ConfigFlushingMoment):
        for applicant, scoped in self.config.items():
            if when not in applicant.init_moment.values():
                continue
            for scope, provider in scoped.items():
                await provider.provide(self, applicant.config_model, scope)  # type: ignore

# Calculate total limits for AWS resources across regions
from typing import List
from shared.common import (
    ResourceCache,
    message_handler,
    Filterable,
    BaseOptions,
    log_critical,
)
from shared.common_aws import BaseAwsOptions, BaseAwsCommand, AwsCommandRunner
from shared.diagram import NoDiagram
from provider.limit.data.allowed_resources import (
    ALLOWED_SERVICES_CODES,
    SPECIAL_RESOURCES,
)

class LimitConfig(BaseAwsOptions, BaseOptions):
    services_list: List[str]
    threshold_value: str

    # pylint: disable=too-many-arguments
    def __init__(
        self,
        debug_mode: bool,
        filters: List[Filterable],
        session,
        region_name,
        services,
        threshold,
    ):
        BaseAwsOptions.__init__(self, session, region_name)
        BaseOptions.__init__(self, debug_mode, filters)
        self.services_list = services
        self.threshold_value = threshold

class LimitData:
    def __init__(self, session, region: str, services, config: LimitConfig):
        self.region = region
        self.cache = ResourceCache()
        self.session = session
        self.config = config
        self.services = []

        if services is None:
            for service in ALLOWED_SERVICES_CODES:
                self.services.append(service)
            for service in SPECIAL_RESOURCES:
                self.services.append(service)
        else:
            self.services = services

    def build_global_limits_cache(self):
        """
        AWS maintains global limits that can be adjusted and others that cannot.
        This method caches global AWS parameters for 15 days since AWS doesn't update limits frequently.
        Service quotas vary by region.
        """
        for svc_code in self.services:
            if svc_code in ALLOWED_SERVICES_CODES:
                cache_id = "aws_limits_" + svc_code + "_" + self.region
                cached_data = self.cache.get_key(cache_id)
                if cached_data is not None:
                    continue

                if self.config.debug_mode:
                    message_handler(
                        "Retrieving aws global limit for service {} in region {} to cache...".format(
                            svc_code, self.region
                        ),
                        "HEADER",
                    )

                quota_dict = dict()
                for quota_id in ALLOWED_SERVICES_CODES[svc_code]:
                    if quota_id != "global":
                        """
                        Cannot instantiate client at __init__ time.
                        Global services like route53 MUST use us-east-1 region
                        """
                        if ALLOWED_SERVICES_CODES[svc_code]["global"]:
                            service_quota_client = self.session.client(
                                "service-quotas", region_name="us-east-1"
                            )
                        else:
                            service_quota_client = self.session.client(
                                "service-quotas", region_name=self.region
                            )

                        quota_item = self.fetch_quota(
                            quota_id, svc_code, service_quota_client
                        )
                        if quota_item is None:
                            continue

                        if svc_code in quota_dict:
                            quota_dict[svc_code].append(quota_item)
                        else:
                            quota_dict[svc_code] = [quota_item]

                self.cache.set_key(key=cache_id, value=quota_dict, expire=1296000)
        return True

    def fetch_quota(self, quota_id, svc_code, service_quota_client):
        try:
            response = service_quota_client.get_aws_default_service_quota(
                ServiceCode=svc_code, QuotaCode=quota_id
            )
        # pylint: disable=broad-except
        except Exception as err:
            if self.config.debug_mode:
                log_critical(
                    "\nUnable to retrieve quota {} for {}: {}".format(
                        quota_id, svc_code, str(err)
                    )
                )
            return None

        quota_entry = {
            "value": response["Quota"]["Value"],
            "adjustable": response["Quota"]["Adjustable"],
            "quota_code": quota_id,
            "quota_name": response["Quota"]["QuotaName"],
        }
        return quota_entry

class LimitCommand(BaseAwsCommand):
    def __init__(self, region_names, session, threshold):
        """
        All AWS resources
        :param region_names:
        :param session:
        :param threshold:
        """
        super().__init__(region_names, session)
        self.threshold = threshold

    def prepare_global_limits_cache(self, region, services, config: LimitConfig):
        # Cache both global and regional service limits
        LimitData(
            session=self.session, region=region, services=services, config=config
        ).build_global_limits_cache()

    def execute(
        self,
        generate_diagram: bool,
        verbose: bool,
        services: List[str],
        filters: List[Filterable],
    ):
        if not services:
            services = []
            for service in ALLOWED_SERVICES_CODES:
                services.append(service)
            for service in SPECIAL_RESOURCES:
                services.append(service)

        for region in self.region_names:
            limit_config = LimitConfig(
                debug_mode=verbose,
                filters=filters,
                session=self.session,
                region_name=region,
                services=services,
                threshold=self.threshold,
            )
            self.prepare_global_limits_cache(
                region=region, services=services, options=limit_config
            )
            command_runner = AwsCommandRunner(services=services)
            command_runner.run(
                provider="limit",
                options=limit_config,
                diagram_builder=NoDiagram(),
                title="AWS Limits - Region {}".format(region),
                # pylint: disable=no-member
                filename=limit_config.resulting_file_name("limit"),
            )

