DictStrHier = Dict[str, Any]
StrOrDictStrHier = Union[str, DictStrHier]

def settings_to_dict(
    settings: Union[
        None, List[str], Tuple[str, ...], Dict[str, StrOrDictStrHier], Flow.Settings
    ],
) -> Dict[str, Any]:
    if not settings:
        return {}
    if isinstance(settings, (tuple, list)):
        res: DictStrHier = {}
        for override in settings:
            sp = override.split("=")
            if len(sp) != 2:
                raise ValueError("Settings should be in KEY=VALUE format!")
            key, val = sp
            set_hierarchy(res, key, try_convert(val, convert_lists=True))
        return res
    if isinstance(settings, Flow.Settings):
        return asdict(settings)
    if isinstance(settings, dict):
        return settings
    raise TypeError(f"overrides is of unsupported type: {type(settings)}")

def print_flow_settings(flow, options: XedaOptions):
    flow_class = discover_flow_class(flow)
    schema = flow_class.Settings.schema(by_alias=True)
    type_defs = {}

    def get_type(field):
        if isinstance(field, (list, tuple)):
            return Text("|".join(str(get_type(f)) for f in field))
        typ = field.get("type")
        ref = field.get("$ref")
        if typ is None and ref:
            typ = ref.split("/")[-1]
            typ_def = schema.get("definitions", {}).get(typ)
            if typ not in type_defs:
                type_defs[typ] = typ_def
            elif type_defs[typ] != typ_def:
                log.critical(
                    "type definition for %s changed!\nPrevious def:\n %s new def:\n %s",
                    typ,
                    type_defs[typ],
                    typ_def,
                )
            return Text(typ, style="blue")
        additional = field.get("additionalProperties")
        if typ == "object" and additional:
            return Text(f"Dict[string -> {get_type(additional)}]")
        if typ == "array":
            items = field.get("items")
            if items:
                return Text(f"array[{get_type(items)}]")
        def join_types(lst, joiner, style="red"):
            return reduce(
                lambda x, y: x + Text(joiner, style) + y, (get_type(t) for t in lst)
            )
        allof = field.get("allOf")
        if allof:
            return join_types(allof, " & ")  # intersection
        anyOf = field.get("anyOf")
        if anyOf:
            return join_types(anyOf, " | ")  # union
        return Text(typ)

    table = Table(
        title=f"{flow} settings",
        show_header=True,
        header_style="bold yellow",
        title_style=Style(frame=True, bold=True),
        box=box.HEAVY_HEAD,
        show_lines=True,
    )
    table.add_column("Property", header_style="bold green", style="bold")
    table.add_column("Type", max_width=32)
    table.add_column("Default", max_width=42)
    table.add_column("Description")

    def fmt_default(v: Any) -> str:
        if isinstance(v, str):
            return f'"{v}"'
        if isinstance(v, bool):
            return str(v).lower()
        return str(v)

    for name, field in schema.get("properties", {}).items():
        if name in ["results"] or name in Flow.Settings.__fields__.keys():
            continue
        required = name in schema.get("required", [])
        desc: str = field.get("description", "")
        typ = get_type(field)
        req_or_def = (
            "[red]<required>[/red]" if required else fmt_default(field.get("default"))
        )
        table.add_row(name, typ, req_or_def, desc)
    console.print(table)

    for typ_name, typ_def in list(type_defs.items()):
        for prop, prop_def in typ_def.get("properties").items():
            get_type(prop_def)

    for typ_name, typ_def in list(type_defs.items()):
        c = "blue"
        table = Table(
            title=f"Type [{c}]{typ_name}[/{c}]",
            show_header=True,
            header_style="bold green",
            title_style=Style(frame=True, bold=True),
            box=box.SQUARE_DOUBLE_HEAD,
            show_lines=True,
        )
        if options.debug:
            console.print(f"Type: {typ_name}")
            console.print_json(data=typ_def)
        table.add_column("property")
        table.add_column("type")
        table.add_column("description")
        for prop, prop_def in typ_def.get("properties").items():
            if prop_def.get("hidden_from_schema"):
                continue
            if (
                typ_name.endswith("__Settings")
                and prop in Flow.Settings.__fields__.keys()
            ):
                continue
            desc = prop_def.get("description", prop_def.get("title", "-"))
            desc = re.sub(r"\s*\.*\s*$", "", desc)
            table.add_row(prop, get_type(prop_def), desc)
        console.print(table)

def discover_flow_class(flow: str) -> Type[Flow]:
    try:
        return get_flow_class(flow, "xeda.flows", __package__)
    except FlowNotFoundError:
        log.critical(
            "Flow %s is not known to Xeda. Please make sure the name is correctly specified.",
            flow,
        )
        sys.exit(1)

# HTTP request utility functions using aiohttp
import json
from botsdk.tool.Error import printTraceBack

async def fetchUrl(url, proxy=None, headers=None, asBytes=None):
    try:
        async with aiohttp.ClientSession(headers=headers if headers is not None else None) as clientSession:
            async with clientSession.get(url, proxy=proxy if proxy is not None else None, verify_ssl=False) as response:
                if asBytes is not None and asBytes:
                    return await response.read()
                return await response.text()
    except Exception as error:
        printTraceBack()
        return None

async def sendPostRequest(url, payload, asBytes=None):
    try:
        async with aiohttp.ClientSession() as clientSession:
            async with clientSession.post(url, data=json.dumps(payload).encode("utf-8"), verify_ssl=False) as response:
                if asBytes is True:
                    return await response.read()
                return await response.text()
    except Exception as error:
        printTraceBack()
        return None

# Exporter for nanogi format (YAML-based)
import os
import bpy
from bpy_extras.io_utils import ExportHelper
from .yaml import dump
from .primCamera import *
from .primMesh import *
from .primLamp import *

bl_info = {
  "name" : "nanogi",
  "category" : "Import-Export",
  "version" : ( 0, 0 ),
  "blender" : ( 2, 7, 3 )
}

class ExportNanogi( bpy.types.Operator, ExportHelper ):
  bl_label = "Export nanogi"
  bl_idname = "export.nanogi"
  filename_ext = ".yml"

  flag_selection = bpy.props.BoolProperty(
    name = "Selection Only",
    description = "Export selected objects only",
    default = False
  )

  def export_scene( self, filepath ):
    # Initialize output structure
    directory = os.path.dirname( filepath ) + "/"
    result = {
      "version" : 5,
      "scene" : {
        "primitives" : []
      }
    }

    # Store current selection state
    original_selection = []
    for obj in bpy.context.selected_objects:
      original_selection.append( obj )
      obj.select = False

    # Collect objects to process
    candidates = []
    if self.flag_selection:
      candidates = original_selection
    else:
      for obj in bpy.data.objects:
        candidates.append( obj )

    # Process and separate meshes by material
    processed_objects = []
    for obj in candidates:
      obj.select = True
      bpy.ops.object.duplicate()
      bpy.ops.mesh.separate( type = "MATERIAL" )
      for sel_obj in bpy.context.selected_objects:
        processed_objects.append( sel_obj )
        sel_obj.select = False

    # Generate primitives for each object
    for obj in processed_objects:
      prim_data = {}
      if obj.type == "CAMERA":
        prim_data = primCamera( obj )
      elif obj.type == "MESH":
        prim_data = primMesh( obj, directory )
      elif obj.type == "LAMP":
        prim_data = primLamp( obj, directory )
      result[ "scene" ][ "primitives" ].append( prim_data )

    # Write YAML file
    with open( filepath, "w" ) as file_handle:
      file_handle.write( dump( result ) )

    # Clean up duplicate objects
    for obj in processed_objects:
      obj.select = True
    bpy.ops.object.delete()

    # Restore original selection
    for obj in original_selection:
      obj.select = True

  def execute( self, context ):
    self.export_scene( self.filepath )
    return { "FINISHED" }

def menu_func( self, context ):
    self.layout.operator( ExportNanogi.bl_idname, text = "nanogi (.yml)" )

def register():
  bpy.utils.register_module( __name__ )
  bpy.types.INFO_MT_file_export.append( menu_func )

def unregister():
  bpy.utils.unregister_module( __name__ )
  bpy.types.INFO_MT_file_export.remove( menu_func )

# Calculate the final score for the bingo game
from aoc2021.util import print_solutions, import_strs
import timeit

MARKER = "X"

def solve_part_one(game_data):
    drawn_numbers, boards_list = game_data
    for number in drawn_numbers:
        for board in boards_list:
            if update_board(board, number) and is_winning(board):
                return calculate_score(board) * number
    return None

def calculate_score(board):
    total = 0
    for value in sum(board, []):
        if value != MARKER:
            total += value
    return total

def update_board(board, number):
    found = False
    for row in board:
        for col_index, value in enumerate(row):
            if value == number:
                row[col_index] = MARKER
                found = True
    return found

def is_winning(board):
    columns = []
    for index in range(len(board[0])):
        columns.append([row[index] for row in board])

    for line in board + columns:
        if not [n for n in line if n != MARKER]:
            return True
    return False

def parse_bingo_input(file_path):
    with open(file_path) as file:
        lines = file.readlines()

    first_line = lines[0].strip()
    drawn = [int(num) for num in first_line.split(",")]
    lines.pop(0)

    current_board = []
    all_boards = []

    for line in lines:
        line = line.strip()
        if not line:
            if current_board:
                all_boards.append(current_board)
                current_board = []
            continue

        row_values = [int(num) for num in line.split() if num]
        current_board.append(row_values)

    if current_board:
        all_boards.append(current_board)

    return (drawn, all_boards)

def solve_part_two(game_data):
    drawn_numbers, boards_list = game_data
    final_score = None

    for number in drawn_numbers:
        # Remove already completed boards
        boards_list[:] = [b for b in boards_list if b]
        if not boards_list:
            break

        for idx, board in enumerate(boards_list):
            # Debug output for specific condition
            if calculate_score(board) == 148:
                print(board)

            if update_board(board, number) and is_winning(board):
                final_score = calculate_score(board) * number
                boards_list[idx] = None

    return final_score

def execute():
    print_solutions(
        ["resources/day4-test.txt", "resources/day4.txt"],
        #["resources/day4-test.txt"],
        parse_bingo_input,
        solve_part_two
    )

if __name__ == "__main__":
    execute()

