# Calculate hash of a database file using SHA-256
import hashlib
from .utils import (
    detect_spatialite,
    detect_fts,
    escape_sqlite,
    get_all_foreign_keys,
    sqlite3
)

HASH_BLOCK_SIZE = 1024 * 1024

def inspect_hash(file_path):
    " Compute the SHA-256 hash of a database file in an efficient manner. "
    hasher = hashlib.sha256()
    with file_path.open("rb") as file_handle:
        while True:
            chunk = file_handle.read(HASH_BLOCK_SIZE)
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.hexdigest()

def inspect_views(connection):
    " Retrieve a list of views present in the database. "
    return [row[0] for row in connection.execute('select name from sqlite_master where type = "view"')]

def detect_label_column(column_list):
    """ Identify the label column for display purposes during joins.
        If a table has exactly two columns and one is named 'id', 
        the other column is considered the label column.
    """
    if (column_list and len(column_list) == 2 and "id" in column_list):
        return [col for col in column_list if col != "id"][0]
    return None

def detect_primary_keys(connection, table_name):
    " Determine the primary key columns for a given table. "
    table_info_rows = [
        row
        for row in connection.execute(
            'PRAGMA table_info("{}")'.format(table_name)
        ).fetchall()
        if row[-1]  # Only include columns with non-zero pk index
    ]
    table_info_rows.sort(key=lambda row: row[-1])
    return [str(r[1]) for r in table_info_rows]

def inspect_tables(connection, db_metadata):
    " Enumerate tables and gather metadata including row counts, excluding internal/system tables. "
    tables_dict = {}
    table_names = [
        row["name"]
        for row in connection.execute(
            'select * from sqlite_master where type="table"'
        )
    ]

    for table in table_names:
        table_meta = db_metadata.get("tables", {}).get(table, {})
        try:
            row_count = connection.execute(
                "select count(*) from {}".format(escape_sqlite(table))
            ).fetchone()[0]
        except sqlite3.OperationalError:
            # May occur with FTS virtual tables like "select count(*) from some_fts;"
            row_count = 0

        column_names = [
            row[1]
            for row in connection.execute(
                "PRAGMA table_info({});".format(escape_sqlite(table))
            ).fetchall()
        ]

        tables_dict[table] = {
            "name": table,
            "columns": column_names,
            "primary_keys": detect_primary_keys(connection, table),
            "count": row_count,
            "label_column": detect_label_column(column_names),
            "hidden": table_meta.get("hidden") or False,
            "fts_table": detect_fts(connection, table),
        }

    # Add foreign key information
    fk_info = get_all_foreign_keys(connection)
    for table, fks in fk_info.items():
        tables_dict[table]["foreign_keys"] = fks

    # Identify tables to hide (FTS virtual tables and Spatialite internals)
    hidden_tables = [
        row["name"]
        for row in connection.execute(
            """
                select name from sqlite_master
                where rootpage = 0
                and sql like '%VIRTUAL TABLE%USING FTS%'
            """
        )
    ]

    if detect_spatialite(connection):
        # Append Spatialite-specific internal table names
        hidden_tables += [
            "ElementaryGeometries",
            "SpatialIndex",
            "geometry_columns",
            "spatial_ref_sys",
            "spatialite_history",
            "sql_statements_log",
            "sqlite_sequence",
            "views_geometry_columns",
            "virts_geometry_columns",
        ] + [
            row["name"]
            for row in connection.execute(
                """
                    select name from sqlite_master
                    where name like "idx_%"
                    and type = "table"
                """
            )
        ]

    # Mark matching tables as hidden
    for t in tables_dict.keys():
        for hidden_table in hidden_tables:
            if t == hidden_table or t.startswith(hidden_table):
                tables_dict[t]["hidden"] = True
                break

    return tables_dict

# Clone a git repository and collect Python files
import os
import subprocess
import tempfile
from typing import (
    Dict,
    Iterator,
)

class GitProject(object):
    """Represents a git repository containing a python project."""
    def __init__(self, url: str) -> None:
        self.contents = dict()  # type: Dict[str, str]
        try:
            with tempfile.TemporaryDirectory() as tmpdir:
                subprocess.run(['git', 'clone', url, tmpdir])
                for filepath in self._list_python_files(tmpdir):
                    try:
                        with open(filepath, 'r') as source_file:
                            self.contents[filepath] = source_file.read()
                    except Exception as err:
                        print(f'Failed to read file {filepath}: {err}')
        except Exception as err:
            print(f'Could not create temporary directory: {err}')

    def _list_python_files(self, directory: str) -> Iterator[str]:
        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    yield os.path.join(root, file)

    @property
    def py_files(self) -> Dict[str, str]:
        return self.contents

# Generate plots for performance metrics
import json
from pathlib import Path
import click
import matplotlib.pyplot as plt
from ..common import METRICS

@click.command()
@click.option("--datadir", help="Directory containing the dataset.", required=True, type=click.Path())
@click.option("--outdir", help="Directory where to create plots.", required=True, type=click.Path())
@click.option("--configurations", help="Comma separated list of configurations.", required=True)
@click.option("--nodes", help="Comma separated list of nodes.", required=True)
def generate(datadir, outdir, configurations, nodes):
    create_plots(datadir, outdir, configurations.split(","), nodes.split(","))

def create_plots(datadir, outdir, configs, node_list):
    # Load samples
    data_samples = {}
    for config in configs:
        data_samples[config] = {}
        for node_count in node_list:
            samples_file = f"{datadir}/{config}/{node_count}nodes/samples.json"
            with open(samples_file) as f:
                data_samples[config][str(node_count)] = json.load(f)

    for metric_name in [m["name"] for m in METRICS]:
        dataset = {}

        # Build dataset
        for config in configs:
            dataset[config] = [
                [float(val) for val in data_samples[config][str(node)][f"{metric_name}Sample"].split(",")] 
                for node in node_list
            ]

        # Create figure
        figure, axis = plt.subplots(figsize=(10, 5), layout="constrained")

        # Set titles and labels
        axis.set_title(f"AWS ParallelCluster\n{metric_name}", fontweight="bold")
        axis.set_xlabel("Compute Nodes", fontweight="bold")
        unit = next(m['unit'] for m in METRICS if m['name'] == metric_name)
        axis.set_ylabel(f"Time ({unit})", fontweight="bold")

        num_configs = len(configs)
        num_nodes = len(node_list)
        all_positions = [i for i in range(1, num_configs * num_nodes + 1)]

        # Create box plots
        plot_handles = {}
        for config in configs:
            start_idx = configs.index(config)
            positions = all_positions[start_idx :: num_configs]
            plot_handles[config] = axis.boxplot(
                dataset[config],
                patch_artist=True,
                boxprops=dict(facecolor="palegreen" if config == "baseline" else "steelblue"),
                labels=node_list,
                positions=positions,
            )

        # Add legend
        legend_entries = [plot_handles[bp]["boxes"][0] for bp in plot_handles]
        axis.legend(legend_entries, configs, loc="upper left")

        # Save plot
        output_path = Path(f"{outdir}/{metric_name}.png")
        output_path.parent.mkdir(parents=True, exist_ok=True)
        plt.savefig(output_path.absolute())

# Test suite for resolver functionality
import itertools
import unittest
import click
from click.testing import CliRunner, Result
from class_resolver import Resolver, UnexpectedKeywordError

try:
    import ray.tune as tune
except ImportError:
    tune = None

class Parent:
    """A parent class."""
    def __init__(self, label):
        """Initialize the class."""
        self.label = label

    def __eq__(self, other) -> bool:
        """Check two instances are equal."""
        return type(self) == type(other) and self.label == other.label

class X(Parent):
    """X derived class."""

class Y(Parent):
    """Y derived class."""

class Z(Parent):
    """Z derived class."""

class DifferentBase:
    """Another base class."""

class XDiff(DifferentBase):
    """X in different hierarchy."""

class TestResolverSuite(unittest.TestCase):
    """Tests for the resolver class."""

    def setUp(self) -> None:
        """Set up test fixtures."""
        self.resolver = Resolver([X, Y, Z], base=Parent)

    def test_class_lookup(self):
        """Test resolving classes by name."""
        self.assertEqual(X, self.resolver.lookup("x"))
        self.assertEqual(X, self.resolver.lookup("X"))

    def test_class_iteration(self):
        """Test iterating over registered classes."""
        self.assertEqual([X, Y, Z], list(self.resolver))

    def test_instantiation(self):
        """Test creating class instances."""
        identifier = "alice"
        # Test with positional dict passed as kwargs
        self.assertEqual(X(label=identifier), self.resolver.make("x", {"label": identifier}))
        # Test with keyword arguments
        self.assertEqual(X(label=identifier), self.resolver.make("x", label=identifier))

    def test_instantiation_from_kwargs(self):
        """Test creating instances using nested kwargs structure."""
        identifier = "alice"
        self.assertEqual(
            X(label=identifier),
            self.resolver.make_from_kwargs(
                key="enigma",
                data=dict(
                    filler=...,
                    enigma="x",
                    enigma_kwargs=dict(
                        label=identifier,
                    ),
                ),
            ),
        )

    def test_instance_passthrough(self):
        """Test that existing instances pass through unchanged."""
        x_instance = X(label="alice")
        self.assertEqual(x_instance, self.resolver.make(x_instance))

    @unittest.skipIf(tune is None, "ray[tune] not properly installed")
    def test_ray_tune_integration(self):
        """Test ray tune search space generation."""
        search_space = self.resolver.ray_tune_search_space(
            kwargs_search_space=dict(
                label=tune.choice(["alice", "bob"]),
            ),
        )
        for spec in itertools.islice(
            tune.suggest.variant_generator.generate_variants(search_space), 2
        ):
            config = {k[0]: v for k, v in spec[0].items()}
            query = config.pop("query")
            instance = self.resolver.make(query=query, pos_kwargs=config)
            self.assertIsInstance(instance, Parent)

    def test_invalid_click_option(self):
        """Test error when no default provided for click option."""
        with self.assertRaises(ValueError):
            self.resolver.get_option("--choice")  # missing default

    def test_click_integration(self):
        """Test CLI integration with click."""
        @click.command()
        @self.resolver.get_option("--choice", default="x")
        def cli(choice):
            """Execute CLI command."""
            self.assertIsInstance(choice, type)
            click.echo(choice.__name__, nl=False)
        self._run_cli_test(cli)

    def _run_cli_test(self, cli):
        runner = CliRunner()
        # Test default behavior
        result: Result = runner.invoke(cli, [])
        self.assertEqual(X.__name__, result.output)
        # Test explicit canonical name
        result: Result = runner.invoke(cli, ["--choice", "X"])
        self.assertEqual(X.__name__, result.output)
        # Test case-insensitive name
        result: Result = runner.invoke(cli, ["--choice", "x"])
        self.assertEqual(X.__name__, result.output)

    def test_click_string_mode(self):
        """Test CLI option returning string instead of class."""
        @click.command()
        @self.resolver.get_option("--choice", default="x", as_string=True)
        def cli(choice):
            """Execute CLI command."""
            self.assertIsInstance(choice, str)
            click.echo(self.resolver.lookup(choice).__name__, nl=False)
        self._run_cli_test(cli)

    def test_argument_support_check(self):
        """Verify argument support detection."""
        self.assertTrue(self.resolver.supports_argument("X", "label"))
        self.assertFalse(self.resolver.supports_argument("X", "invalid_param"))

    def test_unexpected_kwarg_handling(self):
        """Verify proper exception handling for unexpected kwargs."""
        resolver = Resolver.from_subclasses(DifferentBase)
        with self.assertRaises(UnexpectedKeywordError) as exc_info:
            resolver.make("X", invalid_arg="wrong_value")
            self.assertEqual("XDiff did not expect any keyword arguments", str(exc_info.exception))

# Modified version of the original code with Type I clone transformations
import enum
import logging
from typing import Any, Callable, Dict, Iterable, List, Optional, Tuple
from .schema_utils import JsonSchema, SchemaEnum

logger = logging.getLogger(__name__)

class DiscoveredEnums(object):
    def __init__(
        self,
        enums: Optional[SchemaEnum] = None,
        children: Optional[Dict[str, "DiscoveredEnums"]] = None,
    ) -> None:
        self.enums = enums
        self.children = children

    def __str__(self) -> str:
        def value_to_string(val):
            if val is None:
                return "null"
            elif isinstance(val, str):
                return f"'{val}'"
            else:
                return str(val)

        enum_str = ""
        if self.enums:
            enum_list = [value_to_string(v) for v in self.enums]
            enum_str = ", ".join(sorted(enum_list))

        child_str = ""
        if self.children:
            child_items = [f"{str(key)}->{str(child)}" for key, child in self.children.items()]
            child_str = ",".join(child_items)

        if enum_str and child_str:
            enum_str = enum_str + "; "

        return "<" + enum_str + child_str + ">"

def schemaToDiscoveredEnums(schema: JsonSchema) -> Optional[DiscoveredEnums]:
    """Given a schema, returns a positive enumeration set.
    This is very conservative, and even includes negated enum constants
    (since the assumption is that they may, in some contexts, be valid)
    """
    def combineDiscoveredEnums(
        combiner: Callable[[Iterable[SchemaEnum]], Optional[SchemaEnum]],
        des: Iterable[Optional[DiscoveredEnums]],
    ) -> Optional[DiscoveredEnums]:
        enums_list: List[SchemaEnum] = []
        children_map: Dict[str, List[DiscoveredEnums]] = {}

        for de in des:
            if de is None:
                continue

            if de.enums is not None:
                enums_list.append(de.enums)

            if de.children is not None:
                for cn, cv in de.children.items():
                    if cv is None:
                        continue
                    if cn in children_map:
                        children_map[cn].append(cv)
                    else:
                        children_map[cn] = [cv]

        combined_enums: Optional[SchemaEnum] = None
        if enums_list:
            combined_enums = combiner(enums_list)

        if not children_map:
            if combined_enums is None:
                return None
            else:
                return DiscoveredEnums(enums=combined_enums)
        else:
            combined_children: Dict[str, DiscoveredEnums] = {}
            for ccn, ccv in children_map.items():
                if not ccv:
                    continue
                ccvc = combineDiscoveredEnums(combiner, ccv)
                if ccvc is not None:
                    combined_children[ccn] = ccvc
            return DiscoveredEnums(enums=combined_enums, children=combined_children)

    def joinDiscoveredEnums(
        des: Iterable[Optional[DiscoveredEnums]],
    ) -> Optional[DiscoveredEnums]:
        def union_op(args: Iterable[SchemaEnum]) -> Optional[SchemaEnum]:
            return set.union(*args)
        return combineDiscoveredEnums(union_op, des)

    def meetDiscoveredEnums(
        des: Tuple[Optional[DiscoveredEnums], ...]
    ) -> Optional[DiscoveredEnums]:
        def intersection_op(args: Iterable[SchemaEnum]) -> Optional[SchemaEnum]:
            return set.intersection(*args)
        return combineDiscoveredEnums(intersection_op, des)

    if schema is True or schema is False:
        return None

    if "enum" in schema:
        # TODO: we should validate the enum elements according to the schema, like schema2search_space does
        return DiscoveredEnums(enums=set(schema["enum"]))

    if "type" in schema:
        typ = schema["type"]
        if typ == "object" and "properties" in schema:
            props = schema["properties"]
            result_dict: Dict[str, DiscoveredEnums] = {}
            for prop_name, prop_schema in props.items():
                prop_result = schemaToDiscoveredEnums(prop_schema)
                if prop_result is not None:
                    result_dict[prop_name] = prop_result
            if result_dict:
                return DiscoveredEnums(children=result_dict)
            else:
                return None
        else:
            return None

    if "not" in schema:
        neg_result = schemaToDiscoveredEnums(schema["not"])
        return neg_result

    if "allOf" in schema:
        posl = [schemaToDiscoveredEnums(s) for s in schema["allOf"]]
        return joinDiscoveredEnums(posl)

    if "anyOf" in schema:
        posl = [schemaToDiscoveredEnums(s) for s in schema["anyOf"]]
        return joinDiscoveredEnums(posl)

    if "oneOf" in schema:
        posl = [schemaToDiscoveredEnums(s) for s in schema["oneOf"]]
        return joinDiscoveredEnums(posl)

    return None

def accumulateDiscoveredEnumsToPythonEnums(
    de: Optional[DiscoveredEnums], path: List[str], acc: Dict[str, enum.Enum]
) -> None:
    def withEnumValue(e: str) -> Tuple[str, Any]:
        if isinstance(e, str):
            return (e.replace("-", "_"), e)
        elif isinstance(e, (int, float, complex)):
            return ("num" + str(e), e)
        else:
            logger.info(
                f"Unknown type ({type(e)}) of enumeration constant {e}, not handling very well"
            )
            return (str(e), e)

    if de is None:
        return

    if de.enums is not None:
        ppath, _ = withEnumValue("_".join(path))
        epath = ".".join(path)
        vals = (withEnumValue(x) for x in de.enums if x is not None)
        # pyright does not currently understand this form
        acc[ppath] = enum.Enum(epath, vals)  # type: ignore

    if de.children is not None:
        for k in de.children:
            accumulateDiscoveredEnumsToPythonEnums(de.children[k], [k] + path, acc)

def discoveredEnumsToPythonEnums(de: Optional[DiscoveredEnums]) -> Dict[str, enum.Enum]:
    acc: Dict[str, enum.Enum] = {}
    accumulateDiscoveredEnumsToPythonEnums(de, [], acc)
    return acc

def schemaToPythonEnums(schema: JsonSchema) -> Dict[str, enum.Enum]:
    de = schemaToDiscoveredEnums(schema)
    enums = discoveredEnumsToPythonEnums(de)
    return enums

def addDictAsFields(obj: Any, d: Dict[str, Any], force=False) -> None:
    if d is None:
        return
    for k, v in d.items():
        if k == "":
            logger.warning(
                f"There was a top level enumeration specified, so it is not being added to {obj._name}"
            )
        elif hasattr(obj, k) and not force:
            logger.error(
                f"The object {obj._name} already has the field {k}.  This conflicts with our attempt at adding that key as an enumeration field"
            )
        else:
            setattr(obj, k, v)

def addSchemaEnumsAsFields(obj: Any, schema: JsonSchema, force=False) -> None:
    enums = schemaToPythonEnums(schema)
    addDictAsFields(obj, enums, force)

import os
import xml.etree.ElementTree as ET
from pathlib import Path
from pprint import pprint
from typing import Dict, Optional
from .abstract_commands import AbstractCommands
_LOGGER = logging.getLogger(__name__)

class IRCommands:
    ir_data: Dict[str, bytes] = {}

    def __init__(self, config_file: str, converter: AbstractCommands):
        self.converter = converter
        config_path = Path(os.getcwd(), f"usr/share/{config_file}.xml")

        if config_path.exists():
            root_elem = ET.parse(config_path).getroot()
            for item in root_elem.findall("remote/code"):
                signal_name = item.attrib["name"]
                ccf_node = item.find("ccf")

                if ccf_node is not None and ccf_node.text is not None:
                    # Reorder byte pairs from big-endian to little-endian format
                    hex_bytes = " ".join(
                        map(lambda x: x[2:4] + x[0:2], ccf_node.text.split(" "))
                    )
                    self.ir_data[signal_name] = bytes.fromhex(hex_bytes)
                else:
                    _LOGGER.error("Failed to parse CCF data from %s", config_path)
        else:
            raise FileNotFoundError(
                f"Configuration file missing at {config_path}"
            )

    def get_state(self) -> Dict[str, str]:
        return self.converter.get_state()

    def resolve(self, name: str) -> Optional[bytes]:
        pprint(name)
        if name in self.ir_data:
            return self.ir_data[name]
        else:
            _LOGGER.error("Unknown command: %s", name)
            return None

    def get(self, updates: dict) -> str:
        return self.converter.get_command_from_state(updates)

# Pattern matching implementation with dataclass-based branches
from dataclasses import dataclass, field
import sys
from typing import (
    Any,
    Callable,
    Optional,
    Tuple,
    Union,
    Dict,
    ClassVar,
    Generic,
    TypeVar,
    Type,
    List,
)
from .composition import Compose
from .interface import Interface, implements, isimplementation

__all__ = ("match", "_")

def match(target: Any, *branches: MatchBranch) -> Any:
    """Match a target to patterns and evaluate expressions based on the first matching pattern.

    :param target: the target to perform branch checks on
    :param branches: the branches to check
    """
    if not all(isimplementation(branch, _IMatchBranch) for branch in branches):
        raise TypeError("Custom branches must implement `_IMatchBranch` interface.")
    for idx, branch in enumerate(branches):
        check_result = branch.check(target)
        if check_result is not None:
            return branch.apply(check_result)
    return None

@dataclass
class _MatchBranchData:
    """MatchBranch data holder."""
    check_val: Any = field(init=False, default=None)
    func: Callable = field(init=False, default=lambda: None)

class _IMatchBranch(Interface):
    """MatchBranch interface."""
    def check(self, target: Any) -> Optional[Tuple]:
        ...

@implements(_IMatchBranch)
class MatchBranch(
    Compose(_MatchBranchData, "check_val", name="_mb")  # type: ignore
):
    """Match branch with no checks."""
    def __init_subclass__(cls, symbol: Optional[str] = None) -> None:
        if symbol is not None:
            setattr(MatchBranch, symbol, cls)

    def __init__(self, check_val: Any = None):
        super().__init__()
        self.check_val = check_val

    def __rshift__(self, result: Any) -> MatchBranch:
        setattr(self._mb, "func", result if callable(result) else (lambda: result))
        return self

    def check(self, target: Any) -> Optional[Tuple]:
        return tuple()

    def apply(self, args: Tuple) -> Any:
        return self._mb.func(*args)

_ = MatchBranch

@implements(_IMatchBranch)
class Literal(MatchBranch, symbol="l"):
    """Matching branch with a literal compare value."""
    check_val: Any

    def check(self, target: Any) -> Optional[Tuple]:
        if self.check_val == target:
            return tuple()
        return None

@implements(_IMatchBranch)
class Conditional(MatchBranch, symbol="c"):
    """Matching branch with a conditional."""
    check_val: Callable

    def check(self, target: Any) -> Optional[Tuple]:
        if self.check_val(target):
            return (target,)
        return None

@implements(_IMatchBranch)
class Struct(MatchBranch, symbol="s"):
    """Matching branch with 'struct' decomposition."""
    _type: type
    check_val: Tuple[Tuple, Dict]

    def __init__(self, *args, **kwargs):
        super().__init__()
        self.check_val = (args, kwargs)

    def __class_getitem__(cls, type_: type) -> Type[Struct]:
        return type(f"{type_.__name__}MatchBrach", (Struct,), {"_type": type_})

    def check(self, target: Any) -> Optional[Tuple]:
        if isinstance(target, self._type):
            args, kwargs = self.check_val
            try:
                if all(
                    getattr(target, attr) == val
                    if not callable(val)
                    else val(getattr(target, attr))
                    for attr, val in kwargs.items()
                ):
                    return tuple(getattr(target, attr) for attr in args)
            except AttributeError:
                ...
        return None

