import enum
from .device import _WiserDevice
from .rest_controller import _WiserRestController
from .schedule import _WiserSchedule
from .const import (
    WISERSMARTPLUG,
    WISERDEVICE,
    TEXT_UNKNOWN,
    TEXT_AUTO,
    TEXT_MANUAL,
    TEXT_OFF,
    TEXT_ON,
    TEXT_NO_CHANGE
)

class SmartPlugModeEnum(enum.Enum):
    auto = TEXT_AUTO
    manual = TEXT_MANUAL

class AwayActionEnum(enum.Enum):
    off = TEXT_OFF
    nochange = TEXT_NO_CHANGE

import inspect

class _WiserSmartPlug(_WiserDevice):
    """Class representing a Wiser Smart Plug device"""

    def __init__(self, wiser_rest_controller: _WiserRestController, data: dict, device_type_data: dict, schedule: _WiserSchedule):
        super().__init__(data)
        self._wiser_rest_controller = wiser_rest_controller
        self._device_type_data = device_type_data
        self._schedule = schedule
        self._away_action = device_type_data.get("AwayAction", TEXT_UNKNOWN)
        self._mode = device_type_data.get("Mode", TEXT_UNKNOWN)
        self._name = device_type_data.get("Name", TEXT_UNKNOWN)
        self._device_lock_enabled = data.get("DeviceLockEnabled", False)
        self._output_state = device_type_data.get("OutputState", TEXT_OFF)

    def _send_command(self, cmd: dict, device_level: bool = False):
        """
        Send control command to the smart plug
        param cmd: json command structure
        return: boolean - true = success, false = failed
        """
        if device_level:
            result = self._wiser_rest_controller._send_command(WISERDEVICE.format(self.id), cmd)
        else:
            result = self._wiser_rest_controller._send_command(WISERSMARTPLUG.format(self.id), cmd)
        if result:
            _LOGGER.debug(
                "Wiser smart plug - {} command successful".format(
                    inspect.stack()[1].function
                )
            )
        return result

    def _validate_mode(self, mode: str) -> bool:
        for available_mode in self.available_modes:
            if mode.lower() == available_mode.lower():
                return True
        return False

    def _validate_away_action(self, action: str) -> bool:
        for available_action in self.available_away_mode_actions:
            if action.lower() == available_action.lower():
                return True
        return False

    @property
    def available_modes(self):
        return [mode.value for mode in SmartPlugModeEnum]

    @property
    def available_away_mode_actions(self):
        return [action.value for action in AwayActionEnum]

    @property
    def away_mode_action(self) -> str:
        """Get or set the away action of the smart plug (off or no change)"""
        return AwayActionEnum[self._away_action.lower()].value

    @away_mode_action.setter
    def away_mode_action(self, action: str):
        if self._validate_away_action(action):
            if self._send_command({"AwayAction": AwayActionEnum[action.lower()].value}):
                self._away_action = AwayActionEnum[action.lower()].value
        else:
            raise ValueError(f"{action} is not a valid Smart Plug away mode action.  Valid modes are {self.available_away_mode_actions}")

    @property
    def control_source(self) -> str:
        """Get the current control source of the smart plug"""
        return self._device_type_data.get("ControlSource", TEXT_UNKNOWN)

    @property
    def delivered_power(self) -> int:
        """Get the amount of energy consumed by the plug over time"""
        return self._device_type_data.get("CurrentSummationDelivered", -1)

    @property
    def device_lock_enabled(self) -> bool:
        """Get or set smart plug device lock"""
        return self._device_lock_enabled

    @device_lock_enabled.setter
    def device_lock_enabled(self, enable: bool):
        if self._send_command({"DeviceLockEnabled": enable}, True):
            self._device_lock_enabled = enable

    @property
    def instantaneous_power(self) -> int:
        """Get the amount of power currently drawn through the plug"""
        return self._device_type_data.get("InstantaneousDemand", -1)

    @property
    def manual_state(self) -> str:
        """Get the current manual mode setting of the smart plug"""
        return self._device_type_data.get("ManualState", TEXT_UNKNOWN)

    @property
    def mode(self) -> str:
        """Get or set the current mode of the smart plug (Manual or Auto)"""
        return SmartPlugModeEnum[self._mode.lower()].value

    @mode.setter
    def mode(self, mode: str):
        if self._validate_mode(mode):
            if self._send_command({"Mode": SmartPlugModeEnum[mode.lower()].value}):
                self._mode = SmartPlugModeEnum[mode.lower()].value
        else:
            raise ValueError(f"{mode} is not a valid Smart Plug mode.  Valid modes are {self.available_modes}")

    @property
    def name(self) -> str:
        """Get or set the name of the smart plug"""
        return self._name

    @name.setter
    def name(self, name: str):
        if self._send_command({"Name": name}):
            self._name = name

    @property
    def is_on(self) -> bool:
        """Get if the smart plug is on"""
        return True if self._output_state == TEXT_ON else False

    @property
    def room_id(self) -> int:
        """Get smart plug room id"""
        return self._device_type_data.get("RoomId", 0)

    @property
    def schedule(self):
        """Get the schedule of the smart plug"""
        return self._schedule

    @property
    def scheduled_state(self) -> str:
        """Get the current scheduled state of the smart plug"""
        return self._device_type_data.get("ScheduledState", TEXT_UNKNOWN)

    def turn_on(self) -> bool:
        """
        Turn on the smart plug
        return: boolean
        """
        result = self._send_command({"RequestOutput": TEXT_ON})
        if result:
            self._output_state = TEXT_ON
        return result

    def turn_off(self) -> bool:
        """
        Turn off the smart plug
        return: boolean
        """
        result = self._send_command({"RequestOutput": TEXT_OFF})
        if result:
            self._output_state = TEXT_OFF
        return result


class _WiserSmartPlugCollection(object):
    """Class holding all wiser smart plugs"""
    def __init__(self):
        self._smartplugs = []

    @property
    def all(self) -> list:
        return list(self._smartplugs)

    @property
    def available_modes(self):
        return [mode.value for mode in SmartPlugModeEnum]

    @property
    def count(self) -> int:
        return len(self.all)

    # Smartplugs
    def get_by_id(self, id: int) -> _WiserSmartPlug:
        """
        Gets a SmartPlug object from the SmartPlugs id
        param id: id of smart plug
        return: _WiserSmartPlug object
        """
        try:
            return [plug for plug in self.all if plug.id == id][0]
        except IndexError:
            return None

# Utility functions for safe dictionary access and flattening/unflattening
from __future__ import annotations
import typing as t

T = t.TypeVar("T")

def safe_get(
    data: t.Dict[object, object],
    /,
    field: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
) -> t.Optional[T]:
    """Safely retrieve a value from the dictionary using the specified key.
    Returns None if the key is not present or the value is None.
    :raises: ValueError if the value exists but does not match the expected type.
    """
    if transform is None:
        result = data.get(field)
    else:
        result = transform(data, field)

    if result is not None and not isinstance(result, expected_type):
        raise ValueError(
            f"{data}: {repr(field)}: {repr(result)}: invalid type {type(result)}, expecting {expected_type}"
        )
    return t.cast(T, result)

def mandatory_get(
    data: t.Dict[object, object],
    /,
    field: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
    fallback: t.Optional[T] = None,
    factory: t.Optional[t.Callable[[], T]] = None,
) -> T:
    """Retrieve a required value from the dictionary using the specified key.
    Raises ValueError if the value is missing and no fallback/factory is provided.
    :raises: ValueError if value is missing and no fallback/factory is available.
    """
    value: t.Optional[T] = safe_get(data, field, expected_type, transform=transform)
    if value is None:
        if fallback is not None:
            return fallback
        if factory is not None:
            return factory()
        raise ValueError(f"{data}: {repr(field)}: value is required")
    return value

def compress_dict(source: t.Dict[t.Any, t.Any]) -> t.Dict[str, object]:
    """Flatten a nested dictionary into a single-level dictionary with composite keys.
    :param dict source: The nested dictionary to compress.
    :rtype: dict
    :example:
    .. code-block:: python
        compress_dict({"a": 1, "b": {"c": 2, "d": {"e": 3, "f": 4}}})
        # {
        #     "a": 1,
        #     "b:c": 2,
        #     "b:d:e": 3,
        #     "b:d:f": 4,
        # }
    """
    def generate_pairs() -> t.Iterable[t.Tuple[str, object]]:
        for key, value in source.items():
            if not isinstance(key, str):
                raise ValueError(f"{key}: expected {str}, but got {type(key)}")
            if isinstance(value, dict):
                for subkey, subvalue in compress_dict(value).items():
                    if not isinstance(subkey, str):
                        raise ValueError(
                            f"{subkey}: expected {str}, but got {type(subkey)}"
                        )
                    yield key + ":" + subkey, subvalue
            else:
                yield key, value
    return dict(generate_pairs())

def expand_dict(compressed: t.Dict[object, object]) -> t.Dict[object, object]:
    """Reconstruct a nested dictionary from its flattened representation.
    :param dict compressed: The flattened dictionary to expand.
    :rtype: dict
    :example:
    .. code-block:: python
        expand_dict({"a": 1, "b:c": 2, "b:d:e": 3, "b:d:f": 4})
        # {
        #   "a": 1,
        #   "b": {"c": 2, "d": {"e": 3, "f": 4}},
        # }
    """
    result: t.Dict[object, object] = {}
    for key, value in compressed.items():
        if not isinstance(key, str):
            raise ValueError(f"{key}: expected {str}, but got {type(key)}")
        if ":" in key:
            current: t.Union[object, t.Dict[object, object]] = result
            parts = key.split(":")
            length = len(parts)
            for idx in range(length):
                part = parts[idx]
                if not isinstance(current, dict):
                    continue
                if part not in current:
                    current[part] = value if idx == (length - 1) else {}
                current = current[part]
        else:
            result[key] = value
    return result

# Utility functions for datetime and dictionary handling
from collections import defaultdict
import pytz

def get_current_utc_datetime() -> datetime.datetime:
    """Returns the current UTC datetime (timezone aware)"""
    return datetime.datetime.now(tz=datetime.timezone.utc)

def convert_to_local_timezone(dt_obj: datetime.datetime) -> datetime.datetime:
    """Converts a datetime object to the system's local timezone"""
    return dt_obj.astimezone()

def parse_bungie_timestamp(timestamp_str: str) -> datetime.datetime:
    """Parses a Bungie-formatted timestamp string into a UTC datetime object"""
    return apply_utc_timezone(datetime.datetime.strptime(timestamp_str, "%Y-%m-%dT%H:%M:%SZ"))

def apply_utc_timezone(dt_obj: datetime.datetime) -> datetime.datetime:
    """Attaches UTC timezone information to a naive datetime object"""
    return pytz.utc.localize(dt_obj)

def transform_to_defaultdict(data_structure):
    """Recursively converts nested dictionaries/lists into defaultdict structures"""
    if isinstance(data_structure, dict):
        return defaultdict(lambda: None, {key: transform_to_defaultdict(value) for key, value in data_structure.items()})
    elif isinstance(data_structure, list):
        return [transform_to_defaultdict(item) for item in data_structure]
    else:
        return data_structure

import click
import pandas
from dateutil import parser as dp

from pathlib import Path
from sketchy.utils import SketchySimulator, MutuallyExclusiveOption


@click.command()
@click.option(
    "--input-reads",
    "-r",
    type=Path,
    help="Path to Fast{a,q} input file used in evaluation",
    default=None,
    required=True,
    cls=MutuallyExclusiveOption,
    mutually_exclusive=["read-index"]
)
@click.option(
    "--read-index",
    "-x",
    type=Path,
    help="Path to input file read index from `sketchy utils fx-sort`",
    default=None,
    required=False,
    cls=MutuallyExclusiveOption,
    mutually_exclusive=["input-reads"]
)
@click.option(
    "--results",
    "-o",
    type=Path,
    help="Path to evaluation file from `sketchy evaluate`",
    default=None,
    required=True,
)
def fx_time(input_reads, results, read_index):

    """ Experimental: compute time to prediction from evaluation output and input reads """

    simulator = SketchySimulator(
        fastx=input_reads, fastx_index=read_index
    )

    if read_index:
        fx_data = simulator.fastx_index
    else:
        fx_data = simulator.get_run_index()

    predictions_df = pandas.read_csv(
        results, sep='\t', names=['feature', 'prediction', 'first', 'stable']
    )

    for idx, record in predictions_df.iterrows():
        first_interval, stable_interval = compute_feature_time_delta(fx_data, record)
        print(
            f"{record['feature']}\t{record['prediction']}\t{record['first']}\t"
            f"{first_interval}\t{record['stable']}\t{stable_interval}"
        )


def compute_feature_time_delta(fx_data, row):

    try:
        first_pos = int(
            row['first']
        ) - 1
        first_entry = fx_data.iloc[first_pos]
    except (TypeError, KeyError, ValueError):
        first_entry = None

    try:
        stable_pos = int(
            row['stable']
        ) - 1
        stable_entry = fx_data.iloc[stable_pos]
    except (TypeError, KeyError, ValueError):
        stable_entry = None

    reference_read = fx_data.iloc[0]

    if first_entry is not None:
        first_time_delta = \
            dp.parse(first_entry.start_time) - dp.parse(reference_read.start_time)
    else:
        first_time_delta = None

    if stable_entry is not None:
        stable_time_delta = \
            dp.parse(stable_entry.start_time) - dp.parse(reference_read.start_time)
    else:
        stable_time_delta = None

    return first_time_delta, stable_time_delta

# Process bag rules from input file
def interpret_bag_rule(rule_text: str) -> Tuple[str, List[Tuple[int, str]]]:
    outer_bag, inner_bags = rule_text.split(" bags contain ")
    bag_list = [inner.rsplit(maxsplit=1)[0].split(maxsplit=1) 
                for inner in inner_bags.split(", ") 
                if inner != "no other bags."]
    parsed_bags = [(int(amount), color) for amount, color in bag_list]
    return outer_bag, parsed_bags

# Read and parse all rules
with open("inputs/day07.txt", 'r') as file:
    bag_rules: Dict[str, List[Tuple[int, str]]] = {
        key: value for key, value in (interpret_bag_rule(line) for line in file.read().splitlines())
    }

    # Check if a bag type can eventually contain shiny gold bags
    def contains_shiny_gold(bag_type: str) -> bool:
        return bag_type in bag_rules and any(
            color == "shiny gold" or contains_shiny_gold(color) 
            for _, color in bag_rules[bag_type]
        )

    # Count total bags inside a given bag type (including the bag itself)
    def count_total_bags(bag_type: str) -> int:
        return 1 + sum(count_total_bags(color) * count 
                      for count, color in bag_rules.get(bag_type, []))

    # Part A: Count how many bag types can contain shiny gold
    result_part_a = sum(contains_shiny_gold(bag) for bag in bag_rules)
    print(f"part a: {result_part_a}")

    # Part B: Count total bags inside shiny gold bag (excluding the outermost bag)
    result_part_b = count_total_bags("shiny gold") - 1
    print(f"part b: {result_part_b}")

