# Utility functions for parameter handling and item lookup
from enum import Enum
from typing import Dict, List, TypeVar

def convert_locals_to_params(parameters: Dict) -> Dict:
    result = dict()
    for field_name in parameters:
        if field_name == "self":
            continue
        if parameters[field_name] is not None:
            data = parameters[field_name]
            if isinstance(data, Enum):
                result[field_name] = data.name
            else:
                result[field_name] = data
    return result

""" Searches for the first dictionary in a list that has an 'id' field matching the given identifier """
S = TypeVar("S")
def locate_by_identifier(identifier: str, collection: List[Dict[str, S]], report_issue=True) -> Dict[str, S]:
    from ..utils import logger
    def match_condition(entry):
        return entry["id"] == identifier
    try:
        candidates = filter(match_condition, collection)
        return next(candidates)
    except StopIteration:
        if report_issue:
            logger.error(
                f"Missing entry with id {identifier}. Available ids: {[entry['id'] for entry in collection]}"
            )
        raise

