# Event storer module for Ftrack integration with Pype
import sys
import datetime
import signal
import socket
import pymongo
import ftrack_api
from ftrack_server import FtrackServer
from pype.modules.ftrack.ftrack_server.lib import (
    SocketSession, StorerEventHub,
    get_ftrack_event_mongo_info,
    TOPIC_STATUS_SERVER, TOPIC_STATUS_SERVER_RESULT
)
from pype.modules.ftrack.lib.custom_db_connector import CustomDbConnector
from pype.api import Logger

logger = Logger().get_logger("Event storer")
process_start_time = datetime.datetime.now()

class SessionFactory:
    session = None

uri, port, database, collection_name = get_ftrack_event_mongo_info()
db_handler = CustomDbConnector(uri, database, port, collection_name)

# topics to skip processing
skip_topics = []

def setup_database():
    try:
        db_handler.install()
        db_handler._database.list_collection_names()
    except pymongo.errors.AutoReconnect:
        logger.error("Mongo server \"{}\" is not responding, exiting.".format(
            os.environ["AVALON_MONGO"]
        ))
        sys.exit(0)

def handle_event(event):
    if event.get("topic") in skip_topics:
        return

    event_payload = event._data
    event_uuid = event["id"]
    event_payload["pype_data"] = {
        "saved_at": datetime.datetime.utcnow(),
        "is_processed": False
    }

    try:
        # db_handler.insert_one(event_payload)
        db_handler.replace_one({"id": event_uuid}, event_payload, upsert=True)
        logger.debug("Event: {} stored".format(event_uuid))
    except pymongo.errors.AutoReconnect:
        logger.error("Mongo server \"{}\" is not responding, exiting.".format(
            os.environ["AVALON_MONGO"]
        ))
        sys.exit(0)
    except Exception as error:
        logger.error(
            "Event: {} failed to store".format(event_uuid),
            exc_info=True
        )

def synchronize_data(event):
    session = SessionFactory.session
    origin_id = event.get("source", {}).get("id")
    if not origin_id or origin_id != session.event_hub.id:
        return

    if session is None:
        logger.warning("Session is not set. Can't trigger Sync to avalon action.")
        return True

    projects = session.query("Project").all()
    if not projects:
        return True

    filter_query = {
        "pype_data.is_processed": False,
        "topic": "ftrack.action.launch",
        "data.actionIdentifier": "sync.to.avalon.server"
    }
    update_operation = {
        "$set": {"pype_data.is_processed": True}
    }
    db_handler.update_many(filter_query, update_operation)

    selected_items = []
    for project in projects:
        if project["status"] != "active":
            continue
        auto_sync_enabled = project["custom_attributes"].get("avalon_auto_sync")
        if not auto_sync_enabled:
            continue
        selected_items.append({
            "entityId": project["id"],
            "entityType": "show"
        })

    if not selected_items:
        return

    user = session.query(
        "User where username is \"{}\"".format(session.api_user)
    ).one()
    user_info = {
        "username": user["username"],
        "id": user["id"]
    }

    for item in selected_items:
        event_info = {
            "actionIdentifier": "sync.to.avalon.server",
            "selection": [item]
        }
        session.event_hub.publish(
            ftrack_api.event.base.Event(
                topic="ftrack.action.launch",
                data=event_info,
                source=dict(user=user_info)
            ),
            on_error="ignore"
        )

def report_status(event):
    session = SessionFactory.session
    if not session:
        return

    process_identifier = event["data"].get("subprocess_id")
    if not process_identifier:
        return

    if process_identifier != os.environ["FTRACK_EVENT_SUB_ID"]:
        return

    updated_event_data = {
        "subprocess_id": os.environ["FTRACK_EVENT_SUB_ID"],
        "source": "storer",
        "status_info": {
            "created_at": process_start_time.strftime("%Y.%m.%d %H:%M:%S")
        }
    }

    new_event = ftrack_api.event.base.Event(
        topic=TOPIC_STATUS_SERVER_RESULT,
        data=updated_event_data
    )
    session.event_hub.publish(new_event)

def register_handlers(session):
    '''Registers the event handlers, subscribing required topics.'''
    setup_database()
    session.event_hub.subscribe("topic=*", handle_event)
    session.event_hub.subscribe("topic=pype.storer.started", synchronize_data)
    session.event_hub.subscribe(
        "topic={}".format(TOPIC_STATUS_SERVER), report_status
    )

def main(arguments):
    listening_port = int(arguments[-1])
    # Create a TCP/IP socket
    connection_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    # Connect the socket to the port where the server is listening
    server_endpoint = ("localhost", listening_port)
    logger.debug("Storer connected to {} port {}".format(*server_endpoint))
    connection_socket.connect(server_endpoint)
    connection_socket.sendall(b"CreatedStore")

    try:
        session = SocketSession(
            auto_connect_event_hub=True, sock=connection_socket, Eventhub=StorerEventHub
        )
        SessionFactory.session = session
        register_handlers(session)
        server_instance = FtrackServer("event")
        logger.debug("Launched Ftrack Event storer")
        server_instance.run_server(session, load_files=False)
    except pymongo.errors.OperationFailure:
        logger.error((
            "Error with Mongo access, probably permissions."
            "Check if exist database with name \"{}\""
            " and collection \"{}\" inside."
        ).format(database, collection_name))
        connection_socket.sendall(b"MongoError")
    finally:
        logger.debug("First closing socket")
        connection_socket.close()
        return 1

if __name__ == "__main__":
    # Register interrupt signal handlers
    def handle_interrupt_signal(sig, frame):
        print("You pressed Ctrl+C. Process ended.")
        sys.exit(0)

    signal.signal(signal.SIGINT, handle_interrupt_signal)
    signal.signal(signal.SIGTERM, handle_interrupt_signal)
    sys.exit(main(sys.argv))

# Modified version with renamed variables, changed literals, and reordered statements
from typing import Any, Callable, Dict

def split_bool(input_param: Any) -> Dict[str, Any]:
    """ Split query parameter into filter-bool parameters """
    if not input_param:
        return {}

    value = input_param
    if type(value) == bool:
        return dict(result=value)

    result_value = str(value).lower() in ["true", "yes", "on", "1"]
    return dict(result=result_value)

def split_comp(input_param: Any, converter: Callable[[str], Any] = str) -> Dict[str, Any]:
    """ Split query parameter into filter-comp parameters """
    if not input_param:
        return {}

    param_value = input_param
    if type(param_value) != str:
        return dict(result=param_value)

    if ":" not in str(param_value):
        return dict(result=converter(param_value))

    # param = (not:)(oper:)value(:upper)
    segments = str(param_value).split(":")
    segment_count = len(segments)
    is_negated = segments[0] == "not"

    if segment_count >= 4:
        return dict(
            negate=is_negated,
            operator=segments[1],
            result=converter(segments[2]),
            upper_bound=converter(segments[3]),
        )
    elif segment_count == 3:
        if is_negated:
            return dict(negate=is_negated, operator=segments[1], result=converter(segments[2]))
        return dict(operator=segments[0], result=converter(segments[1]), upper_bound=converter(segments[2]))
    # else segment_count == 2 (and can't be 1)
    elif is_negated:
        return dict(negate=is_negated, result=converter(segments[1]))
    return dict(operator=segments[0], result=converter(segments[1]))

def split_in(input_param: Any, converter: Callable[[str], Any] = str) -> Dict[str, Any]:
    """ Split query parameter into filter-in parameters """
    if not input_param:
        return {}

    param_value = input_param
    if type(param_value) != str:
        return dict(results=[param_value])

    if str(param_value) == "is:null":
        return dict(is_null=True)

    if ":" not in str(param_value):
        return dict(results=list(map(converter, str(param_value).split(","))))

    segments = str(param_value).split(":")
    return dict(
        negate=(segments[0] == "not"), 
        results=list(map(converter, segments[1].split(",")))
    )

def split_str(input_param: Any) -> Dict[str, Any]:
    """ Split query parameter into filter-str parameters """
    if not input_param or type(input_param) != str:
        return {}

    param_value = input_param
    if ":" not in str(param_value):
        return dict(result=param_value)

    # param = (not:)(oper:)value
    segments = str(param_value).split(":")
    segment_count = len(segments)
    is_negated = segments[0] == "not"

    if segment_count >= 3:
        return dict(negate=is_negated, operator=segments[1], result=segments[2])
    # else segment_count == 2 (and can't be 1)
    elif is_negated:
        return dict(negate=is_negated, result=segments[1])
    return dict(operator=segments[0], result=segments[1])

