import re
import os.path as path_module
from images import load_image as get_image
from medias import load_media_file as fetch_media
from utils import sanitize_string, convert_booleans

def process_game_nodes(BASE_DIR, renpy_engine, result_dict):
    '''
    Process all nodes into a usable format. The node labeled 'start' will be 
    assigned the ID '0'.
    '''
    initial_label = find_label_by_name(renpy_engine, 'start')
    actual_start = get_next_valid_node(renpy_engine, initial_label)
    pending_nodes = [actual_start]

    while len(pending_nodes) != 0:
        current_node = pending_nodes[0]
        pending_nodes = pending_nodes[1:]
        if current_node and id(current_node) not in result_dict['nodes']:
            pending_nodes += process_single_node(BASE_DIR, renpy_engine, current_node, result_dict)

    start_id = id(actual_start)
    result_dict['nodes'][0] = result_dict['nodes'][start_id]
    del result_dict['nodes'][start_id]

def find_label_by_name(renpy_engine, label_name):
    for key, node in renpy_engine.game.script.namemap.items():
        if isinstance(node, renpy.ast.Label) and node.name == label_name:
            return node

def warn_about_unknown_node(node_obj):
    info_str = node_obj.diff_info() if hasattr(node_obj, 'diff_info') else str(node_obj)
    print('[WARNING] unknown node %s: %s' % (type(node_obj).__name__, info_str))

# Processes a single node and updates result_dict['nodes']
# If the node involves media, adds it to result_dict['sounds'] or ['videos']
# Returns list of next nodes
def process_single_node(BASE_DIR, renpy_engine, node, result_dict):
    if isinstance(node, renpy.ast.Menu):
        return handle_menu_node(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Say):
        return handle_say_node(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.If):
        return handle_if_node(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Python):
        return handle_python_node(BASE_DIR, renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Scene):
        return handle_scene_node(BASE_DIR, renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Show):
        return handle_show_node(BASE_DIR, renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Hide):
        return handle_hide_node(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.UserStatement):
        return handle_custom_statement(BASE_DIR, renpy_engine, node, result_dict)
    else:
        warn_about_unknown_node(node)
        next_node = get_next_valid_node(renpy_engine, node.next)
        return [str(id(next_node))] if next_node else []

def get_next_valid_node(renpy_engine, node):
    while True:
        # Known valid node types
        if (isinstance(node, renpy.ast.Menu)
            or isinstance(node, renpy.ast.Say)
            or isinstance(node, renpy.ast.If)
            or isinstance(node, renpy.ast.Python)
            or isinstance(node, renpy.ast.Scene)
            or isinstance(node, renpy.ast.Show)
            or isinstance(node, renpy.ast.Hide)
                or isinstance(node, renpy.ast.UserStatement)):
            return node
        # Skip jumps by resolving target labels
        elif isinstance(node, renpy.ast.Jump):
            node = find_label_by_name(renpy_engine, node.target)
        # Ignore control flow and metadata nodes
        elif (isinstance(node, renpy.ast.Label)
              or isinstance(node, renpy.ast.Translate)
              or isinstance(node, renpy.ast.EndTranslate)
              or isinstance(node, renpy.ast.Pass)
              or isinstance(node, renpy.ast.Return)
              or isinstance(node, renpy.ast.With)):
            node = node.next
        elif node is not None:
            warn_about_unknown_node(node)
            break
        else:
            break

def handle_menu_node(renpy_engine, menu_node, result_dict):
    next_nodes = []
    menu_items_list = []
    display_messages = []

    for item in menu_node.items:
        (text, condition, lnext) = item
        if lnext:
            next_node = get_next_valid_node(renpy_engine, lnext[0])
            result_dict['nodes'][id(item)] = {
                'class_name': 'MenuItem',
                'arguments': [
                    text,
                    convert_booleans(condition),
                    [str(id(next_node))] if next_node else []
                ]
            }
            next_nodes.append(next_node)
            menu_items_list.append(item)
        else:
            display_messages.append(text)

    item_ids = [str(id(item)) for item in menu_items_list]
    result_dict['nodes'][id(menu_node)] = {
        'class_name': 'Menu',
        'arguments': [
            '\n'.join(display_messages),
            item_ids
        ]
    }
    return next_nodes

def handle_say_node(renpy_engine, say_node, result_dict):
    next_node = get_next_valid_node(renpy_engine, say_node.next)
    result_dict['nodes'][id(say_node)] = {
        'class_name': 'Say',
        'arguments': [
            say_node.who,
            say_node.what,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def handle_if_node(renpy_engine, if_node, result_dict):
    has_else = False
    for condition, block in if_node.entries:
        if condition == 'True':
            has_else = True

    if not has_else:
        if_node.entries.append(('true', [if_node.next]))

    block_nexts = []
    if_block_ids = []

    for condition, block in if_node.entries:
        id_block = id((condition, block))
        next_in_block = get_next_valid_node(renpy_engine, block[0])
        result_dict['nodes'][id_block] = {
            'class_name': 'IfBlock',
            'arguments': [
                convert_booleans(condition),
                [str(id(next_in_block))] if next_in_block else []
            ]
        }
        block_nexts.append(next_in_block)
        if_block_ids.append(str(id_block))

    result_dict['nodes'][id(if_node)] = {
        'class_name': 'If',
        'arguments': [if_block_ids],
    }
    return block_nexts

VIDEO_PATTERN = re.compile(r'^\s*renpy\.movie_cutscene\s*\((.+)\)\s*$')
PLAY_PATTERN = re.compile(r'^\s*renpy\.sound\.play\s*\((.+)\)\s*$')
LOOP_PATTERN = re.compile(r'^\s*loop\s*=(.*)$')

def handle_python_node(BASE_DIR, renpy_engine, py_node, result_dict):
    next_node = get_next_valid_node(renpy_engine, py_node.next)
    next_ids = [str(id(next_node))] if next_node else []

    video_match = re.search(VIDEO_PATTERN, py_node.code.source)
    if video_match and len(video_match.groups()) == 1:
        file_path = video_match.group(1)[1:-1]
        sanitized_name = sanitize_string(file_path)
        fetch_media(BASE_DIR, result_dict, 'videos', sanitized_name, file_path)
        result_dict['nodes'][id(py_node)] = {
            'class_name': 'Video',
            'arguments': [
                sanitized_name,
                next_ids
            ]
        }
    else:
        play_match = re.search(PLAY_PATTERN, py_node.code.source)
        if play_match and len(play_match.groups()) == 1:
            args = [arg.strip() for arg in play_match.group(1).split(',')]
            loop_flag = extract_loop_value(get_loop_condition, args[1:])
            handle_play_node(BASE_DIR, py_node, next_ids, result_dict, args[0][1:-1], 'sound', loop_flag)
        else:
            result_dict['nodes'][id(py_node)] = {
                'class_name': 'PyExpr',
                'arguments': [
                    convert_booleans(py_node.code.source),
                    next_ids
                ]
            }
    return [next_node]

def get_loop_condition(arg):
    match = re.search(LOOP_PATTERN, arg)
    if arg is not None and len(match.groups()) == 1:
        return match.group(1) == "True"

def extract_loop_value(func, collection):
    for item in collection:
        result = func(item)
        if result is not None:
            return result

def handle_scene_node(BASE_DIR, renpy_engine, scene_node, result_dict):
    next_node = get_next_valid_node(renpy_engine, scene_node.next)
    image_name = scene_node.imspec[0][0]
    get_image(BASE_DIR, renpy_engine, result_dict, image_name, scene_node.imspec)
    result_dict['nodes'][id(scene_node)] = {
        'class_name': 'Scene',
        'arguments': [
            image_name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def handle_show_node(BASE_DIR, renpy_engine, show_node, result_dict):
    next_node = get_next_valid_node(renpy_engine, show_node.next)
    image_name = show_node.imspec[0][0]
    is_video = get_image(BASE_DIR, renpy_engine, result_dict, image_name, show_node.imspec)
    result_dict['nodes'][id(show_node)] = {
        'class_name': 'ShowVideo' if is_video else 'Show',
        'arguments': [
            image_name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def handle_hide_node(renpy_engine, hide_node, result_dict):
    next_node = get_next_valid_node(renpy_engine, hide_node.next)
    result_dict['nodes'][id(hide_node)] = {
        'class_name': 'Hide',
        'arguments': [
            hide_node.imspec[0][0],
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

WORD_PATTERN = re.compile(r'([\w.]+|".*?")')

def handle_custom_statement(BASE_DIR, renpy_engine, user_stmt, result_dict):
    tokens = re.findall(WORD_PATTERN, user_stmt.line)
    next_node = get_next_valid_node(renpy_engine, user_stmt.next)
    next_ids = [str(id(next_node))] if next_node else []

    if tokens[0] == 'play' and len(tokens) >= 3:
        loop_flag = 'loop' in tokens[3:] if len(tokens) >= 4 else False
        handle_play_node(BASE_DIR, user_stmt, next_ids, result_dict, tokens[2][1:-1], tokens[1], loop_flag)
    elif tokens[0] == 'voice' and len(tokens) >= 2:
        handle_play_node(BASE_DIR, user_stmt, next_ids, result_dict, tokens[1][1:-1], 'voice', False)
    elif tokens[0] == 'stop' and len(tokens) >= 2:
        handle_stop_command(tokens, user_stmt, next_ids, result_dict)
    elif tokens[0] == 'window' and len(tokens) >= 2:
        handle_window_command(tokens, user_stmt, next_ids, result_dict)
    elif tokens[0] == 'pause' and len(tokens) >= 1:
        handle_pause_command(tokens, user_stmt, next_ids, result_dict)
    else:
        print('[WARNING] unrecognized UserStatement: %s' % user_stmt.line)
    return [next_node]

VIDEO_EXTENSIONS = ['.webm', '.ogv']

def handle_play_node(BASE_DIR, node_obj, next_ids, result_dict, file_path, channel, loop_flag):
    sanitized_name = sanitize_string(file_path)
    _, ext = path_module.splitext(file_path)
    media_category = 'videos' if ext in VIDEO_EXTENSIONS else 'sounds'
    fetch_media(BASE_DIR, result_dict, media_category, sanitized_name, file_path)
    result_dict['nodes'][id(node_obj)] = {
        'class_name': 'Play',
        'arguments': [
            channel,
            sanitized_name,
            loop_flag,
            next_ids
        ]
    }

def handle_stop_command(tokens, node_obj, next_ids, result_dict):
    channel_name = tokens[1]
    result_dict['nodes'][id(node_obj)] = {
        'class_name': 'Stop',
        'arguments': [
            channel_name,
            next_ids
        ]
    }

def handle_window_command(tokens, node_obj, next_ids, result_dict):
    show_state = True if tokens[1] == 'show' else False if tokens[1] == 'hide' else None
    if isinstance(show_state, bool):
        result_dict['nodes'][id(node_obj)] = {
            'class_name': 'ShowWindow',
            'arguments': [
                show_state,
                next_ids
            ]
        }
    else:
        print('[WARNING] unrecognized window option: %s' % tokens[1])

def handle_pause_command(tokens, node_obj, next_ids, result_dict):
    result_dict['nodes'][id(node_obj)] = {
        'class_name': 'Pause',
        'arguments': [
            next_ids
        ]
    }

