def overwrite_file(source_path, dest_path):
    if not isinstance(source_path, Path): 
        source_path = Path(source_path)
    if not isinstance(dest_path, Path): 
        dest_path = Path(dest_path)

    if not source_path.exists(): 
        raise FileNotFoundError("path '{}' does not exist".format(source_path))
    if not dest_path.exists(): 
        raise FileNotFoundError("target '{}' does not exist".format(dest_path))

    if not dest_path.is_file(): 
        rmtree(dest_path)
    else: 
        remove(dest_path)

    if not source_path.is_file(): 
        copytree(str(source_path), str(dest_path))
    else: 
        copy2(str(source_path), str(dest_path))

def fetch_latest_version():
    try: 
        response = urlopen(REPO_URL + 'res/data/version').read().decode('utf-8')
    except (URLError,): 
        return -2
    except (ValueError,): 
        return -1
    else:
        version_data = loads(response)
        release_num = version_data['version']['release']
        major_v, minor_v, patch_v = version_data['version']['version']
        release_date = version_data['meta']['date']
        return release_num, major_v, minor_v, patch_v, release_date,

def update_progress(block_num, block_size, total_size):
    global bar
    if bar is None: 
        bar = ProgressBar(maxval=total_size).start()
    downloaded = block_num * block_size
    if downloaded < total_size: 
        bar.update(downloaded)
    else: 
        bar.finish()

def install_release(release_id):
    clear_screen()
    temp_dir = Path('./download_{}'.format(release_id))
    version_file = temp_dir / 'version_{}'.format(release_id)

    print('create temporary directory')
    try: 
        temp_dir.mkdir()
    except (FileExistsError,): 
        pass

    print('downloading latest release')
    urlretrieve(REPO_URL + 'release/release_{}'.format(release_id), version_file, update_progress)

    print('\nextracting data')
    with ZipFile(str(version_file), 'r') as zip_ref:
        extract_bar = ProgressBar()
        for item in extract_bar(zip_ref.namelist()): 
            zip_ref.extract(item)

    print('extracted successfully')

    # Install files
    print('installing')
    file_list, dir_list = ProgressBar(), ProgressBar()

    for root, dirs, files in walk(temp_dir):
        print('installing files')
        for filename in file_list(files):
            if filename == version_file.name: 
                continue
            src = Path(filename).resolve()
            dst = Path(filename).resolve()
            overwrite_file(src, dst)

        print('installing directories')
        break

    print('installed successfully')
    rmtree(str(temp_dir))
    wait_for_input()

