import re as _re
import json as json_lib
import socket as sock
import asyncio as aio
import logging as log
# Third Party
import httpx as _httpx
# Project
from stats.util import make_repr as _make_repr, split_on_uppercase as _split_case

DEFAULT_LOG = log.getLogger(__name__)

class HttpClientBase:
    """Base session manager."""
    def __init__(
        self,
        server_url,
        settings=None,
        prefix="",
        suffix="",
        ssl_verify=True,
        connect_timeout=10,
        logger=DEFAULT_LOG,
        error_class=ValueError,
        client_agent=f"httpx/{_httpx.__version__}",
    ):
        """Initialize connection object."""
        self.__class__.__name__ = self.class_name
        self.settings = settings
        self.scheme, self.hostname, self.port_num = self._extract_url(server_url)
        self.root_url = self._compose_url(self.scheme, self.hostname, self.port_num)
        self.prefix_path = prefix.strip("/")
        self.suffix_path = suffix.strip("/")
        self.ssl_check = ssl_verify
        self.connection_timeout = connect_timeout
        self.logger = logger
        self.error_type = error_class
        self.client_header = client_agent

        # Session configuration
        session_config = {
            "verify": self.ssl_check,
            "base_url": self.root_url,
            "timeout": self.connection_timeout,
        }

        self._sync_session = _httpx.Client(**session_config)
        self._async_session = _httpx.AsyncClient(**session_config)

    @classmethod
    def __init_subclass__(cls, class_name=None, **options):
        """Assign correct subclass identifier."""
        super().__init_subclass__(**options)
        cls.class_name = class_name or cls.__name__

    async def __aenter__(self):
        """Verify connectivity upon entering context."""
        reachable = await self._check_availability()
        if reachable:
            self.logger.debug("Established session with {}", self.root_url)
            return self
        else:
            raise self._create_error(f"Failed to establish session to {self.class_name}")

    async def __aexit__(self, exc_type=None, exc_value=None, traceback=None):
        """Clean up connection on exit."""
        self.logger.debug("Terminating session with {}", self.root_url)
        await self._async_session.aclose()

    def __enter__(self):
        """Verify connectivity upon entering context."""
        reachable = self._check_connectivity()
        if reachable:
            self.logger.debug("Established session with {}", self.root_url)
            return self
        else:
            raise self._create_error(f"Failed to establish session to {self.class_name}")

    def __exit__(self, exc_type=None, exc_value=None, traceback=None):
        """Clean up connection on exit."""
        if exc_type is not None:
            self.logger.error(traceback)
        self._sync_session.close()

    def __repr__(self):
        """Return user-friendly string representation."""
        return _make_repr(self)

    def _create_error(self, msg, original_exc=None, **extra_kwargs):
        """Augment error message with exception details if provided."""
        if original_exc is not None:
            msg = "{}: {}".format(str(msg), str(original_exc), **extra_kwargs)
        return self.error_type(msg)

    def _check_connectivity(self):
        """Perform low-level port check to verify base URL accessibility."""
        self.logger.debug("Verifying connectivity to {}", self.root_url)
        try:
            host_only = _re.sub(r"http(s)?\:\/\/", "", self.root_url)
            sock.socket().connect((host_only, 443))
        except sock.gaierror as err:
            raise self._create_error(
                f"{self.class_name} seems unreachable", err
            ) from None
        return True

    async def _check_availability(self):
        """Async version of connectivity check."""
        self.logger.debug("Verifying connectivity to {}", self.root_url)
        try:
            reader, writer = await aio.open_connection(self.hostname, self.port_num)
            # Explicitly close writer to avoid resource leak
            writer.close()
            await writer.wait_closed()
        except sock.gaierror as err:
            raise self._create_error(
                f"{self.class_name} appears unreachable at {self.root_url}", err
            )
        return bool(reader or writer)

    @staticmethod
    def _compose_url(scheme, host, port):
        port_str = str(port)
        if port_str == "80":
            port_str = ""
            scheme = "http"
        elif port_str == "443":
            port_str = ""
            scheme = "https"
        if port_str != "":
            port_str = f":{port_str}"
        return "{scheme}://{host}{port}".format(
            scheme=scheme, host=host, port=port_str
        )

    @staticmethod
    def _extract_url(url_string):
        [parts] = _re.findall(r"^(http[s]?):\/\/([^:]+)\:?(\d*)$", url_string)
        scheme, host, port = parts
        return scheme, host, int(port) if port else 80

    @staticmethod
    def _normalize_dict(data_dict):
        return json_lib.loads(json_lib.dumps(data_dict, default=str))

    def _handle_response(self, raw_response):
        result = {}
        try:
            result = raw_response.json()
        except json_lib.JSONDecodeError:
            try:
                result = json_lib.loads(raw_response.text)
            except (json_lib.JSONDecodeError, TypeError):
                self.logger.error("JSON parsing failed for response {}", repr(raw_response))
                result = {"data": raw_response.text}
        return result

    @staticmethod
    def _describe_exception(err):
        """Extract class name and docstring from an exception."""
        if not isinstance(err, BaseException):
            raise TypeError(f"'{repr(err)}' is not an exception.")

        def extract_class_name(exception):
            return " ".join(_split_case(exception.__class__.__name__))

        def get_first_line(doc):
            return doc.strip().split("\n")[0].strip(".") if doc else ""

        class_name = extract_class_name(err)
        description_parts = []

        if err.__doc__:
            first_doc_line = get_first_line(err.__doc__)
            description_parts.append(f"{class_name} ({first_doc_line})")
        else:
            description_parts.append(class_name)

        if err.__cause__:
            cause_name = extract_class_name(err.__cause__)
            if err.__cause__.__doc__:
                cause_desc = get_first_line(err.__cause__.__doc__)
                description_parts.append(f"{cause_name} ({cause_desc})")
            else:
                description_parts.append(cause_name)

        return ", caused by ".join(description_parts)

    def _construct_request(self, **kwargs):
        """Process request parameters into structure compatible with HTTP library."""
        # Standard Library
        from operator import itemgetter
        allowed_methods = ("GET", "POST", "PUT", "DELETE", "HEAD", "PATCH")

        (
            method,
            path,
            subpath,
            custom_headers,
            query_params,
            payload,
            request_timeout,
            need_response,
        ) = itemgetter(*kwargs.keys())(kwargs)

        if method.upper() not in allowed_methods:
            raise self._create_error(
                f'Method must be one of {", ".join(allowed_methods)}. '
                f"Received: {str(method)}"
            )

        # Build final endpoint path
        segments = [
            "",
            self.prefix_path.strip("/"),
            path.strip("/"),
            self.suffix_path.strip("/"),
            subpath,
        ]
        final_endpoint = "/".join(seg for seg in segments if seg)

        request_data = {
            "method": method,
            "url": final_endpoint,
            "headers": {"user-agent": self.client_header},
        }

        if custom_headers is not None:
            request_data.update({"headers": custom_headers})

        if query_params is not None:
            cleaned_params = {str(k): str(v) for k, v in query_params.items() if v is not None}
            request_data["params"] = cleaned_params

        if payload is not None:
            if not isinstance(payload, dict):
                raise self._create_error(f"Payload must be a dict, got: {str(payload)}")
            request_data["json"] = self._normalize_dict(payload)

        if request_timeout is not None:
            if not isinstance(request_timeout, int):
                try:
                    request_timeout = int(request_timeout)
                except TypeError:
                    raise self._create_error(
                        f"Timeout must be an integer, got: {str(request_timeout)}"
                    )
            request_data["timeout"] = request_timeout

        self.logger.debug("Built request parameters {}", request_data)
        return request_data

    async def _async_make_request(  # noqa: C901
        self,
        method,
        path,
        subpath=None,
        headers=None,
        params=None,
        body=None,
        timeout=None,
        expect_response=False,
    ):
        """Execute asynchronous HTTP request."""
        prepared_request = self._construct_request(
            method=method,
            path=path,
            subpath=subpath,
            headers=headers,
            params=params,
            data=body,
            timeout=timeout,
            response_required=expect_response,
        )

        try:
            response = await self._async_session.request(**prepared_request)
            if response.status_code not in range(200, 300):
                status_obj = _httpx.StatusCode(response.status_code)
                error_details = self._handle_response(response)
                raise self._create_error(
                    f'{status_obj.name.replace("_", " ")}: {error_details}', level="danger"
                ) from None
        except _httpx.HTTPError as network_error:
            raise self._create_error(self._describe_exception(network_error)) from None

        return self._handle_response(response)

    # Async methods
    async def _aget(self, endpoint, **kwargs):
        return await self._async_make_request(method="GET", path=endpoint, **kwargs)

    async def _apost(self, endpoint, **kwargs):
        return await self._async_make_request(method="POST", path=endpoint, **kwargs)

    async def _aput(self, endpoint, **kwargs):
        return await self._async_make_request(method="PUT", path=endpoint, **kwargs)

    async def _adelete(self, endpoint, **kwargs):
        return await self._async_make_request(method="DELETE", path=endpoint, **kwargs)

    async def _apatch(self, endpoint, **kwargs):
        return await self._async_make_request(method="PATCH", path=endpoint, **kwargs)

    async def _ahead(self, endpoint, **kwargs):
        return await self._async_make_request(method="HEAD", path=endpoint, **kwargs)

    def _make_request(  # noqa: C901
        self,
        method,
        path,
        subpath=None,
        headers=None,
        params=None,
        body=None,
        timeout=None,
        expect_response=False,
    ):
        """Execute synchronous HTTP request."""
        prepared_request = self._construct_request(
            method=method,
            path=path,
            subpath=subpath,
            headers=headers,
            params=params,
            data=body,
            timeout=timeout,
            response_required=expect_response,
        )

        try:
            response = self._sync_session.request(**prepared_request)
            if response.status_code not in range(200, 300):
                status_obj = _httpx.StatusCode(response.status_code)
                error_details = self._handle_response(response)
                raise self._create_error(
                    f'{status_obj.name.replace("_", " ")}: {error_details}', level="danger"
                ) from None
        except _httpx.HTTPError as network_error:
            raise self._create_error(
                self._describe_exception(network_error), level="danger"
            ) from None

        return self._handle_response(response)

    # Synchronous methods
    def _get(self, endpoint, **kwargs):
        return self._make_request(method="GET", path=endpoint, **kwargs)

    def _post(self, endpoint, **kwargs):
        return self._make_request(method="POST", path=endpoint, **kwargs)

    def _put(self, endpoint, **kwargs):
        return self._make_request(method="PUT", path=endpoint, **kwargs)

    def _delete(self, endpoint, **kwargs):
        return self._make_request(method="DELETE", path=endpoint, **kwargs)

    def _patch(self, endpoint, **kwargs):
        return self._make_request(method="PATCH", path=endpoint, **kwargs)

    def _head(self, endpoint, **kwargs):
        return self._make_request(method="HEAD", path=endpoint, **kwargs)

# Custom exceptions for Solana-py library
from typing import Callable, Any

class SolanaBaseError(Exception):
    """Parent class for all Solana-py custom exceptions."""
    def __init__(self, error: Exception, method: Callable[[Any], Any], *params: Any, **options: Any) -> None:
        """Initialize the exception with details."""
        super().__init__()
        self.description = self._construct_error_description(error, method, *params, **options)

    @staticmethod
    def _construct_error_description(
        error: Exception, method: Callable[[Any], Any], *params: Any, **options: Any  # pylint: disable=unused-argument
    ) -> str:
        return f"{type(error)} occurred during {method} call"

class SolanaRpcError(SolanaBaseError):
    """Exception raised for RPC-related errors in Solana-py."""
    @staticmethod
    def _construct_error_description(
        error: Exception, method: Callable[[Any], Any], *params: Any, **options: Any  # pylint: disable=unused-argument
    ) -> str:
        endpoint_name = params[1]
        return f'{type(error)} occurred while calling "{endpoint_name}" RPC endpoint'

def catch_exceptions(wrapper_class, *target_types):
    """Decorator factory to wrap specific exceptions into custom ones (synchronous)."""
    def decorator(fn):
        def wrapper(*args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except target_types as err:
                raise wrapper_class(err, fn, *args, **kwargs) from err
        return wrapper
    return decorator

def catch_async_exceptions(wrapper_class, *target_types):
    """Decorator factory to wrap specific exceptions into custom ones (asynchronous)."""
    def decorator(fn):
        async def wrapper(*args, **kwargs):
            try:
                return await fn(*args, **kwargs)
            except target_types as err:
                raise wrapper_class(err, fn, *args, **kwargs) from err
        return wrapper
    return decorator

# Custom dataset class for toxic span token classification
from src.utils.mapper import configmapper
from transformers import AutoTokenizer
from datasets import load_dataset

@configmapper.map("datasets", "toxic_spans_tokens")
class ToxicSpansTokenDataset:
    def __init__(self, config):
        self.config = config
        self.tokenizer = AutoTokenizer.from_pretrained(
            self.config.model_checkpoint_name
        )
        # Load training and evaluation datasets from CSV files
        self.dataset = load_dataset("csv", data_files=dict(self.config.train_files))
        self.test_dataset = load_dataset("csv", data_files=dict(self.config.eval_files))

        # Tokenize and align labels for training data
        self.tokenized_inputs = self.dataset.map(
            self._process_training_samples, batched=True
        )
        # Tokenize test/evaluation data
        self.test_tokenized_inputs = self.test_dataset.map(
            self._process_test_samples, batched=True
        )

    def _process_training_samples(self, examples):
        # Tokenize input texts
        tokenized_inputs = self.tokenizer(
            examples["text"], **self.config.tokenizer_params
        )

        example_spans = []
        all_labels = []
        offsets_mapping = tokenized_inputs["offset_mapping"]

        for i, offset_list in enumerate(offsets_mapping):
            current_labels = []
            spans = eval(examples["spans"][i])
            example_spans.append(spans)

            # Determine classification label based on toxicity ratio
            if self.config.label_cls:
                text_length = len(examples["text"][i])
                cls_label = (
                    1
                    if (text_length > 0 and len(spans) / text_length > self.config.cls_threshold)
                    else 0
                )
            else:
                cls_label = -100

            # Assign labels for each token
            for j, (start, end) in enumerate(offset_list):
                if tokenized_inputs["input_ids"][i][j] == self.tokenizer.cls_token_id:
                    current_labels.append(cls_label)
                elif start == end and start == 0:
                    current_labels.append(-100)  # Special token marker
                else:
                    # Check which character positions fall within toxic spans
                    char_positions = list(range(start, end))
                    toxic_mask = [pos in spans for pos in char_positions]

                    # Mark as toxic if more than threshold portion is toxic
                    if toxic_mask and sum(toxic_mask) / len(toxic_mask) > self.config.token_threshold:
                        current_labels.append(1)
                    else:
                        current_labels.append(0)

            all_labels.append(current_labels)

        tokenized_inputs["labels"] = all_labels
        return tokenized_inputs

    def _process_test_samples(self, examples):
        # Tokenize test examples without label alignment
        tokenized_inputs = self.tokenizer(
            examples["text"], **self.config.tokenizer_params
        )
        return tokenized_inputs

# Modified version of the test framework code
import numpy as np
import multiprocessing
from unittest import IsolatedAsyncioTestCase
from ourtransform.framework import Process, Selector, AnyChain, Transformer, Element

def modified_transform(data: dict, output_map, metadata) -> list:
    # Extract keys where value equals 1
    return [key for key, value in data.items() if value == 1]

class TestFrameworkAsyncModified(IsolatedAsyncioTestCase):
    async def test_process_run_async_will_succeed(self):

        process = Process(
            selector=Selector(
                chains=[
                    AnyChain(
                        ordered_events=[
                            Transformer(fn=modified_transform),
                        ],
                    ),
                ],
            ),
        )
        try:
            result = await process.run_async(
                elements=[
                    Element(input={"x": 0, "y": 1}),
                    Element(input={"z": 0, "w": 1}),
                    Element(input={"p": 1, "q": 0}),
                ]
            )
            self.assertEqual(["y"], result.elements[0].output)
            self.assertEqual(["w"], result.elements[1].output)
            self.assertEqual(["p"], result.elements[2].output)
        except Exception as e:
            self.fail(e)

    async def test_process_run_async_with_timeout(self):
        letters = list("opqrstuvwxyzabcde")
        process = Process(
            selector=Selector(
                chains=[
                    AnyChain(
                        ordered_events=[
                            Transformer(fn=modified_transform),
                        ],
                    ),
                ],
            ),
        )
        try:
            await process.run_async(
                elements=[
                    Element(
                        input={
                            np.random.choice(letters): np.random.randint(0, 2) 
                            for _ in range(np.random.randint(1, 8))
                        },
                    )
                    for _ in range(5000)
                ],
                timeout=0.05,
            )
        except Exception as e:
            self.assertEqual(type(e), multiprocessing.TimeoutError)

# Modified version with Type I clone transformations
from __future__ import annotations
from typing import TYPE_CHECKING, List, Optional, Union, overload

if TYPE_CHECKING:
    from typing import Literal

class _InvalidResponseException(ValueError):
    pass

def query_yes_no(
    question: str,
    default: bool = True,
):
    """Query for a yes/no response on the CLI.
    Args:
        question (str): Question to ask.
        default (bool, optional): Default response. Defaults to True.
    Returns:
        bool: The response. 
    """
    if default is None:
        prompt_text = " [y/n] "
    elif default:
        prompt_text = " [Y/n] "
    else:
        prompt_text = " [y/N] "

    while True:
        user_input = input(question + prompt_text).lower()
        if default is not None and user_input == '':
            return default
        if "yes".startswith(user_input):
            return True
        if "no".startswith(user_input):
            return False
        print("Please respond with 'yes' or 'no' (or 'y' or 'n').")

def query_with_default(
    name: str,
    default_value: Optional[str] = None,
) -> str:
    """Query for a string response on the CLI.
    Args:
        name (str): Prompt to display.
        default_value (Optional[str], optional):
            Default value. Set to None to require a response.
    Returns:
        str: The response.
    """
    default_value_suffix = f" [{default_value}]" if default_value is not None else ""

    while True:
        try:
            user_response = input(f"{name}{default_value_suffix}: ")
            if user_response.strip() == "":
                if default_value is None:
                    raise _InvalidResponseException("A response is required.")
                user_response = default_value
            return user_response
        except _InvalidResponseException as error:
            print(error.args[0])

def _parse_user_response(response: str, available_options: List[str]):
    option_lower_to_original = {opt.lower(): opt for opt in available_options}

    try:
        option_index = int(response)
    except ValueError:
        selected_value = response
    else:
        if option_index <= 0 or option_index > len(available_options):
            raise _InvalidResponseException(f"Value {option_index} is not a valid option")
        selected_value = available_options[option_index - 1]

    if selected_value.lower() in option_lower_to_original:
        return option_lower_to_original[selected_value.lower()]
    raise _InvalidResponseException(f"Value {selected_value} is not a valid option")

@overload
def query_with_options(
    name: str, 
    options: List[str], 
    default_response: Optional[str],
    multiple_ok: Literal[False]
) -> str:
    ...

@overload
def query_with_options(
    name: str, 
    options: List[str], 
    default_response: Optional[str],
    multiple_ok: Literal[True]
) -> List[str]:
    ...

def query_with_options(
    name: str,
    options: List[str],
    default_response: Optional[str],
    multiple_allowed: bool,
) -> Union[str, List[str]]:
    """Interactively queries the user to select from a list of options.
    Args:
        name (str): Prompt for the user.
        options (List[str]): List of options.
        default_response (Optional[str]):
            Default response. Set to `None` to require a response.
        multiple_allowed (bool):
            Whether the user can specify multiple options
            via a comma-separated response.
    Returns:
        The response, or if ``multiple_allowed`` is True, a list of responses.
    """
    default_suffix = f" [{default_response}]" if default_response is not None else ""

    while True:
        try:
            print()
            print(name)
            print()
            for idx, item in enumerate(options):
                print(f"{idx + 1}): {item}")
            print()

            if multiple_allowed:
                help_message = "Enter a number, value, or comma separated numbers"
            else:
                help_message = "Enter a number or value"

            user_input = input(f"{help_message}{default_suffix}: ").strip()

            if user_input == "":
                if default_response is None:
                    raise _InvalidResponseException("A response is required.")
                return [default_response] if multiple_allowed else default_response

            if multiple_allowed:
                selections = user_input.split(",")
                final_answers: List[str] = []
                for item in selections:
                    final_answers.append(_parse_user_response(item, options))
                return final_answers
            else:
                return _parse_user_response(user_input, options)
        except _InvalidResponseException as exception:
            print(exception.args[0])
            # try again in the while loop

# Data class for storing calibration parameter values
from dataclasses import dataclass
from datetime import datetime
from typing import Union
from qiskit_experiments.exceptions import CalibrationError

@dataclass
class CalibParameter:
    """A data structure to hold calibrated parameter values."""
    # The numerical value assigned to the parameter
    param_value: Union[int, float, complex] = None
    # Timestamp indicating when the parameter was computed
    timestamp: datetime = datetime.fromtimestamp(0)
    # Flag indicating whether the parameter is considered valid
    is_valid: bool = True
    # Identifier of the experiment that produced this parameter
    experiment_uid: str = None
    # Calibration group this parameter belongs to
    calib_group: str = "default"

    def __post_init__(self):
        """
        Validate and convert field types after initialization. This enables
        deserialization from string representations (e.g., JSON) by ensuring
        all fields conform to expected types.
        """
        # Handle string representation of boolean validity
        if isinstance(self.is_valid, str):
            self.is_valid = (self.is_valid == "True")

        # Convert string representations of numeric values
        if isinstance(self.param_value, str):
            self.param_value = self._parse_numeric_value(self.param_value)

        # Parse datetime from string if needed
        if isinstance(self.timestamp, str):
            base_format = "%Y-%m-%d %H:%M:%S.%f"
            timezone_formats = ["%z", "", "Z"]
            for tz in timezone_formats:
                full_format = base_format + tz
                try:
                    self.timestamp = datetime.strptime(self.timestamp, full_format)
                    break
                except ValueError:
                    continue
            else:
                all_formats = [base_format + tz for tz in timezone_formats]
                raise CalibrationError(
                    f"Unable to parse timestamp '{self.timestamp}'. "
                    f"Expected one of: {all_formats}"
                )

        # Type validation for all fields
        if not isinstance(self.param_value, (int, float, complex)):
            raise CalibrationError(f"Parameter value '{self.param_value}' must be int, float, or complex.")
        if not isinstance(self.timestamp, datetime):
            raise CalibrationError(f"Timestamp '{self.timestamp}' must be a datetime object.")
        if not isinstance(self.is_valid, bool):
            raise CalibrationError(f"Validity flag '{self.is_valid}' must be a boolean.")
        if self.experiment_uid is not None and not isinstance(self.experiment_uid, str):
            raise CalibrationError(f"Experiment ID '{self.experiment_uid}' must be a string.")
        if not isinstance(self.calib_group, str):
            raise CalibrationError(f"Calibration group '{self.calib_group}' must be a string.")

    @staticmethod
    def _parse_numeric_value(value_str: str) -> Union[int, float, complex]:
        """
        Attempt to convert a string into a numeric type.

        Args:
            value_str: String representation of a number.

        Returns:
            Converted numeric value (int, float, or complex).

        Raises:
            CalibrationError: If conversion to any numeric type fails.
        """
        # Try integer conversion first
        try:
            return int(value_str)
        except ValueError:
            pass

        # Try float conversion
        try:
            return float(value_str)
        except ValueError:
            pass

        # Try complex conversion
        try:
            return complex(value_str)
        except ValueError as exc:
            raise CalibrationError(
                f"Failed to convert '{value_str}' to any numeric type (int/float/complex)."
            ) from exc

# Distributed utilities for PyTorch training
import functools
import logging
import pickle
import numpy as np
import torch
import torch.distributed as dist

_LOCAL_PROCESS_GROUP = None

def get_world_size() -> int:
    if not dist.is_available():
        return 1
    if not dist.is_initialized():
        return 1
    return dist.get_world_size()

def get_rank() -> int:
    if not dist.is_available():
        return 0
    if not dist.is_initialized():
        return 0
    return dist.get_rank()

def get_local_rank() -> int:
    if not dist.is_available():
        return 0
    if not dist.is_initialized():
        return 0
    assert _LOCAL_PROCESS_GROUP is not None
    return dist.get_rank(group=_LOCAL_PROCESS_GROUP)

def get_local_size() -> int:
    if not dist.is_available():
        return 1
    if not dist.is_initialized():
        return 1
    return dist.get_world_size(group=_LOCAL_PROCESS_GROUP)

def is_main_process() -> bool:
    return get_rank() == 0

def synchronize():
    if not dist.is_available():
        return
    if not dist.is_initialized():
        return
    world_size = dist.get_world_size()
    if world_size == 1:
        return
    dist.barrier()

@functools.lru_cache()
def _get_global_gloo_group():
    if dist.get_backend() == "nccl":
        return dist.new_group(backend="gloo")
    else:
        return dist.group.WORLD

def _serialize_to_tensor(data, group):
    backend = dist.get_backend(group)
    assert backend in ["gloo", "nccl"]
    device = torch.device("cpu" if backend == "gloo" else "cuda")
    buffer = pickle.dumps(data)
    if len(buffer) > 1024 ** 3:
        logger = logging.getLogger(__name__)
        logger.warning(
            "Rank {} attempting to all-gather {:.2f} GB of data on device {}".format(
                get_rank(),
                len(buffer) / (1024 ** 3),
                device
            )
        )
    storage = torch.ByteStorage.from_buffer(buffer)
    tensor = torch.ByteTensor(storage).to(device=device)
    return tensor

def _pad_to_largest_tensor(tensor, group):
    world_size = dist.get_world_size(group=group)
    assert world_size >= 1, \
        "comm.gather/all_gather must be called from ranks within the given group!"
    local_size = torch.tensor([tensor.numel()], dtype=torch.int64, device=tensor.device)
    size_list = [
        torch.zeros([1], dtype=torch.int64, device=tensor.device) for _ in range(world_size)
    ]
    dist.all_gather(size_list, local_size, group=group)
    size_list = [int(size.item()) for size in size_list]
    max_size = max(size_list)
    if local_size != max_size:
        padding = torch.zeros((max_size - local_size,), dtype=torch.uint8, device=tensor.device)
        tensor = torch.cat((tensor, padding), dim=0)
    return size_list, tensor

def all_gather(data, group=None):
    if get_world_size() == 1:
        return [data]
    if group is None:
        group = _get_global_gloo_group()
    if dist.get_world_size(group) == 1:
        return [data]
    tensor = _serialize_to_tensor(data, group)
    size_list, tensor = _pad_to_largest_tensor(tensor, group)
    max_size = max(size_list)
    tensor_list = [
        torch.empty((max_size,), dtype=torch.uint8, device=tensor.device) for _ in size_list
    ]
    dist.all_gather(tensor_list, tensor, group=group)
    data_list = []
    for size, tensor in zip(size_list, tensor_list):
        buffer = tensor.cpu().numpy().tobytes()[:size]
        data_list.append(pickle.loads(buffer))
    return data_list

def gather(data, dst=0, group=None):
    if get_world_size() == 1:
        return [data]
    if group is None:
        group = _get_global_gloo_group()
    if dist.get_world_size(group=group) == 1:
        return [data]
    rank = dist.get_rank(group=group)
    tensor = _serialize_to_tensor(data, group)
    size_list, tensor = _pad_to_largest_tensor(tensor, group)
    if rank == dst:
        max_size = max(size_list)
        tensor_list = [
            torch.empty((max_size,), dtype=torch.uint8, device=tensor.device) for _ in size_list
        ]
        dist.gather(tensor, tensor_list, dst=dst, group=group)
        data_list = []
        for size, tensor in zip(size_list, tensor_list):
            buffer = tensor.cpu().numpy().tobytes()[:size]
            data_list.append(pickle.loads(buffer))
        return data_list
    else:
        dist.gather(tensor, [], dst=dst, group=group)
        return []

def shared_random_seed():
    ints = np.random.randint(2 ** 31)
    all_ints = all_gather(ints)
    return all_ints[0]

def reduce_dict(input_dict, average=True):
    world_size = get_world_size()
    if world_size < 2:
        return input_dict
    with torch.no_grad():
        names = []
        values = []
        for k in sorted(input_dict.keys()):
            names.append(k)
            values.append(input_dict[k])
        values = torch.stack(values, dim=0)
        dist.reduce(values, dst=0)
        if dist.get_rank() == 0 and average:
            values /= world_size
        reduced_dict = {k: v for k, v in zip(names, values)}
    return reduced_dict

