def validate_table_record(table_record: DatabaseRecord,
                          *,
                          table: SQLAlchemyTable) -> bool:
    return all(
        (coordinate is None and column.nullable) or 
        isinstance(coordinate, convert_to_python_type(column))
        for coordinate, column in zip(table_record, table.columns)
    )

def convert_to_python_type(column: SQLAlchemyColumn) -> type:
    column_type = column.type
    if isinstance(column_type, postgresql_dialect.UUID):
        return UUIDType if column_type.as_uuid else str
    return column_type.python_type

def check_records_constraints(records: List[DatabaseRecord],
                              *,
                              table: SQLAlchemyTable) -> bool:
    def are_all_unique(iterable: Iterable[Hashable]) -> bool:
        observed = set()
        for item in iterable:
            if item in observed:
                return False
            observed.add(item)
        return True

    column_position_map = {
        column: index
        for index, column in enumerate(table.columns)
    }

    return all(
        are_all_unique(
            tuple(record[column_position_map[column]]
                  for column in constraint.columns)
            for record in records
        )
        for constraint in table.constraints
        if isinstance(constraint, constraints_module.UNIQUE_TYPES)
        and constraint.columns
    )

