from typing import Iterable, Union, cast
from cadquery import DirectionSelector, Wire, Workplane
from cadquery.cq import T, VectorLike
from ._util import toTuples, toVectors
from .polygon import hull2D

def bool2D(plane_obj: T, operand: Union[T, Wire], operation: str) -> T:
    if isinstance(operand, Workplane):
        extruded_operand = (
            Workplane(plane_obj.plane)
                .add(operand.ctx.pendingWires)
                .toPending()
        )
    elif isinstance(operand, Wire):
        extruded_operand = (
            Workplane(plane_obj.plane)
                .add(operand)
                .toPending()
        )
    else:
        raise ValueError("Cannot {} type '{}'".format(operation, type(operand)))

    result = Workplane.__dict__[operation](plane_obj.extrude(1), extruded_operand.extrude(1))
    plane_normal = DirectionSelector(-plane_obj.plane.zDir)
    return result.faces(plane_normal).wires().toPending()

def createPolygon(vertex_coords: Iterable[VectorLike], is_construction: bool = False) -> Wire:
    vectors = toVectors(vertex_coords)
    closed_polygon = vectors + (vectors[0], )
    return Wire.makePolygon(closed_polygon, is_construction)

def connectPolylineWithWire(path_points: Iterable[VectorLike], connector: Union[T, Wire], 
                           is_construction: bool = False) -> Wire:
    if isinstance(connector, Workplane):
        connector_wire = cast(Wire, connector.val())
    elif isinstance(connector, Wire):
        connector_wire = connector
    else:
        raise ValueError("Connector type '{}' is not allowed".format(type(connector)))

    point_list = toTuples(path_points)
    connector_vertices = [v.toTuple() for v in connector_wire.Vertices()]
    transformed_connectors = [
        [(pt[0] + vert[0], pt[1] + vert[1]) for vert in connector_vertices] 
        for pt in point_list
    ]

    workplane_segments = [
        Workplane(createPolygon(hull2D(transformed_connectors[i] + transformed_connectors[i + 1]), 
                               is_construction)).toPending()
        for i in range(len(point_list) - 1)
    ]

    # Build the combined shape by successively adding segments
    combined_wp = workplane_segments[0].extrude(1)
    for idx in range(1, len(workplane_segments)):
        combined_wp = combined_wp.add(workplane_segments[idx].extrude(1))

    final_wire = cast(Wire, combined_wp.combine().faces('<Z').wires().val())
    final_wire.forConstruction = is_construction
    return final_wire

