from .errors import ConfigurationError
from docker.utils.ports import build_port_bindings

class ServicePort(namedtuple('_ServicePort', 'target published protocol mode external_ip')):
    def __new__(cls, target, published, *args, **kwargs):
        try:
            if target is not None:
                target = int(target)
        except ValueError:
            raise ConfigurationError('Invalid target port: {}'.format(target))

        if published is not None:
            if isinstance(published, str) and '-' in published:  # "x-y:z" format
                a, b = published.split('-', 1)
                if not a.isdigit() or not b.isdigit():
                    raise ConfigurationError('Invalid published port: {}'.format(published))
            else:
                try:
                    published = int(published)
                except ValueError:
                    raise ConfigurationError('Invalid published port: {}'.format(published))

        return super().__new__(
            cls, target, published, *args, **kwargs
        )

    @classmethod
    def parse(cls, spec):
        if isinstance(spec, cls):
            # When extending a service with ports, the port definitions have already been parsed
            return [spec]

        if not isinstance(spec, dict):
            result = []
            try:
                for k, v in build_port_bindings([spec]).items():
                    if '/' in k:
                        target, proto = k.split('/', 1)
                    else:
                        target, proto = (k, None)

                    for pub in v:
                        if pub is None:
                            result.append(
                                cls(target, None, proto, None, None)
                            )
                        elif isinstance(pub, tuple):
                            result.append(
                                cls(target, pub[1], proto, None, pub[0])
                            )
                        else:
                            result.append(
                                cls(target, pub, proto, None, None)
                            )
            except ValueError as e:
                raise ConfigurationError(str(e))
            return result

        return [cls(
            spec.get('target'),
            spec.get('published'),
            spec.get('protocol'),
            spec.get('mode'),
            None
        )]

    @property
    def merge_field(self):
        return (self.target, self.published, self.external_ip, self.protocol)

    def repr(self):
        return {
            field: value for field, value in zip(self._fields, self) if value is not None
        }

    def legacy_repr(self):
        return normalize_port_dict(self.repr())

def normalize_port_dict(port):
    return '{external_ip}{has_ext_ip}{published}{is_pub}{target}/{protocol}'.format(
        published=port.get('published', ''),
        is_pub=(':' if port.get('published') is not None or port.get('external_ip') else ''),
        target=port.get('target'),
        protocol=port.get('protocol', 'tcp'),
        external_ip=port.get('external_ip', ''),
        has_ext_ip=(':' if port.get('external_ip') else ''),
    )

# Calculate Bingo scores for part 1 and part 2 
day = "4"
filepath_data = f"input/{day}.txt"
filepath_example = f"input/{day}-example.txt"

def read_boards_from_file(filename: str) -> tuple[list[str], list[list[list[str]]]]:
    boards: list[list[list[str]]] = []
    with open(filename) as file:
        drawn_numbers_line = file.readline().strip()
        drawn_numbers: list[str] = drawn_numbers_line.split(",")
        board: list[list[str]] = []
        row_counter = 0
        for line in file:
            row_counter += 1
            if row_counter == 1:
                continue
            board.append(line.split())
            if row_counter == 6:
                boards.append(board)
                board = []
                row_counter = 0
                continue
    return drawn_numbers, boards

def get_real_input() -> tuple[list[str], list[list[list[str]]]]:
    return read_boards_from_file(filepath_data)

def get_sample_input() -> tuple[list[str], list[list[list[str]]]]:
    return read_boards_from_file(filepath_example)

def mark_number_on_boards(
    number_called: str, 
    game_boards: list[list[list[str]]], 
    find_last_winning_board: bool = False
) -> tuple[int, list[list[list[str]]]]:
    boards_to_skip: list[int] = []
    for idx, current_board in enumerate(game_boards):
        for r_idx, row in enumerate(current_board):
            if idx in boards_to_skip:
                continue
            for c_idx, cell_value in enumerate(row):
                if idx in boards_to_skip:
                    continue
                if cell_value == number_called:
                    game_boards[idx][r_idx][c_idx] = "x"
                    if check_board_win(current_board, c_idx, r_idx):
                        is_last_board_and_mode_enabled = find_last_winning_board and len(game_boards) == 1
                        if not find_last_winning_board or is_last_board_and_mode_enabled:
                            return compute_board_score(current_board, int(number_called)), game_boards
                        else:
                            boards_to_skip.append(idx)

    # Remove winning boards that were marked to skip (if any)
    boards_to_skip = list(set(boards_to_skip))
    boards_to_skip.sort(reverse=True)
    for idx in boards_to_skip:
        del game_boards[idx]
    return 0, game_boards

def check_board_win(board: list[list[str]], col: int, row: int) -> bool:
    horizontal_win = True
    for i in range(5):
        if board[row][i] != "x":
            horizontal_win = False
            break

    vertical_win = True
    for i in range(5):
        if board[i][col] != "x":
            vertical_win = False
            break

    return horizontal_win or vertical_win

def compute_board_score(board: list[list[str]], last_number: int) -> int:
    total_sum = 0
    for row in board:
        for val in row:
            if val != "x":
                total_sum += int(val)
    return total_sum * last_number

def find_final_score(
    numbers_drawn: list[str], 
    all_boards: list[list[list[str]]], 
    use_last_winning_mode: bool = False
) -> int:
    active_boards = all_boards
    for num in numbers_drawn:
        score, active_boards = mark_number_on_boards(num, active_boards, use_last_winning_mode)
        if score > 0:
            return score
    return 0

if __name__ == "__main__":
    print(day)
    drawn_nums, boards_list = get_real_input()
    result_part1 = find_final_score(drawn_nums, boards_list)
    print(f"Part 1: {result_part1}")

    drawn_nums, boards_list = get_real_input()
    result_part2 = find_final_score(drawn_nums, boards_list, use_last_winning_mode=True)
    print(f"Part 2: {result_part2}")
    print()

# Terminal summary hook for pytest to trigger blink1 patterns based on test results
from urllib.request import urlopen, URLError

def pytest_terminal_summary(terminalreporter, exitstatus=None):  # pylint: disable=unused-argument
    _register_patterns()
    reporter = terminalreporter
    passed_count = len(reporter.stats.get('passed', []))
    failed_count = len(reporter.stats.get('failed', []))
    skipped_count = len(reporter.stats.get('deselected', []))
    error_count = len(reporter.stats.get('error', []))

    if (passed_count or skipped_count) and not (failed_count or error_count):
        _trigger_pattern('pytest-success')
    else:
        _trigger_pattern('pytest-failure')

def _register_patterns():
    _send_blink_command('pattern/add?pname=pytest-success&pattern=3,%2300ff00,1.5,%23000000,0.5')
    _send_blink_command('pattern/add?pname=pytest-failure&pattern=1,%23ff0000,0.3,1,%23ff0000,0.3,2,%23000000,0.1,0,%23ff0000,0.3,2,%23ff0000,0.3,1,%23000000,0.1,0')

def _trigger_pattern(pattern_name):
    _send_blink_command('pattern/play?pname={}'.format(pattern_name))

def _send_blink_command(cmd):
    try:
        urlopen('http://localhost:8934/blink1/{}'.format(cmd))
    except URLError:
        pass

# Liquidity Provider client implementation
import os
from http import HTTPStatus
from typing import Optional, List
from urllib.parse import urljoin
from uuid import UUID
import requests
from diem_utils.types.liquidity.currency import CurrencyPair
from diem_utils.types.liquidity.lp import LPDetails
from diem_utils.types.liquidity.quote import QuoteData, QuoteId
from diem_utils.types.liquidity.settlement import DebtData
from diem_utils.types.liquidity.trade import TradeId, Direction, TradeData

class LpClient:
    def __init__(self, base_url=None):
        # Set default host and port from environment variables or use defaults
        self._base_url = f"http://{os.getenv('LIQUIDITY_SERVICE_HOST', 'liquidity')}:{os.getenv('LIQUIDITY_SERVICE_PORT', 5000)}"
        if base_url:
            self._base_url = base_url

    def get_quote(self, pair: CurrencyPair, amount: int) -> QuoteData:
        payload = {
            "base_currency": pair.base.value,
            "quote_currency": pair.quote.value,
            "amount": amount,
        }
        response = requests.post(url=urljoin(self._base_url, "quote"), json=payload)
        raise_if_failed(response, f"Failed to obtain quote for {payload}")
        return QuoteData.from_json(response.text)

    def lp_details(self) -> LPDetails:
        response = requests.get(url=urljoin(self._base_url, "details"))
        raise_if_failed(response, "Failed to retrieve Liquidity Provider information")
        return LPDetails.from_json(response.text)

    def trade_info(self, trade_id: TradeId) -> TradeData:
        trade_id_str = str(trade_id)
        response = requests.get(url=urljoin(self._base_url, f"trade/{trade_id_str}"))
        raise_if_failed(response, f"Failed to fetch details for trade ID {trade_id_str}")
        return TradeData.from_json(response.text)

    def trade_and_execute(
        self,
        quote_id: QuoteId,
        direction: Direction,
        diem_deposit_address: Optional[str] = None,
        tx_version: Optional[int] = None,
    ) -> TradeId:
        request_body = {
            "quote_id": str(quote_id),
            "direction": direction.value,
        }
        if diem_deposit_address:
            request_body["diem_deposit_address"] = diem_deposit_address
        if tx_version:
            request_body["tx_version"] = tx_version
        response = requests.post(
            url=urljoin(self._base_url, "trade"), json=request_body
        )
        raise_if_failed(response, f"Failed to execute trade for {request_body}")
        return TradeId(UUID(response.json()["trade_id"]))

    def get_debt(self) -> List[DebtData]:
        response = requests.get(url=urljoin(self._base_url, "debt"))
        raise_if_failed(response, "Failed to retrieve outstanding debt records")
        return [DebtData.from_dict(debt_item) for debt_item in response.json()["debts"]]

    def settle(self, debt_id, settlement_confirmation):
        response = requests.put(
            url=urljoin(self._base_url, f"debt/{debt_id}"),
            json={"settlement_confirmation": settlement_confirmation},
        )
        raise_if_failed(
            response,
            f"Failed to settle debt ID {debt_id}; "
            f"confirmation {settlement_confirmation}",
        )

def raise_if_failed(response, error_description):
    if response.status_code < 200 or response.status_code >= 300:
        raise LpError(f"{error_description} (HTTP {response.status_code})")

class LpError(Exception):
    """Custom exception for liquidity provider related errors"""
    pass

# Monitor for service keep-alive status using a background thread
import logging
from datetime import datetime
from threading import Thread
from time import sleep
from typing import Dict, List

# project
from . import EventService, Event, EventType, EventPriority

class ServiceHealthMonitor:
    """Monitors service health by tracking time since last keep-alive event.
    If any service fails to send keep-alive events within its threshold,
    a high-priority user alert is generated and forwarded to the notifier.
    """
    def __init__(self, timeout_limits: Dict[EventService, int] = None):
        self._alert_handler = None
        self._last_activity_time = {EventService.HARVESTER: datetime.now()}
        self._service_timeout_seconds = timeout_limits or {EventService.HARVESTER: 300}

        # Determine monitoring interval based on smallest threshold (default behavior)
        # This interval controls how frequently alerts are re-evaluated; 
        # intervals under 5 minutes may cause frequent alerts if issues persist
        self._monitor_interval = float("inf")
        for limit in self._service_timeout_seconds.values():
            self._monitor_interval = min(limit, self._monitor_interval)

        logging.info(f"Service health check interval: {self._monitor_interval} seconds")
        if self._monitor_interval < 300:
            logging.warning(
                "Monitoring interval below 5 minutes could lead to "
                "repeated high-priority alerts when services are unresponsive. "
                "Is this configuration intentional?"
            )

        # Initialize and start monitoring thread
        self._monitor_active = True
        self._health_check_thread = Thread(target=self._run_health_checks)
        self._health_check_thread.start()

    def set_alert_handler(self, handler):
        self._alert_handler = handler

    def _run_health_checks(self):
        """Background thread function that periodically verifies
        whether all services have sent recent keep-alive signals.
        """
        previous_check = datetime.now()
        while self._monitor_active:
            sleep(1)  # Short sleep to allow graceful shutdown
            elapsed = (datetime.now() - previous_check).seconds
            if elapsed < self._monitor_interval:
                continue

            previous_check = datetime.now()
            alerts = []

            for service in self._last_activity_time.keys():
                idle_duration = (datetime.now() - self._last_activity_time[service]).seconds
                logging.debug(f"Keep-alive check for {service.name}: Last activity {idle_duration} seconds ago.")

                if idle_duration > self._service_timeout_seconds[service]:
                    warning_msg = (
                        f"Harvester service appears unreachable! "
                        f"No keep-alive received for {idle_duration} seconds."
                    )
                    logging.warning(warning_msg)
                    alerts.append(
                        Event(
                            type=EventType.USER,
                            priority=EventPriority.HIGH,
                            service=EventService.HARVESTER,
                            message=warning_msg,
                        )
                    )

            if alerts:
                if self._alert_handler:
                    self._alert_handler.handle_events(alerts)
                else:
                    logging.warning("Alert handler not configured - cannot dispatch high-priority alerts!")

    def handle_events(self, incoming_events: List[Event]):
        """Update last known activity timestamps for services sending keep-alive events."""
        for evt in incoming_events:
            if evt.type == EventType.KEEPALIVE:
                logging.debug(f"Keep-alive signal received from {evt.service.name}")
                self._last_activity_time[evt.service] = datetime.now()

    def shutdown(self):
        logging.info("Shutting down health monitor")
        self._monitor_active = False

