pending_buffer_changes = dict()  # type: Dict[int, Dict]

def queue_buffer_update(view: sublime.View):
    buffer_id = view.buffer_id()
    buffer_version = 1
    pending_buffer = None
    if buffer_id in pending_buffer_changes:
        pending_buffer = pending_buffer_changes[buffer_id]
        buffer_version = pending_buffer["version"] + 1
        pending_buffer["version"] = buffer_version
    else:
        pending_buffer_changes[buffer_id] = {
            "view": view,
            "version": buffer_version
        }
    sublime.set_timeout_async(
        lambda: flush_buffer_update(buffer_id, buffer_version), 500)

def flush_buffer_update(buffer_id: int, buffer_version=None):
    if buffer_id not in pending_buffer_changes:
        return
    pending_buffer = pending_buffer_changes.get(buffer_id)
    if pending_buffer:
        if buffer_version is None or buffer_version == pending_buffer["version"]:
            send_buffer_update(pending_buffer["view"])

def send_did_open(view: sublime.View):
    config = config_for_scope(view)
    client = client_for_view(view)
    if client and config:
        view.settings().set("show_definitions", False)
        window = view.window()
        view_file = view.file_name()
        if window and view_file:
            if not has_document_state(window, view_file):
                ds = get_or_create_document_state(window, view_file)
                ds.language_id = config.get_language_id(view)
                if settings.show_view_status:
                    view.set_status("code_intel_clients", config.name)
                params = {
                    "textDocument": {
                        "uri": filename_to_uri(view_file),
                        "languageId": ds.language_id,
                        "text": view.substr(sublime.Region(0, view.size())),
                        "version": ds.version_number
                    }
                }
                client.send_notification(Notification.didOpen(params))

def send_did_close(view: sublime.View):
    file_name = view.file_name()
    window = sublime.active_window()
    if window and file_name:
        if has_document_state(window, file_name):
            remove_document_state(window, file_name)
            client = client_for_closed_view(view)
            if client:
                params = {"textDocument": {"uri": filename_to_uri(file_name)}}
                client.send_notification(Notification.didClose(params))

def send_did_save(view: sublime.View):
    file_name = view.file_name()
    window = view.window()
    if window and file_name:
        if has_document_state(window, file_name):
            client = client_for_view(view)
            if client:
                params = {"textDocument": {"uri": filename_to_uri(file_name)}}
                client.send_notification(Notification.didSave(params))
        else:
            debug('document not tracked', file_name)

def send_did_change(view: sublime.View):
    file_name = view.file_name()
    window = view.window()
    if window and file_name:
        if view.buffer_id() in pending_buffer_changes:
            del pending_buffer_changes[view.buffer_id()]
        config = config_for_scope(view)
        client = client_for_view(view)
        if client and config:
            uri = filename_to_uri(file_name)
            language_id = config.get_language_id(view)
            ds = get_or_create_document_state(window, file_name)
            if ds.language_id == language_id:
                params = {
                    "textDocument": {
                        "uri": uri,
                        "version": ds.increment_version(),
                    },
                    "contentChanges": [{
                        "text": view.substr(sublime.Region(0, view.size()))
                    }]
                }
                client.send_notification(Notification.didChange(params))
            else:
                # The language_id has changed, reopen file
                ds.language_id = language_id
                params = {"textDocument": {"uri": uri}}
                client.send_notification(Notification.didClose(params))
                params = {
                    "textDocument": {
                        "uri": uri,
                        "languageId": ds.language_id,
                        "text": view.substr(sublime.Region(0, view.size())),
                        "version": ds.increment_version(),
                    }
                }
                client.send_notification(Notification.didOpen(params))

document_sync_initialized = False

class CloseListener(sublime_plugin.EventListener):
    def on_close(self, view):
        if is_supported_syntax(view.settings().get("syntax")):
            Events.publish("view.on_close", view)
        sublime.set_timeout_async(check_window_unloaded, 500)

class SaveListener(sublime_plugin.EventListener):
    def on_post_save_async(self, view):
        if is_supported_view(view):
            Events.publish("view.on_post_save_async", view)

def is_transient_view(view):
    window = view.window()
    if window:
        if window.get_view_index(view)[1] == -1:
            return True  # Quick panel transient views
        return view == window.transient_view_in_group(window.active_group())
    else:
        return True

class DocumentSyncListener(sublime_plugin.ViewEventListener):
    def __init__(self, view):
        self.view = view

    @classmethod
    def is_applicable(cls, settings):
        syntax = settings.get('syntax')
        # This enables all of document sync for any supportable syntax
        # Global performance cost, consider a detect_lsp_support setting
        return syntax and (is_supported_syntax(syntax) or is_supportable_syntax(syntax))

    @classmethod
    def applies_to_primary_view_only(cls):
        return False

    def on_load_async(self):
        # skip transient views:
        if not is_transient_view(self.view):
            Events.publish("view.on_load_async", self.view)

    def on_modified(self):
        if self.view.file_name():
            Events.publish("view.on_modified", self.view)

    def on_activated_async(self):
        if self.view.file_name() and not is_transient_view(self.view):
            Events.publish("view.on_activated_async", self.view)

def initialize_document_sync(text_document_sync_kind):
    global document_sync_initialized
    if document_sync_initialized:
        return
    document_sync_initialized = True
    # TODO: hook up events per scope/client
    Events.subscribe('view.on_load_async', send_did_open)
    Events.subscribe('view.on_activated_async', send_did_open)
    Events.subscribe('view.on_modified', queue_buffer_update)
    Events.subscribe('view.on_post_save_async', send_did_save)
    Events.subscribe('view.on_close', send_did_close)

# GeeTest task implementation for handling CAPTCHA challenges
class GeeTestTask(UserAgent, Proxy):
    def __init__(self, api_key):
        super(GeeTestTask, self).__init__(api_key)

    def create_task(self, target_url: str, gt_token: str, challenge_code: str,
                    api_domain: str = None, library_version: str = None):
        payload = {
            "clientKey": self._client_key,
            "task": {
                "type": "GeeTestTask",
                "websiteURL": target_url,
                "gt": gt_token,
                "challenge": challenge_code
            }
        }

        payload, has_user_agent = self._add_user_agent(payload)
        payload, uses_proxy = self._is_proxy_task(payload)

        if api_domain:
            payload["task"]["geetestApiServerSubdomain"] = api_domain
        if library_version:
            payload["task"]["geetestGetLib"] = library_version

        return self._make_request("createTask", payload).get("taskId")

# Custom imports below
from komand.exceptions import PluginException
from .schema import CreateWorkspaceInput, CreateWorkspaceOutput, Component, Input, Output

class CreateWorkspace(komand.Action):
    def __init__(self):
        super(self.__class__, self).__init__(
            name='create_workspace',
            description=Component.DESCRIPTION,
            input=CreateWorkspaceInput(),
            output=CreateWorkspaceOutput()
        )

    def run(self, params={}):
        dir_id = params.get(Input.DIRECTORY_ID)
        user_name = params.get(Input.USERNAME)
        bundle_id = params.get(Input.BUNDLE_ID)
        vol_enc_key = params.get(Input.VOLUME_ENCRYPTION_KEY)
        user_vol_enc_flag = params.get(Input.USER_VOLUME_ENCRYPTION_ENABLED)
        root_vol_enc_flag = params.get(Input.ROOT_VOLUME_ENCRYPTION_ENABLED)
        ws_props = params.get(Input.WORKSPACE_PROPERTIES)
        tag_list = params.get(Input.TAGS)

        result = {}
        payload = {
            'DirectoryId': dir_id,
            'UserName': user_name,
            'BundleId': bundle_id,
            'Tags': tag_list,
            'WorkspaceProperties': {
                'ComputeTypeName': ws_props['compute_type_name'],
                'RootVolumeSizeGib': ws_props['root_volume_size'],
                'RunningMode': ws_props['running_mode'],
                'RunningModeAutoStopTimeoutInMinutes': ws_props['running_mode_auto_stop_time_out'],
                'UserVolumeSizeGib': ws_props['user_volume_size']
            }
        }

        # Validate encryption flags - only one can be enabled
        if user_vol_enc_flag and root_vol_enc_flag:
            raise PluginException(
                cause="Both user and root volume encryption flags are enabled.",
                assistance="Only one encryption flag (user or root) may be set at a time."
            )

        # Add encryption flags to payload if enabled
        if user_vol_enc_flag:
            payload['UserVolumeEncryptionEnabled'] = user_vol_enc_flag
        if root_vol_enc_flag:
            payload['RootVolumeEncryptionEnabled'] = root_vol_enc_flag

        # Handle volume encryption key requirement
        if user_vol_enc_flag or root_vol_enc_flag:
            if vol_enc_key:
                payload['VolumeEncryptionKey'] = vol_enc_key
            else:
                raise PluginException(
                    cause="Invalid value for Volume Encryption Key input.",
                    assistance='Please provide a valid encryption key when encryption is enabled.'
                )

        try:
            result = self.connection.aws.client('workspaces').create_workspaces(Workspaces=[payload])
        except Exception:
            raise PluginException(cause="An unknown error occurred during workspace creation",
                                  data=result)

        # Handle failed requests
        try:
            if result.get('FailedRequests'):
                failed_req = result['FailedRequests'][0]
                raise PluginException(
                    cause=failed_req.get('ErrorCode'),
                    assistance=failed_req.get('ErrorMessage'),
                    data=result
                )
        except KeyError:
            raise PluginException(
                cause='Response missing expected keys in FailedRequests section.',
                assistance='Contact support for help.',
                data=result
            )

        # Handle pending requests
        try:
            pending_req = result['PendingRequests'][0]
            if pending_req.get('ErrorCode'):
                raise PluginException(
                    cause=pending_req.get('ErrorCode'),
                    assistance=pending_req.get('ErrorMessage'),
                    data=result
                )
            else:
                result = {
                    'id': pending_req.get('WorkspaceId'),
                    'state': pending_req.get('State')
                }
        except (IndexError, KeyError):
            raise PluginException(
                cause='Response missing expected PendingRequests structure.',
                assistance='Contact support for help.',
                data=result
            )

        return {Output.WORKSPACE_ID_STATE: result}

# Import required modules for logging and model loading
import logging
import torch.hub
from .demucs import Demucs
from .utils import deserialize_model

logger = logging.getLogger(__name__)

# Base URL for pre-trained models
BASE_URL = "https://dl.fbaipublicfiles.com/adiyoss/denoiser/"
DNS_48_MODEL = BASE_URL + "dns48-11decc9d8e3f0998.th"
DNS_64_MODEL = BASE_URL + "dns64-a7761ff99a7d5bb6.th"
MASTER_64_MODEL = BASE_URL + "master64-8a5dfb4bb92753dd.th"

def _build_demucs(pretrained, checkpoint_url, **config):
    network = Demucs(**config)
    if pretrained:
        weights = torch.hub.load_state_dict_from_url(checkpoint_url, map_location='cpu')
        network.load_state_dict(weights)
    return network

def dns_48(pretrained=True):
    return _build_demucs(pretrained, DNS_48_MODEL, hidden=48)

def dns_64(pretrained=True):
    return _build_demucs(pretrained, DNS_64_MODEL, hidden=64)

def master_64(pretrained=True):
    return _build_demucs(pretrained, MASTER_64_MODEL, hidden=64)

def register_model_arguments(parser):
    group = parser.add_mutually_exclusive_group(required=False)
    group.add_argument("-c", "--checkpoint_path", help="Path to local trained model.")
    group.add_argument("--dns48", action="store_true",
                       help="Use pre-trained real time H=48 model trained on DNS.")
    group.add_argument("--dns64", action="store_true",
                       help="Use pre-trained real time H=64 model trained on DNS.")
    group.add_argument("--master64", action="store_true",
                       help="Use pre-trained real time H=64 model trained on DNS and Valentini.")

def retrieve_model(args):
    """
    Load either a local model file or a pre-trained model from torchhub.
    """
    if args.checkpoint_path:
        logger.info("Loading model from %s", args.checkpoint_path)
        package = torch.load(args.checkpoint_path, 'cpu')
        if 'network' in package:
            if 'optimal_state' in package:
                package['network']['state'] = package['optimal_state']
            network = deserialize_model(package['network'])
        else:
            network = deserialize_model(package)
    elif args.dns64:
        logger.info("Loading pre-trained real time H=64 model trained on DNS.")
        network = dns_64()
    elif args.master64:
        logger.info("Loading pre-trained real time H=64 model trained on DNS and Valentini.")
        network = master_64()
    else:
        logger.info("Loading pre-trained real time H=48 model trained on DNS.")
        network = dns_48()
    logger.debug(network)
    return network

import marcotti.models.common.suppliers as mcs
import marcotti.models.common.overview as mco
import marcotti.models.common.personnel as mcp
import marcotti.models.common.match as mcm
import marcotti.models.common.events as mce
import marcotti.models.common.statistics as stats
import marcotti.models.club as mc
from .workflows import WorkflowBase

logger = logging.getLogger(__name__)

class MarcottiLoad(WorkflowBase):
    """
    Load transformed data into database.
    """
    def record_exists(self, model, **conditions):
        return self.session.query(model).filter_by(**conditions).count() != 0

    def suppliers(self, data_frame):
        supplier_records = [mcs.Suppliers(**data_row) for idx, data_row in data_frame.iterrows()
                            if not self.record_exists(mcs.Suppliers, name=data_row['name'])]
        self.session.add_all(supplier_records)
        self.session.commit()

    def years(self, data_frame):
        year_records = [mco.Years(**data_row) for idx, data_row in data_frame.iterrows()
                        if not self.record_exists(mco.Years, yr=data_row['yr'])]
        self.session.add_all(year_records)
        self.session.commit()

    def seasons(self, data_frame):
        season_records = []
        map_records = []
        for idx, row in data_frame.iterrows():
            if 'name' not in row:
                if row['start_year'] == row['end_year']:
                    yr_obj = self.session.query(mco.Years).filter_by(yr=row['start_year']).one()
                    if not self.record_exists(mco.Seasons, start_year_id=yr_obj.id, end_year_id=yr_obj.id):
                        season_records.append(mco.Seasons(start_year=yr_obj, end_year=yr_obj))
                else:
                    start_yr_obj = self.session.query(mco.Years).filter_by(yr=row['start_year']).one()
                    end_yr_obj = self.session.query(mco.Years).filter_by(yr=row['end_year']).one()
                    if not self.record_exists(mco.Seasons, start_year_id=start_yr_obj.id, end_year_id=end_yr_obj.id):
                        season_records.append(mco.Seasons(start_year=start_yr_obj, end_year=end_yr_obj))
                self.session.add_all(season_records)
            else:
                if not self.record_exists(mcs.SeasonMap, remote_id=row['remote_id'], supplier_id=self.supplier_id):
                    map_records.append(mcs.SeasonMap(id=self.get_id(mco.Seasons, name=row['name']),
                                                     remote_id=row['remote_id'],
                                                     supplier_id=self.supplier_id))
                self.session.add_all(map_records)
        self.session.commit()

    def countries(self, data_frame):
        remote_ids = []
        country_records = []
        fields = ['name', 'code', 'confederation']
        for idx, row in data_frame.iterrows():
            country_dict = {field: row[field] for field in fields if row[field]}
            if not self.record_exists(mco.Countries, name=row['name']):
                country_records.append(mco.Countries(**country_dict))
                remote_ids.append(row['remote_id'])
        self.session.add_all(country_records)
        self.session.commit()
        map_records = [mcs.CountryMap(id=country_record.id, remote_id=remote_id, supplier_id=self.supplier_id)
                       for remote_id, country_record in zip(remote_ids, country_records) if remote_id]
        self.session.add_all(map_records)
        self.session.commit()

    def competitions(self, data_frame):
        remote_ids = []
        comp_records = []
        for idx, row in data_frame.iterrows():
            if 'country_id' in data_frame.columns:
                fields = ['name', 'level', 'country_id']
                comp_dict = {field: row[field] for field in fields if row[field]}
                if not self.record_exists(mco.DomesticCompetitions, **comp_dict):
                    comp_records.append(mco.DomesticCompetitions(**comp_dict))
                    remote_ids.append(row['remote_id'])
            elif 'confederation' in data_frame.columns:
                fields = ['name', 'level', 'confederation']
                comp_dict = {field: row[field] for field in fields if row[field]}
                if not self.record_exists(mco.InternationalCompetitions, **comp_dict):
                    comp_records.append(mco.InternationalCompetitions(**comp_dict))
                    remote_ids.append(row['remote_id'])
        self.session.add_all(comp_records)
        self.session.commit()
        map_records = [mcs.CompetitionMap(id=comp_record.id, remote_id=remote_id, supplier_id=self.supplier_id)
                       for remote_id, comp_record in zip(remote_ids, comp_records) if remote_id]
        self.session.add_all(map_records)
        self.session.commit()

    def clubs(self, data_frame):
        remote_ids = []
        club_records = []
        fields = ['short_name', 'name', 'country_id']
        for idx, row in data_frame.iterrows():
            club_dict = {field: row[field] for field in fields if row[field]}
            if not self.record_exists(mc.Clubs, **club_dict):
                club_records.append(mc.Clubs(**club_dict))
                remote_ids.append(row['remote_id'])
        self.session.add_all(club_records)
        self.session.commit()
        map_records = [mc.ClubMap(id=club_record.id, remote_id=remote_id, supplier_id=self.supplier_id)
                       for remote_id, club_record in zip(remote_ids, club_records) if remote_id]
        self.session.add_all(map_records)
        self.session.commit()

    def venues(self, data_frame):
        remote_ids = []
        venue_records = []
        history_records = []
        fields = ['name', 'city', 'region', 'latitude', 'longitude', 'altitude', 'country_id', 'timezone_id']
        history_fields = ['eff_date', 'length', 'width', 'capacity', 'seats', 'surface_id']
        for idx, row in data_frame.iterrows():
            venue_dict = {field: row[field] for field in fields if row[field]}
            if not self.record_exists(mco.Venues, **venue_dict):
                venue_records.append(mco.Venues(**venue_dict))
                history_dict = {field: row[field] for field in history_fields if row[field]}
                history_records.append(mco.VenueHistory(venue_id=venue_dict['id'], **history_dict))
                remote_ids.append(row['remote_id'])
        self.session.add_all(venue_records)
        self.session.add_all(history_records)
        self.session.commit()
        map_records = [mcs.VenueMap(id=venue_record.id, remote_id=remote_id, supplier_id=self.supplier_id)
                       for remote_id, venue_record in zip(remote_ids, venue_records) if remote_id]
        self.session.bulk_save_objects(map_records)
        self.session.commit()

    def surfaces(self, data_frame):
        surface_records = [mco.Surfaces(**row) for indx, row in data_frame.iterrows()
                           if not self.record_exists(mco.Surfaces, description=row['description'])]
        self.session.add_all(surface_records)
        self.session.commit()

    def timezones(self, data_frame):
        tz_records = [mco.Timezones(**row) for indx, row in data_frame.iterrows()
                      if not self.record_exists(mco.Timezones, name=row['name'])]
        self.session.add_all(tz_records)
        self.session.commit()

    def players(self, data_frame):
        player_set = set()
        player_records = []
        remote_countryids = []
        remote_ids = []
        fields = ['known_first_name', 'first_name', 'middle_name', 'last_name', 'second_last_name',
                  'nick_name', 'birth_date', 'order', 'country_id', 'position_id', 'remote_id',
                  'remote_country_id']
        for _, row in data_frame.iterrows():
            player_set.add(tuple([(field, row[field]) for field in fields
                                  if field in row and row[field] is not None]))
        logger.info("{} players in data feed".format(len(player_set)))
        for elements in player_set:
            player_dict = dict(elements)
            remote_id = player_dict.pop('remote_id')
            remote_country_id = player_dict.pop('remote_country_id', None)
            if not self.record_exists(mcs.PlayerMap, remote_id=remote_id):
                if not self.record_exists(mcp.Players, **player_dict):
                    player_records.append(mcp.Players(**player_dict))
                    remote_ids.append(remote_id)
                    remote_countryids.append(remote_country_id)
                else:
                    player_id = self.session.query(mcp.Players).filter_by(**player_dict).one().id
                    map_record = mcs.PlayerMap(id=player_id, remote_id=remote_id, supplier_id=self.supplier_id)
                    self.session.add(map_record)
            else:
                player_id = self.session.query(mcs.PlayerMap).filter_by(remote_id=remote_id).one().id
                if not self.record_exists(mcp.Players, **player_dict):
                    updated_records = self.session.query(mcp.Players).\
                        filter(mcp.Players.person_id == mcp.Persons.person_id).\
                        filter(mcp.Players.id == player_id)
                    for rec in updated_records:
                        for field, value in player_dict.items():
                            setattr(rec, field, value)
        if self.session.dirty:
            self.session.commit()
        logger.info("{} player records ingested".format(len(player_records)))
        self.session.add_all(player_records)
        self.session.commit()
        map_records = [mcs.PlayerMap(id=player_record.id, remote_id=remote_id, supplier_id=self.supplier_id)
                       for remote_id, player_record in zip(remote_ids, player_records) if remote_id]
        self.session.add_all(map_records)
        self.session.commit()
        for remote_id, player_record in zip(remote_countryids, player_records):
            if remote_id and not self.record_exists(mcs.CountryMap, remote_id=remote_id,
                                                    supplier_id=self.supplier_id):
                self.session.add(mcs.CountryMap(id=player_record.country_id, remote_id=remote_id,
                                                supplier_id=self.supplier_id))
                self.session.commit()

    def managers(self, data_frame):
        manager_records = []
        remote_ids = []
        fields = ['known_first_name', 'first_name', 'middle_name', 'last_name', 'second_last_name',
                  'nick_name', 'birth_date', 'order', 'country_id']
        for indx, row in data_frame.iterrows():
            manager_dict = {field: row[field] for field in fields if field in row and row[field]}
            if not self.record_exists(mcs.ManagerMap, remote_id=row['remote_id']):
                if not self.record_exists(mcp.Managers, **manager_dict):
                    manager_records.append(mcp.Managers(**manager_dict))
                    remote_ids.append(row['remote_id'])
                else:
                    manager_id = self.session.query(mcp.Managers).filter_by(**manager_dict).one().id
                    map_record = mcs.ManagerMap(id=manager_id, remote_id=row['remote_id'],
                                                supplier_id=self.supplier_id)
                    self.session.add(map_record)
            else:
                manager_id = self.session.query(mcs.ManagerMap).filter_by(remote_id=row['remote_id']).one().id
                if not self.record_exists(mcp.Managers, **manager_dict):
                    updated_records = self.session.query(mcp.Managers).\
                        filter(mcp.Managers.person_id == mcp.Persons.person_id).\
                        filter(mcp.Managers.id == manager_id)
                    for rec in updated_records:
                        for field, value in manager_dict.items():
                            setattr(rec, field, value)
        if self.session.dirty:
            self.session.commit()
        self.session.add_all(manager_records)
        self.session.commit()
        map_records = [mcs.ManagerMap(id=manager_record.id, remote_id=remote_id, supplier_id=self.supplier_id)
                       for remote_id, manager_record in zip(remote_ids, manager_records) if remote_id]
        self.session.add_all(map_records)
        self.session.commit()

    def referees(self, data_frame):
        referee_records = []
        remote_ids = []
        fields = ['known_first_name', 'first_name', 'middle_name', 'last_name', 'second_last_name',
                  'nick_name', 'birth_date', 'order', 'country_id']
        for indx, row in data_frame.iterrows():
            referee_dict = {field: row[field] for field in fields if field in row and row[field]}
            if not self.record_exists(mcs.RefereeMap, remote_id=row['remote_id']):
                if not self.record_exists(mcp.Referees, **referee_dict):
                    referee_records.append(mcp.Referees(**referee_dict))
                    remote_ids.append(row['remote_id'])
                else:
                    referee_id = self.session.query(mcp.Referees).filter_by(**referee_dict).one().id
                    map_record = mcs.RefereeMap(id=referee_id, remote_id=row['remote_id'],
                                                supplier_id=self.supplier_id)
                    self.session.add(map_record)
            else:
                referee_id = self.session.query(mcs.RefereeMap).filter_by(remote_id=row['remote_id']).one().id
                if not self.record_exists(mcp.Referees, **referee_dict):
                    updated_records = self.session.query(mcp.Referees). \
                        filter(mcp.Referees.person_id == mcp.Persons.person_id). \
                        filter(mcp.Referees.id == referee_id)
                    for rec in updated_records:
                        for field, value in referee_dict.items():
                            setattr(rec, field, value)
        if self.session.dirty:
            self.session.commit()
        self.session.add_all(referee_records)
        self.session.commit()
        map_records = [mcs.RefereeMap(id=referee_record.id, remote_id=remote_id, supplier_id=self.supplier_id)
                       for remote_id, referee_record in zip(remote_ids, referee_records) if remote_id]
        self.session.add_all(map_records)
        self.session.commit()

