# High-level helper class to provide a DynamoDB encrypted table interface
from typing import Optional
from boto3.resources.base import ServiceResource
from dynamodb_encryption_sdk.structures import (
    AttributeActions,
    TableInfo,
    EncryptionContext,
)
from dynamodb_encryption_sdk.encrypted.table import EncryptedTable
from ..key_store import KeyStore
from .item import decrypt_python_item
from .materials_provider import KeyStoreMaterialsProvider

class EncryptedDynamoDBTable(object):
    """High-level helper class to provide a boto3 familiar interface to encrypted tables."""
    def __init__(
        self,
        resource_table: ServiceResource,
        key_storage: KeyStore,
        table_metadata: Optional[TableInfo] = None,
        action_definitions: Optional[AttributeActions] = None,
        auto_update_index_info: Optional[bool] = True,
    ) -> None:
        if action_definitions is None:
            action_definitions = AttributeActions()
        if table_metadata is None:
            table_metadata = TableInfo(name=resource_table.name)
        if auto_update_index_info:
            table_metadata.refresh_indexed_attributes(resource_table.meta.client)
        self._underlying_table = resource_table
        self._key_storage = key_storage
        self._table_metadata = table_metadata
        self._action_definitions = action_definitions

    def put_item(self, CSEKeyId: str, **kwargs):
        materials_provider = KeyStoreMaterialsProvider(
            key_store=self._key_storage,
            material_description={"key_id": CSEKeyId},
        )
        encrypted_table = EncryptedTable(
            table=self._underlying_table,
            materials_provider=materials_provider,
            table_info=self._table_metadata,
            attribute_actions=self._action_definitions,
        )
        encrypted_table.put_item(**kwargs)

    def get_item(self, **kwargs):
        materials_provider = KeyStoreMaterialsProvider(
            key_store=self._key_storage,
        )
        encrypted_table = EncryptedTable(
            table=self._underlying_table,
            materials_provider=materials_provider,
            table_info=self._table_metadata,
            attribute_actions=self._action_definitions,
        )
        return encrypted_table.get_item(**kwargs)

    def query(self, **kwargs):
        response = self._underlying_table.query(**kwargs)
        return self._decrypt_dynamodb_response(response)

    def scan(self, **kwargs):
        response = self._underlying_table.scan(**kwargs)
        return self._decrypt_dynamodb_response(response)

    def update_item(self, **kwargs):
        """Update item is not yet supported."""
        raise NotImplementedError('"update_item" is not yet implemented')

    def _decrypt_dynamodb_response(self, response):
        ec_kwargs = self._table_metadata.encryption_context_values
        if self._table_metadata.primary_index is not None:
            ec_kwargs.update(
                {
                    "partition_key_name": self._table_metadata.primary_index.partition,
                    "sort_key_name": self._table_metadata.primary_index.sort,
                }
            )
        self._action_definitions.set_index_keys(*self._table_metadata.protected_index_keys())
        encryption_context = EncryptionContext(**ec_kwargs)

        def decrypt(items):
            for item in items:
                try:
                    decrypted_item = decrypt_python_item(
                        item=item,
                        key_store=self._key_storage,
                        encryption_context=encryption_context,
                        attribute_actions=self._action_definitions,
                    )
                    yield decrypted_item
                except Exception:  # TODO
                    pass

        response["Items"] = list(decrypt(response["Items"]))
        response["Count"] = len(response["Items"])
        return response

    def __getattr__(self, name):
        """Catch any method/attribute lookups that are not defined in this class and try
        to find them on the provided bridge object.
        :param str name: Attribute name
        :returns: Result of asking the provided table object for that attribute name
        :raises AttributeError: if attribute is not found on provided bridge object
        """
        return getattr(self._underlying_table, name)

import time
import websocket
import json
from urllib.parse import urlencode
from resotolib.logger import log
from resotolib.event import EventType, remove_event_listener, add_event_listener, Event
from resotolib.args import ArgumentParser
from resotolib.jwt import encode_jwt_to_headers
from resotolib.core.ca import TLSData
from typing import Callable, Dict, Optional, Set
import threading

class CoreEvents(threading.Thread):
    def __init__(
        self,
        core_ws_endpoint: str,
        event_types: Optional[Set] = None,
        msg_handler: Optional[Callable] = None,
        tls_config: Optional[TLSData] = None,
    ) -> None:
        super().__init__()
        self.endpoint_uri = f"{core_ws_endpoint}/events"
        if event_types:
            query_params = urlencode({"show": ",".join(event_types)})
            self.endpoint_uri += f"?{query_params}"
        self.handler = msg_handler
        self.tls_settings = tls_config
        self.socket = None
        self.stop_flag = threading.Event()

    def __del__(self):
        remove_event_listener(EventType.SHUTDOWN, self.terminate)

    def run(self) -> None:
        self.name = "eventbus-listener"
        add_event_listener(EventType.SHUTDOWN, self.terminate)
        while not self.stop_flag.is_set():
            log.info("Connecting to resotocore event bus")
            try:
                self.establish_connection()
            except Exception as err:
                log.error(err)
            time.sleep(10)

    def establish_connection(self) -> None:
        log.debug(f"Connecting to {self.endpoint_uri}")
        auth_headers = {}
        if getattr(ArgumentParser.args, "psk", None):
            encode_jwt_to_headers(auth_headers, {}, ArgumentParser.args.psk)
        self.socket = websocket.WebSocketApp(
            self.endpoint_uri,
            header=auth_headers,
            on_open=self.on_connect,
            on_message=self.handle_message,
            on_error=self.handle_error,
            on_close=self.on_disconnect,
            on_ping=self.on_ping_received,
            on_pong=self.on_pong_received,
        )
        ssl_options = None
        if self.tls_settings:
            ssl_options = {"ca_certs": self.tls_settings.ca_cert_path}
        self.socket.run_forever(
            sslopt=ssl_options, ping_interval=30, ping_timeout=10, ping_payload="ping"
        )

    def terminate(self, event: Event = None) -> None:
        log.debug(
            "Received shutdown event - shutting down resotocore event bus listener"
        )
        self.stop_flag.set()
        if self.socket:
            self.socket.close()

    def handle_message(self, ws, payload):
        try:
            data: Dict = json.loads(payload)
        except json.JSONDecodeError:
            log.exception(f"Unable to decode received message {payload}")
            return
        log.debug(f"Received event: {data}")
        if self.handler is not None and callable(self.handler):
            try:
                self.handler(data)
            except Exception:
                log.exception(f"Something went wrong while processing {data}")

    def handle_error(self, ws, error):
        log.error(f"Event bus error: {error}")

    def on_disconnect(self, ws, close_code, close_reason):
        log.debug("Disconnected from resotocore event bus")

    def on_connect(self, ws):
        log.debug("Connected to resotocore event bus")

    def on_ping_received(self, ws, message):
        log.debug("Ping from resotocore event bus")

    def on_pong_received(self, ws, message):
        log.debug("Pong from resotocore event bus")

