# Modified version with Type I clone transformations applied
import codecs
import dataclasses
import io
import json
import os
import pathlib
import pprint
import sys
from typing import Optional
from . import get_github_json

@dataclasses.dataclass
class Repository:
    owner: str
    name: str
    branch: str
    pr: Optional[int] = None

    @property
    def identifier(self):
        return f"{self.owner}/{self.name}"

    @property
    def branch_link(self):
        return f"https://github.com/{self.identifier}/tree/{self.branch}"

    @property
    def pr_link(self):
        assert self.pr is not None, self
        return f"https://github.com/{self.identifier}/pull/{self.pr}"

def fetch_event_data(debug=(os.environ.get('ACTIONS_STEP_DEBUG', None)=='true')):
    event_path = os.environ.get('GITHUB_EVENT_PATH', None)
    if not event_path:
        raise SystemError("Missing GITHUB_EVENT_PATH environment variable.")

    event_file = pathlib.Path(event_path)
    if not event_file.exists():
        raise SystemError(f"Event file {event_file} does not exist.")

    with open(event_file) as file:
        event_data = json.load(file)

    if debug:
        print()
        print("::group::Raw Event Data")
        print(open(event_file).read())
        print("::endgroup::")
        print()
        print("::group::Parsed Event Details")
        pprint.pprint(event_data)
        print("::endgroup::")
        print(flush=True)

    return event_data

def fetch_repository_name(env_key, private_repo, _cache={}):
    if env_key in os.environ:
        return os.environ[env_key]

    if env_key not in _cache:
        repo_info = get_github_json(f'https://api.github.com/repos/{private_repo.identifier}')
        if 'parent' in repo_info:
            _cache[env_key] = repo_info['parent']['name']
        else:
            _cache[env_key] = repo_info['name']

    return _cache[env_key]

def extract_details(event_data=None):
    # There are three repositories involved:
    #
    #  * 'event_data' relates to the **private** repository where the branch came from.
    #
    #  * `staging_.*` is the **public** staging repository used as source for the PR.
    #    The branch from 'event_data' was copied here from the **private** repo.
    #
    #  * `upstream_.*` is the **public** target repository for the pull request.

    # Support ROT13-encoded values for STAGING_OWNER, UPSTREAM_OWNER and UPSTREAM_BRANCH
    if 'ROT13_STAGING_OWNER' in os.environ:
        os.environ['STAGING_OWNER'] = codecs.decode(
            os.environ.get('ROT13_STAGING_OWNER'), 'rot_13')
    if 'ROT13_UPSTREAM_OWNER' in os.environ:
        os.environ['UPSTREAM_OWNER'] = codecs.decode(
            os.environ.get('ROT13_UPSTREAM_OWNER'), 'rot_13')
    if 'ROT13_UPSTREAM_BRANCH' in os.environ:
        os.environ['UPSTREAM_BRANCH'] = codecs.decode(
            os.environ.get('ROT13_UPSTREAM_BRANCH'), 'rot_13')

    if event_data:
        if 'pull_request' in event_data:
            repo_info = event_data['pull_request']['head']['repo']
            branch_name = event_data['pull_request']['head']['ref']
            pr_number = event_data['pull_request']['number']
            commit_sha = event_data['pull_request']['head']['sha']
        else:
            repo_info = event_data['repository']
            branch_name = event_data['ref']
            pr_number = None
            commit_sha = None

        private_base = Repository(
            owner=repo_info['owner']['login'],
            name=repo_info['name'],
            branch=branch_name,
            pr=pr_number,
        )
    else:
        private_base = Repository(
            owner=None,
            name=None,
            branch=None,
            pr=None,
        )

    private = Repository(
        owner=os.environ.get('PRIVATE_OWNER', private_base.owner),
        name=os.environ.get('PRIVATE_REPO', private_base.name),
        branch=os.environ.get('PRIVATE_BRANCH', private_base.branch),
        pr=private_base.pr,
    )

    staging = Repository(
        owner=os.environ.get('STAGING_OWNER', None),
        name=fetch_repository_name('STAGING_REPO', private),
        branch=os.environ.get('STAGING_BRANCH', private.branch),
    )

    upstream = Repository(
        owner=os.environ.get('UPSTREAM_OWNER', None),
        name=fetch_repository_name('UPSTREAM_REPO', private),
        branch=os.environ.get('UPSTREAM_BRANCH', 'main'),
        pr=os.environ.get('UPSTREAM_PR', None),
    )

    print()
    print(" Private:", private.identifier, "@", private.branch, "(", private.branch_link, ")")
    print(" Staging:", staging.identifier, "@", staging.branch, "(", staging.branch_link, ")")
    print("Upstream:", upstream.identifier, "@", upstream.branch, "(", upstream.branch_link, ")")
    print()

    commit_url = f"https://github.com/{private.identifier}/commits/{commit_sha}"
    print()
    print(" Pull request @", commit_sha, "(", commit_url, ")")
    print()

    return (private, staging, upstream, commit_sha)

def execute(args):
    original_stdout = sys.stdout
    if '--quiet' in args:
        args.remove('--quiet')
        sys.stdout = io.StringIO()

    event_data = fetch_event_data(sys.stdout == original_stdout)
    private, staging, upstream, commit_sha = extract_details(event_data)

    if args:
        for arg in args:
            print(eval(arg), file=original_stdout)
    else:
        print(f"""
PRIVATE_OWNER={private.owner}
PRIVATE_REPO={private.name}
PRIVATE_BRANCH={private.branch}
STAGING_OWNER={staging.owner}
STAGING_REPO={staging.name}
STAGING_BRANCH={staging.branch}
UPSTREAM_OWNER={upstream.owner}
UPSTREAM_REPO={upstream.name}
UPSTREAM_BRANCH={upstream.branch}
""".strip(), file=original_stdout)

if __name__ == "__main__":
    sys.exit(execute(list(sys.argv[1:])))

