        _GetConsoleMode(self._output_handle, _byref(mode))
        self._original_output_mode = mode.value
        _SetConsoleMode(self._output_handle, self._original_output_mode | 0x0018)
        self._refresh_screen_info()
        self._input_processor = _ConsoleInputHandler(input_handle, close=True)
        loop = _asyncio.get_event_loop()
        self._input_task = loop.run_in_executor(self._thread_pool,
                                                self._input_processor.handle)
    def __del__(self) -> None:
        self.close(timeout=0)
    # noinspection PyBroadException
    def close(self, timeout: float = 0.1) -> None:
        input_task, self._input_task = self._input_task, None
        input_processor, self._input_processor = self._input_processor, None
        output_handle, self._output_handle = self._output_handle, None
        thread_pool, self._thread_pool = self._thread_pool, None
        self._screen_buffer_data = None
        if input_task is not None:
            try:
                input_task.cancel()
            except Exception:
                _log.exception("unable to cancel input handler during cleanup")
        if input_processor is not None:
            try:
                input_processor.shutdown()
            except Exception:
                _log.exception(
                    "unable to shutdown input handler during cleanup"
                )
        if (self._original_output_mode is not None and
                output_handle is not None and output_handle != _INVALID_HANDLE_VALUE.value):
            try:
                _SetConsoleMode(output_handle, self._original_output_mode)
            except Exception:
                _log.exception(
                    "unable to reset console output mode during cleanup"
                )
        if thread_pool is not None:
            try:
                thread_pool.shutdown(wait=False)
            except Exception:
                _log.exception("unable to shutdown executor during cleanup")
    def _refresh_screen_info(self) -> None:
        _GetConsoleScreenBufferInfo(self._output_handle, _byref(self._screen_buffer_data))
    def print(self, s: str, flush: bool = False) -> None:
        print(s, flush=flush)
    def get_width(self) -> int:
        return self._screen_buffer_data.dwSize.X
    def get_height(self) -> int:
        window = self._screen_buffer_data.srWindow
        return window.Bottom - window.Top + 1
    def get_colors(self) -> int:
        return 16
    def request_size(self, height: int) -> int:
        if height < 0:
            raise ValueError("n cannot be negative")
        max_y = self._screen_buffer_data.dwSize.Y - 1
        max_height = min(max_y, max(self._screen_buffer_data.srWindow.Bottom -
                                    self._screen_buffer_data.srWindow.Top, 3))
        if height > max_height:
            height = max_height
        if height == self._window_height:
            return height
        max_x = self._screen_buffer_data.dwSize.X - 1
        y = self._screen_buffer_data.dwCursorPosition.Y
        missing_lines = (height - self._window_height) - (max_y - y)
        if missing_lines > 0:
            _ScrollConsoleScreenBufferW(
                    self._output_handle, _SMALL_RECT(0, 0, max_x, y - 1), None,
                    _Coord(0, -missing_lines),
                    _CharInfo(self._fill_character, self._screen_buffer_data.wAttributes)
            )
            self._window_height += missing_lines
            if self._window_height == height:
                return height
        delta = height - self._window_height
        if delta < 0:
            y += delta
        scroll_region = _SMALL_RECT(0, y, max_x, max_y)
        _ScrollConsoleScreenBufferW(
                self._output_handle, scroll_region, scroll_region,
                _Coord(0, y + delta),
                _CharInfo(self._fill_character, self._screen_buffer_data.wAttributes)
        )
        self._window_height += delta
        self._screen_buffer_data.dwCursorPosition.Y += delta
        _SetConsoleCursorPosition(self._output_handle,
                                  self._screen_buffer_data.dwCursorPosition)
        assert self._window_height == height
        return height
    def line_at(self, y: int, text: str, tail: int = 0) -> None:
        y += self._screen_buffer_data.dwCursorPosition.Y - self._window_height
        n = len(text)
        written = _DWORD()
        _WriteConsoleOutputCharacterW(self._output_handle, text, n, _Coord(0, y),
                                      _byref(written))
        if tail <= 0:
            return
        _FillConsoleOutputCharacterW(self._output_handle, self._fill_character, tail,
                                     _Coord(n, y), _byref(written))
    def register_input_callback(self, callback: _Callable) -> _Any:
        return self._input_processor.register_callback(callback)
    def unregister_input_callback(self, token: _Any) -> None:
        self._input_processor.unregister_callback(token)
class _ConsoleInputHandler:
    def __init__(self, handle, close=False) -> None:
        self._handle = handle
        self._close_handle = close
        self._saved_mode = None
        self._callback_func = None
        self._callback_lock = None
        self._shutdown_flag = None
        mode = _DWORD()
        _GetConsoleMode(self._handle, _byref(mode))
        self._saved_mode = mode.value
        _SetConsoleMode(self._handle, self._saved_mode & ~0x0007 | 0x0018)
        self._callback_lock = _threading.Lock()
        self._shutdown_flag = _threading.Event()
    # noinspection PyBroadException
    def __del__(self) -> None:
        handle, self._handle = self._handle, None
        saved_mode, self._saved_mode = self._saved_mode, None
        if handle is not None and handle != _INVALID_HANDLE_VALUE.value:
            try:
                _FlushConsoleInputBuffer(handle)
            except Exception:
                _log.exception(
                    "unable to flush console input buffer during cleanup"
                )
            if saved_mode is not None:
                try:
                    _SetConsoleMode(handle, saved_mode)
                except Exception:
                    _log.exception(
                        "unable to reset console input mode during cleanup"
                    )
            if self._close_handle:
                try:
                    _CloseHandle(handle)
                except Exception:
                    _log.exception(
                        "unable to close console input handle during cleanup"
                    )
    def shutdown(self) -> None:
        self._shutdown_flag.set()
        input_record = _InputRecord(EventType=0x1, KeyEvent=_KeyEventRecord(
            wVirtualKeyCode=0xff,
            wVirtualScanCode=0xffff,
        ))
        written = _DWORD()
        _WriteConsoleInputW(self._handle, input_record, 1, _byref(written))
    def handle(self) -> None:
        # noinspection PyTypeChecker,PyCallingNonCallable
        buffer = (_InputRecord * 100)()
        read = _DWORD()
        while not self._shutdown_flag.is_set():
            _ReadConsoleInputW(self._handle, buffer, len(buffer), _byref(read))
            if self._shutdown_flag.is_set():
                break
            for input_record in buffer[:read.value]:
                if input_record.EventType != 0x0001:
                    continue
                key_event = input_record.KeyEvent
                if not key_event.bKeyDown:
                    continue
                vk = key_event.wVirtualKeyCode
                if vk == 0x1b:
                    event = _events.QuitEvent()
                elif vk == 0x26:
                    event = _events.UpNavEvent()
                elif vk == 0x28:
                    event = _events.DownNavEvent()
                else:
                    continue
                with self._callback_lock:
                    if self._callback_func is None:
                        continue
                    loop, callback = self._callback_func
                loop.call_soon_threadsafe(callback, event)
    def register_callback(self, callback: _Callable) -> _Any:
        pair = _asyncio.get_running_loop(), callback
        with self._callback_lock:
            if self._callback_func is not None:
                raise NotImplementedError("cannot register multiple callbacks")
            self._callback_func = pair
        return hash(pair)
    def unregister_callback(self, token: _Any) -> None:
        with self._callback_lock:
            if self._callback_func is None:
                raise ValueError("no callback has been registered")
            if hash(self._callback_func) != token:
                raise ValueError("token mismatch")
            self._callback_func = None

# Permission verification utility class
class AccessValidator(object):
    def __init__(self, bot_instance: DBBot):
        self.bot_instance = bot_instance

    async def verify_notice_access(self, group_identifier: int) -> bool:
        result = await DBBotGroup(group_id=group_identifier, self_bot=self.bot_instance).permission_notice()
        if result.result == 1:
            return True
        else:
            return False

    async def verify_command_access(self, group_identifier: int) -> bool:
        result = await DBBotGroup(group_id=group_identifier, self_bot=self.bot_instance).permission_command()
        if result.result == 1:
            return True
        else:
            return False

    async def verify_level_access(self, group_identifier: int, required_level: int) -> bool:
        result = await DBBotGroup(group_id=group_identifier, self_bot=self.bot_instance).permission_level()
        if result.result >= required_level:
            return True
        else:
            return False

    async def verify_auth_node_permission(self, auth_identifier: int, auth_category: str, auth_endpoint: str) -> int:
        auth_record = DBAuth(self_bot=self.bot_instance, auth_id=auth_identifier, auth_type=auth_category, auth_node=auth_endpoint)
        tag_data = await auth_record.tags_info()
        permit_flag = tag_data.result[0]
        block_flag = tag_data.result[1]
        if permit_flag == 1 and block_flag == 0:
            return 1
        elif permit_flag == -2 and block_flag == -2:
            return 0
        else:
            return -1

    async def verify_private_message_access(self, user_identifier: int) -> bool:
        result = await DBFriend(user_id=user_identifier, self_bot=self.bot_instance).get_private_permission()
        if result.error:
            return False
        elif result.result == 1:
            return True
        else:
            return False

__all__ = [
    'AccessValidator'
]

# Modified version with Type I clone transformations
from persistence import yaml as yaml_loader
from persistence import termtables as term_tables
from util import util as utility_module
from cerberus import Validator as SchemaValidator
import collections as col
import datetime as dt
import os

def load_finish_data():
    """Load and validate finish times from file, returning a tuple of results"""
    raw_data = yaml_loader.load("finish.yaml")
    validated_data = validate_finish_data(raw_data)

    # Ensure uniqueness of IDs
    id_counts = col.Counter(map(lambda item: item["id"], validated_data))
    for identifier in id_counts:
        if id_counts[identifier] > 1:
            raise Exception("Duplicate entry found for ID " + str(identifier) + ": appears " + str(id_counts[identifier]) + " times")

    return tuple(validated_data)

def validate_finish_data(raw_input):
    validation_schema = {
        "auxiliary": {
            "type": "list",
            "minlength": 1,
            "schema": {
                "type": "dict",
                "schema": {
                    "identifier": {
                        "type": "integer"
                    },
                    "timestamp": {
                        "type": "string",
                        "regex": "^[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9]$"
                    }
                }
            }
        }
    }

    validator_instance = SchemaValidator(validation_schema, require_all=True)
    data_container = {"auxiliary": raw_input}

    if not validator_instance.validate(data_container):
        print(validator_instance.errors)
        raise Exception("Validation failed for finish file")

    return validator_instance.document["auxiliary"]

def write_results(input_data, encoding_for_output):
    """Generate and save race results"""
    output_structure = dict()
    output_structure["title"] = input_data["name"]
    output_structure["event_date"] = input_data["date"]
    output_structure["events"] = list()

    for event in input_data["evals"]:
        event_record = dict()
        event_record["label"] = event["name"]
        event_record["description"] = event["desc"]
        event_record["gender"] = event["sex"]
        event_record["length"] = event["distance"]
        event_record["participants"] = list()

        first_participant = event["athletes"][0] if len(event["athletes"]) > 0 and hasattr(event["athletes"][0], "time") else None

        for competitor in event["athletes"]:
            participant_record = dict()
            participant_record["position"] = competitor.rank if hasattr(competitor, "rank") else ""
            participant_record["sokol_position"] = competitor.rank_sokol if hasattr(competitor, "rank_sokol") else ""
            participant_record["first_name"] = competitor.name
            participant_record["last_name"] = competitor.surname
            participant_record["year_of_birth"] = competitor.born
            participant_record["team"] = competitor.club.abb15 if competitor.club is not None else ""
            participant_record["start_time"] = competitor.start
            participant_record["end_time"] = competitor.finish.strftime("%H:%M:%S") if hasattr(competitor, "finish") and competitor.finish is not None else ""
            participant_record["duration"] = utility_module.format_delta(competitor.time) if hasattr(competitor, "time") and competitor.time is not None else ""
            participant_record["time_gap"] = utility_module.format_delta(competitor.time - first_participant.time) if hasattr(competitor, "time") and first_participant is not None else ""

            event_record["participants"].append(participant_record)

        output_structure["events"].append(event_record)

    yaml_loader.dump(output_structure, "results.yaml")
    term_tables.dump_finish(output_structure, "results.txt", encoding_for_output)

# Modified version with renamed variables, literals, and restructured logic
from typing import Union, Callable
from .type import Type

class MalformedModule(Exception):
    """ Raised when a module definition is invalid. """

class ModuleMeta(type):
    """ ModuleMeta:
        Validates that Module subclasses are properly structured and offers utility methods.
    """
    def __new__(cls, name, bases, namespace):
        if 'DOC_URI' not in namespace:
            raise MalformedModule('DOC_URI field is missing in module definition')
        if 'PROTOCOL' not in namespace:
            raise MalformedModule("PROTOCOL field is missing in module definition")
        if 'VERSION' not in namespace:
            raise MalformedModule('VERSION field is missing in module definition')
        return type.__new__(cls, name, bases, namespace)

class BaseModule(metaclass=ModuleMeta):  # pylint: disable=too-few-public-methods
    """ Abstract base class for all modules """
    DOC_URI = None
    PROTOCOL = None
    VERSION = None

    def __init__(self):
        self._route_map = None

    def build_type(
            self,
            type_name: str,
            doc_uri: str = None,
            protocol: str = None,
            version: str = None
                ):
        """ Construct a type string using this module's context. """
        doc_uri = doc_uri if doc_uri is not None else self.DOC_URI
        protocol = protocol if protocol is not None else self.PROTOCOL
        version = version if version is not None else self.VERSION

        if doc_uri is None:
            raise TypeError('doc_uri must be a string')
        if protocol is None:
            raise TypeError('protocol must be a string')
        if version is None:
            raise TypeError('version must be a string')

        return Type(doc_uri, protocol, version, type_name)

    def _discover_routes(self):
        discovered = {}
        for attr_name in dir(self):
            if attr_name == 'routes' or attr_name.startswith('__'):
                continue
            attribute_value = getattr(self, attr_name)
            if hasattr(attribute_value, 'handler_for'):
                message_type = attribute_value.handler_for
                if isinstance(message_type, IncompleteType):
                    message_type = message_type.resolve(self)
                discovered[message_type] = attribute_value
        return discovered

    @property
    def routes(self):
        """ Retrieve the static routes defined for this module and cache them. """
        if self._route_map is None:
            self._route_map = self._discover_routes()
        return self._route_map

class IncompleteType():
    """ Represents partial type information for a route before full module context is available,
        typically used during static route definitions within a module.
    """
    __slots__ = (
        'doc_uri',
        'protocol',
        'version',
        'name'
    )

    def __init__(
            self,
            name: str,
            doc_uri: str = None,
            protocol: str = None,
            version: str = None
                ):
        self.name = name
        self.version = version
        self.protocol = protocol
        self.doc_uri = doc_uri

    def resolve(self, mod: BaseModule) -> Type:
        """ Return a complete Type object using the module's metadata as fallbacks. """
        doc_uri = self.doc_uri if self.doc_uri else type(mod).DOC_URI
        protocol = self.protocol if self.protocol else type(mod).PROTOCOL
        version = self.version if self.version else type(mod).VERSION

        if doc_uri is None:
            raise TypeError('doc_uri must be a string')
        if protocol is None:
            raise TypeError('protocol must be a string')
        if version is None:
            raise TypeError('version must be a string')

        return Type(doc_uri, protocol, version, self.name)

def route(*args, **kwargs):
    """ Decorator for defining message routes.
        Usage:
            - @route (without parentheses) applies to the decorated function directly
            - @route("type_string") uses the provided type string
            - @route(name="...", doc_uri="...", ...) uses keyword arguments
    """
    if args:
        target = args[0]

        if callable(target):
            func = target
            func.handler_for = IncompleteType(func.__name__)
            return func

        if isinstance(target, str):
            msg_type_str = target
            def _apply_route(func):
                func.handler_for = Type.from_str(msg_type_str)
                return func
            return _apply_route

        if isinstance(target, Type):
            msg_type_obj = target
            def _apply_route(func):
                func.handler_for = msg_type_obj
                return func
            return _apply_route

    if kwargs:
        def _apply_route(func):
            name = kwargs.get('name', func.__name__)
            del kwargs['name']
            func.handler_for = IncompleteType(name, **kwargs)
            return func
        return _apply_route

    raise ValueError(
        'Expected either @route or @route("type_string") before a function!'
    )

# Music bot module for Discord
from discord.embeds import Embed
from discord.ext import commands
import youtube_dl
import asyncio
import pafy
import discord
import datetime

class AudioPlayer(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.music_queue = {}

        self.initialize()

    def initialize(self):
        for server in self.bot.guilds:
            self.music_queue[server.id] = []

    async def next_track(self, ctx):
        if len(self.music_queue[ctx.guild.id]) > 0:
            ctx.voice_client.stop()
            await self.start_audio(ctx, self.music_queue[ctx.guild.id][0])
            self.music_queue[ctx.guild.id].pop(0)

    async def fetch_song(self, count, query, return_url=False):
        data = await self.bot.loop.run_in_executor(None, lambda: youtube_dl.YoutubeDL({"format": "bestaudio", "quiet": True}).extract_info(f'ytsearch{count}:{query}', download=False, ie_key="YoutubeSearch"))
        if len(data["entries"]) == 0: return None

        return [item["webpage_url"] for item in data["entries"]] if return_url else data

    async def start_audio(self, ctx, track):
        audio_url = pafy.new(track).getbestaudio().url
        ctx.voice_client.play(discord.PCMVolumeTransformer(discord.FFmpegPCMAudio(audio_url)), after=lambda error: self.bot.loop.create_task(self.next_track(ctx)))
        ctx.voice_client.source.volume = 0.5

    @commands.command(
        name="join",
        description='Connects to voice channel.',
        usage="join",
        aliases=['connect']
    )
    async def join_channel(self, ctx):
        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")

        target_channel = ctx.author.voice.channel
        if ctx.voice_client is None:
            await target_channel.connect()
            await ctx.send(f"Successfully Connected to **{target_channel}**.")
        else:
            if len(ctx.voice_client.channel.members) == 1:
                ctx.voice_client.stop()
                await ctx.voice_client.move_to(target_channel)
                await ctx.send(f"Successfully Connected to **{target_channel}**.")
            else:
                await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="disconnect",
        description='Leaves voice channel.',
        usage="disconnect",
        aliases=['leave', 'dc']
    )
    async def leave_channel(self, ctx):
        voice = ctx.voice_client

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")
        elif ctx.voice_client is None:
            await ctx.send("I'm not in a voice channel.")
        else:
            if ctx.author.voice.channel == voice.channel:
                ctx.voice_client.stop()
                await ctx.voice_client.disconnect()
                await ctx.send(f"Successfully Disconnected from **{voice.channel}**.")
            else:
                if len(ctx.voice_client.channel.members) == 1:
                    ctx.voice_client.stop()
                    await ctx.voice_client.disconnect()
                    await ctx.send(f"Successfully Disconnected from **{voice.channel}**.")
                else:
                    await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="play",
        description='Plays song from url into voice channel.',
        usage='play [url/song_name]',
        aliases=['start', 'p']
    )
    async def play_track(self, ctx, *, track=None):
        voice = ctx.voice_client

        if track is None:
            await ctx.send("Please include a song to play.")

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")

        if not ("youtube.com/watch?" in track or "https://youtu.be/" in track):
            result = await self.fetch_song(1, track, get_url=True)

            if result is None:
                return await ctx.send("Couldn't find entered song.")

            track = result[0]

        voice_channel = ctx.author.voice.channel
        if ctx.voice_client is None:
            await voice_channel.connect()
            await self.start_audio(ctx, track)
            await ctx.send(f"Now playing {track}")
        else:
            if ctx.voice_client.source is not None:
                if ctx.author.voice.channel == voice.channel:
                    queue_size = len(self.music_queue[ctx.guild.id])

                    if queue_size < 10:
                        self.music_queue[ctx.guild.id].append(track)
                        return await ctx.send("Song has been added to queue.")
                    else:
                        return await ctx.send("I can only queue up to 10 songs, please wait for the current song to finish.")
                else:
                    if len(ctx.voice_client.channel.members) == 1:
                        ctx.voice_client.stop()
                        await ctx.voice_client.move_to(voice_channel)
                        await self.start_audio(ctx, track)
                        await ctx.send(f"Now playing {track}")
                    else:
                        return await ctx.send("Someone else is already listening to music in different channel.")

            if ctx.author.voice.channel == voice.channel:
                await self.start_audio(ctx, track)
                await ctx.send(f"Now playing {track}")
            else:
                if len(ctx.voice_client.channel.members) == 1:
                    ctx.voice_client.stop()
                    await ctx.voice_client.move_to(voice_channel)
                    await self.start_audio(ctx, track)
                    await ctx.send(f"Now playing {track}")
                else:
                    await ctx.send("Someone else is already listening to music in different channel.")

    @commands.command(
        name="queue",
        description="Shows all songs in queue.",
        usage='queue',
        aliases=['list', 'q']
    )
    async def show_queue(self, ctx):
        if len(self.music_queue[ctx.guild.id]) == 0:
            return await ctx.send("There is currently no songs in queue.")

        embed = discord.Embed(title="Song Queue", description="", timestamp=datetime.datetime.utcnow(), color=0x86242a)
        embed.set_footer(text=f"Requested by {ctx.author}", icon_url=ctx.author.avatar_url)
        embed.set_thumbnail(url=self.bot.user.avatar_url)
        index = 1
        for url in self.music_queue[ctx.guild.id]:
            embed.description += f"{index}) {url}\n"

            index += 1

        await ctx.send(embed=embed)

    @commands.command(
        name="skip",
        description="Skips current song.",
        usage='skip'
    )
    async def skip_track(self, ctx):
        voice = ctx.voice_client

        if ctx.author.voice is None:
            await ctx.send("You must be connected to a voice channel to use this command.")
        elif ctx.voice_client is None:
            await ctx.send("I'm not in a voice channel.")
        else:
            if ctx.author.voice.channel == voice.channel:
                poll_message = await ctx.send("Skip current song? 80% of the voice channel must vote to skip. Voting ends in 15 seconds.")

                poll_id = poll_message.id

                await poll_message.add_reaction(u"\u2705")
                await poll_message.add_reaction(u"\U0001F6AB")

                await asyncio.sleep(15)

                poll_msg = await ctx.channel.fetch_message(poll_id)

                votes = {u"\u2705": 0, u"\U0001F6AB": 0}
                participants = []

                for reaction in poll_msg.reactions:
                    if reaction.emoji in [u"\u2705", u"\U0001F6AB"]:
                        async for user in reaction.users():
                            if user.voice.channel.id == ctx.voice_client.channel.id and user.id not in participants and not user.bot:
                                votes[reaction.emoji] += 1

                                participants.append(user.id)

                proceed = False

                if votes[u"\u2705"] > 0:
                    if votes[u"\U0001F6AB"] == 0 or votes[u"\u2705"] / (votes[u"\u2705"] + votes[u"\U0001F6AB"]) > 0.79:
                        proceed = True
                        await ctx.send("Voted song has been skipped.")

                if not proceed:
                    await ctx.send("Voted song has not been skipped.")

                await poll_message.clear_reactions()

                if proceed:
                    ctx.voice_client.stop()
                    await self.next_track(ctx)
            else:
