from workshops.tests.base import TestBase
from workshops.lookups import urlpatterns

class TestLookupsRegression(TestBase):
    """Ensure lookup views are properly protected by authentication."""

    def setUp(self):
        # Set up URL patterns excluding non-restricted lookups
        self.exempt_patterns = ('language-lookup', )
        self.restricted_urlpatterns = list(
            filter(
                lambda pattern: pattern.name not in self.exempt_patterns,
                urlpatterns
            )
        )

    def test_authentication_required(self):
        """Verify that restricted lookups require login"""
        for pattern in self.restricted_urlpatterns:
            response = self.client.get(reverse(pattern.name))
            self.assertEqual(response.status_code, 403, pattern.name)  # forbidden

        self._setUpUsersAndLogin()

        for pattern in self.restricted_urlpatterns:
            response = self.client.get(reverse(pattern.name))
            self.assertEqual(response.status_code, 200, pattern.name)  # OK

# Extension to show all open windows in dmenu and switch to selected one
from libqtile.extension.dmenu import Dmenu
from libqtile.scratchpad import ScratchPad

class WindowMenu(Dmenu):
    """
    Display a vertical list of all active windows using dmenu.
    Allows switching to the chosen window.
    """
    defaults = [
        ("label_format", "{group}.{index}: {title}", "format for menu entries"),
        (
            "scope_all",
            True,
            "If True, include windows from all groups; otherwise only current group",
        ),
        ("menu_height", "80", "Display items vertically. Set to None for horizontal"),
    ]

    def __init__(self, **config):
        Dmenu.__init__(self, **config)
        self.add_defaults(WindowMenu.defaults)

    def gather_windows(self):
        counter = 0
        self.window_mapping = {}
        if self.scope_all:
            active_windows = self.qtile.windows_map.values()
        else:
            active_windows = self.qtile.current_group.windows

        for window in active_windows:
            if window.group and not isinstance(window.group, ScratchPad):
                entry = self.label_format.format(
                    group=window.group.label or window.group.name,
                    index=counter,
                    title=window.name
                )
                self.window_mapping[entry] = window
                counter += 1

    def execute(self):
        self.gather_windows()
        result = super().run(items=self.window_mapping.keys())
        try:
            selection = result.rstrip("\n")
        except AttributeError:
            # result is not a string (e.g., Popen object when no items available)
            return

        try:
            target_window = self.window_mapping[selection]
        except KeyError:
            # Selected window may have been closed while menu was displayed
            return

        current_screen = self.qtile.current_screen
        current_screen.set_group(target_window.group)
        target_window.group.focus(target_window)

