# Calculate total time for model training and evaluation
import argparse
import logging
import math
import torch
import os
import sys
from dataclasses import dataclass, field
from typing import Optional
from datasets import load_dataset
import transformers
from transformers import (
    CONFIG_MAPPING,
    MODEL_FOR_CAUSAL_LM_MAPPING,
    AutoConfig,
    AutoModelForCausalLM,
    AutoTokenizer,
    HfArgumentParser,
    Trainer,
    TrainingArguments,
    default_data_collator,
    set_seed,
)
from transformers.trainer_utils import get_last_checkpoint, is_main_process
from transformers.utils import check_min_version

check_min_version("4.5.0.dev0")
logger = logging.getLogger(__name__)

def synchronize_cuda():
    event = torch.cuda.Event()
    event.record()
    event.synchronize()

MODEL_CONFIG_CLASSES = list(MODEL_FOR_CAUSAL_LM_MAPPING.keys())
MODEL_TYPES = tuple(conf.model_type for conf in MODEL_CONFIG_CLASSES)

start_event = torch.cuda.Event(enable_timing=True)
end_event = torch.cuda.Event(enable_timing=True)
start_event.record()

@dataclass
class ModelArguments:
    """
    Arguments related to model, configuration, and tokenizer selection.
    """
    model_name_or_path: Optional[str] = field(
        default=None,
        metadata={
            "help": "Path to pre-trained model or shortcut name."
        },
    )
    model_type: Optional[str] = field(
        default=None,
        metadata={"help": "If training from scratch, specify a model type from: " + ", ".join(MODEL_TYPES)},
    )
    config_name: Optional[str] = field(
        default=None, metadata={"help": "Pretrained config name or path if different from model name"}
    )
    tokenizer_name: Optional[str] = field(
        default=None, metadata={"help": "Pretrained tokenizer name or path if different from model name"}
    )
    cache_dir: Optional[str] = field(
        default=None,
        metadata={"help": "Directory to store downloaded pre-trained models."},
    )
    use_fast_tokenizer: bool = field(
        default=True,
        metadata={"help": "Use fast tokenizer (tokenizers library) or not."},
    )
    model_revision: str = field(
        default="main",
        metadata={"help": "Specific model version (branch, tag, or commit)."},
    )
    use_auth_token: bool = field(
        default=False,
        metadata={
            "help": "Use token generated by `transformers-cli login` for private models."
        },
    )

@dataclass
class DataTrainingArguments:
    """
    Arguments related to dataset and preprocessing.
    """
    dataset_name: Optional[str] = field(
        default=None, metadata={"help": "Dataset name via datasets library."}
    )
    dataset_config_name: Optional[str] = field(
        default=None, metadata={"help": "Dataset configuration name via datasets library."}
    )
    train_file: Optional[str] = field(default=None, metadata={"help": "Training data file (text, csv, json)."})
    validation_file: Optional[str] = field(
        default=None,
        metadata={"help": "Optional evaluation data file for perplexity calculation."},
    )
    max_train_samples: Optional[int] = field(
        default=None,
        metadata={
            "help": "Limit number of training examples for debugging or faster training."
        },
    )
    max_val_samples: Optional[int] = field(
        default=None,
        metadata={
            "help": "Limit number of validation examples for debugging or faster training."
        },
    )
    block_size: Optional[int] = field(
        default=None,
        metadata={
            "help": "Sequence length after tokenization. Default uses model's max length."
        },
    )
    overwrite_cache: bool = field(
        default=False, metadata={"help": "Overwrite cached datasets."}
    )
    validation_split_percentage: Optional[int] = field(
        default=5,
        metadata={
            "help": "Percentage of training data used as validation when no split exists."
        },
    )
    preprocessing_num_workers: Optional[int] = field(
        default=None,
        metadata={"help": "Number of processes for preprocessing."},
    )

    def __post_init__(self):
        if self.dataset_name is None and self.train_file is None and self.validation_file is None:
            raise ValueError("Specify either dataset_name or train/validation files.")
        else:
            if self.train_file is not None:
                ext = self.train_file.split(".")[-1]
                assert ext in ["csv", "json", "txt"], "train_file must be csv, json, or txt."
            if self.validation_file is not None:
                ext = self.validation_file.split(".")[-1]
                assert ext in ["csv", "json", "txt"], "validation_file must be csv, json, or txt."

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--max_iterations", default=3000, type=int, help="Maximum iterations per epoch")

    hf_parser = HfArgumentParser((ModelArguments, DataTrainingArguments, TrainingArguments))

    if len(sys.argv) == 2 and sys.argv[1].endswith(".json"):
        model_args, data_args, training_args = hf_parser.parse_json_file(json_file=os.path.abspath(sys.argv[1]))
    else:
        model_args, data_args, training_args = hf_parser.parse_args_into_dataclasses()

    # Check for existing checkpoint
    last_checkpoint = None
    if os.path.isdir(training_args.output_dir) and training_args.do_train and not training_args.overwrite_output_dir:
        last_checkpoint = get_last_checkpoint(training_args.output_dir)
        if last_checkpoint is None and len(os.listdir(training_args.output_dir)) > 0:
            raise ValueError(f"Output directory ({training_args.output_dir}) exists and is not empty.")
        elif last_checkpoint is not None:
            logger.info(f"Resuming training from checkpoint {last_checkpoint}.")

    # Setup logging
    logging.basicConfig(
        format="%(asctime)s - %(levelname)s - %(name)s -   %(message)s",
        datefmt="%m/%d/%Y %H:%M:%S",
        handlers=[logging.StreamHandler(sys.stdout)],
    )
    logger.setLevel(logging.INFO if is_main_process(training_args.local_rank) else logging.WARN)

    logger.warning(
        f"Process rank: {training_args.local_rank}, device: {training_args.device}, n_gpu: {training_args.n_gpu}, "
        f"distributed training: {bool(training_args.local_rank != -1)}, 16-bits training: {training_args.fp16}"
    )

    if is_main_process(training_args.local_rank):
        transformers.utils.logging.set_verbosity_info()
        transformers.utils.logging.enable_default_handler()
        transformers.utils.logging.enable_explicit_format()

    logger.info("Training/evaluation parameters %s", training_args)
    set_seed(training_args.seed)

    # Load dataset
    if data_args.dataset_name is not None:
        raw_datasets = load_dataset(data_args.dataset_name, data_args.dataset_config_name)
        if "validation" not in raw_datasets:
            raw_datasets["validation"] = load_dataset(
                data_args.dataset_name, data_args.dataset_config_name,
                split=f"train[:{data_args.validation_split_percentage}%]"
            )
            raw_datasets["train"] = load_dataset(
                data_args.dataset_name, data_args.dataset_config_name,
                split=f"train[{data_args.validation_split_percentage}%:]"
            )
    else:
        data_files = {}
        if data_args.train_file is not None:
            data_files["train"] = data_args.train_file
        if data_args.validation_file is not None:
            data_files["validation"] = data_args.validation_file

        ext = (
            data_args.train_file.split(".")[-1]
            if data_args.train_file is not None
            else data_args.validation_file.split(".")[-1]
        )
        if ext == "txt":
            ext = "text"
        raw_datasets = load_dataset(ext, data_files=data_files)

    # Load config and tokenizer
    config_kwargs = {
        "cache_dir": model_args.cache_dir,
        "revision": model_args.model_revision,
        "use_auth_token": True if model_args.use_auth_token else None,
    }

    if model_args.config_name:
        config = AutoConfig.from_pretrained(model_args.config_name, **config_kwargs)
    elif model_args.model_name_or_path:
        config = AutoConfig.from_pretrained(model_args.model_name_or_path, **config_kwargs)
    else:
        config = CONFIG_MAPPING[model_args.model_type]()
        logger.warning("Initializing new config from scratch.")

    tokenizer_kwargs = {
        "cache_dir": model_args.cache_dir,
        "use_fast": model_args.use_fast_tokenizer,
        "revision": model_args.model_revision,
        "use_auth_token": True if model_args.use_auth_token else None,
    }

    if model_args.tokenizer_name:
        tokenizer = AutoTokenizer.from_pretrained(model_args.tokenizer_name, **tokenizer_kwargs)
    elif model_args.model_name_or_path:
        tokenizer = AutoTokenizer.from_pretrained(model_args.model_name_or_path, **tokenizer_kwargs)
    else:
        raise ValueError("Tokenizer must be specified with --tokenizer_name or model_name_or_path.")

    if model_args.model_name_or_path:
        model = AutoModelForCausalLM.from_pretrained(
            model_args.model_name_or_path,
            from_tf=bool(".ckpt" in model_args.model_name_or_path),
            config=config,
            cache_dir=model_args.cache_dir,
            revision=model_args.model_revision,
            use_auth_token=True if model_args.use_auth_token else None,
        )
    else:
        logger.info("Training new model from scratch")
        model = AutoModelForCausalLM.from_config(config)

    model.resize_token_embeddings(len(tokenizer))

    # Tokenize datasets
    column_names = list(raw_datasets["train"].column_names) if training_args.do_train else list(raw_datasets["validation"].column_names)
    text_column = "text" if "text" in column_names else column_names[0]

    def tokenize_batch(examples):
        return tokenizer(examples[text_column])

    tokenized_datasets = raw_datasets.map(
        tokenize_batch,
        batched=True,
        num_proc=data_args.preprocessing_num_workers,
        remove_columns=column_names,
        load_from_cache_file=not data_args.overwrite_cache,
    )

    # Determine block size
    if data_args.block_size is None:
        block_size = min(tokenizer.model_max_length, 1024)
        if tokenizer.model_max_length > 1024:
            logger.warn(f"Using block_size=1024 instead of tokenizer's large model_max_length={tokenizer.model_max_length}")
    else:
        block_size = min(data_args.block_size, tokenizer.model_max_length)
        if data_args.block_size > tokenizer.model_max_length:
            logger.warn(f"block_size ({data_args.block_size}) exceeds model max length. Using {tokenizer.model_max_length}.")

    # Group texts into chunks
    def prepare_lm_batch(examples):
        concatenated = {key: sum(examples[key], []) for key in examples.keys()}
        total_len = len(concatenated[list(examples.keys())[0]])
        total_len = (total_len // block_size) * block_size
        result = {
            key: [t[i:i+block_size] for i in range(0, total_len, block_size)]
            for key, t in concatenated.items()
        }
        result["labels"] = result["input_ids"].copy()
        return result

    lm_datasets = tokenized_datasets.map(
        prepare_lm_batch,
        batched=True,
        num_proc=data_args.preprocessing_num_workers,
        load_from_cache_file=not data_args.overwrite_cache,
    )

    train_dataset = lm_datasets["train"]
    eval_dataset = lm_datasets["validation"]

    if data_args.max_train_samples is not None:
        train_dataset = train_dataset.select(range(data_args.max_train_samples))
    if data_args.max_val_samples is not None:
        eval_dataset = eval_dataset.select(range(data_args.max_val_samples))

    # Initialize trainer
    trainer = Trainer(
        model=model,
        args=training_args,
        train_dataset=train_dataset if training_args.do_train else None,
        eval_dataset=eval_dataset if training_args.do_eval else None,
        tokenizer=tokenizer,
        data_collator=default_data_collator,
    )

    # Training
    if training_args.do_train:
        checkpoint = last_checkpoint or model_args.model_name_or_path if os.path.isdir(model_args.model_name_or_path) else None
        train_result = trainer.train(resume_from_checkpoint=checkpoint)
        trainer.save_model()
        metrics = train_result.metrics
        samples_count = min(data_args.max_train_samples or len(train_dataset), len(train_dataset))
        metrics["train_samples"] = samples_count
        trainer.log_metrics("train", metrics)
        trainer.save_metrics("train", metrics)
        trainer.save_state()

    # Evaluation
    if training_args.do_eval:
        logger.info("*** Evaluating ***")
        metrics = trainer.evaluate()
        val_samples = min(data_args.max_val_samples or len(eval_dataset), len(eval_dataset))
        metrics["eval_samples"] = val_samples
        metrics["perplexity"] = math.exp(metrics["eval_loss"])
        trainer.log_metrics("eval", metrics)
        trainer.save_metrics("eval", metrics)

