import sys

def dot_product(a, b):
    assert len(a) == len(b)
    return sum(a[i] * b[i] for i in range(len(a)))

def perpendicular(v):
    return -v[1], v[0]

def check_possible(state_q, state_p):
    upward = state_q[1] or state_p[0]
    downward = state_q[2] or state_p[1]
    return upward and downward

def check_impossible(state_q, state_p):
    upward = state_q[0] or state_q[1] or state_p[0]
    downward = state_q[2] or state_q[3] or state_p[1]
    if upward ^ downward:
        return True
    leftward = state_q[1] or state_q[2]
    if not leftward:
        return True

def can_form_polygon(count, vectors):
    # Convert original vectors to direction vectors relative to first component
    direction_vectors = [(v[1] - v[0], v[2] - v[0]) for v in vectors]

    # Start with the first direction vector as reference
    current_axis = direction_vectors[0]

    while current_axis:
        # Get perpendicular axis (rotated 90 degrees)
        perp_axis = perpendicular(current_axis)

        # Initialize quadrant flags and axis flags
        quadrants = [False] * 4
        axes_flags = [False] * 2
        candidates = [None] * 2

        # Process each vector
        for vec in direction_vectors:
            # Project onto current and perpendicular axes
            proj_x = dot_product(vec, current_axis)
            proj_y = dot_product(vec, perp_axis)

            if proj_x == 0:
                # Vector is parallel to perpendicular axis
                if proj_y < 0:
                    axes_flags[1] = True
                elif proj_y > 0:
                    axes_flags[0] = True
                # Skip zero vector case
            elif proj_x > 0:
                # In positive x half-plane
                if proj_y > 0:
                    quadrants[0] = True
                    candidates[0] = vec
                elif proj_y < 0:
                    quadrants[3] = True
                # Skip same direction as current_axis
            else:
                # In negative x half-plane
                if proj_y > 0:
                    quadrants[1] = True
                    candidates[1] = vec
                elif proj_y < 0:
                    quadrants[2] = True
                else:
                    # Found opposite vector to current_axis
                    return True

            # Check if solution is possible with current configuration
            if check_possible(quadrants, axes_flags):
                return True

        # Check if solution is impossible
        if check_impossible(quadrants, axes_flags):
            return False

        # Ensure we have a candidate to continue iteration
        assert candidates[1] or candidates[0]

        # Update current axis based on candidate
        if candidates[1]:
            current_axis = candidates[1]
        else:
            current_axis = candidates[0]

    return True

# Test cases from original code
assert can_form_polygon(4, [[1, 2, 3], [1, 11, 5], [9, 4, 3], [2, 3, 2]])
assert can_form_polygon(3, [[5, 3, 1], [1, 2, 2], [2, 1, 1]])
assert not can_form_polygon(4, [[1, 3, 3], [1, 11, 5], [9, 4, 3], [2, 3, 2]])
assert can_form_polygon(2, [[1, 2, 2], [2, 1, 1]])

