# Factory pattern implementation for memory optimization strategies
from enum import Enum

class MemoryOptimizationStrategyType(str, Enum):
    """Defines available memory optimization approaches."""
    COMPRESS = "compress"

class StrategyFactory:
    """Factory class responsible for instantiating memory optimization strategies."""

    @classmethod
    def generate_strategy(cls, strategy_kind: MemoryOptimizationStrategyType, **options) -> object:
        """Generate a strategy instance based on the specified type and options.

        Args:
            strategy_kind: The type of strategy to instantiate
            **options: Additional configuration parameters for the strategy

        Returns:
            An instance implementing the requested strategy
        """
        strategy_registry = {
            MemoryOptimizationStrategyType.COMPRESS: cls._build_compress_strategy,
        }
        return strategy_registry[strategy_kind](**options)

    @classmethod
    def _build_compress_strategy(cls, **config) -> object:
        from app.core.agent.memory.strategies.compress import CompressStrategy
        return CompressStrategy(**config)

# Script to load and print NumPy data files with full precision
import argparse

try:
    import argcomplete
except ImportError:
    argcomplete = None

import numpy as np

def parse_args():
    parser = argparse.ArgumentParser(description="Load and display NumPy data files")
    parser.add_argument("input_files", metavar="file", nargs="+", help="Path to NumPy data file(s)")

    if argcomplete:
        argcomplete.autocomplete(parser)

    return parser.parse_args()

def run():
    options = parse_args()

    with np.printoptions(threshold=np.inf):
        for filepath in options.input_files:
            print(np.load(filepath))

if __name__ == "__main__":
    run()

# Modified version with Type I clone transformations
from common.session_manager import SessionManager

class _MockCheckpointer:
    def __init__(self, store):
        self.store = store

class _Config:
    def __init__(self, session_id: str):
        self.configurable = {"thread_id": session_id}

    def __hash__(self) -> int:  # pragma: no cover
        return hash(self.configurable["thread_id"])

    def __eq__(self, other: object) -> bool:  # pragma: no cover
        return isinstance(other, _Config) and other.configurable == self.configurable

def test_list_sessions_with_user_filter():
    checkpointer = _MockCheckpointer(
        store={
            _Config("session_alice"): {
                "channel_values": {
                    "user_id": "alice",
                    "message": "hello",
                    "path": "direct",
                }
            },
            _Config("session_bob"): {
                "channel_values": {
                    "user_id": "bob",
                    "message": "hi",
                    "path": "direct",
                }
            },
        }
    )
    manager = SessionManager(checkpointer)
    result_sessions = manager.list_sessions(limit=50, user_id_filter="alice")
    assert [s.thread_id for s in result_sessions] == ["session_alice"]

# Register dataclass types for PyTree support in torch
from dataclasses import fields, is_dataclass
from typing import Any
from torch.utils import _pytree

_REGISTERED_DATACLASSES: set[type[Any]] = set()

def register_dataclass_for_pytree(cls: type[Any]) -> None:
    """Register a dataclass so that torch's pytree can traverse its fields."""
    if cls in _REGISTERED_DATACLASSES:
        return
    if not is_dataclass(cls):
        return

    field_names = tuple(f.name for f in fields(cls))

    def _flatten_instance(instance: Any):
        return [getattr(instance, name) for name in field_names], field_names

    def _unflatten_instance(values: list[Any], context: tuple[str, ...]):
        kwargs = dict(zip(context, values))
        return cls(**kwargs)

    try:
        _pytree.register_pytree_node(cls, _flatten_instance, _unflatten_instance)
    except ValueError:
        # Already registered in this process.
        pass

    _REGISTERED_DATACLASSES.add(cls)

def register_nested_dataclasses(obj: Any) -> None:
    """Recursively register all dataclass types found within the given object structure."""
    if is_dataclass(obj) and not isinstance(obj, type):
        register_dataclass_for_pytree(type(obj))
        for field in fields(obj):
            register_nested_dataclasses(getattr(obj, field.name))
        return

    if isinstance(obj, dict):
        for value in obj.values():
            register_nested_dataclasses(value)
        return

    if isinstance(obj, (list, tuple)):
        for item in obj:
            register_nested_dataclasses(item)

