@pytest.fixture
def approval_hook():
    class ApprovalHook(HookProvider):
        def register_hooks(self, registry):
            registry.add_callback(BeforeToolCallEvent, self.handle_approval)

        def handle_approval(self, event):
            if event.tool_use["name"] == "weather_tool":
                return

            interruption = event.interrupt("test_interrupt", reason="need approval")
            if interruption != "APPROVE":
                event.cancel_tool = "tool rejected"

    return ApprovalHook()

@pytest.fixture
def clock_tool():
    @tool(name="time_tool")
