def test_interrupt_handling(main_agent):
    # First call to trigger interrupt
    actual_result = main_agent("What is the time and weather?")
    actual_stop_reason = actual_result.stop_reason
    expected_stop_reason = "interrupt"
    assert actual_stop_reason == expected_stop_reason

    actual_interrupts = actual_result.interrupts
    expected_interrupts = [
        Interrupt(
            id=ANY,
            name="test_interrupt",
            reason="need approval",
        ),
    ]
    assert actual_interrupts == expected_interrupts

    # Get the first interrupt ID for response
    interrupt_obj = actual_interrupts[0]

    # Provide approval response
    responses = [
        {
            "interruptResponse": {
                "interruptId": interrupt_obj.id,
                "response": "APPROVE",
            },
        },
    ]

    # Second call after approval
    final_result = main_agent(responses)
    actual_stop_reason = final_result.stop_reason
    expected_stop_reason = "end_turn"
    assert actual_stop_reason == expected_stop_reason

    result_text = json.dumps(final_result.message).lower()
    assert all(item in result_text for item in ["12:00", "sunny"])

    # Check tool results message
    actual_tool_message = main_agent.messages[-2]
    expected_tool_message = {
        "role": "user",
        "content": [
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [
                        {"text": "sunny"},
                    ],
                },
            },
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [
                        {"text": "12:00"},
                    ],
                },
            },
        ],
    }
    assert actual_tool_message == expected_tool_message

def test_interrupt_rejection(main_agent):
