# Utility function to shard and place arrays on devices
import math
from typing import Tuple
import jax
from jax.sharding import NamedSharding
from jax.sharding import PartitionSpec as P

def distribute_to_devices(
    array: jax.Array,
    axis_names: Tuple[str, ...] | P,
    device_mesh: jax.sharding.Mesh
) -> jax.Array:
    # Handle single-device case explicitly to prevent nested JIT compilation issues
    if math.prod(device_mesh.axis_sizes) == 1:
        return jax.device_put(array, device_mesh.devices.flatten()[0])

    return jax.device_put(
        array, 
        NamedSharding(device_mesh, P(*axis_names))
    )

# Trust Store Management Routes v2.0
# API endpoints for managing trusted certificates
"""
from flask import Blueprint, request, g
from auth.unified import require_auth
from utils.response import success_response, error_response, created_response, no_content_response
from models import db
from models.truststore import TrustedCertificate
from services.audit_service import AuditService
from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.backends import default_backend
import hashlib
from datetime import datetime
import base64
import os

bp = Blueprint('truststore_v2', __name__)

import logging
logger = logging.getLogger(__name__)

def extract_certificate_info(pem_data):
    """
    Extract certificate information from PEM data

    Returns dict with subject, issuer, fingerprints, validity dates, etc.
    """
    try:
        cert = x509.load_pem_x509_certificate(pem_data.encode(), default_backend())

        # Extract subject and issuer information
        subject = cert.subject.rfc4514_string()
        issuer = cert.issuer.rfc4514_string()

        # Calculate cryptographic fingerprints
        cert_der = cert.public_bytes(serialization.Encoding.DER)
        sha256_hash = hashlib.sha256(cert_der).hexdigest()
        sha1_hash = hashlib.sha1(cert_der).hexdigest()

        return {
            'subject': subject,
            'issuer': issuer,
            'serial_number': format(cert.serial_number, 'X'),
            'valid_from': cert.not_valid_before_utc,
            'valid_until': cert.not_valid_after_utc,
            'sha256_fingerprint': sha256_hash,
            'sha1_fingerprint': sha1_hash,
        }
    except Exception as e:
        raise ValueError(f'Invalid certificate format: {str(e)}')

def decode_der_certificate(der_bytes):
    """Decode DER-encoded certificate to PEM format"""
    try:
        cert = x509.load_der_x509_certificate(der_bytes, default_backend())
        pem_string = cert.public_bytes(serialization.Encoding.PEM).decode('utf-8')
        return pem_string, extract_certificate_info(pem_string)
    except Exception as e:
        raise ValueError(f'Invalid DER certificate encoding: {str(e)}')

@bp.route('/api/v2/truststore/statistics', methods=['GET'])
@require_auth(['read:truststore'])
def get_truststore_statistics():
    """Retrieve trust store statistics summary"""
    current_time = datetime.utcnow()

    total_count = TrustedCertificate.query.count()
    root_cas = TrustedCertificate.query.filter_by(purpose='root_ca').count()
    intermediate_cas = TrustedCertificate.query.filter_by(purpose='intermediate_ca').count()
    expired_certs = TrustedCertificate.query.filter(TrustedCertificate.valid_until <= current_time).count()

    return success_response(data={
        'total_certificates': total_count,
        'root_authorities': root_cas,
        'intermediate_authorities': intermediate_cas,
        'expired_count': expired_certs,
        'active_count': total_count - expired_certs
    })

@bp.route('/api/v2/truststore/import', methods=['POST'])
@require_auth(['write:truststore'])
def import_certificate_to_store():
    """
    Import certificate via file upload

    Supports both PEM and DER formats
    """
    if 'file' not in request.files:
        return error_response('No file provided in request', 400)

    uploaded_file = request.files['file']
    if not uploaded_file.filename:
        return error_response('No file selected for upload', 400)

    from utils.file_validation import validate_upload, CERT_EXTENSIONS
    try:
        file_content, safe_name = validate_upload(uploaded_file, CERT_EXTENSIONS)
    except ValueError as validation_error:
        logger.error(f'Trust store file validation failed: {validation_error}')
        return error_response('Invalid file upload detected', 400)

    cert_name = request.form.get('name', safe_name.rsplit('.', 1)[0])
    cert_purpose = request.form.get('purpose', 'custom')
    cert_description = request.form.get('description', '')
    cert_notes = request.form.get('notes', '')

    try:
        # Attempt PEM format first
        if b'-----BEGIN CERTIFICATE-----' in file_content:
            pem_content = file_content.decode('utf-8')
            cert_info = extract_certificate_info(pem_content)
        else:
            # Try DER format
            pem_content, cert_info = decode_der_certificate(file_content)

        # Check for duplicate certificate
        existing_cert = TrustedCertificate.query.filter_by(
            sha256_fingerprint=cert_info['sha256_fingerprint']
        ).first()

        if existing_cert:
            return error_response(f'Certificate already exists in trust store as "{existing_cert.name}"', 409)

        # Create new trusted certificate record
        new_cert = TrustedCertificate(
            name=cert_name,
            description=cert_description,
            certificate_pem=pem_content,
            sha256_fingerprint=cert_info['sha256_fingerprint'],
            sha1_fingerprint=cert_info['sha1_fingerprint'],
            subject=cert_info['subject'],
            issuer=cert_info['issuer'],
            serial_number=cert_info['serial_number'],
            valid_from=cert_info['valid_from'],
            valid_until=cert_info['valid_until'],
            purpose=cert_purpose,
            added_by=g.current_user.username,
            notes=cert_notes
        )

        db.session.add(new_cert)
        db.session.commit()

        from services.audit_service import AuditService
        AuditService.log_action(
            action='truststore_import',
            resource_type='truststore',
            resource_id=new_cert.id,
            resource_name=new_cert.name,
            details=f'Imported certificate: {new_cert.name}',
            success=True
        )

        return created_response(
            data=new_cert.to_dict(),
            message=f'Certificate "{cert_name}" successfully imported to trust store'
        )

    except ValueError as parse_error:
        db.session.rollback()
        logger.error(f'Trust store import validation error: {parse_error}')
        return error_response('Invalid certificate data provided', 400)
    except Exception as import_error:
        db.session.rollback()
        logger.error(f'Trust store import failed: {import_error}')
        return error_response('Certificate import process failed', 500)

@bp.route('/api/v2/truststore', methods=['GET'])
@require_auth(['read:truststore'])
def list_certificates():
    """
    List all trusted certificates with optional filtering

    Query params:
    - purpose: Filter by certificate purpose
    - search: Search name, subject, fingerprint
    """
    filter_purpose = request.args.get('purpose')
    search_query = request.args.get('search', '').strip()

    query = TrustedCertificate.query

    if filter_purpose:
        query = query.filter_by(purpose=filter_purpose)

    if search_query:
        search_pattern = f'%{search_query}%'
        query = query.filter(
            db.or_(
                TrustedCertificate.name.ilike(search_pattern),
                TrustedCertificate.subject.ilike(search_pattern),
                TrustedCertificate.sha256_fingerprint.ilike(search_pattern)
            )
        )

    certificates = query.order_by(TrustedCertificate.added_at.desc()).all()

    return success_response(
        data=[cert.to_dict() for cert in certificates]
    )

@bp.route('/api/v2/truststore', methods=['POST'])
@require_auth(['write:truststore'])
def add_certificate():
    """
    Add certificate to trust store

    POST /api/v2/truststore
    {
        "name": "DigiCert Global Root CA",
        "description": "DigiCert public root CA",
        "certificate_pem": "-----BEGIN CERTIFICATE-----...",
        "purpose": "root_ca",
        "notes": "Trusted for code signing"
    }
    """
    request_data = request.get_json()

    # Required fields validation
    if not request_data.get('name'):
        return error_response('Certificate name is required', 400)
    if not request_data.get('certificate_pem'):
        return error_response('Certificate PEM data is required', 400)

    # Parse certificate data
    try:
        cert_info = extract_certificate_info(request_data['certificate_pem'])
    except ValueError as parse_error:
        logger.error(f'Trust store certificate parsing failed: {parse_error}')
        return error_response('Invalid certificate data provided', 400)

    # Check for duplicate certificate by fingerprint
    existing_cert = TrustedCertificate.query.filter_by(
        sha256_fingerprint=cert_info['sha256_fingerprint']
    ).first()

    if existing_cert:
        return error_response('Certificate already present in trust store', 409)

    # Create new certificate entry
    new_cert = TrustedCertificate(
        name=request_data['name'],
        description=request_data.get('description', ''),
        certificate_pem=request_data['certificate_pem'],
        sha256_fingerprint=cert_info['sha256_fingerprint'],
        sha1_fingerprint=cert_info['sha1_fingerprint'],
        subject=cert_info['subject'],
        issuer=cert_info['issuer'],
        serial_number=cert_info['serial_number'],
        valid_from=cert_info['valid_from'],
        valid_until=cert_info['valid_until'],
        purpose=request_data.get('purpose', 'custom'),
        added_by=g.current_user.username,
        notes=request_data.get('notes', '')
    )

    try:
        db.session.add(new_cert)
        db.session.commit()

        AuditService.log_action(
            action='truststore_add',
            resource_type='truststore',
            resource_id=str(new_cert.id),
            resource_name=new_cert.name,
            details=f'Added certificate to trust store: {new_cert.name}',
            success=True
        )

        return created_response(
            data=new_cert.to_dict(),
            message=f'Certificate {new_cert.name} added to trust store'
        )
