@bp.route('/api/v2/truststore/sync', methods=['POST'])
@require_auth(['write:truststore'])
def sync_trust_store_with_system():
    """
    Synchronize trust store with system CA bundle

    POST /api/v2/truststore/sync
    {
        "source": "system",  # "system" reads from /etc/ssl/certs
        "limit": 50          # Optional: limit number of certs to import
    }
    """
    request_data = request.get_json() or {}
    sync_source = request_data.get('source', 'system')
    max_import = request_data.get('limit', 50)

    SYSTEM_CA_PATH = '/etc/ssl/certs/ca-certificates.crt'

    if sync_source != 'system':
        return error_response('Only "system" source is currently supported', 400)

    if not os.path.exists(SYSTEM_CA_PATH):
        return error_response(f'System CA bundle not found at {SYSTEM_CA_PATH}', 404)

    try:
        # Read and parse system CA bundle
        with open(SYSTEM_CA_PATH, 'r') as ca_file:
            bundle_text = ca_file.read()

        # Split into individual certificates
        individual_certs = []
        current_cert_lines = []
        in_certificate = False

        for line in bundle_text.split('\n'):
            if '-----BEGIN CERTIFICATE-----' in line:
                in_certificate = True
                current_cert_lines = [line]
            elif '-----END CERTIFICATE-----' in line:
                current_cert_lines.append(line)
                individual_certs.append('\n'.join(current_cert_lines))
                in_certificate = False
                current_cert_lines = []
            elif in_certificate:
                current_cert_lines.append(line)

        imported_count = 0
        skipped_count = 0
        failed_count = 0

        for pem_cert in individual_certs[:max_import]:
            try:
                cert_info = extract_certificate_info(pem_cert)

                # Check if certificate already exists
                existing = TrustedCertificate.query.filter_by(
                    sha256_fingerprint=cert_info['sha256_fingerprint']
                ).first()

                if existing:
                    skipped_count += 1
                    continue

                # Extract CN for naming
                subject_str = cert_info['subject']
                common_name = None
                for part in subject_str.split(','):
                    if part.strip().startswith('CN='):
                        common_name = part.strip()[3:]
                        break

                cert_name = common_name or f"System CA {cert_info['sha256_fingerprint'][:8]}"

                new_trusted_cert = TrustedCertificate(
                    name=cert_name,
                    description='Imported from system CA bundle',
                    certificate_pem=pem_cert,
                    sha256_fingerprint=cert_info['sha256_fingerprint'],
                    sha1_fingerprint=cert_info['sha1_fingerprint'],
                    subject=cert_info['subject'],
                    issuer=cert_info['issuer'],
                    serial_number=cert_info['serial_number'],
                    valid_from=cert_info['valid_from'],
                    valid_until=cert_info['valid_until'],
                    purpose='system',
                    added_by='system_sync',
                    notes='Auto-imported from /etc/ssl/certs/ca-certificates.crt'
                )

                db.session.add(new_trusted_cert)
                imported_count += 1

            except Exception as cert_error:
                failed_count += 1
                continue

        db.session.commit()

        from services.audit_service import AuditService
        AuditService.log_action(
            action='truststore_sync',
            resource_type='truststore',
            resource_name='System CA Bundle',
            details=f'Synced {imported_count} new certificates from system',
            success=True
        )

        return success_response(
            message=f'Trust store synchronized: {imported_count} new, {skipped_count} duplicates',
            data={
                'source': sync_source,
                'total_found': len(individual_certs),
                'imported_count': imported_count,
                'skipped_count': skipped_count,
                'failed_count': failed_count
            }
        )

    except Exception as sync_error:
        db.session.rollback()
        logger.error(f'Failed to sync trust store: {sync_error}')
        return error_response('Failed to synchronize trust store', 500)

@bp.route('/api/v2/truststore/export', methods=['GET'])
@require_auth(['read:truststore'])
def export_trust_bundle():
    """
    Export trust store as a certificate bundle.

    GET /api/v2/truststore/export?format=pem&purpose=root_ca

    Query params:
      - format: pem (default), p7b
      - purpose: root_ca, intermediate_ca, system, all (default)
    """
    from flask import Response

    output_format = request.args.get('format', 'pem')
    filter_purpose = request.args.get('purpose', 'all')

    if output_format not in ('pem', 'p7b'):
        return error_response('Unsupported export format. Valid options: pem, p7b', 400)

    try:
        query = TrustedCertificate.query
        if filter_purpose != 'all':
            query = query.filter_by(purpose=filter_purpose)

        certs = query.order_by(TrustedCertificate.name).all()

        if not certs:
            return error_response('No certificates found matching specified criteria', 404)

        if output_format == 'pem':
            bundle_lines = []
            for cert in certs:
                bundle_lines.append(f'# {cert.name}')
                bundle_lines.append(cert.certificate_pem.strip())
                bundle_lines.append('')

            bundle_content = '\n'.join(bundle_lines)
            filename = f'truststore-{filter_purpose}-bundle.pem'

            return Response(
                bundle_content,
                mimetype='application/x-pem-file',
                headers={'Content-Disposition': f'attachment; filename="{filename}"'}
            )

        elif output_format == 'p7b':
            from cryptography.hazmat.primitives.serialization import pkcs7

            x509_certificates = []
            for cert in certs:
                try:
                    x509_cert = x509.load_pem_x509_certificate(
                        cert.certificate_pem.encode(), default_backend()
                    )
                    x509_certificates.append(x509_cert)
                except Exception:
                    continue

            if not x509_certificates:
                return error_response('No valid certificates available for export', 400)

            p7b_data = pkcs7.serialize_certificates(x509_certificates, serialization.Encoding.DER)

            filename = f'truststore-{filter_purpose}-bundle.p7b'
            return Response(
                p7b_data,
                mimetype='application/x-pkcs7-certificates',
                headers={'Content-Disposition': f'attachment; filename="{filename}"'}
            )

    except Exception as export_error:
        logger.error(f'Failed to export trust store bundle: {export_error}')
        return error_response('Failed to export trust store bundle', 500)

@bp.route('/api/v2/truststore/expiring', methods=['GET'])
@require_auth(['read:truststore'])
def get_expiring_certificates():
    """
    Get trusted certificates expiring within N days.

    GET /api/v2/truststore/expiring?days=90
    """
    from sqlalchemy import and_

    days_threshold = request.args.get('days', 90, type=int)

    try:
        current_time = datetime.utcnow()
        from datetime import timedelta
        future_threshold = current_time + timedelta(days=days_threshold)

        # Certificates expiring soon (valid but within threshold)
        expiring_soon = TrustedCertificate.query.filter(
            and_(
                TrustedCertificate.valid_until != None,
                TrustedCertificate.valid_until > current_time,
                TrustedCertificate.valid_until <= future_threshold
            )
        ).order_by(TrustedCertificate.valid_until.asc()).all()

        # Already expired certificates
        expired_certs = TrustedCertificate.query.filter(
            and_(
                TrustedCertificate.valid_until != None,
                TrustedCertificate.valid_until <= current_time
            )
        ).order_by(TrustedCertificate.valid_until.desc()).all()

        def format_cert_info(c):
            days_remaining = (c.valid_until - current_time).days if c.valid_until else None
            return {
                'id': c.id,
                'name': c.name,
                'subject': c.subject,
                'purpose': c.purpose,
                'valid_until': c.valid_until.isoformat() if c.valid_until else None,
                'days_remaining': days_remaining,
                'sha256_fingerprint': c.sha256_fingerprint,
            }

        return success_response(data={
            'expiring_soon': [format_cert_info(c) for c in expiring_soon],
            'expired': [format_cert_info(c) for c in expired_certs],
            'expiring_count': len(expiring_soon),
            'expired_count': len(expired_certs),
            'threshold_days': days_threshold,
        })

    except Exception as expiry_error:
        logger.error(f'Failed to retrieve expiring certificates: {expiry_error}')
        return error_response('Failed to retrieve expiring certificates', 500)

@bp.route('/api/v2/truststore/add-from-ca/<string:ca_identifier>', methods=['POST'])
@require_auth(['write:truststore'])
def add_ca_certificate_to_truststore(ca_identifier):
    """
    Add a managed CA's certificate to the Trust Store.

    POST /api/v2/truststore/add-from-ca/<ca_identifier>
    Body (optional): { "purpose": "root_ca", "notes": "..." }
    """
    from models import CA

    ca_record = CA.query.filter_by(refid=ca_identifier).first()
    if not ca_record:
        return error_response('CA record not found', 404)

    try:
        decoded_cert = base64.b64decode(ca_record.crt).decode('utf-8')
    except Exception:
        return error_response('Failed to decode CA certificate data', 500)

    # Validate certificate
    cert_metadata = extract_certificate_info(decoded_cert)
    if not cert_metadata:
        return error_response('Failed to parse CA certificate data', 500)

    # Check if already in Trust Store
    existing_entry = TrustedCertificate.query.filter_by(
        sha256_fingerprint=cert_metadata['sha256_fingerprint']
    ).first()
    if existing_entry:
        return error_response('This CA certificate is already in the Trust Store', 409)

    request_body = request.get_json(silent=True) or {}
    cert_purpose = request_body.get('purpose', 'root_ca' if ca_record.is_root else 'intermediate_ca')

    new_trusted = TrustedCertificate(
        name=ca_record.common_name or ca_record.descr or cert_metadata['subject'],
        certificate_pem=decoded_cert,
        subject=cert_metadata['subject'],
        issuer=cert_metadata['issuer'],
        serial_number=cert_metadata['serial_number'],
        valid_from=cert_metadata['valid_from'],
        valid_until=cert_metadata['valid_until'],
        sha256_fingerprint=cert_metadata['sha256_fingerprint'],
        sha1_fingerprint=cert_metadata['sha1_fingerprint'],
        purpose=cert_purpose,
        added_by=g.current_user.username,
        notes=request_body.get('notes', f'Added from managed CA: {ca_record.descr or ca_record.common_name}'),
    )

    db.session.add(new_trusted)
    db.session.commit()

    AuditService.log_action(
        action='truststore.add_from_ca',
        resource_type='truststore',
        resource_id=str(new_trusted.id),
        resource_name=new_trusted.name,
        details=f'Added managed CA "{ca_record.common_name or ca_record.descr}" to Trust Store'
    )

    return created_response(data={
        'id': new_trusted.id,
        'name': new_trusted.name,
        'sha256_fingerprint': new_trusted.sha256_fingerprint,
        'purpose': new_trusted.purpose,
    }, message=f'CA "{new_trusted.name}" added to Trust Store')

import contextlib
import os
from collections import defaultdict
from enum import Enum
import torch
from torch.autograd.graph import saved_tensors_hooks
from primus.modules.module_utils import log_rank_all

def compute_checksum(tensor):
    with torch.no_grad():
        if tensor.dtype == torch.float16:
            return torch.mean(tensor * tensor).sum().item()
        else:
            return 0

def is_same_storage(x, y):
    return (
        x.storage().data_ptr() == y.storage().data_ptr()
        and x.storage_offset() == y.storage_offset()
        and x.numel() == y.numel()
    )

def get_tensor_metadata(tensor):
    return (tensor.shape, tensor.layout, tensor.dtype, tensor.stride())

def capture_rng_states():
    from megatron.core.tensor_parallel.random import get_cuda_rng_tracker
    return torch.get_rng_state(), torch.cuda.get_rng_state(), get_cuda_rng_tracker().get_states()

def restore_rng_states(states):
    from megatron.core.tensor_parallel.random import (
        _set_cuda_rng_state,
        get_cuda_rng_tracker,
    )
    torch.set_rng_state(states[0])
    _set_cuda_rng_state(states[1])
    get_cuda_rng_tracker().set_states(states[2])

class PartialRecompute(saved_tensors_hooks):
    class SaveMode(Enum):
        DIRECT = 1
        RECOMPUTE = 2

    def _handle_save(self, tensor):
        if self._pending_recompute is not None and is_same_storage(tensor, self._pending_recompute[0]):
            packed = self._pending_recompute[1:]
            self._pending_recompute = None
            return PartialRecompute.SaveMode.RECOMPUTE, packed
        return PartialRecompute.SaveMode.DIRECT, tensor

    def _handle_load(self, packed):
        mode, info = packed
        if mode == PartialRecompute.SaveMode.RECOMPUTE:
            parents, function, rng_states = info
            with torch.no_grad():
                if rng_states is not None:
                    current_rng_states = capture_rng_states()
                    restore_rng_states(rng_states)
                r = function(*parents)
                if rng_states is not None:
                    restore_rng_states(current_rng_states)
            return r
        return info

    def __init__(self):
        self._pending_recompute = None
        super().__init__(self._handle_save, self._handle_load)

    def trigger_recompute(self, tensor, parents, function, rng_states=None):
        assert self._pending_recompute is None
        self._pending_recompute = (tensor, parents, function, rng_states)

partial_recompute = PartialRecompute()

class SynchronizedBarrier:
    prev_event = None
    curr_event = None

    @classmethod
    def record(cls):
        cls.prev_event = cls.curr_event
        from megatron.training import get_args
        if not get_args().synchronized_barrier:
            return
        cls.curr_event = torch.cuda.Event(interprocess=True)
        cls.curr_event.record()
        cls.ipc_handle = cls.curr_event.ipc_handle()

    @classmethod
    def wait_peer(cls, peer: int = None):
        from megatron.training import get_args
        if not get_args().synchronized_barrier:
            return
        if peer is None:
            peer = torch.distributed.get_rank() ^ 1
            if peer >= torch.distributed.get_world_size():
                return
        if cls.curr_event is None:
            cls.record()
        peer_handle = bytearray(len(cls.ipc_handle))
        s = torch.distributed.isend(
            tensor=torch.frombuffer(bytearray(cls.ipc_handle), dtype=torch.uint8), dst=peer
        )
        torch.distributed.recv(tensor=torch.frombuffer(peer_handle, dtype=torch.uint8), src=peer)
        s.wait()
        cls.prev_event = None
        peer_event = torch.cuda.Event.from_ipc_handle(torch.cuda.current_device(), bytes(peer_handle))
        peer_event.wait()

class DummyStorageManager:
    @classmethod
    def synchronize(cls):
        from megatron.training import get_args
        assert not get_args().offload_overlap_sr
        cls.unload()

    @classmethod
    def reload(cls):
        with torch.cuda.stream(get_transfer_h2d_stream()):
            SynchronizedBarrier.wait_peer()
        return

    @classmethod
    def unload(cls):
        with torch.cuda.stream(get_transfer_d2h_stream()):
            SynchronizedBarrier.wait_peer()
        return

class StorageManager(saved_tensors_hooks):
    @classmethod
    def trigger_recompute(cls, tensor, parents, function, rng_states=None):
        return partial_recompute.trigger_recompute(tensor, parents, function, rng_states)

    def __enter__(self):
        assert (
            not hasattr(StorageManager, "_active_storage_manager")
            or StorageManager._active_storage_manager is None
        ), "Nested offload not supported"
        StorageManager._active_storage_manager = self
        return super().__enter__()

    def __exit__(self, *args):
        super().__exit__(*args)
        StorageManager._active_storage_manager = None

    class Status(Enum):
        INITIAL = 0
        STORING = 1
        OFFLOADED = 2
        OFFLOAD_FREED = 3
        RESUME_PREPARED = 4
        RESUMED = 5
        RESUME_ACTIVE = 6
        RESUME_FREED = 7

    def _transition_state(self, from_status, to_status):
        if isinstance(from_status, set):
            assert self._current_status in from_status
        else:
            assert self._current_status == from_status
        self._current_status = to_status

    class TransferType(Enum):
        OFFLOAD = 1
        PASS_THROUGH = 2
        RECOMPUTE = 3
        ALIAS = 4

    def _handle_save(self, tensor):
        assert not self._is_offloaded
        self._transition_state(
            {StorageManager.Status.INITIAL, StorageManager.Status.STORING}, StorageManager.Status.STORING
        )
        if isinstance(tensor, torch.nn.parameter.Parameter):
            return StorageManager.TransferType.PASS_THROUGH, tensor
        if tensor.numel() <= 1024:
            return StorageManager.TransferType.PASS_THROUGH, tensor
        recompute_result = partial_recompute._handle_save(tensor)
        if recompute_result[0] == PartialRecompute.SaveMode.RECOMPUTE:
            (parents, function, rng_states) = recompute_result[1]
            parent_handles = [self._handle_save(x) for x in parents]
            return StorageManager.TransferType.RECOMPUTE, (parent_handles, function, rng_states)
        for index, stored_tensor in enumerate(self._gpu_cache):
            if is_same_storage(tensor, stored_tensor):
                offset = tensor.storage_offset() - stored_tensor.storage_offset()
                stride = tensor.stride()
                shape = tensor.shape
                return StorageManager.TransferType.ALIAS, (tensor.dtype, index, shape, stride, offset)
        self._gpu_cache.append(tensor.data)
        if len(self._offload_info) < len(self._gpu_cache):
            self._offload_info.append(get_tensor_metadata(tensor))
        else:
            assert self._offload_info[len(self._gpu_cache) - 1] == get_tensor_metadata(tensor)
        self._save_event.record()
        return (StorageManager.TransferType.OFFLOAD, len(self._gpu_cache) - 1)

    def _handle_load(self, packed, remove_used=True):
        assert not self._is_offloaded
        type, info = packed
        self._transition_state(
            {StorageManager.Status.RESUMED, StorageManager.Status.RESUME_ACTIVE},
            StorageManager.Status.RESUME_ACTIVE,
        )
        if type == StorageManager.TransferType.PASS_THROUGH:
            return info
        if type == StorageManager.TransferType.RECOMPUTE:
            p_infos, function, rng_states = info
            parents = [self._handle_load(x, remove_used=False) for x in p_infos]
            return partial_recompute._handle_load(
                (PartialRecompute.SaveMode.RECOMPUTE, (parents, function, rng_states))
            )
        if packed[0] == StorageManager.TransferType.ALIAS:
            dtype, index, shape, stride, offset = packed[1]
            self._resume_event.wait()
            bin, o = self.index_mapping[index]
            return torch.as_strided(self._continuous_gpu_buffer[dtype][bin], shape, stride, o + offset)
        assert type == StorageManager.TransferType.OFFLOAD
        self._resume_event.wait()
        index = info
        ret = self._gpu_cache[index]
        self._gpu_cache[index] = None
        if remove_used:
            shape, layout, dtype, stride = self._offload_info[index]
            bin, offset = self.index_mapping[index]
            all_freed = True
            for i, (b, o) in enumerate(self.index_mapping):
                if self._gpu_cache[i] is not None and b == bin and self._offload_info[i][2] == dtype:
                    all_freed = False
                    break
            if all_freed:
                self._continuous_gpu_buffer[dtype][bin] = None
        return ret

    def __init__(self, h2d_stream=None, d2h_stream=None):
        self._gpu_cache = []
        self._is_offloaded = False
        self._save_event = torch.cuda.Event()
        self._prepare_resume_event = torch.cuda.Event()
        self._resume_event = torch.cuda.Event()
        self._offload_complete_event = torch.cuda.Event()
        self._h2d_stream = h2d_stream
        self._d2h_stream = d2h_stream
        self._continuous_cpu_buffer = None
        self._continuous_gpu_buffer = None
        self._offload_info = []
        self._index_mapping = []
        self._index_cpu_buffer = []
        self._current_status = StorageManager.Status.INITIAL
        super().__init__(self._handle_save, self._handle_load)

    def _allocate_cpu_buffers(self):
        if self._continuous_cpu_buffer is not None:
            return
        alignment = 64
        def calculate_size(shape, stride):
            id_stride = list(
                sorted([(i, s) for i, s in enumerate(stride) if shape[i] != 1], key=lambda x: x[1])
            )
            size = 1
            for i, st in id_stride:
                assert size == st, f"stride {stride} size {shape} not continuous"
                size *= shape[i]
            return (size + (alignment - 1)) // alignment * alignment
        self.index_mapping = []
        type_tensors = defaultdict(list)
        for id, (shape, layout, dtype, stride) in enumerate(self._offload_info):
            assert layout == torch.strided
            mysize = calculate_size(shape, stride)
            type_tensors[dtype].append((mysize, id))

        def nearest_power_of_2(x):
            return 2 ** (x - 1).bit_length()

        def allocate_offsets(tensors, max_split=4):
            total_size = sum([x[0] for x in tensors])
            aligned_size = nearest_power_of_2(total_size)
            bin_size = [aligned_size // 2**i for i in range(max_split)]
            bins = [0] * max_split
            tensors = sorted(tensors, key=lambda x: x[0], reverse=True)
            while True:
                bins[-1] += bin_size[-1]
                for i in range(max_split - 1, 0, -1):
                    if bins[i] > bin_size[i]:
                        bins[i] = 0
                        bins[i - 1] += bin_size[i - 1]
                solution_bins = [x for x in bins if x > 0]
                if sum(solution_bins) < total_size:
                    continue
                current_bin = [0] * len(solution_bins)
                solution = {}
                fit = True
                for size, id in tensors:
                    ok = False
                    for i in range(len(solution_bins)):
                        if current_bin[i] + size <= solution_bins[i]:
                            current_bin[i] += size
                            solution[id] = (i, current_bin[i] - size)
                            ok = True
                            break
                    if not ok:
                        fit = False
                        break
                if fit:
                    assert len(solution) == len(tensors)
                    assert all([x > 0 for x in current_bin])
                    return current_bin, solution

        import psutil
        log_rank_all(
            f"rank {torch.distributed.get_rank()} before allocation rss {psutil.Process(os.getpid()).memory_info().rss / 1000000} MB"
        )
        self._continuous_cpu_buffer = {}
        self.index_mapping = [None] * len(self._offload_info)
        for dtype, tensors in type_tensors.items():
            from megatron.training import get_args
            if get_args().offload_continuous_buffers:
                bins, solution = allocate_offsets(tensors, max_split=8)
            else:
                bins = [t[0] for t in tensors]
                solution = {tensors[i][1]: (i, 0) for i in range(len(tensors))}
            self._continuous_cpu_buffer[dtype] = [
                torch.empty([size], dtype=dtype, pin_memory=True, device="cpu") for size in bins
            ]
            for id, (bin, offset) in solution.items():
                self.index_mapping[id] = (bin, offset)
            log_rank_all(
                f"rank {torch.distributed.get_rank()} after allocation {dtype} {bins} elements rss {psutil.Process(os.getpid()).memory_info().rss / 1000000} MB"
            )
        for dtype, tensors in type_tensors.items():
            total_size = sum([x[0] for x in tensors])
            allocated_size = sum([x.numel() for x in self._continuous_cpu_buffer[dtype]])
            aligned_size = sum([nearest_power_of_2(x.numel()) for x in self._continuous_cpu_buffer[dtype]])
            log_rank_all(
                f"rank {torch.distributed.get_rank()} Allocated {allocated_size / 1000000} M elements for {len(tensors)} tensors of type {dtype} total length {total_size} aligned size {aligned_size}"
            )
        for index, (shape, layout, dtype, stride) in enumerate(self._offload_info):
            bin, offset = self.index_mapping[index]
            ctensor = torch.as_strided(self._continuous_cpu_buffer[dtype][bin], shape, stride, offset)
            self._index_cpu_buffer.append(ctensor)

    @torch.no_grad()
    @torch.cuda.nvtx.range("Offload")
    def offload(self):
        self._transition_state(StorageManager.Status.STORING, StorageManager.Status.OFFLOADED)
        assert not self._is_offloaded
        size = 0
        storage_size = 0
        storages = set()
        with torch.cuda.stream(self._d2h_stream) if self._d2h_stream else contextlib.nullcontext():
            self._save_event.wait()
            self._allocate_cpu_buffers()
            SynchronizedBarrier.wait_peer()
            for index, tensor in enumerate(self._gpu_cache):
                buffer = self._index_cpu_buffer[index]
                assert buffer.shape == tensor.shape
                buffer.copy_(tensor, non_blocking=True)
                size += tensor.numel()
                if tensor.storage().data_ptr() not in storages:
                    storages.add(tensor.storage().data_ptr())
                    storage_size += tensor.storage().nbytes()
                else:
                    pass
            SynchronizedBarrier.record()
            self._offload_complete_event.record()
        self._is_offloaded = True

    @torch.no_grad()
    @torch.cuda.nvtx.range("OffloadRelease")
    def offload_release(self):
        self._transition_state(StorageManager.Status.OFFLOADED, StorageManager.Status.OFFLOAD_FREED)
        assert self._is_offloaded
        if self._d2h_stream is not None:
            self._offload_complete_event.wait()
        self._gpu_cache.clear()

    @torch.no_grad()
    @torch.cuda.nvtx.range("PrepareResume")
    def prepare_resume(self):
        self._transition_state(StorageManager.Status.OFFLOAD_FREED, StorageManager.Status.RESUME_PREPARED)
        assert self._is_offloaded
        self._continuous_gpu_buffer = {
            dtype: [torch.empty_like(x, device="cuda") for x in bins]
            for dtype, bins in self._continuous_cpu_buffer.items()
        }
        for index, (shape, layout, dtype, stride) in enumerate(self._offload_info):
            bin, offset = self.index_mapping[index]
            gtensor = torch.as_strided(self._continuous_gpu_buffer[dtype][bin], shape, stride, offset)
            self._gpu_cache.append(gtensor)
        self._prepare_resume_event.record()

    @torch.no_grad()
    @torch.cuda.nvtx.range("Resume")
    def resume(self):
        self._transition_state(StorageManager.Status.RESUME_PREPARED, StorageManager.Status.RESUMED)
        assert self._is_offloaded
        torch.cuda.current_stream()
        with torch.cuda.stream(self._h2d_stream) if self._h2d_stream else contextlib.nullcontext():
            self._prepare_resume_event.wait()
            self._offload_complete_event.wait()
            SynchronizedBarrier.wait_peer()
            for dtype, bins in self._continuous_cpu_buffer.items():
                for cpu, gpu in zip(bins, self._continuous_gpu_buffer[dtype]):
                    gpu.copy_(cpu, non_blocking=True)
            SynchronizedBarrier.record()
            self._resume_event.record()
        self._is_offloaded = False

    @torch.no_grad()
    @torch.cuda.nvtx.range("ResumeRelease")
    def resume_release(self):
        self._transition_state(StorageManager.Status.RESUME_ACTIVE, StorageManager.Status.RESUME_FREED)
        assert all([x is None for x in self._gpu_cache])
        assert all([all([x is None for x in y]) for y in self._continuous_gpu_buffer.values()])
        self._resume_event.wait()
        self._gpu_cache.clear()
        self._continuous_gpu_buffer.clear()

    def reset_state(self):
        self._transition_state(StorageManager.Status.RESUME_FREED, StorageManager.Status.INITIAL)

transfer_h2d_stream = None
transfer_d2h_stream = None

def get_transfer_h2d_stream():
    global transfer_h2d_stream
    if transfer_h2d_stream is None:
        transfer_h2d_stream = torch.cuda.Stream()
    return transfer_h2d_stream

def get_transfer_d2h_stream():
    from megatron.training import get_args
    if not get_args().offload_overlap_sr:
        return get_transfer_h2d_stream()
    global transfer_d2h_stream
    if transfer_d2h_stream is None:
        transfer_d2h_stream = torch.cuda.Stream()
    return transfer_d2h_stream

class StorageManagerPool:
    def __init__(self) -> None:
        self._pool = []
        self._stage_queues = [[] for x in range(6)]

    def get_for_offload(self) -> StorageManager:
        if self._pool:
            ret = self._pool.pop(-1)
            ret.reset_state()
        else:
            ret = StorageManager(get_transfer_h2d_stream(), get_transfer_d2h_stream())
        self._stage_queues[0].append(ret)
        return ret

    def pop_call_push(self, stage_idx, func):
        assert self._stage_queues[stage_idx]
        store = self._stage_queues[stage_idx].pop(0)
        ret = func(store)
        self._stage_queues[stage_idx + 1].append(store)
        return ret

    def offload(self):
        return self.pop_call_push(0, lambda x: x.offload())

    def offload_release(self):
        return self.pop_call_push(1, lambda x: x.offload_release())

    def prepare_resume(self):
        return self.pop_call_push(2, lambda x: x.prepare_resume())

    def resume(self):
        return self.pop_call_push(3, lambda x: x.resume())

    def resume_release(self, store_deprecated=None):
        self.pop_call_push(4, lambda x: x.resume_release())
        self._pool.append(self._stage_queues[5].pop(0))

    def is_empty(self):
        return sum([len(x) for x in self._stage_queues]) == 0

# Determine if debug flags are enabled based on environment variables
def _is_debug_flag_active(flag_name: str, fallback: bool = False) -> bool:
    env_value = os.getenv(flag_name)
    if env_value is None:
        return fallback
    else:
        return env_value == "1" or env_value.lower() == "true"

