def timed_generation(model_instance: VLLM,
                     input_prompts: Optional[list[str]],
                     sampling_config: SamplingParams,
                     num_draft_tokens=5,
                     warmup_iterations=1,
                     enable_profiling=False,
                     accuracy_threshold=None,
                     sample_limit=None) -> dict:
    # Generate texts from the prompts. The output is a list of RequestOutput
    # objects that contain the prompt, generated text, and other information.
    # Warmup first
    need_accuracy_check = input_prompts is None
    output_results = [""]

    if need_accuracy_check:
        benchmark_task = "gsm8k"
        TOLERANCE = 0.03
        EVALUATION_METRIC = "exact_match,strict-match"
        accuracy_threshold = accuracy_threshold or 0.3

        start_time = time.time()
        evaluation_results = lm_eval.simple_evaluate(model=model_instance, tasks=[benchmark_task], limit=sample_limit)
        end_time = time.time()

        elapsed_time = end_time - start_time

        try:
            actual_score = evaluation_results["results"][benchmark_task][EVALUATION_METRIC]
        except KeyError as e:
            raise KeyError(f"Available metrics: {evaluation_results['results']}") from e

        output_results = [f"Task: {benchmark_task} | Metric: {EVALUATION_METRIC} | Expected: {accuracy_threshold} | Measured: {actual_score}"]

        performance_metrics = model_instance.model.llm_engine.get_metrics()

        if accuracy_threshold > (actual_score + TOLERANCE):
            raise AssertionError(f"Expected: {accuracy_threshold} |  Measured: {actual_score}")
    else:
        logging.info("Warming up the model...")
        for _ in range(warmup_iterations):
            model_instance.generate(input_prompts, sampling_config)

        logging.info("Starting generation...")
        output_results = []

        if enable_profiling:
            model_instance.start_profile()

        start_time = time.time()
        generated_outputs = model_instance.generate(input_prompts, sampling_config)
        end_time = time.time()

        elapsed_time = end_time - start_time

        if enable_profiling:
            model_instance.stop_profile()

        # Print the outputs.
        for gen_output in generated_outputs:
            generated_text = gen_output.outputs[0].text
            output_results.append(generated_text[:200])

        performance_metrics = model_instance.llm_engine.get_metrics()

    logging.info("Generation completed in %.2f seconds.", elapsed_time)

    total_drafts = 0
    total_draft_tokens = 0
    total_accepted_tokens = 0
    token_acceptance_counts = [0] * (num_draft_tokens + 1)

    for metric in performance_metrics:
        if metric.name == "vllm:spec_decode_num_drafts":
            assert isinstance(metric, Counter)
            total_drafts += metric.value
        elif metric.name == "vllm:spec_decode_num_draft_tokens":
            assert isinstance(metric, Counter)
            total_draft_tokens += metric.value
        elif metric.name == "vllm:spec_decode_num_accepted_tokens":
            assert isinstance(metric, Counter)
            total_accepted_tokens += metric.value
        elif metric.name == "vllm:spec_decode_num_accepted_tokens_per_pos":
            assert isinstance(metric, Vector)
            for pos in range(len(metric.values)):
                token_acceptance_counts[pos] += metric.values[pos]

    acceptance_ratio = total_accepted_tokens / total_draft_tokens \
        if total_draft_tokens > 0 else 0.0

    result_dictionary = {
        'output_spec': output_results,
        'elapsed_time': elapsed_time,
        'acceptance_counts': token_acceptance_counts,
        'acceptance_ratio': acceptance_ratio,
        'total_draft_tokens': total_draft_tokens,
        'total_drafts': total_drafts,
    }
    return result_dictionary

def create_error_response(exception: Exception) -> dict:
    """Helper function to create a standardized error response dictionary."""
    return {
        'output_spec': [],
        'elapsed_time': 0,
        'acceptance_counts': [],
        'acceptance_ratio': 0,
        'total_draft_tokens': 0,
        'total_drafts': 0,
        'error': str(exception)
    }

def run_ngram_test(is_active, config, input_prompts, sampling_config, task_label, output_queue):
    MODEL_CLASS = LLM if input_prompts is not None else VLLM
    kwargs = {"model":"Qwen/Qwen3-4B",} if input_prompts is not None \
        else {"pretrained":"Qwen/Qwen3-4B","batch_size":"16"}
    try:
        if not is_active:
            model = MODEL_CLASS(
                **kwargs,
                disable_log_stats=False,
            )
        else:
            model = MODEL_CLASS(
                **kwargs,
                speculative_config={
                    "method": "ngram",
                    "prompt_lookup_max": 3,
                    "num_speculative_tokens": config.num_spec_tokens,
                },
                disable_log_stats=False,
            )
        result_dict = timed_generation(model,
                                      input_prompts,
                                      sampling_config,
                                      config.num_spec_tokens,
                                      config.num_warmups,
                                      config.do_profile,
                                      accuracy=config.accuracy_rate,
                                      limit=config.limit)
    except Exception as e:
        logging.exception("Task %s failed: %s", task_label, e)
        result_dict = create_error_response(e)
    output_queue.put((task_label, result_dict))

