                                    args=(True, args, prompts, sampling_params, 'spec_medusa', result_queue))
        }
    else:
        raise ValueError(f"Unknown task: {selected_task}")

    try:
        for key, task in task_list.items():
            logging.info("=============== Starting task: %s ====================", key)
            task['proc'].start()
            task['proc'].join()
            logging.info("=============== Task %s completed. ====================", key)

        for _ in range(len(task_list)):
            key, result_data = result_queue.get()
            task_list[key]['result'] = result_data
    except KeyboardInterrupt:
        logging.info("Interrupted by user, terminating processes...")
    finally:
        for key, proc in task_list.items():
            print(f"================= {key} =================")
            print(f"elapsed_time: {proc['result']['elapsed_time']}")
            print(f"acceptance_counts: {proc['result']['acceptance_counts']}")
            print(f"acceptance_ratio: {proc['result']['acceptance_ratio']}")
            print(f"total_draft_tokens: {proc['result']['total_draft_tokens']}")
            print(f"total_drafts: {proc['result']['total_drafts']}")

            if prompts:
                for prompt, text in zip(prompts, proc['result']['output_spec']):
                    print("---")
                    print(f"Prompt: {prompt}")
                    print(f"Generated text: {text}'...'")
            else:
                print(f"accuracy check: {proc['result']['output_spec'][0]}")

            print("=========================================")

            if proc['proc'].is_alive():
                proc['proc'].terminate()
                proc['proc'].join(timeout=2)

            if args.assert_accept_rate > 0 and 'spec' in key:
                assert proc['result']['acceptance_ratio'] >= args.assert_accept_rate, \
                    f"Acceptance ratio {proc['result']['acceptance_ratio']} is lower" \
                    f"than the threshold {args.assert_accept_rate}"

        logging.info("Benchmark finished.")

import logging
from .base import Collector, CollectorResult
from ..speedtest import SpeedtestClient
logger = logging.getLogger("docsis.collector.speedtest")

class SpeedtestDataCollector(Collector):
    """Retrieves speed test data from Speedtest Tracker and stores it locally."""
    name = "speedtest"

    def __init__(self, config_handler, data_store, web_interface, check_interval=300):
        super().__init__(check_interval)
        self._config_handler = config_handler
        self._data_store = data_store
        self._web_interface = web_interface
        self._client_instance = None
        self._previous_url = None

    def is_active(self) -> bool:
        return self._config_handler.is_speedtest_enabled()

    def _initialize_client(self):
        """Recreate client if the configured URL has changed."""
        url = self._config_handler.get("speedtest_tracker_url")
        if url != self._previous_url:
            api_token = self._config_handler.get("speedtest_tracker_token")
            self._client_instance = SpeedtestClient(url, api_token)
            self._previous_url = url
            logger.info("Speedtest Tracker endpoint: %s", url)

    def gather(self) -> CollectorResult:
        self._initialize_client()

        # Get most recent result for dashboard display
        latest_data = self._client_instance.get_latest(1)
        if latest_data:
            self._web_interface.update_state(speedtest_latest=latest_data[0])

        # Update local cache (isolated operation: errors shouldn't affect overall collection)
        try:
            last_record_id = self._data_store.get_latest_speedtest_id()
            current_cache_size = self._data_store.get_speedtest_count()

            if current_cache_size < 50:
                batch_results = self._client_instance.get_results(per_page=2000)
            else:
                batch_results = self._client_instance.get_newer_than(last_record_id)

            if batch_results:
                self._data_store.save_speedtest_results(batch_results)
                logger.info(
                    "Stored %d new speedtest records (cumulative: %d)",
                    len(batch_results),
                    current_cache_size + len(batch_results),
                )
        except Exception as error:
            logger.warning("Speedtest cache update failed: %s", error)

        return CollectorResult(source=self.name)

