class RequestHandler(BaseHTTPRequestHandler):
    """Custom HTTP request handler for mock authentication endpoints."""

    def do_GET(self) -> None:
        """Process incoming GET requests."""
        if self.path == "/.well-known/jwks.json":
            self._send_json_response(JWKS_DATA)
        elif self.path == "/tokens":
            self._send_json_response(TOKENS_DB)
        elif self.path == "/health":
            self._send_json_response({"status": "healthy"})
        else:
            self.send_error(404)

    def _send_json_response(self, payload: dict) -> None:
        """Helper method to send JSON responses."""
        response_body = json.dumps(payload).encode('utf-8')
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(response_body)))
        self.end_headers()
        self.wfile.write(response_body)

    def log_message(self, format: str, *args: Any) -> None:
        """Override to suppress default logging."""
        pass

