# BQM Collector module for fetching daily quality graphs
import logging
import time
from datetime import date, timedelta
from .base import Collector, CollectorResult
from .. import thinkbroadband

log = logging.getLogger("docsis.collector.bqm")

class BQMCollector(Collector):
    """Collects BQM quality graph PNG images once daily.
    Schedules collection based on specific time-of-day rather than fixed intervals.
    When configured time is before noon, the image is associated with the previous day's date,
    as the 24-hour graph reflects data from the prior day.
    """
    name = "bqm"

    def __init__(self, config_manager, storage_backend, poll_interval=86400):
        super().__init__(poll_interval)
        self._config_manager = config_manager
        self._storage_backend = storage_backend
        self._collected_date = None

    def is_enabled(self) -> bool:
        return self._config_manager.is_bqm_configured()

    def should_poll(self) -> bool:
        """Returns True if scheduled collection time has arrived today and not yet processed."""
        current_date = time.strftime("%Y-%m-%d")
        if current_date == self._collected_date:
            return False
        target_time = self._config_manager.get("bqm_collect_time") or "02:00"
        current_time = time.strftime("%H:%M")
        return current_time >= target_time

    def collect(self) -> CollectorResult:
        current_date = time.strftime("%Y-%m-%d")
        if current_date == self._collected_date:
            return CollectorResult(source=self.name, data={"skipped": True})

        graph_url = self._config_manager.get("bqm_url")
        raw_image = thinkbroadband.fetch_graph(graph_url)

        if raw_image:
            collection_time = self._config_manager.get("bqm_collect_time") or "02:00"
            if collection_time < "12:00":
                image_date = (date.today() - timedelta(days=1)).isoformat()
            else:
                image_date = date.today().isoformat()

            self._storage_backend.save_bqm_graph(raw_image, graph_date=image_date)
            self._collected_date = current_date
            return CollectorResult(source=self.name)

        return CollectorResult(
            source=self.name, success=False, error="Unable to retrieve BQM graph"
        )

