# Analyze JSON data structure and key statistics
import re
from collections import defaultdict
from rich.text import Text
from scripts.use_pickled import console, epstein_files
from epstein_files.output.rich import highlighter, print_subtitle_panel
from epstein_files.util.helpers.data_helpers import sort_dict

INDENT_SPACES = '    '
GUID_PATTERN = re.compile(r'[a-f0-9\-]{36}')

class JsonAnalyzer:
    unique_key_frequency = defaultdict(int)
    total_lists_found = 0

    def analyze_structure(self, data, depth: int = 0):
        if isinstance(data, dict):
            for key, value in data.items():
                # Skip specific bannerType entries
                if key == 'bannerType' and value == 'any':
                    continue

                self.analyze_structure(value, depth + 1)

                # Count non-GUID keys
                if not GUID_PATTERN.match(key):
                    self.unique_key_frequency[key] += 1

                # Print interesting key-value pairs with formatting
                if isinstance(value, str) and self.is_significant_key(key):
                    if key != 'URL' or not value.startswith('asset:'):
                        formatted_line = Text(INDENT_SPACES * depth).append(key, style='magenta').append(': ').append(f'"{value}"')
                        console.print(highlighter(formatted_line))

        elif isinstance(data, list):
            self.total_lists_found += 1
            for element in data:
                self.analyze_structure(element, depth + 1)

    def is_significant_key(self, field_name: str) -> bool:
        # Exclude styling-related keys
        if 'Color' in field_name or 'Alignment' in field_name:
            return False
        # Exclude text variants (but keep 'text' itself)
        elif field_name.startswith("text") and field_name != 'text':
            return False
        # Exclude font, ignore, color-related, thumbnail keys
        elif field_name.startswith('font') or field_name.startswith('ignore') or 'color' in field_name.lower() or field_name.startswith('thumbnail'):
            return False
        # Exclude specific common fields
        elif field_name in ['bottom', 'classification', 'fillMode', 'identifier', 'layout', 'role', 'style', 'top', 'type', 'weightLabel', 'width']:
            return False
        # Exclude height/Identifier suffixes
        elif field_name.lower().endswith('height') or field_name.endswith('Identifier'):
            return False
        # Apply additional filtering rules
        elif not self.meets_inclusion_criteria(field_name):
            return False
        return True

    def meets_inclusion_criteria(self, field_name: str) -> bool:
        # Exclude GUID-like keys
        if GUID_PATTERN.match(field_name):
            return False
        # Exclude call-to-action and icon prefixes
        elif field_name.startswith('call-to-action') or field_name.startswith('icon'):
            return False
        # Exclude specific field names
        elif field_name in ['familyName']:
            return False
        return True

# Process all JSON files
analyzer = JsonAnalyzer()
for json_document in epstein_files.json_files:
    analyzer.analyze_structure(json_document.json_data())

console.line(4)
print_subtitle_panel("Key Frequency Statistics from JSON Data")
for (field_name, occurrence_count) in sort_dict(analyzer.unique_key_frequency):
    console.print(f"{field_name}: {occurrence_count}")

console.print(f"\n\nDetected {analyzer.total_lists_found} lists in total.\n")

# Catch up on unsynced session context for planning files
import json
import sys
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from datetime import datetime

PLANNING_FILE_LIST = ['task_plan.md', 'progress.md', 'findings.md']

def get_project_directory(project_path: str) -> Path:
    """Transform project path into Claude's internal storage format."""
    cleaned = project_path.replace('/', '-')
    if not cleaned.startswith('-'):
        cleaned = '-' + cleaned
    cleaned = cleaned.replace('_', '-')
    return Path.home() / '.claude' / 'projects' / cleaned

def retrieve_sessions_in_order(project_dir: Path) -> List[Path]:
    """Fetch all session files ordered by modification time (most recent first)."""
    session_files = list(project_dir.glob('*.jsonl'))
    primary_sessions = [s for s in session_files if not s.name.startswith('agent-')]
    return sorted(primary_sessions, key=lambda p: p.stat().st_mtime, reverse=True)

def extract_session_entries(session_file: Path) -> List[Dict]:
    """Load and parse all JSON entries from a session file sequentially."""
    entries = []
    with open(session_file, 'r') as file:
        for idx, line in enumerate(file):
            try:
                record = json.loads(line)
                record['_line_index'] = idx
                entries.append(record)
            except json.JSONDecodeError:
                continue
    return entries

def locate_latest_planning_change(entries: List[Dict]) -> Tuple[int, Optional[str]]:
    """
    Identify the most recent instance where a planning file was modified.
    Returns (line_index, filename) or (-1, None) if no such entry exists.
    """
    latest_change_index = -1
    latest_change_name = None
    for entry in entries:
        entry_kind = entry.get('type')
        if entry_kind == 'assistant':
            payload = entry.get('message', {}).get('content', [])
            if isinstance(payload, list):
                for segment in payload:
                    if segment.get('type') == 'tool_use':
                        tool_id = segment.get('name', '')
                        tool_params = segment.get('input', {})
                        if tool_id in ('Write', 'Edit'):
                            target_path = tool_params.get('file_path', '')
                            for plan_file in PLANNING_FILE_LIST:
                                if target_path.endswith(plan_file):
                                    latest_change_index = entry['_line_index']
                                    latest_change_name = plan_file
    return latest_change_index, latest_change_name

def collect_messages_subsequent_to(entries: List[Dict], after_index: int) -> List[Dict]:
    """Gather conversation entries that occurred after a specific line index."""
    output = []
    for entry in entries:
        if entry['_line_index'] <= after_index:
            continue
        entry_kind = entry.get('type')
        is_system = entry.get('isMeta', False)
        if entry_kind == 'user' and not is_system:
            body = entry.get('message', {}).get('content', '')
            if isinstance(body, list):
                for part in body:
                    if isinstance(part, dict) and part.get('type') == 'text':
                        body = part.get('text', '')
                        break
                else:
                    body = ''
            if isinstance(body, str) and body:
                if body.startswith(('<local-command', '<command-', '<task-notification')):
                    continue
                if len(body) > 20:
                    output.append({'role': 'user', 'content': body, 'index': entry['_line_index']})
        elif entry_kind == 'assistant':
            msg_body = entry.get('message', {}).get('content', '')
            text_snippet = ''
            tool_actions = []
            if isinstance(msg_body, str):
                text_snippet = msg_body
            elif isinstance(msg_body, list):
                for part in msg_body:
                    if part.get('type') == 'text':
                        text_snippet = part.get('text', '')
                    elif part.get('type') == 'tool_use':
                        tool_label = part.get('name', '')
                        tool_data = part.get('input', {})
                        if tool_label == 'Edit':
                            tool_actions.append(f"Edit: {tool_data.get('file_path', 'unknown')}")
                        elif tool_label == 'Write':
                            tool_actions.append(f"Write: {tool_data.get('file_path', 'unknown')}")
                        elif tool_label == 'Bash':
                            cmd_text = tool_data.get('command', '')[:80]
                            tool_actions.append(f"Bash: {cmd_text}")
                        else:
                            tool_actions.append(f"{tool_label}")
            if text_snippet or tool_actions:
                output.append({
                    'role': 'assistant',
                    'content': text_snippet[:600] if text_snippet else '',
                    'tools': tool_actions,
                    'index': entry['_line_index']
                })
    return output

def main():
    project_location = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    project_root = get_project_directory(project_location)

    # Verify presence of planning files (indicates active task)
    planning_present = any(
        Path(project_location, f).exists() for f in PLANNING_FILE_LIST
    )

    if not project_root.exists():
        # No prior sessions exist, nothing to recover
        return

    session_list = retrieve_sessions_in_order(project_root)
    if len(session_list) < 1:
        return

    # Locate a meaningful previous session
    selected_session = None
    for session in session_list:
        if session.stat().st_size > 5000:
            selected_session = session
            break
    if not selected_session:
        return

    entry_list = extract_session_entries(selected_session)
    change_index, change_file = locate_latest_planning_change(entry_list)

    # Only report if there is new content
    if change_index < 0:
        subsequent_entries = collect_messages_subsequent_to(entry_list, len(entry_list) - 30)
    else:
        subsequent_entries = collect_messages_subsequent_to(entry_list, change_index)

    if not subsequent_entries:
        return

    # Generate catch-up summary
    print("\n[planning-with-files] SESSION RESUMPTION DETECTED")
    print(f"Previous session: {selected_session.stem}")
    if change_index >= 0:
        print(f"Last planning update: {change_file} at message #{change_index}")
        print(f"Unsynced messages: {len(subsequent_entries)}")
    else:
        print("No planning file updates found in previous session")

    print("\n--- UNSYNCED CONTEXT ---")
    for entry in subsequent_entries[-15:]:  # Last 15 entries
        if entry['role'] == 'user':
            print(f"USER: {entry['content'][:300]}")
        else:
            if entry.get('content'):
                print(f"CLAUDE: {entry['content'][:300]}")
            if entry.get('tools'):
                print(f"  Tools: {', '.join(entry['tools'][:4])}")

    print("\n--- RECOMMENDED ---")
    print("1. Run: git diff --stat")
    print("2. Read: task_plan.md, progress.md, findings.md")
    print("3. Update planning files based on above context")
    print("4. Continue with task")

if __name__ == '__main__':
    main()

# Modified version with Type I clone transformations (variable renaming, literal changes, statement reordering)
import os
import torch
import torch.distributed as dist

# Logger setup
logger = logging.getLogger(__name__)

def _get_rank():
    # Return current process rank or 0 if not initialized
    return dist.get_rank() if dist.is_initialized() else 0

class ReplayBuffer:
    def __init__(self):
        self.read_ptr = 0
        self.write_ptr = 0
        self.buffer_list: list[torch.Tensor] = []

    def store(self, indices: torch.Tensor):
        # Create pinned CPU buffer and copy data
        temp_buffer = torch.empty_like(indices, device="cpu", pin_memory=True)
        temp_buffer.copy_(indices)
        self.buffer_list.append(temp_buffer)

    def read_next(self) -> torch.Tensor:
        if self.read_ptr >= len(self.buffer_list):
            shapes_info = [
                t.shape if isinstance(t, torch.Tensor) else f"non-tensor({type(t)})" 
                for t in self.buffer_list
            ]
            raise IndexError(
                f"read_next out of bounds: read_ptr={self.read_ptr}, "
                f"buffer_size={len(self.buffer_list)}, shapes={shapes_info}"
            )
        selected_indices = self.buffer_list[self.read_ptr]
        self.read_ptr += 1
        return selected_indices.to(torch.cuda.current_device())

    def read_backward(self) -> torch.Tensor:
        selected_indices = self.buffer_list[self.write_ptr]
        self.write_ptr += 1
        return selected_indices.to(torch.cuda.current_device())

    def reset_all(self):
        self.read_ptr = 0
        self.write_ptr = 0
        self.buffer_list = []

    def reset_read(self):
        self.read_ptr = 0

class BaseReplayController:
    identifier: str = ""
    storage_file: str = ""

    def __init__(self):
        self.buffers: list[ReplayBuffer] = []
        self.active_buffer: ReplayBuffer | None = None
        self.active = False
        self.phase = "default"

    def create_buffer(self) -> ReplayBuffer:
        new_buffer = ReplayBuffer()
        self.buffers.append(new_buffer)
        return new_buffer

    def set_active(self, buffer: ReplayBuffer):
        self.active_buffer = buffer

    def get_active(self) -> ReplayBuffer | None:
        return self.active_buffer

    def reset_all_buffers(self):
        for buf in self.buffers:
            buf.reset_all()

    def reset_read_pointers(self):
        for buf in self.buffers:
            buf.reset_read()

    def get_topk_wrapper(self, original_fn, include_probabilities):
        controller = self

        def _replay_handler(retrieved_indices, logits, k_value, *args, **kwargs):
            assert (
                retrieved_indices.shape[0] == logits.shape[0]
            ), f"rank {_get_rank()}: replay token count {retrieved_indices.shape[0]} != logits token count {logits.shape[0]}"
            assert (
                retrieved_indices.shape[1] == k_value
            ), f"replay top-k mismatch: replay has {retrieved_indices.shape[1]}, expected {k_value}"

            if controller.enable_validation:
                controller.validate_replay(original_fn, logits, k_value, retrieved_indices, *args, **kwargs)

            # Handle padding tokens
            pad_mask = retrieved_indices == -1
            if pad_mask.any():
                retrieved_indices[pad_mask] = (
                    torch.arange(pad_mask.sum(), device=retrieved_indices.device, dtype=retrieved_indices.dtype)
                    % logits.shape[1]
                )

            if include_probabilities:
                return logits.gather(1, retrieved_indices), retrieved_indices
            else:
                return retrieved_indices

        def modified_topk(logits, k_value, *args, **kwargs):
            if not controller.active:
                return original_fn(logits, k_value, *args, **kwargs)

            phase = controller.phase
            active_buf = controller.get_active()

            if phase == "default":
                return original_fn(logits, k_value, *args, **kwargs)
            elif phase == "capture":
                result = original_fn(logits, k_value, *args, **kwargs)
                if include_probabilities:
                    probs, indices = result
                else:
                    indices = result
                active_buf.store(indices)
                return result
            elif phase == "restore_forward":
                return _replay_handler(active_buf.read_next(), logits, k_value, *args, **kwargs)
            elif phase == "restore_backward":
                return _replay_handler(active_buf.read_backward(), logits, k_value, *args, **kwargs)
            else:
                return original_fn(logits, k_value, *args, **kwargs)

        return modified_topk

    def attach_to_module(self, module, attribute_name: str):
        if not self.active:
            return

        buffer = self.create_buffer()
        setattr(module, attribute_name, buffer)
        controller = self

        def pre_forward_hook(*args, **kwargs):
            controller.set_active(buffer)

        module.register_forward_pre_hook(pre_forward_hook)

    def validate_replay(self, original_fn, logits, k_value, retrieved_indices, *args, **kwargs):
        """
        Validation routine for R3. Only active when enable_validation=True.
        Measures overlap between original routing results and replayed results.
        Raises error if mismatch exceeds threshold.
        """
        orig_result = original_fn(logits, k_value, *args, **kwargs)
        if isinstance(orig_result, tuple):
            _, orig_result = orig_result

        orig_flat = orig_result.view(-1, orig_result.shape[-1])      # [n_tokens, topk]
        replay_flat = retrieved_indices.view(-1, retrieved_indices.shape[-1])

        # Compute element-wise matches
        matches = orig_flat.unsqueeze(2) == replay_flat.unsqueeze(1)
        # Exclude padding positions from matching
        valid_matches = matches & (orig_flat != -1).unsqueeze(2) & (replay_flat != -1).unsqueeze(1)
        has_overlap = valid_matches.any(dim=(1, 2))  # Per-token overlap check
        is_padding = (replay_flat == -1).all(dim=1)
        is_error = ~has_overlap & ~is_padding

        error_count = is_error.sum().item()
        if error_count == 0:
            return

        # Get threshold from environment or default
        threshold = float(os.environ.get("MILES_TEST_R3_THRESHOLD", self.validation_threshold))
        error_limit = threshold * orig_flat.shape[0]

        error_indices = is_error.nonzero(as_tuple=False).squeeze(1)
        for idx in error_indices:
            i = idx.item()
            context_lines = []
            start_idx = max(0, i - 3)
            end_idx = min(len(orig_flat), i + 4)

            for j in range(start_idx, end_idx):
                marker = " <<<" if j == i else ""
                context_lines.append(f"  token {j}: orig={orig_flat[j].tolist()}, replay={replay_flat[j].tolist()}{marker}")

            logger.warning(
                f"Validation (rank {_get_rank()}, phase {self.phase}): "
                f"token {i} has no overlap, topk={k_value}\n" + "\n".join(context_lines)
            )

        if error_count > error_limit:
            raise AssertionError(f"R3 validation failed: {error_count} mismatches exceed limit ({error_limit:.0f})")

