    @staticmethod
    def to_blankly_symbol(symbol: str):
        return symbol

    @staticmethod
    def to_exchange_symbol(symbol: str):
        return symbol

    def get_exchange_type(self) -> str:
        """Returns the exchange type (ex. 'binance', 'coinbase', 'alpaca')"""
        return self.exchange_name

    @abc.abstractmethod
    def init_exchange(self):
        """Initializes the exchange"""
        pass

    @abc.abstractmethod
    def get_products(self, symbol: str = None) -> dict:
        """Returns a list of all products traded on this exchange"""
        pass

    @abc.abstractmethod
    def get_account(self, symbol: str = None) -> dict:
        """Returns account information, or information for only one `symbol` if one is given."""
        pass

    # TODO this method name might need to change to get_position ?
    @abc.abstractmethod
    def get_position(self, symbol: str = None) -> Optional[dict]:
        """Returns position information, or information for only one `symbol` if one is given"""
        pass

    @abc.abstractmethod
    def market_order(self,
                     symbol: str,
                     side: Side,
                     size: float,
                     position: PositionMode = None,
                     reduce_only: bool = None) -> FuturesOrder:
        """Places a market order"""
        pass

    @abc.abstractmethod
    def limit_order(self,
                    symbol: str,
                    side: Side,
                    price: float,
                    size: float,
                    position: PositionMode = None,
                    reduce_only: bool = None,
                    time_in_force: TimeInForce = None) -> FuturesOrder:
        """Places a limit order"""
        pass

    @abc.abstractmethod
    def take_profit_order(self,
                          symbol: str,
                          side: Side,
                          price: float,
                          size: float,
                          position: PositionMode = None) -> FuturesOrder:
        """Place a take-profit order for a position"""
        pass

    @abc.abstractmethod
    def stop_loss_order(self,
                        symbol: str,
                        side: Side,
                        price: float,
                        size: float,
                        position: PositionMode = None) -> FuturesOrder:
        """Place a stop-loss order for a position"""
        pass

    @abc.abstractmethod
    def set_hedge_mode(self, hedge_mode: HedgeMode):
        pass

    @abc.abstractmethod
    def get_hedge_mode(self):
        pass

    @abc.abstractmethod
    def set_leverage(self, leverage: float, symbol: str = None):
        pass

    @abc.abstractmethod
    def get_leverage(self, symbol: str = None) -> float:
        pass

    @abc.abstractmethod
    def set_margin_type(self, symbol: str, margin_type: MarginType):
        pass

    @abc.abstractmethod
    def get_margin_type(self, symbol: str):
        pass

    @abc.abstractmethod
    def cancel_order(self, symbol: str, order_id: int) -> FuturesOrder:
        """Cancels an order"""
        pass

    @abc.abstractmethod
    def get_open_orders(self, symbol: str = None) -> List[FuturesOrder]:
        """Returns all currently open orders, filtered by `symbol` if one is provided."""
        pass

    @abc.abstractmethod
    def get_order(self, symbol: str, order_id: int) -> FuturesOrder:
        """Returns information for the order corresponding to `order_id`"""
        pass

    @abc.abstractmethod
    def get_price(self, symbol: str) -> float:
        """Returns the current price of an asset"""
        pass

    @property
    def account(self) -> dict:
        """Account information"""
        return self.get_account()

    @property
    def positions(self) -> dict:
        """Position information"""
        return self.get_position()

    @property
    def orders(self) -> list:
        """All currently open orders"""
        return self.get_open_orders()

    @property
    def cash(self) -> float:
        """The amount of cash in a portfolio. The currency for 'cash' is set in settings.json"""
        using_setting = self.user_preferences['settings'][
            self.exchange_name]['cash']
        return self.get_account(using_setting)['available']

    @abc.abstractmethod
    def get_funding_rate_history(self, symbol: str, epoch_start: int,
                                 epoch_stop: int) -> list:
        """
        Get the funding rate history between `epoch_start` and `epoch_end`.
        Returns a list of {'rate': int, 'time': int}
        """
        pass

    @abc.abstractmethod
    def get_funding_rate(self, symbol: str) -> float:
        pass

    @abc.abstractmethod
    def get_maker_fee(self) -> float:
        pass

    @abc.abstractmethod
    def get_taker_fee(self) -> float:
        pass

    @abc.abstractmethod
    def get_funding_rate_resolution(self) -> int:
        pass

    @property
    def should_auto_trunc(self):
        return self.user_preferences['settings'].get('auto_truncate', False)

# Modified version of OptimizerWrapper with Type I clone transformations
from __future__ import annotations
import logging
from collections.abc import Callable, Iterable
from typing import TYPE_CHECKING, Any
import torch
from torch.amp.grad_scaler import GradScaler
from noether.core.schemas.optimizers import OptimizerConfig
from noether.core.utils.bidict import Bidict
from noether.core.utils.logging import float_to_scientific_notation
from noether.core.utils.torch import NoopGradScaler

if TYPE_CHECKING:
    from noether.core.models import Model
    from noether.core.optimizer.param_group_modifiers import ParamGroupModifierBase
    from noether.core.utils.training.counter import UpdateCounter
    from noether.core.utils.training.schedule_wrapper import ScheduleWrapper


class OptimizerWrapper:
    """Wrapper around a `torch.optim.Optimizer` that enables:
        - exclusion of biases and normalization layer weights from weight decay
        - creation of parameter groups (e.g., for layerwise learning rate scaling)
        - learning rate scheduling
        - gradient clipping
        - weight decay scheduling

    See `noether.core.schemas.optimizers.OptimizerConfig` for available options.
    """
    lr_schedule: ScheduleWrapper | None = None
    weight_decay_schedule: ScheduleWrapper | None = None

    def __init__(
        self,
        network: Model,
        optim_constructor: Callable[[Iterable[dict[str, Any]]], torch.optim.Optimizer],
        config: OptimizerConfig,
        counter: UpdateCounter | None = None,
    ):
        """
        Args:
            network: Parameters of this model will be optimized.
            optim_constructor: The :class:`~torch.optim.Optimizer` constructor to wrap. Needs to be callable
                because it requires the parameters of the model for initialization.
            config: Configuration for the optimizer wrapper.
            counter: Object providing current training progress to enable scheduling of learning rate or weight decay.
        """
        # import here to avoid circular dependency
        from noether.core.factory import Factory, ScheduleFactory

        self.logger = logging.getLogger(self.__class__.__name__)
        self.network = network
        self.counter = counter
        self.config = config

        # Create param group modifiers
        param_modifiers = Factory().create_list(self.config.param_group_modifiers_config)
        self.logger.debug(
            f"exclude_bias_from_wd={self.config.exclude_bias_from_weight_decay} "
            f"exclude_norm_from_wd={self.config.exclude_normalization_params_from_weight_decay} "
            f"param_modifiers=[{' '.join(str(pgm) for pgm in param_modifiers)}]"
        )

        # Apply parameter modifiers to named parameters
        param_groups = self._apply_parameter_modifiers(network, param_modifiers)

        # Merge groups with same properties
        merged_groups, merged_param_names = self._merge_groups_with_the_same_parameters(param_groups)
        merged_groups = self._add_names_to_param_groups(merged_groups)
        self._log_param_groups(merged_groups, merged_param_names)

        # Store mapping from parameter index to name for state dict operations
        self.param_idx_to_name = Bidict[int, str]()
        idx = 0
        for group_paramnames in merged_param_names:
            for param_name in group_paramnames:
                self.param_idx_to_name.set(idx, param_name)
                idx += 1

        # Initialize torch optimizer
        self.torch_optim = optim_constructor(merged_groups)

        # Store all parameters if gradient clipping is enabled
        self.all_parameters = None
        if self.config.clip_grad_value is not None or self.config.clip_grad_norm is not None:
            self.all_parameters = list(network.parameters())

        # Apply learning rate scaling
        self._apply_learning_rate_scaling()

        # Create schedules
        if config.lr_schedule_config is not None:
            self.lr_schedule = ScheduleFactory().create(
                config.lr_schedule_config,
                update_counter=self.counter,
            )
        if config.weight_decay_schedule is not None:
            self.weight_decay_schedule = ScheduleFactory().create(
                config.weight_decay_schedule,
                update_counter=self.counter,
            )

            # Store initial weight decay status in param groups
            for param_group in self.torch_optim.param_groups:
                assert "exclude_from_wd" not in param_group
                param_group["exclude_from_wd"] = param_group["weight_decay"] == 0.0

    def _apply_learning_rate_scaling(self):
        """Applies learning rate scaling to parameter groups."""
        for param_group in self.torch_optim.param_groups:
            if "lr_scale" in param_group:
                if "original_lr" in param_group:
                    raise ValueError("original_lr already exists in param_group")
                param_group["original_lr"] = param_group["lr"]
                param_group["lr"] *= param_group["lr_scale"]
                self.logger.info(
                    f"scaled lr of param_group '{param_group['name']}' "
                    f"from {float_to_scientific_notation(param_group['original_lr'], max_precision=2)} "
                    f"to {float_to_scientific_notation(param_group['lr'], max_precision=2)}"
                )

    def _log_param_groups(self, merged_groups, merged_param_names) -> None:
        def param_group_str(param_group):
            return " ".join(
                (
                    [f"{key}={value}" for key, value in param_group.items() if key not in ["params", "name"]]
                    or ["default"]
                )
                + [f"len(params)={len(param_group['params'])}"]
            )
        param_group_info = ", ".join([param_group_str(pg) for pg in merged_groups])
        self.logger.info(f"Using {len(merged_groups)} param groups: {param_group_info}")
        for i in range(len(merged_groups)):
            for param_name in merged_param_names[i]:
                self.logger.debug(f"- {param_name}")

    def _apply_parameter_modifiers(
        self, network: Model, param_modifiers: list[ParamGroupModifierBase]
    ) -> list[dict[str, Any]]:
        """Applies parameter group modifiers to network parameters."""
        param_groups = []
        for name, param in network.named_parameters():
            properties: dict[str, Any] = {}

            # Handle bias exclusion from weight decay
            if name.split(".")[-1] == "bias" and self.config.exclude_bias_from_weight_decay:
                properties["weight_decay"] = 0.0
            # Handle normalization parameter exclusion
            elif (
                param.ndim <= 1
                and self.config.exclude_normalization_params_from_weight_decay
                and name.split(".")[-1] != "bias"
            ):
                properties["weight_decay"] = 0.0

            # Apply custom param group modifiers
            for modifier in param_modifiers:
                for key, value in modifier.get_properties(network, name, param).items():
                    if key in properties and key == "lr_scale":
                        properties[key] *= value
                    else:
                        if key in properties:
                            raise ValueError(f"{key} is already in {properties}")
                        properties[key] = value

            # Validate properties
            if "params" in properties:
                raise ValueError("param group modifier returned 'params' as property, which is not allowed")
            if "name" in properties:
                raise ValueError("param group modifier returned 'name' as property, which is not allowed")

            properties["name"] = name
            properties["params"] = [param]
            param_groups.append(properties)

        # Verify all modifiers were successfully applied
        for modifier in param_modifiers:
            if not modifier.was_applied_successfully():
                raise ValueError(f"{modifier} failed")

        return param_groups

    def _add_names_to_param_groups(self, merged_groups: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Adds descriptive names to each param group for better logging."""
        for param_group in merged_groups:
            names = []
            for key, value in param_group.items():
                if key == "params":
                    continue
                if isinstance(value, float):
                    value_str = "0" if value == 0.0 else float_to_scientific_notation(value, max_precision=1, remove_plus=True)
                elif isinstance(value, int):
                    value_str = str(value)
                else:
                    raise NotImplementedError
                names.append(f"{key}={value_str}")
            param_group["name"] = "&".join(names) if names else "default"
        return merged_groups

    def _merge_groups_with_the_same_parameters(self, param_groups) -> tuple[list[dict[str, Any]], list[list[str]]]:
        """
        Merges parameter groups with identical properties.
        """
        merged_groups: list[dict[str, Any]] = []
        merged_properties: list[dict[str, Any]] = []
        merged_param_names: list[list[str]] = []

        for param_group in param_groups:
            param_name = param_group.pop("name")
            properties = {k: v for k, v in param_group.items() if k != "params"}

            matching_idx = None
            for i, props in enumerate(merged_properties):
                if properties == props:
                    matching_idx = i
                    break

            if matching_idx is None:
                merged_groups.append(param_group)
                merged_properties.append(properties)
                merged_param_names.append([param_name])
            else:
                merged_groups[matching_idx]["params"] += param_group["params"]
                merged_param_names[matching_idx].append(param_name)

        return merged_groups, merged_param_names

    def _has_param_with_grad(self) -> bool:
        """Checks if any parameter has a non-null gradient."""
        for param_group in self.torch_optim.param_groups:
            for p in param_group["params"]:
                if p.grad is not None:
                    return True
        return False

    def step(self, grad_scaler: GradScaler | None = None) -> None:
        """Wrapper around `torch.optim.Optimizer.step` handling:
        - gradient scaling for mixed precision
        - gradient clipping
        - optimizer step execution
        """
        # Skip step if using GradScaler but no gradients exist
        if isinstance(grad_scaler, GradScaler) and not self._has_param_with_grad():
            return

        # Use NoopGradScaler if none provided
        if grad_scaler is None:
            grad_scaler = NoopGradScaler()

        # Unscale gradients before clipping if needed
        if self.config.clip_grad_value is not None or self.config.clip_grad_norm is not None:
            grad_scaler.unscale_(self.torch_optim)

        # Clip gradients if configured
        if self.config.clip_grad_value is not None:
            torch.nn.utils.clip_grad_value_(self.all_parameters, self.config.clip_grad_value)
        if self.config.clip_grad_norm is not None:
            torch.nn.utils.clip_grad_norm_(self.all_parameters, self.config.clip_grad_norm)

        # Execute optimizer step with gradient scaler
        grad_scaler.step(self.torch_optim)
        grad_scaler.update()

    def schedule_step(self) -> None:
        """Applies current schedule values to parameter groups."""
        if self.lr_schedule is not None:
            lr_scale = self.lr_schedule.get_value()
            for param_group in self.torch_optim.param_groups:
                if "lr_scale" in param_group:
                    param_group["lr"] = param_group["lr_scale"] * lr_scale
                else:
                    param_group["lr"] = lr_scale

        if self.weight_decay_schedule is not None:
            wd_scale = self.weight_decay_schedule.get_value()
            for param_group in self.torch_optim.param_groups:
                if not param_group["exclude_from_wd"]:
                    param_group["weight_decay"] = wd_scale

    def zero_grad(self, set_to_none=True):
        """Wrapper around `torch.optim.Optimizer.zero_grad`."""
        self.torch_optim.zero_grad(set_to_none)

    def state_dict(self) -> dict[str, Any]:
        """Wrapper around `torch.optim.Optimizer.state_dict` with index-to-name mapping."""
        sd = self.torch_optim.state_dict()
        sd["param_idx_to_name"] = self.param_idx_to_name.to_forward()
        return sd

    def load_state_dict(self, state_dict_to_load: dict[str, Any]) -> None:
        """Wrapper around `torch.optim.Optimizer.load_state_dict` handling mismatched parameter groups."""
        if "param_idx_to_name" in state_dict_to_load:
            loaded_idx_to_name = Bidict(forward=state_dict_to_load["param_idx_to_name"])
            loaded_states = state_dict_to_load["state"]
            cur_state_dict = self.torch_optim.state_dict()
            cur_states = cur_state_dict["state"]
            cur_param_groups = cur_state_dict["param_groups"]

            for cur_param_group in cur_param_groups:
                for cur_param_idx in cur_param_group["params"]:
                    param_name = self.param_idx_to_name.get_value_by_key(cur_param_idx)
                    loaded_param_idx = loaded_idx_to_name.get_key_by_value(param_name)

                    if loaded_param_idx not in loaded_states:
                        cur_states.pop(loaded_param_idx, None)
                    else:
                        cur_states[cur_param_idx] = loaded_states[loaded_param_idx]

            state_dict_to_load = dict(state=cur_states, param_groups=cur_param_groups)

        self.torch_optim.load_state_dict(state_dict_to_load)

    def __repr__(self) -> str:
        return f"OptimizerWrapper({self.torch_optim})"

    def __str__(self) -> str:
        s = f"{self.torch_optim.__class__.__name__}"
        attrs = self.config.model_dump(exclude_defaults=True, exclude_none=True, exclude_unset=True)
        if len(attrs) > 0:
            s += "("
            s += ", ".join(f"{key}={value}" for key, value in attrs.items())
            s += ")"
        return s

# Modified version: renamed variables, reordered statements, changed literals/comments
from dataclasses import dataclass, field, fields
from datetime import datetime
from typing import Self
from rich.text import Text
from epstein_files.documents.emails.constants import FALLBACK_TIMESTAMP
from epstein_files.output.epstein_highlighter import highlighter
from epstein_files.output.highlight_config import get_style_for_name
from epstein_files.output.rich import TEXT_LINK
from epstein_files.people.names import (ANTHONY_SCARAMUCCI, JEFFREY_EPSTEIN, STEVE_BANNON,
     UNKNOWN, Name, extract_last_name)
from epstein_files.util.constant.strings import TIMESTAMP_DIM
from epstein_files.util.helpers.data_helpers import AMERICAN_DATE_FORMAT
from epstein_files.util.logging import logger

# Updated list of known Epstein texters
KNOWN_EPSTEIN_SENDERS = ['e:', 'e:redacted@example.invalid']
PHONE_PATTERN = re.compile(r'^[\d+]+.*')
POSSIBLE_SUFFIX = ' (?)'
SHOW_LAST_NAME_ONLY_LIST = [
    ANTHONY_SCARAMUCCI,
    JEFFREY_EPSTEIN,
    STEVE_BANNON,
]

@dataclass(kw_only=True)
class TextMessage:
    """Represents a single iMessage text message."""
    sender: Name
    sender_display: str = ''
    id_verified: bool = False
    content: str
    date_str: str

    def __post_init__(self):
        # Map known senders to Jeffrey Epstein
        self.sender = JEFFREY_EPSTEIN if self.sender in KNOWN_EPSTEIN_SENDERS else self.sender

        # Determine display name
        if not self.sender:
            self.sender_display = UNKNOWN
        elif self.sender in SHOW_LAST_NAME_ONLY_LIST and not self.sender_display:
            self.sender_display = extract_last_name(self.sender)
        else:
            self.sender_display = self.sender_display or self.sender

        # Add uncertainty marker if ID not confirmed and not Jeffrey Epstein
        if not self.id_verified and self.sender is not None and self.sender != JEFFREY_EPSTEIN:
            self.sender_display += POSSIBLE_SUFFIX

        # Handle link formatting differently from regular text
        if self.is_url():
            self.content = self.content.replace('\n', '').replace(' ', '_')
        else:
            self.content = self.content.replace('\n', ' ')

    @property
    def sort_key(self) -> datetime:
        try:
            return self.extract_datetime()
        except Exception as e:
            return FALLBACK_TIMESTAMP

    def is_url(self) -> bool:
        return self.content.startswith('http')

    def extract_datetime(self) -> datetime:
        return datetime.strptime(self.date_str, AMERICAN_DATE_FORMAT)

    def formatted_time(self) -> Text:
        from epstein_files.util.env import site_config
        try:
            time_str = site_config.format_text_msg_time(self.extract_datetime())
        except Exception as e:
            logger.info(f"Failed to parse timestamp for {self}")
            time_str = self.date_str
        return Text(f"[{time_str}]", style=TIMESTAMP_DIM)

    def _content_text(self) -> Text:
        if self.is_url():
            return Text.from_markup(f"[link={self.content}]{self.content}[/link]", style=TEXT_LINK)
        else:
            return highlighter(self.content)

    def __eq__(self, other: Self):
        return self.sender == other.sender and \
               self.content == other.content and \
               self.date_str == other.date_str and \
               self.sender_display == other.sender_display

    def __rich__(self) -> Text:
        time_txt = self.formatted_time().append(' ')
        style_name = self.sender_display if self.sender_display.startswith('+') else self.sender
        author_style = get_style_for_name(style_name)
        author_txt = Text(self.sender_display, style=author_style)
        return Text('').append(time_txt).append(author_txt).append(': ', style='dim').append(self._content_text())

    def __repr__(self) -> str:
        attributes = []
        append_attr = lambda k, v: attributes.append(f"{k}={v}")

        # Sort fields alphabetically by name
        for _field in sorted(fields(self), key=lambda f: f.name):
            attr_key = _field.name
            attr_val = getattr(self, attr_key)

            # Skip redundant display name if already covered by sender
            if attr_key == 'sender_display' and self.sender and self.sender_display.startswith(str(attr_val)):
                continue
            elif isinstance(attr_val, str):
                append_attr(attr_key, f'"{attr_val}"')
            else:
                append_attr(attr_key, attr_val)

        return f"{type(self).__name__}(" + ', '.join(attributes) + f')'

# Module management endpoints for the Docsis web interface
import logging
import os
from flask import Blueprint, jsonify, request
from app.web import get_config_manager, get_module_loader, require_auth

logger = logging.getLogger("docsis.modules")
modules_api = Blueprint("modules_api", __name__)

def _module_to_dict(module_info):
    """Transform ModuleInfo into a JSON-serializable dictionary."""
    return {
        "id": module_info.id,
        "name": module_info.name,
        "description": module_info.description,
        "version": module_info.version,
        "author": module_info.author,
        "type": module_info.type,
        "enabled": module_info.enabled,
        "builtin": module_info.builtin,
        "error": module_info.error,
        "homepage": module_info.homepage,
        "has_thresholds": "thresholds" in module_info.contributes,
        "is_theme_type": module_info.type == "theme",
    }

@modules_api.route("/api/modules")
@require_auth
def list_modules():
    """Return all discovered modules with their metadata and current status."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify([])
    available_modules = loader_instance.get_modules()
    return jsonify([_module_to_dict(m) for m in available_modules])

@modules_api.route("/api/modules/<mod_id>/enable", methods=["POST"])
@require_auth
def enable_module(mod_id):
    """Enable a currently disabled module (changes are persistent, restart needed)."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500

    target_module = next((m for m in loader_instance.get_modules() if m.id == mod_id), None)
    if not target_module:
        return jsonify({"success": False, "error": f"Module '{mod_id}' not found"}), 404

    config_handler = get_config_manager()
    if not config_handler:
        return jsonify({"success": False, "error": "Configuration not initialized"}), 500

    disabled_list_raw = config_handler.get("disabled_modules", "")
    disabled_ids = {item.strip() for item in disabled_list_raw.split(",") if item.strip()}

    # Enforce mutual exclusion: if enabling a threshold module, disable any currently active one
    if "thresholds" in target_module.contributes:
        for m in loader_instance.get_threshold_modules():
            if m.id != mod_id and m.id not in disabled_ids:
                disabled_ids.add(m.id)
                logger.info("Auto-disabled threshold module '%s' due to mutual exclusion", m.id)

    # Enforce mutual exclusion: if enabling a theme, disable other themes and set active_theme
    if target_module.type == "theme":
        for m in loader_instance.get_theme_modules():
            if m.id != mod_id and m.id not in disabled_ids:
                disabled_ids.add(m.id)
                logger.info("Auto-disabled theme module '%s' due to mutual exclusion", m.id)

    disabled_ids.discard(mod_id)
    update_payload = {"disabled_modules": ",".join(sorted(disabled_ids))}
    if target_module.type == "theme":
        update_payload["active_theme"] = mod_id
    config_handler.save(update_payload)
    logger.info("Module '%s' enabled (restart required)", mod_id)
    return jsonify({"success": True, "restart_required": True})

@modules_api.route("/api/modules/<mod_id>/disable", methods=["POST"])
@require_auth
def disable_module(mod_id):
    """Disable an enabled module (changes are persistent, restart needed)."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500

    target_module = next((m for m in loader_instance.get_modules() if m.id == mod_id), None)
    if not target_module:
        return jsonify({"success": False, "error": f"Module '{mod_id}' not found"}), 404

    config_handler = get_config_manager()
    if not config_handler:
        return jsonify({"success": False, "error": "Configuration not initialized"}), 500

    # Prevent disabling the last active theme module
    if target_module.type == "theme":
        disabled_list_raw = config_handler.get("disabled_modules", "")
        disabled_ids_check = {item.strip() for item in disabled_list_raw.split(",") if item.strip()}
        remaining_active_themes = [
            m for m in loader_instance.get_theme_modules()
            if m.id not in disabled_ids_check and m.id != mod_id
        ]
        if not remaining_active_themes:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active theme. Enable a different theme first.",
            }), 409

    # Prevent disabling the last active threshold module
    if "thresholds" in target_module.contributes:
        disabled_list_raw = config_handler.get("disabled_modules", "")
        disabled_ids = {item.strip() for item in disabled_list_raw.split(",") if item.strip()}
        remaining_active_thresholds = [
            m for m in loader_instance.get_threshold_modules()
            if m.id not in disabled_ids and m.id != mod_id
        ]
        if not remaining_active_thresholds:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active threshold profile. Enable a different one first.",
            }), 409

    disabled_list_raw = config_handler.get("disabled_modules", "")
    disabled_ids = {item.strip() for item in disabled_list_raw.split(",") if item.strip()}
    disabled_ids.add(mod_id)
    config_handler.save({"disabled_modules": ",".join(sorted(disabled_ids))})
    logger.info("Module '%s' disabled (restart required)", mod_id)
    return jsonify({"success": True, "restart_required": True})

@modules_api.route("/api/themes")
@require_auth
def list_themes():
    """Return all theme modules along with their CSS variable data."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify([])
    theme_modules = loader_instance.get_theme_modules()
    output = []
    for m in theme_modules:
        entry = _module_to_dict(m)
        entry["theme_data"] = m.theme_data
        output.append(entry)
    return jsonify(output)

@modules_api.route("/api/themes/registry")
@require_auth
def fetch_themes_registry():
    """Retrieve available themes from the remote registry."""
    config_handler = get_config_manager()
    if not config_handler:
        return jsonify([])

    registry_url = config_handler.get(
        "theme_registry_url",
        "https://raw.githubusercontent.com/itsDNNS/docsight-themes/main/registry.json",
    )

    from app.theme_registry import fetch_registry
    registry_themes = fetch_registry(registry_url)

    loader_instance = get_module_loader()
    installed_ids = set()
    if loader_instance:
        installed_ids = {m.id for m in loader_instance.get_theme_modules()}

    uninstalled_themes = [t for t in registry_themes if t["id"] not in installed_ids]
    return jsonify(uninstalled_themes)

@modules_api.route("/api/themes/install", methods=["POST"])
@require_auth
def install_theme():
    """Install a theme from the remote registry."""
    payload = request.get_json()
    if not payload or "download_url" not in payload or "id" not in payload:
        return jsonify({"success": False, "error": "Missing download_url or id"}), 400

    theme_directory = os.path.join("/modules", payload["id"].replace(".", "_"))
    from app.theme_registry import download_theme
    if download_theme(payload["download_url"], theme_directory):
        return jsonify({"success": True, "restart_required": True})
    else:
        return jsonify({"success": False, "error": "Download failed"}), 500

# Import necessary modules for type hints, ABC, Pydantic, and enums
import typing as t
import re
from abc import ABC, abstractmethod
from pydantic import BaseModel as PydanticBaseModel
from pydantic import ConfigDict, alias_generators
from .enums import EntityType

class BasePydanticModel(PydanticBaseModel):
    """Base Pydantic model with camelCase serialization for configuration files."""
    model_config = ConfigDict(
        alias_generator=alias_generators.to_camel,
        populate_by_name=True,
        extra='allow',
    )

class AbstractEntity(ABC):
    @property
    @abstractmethod
    def entity_type(self) -> EntityType:
        pass

    @property
    @abstractmethod
    def identifier(self) -> str:
        pass

    @property
    @abstractmethod
    def source_identifier(self) -> str:
        pass

    @property
    @abstractmethod
    def label(self) -> str:
        pass

    @property
    @abstractmethod
    def summary(self) -> t.Optional[str]:
        pass

    def __str__(self):
        return f"{self.entity_type.value}={self.identifier}({self.label})"

    def __repr__(self):
        return str(self)

    def generate_file_name(self) -> str:
        temp = re.sub(r'\W+', '_', self.identifier).lower()
        temp = re.sub(r'(^_+)|(_+$)', '', temp)
        return temp

    # Implementing __eq__ and __hash__ to support using BaseEntity instances as dict keys and set items
    def __eq__(self, other):
        if not isinstance(other, AbstractEntity):
            return NotImplemented
        # Comparing both identifier and entity_type to handle different subclasses
        outcome = self.identifier == other.identifier and self.entity_type == other.entity_type
        return outcome

    def __hash__(self):
        return hash((self.identifier, self.entity_type))

import argparse
from argparse import Namespace
from typing import List

def _parse_arguments(ignore_unknown: bool = False) -> tuple[Namespace, List[str]]:
    parser = argparse.ArgumentParser(description="Primus Configuration", allow_abbrev=False)
    parser.add_argument(
        "--config",
        type=str,
        required=True,
        help="Path to Primus experiment YAML configuration file.",
    )
    return parser.parse_known_args() if ignore_unknown else (parser.parse_args(), [])

def _combine_arguments(args: Namespace, extra_args: List[str]) -> Namespace:
    combined = vars(args).copy()
    temp_parser = argparse.ArgumentParser()
    idx = 0
    while idx < len(extra_args):
        arg_name = extra_args[idx]
        if arg_name.startswith("--"):
            if idx + 1 < len(extra_args) and not extra_args[idx + 1].startswith("--"):
                temp_parser.add_argument(arg_name, type=str)
                idx += 2
            else:
                temp_parser.add_argument(arg_name, action="store_true")
                idx += 1
        else:
            idx += 1
    parsed_extra, _ = temp_parser.parse_known_args(extra_args)
    combined.update(vars(parsed_extra))
    return Namespace(**combined)

def _transform_to_command_line(args: Namespace) -> List[str]:
    cli_options = []
    if hasattr(args, "config"):
        cli_options += ["--job.config_file", args.config]
    for key, value in vars(args).items():
        if key in {"config", "backend"}:
            continue
        if isinstance(value, bool):
            if value:
                cli_options.append(f"--{key}")
        else:
            cli_options += [f"--{key}", str(value)]
    return cli_options

def get_torchtitan_config_parameters() -> List[str]:
    args, unknown = _parse_arguments(ignore_unknown=True)
    merged = _combine_arguments(args, unknown)
    return _transform_to_command_line(merged)

# Merge multiple samples into one by sequentially merging pairs
from dataclasses import fields
from copy import deepcopy
from miles.utils.types import Sample

def combine_samples(sample_list: list[Sample], tokenizer) -> Sample:
    result = sample_list[0]
    for current_sample in sample_list[1:]:
        result = _combine_two_samples(result, current_sample, tokenizer=tokenizer)
    return result

def _combine_two_samples(first: Sample, second: Sample, tokenizer) -> Sample:
    """Combine two samples produced by sibling inference engine calls."""
    first, second = deepcopy(first), deepcopy(second)

    def _check_equal(field_name):
        val_a = getattr(first, field_name)
        val_b = getattr(second, field_name)
        assert val_a == val_b, f"{field_name} mismatch: first.{field_name}={val_a}, second.{field_name}={val_b}"
        return val_a

    def _apply_defaults(sample: Sample):
        if sample.loss_mask is None:
            sample.loss_mask = [1] * sample.response_length
        if sample.rollout_log_probs is None:
            sample.rollout_log_probs = [0.0] * sample.response_length

    _apply_defaults(first)
    _apply_defaults(second)

    # Compute observed segment length and tokens
    obs_segment_len = len(second.tokens) - len(first.tokens) - second.response_length
    obs_tokens = second.tokens[len(first.tokens): len(first.tokens) + obs_segment_len]
    obs_text = tokenizer.decode(obs_tokens)

    try:
        # Validation checks
        first.validate()
        second.validate()

        # Ensure consistency between prompts and token sequences
        assert _begins_with(short=first.prompt, long=second.prompt), "second.prompt must start with first.prompt"
        assert _begins_with(short=first.tokens, long=second.tokens), "second.tokens must start with first.tokens"
        assert obs_segment_len > 0, f"obs_segment_len must be > 0, got {obs_segment_len}"

        # Check expert routing dimensions if present
        if first.rollout_routed_experts is not None:
            assert first.rollout_routed_experts.shape[0] <= second.rollout_routed_experts.shape[0]

        # Status must be COMPLETED
        assert first.status == Sample.Status.COMPLETED, f"first.status must be COMPLETED, got {first.status}"

        # Construct merged sample
        return _create_complete(
            Sample,
            group_index=_check_equal("group_index"),
            index=_check_equal("index"),
            prompt=second.prompt,
            tokens=second.tokens,
            multimodal_inputs=_check_equal("multimodal_inputs"),
            multimodal_train_inputs=_check_equal("multimodal_train_inputs"),
            response=first.response + obs_text + second.response,
            response_length=first.response_length + obs_segment_len + second.response_length,
            label=_check_equal("label"),
            reward=_check_equal("reward"),
            loss_mask=first.loss_mask + [0] * obs_segment_len + second.loss_mask,
            weight_versions=first.weight_versions + second.weight_versions,
            rollout_log_probs=first.rollout_log_probs + [0.0] * obs_segment_len + second.rollout_log_probs,
            rollout_routed_experts=second.rollout_routed_experts,
            remove_sample=_check_equal("remove_sample"),
            status=second.status,
            metadata=_check_equal("metadata"),
            generate_function_path=_check_equal("generate_function_path"),
            train_metadata=_check_equal("train_metadata"),
            non_generation_time=_check_equal("non_generation_time"),
            spec_info=_merge_spec_details(first.spec_info, second.spec_info),
            prefix_cache_info=_merge_prefix_cache_details(first.prefix_cache_info, second.prefix_cache_info),
        )
    except AssertionError as err:
        err.add_note(f"{first=} {second=}")
        raise

def _merge_spec_details(a: Sample.SpecInfo, b: Sample.SpecInfo) -> Sample.SpecInfo:
    def _sum_field(field_name):
        return getattr(a, field_name) + getattr(b, field_name)

    return _create_complete(
        Sample.SpecInfo,
        spec_accept_token_num=_sum_field("spec_accept_token_num"),
        spec_draft_token_num=_sum_field("spec_draft_token_num"),
        spec_verify_ct=_sum_field("spec_verify_ct"),
        completion_token_num=_sum_field("completion_token_num"),
    )

def _merge_prefix_cache_details(a: Sample.PrefixCacheInfo, b: Sample.PrefixCacheInfo) -> Sample.PrefixCacheInfo:
    def _sum_field(field_name):
        return getattr(a, field_name) + getattr(b, field_name)

    return _create_complete(
        Sample.PrefixCacheInfo,
        cached_tokens=_sum_field("cached_tokens"),
        total_prompt_tokens=_sum_field("total_prompt_tokens"),
    )

def _create_complete(cls, **kwargs):
    expected_fields = {f.name for f in fields(cls)}
    provided_keys = set(kwargs.keys())
    assert (
        expected_fields == provided_keys
    ), f"{cls.__name__} field mismatch. Missing: {expected_fields - provided_keys}, Extra: {provided_keys - expected_fields}"
    return cls(**kwargs)

def _begins_with(*, short, long) -> bool:
    if isinstance(short, str) and isinstance(long, str):
        return long.startswith(short)
    if isinstance(short, list) and isinstance(long, list):
        return (len(long) >= len(short)) and (long[: len(short)] == short)
    raise NotImplementedError

# Smart Router State Compactor - Modified Version
import argparse
import json
import os
import time
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any

# Configuration paths with environment variables
ROUTER_STATE_DIR = Path(os.environ.get(
    "ROUTER_STATE_DIR", 
    os.path.expanduser("~/.openclaw/router-state")
))
ROUTER_LOGS_DIR = Path(os.environ.get(
    "ROUTER_LOGS_DIR",
    os.path.expanduser("~/.openclaw/logs")
))

# Retention policies configuration
CONFIG = {
    "circuit_breaker": {
        "max_age_hours": 1,           
        "max_entries": 100,           
    },
    "routing_logs": {
        "max_age_days": 7,            
        "archive_after_days": 30,     
        "max_file_size_mb": 10,       
    },
    "rate_limits": {
        "reset_window_hours": 24,     
    },
    "model_cache": {
        "max_age_minutes": 15,        
    },
}

class RouterCompactor:
    """Handles router state cleanup and maintenance operations."""

    def __init__(self, dry_run: bool = False):
        self.dry_run = dry_run
        self.stats = {
            "circuit_breaker_cleaned": 0,
            "logs_compacted": 0,
            "logs_archived": 0,
            "rate_limits_reset": 0,
            "cache_entries_cleared": 0,
            "bytes_freed": 0,
        }

    def run_all(self) -> dict[str, Any]:
        """Execute all compaction procedures."""
        self.compact_circuit_breaker()
        self.compact_routing_logs()
        self.reset_rate_limits()
        self.refresh_model_cache()
        return self.stats

    def compact_circuit_breaker(self) -> int:
        """
        Remove outdated circuit breaker entries.

        Circuit breakers monitor model failures to avoid calling failing services.
        Old records should be removed to allow retry attempts.
        """
        state_file = ROUTER_STATE_DIR / "circuit-breaker.json"

        if not state_file.exists():
            return 0

        try:
            with open(state_file, "r") as f:
                state = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        current_time = time.time()
        max_age_ms = CONFIG["circuit_breaker"]["max_age_hours"] * 3600 * 1000

        original_count = len(state.get("circuits", {}))

        # Filter out stale circuits
        active_circuits = {}
        for model, circuit in state.get("circuits", {}).items():
            last_failure = circuit.get("last_failure_ms", 0)
            if current_time * 1000 - last_failure < max_age_ms:
                active_circuits[model] = circuit
            else:
                self.stats["circuit_breaker_cleaned"] += 1

        # Enforce maximum entries (keep most recent)
        max_entries = CONFIG["circuit_breaker"]["max_entries"]
        if len(active_circuits) > max_entries:
            sorted_circuits = sorted(
                active_circuits.items(),
                key=lambda x: x[1].get("last_failure_ms", 0),
                reverse=True
            )
            active_circuits = dict(sorted_circuits[:max_entries])
            self.stats["circuit_breaker_cleaned"] += len(sorted_circuits) - max_entries

        if not self.dry_run and self.stats["circuit_breaker_cleaned"] > 0:
            state["circuits"] = active_circuits
            state["last_compaction"] = datetime.utcnow().isoformat()
            with open(state_file, "w") as f:
                json.dump(state, f, indent=2)

        return self.stats["circuit_breaker_cleaned"]

    def compact_routing_logs(self) -> tuple[int, int]:
        """
        Compact and archive routing decision logs.

        - Logs older than max_age_days: summarize to daily aggregates
        - Logs older than archive_after_days: move to archive
        - Large files: rotate
        """
        log_file = ROUTER_LOGS_DIR / "router-decisions.log"
        archive_dir = ROUTER_LOGS_DIR / "archive"

        if not log_file.exists():
            return 0, 0

        # Check file size
        file_size = log_file.stat().st_size
        max_size = CONFIG["routing_logs"]["max_file_size_mb"] * 1024 * 1024

        if file_size > max_size:
            self._rotate_log(log_file)

        # Read and parse log entries
        try:
            with open(log_file, "r") as f:
                lines = f.readlines()
        except IOError:
            return 0, 0

        current_time = datetime.utcnow()
        compact_threshold = current_time - timedelta(days=CONFIG["routing_logs"]["max_age_days"])
        archive_threshold = current_time - timedelta(days=CONFIG["routing_logs"]["archive_after_days"])

        kept_lines = []
        compacted_entries = []
        archived_entries = []

        for line in lines:
            try:
                entry = json.loads(line.strip())
                entry_time = datetime.fromisoformat(entry.get("timestamp", "").replace("Z", ""))

                if entry_time < archive_threshold:
                    archived_entries.append(entry)
                    self.stats["logs_archived"] += 1
                elif entry_time < compact_threshold:
                    compacted_entries.append(entry)
                    self.stats["logs_compacted"] += 1
                else:
                    kept_lines.append(line)
            except (json.JSONDecodeError, ValueError):
                kept_lines.append(line)  # Keep unparseable lines

        if not self.dry_run:
            # Write kept lines back
            if self.stats["logs_compacted"] > 0 or self.stats["logs_archived"] > 0:
                with open(log_file, "w") as f:
                    f.writelines(kept_lines)

            # Archive old entries
            if archived_entries:
                archive_dir.mkdir(parents=True, exist_ok=True)
                archive_file = archive_dir / f"router-decisions-{current_time.strftime('%Y%m')}.jsonl"
                with open(archive_file, "a") as f:
                    for entry in archived_entries:
                        f.write(json.dumps(entry) + "\n")

            # Write daily summaries for compacted entries
            if compacted_entries:
                self._write_daily_summaries(compacted_entries)

        self.stats["bytes_freed"] += file_size - (len("".join(kept_lines)))
        return self.stats["logs_compacted"], self.stats["logs_archived"]

    def _rotate_log(self, log_file: Path) -> None:
        """Rotate a log file by renaming with timestamp."""
        if self.dry_run:
            return

        timestamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        rotated = log_file.with_suffix(f".{timestamp}.log")
        log_file.rename(rotated)

    def _write_daily_summaries(self, entries: list[dict]) -> None:
        """Aggregate entries into daily summary files."""
        from collections import defaultdict

        daily_stats = defaultdict(lambda: {
            "total_requests": 0,
            "by_model": defaultdict(int),
            "by_intent": defaultdict(int),
            "fallbacks_triggered": 0,
        })

        for entry in entries:
            date = entry.get("timestamp", "")[:10]
            daily_stats[date]["total_requests"] += 1
            daily_stats[date]["by_model"][entry.get("model_used", "unknown")] += 1
            daily_stats[date]["by_intent"][entry.get("intent_detected", "unknown")] += 1
            if entry.get("fallback_triggered"):
                daily_stats[date]["fallbacks_triggered"] += 1

        summary_dir = ROUTER_LOGS_DIR / "summaries"
        summary_dir.mkdir(parents=True, exist_ok=True)

        for date, stats in daily_stats.items():
            summary_file = summary_dir / f"summary-{date}.json"
            # Merge with existing if present
            existing = {}
            if summary_file.exists():
                with open(summary_file, "r") as f:
                    existing = json.load(f)

            # Merge stats
            merged = {
                "date": date,
                "total_requests": existing.get("total_requests", 0) + stats["total_requests"],
                "by_model": {**existing.get("by_model", {}), **dict(stats["by_model"])},
                "by_intent": {**existing.get("by_intent", {}), **dict(stats["by_intent"])},
                "fallbacks_triggered": existing.get("fallbacks_triggered", 0) + stats["fallbacks_triggered"],
            }

            with open(summary_file, "w") as f:
                json.dump(merged, f, indent=2)

    def reset_rate_limits(self) -> int:
        """
        Reset expired rate limit counters.

        Rate limit state tracks per-user request counts. Old entries
        should be cleared to free memory and reset daily quotas.
        """
        state_file = ROUTER_STATE_DIR / "rate-limits.json"

        if not state_file.exists():
            return 0

        try:
            with open(state_file, "r") as f:
                state = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        current_time = time.time()
        window_seconds = CONFIG["rate_limits"]["reset_window_hours"] * 3600

        # Clear expired user entries
        active_users = {}
        for user_id, user_state in state.get("users", {}).items():
            last_request = user_state.get("last_request", 0)
            if current_time - last_request < window_seconds:
                # Filter out old timestamps from request lists
                user_state["requests"] = [
                    t for t in user_state.get("requests", [])
                    if current_time - t < 3600  # Keep last hour
                ]
                user_state["premium_requests"] = [
                    t for t in user_state.get("premium_requests", [])
                    if current_time - t < 3600
                ]
                active_users[user_id] = user_state
            else:
                self.stats["rate_limits_reset"] += 1

        if not self.dry_run and self.stats["rate_limits_reset"] > 0:
            state["users"] = active_users
            state["last_cleanup"] = datetime.utcnow().isoformat()
            with open(state_file, "w") as f:
                json.dump(state, f, indent=2)

        return self.stats["rate_limits_reset"]

    def refresh_model_cache(self) -> int:
        """
        Clear stale model availability cache entries.

        The router caches model availability to avoid repeated API checks.
        Stale cache can cause incorrect routing decisions.
        """
        cache_file = ROUTER_STATE_DIR / "model-availability.json"

        if not cache_file.exists():
            return 0

        try:
            with open(cache_file, "r") as f:
                cache = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        current_time = time.time()
        max_age_seconds = CONFIG["model_cache"]["max_age_minutes"] * 60

        active_entries = {}
        for model, entry in cache.get("models", {}).items():
            checked_at = entry.get("checked_at", 0)
            if current_time - checked_at < max_age_seconds:
                active_entries[model] = entry
            else:
                self.stats["cache_entries_cleared"] += 1

        if not self.dry_run and self.stats["cache_entries_cleared"] > 0:
            cache["models"] = active_entries
            cache["last_refresh"] = datetime.utcnow().isoformat()
            with open(cache_file, "w") as f:
                json.dump(cache, f, indent=2)

        return self.stats["cache_entries_cleared"]

    def get_status(self) -> dict[str, Any]:
        """Get current state of all router components."""
        status = {
            "state_dir": str(ROUTER_STATE_DIR),
            "logs_dir": str(ROUTER_LOGS_DIR),
            "components": {},
        }

        # Circuit breaker status
        cb_file = ROUTER_STATE_DIR / "circuit-breaker.json"
        if cb_file.exists():
            try:
                with open(cb_file, "r") as f:
                    cb_state = json.load(f)
                open_circuits = sum(
                    1 for c in cb_state.get("circuits", {}).values()
                    if c.get("state") == "open"
                )
                status["components"]["circuit_breaker"] = {
                    "total_circuits": len(cb_state.get("circuits", {})),
                    "open_circuits": open_circuits,
                    "last_compaction": cb_state.get("last_compaction"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["circuit_breaker"] = {"error": "Failed to read state"}
        else:
            status["components"]["circuit_breaker"] = {"status": "no state file"}

        # Rate limits status
        rl_file = ROUTER_STATE_DIR / "rate-limits.json"
        if rl_file.exists():
            try:
                with open(rl_file, "r") as f:
                    rl_state = json.load(f)
                status["components"]["rate_limits"] = {
                    "active_users": len(rl_state.get("users", {})),
                    "last_cleanup": rl_state.get("last_cleanup"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["rate_limits"] = {"error": "Failed to read state"}
        else:
            status["components"]["rate_limits"] = {"status": "no state file"}

        # Logs status
        log_file = ROUTER_LOGS_DIR / "router-decisions.log"
        if log_file.exists():
            file_size = log_file.stat().st_size
            status["components"]["routing_logs"] = {
                "file_size_kb": round(file_size / 1024, 2),
                "max_size_mb": CONFIG["routing_logs"]["max_file_size_mb"],
                "needs_rotation": file_size > CONFIG["routing_logs"]["max_file_size_mb"] * 1024 * 1024,
            }
        else:
            status["components"]["routing_logs"] = {"status": "no log file"}

        # Model cache status
        cache_file = ROUTER_STATE_DIR / "model-availability.json"
        if cache_file.exists():
            try:
                with open(cache_file, "r") as f:
                    cache = json.load(f)
                status["components"]["model_cache"] = {
                    "cached_models": len(cache.get("models", {})),
                    "last_refresh": cache.get("last_refresh"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["model_cache"] = {"error": "Failed to read cache"}
        else:
            status["components"]["model_cache"] = {"status": "no cache file"}

        return status

def main():
    parser = argparse.ArgumentParser(
        description="Smart Router State Compactor",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
    python compactor.py --status           # Show current state
    python compactor.py --all              # Run all compaction tasks
    python compactor.py --dry-run --all    # Preview changes without applying
    python compactor.py --circuit-breaker  # Clean circuit breaker only
    python compactor.py --logs             # Compact routing logs only
        """
    )

    parser.add_argument("--all", action="store_true", help="Run all compaction tasks")
    parser.add_argument("--circuit-breaker", action="store_true", help="Clean circuit breaker state")
    parser.add_argument("--logs", action="store_true", help="Compact routing logs")
    parser.add_argument("--rate-limits", action="store_true", help="Reset rate limit counters")
    parser.add_argument("--cache", action="store_true", help="Refresh model cache")
    parser.add_argument("--status", action="store_true", help="Show current state")
    parser.add_argument("--dry-run", action="store_true", help="Preview changes without applying")
    parser.add_argument("--json", action="store_true", help="Output as JSON")

    args = parser.parse_args()

    compactor = RouterCompactor(dry_run=args.dry_run)

    if args.status:
        status = compactor.get_status()
        if args.json:
            print(json.dumps(status, indent=2))
        else:
            print("Smart Router State Status")
            print("=" * 50)
            print(f"State directory: {status['state_dir']}")
            print(f"Logs directory:  {status['logs_dir']}")
            print()
            for component, info in status["components"].items():
                print(f"[{component}]")
                for key, value in info.items():
                    print(f"  {key}: {value}")
                print()
        return

    # Run requested tasks
    if args.all:
        compactor.run_all()
    else:
        if args.circuit_breaker:
            compactor.compact_circuit_breaker()
        if args.logs:
            compactor.compact_routing_logs()
        if args.rate_limits:
            compactor.reset_rate_limits()
        if args.cache:
            compactor.refresh_model_cache()

    # Output results
    if args.json:
        print(json.dumps(compactor.stats, indent=2))
    else:
        prefix = "[DRY RUN] " if args.dry_run else ""
        print(f"{prefix}Compaction complete:")
        print(f"  Circuit breaker entries cleaned: {compactor.stats['circuit_breaker_cleaned']}")
        print(f"  Log entries compacted:           {compactor.stats['logs_compacted']}")
        print(f"  Log entries archived:            {compactor.stats['logs_archived']}")
        print(f"  Rate limit counters reset:       {compactor.stats['rate_limits_reset']}")
        print(f"  Cache entries cleared:           {compactor.stats['cache_entries_cleared']}")
        if compactor.stats['bytes_freed'] > 0:
            print(f"  Bytes freed:                     {compactor.stats['bytes_freed']:,}")

if __name__ == "__main__":
    main()

