@require_torch
@require_vision
class ProcessorTestBase:
    processor_type = None

    def setup_processor_config(self):
        return {}

    def fetch_component(self, attr_name, **kwargs):
        assert attr_name in self.processor_type.attributes
        class_name_attr = getattr(self.processor_type, f"{attr_name}_class")
        if isinstance(class_name_attr, tuple):
            class_name_attr = class_name_attr[0]
        component_cls = processor_class_from_name(class_name_attr)
        component = component_cls.from_pretrained(self.temp_dir, **kwargs)
        if attr_name == "tokenizer" and not component.pad_token:
            component.pad_token = "[TEST_PAD]"
        return component

    def assemble_components(self):
        parts = {}
        for attr in self.processor_type.attributes:
            part = self.fetch_component(attr)
            parts[attr] = part
        return parts

    def build_processor(self):
        parts = self.assemble_components()
        processor = self.processor_type(**parts, **self.setup_processor_config())
        return processor

    def generate_image_samples(self):
        """Generates a list of PIL images or numpy arrays based on flags."""
        image_samples = [np.random.randint(255, size=(3, 30, 400), dtype=np.uint8)]
        image_samples = [Image.fromarray(np.moveaxis(x, 0, -1)) for x in image_samples]
        return image_samples

    def test_serialization_to_json(self):
        proc = self.build_processor()
        parsed_obj = json.loads(proc.to_json_string())
        for k, v in self.setup_processor_config().items():
            self.assertEqual(parsed_obj[k], v)
            self.assertEqual(getattr(proc, k, None), v)

    def test_save_and_load_pretrained(self):
        first_proc = self.build_processor()
        with tempfile.TemporaryDirectory() as temp_dir:
            saved_paths = first_proc.save_pretrained(temp_dir)
            if len(saved_paths) > 0:
                check_json_file_has_correct_format(saved_paths[0])
                second_proc = self.processor_type.from_pretrained(temp_dir)
                self.assertEqual(second_proc.to_dict(), first_proc.to_dict())


@require_torch
@require_vision
class ProcessorTesterMixin(ProcessorTestBase):
    processor_type = None

    def skip_if_no_typed_kwargs(self, proc):
        is_kwargs_typed_dict = False
        call_sig = inspect.signature(proc.__call__)
        for param in call_sig.parameters.values():
            if param.kind == param.VAR_KEYWORD and param.annotation != param.empty:
                is_kwargs_typed_dict = (
                    hasattr(param.annotation, "__origin__") and 
                    param.annotation.__origin__ == Unpack
                )
        if not is_kwargs_typed_dict:
            self.skipTest(f"{self.processor_type} doesn't have typed kwargs.")

    @require_vision
    @require_torch
    def test_tokenizer_kwargs_preserved(self):
        if "image_processor" not in self.processor_type.attributes:
            self.skipTest(f"image_processor attribute not present in {self.processor_type}")

        img_proc = self.fetch_component("image_processor")
        tok = self.fetch_component("tokenizer", max_length=117, padding="max_length")
        proc = self.processor_type(tokenizer=tok, image_processor=img_proc)
        self.skip_if_no_typed_kwargs(proc)

        text_input = "lower newer"
        img_data = self.generate_image_samples()
        inputs = proc(text=text_input, images=img_data, return_tensors="pt")
        self.assertEqual(len(inputs["input_ids"][0]), 117)

    @require_torch
