# AMap (Gaode Map) API Client and CLI Tool
import sys
import json
import requests
import argparse
import os

class GaodeMapClient:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = "https://restapi.amap.com/v3"

    def search_places(self, query_terms, region=None):
        """
        Search for places using keywords.
        """
        endpoint = f"{self.base_url}/place/text"
        parameters = {
            "key": self.api_key,
            "keywords": query_terms,
            "output": "json"
        }
        if region:
            parameters["city"] = region

        try:
            response = requests.get(endpoint, params=parameters)
            response.raise_for_status()
            data = response.json()
            if data.get("status") == "1":
                return data.get("pois", [])
            else:
                return {"error": data.get("info", "Unknown error")}
        except Exception as ex:
            return {"error": str(ex)}

    def get_coordinates(self, location_address, region=None):
        """
        Convert a textual address to geographic coordinates.
        """
        endpoint = f"{self.base_url}/geocode/geo"
        parameters = {
            "key": self.api_key,
            "address": location_address,
            "output": "json"
        }
        if region:
            parameters["city"] = region

        try:
            response = requests.get(endpoint, params=parameters)
            response.raise_for_status()
            data = response.json()
            if data.get("status") == "1" and data.get("geocodes"):
                return data["geocodes"][0]["location"]
            else:
                return None
        except:
            return None

    def calculate_direction(self, start_point, end_point, travel_mode="driving", region=None):
        """
        Calculate route between start and end points.
        Points can be coordinates (lon,lat) or place names.
        If names are given, geocoding will be attempted automatically.
        """
        # Attempt geocoding if input doesn't contain comma (not in coordinate format)
        if "," not in start_point:
            coord = self.get_coordinates(start_point, region)
            if coord:
                start_point = coord
            else:
                return {"error": f"Failed to resolve start location: {start_point}"}

        if "," not in end_point:
            coord = self.get_coordinates(end_point, region)
            if coord:
                end_point = coord
            else:
                return {"error": f"Failed to resolve end location: {end_point}"}

        if travel_mode == "driving":
            endpoint = f"{self.base_url}/direction/driving"
        elif travel_mode == "walking":
            endpoint = f"{self.base_url}/direction/walking"
        elif travel_mode == "bicycling":
            endpoint = f"{self.base_url}/direction/bicycling"
        elif travel_mode == "transit":
            endpoint = f"{self.base_url}/direction/transit/integrated"
            if not region:
                 return {"error": "City parameter is mandatory for public transit routing"}
        else:
            return {"error": f"Unsupported travel mode: {travel_mode}"}

        parameters = {
            "key": self.api_key,
            "origin": start_point,
            "destination": end_point,
            "output": "json"
        }

        if travel_mode == "transit" and region:
             parameters["city"] = region

        try:
            response = requests.get(endpoint, params=parameters)
            response.raise_for_status()
            data = response.json()
            if data.get("status") == "1":
                return data.get("route", {})
            else:
                return {"error": data.get("info", "Unknown error")}
        except Exception as ex:
            return {"error": str(ex)}

def execute():
    parser = argparse.ArgumentParser(description="Gaode Map (AMap) Utility Tool")
    parser.add_argument("command", choices=["search", "route"], help="Operation to perform")
    parser.add_argument("--api-key", help="Gaode Map API Key (can also use AMAP_API_KEY environment variable)")
    parser.add_argument("--terms", help="Search terms for place lookup")
    parser.add_argument("--region", help="City/region scope for search or routing")
    parser.add_argument("--from-place", help="Starting point for route calculation")
    parser.add_argument("--to-place", help="Destination for route calculation")
    parser.add_argument("--transport", default="driving", choices=["driving", "walking", "bicycling", "transit"], help="Routing method")
    arguments = parser.parse_args()

    api_key = arguments.api_key or os.environ.get("AMAP_API_KEY")
    if not api_key:
        print(json.dumps({"error": "API key required. Provide via --api-key or set AMAP_API_KEY environment variable."}))
        sys.exit(1)

    client = GaodeMapClient(api_key)
    output = {}

    if arguments.command == "search":
        if not arguments.terms:
            output = {"error": "--terms must be specified for search operation"}
        else:
            output = client.search_places(arguments.terms, arguments.region)
    elif arguments.command == "route":
        if not arguments.from_place or not arguments.to_place:
            output = {"error": "--from-place and --to-place are necessary for route planning"}
        else:
            output = client.calculate_direction(arguments.from_place, arguments.to_place, arguments.transport, arguments.region)

    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    execute()

