try:
    import nltk
    from nltk.tokenize.punkt import PunktLanguageVars
    has_nltk = True
except ImportError:
    PunktLanguageVars = object  # Fallback to the built-in object class
    has_nltk = False

try:
    import pyarrow.parquet as pq
    has_parquet = True
except ImportError:
    has_parquet = False

from transformers import AutoTokenizer
from nemo_automodel.components.datasets.llm.megatron import indexed_dataset

class ModifiedLanguageVars(PunktLanguageVars):
    _period_context_fmt = r"""
        \S*                          # some word material
        %(SentEndChars)s             # a potential sentence ending
        \s*                       #  <-- THIS is what I changed
        (?=(?P<after_tok>
            %(NonWord)s              # either other punctuation
            |
            (?P<next_tok>\S+)     #  <-- Normally you would have \s+ here
        ))"""

class NullSplitter(object):
    def tokenize(self, *text):
        return text

def parquet_line_generator(file_path, text_field, batch_size=5000):
    """Iterate over parquet file rows, yielding JSON-like strings for each row."""
    parquet_file = pq.ParquetFile(file_path)
    for batch in parquet_file.iter_batches(batch_size=batch_size, columns=[text_field]):
        for text_value in batch.column(text_field):
            yield json.dumps({"text": text_value.as_py()})

class Processor(object):
    def __init__(self, config):
        self.config = config

    def setup(self):
        Processor.tokenizer = AutoTokenizer.from_pretrained(self.config.pretrained_model_name_or_path)
        if self.config.segment_sentences:
            if not has_nltk:
                print("NLTK is not available to split sentences.")
                exit()
            if os.environ.get("NLTK_DATA"):
                library = os.path.join(os.environ.get("NLTK_DATA"), "tokenizers", "punkt", f"{self.config.language}.pickle")
                url = f"file:{library}"
            else:
                library = os.path.join("tokenizers", "punkt", f"{self.config.language}.pickle")
                url = f"nltk:{library}"
            splitter = nltk.load(url)
            if self.config.preserve_linebreaks:
                Processor.splitter = nltk.tokenize.punkt.PunktSentenceTokenizer(
                    train_text=splitter._params, lang_vars=ModifiedLanguageVars()
                )
            else:
                Processor.splitter = splitter
        else:
            Processor.splitter = NullSplitter()

    def break_into_parts(self, json_string):
        data = json.loads(json_string)
        result = {}
        for field in self.config.json_fields:
            content = data[field]
            chunk_size = 1000000
            tokenized_chunks = [Processor.splitter.tokenize(content[i : i + chunk_size]) for i in range(0, len(content), chunk_size)]
            result[field] = [tokens for partial in tokenized_chunks for tokens in partial]
        return json.dumps(result), len(json_string)

    def convert_to_ids(self, json_string):
        data = json.loads(json_string)
        token_ids = {}
        lengths = {}
        for field in self.config.json_fields:
            content = data[field]
            if isinstance(content, list):
                segments = content
            else:
                segments = [content]
            document_ids = []
            segment_lengths = []
            for segment in segments:
                ids = Processor.tokenizer(segment).input_ids
                if len(ids) > 0:
                    document_ids.extend(ids)
                    segment_lengths.append(len(ids))
            if len(document_ids) > 0 and self.config.add_eos_token:
                document_ids.append(Processor.tokenizer.eos_token_id)
                segment_lengths[-1] += 1
            token_ids[field] = document_ids
            lengths[field] = segment_lengths
        return token_ids, lengths, len(json_string)

class Distributor(object):
    def __init__(self, config, num_workers):
        self.config = config
        self.num_workers = num_workers

    def show_progress(self, count, start_time, total_bytes, source=None):
        if count % self.config.report_frequency == 0:
            now = time.time()
            duration = now - start_time
            mb_per_sec = total_bytes / duration / 1024 / 1024
            source_info = f" in {os.path.basename(source)}" if source else ""
            print(
                f"Processed {count} documents{source_info}", f"({count / duration} docs/s, {mb_per_sec} MB/s).", file=sys.stderr
            )

    def perform_sentence_splitting(self, filenames):
        input_file, output_file = filenames
        print("Opening", input_file)
        with open(input_file, "r", encoding="utf-8") as fin:
            with open(output_file, "w") as fout:
                processor = Processor(self.config)
                pool = multiprocessing.Pool(self.num_workers, initializer=processor.setup)
                processed_docs = pool.imap(processor.break_into_parts, fin, 32)
                start_time = time.time()
                total_bytes_processed = 0
                for idx, (doc, bytes_read) in enumerate(processed_docs, start=1):
                    total_bytes_processed += bytes_read
                    fout.write(doc + "\n")
                    self.show_progress(idx, start_time, total_bytes_processed, source=input_file)
                pool.close()
                pool.join()

    def handle_json_input(self, filenames):
        input_file, output_prefix = filenames
        print("Opening", input_file)
        startup_start = time.time()
        processor = Processor(self.config)
        tokenizer = AutoTokenizer.from_pretrained(self.config.pretrained_model_name_or_path)
        pool = multiprocessing.Pool(self.num_workers, initializer=processor.setup)
        encoded_docs = pool.imap(processor.convert_to_ids, open(input_file, "r", encoding="utf-8"), 32)
        level = "document"
        if self.config.segment_sentences:
            level = "sentence"
        output_bin_files = {}
        output_idx_files = {}
        builders = {}
        for key in self.config.json_fields:
            output_bin_files[key] = "{}_{}_{}.bin".format(output_prefix, key, level)
            output_idx_files[key] = "{}_{}_{}.idx".format(output_prefix, key, level)
            builders[key] = indexed_dataset.IndexedDatasetBuilder(
                output_bin_files[key],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )
        startup_end = time.time()
        proc_start = time.time()
        total_bytes_processed = 0
        print("Time to startup:", startup_end - startup_start)
        for i, (doc, sentence_lens, bytes_processed) in enumerate(encoded_docs, start=1):
            total_bytes_processed += bytes_processed
            for key in doc.keys():
                builders[key].add_document(doc[key], sentence_lens[key])
            self.show_progress(i, proc_start, total_bytes_processed, source=input_file)
        pool.close()
        pool.join()
        for key in builders.keys():
            builders[key].finalize(output_idx_files[key])

    def handle_parquet_input(self, filenames):
        input_file, output_prefix = filenames
        print("Opening parquet file:", input_file)
        startup_start = time.time()
        processor = Processor(self.config)
        tokenizer = AutoTokenizer.from_pretrained(self.config.pretrained_model_name_or_path)
        pool = multiprocessing.Pool(self.num_workers, initializer=processor.setup)
        row_iterator = parquet_line_generator(
            input_file, self.config.text_column, batch_size=self.config.parquet_batch_size
        )
        encoded_docs = pool.imap(processor.convert_to_ids, row_iterator, 32)
        level = "document"
        if self.config.segment_sentences:
            level = "sentence"
        output_bin_files = {}
        output_idx_files = {}
        builders = {}
        for key in self.config.json_fields:
            output_bin_files[key] = "{}_{}_{}.bin".format(output_prefix, key, level)
            output_idx_files[key] = "{}_{}_{}.idx".format(output_prefix, key, level)
            builders[key] = indexed_dataset.IndexedDatasetBuilder(
                output_bin_files[key],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )
        startup_end = time.time()
        proc_start = time.time()
        total_bytes_processed = 0
        print("Time to startup:", startup_end - startup_start)
        for i, (doc, sentence_lens, bytes_processed) in enumerate(encoded_docs, start=1):
            total_bytes_processed += bytes_processed
            for key in doc.keys():
                builders[key].add_document(doc[key], sentence_lens[key])
            self.show_progress(i, proc_start, total_bytes_processed, source=input_file)
        pool.close()
        pool.join()
        for key in builders.keys():
            builders[key].finalize(output_idx_files[key])

def parse_arguments():
    parser = argparse.ArgumentParser()
    group = parser.add_argument_group(title="input data")
    group.add_argument("--input", type=str, required=True, help="Path to input JSON or Parquet file(s)")
    group.add_argument(
        "--json-fields", nargs="+", default=["text"], help="space separate listed of keys to extract from json"
    )
    group.add_argument(
        "--input-format",
        type=str,
        choices=["json", "parquet", "auto"],
        default="auto",
        help="Input file type. 'auto' detects from file extension (default: auto)",
    )
    group.add_argument(
        "--text-column",
        type=str,
        default="text",
        help="Column name containing text data in parquet files (default: text)",
    )
    group.add_argument(
        "--parquet-batch-size",
        type=int,
        default=5000,
        help="Batch size for reading parquet files (default: 5000)",
    )
    group.add_argument("--segment-sentences", action="store_true", help="Split documents into sentences.")
    group.add_argument("--preserve-linebreaks", action="store_true", help="Keep newlines between sentences when splitting.")
    group = parser.add_argument_group(title="tokenization process")
    group.add_argument("--add-eos-token", action="store_true", help="Append an <eod> token to the end of a document.")
    group.add_argument(
        "--language", type=str, default="english", help="Language to use for NLTK-powered sentence splitting."
    )
    group = parser.add_argument_group(title="output data")
    group.add_argument("--output-prefix", type=str, required=True, help="Path to binary output file without suffix")
    group.add_argument(
        "--output-directory",
        type=str,
        default=None,
        help=(
            "Directory to write outputs. If provided, this directory "
            "will be created if missing and used for all generated files. "
            "Overrides any directory component in --output-prefix."
        ),
    )
    group = parser.add_argument_group(title="runtime")
    group.add_argument(
        "--workers",
        type=int,
        required=True,
        help=("Number of worker processes to launch. Workers are divided across matched input files."),
    )
    group.add_argument("--report-frequency", type=int, default=1000, help="Interval between progress updates")
    group.add_argument("--pretrained-model-name-or-path", type=str, required=True, help="Pretrained model name or path")
    args = parser.parse_args()
    return args

def identify_file_type(file_path):
    """Detect file type based on extension."""
    ext = os.path.splitext(file_path)[1].lower()
    if ext in [".parquet", ".pq"]:
        return "parquet"
    elif ext in [".json", ".jsonl"]:
        return "json"
    else:
        return "json"

def verify_output_files(file_mappings, key, count):
    for i in range(count):
        if not os.path.exists(file_mappings[i][key]):
            return False
    return True

def run_pipeline():
    config = parse_arguments()
    if config.segment_sentences:
        if has_nltk:
            nltk.download("punkt", quiet=True, download_dir=os.environ.get("NLTK_DATA"))
        else:
            raise Exception("nltk library required for sentence splitting is not available.")

    if config.output_directory:
        os.makedirs(config.output_directory, exist_ok=True)

    if glob.has_magic(config.input):
        input_files = glob.glob(config.input)
    else:
        input_files = [config.input]

    if len(input_files) == 0:
        print(f"No files matched input pattern: {config.input}")
        return

    if config.input_format == "auto":
        detected_type = identify_file_type(input_files[0])
    else:
        detected_type = config.input_format

    if detected_type == "parquet" and not has_parquet:
        raise Exception(
            "pyarrow library is required for parquet files but is not available. Install with: pip install pyarrow"
        )

    if detected_type == "parquet" and config.segment_sentences:
        print("Warning: Sentence splitting for parquet files is not currently supported. Ignoring --segment-sentences.")
        config.segment_sentences = False

    workers_per_input = max(1, config.workers // len(input_files))
    distributor = Distributor(config, workers_per_input)

    file_mappings = []
    for idx, input_file in enumerate(input_files):
        base_name, extension = os.path.splitext(input_file)
        if config.output_directory:
            base_filename = os.path.basename(base_name)
            intermediate_file = os.path.join(config.output_directory, base_filename + "_ss" + extension)
            final_prefix = os.path.join(config.output_directory, f"{os.path.basename(config.output_prefix)}_{idx}")
        else:
            intermediate_file = base_name + "_ss" + extension
            final_prefix = f"{config.output_prefix}_{idx}"

        file_mappings.append(
            {"original": input_file, "intermediate": intermediate_file, "final_prefix": final_prefix}
        )

    if detected_type == "json":
        needs_splitting = verify_output_files(file_mappings, "intermediate", len(file_mappings))
        if config.segment_sentences and not needs_splitting:
            processes = []
            for mapping in file_mappings:
                p = multiprocessing.Process(
                    target=distributor.perform_sentence_splitting, 
                    args=((mapping["original"], mapping["intermediate"]),)
                )
                p.start()
                processes.append(p)
            for p in processes:
                p.join()

        processes = []
        input_key = "intermediate" if config.segment_sentences else "original"
        for mapping in file_mappings:
            p = multiprocessing.Process(
                target=distributor.handle_json_input, 
                args=((mapping[input_key], mapping["final_prefix"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()
    else:
        processes = []
        for mapping in file_mappings:
            p = multiprocessing.Process(
                target=distributor.handle_parquet_input, 
                args=((mapping["original"], mapping["final_prefix"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()

if __name__ == "__main__":
    run_pipeline()

