def batch_generator(rng: jax.random.PRNGKey, dataset: Dataset, size: int, shuffle_samples: bool = False):
    """
    Create batches of specified size from dataset, distributed across devices.
    Shuffle batches when shuffle_samples is True.
    """
    num_batches = len(dataset) // size
    if shuffle_samples:
        indices = jax.random.permutation(rng, len(dataset))
    else:
        indices = jnp.arange(len(dataset))

    indices = indices[:num_batches * size]  # Remove incomplete batches
    indices = indices.reshape((num_batches, size))

    for idx in indices:
        batch_data = dataset[idx]
        yield {k: jnp.array(v) for k, v in batch_data.items()}

def log_training_metrics(writer, metrics, duration, step):
    writer.scalar("training_duration", duration, step)
    stacked_metrics = stack_forest(metrics)
    for metric_name, values in stacked_metrics.items():
        tag = f"train_{metric_name}"
        for i, value in enumerate(values):
            writer.scalar(tag, value, step - len(values) + i + 1)

def log_evaluation_metrics(writer, metrics, step):
    for name, value in metrics.items():
        writer.scalar(f"eval_{name}", value, step)

def create_scheduler(
    dataset_size: int, batch_size: int, epochs: int, warmup_steps: int, base_lr: float
) -> Callable[[int], jnp.ndarray]:
    """Returns linear warmup followed by linear decay learning rate schedule."""
    steps_per_epoch = dataset_size // batch_size
    total_steps = steps_per_epoch * epochs

    warmup_schedule = optax.linear_schedule(
        init_value=0.0, end_value=base_lr, transition_steps=warmup_steps
    )
    decay_schedule = optax.linear_schedule(
        init_value=base_lr, end_value=0.0, transition_steps=total_steps - warmup_steps
    )

    return optax.join_schedules(
        schedules=[warmup_schedule, decay_schedule],
        boundaries=[warmup_steps]
    )

def main():
    # Argument parsing setup
    parser = HfArgumentParser((ModelArgs, DataArgs, TrainingArguments))

    # Load arguments from JSON file if provided
    if len(sys.argv) == 2 and sys.argv[1].endswith(".json"):
        model_args, data_args, training_args = parser.parse_json_file(
            json_file=os.path.abspath(sys.argv[1])
        )
    else:
        model_args, data_args, training_args = parser.parse_args_into_dataclasses()

    # Check output directory existence
    if (
        os.path.exists(training_args.output_dir)
        and os.listdir(training_args.output_dir)
        and training_args.do_train
        and not training_args.force_overwrite
    ):
        raise ValueError(
            f"Output directory ({training_args.output_dir}) exists and is not empty. "
            "Use --force_overwrite to override."
        )

    # Logging configuration
    logging.basicConfig(
        format="%(asctime)s - %(levelname)s - %(name)s - %(message)s",
        datefmt="%m/%d/%Y %H:%M:%S",
        level=logging.INFO,
    )

    # Process-specific logging setup
    logger.setLevel(logging.INFO if jax.process_index() == 0 else logging.ERROR)
    if jax.process_index() == 0:
        datasets.utils.logging.set_verbosity_warning()
        transformers.utils.logging.set_verbosity_info()
    else:
        datasets.utils.logging.set_verbosity_error()
        transformers.utils.logging.set_verbosity_error()

    logger.info(f"Training/evaluation parameters: {training_args}")

    # Dataset loading
    if data_args.dataset_id is not None:
        raw_dataset = load_dataset(
            data_args.dataset_id, data_args.dataset_variant, 
            cache_dir=model_args.cache_directory, keep_in_memory=False
        )

        if "validation" not in raw_dataset:
            raw_dataset["validation"] = load_dataset(
                data_args.dataset_id,
                data_args.dataset_variant,
                split=f"train[:{data_args.validation_ratio}%]",
                cache_dir=model_args.cache_directory,
            )
            raw_dataset["train"] = load_dataset(
                data_args.dataset_id,
                data_args.dataset_variant,
                split=f"train[{data_args.validation_ratio}%:]",
                cache_dir=model_args.cache_directory,
            )
    else:
        data_files = {}
        if data_args.train_source is not None:
            data_files["train"] = data_args.train_source
        if data_args.eval_source is not None:
            data_files["validation"] = data_args.eval_source

        ext = data_args.train_source.split(".")[-1] if data_args.train_source else "text"
        if ext not in ["csv", "json"]:
            ext = "text"

        raw_dataset = load_dataset(ext, data_files=data_files, cache_dir=model_args.cache_directory)

    # Model and tokenizer loading
    if model_args.config_path:
        config = AutoConfig.from_pretrained(model_args.config_path, cache_dir=model_args.cache_directory)
    elif model_args.checkpoint_path:
        config = AutoConfig.from_pretrained(model_args.checkpoint_path, cache_dir=model_args.cache_directory)
    else:
        config = CONFIG_MAPPING[model_args.architecture_type]()
        logger.warning("Initializing new model configuration from scratch")

    if model_args.tokenizer_path:
        tokenizer = AutoTokenizer.from_pretrained(
            model_args.tokenizer_path, 
            cache_dir=model_args.cache_directory, 
            use_fast=model_args.use_fast_tokenization
        )
    elif model_args.checkpoint_path:
        tokenizer = AutoTokenizer.from_pretrained(
            model_args.checkpoint_path, 
            cache_dir=model_args.cache_directory, 
            use_fast=model_args.use_fast_tokenization
        )
    else:
        raise ValueError(
            "Tokenizer initialization from scratch not supported. "
            "Use --tokenizer_path to specify existing tokenizer."
        )

    # Prepare datasets
    column_names = (
        raw_dataset["train"].column_names if training_args.do_train 
        else raw_dataset["validation"].column_names
    )
    text_column = "text" if "text" in column_names else column_names[0]

    # Tokenization setup
    tokenizer_logger = transformers.utils.logging.get_logger("transformers.tokenization_utils_base")

    def tokenize_batch(examples):
        with CaptureLogger(tokenizer_logger) as cl:
            result = tokenizer(examples[text_column])
        if "Token indices sequence length is longer than" in cl.out:
            tokenizer_logger.warning(
                "^^^^^^^^^^^^^^^^ Long sequences will be chunked into smaller segments."
            )
        return result

    tokenized_datasets = raw_dataset.map(
        tokenize_batch,
        batched=True,
        num_proc=data_args.workers_count,
        remove_columns=column_names,
        load_from_cache_file=not data_args.force_cache_refresh,
    )

    # Determine sequence length
    if data_args.sequence_length is None:
        seq_len = tokenizer.model_max_length
        if seq_len > config.max_position_embeddings:
            logger.warning(
                f"Tokenizer has large model_max_length ({seq_len}). Using block_size={min(1024, config.max_position_embeddings)}"
            )
            seq_len = min(1024, config.max_position_embeddings)
    else:
        if data_args.sequence_length > tokenizer.model_max_length:
            logger.warning(
                f"Specified block_size ({data_args.sequence_length}) exceeds tokenizer limit. Using {tokenizer.model_max_length}."
            )
        seq_len = min(data_args.sequence_length, tokenizer.model_max_length)

    # Group texts into blocks
    def prepare_lm_data(examples):
        merged = {k: list(chain(*examples[k])) for k in examples.keys()}
        total_len = len(merged[list(examples.keys())[0]])

        if total_len >= seq_len:
            total_len = (total_len // seq_len) * seq_len

        result = {
            k: [t[i : i + seq_len] for i in range(0, total_len, seq_len)]
            for k, t in merged.items()
        }
        result["labels"] = result["input_ids"].copy()
        return result

    lm_datasets = tokenized_datasets.map(
        prepare_lm_data,
        batched=True,
        num_proc=data_args.workers_count,
        load_from_cache_file=not data_args.force_cache_refresh,
    )

    # Prepare datasets for training/evaluation
    train_dataset = lm_datasets["train"] if training_args.do_train else None
    eval_dataset = lm_datasets["validation"] if training_args.do_eval else None

    if training_args.do_train and data_args.max_train_items:
        train_dataset = train_dataset.select(range(min(len(train_dataset), data_args.max_train_items)))

    if training_args.do_eval and data_args.max_eval_items:
        eval_dataset = eval_dataset.select(range(min(len(eval_dataset), data_args.max_eval_items)))

    # TensorBoard setup
    tensorboard_available = is_tensorboard_available()
    if tensorboard_available and jax.process_index() == 0:
        try:
            from flax.metrics.tensorboard import SummaryWriter
            summary_writer = SummaryWriter(log_dir=Path(training_args.output_dir))
        except ImportError as e:
            tensorboard_available = False
            logger.warning(f"TensorBoard unavailable: {e}")
    else:
        logger.warning("TensorBoard not available. Install with 'pip install tensorboard'")

    # Initialize training components
    rng = jax.random.PRNGKey(training_args.seed)
    rng, dropout_rng = jax.random.split(rng)

    # Calculate batch sizes and steps
    num_epochs = int(training_args.num_train_epochs)
    train_batch_size = int(training_args.per_device_train_batch_size) * jax.device_count()
    eval_batch_size = int(training_args.per_device_eval_batch_size) * jax.device_count()
    steps_per_epoch = len(train_dataset) // train_batch_size
    total_steps = steps_per_epoch * num_epochs

    # Load model
    model = FlaxAutoModelForCausalLM.from_pretrained(
        model_args.checkpoint_path, 
        seed=training_args.seed, 
        dtype=getattr(jnp, model_args.precision)
    )

    # Learning rate scheduler and optimizer
    lr_scheduler = create_scheduler(
        len(train_dataset),
        train_batch_size,
        training_args.num_train_epochs,
        training_args.warmup_steps,
        training_args.learning_rate,
    )

    optimizer = optax.adamw(
        learning_rate=lr_scheduler,
        b1=training_args.adam_beta1,
        b2=training_args.adam_beta2,
        eps=training_args.adam_epsilon,
        weight_decay=training_args.weight_decay,
    )

    # State initialization
    def initialize_state(params):
        state = optimizer.init(params)
        return tuple(state), params

    # Partitioning setup
    param_spec = set_partitions(unfreeze(model.params))
    param_shapes = jax.tree_util.tree_map(lambda x: x.shape, model.params)
    state_shapes = jax.eval_shape(initialize_state, param_shapes)

    def get_opt_spec(x):
        return param_spec if isinstance(x, dict) else None

    opt_state_spec, param_spec = jax.tree_util.tree_map(
        get_opt_spec, state_shapes,
        is_leaf=lambda x: isinstance(x, (dict, optax.EmptyState))
    )

    # JIT-compiled state initialization
    p_initialize_state = pjit(
        initialize_state,
        in_axis_resources=None,
        out_axis_resources=(opt_state_spec, param_spec),
    )

    # Move initial params to CPU
    model.params = jax.tree_util.tree_map(lambda x: np.asarray(x), model.params)

    # Device mesh setup
    device_mesh = np.array(jax.devices()).reshape(1, jax.local_device_count())

    # Initialize optimizer state
    with mesh(device_mesh, ("dp", "mp")):
        opt_state, params = p_initialize_state(freeze(model.params))

    # Loss function definition
    def compute_loss(logits, labels, z_loss_weight=0):
        shift_logits = logits[..., :-1, :]
        shift_labels = labels[..., 1:]
        shift_labels = onehot(shift_labels, shift_logits.shape[-1])

        shift_logits = shift_logits - jax.lax.stop_gradient(shift_logits.max(axis=-1, keepdims=True))
        log_z = jnp.log(jnp.sum(jnp.exp(shift_logits), axis=-1, keepdims=True))
        log_softmax = shift_logits - log_z

        loss = -jnp.sum(shift_labels * log_softmax, axis=-1)
        loss += (1e-4 * jnp.square(log_z.squeeze(-1))) * z_loss_weight
        return loss.mean()

    # Training step function
    def train_step(params, opt_state, dropout_rng, batch, step):
        dropout_rng, new_dropout_rng = jax.random.split(dropout_rng)

        def compute_loss_value(params):
            labels = batch.pop("labels")
            logits = model(**batch, params=params, dropout_rng=dropout_rng, train=True)[0]
            return compute_loss(logits, labels, z_loss_weight=1.0)

        loss_val, grads = jax.value_and_grad(compute_loss_value)(params)
        updates, new_opt_state = optimizer.update(grads, opt_state, params)
        updated_params = optax.apply_updates(params, updates)

        metrics = {"loss": loss_val, "learning_rate": lr_scheduler(step)}
        return updated_params, tuple(new_opt_state), new_dropout_rng, metrics, step + 1

    # Evaluation step function
    def eval_step(input_ids, labels, params):
        logits = model(input_ids=input_ids, params=params, train=False)[0]
        loss = compute_loss(logits, labels)
        return {"loss": loss}

    # JIT-compiled functions
    p_train_step = pjit(
        train_step,
        in_axis_resources=(param_spec, opt_state_spec, None, None, None),
        out_axis_resources=(param_spec, opt_state_spec, None, None, None),
        donate_argnums=(0, 1),
    )

    p_eval_step = pjit(
        eval_step,
        in_axis_resources=(None, None, param_spec),
        out_axis_resources=None,
    )

    # Training loop
    logger.info("***** Starting training *****")
    logger.info(f"  Examples: {len(train_dataset)}")
    logger.info(f"  Epochs: {num_epochs}")
    logger.info(f"  Batch size per device: {training_args.per_device_train_batch_size}")
    logger.info(f"  Total batch size: {train_batch_size}")
    logger.info(f"  Optimization steps: {total_steps}")

    train_time = 0
    train_metrics = []
    global_step = 0

    with mesh(device_mesh, ("dp", "mp")):
        for epoch in tqdm(range(num_epochs), desc=f"Epoch ... (1/{num_epochs})", position=0):
            train_start = time.time()
            rng, data_rng = jax.random.split(rng)

            train_metrics = []
            train_loader = batch_generator(data_rng, train_dataset, train_batch_size, shuffle=True)

            for _ in tqdm(range(steps_per_epoch), desc="Training...", position=1, leave=False):
                batch = next(train_loader)
                params, opt_state, dropout_rng, metrics, global_step = p_train_step(
                    params, opt_state, dropout_rng, batch, global_step
                )
                train_metrics.append(metrics)

                if global_step % training_args.logging_steps == 0 and global_step > 0:
                    train_time += time.time() - train_start
                    if tensorboard_available and jax.process_index() == 0:
                        log_training_metrics(summary_writer, train_metrics, train_time, global_step)

                    logger.info(
                        f"Step... ({global_step} | Loss: {metrics['loss']}, LR:"
                        f" {metrics['learning_rate']})"
                    )
                    train_metrics = []

                if global_step % training_args.eval_steps == 0 and global_step > 0:
                    eval_metrics = []
                    eval_loader = batch_generator(data_rng, eval_dataset, eval_batch_size)

                    for _ in tqdm(range(len(eval_dataset) // eval_batch_size), desc="Evaluating...", position=2, leave=False):
                        batch = next(eval_loader)
                        metrics = p_eval_step(batch["input_ids"], batch["labels"], params)
                        eval_metrics.append(metrics)

                    eval_metrics = stack_forest(eval_metrics)
                    eval_metrics = jax.tree_util.tree_map(jnp.mean, eval_metrics)

                    try:
                        eval_metrics["perplexity"] = math.exp(eval_metrics["loss"])
                    except OverflowError:
                        eval_metrics["perplexity"] = float("inf")

                    logger.info(
                        f"Step... ({global_step} | Eval loss: {eval_metrics['loss']} | Perplexity:"
                        f" {eval_metrics['perplexity']})"
                    )

                if global_step % training_args.save_steps == 0 and global_step > 0:
                    if jax.process_index() == 0:
                        params_cpu = jax.device_get(params)
                        model.save_pretrained(
                            training_args.output_dir,
                            params=params_cpu,
                            push_to_hub=training_args.push_to_hub,
                            commit_message=f"Saving weights at step {global_step}",
                        )

if __name__ == "__main__":
    main()

# Initialize logging configuration and utilities for weathergen package
import json
import logging
import logging.config
import os
import pathlib
from functools import cache
from weathergen.common.config import _load_private_conf

DEFAULT_LOGGING_CONFIG = """
{
    "version": 1,
    "disable_existing_loggers": false,
    "formatters": {
        "custom": {
            "class": "weathergen.common.logger.ColoredRelPathFormatter",
            "format": \
                "%(asctime)s %(process)d %(filename)s:%(lineno)d : %(levelname)-8s : %(message)s"
        }
    },
    "handlers": {
        "console_out": {
            "class": "logging.StreamHandler",
            "level": "INFO",
            "formatter": "custom",
            "stream": "ext://sys.stdout"
        },
        "console_err": {
            "class": "logging.StreamHandler",
            "level": "ERROR",
            "formatter": "custom",
            "stream": "ext://sys.stderr"
        },
        "debug_log": {
            "class": "logging.FileHandler",
            "level": "DEBUG",
            "formatter": "custom",
            "filename": "debug_output.log",
            "mode": "w"
        },
        "error_log": {
            "class": "logging.FileHandler",
            "level": "ERROR",
            "formatter": "custom",
            "filename": "error_output.log",
            "mode": "w"
        }
    },
    "root": {
        "level": "DEBUG",
        "handlers": [
            "console_err",
            "console_out",
            "debug_log",
            "error_log"
        ]
    }
}
"""

class ColoredRelPathFormatter(logging.Formatter):
    # ANSI color codes for different log levels
    COLOR_MAP = {
        logging.CRITICAL: "\033[1;35m",  # bright/bold magenta
        logging.ERROR:    "\033[1;31m",  # bright/bold red
        logging.WARNING:  "\033[1;33m",  # bright/bold yellow
        logging.INFO:     "\033[0;37m",  # white / light gray
        logging.DEBUG:    "\033[1;30m",  # bright/bold dark gray
    }
    RESET_COLOR = "\033[0m"

    def __init__(self, use_color=True, *args, **kwargs):
        super(ColoredRelPathFormatter, self).__init__(*args, **kwargs)
        self.use_color = use_color
        base_dir = pathlib.Path(__file__).resolve()
        self.base_path = base_dir.parent.parent.parent

    def format(self, record, *args, **kwargs):
        if self.use_color and record.levelno in self.COLOR_MAP:
            record.color_start = self.COLOR_MAP[record.levelno]
            record.color_end = self.RESET_COLOR
        else:
            record.color_start = ""
            record.color_end = ""

        # Convert absolute path to relative path from project root
        record.pathname = os.path.relpath(record.pathname, self.base_path)
        return super(ColoredRelPathFormatter, self).format(record, *args, **kwargs)

@cache
def setup_logging(run_id=None, config_data=None):
    """
    Configure logging system for the application.
    This function uses a singleton pattern and only executes once per process.

    Parameters:
    - run_id: Optional identifier used to create unique log directories/files
    - config_data: Optional custom logging configuration (dict or None to use default)

    Note: If run_id is provided, log files will be placed under ./output/<run_id>/ directory.
          When run_id is not provided, file handlers are removed from configuration.
    """
    # Determine output directory based on run_id
    output_path = ""
    if run_id is not None:
        output_path = f"./output/{run_id}"

    # Load logging configuration
    if config_data is None:
        config_data = json.loads(DEFAULT_LOGGING_CONFIG)
        if run_id is None:
            # Remove file handlers when no run_id is specified
            del config_data["handlers"]["debug_log"]
            del config_data["handlers"]["error_log"]
            del config_data["root"]["handlers"][2:]

    # Process each handler in the configuration
    for name, handler_settings in config_data["handlers"].items():
        for key, value in handler_settings.items():
            if key == "formatter":
                handler_settings[key] = value
            elif key == "filename":
                # Construct full path for log files
                filename = f"{output_path}/{run_id}-{value}" if run_id else value
                log_file = pathlib.Path(filename)

                # Ensure absolute paths are resolved relative to working directory
                if not log_file.is_absolute():
                    work_dir = pathlib.Path(_load_private_conf().get("path_shared_working_dir"))
                    log_file = work_dir / log_file

                # Create parent directories if they don't exist
                pathlib.Path(log_file.parent).mkdir(parents=True, exist_ok=True)
                handler_settings[key] = str(log_file)
            else:
                continue

    # Apply the logging configuration
    logging.config.dictConfig(config_data)

    # Log confirmation message
    if output_path:
        logging.info(f"Logging initialized. Logs stored at {output_path}")
    else:
        logging.info("Logging initialized. No log files created.")

# Type I clone: Renamed variables, changed literals, reordered statements
from __future__ import annotations
import torch
from prettytable import PrettyTable
from typing import TYPE_CHECKING
from collections.abc import Sequence
import isaaclab.sim as sim_utils
import isaaclab.utils.math as math_utils
from isaaclab.assets import Articulation
from isaaclab.managers import ManagerBase, ManagerTermBase
from isaaclab.markers import VisualizationMarkers, VisualizationMarkersCfg
from .animation_manager_cfg import AnimationTermCfg
from .motion_data_manager import MotionDataTerm

if TYPE_CHECKING:
    from robolab.tasks.manager_based.amp.animation_env import AnimationEnv


class AnimationTerm(ManagerTermBase):
    cfg: AnimationTermCfg
    _env: AnimationEnv

    def __init__(self, cfg: AnimationTermCfg, env: AnimationEnv):
        super().__init__(cfg, env)

        # Determine step indices based on configuration
        if cfg.num_steps_to_use > 0:
            self.step_indices = torch.arange(0, cfg.num_steps_to_use, dtype=torch.long, device=env.device)
        elif cfg.num_steps_to_use < 0:
            self.step_indices = torch.arange(cfg.num_steps_to_use + 1, 1, dtype=torch.long, device=env.device)
        else:
            raise ValueError("num_steps_to_use cannot be zero.")

        # Retrieve motion data term
        self.motion_data_term: MotionDataTerm = env.motion_data_manager.get_term(cfg.motion_data_term)

        # Initialize buffers for each component
        self.num_steps = len(self.step_indices)
        for comp in cfg.motion_data_components:
            buffer_shape = (self.num_envs, self.num_steps)
            if comp in ["root_pos_w", "root_vel_w", "root_vel_b", "root_ang_vel_w", "root_ang_vel_b"]:
                buffer_shape += (3,)
            elif comp == "root_quat":
                buffer_shape += (4,)
            elif comp in ["dof_pos", "dof_vel"]:
                num_dofs = self.motion_data_term.num_dofs
                buffer_shape += (num_dofs,)
            elif comp == "key_body_pos_b":
                num_key_bodies = self.motion_data_term.num_key_bodies
                buffer_shape += (num_key_bodies, 3)
            else:
                raise ValueError(f"Unknown motion data component: {comp}")
            setattr(self, f"{comp}_buffer", torch.zeros(buffer_shape, device=env.device, dtype=torch.float32))

        # Motion IDs and timing buffers
        self.motion_ids = torch.zeros(self.num_envs, device=env.device, dtype=torch.long)
        self.motion_fetch_time = torch.zeros((self.num_envs, self.num_steps), device=env.device, dtype=torch.float32)
        self.motion_durations = torch.zeros(self.num_envs, device=env.device, dtype=torch.float32)

        # Initialize state
        self.reset(torch.arange(self.num_envs))
        self._fetch_motion_data()

        # Visualization setup
        if self.cfg.enable_visualization:
            self.vis_root_offset = torch.tensor(self.cfg.vis_root_offset, device=env.device, dtype=torch.float32).unsqueeze(0)  # (1, 3)

            marker_cfg = VisualizationMarkersCfg(
                prim_path="/Visuals/KeyBodyVisualizerFromTerm",
                markers={
                    "red_sphere": sim_utils.SphereCfg(
                        radius=0.03, 
                        visual_material=sim_utils.PreviewSurfaceCfg(diffuse_color=(1.0, 0.0, 0.0))
                    ),
                }
            )
            self.key_body_marker: VisualizationMarkers = VisualizationMarkers(marker_cfg)

    def reset(self, env_ids: Sequence[int] | None = None):
        if env_ids is None:
            return

        # Resample motion IDs for the specified environments
        self.motion_ids[env_ids] = self.motion_data_term.sample_motions(len(env_ids))
        self.motion_durations[env_ids] = self.motion_data_term.get_motion_durations(self.motion_ids[env_ids])

        truncate_time = self.num_steps * self._env.step_dt
        if self.cfg.random_initialize:
            # Random start time
            if self.cfg.num_steps_to_use > 0:
                self.motion_fetch_time[env_ids, 0] = self.motion_data_term.sample_times(self.motion_ids[env_ids], truncate_time_end=truncate_time)
            else:
                self.motion_fetch_time[env_ids, 0] = self.motion_data_term.sample_times(self.motion_ids[env_ids], truncate_time_start=truncate_time)
        else:
            # Start from beginning
            self.motion_fetch_time[env_ids, 0] = 0.0

        if self.num_steps > 1:
            self.motion_fetch_time[env_ids, 1:] = self.motion_fetch_time[env_ids, 0:1] + self.step_indices[1:].float() * self._env.step_dt

        self._fetch_motion_data(env_ids)

    def update(self, dt: float):
        if self.cfg.random_fetch:
            if self.cfg.num_steps_to_use > 0:
                self.motion_fetch_time[:, 0] = self.motion_data_term.sample_times(self.motion_ids, truncate_time_end=self.num_steps * dt)
            else: 
                self.motion_fetch_time[:, 0] = self.motion_data_term.sample_times(self.motion_ids, truncate_time_start=self.num_steps * dt)

            if self.num_steps > 1:
                self.motion_fetch_time[:, 1:] = self.motion_fetch_time[:, 0:1] + self.step_indices[1:].float() * dt

        self._fetch_motion_data()

        # Advance time only when not randomly fetching
        if not self.cfg.random_fetch:
            self.motion_fetch_time += dt

        if self.cfg.enable_visualization:
            self._visualize()

    def _fetch_motion_data(self, env_ids: Sequence[int] | None = None):
        if env_ids is None:
            env_ids = torch.arange(self.num_envs, device=self._env.device)

        # Flatten for batch processing
        num_queries = len(env_ids) * self.num_steps
        motion_times_flat = self.motion_fetch_time[env_ids].reshape(-1)
        motion_ids_flat = self.motion_ids[env_ids].repeat_interleave(self.num_steps)

        # Sanity check
        assert motion_times_flat.shape[0] == num_queries
        assert motion_ids_flat.shape[0] == num_queries

        # Fetch motion data
        motion_data_dict = self.motion_data_term.get_motion_state(
            motion_ids=motion_ids_flat,
            motion_times=motion_times_flat
        )

        # Reshape and store in buffers
        for comp in self.cfg.motion_data_components:
            if comp in motion_data_dict:
                buffer_name = f"{comp}_buffer"
                data = motion_data_dict[comp]
                # Reshape: (num_envs * num_steps, *) -> (num_envs, num_steps, *)
                data_reshaped = data.view(len(env_ids), self.num_steps, *data.shape[1:])
                getattr(self, buffer_name)[env_ids, :, :] = data_reshaped

    def _visualize(self):
        # try to get the 'robot_anim' articulation
        robot_anim: Articulation = self._env.scene["robot_anim"]
        if robot_anim is None:
            print("[WARNING] AnimationTerm visualization: 'robot_anim' not found in the scene.")
            return

        # check if some necessary buffers are available
        if not hasattr(self, "root_pos_w_buffer") or not hasattr(self, "root_quat_buffer") or not hasattr(self, "dof_pos_buffer"):
            print("[WARNING] AnimationTerm visualization: 'root_pos_w_buffer' or 'root_quat_buffer' or 'dof_pos_buffer' not found.")
            return

        root_pos_w = self.root_pos_w_buffer[:, 0, :]  # (num_envs, 3)
        root_quat = self.root_quat_buffer[:, 0, :]    # (num_envs, 4)
        dof_pos = self.dof_pos_buffer[:, 0, :]        # (num_envs, num_dofs)

        root_states = robot_anim.data.default_root_state.clone()
        root_states[:, :3] = root_pos_w + self._env.scene.env_origins[:, :3] + self.vis_root_offset
        root_states[:, 3:7] = root_quat
        root_states[:, 7:10] = 0.0  # zero linear velocity
        root_states[:, 10:13] = 0.0  # zero angular velocity
        robot_anim.write_root_state_to_sim(root_states)

        joint_pos = robot_anim.data.default_joint_pos.clone()
        joint_pos[:, :] = dof_pos
        joint_vel = torch.zeros_like(robot_anim.data.default_joint_vel)
        robot_anim.write_joint_state_to_sim(joint_pos, joint_vel)

        key_body_pos_b = self.key_body_pos_b_buffer[:, 0, :, :]  # (num_envs, num_key_bodies, 3)
        num_key_bodies = key_body_pos_b.shape[1]
        key_body_pos_w = root_states[:, :3].unsqueeze(1) + math_utils.quat_apply(
            root_quat.unsqueeze(1).expand(-1, num_key_bodies, -1),
            key_body_pos_b
        )
        self.key_body_marker.visualize(
            translations=key_body_pos_w.reshape(-1, 3)
        )

    # Helper methods
    def get_root_pos_w(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_pos_w_buffer"):
            raise AttributeError("root_pos_w_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_pos_w_buffer
        return self.root_pos_w_buffer[env_ids, :, :]

    def get_root_quat(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_quat_buffer"):
            raise AttributeError("root_quat_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_quat_buffer
        return self.root_quat_buffer[env_ids, :, :]

    def get_dof_pos(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "dof_pos_buffer"):
            raise AttributeError("dof_pos_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.dof_pos_buffer
        return self.dof_pos_buffer[env_ids, :, :]

    def get_dof_vel(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "dof_vel_buffer"):
            raise AttributeError("dof_vel_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.dof_vel_buffer
        return self.dof_vel_buffer[env_ids, :, :]

    def get_key_body_pos_b(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "key_body_pos_b_buffer"):
            raise AttributeError("key_body_pos_b_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.key_body_pos_b_buffer
        return self.key_body_pos_b_buffer[env_ids, :, :]

    def get_root_vel_w(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_vel_w_buffer"):
            raise AttributeError("root_vel_w_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_vel_w_buffer
        return self.root_vel_w_buffer[env_ids, :, :]

    def get_root_ang_vel_w(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_ang_vel_w_buffer"):
            raise AttributeError("root_ang_vel_w_buffer not found in AnimationTerm.")
        if env_ids is None:
            return self.root_ang_vel_w_buffer
        return self.root_ang_vel_w_buffer[env_ids, :, :]


class AnimationManager(ManagerBase):

    def __init__(self, cfg: object, env: AnimationEnv):
        if cfg is None:
            raise ValueError("AnimationManager configuration is required.")

        self._terms: dict[str, AnimationTerm] = {}
        self._term_cfgs: dict[str, AnimationTermCfg] = {}

        super().__init__(cfg, env)

    def __str__(self) -> str:
        """Returns: A string representation for animation data manager."""
        msg = f"<AnimationManager> contains {len(self._terms)} active terms.\n"

        # create table for term information
        table = PrettyTable()
        table.title = "Animation Manager Terms"
        table.field_names = ["Index", "Term Name", "Motion Data Term", "Num Steps to Use", "Random Init", "Random Fetch"]
        for idx, (term_name, term_cfg) in enumerate(self._term_cfgs.items()):
            table.add_row([
                idx, 
                term_name,
                term_cfg.motion_data_term,
                term_cfg.num_steps_to_use,
                term_cfg.random_initialize,
                term_cfg.random_fetch
            ])
        msg += table.get_string()
        msg += "\n"

        return msg

    def update(self, dt: float):
        """Update all animation terms.
        Args:
            dt: The time step to update the animation terms.
        """
        for term in self._terms.values():
            term.update(dt)

    def reset(self, env_ids: Sequence[int] | None = None) -> dict[str, torch.Tensor]:
        if env_ids is None:
            return {}
        # reset all terms
        for term in self._terms.values():
            term.reset(env_ids)
        return {}

    """
    Properties.
    """
    @property
    def active_terms(self) -> list[str]:
        """Name of active command terms."""
        return list(self._terms.keys())

    def get_term(self, term_name: str) -> AnimationTerm:
        """Get the animation data term by name."""
        if term_name not in self._terms:
            raise KeyError(f"Animation data term '{term_name}' not found.")
        return self._terms[term_name]

    """
    Helper functions.
    """
    def _prepare_terms(self):
        # check if config is dict already
        if isinstance(self.cfg, dict):
            cfg_items = self.cfg.items()
        else:
            cfg_items = self.cfg.__dict__.items()
        # iterate over all the terms
        for term_name, term_cfg in cfg_items:
            # check for non config
            if term_cfg is None:
                continue
            # check for valid config type
            if not isinstance(term_cfg, AnimationTermCfg):
                raise TypeError(
                    f"Configuration for the term '{term_name}' is not of type AnimationTermCfg."
                    f" Received: '{type(term_cfg)}'."
                )
            # create the action term
            term = AnimationTerm(term_cfg, self._env)
            # add class to dict
            self._terms[term_name] = term
            self._term_cfgs[term_name] = term_cfg

import pytest
import torch
from noether.data.pipeline.sample_processors import MomentNormalizationSampleProcessor
from noether.modeling.functional.logscale import to_logscale

@pytest.fixture
def data_normalizer():
    return MomentNormalizationSampleProcessor(item="pressure", mean=[2.0, 3.0], std=[1.0, 2.0])

def test_batch_normalization(data_normalizer):
    input_data = {
        "pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]]),
        "static_field": torch.tensor([[7.0, 8.0], [9.0, 10.0]]),
    }
    processed = data_normalizer(input_data)
    expected_normalized = (input_data["pressure"] - torch.tensor([2.0, 3.0])) / torch.tensor([1.0, 2.0])
    assert torch.allclose(processed["pressure"], expected_normalized)
    assert torch.all(processed["static_field"] == input_data["static_field"])

def test_missing_key_raises_error(data_normalizer):
    incomplete_sample = {"static_field": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}
    with pytest.raises(KeyError):
        data_normalizer(incomplete_sample)

def test_inverse_normalization(data_normalizer):
    original = {
        "pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]]),
        "static_field": torch.tensor([[7.0, 8.0], [9.0, 10.0]]),
    }
    normalized = data_normalizer(original)
    reconstructed = {}
    for field_name, tensor_value in normalized.items():
        restored_key, restored_tensor = data_normalizer.inverse(key=field_name, value=tensor_value)
        assert restored_key == field_name
        reconstructed[field_name] = restored_tensor
    assert torch.equal(reconstructed["pressure"], original["pressure"])
    assert torch.equal(reconstructed["static_field"], original["static_field"])

def test_logscale_processing():
    log_processor = MomentNormalizationSampleProcessor(
        item="pressure",
        logmean=[0.0, 0.0],
        logstd=[1.0, 1.0],
        logscale=True,
    )
    test_input = {"pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}
    log_normalized = log_processor(test_input)
    assert torch.equal(log_normalized["pressure"], to_logscale(test_input["pressure"]))

    denormalized_output = {}
    for field, tensor in log_normalized.items():
        restored_field, restored_tensor = log_processor.inverse(key=field, value=tensor)
        assert restored_field == field
        denormalized_output[field] = restored_tensor
    assert torch.allclose(denormalized_output["pressure"], test_input["pressure"])

def test_inverse_noop_for_unaffected_fields(data_normalizer):
    raw_data = {"static_field": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}
    reconstructed_data = {}
    for field_name, tensor_value in raw_data.items():
        restored_key, restored_tensor = data_normalizer.inverse(key=field_name, value=tensor_value)
        assert restored_key == field_name
        reconstructed_data[field_name] = restored_tensor
    assert torch.equal(reconstructed_data["static_field"], raw_data["static_field"])

# JAX embedding layer with quantization support
from typing import Optional
import jax
from flax import nnx
from tpu_inference.layers.jax import JaxModule
from tpu_inference.layers.jax.quantization import QuantizeMethodBase
from tpu_inference.layers.jax.quantization.configs import QuantizationConfig

class JaxEmbedding(nnx.Embed, JaxModule):
    """Embedding implementation for JAX with optional quantization."""

    def __init__(self,
                 *args,
                 quant_config: Optional[QuantizationConfig] = None,
                 module_name: str = "",
                 **kwargs):
        nnx.Embed.__init__(self, *args, **kwargs)

        # Compatibility alias: HuggingFace models expect 'weight' parameter name
        self.weight = self.embedding
        delattr(self, 'embedding')

        # Set sharding metadata if available
        if hasattr(self.weight, "out_sharding"):
            self.weight.set_metadata('sharding', self.weight.out_sharding)

        self.quantization_method = None

        # Initialize quantization method if config is provided
        if quant_config is not None:
            quant_method = quant_config.get_quant_method(self, prefix=module_name)
            if quant_method is not None:
                self.quantization_method = quant_method
                assert isinstance(quant_method, QuantizeMethodBase)
                quant_method.create_weights_jax(self)

    def __getattr__(self, attr_name: str):
        if attr_name == "embedding":
            # Required by nnx.Embed internal access pattern
            return self.weight

    def __call__(self, input_ids) -> jax.Array:
        if self.quantization_method is None:
            return super().__call__(input_ids)
        return self.quantization_method.apply_jax(self, input_ids)

    def decode(self, hidden_states: jax.Array) -> jax.Array:
        return jax.numpy.dot(hidden_states, self.weight.value.T)

# Modified version with Type I clone transformations (variable renaming, literal changes, reordering)
import time
from collections import defaultdict
from collections.abc import Sequence
from functools import wraps
from typing import Any, Callable, List, Tuple, Union
import jax
import jax.numpy as jnp
import numpy as np
import torch
from jax._src import dtypes
from jax._src import mesh as mesh_lib
from jax._src import xla_bridge as xb
from jax._src.lib import xla_client as xc
from jax._src.numpy.scalar_types import _ScalarMeta
from jax.sharding import Mesh, NamedSharding, PartitionSpec
from torchax.ops.mappings import j2t_dtype, t2j_dtype
from vllm import envs as vllm_envs
from vllm import utils
from tpu_inference import envs
from tpu_inference.logger import init_logger

# Constants with modified names and values
MEM_UNIT = 1024 * 1024 * 1024
HEAD_SIZE_ALIGN_VAL = 128
SECOND_LAST_MINOR_VAL = 8

# Mapping from string aliases to JAX dtypes (reordered and renamed)
_DTYPE_ALIAS_MAP = {
    "fp8": jnp.float8_e4m3fn.dtype,
    "fp8_e4m3": jnp.float8_e4m3fn.dtype,
    "fp8_e5m2": jnp.float8_e5m2.dtype,
    "fp4": jnp.float4_e2m1fn.dtype,
}

def convert_to_jax_dtype(dtype_input: str | jnp.dtype | torch.dtype) -> jnp.dtype:
    """Convert various dtype representations to JAX dtype."""
    if isinstance(dtype_input, (str, type)):
        if isinstance(dtype_input, str) and (mapped_dtype := 
                                             _DTYPE_ALIAS_MAP.get(dtype_input, None)):
            return mapped_dtype
        return jnp.dtype(dtype_input)
    elif isinstance(dtype_input, torch.dtype):
        return t2j_dtype(dtype_input)
    elif isinstance(dtype_input, jnp.dtype):
        return dtype_input
    elif isinstance(dtype_input, _ScalarMeta):
        return dtype_input.dtype
    else:
        raise ValueError(f"Unsupported data type provided: {type(dtype_input)}")

def convert_to_torch_dtype(dtype_input: str | jnp.dtype | torch.dtype) -> torch.dtype:
    # Convert through JAX dtype as intermediate representation
    dtype_jax = convert_to_jax_dtype(dtype_input)
    return j2t_dtype(dtype_jax)

_megacore_enabled = False
logger = init_logger(__name__)

def align_dimension(unpadded_size, alignment_multiple):
    return (unpadded_size + alignment_multiple - 1) // alignment_multiple * alignment_multiple

def activate_megacore() -> None:
    global _megacore_enabled
    _megacore_enabled = True

def is_megacore_active() -> bool:
    return _megacore_enabled

def compute_kv_heads_for_tp(num_kv_heads: int, tp_degree: int) -> int:
    if tp_degree <= num_kv_heads:
        assert num_kv_heads % tp_degree == 0
        return num_kv_heads
    else:
        assert tp_degree % num_kv_heads == 0
        return tp_degree

def get_hbm_usage(devices: Any) -> List[Tuple[int, int]]:
    usage_records = []
    if vllm_envs.VLLM_TPU_USING_PATHWAYS:
        return pathways_memory_stats(devices)

    multihost_backend = envs.TPU_MULTIHOST_BACKEND
    if multihost_backend == "ray":
        for device in devices:
            try:
                memory_info = device.memory_stats()
                used_bytes = memory_info["bytes_in_use"]
                limit_bytes = memory_info["bytes_limit"]
                logger.info(
                    "Retrieved memory stats for device %s. Assuming uniform usage across all devices.",
                    device)
                usage_records.extend([(used_bytes, limit_bytes)] * len(devices))
                break
            except Exception as e:
                logger.warning(
                    "Failed to retrieve memory stats for device %s: %s", device,
                    e)
    else:
        for device in devices:
            memory_info = device.memory_stats()
            used_bytes = memory_info["bytes_in_use"]
            limit_bytes = memory_info["bytes_limit"]
            usage_records.append((used_bytes, limit_bytes))
    return usage_records

def identify_device_type(num_devices: int | None = None):
    kind = jax.devices()[0].device_kind
    if 'TPU' not in kind:
        raise RuntimeError('Expected TPU devices')

    suffix = ''
    if kind.endswith(' lite'):
        kind = kind[:-len(' lite')]
        suffix = 'e'
    elif kind.endswith('e'):
        kind = kind[:-1]
        suffix = 'e'
    elif kind.endswith('p'):
        kind = kind[:-1]
        suffix = 'p'
    elif kind == 'TPU7x':
        kind = 'TPU v7'

    assert kind[:-1] == 'TPU v', kind
    kind += suffix

    if num_devices is not None:
        kind += f'-{num_devices}'
    return kind

def get_hbm_capacity() -> int:
    device_type = identify_device_type()
    if device_type == "TPU v5p" or device_type == "TPU v5":
        return 95 * MEM_UNIT
    elif device_type == "TPU v5e":
        return 16 * MEM_UNIT
    elif device_type == "TPU v6e" or device_type == "TPU v4":
        return 32 * MEM_UNIT
    elif device_type == "TPU v7":
        return 96 * MEM_UNIT
    else:
        raise ValueError(f"Unknown device type: {device_type}")

def pathways_memory_stats(devices: Any) -> List[Tuple[float, float]]:
    live_arrays = jax.live_arrays()
    memory_used = defaultdict(int)
    memory_capacity = get_hbm_capacity()
    seen_buffers = set()

    for array in live_arrays:
        for buffer in array.addressable_shards:
            buffer_id = id(buffer.data)
            if buffer_id not in seen_buffers:
                seen_buffers.add(buffer_id)
                memory_used[buffer.data.device] += buffer.data.nbytes

    return [(memory_used[device], memory_capacity) for device in devices]

def get_hbm_usage_gb(devices: Any) -> List[Tuple[float, float]]:
    raw_usage = get_hbm_usage(devices)
    converted = [(round(used / MEM_UNIT, 2), round(limit / MEM_UNIT, 2))
                 for used, limit in raw_usage]
    return converted

def pad_head_dimension(head_dim: int) -> int:
    """Pad head dimension to nearest multiple of 128 for kernel optimization."""
    if head_dim == 64:
        return 64
    return (head_dim + 127) // 128 * 128

def pad_num_heads(num_heads: int, sharding_dim: int) -> int:
    if num_heads >= sharding_dim:
        assert num_heads % sharding_dim == 0
    else:
        assert sharding_dim % num_heads == 0
        num_heads = sharding_dim
    return num_heads

def compute_packing_factor(dtype):
    bits = dtypes.itemsize_bits(dtype)
    return 32 // bits

def create_optimized_mesh(axis_dims: Sequence[int],
                        axis_labels: Sequence[str],
                        *,
                        devices: Sequence[xc.Device] | None = None):
    if devices is None:
        devices = xb.devices()

    devices = sorted(devices, key=lambda x: x.coords)

    def _is_single_axis(axis_dims):
        return sum(x > 1 for x in axis_dims) == 1

    if _is_single_axis(axis_dims):
        dev_kind = devices[0].device_kind
        device_count = len(devices)
        if dev_kind == "TPU v6 lite":
            ordered_devices = None

            if device_count == 8:
                ordered_devices = np.array([
                    devices[0],
                    devices[1],
                    devices[2],
                    devices[3],
                    devices[7],
                    devices[6],
                    devices[5],
                    devices[4],
                ])
            elif device_count == 4:
                ordered_devices = np.array([
                    devices[0],
                    devices[1],
                    devices[3],
                    devices[2],
                ])

            if ordered_devices is not None:
                ordered_devices = np.array(ordered_devices)
                ordered_devices = ordered_devices.reshape(axis_dims)
                mesh = mesh_lib.Mesh(ordered_devices, axis_labels)
                logger.info("Using custom mesh configuration: %s", mesh)
                return mesh

    try:
        return jax.make_mesh(axis_dims, axis_labels, devices=devices)
    except (AssertionError, ValueError, RuntimeError) as e:
        logger.warning(
            "jax.make_mesh failed due to topology constraints. Falling back to manual mesh: %s",
            e)
        ordered_devices = np.array(devices).reshape(axis_dims)
        return mesh_lib.Mesh(ordered_devices, axis_labels)

def create_device_array(mesh: Mesh, *args, sharding=None, **kwargs) -> jax.Array:
    """
    Create a device array with the specified mesh and sharding.
    """
    if sharding is None:
        sharding = NamedSharding(mesh, PartitionSpec(None))
    return jax.device_put(*args, device=sharding, **kwargs)

def resolve_hash_function(hash_name: str) -> Callable[[Any], bytes]:
    """
    Wrapper for vllm.utils.hashing.get_hash_fn_by_name with builtin support.
    """
    if hash_name == "builtin":
        return hash
    return utils.hashing.get_hash_fn_by_name(hash_name)

def extract_jax_dtype_from_string(str_dtype: str) -> jnp.dtype:
    """
    Get the JAX dtype from a string dtype.
    """
    return convert_to_jax_dtype(str_dtype)

def compute_mesh_product(
    mesh: Mesh,
    axes: Union[str, list[str], None],
) -> int:
    """
    Compute the product of mesh dimensions for one or more axes.
    """
    if axes is None:
        return 1
    if isinstance(axes, str):
        axes = [axes]
    product = 1
    for axis in axes:
        product *= mesh.shape.get(axis, 1)
    return product

def timed_execution(func):
    """
    Decorator to measure function execution time.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.perf_counter()
        result = func(*args, **kwargs)
        end_time = time.perf_counter()
        duration = end_time - start_time
        logger.debug(
            f"Function '{func.__name__}' completed in {duration:.4f} seconds."
        )
        return result
    return wrapper

import asyncio
from typing import Optional
import click
from storage.service import chat as chat_service
from storage.service.user import get_cli_user_id
from yagent.config import config

@click.command()
@click.option('--chat-id', '-c', help='Identifier of the chat to share')
@click.option('--latest', '-l', is_flag=True, help='Share the most recent chat')
@click.option('--message-id', '-m', help='Share up to a particular message ID')
@click.option('--publish', '-p', is_flag=True, help='Generate HTML and upload to S3 (legacy)')
def share(chat_id: Optional[str], latest: bool, message_id: Optional[str], publish: bool):
    """Share a chat conversation.
    Use --latest/-l to distribute your newest chat.
    Use --chat-id/-c to distribute a particular chat ID.
    Use --publish/-p to produce HTML and upload to S3 (legacy behavior).
    """
    user_id = get_cli_user_id()

    # Process --latest flag
    if latest:
        chats = asyncio.run(chat_service.list_chats(user_id, limit=1))
        if not chats:
            click.echo("Error: No chats available for sharing")
            raise click.Abort()
        chat_id = chats[0].chat_id
    elif not chat_id:
        raise click.Abort("Error: Chat ID is necessary for sharing")

    try:
        if publish:
            # Legacy: generate HTML and upload to S3
            tmp_file = asyncio.run(chat_service.generate_share_html(chat_id))
            if not config["s3_bucket"] or not config["cloudfront_distribution_id"]:
                click.echo("Error: S3 bucket and CloudFront distribution ID must be configured")
                click.echo("Please set S3_BUCKET and CLOUDFRONT_DISTRIBUTION_ID environment variables")
                raise click.Abort()
            os.system(f'open "{tmp_file}"')
            os.system(f'aws s3 cp "{tmp_file}" s3://{config["s3_bucket"]}/chat/{chat_id}.html > /dev/null')
            os.system(f'aws cloudfront create-invalidation --distribution-id {config["cloudfront_distribution_id"]} --paths "/chat/{chat_id}.html" > /dev/null')
            click.echo(f'https://{config["s3_bucket"]}/chat/{chat_id}.html')
        else:
            # Default: create DB share
            share_id = asyncio.run(chat_service.create_share(user_id, chat_id, message_id))
            click.echo(share_id)
    except ValueError as e:
        click.echo(f"Error: {str(e)}")
        raise click.Abort()

