# Analyze agent project structures and extract metadata
from __future__ import annotations
import json
import os
import sys
from collections import defaultdict

def inspect_agent_layout(agent_path):
    """Inspect the layout of an agent directory."""
    output = {"modules": [], "dependencies": defaultdict(list), "types": [], "methods": []}
    for dirpath, _, filenames in os.walk(agent_path):
        for filename in filenames:
            if filename.endswith(".py"):
                full_path = os.path.join(dirpath, filename)
                relative = os.path.relpath(full_path, agent_path)
                output["modules"].append(relative)
                # Basic parsing to gather dependencies, types, and methods
                with open(full_path, encoding="utf-8", errors="ignore") as file_obj:
                    text = file_obj.read()
                    # Collect dependency lines
                    for line in text.split("\n"):
                        stripped = line.strip()
                        if stripped.startswith(("import ", "from ")):
                            tokens = line.split()
                            if len(tokens) > 1:
                                tokens[1]
                                output["dependencies"][relative].append(stripped)
                    # rudimentary type/class detection
                    for line in text.split("\n"):
                        stripped = line.strip()
                        if stripped.startswith("class "):
                            class_part = stripped.split("class ")[1].split("(")[0].strip()
                            output["types"].append(f"{relative}: {class_part}")
                    # basic method detection (top-level only)
                    for line in text.split("\n"):
                        stripped = line.strip()
                        if stripped.startswith("def ") and not stripped.startswith("    def"):
                            func_part = stripped.split("def ")[1].split("(")[0].strip()
                            output["methods"].append(f"{relative}: {func_part}")
    return output

def inspect_all_agents(root_dir):
    """Inspect all agents in the specified root directory."""
    summaries = {}
    # Identify all possible agent folders
    for entry in os.listdir(root_dir):
        entry_full = os.path.join(root_dir, entry)
        if os.path.isdir(entry_full):
            # Look for typical agent files like agent.py, config.py, etc.
            key_files = ["agent.py", "config.py", "state.py"]
            if any(
                os.path.isfile(os.path.join(entry_full, marker))
                for marker in key_files
            ):
                summaries[entry] = inspect_agent_layout(entry_full)
    return summaries

def discover_shared_patterns(summaries):
    """Discover shared patterns among different agents."""
    shared_modules = set()
    initial = True
    for _name, info in summaries.items():
        if initial:
            shared_modules = set(info["modules"])
            initial = False
        else:
            shared_modules = shared_modules.intersection(set(info["modules"]))
    return {
        "shared_modules": sorted(shared_modules),
        "module_counts": count_module_occurrences(summaries),
    }

def count_module_occurrences(summaries):
    """Determine how frequently each module appears across agents."""
    counts = defaultdict(int)
    for _name, info in summaries.items():
        for module in info["modules"]:
            counts[module] += 1
    return dict(sorted(counts.items(), key=lambda pair: pair[1], reverse=True))

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(1)
    agents_folder = sys.argv[1]
    if not os.path.isdir(agents_folder):
        sys.exit(1)
    analysis = inspect_all_agents(agents_folder)
    # Display shared patterns
    shared_info = discover_shared_patterns(analysis)
    for module_name in shared_info["shared_modules"]:
        pass
    for module_name, occurrences in list(shared_info["module_counts"].items())[:10]:
        pass
    # Save comprehensive results to JSON
    with open("agent_inspection.json", "w") as output_file:
        json.dump(analysis, output_file, indent=2)

# Boosta API client utility for job submission, status checking, listing, and usage
import argparse
import json
import os
import sys
import time
import urllib.error
import urllib.request

API_BASE = "https://boosta.pro/api/v1"

class BoostaClient:
    def __init__(self, api_token, timeout=60):
        self.api_token = api_token
        self.timeout = timeout

    def _send_request(self, http_method, endpoint, data=None):
        payload_body = None
        request_headers = {"Authorization": f"Bearer {self.api_token}"}

        if data is not None:
            payload_body = json.dumps(data).encode("utf-8")
            request_headers["Content-Type"] = "application/json"

        full_url = f"{API_BASE}{endpoint}"
        request = urllib.request.Request(
            url=full_url,
            data=payload_body,
            headers=request_headers,
            method=http_method,
        )

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                response_text = response.read().decode("utf-8")
                return response.getcode(), _parse_json_safely(response_text)
        except urllib.error.HTTPError as error:
            error_body = error.read().decode("utf-8") if error.fp else ""
            return error.code, _parse_json_safely(error_body)
        except urllib.error.URLError as error:
            return 0, {"error": f"network_issue: {error}"}

    def create_job(self, video_source, video_category, config_label=None):
        job_data = {"video_url": video_source, "video_type": video_category}
        if config_label:
            job_data["config_name"] = config_label
        return self._send_request("POST", "/jobs", job_data)

    def check_job(self, job_identifier):
        return self._send_request("GET", f"/jobs/{job_identifier}")

    def retrieve_jobs(self):
        return self._send_request("GET", "/jobs")

    def account_usage(self):
        return self._send_request("GET", "/usage")

def _parse_json_safely(raw_response):
    if not raw_response:
        return {}
    try:
        return json.loads(raw_response)
    except json.JSONDecodeError:
        return {"raw_content": raw_response}

def _fetch_api_token():
    token = os.getenv("BOOSTA_API_KEY")
    if not token:
        print(
            "Environment variable BOOSTA_API_KEY is missing.",
            file=sys.stderr,
        )
        sys.exit(2)
    return token

def _display_output(status_code, response_data):
    output = {"status_code": status_code, "payload": response_data}
    print(json.dumps(output, indent=2, ensure_ascii=True))

def _wait_for_completion(client, job_id, delay, max_duration):
    end_time = time.time() + max_duration if max_duration > 0 else None
    while True:
        status_code, response = client.check_job(job_id)

        if status_code >= 400:
            if status_code == 429:
                wait_seconds = int(response.get("retry_after", 60))
                print(
                    json.dumps(
                        {
                            "message": "rate_limited_during_poll",
                            "retry_after": wait_seconds,
                            "job_id": job_id,
                        },
                        ensure_ascii=True,
                    )
                )
                time.sleep(wait_seconds)
                continue
            return status_code, response

        current_status = response.get("status")
        if current_status in {"completed", "failed"}:
            return status_code, response

        print(
            json.dumps(
                {
                    "job_id": job_id,
                    "status": current_status,
                    "progress": response.get("progress"),
                    "step": response.get("step"),
                },
                ensure_ascii=True,
            )
        )

        if end_time is not None and time.time() >= end_time:
            return 408, {"error": "poll_timeout_exceeded", "job_id": job_id}

        time.sleep(delay)

def handle_submit(args):
    client = BoostaClient(_fetch_api_token(), timeout=args.timeout)
    status_code, response = client.create_job(
        video_source=args.video_url,
        video_category=args.video_type,
        config_label=args.config_name,
    )

    if status_code >= 400 and response.get("status") == "active_job_exists":
        existing_job_id = response.get("job_id")
        if args.wait and existing_job_id:
            print(
                json.dumps(
                    {"info": "existing_active_job", "job_id": existing_job_id},
                    ensure_ascii=True,
                )
            )
            poll_status, poll_response = _wait_for_completion(
                client, existing_job_id, args.poll_interval, args.max_wait
            )
            _display_output(poll_status, poll_response)
            return 0 if poll_status < 400 else 1
        _display_output(status_code, response)
        return 1

    if status_code >= 400:
        _display_output(status_code, response)
        return 1

    if not args.wait:
        _display_output(status_code, response)
        return 0

    job_id = response.get("job_id")
    if not job_id:
        _display_output(500, {"error": "no_job_id_in_response", "raw_data": response})
        return 1

    final_status, final_response = _wait_for_completion(
        client, job_id, args.poll_interval, args.max_wait
    )
    _display_output(final_status, final_response)
    return 0 if final_status < 400 else 1

def handle_status(args):
    client = BoostaClient(_fetch_api_token(), timeout=args.timeout)
    status_code, response = client.check_job(args.job_id)
    _display_output(status_code, response)
    return 0 if status_code < 400 else 1

def handle_list(args):
    client = BoostaClient(_fetch_api_token(), timeout=args.timeout)
    status_code, response = client.retrieve_jobs()
    _display_output(status_code, response)
    return 0 if status_code < 400 else 1

def handle_usage(args):
    client = BoostaClient(_fetch_api_token(), timeout=args.timeout)
    status_code, response = client.account_usage()
    _display_output(status_code, response)
    return 0 if status_code < 400 else 1

def setup_argument_parser():
    parser = argparse.ArgumentParser(
        description="Boosta API command-line tool for job management."
    )
    subparsers = parser.add_subparsers(dest="action", required=True)

    submit_parser = subparsers.add_parser("submit", help="Submit a new processing job.")
    submit_parser.add_argument("--video-url", required=True, help="URL of the source video.")
    submit_parser.add_argument(
        "--video-type",
        required=True,
        choices=["conversation", "gaming", "faceless", "solo", "vlog", "movies"],
        help="Type of video content.",
    )
    submit_parser.add_argument("--config-name", help="Optional configuration preset name.")
    submit_parser.add_argument(
        "--wait",
        action="store_true",
        help="Wait until job completes or fails.",
    )
    submit_parser.add_argument(
        "--poll-interval",
        type=int,
        default=15,
        help="Seconds between status checks when waiting.",
    )
    submit_parser.add_argument(
        "--max-wait",
        type=int,
        default=1800,
        help="Maximum seconds to wait (0 means no limit).",
    )
    submit_parser.add_argument("--timeout", type=int, default=60, help="HTTP request timeout in seconds.")
    submit_parser.set_defaults(func=handle_submit)

    status_parser = subparsers.add_parser("status", help="Check job status.")
    status_parser.add_argument("--job-id", required=True, help="Job identifier.")
    status_parser.add_argument("--timeout", type=int, default=60, help="HTTP request timeout in seconds.")
    status_parser.set_defaults(func=handle_status)

    list_parser = subparsers.add_parser("list", help="List all jobs.")
    list_parser.add_argument("--timeout", type=int, default=60, help="HTTP request timeout in seconds.")
    list_parser.set_defaults(func=handle_list)

    usage_parser = subparsers.add_parser("usage", help="View account usage and credits.")
    usage_parser.add_argument("--timeout", type=int, default=60, help="HTTP request timeout in seconds.")
    usage_parser.set_defaults(func=handle_usage)

    return parser

def main():
    parser = setup_argument_parser()
    arguments = parser.parse_args()
    return arguments.func(arguments)

if __name__ == "__main__":
    raise SystemExit(main())

# Test filtering of ranked search embeddings
from uuid import uuid4
import pytest
from common.services.lazybytes_service import LazyBytes
from worker.ai.tasks.rag import RankedSearchEmbedding, filter_ranked_search_embeddings

@pytest.mark.parametrize(
    "clusters,",
    [
        ([2.0, 2.0, 2.0], [4.0, 4.0], [6.0, 6.0, 6.0]),
        ([1.5, 1.5, 1.5, 1.5, 1.5], [5.5]),
        ([3.0, 3.0, 3.0, 3.0, 3.0],),
        (
            [
                7.0,
            ],
        ),
    ],
)
def test_filter_ranked_file_text(clusters: list[list[float]]):
    def create_ranked_embedding(rank_value: float):
        return RankedSearchEmbedding(
            file_id=uuid4(),
            file_score=2,
            text_score=2,
            text_lazy=LazyBytes(embedded_data=b"test"),
            rank=rank_value,
        )

    all_ranked_embeddings: list[RankedSearchEmbedding] = []
    for group in clusters:
        current_group_embeddings: list[RankedSearchEmbedding] = []
        for rank_val in group:
            embedding = create_ranked_embedding(rank_val)
            all_ranked_embeddings.append(embedding)
            current_group_embeddings.append(embedding)

    # Test with different input orderings
    for _ in range(len(all_ranked_embeddings)):
        from random import shuffle
        shuffled_list = all_ranked_embeddings.copy()
        shuffle(shuffled_list)
        result_ranks = filter_ranked_search_embeddings(shuffled_list)
        assert len(result_ranks) == len(current_group_embeddings)
        for item in current_group_embeddings:
            assert item in result_ranks

# Manage request context using ContextVar
from contextvars import ContextVar
from contextlib import contextmanager

REQUEST_CONTEXT = ContextVar("request_context", default=None)

def fetch_request_context(key, fallback=None):
    ctx = REQUEST_CONTEXT.get()
    return ctx[key] if ctx and key in ctx else fallback

def modify_request_context(**kwargs):
    ctx = REQUEST_CONTEXT.get()
    if ctx is not None:
        ctx.update(kwargs)

@contextmanager
def establish_request_context(data):
    token = REQUEST_CONTEXT.set(data)
    try:
        yield
    finally:
        REQUEST_CONTEXT.reset(token)

