def _sync_check_counts_with_available_file() -> None:
    """Lazy import and call sync function from main.py to avoid circular imports."""
    try:
        # Lazy import to avoid circular dependency
        from .main import _sync_check_counts_with_available_file as sync_func
        sync_func()
    except (ImportError, AttributeError):
        # Silently fail if import is not available (e.g., during circular import)
        pass

def _has_connectivity() -> bool:
    """Best-effort Internet connectivity check using IP-only probes to avoid DNS dependency."""
    try:
        probes = [('1.1.1.1', 443), ('8.8.8.8', 53)]
        for ip, port in probes:
            try:
                if ping_host(ip):
                    return True
            except Exception:
                pass
            try:
                if connect_host_port(ip, port):
                    return True
            except Exception:
                pass
    except Exception:
        return False
    return False

def main() -> int:
    ensure_dirs()

    # Pre-flight connectivity check to avoid destructive actions during outages
    if not _has_connectivity():
        log("No Internet connectivity detected; skipping network operations and leaving existing outputs unchanged.")
        return 2

    # Load streaks persistence
    streaks: Dict[str, Dict[str, int]] = load_streaks()

    # Re-validate current available proxies to drop broken ones
    host_success_run: Dict[str, bool] = {}
    alive: List[str] = []
    deduplicated_alive: List[str] = []
    host_map_existing: Dict[str, Optional[str]] = {}

    if os.path.exists(AVAILABLE_FILE):
        existing_lines = [ln.strip() for ln in read_lines(AVAILABLE_FILE) if ln.strip()]
        if existing_lines:
            from .parsing import extract_host as _extract_host_for_existing

            # Deduplicate existing proxies using V2RayN-style connection-based uniqueness
            seen_connection_keys = set()
            deduplicated_existing = []
            for u in existing_lines:
                conn_key = get_v2rayn_connection_key(u)
                if conn_key not in seen_connection_keys:
                    seen_connection_keys.add(conn_key)
                    deduplicated_existing.append(u)

            log(f"Deduplicated existing proxies: {len(deduplicated_existing)} unique out of {len(existing_lines)} total")
            existing_lines = deduplicated_existing
            host_map_existing = {u: _extract_host_for_existing(u) for u in existing_lines}
            items = [(u, h) for u, h in host_map_existing.items() if h]

            # initialize to False for tested hosts
            for _, h in items:
                if h not in host_success_run:
                    host_success_run[h] = False

            def check_existing(item: Tuple[str, str]) -> Optional[str]:
                u, h = item
                try:
                    if not ping_host(h):
                        return None
                    scheme = u.split('://', 1)[0].lower()
                    if scheme in ('vmess', 'vless', 'trojan', 'ss', 'ssr', 'hysteria', 'hysteria2', 'hy2', 'tuic', 'juicity', 'wireguard'):
                        p = extract_port(u)
                        if p is not None:
                            ok = connect_host_port(h, int(p))
                            if not ok:
                                return None
                            if int(ENABLE_STAGE2) == 1:
                                return u if quick_protocol_probe(u, h, int(p)) else None
                            return u
                    return u
                except Exception:
                    return None

            # Keep all existing proxies without Stage 2 revalidation
            for u in existing_lines:
                alive.append(u)
                h = host_map_existing.get(u)
                if h:
                    host_success_run[h] = True

            # Optional Stage 3: validate a subset of revalidated existing proxies with V2Ray core (if configured)
            if int(ENABLE_STAGE3) == 1 and alive:
                core_path = ''
                try:
                    from .constants import V2RAY_CORE_PATH  # local import to avoid circulars in some contexts
                    core_path = (V2RAY_CORE_PATH or '').strip()
                except Exception:
                    core_path = ''
                if not core_path:
                    log("Stage 3 enabled, but V2Ray/Xray core not found or OPENRAY_V2RAY_CORE is not set; skipping core validation for existing proxies.")
                else:
                    subset = alive # [:int(STAGE3_MAX)]
                    kept_subset: List[str] = []

                    def _core_check(u: str) -> Tuple[str, bool]:
                        try:
                            res = validate_with_v2ray_core(u, timeout_s=12)
                        except Exception:
                            return u, False
                        return u, (res is True)

                    workers = int(STAGE3_WORKERS)
                    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool2:
                        print("Start Stage 3 for existing proxies")
                        for u, success in progress(pool2.map(_core_check, subset), total=len(subset)):
                            h = host_map_existing.get(u)
                            if success:
                                kept_subset.append(u)
                                if h:
                                    if h not in streaks:
                                        streaks[h] = {'streak': 0, 'last_test': 0, 'last_success': 0, 'failure_count': 0}
                                    streaks[h]['failure_count'] = 0
                            else:
                                if h:
                                    if h not in streaks:
                                        streaks[h] = {'streak': 0, 'last_test': 0, 'last_success': 0, 'failure_count': 0}

                                    curr_fails = streaks[h].get('failure_count', 0)
                                    streaks[h]['failure_count'] = curr_fails + 1

                                    if streaks[h]['failure_count'] < int(EXISTING_PROXY_FAILURE_LIMIT):
                                        kept_subset.append(u)
                                    else:
                                        log(f"Proxy {h} reached failure limit ({EXISTING_PROXY_FAILURE_LIMIT}). Removing it.")

                    # Save updated streaks after revalidation
                    save_streaks(streaks)
                    # Merge: replace subset portion with validated ones
                    alive = kept_subset + alive[len(subset):]

            # Deduplicate alive proxies using V2RayN-style connection-based uniqueness
            seen_keys: Set[str] = set()
            deduplicated_alive = []
            for u in alive:
                conn_key = get_v2rayn_connection_key(u)
                if conn_key not in seen_keys:
                    seen_keys.add(conn_key)
                    deduplicated_alive.append(u)

            if len(deduplicated_alive) != len(existing_lines):
                # Outage-safe guard: avoid purging available file if connectivity appears down
                if len(existing_lines) > 0 and len(deduplicated_alive) == 0 and not _has_connectivity():
                    log("Suspected Internet outage during revalidation; keeping existing available proxies file unchanged.")
                else:
                    tmp_path = AVAILABLE_FILE + '.tmp'
                    with open(tmp_path, 'w', encoding='utf-8', errors='ignore') as f:
                        for u in deduplicated_alive:
                            f.write(u)
                            f.write('\n')
                    os.replace(tmp_path, AVAILABLE_FILE)
                    log(f"Revalidated existing available proxies: kept {len(deduplicated_alive)} of {len(existing_lines)} (deduplicated from {len(alive)})")
                    _sync_check_counts_with_available_file()
            else:
                log("Revalidated existing available proxies: all still reachable")
    else:
        log(f"No existing proxies file found: {AVAILABLE_FILE}")
        return 0

    # Update streaks for hosts that were successfully tested
    for host, success in host_success_run.items():
        if host not in streaks:
            streaks[host] = {}
        if success:
            streaks[host]['consecutive'] = streaks[host].get('consecutive', 0) + 1
            streaks[host]['last_success'] = int(time.time())
        else:
            streaks[host]['consecutive'] = 0

    save_streaks(streaks)

    # Group and write outputs
    if deduplicated_alive:
        # Write grouped outputs (this will read from AVAILABLE_FILE which we just updated)
        write_grouped_outputs()

        log(f"Successfully processed {len(deduplicated_alive)} existing proxies")
    else:
        log("No existing proxies found to process")

    return 0

if __name__ == '__main__':
    raise SystemExit(main())

import base64
from datetime import datetime, timezone
import json
import os
import secrets
import shutil
import subprocess
import sys
from pathlib import Path

def _qrencode_installation_guide() -> str:
    if sys.platform == "darwin":
        return "brew install qrencode"
    if shutil.which("apt-get"):
        return "sudo apt-get install -y qrencode"
    if shutil.which("dnf"):
        return "sudo dnf install -y qrencode"
    if shutil.which("pacman"):
        return "sudo pacman -S --needed qrencode"
    return "install qrencode using your system package manager"

def _generate_base32_secret(byte_count: int = 20) -> str:
    return base64.b32encode(secrets.token_bytes(byte_count)).decode("ascii").rstrip("=")

def _parse_base32_input(encoded: str) -> bytes:
    cleaned = encoded.strip().replace(" ", "")
    padding_needed = "=" * ((8 - len(cleaned) % 8) % 8)
    return base64.b32decode(cleaned.upper() + padding_needed, casefold=True)

def main() -> int:
    config_dir = Path.home() / ".passwordstore-broker"
    secret_path = config_dir / "totp.secret"
    qr_image_file = config_dir / "totp-enroll.png"
    timestamp_file = config_dir / "setup_completed_at.txt"

    config_dir.mkdir(mode=0o700, parents=True, exist_ok=True)
    try:
        os.chmod(config_dir, 0o700)
    except OSError:
        pass

    newly_provisioned = False
    if secret_path.exists():
        secret = secret_path.read_text(encoding="utf-8").strip().replace(" ", "")
        if not secret:
            print(f"TOTP secret file is empty: {secret_path}", file=sys.stderr)
            return 2
    else:
        secret = _generate_base32_secret()
        secret_path.write_text(secret + "\n", encoding="utf-8")
        newly_provisioned = True

    try:
        _parse_base32_input(secret)
    except Exception:  # noqa: BLE001
        print(f"Invalid base32 value in TOTP secret file: {secret_path}", file=sys.stderr)
        return 2

    try:
        os.chmod(secret_path, 0o600)
    except OSError:
        pass

    if timestamp_file.exists():
        setup_time = timestamp_file.read_text(encoding="utf-8").strip()
    else:
        setup_time = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
        timestamp_file.write_text(setup_time + "\n", encoding="utf-8")

    try:
        os.chmod(timestamp_file, 0o600)
    except OSError:
        pass

    otp_url = (
        "otpauth://totp/Passwordstore%20Broker"
        f"?secret={secret}&issuer=PasswordstoreBroker&algorithm=SHA1&digits=6&period=30"
    )

    output_data = {
        "secret_file": str(secret_path),
        "otpauth_url": otp_url,
        "qr_png_path": str(qr_image_file),
        "setup_timestamp_file": str(timestamp_file),
        "setup_completed_at": setup_time,
        "provisioned": newly_provisioned,
    }

    qrencode_cmd = shutil.which("qrencode")
    if qrencode_cmd is None:
        print(json.dumps(output_data), flush=True)
        print(f"Missing required command: qrencode. Install with: {_qrencode_installation_guide()}", file=sys.stderr)
        print(f"Manual enrollment URL: {otp_url}", file=sys.stderr)
        return 2

    try:
        subprocess.run(
            [qrencode_cmd, "-o", str(qr_image_file), "-t", "PNG", otp_url],
            check=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.PIPE,
            text=True,
        )
    except subprocess.CalledProcessError as err:
        print(json.dumps(output_data), flush=True)
        error_msg = err.stderr.strip() or "qrencode failed"
        print(f"Failed to generate QR PNG: {error_msg}", file=sys.stderr)
        print(f"Manual enrollment URL: {otp_url}", file=sys.stderr)
        return 2

    try:
        os.chmod(qr_image_file, 0o600)
    except OSError:
        pass

    print(json.dumps(output_data), flush=True)
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

# Modified version of the original code with renamed variables and structures
from collections import namedtuple
import datetime
import sys
import struct

# Check Python version
IS_PY2 = sys.version_info[0] == 2

if IS_PY2:
    integer_types = (int, long)
    _timezone_utc = None
else:
    integer_types = int
    try:
        _timezone_utc = datetime.timezone.utc
    except AttributeError:
        _timezone_utc = datetime.timezone(datetime.timedelta(0))

class ExtensionType(namedtuple("ExtensionType", "identifier payload")):
    """ExtensionType represents ext type in msgpack."""
    def __new__(cls, identifier, payload):
        if not isinstance(identifier, int):
            raise TypeError("identifier must be int")
        if not isinstance(payload, bytes):
            raise TypeError("payload must be bytes")
        if not 0 <= identifier <= 127:
            raise ValueError("identifier must be 0~127")
        return super(ExtensionType, cls).__new__(cls, identifier, payload)

class TimeStamp(object):
    """TimeStamp represents the Timestamp extension type in msgpack.
    When built with Cython, msgpack uses C methods to pack and unpack `TimeStamp`. When using pure-Python
    msgpack, :func:`to_bytes` and :func:`from_bytes` are used to pack and unpack `TimeStamp`.
    This class is immutable: Do not override seconds and nanoseconds.
    """
    __slots__ = ["seconds", "nanoseconds"]

    def __init__(self, seconds, nanoseconds=0):
        """Initialize a TimeStamp object.
        :param int seconds:
            Number of seconds since the UNIX epoch (00:00:00 UTC Jan 1 1970, minus leap seconds).
            May be negative.
        :param int nanoseconds:
            Number of nanoseconds to add to `seconds` to get fractional time.
            Maximum is 999_999_999.  Default is 0.
        Note: Negative times (before the UNIX epoch) are represented as negative seconds + positive ns.
        """
        if not isinstance(seconds, integer_types):
            raise TypeError("seconds must be an integer")
        if not isinstance(nanoseconds, integer_types):
            raise TypeError("nanoseconds must be an integer")
        if not (0 <= nanoseconds < 10**9):
            raise ValueError(
                "nanoseconds must be a non-negative integer less than 999999999."
            )
        self.seconds = seconds
        self.nanoseconds = nanoseconds

    def __repr__(self):
        """String representation of TimeStamp."""
        return "TimeStamp(seconds={0}, nanoseconds={1})".format(
            self.seconds, self.nanoseconds
        )

    def __eq__(self, other):
        """Check for equality with another TimeStamp object"""
        if type(other) is self.__class__:
            return (
                self.seconds == other.seconds and self.nanoseconds == other.nanoseconds
            )
        return False

    def __ne__(self, other):
        """not-equals method (see :func:`__eq__()`)"""
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self.seconds, self.nanoseconds))

    @staticmethod
    def from_bytes(b):
        """Unpack bytes into a `TimeStamp` object.
        Used for pure-Python msgpack unpacking.
        :param b: Payload from msgpack ext message with code -1
        :type b: bytes
        :returns: TimeStamp object unpacked from msgpack ext payload
        :rtype: TimeStamp
        """
        if len(b) == 4:
            seconds = struct.unpack("!L", b)[0]
            nanoseconds = 0
        elif len(b) == 8:
            data64 = struct.unpack("!Q", b)[0]
            seconds = data64 & 0x00000003FFFFFFFF
            nanoseconds = data64 >> 34
        elif len(b) == 12:
            nanoseconds, seconds = struct.unpack("!Iq", b)
        else:
            raise ValueError(
                "TimeStamp type can only be created from 32, 64, or 96-bit byte objects"
            )
        return TimeStamp(seconds, nanoseconds)

    def to_bytes(self):
        """Pack this TimeStamp object into bytes.
        Used for pure-Python msgpack packing.
        :returns data: Payload for EXT message with code -1 (timestamp type)
        :rtype: bytes
        """
        if (self.seconds >> 34) == 0:  # seconds is non-negative and fits in 34 bits
            data64 = self.nanoseconds << 34 | self.seconds
            if data64 & 0xFFFFFFFF00000000 == 0:
                # nanoseconds is zero and seconds < 2**32, so timestamp 32
                data = struct.pack("!L", data64)
            else:
                # timestamp 64
                data = struct.pack("!Q", data64)
        else:
            # timestamp 96
            data = struct.pack("!Iq", self.nanoseconds, self.seconds)
        return data

    @staticmethod
    def from_unix(unix_sec):
        """Create a TimeStamp from posix timestamp in seconds.
        :param unix_float: Posix timestamp in seconds.
        :type unix_float: int or float.
        """
        seconds = int(unix_sec // 1)
        nanoseconds = int((unix_sec % 1) * 10**9)
        return TimeStamp(seconds, nanoseconds)

    def to_unix(self):
        """Get the timestamp as a floating-point value.
        :returns: posix timestamp
        :rtype: float
        """
        return self.seconds + self.nanoseconds / 1e9

    @staticmethod
    def from_unix_nano(unix_ns):
        """Create a TimeStamp from posix timestamp in nanoseconds.
        :param int unix_ns: Posix timestamp in nanoseconds.
        :rtype: TimeStamp
        """
        return TimeStamp(*divmod(unix_ns, 10**9))

    def to_unix_nano(self):
        """Get the timestamp as a unixtime in nanoseconds.
        :returns: posix timestamp in nanoseconds
        :rtype: int
        """
        return self.seconds * 10**9 + self.nanoseconds

    def to_datetime(self):
        """Get the timestamp as a UTC datetime.
        Python 2 is not supported.
        :rtype: datetime.
        """
        return datetime.datetime.fromtimestamp(0, _timezone_utc) + datetime.timedelta(
            seconds=self.to_unix()
        )

    @staticmethod
    def from_datetime(dt):
        """Create a TimeStamp from datetime with tzinfo.
        Python 2 is not supported.
        :rtype: TimeStamp
        """
        return TimeStamp.from_unix(dt.timestamp())

