def add_cuda_sync(func, target_device):
    """Wrap function to include CUDA synchronization if needed."""
    def inner(*args, **kwargs):
        output = func(*args, **kwargs)
        if target_device == "cuda":
            torch.cuda.synchronize()
        return output
    return inner

