# Layer-wise distributed optimizer implementation for Megatron-core models
import logging
from typing import Callable, List, Optional
import torch
from megatron.core.dist_checkpointing.dict_utils import nested_values
from megatron.core.dist_checkpointing.mapping import (
    LocalNonpersistentObject,
    ShardedStateDict,
)
from megatron.core.optimizer.clip_grads import count_zeros_fp32, get_grad_norm_fp32
from megatron.core.optimizer.optimizer import (
    ChainedOptimizer,
    Float16OptimizerWithFloat16Params,
    FP32Optimizer,
    MegatronOptimizer,
)
from megatron.core.optimizer.optimizer_config import OptimizerConfig
from megatron.core.process_groups_config import ProcessGroupCollection
from megatron.core.utils import get_pg_rank, get_pg_size
from torch._utils import _flatten_dense_tensors, _unflatten_dense_tensors

logger = logging.getLogger(__name__)

class DistributedLayerOptimizer(ChainedOptimizer):
    """Distributed optimizer with layer-based parameter distribution across DP ranks.

    Experimental implementation that shards model parameters by layer across data parallel ranks.
    Built on ChainedOptimizer to support multiple optimizers (e.g., muon + adamW).
    When using this optimizer, disable all other Megatron distributed-optimizer settings.

    Operation principles:
    1. Model weights are partitioned into lists; each rank stores only its assigned shard
    2. Megatron DDP handles gradient all-reduction; each rank maintains full model and gradients
    3. Optimizer is modified to update only parameters belonging to the current DP rank
    4. Gradient norm and zero-counting operations perform global reduction in step()
    5. Standard update proceeds via chained optimizers, but local optimizer updates only shard
    6. Updated parameters are gathered to all ranks via all-gather operation
    """
    def __init__(
        self,
        opt_list: List[MegatronOptimizer],
        cfg: OptimizerConfig,
        pg_group_collection: Optional[ProcessGroupCollection] = None,
        init_state_funcs: Optional[List[Callable]] = None,
    ) -> None:
        """
        Initialize DistributedLayerOptimizer.

        Args:
            opt_list: List of MegatronOptimizer instances.
            cfg: Configuration object for optimizer settings.
            pg_group_collection: ProcessGroupCollection for distributed communication.
            init_state_funcs: Optional list of initialization functions for optimizer states.
        """
        self.pg_collection = pg_group_collection
        self.partition_parameters(opt_list)

        if init_state_funcs:
            assert len(init_state_funcs) == len(
                opt_list
            ), "init_state_funcs must match length of optimizers when provided"

        # Wrap optimizers after parameter partitioning to avoid unnecessary master weight creation
        # Higher precision optimizers are already wrapped with Megatron conventions
        if cfg.bf16:
            for idx in range(len(opt_list)):
                current_opt = opt_list[idx]
                if isinstance(current_opt, Float16OptimizerWithFloat16Params):
                    raise TypeError("DistributedLayerOptimizer received Float16 optimizer already.")

                # Unwrap FP32 optimizer if reused from get_megatron_optimizer for Adam
                if isinstance(current_opt, FP32Optimizer):
                    current_opt = current_opt.optimizer

                opt_list[idx] = Float16OptimizerWithFloat16Params(
                    current_opt, cfg, None, init_state_funcs[idx] if init_state_funcs else None
                )

        super().__init__(opt_list)

    def partition_parameters(self, optimizers):
        """Partition all parameters into lists according to DP rank."""
        # Parameter lists are sorted by number of elements and assigned to ranks in ping-pong style
        # Example with 4 ranks and 10 parameters p0-p9 after sorting:
        # dp_cp_params_list becomes [[p0, p7, p8], [p1, p6, p9], [p2, p5], [p3, p4]]
        # Simplified handling when dp_cp group size is 1
        if get_pg_size(self.pg_collection.dp_cp) == 1:
            self.dp_cp_params_list = None
            self.expt_dp_params_list = None
            return

        dp_cp_idx, expt_dp_idx = 0, 0
        dp_cp_size = get_pg_size(self.pg_collection.dp_cp)
        expt_dp_size = get_pg_size(self.pg_collection.expt_dp)

        # Create ping-pong loop pattern for balanced memory usage
        dp_cp_loop = list(range(dp_cp_size)) + list(range(dp_cp_size))[::-1]
        expt_dp_loop = list(range(expt_dp_size)) + list(range(expt_dp_size))[::-1]

        self.dp_cp_params_list = [[] for _ in range(dp_cp_size)]
        self.expt_dp_params_list = [[] for _ in range(expt_dp_size)]

        # Collect all parameter groups
        param_groups = []
        for optimizer in optimizers:
            param_groups += optimizer.param_groups

        # Sort parameters by numel and assign evenly across ranks
        param_list = []
        for group_index, group in enumerate(param_groups):
            for p in group["params"]:
                param_list.append((p, group_index))

        param_list.sort(key=lambda x: x[0].numel())
        param_groups_this_rank = [[] for g in param_groups]

        # Assign parameters to ranks using ping-pong pattern
        for p, group_index in param_list:
            if param_groups[group_index].get("is_expert_parallel", False):
                if expt_dp_loop[expt_dp_idx] == get_pg_rank(self.pg_collection.expt_dp):
                    param_groups_this_rank[group_index].append(p)
                self.expt_dp_params_list[expt_dp_loop[expt_dp_idx]].append(p)
                expt_dp_idx = (expt_dp_idx + 1) % len(expt_dp_loop)
            else:
                if dp_cp_loop[dp_cp_idx] == get_pg_rank(self.pg_collection.dp_cp):
                    param_groups_this_rank[group_index].append(p)
                self.dp_cp_params_list[dp_cp_loop[dp_cp_idx]].append(p)
                dp_cp_idx = (dp_cp_idx + 1) % len(dp_cp_loop)

        # Modify parameter groups to contain only local parameters
        for groups, params in zip(param_groups, param_groups_this_rank):
            groups["params"] = params

        # Simplify when expert DP group size is 1 or expert parallel is disabled
        if expt_dp_size == 1 or len(self.expt_dp_params_list[0]) == 0:
            self.expt_dp_params_list = None

    @torch.no_grad()
    def allgather_updated_params(self) -> None:
        """All-gather updated parameters from all ranks."""
        def _allgather_helper(params_list, group):
            device = params_list[0][0].device
            dtype = params_list[0][0].dtype
            rank = get_pg_rank(group)

            # Flatten local params and prepare output tensors
            src = (
                _flatten_dense_tensors(params_list[rank])
                if len(params_list[rank]) > 0
                else torch.empty(0, device=device, dtype=dtype)
            )

            output_list = [
                torch.empty(sum([p.numel() for p in params]), device=device, dtype=dtype)
                for params in params_list
            ]

            # Single all_gather_v to collect all updated parameters
            torch.distributed.all_gather(output_list, src, group=group)

            # Unflatten and copy gathered parameters for each rank
            for idx, (flat_params, params) in enumerate(zip(output_list, params_list)):
                if len(params) == 0 or idx == rank:
                    continue
                updated_params = _unflatten_dense_tensors(flat_params, params)
                for updated_p, model_p in zip(updated_params, params):
                    model_p.data.copy_(updated_p)

        if self.pg_collection is None:
            return

        if self.dp_cp_params_list:
            _allgather_helper(self.dp_cp_params_list, self.pg_collection.dp_cp)
        if self.expt_dp_params_list:
            _allgather_helper(self.expt_dp_params_list, self.pg_collection.expt_dp)

    @torch.no_grad()
    def broadcast_local_params(self):
        """Broadcast updated local parameters to all other ranks."""
        if self.dp_cp_params_list is None:
            return

        for i, params in enumerate(self.dp_cp_params_list):
            src_global_rank = torch.distributed.get_global_rank(self.pg_collection.dp_cp, i)
            for p in params:
                torch.distributed.broadcast(p, src_global_rank, self.pg_collection.dp_cp)

        if self.expt_dp_params_list is None:
            return

        for i, params in enumerate(self.expt_dp_params_list):
            src_global_rank = torch.distributed.get_global_rank(self.pg_collection.expt_dp, i)
            for p in params:
                torch.distributed.broadcast(p, src_global_rank, self.pg_collection.expt_dp)

    @torch.no_grad()
    def compute_grad_norm(self):
        grads_for_norm = []
        for optimizer in self.chained_optimizers:
            grads_for_norm += optimizer.get_main_grads_for_grad_norm()
        grad_norm = get_grad_norm_fp32(grads_for_norm, grad_stats_parallel_group=None)
        return grad_norm

    @torch.no_grad()
    def count_zero_gradients(self):
        params = []
        for optimizer in self.chained_optimizers:
            params += optimizer.get_parameters()
        return count_zeros_fp32(
            params,
            grad_stats_parallel_group=None,
            use_decoupled_grad=self.config.use_precision_aware_optimizer_no_fp8_or_ds_fp8,
        )

    @torch.no_grad()
    def perform_step(self):  # type: ignore[no-untyped-def]
        """Execute one optimization step."""
        success, grad_norm, num_zeros_in_grad = super().step()
        # Gather updated parameters from all ranks
        self.allgather_updated_params()
        return success, grad_norm, num_zeros_in_grad

    # TODO(deyuf): Need improved distributed checkpointing design
    # fp32_from_fp16_params is a list where sublists may be empty if group has no parameters
    # This breaks dist checkpointing assumptions since extract_sharded_base drops list structure
    # For now, convert to dict with index as key and convert back during load_state_dict
    def load_state_dict(self, state_dict):
        if len(self.chained_optimizers) == 1:
            wrapped_state_dict = {1: state_dict}
        else:
            wrapped_state_dict = state_dict

        for sd in wrapped_state_dict.values():
            if "fp32_from_fp16_params" in sd and isinstance(sd["fp32_from_fp16_params"], dict):
                logger.info("[layerwise] converting fp32_from_fp16_params from dict to list")
                sd["fp32_from_fp16_params"] = [v for k, v in sorted(sd["fp32_from_fp16_params"].items())]

        super().load_state_dict(state_dict)

    def sharded_state_dict(
        self, model_sharded_state_dict: ShardedStateDict, is_loading: bool = False, **kwargs
    ):
        """
        Generate sharded state dict for torch_dist format checkpointing.
        For fixed DP usage only, set replica_id to 0 for all ShardedTensor.
        """
        sharded_state_dict = super().sharded_state_dict(model_sharded_state_dict, is_loading, **kwargs)

        # For fixed DP usage only
        for sh_base in nested_values(sharded_state_dict):
            if hasattr(sh_base, "replica_id"):
                assert (
                    isinstance(sh_base.replica_id, int) or len(sh_base.replica_id) == 3
                ), f"Expected replica_id as int or (PP, TP, DP), got: {sh_base}"
                sh_base.replica_id = (
                    0 if isinstance(sh_base.replica_id, int) else (*sh_base.replica_id[:2], 0)
                )

        # Later code assumes list but chained optimizer falls back to non-list if single optimizer
        if len(self.chained_optimizers) == 1:
            wrapped_sharded_state_dict = {1: sharded_state_dict}
        else:
            wrapped_sharded_state_dict = sharded_state_dict

        # Adjust dict rank 0 output to correct global metadata into common_dict
        for sd in wrapped_sharded_state_dict.values():
            # Wrap empty containers into LocalNonpersistentObject to prevent saving/loading
            # Parameters are already wrapped; handle only fp32_from_fp16_params and state
            if "fp32_from_fp16_params" in sd:
                sd["fp32_from_fp16_params"][:] = [
                    group if group else LocalNonpersistentObject(group)
                    for group in sd["fp32_from_fp16_params"]
                ]
                sd["fp32_from_fp16_params"] = {i: v for i, v in enumerate(sd["fp32_from_fp16_params"])}

            # State is a single dict and will be empty if optimizer is fully empty
            if not sd["optimizer"]["state"]:
                sd["optimizer"]["state"] = LocalNonpersistentObject(sd["optimizer"]["state"])

            # Group keys (e.g., 'step') might be missing or not updated
            for i, group in enumerate(sd["optimizer"]["param_groups"]):
                # Keep local param tensor so we only gather metadata
                local_params = group.pop("params")
                # Save whether this group is empty for metadata selection
                group["params"] = bool(local_params.unwrap())
                all_rank_groups = [None for _ in range(torch.distributed.get_world_size())]
                torch.distributed.all_gather_object(all_rank_groups, group)

                # Find first non-empty group if it exists
                nonempty_rank_group = next((g for g in all_rank_groups if g["params"]), group)
                nonempty_rank_group["params"] = local_params
                sd["optimizer"]["param_groups"][i] = nonempty_rank_group

        return sharded_state_dict

    def save_to_file(self, filename: str) -> None:
        """Save the parameter state of the optimizer. For torch format only.

        Args:
            filename: Path to save the parameter state.
        """
        torch.save(super().state_dict(), filename)

    def load_from_file(self, filename: str) -> None:
        """Load the parameter state of the optimizer. For torch format only."""
        super().load_state_dict(torch.load(filename))

# Modified version of the original Git VCS implementation
import os.path
import pathlib
import re
import urllib.parse
import urllib.request
from typing import List, Optional, Tuple
from pip._internal.exceptions import BadCommand, InstallationError
from pip._internal.utils.misc import HiddenText, display_path, hide_url
from pip._internal.utils.subprocess import make_command
from pip._internal.vcs.versioncontrol import (
    AuthInfo,
    RemoteNotFoundError,
    RemoteNotValidError,
    RevOptions,
    VersionControl,
    find_path_to_project_root_from_repo_root,
    vcs,
)

urlsplit = urllib.parse.urlsplit
urlunsplit = urllib.parse.urlunsplit
logger = logging.getLogger(__name__)

# Regex for parsing git version output
GIT_VERSION_PATTERN = re.compile(
    r"^git version "  # Prefix.
    r"(\d+)"  # Major.
    r"\.(\d+)"  # Dot, minor.
    r"(?:\.(\d+))?"  # Optional dot, patch.
    r".*$"  # Suffix, including any pre- and post-release segments we don't care about.
)

# Regex for validating SHA hashes
HASH_PATTERN = re.compile("^[a-fA-F0-9]{40}$")

# SCP (Secure copy protocol) shorthand pattern. e.g. 'redacted@example.invalid:foo/bar.git'
SCP_PATTERN = re.compile(
    r"""^
    # Optional user, e.g. 'git@
    (\w+@)?
    # Server, e.g. 'github.com'.
    ([^/:]+):
    # The server-side path. e.g. 'user/project.git'. Must start with an
    # alphanumeric character so as not to be confusable with Windows paths
    # like 'C:/foo/bar' or 'C:\foo\bar'.
    (\w[^:]*)
    $""",
    re.VERBOSE,
)

def is_valid_hash(sha: str) -> bool:
    return bool(HASH_PATTERN.match(sha))

class Git(VersionControl):
    name = "git"
    dirname = ".git"
    repo_name = "clone"
    schemes = (
        "git+http",
        "git+https",
        "git+ssh",
        "git+git",
        "git+file",
    )
    # Prevent user environment variables from interfering with pip operations
    unset_environ = ("GIT_DIR", "GIT_WORK_TREE")
    default_arg_rev = "HEAD"

    @staticmethod
    def get_base_rev_args(rev: str) -> List[str]:
        return [rev]

    def is_immutable_rev_checkout(self, url: str, dest: str) -> bool:
        _, rev_options = self.get_url_rev_options(hide_url(url))
        if not rev_options.rev:
            return False
        if not self.is_commit_id_equal(dest, rev_options.rev):
            # the current commit differs from rev, meaning rev was something else than a commit hash
            return False
        # return False in the rare case rev is both a commit hash and a tag or branch
        # we don't want to cache in that case since that branch/tag could change later
        is_tag_or_branch = bool(self.get_revision_sha(dest, rev_options.rev)[0])
        return not is_tag_or_branch

    def get_git_version(self) -> Tuple[int, ...]:
        version = self.run_command(
            ["version"],
            command_desc="git version",
            show_stdout=False,
            stdout_only=True,
        )
        match = GIT_VERSION_PATTERN.match(version)
        if not match:
            logger.warning("Unable to parse git version: %s", version)
            return ()
        return (int(match.group(1)), int(match.group(2)))

    @classmethod
    def get_current_branch(cls, location: str) -> Optional[str]:
        """
        Return the current branch, or None if HEAD isn't at a branch
        (e.g., detached HEAD).
        """
        args = ["symbolic-ref", "-q", "HEAD"]
        output = cls.run_command(
            args,
            extra_ok_returncodes=(1,),
            show_stdout=False,
            stdout_only=True,
            cwd=location,
        )
        ref = output.strip()
        if ref.startswith("refs/heads/"):
            return ref[len("refs/heads/") :]
        return None

    @classmethod
    def get_revision_sha(cls, dest: str, rev: str) -> Tuple[Optional[str], bool]:
        """
        Return (sha_or_none, is_branch), where sha_or_none is a commit hash
        if the revision names a remote branch or tag, otherwise None.
        Args:
          dest: the repository directory.
          rev: the revision name.
        """
        output = cls.run_command(
            ["show-ref", rev],
            cwd=dest,
            show_stdout=False,
            stdout_only=True,
            on_returncode="ignore",
        )
        refs = {}
        for line in output.strip().split("\n"):
            line = line.rstrip("\r")
            if not line:
                continue
            try:
                ref_sha, ref_name = line.split(" ", maxsplit=2)
            except ValueError:
                raise ValueError(f"unexpected show-ref line: {line!r}")
            refs[ref_name] = ref_sha
        branch_ref = f"refs/remotes/origin/{rev}"
        tag_ref = f"refs/tags/{rev}"
        sha = refs.get(branch_ref)
        if sha is not None:
            return (sha, True)
        sha = refs.get(tag_ref)
        return (sha, False)

    @classmethod
    def _should_fetch(cls, dest: str, rev: str) -> bool:
        """
        Return true if rev is a ref or is a commit that we don't have locally.
        Branches and tags are not considered here as they're assumed to be available locally.
        """
        if rev.startswith("refs/"):
            return True
        if not is_valid_hash(rev):
            return False
        if cls.has_commit(dest, rev):
            return False
        return True

    @classmethod
    def resolve_revision(
        cls, dest: str, url: HiddenText, rev_options: RevOptions
    ) -> RevOptions:
        rev = rev_options.arg_rev
        assert rev is not None
        sha, is_branch = cls.get_revision_sha(dest, rev)
        if sha is not None:
            rev_options = rev_options.make_new(sha)
            rev_options.branch_name = rev if is_branch else None
            return rev_options
        if not is_valid_hash(rev):
            logger.warning(
                "Did not find branch or tag '%s', assuming revision or ref.",
                rev,
            )
        if not cls._should_fetch(dest, rev):
            return rev_options
        cls.run_command(
            make_command("fetch", "-q", url, rev_options.to_args()),
            cwd=dest,
        )
        sha = cls.get_revision(dest, rev="FETCH_HEAD")
        rev_options = rev_options.make_new(sha)
        return rev_options

    @classmethod
    def is_commit_id_equal(cls, dest: str, name: Optional[str]) -> bool:
        if not name:
            return False
        return cls.get_revision(dest) == name

    def fetch_new(
        self, dest: str, url: HiddenText, rev_options: RevOptions, verbosity: int
    ) -> None:
        rev_display = rev_options.to_display()
        logger.info("Cloning %s%s to %s", url, rev_display, display_path(dest))
        if verbosity <= 0:
            flags: Tuple[str, ...] = ("--quiet",)
        elif verbosity == 1:
            flags = ()
        else:
            flags = ("--verbose", "--progress")
        if self.get_git_version() >= (2, 17):
            self.run_command(
                make_command(
                    "clone",
                    "--filter=blob:none",
                    *flags,
                    url,
                    dest,
                )
            )
        else:
            self.run_command(make_command("clone", *flags, url, dest))
        if rev_options.rev:
            rev_options = self.resolve_revision(dest, url, rev_options)
            branch_name = getattr(rev_options, "branch_name", None)
            logger.debug("Rev options %s, branch_name %s", rev_options, branch_name)
            if branch_name is None:
                if not self.is_commit_id_equal(dest, rev_options.rev):
                    cmd_args = make_command(
                        "checkout",
                        "-q",
                        rev_options.to_args(),
                    )
                    self.run_command(cmd_args, cwd=dest)
            elif self.get_current_branch(dest) != branch_name:
                track_branch = f"origin/{branch_name}"
                cmd_args = [
                    "checkout",
                    "-b",
                    branch_name,
                    "--track",
                    track_branch,
                ]
                self.run_command(cmd_args, cwd=dest)
        else:
            sha = self.get_revision(dest)
            rev_options = rev_options.make_new(sha)
        logger.info("Resolved %s to commit %s", url, rev_options.rev)
        self.update_submodules(dest)

    def switch(self, dest: str, url: HiddenText, rev_options: RevOptions) -> None:
        self.run_command(
            make_command("config", "remote.origin.url", url),
            cwd=dest,
        )
        cmd_args = make_command("checkout", "-q", rev_options.to_args())
        self.run_command(cmd_args, cwd=dest)
        self.update_submodules(dest)

    def update(self, dest: str, url: HiddenText, rev_options: RevOptions) -> None:
        if self.get_git_version() >= (1, 9):
            self.run_command(["fetch", "-q", "--tags"], cwd=dest)
        else:
            self.run_command(["fetch", "-q"], cwd=dest)
        rev_options = self.resolve_revision(dest, url, rev_options)
        cmd_args = make_command("reset", "--hard", "-q", rev_options.to_args())
        self.run_command(cmd_args, cwd=dest)
        self.update_submodules(dest)

    @classmethod
    def get_remote_url(cls, location: str) -> str:
        stdout = cls.run_command(
            ["config", "--get-regexp", r"remote\..*\.url"],
            extra_ok_returncodes=(1,),
            show_stdout=False,
            stdout_only=True,
            cwd=location,
        )
        remotes = stdout.splitlines()
        try:
            found_remote = remotes[0]
        except IndexError:
            raise RemoteNotFoundError
        for remote in remotes:
            if remote.startswith("remote.origin.url "):
                found_remote = remote
                break
        url = found_remote.split(" ")[1]
        return cls._git_remote_to_pip_url(url.strip())

    @staticmethod
    def _git_remote_to_pip_url(url: str) -> str:
        if re.match(r"\w+://", url):
            return url
        if os.path.exists(url):
            return pathlib.PurePath(url).as_uri()
        scp_match = SCP_PATTERN.match(url)
        if scp_match:
            return scp_match.expand(r"ssh://\1\2/\3")
        raise RemoteNotValidError(url)

    @classmethod
    def has_commit(cls, location: str, rev: str) -> bool:
        try:
            cls.run_command(
                ["rev-parse", "-q", "--verify", "sha^" + rev],
                cwd=location,
                log_failed_cmd=False,
            )
        except InstallationError:
            return False
        else:
            return True

    @classmethod
    def get_revision(cls, location: str, rev: Optional[str] = None) -> str:
        if rev is None:
            rev = "HEAD"
        current_rev = cls.run_command(
            ["rev-parse", rev],
            show_stdout=False,
            stdout_only=True,
            cwd=location,
        )
        return current_rev.strip()

    @classmethod
    def get_subdirectory(cls, location: str) -> Optional[str]:
        git_dir = cls.run_command(
            ["rev-parse", "--git-dir"],
            show_stdout=False,
            stdout_only=True,
            cwd=location,
        ).strip()
        if not os.path.isabs(git_dir):
            git_dir = os.path.join(location, git_dir)
        repo_root = os.path.abspath(os.path.join(git_dir, ".."))
        return find_path_to_project_root_from_repo_root(location, repo_root)

    @classmethod
    def get_url_rev_and_auth(cls, url: str) -> Tuple[str, Optional[str], AuthInfo]:
        scheme, netloc, path, query, fragment = urlsplit(url)
        if scheme.endswith("file"):
            initial_slashes = path[: -len(path.lstrip("/"))]
            newpath = initial_slashes + urllib.request.url2pathname(path).replace(
                "\\", "/"
            ).lstrip("/")
            after_plus = scheme.find("+") + 1
            url = scheme[:after_plus] + urlunsplit(
                (scheme[after_plus:], netloc, newpath, query, fragment),
            )
        if "://" not in url:
            assert "file:" not in url
            url = url.replace("git+", "git+ssh://")
            url, rev, user_pass = super().get_url_rev_and_auth(url)
            url = url.replace("ssh://", "")
        else:
            url, rev, user_pass = super().get_url_rev_and_auth(url)
        return url, rev, user_pass

    @classmethod
    def update_submodules(cls, location: str) -> None:
        if not os.path.exists(os.path.join(location, ".gitmodules")):
            return
        cls.run_command(
            ["submodule", "update", "--init", "--recursive", "-q"],
            cwd=location,
        )

    @classmethod
    def get_repository_root(cls, location: str) -> Optional[str]:
        loc = super().get_repository_root(location)
        if loc:
            return loc
        try:
            r = cls.run_command(
                ["rev-parse", "--show-toplevel"],
                cwd=location,
                show_stdout=False,
                stdout_only=True,
                on_returncode="raise",
                log_failed_cmd=False,
            )
        except BadCommand:
            logger.debug(
                "could not determine if %s is under git control "
                "because git is not available",
                location,
            )
            return None
        except InstallationError:
            return None
        return os.path.normpath(r.rstrip("\r\n"))

    @staticmethod
    def should_add_vcs_url_prefix(repo_url: str) -> bool:
        return True

vcs.register(Git)

import unittest
from noether.core.schedules import ScheduleBase, SequentialPercentSchedule, SequentialPercentScheduleConfig

class PlaceholderSchedule(ScheduleBase):
    def __init__(self, step_to_value=None, **kwargs):
        super().__init__(**kwargs)
        self.step_to_value = step_to_value

    def _get_value(self, step: int, total_steps: int) -> float:
        if self.step_to_value is None:
            return 0.0
        return self.step_to_value[step]

class TestSequentialPercentSchedule(unittest.TestCase):
    def test_propagate_singleconfig(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0.0, sched.schedule_configs[0].start_percent)
        self.assertEqual(1.0, sched.schedule_configs[0].end_percent)

    def test_propagate_forward(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(end_percent=0.1, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0.0, sched.schedule_configs[0].start_percent)
        self.assertEqual(0.1, sched.schedule_configs[0].end_percent)
        self.assertEqual(0.1, sched.schedule_configs[1].start_percent)
        self.assertEqual(1.0, sched.schedule_configs[1].end_percent)

    def test_propagate_backward(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(start_percent=0.1, schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0.0, sched.schedule_configs[0].start_percent)
        self.assertEqual(0.1, sched.schedule_configs[0].end_percent)
        self.assertEqual(0.1, sched.schedule_configs[1].start_percent)
        self.assertEqual(1.0, sched.schedule_configs[1].end_percent)

    def test_propagate_gap(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(end_percent=0.1, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(start_percent=0.15, schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0.0, sched.schedule_configs[0].start_percent)
        self.assertEqual(0.1, sched.schedule_configs[0].end_percent)
        self.assertEqual(0.15, sched.schedule_configs[1].start_percent)
        self.assertEqual(1.0, sched.schedule_configs[1].end_percent)

    def test_propagate_middle(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(end_percent=0.1, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(start_percent=0.15, schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0.0, sched.schedule_configs[0].start_percent)
        self.assertEqual(0.1, sched.schedule_configs[0].end_percent)
        self.assertEqual(0.1, sched.schedule_configs[1].start_percent)
        self.assertEqual(0.15, sched.schedule_configs[1].end_percent)
        self.assertEqual(0.15, sched.schedule_configs[2].start_percent)
        self.assertEqual(1.0, sched.schedule_configs[2].end_percent)

    def test_propagate_noneinbetween(self):
        with self.assertRaises(AssertionError):
            SequentialPercentSchedule(
                [
                    SequentialPercentScheduleConfig(end_percent=0.1, schedule=PlaceholderSchedule()),
                    SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
                    SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
                ]
            )

    def test_check_singleconfig(self):
        with self.assertRaises(AssertionError):
            SequentialPercentSchedule(
                [
                    SequentialPercentScheduleConfig(start_percent=0.5, end_percent=0.3, schedule=PlaceholderSchedule()),
                ]
            )

    def test_check_propagatedendstep(self):
        with self.assertRaises(AssertionError):
            SequentialPercentSchedule(
                [
                    SequentialPercentScheduleConfig(end_percent=0.1, schedule=PlaceholderSchedule()),
                    SequentialPercentScheduleConfig(start_percent=0.05, schedule=PlaceholderSchedule()),
                ]
            )

    def test_get_sequential_schedule_config_zeroduration(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(end_percent=0.0, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(0, 10))

    def test_get_sequential_schedule_config(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(start_percent=0.05, end_percent=0.1, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(end_percent=0.15, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i, 101))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i, 101))
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i, 101))
        for i in range(15, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i, 101))

    def test_get_sequential_schedule_config_gap(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(start_percent=0.05, end_percent=0.1, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(start_percent=0.15, end_percent=0.2, schedule=PlaceholderSchedule()),
                SequentialPercentScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i, 101))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i, 101))
        # gap returns previous schedule
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i, 101))
        for i in range(15, 20):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i, 101))
        for i in range(20, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i, 101))

    def test_get_value_before_first_schedule(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(start_percent=0.5, schedule=PlaceholderSchedule(step_to_value={0: 0.5})),
            ]
        )
        for i in range(5):
            self.assertEqual(0.5, sched.get_value(i, 10))

    def test_get_value_after_last_schedule(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(
                    start_percent=0.3,
                    end_percent=0.5,
                    schedule=PlaceholderSchedule(step_to_value={0: 0.1, 1: 0.2}),
                ),
            ]
        )
        for i in range(4):
            self.assertEqual(0.1, sched.get_value(i, 11))
        self.assertEqual(0.2, sched.get_value(4, 11))
        for i in range(5, 11):
            self.assertEqual(0.2, sched.get_value(i, 11))

    def test_tostring(self):
        sched = SequentialPercentSchedule(
            [
                SequentialPercentScheduleConfig(
                    start_percent=0.3,
                    end_percent=0.5,
                    schedule=PlaceholderSchedule(),
                ),
            ]
        )
        lines = str(sched).split("\n")
        self.assertEqual(3, len(lines))
        self.assertEqual(SequentialPercentSchedule.__name__, lines[0])
        self.assertEqual("  (0): 0.3 - 0.5 PlaceholderSchedule", lines[1])
        self.assertEqual(")", lines[2])

