# Modified version with renamed variables, changed literals, and reordered statements
import re
from abc import ABC, abstractmethod
from collections import namedtuple
from dataclasses import dataclass, field
from typing import Optional, Union, List
from typing import Sequence, Dict, Set
import json
from typing_extensions import override
from mindspeed_mm.data.data_utils.func_utils.tool_utils import get_tool_utils

# Define slot types as a sequence of strings, sets, or dictionaries
SLOTS = Sequence[Union[str, Set[str], Dict[str, str]]]

@dataclass
class BaseFormatter(ABC):
    fields: SLOTS = field(default_factory=list)
    format_style: Optional[str] = None

    @abstractmethod
    def process(self, **kwargs) -> SLOTS:
        r"""
        Constructs a list of slots based on the provided inputs for encoding.
        """
        ...

    def retrieve(self, text: str) -> Union[str, List["FunctionCall"]]:
        r"""
        Extracts function calls from the response message when tools are used.
        Returns either a string or a list of FunctionCall objects.
        """
        raise NotImplementedError

@dataclass
class NullFormatter(BaseFormatter):
    def __post_init__(self):
        has_placeholder = False
        for slot in filter(lambda s: isinstance(s, str), self.fields):
            if re.search(r"\{\{[a-zA-Z_][a-zA-Z0-9_]*\}\}", slot):
                has_placeholder = True
        if has_placeholder:
            raise ValueError("Null formatter should not contain any placeholder.")

    def process(self, **kwargs) -> SLOTS:
        return self.fields

@dataclass
class TextFormatter(BaseFormatter):
    def __post_init__(self):
        has_placeholder = False
        for slot in filter(lambda s: isinstance(s, str), self.fields):
            if re.search(r"\{\{[a-zA-Z_][a-zA-Z0-9_]*\}\}", slot):
                has_placeholder = True
        if not has_placeholder:
            raise ValueError("A placeholder is required in the text formatter.")

    def process(self, **kwargs) -> SLOTS:
        elements = []
        for slot in self.fields:
            if isinstance(slot, str):
                for name, value in kwargs.items():
                    if not isinstance(value, str):
                        raise RuntimeError("Expected a string, got {}".format(value))
                    slot = slot.replace("{{" + name + "}}", value, 1)
                elements.append(slot)
            elif isinstance(slot, (dict, set)):
                elements.append(slot)
            else:
                raise RuntimeError("Input must be string, set[str] or dict[str, str], got {}".format(type(slot)))
        return elements

# Named tuple to represent a function call with name and arguments
FunctionCall = namedtuple("FunctionCall", ["name", "arguments"])

@dataclass
class FuncFormatter(TextFormatter):
    def __post_init__(self):
        super().__post_init__()
        self.tool_helpers = get_tool_utils(self.format_style)

    @override
    def process(self, **kwargs) -> SLOTS:
        content: str = kwargs.pop("content")
        thought_words = kwargs.pop("thinking_markers", None)
        tool_call_words = kwargs.pop("function_markers", None)

        def _extract_functions(json_text: str) -> list["FunctionCall"]:
            try:
                tool_calls = json.loads(json_text)
                if not isinstance(tool_calls, list):  # parallel function call
                    tool_calls = [tool_calls]
                return [FunctionCall(tc["name"], json.dumps(tc["arguments"], ensure_ascii=False)) for tc in tool_calls]
            except json.JSONDecodeError:
                raise RuntimeError(f"Invalid JSON format in function message: {str([content])}.")

        tool_match = None
        if tool_call_words and len(tool_call_words) == 2:
            tool_regex = re.compile(
                rf"{re.escape(tool_call_words[0])}(.*?){re.escape(tool_call_words[1])}", re.DOTALL
            )
            tool_match = re.search(tool_regex, content)

        if tool_match is None:
            thought_match = None
            if thought_words and len(thought_words) == 2:
                regex = re.compile(rf"{re.escape(thought_words[0])}(.*?){re.escape(thought_words[1])}", re.DOTALL)
                thought_match = re.search(regex, content)

            if thought_match:
                json_part = content.replace(thought_match.group(0), "")
            else:
                json_part = content

            functions = _extract_functions(json_part)
            function_str = self.tool_helpers.function_formatter(functions)
            if thought_match:
                function_str = thought_match.group(0) + function_str
        else:
            thought_content = content.replace(tool_match.group(0), "")
            functions = _extract_functions(tool_match.group(1))
            function_str = self.tool_helpers.function_formatter(functions)
            function_str = thought_content + function_str

        return super().process(content=function_str)

@dataclass
class ToolHandler(BaseFormatter):
    def __post_init__(self):
        self.tool_helpers = get_tool_utils(self.format_style)

    @override
    def process(self, **kwargs) -> SLOTS:
        content = kwargs.pop("content")
        try:
            tools = json.loads(content)
            return [self.tool_helpers.tool_formatter(tools) if len(tools) != 0 else ""]
        except json.JSONDecodeError:
            raise RuntimeError(f"Invalid JSON format in tool description: {str([content])}.")  # flat string

    @override
    def retrieve(self, text: str) -> str | list["FunctionCall"]:
        return self.tool_helpers.tool_extractor(text)

# Modified version of LLMRouterClient with Type I clone techniques applied
import argparse
import io
import json
import os
import sys
import urllib.request
import urllib.error
from typing import Any, Dict, Generator, List, Optional

# Ensure UTF-8 output on Windows
if sys.platform == "win32":
    sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
    sys.stderr = io.TextIOWrapper(sys.stderr.buffer, encoding="utf-8", errors="replace")


class LLMGatewayClient:
    """Unified LLM Gateway Client for AIsa API."""

    BASE_URL = "https://api.aisa.one/v1"

    # Popular models for reference (check marketplace.aisa.one/pricing for full list)
    MODEL_LIST = {
        "openai": ["gpt-5.2", "gpt-5", "gpt-5-mini", "gpt-4.1", "gpt-4.1-mini", "gpt-4o", "gpt-4o-mini", "gpt-oss-120b"],
        "anthropic": ["claude-sonnet-4-5-20250929", "claude-opus-4-1-20250805", "claude-opus-4-20250514", "claude-sonnet-4-20250514", "claude-haiku-4-5-20251001", "claude-3-7-sonnet-20250219"],
        "google": ["gemini-2.5-pro", "gemini-2.5-flash", "gemini-2.5-flash-lite", "gemini-3-pro-preview"],
        "xai": ["grok-4", "grok-3"],
        "meta": ["llama-3.1-405b", "llama-3.1-70b", "llama-3.1-8b"],
        "mistral": ["mistral-large", "mistral-medium", "mixtral-8x7b"],
    }

    def __init__(self, api_key: Optional[str] = None):
        """Initialize the client with an API key."""
        self.api_token = api_key or os.environ.get("AISA_API_KEY")
        if not self.api_token:
            raise ValueError(
                "AISA_API_KEY is required. Set it via environment variable or pass to constructor."
            )

    def _send_request(
        self, 
        method: str, 
        path: str, 
        payload: Optional[Dict[str, Any]] = None,
        streaming: bool = False
    ) -> Any:
        """Make an HTTP request to the AIsa API."""
        endpoint_url = f"{self.BASE_URL}{path}"

        request_headers = {
            "Authorization": f"Bearer {self.api_token}",
            "Content-Type": "application/json",
            "User-Agent": "OpenClaw-LLMRouter/1.0",
            "Accept": "application/json"
        }

        body_data = None
        if payload:
            body_data = json.dumps(payload).encode("utf-8")

        req = urllib.request.Request(endpoint_url, data=body_data, headers=request_headers, method=method)

        try:
            response = urllib.request.urlopen(req, timeout=120)

            if streaming:
                return self._process_stream(response)
            else:
                return json.loads(response.read().decode("utf-8"))

        except urllib.error.HTTPError as e:
            error_content = e.read().decode("utf-8")
            try:
                return json.loads(error_content)
            except json.JSONDecodeError:
                return {"error": {"code": str(e.code), "message": error_content}}
        except urllib.error.URLError as e:
            return {"error": {"code": "NETWORK_ERROR", "message": str(e.reason)}}

    def _process_stream(self, response) -> Generator[str, None, None]:
        """Handle streaming response (SSE)."""
        for line in response:
            line = line.decode("utf-8").strip()
            if line.startswith("data: "):
                data = line[6:]
                if data == "[DONE]":
                    break
                try:
                    chunk = json.loads(data)
                    if "choices" in chunk and chunk["choices"]:
                        delta = chunk["choices"][0].get("delta", {})
                        text = delta.get("content", "")
                        if text:
                            yield text
                except json.JSONDecodeError:
                    continue

    def chat_completion(
        self,
        model_name: str,
        conversation: List[Dict[str, str]],
        temp: Optional[float] = None,
        limit_tokens: Optional[int] = None,
        nucleus_p: Optional[float] = None,
        do_stream: bool = False,
        **extra_params
    ) -> Dict[str, Any]:
        """
        Create a chat completion.

        Args:
            model_name: Model identifier (e.g., gpt-4.1, claude-sonnet-4-5)
            conversation: List of message dicts with 'role' and 'content'
            temp: Sampling temperature (0-2)
            limit_tokens: Maximum tokens to generate
            nucleus_p: Nucleus sampling parameter
            do_stream: Whether to stream the response
            **extra_params: Additional parameters (functions, function_call, etc.)

        Returns:
            Chat completion response
        """
        request_body = {
            "model": model_name,
            "messages": conversation,
            "stream": do_stream
        }

        if temp is not None:
            request_body["temperature"] = temp
        if limit_tokens is not None:
            request_body["max_tokens"] = limit_tokens
        if nucleus_p is not None:
            request_body["top_p"] = nucleus_p

        # Add any additional kwargs
        request_body.update(extra_params)

        return self._send_request("POST", "/chat/completions", data=request_body, streaming=do_stream)

    def chat_streaming(
        self,
        model_name: str,
        conversation: List[Dict[str, str]],
        **extra_params
    ) -> Generator[str, None, None]:
        """
        Create a streaming chat completion.

        Yields content chunks as they arrive.
        """
        return self.chat_completion(model_name=model_name, conversation=conversation, do_stream=True, **extra_params)

    def image_analysis(
        self,
        model_name: str,
        image_location: str,
        query: str,
        **extra_params
    ) -> Dict[str, Any]:
        """
        Analyze an image with a vision-capable model.

        Args:
            model_name: Vision-capable model (e.g., gpt-4o, gemini-1.5-pro)
            image_location: URL of the image to analyze
            query: Question or instruction about the image

        Returns:
            Chat completion response
        """
        conversation = [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": query},
                    {"type": "image_url", "image_url": {"url": image_location}}
                ]
            }
        ]
        return self.chat_completion(model_name=model_name, conversation=conversation, **extra_params)

    def benchmark_models(
        self,
        model_names: List[str],
        user_message: str,
        **extra_params
    ) -> Dict[str, Any]:
        """
        Compare responses from multiple models.

        Args:
            model_names: List of model identifiers
            user_message: The message to send to each model

        Returns:
            Dict with model names as keys and results as values
        """
        import time

        benchmark_results = {}
        for model_name in model_names:
            start_time = time.time()
            try:
                response = self.chat_completion(
                    model_name=model_name,
                    conversation=[{"role": "user", "content": user_message}],
                    **extra_params
                )
                elapsed_time = time.time() - start_time

                if "error" in response:
                    benchmark_results[model_name] = {
                        "success": False,
                        "error": response["error"],
                        "latency": elapsed_time
                    }
                else:
                    content = response.get("choices", [{}])[0].get("message", {}).get("content", "")
                    usage = response.get("usage", {})
                    benchmark_results[model_name] = {
                        "success": True,
                        "response": content,
                        "latency": elapsed_time,
                        "tokens": usage.get("total_tokens", 0),
                        "cost": usage.get("cost", 0)
                    }
            except Exception as e:
                benchmark_results[model_name] = {
                    "success": False,
                    "error": str(e),
                    "latency": time.time() - start_time
                }

        return benchmark_results

    def available_models(self) -> Dict[str, List[str]]:
        """List supported model families and models."""
        return self.MODEL_LIST


def main():
    """Main CLI entry point."""
    parser = argparse.ArgumentParser(
        description="LLM Router - Unified Model Gateway (70+ models)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
    %(prog)s chat --model gpt-4.1 --message "Hello!"
    %(prog)s chat --model claude-sonnet-4-5 --message "Write a poem" --stream
    %(prog)s chat --model gpt-4 --system "You are a pirate" --message "Greet me"
    %(prog)s vision --model gpt-4o --image "https://example.com/img.jpg" --prompt "Describe this"
    %(prog)s compare --models "gpt-4.1,claude-sonnet-4-5" --message "Explain AI"
    %(prog)s models
        """
    )

    subparsers = parser.add_subparsers(dest="command", help="Command")

