from functools import partial
from typing import Any, Callable, Dict, List, Type, TypeVar, Union, overload
import torch
import torch.nn as nn
import torch.types

def add_tensors(m1: torch.Tensor, m2: torch.Tensor, perform_inplace: bool) -> torch.Tensor:
    # First operation in a checkpoint cannot be in-place, but in-place addition is useful during inference
    if not perform_inplace:
        result = m1 + m2
    else:
        m1.add_(m2)
        result = m1
    return result

def rearrange_dims(tensor: torch.Tensor, indices: List[int]) -> torch.Tensor:
    core_dims = -1 * len(indices)
    leading_indices = list(range(len(tensor.shape[:core_dims])))
    return tensor.permute(leading_indices + [core_dims + i for i in indices])

def collapse_final_dimensions(t: torch.Tensor, num_dims: int) -> torch.Tensor:
    original_shape = t.shape
    new_shape = original_shape[:-num_dims] + (-1,)
    return t.reshape(new_shape)

def compute_masked_average(mask: torch.Tensor, values: torch.Tensor, axis: int, epsilon: float = 1e-4) -> torch.Tensor:
    expanded_mask = mask.expand(*values.shape)
    numerator = torch.sum(expanded_mask * values, dim=axis)
    denominator = epsilon + torch.sum(expanded_mask, dim=axis)
    return numerator / denominator

def create_distance_histogram(
    coordinates: torch.Tensor, 
    min_dist: torch.types.Number = 2.3125, 
    max_dist: torch.types.Number = 21.6875, 
    num_bins: int = 64
) -> torch.Tensor:
    bin_edges = torch.linspace(min_dist, max_dist, num_bins - 1, device=coordinates.device)
    pairwise_diffs = coordinates.unsqueeze(-2) - coordinates.unsqueeze(-3)
    distances = torch.sqrt(torch.sum(pairwise_diffs ** 2, dim=-1))
    return torch.bucketize(distances, bin_edges)

def apply_function_to_dicts(fn: Callable[[list], Any], dict_list: List[dict]) -> dict:
    base_dict = dict_list[0]
    output_dict = {}
    for key, value in base_dict.items():
        all_values = [d[key] for d in dict_list]
        if isinstance(value, dict):
            output_dict[key] = apply_function_to_dicts(fn, all_values)
        else:
            output_dict[key] = fn(all_values)
    return output_dict

def convert_to_one_hot(input_tensor: torch.Tensor, bin_positions: torch.Tensor) -> torch.Tensor:
    reshaped_bins = bin_positions.view(((1,) * len(input_tensor.shape)) + (len(bin_positions),))
    differences = input_tensor[..., None] - reshaped_bins
    nearest_bin_idx = torch.argmin(torch.abs(differences), dim=-1)
    return nn.functional.one_hot(nearest_bin_idx, num_classes=len(bin_positions)).float()

def gather_batched_data(data: torch.Tensor, indices: torch.Tensor, dimension: int = 0, batch_dims: int = 0) -> torch.Tensor:
    index_ranges: List[Union[slice, torch.Tensor]] = []

    # Build ranges for batch dimensions
    for i, size in enumerate(data.shape[:batch_dims]):
        r = torch.arange(size)
        r = r.view(*(*((1,) * i), -1, *((1,) * (len(indices.shape) - i - 1))))
        index_ranges.append(r)

    # Handle remaining dimensions
    rest_dims: List[Union[slice, torch.Tensor]] = [slice(None) for _ in range(len(data.shape) - batch_dims)]
    adjusted_dim = dimension - batch_dims if dimension >= 0 else dimension
    rest_dims[adjusted_dim] = indices
    index_ranges.extend(rest_dims)

    # Use tuple indexing to avoid NumPy compatibility issues
    return data[tuple(index_ranges)]

T = TypeVar("T")

# Tree mapping utility - similar to JAX's tree_map
def recursive_map(
    fn: Callable[[T], Any], structure: Dict[Any, Union[dict, list, tuple, T]], leaf_type: Type[T]
) -> Dict[Any, Union[dict, list, tuple, Any]]:
    updated_structure: Dict[Any, Union[dict, list, tuple, Any]] = {}
    for key, val in structure.items():
        if isinstance(val, dict):
            updated_structure[key] = recursive_map(fn, val, leaf_type)
        else:
            updated_structure[key] = apply_tree_map(fn, val, leaf_type)
    return updated_structure

@overload
def apply_tree_map(fn: Callable[[T], Any], tree: T, leaf_type: Type[T]) -> Any: ...
@overload
def apply_tree_map(fn: Callable[[T], Any], tree: dict, leaf_type: Type[T]) -> dict: ...
@overload
def apply_tree_map(fn: Callable[[T], Any], tree: list, leaf_type: Type[T]) -> list: ...
@overload
def apply_tree_map(fn: Callable[[T], Any], tree: tuple, leaf_type: Type[T]) -> tuple: ...

def apply_tree_map(fn, tree, leaf_type):
    if isinstance(tree, dict):
        return recursive_map(fn, tree, leaf_type)
    elif isinstance(tree, list):
        return [apply_tree_map(fn, x, leaf_type) for x in tree]
    elif isinstance(tree, tuple):
        return tuple(apply_tree_map(fn, x, leaf_type) for x in tree)
    elif isinstance(tree, leaf_type):
        return fn(tree)
    else:
        print(type(tree))
        raise TypeError("Unsupported type")

# Create specialized function for tensor trees
tensor_tree_transform = partial(apply_tree_map, leaf_type=torch.Tensor)

