import os
import random
import time
import ray
import requests
from kimina_client import AsyncKiminaClient, CheckResponse
from ray.util.scheduling_strategies import NodeAffinitySchedulingStrategy
from miles.utils.misc import exec_command, get_free_port

# Configuration to control previous Docker container termination
_TERMINATE_OLD_KIMINA_CONTAINERS = bool(int(os.environ.get("MILES_KILL_PREVIOUS_KIMINA_DOCKER", "1")))

class KiminaServerAndClientCluster:
    def __init__(self):
        self._server_actors = _spawn_actor_per_node(actor_cls=_KiminaServerActor)
        self._client_pool = _KiminaClientPool(self._server_actors)

    async def validate(self, *args, **kwargs) -> CheckResponse:
        return await self._client_pool.validate(*args, **kwargs)

class _KiminaClientPool:
    def __init__(self, servers: list["_KiminaServerActor"]):
        self._clients = [AsyncKiminaClient(api_url=ray.get(server.fetch_api_endpoint.remote())) for server in servers]
        self._current_client_idx = 0

    async def validate(self, *args, **kwargs):
        client = self._clients[self._current_client_idx]
        self._current_client_idx = (self._current_client_idx + 1) % len(self._clients)
        return await client.check(*args, **kwargs)

def _spawn_actor_per_node(actor_cls) -> list:
    # Use all currently active nodes for actor placement
    active_nodes = [n for n in ray.nodes() if n.get("Alive")]
    assert len(active_nodes) > 0

    deployed_actors = []
    for node_info in active_nodes:
        deployed_actors.append(
            actor_cls.options(
                name=None,
                lifetime="detached",
                scheduling_strategy=NodeAffinitySchedulingStrategy(node_id=node_info["NodeID"], soft=False),
                num_cpus=0.001,
            ).remote()
        )
    return deployed_actors

@ray.remote
class _KiminaServerActor:
    def __init__(self):
        self._port = get_free_port()
        if _TERMINATE_OLD_KIMINA_CONTAINERS:
            _stop_all_existing_docker_containers()
        self._container_name = _launch_docker_container(port=self._port)
        _await_server_startup(base_url=self.fetch_api_endpoint())

    def fetch_api_endpoint(self):
        return f"http://{self._container_name}:8000"

def _launch_docker_container(port: int):
    container_id = (
        f"kimina_lean_server_auto_{time.strftime('%Y%m%d%H%M%S')}-{random.randint(0, 999999)}"
    )
    exec_command(
        "docker run "
        "-d "
        f"--name {container_id} "
        "--restart unless-stopped "
        "--network formal_math "
        f"-p {port}:8000 "
        "projectnumina/kimina-lean-server:2.0.0"
    )
    return container_id

def _await_server_startup(base_url: str):
    with requests.Session() as session:
        while True:
            try:
                response = session.get(f"{base_url}/health")
                if response.status_code == 200:
                    break
            except requests.RequestException:
                pass
            print(f"Waiting for Kimina server initialization ({base_url})...")
            time.sleep(2)

def _stop_all_existing_docker_containers():
    exec_command(
        'container_ids=$(docker ps -a --filter "name=kimina_lean_server_auto" -q); '
        '[ -n "$container_ids" ] && docker stop $container_ids && docker rm $container_ids; '
        "true"
    )

