class MultiDistillModelStruct(MultiModelStruct):
    def __init__(self, model_list, cfg, boundary_step_idx=2):
        self.model = model_list  # [high_noise_model, low_noise_model]
        assert len(self.model) == 2, "MultiModelStruct only supports 2 models now."
        self.config = cfg
        self.boundary_step_index = boundary_step_idx
        self.cur_model_index = -1
        logger.info(f"boundary step index: {self.boundary_step_index}")

    @ProfilingContext4DebugL2("Swtich models in infer_main costs")
    def get_current_model_index(self):
        if self.scheduler.step_index < self.boundary_step_index:
            logger.info(f"using - HIGH - noise model at step_index {self.scheduler.step_index + 1}")
            #  self.scheduler.sample_guide_scale = self.config["sample_guide_scale"][0]
            if self.config.get("cpu_offload", False) and self.config.get("offload_granularity", "block") == "model":
                if self.cur_model_index == -1:
                    self.to_cuda(model_index=0)
                elif self.cur_model_index == 1:  # 1 -> 0
                    self.offload_cpu(model_index=1)
                    self.to_cuda(model_index=0)
            self.cur_model_index = 0
        else:
            logger.info(f"using - LOW - noise model at step_index {self.scheduler.step_index + 1}")
            # self.scheduler.sample_guide_scale = self.config["sample_guide_scale"][1]
            if self.config.get("cpu_offload", False) and self.config.get("offload_granularity", "block") == "model":
                if self.cur_model_index == -1:
                    self.to_cuda(model_index=1)
                elif self.cur_model_index == 0:  # 0 -> 1
                    self.offload_cpu(model_index=0)
                    self.to_cuda(model_index=1)
            self.cur_model_index = 1

    def infer(self, inputs):
        self.get_current_model_index()
        if not self.config.get("lazy_load", False) and not self.config.get("unload_modules", False):
            self.model[self.cur_model_index].infer(inputs)
        else:
            if self.model[self.cur_model_index] is not None:
                self.model[self.cur_model_index].infer(inputs)
            else:
                if self.cur_model_index == 0:
                    lora_opts = self.config.get("lora_configs")
                    high_model_kwargs = {
                        "model_path": self.high_noise_model_path,
                        "config": self.config,
                        "device": self.init_device,
                        "model_type": "wan2.2_moe_high_noise",
                    }
                    if not lora_opts:
                        high_noise_model = WanDistillModel(**high_model_kwargs)
                    else:
                        assert self.config.get("lora_dynamic_apply", False)
                        high_noise_model = build_wan_model_with_lora(WanModel, self.config, high_model_kwargs, lora_opts, model_type="high_noise_model")
                    high_noise_model.set_scheduler(self.scheduler)
                    self.model[0] = high_noise_model
                    self.model[0].infer(inputs)
                elif self.cur_model_index == 1:
                    lora_opts = self.config.get("lora_configs")
                    low_model_kwargs = {
                        "model_path": self.low_noise_model_path,
                        "config": self.config,
                        "device": self.init_device,
                        "model_type": "wan2.2_moe_low_noise",
                    }
                    if not lora_opts:
                        low_noise_model = WanDistillModel(**low_model_kwargs)
                    else:
                        assert self.config.get("lora_dynamic_apply", False)
                        low_noise_model = build_wan_model_with_lora(WanModel, self.config, low_model_kwargs, lora_opts, model_type="low_noise_model")
                    low_noise_model.set_scheduler(self.scheduler)
                    self.model[1] = low_noise_model
                    self.model[1].infer(inputs)

@RUNNER_REGISTER("wan2.2_moe_distill")
class Wan22MoeDistillRunner(WanDistillRunner):
    def __init__(self, cfg):
        super().__init__(cfg)

        # Determine high noise model path
        if self.config.get("dit_quantized", False) and self.config.get("high_noise_quantized_ckpt", None):
            self.high_noise_model_path = self.config["high_noise_quantized_ckpt"]
        elif self.config.get("high_noise_original_ckpt", None):
            self.high_noise_model_path = self.config["high_noise_original_ckpt"]
        else:
            self.high_noise_model_path = os.path.join(self.config["model_path"], "high_noise_model")
            if not os.path.isdir(self.high_noise_model_path):
                raise FileNotFoundError(f"High Noise Model does not find")

        # Determine low noise model path
        if self.config.get("dit_quantized", False) and self.config.get("low_noise_quantized_ckpt", None):
            self.low_noise_model_path = self.config["low_noise_quantized_ckpt"]
        elif not self.config.get("dit_quantized", False) and self.config.get("low_noise_original_ckpt", None):
            self.low_noise_model_path = self.config["low_noise_original_ckpt"]
        else:
            self.low_noise_model_path = os.path.join(self.config["model_path"], "low_noise_model")
            if not os.path.isdir(self.low_noise_model_path):
                raise FileNotFoundError(f"Low Noise Model does not find")

    def load_transformer(self):
        if not self.config.get("lazy_load", False) and not self.config.get("unload_modules", False):
            lora_opts = self.config.get("lora_configs")
            high_model_kwargs = {
                "model_path": self.high_noise_model_path,
                "config": self.config,
                "device": self.init_device,
                "model_type": "wan2.2_moe_high_noise",
            }
            low_model_kwargs = {
                "model_path": self.low_noise_model_path,
                "config": self.config,
                "device": self.init_device,
                "model_type": "wan2.2_moe_low_noise",
            }
            if not lora_opts:
                high_noise_model = WanDistillModel(**high_model_kwargs)
                low_noise_model = WanDistillModel(**low_model_kwargs)
            else:
                high_noise_model = build_wan_model_with_lora(WanModel, self.config, high_model_kwargs, lora_opts, model_type="high_noise_model")
                low_noise_model = build_wan_model_with_lora(WanModel, self.config, low_model_kwargs, lora_opts, model_type="low_noise_model")
            return MultiDistillModelStruct([high_noise_model, low_noise_model], self.config, self.config["boundary_step_index"])
        else:
            model_struct = MultiDistillModelStruct([None, None], self.config, self.config["boundary_step_index"])
            model_struct.low_noise_model_path = self.low_noise_model_path
            model_struct.high_noise_model_path = self.high_noise_model_path
            model_struct.init_device = self.init_device
            return model_struct

    def init_scheduler(self):
        if self.config["feature_caching"] == "NoCaching":
            self.scheduler = Wan22StepDistillScheduler(self.config)
        else:
            raise NotImplementedError(f"Unsupported feature_caching type: {self.config['feature_caching']}")

    def switch_lora(self, high_lora_path: str = None, high_lora_strength: float = 1.0, 
                   low_lora_path: str = None, low_lora_strength: float = 1.0):
        """
        Switch LoRA weights dynamically for Wan2.2 MoE Distill models.
        This method handles both high_noise_model and low_noise_model separately.
        Args:
            lora_path: Path to the LoRA safetensors file (for backward compatibility)
            strength: LoRA strength (default: 1.0) (for backward compatibility)
            high_lora_path: Path to the high_noise_model LoRA safetensors file
            high_lora_strength: High noise model LoRA strength (default: 1.0)
            low_lora_path: Path to the low_noise_model LoRA safetensors file
            low_lora_strength: Low noise model LoRA strength (default: 1.0)
        Returns:
            bool: True if LoRA was successfully switched, False otherwise
        """
        if not hasattr(self, "model") or self.model is None:
            logger.error("Model not loaded. Please load model first.")
            return False

        if high_lora_path is not None:
            if self.model.model[0] is not None and hasattr(self.model.model[0], "_update_lora"):
                logger.info(f"Switching high_noise_model LoRA to: {high_lora_path} with strength={high_lora_strength}")
                self.model.model[0]._update_lora(high_lora_path, high_lora_strength)

        if low_lora_path is not None:
            if self.model.model[1] is not None and hasattr(self.model.model[1], "_update_lora"):
                logger.info(f"Switching low_noise_model LoRA to: {low_lora_path} with strength={low_lora_strength}")
                self.model.model[1]._update_lora(low_lora_path, low_lora_strength)

        logger.info("LoRA switched successfully for Wan2.2 MoE Distill models")
        return True

# Modified version: renamed variables, reordered statements, changed literals/comments
from typing import Any, Callable, Dict, List, Literal, Optional, TypeVar, Union, get_type_hints, get_origin, get_args
import logging
from functools import wraps
from mindspeed.fsdp.utils.log import print_rank

logger = logging.getLogger(__name__)

def build_nested_dataclass_field(
    target_class: type,
    field_identifier: str,
    nested_structure: Dict[str, Any],
) -> None:
    # Generate class name based on field identifier
    inner_cls_name = f"{field_identifier.capitalize()}Structure"
    constructed_class = build_nested_dataclass(inner_cls_name, nested_structure)

    # Attach the new dataclass as a field with default factory
    setattr(target_class, field_identifier, field(default_factory=constructed_class))

    # Ensure __annotations__ exists and register the new field type
    if '__annotations__' not in target_class.__dict__:
        target_class.__annotations__ = {}
    target_class.__annotations__[field_identifier] = constructed_class

def build_nested_dataclass(cls_name: str, structure: Dict[str, Any]) -> type:
    field_definitions = {}
    type_annotations = {}

    for key, value in structure.items():
        if isinstance(value, dict):
            # Recursively create nested dataclasses for dictionary values
            sub_cls = build_nested_dataclass(f"{cls_name}_{key}", value)
            field_definitions[key] = field(default_factory=sub_cls)
            type_annotations[key] = sub_cls
        else:
            # Determine field type; use Any for None values
            inferred_type = type(value) if value is not None else Any

            # Handle container types (list/set) with default factories
            if inferred_type in (list, set):
                field_definitions[key] = field(default_factory=inferred_type)
            else:
                field_definitions[key] = field(default=value)

            type_annotations[key] = inferred_type

    # Dynamically construct the class and apply @dataclass decorator
    dynamic_class = type(cls_name, (), field_definitions)
    dynamic_class.__annotations__ = type_annotations
    return dataclass(dynamic_class)

def permit_extra_fields(cls):
    """
    Decorator: Enables dataclass to accept additional fields beyond its declared attributes.

    This wrapper modifies the original __init__ method to:
    1. Distinguish between recognized fields and unexpected ones
    2. Pass only known fields to the base dataclass constructor
    3. Log warnings and store unknown fields as dynamic attributes
    4. Maintain compatibility with __post_init__ if present

    Args:
        cls: The dataclass to enhance

    Returns:
        Updated dataclass with extended initialization behavior

    Example:
        @permit_extra_fields
        @dataclass
        class SampleConfig:
            lr: float = 0.001
            epochs: int = 10

        # Works even with undefined fields like 'optimizer'
        config = SampleConfig(lr=0.002, optimizer='Adam')
    """
    # Preserve reference to original dataclass __init__
    base_init = cls.__init__

    @wraps(base_init)
    def extended_init(self, *args, **kwargs):
        """
        Enhanced initializer supporting both standard and extra fields.

        Args:
            *args: Positional arguments (rarely used in dataclass init)
            **kwargs: Keyword arguments including both defined and extra fields
        """
        # Extract all declared field names from the dataclass
        known_field_names = {f.name for f in fields(cls)}

        # Partition kwargs into known vs. extra fields
        standard_kwargs = {}
        additional_kwargs = {}

        for param, val in kwargs.items():
            if param in known_field_names:
                standard_kwargs[param] = val
            else:
                # Log warning for unrecognized fields
                print_rank(logger.warning,
                    f"Parameter '{param}' is not part of {cls.__name__}. "
                    f"Adding as dynamic attribute."
                )
                additional_kwargs[param] = val

        # Initialize with only known fields using original logic
        base_init(self, *args, **standard_kwargs)

        # Ensure _extra_fields tracking exists
        if not hasattr(self, '_extra_fields'):
            self._extra_fields = {}

        def _propagate_values(target: Any, mapping: Dict[str, Any]) -> None:
            for k, v in mapping.items():
                if isinstance(v, dict):
                    child_obj = getattr(target, k)
                    _propagate_values(child_obj, v)
                else:
                    setattr(target, k, v)

        # Apply extra fields as attributes and record them
        for name, content in additional_kwargs.items():
            if isinstance(content, dict):
                build_nested_dataclass_field(self, name, content)
                inferred_type = get_type_hints(self)[name]
                instance = inferred_type()
                _propagate_values(instance, content)
                setattr(self, name, instance)
            else:
                setattr(self, name, content)
            self._extra_fields[name] = content

    cls.__init__ = extended_init
    return cls

def construct_from_dict(dataclass_type: type, source_data: Dict[str, Any]) -> Any:
    """
    Construct dataclass instance recursively from dictionary input.

    Args:
        dataclass_type: Target dataclass type
        source_data: Input dictionary containing field values

    Returns:
        Fully initialized dataclass object
    """
    if not is_dataclass(dataclass_type):
        return source_data

    try:
        type_hints = get_type_hints(dataclass_type)
    except Exception as e:
        raise RuntimeError(f"Could not retrieve type hints for {dataclass_type}: {e}") from e

    # Prepare dictionaries for standard and extra field values
    standard_values = {}
    extra_values = {}

    # Collect known field names
    known_fields = {f.name for f in fields(dataclass_type)}

    # Process each entry in the input dictionary
    for field_name, field_value in source_data.items():
        if field_name in known_fields:
            # Handle known fields
            field_annotation = type_hints[field_name]

            # If nested dataclass and value is dict, recurse
            if is_dataclass(field_annotation) and isinstance(field_value, dict):
                standard_values[field_name] = construct_from_dict(field_annotation, field_value)
            else:
                standard_values[field_name] = field_value
        else:
            # Handle unknown/extra fields
            extra_values[field_name] = field_value

    # Combine both categories and instantiate
    combined_kwargs = {**standard_values, **extra_values}
    return dataclass_type(**combined_kwargs)

# CLI tool for interacting with the OpenAlexandria API
import argparse
import json
import os
import sys
import urllib.parse
import urllib.request

DEFAULT_SERVER = "https://openalexandria.vercel.app"
DEFAULT_TOKEN = os.environ.get("OPENALEXANDRIA_API_KEY")

def get_base_url() -> str:
    return os.environ.get("OPENALEXANDRIA_BASE_URL", DEFAULT_SERVER).rstrip("/")

def make_request(method: str, endpoint: str, payload=None, token: str | None = None):
    body = None
    headers = {"Accept": "application/json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    if payload is not None:
        raw_data = json.dumps(payload).encode("utf-8")
        body = raw_data
        headers["Content-Type"] = "application/json; charset=utf-8"
    request = urllib.request.Request(endpoint, data=body, method=method, headers=headers)
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            content = response.read().decode("utf-8")
            if not content.strip():
                return {}
            return json.loads(content)
    except urllib.error.HTTPError as error:
        error_body = None
        try:
            error_body = error.read().decode("utf-8")
        except Exception:
            pass
        raise RuntimeError(f"HTTP {error.code} {error.reason}: {error_body or ''}".strip())

def fetch_wellknown(_args):
    url = get_base_url() + "/.well-known/openalexandria.json"
    return make_request("GET", url)

def perform_query(args):
    query_text = args.q
    limit = args.k
    query_string = urllib.parse.urlencode({"q": query_text, "k": str(limit)})
    url = get_base_url() + "/v1/query?" + query_string
    return make_request("GET", url)

def get_entry(args):
    entry_identifier = urllib.parse.quote(args.id, safe="")
    url = get_base_url() + f"/v1/entry/{entry_identifier}"
    return make_request("GET", url)

def retrieve_feed(args):
    parameters = {}
    if args.since:
        parameters["since"] = args.since
    query_part = ("?" + urllib.parse.urlencode(parameters)) if parameters else ""
    url = get_base_url() + "/v1/feed" + query_part
    return make_request("GET", url)

def check_identity(args):
    api_token = args.api_key or DEFAULT_TOKEN
    if not api_token:
        raise SystemExit("Missing API token. Set OPENALEXANDRIA_API_KEY or pass --api-key.")
    url = get_base_url() + "/v1/whoami"
    return make_request("GET", url, token=api_token)

def get_submission_status(args):
    api_token = args.api_key or DEFAULT_TOKEN
    # Submission status can be retrieved using submitter key; if not provided, attempt unauthenticated request (may fail)
    url = get_base_url() + f"/v1/submission/{urllib.parse.quote(args.id, safe='')}"
    return make_request("GET", url, token=api_token)

def send_submission(args):
    if args.file:
        with open(args.file, "r", encoding="utf-8") as file_handle:
            payload = json.load(file_handle)
    else:
        payload = json.load(sys.stdin)
    api_token = args.api_key or DEFAULT_TOKEN
    if not api_token:
        raise SystemExit("Missing API token. Set OPENALEXANDRIA_API_KEY or pass --api-key.")
    url = get_base_url() + "/v1/submit"
    return make_request("POST", url, payload=payload, token=api_token)

def main():
    parser = argparse.ArgumentParser(description="OpenAlexandria Protocol Command-Line Interface")
    subparsers = parser.add_subparsers(dest="command", required=True)

    sp = subparsers.add_parser("wellknown", help="Retrieve node discovery document")
    sp.set_defaults(func=fetch_wellknown)

    sp = subparsers.add_parser("query", help="Search for entries")
    sp.add_argument("q", help="Search query string")
    sp.add_argument("--k", type=int, default=5, help="Maximum number of results (default: 5)")
    sp.set_defaults(func=perform_query)

    sp = subparsers.add_parser("entry", help="Fetch a specific entry by identifier")
    sp.add_argument("id", help="Entry identifier")
    sp.set_defaults(func=get_entry)

    sp = subparsers.add_parser("feed", help="Retrieve activity feed")
    sp.add_argument("--since", help="Cursor from previous feed response", default=None)
    sp.set_defaults(func=retrieve_feed)

    sp = subparsers.add_parser("whoami", help="Validate API token and view usage limits")
    sp.add_argument("--api-key", dest="api_key", default=None, help="OpenAlexandria API token (or set OPENALEXANDRIA_API_KEY)")
    sp.set_defaults(func=check_identity)

    sp = subparsers.add_parser("submission", help="Check submission status and feedback")
    sp.add_argument("id", help="Submission identifier (sub_...)")
    sp.add_argument("--api-key", dest="api_key", default=None, help="OpenAlexandria API token (or set OPENALEXANDRIA_API_KEY)")
    sp.set_defaults(func=get_submission_status)

    sp = subparsers.add_parser("submit", help="Upload a data bundle")
    sp.add_argument("--file", help="JSON bundle file; if omitted, reads from stdin", default=None)
    sp.add_argument("--api-key", dest="api_key", default=None, help="OpenAlexandria API token (or set OPENALEXANDRIA_API_KEY)")
    sp.set_defaults(func=send_submission)

    arguments = parser.parse_args()
    result = arguments.func(arguments)
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

