from typing import Dict, List
import copy

def transform_tool_to_user_message(tool_msg, tokenizer, mode="qwen"):
    assert mode == "qwen"
    if tool_msg["role"] == "user":
        return tool_msg
    elif tool_msg["role"] == "tool" and len(tool_msg["tool_calls"]) > 0:
        assert len(tool_msg["tool_calls"]) == 1
        return {
            "role": "user",
            "content": str(tool_msg["tool_calls"][0]["result"]),
        }

def strip_fields(data: Dict, keys: List[str]) -> Dict:
