    for key in keys:
        data.pop(key.strip(), None)
    return data

# Validate pipeline execution status based on memory directory contents
import json
import sys
import os
import glob
from datetime import datetime, date, timedelta, timezone


def is_file_modified_after(filepath, reference_time):
    """Determine if the file's modification time is later than the reference time."""
    if not os.path.exists(filepath):
        return False
    mtime = datetime.fromtimestamp(os.path.getmtime(filepath), tz=timezone.utc)
    return mtime > reference_time


def get_last_modification(filepath):
    """Retrieve a human-readable timestamp of the last modification."""
    if not os.path.exists(filepath):
        return 'DOES NOT EXIST'
    mtime = datetime.fromtimestamp(os.path.getmtime(filepath), tz=timezone.utc)
    return mtime.isoformat()


def tally_significant_entries(jsonl_filepath, target_significance):
    """Count entries in a JSONL file matching a specific significance level."""
    tally = 0
    if not os.path.exists(jsonl_filepath):
        return 0
    with open(jsonl_filepath, encoding='utf-8', errors='replace') as stream:
        for record in stream:
            record = record.strip()
            if not record:
                continue
            try:
                item = json.loads(record)
                if item.get('significance') == target_significance:
                    tally += 1
            except json.JSONDecodeError:
                continue
    return tally


def tally_unreflected_entries(jsonl_filepath):
    """Count entries where reflected is explicitly set to false."""
    tally = 0
    if not os.path.exists(jsonl_filepath):
        return 0
    with open(jsonl_filepath, encoding='utf-8', errors='replace') as stream:
        for record in stream:
            record = record.strip()
            if not record:
                continue
            try:
                item = json.loads(record)
                if item.get('reflected') is False:
                    tally += 1
            except json.JSONDecodeError:
                continue
    return tally


def verify(memory_directory, minutes_threshold=30):
    problems = []
    alerts = []
    observations = {}

    current_time = datetime.now(timezone.utc)
    threshold_time = current_time - timedelta(minutes=minutes_threshold)
    current_date_str = date.today().isoformat()

    # ========================================
    # 1. Verify experience file exists and contains data
    # ========================================
    experiences_path = os.path.join(memory_directory, 'experiences')
    daily_file = os.path.join(experiences_path, f'{current_date_str}.jsonl')

    if not os.path.exists(daily_file):
        problems.append({
            'validation': 'experience_file',
            'description': f"Today's experience file does not exist: {daily_file}. "
                           f"If the agent ran a heartbeat, it should have logged something."
        })
        observations['experience_file'] = 'MISSING'
    else:
        observations['experience_file'] = get_last_modification(daily_file)
        if not is_file_modified_after(daily_file, threshold_time):
            alerts.append({
                'validation': 'experience_file',
                'description': f"Experience file exists but wasn't modified in the last {minutes_threshold}m. "
                               f"Last modified: {get_last_modification(daily_file)}"
            })

    # ========================================
    # 2. Check promotion of notable/pivotal items to significant.jsonl
    # ========================================
    important_file = os.path.join(memory_directory, 'significant', 'significant.jsonl')
    notable_today = tally_significant_entries(daily_file, 'notable') if os.path.exists(daily_file) else 0
    pivotal_today = tally_significant_entries(daily_file, 'pivotal') if os.path.exists(daily_file) else 0
    observations['notable_today'] = notable_today
    observations['pivotal_today'] = pivotal_today

    if (notable_today + pivotal_today) > 0 and not os.path.exists(important_file):
        problems.append({
            'validation': 'significant_promotion',
            'description': f"Found {notable_today} notable + {pivotal_today} pivotal experiences today "
                           f"but significant.jsonl does not exist. Notable/pivotal MUST be promoted."
        })

    # ========================================
    # 3. Verify reflection files exist when needed
    # ========================================
    reflections_path = os.path.join(memory_directory, 'reflections')
    unreflected_notable_count = 0
    unreflected_pivotal_count = 0

    # Scan all experience files, not just today's
    if os.path.isdir(experiences_path):
        for exp_file in glob.glob(os.path.join(experiences_path, '*.jsonl')):
            if os.path.exists(exp_file):
                with open(exp_file, encoding='utf-8', errors='replace') as stream:
                    for record in stream:
                        record = record.strip()
                        if not record:
                            continue
                        try:
                            item = json.loads(record)
                            if item.get('reflected') is False:
                                sig = item.get('significance', '')
                                if sig == 'notable':
                                    unreflected_notable_count += 1
                                elif sig == 'pivotal':
                                    unreflected_pivotal_count += 1
                        except json.JSONDecodeError:
                            continue

    observations['unreflected_notable'] = unreflected_notable_count
    observations['unreflected_pivotal'] = unreflected_pivotal_count

    if unreflected_pivotal_count > 0:
        problems.append({
            'validation': 'pivotal_reflection',
            'description': f"{unreflected_pivotal_count} pivotal experience(s) are unreflected. "
                           f"Pivotal experiences require IMMEDIATE reflection."
        })

    # Check if any reflection files exist at all
    if os.path.isdir(reflections_path):
        reflection_files = glob.glob(os.path.join(reflections_path, 'REF-*.json'))
        observations['total_reflection_files'] = len(reflection_files)
        recent_refs = [f for f in reflection_files if is_file_modified_after(f, threshold_time)]
        observations['recent_reflection_files'] = len(recent_refs)
    else:
        observations['total_reflection_files'] = 0
        observations['recent_reflection_files'] = 0
        if (notable_today + pivotal_today) > 0:
            alerts.append({
                'validation': 'reflection_dir',
                'description': 'Reflections directory does not exist but notable/pivotal experiences were logged'
            })

    # ========================================
    # 4. Confirm state file has been updated
    # ========================================
    state_file_path = os.path.join(memory_directory, 'evoclaw-state.json')
    if not os.path.exists(state_file_path):
        problems.append({
            'validation': 'state_file',
            'description': f"State file does not exist: {state_file_path}. Pipeline must update state every heartbeat."
        })
        observations['state_file'] = 'MISSING'
    else:
        observations['state_file'] = get_last_modification(state_file_path)
        if not is_file_modified_after(state_file_path, threshold_time):
            alerts.append({
                'validation': 'state_file',
                'description': f"State file wasn't modified in the last {minutes_threshold}m. "
                               f"Pipeline should update it every heartbeat. "
                               f"Last modified: {get_last_modification(state_file_path)}"
            })

    # ========================================
    # 5. If state indicates pending proposals, verify file existence
    # ========================================
    if os.path.exists(state_file_path):
        try:
            with open(state_file_path) as stream:
                system_state = json.load(stream)
            pending_proposals = system_state.get('pending_proposals_count', 0)
            if pending_proposals > 0:
                pending_file_path = os.path.join(memory_directory, 'proposals', 'pending.jsonl')
                if not os.path.exists(pending_file_path):
                    problems.append({
                        'validation': 'pending_proposals',
                        'description': f"State claims {pending_proposals} pending proposals but pending.jsonl doesn't exist"
                    })
            observations['claimed_pending'] = pending_proposals
        except (json.JSONDecodeError, IOError):
            pass

    # ========================================
    # Overall evaluation
    # ========================================
    outcome = 'FAIL' if problems else 'PASS'
    return {
        'status': outcome,
        'directory': memory_directory,
        'verified_at': current_time.isoformat(),
        'threshold_minutes': minutes_threshold,
        'problems': problems,
        'alerts': alerts,
        'observations': observations
    }


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: check_pipeline_ran.py <memory_dir> [--since-minutes 30]', file=sys.stderr)
        sys.exit(2)

    memory_directory = sys.argv[1]
    time_window = 30

    if '--since-minutes' in sys.argv:
        position = sys.argv.index('--since-minutes')
        if position + 1 < len(sys.argv):
            time_window = int(sys.argv[position + 1])

    validation_result = verify(memory_directory, time_window)
    print(json.dumps(validation_result, indent=2))
    sys.exit(0 if validation_result['status'] == 'PASS' else 1)

# CPU binding logic for Ascend devices with NUMA awareness and topology-aware affinity
import os
import platform
import shutil
import subprocess
from collections import defaultdict
import psutil
from vllm.logger import logger
from vllm_ascend.utils import AscendDeviceType, get_ascend_device_type

MASK_WIDTH = 32  # Number of bits in a CPU affinity mask group  
MIN_CORES_PER_NPU = 5  # 2(IRQ) + 1(main, at least 1 CPU) + 1(acl) + 1(release) = 5 CPUs per NPU  
ALLOWED_CPU_FILE = "/proc/self/status"  
ASCEND_VISIBLE_DEVICES_VAR = os.getenv("ASCEND_RT_VISIBLE_DEVICES")  
TOPO_AFFINITY_STRATEGY = "topo_affinity"
GLOBAL_SLICE_STRATEGY = "global_slice"
DEVICE_POLICY: dict["AscendDeviceType", str] = {
    AscendDeviceType.A2: TOPO_AFFINITY_STRATEGY,
    AscendDeviceType.A3: GLOBAL_SLICE_STRATEGY,
    AscendDeviceType._310P: TOPO_AFFINITY_STRATEGY,
}

def is_arm_processor() -> bool:
    cpu_arch = platform.machine().lower()
    if cpu_arch in {"x86_64", "amd64", "i386", "i686"}:
        return False
    if cpu_arch in {"aarch64", "arm64"} or cpu_arch.startswith("arm"):
        return True
    logger.warning(f"Unknown CPU architecture '{cpu_arch}', CPU binding will be disabled.")
    return False

def run_shell_command(cmd_args: list[str]) -> tuple[str, int]:
    with subprocess.Popen(cmd_args, shell=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE) as proc:
        output_data, _ = proc.communicate(timeout=1000)
    return output_data.decode(), proc.returncode

class HardwareInfo:
    def __init__(self):
        self.npu_topology_info: dict[str, dict[str, str]] = self.fetch_npu_topology()
        self.permitted_cores: list[int] = self.extract_permitted_cores()
        self.active_npu_ids: list[int] = self.identify_active_npus()
        self.npu_core_affinity: dict[int, list[int]] = self.parse_topo_affinity_map()
        self.all_virtual_npus: list[int] = self.collect_all_virtual_npus()
        self.total_virtual_npus: int = len(self.all_virtual_npus)

    @staticmethod
    def expand_cpu_ranges(range_str: str) -> list[int]:
        core_list: list[int] = []
        for segment in range_str.split(","):
            if "-" in segment:
                low, high = map(int, segment.split("-"))
                core_list.extend(range(low, high + 1))
            else:
                core_list.append(int(segment))
        return core_list

    def collect_all_virtual_npus(self) -> list[int]:
        """Gather all virtual NPU identifiers from the topology mapping.
        self.npu_topology_info maps board_id (A3) or npu_id (A2) to per-chip info.
        Each per-chip map uses chip_id as key and virtual NPU ID string as value.
        """
        virtual_ids: set[int] = set()
        for _, chip_info in self.npu_topology_info.items():
            for _, vid_str in chip_info.items():
                if vid_str and vid_str.isdigit():
                    virtual_ids.add(int(vid_str))
        return sorted(virtual_ids)

    @staticmethod
    def fetch_npu_topology() -> dict[str, dict[str, str]]:
        topo_data: dict[str, dict[str, str]] = {}
        npu_output, _ = run_shell_command(["npu-smi", "info", "-m"])
        lines = npu_output.strip().split("\n")[1:]
        for line in lines:
            parts = line.strip().split()
            if len(parts) < 3:
                continue
            board_id, chip_id, chip_logic_id = parts[:3]
            if not chip_logic_id.isdigit():
                continue
            if board_id not in topo_data:
                topo_data[board_id] = {}
            topo_data[board_id][chip_id] = chip_logic_id
        return topo_data

    def identify_active_npus(self) -> list[int]:
        npu_status, _ = run_shell_command(["npu-smi", "info"])
        in_process_section = False
        active_set = set()
        for line in npu_status.splitlines():
            line = line.strip()
            if line.startswith("| NPU") and "Process id" in line:
                in_process_section = True
                continue
            if not in_process_section:
                continue
            if line.startswith("| "):
                fields = [f.strip() for f in line.strip("|").split("|")]
                if len(fields) < 2:
                    continue
                board_part = fields[0].split()
                if len(board_part) < 2:
                    continue
                board_id, chip_id = board_part[0], board_part[1]
                if not board_id.isdigit() or not chip_id.isdigit():
                    continue
                chip_logic_id = self.npu_topology_info.get(board_id, {}).get(chip_id)
                if not chip_logic_id or not chip_logic_id.isdigit():
                    raise RuntimeError("Failed to retrieve correct chip_logic_id from 'npu-smi info -m'.")
                active_set.add(int(chip_logic_id))
        if ASCEND_VISIBLE_DEVICES_VAR:
            visible_devices = [int(x) for x in ASCEND_VISIBLE_DEVICES_VAR.split(",")]
            active_set &= set(visible_devices)
        if not active_set:
            raise RuntimeError("Unable to detect active NPU information.")
        return sorted(active_set)

    def extract_permitted_cores(self) -> list[int]:
        if not os.path.exists(ALLOWED_CPU_FILE):
            return []
        with open(ALLOWED_CPU_FILE) as file_obj:
            for line in file_obj:
                if line.startswith("Cpus_allowed_list"):
                    return self.expand_cpu_ranges(line.split()[1])
        raise RuntimeError("Could not locate 'Cpus_allowed_list' in '/proc/self/status'.")

    def parse_topo_affinity_map(self) -> dict[int, list[int]]:
        chip_index = 0
        affinity_map: dict[int, list[int]] = {}
        topo_output, _ = run_shell_command(["npu-smi", "info", "-t", "topo"])
        for line in topo_output.splitlines():
            if line.startswith("NPU"):
                tokens = line.split()
                last_token = tokens[-1]
                if last_token != "Affinity":
                    affinity_map[chip_index] = self.expand_cpu_ranges(last_token)
                chip_index += 1
        return affinity_map

class CoreManager:
    def __init__(self, process_rank: int):
        self.process_rank = process_rank
        self.hardware_info: HardwareInfo = HardwareInfo()
        self.cpu_numa_mapping: dict[int, int] = {}
        self.numa_to_core_group: dict[int, list[int]] = defaultdict(list)
        self.npu_core_pool: dict[int, list[int]] = {}
        self.main_thread_cores: dict[int, list[int]] = {}
        self.acl_thread_cores: dict[int, list[int]] = {}
        self.release_thread_cores: dict[int, list[int]] = {}

    @staticmethod
    def core_to_bitmask(core_id: int) -> str:
        group_index = core_id // MASK_WIDTH
        bit_position = core_id % MASK_WIDTH
        bitmask_value = 1 << bit_position
        hex_mask = f"{bitmask_value:08x}"
        for _ in range(1, group_index + 1):
            hex_mask = f"{hex_mask},{'0' * (MASK_WIDTH // 4)}"
        return hex_mask

    @staticmethod
    def build_thread_mapping(thread_output: str) -> dict[str, dict[str, list[str]]]:
        thread_map: dict[str, dict[str, list[str]]] = {}
        for line in thread_output.splitlines():
            tokens = line.split()
            if len(tokens) < 2:
                continue
            parent_pid, child_pid = tokens[0], tokens[1]
            if "acl_thread" in line:
                thread_key = "acl_thread"
            elif "release_thread" in line:
                thread_key = "release_thread"
            else:
                continue
            if parent_pid not in thread_map:
                thread_map[parent_pid] = {"acl_thread": [], "release_thread": []}
            thread_map[parent_pid][thread_key].append(child_pid)
        return thread_map

    @staticmethod
    def apply_binding(pid: str, cores: list[int], include_sub_threads: bool) -> None:
        if cores:
            core_string = ",".join(map(str, cores))
            if include_sub_threads:
                result, status = run_shell_command(["taskset", "-acp", core_string, pid])
            else:
                result, status = run_shell_command(["taskset", "-cp", core_string, pid])
            if status != 0:
                raise RuntimeError(f"Failed to bind {pid} to CPU {core_string}.")

    def balanced_partition(self, groups: dict[str, list[int]]) -> dict[int, list[int]]:
        assignment: dict[int, list[int]] = {}
        for label, npu_group in groups.items():
            available_cores = sorted(self.npu_core_pool[npu_group[0]])
            cores_per_npu = len(available_cores) // len(npu_group)
            for idx, npu in enumerate(npu_group):
                start_pos = idx * cores_per_npu
                end_pos = (idx + 1) * cores_per_npu if idx < len(npu_group) - 1 else len(available_cores)
                assignment[npu] = available_cores[start_pos:end_pos]
        return assignment

    def extend_numa_domain(self, core_list: list[int]) -> list[int]:
        if not core_list:
            return []
        numa_nodes = {self.cpu_numa_mapping[c] for c in core_list}
        if len(numa_nodes) != 1:
            return core_list
        current_node = list(numa_nodes)[0]
        next_node = (current_node + 1) % len(self.numa_to_core_group)
        extended_list = core_list[:]
        for core_id in self.numa_to_core_group[next_node]:
            if core_id in self.hardware_info.permitted_cores:
                extended_list.append(core_id)
        return sorted(set(extended_list))

    def construct_cpu_numa_mapping(self) -> None:
        numa_output, _ = run_shell_command(["lscpu", "-e=CPU,NODE"])
        for line in numa_output.splitlines():
            line = line.strip()
            if not line or not line[0].isdigit():
                continue
            cpu_part, node_part = line.split()
            cpu_id = int(cpu_part)
            node_id = int(node_part)
            self.cpu_numa_mapping[cpu_id] = node_id
            self.numa_to_core_group[node_id].append(cpu_id)
        if len(self.numa_to_core_group) == 0:
            raise RuntimeError("lscpu command returned no NUMA node data. Please verify!")

    def build_global_slice_pool(self) -> None:
        """
        Construct per-NPU CPU pools using global slicing over permitted_cores.
        Rationale:
          - Multiple processes/DP groups may share identical cpusets.
          - Independent slicing by visible NPUs leads to overlapping CPU ranges.
          - Global slicing ensures deterministic, non-overlapping CPU partitions per logical NPU id.
        Notes:
          - Does NOT depend on npu-smi topo affinity.
          - NUMA locality only when CPU numbering aligns with NUMA layout.
          - Requires per-NPU slice size >= 5 (IRQ(2) + main(>=1) + acl(1) + release(1)).
        """
        active_npus = list(self.hardware_info.active_npu_ids)
        if not active_npus:
            return
        allowed_cores = sorted(set(self.hardware_info.permitted_cores))
        total_cores = len(allowed_cores)
        if total_cores == 0:
            return
        # Prefer topology mapping (npu-smi info -m), fallback to topo keys, then visible list
        if self.hardware_info.total_virtual_npus > 0:
            total_npus = self.hardware_info.total_virtual_npus
        elif self.hardware_info.npu_core_affinity:
            total_npus = len(self.hardware_info.npu_core_affinity)
        else:
            total_npus = len(active_npus)
        if total_npus <= 0:
            return
        # Compute global per-NPU slicing
        base_slice = total_cores // total_npus
        remainder = total_cores % total_npus
        logger.debug(
            f"[cpu_global_slice] rank:{self.process_rank} ASCEND_RT_VISIBLE_DEVICES={ASCEND_VISIBLE_DEVICES_VAR} "
            f"active_npu_ids:{active_npus} total_npus:{total_npus} allowed_cores:{total_cores} "
            f"base:{base_slice} remainder:{remainder} allowed_cores_head:{allowed_cores[:16]} allowed_cores_tail:{allowed_cores[-16:]}"
        )
        # Enforce per-NPU slice length >= MIN_CORES_PER_NPU.
        if base_slice < MIN_CORES_PER_NPU:
            raise RuntimeError(
                "Insufficient CPUs for binding with IRQ/ACL/REL reservations: "
                f"total_allowed={total_cores}, total_npus={total_npus}, "
                f"min_per_npu={base_slice} (<{MIN_CORES_PER_NPU}). "
                f"Need at least {total_npus * MIN_CORES_PER_NPU} CPUs in cpuset."
            )

        def _assign_for_npu(global_npu_idx: int) -> list[int]:
            start_offset = global_npu_idx * base_slice + (global_npu_idx if global_npu_idx < remainder else remainder)
            take_count = base_slice + (1 if global_npu_idx < remainder else 0)
            end_offset = start_offset + take_count
            return allowed_cores[start_offset:end_offset]

        for npu_id in active_npus:
            if npu_id < 0 or npu_id >= total_npus:
                raise RuntimeError(f"Invalid NPU id {npu_id}, total_npus={total_npus}.")
            assigned_cores = _assign_for_npu(npu_id)
            if len(assigned_cores) < MIN_CORES_PER_NPU:
                raise RuntimeError(
                    f"NPU{npu_id} received too few cores: {len(assigned_cores)} (<5). "
                    f"total_allowed={total_cores}, total_npus={total_npus}, base={base_slice}, remainder={remainder}"
                )
            self.npu_core_pool[npu_id] = assigned_cores

    @staticmethod
    def determine_binding_strategy() -> str:
        device_model = get_ascend_device_type()
        return DEVICE_POLICY.get(device_model, TOPO_AFFINITY_STRATEGY)

    def build_core_pools(self) -> None:
        self.construct_cpu_numa_mapping()
        strategy = self.determine_binding_strategy()
        logger.info(f"[cpu_bind_mode] strategy={strategy} rank={self.process_rank} visible_npus={self.hardware_info.active_npu_ids}")
        if strategy == GLOBAL_SLICE_STRATEGY:
            self.build_global_slice_pool()
            return
        # topo_affinity mode
        if not self.hardware_info.npu_core_affinity:
            logger.warning("NPU topology affinity not found, fallback to global-slice CPU binding.")
            self.build_global_slice_pool()
            return
        for npu_id in self.hardware_info.active_npu_ids:
            candidate_cores = [
                core for core in self.hardware_info.npu_core_affinity.get(npu_id, []) if core in self.hardware_info.permitted_cores
            ]
            if not candidate_cores:
                raise RuntimeError("CPUs in 'Cpus_allowed_list' conflict with NUMA affinity.")
            extended_cores = self.extend_numa_domain(candidate_cores)
            self.npu_core_pool[npu_id] = extended_cores
        cluster_groups = defaultdict(list)
        for npu_id, core_list in self.npu_core_pool.items():
            cluster_groups[str(core_list)].append(npu_id)
        final_assignment: dict[int, list[int]] = {}
        for label, npu_cluster in cluster_groups.items():
            if len(npu_cluster) == 1:
                final_assignment[npu_cluster[0]] = self.npu_core_pool[npu_cluster[0]]
            else:
                final_assignment.update(self.balanced_partition({label: npu_cluster}))
        self.npu_core_pool = final_assignment

    def assign_resources(self) -> None:
        for npu_id, core_pool in self.npu_core_pool.items():
            if len(core_pool) >= MIN_CORES_PER_NPU:
                main_cores = core_pool[2:-2]
                acl_cores = [core_pool[-2]]
                rel_cores = [core_pool[-1]]
            else:
                raise RuntimeError(
                    f"Insufficient CPU cores. Each NPU requires at least {MIN_CORES_PER_NPU} cores."
                )
            self.main_thread_cores[npu_id] = main_cores
            self.acl_thread_cores[npu_id] = acl_cores
            self.release_thread_cores[npu_id] = rel_cores

    def display_plan(self) -> None:
        logger.info("The CPU allocation plan is as follows:")
        target_npu = self.hardware_info.active_npu_ids[self.process_rank]
        main_cores_str = " ".join(map(str, self.main_thread_cores[target_npu]))
        acl_cores_str = " ".join(map(str, self.acl_thread_cores[target_npu]))
        rel_cores_str = str(self.release_thread_cores[target_npu]) if self.release_thread_cores[target_npu] else ""
        logger.info(f"NPU{target_npu}: main=[{main_cores_str}]  acl=[{acl_cores_str}]  release=[{rel_cores_str}]")

    def bind_memory_pages(self, pid: str, npu_id: int) -> None:
        def _locate_npu_numa(npu_identifier: int) -> int | None:
            core_pool = self.npu_core_pool.get(npu_identifier, [])
            if not core_pool:
                return None
            anchor_core = core_pool[0]
            return self.cpu_numa_mapping.get(anchor_core)
        if not shutil.which("migratepages"):
            logger.info("The 'migratepages' command is unavailable, skipping memory binding.")
            return
        target_numa = _locate_npu_numa(npu_id)
        if target_numa is None:
            logger.warning(f"[memory_migration] rank:{self.process_rank} -> NPU{npu_id} has no core pool, skip memory binding.")
            return
        all_numa_nodes = sorted(self.numa_to_core_group.keys())
        if target_numa not in all_numa_nodes:
            logger.warning(f"[memory_migration] NPU:{npu_id} -> NUMA {target_numa} not found, skip memory binding.")
            return
        logger.info(f"[memory_migration] NPU:{npu_id} -> NUMA [{target_numa}]")
        run_shell_command(
            [
                "migratepages",
                pid,
                ",".join(map(str, all_numa_nodes)),
                str(target_numa),
            ]
        )

    def bind_execution_threads(self) -> None:
        thread_info, _ = run_shell_command(["ps", "-Te"])
        thread_mapping = self.build_thread_mapping(thread_info)
        main_process_pid = str(psutil.Process().pid)
        target_npu = self.hardware_info.active_npu_ids[self.process_rank]
        self.apply_binding(main_process_pid, self.main_thread_cores[target_npu], True)
        for acl_tid in thread_mapping.get(main_process_pid, {}).get("acl_thread", []):
            self.apply_binding(acl_tid, self.acl_thread_cores[target_npu], False)
            self.bind_memory_pages(acl_tid, target_npu)
        for rel_tid in thread_mapping.get(main_process_pid, {}).get("release_thread", []):
            self.apply_binding(rel_tid, self.release_thread_cores[target_npu], False)

    def bind_interrupt_lines(self) -> None:
        if not os.access("/proc/irq", os.W_OK):
            return
        target_npu = self.hardware_info.active_npu_ids[self.process_rank]
        if target_npu not in self.npu_core_pool:
            logger.warning(f"[irq_binding] rank:{self.process_rank} -> NPU{target_npu} has no core pool, skip irq binding.")
            return
        if shutil.which("systemctl"):
            systemctl_status, _ = run_shell_command(["systemctl", "list-unit-files"])
            if "irqbalance.service" in systemctl_status:
                _, systemctl_code = run_shell_command(["systemctl", "is-active", "--quiet", "irqbalance"])
                if systemctl_code == 0:
                    logger.warning(
                        "The irqbalance service is active and has been stopped. "
                        "You can run systemctl start irqbalance to re-enable it."
                    )
                    run_shell_command(["systemctl", "stop", "irqbalance"])
        sq_interrupts = []
        with open("/proc/interrupts") as interrupt_file:
            for entry in interrupt_file:
                if "sq_send_trigger_irq" in entry:
                    irq_number = entry.split(":")[0].strip()
                    sq_interrupts.append(irq_number)
        npu_id = target_npu
        assigned_cores = self.npu_core_pool[npu_id]
        if len(assigned_cores) < 2:
            logger.warning(f"[irq_binding] NPU{npu_id} core pool too small (<2), skip irq binding.")
            return
        irq_core_0, irq_core_1 = assigned_cores[0], assigned_cores[1]  # Reserved for IRQ binding
        pci_address = ""
        device_type = get_ascend_device_type()
        if device_type == AscendDeviceType.A3:
            # A3: logical npu_id = card_id*2 + chip_id
            card_number = npu_id // 2
            chip_number = npu_id % 2
            board_info, _ = run_shell_command(["npu-smi", "info", "-t", "board", "-i", str(card_number), "-c", str(chip_number)])
        else:
            # A2 / others: logical npu_id is card id
            board_info, _ = run_shell_command(["npu-smi", "info", "-t", "board", "-i", str(npu_id)])
        for info_line in board_info.splitlines():
            if "PCIe Bus Info" in info_line:
                pci_address = info_line.split()[-1].lower()
                break
        if not pci_address:
            logger.warning(f"Unable to find PCI address for NPU{npu_id}.")
            return
        try:
            msi_interrupts = sorted(os.listdir(f"/sys/bus/pci/devices/{pci_address}/msi_irqs/"), key=lambda x: int(x))
        except FileNotFoundError:
            logger.warning(f"Directory /sys/bus/pci/devices/{pci_address}/msi_irqs/ not found.")
            return
        sq_irq_id, cq_irq_id = "", ""
        for irq in sq_interrupts:
            if irq in msi_interrupts:
                sq_irq_id = irq
                cq_irq_id = str(int(irq) + 1)
                break
        if not sq_irq_id:
            logger.warning(f"Could not locate sq_send_trigger_irq for NPU{npu_id}.")
            return
        logger.info(
            f"NPU{npu_id}(PCI {pci_address}): sq_send_trigger_irq IRQ_ID={sq_irq_id} -> CPU{irq_core_0}, "
            f"cq_update_irq IRQ_ID={cq_irq_id} -> CPU{irq_core_1}"
        )
        with open(f"/proc/irq/{sq_irq_id}/smp_affinity", "w") as affinity_file:
            affinity_file.write(self.core_to_bitmask(irq_core_0))
        with open(f"/proc/irq/{cq_irq_id}/smp_affinity", "w") as cq_affinity_file:
            cq_affinity_file.write(self.core_to_bitmask(irq_core_1))

    def execute_full_binding(self) -> None:
        self.build_core_pools()
        self.assign_resources()
        self.display_plan()
        self.bind_execution_threads()
        self.bind_interrupt_lines()

def perform_cpu_binding(process_rank: int) -> None:
    if not is_arm_processor():
        logger.info("CPU binding skipped: non-ARM CPU detected.")
        return
    binder = CoreManager(process_rank)
    binder.execute_full_binding()

# Modified version with renamed variables, changed literals, and reordered statements
import itertools
import logging
import sys
import time
from typing import IO, Generator, Optional
from pip._internal.utils.compat import WINDOWS
from pip._internal.utils.logging import get_indentation

logger = logging.getLogger(__name__)

class SpinnerBase:
    def spin(self) -> None:
        raise NotImplementedError()

    def finish(self, status_message: str) -> None:
        raise NotImplementedError()

class AnimatedSpinner(SpinnerBase):
    def __init__(
        self,
        display_text: str,
        output_stream: Optional[IO[str]] = None,
        animation_sequence: str = "|/-\\",
        update_frequency_seconds: float = 0.125,
    ):
        self._display_text = display_text
        if output_stream is None:
            output_stream = sys.stdout
        self._output_stream = output_stream
        self._update_limiter = ThrottleController(update_frequency_seconds)
        self._is_complete = False
        self._animation_generator = itertools.cycle(animation_sequence)
        indent = " " * get_indentation()
        self._output_stream.write(indent + self._display_text + " ... ")
        self._current_width = 0

    def _render_status(self, status: str) -> None:
        assert not self._is_complete
        # Clear previous content using backspaces
        clear_sequence = "\b" * self._current_width
        self._output_stream.write(clear_sequence + " " * self._current_width + clear_sequence)
        # Write new status
        self._output_stream.write(status)
        self._current_width = len(status)
        self._output_stream.flush()
        self._update_limiter.trigger()

    def spin(self) -> None:
        if self._is_complete:
            return
        if not self._update_limiter.is_ready():
            return
        self._render_status(next(self._animation_generator))

    def finish(self, status_message: str) -> None:
        if self._is_complete:
            return
        self._render_status(status_message)
        self._output_stream.write("\n")
        self._output_stream.flush()
        self._is_complete = True

class SilentSpinner(SpinnerBase):
    def __init__(self, label: str, check_interval_seconds: float = 60.0) -> None:
        self._label = label
        self._is_complete = False
        self._check_controller = ThrottleController(check_interval_seconds)
        self._log("initialization complete")

    def _log(self, event: str) -> None:
        assert not self._is_complete
        self._check_controller.trigger()
        logger.info("%s: %s", self._label, event)

    def spin(self) -> None:
        if self._is_complete:
            return
        if not self._check_controller.is_ready():
            return
        self._log("processing still in progress...")

    def finish(self, final_event: str) -> None:
        if self._is_complete:
            return
        self._log(f"completed with result '{final_event}'")
        self._is_complete = True

class ThrottleController:
    def __init__(self, minimum_delay_seconds: float) -> None:
        self._minimum_delay_seconds = minimum_delay_seconds
        self._last_trigger_time: float = 0

    def is_ready(self) -> bool:
        current_time = time.time()
        elapsed = current_time - self._last_trigger_time
        return elapsed >= self._minimum_delay_seconds

    def trigger(self) -> None:
        self._last_trigger_time = time.time()

@contextlib.contextmanager
def spinner_context(message: str) -> Generator[SpinnerBase, None, None]:
    # Determine spinner type based on terminal capability and log level
    if sys.stdout.isatty() and logger.getEffectiveLevel() <= logging.INFO:
        active_spinner: SpinnerBase = AnimatedSpinner(message)
    else:
        active_spinner = SilentSpinner(message)

    try:
        with cursor_visibility_control(sys.stdout):
            yield active_spinner
    except KeyboardInterrupt:
        active_spinner.finish("operation cancelled")
        raise
    except Exception:
        active_spinner.finish("operation failed")
        raise
    else:
        active_spinner.finish("operation succeeded")

HIDE_CURSOR_CODE = "\x1b[?25l"
SHOW_CURSOR_CODE = "\x1b[?25h"

@contextlib.contextmanager
def cursor_visibility_control(stream: IO[str]) -> Generator[None, None, None]:
    # Skip cursor control on Windows platforms
    if WINDOWS:
        yield
    # Skip cursor control for non-TTY outputs or quiet mode
    elif not stream.isatty() or logger.getEffectiveLevel() > logging.INFO:
        yield
    else:
        stream.write(HIDE_CURSOR_CODE)
        try:
            yield
        finally:
            stream.write(SHOW_CURSOR_CODE)

import jax.numpy as jnp
from beartype import beartype
from jaxtyping import jaxtyped
from ..tree_util import is_shape_leaf
from ..typing import (
    Any,
    ArrayData,
    ArrayDataShape,
    Data,
    DataShape,
    HyperParams,
    ModuleCallable,
    Params,
    State,
    Tuple,
)
from .basemodule import BaseModule

class Reshape(BaseModule):
    """
    Module that reshapes the input array to a specified shape. Ignores the
    batch dimension.
    """
    __version__: str = "0.0.0"

    def __init__(self, target_shape: DataShape = None) -> None:
        """
        Initialize a ``Reshape`` module.
        Parameters
        ----------
        target_shape
            The target shape to reshape the input to, by default None.
            If None, the input shape will remain unchanged.
            Does not include the batch dimension. If the input to the module is
            a PyTree, then ``target_shape`` should be a PyTree of matching structure.
            Any ``None`` values in the PyTree will leave the corresponding leaf
            arrays unchanged.
        Examples
        --------
        .. code-block:: python
            # Prepare to accept only bare array data (no PyTrees) and reshape
            # to (2, 3)
            reshape_module = Reshape(target_shape=(2, 3))
            # Prepare to accept a PyTree of arrays with structure [*, (*, *)]
            # and reshape the first leaf to (2, 3), leave the second leaf
            # unchanged, and flatten the final leaf
            reshape_module = Reshape(target_shape=[(2, 3), (None, (-1,))])
        """
        # validate target_shape
        # unless it is entirely an iterable of ints, none of the elements can
        # be ints
        if target_shape is None:
            self.target_shape = target_shape
            return
        try:
            len(target_shape)
        except TypeError:
            raise AssertionError(
                "Target shape must be a tuple, list, or PyTree of shapes."
            )
        if all(isinstance(dim, int) for dim in target_shape):
            # target_shape is just an iterable of ints
            pass
        elif any(isinstance(dim, int) for dim in target_shape):
            # target_shape is a PyTree, but not all the of the leaves are shapes
            # (iterables themselves)
            # e.g. target_shape = [(2, 3), 2, (4, 5)], the second element (2) is
            # invalid and should be (2,) instead
            raise TypeError(
                "If target_shape is a PyTree, all leaves must be shapes "
                "(iterables of ints)."
            )
        # at this point target_shape is either an iterable of ints, or a PyTree of
        # shapes or Nones
        self.target_shape = target_shape

    @property
    def name(self) -> str:
        return f"Reshape(shape={self.target_shape})"

    def is_ready(self) -> bool:
        return True

    def get_num_trainable_floats(self) -> int | None:
        return 0

    def _get_callable(
        self,
    ) -> ModuleCallable:
        @jaxtyped(typechecker=beartype)
        def reshape_array(
            arr: ArrayData,
            shape: ArrayDataShape | None,
        ) -> ArrayData:
            batch_dim = arr.shape[0]
            if shape is None:
                return arr
            else:
                return jnp.reshape(arr, (batch_dim, *shape))

        @jaxtyped(typechecker=beartype)
        def reshape_callable(
            params: Params,
            data: Data,
            training: bool,
            state: State,
            rng: Any,
        ) -> Tuple[Data, State]:
            if self.target_shape is None:
                return data, state
            else:
                reshaped_data = jax.tree.map(
                    reshape_array,
                    data,
                    self.target_shape,
                )
                return reshaped_data, state

        return reshape_callable

    def validate_and_concretify_shape(
        self, input_shape: DataShape
    ) -> DataShape:
        # check that input_shape and self.target_shape are compatible
        if self.target_shape is None:
            return input_shape

        assert input_shape is not None, "Input shape must not be None."
        assert not (None in input_shape), "Input shape must not contain None."

        try:
            len(input_shape)
        except TypeError:
            raise TypeError(
                "Input shape must be a tuple, list, or PyTree of shapes."
            )

        promoted = False
        # if input_shape is an iterable of ints, convert to a single-element
        # PyTree for consistency
        if all(isinstance(dim, int) for dim in input_shape):
            input_shape = (input_shape,)
            promoted = True

        # same for self.target_shape
        if all(isinstance(dim, int) for dim in self.target_shape):
            self_target_shape = (self.target_shape,)
        else:
            self_target_shape = self.target_shape

        input_struct = jax.tree.structure(input_shape, is_leaf=is_shape_leaf)
        shape_struct = jax.tree.structure(self_target_shape, is_leaf=is_shape_leaf)
        assert input_struct == shape_struct, (
            f"Input shape structure {input_struct} does not match target shape"
            f" structure {shape_struct}"
        )

        def check_compatibility_and_concretify(
            in_shape: ArrayDataShape,
            target_shape: ArrayDataShape | None,
        ) -> ArrayDataShape:
            if target_shape is None:
                return
            in_size = jnp.prod(jnp.array(in_shape)).item()
            if -1 in target_shape:
                # make sure there is only one -1
                assert (
                    target_shape.count(-1) == 1
                ), "Target shape can only contain one -1 dimension"
                # infer the size of the -1 dimension
                known_size = 1
                for dim in target_shape:
                    if dim != -1:
                        known_size *= dim
                inferred_dim = in_size // known_size
                target_size = known_size * inferred_dim
            else:
                target_size = jnp.prod(jnp.array(target_shape)).item()

            assert in_size == target_size, (
                f"Input shape {in_shape} is not compatible with target shape"
                f" {target_shape}"
            )

            if -1 in target_shape:
                # replace -1 with inferred dimension
                return tuple(
                    inferred_dim if dim == -1 else dim for dim in target_shape
                )
            else:
                return target_shape

        concrete_shape = jax.tree.map(
            check_compatibility_and_concretify,
            input_shape,
            self_target_shape,
            is_leaf=is_shape_leaf,
        )

        if promoted:
            return concrete_shape[0]
        else:
            return concrete_shape

    def compile(self, rng: Any, input_shape: DataShape) -> None:
        self.validate_and_concretify_shape(input_shape)

    def get_output_shape(self, input_shape: DataShape) -> DataShape:
        return self.validate_and_concretify_shape(input_shape)

    def get_hyperparameters(self) -> HyperParams:
        return {
            "shape": self.target_shape,
        }

    def get_params(self) -> Params:
        return ()

    def set_params(self, params: Params) -> None:
        pass

# Initialize database connection and manage table operations

from data_warehouse.db import connect
from data_warehouse.sql_queries import create_table_queries, drop_table_queries

def remove_existing_tables(cursor, connection):
    for statement in drop_table_queries:
        cursor.execute(statement)
        connection.commit()

def setup_new_tables(cursor, connection):
    for statement in create_table_queries:
        cursor.execute(statement)
        connection.commit()

def execute_database_setup(verbose=False):
    cursor, connection = connect()

    if verbose:
        print("Removing existing tables...")
    remove_existing_tables(cursor, connection)

    if verbose:
        print("Setting up new tables...")
    setup_new_tables(cursor, connection)

    if verbose:
        print("Database setup completed.")
    connection.close()

import argparse
from typing import Optional
import termcolor as tc
from cpk import CPKProject
