PROJECT_DETAILS = """
{header}
{indent} Name: {project_name}
{indent} Tag: {version_tag}
{indent} Version: {release_version}
{indent} Template:
{indent}   Name: {template_project}
{indent}   Version: {template_release}
{indent} Index Status: {status}
{indent} Directory: {directory}
{indent} Repository: {repository}
{indent} Plugins: {plugins}
{footer}
"""

class CLIInfoCommand(AbstractCLICommand):
    KEY = 'info'

    @staticmethod
    def parser(parent: Optional[argparse.ArgumentParser] = None,
               args: Optional[Arguments] = None) -> argparse.ArgumentParser:
        return argparse.ArgumentParser(parents=[parent])

    @staticmethod
    def execute(machine: Optional[Machine], parsed: argparse.Namespace) -> bool:
        cpklogger.info("Workspace directory: {}".format(parsed.workdir))

        # Load the project from workspace
        project = CPKProject(parsed.workdir)

        # Determine and colorize index status
        status_text = "Clean" if project.is_clean() else "Dirty"
        status_color = "green" if project.is_clean() else "yellow"
        status = tc.colored(status_text, status_color)

        # Prepare formatted output data
        info_dict = {
            "header": tc.colored("Project Details:", "grey", "on_white"),
            "project_name": project.name,
            "version_tag": project.version.tag,
            "release_version": project.version.head or "unreleased",
            "template_project": project.template.name,
            "template_release": project.template.version,
            "status": status,
            "directory": project.path,
            "repository": project.url or "(none)",
            "plugins": " ".join(project.adapters.keys()),
            "indent": tc.colored("  ", "grey", "on_white"),
            "footer": tc.colored("───────────────", "grey", "on_white"),
        }

        cpklogger.print(PROJECT_DETAILS.format(**info_dict))
        return True

from workerInfra.exceptions import MissingSourceID
from workerInfra.models import Sources, DiscordWebHooks, SourceLinks
from workerInfra.enum import SourcesEnum
from workerInfra.domain import LoggerInterface
from workerService.db import SourcesTable, ArticlesTable, SourceLinksTable, DiscordWebHooksTable
from workerService import CacheFactory, SqlCache
from workerService.logger import BasicLoggerService
from typing import List, Optional
from requests import Response, get
from bs4 import BeautifulSoup


class SourceValidator:
    """
    Validates configuration parameters for a source to ensure required fields are present.
    """

    _logger: LoggerInterface

    def __startValidation__(self) -> None:
        self.__checkSiteName__()
        self.__checkUri__()

    def __checkSiteName__(self) -> None:
        if not self.siteName or self.siteName.strip() == "":
            raise ValueError("Missing 'siteName' in source configuration.")

    def __checkUri__(self) -> None:
        if not self.uri or self.uri.strip() == "":
            raise ValueError("Missing 'uri' in source configuration.")

    def __evaluateEnvironment__(self, siteLabel: str) -> None:
        # Determine if Discord output is active
        activeDiscordServers = self.__fetchActiveDiscordHooks__(siteLabel)
        if activeDiscordServers:
            self.isOutputDiscordEnabled = True
            self._discordWebhookList = activeDiscordServers

        # Check if source links exist
        linkedSources = self.__retrieveLinkedSources__(siteLabel)
        if linkedSources:
            self.isSourceEnabled = True
            self._sourceLinkList = linkedSources

    def __retrieveLinkedSources__(self, siteLabel: str) -> List[Sources]:
        temp_list = []
        records = SourcesTable().getAllBySource(source=siteLabel)
        for record in records:
            temp_list.append(record)
        return temp_list

    def __fetchActiveDiscordHooks__(self, siteLabel: str) -> List[DiscordWebHooks]:
        discord_hooks = []
        source_records = SourcesTable().getAllBySource(source=siteLabel)

        for src in source_records:
            link_record = SourceLinksTable().getBySourceId(src.id)
            if not link_record or not link_record.id:
                continue  # Skip invalid or missing link records

            if link_record.discordID and link_record.discordID.strip():
                hook_ref = DiscordWebHooksTable().getById(id=link_record.discordID)
                if hook_ref and getattr(hook_ref, 'enabled', False):
                    discord_hooks.append(hook_ref)

        return discord_hooks


class SourcesBase(SourceValidator):
    """
    Base class providing shared utilities across various source implementations.
    Do not instantiate directly — intended for subclassing only.
    """

    isOutputDiscordEnabled: bool = False
    isSourceEnabled: bool = False
    _discordWebhookList: List[DiscordWebHooks] = []
    _sourceLinkList: List[Sources] = []

    def __init__(self) -> None:
        self._logger: LoggerInterface = BasicLoggerService()
        self.__initializeSource__()
        super().__init__()

    def __initializeSource__(self) -> None:
        self.__validateConfiguration__()
        self.__setupDataLayers__()
        self.__evaluateEnvironment__(self.siteName)

    def __setupDataLayers__(self) -> None:
        self.articleStore = ArticlesTable()
        self.sourceStore = SourcesTable()
        self.cacheManager: CacheFactory = CacheFactory(SqlCache())

    def setSiteName(self, siteName: SourcesEnum) -> None:
        self.siteName = siteName.value

    def setActiveSource(self, source: SourcesEnum, name: str = "", sourceType: str = '') -> None:
        """
        Fetches and binds the appropriate source record based on input criteria.
        """
        res: Optional[Sources] = None

        if sourceType and sourceType.strip():
            res = SourcesTable().getByNameSourceType(name=name, source=source.value, type=sourceType)
        elif name and name.strip():
            res = SourcesTable().getByNameAndSource(name=name, source=source.value)
        else:
            res = SourcesTable().getBySource(source.value)

        if not res or not res.id:
            raise RuntimeError(f"Source '{source.value}' could not be located.")

        self.activeSourceRecord = res

    def getActiveSourceID(self) -> str:
        return self.activeSourceRecord.id

    def fetchContent(self, uri: str = '') -> Response:
        try:
            user_agent_headers = self.__buildUserAgent__()
            target_uri = uri if uri else self.uri
            return get(url=target_uri, headers=user_agent_headers)
        except Exception as err:
            self._logger.critical(f"Failed to retrieve content from {self.uri}. Error: {err}")
            raise

    def __buildUserAgent__(self) -> dict:
        return {
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64; rv:10.0) Gecko/20100101 Firefox/91.3"
        }

    def parseDocument(
        self, requestsPayload: Response = None, seleniumContent: str = ""
    ) -> BeautifulSoup:
        try:
            if seleniumContent:
                return BeautifulSoup(seleniumContent, features="html.parser")
            elif requestsPayload and hasattr(requestsPayload, 'content'):
                return BeautifulSoup(requestsPayload.content, features="html.parser")
            else:
                raise ValueError("No valid content provided for parsing.")
        except Exception as ex:
            self._logger.critical(f"Error during HTML parsing: {ex}")
            raise

    def getHeaders(self) -> dict:
        return self.__buildUserAgent__()

