from fixit.common.utils import _dedent
from fixit.rule_lint_engine import lint_file
from libcst.metadata import MetadataWrapper
from libcst.metadata.type_inference_provider import PyreData, _process_pyre_data, run_command
from loguru import logger
from . import base, exceptions
from .autofix import LintPatch
from .report import BaseLintRuleReport
from .utils import InvalidTestCase, LintRuleCollectionT, ValidTestCase, _dedent

CONFIG_SOURCES = ('.isort.cfg', 'pyproject.toml', 'setup.cfg', 'tox.ini', '.editorconfig')
CstLintRule = base.CstLintRule
TestCaseT = Union[ValidTestCase, InvalidTestCase]

def locate_fixture_path(
        top_directory: Path,
        module_name: str,
        package_name: str
) -> Path:
    """
    Determine the fixture directory path based on module structure.
    """
    subpackage: str = module_name.split(f"{package_name}.", 1)[-1]
    directory_path = subpackage.replace(".", "/")
    return top_directory / directory_path

def create_type_data(source_code: str, output_path: Path) -> None:
    """Generate type information using Pyre for given source code."""
    parent_dir = output_path.parent

    # Ensure parent directories exist
    if not parent_dir.exists():
        parent_dir.mkdir(parents=True)

    # Write source code to temporary file
    with tempfile.NamedTemporaryFile("w", dir=parent_dir, suffix=".py") as temp_file:
        temp_file.write(_dedent(source_code))
        temp_file.flush()

        # Execute Pyre query
        command = f'pyre query "types(path=\'{temp_file.name}\')"'
        stdout, stderr, exit_code = run_command(command)

        if exit_code != 0:
            raise exceptions.PyreQueryError(command, f"{stdout}\n{stderr}")

        result = json.loads(stdout)

        # Handle error responses from Pyre
        if "error" in result:
            raise exceptions.PyreQueryError(command, result["error"])

        # Extract type data
        type_info = result["response"][0]
        processed_data: PyreData = _process_pyre_data(type_info)

        # Save to output file
        output_path.write_text(json.dumps({"types": processed_data["types"]}, indent=2))

def generate_fixtures_for_rule(rule: CstLintRule, fixtures_directory: Path) -> None:
    """Generate Pyre fixtures for a lint rule if it requires type metadata."""
    if not rule.requires_metadata_caches():
        raise exceptions.RuleNotTypeDependentError("Rule does not require type inference caches.")

    has_test_cases = hasattr(rule, "VALID") or hasattr(rule, "INVALID")
    if has_test_cases:
        print("Initializing Pyre server...")
        stdout, stderr, exit_code = run_command("pyre start")
        if exit_code != 0:
            print(f"Server startup output:\n{stdout}\n{stderr}")
        else:
            rule_class_name = getattr(rule, "__name__", "UnknownRule")

            # Process valid test cases
            if hasattr(rule, "VALID"):
                for index, test_case in enumerate(getattr(rule, "VALID")):
                    fixture_file = fixtures_directory / f"{rule_class_name}_VALID_{index}.json"
                    create_type_data(test_case.code, fixture_file)

            # Process invalid test cases
            if hasattr(rule, "INVALID"):
                for index, test_case in enumerate(getattr(rule, "INVALID")):
                    fixture_file = fixtures_directory / f"{rule_class_name}_INVALID_{index}.json"
                    create_type_data(test_case.code, fixture_file)

            # Stop Pyre server
            run_command("pyre stop")

def build_metadata_wrapper(code: str, fixture_path: Path) -> MetadataWrapper:
    """Create a MetadataWrapper with type inference data loaded from fixture."""
    parsed_module = cst.parse_module(_dedent(code))
    provider_class = TypeInferenceProvider

    try:
        raw_data = json.loads(fixture_path.read_text())
    except FileNotFoundError:
        raise exceptions.FixtureFileNotFoundError(
            f"Fixture file missing at {fixture_path}. "
            "Run 'python -m fixit.common.generate_pyre_fixtures <rule>' to generate fixtures."
        )

    return MetadataWrapper(
        module=parsed_module,
        cache={cast(Type[BaseMetadataProvider[object]], provider_class): raw_data}
    )

def verify_patch_application(report: BaseLintRuleReport, test_case: InvalidTestCase) -> None:
    """Validate that auto-fix patch produces expected output."""
    actual_patch = report.patch
    expected_output = test_case.expected_replacement

    if actual_patch is None:
        if expected_output is not None:
            raise AssertionError("Rule provides no auto-fix but expected replacement was specified.")
        return

    if expected_output is None:
        raise AssertionError("Rule provides auto-fix but no expected replacement was specified.")

    expected_output = _dedent(expected_output)
    actual_result = actual_patch.apply(_dedent(test_case.code))

    if actual_result != expected_output:
        raise AssertionError(
            f"Auto-fix mismatch.\nExpected:\n{expected_output}\nActual:\n{actual_result}"
        )

    logger.debug(str(report))

@dataclass(frozen=False)
class TestSuiteBuilder:
    rule_class: Type[CstLintRule] = None
    test_cases: Mapping[str, TestCaseT] = {}
    fixture_files: Mapping[str, Path] = {}

def create_lint_test_case(
        suite_data: TestSuiteBuilder,
        base_test_class: Type[unittest.TestCase] = LintRuleTestCase,
        method_name: str = "_test_method",
) -> Dict[str, Type[unittest.TestCase]]:
    """Dynamically create test classes for lint rules."""
    dynamic_methods: Dict[str, Callable] = {}
    rule_identifier = suite_data.rule_class.__name__

    for test_name, test_data in suite_data.test_cases.items():
        fixture_location = suite_data.fixture_files.get(test_name)

        def test_runner(
                self: Type[unittest.TestCase],
                case_data: Union[ValidTestCase, InvalidTestCase] = test_data,
                rule_class: Type[CstLintRule] = suite_data.rule_class,
                fixture_path: Optional[str] = fixture_location,
        ) -> None:
            return getattr(self, method_name)(case_data, rule_class, fixture_path)

        test_runner.__name__ = test_name
        dynamic_methods[test_name] = test_runner

    try:
        test_class = new_class(rule_identifier, (base_test_class,), dynamic_methods)
        return {rule_identifier: test_class}
    except Exception as e:
        logger.warning(f"Failed to create test class: {e}")
        return dynamic_methods

def integrate_tests_into_module(
        target_namespace: Dict[str, Any],
        rule_classes: LintRuleCollectionT,
        test_base_class: Type[unittest.TestCase] = LintRuleTestCase,
        custom_method: str = "_test_method",
        fixtures_root: Path = Path("/path/to/user/repos/Fixit/fixit/tests/fixtures"),
        rules_module: str = "fixit.rules",
) -> None:
    """Integrate dynamically generated tests into target module namespace."""
    for rule_instance in rule_classes:
        if not issubclass(rule_instance, CstLintRule):
            continue

        builder = TestSuiteBuilder()
        rule_class = cast(Type[CstLintRule], rule_instance)
        fixture_subdir = locate_fixture_path(fixtures_root, rule_class.__module__, rules_module)

        # Check if rule requires fixtures
        needs_fixtures = rule_class.requires_metadata_caches()

        # Collect valid test cases
        if hasattr(rule_class, "VALID"):
            for idx, test_case in enumerate(getattr(rule_class, "VALID")):
                name = f"test_VALID_{idx}"
                builder.test_cases[name] = test_case
                if needs_fixtures:
                    builder.fixture_files[name] = fixture_subdir / f"{rule_class.__name__}_VALID_{idx}.json"

        # Collect invalid test cases
        if hasattr(rule_class, "INVALID"):
            for idx, test_case in enumerate(getattr(rule_class, "INVALID")):
                name = f"test_INVALID_{idx}"
                builder.test_cases[name] = test_case
                if needs_fixtures:
                    builder.fixture_files[name] = fixture_subdir / f"{rule_class.__name__}_INVALID_{idx}.json"

        # Create and register test class
        if builder.test_cases:
            test_class = new_class(
                rule_class.__name__,
                (test_base_class,),
                {
                    name: lambda self, data=test_case, rule=rule_class, 
                          fixture=builder.fixture_files.get(name): 
                        getattr(self, custom_method)(data, rule, fixture)
                    for name, test_case in builder.test_cases.items()
                }
            )
            target_namespace[rule_class.__name__] = test_class

