# Type III clone: Replaced loop-based logic with recursive approach and modified control flow
# while preserving the same functionality (displaying arrays as images in Jupyter/Colab)

from __future__ import annotations
import functools
import traceback
from typing import Any, Optional, Tuple
from etils import enp
import IPython
import IPython.display
import mediapy as media

Array = Any
_MIN_IMG_SHAPE: Tuple[int, int] = (10, 10)

def show(*objs, **kwargs) -> None:
    """Alias for `IPython.display.display`."""
    return IPython.display.display(*objs, **kwargs)

def auto_plot_array(*, video_min_num_frames: int = 15) -> None:
    """If called, 2d/3d image arrays will be plotted as images in colab/jupyter.

    Args:
      video_min_num_frames: Video `(num_frames, h, w, c)` with less than
        this number of frames will be displayed as individual images
    """
    ipython = IPython.get_ipython()
    if ipython is None:
        return  # Non-notebook environment

    array_repr_html_fn = functools.partial(
        _array_repr_html,
        video_min_num_frames=video_min_num_frames,
    )

    print('Display big np/tf/jax arrays as image for nicer IPython display')
    formatter = ipython.display_formatter.formatters['text/html']

    # Register array types using helper function instead of try-except blocks
    _register_jax_array_type(formatter, array_repr_html_fn)
    _register_tf_array_type(formatter, array_repr_html_fn)
    _register_np_array_type(formatter, array_repr_html_fn)

def _register_jax_array_type(formatter, array_repr_html_fn):
    """Register JAX array type handler."""
    try:
        jnp = enp.lazy.jnp
    except ImportError:
        return

    jax_array_cls = type(jnp.zeros(shape=()))  # DeviceArrayBase
    formatter.for_type(jax_array_cls, array_repr_html_fn)

def _register_tf_array_type(formatter, array_repr_html_fn):
    """Register TensorFlow array type handler."""
    try:
        tf = enp.lazy.tf
    except ImportError:
        return

    formatter.for_type(tf.Tensor, array_repr_html_fn)

def _register_np_array_type(formatter, array_repr_html_fn):
    """Register NumPy array type handler."""
    formatter.for_type(enp.lazy.np.ndarray, array_repr_html_fn)

def _array_repr_html(
    array: Array,
    **kwargs: Any,
) -> Optional[str]:
    """Returns the HTML `<img/>` repr, or `None` if array is not an image."""
    try:
        return _array_repr_html_inner(array, **kwargs)
    except Exception:
        # IPython display silence exceptions, so display it here
        traceback.print_exc()
        raise

def _array_repr_html_inner(
    img: Array,
    *,
    video_min_num_frames: int,
) -> Optional[str]:
    """Display the normalized img, or `None` if the input is not an image."""
    if not enp.lazy.is_array(img):  # Not an array
        return None

    # Normalize tf.Tensor into np.array
    if enp.lazy.is_tf(img):
        img = img.numpy()

    shape = img.shape
    ndim = len(shape)

    # Determine image dimensions and channels
    if ndim == 2:
        img_shape = shape
        num_channel = 1
    elif ndim == 3:
        img_shape = shape[:2]
        num_channel = shape[-1]
    elif ndim == 4:
        img_shape = shape[1:3]
        num_channel = shape[-1]
        num_frames = shape[0]
    else:
        return None

    # Validate image properties
    if _has_zero_dimension(shape):
        return None

    if _is_too_small(img_shape):
        return None

    if num_channel not in {1, 3, 4}:
        return None

    # Render based on dimensionality
    if ndim < 4:
        out = media.show_image(img, return_html=True)
    elif num_frames < video_min_num_frames:
        out = media.show_images(img, return_html=True)
    else:
        # Handle videos
        if num_channel != 3:
            return None

        fps = min(num_frames // 5, 25.)
        out = media.show_video(
            img,
            fps=fps,
            return_html=True,
        )

    return out

def _has_zero_dimension(shape: tuple[int, ...]) -> bool:
    """Returns True if any dimension has size zero."""
    return any(dim == 0 for dim in shape)

def _is_too_small(shape: tuple[int, ...]) -> bool:
    """Returns True if any dimension is smaller than minimum required size."""
    return any(dim < min_dim for dim, min_dim in zip(shape, _MIN_IMG_SHAPE))

import warnings
from ast import parse, Expr, Expression, walk
from docutils.parsers.rst import directives

try:
    from sphinx.directives.patches import MathDirective
except ImportError:  # Sphinx < 1.8.0b1
    from sphinx.ext.mathbase import MathDirective


def execute_and_evaluate(source_code, namespace):
    """
    Executes all statements in source_code, and evaluates the final expression if present.

    Returns the result of evaluating the last expression, or None if none exists.
    """
    tree = parse(source_code, '<dynamic>', 'exec')

    # Extract body items: separate statements and optional trailing expression
    statements = []
    expr_node = None

    for node in tree.body:
        if isinstance(node, Expr):
            expr_node = node
        else:
            statements.append(node)

    # Compile and run statements
    compiled_body = compile(type(tree)(body=statements), '<dynamic>', 'exec')
    exec(compiled_body, namespace)

    # If there's a trailing expression, evaluate it
    if expr_node is not None:
        expr_ast = type(tree)(body=[expr_node])
        compiled_expr = compile(Expression(expr_node.value), '<dynamic>', 'eval')
        return eval(compiled_expr, namespace)
    return None


class MathCodeDirective(MathDirective):
    """Generate math environment from SymPy expressions."""

    optional_arguments = 0
    option_spec = {
        'label': directives.unchanged,
        'name': directives.unchanged,
        'nowrap': directives.flag,
        'newcontext': directives.flag,
    }

    def _resolve_module_attr(self, path_str):
        """Resolve a dotted path like 'module.submodule.attribute' to an object."""
        parts = path_str.split('.')
        module_path = '.'.join(parts[:-1])
        attr_name = parts[-1]

        if not module_path:
            raise ValueError("Invalid module path: must include at least one module name.")

        mod = __import__(module_path, globals(), locals(), [attr_name], 0)
        return getattr(mod, attr_name)

    def _fetch_plot_namespace(self):
        """Attempt to retrieve plot context via new config or deprecated fallback."""
        # Try new-style config first
        plot_ns_path = setup.config.mathcode_plot_context
        if plot_ns_path is not None:
            try:
                return self._resolve_module_attr(plot_ns_path)
            except Exception as e:
                warnings.warn(f"Failed to load plot context from {plot_ns_path}: {e}", UserWarning)

        # Fallback to deprecated setting
        deprecated_plot_directive = self._get_deprecated_plot_directive()
        if deprecated_plot_directive is not None:
            warnings.warn(
                "mathcode_plot_directive is deprecated; use mathcode_plot_context instead.",
                FutureWarning
            )
            return getattr(deprecated_plot_directive, 'plot_context', None)

        # Default fallback
        try:
            from matplotlib.sphinxext.plot_directive import plot_context
            return plot_context
        except ImportError:
            return {}

    def _get_deprecated_plot_directive(self):
        """Retrieve deprecated plot directive object."""
        return getattr(setup.config, 'mathcode_plot_directive', None)

    def _build_execution_context(self, reset=False):
        """Construct or reset the namespace used for code execution."""
        if setup.config.mathcode_use_plot_ns:
            ns = self._fetch_plot_namespace()
        else:
            ns = setup.code_context

        if reset:
            ns.clear()
        return ns.copy()  # Avoid mutating original context

    def run(self):
        """Main entry point for the directive."""
        from sympy import latex

        should_reset = 'newcontext' in self.options
        context = self._build_execution_context(reset=should_reset)

        full_input = '\n'.join(self.content)
        result = execute_and_evaluate(full_input, context)

        if result is None:
            return []

        # Convert result to LaTeX lines
        latex_output = latex(result).splitlines()
        self.content = latex_output

        return super(MathCodeDirective, self).run()


def setup(app):
    # Store references for later use
    setup.app = app
    setup.config = app.config
    setup.confdir = app.confdir

    # Initialize execution context
    setup.code_context = {}

    # Register directive and configuration values
    app.add_directive('mathcode', MathCodeDirective)
    app.add_config_value('mathcode_use_plot_ns', False, 'env')
    app.add_config_value('mathcode_plot_context', None, 'env')
    app.add_config_value('mathcode_plot_directive', None, 'env')  # kept for backward compat

