def _check_entities(entity_type, entity_list):
    LOGGER.debug("Checking {0} configuration".format(entity_type))
    for item in entity_list:
        if isinstance(item, str):
            continue
        for actor_name, config in item.items():
            actor_class = ACTOR_CLASSES.get(actor_name, None)
            if not actor_class:
                raise Invalid("Unknown {0} {1}".format(entity_type, actor_name))
            actor_class.schema(config)

