class WistiaHelper:
    """
    Helper class for interacting with Wistia API and Wistia videos, which
    further simplifies any calls. This assumes that :class:`WistiaApi` has
    been configured as needed with the API token.
    """

    @staticmethod
    def is_archived_video(video_name: str) -> bool:
        """
        Check if this is an archived video which is automatically created by
        Wistia.
        In that case, we shouldn't order captions for it, since it's a copy of
        a video that was replaced with new media.
        Source: https://wistia.com/learn/product-updates/improved-library-management-tools  # noqa: E501
        """
        return video_name.startswith('[Archived') and video_name.endswith(']')

    @classmethod
    def video_exists(cls, video_id: str) -> bool:
        """
        Check if a video exists on Wistia.
        """
        response = WistiaDataApi.session().head(
            WistiaConfig.MEDIAS_SHOW_URL.format(media_id=video_id)
        )
        return response.status_code != 404

    @classmethod
    def rename_video(
        cls,
        video_id: str,
        new_title: str
    ) -> Video:
        """Update the title for a Wistia video."""
        return WistiaDataApi.update_video(video_id, new_title)

    @classmethod
    def captions_available(cls, video_id: str) -> bool:
        """
        Check if a video has captions available in the player settings.
        :return: A boolean indicating if the video player has captions
          available.
        """
        customizations = WistiaDataApi.get_customizations(video_id)
        return getattr(customizations.plugin.captions_v1, 'on', False) is True

    @classmethod
    def turn_on_captions(
        cls,
        video_id: str,
        default_state: bool = False
    ):
        """
        Enable captions on a Wistia video.
        """
        config = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    enabled_by_default=default_state,
                    active=True
                )
            )
        )
        return WistiaDataApi.update_customizations(video_id, config)

    @classmethod
    def activate_audio_descriptions(cls, video_id: str):
        """
        Enable audio descriptions on a Wistia video.
        """
        config = Customizations(audio_description_required=True)
        return WistiaDataApi.update_customizations(video_id, config)

    @classmethod
    def enable_accessibility_features(
        cls,
        video_id: str,
        default_state: bool = False
    ):
        """
        Enable captions and AD on a Wistia video.
        """
        config = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    enabled_by_default=default_state,
                    active=True
                )
            ),
            audio_description_required=True
        )
        return WistiaDataApi.update_customizations(video_id, config)

    @classmethod
    def disable_accessibility_features(
        cls,
        video_id: str,
        default_state: bool = False
    ):
        """
        Disable captions and AD on a Wistia video.
        """
        config = Customizations(
            plugin=Plugin(
                captions_v1=CaptionsV1(
                    enabled_by_default=default_state,
                    active=False
                )
            ),
            audio_description_required=False
        )
        return WistiaDataApi.update_customizations(video_id, config)

    @classmethod
    def apply_player_settings(
        cls,
        video_id: str,
        accent_color: str
    ):
        """Set commonly used customization options for a media on Wistia."""
        payload = {'playerColor': accent_color}
        r = WistiaDataApi.session().put(
            WistiaConfig.CUSTOMIZATION_URL.format(media_id=video_id),
            json=payload
        )
        try:
            r.raise_for_status()
        except HTTPError:
            LOG.error('Wistia Customizations API. status=%d text=%s',
                      r.status_code, r.text)
            raise
        LOG.info('[%s] Wistia: Customize Video success', r.elapsed)
        return r.json()

    @classmethod
    def fetch_project_info(
        cls,
        project_id: str,
        all_projects: Container[Project] | None = None
    ) -> Project:
        """Retrieve details on a Wistia project.
        The optional parameter `all_projects` contains info on all projects in
        the Wistia account, such as a response from the `Projects:list` API.
        :raises NoSuchProject: If the project doesn't exist on Wistia
        """
        if all_projects is None:
            all_projects = WistiaDataApi.list_all_projects()

        found = None
        for proj in all_projects:
            if proj.hashed_id == project_id:
                found = proj
                break

        if found is None:
            raise NoSuchProject(project_id)

        return found

# Azure Blob Storage path implementation with pathlib-like interface

from pathlib import Path
from tempfile import TemporaryDirectory
from typing import TYPE_CHECKING

try:
    from azure.core.exceptions import ResourceNotFoundError
except ImportError:
    ResourceNotFoundError = None

import os

from ..cloudpath import CloudPath, NoStatError, register_path_class

if TYPE_CHECKING:
    from .azblobclient import AzureBlobClient


@register_path_class("azure")
class AzureBlobPath(CloudPath):
    """Implementation for Azure Blob Storage paths using a pathlib-inspired API.

    Provides filesystem-like operations on Azure Blob Storage URIs. Instances 
    represent blob storage paths and support common operations like reading, 
    writing, checking existence, etc. Follows the pathlib.Path interface where 
    applicable.

    Authentication is handled by AzureBlobClient; if not explicitly provided, 
    a default client is used automatically.
    """

    cloud_prefix: str = "az://"
    client: "AzureBlobClient"

    @property
    def drive(self) -> str:
        """Return the container name as the 'drive' component."""
        return self.container

    def is_dir(self) -> bool:
        """Check if this path represents a directory in blob storage."""
        return self.client._is_file_or_dir(self) == "dir"

    def is_file(self) -> bool:
        """Check if this path represents a file in blob storage."""
        return self.client._is_file_or_dir(self) == "file"

    def mkdir(self, parents=False, exist_ok=False):
        """Create a directory (no-op since Azure Blob Storage doesn't have real directories)."""
        pass

    def touch(self):
        """Create an empty file or update timestamp if it exists."""
        if self.exists():
            self.client._move_file(self, self)
        else:
            temp_dir = TemporaryDirectory()
            try:
                empty_file_path = Path(temp_dir.name) / "empty"
                empty_file_path.touch()
                self.client._upload_file(empty_file_path, self)
            finally:
                temp_dir.cleanup()

    def stat(self):
        """Get metadata statistics for this blob."""
        try:
            metadata = self.client._get_metadata(self)
        except (ResourceNotFoundError, AttributeError):
            raise NoStatError(
                f"No stats available for {self}; it may be a directory or not exist."
            )

        return os.stat_result((
            None,  # mode
            None,  # ino
            self.cloud_prefix,  # dev
            None,  # nlink
            None,  # uid
            None,  # gid
            metadata.get("size", 0),  # size
            None,  # atime
            metadata.get("last_modified", 0).timestamp() if hasattr(metadata.get("last_modified"), "timestamp") else 0,  # mtime
            None,  # ctime
        ))

    @property
    def container(self) -> str:
        """Extract the container name from the path."""
        return self._no_prefix.split("/", 1)[0]

    @property
    def blob(self) -> str:
        """Extract the blob name (path within container) from the full path."""
        key = self._no_prefix_no_drive
        # Remove leading slash if present (not valid in blob names)
        return key.lstrip("/")

    @property
    def etag(self):
        """Get the ETag value for this blob."""
        try:
            return self.client._get_metadata(self).get("etag", None)
        except (ResourceNotFoundError, AttributeError):
            return None

    @property
    def md5(self) -> str:
        """Get the MD5 hash of the blob content."""
        try:
            content_settings = self.client._get_metadata(self).get("content_settings", {})
            return content_settings.get("content_md5", None)
        except (ResourceNotFoundError, AttributeError):
            return None

