class ConfigEntry:
    """Represents an expected configuration entry with type, path, and description."""

    def __init__(self, 
                 expected_type: type, 
                 path_components: Sequence[str], 
                 description: str):
        self.expected_type = expected_type
        self.path = tuple(path_components)
        self.description = description

    def get_value(self, config_dict: dict) -> Tuple[bool, Any]:
        """Extract value from nested dictionary using path components."""
        current = config_dict
        for component in self.path:
            if component not in current:
                return False, None
            current = current[component]
        return True, current


