class DotNotationDict(dict):
    """Dictionary subclass that supports dot notation access."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.__dict__ = self

    def __getattr__(self, key):
        try:
            return self[key]
        except KeyError:
            raise AttributeError(f"'{type(self).__name__}' object has no attribute '{key}'")

    def __setattr__(self, key, value):
        self[key] = value

    def __delattr__(self, key):
        try:
            del self[key]
        except KeyError:
            raise AttributeError(f"'{type(self).__name__}' object has no attribute '{key}'")


def _resolve_nested_value(data: dict, path: Sequence[str]) -> Tuple[bool, Any]:
    """Safely retrieve nested value from dictionary using path."""
    current = data
    for segment in path:
        if isinstance(current, dict) and segment in current:
            current = current[segment]
        else:
            return False, None
    return True, current


def _validate_config_entry(entry: ConfigEntry, config: dict) -> List[str]:
    """Validate a single configuration entry against the schema."""
    issues = []
    exists, value = _resolve_nested_value(config, entry.path)

    if not exists:
        issues.append(f"Missing required configuration: {'.'.join(entry.path)}")
        return issues

    # Type-specific validation
    if entry.expected_type is str:
        if not isinstance(value, str) or not value.strip():
            issues.append(f"String field {'.'.join(entry.path)} must be non-empty string")

    elif entry.expected_type is Path:
        if not isinstance(value, (str, Path)) or not str(value).strip():
            issues.append(f"Path field {'.'.join(entry.path)} must be non-empty path")
        elif not Path(value).exists():
            issues.append(f"Path {'.'.join(entry.path)} does not exist: {value}")

    elif entry.expected_type is Callable:
        if shutil.which(str(value)) is None:
            issues.append(f"Executable {'.'.join(entry.path)} not found or not executable: {value}")

    elif entry.expected_type is list:
        if not isinstance(value, list):
            issues.append(f"List field {'.'.join(entry.path)} must be a list")

    return issues


def validate_configuration(config: dict) -> None:
    """Validate entire configuration against schema."""
    all_issues = []
    for entry in CONFIG_ENTRIES:
        all_issues.extend(_validate_config_entry(entry, config))

    if all_issues:
        print("Configuration validation failed:")
        for issue in sorted(all_issues):
            print(f"  - {issue}")
        exit(1)


def convert_to_absolute_paths(config: dict, base_dir: Path) -> None:
    """Convert relative paths in config to absolute paths."""
    for entry in CONFIG_ENTRIES:
        if entry.expected_type is Path:
            exists, value = _resolve_nested_value(config, entry.path)
            if exists and isinstance(value, str) and not Path(value).is_absolute():
                new_value = str(base_dir / value)
                # Update nested dict in place
                current = config
                for segment in entry.path[:-1]:
                    current = current[segment]
                current[entry.path[-1]] = new_value

        elif entry.expected_type is Callable:
            exists, value = _resolve_nested_value(config, entry.path)
            if exists and isinstance(value, str) and "/" in value and not Path(value).is_absolute():
                new_value = str(base_dir / value)
                current = config
                for segment in entry.path[:-1]:
                    current = current[segment]
                current[entry.path[-1]] = new_value


def load_configuration(config_path: Optional[Path] = None, 
                      validate: bool = True) -> DotNotationDict:
    """Load configuration from JSON file."""
    if config_path is None:
        home_config = Path.home() / ".config/dead/config.json"
        if home_config.exists():
            config_path = home_config
        else:
            raise FileNotFoundError(f"No config found at {home_config}")

    if not Path(config_path).is_file():
        raise FileNotFoundError(f"Config file not found: {config_path}")

    with open(config_path, 'r') as f:
        raw_config = json.load(f)

    raw_config["config_path"] = str(Path(config_path).absolute())
    config_obj = DotNotationDict(raw_config)

    project_dir = Path(__file__).parent
    convert_to_absolute_paths(config_obj, project_dir)

    if validate:
        validate_configuration(config_obj)

    # Ensure cache directory exists with proper permissions
    cache_path = Path(config_obj.cachedir)
    if not cache_path.exists():
        cache_path.mkdir(parents=True, exist_ok=True)
        shutil.chown(str(cache_path), group=config_obj.cache_group)
        os.chmod(str(cache_path), 0o770 | stat.S_ISGID)
    else:
        # Handle symlinks
        real_path = cache_path.resolve()
        if real_path.group() != config_obj.cache_group:
            raise PermissionError(f"Cache directory group mismatch: expected {config_obj.cache_group}, got {real_path.group()}")

        # Check permissions
        mode = os.stat(str(cache_path)).st_mode
        if mode & 0o777 != 0o770:
            raise PermissionError(f"Cache directory has incorrect permissions. Expected 0o770, got {oct(mode & 0o777)}")

    return config_obj


def parse_arguments(parser_list: List[argparse.ArgumentParser]) -> Tuple[DotNotationDict, argparse.Namespace]:
    """Parse command line arguments and merge with configuration."""
    combined_parser = argparse.ArgumentParser(parents=parser_list)
    args = combined_parser.parse_args()

    # Set up logging
    if hasattr(args, 'log_level') and args.log_level:
        try:
            level = getattr(logging, args.log_level.upper())
            logging.basicConfig(level=level)
        except AttributeError:
            print(f"Invalid log level: {args.log_level}")
            exit(1)

    # Load configuration
    config = load_configuration(getattr(args, 'config', None), validate=False)

    # Override config values with CLI arguments
    for entry in CONFIG_ENTRIES:
        cli_val = getattr(args, '.'.join(entry.path), None)
        if cli_val is not None:
            current = config
            for segment in entry.path[:-1]:
                current = current[segment]
            current[entry.path[-1]] = cli_val

    validate_configuration(config)
    return config, args


@dataclass
class CompilerConfiguration:
    """Represents a compiler configuration setting."""
    name: str
    revision: str
    optimization_level: str
    extra_flags: List[str] = field(default_factory=list)

    def __str__(self) -> str:
        if not self.extra_flags:
            return f"{self.name} {self.revision} -O{self.optimization_level}"
        return f"{self.name} {self.revision} -O{self.optimization_level} {' '.join(self.extra_flags)}"

    def report_format(self) -> str:
        """Format for reports."""
        return f"{self.name}-{self.revision} -O{self.optimization_level}"

    def to_dict(self) -> Dict[str, Any]:
        """Serialize to dictionary."""
        return {
            "compiler": self.name,
            "rev": self.revision,
            "opt_level": self.optimization_level,
            "flags": self.extra_flags
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "CompilerConfiguration":
        """Deserialize from dictionary."""
        return cls(
            name=data["compiler"],
            revision=data["rev"],
            optimization_level=data["opt_level"],
            extra_flags=data.get("flags", [])
        )

    def add_flag(self, flag: str) -> None:
        """Add a flag if not already present."""
        if flag not in self.extra_flags:
            self.extra_flags.append(flag)

    def get_flags_string(self) -> str:
        """Get flags as space-separated string."""
        return " ".join(self.extra_flags)

    def get_flags_list(self) -> List[str]:
        """Get flags as list."""
        return self.extra_flags.copy()


class TestScenario:
    """Represents a test scenario with target and attacker compiler configurations."""

    def __init__(self, 
                 targets: List[CompilerConfiguration],
                 attackers: List[CompilerConfiguration]):
        self.targets = targets
        self.attackers = attackers
        self.tool_versions = {
            "instrumenter": VERSIONS.instrumenter_version,
            "generator": VERSIONS.generator_version,
            "bisector": VERSIONS.bisector_version,
            "reducer": VERSIONS.reducer_version
        }

    def apply_flags(self, flags: List[str]) -> None:
        """Apply flags to all compiler configurations."""
        for cfg in self.targets + self.attackers:
            for flag in flags:
                cfg.add_flag(flag)

    def to_dict(self) -> Dict[str, Any]:
        """Serialize to dictionary."""
        return {
            "targets": [t.to_dict() for t in self.targets],
            "attackers": [a.to_dict() for a in self.attackers],
            "versions": self.tool_versions.copy()
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "TestScenario":
        """Deserialize from dictionary."""
        targets = [CompilerConfiguration.from_dict(t) for t in data["targets"]]
        attackers = [CompilerConfiguration.from_dict(a) for a in data["attackers"]]
        scenario = cls(targets, attackers)
        if "versions" in data:
            scenario.tool_versions.update(data["versions"])
        return scenario

    @classmethod
    def from_file(cls, config_path: Path) -> "TestScenario":
        """Load scenario from JSON file."""
        with open(config_path, 'r') as f:
            data = json.load(f)
        return cls.from_dict(data)


def execute_command(cmd: Union[str, List[str]], 
                   working_dir: Optional[Path] = None,
                   env_updates: Dict[str, str] = {}) -> str:
    """Execute a command and return its output."""
    if working_dir is None:
        working_dir = Path.cwd()

    env = os.environ.copy()
    env.update(env_updates)

    if isinstance(cmd, str):
        cmd = cmd.split()

    result = subprocess.run(
        cmd,
        cwd=str(working_dir),
        check=True,
        env=env,
        capture_output=True
    )

    logging.debug(result.stdout.decode().strip())
    logging.debug(result.stderr.decode().strip())

    return result.stdout.decode().strip()


def find_header_paths(compiler: str, source_file: str, flags: str) -> List[str]:
    """Find include paths used by the compiler."""
    cmd = [compiler, source_file, "-c", "-o/dev/null", "-v"]
    if flags:
        cmd.extend(flags.split())

    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    if result.returncode != 0:
        raise RuntimeError(f"Failed to determine include paths: {result.stderr.decode()}")

    lines = result.stdout.decode().split('\n')
    start_idx = next(i for i, line in enumerate(lines) 
                    if "#include <...> search starts here:" in line) + 1
    end_idx = next(i for i, line in enumerate(lines) 
                  if "End of search list." in line)

    return [line.strip() for line in lines[start_idx:end_idx]]


def get_compiler_config(config: DotNotationDict, compiler_name: str) -> DotNotationDict:
    """Get configuration for specified compiler."""
    if compiler_name.lower() == "gcc":
        return config.gcc
    elif compiler_name.lower() in ("llvm", "clang"):
        return config.llvm
    else:
        raise ValueError(f"Unknown compiler: {compiler_name}")


def create_symlink(source: Path, destination: Path) -> None:
    """Create symlink, handling existing files appropriately."""
    if destination.exists():
        if destination.is_symlink():
            destination.unlink()
        else:
            backup_name = destination.parent / f"conflict_{destination.name}"
            logging.warning(f"Moving conflicting file to {backup_name}")
            shutil.move(str(destination), str(backup_name))

    logging.debug(f"Creating symlink {destination} -> {source}")
    os.symlink(source, destination)


def extract_tarball_member(tf: tarfile.TarFile, member_name: str) -> str:
    """Extract text content from tarball member."""
    try:
        member = tf.extractfile(member_name)
    except KeyError:
        raise FileNotFoundError(f"Member '{member_name}' not found in archive")

    if member is None:
        raise FileNotFoundError(f"Member '{member_name}' could not be extracted")

    return member.read().decode('utf-8').strip()


@dataclass
class TestCase:
    """Represents a test case with code, markers, and compiler settings."""
    source_code: str
    marker: str
    bad_compiler: CompilerConfiguration
    good_compilers: List[CompilerConfiguration]
    scenario: TestScenario
    reduced_code: Optional[str]
    bisection_log: Optional[str]
    creation_time: float
    file_path: Optional[Path] = None

    def __post_init__(self):
        if self.creation_time is None:
            self.creation_time = time.time()

    def apply_flags(self, flags: List[str]) -> None:
        """Apply flags to all compiler configurations."""
        for flag in flags:
            self.bad_compiler.add_flag(flag)
            for good_cfg in self.good_compilers:
                good_cfg.add_flag(flag)
        self.scenario.apply_flags(flags)

    @classmethod
    def from_archive(cls, archive_path: Path, config: DotNotationDict) -> "TestCase":
        """Load test case from tar archive."""
        with tarfile.open(archive_path, 'r') as tf:
            source = extract_tarball_member(tf, "code.c")
            marker = extract_tarball_member(tf, "marker.txt")

            int_settings = json.loads(extract_tarball_member(tf, "interesting_settings.json"))
            bad_compiler = CompilerConfiguration.from_dict(int_settings["bad_setting"])
            good_compilers = [CompilerConfiguration.from_dict(d) for d in int_settings["good_settings"]]

            scenario = TestScenario.from_dict(json.loads(extract_tarball_member(tf, "scenario.json")))

            reduced_code = None
            if "reduced_code_0.c" in tf.getnames():
                reduced_code = extract_tarball_member(tf, "reduced_code_0.c")

            bisection_log = None
            if "bisection_0.txt" in tf.getnames():
                bisection_log = extract_tarball_member(tf, "bisection_0.txt")

            try:
                timestamp = float(extract_tarball_member(tf, "timestamp.txt"))
            except (KeyError, ValueError):
                timestamp = archive_path.stat().st_mtime

            return cls(
                source_code=source,
                marker=marker,
                bad_compiler=bad_compiler,
                good_compilers=good_compilers,
                scenario=scenario,
                reduced_code=reduced_code,
                bisection_log=bisection_log,
                creation_time=timestamp,
                file_path=archive_path.absolute()
            )

    def save_to_archive(self, archive_path: Path) -> None:
        """Save test case to tar archive."""
        with tarfile.open(archive_path, 'w') as tf:
            for name, content in [
                ("code.c", self.source_code),
                ("marker.txt", self.marker),
                ("interesting_settings.json", json.dumps({
                    "bad_setting": self.bad_compiler.to_dict(),
                    "good_settings": [g.to_dict() for g in self.good_compilers]
                })),
                ("scenario.json", json.dumps(self.scenario.to_dict())),
                ("timestamp.txt", str(self.creation_time))
            ]:
                with tempfile.NamedTemporaryFile(mode='w', delete=False) as tmp:
                    tmp.write(content)
                    tmp.flush()
                    tf.add(tmp.name, name)
                    os.unlink(tmp.name)

            if self.reduced_code:
                with tempfile.NamedTemporaryFile(mode='w', delete=False) as tmp:
                    tmp.write(self.reduced_code)
                    tmp.flush()
                    tf.add(tmp.name, "reduced_code_0.c")
                    os.unlink(tmp.name)

            if self.bisection_log:
                with tempfile.NamedTemporaryFile(mode='w', delete=False) as tmp:
                    tmp.write(self.bisection_log)
                    tmp.flush()
                    tf.add(tmp.name, "bisection_0.txt")
                    os.unlink(tmp.name)

    def to_dict(self) -> Dict[str, Any]:
        """Serialize to dictionary."""
        return {
            "code": self.source_code,
            "marker": self.marker,
            "bad_setting": self.bad_compiler.to_dict(),
            "good_settings": [g.to_dict() for g in self.good_compilers],
            "scenario": self.scenario.to_dict(),
            "reduced_code": self.reduced_code,
            "bisection": self.bisection_log,
            "timestamp": self.creation_time,
            "path": str(self.file_path) if self.file_path else None
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any], config: DotNotationDict) -> "TestCase":
        """Deserialize from dictionary."""
        bad_setting = CompilerConfiguration.from_dict(data["bad_setting"])
        good_settings = [CompilerConfiguration.from_dict(g) for g in data["good_settings"]]
        scenario = TestScenario.from_dict(data["scenario"])

        path = Path(data["path"]) if data.get("path") else None

        return cls(
            source_code=data["code"],
            marker=data["marker"],
            bad_compiler=bad_setting,
            good_compilers=good_settings,
            scenario=scenario,
            reduced_code=data.get("reduced_code"),
            bisection_log=data.get("bisection"),
            creation_time=data.get("timestamp", time.time()),
            file_path=path
        )


def find_newest_compiler(repo: repository.Repo, compilers: List[CompilerConfiguration]) -> CompilerConfiguration:
    """Find the compiler closest to the main branch."""
    def compare_revisions(a: CompilerConfiguration, b: CompilerConfiguration) -> int:
        if a.revision == b.revision:
            return 0
        if repo.is_ancestor_of_master(a.revision, b.revision):
            return -1
        return 1

    return max(compilers, key=functools.cmp_to_key(compare_revisions))


def get_scenario_from_args(config: DotNotationDict, 
                          args: argparse.Namespace) -> TestScenario:
    """Build test scenario from command-line arguments."""
    scenario = TestScenario([], [])

    if hasattr(args, 'scenario') and args.scenario:
        scenario = TestScenario.from_file(Path(args.scenario))

    if hasattr(args, 'targets') and args.targets:
        targets = []
        pos = 0
        while pos < len(args.targets):
            compiler_config = get_compiler_config(config, args.targets[pos])
            repo = repository.Repo(compiler_config.repo, compiler_config.main_branch)
            rev = repo.commit_for_revision(args.targets[pos + 1])
            pos += 2

            opt_levels = set(getattr(args, 'targets_default_opt_levels', ['1', '2', '3']))
            while pos < len(args.targets) and args.targets[pos] in ['1', '2', '3', 's', 'z']:
                opt_levels.add(args.targets[pos])
                pos += 1

            for level in opt_levels:
                targets.append(CompilerConfiguration(
                    name=compiler_config.name,
                    revision=rev,
                    optimization_level=level
                ))

        scenario.targets = targets

    if hasattr(args, 'additional_compilers') and args.additional_compilers:
        attackers = []
        pos = 0
        while pos < len(args.additional_compilers):
            compiler_config = get_compiler_config(config, args.additional_compilers[pos])
            repo = repository.Repo(compiler_config.repo, compiler_config.main_branch)
            rev = repo.commit_for_revision(args.additional_compilers[pos + 1])
            pos += 2

            opt_levels = set(getattr(args, 'additional_compilers_default_opt_levels', ['1', '2', '3']))
            while pos < len(args.additional_compilers) and args.additional_compilers[pos] in ['1', '2', '3', 's', 'z']:
                opt_levels.add(args.additional_compilers[pos])
                pos += 1

            for level in opt_levels:
                attackers.append(CompilerConfiguration(
                    name=compiler_config.name,
                    revision=rev,
                    optimization_level=level
                ))

        scenario.attackers = attackers

    return scenario

