def build_log_path(sub_command, base_dir: Path, scenario_file: Path = None) -> str:
    directory = base_dir
    if scenario_file:
        stem = scenario_file.stem
        filename = (
            f"scenario-player-{sub_command}_{stem}"
            f"_{datetime.now():%Y-%m-%dT%H:%M:%S}.log"
        )
        directory = directory.joinpath("scenarios", stem)
    else:
        filename = f"scenario-player-{sub_command}_{datetime.now():%Y-%m-%dT%H:%M:%S}.log"
    return str(directory.joinpath(filename))


def setup_logging_for_command(log_path: str):
    Path(log_path).parent.mkdir(parents=True, exist_ok=True)
    click.secho(f"Logging to {log_path}", fg="yellow")
    configure_logging(
        {"": "INFO", "raiden": "DEBUG", "scenario_player": "DEBUG"},
        debug_log_file_path=log_path,
        _first_party_packages=_FIRST_PARTY_PACKAGES | frozenset(["scenario_player"]),
        _debug_log_file_additional_level_filters={"scenario_player": "DEBUG"},
    )


def load_account_from_keystore(keystore_path, pwd):
    with open(keystore_path, "r") as ks_file:
        account = Account(json.load(ks_file), pwd, keystore_path)
        assert account.address
        log.info("Using account", account=to_checksum_address(account.address))
        return account


def obtain_password(cli_pwd=None, pwd_file=None):
    if pwd_file:
        with open(pwd_file, "r") as f:
            cli_pwd = f.read().strip()
    if cli_pwd is None and pwd_file is None:
        cli_pwd = click.prompt(text="Enter your password: "REDACTED_CREDENTIAL
    return cli_pwd


def retrieve_account(keystore_path, pwd):
    try:
        return load_account_from_keystore(keystore_path, pwd)
    except ValueError:
        raise WrongPassword()


def add_auth_and_credentials(func):
    """Decorator to inject authentication-related CLI options."""
    @click.option("--keystore-file", required=True, type=click.Path(exists=True, dir_okay=False))
    @click.option(
        "--password-file",
        type=click.Path(exists=True, dir_okay=False),
        cls=MutuallyExclusiveOption,
        mutually_exclusive=["password"],
        default=None,
    )
    @click.option(
        "--password",
        envvar="ACCOUNT_PASSWORD",
        cls=MutuallyExclusiveOption,
        mutually_exclusive=["password-file"],
        default=None,
    )
    @functools.wraps(func)
    def decorated(*args, **kwargs):
        return func(*args, **kwargs)
    return decorated


def add_data_directory(func):
    """Decorator to inject data directory option."""
    @click.option(
        "--data-path",
        default=Path(str(Path.home().joinpath(".raiden", "scenario-player"))),
        type=click.Path(exists=False, dir_okay=True, file_okay=False),
        show_default=True,
    )
    @functools.wraps(func)
