@cli_root.command(name="run")
@click.argument("scenario-file", type=click.File(), required=False)
@click.option("--auth", default="")
@click.option("--mailgun-api-key")
@click.option(
    "--notify-tasks",
    type=EnumChoiceType(TaskStatusNotification),
    default=TaskStatusNotification.DISABLED.value,
    help="Notify of task status via chosen method.",
)
@click.option(
    "--ui/--no-ui",
    "enable_ui",
    default=sys.stdout.isatty(),
    help="En-/disable console UI. [default: auto-detect]",
)
@add_auth_and_credentials
@add_chain_option
@add_data_directory
@click.pass_context
def run_scenario(
    ctx,
    chain,
    data_path,
    mailgun_api_key,
    auth,
    password,
    keystore_file,
    scenario_file,
    notify_tasks,
    enable_ui,
    password_file,
):
    """Execute a scenario as defined in scenario definition file.
    Calls :func:`exit` when done, with the following status codes:
        Exit code 1x
        There was a problem when starting up the SP, nodes, deploying tokens
        or setting up services. This points at an issue in the SP and of its
        components.
        Exit code 2x
        There was an error when parsing or evaluating the given scenario definition file.
        This may be a syntax- or logic-related issue.
        Exit code 3x
        There was an assertion error while executing the scenario. This points
        to an error in a `raiden` component (the client, services or contracts).
    """
    data_path = Path(data_path)
    scenario_file = Path(scenario_file.name).absolute()
    log_file_name = build_log_path("run", data_path, scenario_file)
    setup_logging_for_command(log_file_name)
    log.info("Scenario Player version:", version_info=get_complete_spec())
    password = obtain_password(password, password_file)
    account = retrieve_account(keystore_file, password)

    notification_handler = None
    if notify_tasks is TaskStatusNotification.ROCKETCHAT:
        if "RC_WEBHOOK_URL" not in os.environ:
            click.secho(
                "'--notify-tasks rocket-chat' requires env variable 'RC_WEBHOOK_URL' to be set.",
                fg="red",
            )
        notification_handler = post_task_state_to_rc

    log_buffer = None
    if enable_ui:
        log_buffer = attach_urwid_logbuffer()

    # Dynamically import valid Task classes from sceanrio_player.tasks package.
    collect_tasks(tasks)

    report: Dict[str, str] = dict()
    success_event = Event()
    success_event.clear()

    try:
        orchestrate(
            report,
            success_event,
            enable_ui,
            log_buffer,
            log_file_name,
            mailgun_api_key,
            RunnerArguments(
                account, auth, chain, data_path, scenario_file, notification_handler
            ),
        )
    except ScenarioAssertionError as ex:
        log.error("Run finished", result="assertion errors")
        exit_code = getattr(ex, "exit_code", 30)
        report.update(dict(subject=f"Assertion mismatch in {scenario_file.name}", message=str(ex)))
        exit(exit_code)
    except ScenarioError as ex:
        log.error("Run finished", result="scenario error", message=str(ex))
        exit_code = getattr(ex, "exit_code", 20)
        report.update(
            dict(subject=f"Invalid scenario {scenario_file.name}", message=traceback.format_exc())
        )
        exit(exit_code)
    except Exception as ex:
        log.exception("Exception while running scenario")
        exit_code = getattr(ex, "exit_code", 10)
        report.update(
            dict(
                subject=f"Error running scenario {scenario_file.name}",
                message=traceback.format_exc(),
            )
        )
        exit(exit_code)
    else:
        success_event.set()
        exit_code = 0
        log.info("Run finished", result="success")
        report.update(dict(subject=f"Scenario successful {scenario_file.name}", message="Success"))
        log.info("Scenario player unwind complete")
        exit(exit_code)


RunnerArguments = namedtuple(
    "RunnerArguments",
    ["account", "auth", "chain", "data_path", "scenario_file", "notification_handler"],
)


def orchestrate(
    report_container,
    success_event,
    enable_ui,
    log_buffer,
    log_file_name,
    mailgun_api_key,
    runner_args,
):
    with ServiceProcessManager():
        scenario_runner = ScenarioRunner(*runner_args)
        runner_manager = ScenarioRunnerManager(scenario_runner)
        with runner_manager as runner:
            if enable_ui:
                ui_context = ScenarioUIManager(
                    runner, log_buffer, log_file_name, success_event
                )
            else:
                ui_context = nullcontext()
            log.info("Startup complete")
            with ui_context:
                runner.run_scenario()


class ScenarioUIManager:
    def __init__(self, runner, log_buffer, log_file_name, success_event):
        self.ui = ScenarioUI(runner, log_buffer, log_file_name)
        self.success_event = success_event
        self.ui_greenlet = None

    def __enter__(self):
        self.ui_greenlet = self.ui.run()
        return self.success_event

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self.ui.set_success(self.success_event.is_set())
            log.warning("Press q to exit")
            while not self.ui_greenlet.dead:
                gevent.sleep(1)
        finally:
            if self.ui_greenlet is not None and not self.ui_greenlet.dead:
                self.ui_greenlet.kill(ExitMainLoop)
                self.ui_greenlet.join()


class ServiceProcessManager:
    def __enter__(self):
        self.service_process = ServiceProcess()
        self.service_process.start()
        return self.service_process

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self.service_process.stop()
        except ServiceProcessException:
            log.exception("ServiceProcessManager died")
        except Exception:
            log.exception("ServiceProcessManager died")
            self.service_process.kill()


class ScenarioRunnerManager:
    def __init__(self, scenario_runner: ScenarioRunner):
        self.scenario_runner = scenario_runner

    def __enter__(self):
        return self.scenario_runner

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self.scenario_runner.node_controller.stop()
        except ProcessExitedWithError:
            log.exception("ScenarioRunnerManager stop died")
        except Exception:
            log.exception("ScenarioRunnerManager stop died")
            self.scenario_runner.node_controller.kill()


