import triton
import torch

class _matrix_multiply(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input_a, input_b):
        output = _matrix_multiply._execute(input_a, input_b)
        return output

    kernel_cache = {}

    @staticmethod
    def _execute(tensor_x, tensor_y):
        # Determine data type for kernel configuration
        dtype = tensor_x.dtype

        # Reuse compiled kernel if available for this dtype
        if dtype not in _matrix_multiply.kernel_cache:
            kernel_source = """
    __global__ void matmul(TYPE *A __noalias __readonly __aligned(16),
                           TYPE *B __noalias __readonly __aligned(16),
                           TYPE *C __noalias __aligned(16),
                           float scale,
                           int rows_A __retune,
                           int cols_B __retune,
                           int common_dim __retune,
                           int stride_A0 __multipleof(8),
                           int stride_B0 __multipleof(8),
                           int stride_C0 __multipleof(8)) {
      // Thread block indexing
      int tx = get_program_id(0);
      int ty = get_program_id(1);
      int tz = get_program_id(2);

      int tile_rows_A = rows_A / TM;
      int tile_cols_B = cols_B / TN;
      int global_tile_idx = tx + ty * tile_rows_A;
      tx = global_tile_idx / tile_cols_B;
      ty = global_tile_idx % tile_cols_B;

      // Compute row and column indices within tile
      int row_indices[TM] = tx * TM + 0 ... TM;
      int col_indices[TN] = ty * TN + 0 ... TN;

      // Adjust reduction dimension per thread block
      common_dim = common_dim / TZ;
      int reduction_indices[TK] = tz * common_dim + 0 ... TK;

      // Compute offsets for matrix A (TM x TK)
      int offset_A[TM, TK] = reduction_indices[newaxis, :] * STRIDE_AK + 
                             row_indices[:, newaxis] * STRIDE_AM;
      TYPE* ptr_A[TM, TK] = A + offset_A;

      // Compute offsets for matrix B (TK x TN)
      int offset_B[TK, TN] = reduction_indices[:, newaxis] * STRIDE_BK + 
                             col_indices[newaxis, :] * STRIDE_BN;
      TYPE* ptr_B[TK, TN] = B + offset_B;

      // Load data with bounds checking
      bool valid_A[TM, TK] = reduction_indices[newaxis, :] < common_dim;
      bool valid_B[TK, TN] = reduction_indices[:, newaxis] < common_dim;
      TYPE data_A[TM, TK] = valid_A ? *ptr_A : 0;
      TYPE data_B[TK, TN] = valid_B ? *ptr_B : 0;

      // Accumulator initialization
      float accumulator[TM, TN] = 0.0f;

      // Main computation loop
      for(int k = common_dim; k > 0; k -= TK) {
        accumulator += data_A @ data_B;

        // Update pointers and validity checks
        bool next_valid_A[TM, TK] = k > TK;
        bool next_valid_B[TK, TN] = k > TK;
        ptr_A += TK * STRIDE_AK;
        ptr_B += TK * STRIDE_BK;
        data_A = next_valid_A ? *ptr_A : 0;
        data_B = next_valid_B ? *ptr_B : 0;
      }

      // Scale result
      accumulator *= scale;
      TYPE result[TM, TN] = accumulator;

      // Output computation and write-back
      int out_row[TM] = get_program_id(0) * TM + 0 ... TM;
      int out_col[TN] = get_program_id(1) * TN + 0 ... TN;
      int output_offset[TM, TN] = out_row[:, newaxis] * stride_C0 + 
                                  out_col[newaxis, :] * 1;
      TYPE* output_ptr[TM, TN] = C + output_offset;
      bool output_mask[TM, TN] = (out_row[:, newaxis] < rows_A) && 
                                 (out_col[newaxis, :] < cols_B);

#if (TZ==1)
      *?(output_mask) output_ptr = result;
#else
      // Handle accumulation across multiple thread blocks
      int *lock_ptr   = locks + global_tile_idx;
      int *count_ptr  = lock_ptr + get_num_programs(0) * get_num_programs(1);

      // Acquire lock using atomic CAS
      for(int attempt = 1; attempt == 1; attempt = atomic_cas(lock_ptr, 0, 1));

      int current_count = *count_ptr;
      if(current_count == 0) {
        *?(output_mask) output_ptr = result;
      } else {
        *?(output_mask) output_ptr = result + *?(output_mask)output_ptr;
      }

      // Release lock and update count
      atomic_xchg(count_ptr, (current_count + 1) % TZ);
      atomic_xchg(lock_ptr, 0);
#endif
}
            """

            # Define kernel parameters
            kernel_config = {
                'TYPE': dtype,
                'STRIDE_AM': '1', 'STRIDE_AK': 'stride_A0',
                'STRIDE_BN': '1', 'STRIDE_BK': 'stride_B0',
                'TM': [64, 128],
                'TN': [64, 128],
                'TK': [8, 16],
                'TZ': [1]
            }

            # Compile kernel with specified warp count and configuration
