class LaunchSimulator:
    """A restructured variant of LaunchMock with equivalent behavior."""
    active_components: Dict[str, LaunchComponent]
    registered_services: List[Service]
    ui_console: Console
    termination_flag: asyncio.Event

    def __init__(self, initial_components: Dict[str, LaunchComponent], services: List[Service]):
        self.active_components = {}
        # Merge user-provided components and service launch components
        for key, comp in initial_components.items():
            self.active_components[key] = comp
        for svc in services:
            svc_comp = svc.launch_component
            self.active_components[svc_comp.id] = svc_comp

        self.registered_services = list(services)
        self.ui_console = Console()

    def create_launch_task(
        self,
        identifier: str,
        dependencies: Set[str] = None,
        startup_func: Callable[["LaunchSimulator"], Awaitable[Any]] = None,
        setup_func: Callable[["LaunchSimulator"], Awaitable[Any]] = None,
        teardown_func: Callable[["LaunchSimulator"], Awaitable[Any]] = None,
    ) -> LaunchComponent:
        deps = dependencies or set()
        new_task = LaunchComponent(identifier, deps, startup_func, setup_func, teardown_func)  # type: ignore
        self.active_components[identifier] = new_task
        return new_task

    def discard_launch_task(self, identifier: str):
        if identifier not in self.active_components:
            raise KeyError(f"Component '{identifier}' not found.")
        del self.active_components[identifier]

    def register_service(self, service: Service):
        if service in self.registered_services:
            raise ValueError("Service already registered.")
        self.registered_services.append(service)
        comp = service.launch_component
        self.active_components[comp.id] = comp

    def unregister_service(self, service: Service):
        if service not in self.registered_services:
            raise ValueError("Service not registered.")
        self.registered_services.remove(service)
        del self.active_components[service.launch_component.id]

    def fetch_interface(self, interface_class: Type[TInterface]) -> TInterface:
        for svc in self.registered_services:
            if interface_class in svc.supported_interface_types:
                return svc.provide_interface(interface_class)
        raise ValueError(f"Interface {interface_class} is unsupported.")

    async def start_up(self):
        # Configure logging with Rich integration
        logger.configure(
            handlers=[
                {
                    "sink": RichHandler(console=self.ui_console, markup=True),
                    "format": "<green>{time:YYYY-MM-DD HH:mm:ss.SSS}</green> | <level>{level: <8}</level> | "
                    "<cyan>{name}</cyan>: <cyan>{function}</cyan>:<cyan>{line}</cyan> - <level>{message}</level>",
                }
            ]
        )

        # Announce loaded services
        for svc in self.registered_services:
            logger.info(f"Loaded service: {svc.__class__.__name__}")

        logger.info(f"Total launch tasks: {len(self.active_components)}")

        # Prepare phase
        with Status("[orange bold]initializing components...", console=self.ui_console) as spinner:
            for layer in resolve_requirements(set(self.active_components.values())):
                pending_tasks = []
                for comp in layer:
                    if comp.setup:
                        task = asyncio.create_task(comp.setup(self), name=comp.id)
                        task.add_done_callback(lambda t: spinner.update(f"{t.get_name()} initialized."))
                        pending_tasks.append(task)

                if pending_tasks:
                    await asyncio.wait(pending_tasks)

            spinner.update("All components initialized.")
            await asyncio.sleep(1)

        logger.info("[green bold]Initialization complete — proceeding to main execution.")

        loop = asyncio.get_running_loop()
        main_tasks = [
            loop.create_task(comp.run_main(self), name=comp.id)  # type: ignore
            for comp in self.active_components.values()
            if comp.main
        ]

        for task in main_tasks:
            task.add_done_callback(lambda t: logger.info(f"Main task '{t.get_name()}' finished."))

        logger.info(f"Active main tasks: {len(main_tasks)}")

        try:
            await asyncio.gather(*main_tasks)
        except asyncio.CancelledError:
            logger.info("[red bold]Execution cancelled by user.")
            if not self.termination_flag.is_set():
                self.termination_flag.set()
        finally:
            logger.info("[red bold]Main tasks terminated — initiating shutdown sequence.")
            # Cleanup in reverse dependency order
            for layer in reversed(list(resolve_requirements(set(self.active_components.values())))):
                cleanup_tasks = []
                for comp in layer:
                    if comp.cleanup:
                        task = asyncio.create_task(comp.cleanup(self), name=comp.id)
                        task.add_done_callback(lambda t: logger.info(f"{t.get_name()} cleanup done."))
                        cleanup_tasks.append(task)

                if cleanup_tasks:
                    await asyncio.gather(*cleanup_tasks)

            logger.info("[green bold]Shutdown sequence completed.")
            logger.warning("[red bold]Terminating process...")

    def run_forever(self):
        loop = asyncio.new_event_loop()
        self.termination_flag = asyncio.Event(loop=loop)
        main_task = loop.create_task(self.start_up(), name="avilla-main")
        try:
            loop.run_until_complete(main_task)
        except KeyboardInterrupt:
            self.termination_flag.set()
            main_task.cancel()
            loop.run_until_complete(main_task)


class SettingsSimulator:
    """Reimplementation of ConfigMock with equivalent configuration handling."""
    storage: Dict[
        Union[ConfigApplicant, Type[ConfigApplicant]],
        Dict[Hashable, "ConfigProvider[BaseModel]"]
    ]

    def __init__(
        self,
        raw_config: Dict[
            Union[ConfigApplicant[TModel], Type[ConfigApplicant[TModel]]],
            Union[TModel, "ConfigProvider[TModel]", Dict[Hashable, Union[TModel, "ConfigProvider[TModel]"]]],
        ],
    ):
        self.storage = {}
        for applicant, value in raw_config.items():
            scope_map = {}
            if not isinstance(value, dict):
                value = {...: value}

            for key, provider_like in value.items():
                if not isinstance(provider_like, ConfigProvider):
                    if isinstance(provider_like, BaseModel):
                        provider_like = direct(provider_like)  # type: ignore
                    else:
                        raise ValueError(f"Invalid config entry: {provider_like}")
                scope_map[key] = provider_like

            self.storage[applicant] = scope_map

        # Ensure default Avilla config exists
        self.storage.setdefault(Avilla, {...: direct(AvillaConfig())})  # type: ignore

    def retrieve_config(
        self,
        applicant: Union[ConfigApplicant[TModel], Type[ConfigApplicant[TModel]]],
        context: Hashable = ...,
    ) -> Optional[TModel]:
        scoped = self.storage.get(applicant)
        if scoped:
            provider = scoped.get(context)
            if provider:
                return provider.fetch()
        return None

    async def synchronize_configs(self, timing: ConfigFlushingMoment):
        for applicant, scopes in self.storage.items():
            if timing not in applicant.trigger_times.values():
                continue
            for ctx, provider in scopes.items():
                await provider.deliver(self, applicant.model_type, ctx)  # type: ignore

