)

class LimitConfiguration(BaseAwsOptions, BaseOptions):
    service_list: List[str]
    threshold_value: str

    def __init__(
        self,
        verbose_mode: bool,
        filter_criteria: List[Filterable],
        aws_session,
        region_identifier: str,
        services_input,
        threshold_input: str,
    ):
        BaseAwsOptions.__init__(self, aws_session, region_identifier)
        BaseOptions.__init__(self, verbose_mode, filter_criteria)
        self.service_list = services_input if services_input else []
        self.threshold_value = threshold_input


class ServiceLimitManager:
    def __init__(self, session, region_name: str, service_selection, config: LimitConfiguration):
        self.region = region_name
        self.cache_store = ResourceCache()
        self.session = session
        self.config = config
        self.active_services = []

        # Determine which services to process
        if not service_selection:
            for svc in ALLOWED_SERVICES_CODES:
                self.active_services.append(svc)
            for svc in SPECIAL_RESOURCES:
                self.active_services.append(svc)
        else:
            self.active_services = service_selection

    def populate_global_service_cache(self) -> bool:
        """
        Build cache of AWS global service limits (valid for 15 days).
        Some services have global limits that require us-east-1 client.
        """
        for current_service in self.active_services:
            if current_service in ALLOWED_SERVICES_CODES:
                cache_id = f"aws_limits_{current_service}_{self.region}"

                # Skip if already cached
                if self.cache_store.get_key(cache_id) is not None:
                    continue

                if self.config.verbose:
                    message_handler(
                        f"Fetching global limits for {current_service} in {self.region}...",
                        "HEADER"
                    )

                service_limits = {}

                for quota_identifier in ALLOWED_SERVICES_CODES[current_service]:
                    if quota_identifier != "global":
                        # Handle global services requiring us-east-1
                        if ALLOWED_SERVICES_CODES[current_service].get("global", False):
                            quota_client = self.session.client(
                                "service-quotas", region_name="us-east-1"
                            )
                        else:
                            quota_client = self.session.client(
                                "service-quotas", region_name=self.region
                            )

                        limit_data = self.fetch_quota_details(
                            quota_identifier, current_service, quota_client
                        )

                        if limit_data is None:
                            continue

                        if current_service not in service_limits:
                            service_limits[current_service] = []
                        service_limits[current_service].append(limit_data)

                self.cache_store.set_key(
                    key=cache_id, 
                    value=service_limits, 
                    expire=1296000  # 15 days in seconds
                )
        return True

    def fetch_quota_details(self, quota_code: str, service_code: str, quota_client) -> Optional[Dict]:
        try:
            response = quota_client.get_aws_default_service_quota(
                ServiceCode=service_code, QuotaCode=quota_code
            )
        except Exception as error:
            if self.config.verbose:
                log_critical(
                    f"\nFailed to retrieve quota {quota_code} for {service_code}: {error}"
                )
            return None

        return {
            "value": response["Quota"]["Value"],
            "adjustable": response["Quota"]["Adjustable"],
            "quota_code": quota_code,
            "quota_name": response["Quota"]["QuotaName"],
        }


class LimitReportGenerator(BaseAwsCommand):
    def __init__(self, target_regions, session, warning_threshold):
        super().__init__(target_regions, session)
        self.warning_threshold = warning_threshold

    def prepare_service_cache(self, region, services, config: LimitConfiguration):
        ServiceLimitManager(
            session=self.session, 
            region_name=region, 
            service_selection=services, 
            config=config
        ).populate_global_service_cache()

    def execute(
        self,
        generate_diagram: bool,
        debug_mode: bool,
        service_filter: List[str],
        filter_rules: List[Filterable],
    ):
        # Default to all services if none specified
        active_services = service_filter if service_filter else []
        if not service_filter:
            for svc in ALLOWED_SERVICES_CODES:
                active_services.append(svc)
            for svc in SPECIAL_RESOURCES:
                active_services.append(svc)

        # Process each region
        for region in self.region_names:
            config = LimitConfiguration(
                verbose_mode=debug_mode,
                filter_criteria=filter_rules,
                aws_session=self.session,
                region_identifier=region,
                services_input=active_services,
                threshold_input=self.warning_threshold,
            )

            self.prepare_service_cache(
                region=region, 
                services=active_services, 
                config=config
            )

            processor = AwsCommandRunner(services=active_services)
            processor.execute(
                provider="limit",
                options=config,
                diagram_builder=NoDiagram(),
                title=f"AWS Limits - Region {region}",
                filename=config.resulting_file_name("limit"),
            )

