class ClickMutex(click.Option):
    """Mutual exclusion of options"""
    def __init__(self, *args, **kwargs):
        self.conflicting_opts: list = kwargs.pop("mutually_exclusive_with", [])
        self.dependent_opts: list = kwargs.pop("required_if", [])

        if self.conflicting_opts:
            kwargs["help"] = (
                kwargs.get("help", "")
                + "Option is mutually exclusive with "
                + ", ".join(self.conflicting_opts)
                + "."
            ).strip()
        if self.dependent_opts:
            kwargs["help"] = (
                kwargs.get("help", "")
                + "Option is required only if "
                + " or ".join(self.conflicting_opts)
                + " is specified "
            ).strip()
        super().__init__(*args, **kwargs)

    def handle_parse_result(self, ctx, opts, args):
        opt_name = self.name
        if opt_name in opts:
            for conflict in self.conflicting_opts:
                if conflict in opts:
                    raise click.UsageError(
                        f"Option {opt_name} is mutually exclusive with {conflict}."
                    )
        else:
            for dep in self.dependent_opts:
                if dep in opts:
                    raise click.UsageError(
                        f"Option {opt_name} is required when {dep} is specified."
                    )
        return super().handle_parse_result(ctx, opts, args)


class OptionEatAll(click.Option):
    """
    Taken from https://stackoverflow.com/questions/48391777/nargs-equivalent-for-options-in-click#answer-48394004.
    """  # noqa: ignore=E501 pylint: disable=C0301
    @overrides
    def __init__(self, *args, **kwargs):
        self.retain_remaining = kwargs.pop("save_other_options", True)
        super().__init__(*args, **kwargs)
        self._prev_parser_action: Optional[
            Callable[[Union[str, Tuple[str, ...]], click.parser.ParsingState], None]
        ] = None
        self._eat_all_parser_obj = None

    @overrides
    def add_to_parser(self, parser, ctx):
        def parser_action(value: str, state: click.parser.ParsingState):
            """method to hook to the parser.process"""
            value_list = [value]
            if self._eat_all_parser_obj is not None and self.retain_remaining:
                # collect everything up to the next option
                finished = False
                while state.rargs:
                    for prefix in self._eat_all_parser_obj.prefixes:
                        if state.rargs[0].startswith(prefix):
                            finished = True
                            break
                    if finished:
                        break
                    value_list.append(state.rargs.pop(0))
            else:
                # collect all remaining arguments
                value_list.extend(state.rargs)
                state.rargs.clear()
            # invoke original processing
            if self._prev_parser_action is not None:
                self._prev_parser_action(tuple(value_list), state)
        super().add_to_parser(parser, ctx)
        for name in self.opts:
            # pylint: disable=protected-access
            our_parser = parser._long_opt.get(name) or parser._short_opt.get(name)
            if our_parser:
                self._eat_all_parser_obj = our_parser
                self._prev_parser_action = our_parser.process  # type: ignore
                our_parser.process = parser_action
                break


