DictStrHier = Dict[str, Any]
StrOrDictStrHier = Union[str, DictStrHier]


def settings_to_dict(
    settings: Union[
        None, List[str], Tuple[str, ...], Dict[str, StrOrDictStrHier], Flow.Settings
    ],
) -> Dict[str, Any]:
    if not settings:
        return {}
    if isinstance(settings, (tuple, list)):
        result: DictStrHier = {}
        for override in settings:
            parts = override.split("=")
            if len(parts) != 2:
                raise ValueError("Settings should be in KEY=VALUE format!")
            key, val = parts
            set_hierarchy(result, key, try_convert(val, convert_lists=True))
        return result
    if isinstance(settings, Flow.Settings):
        return asdict(settings)
    if isinstance(settings, dict):
        return settings
    raise TypeError(f"overrides is of unsupported type: {type(settings)}")


def print_flow_settings(flow, options: XedaOptions):
    flow_class = discover_flow_class(flow)
    schema = flow_class.Settings.schema(by_alias=True)
    type_defs = {}

    def extract_type(field):
        if isinstance(field, (list, tuple)):
            return Text("|".join(str(extract_type(f)) for f in field))
        typ = field.get("type")
        ref = field.get("$ref")
        if typ is None and ref:
            typ = ref.split("/")[-1]
            typ_def = schema.get("definitions", {}).get(typ)
            if typ not in type_defs:
                type_defs[typ] = typ_def
            elif type_defs[typ] != typ_def:
                log.critical(
                    "type definition for %s changed!\nPrevious def:\n %s new def:\n %s",
                    typ,
                    type_defs[typ],
                    typ_def,
                )
            return Text(typ, style="blue")
        additional = field.get("additionalProperties")
        if typ == "object" and additional:
            return Text(f"Dict[string -> {extract_type(additional)}]")
        if typ == "array":
            items = field.get("items")
            if items:
                return Text(f"array[{extract_type(items)}]")
        def combine_types(lst, combiner, style="red"):
            return reduce(
                lambda x, y: x + Text(combiner, style) + y, (extract_type(t) for t in lst)
            )
        allof = field.get("allOf")
        if allof:
            return combine_types(allof, " & ")  # intersection
        anyof = field.get("anyOf")
        if anyof:
            return combine_types(anyof, " | ")  # union
        return Text(typ)

    table = Table(
        title=f"{flow} settings",
        show_header=True,
        header_style="bold yellow",
        title_style=Style(frame=True, bold=True),
        box=box.HEAVY_HEAD,
        show_lines=True,
    )
    table.add_column("Property", header_style="bold green", style="bold")
    table.add_column("Type", max_width=32)
    table.add_column("Default", max_width=42)
    table.add_column("Description")

    def format_default(v: Any) -> str:
        if isinstance(v, str):
            return f'"{v}"'
        if isinstance(v, bool):
            return str(v).lower()
        return str(v)

    for name, field in schema.get("properties", {}).items():
        if name in ["results"] or name in Flow.Settings.__fields__.keys():
            continue
        required = name in schema.get("required", [])
        desc: str = field.get("description", "")
        typ = extract_type(field)
        req_or_def = (
            "[red]<required>[/red]" if required else format_default(field.get("default"))
        )
        table.add_row(name, typ, req_or_def, desc)
    console.print(table)

    for typ_name, typ_def in list(type_defs.items()):
        for prop, prop_def in typ_def.get("properties").items():
            extract_type(prop_def)

    for typ_name, typ_def in list(type_defs.items()):
        c = "blue"
        table = Table(
            title=f"Type [{c}]{typ_name}[/{c}]",
            show_header=True,
            header_style="bold green",
            title_style=Style(frame=True, bold=True),
            box=box.SQUARE_DOUBLE_HEAD,
            show_lines=True,
        )
        if options.debug:
            console.print(f"Type: {typ_name}")
            console.print_json(data=typ_def)
        table.add_column("property")
        table.add_column("type")
        table.add_column("description")
        for prop, prop_def in typ_def.get("properties").items():
            if prop_def.get("hidden_from_schema"):
                continue
            if (
                typ_name.endswith("__Settings")
                and prop in Flow.Settings.__fields__.keys()
            ):
                continue
            desc = prop_def.get("description", prop_def.get("title", "-"))
            desc = re.sub(r"\s*\.*\s*$", "", desc)
            table.add_row(prop, extract_type(prop_def), desc)
        console.print(table)


def discover_flow_class(flow: str) -> Type[Flow]:
    try:
        return get_flow_class(flow, "xeda.flows", __package__)
    except FlowNotFoundError:
        log.critical(
            "Flow %s is not known to Xeda. Please make sure the name is correctly specified.",
            flow,
        )
        sys.exit(1)

# Type III Clone: Refactored Collaboration Model with Equivalent Logic

import uuid
import logging
from flask_login import current_user
from app.extensions import db, HoustonModel
import app.extensions.logging as AuditLog
from app.utils import HoustonException

log = logging.getLogger(__name__)

# State definitions - same values but different structure
class UserCollabStatus:
    VALID_STATES = [
        'rejected',      # was 'declined'
        'granted',       # was 'approved'
        'awaiting',      # was 'pending'
        'uninitiated',   # was 'not_initiated'
        'withdrawn',     # was 'revoked'
        'originator',    # was 'creator'
    ]

    REJECTED = VALID_STATES[0]
    GRANTED = VALID_STATES[1]
    AWAITING = VALID_STATES[2]
    UNINITIATED = VALID_STATES[3]
    WITHDRAWN = VALID_STATES[4]
    ORIGINATOR = VALID_STATES[5]

class UserCollabLink(db.Model, HoustonModel):
    """
    Many-to-many link between users and collaborations.
    Enforces maximum of two participants per collaboration.
    """
    __mapper_args__ = {
        'confirm_deleted_rows': False,
    }

    collab_guid = db.Column(
        db.GUID, db.ForeignKey('collaboration.guid'), default=uuid.uuid4, primary_key=True
    )
    collab = db.relationship(
        'Collaboration', back_populates='user_links'
    )
    user_guid = db.Column(db.GUID, db.ForeignKey('user.guid'), primary_key=True)
    user = db.relationship('User', backref=db.backref('user_collab_links'))

    view_permission = db.Column(
        db.String(length=32), default=UserCollabStatus.AWAITING, nullable=False
    )
    edit_permission = db.Column(
        db.String(length=32), default=UserCollabStatus.UNINITIATED, nullable=False
    )

    def remove(self):
        self.collab.handle_user_removal(self)

    def can_view(self):
        return self.collab.user_has_view_access(self.user_guid)

    def can_edit(self):
        return self.collab.user_has_edit_access(self.user_guid)

    def get_peer_user(self):
        return self.collab.get_other_member(self.user_guid)

class Collaboration(db.Model, HoustonModel):
    """
    Database model for collaborative projects.
    """
    __mapper_args__ = {
        'confirm_deleted_rows': False,
    }

    guid = db.Column(
        db.GUID, default=uuid.uuid4, primary_key=True
    )

    user_links = db.relationship(
        'UserCollabLink', back_populates='collab'
    )

    creator_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=False
    )
    edit_requester_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=True
    )

    def __init__(self, participants, requestor, **kwargs):
        participant_count = len(participants)
        if participant_count != 2:
            raise ValueError('A collaboration must have exactly two participants.')

        if not hasattr(requestor, 'is_user_manager'):
            raise ValueError(f'Requestor {requestor} is not a valid user')

        # Check if manager created the collaboration
        manager_initiated = requestor not in participants
        if manager_initiated and not requestor.is_user_manager:
            raise ValueError(
                f'Non-manager {requestor.email} attempted to create a collaboration.'
            )

        self.creator_guid = requestor.guid
        self.edit_requester_guid = None

        for member in participants:
            if not hasattr(member, 'is_user_manager'):
                raise ValueError(f'Invalid user {member}')

            link = UserCollabLink(
                collab=self, user=member
            )
            link.edit_permission = UserCollabStatus.UNINITIATED

            with db.session.begin(subtransactions=True):
                db.session.add(link)

            # Auto-grant view permission for initiators and managers
            if member == requestor or manager_initiated:
                link.view_permission = UserCollabStatus.GRANTED
            else:
                link.view_permission = UserCollabStatus.AWAITING

        if manager_initiated:
            originator_link = UserCollabLink(
                collab=self, user=requestor
            )
            from app.modules.notifications.models import NotificationType
            originator_link.view_permission = UserCollabStatus.ORIGINATOR
            originator_link.edit_permission = UserCollabStatus.ORIGINATOR

            for member in participants:
                member_link = self._find_link_for_user(member.guid)
                self._send_notification(
                    originator_link, member_link, NotificationType.collab_manager_create
                )

            with db.session.begin(subtransactions=True):
                db.session.add(originator_link)

    def _find_link_for_user(self, user_id):
        for link in self.user_links:
            if link.user_guid == user_id:
                return link
        return None

    def _find_peer_link(self, user_id):
        peer_link = None
        if user_id is not None:
            other_ids = [
                link.user_guid
                for link in self.user_links
                if (link.user_guid != user_id) and 
                   (link.view_permission != UserCollabStatus.ORIGINATOR)
            ]
            assert len(other_ids) == 1
            peer_link = self._find_link_for_user(other_ids[0])
        return peer_link

    def get_members(self):
        members = []
        for link in self.user_links:
            if link.view_permission != UserCollabStatus.ORIGINATOR:
                members.append(link.user)
        return members

    def get_member_ids(self):
        ids = []
        for link in self.user_links:
            if link.view_permission != UserCollabStatus.ORIGINATOR:
                ids.append(link.user_guid)
        return ids

    def alert_pending_users(self):
        for link in self.user_links:
            if (
                link.view_permission == UserCollabStatus.AWAITING or
                link.edit_permission == UserCollabStatus.AWAITING
            ):
                from app.modules.notifications.models import NotificationType
                peer_link = self._find_peer_link(link.user.guid)

                if link.view_permission == UserCollabStatus.AWAITING:
                    self._send_notification(
                        peer_link, link, NotificationType.collab_request
                    )

                if link.edit_permission == UserCollabStatus.AWAITING:
                    self._send_notification(
                        peer_link, link, NotificationType.collab_edit_request
                    )

    def _send_notification(self, sender_link, receiver_link, notification_type):
        from app.modules.notifications.models import Notification, NotificationBuilder
        builder = NotificationBuilder(sender_link.user)
        builder.set_collaboration(self)
        Notification.create(notification_type, receiver_link.user, builder)

    def get_participant_data(self):
        from app.modules.users.schemas import BaseUserSchema
        data = {}
        for link in self.user_links:
            if link.view_permission == UserCollabStatus.ORIGINATOR:
                continue
            user_info = BaseUserSchema().dump(link.user).data
            user_info['viewState'] = link.view_permission
            user_info['editState'] = link.edit_permission
            data[str(link.user_guid)] = user_info
        return data

    def _validate_state_change(self, previous, new):
        allowed = False

        # Define valid transitions
        if previous == UserCollabStatus.UNINITIATED:
            allowed = new in [
                UserCollabStatus.ORIGINATOR,
                UserCollabStatus.GRANTED,
                UserCollabStatus.AWAITING,
            ]
        elif previous == UserCollabStatus.AWAITING:
            allowed = new in [
                UserCollabStatus.GRANTED,
                UserCollabStatus.REJECTED,
            ]
        elif previous == UserCollabStatus.GRANTED:
            allowed = new == UserCollabStatus.WITHDRAWN
        elif previous == UserCollabStatus.REJECTED:
            allowed = new == UserCollabStatus.GRANTED
        elif previous == UserCollabStatus.WITHDRAWN:
            allowed = new == UserCollabStatus.GRANTED

        # Allow no-op changes
        if not allowed:
            allowed = previous == new

        return allowed

    def update_view_permission(self, user_id, new_status):
        updated = False

        if new_status not in UserCollabStatus.VALID_STATES:
            raise ValueError(
                f'Invalid state "{new_status}". Must be one of: {", ".join(UserCollabStatus.VALID_STATES)}'
            )

        if user_id is not None:
            assert isinstance(user_id, uuid.UUID)
            for link in self.user_links:
                if link.user_guid == user_id:
                    if self._validate_state_change(
                        link.view_permission, new_status
                    ):
                        link.view_permission = new_status

                        # If view access is revoked and edit was granted, revoke edit too
                        if (
                            new_status == UserCollabStatus.WITHDRAWN and
                            link.edit_permission == UserCollabStatus.GRANTED
                        ):
                            link.edit_permission = new_status

                        from app.modules.notifications.models import NotificationType
                        if new_status == UserCollabStatus.WITHDRAWN:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_id),
                                NotificationType.collab_revoke,
                            )
                        elif new_status == UserCollabStatus.GRANTED:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_id),
                                NotificationType.collab_approved,
                            )

                        with db.session.begin(subtransactions=True):
                            db.session.merge(link)
                        updated = True
        return updated

    def user_has_view_access(self, user_id):
        has_access = False
        assert isinstance(user_id, uuid.UUID)

        my_link = self._find_link_for_user(user_id)
        peer_link = self._find_peer_link(user_id)

        if my_link and peer_link:
            has_access = (
                my_link.view_permission == UserCollabStatus.GRANTED and
                peer_link.view_permission == UserCollabStatus.GRANTED
            )
        return has_access

    def user_has_edit_access(self, user_id):
        has_access = False
        assert isinstance(user_id, uuid.UUID)

        my_link = self._find_link_for_user(user_id)
        peer_link = self._find_peer_link(user_id)

        if my_link and peer_link:
            has_access = (
                my_link.edit_permission == UserCollabStatus.GRANTED and
                peer_link.edit_permission == UserCollabStatus.GRANTED
            )
        return has_access

    def get_other_member(self, user_id):
        peer = self._find_peer_link(user_id)
        return peer.user if peer else None

    def update_edit_permission(self, user_id, new_status):
        updated = False

        if new_status not in UserCollabStatus.VALID_STATES:
            raise ValueError(
                f'Invalid state "{new_status}". Must be one of: {", ".join(UserCollabStatus.VALID_STATES)}'
            )

        if user_id is not None:
            assert isinstance(user_id, uuid.UUID)
            for link in self.user_links:
                if link.user_guid == user_id:
                    if self._validate_state_change(
                        link.edit_permission, new_status
                    ):
                        link.edit_permission = new_status

                        with db.session.begin(subtransactions=True):
                            db.session.merge(link)

                        from app.modules.notifications.models import NotificationType
                        if new_status == UserCollabStatus.WITHDRAWN:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_id),
                                NotificationType.collab_edit_revoke,
                            )
                        elif new_status == UserCollabStatus.GRANTED:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_id),
                                NotificationType.collab_edit_approved,
                            )
                        updated = True
        return updated

    def start_edit_session(self):
        self.edit_requester_guid = current_user.guid
        my_link = self._find_link_for_user(current_user.guid)
        peer_link = self._find_peer_link(current_user.guid)

        if (
            my_link.view_permission == UserCollabStatus.GRANTED and
            peer_link.view_permission == UserCollabStatus.GRANTED
        ):
            if self._validate_state_change(
                my_link.view_permission, UserCollabStatus.GRANTED
            ):
                my_link.edit_permission = UserCollabStatus.GRANTED
                with db.session.begin(subtransactions=True):
                    db.session.merge(my_link)

            if self._validate_state_change(
                peer_link.edit_permission, UserCollabStatus.AWAITING
            ):
                peer_link.edit_permission = UserCollabStatus.AWAITING
                with db.session.begin(subtransactions=True):
                    db.session.merge(peer_link)
        else:
            raise HoustonException(
                log, 'Cannot start edit on unapproved collaboration'
            )

    def can_user_access(self, user):
        return user in self.get_members()

    def __repr__(self):
        return (
            '<{class_name}('
            'guid={self.guid}, '
            ')>'.format(class_name=self.__class__.__name__, self=self)
        )

    def handle_user_removal(self, user_link):
        if user_link.view_permission == UserCollabStatus.ORIGINATOR:
            # Handle originator removal by selecting new initiator
            remaining_links = [
                link for link in self.user_links if link != user_link
            ]
            new_originator = remaining_links[0] if remaining_links else None

            if new_originator:
                message = (
                    f'Originator removed, assigning {new_originator.user_guid} as new initiator'
                )
                AuditLog.audit_log_object(log, self, message)
                self.creator_guid = new_originator.user_guid

                with db.session.begin(subtransactions=True):
                    db.session.merge(self)
                    db.session.delete(user_link)
        else:
            # Remove entire collaboration if non-originator is removed
            self.remove()

    def remove(self):
        AuditLog.delete_object(log, self)
        with db.session.begin(subtransactions=True):
            for link in self.user_links:
                db.session.delete(link)
            db.session.delete(self)

