from botsdk.tool.Error import printTraceBack

async def fetch_url(url, proxy=None, headers=None, return_bytes=False):
    try:
        async with aiohttp.ClientSession(headers=headers if headers is not None else None) as session:
            async with session.get(url, proxy=proxy if proxy is not None else None, ssl=False) as response:
                if return_bytes:
                    return await response.read()
                return await response.text()
    except Exception:
        printTraceBack()
        return None

async def send_post_request(url, payload, return_bytes=False):
    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                url,
                data=json.dumps(payload).encode("utf-8"),
                ssl=False
            ) as response:
                if return_bytes:
                    return await response.read()
                return await response.text()
    except Exception:
        printTraceBack()
        return None

# nanogi Blender Exporter - YAML format (.yml)

import os
import bpy
from bpy_extras.io_utils import ExportHelper
from .yaml import dump
from .primCamera import *
from .primMesh import *
from .primLamp import *

bl_info = {
  "name" : "nanogi",
  "category" : "Import-Export",
  "version" : ( 0, 0 ),
  "blender" : ( 2, 7, 3 )
}

class ExportNanogi( bpy.types.Operator, ExportHelper ):
  bl_label = "Export nanogi"
  bl_idname = "export.nanogi"
  filename_ext = ".yml"

  flag_selection = bpy.props.BoolProperty(
    name = "Selection Only",
    description = "Export selected objects only",
    default = False
  )

  def export_scene( self, filepath ):
    # Initialize output structure
    directory = os.path.dirname( filepath ) + "/"
    result = {
      "version" : 5,
      "scene" : {
        "primitives" : []
      }
    }

    # Store original selection state
    current_selection = list(bpy.context.selected_objects)
    for obj in current_selection:
      obj.select = False

    # Determine which objects to process
    source_objects = []
    if self.flag_selection:
      source_objects = current_selection
    else:
      source_objects = list(bpy.data.objects)

    # Process and prepare objects for export
    processed_objects = []
    for original_obj in source_objects:
      original_obj.select = True
      bpy.ops.object.duplicate()
      bpy.ops.mesh.separate( type = "MATERIAL" )

      for new_obj in bpy.context.selected_objects:
        processed_objects.append( new_obj )
        new_obj.select = False
      original_obj.select = False

    # Generate primitives for each object
    for obj in processed_objects:
      primitive_data = {}
      if obj.type == "CAMERA":
        primitive_data = primCamera( obj )
      elif obj.type == "MESH":
        primitive_data = primMesh( obj, directory )
      elif obj.type == "LAMP":
        primitive_data = primLamp( obj, directory )
      result[ "scene" ][ "primitives" ].append( primitive_data )

    # Write YAML file
    with open( filepath, "w" ) as file_handle:
      file_handle.write( dump( result ) )

    # Cleanup: delete temporary duplicated objects
    for obj in processed_objects:
      obj.select = True
    bpy.ops.object.delete()

    # Restore original selection
    for obj in current_selection:
      obj.select = True

  def execute( self, context ):
    self.export_scene( self.filepath )
    return { "FINISHED" }

def draw_menu_item( self, context ):
    self.layout.operator( ExportNanogi.bl_idname, text = "nanogi (.yml)" )

def register():
  bpy.utils.register_module( __name__ )
  bpy.types.INFO_MT_file_export.append( draw_menu_item )

def unregister():
  bpy.utils.unregister_module( __name__ )
  bpy.types.INFO_MT_file_export.remove( draw_menu_item )

from aoc2021.util import print_solutions, import_strs
import timeit

MARKER = "X"

def calculate_unmarked_sum(grid):
    total = 0
    for row in grid:
        for cell in row:
            if cell != MARKER:
                total += cell
    return total

def apply_mark(grid, number):
    found = False
    for r_idx, row in enumerate(grid):
        for c_idx, val in enumerate(row):
            if val == number:
                grid[r_idx][c_idx] = MARKER
                found = True
    return found

def is_bingo(grid):
    size = len(grid)
    # Check rows
    for row in grid:
        if all(cell == MARKER for cell in row):
            return True

    # Check columns
    for col in range(size):
        if all(grid[row][col] == MARKER for row in range(size)):
            return True

    return False

def parse_input(filepath):
    with open(filepath) as file:
        content = file.read().splitlines()

    drawn_numbers = list(map(int, content[0].split(',')))
    boards = []
    current_board = []

    for line in content[1:]:
        stripped = line.strip()
        if not stripped:
            if current_board:
                boards.append(current_board)
                current_board = []
            continue

        numbers = [int(n) for n in stripped.split() if n]
        current_board.append(numbers)

    if current_board:
        boards.append(current_board)

    return drawn_numbers, boards

def solve_first_winning(inputs):
    drawn, grids = inputs
    for num in drawn:
        for grid in grids:
            if apply_mark(grid, num) and is_bingo(grid):
                return calculate_unmarked_sum(grid) * num
    return None

def solve_last_winning(inputs):
    drawn, grids = inputs
    remaining_grids = grids[:]
    final_score = None

    for num in drawn:
        # Remove already-bingoed boards to avoid reprocessing
        active_grids = [g for g in remaining_grids if g is not None]
        if not active_grids:
            break

        for idx, grid in enumerate(remaining_grids):
            if grid is None:
                continue

            if apply_mark(grid, num):
                if is_bingo(grid):
                    final_score = calculate_unmarked_sum(grid) * num
                    remaining_grids[idx] = None

    return final_score

def main():
    print_solutions(
        ["resources/day4-test.txt", "resources/day4.txt"],
        parse_input,
        solve_last_winning
    )

if __name__ == "__main__":
    main()

import os
import subprocess
import tempfile
from typing import Dict, Generator

class GitProjectAnalyzer:
    """Analyzes Python files in a git repository."""

    def __init__(self, repo_url: str) -> None:
        self._file_contents = {}  # type: Dict[str, str]

        try:
            with tempfile.TemporaryDirectory() as temp_dir:
                # Clone the repository into the temporary directory
                subprocess.run(['git', 'clone', repo_url, temp_dir], 
                             capture_output=True)

                # Collect and read all Python files
                for file_path in self._list_python_files(temp_dir):
                    try:
                        with open(file_path, 'r', encoding='utf-8') as file:
                            self._file_contents[file_path] = file.read()
                    except (IOError, OSError) as error:
                        print(f"Failed to read {file_path}: {error}")
        except Exception as error:
            print(f"Repository initialization failed: {error}")

    def _list_python_files(self, base_dir: str) -> Generator[str, None, None]:
        """Recursively find all .py files in the given directory."""
        for root, _, files in os.walk(base_dir):
            for name in files:
                if name.endswith('.py'):
                    yield os.path.join(root, name)

    @property
    def source_files(self) -> Dict[str, str]:
        """Returns dictionary mapping file paths to their contents."""
        return self._file_contents

import json
from pathlib import Path
import click
import matplotlib.pyplot as plt
from ..common import METRICS

@click.command()
@click.option("--datadir", help="Directory containing the dataset.", required=True, type=click.Path())
@click.option("--outdir", help="Directory where to save plots.", required=True, type=click.Path())
@click.option("--configs", help="Comma-separated list of configurations.", required=True)
@click.option("--nodes", help="Comma-separated list of node counts.", required=True)
def generate(datadir, outdir, configs, nodes):
    run_plot_generation(datadir, outdir, configs.split(","), nodes.split(","))

def run_plot_generation(datadir, outdir, config_list, node_list):
    # Load all sample data
    all_samples = {}
    for cfg in config_list:
        all_samples[cfg] = {}
        for node_count in node_list:
            sample_path = f"{datadir}/{cfg}/{node_count}nodes/samples.json"
            with open(sample_path) as file:
                all_samples[cfg][str(node_count)] = json.load(file)

    # Process each metric
    for metric_name in [m["name"] for m in METRICS]:
        dataset = {}

        # Build data arrays per configuration
        for cfg in config_list:
            dataset[cfg] = [
                [float(val) for val in all_samples[cfg][str(n)][f"{metric_name}Sample"].split(",")]
                for n in node_list
            ]

        # Initialize figure
        fig, axis = plt.subplots(figsize=(10, 5), layout="constrained")

        # Set plot labels and title
        unit = next(m["unit"] for m in METRICS if m["name"] == metric_name)
        axis.set_title(f"AWS ParallelCluster\n{metric_name}", fontweight="bold")
        axis.set_xlabel("Compute Nodes", fontweight="bold")
        axis.set_ylabel(f"Time ({unit})", fontweight="bold")

        num_configs = len(config_list)
        num_nodes = len(node_list)
        total_positions = list(range(1, num_configs * num_nodes + 1))

        # Generate boxplots per configuration
        plot_handles = {}
        for idx, cfg in enumerate(config_list):
            pos = total_positions[idx::num_configs]
            plot_handles[cfg] = axis.boxplot(
                dataset[cfg],
                patch_artist=True,
                boxprops=dict(facecolor="palegreen" if cfg == "baseline" else "steelblue"),
                labels=node_list,
                positions=pos,
            )

        # Create legend using first box from each configuration
        legend_entries = [plot_handles[c]["boxes"][0] for c in plot_handles]
        axis.legend(legend_entries, config_list, loc="upper left")

        # Save figure
        output_file = Path(outdir) / f"{metric_name}.png"
        output_file.parent.mkdir(parents=True, exist_ok=True)
        plt.savefig(output_file.resolve())

