class Root:
    """Root base class for hierarchy."""
    def __init__(self, label):
        self.label = label

    def __eq__(self, other) -> bool:
        return type(self) is type(other) and self.label == other.label

class First(Root):
    """First subclass of Root."""
    pass

class Second(Root):
    """Second subclass of Root."""
    pass

class Third(Root):
    """Third subclass of Root."""
    pass

class AlternativeRoot:
    """Alternative root class."""
    pass

class FirstAlt(AlternativeRoot):
    """First subclass of AlternativeRoot."""
    pass

class TestResolverFunctionality(unittest.TestCase):
    """Tests for resolver functionality."""

    def setUp(self) -> None:
        """Initialize resolver instance before each test."""
        self.resolver = Resolver([First, Second, Third], base=Root)

    def test_class_lookup(self):
        """Verify correct class lookup by name."""
        self.assertEqual(First, self.resolver.lookup("first"))
        self.assertEqual(First, self.resolver.lookup("First"))

    def test_iterable_behavior(self):
        """Ensure resolver supports iteration over registered classes."""
