from bson.binary import Binary
from typing import Union, Dict, Any, Optional, List, Iterable
from ampel.types import StockId, ChannelId, StrictIterable, strict_iterable
from ampel.model.operator.AnyOf import AnyOf
from ampel.model.operator.AllOf import AllOf
from ampel.model.operator.OneOf import OneOf
from ampel.util.collections import check_seq_inner_type
from ampel.mongo.utils import maybe_match_array
from ampel.mongo.query.general import build_general_query


def construct_stateless_filter(
    ids: Optional[Union[StockId, StrictIterable[StockId]]] = None,
    channels: Optional[Union[ChannelId, Dict, AllOf[ChannelId], AnyOf[ChannelId], OneOf[ChannelId]]] = None,
    t2_units: Union[int, str, StrictIterable[Union[int, str]]] = None
) -> Dict[str, Any]:
    """
    Constructs a MongoDB query to fetch transient-related documents (t2 or compounds),
    without restricting by state — i.e., all matching records are considered.

    :param ids: one or more stock identifiers
    :param channels: channel(s) to filter on; if omitted, no channel restriction is applied
    :param t2_units: optional filter for specific T2 unit names/classes
    """
    base_filter = build_general_query(stock=ids, channel=channels)

    if t2_units:
        # Convert scalar or iterable into appropriate query format
        if isinstance(t2_units, (str, int)):
            base_filter['unit'] = t2_units
        else:
            base_filter['unit'] = maybe_match_array(t2_units)

    return base_filter


def build_transient_t1_filter_by_state(
    state_data: Union[str, bytes, Binary, StrictIterable[Union[str, bytes, Binary]]],
) -> Dict[str, Any]:
    """Builds a query to match compound documents by their binary state representation."""
    return {'_id': _compile_state_match(state_data)}


def build_transient_t2_filter_by_state(
    stock_ids: Optional[Union[StockId, StrictIterable[StockId]]],
    state_data: Union[str, bytes, Binary, StrictIterable[Union[str, bytes, Binary]]],
    channels: Optional[Union[ChannelId, Dict, AllOf[ChannelId], AnyOf[ChannelId], OneOf[ChannelId]]] = None,
    t2_units: Union[int, str, StrictIterable[Union[int, str]]] = None
) -> Dict[str, Any]:
    """
    Similar to `construct_stateless_filter`, but restricts results to those
    associated with specific compound states.

    :param stock_ids: transient identifiers to consider
    :param state_data: one or more binary state values
    :param channels: optional channel constraints
    :param t2_units: optional T2 class filters
    """
    base_filter = build_general_query(stock=stock_ids, channel=channels)
    base_filter['link'] = _compile_state_match(state_data)

    if t2_units:
        if isinstance(t2_units, (str, int)):
            base_filter['unit'] = t2_units
        else:
            base_filter['unit'] = maybe_match_array(t2_units)

    return base_filter


def _normalize_to_binary(raw_state: Union[str, bytes, Binary]) -> Binary:
    """Converts various input types into a BSON Binary object with subtype 0."""
    if isinstance(raw_state, str):
        if len(raw_state) == 32:
            return Binary(bytes.fromhex(raw_state), 0)
        else:
            raise ValueError("Hex string must be exactly 32 characters long")
    elif isinstance(raw_state, bytes):
        if len(raw_state) == 16:
            return Binary(raw_state, 0)
        else:
            raise ValueError("Byte sequence must be exactly 16 bytes long")
    else:
        if raw_state.subtype == 0:
            return raw_state
        else:
            raise ValueError("Only Binary objects with subtype 0 are accepted")


def _compile_state_match(
    states: Union[str, bytes, Binary, StrictIterable[Union[str, bytes, Binary]]],
) -> Union[Binary, Dict[str, List[Binary]]]:
    """
    Converts one or more state representations into either a single Binary value
    or a $in clause for multiple matches.

    :raises ValueError: if any state fails validation
    """
    # Handle single-state case
    if isinstance(states, (str, bytes, Binary)):
        return _normalize_to_binary(states)

    # Handle list-like case
    elif isinstance(states, Iterable) and not isinstance(states, (str, bytes)):
        normalized_list = []
        for item in states:
            normalized_list.append(_normalize_to_binary(item))
        return {'$in': normalized_list}

    else:
        raise TypeError(
            f"Unsupported type for state input: {type(states)}. "
            "Expected str, bytes, Binary, or an iterable of these."
        )

import enum
import logging
from typing import Any, Callable, Dict, Iterable, List, Optional, Tuple, Set
from .schema_utils import JsonSchema, SchemaEnum
logger = logging.getLogger(__name__)

class EnumCollection(object):
    def __init__(
        self,
        constants: Optional[Set[Any]] = None,
        subitems: Optional[Dict[str, "EnumCollection"]] = None,
    ) -> None:
        self.constants = constants
        self.subitems = subitems

    def __repr__(self) -> str:
        def format_value(val):
            if val is None:
                return "None"
            elif isinstance(val, str):
                return f"'{val}'"
            else:
                return str(val)

        const_part = ""
        if self.constants:
            sorted_consts = sorted([format_value(c) for c in self.constants])
            const_part = ", ".join(sorted_consts)

        sub_part = ""
        if self.subitems:
            sub_entries = [f"{key}:{repr(value)}" for key, value in self.subitems.items()]
            sub_part = ",".join(sub_entries)

        if const_part and sub_part:
            const_part += "; "
        return "<" + const_part + sub_part + ">"

def extract_enums_from_schema(schema: JsonSchema) -> Optional[EnumCollection]:
    """Extracts enumeration information from a schema in a conservative manner.
    Includes both positive and potentially negated enum values since they might
    be valid in certain contexts."""

    def merge_collections(
        merger: Callable[[Iterable[Set[Any]]], Optional[Set[Any]]],
        collections: Iterable[Optional[EnumCollection]],
    ) -> Optional[EnumCollection]:
        all_constants: List[Set[Any]] = []
        nested_items: Dict[str, List[EnumCollection]] = {}

        for coll in collections:
            if coll is None:
                continue

            if coll.constants is not None:
                all_constants.append(coll.constants)

            if coll.subitems is not None:
                for name, content in coll.subitems.items():
                    if content is None:
                        continue
                    if name in nested_items:
                        nested_items[name].append(content)
                    else:
                        nested_items[name] = [content]

        merged_constants: Optional[Set[Any]] = None
        if all_constants:
            merged_constants = merger(all_constants)

        if not nested_items:
            if merged_constants is None:
                return None
            else:
                return EnumCollection(constants=merged_constants)
        else:
            final_nested: Dict[str, EnumCollection] = {}
            for field_name, contents in nested_items.items():
                if not contents:
                    continue
                merged_content = merge_collections(merger, contents)
                if merged_content is not None:
                    final_nested[field_name] = merged_content
            return EnumCollection(constants=merged_constants, subitems=final_nested)

    def union_collections(
        collections: Iterable[Optional[EnumCollection]],
    ) -> Optional[EnumCollection]:
        def union_op(sets: Iterable[Set[Any]]) -> Optional[Set[Any]]:
            result = set()
            for s in sets:
                result.update(s)
            return result if result else None
        return merge_collections(union_op, collections)

    def intersect_collections(
        collections: Tuple[Optional[EnumCollection], ...]
    ) -> Optional[EnumCollection]:
        def intersection_op(sets: Iterable[Set[Any]]) -> Optional[Set[Any]]:
            sets_list = list(sets)
            if not sets_list:
                return None
            result = sets_list[0].copy()
            for s in sets_list[1:]:
                result.intersection_update(s)
            return result if result else None
        return merge_collections(intersection_op, collections)

    # Handle boolean schemas
    if schema is True or schema is False:
        return None

    # Handle direct enum definitions
    if "enum" in schema:
        return EnumCollection(constants=set(schema["enum"]))

    # Handle object types with properties
    if "type" in schema:
        obj_type = schema["type"]
        if obj_type == "object" and "properties" in schema:
            properties = schema["properties"]
            collected: Dict[str, EnumCollection] = {}

            for prop_name, prop_schema in properties.items():
                extracted = extract_enums_from_schema(prop_schema)
                if extracted is not None:
                    collected[prop_name] = extracted

            if collected:
                return EnumCollection(subitems=collected)
            else:
                return None
        else:
            return None

    # Handle negation
    if "not" in schema:
        negated = extract_enums_from_schema(schema["not"])
        return negated

    # Handle logical combinations
    if "allOf" in schema:
        sub_schemas = [extract_enums_from_schema(s) for s in schema["allOf"]]
        return union_collections(sub_schemas)

    if "anyOf" in schema:
        sub_schemas = [extract_enums_from_schema(s) for s in schema["anyOf"]]
        return union_collections(sub_schemas)

    if "oneOf" in schema:
        sub_schemas = [extract_enums_from_schema(s) for s in schema["oneOf"]]
        return union_collections(sub_schemas)

    return None

def convert_to_python_enums(
    collection: Optional[EnumCollection], 
    current_path: List[str], 
    accumulator: Dict[str, enum.Enum]
) -> None:
    def normalize_constant(constant: Any) -> Tuple[str, Any]:
        if isinstance(constant, str):
            return (constant.replace("-", "_"), constant)
        elif isinstance(constant, (int, float)):
            return (f"numeric_{constant}", constant)
        else:
            logger.warning(
                f"Encountered enumeration value of type {type(constant).__name__} ({constant}) that may not be handled correctly"
            )
            return (str(constant), constant)

    if collection is None:
        return

    if collection.constants is not None:
        path_segment, _ = normalize_constant("_".join(current_path))
        full_path = ".".join(current_path)
        normalized_values = (normalize_constant(c) for c in collection.constants if c is not None)
        accumulator[path_segment] = enum.Enum(full_path, normalized_values)

    if collection.subitems is not None:
        for key in collection.subitems:
            convert_to_python_enums(collection.subitems[key], [key] + current_path, accumulator)

def schema_to_enums(schema: JsonSchema) -> Dict[str, enum.Enum]:
    collection = extract_enums_from_schema(schema)
    result: Dict[str, enum.Enum] = {}
    convert_to_python_enums(collection, [], result)
    return result

def attach_fields_to_object(target: Any, data: Dict[str, Any], override=False) -> None:
    if data is None:
        return

    for name, value in data.items():
        if name == "":
            logger.warning(
                "Top-level enumeration found - cannot attach to target object"
            )
        elif hasattr(target, name) and not override:
            logger.error(
                f"Field '{name}' already exists on {target._name}. Skipping due to conflict."
            )
        else:
            setattr(target, name, value)

def attach_schema_enums(target: Any, schema: JsonSchema, override=False) -> None:
    enums = schema_to_enums(schema)
    attach_fields_to_object(target, enums, override)

import os
import logging
import xml.etree.ElementTree as ET
from pathlib import Path
from typing import Dict, Optional
from .abstract_commands import AbstractCommands

_LOGGER = logging.getLogger(__name__)

class IRCommands:
    _ir_data: Dict[str, bytes] = {}

    def __init__(self, config_name: str, command_handler: AbstractCommands):
        self._handler = command_handler
        config_path = Path(os.getcwd()) / "usr" / "share" / f"{config_name}.xml"

        if config_path.is_file():
            root = ET.parse(config_path).getroot()
            for node in root.findall("remote/code"):
                signal_name = node.get("name")
                ccf_node = node.find("ccf")

                if ccf_node is not None and ccf_node.text:
                    # Convert hex string format: swap each byte pair (e.g., "AB CD" -> "BA DC")
                    raw_bytes = ccf_node.text.strip().split()
                    swapped_bytes = [byte[2:4] + byte[0:2] for byte in raw_bytes]
                    self._ir_data[signal_name] = bytes.fromhex(" ".join(swapped_bytes))
                else:
                    _LOGGER.warning("Missing or empty CCF data in %s for signal '%s'", 
                                   config_path, signal_name)
        else:
            raise FileNotFoundError(
                f"Configuration file not found at {config_path}"
            )

    def get_state(self) -> Dict[str, str]:
        return self._handler.get_state()

    def lookup(self, signal_name: str) -> Optional[bytes]:
        if signal_name in self._ir_data:
            return self._ir_data[signal_name]
        else:
            _LOGGER.error("Signal '%s' not found in IR database", signal_name)
            return None

    def build_command(self, state_updates: dict) -> str:
        return self._handler.get_command_from_state(state_updates)

# Type III Clone: Refactored pattern matching implementation with equivalent functionality

from dataclasses import dataclass, field
import sys
from typing import (
    Any,
    Callable,
    Optional,
    Tuple,
    Union,
    Dict,
    ClassVar,
    Generic,
    TypeVar,
    Type,
    List,
)
from .composition import Compose
from .interface import Interface, implements, isimplementation

__all__ = ("match", "_")

def match(target: Any, *patterns: 'PatternBranch') -> Any:
    """Match a target against patterns and execute corresponding actions.

    :param target: the value to be matched against patterns
    :param patterns: sequence of pattern branches to evaluate in order
    """
    if not all(isimplementation(pattern, _IPatternBranch) for pattern in patterns):
        raise TypeError("All pattern branches must implement the `_IPatternBranch` interface.")

    for idx, branch in enumerate(patterns):
        validation_result = branch.validate(target)
        if validation_result is not None:
            return branch.execute(validation_result)
    return None

@dataclass
class _PatternBranchData:
    """Internal storage for pattern branch data."""
    predicate_value: Any = field(init=False, default=None)
    action_func: Callable = field(init=False, default=lambda: None)

class _IPatternBranch(Interface):
    """Abstract interface for pattern branches."""
    def validate(self, item: Any) -> Optional[Tuple]:
        ...

@implements(_IPatternBranch)
class PatternBranch(
    Compose(_PatternBranchData, "predicate_value", name="_pb")  # type: ignore
):
    """Base pattern branch with minimal matching behavior."""
    def __init_subclass__(cls, alias: Optional[str] = None) -> None:
        if alias is not None:
            setattr(PatternBranch, alias, cls)

    def __init__(self, predicate_value: Any = None):
        super().__init__()
        self.predicate_value = predicate_value

    def __rshift__(self, outcome: Any) -> PatternBranch:
        # Store either the callable or wrap non-callable in lambda
        stored_func = outcome if callable(outcome) else (lambda: outcome)
        setattr(self._pb, "action_func", stored_func)
        return self

    def validate(self, item: Any) -> Optional[Tuple]:
        # Default implementation always matches with empty tuple
        return tuple()

    def execute(self, args: Tuple) -> Any:
        return self._pb.action_func(*args)

_ = PatternBranch  # Alias for convenience

@implements(_IPatternBranch)
class ExactValue(PatternBranch, alias="e"):
    """Pattern branch that checks for exact equality with a literal value."""
    predicate_value: Any

    def validate(self, item: Any) -> Optional[Tuple]:
        if self.predicate_value == item:
            return tuple()
        return None

@implements(_IPatternBranch)
class PredicateCheck(PatternBranch, alias="p"):
    """Pattern branch using a predicate function for conditional matching."""
    predicate_value: Callable

    def validate(self, item: Any) -> Optional[Tuple]:
        if self.predicate_value(item):
            return (item,)
        return None

@implements(_IPatternBranch)
class Structured(PatternBranch, alias="t"):
    """Pattern branch for structured data decomposition."""
    _type_hint: type
    predicate_value: Tuple[Tuple, Dict]

    def __init__(self, *args, **kwargs):
        super().__init__()
        self.predicate_value = (args, kwargs)

    def __class_getitem__(cls, typ: type) -> Type['Structured']:
        # Dynamically create subclass with specific type hint
        return type(f"{typ.__name__}PatternBranch", (Structured,), {"_type_hint": typ})

    def validate(self, item: Any) -> Optional[Tuple]:
        # Check if item is instance of expected type
        if isinstance(item, self._type_hint):
            args, kwargs = self.predicate_value
            try:
                # Validate keyword arguments with optional callables
                kwarg_match = all(
                    getattr(item, key) == val
                    if not callable(val)
                    else val(getattr(item, key))
                    for key, val in kwargs.items()
                )

                if kwarg_match:
                    # Extract positional attributes
                    extracted_values = tuple(getattr(item, attr) for attr in args)
                    return extracted_values
            except AttributeError:
                pass
        return None

