def _null_context():
    """Context manager that does nothing"""
    @contextmanager
    def nullcontext():
        yield
    return nullcontext

def _get_compression_param_class():
    """Attempt to import CompressionParameter from NNCF, fallback to None"""
    try:
        from nncf.torch.layer_utils import CompressionParameter
        return CompressionParameter
    except ImportError:
        return None

def _get_no_nncf_trace_manager():
    """Get NNCF's no_nncf_trace context manager or fallback to null context"""
    try:
        from nncf.torch.dynamic_graph.context import no_nncf_trace as original_no_nncf_trace
        return original_no_nncf_trace
    except ImportError:
        return _null_context()

def _extract_nncf_metadata_from_checkpoint(filepath):
    """Extract NNCF metadata from checkpoint file if available"""
    if not filepath:
        return None

    try:
        checkpoint = torch.load(filepath, map_location='cpu')
    except Exception:
        return None

    if not isinstance(checkpoint, dict):
        return None

    return checkpoint.get('nncf_metainfo', None)

def _build_nncf_metadata(compression_enabled, config_data):
    """Construct NNCF metadata dictionary"""
    return {
        'nncf_compression_enabled': compression_enabled,
        'nncf_config': config_data
    }

def _is_nncf_checkpoint(filepath):
    """Determine if a checkpoint contains NNCF metadata"""
    metadata = _extract_nncf_metadata_from_checkpoint(filepath)
    if not metadata:
        return False
    return bool(metadata.get('nncf_compression_enabled', False))

def _load_state_into_model(model, checkpoint_path, device=None):
    """Load model state from checkpoint, handling various checkpoint formats"""
    from nncf.torch import load_state

    map_loc = device if device is not None else 'cpu'
    checkpoint = torch.load(checkpoint_path, map_location=map_loc)

    # Extract state_dict based on checkpoint format
    if isinstance(checkpoint, OrderedDict):
        state_dict = checkpoint
    elif isinstance(checkpoint, dict) and 'state_dict' in checkpoint:
        state_dict = checkpoint['state_dict']
    else:
        raise RuntimeError(f'No state_dict found in checkpoint file {checkpoint_path}')

    # Load state into model
    load_state(model, state_dict, strict=True)
    return checkpoint

def _default_quantization_config(height, width):
    """Generate default quantization configuration for NNCF"""
    return {
        'input_info': {
            'sample_size': [1, 3, height, width]
        },
        'compression': [{
            'algorithm': 'quantization',
            'initializer': {
                'range': {
                    'num_init_samples': 8192
                },
                'batchnorm_adaptation': {
                    'num_bn_adaptation_samples': 8192
                }
            }
        }],
        'log_dir': '.'
    }

def _prepare_nncf_model(model, config, data_loader_for_init=None, 
                        checkpoint_file=None, config_file=None):
    """Wrap model with NNCF compression capabilities"""
    # Import required modules
    from torchreid.data.transforms import build_inference_transform
    from torchreid.utils import read_json

    # Validate input parameters
    if not (data_loader_for_init or checkpoint_file):
        raise RuntimeError('One of data_loader_for_init or checkpoint_file must be provided')

    # Import NNCF components
    from nncf import NNCFConfig
    from nncf.torch import create_compressed_model
    from nncf.torch.initialization import register_default_init_args
    from nncf.torch.dynamic_graph.io_handling import nncf_model_input
    from nncf.torch.dynamic_graph.trace_tensor import TracedTensor
    from nncf.torch.initialization import PTInitializingDataLoader

    # Determine if we have existing NNCF metadata
    existing_metadata = _extract_nncf_metadata_from_checkpoint(checkpoint_file)
    nncf_config_data = None

    if existing_metadata and existing_metadata.get('nncf_compression_enabled'):
        nncf_config_data = existing_metadata['nncf_config']
        data_loader_for_init = None
        print(f'Loaded NNCF metainfo from checkpoint:\n{pformat(existing_metadata)}')
    else:
        # Non-NNCF model case
        checkpoint_file = None
        if config_file:
            nncf_config_data = read_json(config_file)
            print(f'Loaded NNCF config from file {config_file}:\n{pformat(nncf_config_data)}')

        if nncf_config_data is None:
            print('Failed to load NNCF config from file')

    # Ensure only one initialization source is used
    if data_loader_for_init and checkpoint_file:
        raise RuntimeError('Only ONE of data_loader_for_init or checkpoint_file should be provided')

    # Get model dimensions
    h, w = config.data.height, config.data.width

    # Use default config if none provided
    if not nncf_config_data:
        print('Using default NNCF int8 quantization config')
        nncf_config_data = _default_quantization_config(h, w)

    # Update input size in config
    nncf_config_data.setdefault('input_info', {})
    nncf_config_data['input_info']['sample_size'] = [1, 3, h, w]

    # Create NNCF config object
    nncf_config = NNCFConfig(nncf_config_data)
    print(f'NNCF configuration:\n{pformat(nncf_config)}')

    # Prepare metadata for compression
    if not existing_metadata:
        nncf_metainfo = _build_nncf_metadata(True, nncf_config_data)
    else:
        nncf_metainfo = existing_metadata.copy()
        nncf_metainfo['nncf_config'] = nncf_config_data

    # Define custom data loader for initialization
    class CustomInitDataLoader(PTInitializingDataLoader):
        def get_inputs(self, dataloader_output):
            args = (dataloader_output[0],)
            return args, {}

    # Get current device
    cur_device = next(model.parameters()).device
    print(f'NNCF: Current device = {cur_device}')

    # Initialize compression controller
    resuming_state = None
    if checkpoint_file is None:
        print('Registering initialization data loader')
        train_loader = data_loader_for_init.train_loader
        wrapped_loader = CustomInitDataLoader(train_loader)
        nncf_config = register_default_init_args(nncf_config, wrapped_loader, device=cur_device)
    else:
        print(f'Loading compressed model from {checkpoint_file}')
        resuming_state = _load_state_into_model(model, checkpoint_file, device=cur_device)
        print(f'Loaded compressed model from {checkpoint_file}')

    # Build inference transforms
    transform = build_inference_transform(
        cfg.data.height,
        cfg.data.width,
        norm_mean=cfg.data.norm_mean,
        norm_std=cfg.data.norm_std,
    )

    # Define dummy forward function for NNCF graph construction
    def dummy_forward_pass(model_module):
        prev_training = model_module.training
        model_module.eval()
        input_img = random_image(cfg.data.height, cfg.data.width)
        input_blob = transform(input_img).unsqueeze(0)
        assert len(input_blob.size()) == 4
        input_blob = input_blob.to(device=cur_device)
        input_blob = nncf_model_input(input_blob)
        model_module(input_blob)
        model_module.train(prev_training)

    # Input wrapping function for NNCF
    def wrap_input_tensors(args, kwargs):
        assert not kwargs
        assert len(args) == 1
        if isinstance(args[0], TracedTensor):
            print('Skipping wrapping of already traced tensor')
            return args, {}
        return (nncf_model_input(args[0]),), {}

    # Attach functions to model
    model.dummy_forward_fn = dummy_forward_pass

    # Ensure log directory exists
    if 'log_dir' in nncf_config:
        os.makedirs(nncf_config['log_dir'], exist_ok=True)
    print(f'NNCF log directory: {nncf_config["log_dir"]}')

    # Create compressed model
    compression_ctrl, compressed_model = create_compressed_model(
        model,
        nncf_config,
        dummy_forward_fn=dummy_forward_pass,
        wrap_inputs_fn=wrap_input_tensors,
        compression_state=resuming_state
    )

    return compression_ctrl, compressed_model, nncf_metainfo

def _get_compression_stage_class():
    """Get NNCF CompressionStage class or fallback implementation"""
    try:
        from nncf.api.compression import CompressionStage
        return CompressionStage
    except ImportError:
        return lambda x: None

def _get_tensorboard_prep_function():
    """Get NNCF tensorboard preparation function or fallback"""
    try:
        from nncf.common.utils.tensorboard import prepare_for_tensorboard
        return prepare_for_tensorboard
    except ImportError:
        return lambda x: None

