    help="Output format for the data",
)
@click.option(
    "--no-accounts",
    default=False,
    is_flag=True,
    help="Exclude account data from the model",
)
@click.option(
    "--no-policies",
    default=False,
    is_flag=True,
    help="Exclude policy data from the model",
)
@click.option("--out-file", "-o", help="File path to write data instead of stdout")
@click.option(
    "--flatten", default=False, is_flag=True, help="Flatten nested model keys"
)
@click.pass_context
def dump_all(
    ctx: dict[str, Any],
    format_: str,
    no_accounts: bool,
    no_policies: bool,
    out_file: str,
    flatten: bool,
) -> None:
    """Export a complete representation of the organization structure"""
    err_msg = None
    tb = None
    try:
        kwargs = {"init_all": True}
        if no_accounts or no_policies:
            del kwargs["init_all"]
        if no_accounts:
            kwargs["init_accounts"] = False
            kwargs["init_account_tags"] = False
            kwargs["init_effective_policies"] = False
        if no_policies:
            kwargs["init_effective_policies"] = False
            kwargs["init_policies"] = False
            kwargs["init_policy_tags"] = False
            kwargs["init_policy_targets"] = False
        odb = OrganizationDataBuilder(include_account_parents=True, **kwargs)
        if format_ == "JSON":
            s_func = odb.to_json
        elif format_ == "YAML":
            s_func = odb.to_yaml
        elif format_ == "DOT":
            s_func = odb.to_dot
        if out_file is None:
            out_file = "-"
        with click.open_file(out_file, mode="wb") as f:
            f.write(bytes(s_func(flatten=flatten), "utf-8"))
    except ClientError as exc_info:
        err_msg = f"Service Error: {str(exc_info)}"
    except NoCredentialsError:
        err_msg = "Error: Unable to locate AWS credentials"
    except Exception as exc_info:
        err_msg = f"Unknown Error: {str(exc_info)}"
        tb = traceback.format_exc()
    handle_error(ctx, err_msg, tb)

@organization.command(short_help="Query for account details")
@click.option(
    "--accounts", "-a", required=True, help="A space-delimited list of account IDs"
)
@click.option(
    "--include-effective-policies",
    default=False,
    is_flag=True,
    help="Include effective policies for the accounts",
)
@click.option(
    "--include-parents",
    default=False,
    is_flag=True,
    help="Include parent data for the accounts",
)
@click.option(
    "--include-tags",
    default=False,
    is_flag=True,
    help="Include tags applied to the accounts",
)
@click.option(
    "--include-policies",
    default=False,
    is_flag=True,
    help="Include policies attached to the accounts",
)
@click.pass_context
def lookup_accounts(
    ctx: dict[str, Any],
    accounts: list[str],
    include_parents: bool,
    include_effective_policies: bool,
    include_policies: bool,
    include_tags: bool,
) -> None:
    """Retrieve account information using provided account IDs"""
    accounts_unvalidated = []
    if " " in accounts:
        accounts_unvalidated = accounts.split(" ")
    else:
        accounts_unvalidated = [accounts]

    account_ids = []
    invalid_ids = []
    for account in accounts_unvalidated:
        if re.fullmatch(r"^[\d]{12}$", account) is not None:
            account_ids.append(account)
        else:
            invalid_ids.append(account)

    if len(invalid_ids) > 0:
        handle_error(
            ctx,
            f"Invalid account IDs included in request: {str.join(' ', invalid_ids)}",
        )

    odb = OrganizationDataBuilder()
    odb.Connect()
    odb.fetch_accounts(include_parents=include_parents)

    exclude_keys = []
    if not include_parents:
        exclude_keys.append("parent")
    if not include_policies:
        exclude_keys.append("policies")
    if not include_effective_policies:
        exclude_keys.append("effective_policies")
    if not include_tags:
        exclude_keys.append("tags")

    if include_policies:
        odb.fetch_policies()
        odb.fetch_policy_targets()
    if include_effective_policies:
        odb.fetch_effective_policies(account_ids=account_ids)
    if include_tags:
        odb.fetch_account_tags(account_ids=account_ids)

    data = [
        {k: v for k, v in acct.to_dict().items() if k not in exclude_keys}
        for acct in odb.dm.accounts
        if acct.id in account_ids
    ]
    click.echo(json.dumps(data, default=str))

@organization.command()
@click.option("--table", "-t", required=True, help="Name of the DynamoDB table")
@click.option(
    "--in-file", "-i", required=True, help="File containing a list of Account objects"
)
@click.pass_context
def write_accounts_to_dynamodb(
    ctx: dict[str, Any],
    table: str,
    in_file: str,
) -> None:
    """Upload a list of accounts to a specified DynamoDB table"""
    data = None
    with click.open_file(in_file, mode="r") as f:
        data = json.load(f)

    odb = OrganizationDataBuilder()
    if not isinstance(data, list):
        handle_error(err_msg="Data is not a list")

    odb.dm.accounts = [Account(**account) for account in data]
    accounts = odb.to_dynamodb(field_name="accounts")
    client = APIClient("dynamodb")
    ret = {"responses": []}

    # Group into batches of 25 since that's the max for BatchWriteItem
    for group_ in itertools.zip_longest(*[iter(accounts)] * 25):
        items = prepare_dynamodb_batch_put_request(table=table, items=group_)
        res = client.api("batch_write_item", request_items=items)
        # TODO: Add handling of any "UnprocessedItems" in the response. Add retry with
        # exponential backoff.
        ret["responses"].append(res)

    click.echo(json.dumps(ret))

@organization.command()
@click.option("--table", "-t", required=True, help="Name of the DynamoDB table")
@click.pass_context
def read_accounts_from_dynamodb(
    ctx: dict[str, Any],
    table: str,
) -> None:
    """Download account data from a specified DynamoDB table"""
    client = APIClient("dynamodb")
    res = client.api("scan", table_name=table)
    accounts = [Account(**account) for account in deserialize_dynamodb_items(res)]
    odb = OrganizationDataBuilder()
    odb.dm.accounts = accounts
    click.echo(odb.to_json(field_name="accounts"))

# Calculate combined rankings from multiple ranked lists

def merge_two_rankings(list_a, list_b):
    unique_elements = set(list_a + list_b)
    scores_a = {}
    scores_b = {}

    # Assign scores for elements in list_a
    current_score = len(unique_elements)
    for element in list_a:
        scores_a[element] = current_score
        current_score -= 1
    for element in list_b:
        if element not in scores_a:
            scores_a[element] = current_score
            current_score -= 1

    # Assign scores for elements in list_b
    current_score = len(unique_elements)
    for element in list_b:
        scores_b[element] = current_score
        current_score -= 1
    for element in list_a:
        if element not in scores_b:
            scores_b[element] = current_score
            current_score -= 1

    # Aggregate scores for each element
    combined_scores = []
    for element in unique_elements:
        a_val = scores_a[element]
        b_val = scores_b[element]
        combined_scores.append((element, a_val, b_val, a_val + b_val))

    # Sort by total score (descending), then by first list's score (descending) for ties
    combined_scores.sort(key=lambda x: (x[3], x[1]), reverse=True)

    return [entry[0] for entry in combined_scores]

def merge_multiple_rankings(lists_of_ranks):
    if len(lists_of_ranks) == 0:
        raise ValueError("No ranked lists provided!")

    # Collect all unique items across all lists
    all_items = set(lists_of_ranks[0])
    for current_list in lists_of_ranks[1:]:
        all_items.update(current_list)

    # Initialize scores for all items to zero
    item_scores = {item: 0 for item in all_items}

    # Process each ranking list
    for current_list in lists_of_ranks:
        # Assign decreasing scores to items present in the current list
        current_score = len(all_items)
        seen_in_list = set()
        for item in current_list:
            item_scores[item] += current_score
            seen_in_list.add(item)
            current_score -= 1

        # Add remaining score to items not in current list
        for item in all_items:
            if item not in seen_in_list:
                item_scores[item] += current_score

    # Convert to list of tuples and sort by score descending
    scored_items = [(item, score) for item, score in item_scores.items()]
    scored_items.sort(key=lambda x: x[1], reverse=True)

    return [item for item, _ in scored_items]

import enum
from .device import _WiserDevice
from .rest_controller import _WiserRestController
from .schedule import _WiserSchedule
from .const import (
    WISERSMARTPLUG,
    WISERDEVICE,
    TEXT_UNKNOWN,
    TEXT_AUTO,
    TEXT_MANUAL,
    TEXT_OFF,
    TEXT_ON,
    TEXT_NO_CHANGE
)

# Replace enums with simple mappings
SMART_PLUG_MODES = {
    "auto": TEXT_AUTO,
    "manual": TEXT_MANUAL
}
AWAY_MODE_ACTIONS = {
    "off": TEXT_OFF,
    "nochange": TEXT_NO_CHANGE
}

import inspect

class _WiserSmartPlug(_WiserDevice):
    """Class representing a Wiser Smart Plug device"""

    def __init__(self, wiser_rest_controller: _WiserRestController, data: dict, device_type_data: dict, schedule: _WiserSchedule):
        super().__init__(data)
        self._wiser_rest_controller = wiser_rest_controller
        self._device_type_data = device_type_data
        self._schedule = schedule
        self._away_action = device_type_data.get("AwayAction", TEXT_UNKNOWN)
        self._mode = device_type_data.get("Mode", TEXT_UNKNOWN)
        self._name = device_type_data.get("Name", TEXT_UNKNOWN)
        self._device_lock_enabled = data.get("DeviceLockEnabled", False)
        self._output_state = device_type_data.get("OutputState", TEXT_OFF)

    def _send_command(self, cmd: dict, device_level: bool = False) -> bool:
        """
        Send control command to the smart plug
        param cmd: json command structure
        return: boolean - true = success, false = failed
        """
        endpoint = WISERDEVICE if device_level else WISERSMARTPLUG
        result = self._wiser_rest_controller._send_command(endpoint.format(self.id), cmd)
        if result:
            caller_name = inspect.stack()[1].function
            _LOGGER.debug(f"Wiser smart plug - {caller_name} command successful")
        return result

    def _validate_mode(self, mode: str) -> bool:
        normalized = mode.lower()
        return normalized in SMART_PLUG_MODES

    def _validate_away_action(self, action: str) -> bool:
        normalized = action.lower()
        return normalized in AWAY_MODE_ACTIONS

    @property
    def available_modes(self):
        return list(SMART_PLUG_MODES.values())

    @property
    def available_away_mode_actions(self):
        return list(AWAY_MODE_ACTIONS.values())

    @property
    def away_mode_action(self) -> str:
        """Get or set the away action of the smart plug (off or no change)"""
        return AWAY_MODE_ACTIONS.get(self._away_action.lower(), TEXT_UNKNOWN)

    @away_mode_action.setter
    def away_mode_action(self, action: str):
        if self._validate_away_action(action):
            key = action.lower()
            payload = {"AwayAction": AWAY_MODE_ACTIONS[key]}
            if self._send_command(payload):
                self._away_action = AWAY_MODE_ACTIONS[key]
        else:
            raise ValueError(f"{action} is not a valid Smart Plug away mode action. Valid actions are {self.available_away_mode_actions}")

    @property
    def control_source(self) -> str:
        """Get the current control source of the smart plug"""
        return self._device_type_data.get("ControlSource", TEXT_UNKNOWN)

    @property
    def delivered_power(self) -> int:
        """Get the amount of current through the plug over time"""
        return self._device_type_data.get("CurrentSummationDelivered", -1)

    @property
    def device_lock_enabled(self) -> bool:
        """Get or set smart plug device lock"""
        return self._device_lock_enabled

    @device_lock_enabled.setter
    def device_lock_enabled(self, enable: bool):
        if self._send_command({"DeviceLockEnabled": enable}, True):
            self._device_lock_enabled = enable

    @property
    def instantaneous_power(self) -> int:
        """Get the amount of current through the plug now"""
        return self._device_type_data.get("InstantaneousDemand", -1)

    @property
    def manual_state(self) -> str:
        """Get the current manual mode setting of the smart plug"""
        return self._device_type_data.get("ManualState", TEXT_UNKNOWN)

    @property
    def mode(self) -> str:
        """Get or set the current mode of the smart plug (Manual or Auto)"""
        return SMART_PLUG_MODES.get(self._mode.lower(), TEXT_UNKNOWN)

    @mode.setter
    def mode(self, mode: str):
        if self._validate_mode(mode):
            key = mode.lower()
            payload = {"Mode": SMART_PLUG_MODES[key]}
            if self._send_command(payload):
                self._mode = SMART_PLUG_MODES[key]
        else:
            raise ValueError(f"{mode} is not a valid Smart Plug mode. Valid modes are {self.available_modes}")

    @property
    def name(self) -> str:
        """Get or set the name of the smart plug"""
        return self._name

    @name.setter
    def name(self, name: str):
        if self._send_command({"Name": name}):
            self._name = name

    @property
    def is_on(self) -> bool:
        """Get if the smart plug is on"""
        return self._output_state == TEXT_ON

    @property
    def room_id(self) -> int:
        """Get smart plug room id"""
        return self._device_type_data.get("RoomId", 0)

    @property
    def schedule(self):
        """Get the schedule of the smart plug"""
        return self._schedule

    @property
    def scheduled_state(self) -> str:
        """Get the current scheduled state of the smart plug"""
        return self._device_type_data.get("ScheduledState", TEXT_UNKNOWN)

    def turn_on(self) -> bool:
        """
        Turn on the smart plug
        return: boolean
        """
        result = self._send_command({"RequestOutput": TEXT_ON})
        if result:
            self._output_state = TEXT_ON
        return result

    def turn_off(self) -> bool:
        """
        Turn off the smart plug
        return: boolean
        """
        result = self._send_command({"RequestOutput": TEXT_OFF})
        if result:
            self._output_state = TEXT_OFF
        return result


class _WiserSmartPlugCollection(object):
    """Class holding all wiser smart plugs"""

    def __init__(self):
        self._smartplugs_by_id = {}

    @property
    def all(self) -> list:
        return list(self._smartplugs_by_id.values())

    @property
    def available_modes(self):
        return list(SMART_PLUG_MODES.values())

    @property
    def count(self) -> int:
        return len(self._smartplugs_by_id)

    def add(self, smartplug: _WiserSmartPlug):
        """Add a smart plug to the collection"""
        self._smartplugs_by_id[smartplug.id] = smartplug

    def get_by_id(self, id: int) -> _WiserSmartPlug:
        """
        Gets a SmartPlug object from the SmartPlugs id
        param id: id of smart plug
        return: _WiserSmartPlug object or None
        """
        return self._smartplugs_by_id.get(id)

# Type III Clone: Refactored version with equivalent functionality but different implementation approach

from __future__ import annotations
import typing as t

T = t.TypeVar("T")

def safe_get_value(
    data: t.Dict[t.Any, t.Any],
    /,
    lookup_key: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform_func: t.Optional[t.Callable[[t.Dict[t.Any, t.Any], object], t.Any]] = None,
) -> t.Optional[T]:
    """Safely retrieve a value from dictionary using specified key.

    Returns the value if found and valid, otherwise returns None.
    Validates type against expected_type when value is not None.
    """
    # Use custom parser if provided, otherwise direct dictionary access
    result = transform_func(data, lookup_key) if transform_func else data.get(lookup_key)

    # Type validation only when value exists
    if result is not None and not isinstance(result, expected_type):
        raise ValueError(
            f"{data}: {repr(lookup_key)}: {repr(result)}: invalid type {type(result)}, expecting {expected_type}"
        )

    return t.cast(T, result)

def mandatory_value(
    data: t.Dict[t.Any, t.Any],
    /,
    lookup_key: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform_func: t.Optional[t.Callable[[t.Dict[t.Any, t.Any], object], t.Any]] = None,
    fallback: t.Optional[T] = None,
    factory_func: t.Optional[t.Callable[[], T]] = None,
) -> T:
    """Retrieve required value from dictionary with multiple fallback strategies.

    Raises ValueError if value is missing and no fallbacks are available.
    """
    # First attempt to get optional value
    retrieved = safe_get_value(data, lookup_key, expected_type, transform_func=transform_func)

    # Handle missing value case
    if retrieved is None:
        if fallback is not None:
            return fallback
        if factory_func is not None:
            return factory_func()
        raise ValueError(f"{data}: {repr(lookup_key)}: value is required")

    return retrieved

def expand_nested_dict(source: t.Dict[t.Any, t.Any]) -> t.Dict[str, t.Any]:
    """Convert nested dictionary structure into flattened representation.

    Uses colon-separated keys for nested paths.
    """
    def traverse() -> t.Iterator[t.Tuple[str, t.Any]]:
        for key, value in source.items():
            # Validate key type at each level
            if not isinstance(key, str):
                raise ValueError(f"{key}: expected {str}, but got {type(key)}")

            # Recursively process nested dictionaries
            if isinstance(value, dict):
                for sub_key, sub_val in expand_nested_dict(value).items():
                    if not isinstance(sub_key, str):
                        raise ValueError(
                            f"{sub_key}: expected {str}, but got {type(sub_key)}"
                        )
                    yield f"{key}:{sub_key}", sub_val
            else:
                yield key, value

    return dict(traverse())

def contract_flattened_dict(source: t.Dict[t.Any, t.Any]) -> t.Dict[t.Any, t.Any]:
    """Reconstruct nested dictionary from flattened representation.

    Parses colon-separated keys to rebuild hierarchy.
    """
    result: t.Dict[t.Any, t.Any] = {}

    for key, value in source.items():
        # Validate key type
        if not isinstance(key, str):
            raise ValueError(f"{key}: expected {str}, but got {type(key)}")

        # Process hierarchical keys
        if ":" in key:
            current_level = result
            segments = key.split(":")

            # Navigate/create nested structure
            for idx, segment in enumerate(segments):
                if not isinstance(current_level, dict):
                    break

                if segment not in current_level:
                    current_level[segment] = value if idx == len(segments) - 1 else {}

                current_level = current_level[segment]
        else:
            result[key] = value

    return result

from enum import Enum
from inspect import signature as _get_signature
from typing import List, Set, Optional, Union, Pattern, Type, Callable

class _SectionPatternRegisterer(type):
    def __init__(cls, cls_name, base_classes, class_attrs):
        cls._patterns = []
        for attr_name, attr_val in class_attrs.items():
            meta = getattr(attr_val, '_prop', None)
            if meta is not None:
                cls._patterns.append({'callback': attr_val, 'label': meta['label']})

def section_pattern(label: Optional[str] = None):
    if not (label is None or isinstance(label, str)):
        raise ValueError(f'label must be str but {type(label)} was given.')
    def _wrapper(callback_func: Callable[[str], Optional[Union[str, int]]]):
        nonlocal label
        param_count = len(_get_signature(callback_func).parameters)
        if param_count != 1:
            raise TypeError(
                '@section_pattern() must receive a function with 1 argument.')
        if label is None:
            label = callback_func.__name__
        callback_func._prop = {'label': label}
        return callback_func
    return _wrapper

def register_section_pattern(label: str, regex_patterns: List[Pattern[str]], transform_func: Callable[[str], int]):
    def _decorator(cls_type: Type[BaseSectionNumber]):
        nonlocal label, regex_patterns, transform_func
        if not issubclass(cls_type, BaseSectionNumber):
            raise TypeError(
                '@register_section_pattern may only be used on a class inheriting BaseSectionNumber')
        for pattern_obj in regex_patterns:
            def _make_extractor_factory(pattern):
                def _extractor(text_input: str):
                    match_result = pattern.match(text_input)
                    return None if match_result is None else transform_func(match_result.group('num'))
                return _extractor
            extractor_func = _make_extractor_factory(pattern_obj)
            extractor_func._prop = {'label': label}
            cls_type._patterns.append(
                {'callback': extractor_func,
                 'label': label,
                 'regex': pattern_obj})
        return cls_type
    return _decorator

class BaseSectionNumber(object, metaclass=_SectionPatternRegisterer):
    def __init__(self, section_type: str, value: Union[int, str]):
        if not isinstance(section_type, str):
            raise TypeError(f'section_type must be str but {type(section_type)} was given.')
        if not isinstance(value, (int, str)):
            raise TypeError(f'value must be int or str but {type(value)} was given.')
        self.section_type: str = section_type
        self.value: Optional[int] = value
        self.number = self.value  # alias for compatibility

    def __eq__(self, other):
        return (type(self) == type(other) and
                self.value == other.value and
                self.section_type == other.section_type)

    @classmethod
    def extract_section_number(cls, input_text: str) -> List['BaseSectionNumber']:
        input_text = input_text.strip()
        results = []
        for entry in cls._patterns:
            extracted_value = entry['callback'](input_text)
            if extracted_value is not None:
                results.append(cls(entry['label'], extracted_value))
        return results

    def is_successor_of(self, predecessor: 'BaseSectionNumber') -> bool:
        return predecessor.successor() == self

    def successor(self) -> 'BaseSectionNumber':
        if isinstance(self.value, str):
            # bullet points
            return self
        else:
            # Numbered list
            return type(self)(self.section_type, self.value + 1)

    @staticmethod
    def any_successor_in_set(following_items: Set['BaseSectionNumber'],
                             current_items: Set['BaseSectionNumber']) -> bool:
        for item_a in current_items:
            for item_b in following_items:
                if item_b.is_successor_of(item_a):
                    return True
        return False

    def __repr__(self):
        return f'{str(type(self))[:-1]} type={self.section_type}, number={self.value}>'

class NumberedListState(Enum):
    NO_NUM = 0
    CONSECUTIVE = 1
    DOWN = 2
    UP = 3
    UNKNOWN = 4

class MultiLevelNumberedList(object):
    def __init__(self):
        self._list_entries: List[BaseSectionNumber] = []

    def try_append(self, candidate_set: Set[BaseSectionNumber]) -> NumberedListState:
        if len(candidate_set) == 0:
            return NumberedListState.NO_NUM

        reversed_list = self._list_entries[::-1]
        for idx, prev_entry in enumerate(reversed_list):
            for candidate in candidate_set:
                if candidate.is_successor_of(prev_entry):
                    self._list_entries = self._list_entries[:-idx-1]
                    self._list_entries.append(candidate)
                    if idx == 0:
                        return NumberedListState.CONSECUTIVE
                    else:
                        return NumberedListState.UP

        # No valid continuation found... check if it is a new level
        for candidate in candidate_set:
            if isinstance(candidate.value, str) or candidate.value <= 1:
                self._list_entries.append(candidate)
                return NumberedListState.DOWN
        return NumberedListState.UNKNOWN

import datetime
import pytz

def get_current_utc_datetime() -> datetime.datetime:
    """Returns the current UTC datetime (timezone aware)"""
    return datetime.datetime.now(datetime.timezone.utc)

def convert_to_local_timezone(dt: datetime.datetime) -> datetime.datetime:
    """Converts a datetime object to the system's local timezone"""
    return dt.astimezone()

def parse_bungie_timestamp(timestamp: str) -> datetime.datetime:
    """Parses a Bungie-formatted timestamp string into a UTC datetime object"""
    base_dt = datetime.datetime.strptime(timestamp, "%Y-%m-%dT%H:%M:%SZ")
    return set_utc_timezone(base_dt)

def set_utc_timezone(dt: datetime.datetime) -> datetime.datetime:
    """Attaches UTC timezone information to a naive datetime object"""
    return pytz.UTC.localize(dt)

def recursive_defaultdict_conversion(data):
    """Recursively transforms dictionaries and lists into defaultdicts and lists of defaultdicts"""
    if isinstance(data, dict):
        return {key: recursive_defaultdict_conversion(value) for key, value in data.items()}
    elif isinstance(data, list):
        return [recursive_defaultdict_conversion(item) for item in data]
    else:
        return data

