from enum import Enum
from typing import Dict, List, TypeVar

def convert_local_vars_to_params(variables: Dict) -> Dict:
    result = {}
    for var_name, var_value in variables.items():
        if var_name == "self":
            continue
        if var_value is not None:
            if isinstance(var_value, Enum):
                result[var_name] = var_value.name
            else:
                result[var_name] = var_value
    return result

"""Locates the first dictionary in a list where the 'id' field matches the given identifier"""
U = TypeVar("U")
def locate_by_identifier(identifier: str, collection: List[Dict[str, U]], report_issue=True) -> Dict[str, U]:
    from ..utils import logger

    def match_condition(record):
        return record["id"] == identifier

    try:
        matching_items = filter(match_condition, collection)
        return next(matching_items)
    except StopIteration:
        if report_issue:
            logger.error(
                f"Missing entry with id '{identifier}'. Available ids: {[entry['id'] for entry in collection]}"
            )
        raise

