# Event Storer for Ftrack - Type III Clone (Refactored Logic & Structure)

import os
import sys
import socket
import datetime
import signal
import pymongo
import ftrack_api
from ftrack_server import FtrackServer
from pype.modules.ftrack.ftrack_server.lib import (
    SocketSession,
    StorerEventHub,
    get_ftrack_event_mongo_info,
    TOPIC_STATUS_SERVER,
    TOPIC_STATUS_SERVER_RESULT
)
from pype.modules.ftrack.lib.custom_db_connector import CustomDbConnector
from pype.api import Logger

logger = Logger().get_logger("Event storer")
process_start_time = datetime.datetime.now()

class SessionProvider:
    current_session = None

mongo_uri, mongo_port, mongo_db, mongo_collection = get_ftrack_event_mongo_info()
db_handler = CustomDbConnector(mongo_uri, mongo_db, mongo_port, mongo_collection)

ignored_events = ["ftrack.meta.connected"]

def prepare_database():
    try:
        db_handler.setup()
        # Verify connection by listing collections
        db_handler._database.list_collection_names()
    except pymongo.errors.AutoReconnect:
        logger.error(f"MongoDB server '{os.environ.get('AVALON_MONGO', 'unknown')}' is unreachable. Exiting.")
        sys.exit(0)

def record_event(event):
    if event.get("topic") in ignored_events:
        return

    event_payload = event._data.copy()
    event_identifier = event["id"]

    # Add metadata
    event_payload.setdefault("pype_data", {})
    event_payload["pype_data"].update({
        "recorded_at": datetime.datetime.utcnow(),
        "processed": False
    })

    try:
        # Upsert event data by ID
        db_handler.upsert({"id": event_identifier}, event_payload)
        logger.debug(f"Event {event_identifier} saved successfully")
    except pymongo.errors.AutoReconnect:
        logger.error(f"MongoDB server '{os.environ.get('AVALON_MONGO', 'unknown')}' is unreachable. Exiting.")
        sys.exit(0)
    except Exception as error:
        logger.exception(f"Failed to store event {event_identifier}: {error}")

def synchronize_with_avalon(event):
    session = SessionProvider.current_session
    origin_id = event.get("source", {}).get("id")

    if not origin_id or origin_id != session.event_hub.id:
        return

    if session is None:
        logger.warning("No active session available — cannot trigger Avalon sync.")
        return

    projects = session.query("Project").all()
    if not projects:
        return

    # Mark unprocessed events as processed before syncing
    filter_criteria = {
        "pype_data.processed": False,
        "topic": "ftrack.action.launch",
        "data.actionIdentifier": "sync.to.avalon.server"
    }
    update_operation = {"$set": {"pype_data.processed": True}}
    db_handler.bulk_update(filter_criteria, update_operation)

    eligible_projects = []
    for proj in projects:
        if proj.get("status") != "active":
            continue
        auto_sync_flag = proj.get("custom_attributes", {}).get("avalon_auto_sync")
        if auto_sync_flag:
            eligible_projects.append({
                "entityId": proj["id"],
                "entityType": "show"
            })

    if not eligible_projects:
        return

    actor = session.query(f'User where username is "{session.api_user}"').one()
    actor_info = {
        "username": actor["username"],
        "id": actor["id"]
    }

    for selection in eligible_projects:
        action_payload = {
            "actionIdentifier": "sync.to.avalon.server",
            "selection": [selection]
        }
        session.event_hub.publish(
            ftrack_api.event.base.Event(
                topic="ftrack.action.launch",
                data=action_payload,
                source={"user": actor_info}
            ),
            on_error="ignore"
        )

def report_status(event):
    session = SessionProvider.current_session
    if not session:
        return

    proc_id = event["data"].get("subprocess_id")
    if not proc_id:
        return

    if proc_id != os.environ.get("FTRACK_EVENT_SUB_ID"):
        return

    status_report = {
        "subprocess_id": os.environ["FTRACK_EVENT_SUB_ID"],
        "origin": "storer",
        "info": {
            "initiated_at": process_start_time.strftime("%Y.%m.%d %H:%M:%S")
        }
    }

    status_event = ftrack_api.event.base.Event(
        topic=TOPIC_STATUS_SERVER_RESULT,
        data=status_report
    )
    session.event_hub.publish(status_event)

def setup_handlers(session):
    prepare_database()

    session.event_hub.subscribe("topic=*", record_event)
    session.event_hub.subscribe("topic=pype.storer.started", synchronize_with_avalon)
    session.event_hub.subscribe(TOPIC_STATUS_SERVER, report_status)

def main(argv):
    port = int(argv[-1])

    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_addr = ("localhost", port)
    logger.info(f"Storer connecting to {server_addr[0]}:{server_addr[1]}...")

    sock.connect(server_addr)
    sock.sendall(b"CreatedStore")

    try:
        session = SocketSession(
            auto_connect_event_hub=True,
            sock=sock,
            EventHubClass=StorerEventHub
        )
        SessionProvider.current_session = session

        setup_handlers(session)

        server = FtrackServer("event")
        logger.info("Ftrack Event Storer started")
        server.run_server(session, load_files=False)

    except pymongo.errors.OperationFailure:
        logger.error(
            f"MongoDB access denied. Ensure database '{mongo_db}' and collection '{mongo_collection}' exist."
        )
        sock.sendall(b"MongoError")
    finally:
        logger.info("Closing socket connection")
        sock.close()
        return 1

if __name__ == "__main__":
    def handle_interrupt(signum, frame):
        print("\nShutdown signal received. Terminating process...")
        sys.exit(0)

    signal.signal(signal.SIGINT, handle_interrupt)
    signal.signal(signal.SIGTERM, handle_interrupt)

    sys.exit(main(sys.argv))

from typing import Any, Callable, Dict, List

def parse_bool_value(param: Any) -> Dict[str, Any]:
    """Convert parameter to boolean filter representation"""
    if param is None or param == "":
        return {}

    if isinstance(param, bool):
        return {"value": param}

    # Convert string representations of truthiness
    truthy_values = ["true", "yes", "on", "1"]
    result = str(param).lower() in truthy_values
    return {"value": result}

def parse_comparison(param: Any, converter: Callable[[str], Any] = str) -> Dict[str, Any]:
    """Parse comparison filter parameters from input"""
    if not param:
        return {}

    if not isinstance(param, str):
        return {"value": param}

    if ":" not in param:
        return {"value": converter(param)}

    # Parse format: (not:)(oper:)value(:upper)
    segments = param.split(":")
    segment_count = len(segments)

    is_negated = segments[0] == "not"

    if segment_count >= 4:
        return {
            "negate": is_negated,
            "operator": segments[1],
            "value": converter(segments[2]),
            "upper": converter(segments[3])
        }
    elif segment_count == 3:
        if is_negated:
            return {
                "negate": is_negated,
                "operator": segments[1],
                "value": converter(segments[2])
            }
        else:
            return {
                "operator": segments[0],
                "value": converter(segments[1]),
                "upper": converter(segments[2])
            }
    else:  # segment_count == 2
        if is_negated:
            return {
                "negate": is_negated,
                "value": converter(segments[1])
            }
        else:
            return {
                "operator": segments[0],
                "value": converter(segments[1])
            }

def parse_inclusion(param: Any, converter: Callable[[str], Any] = str) -> Dict[str, Any]:
    """Parse inclusion/exclusion filter parameters"""
    if not param:
        return {}

    if not isinstance(param, str):
        return {"values": [param]}

    if param == "is:null":
        return {"is_null": True}

    if ":" not in param:
        return {"values": list(map(converter, param.split(",")))}

    # Handle format with negation and colon-separated parts
    segments = param.split(":")
    is_negated = segments[0] == "not"

    # Extract values part after first segment (either skip 'not' or operator)
    value_part = segments[1] if is_negated else segments[0]
    values_list = list(map(converter, value_part.split(",")))

    return {
        "negate": is_negated,
        "values": values_list
    }

def parse_string_filter(param: Any) -> Dict[str, Any]:
    """Parse string-based filter parameters"""
    if not param or not isinstance(param, str):
        return {}

    if ":" not in param:
        return {"value": param}

    # Parse format: (not:)(oper:)value
    segments = param.split(":")
    segment_count = len(segments)

    is_negated = segments[0] == "not"

    if segment_count >= 3:
        return {
            "negate": is_negated,
            "operator": segments[1],
            "value": segments[2]
        }
    else:  # segment_count == 2
        if is_negated:
            return {
                "negate": is_negated,
                "value": segments[1]
            }
        else:
            return {
                "operator": segments[0],
                "value": segments[1]
            }

# Modified Transaction class with Type III clones of key functions

class cache:
    def __init__(
        self,
        key_generator: Callable[..., Dict[str, Any]],
        check_state_size_flag=False,
        extra_keys: Optional[List[Callable[[Dict[str, Any]], Dict[str, Any]]]] = None,
    ):
        self.key_generator = key_generator
        self.check_state_size_flag = check_state_size_flag
        self.extra_keys = extra_keys or []

    def __call__(self, original_function):
        wrapper_self = self
        async def wrapped_method(self_instance, *function_args, **function_kwargs):
            # Generate cache key using provided function
            cache_key_dict = wrapper_self.key_generator(*function_args, **function_kwargs)

            # Try to get from cache first
            cached_result = await self_instance._cache.get(**cache_key_dict)
            if cached_result is not None:
                record_cache_metric(original_function.__name__, "hit", cached_result, cache_key_dict)
                return cached_result

            # Cache miss - execute original function
            result = await original_function(self_instance, *function_args, **function_kwargs)
            record_cache_metric(original_function.__name__, "miss", result, cache_key_dict)

            # Store in cache if valid result
            if result is not None:
                if result == _EMPTY:
                    await self_instance._cache.set(result, keyset=[cache_key_dict])
                else:
                    try:
                        should_store = (
                            not wrapper_self.check_state_size_flag
                            or len(result["state"]) < self_instance._cache.max_cache_record_size
                        )
                        if should_store:
                            additional_keys_list = [wrapper_self.key_generator(result)]
                            for extra_func in wrapper_self.extra_keys:
                                additional_keys_list.append(extra_func(result))
                            await self_instance._cache.set(
                                result,
                                keyset=[cache_key_dict] + additional_keys_list
                            )
                    except (TypeError, KeyError):
                        await self_instance._cache.set(result, **cache_key_dict)
                return result
        return wrapped_method


