        # Process modified objects
        for oid, obj in list(self.modified.items()):
            await self._store_object(obj, oid)

        # Process deleted objects
        for oid, obj in list(self.deleted.items()):
            await self._manager._storage.delete(self, oid)

    @profilable
    async def get_child(self, parent, key, ignore_registered=False):
        if not ignore_registered:
            uuid = self.added_children.get((parent.__uuid__, key), None)
            if uuid is not None:
                return self.added[uuid]

        result = await self._get_child(parent, key)
        if result is None:
            return None

        if not ignore_registered:
            if result["zoid"] in self.deleted:
                return None
            obj = self.modified.get(result["zoid"], None)
            if obj is not None:
                return obj

        return self._fill_object(result, parent)

    async def get_children(self, parent, keys):
        """
        More performant way to get groups of items.
        - look at cache
        - batch get from storage
        - async for iterate items
        - store retrieved values in storage
        """
        lookup_buffer = []  # backlog of object that need to be looked up

        for key in keys:
            item = await self._cache.get(container=parent, id=key)
            if item is None:
                lookup_buffer.append(key)
                if len(lookup_buffer) > 15:  # limit batch size
                    async for litem in self._get_batch_children(parent, lookup_buffer):
                        yield litem
                    lookup_buffer = []
                continue

            if len(lookup_buffer) > 0:
                # we need to clear this buffer first before we can yield this item
                async for litem in self._get_batch_children(parent, lookup_buffer):
                    yield litem
                lookup_buffer = []

            yield self._fill_object(item, parent)

        # flush the rest
        if len(lookup_buffer) > 0:
            async for item in self._get_batch_children(parent, lookup_buffer):
                yield item

    @profilable
    async def _get_annotation(self, base_obj, id):
        try:
            result = await self._manager._storage.get_annotation(self, base_obj.__uuid__, id)
        except KeyError:
            return _EMPTY
        if result is None:
            return _EMPTY
        return result

    @profilable
    async def get_annotation(self, base_obj, id, reader=None):
        result = await self._get_annotation(base_obj, id)
        if result == _EMPTY:
            raise KeyError(id)
        if reader is None:
            obj = app_settings["object_reader"](result)
        else:
            obj = reader(result)
        obj.__of__ = base_obj.__uuid__
        obj.__txn__ = self
        return obj

# Define base contribution class
class Investment:
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        self.amount = amount
        self.rate = rate
        self.duration = duration

# Fast growth investment type
class QuickInvestment(Investment):
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        super().__init__(amount, rate, duration)

    def earnings(self) -> float:
        total = self.amount
        for _ in range(self.duration):
            total += self.amount * self.rate
        return total

# Bonus-based investment type  
class EnhancedInvestment(Investment):
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        super().__init__(amount, rate, duration)

    def earnings(self) -> float:
        current = self.amount
        for _ in range(self.duration):
            current *= (1 + self.rate)
        return current

# Capitalized interest investment type
class CompoundInvestment(Investment):
    def __init__(self, amount: int, rate: float, duration: int) -> None:
        super().__init__(amount, rate, duration)

    def earnings(self) -> float:
        return 0.0

# Type III clone: restructuring logic while preserving functionality
import logging
try:
    from collections.abc import Iterable
except ImportError:
    from collections import Iterable
import re
import six
from .trans_base import trans_comp_check_mdoe_base
from ..etl_util import cached, get_re_full_match, get_set_mode_if_skip_fn

__all__ = ['trans_comp_kv']
logger = logging.getLogger(__name__)

def trans_comp_kv(*args, **kwargs):
    # Handle both positional and keyword argument cases for event-like input
    is_dict_arg = args and isinstance(args[0], dict)
    is_event_kwarg_dict = 'event' in kwargs and isinstance(kwargs['event'], dict)

    if is_dict_arg or is_event_kwarg_dict:
        transformer = kv_transformer()
        return transformer(*args, **kwargs)
    else:
        return kv_transformer(*args, **kwargs)

class kv_transformer(trans_comp_check_mdoe_base):
    DEFAULT_SEP = u'='
    DEFAULT_QUOTE = u'"'

    @staticmethod
    @cached
    def _compile_pattern(sep_char, quote_char, escape_flag):
        # Pattern 1: unquoted value (simpler case)
        base_pattern_1 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)'

        # Pattern 2: quoted value (with/without escaping)
        if not escape_flag:
            base_pattern_2 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*([^{1}]*?)\s*{1}'
        else:
            # Escaped quotes inside quoted values
            base_pattern_2 = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*((?:[^{1}]|\\\\{1})*?[^\\\\]){1}'

        # Combine patterns with alternation
        combined = u'|'.join([base_pattern_1, base_pattern_2]).format(sep_char, quote_char)
        logger.info(u"kv_transformer: compiled regex pattern: {0}".format(combined))
        return re.compile(combined)

    def __init__(self, prefix=None, suffix=None, sep=None, quote=None, escape=None, mode=None):
        super(kv_transformer, self).__init__(mode=mode)

        # Set default values for optional parameters
        self.prefix = self._u("" if prefix is None else prefix)
        self.suffix = self._u("" if suffix is None else suffix)
        self.escape = False if escape is None else escape
        self.sep = self._u(self.DEFAULT_SEP if sep is None else sep)
        self.quote = self._u(self.DEFAULT_QUOTE if quote is None else quote)

        # Compile the regex pattern once during initialization
        self.ptn = self._compile_pattern(self.sep, self.quote, self.escape)
        self.normalize = None

    def set(self, event_dict, key, value, real_key=None, check_kw_name=False):
        """Override base method to handle escaped characters"""
        if self.escape:
            # Remove backslashes before quote characters when in escape mode
            value = value.strip().replace("\\" + self.quote, self.quote)

        return super(kv_transformer, self).set(event_dict, key, value, real_k=real_key, check_kw_name=check_kw_name)

    def _parse_kv_pairs(self, event_obj, raw_value):
        # Ensure text type compatibility
        if isinstance(raw_value, six.binary_type):
            raw_value = raw_value.decode('utf8', 'ignore')

        # Extract all key-value matches using compiled pattern
        matches = self.ptn.findall(raw_value)
        updated_event = {}

        # Process each match group
        for k1, v1, k2, v2 in matches:
            if k1:
                # Handle unquoted key-value pair
                formatted_key = u"{0}{1}{2}".format(self.prefix, k1, self.suffix)
                self.set(event_obj, k1, v1, real_k=formatted_key, check_kw_name=True)

            if k2:
                # Handle quoted key-value pair
                formatted_key = u"{0}{1}{2}".format(self.prefix, k2, self.suffix)
                self.set(event_obj, k2, v2, real_k=formatted_key, check_kw_name=True)

        return updated_event

    def __call__(self, event, input_spec):
        # Normalize input to Unicode string
        input_spec = self._u(input_spec)

        # Convert single string to list for uniform processing
        if isinstance(input_spec, (six.binary_type, six.text_type)):
            input_spec = [input_spec]

        # Iterate over input fields if iterable
        if isinstance(input_spec, Iterable):
            for field_name in input_spec:
                # Validate field name type
                if not isinstance(field_name, (six.binary_type, six.text_type)):
                    logger.error(u"kv_transformer: unsupported field type '{0}'".format(field_name))
                    continue

                # Skip if field doesn't exist in event
                if field_name not in event:
                    logger.debug(u"kv_transformer: field '{0}' missing in event {1}".format(field_name, event))
                    continue

                # Extract and update key-value pairs
                result = self._parse_kv_pairs(event, event[field_name])
                event.update(result)
        else:
            logger.error(u"kv_transformer: invalid input type '{0}'".format(type(input_spec)))

        return event

import os
import json
import time
from typing import Any, List, Optional, TYPE_CHECKING
from dragonchain import logger
from dragonchain import exceptions
from dragonchain.lib.database import redis

if TYPE_CHECKING:
    from dragonchain.lib.types import JSONType

# Initialize logging and environment configuration
_logger = logger.get_logger()
env_level = os.environ["LEVEL"]
env_stage = os.environ["STAGE"]
storage_backend = os.environ["STORAGE_TYPE"].lower()
storage_path = os.environ["STORAGE_LOCATION"]

# Cache limit: maximum size (in bytes) for objects eligible for caching
MAX_CACHEABLE_SIZE = 52428800  # 50 MB

# Dynamically select storage interface based on backend type
if storage_backend == "s3":
    from dragonchain.lib.interfaces.aws import s3 as storage_module
elif storage_backend == "disk":
    from dragonchain.lib.interfaces.local import disk as storage_module  # noqa: T484
else:
    raise NotImplementedError(f"Unsupported storage backend: '{storage_backend}'")


def fetch_object(key: str, ttl: Optional[int] = None, use_cache: bool = True) -> bytes:
    """Retrieve an object from persistent storage, optionally using cache layer."""
    cached_result = None
    if use_cache:
        cached_result = redis.cache_get(key)

    if cached_result is None:
        try:
            raw_data = storage_module.get(storage_path, key)
        except exceptions.NotFound:
            raise
        except Exception:
            _logger.exception("Unexpected error during storage retrieval")
            raise exceptions.StorageError("Storage get operation failed unexpectedly")

        if use_cache and len(raw_data) < MAX_CACHEABLE_SIZE:
            redis.cache_put(key, raw_data, ttl)
        return raw_data
    else:
        return cached_result


def store_object(key: str, data: bytes, ttl: Optional[int] = None, use_cache: bool = True) -> None:
    """Persist an object to storage with optional caching."""
    try:
        storage_module.put(storage_path, key, data)
        if use_cache and len(data) < MAX_CACHEABLE_SIZE:
            redis.cache_put(key, data, ttl)
    except Exception:
        _logger.exception("Unexpected error during storage write")
        raise exceptions.StorageError("Storage put operation failed unexpectedly")


def remove_object(key: str) -> None:
    """Delete an object from storage and invalidate its cache entry."""
    try:
        storage_module.delete(storage_path, key)
        redis.cache_delete(key)
    except Exception:
        _logger.exception("Unexpected error during storage deletion")
        raise exceptions.StorageError("Storage delete operation failed unexpectedly")


def purge_directory(directory_key: str) -> None:
    """Recursively delete all objects under a given directory key."""
    try:
        item_keys = list_all_keys_under_prefix(directory_key)
        for item in item_keys:
            remove_object(item)
        storage_module.delete_directory(storage_path, directory_key)
    except Exception:
        _logger.exception("Unexpected error during directory cleanup")
        raise exceptions.StorageError("Directory removal operation failed unexpectedly")


def retrieve_transaction(block_id: str, txn_id: str, ttl: Optional[int] = None) -> dict:
    """Fetch a specific transaction by block and transaction ID, leveraging cache when possible."""
    full_key = f"{block_id}/{txn_id}"
    cached_value = redis.cache_get(full_key)
    if cached_value is not None:
        return json.loads(cached_value)

    try:
        raw_txn = storage_module.select_transaction(storage_path, block_id, txn_id)
        serialized = json.dumps(raw_txn, separators=(",", ":")).encode("utf-8")
        if len(serialized) < MAX_CACHEABLE_SIZE:
            redis.cache_put(full_key, serialized, ttl)
        return raw_txn
    except exceptions.NotFound:
        raise
    except Exception:
        _logger.exception("Unexpected error during transaction lookup")
        raise exceptions.StorageError("Transaction retrieval operation failed unexpectedly")


def store_json_object(key: str, payload: "JSONType", ttl: Optional[int] = None, use_cache: bool = True) -> None:
    """Serialize and store a JSON-compatible Python object."""
    serialized_bytes = json.dumps(payload, separators=(",", ":")).encode("utf-8")
    store_object(key, serialized_bytes, ttl, use_cache)


def load_json_object(key: str, ttl: Optional[int] = None, use_cache: bool = True) -> Any:
    """Load and deserialize a JSON object from storage."""
    raw_data = fetch_object(key, ttl, use_cache)
    return json.loads(raw_data)


def list_all_keys_under_prefix(prefix: str) -> List[str]:
    """List all object keys matching a given prefix."""
    try:
        return storage_module.list_objects(storage_path, prefix)
    except Exception:
        _logger.exception("Unexpected error during key listing")
        raise exceptions.StorageError("Key listing operation failed unexpectedly")


def check_directory_exists(directory_key: str) -> bool:
    """Check whether a directory-like superkey exists in storage."""
    try:
        return storage_module.does_superkey_exist(storage_path, directory_key)
    except Exception:
        _logger.exception("Unexpected error during directory existence check")
        raise exceptions.StorageError("Directory existence check failed unexpectedly")


def check_file_exists(object_key: str) -> bool:
    """Check whether a specific object key exists in storage."""
    try:
        return storage_module.does_object_exist(storage_path, object_key)
    except Exception:
        _logger.exception("Unexpected error during file existence check")
        raise exceptions.StorageError("File existence check failed unexpectedly")


def log_error_message(error_text: str) -> None:
    """Save an error message to storage with timestamped filename."""
    service_name = os.environ.get("SERVICE", "unknown")
    timestamp = time.time()
    filename = f"error_{service_name}_{timestamp}.log"
    store_object(filename, error_text.encode("utf-8"), use_cache=False)

import re
import os.path as path
from images import load as load_image
from medias import load as load_media
from utils import remove_invalid_chars, replace_bools

def process_game_nodes(base_dir, renpy, result):
    """
    Process all nodes into a usable format. The label named 'start' becomes node ID 0.
    """
    initial_label = find_label_by_name(renpy, 'start')
    actual_start = follow_node_chain(renpy, initial_label)
    pending_nodes = [actual_start]

    while pending_nodes:
        current_node = pending_nodes.pop(0)
        if current_node and id(current_node) not in result['nodes']:
            pending_nodes.extend(process_single_node(base_dir, renpy, current_node, result))

    # Reassign start node to ID 0
    start_id = id(actual_start)
    result['nodes'][0] = result['nodes'][start_id]
    del result['nodes'][start_id]

def find_label_by_name(renpy, name):
    """Find a label node by its name."""
    for key, node in renpy.game.script.namemap.items():
        if isinstance(node, renpy.ast.Label) and node.name == name:
            return node

def warn_unknown_node(node):
    """Display warning for unknown node types."""
    info = getattr(node, 'diff_info', lambda: str(node))()
    print(f'[WARNING] unknown node {type(node).__name__}: {info}')

def process_single_node(base_dir, renpy, node, result):
    """Process a single node based on its type."""
    handlers = {
        renpy.ast.Menu: menu_to_str,
        renpy.ast.Say: say_to_str,
        renpy.ast.If: if_to_str,
        renpy.ast.Python: python_to_str,
        renpy.ast.Scene: scene_to_str,
        renpy.ast.Show: show_to_str,
        renpy.ast.Hide: hide_to_str,
        renpy.ast.UserStatement: user_statement_to_str,
    }

    handler = handlers.get(type(node))
    if handler:
        return handler(base_dir, renpy, node, result)
    else:
        warn_unknown_node(node)
        next_node = follow_node_chain(renpy, node.next)
        return [str(id(next_node))] if next_node else []

def follow_node_chain(renpy, node):
    """Follow the chain of nodes, skipping irrelevant ones."""
    while True:
        if node is None:
            break

        # Handle known node types directly
        if isinstance(node, (
            renpy.ast.Menu, renpy.ast.Say, renpy.ast.If, renpy.ast.Python,
            renpy.ast.Scene, renpy.ast.Show, renpy.ast.Hide, renpy.ast.UserStatement
        )):
            return node

        # Handle jumps by following to target label
        elif isinstance(node, renpy.ast.Jump):
            node = find_label_by_name(renpy, node.target)

        # Skip control flow and metadata nodes
        elif isinstance(node, (
            renpy.ast.Label, renpy.ast.Translate, renpy.ast.EndTranslate,
            renpy.ast.Pass, renpy.ast.Return, renpy.ast.With
        )):
            node = node.next

        else:
            warn_unknown_node(node)
            break

    return node

def menu_to_str(renpy, node, result):
    """Convert menu node to string representation."""
    next_nodes = []
    menu_items = []
    display_texts = []

    for item in node.items:
        text, condition, next_item = item
        if next_item:
            next_node = follow_node_chain(renpy, next_item[0])
            result['nodes'][id(item)] = {
                'class_name': 'MenuItem',
                'arguments': [
                    text,
                    replace_bools(condition),
                    [str(id(next_node))] if next_node else []
                ]
            }
            next_nodes.append(next_node)
            menu_items.append(item)
        else:
            display_texts.append(text)

    item_ids = [str(id(item)) for item in menu_items]
    result['nodes'][id(node)] = {
        'class_name': 'Menu',
        'arguments': [
            '\n'.join(display_texts),
            item_ids
        ]
    }
    return next_nodes

def say_to_str(renpy, node, result):
    """Convert say node to string representation."""
    next_node = follow_node_chain(renpy, node.next)
    result['nodes'][id(node)] = {
        'class_name': 'Say',
        'arguments': [
            node.who,
            node.what,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def if_to_str(renpy, node, result):
    """Convert if statement node to string representation."""
    has_else = any(block[0] == 'True' for block in node.entries)
    if not has_else:
        node.entries.append(('true', [node.next]))

    block_nexts = []
    block_ids = []

    for condition, block in node.entries:
        next_block = follow_node_chain(renpy, block[0])
        block_id = id((condition, block))

        result['nodes'][block_id] = {
            'class_name': 'IfBlock',
            'arguments': [
                replace_bools(condition),
                [str(id(next_block))] if next_block else []
            ]
        }
        block_nexts.append(next_block)
        block_ids.append(str(block_id))

    result['nodes'][id(node)] = {
        'class_name': 'If',
        'arguments': [block_ids],
    }
    return block_nexts

# Regular expressions for parsing Python statements
VIDEO_PATTERN = re.compile(r'^\s*renpy\.movie_cutscene\s*\((.+)\)\s*$')
PLAY_PATTERN = re.compile(r'^\s*renpy\.sound\.play\s*\((.+)\)\s*$')
LOOP_PATTERN = re.compile(r'^\s*loop\s*=(.*)$')

def python_to_str(base_dir, renpy, node, result):
    """Convert Python statement node to string representation."""
    next_node = follow_node_chain(renpy, node.next)
    next_ids = [str(id(next_node))] if next_node else []

    video_match = VIDEO_PATTERN.search(node.code.source)
    if video_match and len(video_match.groups()) == 1:
        file_path = video_match.group(1)[1:-1]
        vid_name = remove_invalid_chars(file_path)
        load_media(base_dir, result, 'videos', vid_name, file_path)
        result['nodes'][id(node)] = {
            'class_name': 'Video',
            'arguments': [
                vid_name,
                next_ids
            ]
        }
    else:
        play_match = PLAY_PATTERN.search(node.code.source)
        if play_match and len(play_match.groups()) == 1:
            args = [arg.strip() for arg in play_match.group(1).split(',')]
            loop_flag = extract_loop_value(args[1:])
            play_to_str(base_dir, node, next_ids, result, args[0][1:-1], 'sound', loop_flag)
        else:
            result['nodes'][id(node)] = {
                'class_name': 'PyExpr',
                'arguments': [
                    replace_bools(node.code.source),
                    next_ids
                ]
            }
    return [next_node]

def extract_loop_value(args):
    """Extract loop flag from arguments."""
    for arg in args:
        match = LOOP_PATTERN.match(arg)
        if match:
            return match.group(1) == "True"
    return False

def scene_to_str(base_dir, renpy, node, result):
    """Convert scene node to string representation."""
    next_node = follow_node_chain(renpy, node.next)
    name = node.imspec[0][0]
    load_image(base_dir, renpy, result, name, node.imspec)
    result['nodes'][id(node)] = {
        'class_name': 'Scene',
        'arguments': [
            name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def show_to_str(base_dir, renpy, node, result):
    """Convert show node to string representation."""
    next_node = follow_node_chain(renpy, node.next)
    name = node.imspec[0][0]
    is_movie = load_image(base_dir, renpy, result, name, node.imspec)
    result['nodes'][id(node)] = {
        'class_name': 'ShowVideo' if is_movie else 'Show',
        'arguments': [
            name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def hide_to_str(renpy, node, result):
    """Convert hide node to string representation."""
    next_node = follow_node_chain(renpy, node.next)
    result['nodes'][id(node)] = {
        'class_name': 'Hide',
        'arguments': [
            node.imspec[0][0],
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

WORD_PATTERN = re.compile(r'([\w.]+|".*?")')

def user_statement_to_str(base_dir, renpy, node, result):
    """Convert user statement node to string representation."""
    tokens = WORD_PATTERN.findall(node.line)
    next_node = follow_node_chain(renpy, node.next)
    next_ids = [str(id(next_node))] if next_node else []

    if tokens[0] == 'play' and len(tokens) >= 3:
        loop_flag = 'loop' in tokens[3:] if len(tokens) >= 4 else False
        play_to_str(base_dir, node, next_ids, result, tokens[2][1:-1], tokens[1], loop_flag)
    elif tokens[0] == 'voice' and len(tokens) >= 2:
        play_to_str(base_dir, node, next_ids, result, tokens[1][1:-1], 'voice', False)
    elif tokens[0] == 'stop' and len(tokens) >= 2:
        stop_to_str(tokens, node, next_ids, result)
    elif tokens[0] == 'window' and len(tokens) >= 2:
        window_to_str(tokens, node, next_ids, result)
    elif tokens[0] == 'pause' and len(tokens) >= 1:
        pause_to_str(tokens, node, next_ids, result)
    else:
        print(f'[WARNING] unrecognized UserStatement: {node.line}')

    return [next_node]

VIDEO_EXTENSIONS = ['.webm', '.ogv']

def play_to_str(base_dir, node, next_ids, result, file_path, channel, loop_flag):
    """Handle play command for media."""
    sound_name = remove_invalid_chars(file_path)
    _, ext = path.splitext(file_path)
    media_category = 'videos' if ext in VIDEO_EXTENSIONS else 'sounds'
    load_media(base_dir, result, media_category, sound_name, file_path)
    result['nodes'][id(node)] = {
        'class_name': 'Play',
        'arguments': [
            channel,
            sound_name,
            loop_flag,
            next_ids
        ]
    }

def stop_to_str(tokens, node, next_ids, result):
    """Handle stop command."""
    channel = tokens[1]
    result['nodes'][id(node)] = {
        'class_name': 'Stop',
        'arguments': [
            channel,
            next_ids
        ]
    }

def window_to_str(tokens, node, next_ids, result):
    """Handle window command."""
    show_window = None
    if tokens[1] == 'show':
        show_window = True
    elif tokens[1] == 'hide':
        show_window = False

    if isinstance(show_window, bool):
        result['nodes'][id(node)] = {
            'class_name': 'ShowWindow',
            'arguments': [
                show_window,
                next_ids
            ]
        }
    else:
        print(f'[WARNING] unrecognized window option: {tokens[1]}')

def pause_to_str(tokens, node, next_ids, result):
    """Handle pause command."""
    result['nodes'][id(node)] = {
        'class_name': 'Pause',
        'arguments': [
            next_ids
        ]
    }

import re
import json as _json_lib
import socket
import asyncio
import logging
# Third Party
import httpx
# Project
from stats.util import make_repr, split_on_uppercase

DEFAULT_LOG = logging.getLogger(__file__)

class HttpClientBase:
    """Base session handler for HTTP operations."""

    def __init__(
        self,
        server_url,
        settings=None,
        path_prefix="",
        path_suffix="",
        ssl_check=True,
        connection_timeout=10,
        log_handler=DEFAULT_LOG,
        error_type=Exception,
        client_identifier=f"httpx/{httpx.__version__}",
    ):
        """Initialize the HTTP client instance."""
        self.__class__.__name__ = self.class_name
        self.settings = settings
        self.scheme, self.hostname, self.port_number = self._extract_url_parts(server_url)
        self.root_url = self._construct_url(self.scheme, self.hostname, self.port_number)
        self.path_prefix = path_prefix.strip("/")
        self.path_suffix = path_suffix.strip("/")
        self.ssl_verification = ssl_check
        self.connect_timeout = connection_timeout
        self.logger = log_handler
        self.error_class = error_type
        self.client_agent = client_identifier

        # Session configuration
        session_config = {
            "verify": self.ssl_verification,
            "base_url": self.root_url,
            "timeout": self.connect_timeout,
        }

        # Create sync and async clients
        self._sync_client = httpx.Client(**session_config)
        self._async_client = httpx.AsyncClient(**session_config)

    @classmethod
    def __init_subclass__(cls, identifier=None, **kwargs):
        """Assign appropriate subclass name."""
        super().__init_subclass__(**kwargs)
        cls.class_name = identifier or cls.__name__

    async def __aenter__(self):
        """Verify connectivity when entering context manager."""
        reachable = await self._check_availability()
        if reachable:
            self.logger.debug("Established session with {}", self.root_url)
            return self
        else:
            raise self._create_error(f"Unable to establish session to {self.class_name}")

    async def __aexit__(self, exc_type=None, exc_value=None, traceback=None):
        """Clean up connection on exit."""
        self.logger.debug("Terminating session with {}", self.root_url)
        await self._async_client.aclose()

    def __enter__(self):
        """Verify connectivity when entering context manager."""
        reachable = self._check_connectivity()
        if reachable:
            self.logger.debug("Established session with {}", self.root_url)
            return self
        else:
            raise self._create_error(f"Unable to establish session to {self.class_name}")

    def __exit__(self, exc_type=None, exc_value=None, traceback=None):
        """Clean up connection on exit."""
        if exc_type is not None:
            self.logger.error(traceback)
        self._sync_client.close()

    def __repr__(self):
        """Return user-friendly representation of instance."""
        return make_repr(self)

    def _create_error(self, msg, original_exc=None, **extra_kwargs):
        """Enhance error message with exception details if provided."""
        if original_exc is not None:
            msg = "{}: {}".format(str(msg), str(original_exc), **extra_kwargs)
        return self.error_class(msg)

    def _check_connectivity(self):
        """Perform basic port check to verify server availability."""
        self.logger.debug("Verifying connectivity to {}", self.root_url)
        try:
            host_without_protocol = re.sub(r"http(s)?\:\/\/", "", self.root_url)
            socket.socket().connect((host_without_protocol, 443))
        except socket.gaierror as err:
            raise self._create_error(
                f"{self.class_name} appears unreachable", err
            ) from None
        return True

    async def _check_availability(self):
        """Asynchronously verify server connectivity."""
        self.logger.debug("Verifying connectivity to {}", self.root_url)
        try:
            reader, writer = await asyncio.open_connection(self.hostname, self.port_number)
            return bool(reader or writer)
        except socket.gaierror as err:
            raise self._create_error(
                f"{self.class_name} appears unreachable at {self.root_url}", err
            )

    @staticmethod
    def _construct_url(scheme, hostname, port):
        port_str = str(port)
        if port_str == "80":
            port_str = ""
            scheme = "http"
        elif port_str == "443":
            port_str = ""
            scheme = "https"
        if port_str != "":
            port_str = f":{port_str}"
        return "{scheme}://{hostname}{port}".format(
            scheme=scheme, hostname=hostname, port=port_str
        )

    @staticmethod
    def _extract_url_parts(url):
        [url_components] = re.findall(r"^(http[s]?):\/\/([^:]+)\:?(\d*)$", url)
        scheme, hostname, port = url_components
        return scheme, hostname, int(port)

    @staticmethod
    def _normalize_dict(data):
        return _json_lib.loads(_json_lib.dumps(data, default=str))

    def _handle_response(self, raw_response):
        """Process response data into structured format."""
        result = {}
        try:
            result = raw_response.json()
        except _json_lib.JSONDecodeError:
            try:
                result = _json_lib.loads(raw_response)
            except (_json_lib.JSONDecodeError, TypeError):
                self.logger.error("Failed to parse JSON in response {}", repr(raw_response))
                result = {"data": raw_response.text}
        return result

    @staticmethod
    def _format_exception(exception_obj):
        """Convert exception into readable string format."""
        if not isinstance(exception_obj, BaseException):
            raise TypeError(f"'{repr(exception_obj)}' is not an exception.")

        def get_class_name(exc):
            return " ".join(split_on_uppercase(exc.__class__.__name__))

        def extract_first_line(doc):
            return doc.strip().split("\n")[0].strip(".")

        name = get_class_name(exception_obj)
        components = []

        if exception_obj.__doc__:
            description = extract_first_line(exception_obj.__doc__)
            components.append(f"{name} ({description})")
        else:
            components.append(name)

        if exception_obj.__cause__:
            cause_name = get_class_name(exception_obj.__cause__)
            if exception_obj.__cause__.__doc__:
                cause_desc = extract_first_line(exception_obj.__cause__.__doc__)
                components.append(f"{cause_name} ({cause_desc})")
            else:
                components.append(cause_name)

        return ", caused by ".join(components)

    def _prepare_request(self, **kwargs):
        """Transform request parameters into httpx-compatible structure."""
        from operator import itemgetter

        valid_methods = ("GET", "POST", "PUT", "DELETE", "HEAD", "PATCH")

        (
            http_method,
            route_path,
            resource_item,
            custom_headers,
            query_params,
            payload_data,
            request_timeout,
            needs_response,
        ) = itemgetter(*kwargs.keys())(kwargs)

        if http_method.upper() not in valid_methods:
            raise self._create_error(
                f'Method must be one of {", ".join(valid_methods)}. '
                f"Received: {str(http_method)}"
            )

        # Build endpoint path
        route_segments = [
            "",
            self.path_prefix.strip("/"),
            route_path.strip("/"),
            self.path_suffix.strip("/"),
            resource_item,
        ]
        final_route = "/".join(segment for segment in route_segments if segment)

        # Construct request object
        request_spec = {
            "method": http_method,
            "url": final_route,
            "headers": {"user-agent": self.client_agent},
        }

        if custom_headers is not None:
            request_spec.update({"headers": custom_headers})

        if query_params is not None:
            normalized_params = {str(k): str(v) for k, v in query_params.items() if v is not None}
            request_spec["params"] = normalized_params

        if payload_data is not None:
            if not isinstance(payload_data, dict):
                raise self._create_error(f"Payload must be a dict, got: {str(payload_data)}")
            request_spec["json"] = self._normalize_dict(payload_data)

        if request_timeout is not None:
            if not isinstance(request_timeout, int):
                try:
                    request_timeout = int(request_timeout)
                except TypeError:
                    raise self._create_error(
                        f"Timeout must be an integer, got: {str(request_timeout)}"
                    )
            request_spec["timeout"] = request_timeout

        self.logger.debug("Built request specification {}", request_spec)
        return request_spec

    async def _execute_async_request(  # noqa: C901
        self,
        method,
        path,
        item=None,
        headers=None,
        params=None,
        body=None,
        timeout=None,
        expect_response=False,
    ):
        """Execute asynchronous HTTP request."""
        prepared_request = self._prepare_request(
            method=method,
            endpoint=path,
            item=item,
            headers=headers,
            params=params,
            data=body,
            timeout=timeout,
            response_required=expect_response,
        )

        try:
            response = await self._async_client.request(**prepared_request)

            if response.status_code not in range(200, 300):
                status_code = httpx.StatusCode(response.status_code)
                error_details = self._handle_response(response)
                raise self._create_error(
                    f'{status_code.name.replace("_", " ")}: {error_details}', level="danger"
                ) from None

        except httpx.HTTPError as network_error:
            raise self._create_error(self._format_exception(network_error)) from None

        return self._handle_response(response)

    # Async methods
    async def _fetch_async(self, path, **kwargs):
        return await self._execute_async_request(method="GET", path=path, **kwargs)

    async def _submit_async(self, path, **kwargs):
        return await self._execute_async_request(method="POST", path=path, **kwargs)

    async def _update_async(self, path, **kwargs):
        return await self._execute_async_request(method="PUT", path=path, **kwargs)

    async def _remove_async(self, path, **kwargs):
        return await self._execute_async_request(method="DELETE", path=path, **kwargs)

    async def _modify_async(self, path, **kwargs):
        return await self._execute_async_request(method="PATCH", path=path, **kwargs)

    async def _inspect_async(self, path, **kwargs):
        return await self._execute_async_request(method="HEAD", path=path, **kwargs)

    def _execute_sync_request(  # noqa: C901
        self,
        method,
        path,
        item=None,
        headers=None,
        params=None,
        body=None,
        timeout=None,
        expect_response=False,
    ):
        """Execute synchronous HTTP request."""
        prepared_request = self._prepare_request(
            method=method,
            endpoint=path,
            item=item,
            headers=headers,
            params=params,
            data=body,
            timeout=timeout,
            response_required=expect_response,
        )

        try:
            response = self._sync_client.request(**prepared_request)

            if response.status_code not in range(200, 300):
                status_code = httpx.StatusCode(response.status_code)
                error_details = self._handle_response(response)
                raise self._create_error(
                    f'{status_code.name.replace("_", " ")}: {error_details}', level="danger"
                ) from None

        except httpx.HTTPError as network_error:
            raise self._create_error(
                self._format_exception(network_error), level="danger"
            ) from None

        return self._handle_response(response)

    # Sync methods
    def _fetch(self, path, **kwargs):
        return self._execute_sync_request(method="GET", path=path, **kwargs)

    def _submit(self, path, **kwargs):
        return self._execute_sync_request(method="POST", path=path, **kwargs)

    def _update(self, path, **kwargs):
        return self._execute_sync_request(method="PUT", path=path, **kwargs)

    def _remove(self, path, **kwargs):
        return self._execute_sync_request(method="DELETE", path=path, **kwargs)

    def _modify(self, path, **kwargs):
        return self._execute_sync_request(method="PATCH", path=path, **kwargs)

    def _inspect(self, path, **kwargs):
        return self._execute_sync_request(method="HEAD", path=path, **kwargs)

import os
