def load_properties_from_env(_):
    """Constructs a Properties instance using environment variables.

    Maps configuration keys from dot-notation (e.g., 'server.port') to
    uppercase underscore-separated env var names (e.g., 'SERVER_PORT').
    Only includes keys that have non-empty values in the environment.
    """
    config_dict = {}
    for key in DEFAULT_ALLOWED_PROPERTY_KEYS:
        env_key = key.replace('.', '_').upper()
        val = os.getenv(env_key)
        if val is not None and val != "":
            config_dict[key] = val
    return Properties(config_dict)


def build_request_from_aws_event(aws_event):
    """Creates a standardized Request object from an AWS Lambda event payload."""
    req = Request()
    mapping_rules = [
        ("pathParameters", req.add_path_param),
        ("queryStringParameters", req.add_query_param),
        ("headers", req.add_header)
    ]

    for param_type, setter in mapping_rules:
        raw_params = aws_event.get(param_type)
        if raw_params:
            [(setter(k, v) for k, v in raw_params.items())]

    return req


def create_empty_response():
    """Returns a fresh Response object ready to be populated."""
    return Response()


def prepare_runtime_objects(event, context):
    """Gathers all runtime dependencies: properties, request, and response."""
    return [
        load_properties_from_env(context),
        build_request_from_aws_event(event),
        create_empty_response()
    ]


def adapt_response_for_lambda(resp_obj):
    """Transforms internal Response into AWS Lambda-compatible dictionary format."""
    return {
        "statusCode": resp_obj.get_status_code(),
        "headers": resp_obj.get_headers(),
        "body": resp_obj.get_body()
    }


def handle_get_sequence(event, ctx):
    """AWS Lambda handler for /sequence/{id} endpoint."""
    props, req, resp = prepare_runtime_objects(event, ctx)
    fetch_sequence(props, req, resp)
    return adapt_response_for_lambda(resp)


def handle_get_metadata(event, ctx):
    """AWS Lambda handler for /sequence/{id}/metadata endpoint."""
    props, req, resp = prepare_runtime_objects(event, ctx)
    fetch_metadata(props, req, resp)
    return adapt_response_for_lambda(resp)


def handle_get_service_info(event, ctx):
    """AWS Lambda handler for /service-info endpoint."""
    props, req, resp = prepare_runtime_objects(event, ctx)
    fetch_service_info(props, req, resp)
    return adapt_response_for_lambda(resp)

from typing import Callable, Any, TypeVar, ParamSpec
from functools import wraps

T = TypeVar('T')
P = ParamSpec('P')

class SolanaErrorBase(Exception):
    """Root exception class for Solana-py error handling."""
    def __init__(self, original_error: Exception, operation: Callable[..., Any], *params: Any, **options: Any) -> None:
        """Initialize with wrapped exception details."""
        super().__init__()
        self.message = self._compose_message(original_error, operation, *params, **options)

    @staticmethod
    def _compose_message(
        original_error: Exception, operation: Callable[..., Any], *params: Any, **options: Any  # pylint: disable=unused-argument
    ) -> str:
        return f"{type(original_error).__name__} occurred during {operation.__name__} execution"

class SolanaNetworkException(SolanaErrorBase):
    """Specific exception type for RPC-related issues."""
    @staticmethod
    def _compose_message(
        original_error: Exception, operation: Callable[..., Any], *params: Any, **options: Any  # pylint: disable=unused-argument
    ) -> str:
        endpoint_name = params[1] if len(params) > 1 else "unknown"
        return f'{type(original_error).__name__} triggered in "{endpoint_name}" API call'

def catch_errors(exception_wrapper, *handled_types):
    """Decorator factory to wrap specific exceptions with custom handlers."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except handled_types as err:
                raise exception_wrapper(err, fn, *args, **kwargs) from err
        return wrapper
    return decorator

def async_catch_errors(exception_wrapper, *handled_types):
    """Decorator factory for asynchronous functions with exception wrapping."""
    def decorator(fn):
        @wraps(fn)
        async def wrapper(*args, **kwargs):
            try:
                return await fn(*args, **kwargs)
            except handled_types as err:
                raise exception_wrapper(err, fn, *args, **kwargs) from err
        return wrapper
    return decorator

import numpy as np
import multiprocessing
from unittest import IsolatedAsyncioTestCase
from ourtransform.framework import Process, Selector, AnyChain, Transformer, Element

def transform_dict_values(input_dict: dict) -> list:
    # Return keys where the value equals 1
    return [key for key, value in input_dict.items() if value == 1]

class TestFrameworkAsync(IsolatedAsyncioTestCase):
    async def test_process_run_async_will_succeed(self):
        # Create a process with a selector containing an AnyChain of transformers
        pipeline = Process(
            selector=Selector(
                chains=[
                    AnyChain(
                        ordered_events=[
                            Transformer(fn=transform_dict_values),
                        ],
                    ),
                ],
            ),
        )

        try:
            # Run the process asynchronously with test elements
            output = await pipeline.run_async(
                elements=[
                    Element(input={"a": 0, "b": 1}),
                    Element(input={"c": 0, "y": 1}),
                    Element(input={"d": 1, "b": 0}),
                ]
            )

            # Verify results match expected outputs
            self.assertEqual(["b"], output.elements[0].output)
            self.assertEqual(["y"], output.elements[1].output)
            self.assertEqual(["d"], output.elements[2].output)
        except Exception as error:
            self.fail(f"Unexpected exception occurred: {error}")

    async def test_process_run_async_with_timeout(self):
        # Generate random character set
        letters = list("abcdefghijklmno")

        # Build process with same structure
        workflow = Process(
            selector=Selector(
                chains=[
                    AnyChain(
                        ordered_events=[
                            Transformer(fn=transform_dict_values),
                        ],
                    ),
                ],
            ),
        )

        try:
            # Generate many random input dictionaries
            random_inputs = [
                Element(
                    input={
                        np.random.choice(letters): np.random.randint(0, 2) 
                        for _ in range(np.random.randint(1, 10))
                    }
                )
                for _ in range(10000)
            ]

            # Attempt to run with short timeout
            await workflow.run_async(elements=random_inputs, timeout=0.1)
        except Exception as exc:
            # Expect timeout error due to large workload and short timeout
            self.assertIsInstance(exc, multiprocessing.TimeoutError)

from __future__ import annotations
import logging
from abc import ABCMeta, abstractmethod
from typing import Any, Dict, Iterable, List, Optional, Tuple, cast
import boto3
from pallas.csv import read_csv
from pallas.info import QueryInfo
from pallas.results import QueryResults
from pallas.storage.s3 import s3_parse_uri, s3_wrap_body
from pallas.utils import truncate_str

logger = logging.getLogger(__name__)

# Type aliases for clarity
FieldNames = Tuple[str, ...]
FieldTypes = Tuple[str, ...]
Record = Tuple[Optional[str], ...]


class AthenaAccessor(metaclass=ABCMeta):
    """
    Internal abstraction layer over AWS Athena services.
    Allows substitution with mock implementations for unit testing.
    """

    @abstractmethod
    def submit_query(
        self,
        query: str,
        *,
        schema: str | None = None,
        group: str | None = None,
        result_bucket: str | None = None,
    ) -> str:
        """Initiate execution of an SQL statement."""

    @abstractmethod
    def fetch_status(self, exec_id: str) -> QueryInfo:
        """Poll current status and metadata of a running query."""

    @abstractmethod
    def retrieve_results(self, info: QueryInfo) -> QueryResults:
        """Fetch full result set after completion."""

    @abstractmethod
    def cancel_query(self, exec_id: str) -> None:
        """Terminate an ongoing query execution."""


class Boto3AthenaClient(AthenaAccessor):
    """
    Concrete implementation using AWS SDK (boto3).
    Used by higher-level clients unless overridden in tests.
    """

    _athena: Any  # boto3 client for Athena
    _s3: Any      # boto3 client for S3

    def __init__(
        self,
        *,
        region: str | None = None,
        athena_client: Any | None = None,
        s3_client: Any | None = None,
    ) -> None:
        if athena_client is None:
            athena_client = boto3.client("athena", region_name=region)
        if s3_client is None:
            s3_client = boto3.client("s3")
        self._athena = athena_client
        self._s3 = s3_client

    def submit_query(
        self,
        query: str,
        schema: str | None = None,
        group: str | None = None,
        result_bucket: str | None = None,
    ) -> str:
        payload: Dict[str, Any] = {"QueryString": query}
        if schema is not None:
            payload["QueryExecutionContext"] = {"Database": schema}
        if group is not None:
            payload["WorkGroup"] = group
        if result_bucket is not None:
            payload["ResultConfiguration"] = {"OutputLocation": result_bucket}

        logger.debug(f"SubmitQuery: {truncate_str(query)!r}")
        resp = self._athena.start_query_execution(**payload)
        exec_id = cast(str, resp["QueryExecutionId"])
        logger.debug(f"Started execution: {exec_id!r}")
        return exec_id

    def fetch_status(self, exec_id: str) -> QueryInfo:
        logger.debug(f"Fetching status for: {exec_id!r}")
        resp = self._athena.get_query_execution(QueryExecutionId=exec_id)
        info = QueryInfo(resp["QueryExecution"])
        logger.debug(f"Status update: {info}")
        return info

    def retrieve_results(self, info: QueryInfo) -> QueryResults:
        exec_id = info.execution_id
        params = {"QueryExecutionId": exec_id}
        logger.debug(f"Retrieving results for: {exec_id!r}")
        raw = self._athena.get_query_results(**params)

        headers = _extract_headers(raw)
        types = _extract_types(raw)

        if "NextToken" in raw:
            logger.debug("Large result set; fetching from S3.")
            rows = self._fetch_from_s3(info)
        else:
            rows = _parse_rows(raw)
            logger.debug(f"Full result loaded: {len(rows)} rows (incl. header)")

        cleaned = _clean_data(headers, rows)
        return QueryResults(headers, types, cleaned)

    def cancel_query(self, exec_id: str) -> None:
        logger.debug(f"Cancelling execution: {exec_id!r}")
        self._athena.stop_query_execution(QueryExecutionId=exec_id)

    def _fetch_from_s3(self, info: QueryInfo) -> List[Record]:
        bucket, path = s3_parse_uri(info.output_location)
        params = {"Bucket": bucket, "Key": path}
        logger.debug(f"S3 GetObject: {bucket}/{path}")

        resp = self._s3.get_object(**params)
        with s3_wrap_body(resp["Body"]) as stream:
            records = list(read_csv(stream))
        logger.debug(f"Downloaded {len(records)} rows from S3")
        return records


def _clean_data(field_names: FieldNames, raw_records: Iterable[Record]) -> List[Record]:
    """
    Normalize Athena output depending on query engine used.

    - Presto-based queries (e.g., SELECT) may duplicate column names in first row.
    - Hive-based queries (e.g., DESCRIBE) may merge fields into single string per row.
    """
    rec_list = list(raw_records)
    if not rec_list:
        return []

    first_row = rec_list[0]
    if tuple(first_row) == field_names:
        # DQL/Presto case: drop header row
        return rec_list[1:]
    elif all(len(r) == 1 for r in rec_list) and len(field_names) > 1:
        # DCL/Hive case: split tab-separated values
        parsed = []
        for row in rec_list:
            val = row[0]
            if val is not None:
                parts = val.split("\t", maxsplit=len(field_names) - 1)
                parsed.append(tuple(parts))
        return parsed
    return rec_list


def _extract_headers(response: Dict[str, Any]) -> FieldNames:
    meta = response["ResultSet"]["ResultSetMetadata"]["ColumnInfo"]
    return tuple(col["Name"] for col in meta)


def _extract_types(response: Dict[str, Any]) -> FieldTypes:
    meta = response["ResultSet"]["ResultSetMetadata"]["ColumnInfo"]
    return tuple(col["Type"] for col in meta)


def _parse_rows(response: Dict[str, Any]) -> List[Record]:
    rows = response["ResultSet"]["Rows"]
    return [tuple(item.get("VarCharValue") for item in row["Data"]) for row in rows]

