def get_world_size() -> int:
    if not dist.is_available() or not dist.is_initialized():
        return 1
    return dist.get_world_size()

def get_rank(group=None) -> int:
    if not dist.is_available() or not dist.is_initialized():
        return 0
    return dist.get_rank(group=group)

def get_local_rank() -> int:
    if _LOCAL_PROCESS_GROUP is None:
        return 0
    return get_rank(group=_LOCAL_PROCESS_GROUP)

def get_local_size() -> int:
    if _LOCAL_PROCESS_GROUP is None:
        return 1
    return dist.get_world_size(group=_LOCAL_PROCESS_GROUP)

def is_main_process() -> bool:
    return get_rank() == 0

def synchronize():
    if not dist.is_available() or not dist.is_initialized():
        return
    world_size = get_world_size()
    if world_size <= 1:
        return
    dist.barrier()

def _get_global_gloo_group():
    global _GLOBAL_GLOO_GROUP
    if _GLOBAL_GLOO_GROUP is not None:
        return _GLOBAL_GLOO_GROUP
    backend = dist.get_backend()
    if backend == "nccl":
        _GLOBAL_GLOO_GROUP = dist.new_group(backend="gloo")
    else:
        _GLOBAL_GLOO_GROUP = dist.group.WORLD
    return _GLOBAL_GLOO_GROUP

def _serialize_to_tensor(data, group):
    backend = dist.get_backend(group)
    if backend not in ("gloo", "nccl"):
        raise ValueError(f"Unsupported backend: {backend}")
    device = torch.device("cpu" if backend == "gloo" else "cuda")
    buffer_bytes = pickle.dumps(data)
    buffer_len = len(buffer_bytes)
    if buffer_len > 1024 ** 3:
        logger = logging.getLogger(__name__)
        logger.warning(
            f"Rank {get_rank()} attempting to all-gather {buffer_len / (1024 ** 3):.2f} GB on device {device}"
        )
    storage = torch.ByteStorage.from_buffer(buffer_bytes)
    buffer_tensor = torch.ByteTensor(storage).to(device=device)
    return buffer_tensor

def _pad_to_largest_tensor(tensor, group):
    world_size = get_world_size(group=group)
    assert world_size >= 1, "Communication must occur within a valid group."
    local_len = torch.tensor([tensor.numel()], dtype=torch.int64, device=tensor.device)
    sizes = [torch.zeros_like(local_len) for _ in range(world_size)]
    dist.all_gather(sizes, local_len, group=group)
    sizes = [int(s.item()) for s in sizes]
    max_len = max(sizes)
    current_len = tensor.numel()
    if current_len < max_len:
        pad_len = max_len - current_len
        padding = torch.zeros((pad_len,), dtype=torch.uint8, device=tensor.device)
        padded_tensor = torch.cat((tensor, padding), dim=0)
    else:
        padded_tensor = tensor
    return sizes, padded_tensor

def all_gather(data, group=None):
    world_size = get_world_size()
    if world_size == 1:
        return [data]
    if group is None:
        group = _get_global_gloo_group()
    if get_world_size(group) == 1:
        return [data]
    buffer_tensor = _serialize_to_tensor(data, group)
    sizes, buffer_tensor = _pad_to_largest_tensor(buffer_tensor, group)
    max_len = max(sizes)
    gathered_tensors = [
        torch.empty((max_len,), dtype=torch.uint8, device=buffer_tensor.device)
        for _ in sizes
    ]
    dist.all_gather(gathered_tensors, buffer_tensor, group=group)
    results = []
    for size, tensor in zip(sizes, gathered_tensors):
        raw_bytes = tensor.cpu().numpy().tobytes()[:size]
        results.append(pickle.loads(raw_bytes))
    return results

def gather(data, dst=0, group=None):
    world_size = get_world_size()
    if world_size == 1:
        return [data]
    if group is None:
        group = _get_global_gloo_group()
    if get_world_size(group) == 1:
        return [data]
    rank = get_rank(group=group)
    buffer_tensor = _serialize_to_tensor(data, group)
    sizes, buffer_tensor = _pad_to_largest_tensor(buffer_tensor, group)
    if rank == dst:
        max_len = max(sizes)
        gathered_tensors = [
            torch.empty((max_len,), dtype=torch.uint8, device=buffer_tensor.device)
            for _ in sizes
        ]
        dist.gather(buffer_tensor, gathered_tensors, dst=dst, group=group)
        results = []
        for size, tensor in zip(sizes, gathered_tensors):
            raw_bytes = tensor.cpu().numpy().tobytes()[:size]
            results.append(pickle.loads(raw_bytes))
        return results
    else:
        dist.gather(buffer_tensor, [], dst=dst, group=group)
        return []

def shared_random_seed():
    seed_int = int(np.random.randint(2 ** 31))
    seeds = all_gather(seed_int)
    return seeds[0]

def reduce_dict(input_dict, average=True):
    world_size = get_world_size()
    if world_size < 2:
        return input_dict
    with torch.no_grad():
        keys = sorted(input_dict.keys())
        values = torch.stack([input_dict[k] for k in keys], dim=0)
        dist.reduce(values, dst=0)
        if get_rank() == 0 and average:
            values /= world_size
        reduced = {k: v for k, v in zip(keys, values)}
    return reduced

