# Configure logger
_logger = logging.getLogger(__name__)
_logger.propagate = False

# Formatters
_pprint_fmt = logging.Formatter('%(message)s')
_std_fmt = logging.Formatter('[%(levelname)s] --- %(message)s')

# Handler setup
_handler = logging.StreamHandler(sys.stdout)
_handler.setFormatter(_std_fmt)
