class JSONComparator:
    """Dac-Man plug-in to compare JSON files"""

    @staticmethod
    def description():
        return JSONComparator.__doc__

    @staticmethod
    def supports():
        return ['json']

    # Markers for differences
    positive_marker = '+'
    negative_marker = '-'

    def _validate_paths(self, file_paths: list) -> bool:
        all_valid = True
        for path in file_paths:
            if not os.path.exists(path):
                _logger.error(f'Invalid path: {path}')
                all_valid = False
        return all_valid

    def _format_diff_output(
            self, diff_data: dict, prefix: str = '', spacing: int = 2):
        indent_str = spacing * ' '
        for key, value in diff_data.items():
            if key.startswith((self.positive_marker, self.negative_marker)):
                marker, actual_key = key[0], key[1:]
            else:
                marker, actual_key = prefix, key

            if isinstance(value, dict):
                _logger.info(f'{marker}{indent_str}{actual_key}: {{')
                new_spacing = spacing + 2
                self._format_diff_output(
                    value, prefix=marker, spacing=new_spacing)
                _logger.info(f'{marker}{indent_str}}}')
            else:
                _logger.info(f'{marker}{indent_str}{actual_key}: {value}')

    def _count_nested_keys(self, data: dict, depth: int = 0) -> dict:
        counts = {depth: 0}
        for k, v in data.items():
            if isinstance(v, dict):
                sub_counts = self._count_nested_keys(v, depth + 1)
                for d, cnt in sub_counts.items():
                    counts[d] = cnt
            counts[depth] += 1
        return counts

    def _update_key_statistics(
            self, filename: str, data: dict, stats: dict):
        level_zero = stats.setdefault(0, {})
        level_zero[filename] = level_zero.get(filename, 0) + 1

        if not isinstance(data, dict):
            return

        nested_counts = self._count_nested_keys(data)
        total_keys = 1 + sum(nested_counts.values())
        stats[f'total_{filename}_keys'] = stats.get(f'total_{filename}_keys', 0) + total_keys

        for depth, count in nested_counts.items():
            deeper_stats = stats.setdefault(depth + 1, {})
            deeper_stats[filename] = deeper_stats.get(filename, 0) + count

    def _compare_json_objects(
            self, obj_a: dict, obj_b: dict, depth: int = 0) -> (dict, dict):
        result = {}
        keys_a = set(obj_a.keys())
        keys_b = set(obj_b.keys())

        stats = {
            f'total_{self.file_a_name}_keys': 0,
            f'total_{self.file_b_name}_keys': 0,
            'shared_keys_count': 0,
            depth: {self.file_a_name: 0, self.file_b_name: 0, 'common': 0}}

        # Keys only in A
        for key in keys_a - keys_b:
            result[f'{self.positive_marker}{key}'] = obj_a[key]
            self._update_key_statistics(self.file_a_name, obj_a[key], stats)

        # Keys only in B
        for key in keys_b - keys_a:
            result[f'{self.negative_marker}{key}'] = obj_b[key]
            self._update_key_statistics(self.file_b_name, obj_b[key], stats)

        # Common keys
        for key in keys_a & keys_b:
            stats['shared_keys_count'] += 1
            val_a = obj_a[key]
            val_b = obj_b[key]
            stats[depth]['common'] += 1

            if isinstance(val_a, dict) and isinstance(val_b, dict):
                sub_result, sub_stats = self._compare_json_objects(
                    val_a, val_b, depth + 1)
                if sub_result:
                    result[key] = sub_result

                for stat_key, stat_val in sub_stats.items():
                    if isinstance(stat_val, dict):
                        deeper_level = stats.setdefault(depth + 1, {})
                        for fname, cnt in stat_val.items():
                            deeper_level[fname] = deeper_level.get(fname, 0) + cnt
                    else:
                        stats[stat_key] = stats.get(stat_key, 0) + stat_val
            elif val_a != val_b:
                result[f'{self.positive_marker}{key}'] = val_a
                result[f'{self.negative_marker}{key}'] = val_b

        return result, stats

    def compare(self, path_a: str, path_b: str, **kwargs):
        """Core function for comparing JSON files"""
        self.file_a_name = os.path.basename(path_a)
        self.file_b_name = os.path.basename(path_b)

        if not self._validate_paths([path_a, path_b]):
            return

        with open(path_a) as fa, open(path_b) as fb:
            data_a = json.load(fa)
            data_b = json.load(fb)

        diff_result, statistics = self._compare_json_objects(data_a, data_b)

        if not diff_result:
            return

        self.statistics = statistics

        _handler.setFormatter(_pprint_fmt)
        disclaimer = (
            '\n'
            f'Entries from {self.file_a_name} marked with "{self.positive_marker}"\n'
            f'Entries from {self.file_b_name} marked with "{self.negative_marker}"\n'
            '\n'
        )
        _logger.info(disclaimer)
        self._format_diff_output(diff_result)
        _handler.setFormatter(_std_fmt)

    def _generate_level0_summary(self):
        comparison_word = 'more'
        if float(self.change_percent) < 0:
            comparison_word = 'less'

        detail = (
            '\n'
            'Level 0 summary:\n'
            f'\t{self.file_a_name} has {self.change_percent:05.2f}% '
            f'{comparison_word} keys than {self.file_b_name}'
            '\n')
        return detail

    def _generate_level1_summary(self):
        shared = self.statistics.get('shared_keys_count', 0)
        detail = (
            '\n'
            'Level 1 summary:\n'
            f'\tTotal unique keys in {self.file_a_name}: '
            f'{self.total_keys_a}\n'
            f'\tTotal unique keys in {self.file_b_name}: '
            f'{self.total_keys_b}\n'
            f'\tNumber of common keys: {shared}'
            '\n')
        return detail

    def _generate_level2_summary(self):
        lines = []
        header = '\nLevel 2 summary:'
        for level, details in self.statistics.items():
            if not isinstance(level, int):
                continue

            lines.append(f'JSON depth {level} contains:')
            for name, count in details.items():
                if name == 'common':
                    lines.append(f'\t{count} keys present in both files')
                else:
                    lines.append(f'\t{count} exclusive keys in {name}')

        return f'{header}\n\t' + '\n\t'.join(lines)

    def _adjust_detail_level(self, requested_level: int) -> int:
        max_allowed = 2
        try:
            if hasattr(self, 'output_options'):
                try:
                    custom_level = self.output_options.get('detail_level')
                    custom_level = int(custom_level)
                    if not (0 <= custom_level <= max_allowed):
                        raise ValueError('Out of range detail level, valid ranges are: [0, 2]')
                    requested_level = custom_level
                    _logger.info(f'Using custom detail level {requested_level}')
                except Exception as e:
                    _logger.error(f'Invalid custom detail level: {e}. Using default.')
        except:
            _logger.info('No custom detail level specified, using default.')
        return requested_level

    def calculate_percentage_change(self):
        try:
            self.total_keys_a = (
                self.statistics.get(f'total_{self.file_a_name}_keys', 0) +
                self.statistics.get('shared_keys_count', 0))
            self.total_keys_b = (
                self.statistics.get(f'total_{self.file_b_name}_keys', 0) +
                self.statistics.get('shared_keys_count', 0))

            diff = self.total_keys_a - self.total_keys_b
            self.change_percent = (diff / self.total_keys_a) * 100 if self.total_keys_a else 0.0
        except Exception:
            return False
        return True

    def report_statistics(self, changes, detail_level=0):
        if not self.calculate_percentage_change():
            return

        detail_level = self._adjust_detail_level(detail_level)
        output_parts = []

        if detail_level >= 0:
            output_parts.append(self._generate_level0_summary())
        if detail_level >= 1:
            output_parts.append(self._generate_level1_summary())
        if detail_level >= 2:
            output_parts.append(self._generate_level2_summary())

        _handler.setFormatter(_pprint_fmt)
        for part in output_parts:
            _logger.info(part)
        _handler.setFormatter(_pprint_fmt)

