from collections import defaultdict
import enum
from enum import Enum
import importlib.util
import logging
import sys
import tokenize
from tokenize import TokenInfo
from typing import Iterable, List, Optional, Tuple, Union
import attr
from more_itertools import one
from azul import config

log = logging.getLogger(__name__)


@enum.unique
class ImportErrors(Enum):
    same_line = 'AZUL101 more than one symbol imported per line'
    not_joined = 'AZUL102 symbols from the same module imported in separate statements'
    statement_not_ordered = 'AZUL111 import statements are not correctly ordered'
    symbol_not_ordered = 'AZUL112 symbols in from import are not correctly ordered'
    not_wrapped = 'AZUL131 from import lacks parentheses'
    missing_breaks = 'AZUL132 missing newline between parentheses and imported symbols'
    no_trailing_comma = 'AZUL133 symbol in from import lacks trailing comma'
    unresolvable = 'AZUL141 cannot resolve import statement from project root'


@enum.unique
class ModuleOrigin(enum.IntEnum):
    python_runtime = 1
    external_dependency = 2
    internal = 3

    @classmethod
    def determine_origin(cls, mod_name: str) -> 'ModuleOrigin':
        """
        Determine module origin by inspecting its spec.
        Examples:
        >>> ModuleOrigin.determine_origin('sys')
        <ModuleOrigin.python_runtime: 1>
        >>> ModuleOrigin.determine_origin('os')
        <ModuleOrigin.python_runtime: 1>
        >>> ModuleOrigin.determine_origin('boto3')
        <ModuleOrigin.external_dependency: 2>
        >>> ModuleOrigin.determine_origin('azul.indexer')
        <ModuleOrigin.internal: 3>
        >>> ModuleOrigin.determine_origin('lambdas.service')
        <ModuleOrigin.internal: 3>
        """
        try:
            spec = importlib.util.find_spec(mod_name)
        except (ImportError, ValueError):
            raise ImportError(f"Failed to find spec for {mod_name}")

        if spec is None:
            raise ImportError(f"Spec not found for {mod_name}")
        elif spec.origin is None and spec.submodule_search_locations is None:
            assert mod_name in sys.builtin_module_names, f"{mod_name} should be builtin"
            return cls.python_runtime
        else:
            path = (
                one(spec.submodule_search_locations)
                if spec.origin is None
                else spec.origin
            )
            if 'site-packages' in path:
                return cls.external_dependency
            elif path.startswith(config.project_root):
                return cls.internal
            else:
                return cls.python_runtime


EitherImport = Union['ast.Import', 'ast.ImportFrom']


@attr.s(auto_attribs=True, kw_only=True, frozen=True, order=True)
class ImportMetadata:
    origin: ModuleOrigin
    name: str
    is_from_import: bool

    @classmethod
    def extract_info(cls, node: EitherImport) -> Tuple[str, bool]:
        if isinstance(node, ast.Import):
            mod_name = one(node.names).name
            from_import = False
        elif isinstance(node, ast.ImportFrom):
            mod_name = node.module
            from_import = True
        else:
            raise TypeError(f"Unexpected node type: {type(node)}")
        return mod_name, from_import

    @classmethod
    def build(cls, node: EitherImport) -> 'ImportMetadata':
        mod_name, is_from = cls.extract_info(node)
        origin = ModuleOrigin.determine_origin(mod_name)
        return cls(origin=origin, name=mod_name, is_from_import=is_from)


@attr.s(auto_attribs=True, kw_only=True, frozen=True)
class CanonicalImport:
    syntax_node: EitherImport
    metadata: ImportMetadata

    @classmethod
    def construct(cls, node: EitherImport) -> 'CanonicalImport':
        return cls(syntax_node=node, metadata=ImportMetadata.build(node))

    def precedes(self, other: 'CanonicalImport') -> bool:
        return self.syntax_node.lineno <= other.syntax_node.lineno


@attr.s(auto_attribs=True, kw_only=True, frozen=True)
class ViolationRecord:
    line_no: int
    col_offset: int
    message: str

    @classmethod
    def create(cls, node: EitherImport, error_code: ImportErrors) -> 'ViolationRecord':
        return cls(line_no=node.lineno,
                   col_offset=node.col_offset,
                   message=error_code.value)

    def as_flake8(self) -> tuple:
        return *attr.astuple(self), None


class ImportAnalyzer(ast.NodeVisitor):
    tolerated_missing_modules = {
        'pydevd',
        '_typeshed'
    }

    def __init__(self, source_path: str, token_stream: Iterable[TokenInfo]):
        super().__init__()
        self.path = source_path
        self.token_map = defaultdict(list)
        for tok in token_stream:
            self.token_map[tok.start[0]].append(tok)
        # Sort tokens per line by column position
        for line_tokens in self.token_map.values():
            line_tokens.sort(key=lambda t: t.start[1])
        self.violations: List[ViolationRecord] = []
        self.processed_imports: List[CanonicalImport] = []

    def visit_Import(self, node: ast.Import) -> None:
        self._check_single_import_per_line(node)
        self._validate_import_order(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        self._ensure_joined_import(node)
        self._check_parentheses_and_commas(node)
        self._verify_symbol_order(node)
        self._validate_import_order(node)

    def _check_single_import_per_line(self, node: EitherImport) -> None:
        if len(node.names) > 1:
            self._record_violation(node, ImportErrors.same_line)

    def _validate_import_order(self, node: EitherImport) -> None:
        try:
            canonical = CanonicalImport.construct(node)
        except ValueError:
            pass  # Skip malformed imports
        except ImportError as e:
            mod_name, _ = ImportMetadata.extract_info(node)
            if mod_name not in self.tolerated_missing_modules:
                self._record_violation(node, ImportErrors.unresolvable)
        else:
            prev = self._find_previous_import(node)
            next_ = self._find_next_import(node)
            if prev is not None and not self._order_ok(prev, canonical):
                self._record_violation(node, ImportErrors.statement_not_ordered)
            elif next_ is not None and not self._order_ok(canonical, next_):
                self._record_violation(node, ImportErrors.statement_not_ordered)
            self.processed_imports.append(canonical)

    def _ensure_joined_import(self, node: ast.ImportFrom) -> None:
        for seen in self.processed_imports:
            if (
                isinstance(seen.syntax_node, ast.ImportFrom)
                and seen.syntax_node.module == node.module
                and self._same_block(seen.syntax_node, node)
            ):
                self._record_violation(node, ImportErrors.not_joined)
                break

    def _check_parentheses_and_commas(self, node: ast.ImportFrom) -> None:
        start_lines = self._clean_tokens(node.lineno)
        end_lines = self._clean_tokens(node.end_lineno)

        has_open_paren = False
        for tok in start_lines:
            if tok.string == '(':
                has_open_paren = True
                if len(start_lines) > 1 or len(end_lines) > 1:
                    self._record_violation(node, ImportErrors.missing_breaks)
                break

        if not has_open_paren:
            self._record_violation(node, ImportErrors.not_wrapped)

        for line_num in range(node.lineno + 1, node.end_lineno):
            tokens = self._clean_tokens(line_num)
            if not tokens:
                continue
            elif len(tokens) > 2 and (tokens[1].string != 'as' or len(tokens) > 4):
                self._record_violation(node, ImportErrors.same_line)
            elif tokens[-1].string != ',':
                self._record_violation(node, ImportErrors.no_trailing_comma)

    def _verify_symbol_order(self, node: ast.ImportFrom) -> None:
        aliases = node.names
        for i in range(len(aliases) - 1):
            if aliases[i].name > aliases[i + 1].name:
                self._record_violation(node, ImportErrors.symbol_not_ordered)

    def _record_violation(self, node: EitherImport, err: ImportErrors) -> None:
        self.violations.append(ViolationRecord.create(node, err))

    def _order_ok(self, imp1: CanonicalImport, imp2: CanonicalImport) -> bool:
        return imp1.precedes(imp2) or not self._same_block(imp1.syntax_node, imp2.syntax_node)

    def _same_block(self, n1: EitherImport, n2: EitherImport) -> bool:
        if n1.col_offset != n2.col_offset:
            return False
        first, second = sorted([n1, n2], key=lambda x: x.lineno)
        for ln in range(first.lineno + 1, second.lineno):
            tokens = self._clean_tokens(ln)
            if tokens and tokens[0].start[1] < first.col_offset:
                return False
        return True

    def _find_previous_import(self, node: EitherImport) -> Optional[CanonicalImport]:
        best = None
        for candidate in self.processed_imports:
            if candidate.syntax_node.lineno < node.lineno:
                if best is None or candidate.syntax_node.lineno > best.syntax_node.lineno:
                    best = candidate
        return best

    def _find_next_import(self, node: EitherImport) -> Optional[CanonicalImport]:
        best = None
        for candidate in self.processed_imports:
            if candidate.syntax_node.lineno > node.lineno:
                if best is None or candidate.syntax_node.lineno < best.syntax_node.lineno:
                    best = candidate
        return best

    def _clean_tokens(self, line_no: int) -> List[TokenInfo]:
        return [
            t for t in self.token_map[line_no]
            if t.type not in (tokenize.COMMENT, tokenize.NEWLINE, tokenize.NL, tokenize.ENDMARKER)
        ]


class AzulImports:
    name = 'azul_imports'
    version = 1.0

    def __init__(self, tree, file_tokens, filename):
        self.tree = tree
        self.tokens = file_tokens
        self.filename = filename

    def _execute(self) -> List[ViolationRecord]:
        analyzer = ImportAnalyzer(self.filename, self.tokens)
        analyzer.visit(self.tree)
        return analyzer.violations

    def execute(self) -> List[tuple]:
        return [v.as_flake8() for v in self._execute()]

from .errors import ConfigurationError
from docker.utils.ports import build_port_bindings

class ServicePort(namedtuple('_ServicePort', 'target published protocol mode external_ip')):
    def __new__(cls, target, published, *args, **kwargs):
        # Validate and convert target port
        if target is not None:
            try:
                target = int(target)
            except (ValueError, TypeError):
                raise ConfigurationError('Invalid target port: {}'.format(target))

        # Validate and convert published port
        if published is not None:
            if isinstance(published, str) and '-' in published:
                # Handle range format like "x-y:z"
                parts = published.split('-', 1)
                if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit():
                    raise ConfigurationError('Invalid published port: {}'.format(published))
            else:
                try:
                    published = int(published)
                except (ValueError, TypeError):
                    raise ConfigurationError('Invalid published port: {}'.format(published))

        return super().__new__(cls, target, published, *args, **kwargs)

    @classmethod
    def parse(cls, spec):
        # If already a ServicePort instance, return as list
        if isinstance(spec, cls):
            return [spec]

        # Handle non-dict specifications (string/list formats)
        if not isinstance(spec, dict):
            result_ports = []
            try:
                for key, values in build_port_bindings([spec]).items():
                    # Split protocol if present
                    if '/' in key:
                        target_port, proto = key.split('/', 1)
                    else:
                        target_port, proto = (key, None)

                    # Process each binding
                    for binding in values:
                        if binding is None:
                            result_ports.append(cls(target_port, None, proto, None, None))
                        elif isinstance(binding, tuple):
                            result_ports.append(cls(target_port, binding[1], proto, None, binding[0]))
                        else:
                            result_ports.append(cls(target_port, binding, proto, None, None))
            except ValueError as err:
                raise ConfigurationError(str(err))
            return result_ports

        # Handle dictionary specification
        return [cls(
            spec.get('target'),
            spec.get('published'),
            spec.get('protocol'),
            spec.get('mode'),
            None
        )]

    @property
    def merge_field(self):
        return (self.target, self.published, self.external_ip, self.protocol)

    def to_dict(self):
        # Create dictionary representation excluding None values
        return {
            field_name: value 
            for field_name, value in zip(self._fields, self) 
            if value is not None
        }

    def legacy_format(self):
        return normalize_port_dict(self.to_dict())

def normalize_port_dict(port_info):
    # Build standardized string representation of port mapping
    ext_ip = port_info.get('external_ip', '')
    has_ext = ':' if ext_ip else ''
    pub = port_info.get('published', '')
    has_pub = ':' if pub or ext_ip else ''

    return '{ext_ip}{has_ext}{pub}{has_pub}{target}/{proto}'.format(
        ext_ip=ext_ip,
        has_ext=has_ext,
        pub=pub,
        has_pub=has_pub,
        target=port_info.get('target'),
        proto=port_info.get('protocol', 'tcp')
    )

