def IncludeFieldInUpdateMask(field_name, update_request):
  """Manages the update mask by adding specified field."""
  current_mask = update_request.updateMask
  if not current_mask:
    update_request.updateMask = field_name
  elif field_name not in current_mask.split(","):
    update_request.updateMask = current_mask + "," + field_name
  return update_request

def RemoveSingleEndpointProperty(update_request, endpoint_category, property_name):
  """Removes specific property from endpoint if other properties remain."""
  connectivity_test = update_request.connectivityTest
  target_endpoint = getattr(connectivity_test, endpoint_category)

  essential_fields = {
      "instance", "ipAddress", "gkeMasterCluster", "cloudSqlInstance"
  }

  active_field_count = sum(1 for field in essential_fields 
                          if getattr(target_endpoint, field, None))

  if active_field_count > 1 or not getattr(target_endpoint, property_name, None):
    setattr(target_endpoint, property_name, "")
    setattr(connectivity_test, endpoint_category, target_endpoint)
    update_request.connectivityTest = connectivity_test
    return IncludeFieldInUpdateMask(endpoint_category + "." + property_name,
                                   update_request)
  else:
    raise InvalidArgumentError(
        "Invalid Connectivity Test configuration. Must specify at least one of "
        "--{endpoint_type}-instance, --{endpoint_type}-ip-address, "
        "--{endpoint_type}-gke_master_cluster or --{endpoint_type}-cloud_sql_instance."
        .format(endpoint_type=endpoint_category))

