from aioairzone.common import ConnectionOptions as AirzoneConnection
from aioairzone.exceptions import InvalidHost as InvalidAirzoneHost
from aioairzone.localapi_device import AirzoneLocalApi as LocalAirzoneDevice
from aiohttp.client_exceptions import ClientConnectorError as HttpConnectError

import voluptuous as vol
from homeassistant import config_entries
from homeassistant.const import CONF_HOST, CONF_PORT
from homeassistant.data_entry_flow import FlowResult
from homeassistant.helpers import aiohttp_client
from .const import DEFAULT_LOCAL_API_PORT as DEFAULT_PORT, DOMAIN


class AirzoneConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):
    """Handle configuration flow for Airzone local API devices."""

    async def async_step_user(
        self, user_input: dict[str, Any] | None = None
    ) -> FlowResult:
        """Process the initial user input step."""
        validation_errors = {}

        if user_input is not None:
            # Check for existing entries with same host and port
            self._async_abort_entries_match({
                CONF_HOST: user_input[CONF_HOST],
                CONF_PORT: user_input[CONF_PORT],
            })

            try:
                # Create client session and device instance
                http_session = aiohttp_client.async_get_clientsession(self.hass)
                airzone_options = AirzoneConnection(
                    user_input[CONF_HOST],
                    user_input[CONF_PORT],
                )
                device_instance = LocalAirzoneDevice(http_session, airzone_options)

                # Validate connection to Airzone system
                await device_instance.validate_airzone()
            except (HttpConnectError, InvalidAirzoneHost):
                validation_errors["base"] = "cannot_connect"
            else:
                # Success: create entry with formatted title
                device_title = f"Airzone {user_input[CONF_HOST]}:{user_input[CONF_PORT]}"
                return self.async_create_entry(title=device_title, data=user_input)

        # Render form with schema on initial load or error
        return self.async_show_form(
            step_id="user",
            data_schema=vol.Schema({
                vol.Required(CONF_HOST): str,
                vol.Required(CONF_PORT, default=DEFAULT_PORT): int,
            }),
            errors=validation_errors,
        )

import abc
import vim
import logging
from functools import partial
import typing
from vimspector import utils

class ExpandableBase:
  STATE_USER_EXPANDED = 2
  STATE_AUTO_EXPANDED = 1
  STATE_USER_COLLAPSED = 0
  STATE_DEFAULT_COLLAPSED = None

  def __init__( self ):
    self._variables_list: typing.List[ 'VariableBase' ] = None
    self._expansion_state = ExpandableBase.STATE_DEFAULT_COLLAPSED

  def IsCurrentlyExpanded( self ):
    return bool( self._expansion_state )

  def ShouldShowChildren( self ):
    return self.IsCurrentlyExpanded() and self._variables_list is not None

  def CanBeExpanded( self ):
    return self.GetReferenceId() > 0

  @abc.abstractmethod
  def GetReferenceId( self ):
    raise NotImplementedError()

class ScopeData( ExpandableBase ):
  def __init__( self, scope_data: dict ):
    super().__init__()
    self._scope_data = scope_data

  def GetReferenceId( self ):
    return self._scope_data.get( 'variablesReference', 0 )

  def UpdateScope( self, new_scope ):
    self._scope_data = new_scope

class WatchExpressionResult( ExpandableBase ):
  def __init__( self, result_data: dict ):
    super().__init__()
    self._result_data = result_data
    self._has_changed = True

  def GetReferenceId( self ):
    return self._result_data.get( 'variablesReference', 0 )

  def UpdateResult( self, new_result ):
    self._has_changed = False
    if self._result_data.get( 'result' ) != new_result.get( 'result' ):
      self._has_changed = True
    self._result_data = new_result

class FailedWatch( WatchExpressionResult ):
  def __init__( self, reason ):
    super().__init__( { 'result': reason } )
    self._has_changed = True

class VariableNode( ExpandableBase ):
  def __init__( self, variable_data: dict ):
    super().__init__()
    self._variable_data = variable_data
    self._has_changed = True

  def GetReferenceId( self ):
    return self._variable_data.get( 'variablesReference', 0 )

  def UpdateVariable( self, new_variable ):
    self._has_changed = False
    if self._variable_data.get( 'value' ) != new_variable.get( 'value' ):
      self._has_changed = True
    self._variable_data = new_variable

class UserWatch:
  def __init__( self, expression_data: dict ):
    self._watch_result = None
    self._line_number = None
    self._expression_data = expression_data

class ViewBuffer:
  line_map: typing.Dict[ int, ExpandableBase ]
  render_func: typing.Callable

  def __init__( self, window, lines_dict, draw_function ):
    self.line_map = lines_dict
    self.render_func = draw_function
    self.buffer = window.buffer
    utils.SetUpUIWindow( window )

class VariablesDisplayManager( object ):
  def __init__( self, variables_window, watches_window ):
    self._logger = logging.getLogger( __name__ )
    utils.SetUpLogging( self._logger )
    self._debug_connection = None
    self._current_syntax = ''

    def setup_keybindings():
      vim.command( 'nnoremap <silent> <buffer> <CR> '
                   ':<C-u>call vimspector#ExpandVariable()<CR>' )
      vim.command( 'nnoremap <silent> <buffer> <2-LeftMouse> '
                   ':<C-u>call vimspector#ExpandVariable()<CR>' )

    # Setup variables buffer
    self._scopes_list: typing.List[ ScopeData ] = []
    self._variables_view = ViewBuffer( variables_window, {}, self._RenderScopes )
    utils.SetUpHiddenBuffer( self._variables_view.buffer, 'vimspector.Variables' )
    with utils.LetCurrentWindow( variables_window ):
      setup_keybindings()

    # Setup watches buffer
    self._user_watches: typing.List[ UserWatch ] = []
    self._watches_view = ViewBuffer( watches_window, {}, self._RenderWatches )
    utils.SetUpPromptBuffer( self._watches_view.buffer,
                             'vimspector.Watches',
                             'Expression: ',
                             'vimspector#AddWatchPrompt',
                             'vimspector#OmniFuncWatch' )
    with utils.LetCurrentWindow( watches_window ):
      setup_keybindings()
      vim.command(
        'nnoremap <buffer> <DEL> :call vimspector#DeleteWatch()<CR>' )
      if utils.UseWinBar():
        vim.command( 'nnoremenu 1.1 WinBar.New '
                     ':call vimspector#AddWatch()<CR>' )
        vim.command( 'nnoremenu 1.2 WinBar.Expand/Collapse '
                     ':call vimspector#ExpandVariable()<CR>' )
        vim.command( 'nnoremenu 1.3 WinBar.Delete '
                     ':call vimspector#DeleteWatch()<CR>' )

    # Configure balloon display if supported
    has_balloon      = int( vim.eval( "has( 'balloon_eval' )" ) )
    has_balloon_term = int( vim.eval( "has( 'balloon_eval_term' )" ) )
    self._saved_options = {}
    if has_balloon or has_balloon_term:
      self._saved_options = {
        'balloonexpr': vim.options[ 'balloonexpr' ],
        'balloondelay': vim.options[ 'balloondelay' ],
      }
      vim.options[ 'balloonexpr' ] = 'vimspector#internal#balloon#BalloonExpr()'
      vim.options[ 'balloondelay' ] = 250
    if has_balloon:
      self._saved_options[ 'ballooneval' ] = vim.options[ 'ballooneval' ]
      vim.options[ 'ballooneval' ] = True
    if has_balloon_term:
      self._saved_options[ 'balloonevalterm' ] = vim.options[ 'balloonevalterm' ]
      vim.options[ 'balloonevalterm' ] = True
    self._is_terminal_mode = not bool( int( vim.eval( "has( 'gui_running' )" ) ) )

  def ClearDisplay( self ):
    with utils.ModifiableScratchBuffer( self._variables_view.buffer ):
      utils.ClearBuffer( self._variables_view.buffer )
    with utils.ModifiableScratchBuffer( self._watches_view.buffer ):
      utils.ClearBuffer( self._watches_view.buffer )
    self._current_syntax = ''

  def ActivateConnection( self, connection ):
    self._debug_connection = connection

  def DeactivateConnection( self ):
    self.ClearDisplay()
    self._debug_connection = None

  def Cleanup( self ):
    for key, value in self._saved_options.items():
      vim.options[ key ] = value
    utils.CleanUpHiddenBuffer( self._variables_view.buffer )
    utils.CleanUpHiddenBuffer( self._watches_view.buffer )

  def LoadScopes( self, frame ):
    def process_scopes( message ):
      updated_scopes = []
      expanded_any_scope = False
      for scope_body in message[ 'body' ][ 'scopes' ]:
        existing_scope = None
        for s in self._scopes_list:
          if s._scope_data[ 'name' ] == scope_body[ 'name' ]:
            existing_scope = s
            break

        if existing_scope is None:
          current_scope = ScopeData( scope_body )
        else:
          current_scope = existing_scope
          current_scope.UpdateScope( scope_body )

        updated_scopes.append( current_scope )

        # Auto-expand first non-expensive scope unless user collapsed it
        if ( not expanded_any_scope
             and not current_scope._scope_data.get( 'expensive' )
             and current_scope._expansion_state is not ExpandableBase.STATE_USER_COLLAPSED ):
          current_scope._expansion_state = ExpandableBase.STATE_AUTO_EXPANDED
          expanded_any_scope = True
        elif ( expanded_any_scope and current_scope._expansion_state ==
               ExpandableBase.STATE_AUTO_EXPANDED ):
          current_scope._expansion_state = ExpandableBase.STATE_DEFAULT_COLLAPSED

        if current_scope.IsCurrentlyExpanded():
          self._debug_connection.DoRequest( partial( self._ProcessVariables,
                                                     self._RenderScopes,
                                                     current_scope ), {
            'command': 'variables',
            'arguments': {
              'variablesReference': current_scope.GetReferenceId(),
            },
          } )
      self._scopes_list = updated_scopes
      self._RenderScopes()
    self._debug_connection.DoRequest( process_scopes, {
      'command': 'scopes',
      'arguments': {
        'frameId': frame[ 'id' ]
      },
    } )

  def AddUserWatch( self, frame, expression ):
    watch_entry = {
      'expression': expression,
      'context': 'watch',
    }
    if frame:
      watch_entry[ 'frameId' ] = frame[ 'id' ]
    self._user_watches.append( UserWatch( watch_entry ) )
    self.EvaluateAllWatches()

  def RemoveWatch( self ):
    if vim.current.buffer != self._watches_view.buffer:
      utils.UserMessage( 'Not a watch buffer' )
      return
    current_line = vim.current.window.cursor[ 0 ]
    best_match_index = -1
    for idx, watch in enumerate( self._user_watches ):
      if ( watch._line_number is not None
           and watch._line_number <= current_line
           and watch._line_number > best_match_index ):
        best_match_index = idx

    if best_match_index >= 0:
      del self._user_watches[ best_match_index ]
      utils.UserMessage( 'Deleted' )
      self._RenderWatches()
      return
    utils.UserMessage( 'No watch found' )

  def EvaluateAllWatches( self ):
    for watch in self._user_watches:
      self._debug_connection.DoRequest(
        partial( self._UpdateWatchValue, watch ),
        {
          'command': 'evaluate',
          'arguments': watch._expression_data,
        },
        failure_handler = lambda reason, msg, watch=watch:
            self._HandleWatchFailure( reason, watch ) )

  def _UpdateWatchValue( self, watch: UserWatch, message: dict ):
    if watch._watch_result is not None:
      watch._watch_result.UpdateResult( message[ 'body' ] )
    else:
      watch._watch_result = WatchExpressionResult( message[ 'body' ] )
    if ( watch._watch_result.CanBeExpanded() and
         watch._watch_result.IsCurrentlyExpanded() ):
      self._debug_connection.DoRequest( partial( self._ProcessVariables,
                                                 self._watches_view.render_func,
                                                 watch._watch_result ), {
        'command': 'variables',
        'arguments': {
          'variablesReference': watch._watch_result.GetReferenceId(),
        },
      } )
    self._RenderWatches()

  def _HandleWatchFailure( self, reason: str, watch: UserWatch ):
    if watch._watch_result is not None:
      return
    watch._watch_result = FailedWatch( reason )
    self._RenderWatches()

  def ToggleVariableExpansion( self ):
    if vim.current.buffer == self._variables_view.buffer:
      target_view = self._variables_view
    elif vim.current.buffer == self._watches_view.buffer:
      target_view = self._watches_view
    else:
      return

    current_line = vim.current.window.cursor[ 0 ]
    if current_line not in target_view.line_map:
      return

    node = target_view.line_map[ current_line ]
    if node.IsCurrentlyExpanded():
      node._expansion_state = ExpandableBase.STATE_USER_COLLAPSED
      target_view.render_func()
      return
    if not node.CanBeExpanded():
      return
    node._expansion_state = ExpandableBase.STATE_USER_EXPANDED
    self._debug_connection.DoRequest( partial( self._ProcessVariables,
                                               target_view.render_func,
                                               node ), {
      'command': 'variables',
      'arguments': {
        'variablesReference': node.GetReferenceId()
      },
    } )

  def _RenderVariableList( self, view, variables, indent_level ):
    assert indent_level > 0
    for var_node in variables:
      line = utils.AppendToBuffer(
        view.buffer,
        '{indent}{marker}{icon} {name} ({type_}): {value}'.format(
          indent = ' ' * ( indent_level - 1 ),
          marker = '*' if var_node._has_changed else ' ',
          icon = '+' if ( var_node.CanBeExpanded()
                          and not var_node.IsCurrentlyExpanded() ) else '-',
          name = var_node._variable_data[ 'name' ],
          type_ = var_node._variable_data.get( 'type', '' ),
          value = var_node._variable_data.get( 'value',
                                         '<unknown>' ) ).split( '\n' ) )
      view.line_map[ line ] = var_node
      if var_node.ShouldShowChildren():
        self._RenderVariableList( view, var_node._variables_list, indent_level + 2 )

  def _RenderScopes( self ):
    self._variables_view.line_map.clear()
    with utils.RestoreCursorPosition():
      with utils.ModifiableScratchBuffer( self._variables_view.buffer ):
        utils.ClearBuffer( self._variables_view.buffer )
        for scope in self._scopes_list:
          self._RenderSingleScope( 0, scope )

  def _RenderWatches( self ):
    self._watches_view.line_map.clear()
    with utils.RestoreCursorPosition():
      with utils.ModifiableScratchBuffer( self._watches_view.buffer ):
        utils.ClearBuffer( self._watches_view.buffer )
        utils.AppendToBuffer( self._watches_view.buffer, 'Watches: ----' )
        for watch in self._user_watches:
          line = utils.AppendToBuffer( self._watches_view.buffer,
                                       'Expression: '
                                       + watch._expression_data[ 'expression' ] )
          watch._line_number = line
          self._RenderWatchResult( 2, watch )

  def _RenderSingleScope( self, indent, scope ):
    icon = '+' if scope.CanBeExpanded() and not scope.IsCurrentlyExpanded() else '-'
    line = utils.AppendToBuffer( self._variables_view.buffer,
                                 '{0}{1} Scope: {2}'.format(
                                   ' ' * indent,
                                   icon,
                                   scope._scope_data[ 'name' ] ) )
    self._variables_view.line_map[ line ] = scope
    if scope.ShouldShowChildren():
      indent += 2
      self._RenderVariableList( self._variables_view, scope._variables_list, indent )

  def _RenderWatchResult( self, indent, watch ):
    if not watch._watch_result:
      return
    assert indent > 0
    icon = '+' if ( watch._watch_result.CanBeExpanded() and
                    not watch._watch_result.IsCurrentlyExpanded() ) else '-'
    line =  '{indent}{marker}{icon} Result: {result}'.format(
      indent = ' ' * ( indent - 1 ),
      marker = '*' if watch._watch_result._has_changed else ' ',
      icon = icon,
      result = watch._watch_result._result_data.get( 'result', '<unknown>' ) )
    line = utils.AppendToBuffer( self._watches_view.buffer, line.split( '\n' ) )
    self._watches_view.line_map[ line ] = watch._watch_result
    if watch._watch_result.ShouldShowChildren():
      indent = 4
      self._RenderVariableList( self._watches_view, watch._watch_result._variables_list, indent )

  def _ProcessVariables( self, draw_callback, parent_node, message ):
    new_variables = []
    for variable_body in message[ 'body' ][ 'variables' ]:
      if parent_node._variables_list is None:
        parent_node._variables_list = []

      existing_var = None
      for v in parent_node._variables_list:
        if v._variable_data[ 'name' ] == variable_body[ 'name' ]:
          existing_var = v
          break

      if existing_var is None:
        var_node = VariableNode( variable_body )
      else:
        var_node = existing_var
        var_node.UpdateVariable( variable_body )

      new_variables.append( var_node )

      if var_node.CanBeExpanded() and var_node.IsCurrentlyExpanded():
        self._debug_connection.DoRequest( partial( self._ProcessVariables,
                                                   draw_callback,
                                                   var_node ), {
          'command': 'variables',
          'arguments': {
            'variablesReference': var_node.GetReferenceId()
          },
        } )
    parent_node._variables_list = new_variables
    draw_callback()

  def ShowHoverInfo( self, frame, expression ):
    if not self._debug_connection:
      return ''

    def handle_response( message ):
      body = message[ 'body' ]
      result = body[ 'result' ]
      if result is None:
        result = 'null'
      display_info = [
        'Type: ' + body.get( 'type', '<unknown>' ),
        'Value: ' + result
      ]
      utils.DisplayBaloon( self._is_terminal_mode, display_info )

    def handle_error( reason, message ):
      display_info = [ reason ]
      utils.DisplayBaloon( self._is_terminal_mode, display_info )

    self._debug_connection.DoRequest( handle_response, {
      'command': 'evaluate',
      'arguments': {
        'expression': expression,
        'frameId': frame[ 'id' ],
        'context': 'hover',
      }
    }, handle_error )
    return '...'

  def ApplySyntaxHighlighting( self, syntax_name ):
    self._current_syntax = utils.SetSyntax( self._current_syntax,
                                            syntax_name,
                                            self._variables_view.buffer,
                                            self._watches_view.buffer )

import time

# Custom exception hierarchy for Telegram API errors
class TelegramAPIError(Exception):
    def __init__(self, message=None):
        cleaned_msg = self._clean_message(message)
        super(TelegramAPIError, self).__init__(cleaned_msg)

    @staticmethod
    def _clean_message(text):
        prefixes = ['error: ', '[error]: ', 'bad request: ', 'conflict: ', 'not found: ']
        for prefix in prefixes:
            if text and text.startswith(prefix):
                text = text[len(prefix):]
                break
        return text.strip().capitalize() if text else ''

