SUBLIME_WORD_MASK = 515

def get_document_position(view: sublime.View, point=None) -> 'Optional[OrderedDict]':
    file_path = view.file_name()
    if file_path:
        position = point or view.sel()[0].begin()
        doc_pos = OrderedDict()  # type: OrderedDict[str, Any]
        doc_pos['textDocument'] = {"uri": filename_to_uri(file_path)}
        doc_pos['position'] = offset_to_point(view, position).to_lsp()
        return doc_pos
    return None

def get_cursor_position(view: sublime.View, event_data=None) -> int:
    if event_data:
        return view.window_to_text((event_data["x"], event_data["y"]))
    else:
        return view.sel()[0].begin()

def is_cursor_on_word(view: sublime.View, event_data) -> bool:
    cursor_pos = get_cursor_position(view, event_data)
    classification = view.classify(cursor_pos)
    return bool(classification & SUBLIME_WORD_MASK)

# Global document state tracking (per-window)
document_states = {}  # type: Dict[int, Dict[str, DocumentState]]

class DocumentState:
    """Tracks version information for documents managed by language services"""
    def __init__(self, path: str) -> None:
        self.path = path
        self.version_number = 0
        self.language_identifier = None

    def increment_version(self) -> int:
        self.version_number += 1
        return self.version_number

def retrieve_document_state(window: sublime.Window, path: str) -> DocumentState:
    window_id = window.id()
    window_states = document_states.setdefault(window_id, {})
    if path not in window_states:
        window_states[path] = DocumentState(path)
    return window_states[path]

def has_document_state(window: sublime.Window, path: str) -> bool:
    window_id = window.id()
    return window_id in document_states and path in document_states[window_id]

def remove_document_state(window: sublime.Window, path: str) -> None:
    window_id = window.id()
    if window_id in document_states and path in document_states[window_id]:
        del document_states[window_id][path]

def clear_all_document_states(window: sublime.Window) -> None:
    window_id = window.id()
    if window_id in document_states:
        del document_states[window_id]

pending_buffer_updates = dict()  # type: Dict[int, Dict]

def schedule_did_change(view: sublime.View) -> None:
    buffer_id = view.buffer_id()
    current_version = 1
    existing_update = None

    if buffer_id in pending_buffer_updates:
        existing_update = pending_buffer_updates[buffer_id]
        current_version = existing_update["version"] + 1
        existing_update["version"] = current_version
    else:
        pending_buffer_updates[buffer_id] = {
            "view": view,
            "version": current_version
        }

    sublime.set_timeout_async(
        lambda: process_did_change(buffer_id, current_version), 500)

def process_did_change(buffer_id: int, target_version=None) -> None:
    if buffer_id not in pending_buffer_updates:
        return

    update_info = pending_buffer_updates.get(buffer_id)
    if update_info:
        if target_version is None or target_version == update_info["version"]:
            send_did_change_notification(update_info["view"])

def send_did_open_notification(view: sublime.View) -> None:
    config = config_for_scope(view)
    client = client_for_view(view)

    if client and config:
        view.settings().set("show_definitions", False)
        window = view.window()
        file_path = view.file_name()

        if window and file_path:
            if not has_document_state(window, file_path):
                ds = retrieve_document_state(window, file_path)
                ds.language_identifier = config.get_language_id(view)

                if settings.show_view_status:
                    view.set_status("code_intel_clients", config.name)

                params = {
                    "textDocument": {
                        "uri": filename_to_uri(file_path),
                        "languageId": ds.language_identifier,
                        "text": view.substr(sublime.Region(0, view.size())),
                        "version": ds.version_number
                    }
                }
                client.send_notification(Notification.didOpen(params))

def send_did_close_notification(view: sublime.View) -> None:
    file_path = view.file_name()
    window = sublime.active_window()

    if window and file_path:
        if has_document_state(window, file_path):
            remove_document_state(window, file_path)
            client = client_for_closed_view(view)
            if client:
                params = {"textDocument": {"uri": filename_to_uri(file_path)}}
                client.send_notification(Notification.didClose(params))

def send_did_save_notification(view: sublime.View) -> None:
    file_path = view.file_name()
    window = view.window()

    if window and file_path:
        if has_document_state(window, file_path):
            client = client_for_view(view)
            if client:
                params = {"textDocument": {"uri": filename_to_uri(file_path)}}
                client.send_notification(Notification.didSave(params))
        else:
            debug('document not tracked', file_path)

def send_did_change_notification(view: sublime.View) -> None:
    file_path = view.file_name()
    window = view.window()

    if window and file_path:
        if view.buffer_id() in pending_buffer_updates:
            del pending_buffer_updates[view.buffer_id()]

        config = config_for_scope(view)
        client = client_for_view(view)

        if client and config:
            uri = filename_to_uri(file_path)
            language_id = config.get_language_id(view)
            ds = retrieve_document_state(window, file_path)

            if ds.language_identifier == language_id:
                params = {
                    "textDocument": {
                        "uri": uri,
                        "version": ds.increment_version(),
                    },
                    "contentChanges": [{
                        "text": view.substr(sublime.Region(0, view.size()))
                    }]
                }
                client.send_notification(Notification.didChange(params))
            else:
                # Language ID changed - simulate reopening
                ds.language_identifier = language_id
                params = {"textDocument": {"uri": uri}}
                client.send_notification(Notification.didClose(params))

                params = {
                    "textDocument": {
                        "uri": uri,
                        "languageId": ds.language_identifier,
                        "text": view.substr(sublime.Region(0, view.size())),
                        "version": ds.increment_version(),
                    }
                }
                client.send_notification(Notification.didOpen(params))

document_sync_initialized = False

class ViewCloseHandler(sublime_plugin.EventListener):
    def on_close(self, view):
        if is_supported_syntax(view.settings().get("syntax")):
            Events.publish("view.on_close", view)
        sublime.set_timeout_async(check_window_unloaded, 500)

class ViewSaveHandler(sublime_plugin.EventListener):
    def on_post_save_async(self, view):
        if is_supported_view(view):
            Events.publish("view.on_post_save_async", view)

def is_transient_view(view: sublime.View) -> bool:
    window = view.window()
    if window:
        if window.get_view_index(view)[1] == -1:
            return True  # Quick panel transient views
        return view == window.transient_view_in_group(window.active_group())
    return True

class DocumentSyncHandler(sublime_plugin.ViewEventListener):
    def __init__(self, view):
        self.view = view

    @classmethod
    def is_applicable(cls, settings):
        syntax = settings.get('syntax')
        # Enables document sync for any supportable syntax
        # Consider adding a detect_lsp_support setting for performance
        return syntax and (is_supported_syntax(syntax) or is_supportable_syntax(syntax))

    @classmethod
    def applies_to_primary_view_only(cls):
        return False

    def on_load_async(self):
        if not is_transient_view(self.view):
            Events.publish("view.on_load_async", self.view)

    def on_modified(self):
        if self.view.file_name():
            Events.publish("view.on_modified", self.view)

    def on_activated_async(self):
        if self.view.file_name() and not is_transient_view(self.view):
            Events.publish("view.on_activated_async", self.view)

def initialize_document_sync(text_document_sync_kind):
    global document_sync_initialized
    if document_sync_initialized:
        return

    document_sync_initialized = True

    # Hook up events per scope/client
    Events.subscribe('view.on_load_async', send_did_open_notification)
    Events.subscribe('view.on_activated_async', send_did_open_notification)
    Events.subscribe('view.on_modified', schedule_did_change)
    Events.subscribe('view.on_post_save_async', send_did_save_notification)
    Events.subscribe('view.on_close', send_did_close_notification)

from typing import List, Set

class TCPConnection(object):
    """
    Represents a TCP connection extracted from a network trace.
    Identified uniquely by the 4-tuple: (src_ip, src_port, dst_ip, dst_port).
    """
    def __init__(self,
                 src_ip: str,
                 dst_ip: str,
                 src_port: int,
                 dst_port: int) -> None:
        self.src_ip: str = src_ip
        self.dst_ip: str = dst_ip
        self.src_port: int = src_port
        self.dst_port: int = dst_port
        self.first_seen: float = float("inf")
        self.last_seen: float = -float("inf")
        self.syn_count: int = 0
        self.ack_count: int = 0
        self.fin_count: int = 0
        self.rst_count: int = 0
        self.packets_fwd: int = 0
        self.packets_bwd: int = 0
        self.bytes_fwd: int = 0
        self.bytes_bwd: int = 0
        self.rtt_samples: List[float] = []
        self.win_sizes: List[int] = []

    def __eq__(self, other) -> bool:
        if not isinstance(other, self.__class__):
            return False

        # Compare IP addresses regardless of direction
        ip_pair_self = {self.src_ip, self.dst_ip}
        ip_pair_other = {other.src_ip, other.dst_ip}

        # Compare port numbers regardless of direction
        port_pair_self = {self.src_port, self.dst_port}
        port_pair_other = {other.src_port, other.dst_port}

        return ip_pair_self == ip_pair_other and port_pair_self == port_pair_other

    def __hash__(self) -> int:
        # Combine hashes using XOR to maintain uniqueness while being order-independent for IPs/ports
        return hash(self.src_ip) ^ hash(self.dst_ip) ^ hash(self.src_port) ^ hash(self.dst_port)

    @property
    def duration(self) -> float:
        """Duration of the connection in seconds."""
        return self.last_seen - self.first_seen

    @property
    def state(self) -> str:
        """Connection state represented as SYN/FIN counts."""
        return f"S{self.syn_count}F{self.fin_count}"

    @property
    def is_established(self) -> bool:
        """True if connection was successfully established (SYN+ACK received)."""
        return self.syn_count > 0 and self.ack_count > 0

    @property
    def total_packets(self) -> int:
        """Total number of packets in both directions."""
        return self.packets_fwd + self.packets_bwd

    @property
    def total_bytes(self) -> int:
        """Total number of bytes transferred in both directions."""
        return self.bytes_fwd + self.bytes_bwd

class GeeTestTask(UserAgent, Proxy):
    def __init__(self, api_key):
        super(GeeTestTask, self).__init__(api_key)

    def create_task(self, site_url: str, gt_token: str, challenge_code: str,
                    api_domain: str = None, lib_version: str = None):
        payload = {
            "clientKey": self._client_key,
            "task": {
                "type": "GeeTestTask",
                "websiteURL": site_url,
                "gt": gt_token,
                "challenge": challenge_code
            }
        }

        # Add user agent information if available
        payload, has_user_agent = self._add_user_agent(payload)

        # Handle proxy configuration if needed
        payload, uses_proxy = self._is_proxy_task(payload)

        # Conditionally add optional parameters
        if api_domain:
            payload["task"]["geetestApiServerSubdomain"] = api_domain
        if lib_version:
            payload["task"]["geetestGetLib"] = lib_version

        # Send request and extract task ID
        response = self._make_request("createTask", payload)
        return response.get("taskId")

from .schema import CreateWorkspaceInput, CreateWorkspaceOutput, Component, Input, Output
# Custom imports below
from komand.exceptions import PluginException

class CreateWorkspace(komand.Action):
    def __init__(self):
        super(self.__class__, self).__init__(
            name='create_workspace',
            description=Component.DESCRIPTION,
            input=CreateWorkspaceInput(),
            output=CreateWorkspaceOutput()
        )

    def run(self, params=None):
        if params is None:
            params = {}

        # Extract input parameters
        directory_id = params.get(Input.DIRECTORY_ID)
        username = params.get(Input.USERNAME)
        bundle_id = params.get(Input.BUNDLE_ID)
        volume_encryption_key = params.get(Input.VOLUME_ENCRYPTION_KEY)
        user_volume_encryption_enabled = params.get(Input.USER_VOLUME_ENCRYPTION_ENABLED)
        root_volume_encryption_enabled = params.get(Input.ROOT_VOLUME_ENCRYPTION_ENABLED)
        workspace_properties = params.get(Input.WORKSPACE_PROPERTIES)
        tags = params.get(Input.TAGS)

        # Prepare payload for API request
        workspace_payload = {
            'DirectoryId': directory_id,
            'UserName': username,
            'BundleId': bundle_id,
            'Tags': tags,
            'WorkspaceProperties': {
                'ComputeTypeName': workspace_properties['compute_type_name'],
                'RootVolumeSizeGib': workspace_properties['root_volume_size'],
                'RunningMode': workspace_properties['running_mode'],
                'RunningModeAutoStopTimeoutInMinutes': workspace_properties['running_mode_auto_stop_time_out'],
                'UserVolumeSizeGib': workspace_properties['user_volume_size']
            }
        }

        # Validate encryption flags: only one can be enabled
        if user_volume_encryption_enabled and root_volume_encryption_enabled:
            raise PluginException(
                cause="Both user and root volume encryption are enabled.",
                assistance="Only one encryption flag (user or root) may be enabled at a time."
            )

        # Add encryption-related fields conditionally
        if user_volume_encryption_enabled:
            workspace_payload['UserVolumeEncryptionEnabled'] = True
        if root_volume_encryption_enabled:
            workspace_payload['RootVolumeEncryptionEnabled'] = True

        # If any encryption is enabled, ensure volume key is provided
        if user_volume_encryption_enabled or root_volume_encryption_enabled:
            if not volume_encryption_key:
                raise PluginException(
                    cause="Missing required volume encryption key.",
                    assistance="A valid KMS key ARN must be provided when encryption is enabled."
                )
            workspace_payload['VolumeEncryptionKey'] = volume_encryption_key

        # Attempt to create the workspace(s)
        try:
            response = self.connection.aws.client('workspaces').create_workspaces(Workspaces=[workspace_payload])
        except Exception as e:
            raise PluginException(
                cause="Failed to create WorkSpace(s).",
                assistance=f"Error details: {str(e)}"
            )

        # Handle failed requests
        try:
            failed_requests = response.get('FailedRequests', [])
            if failed_requests:
                first_failure = failed_requests[0]
                error_code = first_failure.get('ErrorCode')
                error_msg = first_failure.get('ErrorMessage')
                raise PluginException(
                    cause=f"Workspace creation failed with error code: {error_code}",
                    assistance=error_msg or "No additional information available.",
                    data=response
                )
        except (TypeError, IndexError, KeyError):
            raise PluginException(
                cause="Unexpected response format in failed requests section.",
                assistance="Please verify the structure of the AWS WorkSpaces response.",
                data=response
            )

        # Extract pending/created workspace info
        try:
            pending_requests = response.get('PendingRequests', [])
            if not pending_requests:
                raise PluginException(
                    cause="No pending requests returned from AWS.",
                    assistance="Expected at least one pending request in the response.",
                    data=response
                )

            workspace_info = pending_requests[0]
            workspace_id = workspace_info.get('WorkspaceId')
            workspace_state = workspace_info.get('State')

            if not workspace_id or workspace_state is None:
                raise PluginException(
                    cause="Missing required workspace identifiers in response.",
                    assistance="Ensure the response contains WorkspaceId and State.",
                    data=response
                )

            result = {
                'id': workspace_id,
                'state': workspace_state
            }

        except (TypeError, IndexError, KeyError):
            raise PluginException(
                cause="Response parsing failed due to missing or malformed keys.",
                assistance="Contact support if this issue persists.",
                data=response
            )

        return {Output.WORKSPACE_ID_STATE: result}

