logger = logging.getLogger(__name__)

class MarcottiLoad(WorkflowBase):
    """
    Load transformed data into database.
    """
    def record_exists(self, model, **conditions):
        return self.session.query(model).filter_by(**conditions).count() > 0

    def suppliers(self, data_frame):
        new_suppliers = []
        for _, row in data_frame.iterrows():
            if not self.record_exists(mcs.Suppliers, name=row['name']):
                new_suppliers.append(mcs.Suppliers(name=row['name']))
        self.session.add_all(new_suppliers)
        self.session.commit()

    def years(self, data_frame):
        new_years = []
        for _, row in data_frame.iterrows():
            if not self.record_exists(mco.Years, yr=row['yr']):
                new_years.append(mco.Years(yr=row['yr']))
        self.session.add_all(new_years)
        self.session.commit()

    def seasons(self, data_frame):
        season_records = []
        map_records = []
        for idx, row in data_frame.iterrows():
            if 'name' not in row:
                if row['start_year'] == row['end_year']:
                    yr_obj = self.session.query(mco.Years).filter_by(yr=row['start_year']).first()
                    if yr_obj and not self.record_exists(mco.Seasons, start_year_id=yr_obj.id, end_year_id=yr_obj.id):
                        season_records.append(mco.Seasons(start_year=yr_obj, end_year=yr_obj))
                else:
                    start_yr_obj = self.session.query(mco.Years).filter_by(yr=row['start_year']).first()
                    end_yr_obj = self.session.query(mco.Years).filter_by(yr=row['end_year']).first()
                    if start_yr_obj and end_yr_obj and not self.record_exists(mco.Seasons, 
                                                                              start_year_id=start_yr_obj.id, 
                                                                              end_year_id=end_yr_obj.id):
                        season_records.append(mco.Seasons(start_year=start_yr_obj, end_year=end_yr_obj))
            else:
                if not self.record_exists(mcs.SeasonMap, remote_id=row['remote_id'], supplier_id=self.supplier_id):
                    season_obj = self.session.query(mco.Seasons).filter_by(name=row['name']).first()
                    if season_obj:
                        map_records.append(mcs.SeasonMap(id=season_obj.id,
                                                         remote_id=row['remote_id'],
                                                         supplier_id=self.supplier_id))

        if season_records:
            self.session.add_all(season_records)
        if map_records:
            self.session.add_all(map_records)
        self.session.commit()

    def countries(self, data_frame):
        country_records = []
        remote_ids = []
        fields = ['name', 'code', 'confederation']
        for _, row in data_frame.iterrows():
            country_dict = {field: row[field] for field in fields if row.get(field)}
            if not self.record_exists(mco.Countries, name=row['name']):
                country_records.append(mco.Countries(**country_dict))
                remote_ids.append(row['remote_id'])

        if country_records:
            self.session.add_all(country_records)
            self.session.commit()

            map_records = [mcs.CountryMap(id=c.id, remote_id=rid, supplier_id=self.supplier_id)
                          for rid, c in zip(remote_ids, country_records) if rid]
            if map_records:
                self.session.add_all(map_records)
                self.session.commit()

    def competitions(self, data_frame):
        comp_records = []
        remote_ids = []

        for _, row in data_frame.iterrows():
            if 'country_id' in data_frame.columns:
                fields = ['name', 'level', 'country_id']
                comp_dict = {field: row[field] for field in fields if row.get(field)}
                if not self.record_exists(mco.DomesticCompetitions, **comp_dict):
                    comp_records.append(mco.DomesticCompetitions(**comp_dict))
                    remote_ids.append(row['remote_id'])
            elif 'confederation' in data_frame.columns:
                fields = ['name', 'level', 'confederation']
                comp_dict = {field: row[field] for field in fields if row.get(field)}
                if not self.record_exists(mco.InternationalCompetitions, **comp_dict):
                    comp_records.append(mco.InternationalCompetitions(**comp_dict))
                    remote_ids.append(row['remote_id'])

        if comp_records:
            self.session.add_all(comp_records)
            self.session.commit()

            map_records = [mcs.CompetitionMap(id=c.id, remote_id=rid, supplier_id=self.supplier_id)
                          for rid, c in zip(remote_ids, comp_records) if rid]
            if map_records:
                self.session.add_all(map_records)
                self.session.commit()

    def clubs(self, data_frame):
        club_records = []
        remote_ids = []
        fields = ['short_name', 'name', 'country_id']
        for _, row in data_frame.iterrows():
            club_dict = {field: row[field] for field in fields if row.get(field)}
            if not self.record_exists(mc.Clubs, **club_dict):
                club_records.append(mc.Clubs(**club_dict))
                remote_ids.append(row['remote_id'])

        if club_records:
            self.session.add_all(club_records)
            self.session.commit()

            map_records = [mc.ClubMap(id=c.id, remote_id=rid, supplier_id=self.supplier_id)
                          for rid, c in zip(remote_ids, club_records) if rid]
            if map_records:
                self.session.add_all(map_records)
                self.session.commit()

    def venues(self, data_frame):
        venue_records = []
        history_records = []
        remote_ids = []
        fields = ['name', 'city', 'region', 'latitude', 'longitude', 'altitude', 'country_id', 'timezone_id']
        history_fields = ['eff_date', 'length', 'width', 'capacity', 'seats', 'surface_id']

        for _, row in data_frame.iterrows():
            venue_dict = {field: row[field] for field in fields if row.get(field)}
            if not self.record_exists(mco.Venues, **venue_dict):
                venue_records.append(mco.Venues(**venue_dict))
