from typing import Optional, Generator
from boto3.resources.base import ServiceResource
from dynamodb_encryption_sdk.structures import (
    AttributeActions,
    TableInfo,
    EncryptionContext,
)
from dynamodb_encryption_sdk.encrypted.table import EncryptedTable
from ..key_store import KeyStore
from .item import decrypt_python_item
from .materials_provider import KeyStoreMaterialsProvider

class CryptoTable(object):
    """High-level helper class to provide a DynamoDB-compatible interface for encrypted tables."""

    def __init__(
        self,
        table: ServiceResource,
        key_store: KeyStore,
        table_info: Optional[TableInfo] = None,
        attribute_actions: Optional[AttributeActions] = None,
        auto_refresh_table_indexes: bool = True,
    ) -> None:
        # Initialize default values if not provided
        if attribute_actions is None:
            attribute_actions = AttributeActions()
        if table_info is None:
            table_info = TableInfo(name=table.name)

        # Refresh index attributes if requested
        if auto_refresh_table_indexes:
            table_info.refresh_indexed_attributes(table.meta.client)

        # Store configuration and resources
        self._table = table
        self._key_store = key_store
        self._table_info = table_info
        self._attribute_actions = attribute_actions

    def put_item(self, CSEKeyId: str, **kwargs) -> None:
        """Encrypt and store an item using the specified encryption key."""
        materials_provider = KeyStoreMaterialsProvider(
            key_store=self._key_store,
            material_description={"key_id": CSEKeyId},
        )
        encrypted_table = EncryptedTable(
            table=self._table,
            materials_provider=materials_provider,
            table_info=self._table_info,
            attribute_actions=self._attribute_actions,
        )
        encrypted_table.put_item(**kwargs)

    def get_item(self, **kwargs):
        """Retrieve and decrypt an item from the table."""
        materials_provider = KeyStoreMaterialsProvider(
            key_store=self._key_store,
        )
        encrypted_table = EncryptedTable(
            table=self._table,
            materials_provider=materials_provider,
            table_info=self._table_info,
            attribute_actions=self._attribute_actions,
        )
        return encrypted_table.get_item(**kwargs)

    def query(self, **kwargs):
        """Execute a query and decrypt returned items."""
        response = self._table.query(**kwargs)
        return self._process_dynamodb_response(response)

    def scan(self, **kwargs):
        """Execute a scan and decrypt returned items."""
        response = self._table.scan(**kwargs)
        return self._process_dynamodb_response(response)

    def update_item(self, **kwargs):
        """Update item is not yet supported."""
        raise NotImplementedError('"update_item" is not yet implemented')

    def _process_dynamodb_response(self, response):
        """Decrypt all items in a DynamoDB response."""
        # Build encryption context from table info
        ec_kwargs = dict(self._table_info.encryption_context_values)

        # Add primary index key names if available
        if self._table_info.primary_index is not None:
            ec_kwargs.update({
                "partition_key_name": self._table_info.primary_index.partition,
                "sort_key_name": self._table_info.primary_index.sort,
            })

        # Configure attribute actions with protected index keys
        self._attribute_actions.set_index_keys(*self._table_info.protected_index_keys())
        encryption_context = EncryptionContext(**ec_kwargs)

        def _decrypt_items(items) -> Generator:
            """Generator that yields decrypted items."""
            for item in items:
                try:
                    yield decrypt_python_item(
                        item=item,
                        key_store=self._key_store,
                        encryption_context=encryption_context,
                        attribute_actions=self._attribute_actions,
                    )
                except Exception:  # TODO: Handle specific exceptions appropriately
                    continue

        # Decrypt items and update response metadata
        response["Items"] = list(_decrypt_items(response["Items"]))
        response["Count"] = len(response["Items"])
        return response

    def __getattr__(self, name):
        """Forward undefined attribute/method access to the underlying table object."""
        try:
            return getattr(self._table, name)
        except AttributeError:
            raise AttributeError(f"'{self.__class__.__name__}' object has no attribute '{name}'")

import sys

def process_line(line):
    # Convert line to list of integers
    numbers = list(map(int, line.strip().split()))

    # Simulate pushing all numbers onto a stack (reverse order)
    stack = []
    for num in numbers:
        stack.append(num)

    # Pop elements and collect every alternate one
    result = []
    alternate = True
    while stack:
        if alternate:
            result.append(str(stack.pop()))
        else:
            stack.pop()  # skip this element
        alternate = not alternate

    return ' '.join(result)

# Main execution
if len(sys.argv) > 1:
    with open(sys.argv[1], 'r') as file:
        for line in file:
            if line.strip():  # ignore empty lines
                print(process_line(line))

import threading
import time
import websocket
import json
from urllib.parse import urlencode
from resotolib.logger import log
from resotolib.event import EventType, add_event_listener, remove_event_listener, Event
from resotolib.args import ArgumentParser
from resotolib.jwt import encode_jwt_to_headers
from resotolib.core.ca import TLSData
from typing import Callable, Dict, Optional, Set

class CoreEvents(threading.Thread):
    def __init__(
        self,
        core_ws_endpoint: str,
        event_filters: Optional[Set[str]] = None,
        handler_func: Optional[Callable[[Dict], None]] = None,
        tls_config: Optional[TLSData] = None,
    ) -> None:
        super().__init__()
        base_uri = f"{core_ws_endpoint}/events"
        if event_filters:
            params = urlencode({"show": ",".join(event_filters)})
            base_uri += f"?{params}"
        self.endpoint = base_uri
        self.handler = handler_func
        self.tls_settings = tls_config
        self.websocket_instance = None
        self.stop_flag = threading.Event()

    def __del__(self) -> None:
        remove_event_listener(EventType.SHUTDOWN, self.handle_shutdown)

    def run(self) -> None:
        self.name = "event-stream-handler"
        add_event_listener(EventType.SHUTDOWN, self.handle_shutdown)
        while not self.stop_flag.is_set():
            log.info("Attempting to connect to resotocore event stream")
            try:
                self._establish_connection()
            except Exception as exc:
                log.warning(f"Connection attempt failed: {exc}")
            time.sleep(10)

    def _establish_connection(self) -> None:
        log.debug(f"Initiating connection to {self.endpoint}")
        auth_headers = {}
        if hasattr(ArgumentParser.args, "psk") and getattr(ArgumentParser.args, "psk", None):
            encode_jwt_to_headers(auth_headers, {}, ArgumentParser.args.psk)

        self.websocket_instance = websocket.WebSocketApp(
            self.endpoint,
            header=auth_headers,
            on_open=self._on_connection_established,
            on_message=self._on_message_received,
            on_error=self._on_connection_error,
            on_close=self._on_connection_closed,
            on_ping=self._on_ping_received,
            on_pong=self._on_pong_received,
        )

        ssl_options = None
        if self.tls_settings:
            ssl_options = {"ca_certs": self.tls_settings.ca_cert_path}

        self.websocket_instance.run_forever(
            sslopt=ssl_options,
            ping_interval=30,
            ping_timeout=10,
            ping_payload="keepalive",
        )

    def handle_shutdown(self, event: Event = None) -> None:
        log.info("Shutdown signal received - terminating event listener")
        self.stop_flag.set()
        if self.websocket_instance:
            self.websocket_instance.close()

    def _on_message_received(self, ws, raw_data):
        try:
            parsed_data: Dict = json.loads(raw_data)
        except json.JSONDecodeError:
            log.error(f"Malformed message received: {raw_data}")
            return

        log.debug(f"Incoming event data: {parsed_data}")
        if self.handler is not None and callable(self.handler):
            try:
                self.handler(parsed_data)
            except Exception as proc_err:
                log.exception(f"Message processing error for {parsed_data}: {proc_err}")

    def _on_connection_error(self, ws, err_msg):
        log.error(f"Event stream error encountered: {err_msg}")

    def _on_connection_closed(self, ws, close_code, reason):
        log.debug(f"Event stream connection closed - code: {close_code}, reason: {reason}")

    def _on_connection_established(self, ws):
        log.debug("Successfully connected to resotocore event stream")

    def _on_ping_received(self, ws, ping_data):
        log.debug(f"Ping received from event stream: {ping_data}")

    def _on_pong_received(self, ws, pong_data):
        log.debug(f"Pong response sent: {pong_data}")

import codecs
import dataclasses
import io
import json
import os
import pathlib
import pprint
import sys
from typing import Optional
from . import get_github_json

@dataclasses.dataclass
class Repository:
    owner: str
    name: str
    ref: str
    pr_number: Optional[int] = None

    @property
    def identifier(self):
        return f"{self.owner}/{self.name}"

    @property
    def branch_link(self):
        return f"https://github.com/{self.identifier}/tree/{self.ref}"

    @property
    def pull_request_link(self):
        assert self.pr_number is not None, self
        return f"https://github.com/{self.identifier}/pull/{self.pr_number}"


def fetch_event_data(debug=(os.environ.get('ACTIONS_STEP_DEBUG', None) == 'true')):
    event_path = os.environ.get('GITHUB_EVENT_PATH')
    if not event_path:
        raise SystemError("Missing GITHUB_EVENT_PATH environment variable.")

    event_file = pathlib.Path(event_path)
    if not event_file.exists():
        raise SystemError(f"Event file not found at {event_file}")

    with open(event_file) as fp:
        event_data = json.load(fp)

    if debug:
        print()
        print("::group::Raw Event JSON")
        print(open(event_file).read())
        print("::endgroup::")
        print()
        print("::group::Parsed Event Details")
        pprint.pprint(event_data)
        print("::endgroup::")
        print(flush=True)

    return event_data


def resolve_repo_name(env_key, base_repo, cache={}):
    if env_key in os.environ:
        return os.environ[env_key]

    if env_key not in cache:
        api_url = f'https://api.github.com/repos/{base_repo.identifier}'
        repo_info = get_github_json(api_url)

        if 'fork' in repo_info and repo_info['fork']:
            cache[env_key] = repo_info['parent']['name']
        else:
            cache[env_key] = repo_info['name']

    return cache[env_key]


def extract_context(event_data=None):
    # Handle ROT13-encoded environment variables to avoid exposure in logs
    for rot_var, plain_var in [
        ('ROT13_STAGING_OWNER', 'STAGING_OWNER'),
        ('ROT13_UPSTREAM_OWNER', 'UPSTREAM_OWNER'),
        ('ROT13_UPSTREAM_BRANCH', 'UPSTREAM_BRANCH')
    ]:
        if rot_var in os.environ:
            os.environ[plain_var] = codecs.decode(
                os.environ.get(rot_var), 'rot_13'
            )

    # Determine source repository info from event payload or environment
    if event_data:
        if 'pull_request' in event_data:
            head_repo = event_data['pull_request']['head']['repo']
            source_branch = event_data['pull_request']['head']['ref']
            pr_id = event_data['pull_request']['number']
            commit_sha = event_data['pull_request']['head']['sha']

            private_repo = Repository(
                owner=head_repo['owner']['login'],
                name=head_repo['name'],
                ref=source_branch,
                pr_number=pr_id
            )
        else:
            repo_data = event_data['repository']
            source_branch = event_data['ref']

            private_repo = Repository(
                owner=repo_data['owner']['login'],
                name=repo_data['name'],
                ref=source_branch,
                pr_number=None
            )
            commit_sha = None
    else:
        private_repo = Repository(owner=None, name=None, ref=None, pr_number=None)
        commit_sha = None

    # Build final configuration using environment overrides
    private = Repository(
        owner=os.environ.get('PRIVATE_OWNER', private_repo.owner),
        name=os.environ.get('PRIVATE_REPO', private_repo.name),
        ref=os.environ.get('PRIVATE_BRANCH', private_repo.ref),
        pr_number=private_repo.pr_number
    )

    staging = Repository(
        owner=os.environ.get('STAGING_OWNER', ''),
        name=resolve_repo_name('STAGING_REPO', private),
        ref=os.environ.get('STAGING_BRANCH', private.ref)
    )

    upstream = Repository(
        owner=os.environ.get('UPSTREAM_OWNER', ''),
        name=resolve_repo_name('UPSTREAM_REPO', private),
        ref=os.environ.get('UPSTREAM_BRANCH', 'main'),
        pr_number=os.environ.get('UPSTREAM_PR')
    )

    # Display summary
    print()
    print(" Private:", private.identifier, "@", private.ref, "(", private.branch_link, ")")
    print(" Staging:", staging.identifier, "@", staging.ref, "(", staging.branch_link, ")")
    print("Upstream:", upstream.identifier, "@", upstream.ref, "(", upstream.branch_link, ")")
    print()

    if commit_sha:
        sha_url = f"https://github.com/{private.identifier}/commits/{commit_sha}"
        print()
        print(" Pull request @", commit_sha, "(", sha_url, ")")
        print()
    else:
        commit_sha = ""

    return (private, staging, upstream, commit_sha)


def execute(args):
    original_stdout = sys.stdout
    quiet_mode = '--quiet' in args
    if quiet_mode:
        args.remove('--quiet')
        sys.stdout = io.StringIO()

    event_data = fetch_event_data(sys.stdout == original_stdout)
    private, staging, upstream, commit_sha = extract_context(event_data)

    if args:
        for expr in args:
            print(eval(expr), file=original_stdout)
    else:
        output = f"""
PRIVATE_OWNER={private.owner}
PRIVATE_REPO={private.name}
PRIVATE_BRANCH={private.ref}
STAGING_OWNER={staging.owner}
STAGING_REPO={staging.name}
STAGING_BRANCH={staging.ref}
UPSTREAM_OWNER={upstream.owner}
UPSTREAM_REPO={upstream.name}
UPSTREAM_BRANCH={upstream.ref}
""".strip()
        print(output, file=original_stdout)


if __name__ == "__main__":
    sys.exit(execute(list(sys.argv[1:])))

from typing import Optional, TYPE_CHECKING

from src.engine import actions
from src.display import colours
from src.components.inventory import Inventory
from src.components.baseComponent import BaseComponent
from src.engine.exceptions import Impossible

if TYPE_CHECKING:
    from src.entities.entity import Actor, Item


class Consumable(BaseComponent):
    parent: Item

    def getAction(self, consumer: Actor) -> Optional[actions.Action]:
        """Attempt to retrieve the action associated with this item."""
        return actions.ItemAction(consumer, self.parent)

    def use(self, action: actions.ItemAction) -> None:
        """
        Trigger this item's special effect.
        'action' provides the execution context for this activation.
        """
        raise NotImplementedError()

    def discard(self) -> None:
        """Removes the used item from its parent inventory."""
        item = self.parent
        container = item.parent
        if isinstance(container, Inventory):
            container.items.remove(item)


class HealthPotion(Consumable):
    def __init__(self, heal_value: int):
        self.heal_amount = heal_value

    def use(self, action: actions.ItemAction) -> None:
        user = action.entity
        actual_healing = user.fighter.restore_health(self.heal_amount)

        if actual_healing > 0:
            self.engine.messageLog.addMessage(
                f"You drink the {self.parent.name} and regain {actual_healing} health points.",
                colours.healthRecovered,
            )
            self.discard()
        else:
            raise Impossible("Your health is already at maximum.")

