from __future__ import unicode_literals
from ipaddress import ip_address
from flask import has_request_context, request, session
from sqlalchemy.ext.associationproxy import association_proxy
from sqlalchemy.ext.declarative import declared_attr
from indico.core.db import db
from indico.core.db.sqlalchemy import PyIPNetwork
from indico.core.db.sqlalchemy.principals import PrincipalType
from indico.util.string import format_repr, return_ascii


class IPNetworkGroup(db.Model):
    __tablename__ = 'ip_network_groups'
    principal_type = PrincipalType.network
    principal_order = 1
    is_group = False
    is_network = True
    is_single_person = False
    is_event_role = False
    is_category_role = False
    is_registration_form = False

    @declared_attr
    def __table_args__(cls):
        return (
            db.Index('ix_uq_ip_network_groups_name_lower', db.func.lower(cls.group_name), unique=True),
            {'schema': 'indico'}
        )

    identifier = db.Column(
        db.Integer,
        primary_key=True
    )
    group_name = db.Column(
        db.String,
        nullable=False
    )
    notes = db.Column(
        db.Text,
        nullable=False,
        default=''
    )
    #: Whether the network group is hidden in ACL forms
    is_hidden = db.Column(
        db.Boolean,
        nullable=False,
        default=False
    )
    #: Grants all IPs in the network group read access to all attachments
    bypass_attachment_access = db.Column(
        db.Boolean,
        nullable=False,
        default=False
    )

    _network_list = db.relationship(
        'IPNetwork',
        lazy=False,
        cascade='all, delete-orphan',
        collection_class=set,
        backref=db.backref(
            'owner_group',
            lazy=True
        )
    )

    # Replaced association proxy with equivalent logic using renamed attribute
    networks = association_proxy('_network_list', 'cidr_block', creator=lambda v: IPNetwork(cidr_block=v))

    # relationship backrefs:
    # - in_category_acls (CategoryPrincipal.ip_network_group)
    # - in_event_acls (EventPrincipal.ip_network_group)

    @return_ascii
    def __repr__(self):
        return format_repr(self, 'identifier', 'group_name', is_hidden=False, bypass_attachment_access=False)

    def __contains__(self, user):
        # This method is called via ``user in principal`` during ACL checks.
        # We have to take the IP from the request so if there's no request
        # (e.g. in the shell) we never grant IP-based access; same if we check
        # for a different user than the one from the current session.
        if not has_request_context() or not request.remote_addr:
            return False
        if session.user != user:
            return False
        return self.ip_matches(unicode(request.remote_addr))

    def ip_matches(self, ip_str):
        """Check whether the given IP address falls within any network in this group."""
        try:
            checked_ip = ip_address(ip_str)
        except ValueError:
            return False
        for net in self._network_list:
            if checked_ip in net.cidr_block:
                return True
        return False

    @property
    def locator(self):
        return {'network_group_id': self.identifier}


class IPNetwork(db.Model):
    __tablename__ = 'ip_networks'
    __table_args__ = {'schema': 'indico'}

    group_identifier = db.Column(
        db.Integer,
        db.ForeignKey('indico.ip_network_groups.identifier'),
        primary_key=True,
        autoincrement=False
    )
    cidr_block = db.Column(
        PyIPNetwork,
        primary_key=True,
        nullable=False
    )

    # relationship backrefs:
    # - owner_group (IPNetworkGroup._network_list)

    @return_ascii
    def __repr__(self):
        return format_repr(self, 'group_identifier', 'cidr_block')

import os
