def load():
    """Load finish data from YAML, validate, ensure uniqueness by 'id', return as tuple."""
    raw_data = yaml.load("finish.yaml")
    validated_data = _validate_finish_data(raw_data)

    # Ensure unique IDs
    ids = [entry["id"] for entry in validated_data]
    id_counts = {}
    for identifier in ids:
        id_counts[identifier] = id_counts.get(identifier, 0) + 1
        if id_counts[identifier] > 1:
            raise ValueError(f"Duplicate 'id' {identifier} found {id_counts[identifier]} times in finish.yaml")

    return tuple(validated_data)


def _validate_finish_data(raw):
    """Validate raw finish data using schema-based rules."""
    required_keys = {"id", "time"}

    # Custom validation: check each item has required keys and correct types/format
    for idx, item in enumerate(raw):
        if not isinstance(item, dict):
            raise TypeError(f"Entry at index {idx} is not a dictionary")

        missing = required_keys - set(item.keys())
        if missing:
            raise KeyError(f"Entry at index {idx} missing keys: {missing}")

        if not isinstance(item["id"], int):
            raise TypeError(f"'id' in entry {idx} must be integer, got {type(item['id']).__name__}")

        time_str = item["time"]
        if not isinstance(time_str, str):
            raise TypeError(f"'time' in entry {idx} must be string, got {type(time_str).__name__}")

        # Regex pattern for HH:MM:SS.m format (e.g., 01:23:45.6)
        pattern = r'^\d{2}:\d{2}:\d{2}\.\d$'
        if not re.match(pattern, time_str):
            raise ValueError(f"'time' value '{time_str}' in entry {idx} does not match expected format HH:MM:SS.m")

    return raw


def dump(start_data, encoding_print):
    """Generate and write results to YAML and text files."""
    output = {
        "name": start_data["name"],
        "date": start_data["date"],
        "races": []
    }

    for race in start_data.get("evals", []):
        race_out = {
            "name": race["name"],
            "desc": race["desc"],
            "sex": race["sex"],
            "distance": race["distance"],
            "athletes": []
        }

        # Get first athlete with time attribute for diff calculation
        first_athlete = None
        athletes_list = race.get("athletes", [])
        if athletes_list:
            candidate = athletes_list[0]
            if hasattr(candidate, "time") and candidate.time is not None:
                first_athlete = candidate

        for athlete in athletes_list:
            athlete_out = {
                "rank": getattr(athlete, "rank", ""),
                "rank_sokol": getattr(athlete, "rank_sokol", ""),
                "name": getattr(athlete, "name", ""),
                "surname": getattr(athlete, "surname", ""),
                "born": getattr(athlete, "born", ""),
                "club": athlete.club.abb15 if hasattr(athlete, "club") and athlete.club else "",
                "start": getattr(athlete, "start", ""),
                "finish": athlete.finish.strftime("%H:%M:%S") if hasattr(athlete, "finish") and athlete.finish else "",
                "time": util.format_delta(athlete.time) if hasattr(athlete, "time") and athlete.time else "",
                "diff": util.format_delta(athlete.time - first_athlete.time) 
                        if hasattr(athlete, "time") and athlete.time and first_athlete and first_athlete.time else ""
            }
            race_out["athletes"].append(athlete_out)

        output["races"].append(race_out)

    yaml.dump(output, "results.yaml")
    termtables.dump_finish(output, "results.txt", encoding_print)

# Custom exception for malformed module definitions
class MalformedModule(Exception):
    """Raised when a module definition is invalid or incomplete."""

# Metaclass to enforce module structure and provide utility methods
class ModuleMeta(type):
    """ModuleMeta:
        Validates that Module subclasses contain required attributes
        and ensures consistent module initialization.
    """
    def __new__(mcs, name, bases, namespace):
        # Check for required class attributes in the new class definition
        if 'DOC_URI' not in namespace:
            raise MalformedModule('DOC_URI attribute missing in module definition')
        if 'PROTOCOL' not in namespace:
            raise MalformedModule('PROTOCOL attribute missing in module definition')
        if 'VERSION' not in namespace:
            raise MalformedModule('VERSION attribute missing in module definition')

        return super().__new__(mcs, name, bases, namespace)

# Base class for all modules with routing capabilities
class BaseModule(metaclass=ModuleMeta):  # pylint: disable=too-few-public-methods
    """Base class providing common functionality for all modules."""

    # Required class attributes (will be overridden by subclasses)
    DOC_URI = None
    PROTOCOL = None
    VERSION = None

    def __init__(self):
        self._route_cache = None

    def build_type(
            self,
            type_name: str,
            doc_uri: str = None,
            protocol: str = None,
            version: str = None
                ):
        """Construct a Type instance using module context or provided values."""
        # Use instance/module defaults if not explicitly provided
        effective_doc_uri = doc_uri if doc_uri is not None else self.DOC_URI
        effective_protocol = protocol if protocol is not None else self.PROTOCOL
        effective_version = version if version is not None else self.VERSION

        # Validate that all components are present
        if effective_doc_uri is None:
            raise TypeError('doc_uri must be specified')
        if effective_protocol is None:
            raise TypeError('protocol must be specified')
        if effective_version is None:
            raise TypeError('version must be specified')

        # Create and return the Type instance
        from .type import Type
        return Type(effective_doc_uri, effective_protocol, effective_version, type_name)

    def discover_routes(self):
        """Scan instance attributes for route handlers."""
        discovered = {}

        # Iterate through all attributes of the instance
        for attr_name in dir(self):
            # Skip special methods and the routes property itself
            if attr_name == 'routes' or attr_name.startswith('__'):
                continue

            # Get the attribute value
            attr_value = getattr(self, attr_name)

            # Check if it's a decorated handler
            if hasattr(attr_value, 'handler_for'):
                msg_type = attr_value.handler_for

                # If it's a partial type, complete it with module context
                if isinstance(msg_type, IncompleteType):
                    msg_type = msg_type.resolve(self)

                # Map the message type to its handler
                discovered[msg_type] = attr_value

        return discovered

    @property
    def routes(self):
        """Access the module's route mappings, caching after first access."""
        if self._route_cache is None:
            self._route_cache = self.discover_routes()
        return self._route_cache

# Class representing an incomplete type specification before module context is applied
class IncompleteType:
    """Represents a type specification that needs module context to be fully resolved."""

    __slots__ = (
        'name',
        'doc_uri',
        'protocol',
        'version'
    )

    def __init__(
            self,
            name: str,
            doc_uri: str = None,
            protocol: str = None,
            version: str = None
                ):
        self.name = name
        self.version = version
        self.protocol = protocol
        self.doc_uri = doc_uri

    def resolve(self, module_instance: BaseModule) -> "Type":
        """Complete the type specification using the module's context."""
        # Prefer explicit values, fall back to module defaults
        final_doc_uri = self.doc_uri if self.doc_uri else type(module_instance).DOC_URI
        final_protocol = self.protocol if self.protocol else type(module_instance).PROTOCOL
        final_version = self.version if self.version else type(module_instance).VERSION

        # Ensure all required fields are present
        if final_doc_uri is None:
            raise TypeError('doc_uri cannot be None')
        if final_protocol is None:
            raise TypeError('protocol cannot be None')
        if final_version is None:
            raise TypeError('version cannot be None')

        # Return the fully resolved Type instance
        from .type import Type
        return Type(final_doc_uri, final_protocol, final_version, self.name)

# Decorator for marking handler functions as route handlers
def route(*args, **kwargs):
    """Decorator to mark methods as message handlers.

    Can be used in multiple ways:
    - @route (no arguments)
    - @route("type_string") (with message type string)
    - @route(name="custom", doc_uri="...", ...) (with keyword arguments)
    """
    # Case 1: Direct decoration without parentheses: @route
    if args and callable(args[0]):
        func = args[0]
        func.handler_for = IncompleteType(func.__name__)
        return func

    # Case 2: Decorator with arguments: @route(...) or @route("type")
    def decorator(func):
        # Handle different argument patterns
        if args:
            type_spec = args[0]
            if isinstance(type_spec, str):
                # String type specification
                from .type import Type
                func.handler_for = Type.from_str(type_spec)
            elif isinstance(type_spec, "Type"):
                # Already a Type object
                func.handler_for = type_spec
            else:
                raise ValueError(f"Unsupported type specification: {type(type_spec)}")
        elif kwargs:
            # Keyword arguments for partial type specification
            name = kwargs.pop('name', func.__name__)
            func.handler_for = IncompleteType(name, **kwargs)
        else:
            raise ValueError("Invalid route decorator usage")

        return func

    # If no arguments were provided, we need to handle the case where
    # someone wrote @route() instead of just @route
    if not args and not kwargs:
        raise ValueError("Route decorator requires either a function or type specification")

    return decorator

# Music bot module using Discord.py and external libraries for audio streaming

import discord
from discord.ext import commands
import asyncio
import pafy
import youtube_dl
from datetime import datetime

class AudioPlayer(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.music_queue = {}
        self.initialize_queues()

    def initialize_queues(self):
        for server in self.bot.guilds:
            self.music_queue[server.id] = []

    async def process_next_track(self, ctx):
        if len(self.music_queue[ctx.guild.id]) > 0:
            ctx.voice_client.stop()
            await self.start_audio(ctx, self.music_queue[ctx.guild.id][0])
            self.music_queue[ctx.guild.id].pop(0)

    async def fetch_song_info(self, count, query, return_urls=False):
        ydl_opts = {"format": "bestaudio", "quiet": True}
        info = await self.bot.loop.run_in_executor(
            None, 
            lambda: youtube_dl.YoutubeDL(ydl_opts).extract_info(
                f"ytsearch{count}:{query}", 
                download=False, 
                ie_key="YoutubeSearch"
            )
        )

        if not info["entries"]:
            return None

        return [item["webpage_url"] for item in info["entries"]] if return_urls else info

    async def start_audio(self, ctx, track_url):
        audio_stream = pafy.new(track_url).getbestaudio().url
        source = discord.PCMVolumeTransformer(discord.FFmpegPCMAudio(audio_stream))
        source.volume = 0.5

        ctx.voice_client.play(
            source, 
            after=lambda err: self.bot.loop.create_task(self.process_next_track(ctx))
        )

    @commands.command(
        name="connect",
        description="Joins the user's voice channel.",
        usage="connect",
        aliases=['join_vc']
    )
    async def connect_to_channel(self, ctx):
        if not ctx.author.voice:
            return await ctx.send("You need to be in a voice channel first.")

        target_channel = ctx.author.voice.channel

        if ctx.voice_client is None:
            await target_channel.connect()
            await ctx.send(f"Joined **{target_channel}** successfully.")
        else:
            if len(ctx.voice_client.channel.members) == 1:
                ctx.voice_client.stop()
                await ctx.voice_client.move_to(target_channel)
                await ctx.send(f"Moved to **{target_channel}**.")
            else:
                await ctx.send("Another user is currently using this voice channel.")

    @commands.command(
        name="leave",
        description="Leaves the current voice channel.",
        usage="leave",
        aliases=['disconnect_vc']
    )
    async def disconnect_from_channel(self, ctx):
        voice_state = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("You must be in a voice channel to use this command.")
        elif not voice_state:
            return await ctx.send("I'm not connected to any voice channel.")

        if ctx.author.voice.channel == voice_state.channel:
            if len(voice_state.channel.members) <= 1:
                voice_state.stop()
                await voice_state.disconnect()
                await ctx.send(f"Disconnected from **{voice_state.channel}**.")
            else:
                await ctx.send("Other users are still in the voice channel.")
        else:
            await ctx.send("You're not in the same voice channel as me.")

    @commands.command(
        name="play",
        description="Plays a song by URL or search term.",
        usage="play [song/url]",
        aliases=['start_music']
    )
    async def play_track(self, ctx, *, track=None):
        voice_client = ctx.voice_client

        if not track:
            return await ctx.send("Please provide a song title or URL.")

        if not ctx.author.voice:
            return await ctx.send("You need to be in a voice channel first.")

        # Convert search terms to YouTube URLs
        if not any(domain in track for domain in ["youtube.com/watch?", "youtu.be/"]):
            urls = await self.fetch_song_info(1, track, return_urls=True)
            if not urls:
                return await ctx.send("Could not find that song on YouTube.")
            track = urls[0]

        voice_channel = ctx.author.voice.channel

        # Connect if not already in voice channel
        if not voice_client:
            await voice_channel.connect()
            await self.start_audio(ctx, track)
            return await ctx.send(f"Now playing: {track}")

        # Handle queueing when music is already playing
        if voice_client.source is not None:
            if ctx.author.voice.channel == voice_client.channel:
                queue_size = len(self.music_queue[ctx.guild.id])

                if queue_size < 10:
                    self.music_queue[ctx.guild.id].append(track)
                    return await ctx.send("Added to queue.")
                else:
                    return await ctx.send("Queue is full (max 10 songs).")
            else:
                # Move to user's channel if only one person there
                if len(voice_client.channel.members) == 1:
                    voice_client.stop()
                    await voice_client.move_to(voice_channel)
                    await self.start_audio(ctx, track)
                    return await ctx.send(f"Now playing: {track}")
                else:
                    return await ctx.send("Someone else is using this voice channel.")

        # Play directly if no active source
        if ctx.author.voice.channel == voice_client.channel:
            await self.start_audio(ctx, track)
            await ctx.send(f"Now playing: {track}")
        else:
            if len(voice_client.channel.members) == 1:
                voice_client.stop()
                await voice_client.move_to(voice_channel)
                await self.start_audio(ctx, track)
                await ctx.send(f"Now playing: {track}")
            else:
                await ctx.send("Someone else is using this voice channel.")

    @commands.command(
        name="list_queue",
        description="Shows all queued songs.",
        usage="list_queue",
        aliases=['show_queue', 'q']
    )
    async def display_queue(self, ctx):
        if not self.music_queue[ctx.guild.id]:
            return await ctx.send("No songs in the queue.")

        embed = discord.Embed(
            title="Music Queue", 
            description="", 
            timestamp=datetime.utcnow(), 
            color=0x86242a
        )
        embed.set_footer(text=f"Requested by {ctx.author}", icon_url=ctx.author.avatar.url)
        embed.set_thumbnail(url=self.bot.user.avatar.url)

        for idx, url in enumerate(self.music_queue[ctx.guild.id], 1):
            embed.description += f"{idx}. {url}\n"

        await ctx.send(embed=embed)

    @commands.command(
        name="skip_song",
        description="Skips the current song via voting.",
        usage="skip_song"
    )
    async def skip_current_song(self, ctx):
        voice_client = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("You must be in a voice channel first.")
        elif not voice_client:
            return await ctx.send("I'm not in a voice channel.")

        if ctx.author.voice.channel != voice_client.channel:
            return await ctx.send("You're not in my voice channel.")

        # Create poll message
        poll = await ctx.send(
            "Skip current song? 80% of participants must vote yes. Voting ends in 15 seconds."
        )
        poll_id = poll.id

        await poll.add_reaction("✅")
        await poll.add_reaction("🚫")

        await asyncio.sleep(15)

        updated_poll = await ctx.channel.fetch_message(poll_id)
        votes = {"✅": 0, "🚫": 0}
        voters = []

        for reaction in updated_poll.reactions:
            if reaction.emoji in ["✅", "🚫"]:
                async for voter in reaction.users():
                    if (voter.voice and voter.voice.channel.id == voice_client.channel.id 
                        and voter.id not in voters and not voter.bot):
                        votes[reaction.emoji] += 1
                        voters.append(voter.id)

        skip_approved = False
        if votes["✅"] > 0:
            total_votes = votes["✅"] + votes["🚫"]
            if votes["✅"] / max(total_votes, 1) >= 0.8:
                skip_approved = True
                await ctx.send("Song skipped based on vote.")

        if not skip_approved:
            await ctx.send("Not enough votes to skip the song.")

        await poll.clear_reactions()

        if skip_approved:
            voice_client.stop()
            await self.process_next_track(ctx)

    @commands.command(
        name="pause_song",
        description="Pauses the current song.",
        usage="pause_song"
    )
    async def pause_current_track(self, ctx):
        voice_client = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("You must be in a voice channel first.")
        elif not voice_client:
            return await ctx.send("I'm not connected to a voice channel.")

        if ctx.author.voice.channel != voice_client.channel:
            return await ctx.send("You're not in my voice channel.")

        if voice_client.is_paused():
            return await ctx.send("Already paused.")
        elif voice_client.is_playing():
            voice_client.pause()
            return await ctx.send("Paused playback.")
        else:
            return await ctx.send("Nothing is currently playing.")

    @commands.command(
        name="resume_song",
        description="Resumes the current song.",
        usage="resume_song"
    )
    async def resume_current_track(self, ctx):
        voice_client = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("You must be in a voice channel first.")
        elif not voice_client:
            return await ctx.send("I'm not connected to a voice channel.")

        if ctx.author.voice.channel != voice_client.channel:
            return await ctx.send("You're not in my voice channel.")

        if voice_client.is_paused():
            voice_client.resume()
            return await ctx.send("Resumed playback.")
        elif voice_client.is_playing():
            return await ctx.send("Already playing.")
        else:
            return await ctx.send("Nothing is currently playing.")

    @commands.command(
        name="end_session",
        description="Stops playback and clears queue.",
        usage="end_session"
    )
    async def stop_music_session(self, ctx):
        voice_client = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("You must be in a voice channel first.")
        elif not voice_client:
            return await ctx.send("I'm not connected to a voice channel.")

        if ctx.author.voice.channel != voice_client.channel:
            return await ctx.send("You're not in my voice channel.")

        if voice_client.is_playing() or voice_client.is_paused():
            voice_client.stop()
            self.music_queue[ctx.guild.id].clear()
            await ctx.send("Playback stopped and queue cleared.")
        else:
