from libqtile.extension.dmenu import Dmenu
from libqtile.scratchpad import ScratchPad

class WindowList(Dmenu):
    """
    Display a vertical list of active windows using dmenu and switch to the chosen one.
    """
    defaults = [
        ("item_template", "{group}.{id}: {window}", "format string for menu entries"),
        (
            "include_all_groups",
            True,
            "When True, include windows from all groups; otherwise only current group's windows",
        ),
        ("vertical_items", "80", "Number of lines displayed vertically; set to None for horizontal"),
    ]

    def __init__(self, **config):
        Dmenu.__init__(self, **config)
        self.add_defaults(WindowList.defaults)

    def gather_windows(self):
        window_index = 0
        self.selection_map = {}

        if self.include_all_groups:
            active_windows = self.qtile.windows_map.values()
        else:
            active_windows = self.qtile.current_group.windows

        for window in active_windows:
            # Skip scratchpad windows and those without valid groups
            if hasattr(window, 'group') and window.group and not isinstance(window.group, ScratchPad):
                label = window.group.label or window.group.name
                entry = self.item_template.format(
                    group=label, id=window_index, window=window.name or ''
                )
                self.selection_map[entry] = window
                window_index += 1

    def execute(self):
        self.gather_windows()
        result = super().run(items=list(self.selection_map.keys()))

        if not result or not isinstance(result, str):
            return

        try:
            selected = result.strip()
        except AttributeError:
            return

        try:
            target_window = self.selection_map[selected]
        except KeyError:
            # Window may have been closed during menu display
            return

        current_screen = self.qtile.current_screen
        current_screen.set_group(target_window.group)
        target_window.group.focus(target_window)

