def _generate_test_id(suffix: str) -> str:
    """Generate a unique identifier for test objects."""
    return f"__ibis_test_{suffix}_{util.guid()}"


@lru_cache(maxsize=None)
def _list_available_backends() -> frozenset[str]:
    """Retrieve set of available backend names from entry points."""
    backends = []
    for entry_point in importlib_metadata.entry_points()["ibis.backends"]:
        backends.append(entry_point.name)
    return frozenset(backends)


def _load_backend_config(backend_name: str):
    """Dynamically load and return the configuration class for a backend."""
    module_path = f"ibis.backends.{backend_name}.tests.conftest"
    module = importlib.import_module(module_path)
    return getattr(module, "TestConf")


def _extract_backend_from_path(path_parts: Tuple[str, ...]) -> str | None:
    """Extract backend name from file path components."""
    try:
        idx = path_parts.index("backends")
        return path_parts[idx + 1]
    except ValueError:
        return None


def pytest_ignore_collect(path_obj, config):
    """Determine whether to ignore collection of a test path."""
    # Extract backend from path
    backend = _extract_backend_from_path(tuple(Path(path_obj).parts))

    if backend is None or backend not in _list_available_backends():
        return False

    # Check markers early to avoid importing unnecessary dependencies
    marker_expr = config.getoption("-m")
    if not marker_expr:
        return False

    expr = _pytest.mark.expression.Expression.compile(marker_expr)

    # Keep tests that match backend or have 'backend' marker
    keep = expr.evaluate(lambda s: s in (backend, "backend"))
    return not keep


def pytest_collection_modifyitems(session, config, items):
    """Apply backend-specific markers to collected test items."""
    all_backends = _list_available_backends()

    for item in items:
        parts = tuple(item.path.parts)
        backend = _extract_backend_from_path(parts)

        if backend and backend in all_backends:
            item.add_marker(getattr(pytest.mark, backend))
            item.add_marker(pytest.mark.backend)
        elif "backends" not in parts:
            item.add_marker(pytest.mark.core)

        # Group specific backends for xdist
        if "sqlite" in item.nodeid:
            item.add_marker(pytest.mark.xdist_group(name="sqlite"))
        if "duckdb" in item.nodeid:
            item.add_marker(pytest.mark.xdist_group(name="duckdb"))


@lru_cache(maxsize=None)
def _select_backends_to_test(
    include: Tuple[str, ...] = (),
    exclude: Tuple[str, ...] = (),
) -> list[Any]:
    """Select backends for testing based on inclusion/exclusion criteria."""
    available = _list_available_backends()

    # Apply exclusion filter
    if exclude:
        available = available.difference(exclude)

    # Apply inclusion filter
    if include:
        available = available.intersection(include)

    # Remove spark alias (use pyspark instead)
    available = available.difference(("spark",))

    # Prepare parameterized test entries
    result = []
    for backend in sorted(available):
        param = pytest.param(
            backend,
            marks=[getattr(pytest.mark, backend), pytest.mark.backend],
            id=backend,
        )
        result.append(param)

    return result


def pytest_runtest_call(item):
    """Dynamically apply custom markers during test execution."""
    nodeid = item.nodeid

    # Identify backend(s) associated with this test
    backend_names = [
        backend.name()
        for key, backend in item.funcargs.items()
        if key.endswith("backend")
    ]

    if len(backend_names) > 1:
        raise ValueError(
            f"Test '{item.originalname}' received multiple backend objects. "
            f"This likely indicates a leaky fixture. "
            f"Backends provided: {', '.join(backend_names)}"
        )

    if not backend_names:
        # Fallback: check path for backend reference
        potential_backends = _list_available_backends()
        backend_names = [p for p in item.path.parts if p in potential_backends]

    if not backend_names:
        return

    backend = next(iter(backend_names))

    # Handle skip_backends marker
    for marker in item.iter_markers(name="skip_backends"):
        if backend in marker.args[0]:
            pytest.skip(f"skip_backends: {backend} {nodeid}")

    # Handle min_spark_version marker
    for marker in item.iter_markers(name='min_spark_version'):
        min_version = marker.args[0]
        if backend == 'pyspark':
            from distutils.version import LooseVersion
            import pyspark
            if LooseVersion(pyspark.__version__) < LooseVersion(min_version):
                item.add_marker(
                    pytest.mark.xfail(
                        reason=f'Require minimal spark version {min_version}, '
                        f'but is {pyspark.__version__}',
                        **marker.kwargs,
                    )
                )

    # Handle notimpl marker (feature not exposed in Ibis)
    for marker in item.iter_markers(name="notimpl"):
        if backend in marker.args[0]:
            reason = marker.kwargs.get("reason")
            kwargs = {k: v for k, v in marker.kwargs.items() if k != "reason"}
            item.add_marker(
                pytest.mark.xfail(
                    reason=reason or f'Feature not yet exposed in {backend}',
                    **kwargs,
                )
            )

    # Handle notyet marker (feature unavailable upstream)
    for marker in item.iter_markers(name="notyet"):
        if backend in marker.args[0]:
            reason = marker.kwargs.get("reason")
            kwargs = {k: v for k, v in marker.kwargs.items() if k != "reason"}
            item.add_marker(
                pytest.mark.xfail(
                    reason=reason or f'Feature not available upstream for {backend}',
                    **kwargs,
                )
            )

    # Handle never marker (intentionally unsupported)
    for marker in item.iter_markers(name="never"):
        if backend in marker.args[0]:
            if "reason" not in marker.kwargs:
                raise ValueError("never requires a reason")
            item.add_marker(pytest.mark.xfail(**marker.kwargs))

    # Handle broken marker (known failures)
    for marker in item.iter_markers(name="broken"):
        if backend in marker.args[0]:
            reason = marker.kwargs.get("reason")
            kwargs = {k: v for k, v in marker.kwargs.items() if k != "reason"}
            item.add_marker(
                pytest.mark.xfail(
                    reason=reason or f"Feature is failing on {backend}",
                    **kwargs,
                )
            )


