# Infuse initialization module for Insanic framework

from insanic.connections import get_connection
from infuse.breaker.storages import CircuitAioRedisStorage
from infuse.patch import patch


class InfuseInitializer:
    @classmethod
    def configure_application(cls, app_instance) -> None:
        # Import configuration module and apply settings
        from . import settings as config_module

        for attribute_name in dir(config_module):
            if attribute_name.isupper():
                config_value = getattr(config_module, attribute_name)

                if attribute_name == "INFUSE_CACHES":
                    # Update cache configurations specifically
                    app_instance.config.INSANIC_CACHES.update(config_value)
                elif not hasattr(app_instance.config, attribute_name):
                    # Set only if not already defined in app config
                    setattr(app_instance.config, attribute_name, config_value)

    @classmethod
    def register_event_handlers(cls, app_instance) -> None:
        @app_instance.listener("after_server_start")
        async def initialize_circuit_state_on_startup(
            app, loop=None, **event_kwargs
        ):
            # Establish Redis connection for circuit breaker storage
            redis_client = await get_connection("infuse")
            connection = await redis_client

            # Generate namespace using environment and service name
            namespace_format = app.config.INFUSE_REDIS_KEY_NAMESPACE_TEMPLATE
            namespace = namespace_format.format(
                env=app.config.ENVIRONMENT,
                service_name=app.config.SERVICE_NAME
            )

            # Initialize circuit breaker storage with configured state
            await CircuitAioRedisStorage.initialize(
                state=app.config.INFUSE_INITIAL_CIRCUIT_STATE,
                redis_object=connection,
                namespace=namespace,
            )

    @classmethod
    def setup(cls, app_instance) -> None:
        """
        Main initialization method for Infuse integration.

        Performs the following steps:
        1. Loads Infuse-specific configuration parameters
        2. Registers startup listener to set initial circuit breaker state
        3. Applies patches to Service objects for circuit handling
        """
        cls.configure_application(app_instance)
        cls.register_event_handlers(app_instance)
        patch()

        # Notify framework of successful plugin initialization
        if hasattr(app_instance, "plugin_initialized"):
            app_instance.plugin_initialized("infuse", cls)

import json
import sys
import demistomock as demisto  # noqa: F401
from CommonServerPython import *  # noqa: F401

def fetch_asset_id_by_ip(ip_address):
    response = demisto.executeCommand("qualys-host-list", {"ips": ip_address})
    if isError(response[0]):
        demisto.results(response)
        sys.exit(0)

    host_data = response[0]
    if isinstance(host_data, dict) and 'Contents' in host_data:
        try:
            xml_content = host_data['Contents']
            if isinstance(xml_content, str):
                json_content = xml2json(xml_content)
                parsed_json = json.loads(json_content)
                asset_id = demisto.get(parsed_json, 'HOST_LIST_OUTPUT.RESPONSE.HOST_LIST.HOST.ID')
            else:
                asset_id = None
        except Exception:
            asset_id = None
    else:
        asset_id = demisto.get(host_data, 'Contents.HOST_LIST_OUTPUT.RESPONSE.HOST_LIST.HOST.ID')

    return asset_id

def main():
    incident_category = demisto.args().get("incidentType", "Vulnerability")
    max_bytes_to_read = int(demisto.args().get("maxFileSize", 1024 ** 2))
    severity_threshold = int(demisto.args().get("minSeverity", 1))

    file_info = demisto.getFilePath(demisto.args().get("entryID"))
    if not file_info or 'path' not in file_info:
        demisto.results({
            "Type": entryTypes["error"],
            "ContentsFormat": formats["text"],
            "Contents": 'File path not found for the provided entry ID'
        })
        sys.exit(0)

    with open(file_info['path'], 'r') as file_handle:
        raw_data = file_handle.read(max_bytes_to_read)

    if raw_data:
        try:
            report_structure = json.loads(xml2json(raw_data))
        except Exception:
            demisto.results({
                "Type": entryTypes["error"],
                "ContentsFormat": formats["text"],
                "Contents": 'Failed to parse XML data into JSON format'
            })
            sys.exit(0)

        report_timestamp = demisto.get(report_structure, "ASSET_DATA_REPORT.HEADER.GENERATION_DATETIME")

        # Extract assets
        assets = demisto.get(report_structure, "ASSET_DATA_REPORT.HOST_LIST.HOST")
        if not assets:
            demisto.results({
                "Type": entryTypes["note"],
                "ContentsFormat": formats["text"],
                "Contents": 'No vulnerable assets were found'
            })
            sys.exit(0)

        if not isinstance(assets, list):
            assets = [assets]

        # Process vulnerabilities
        all_vulns = argToList(
            demisto.get(report_structure, "ASSET_DATA_REPORT.GLOSSARY.VULN_DETAILS_LIST.VULN_DETAILS"))

        # Filter QIDs by minimum severity
        qualifying_qids = []
        for vuln in all_vulns:
            severity_val = demisto.get(vuln, 'SEVERITY')
            if severity_val is not None:
                try:
                    sev_int = int(severity_val)
                    if sev_int >= severity_threshold:
                        qid_val = demisto.get(vuln, "QID.#text")
                        if qid_val:
                            qualifying_qids.append(qid_val)
                except (ValueError, TypeError):
                    continue

        for target_asset in assets:
            ip_addr = demisto.get(target_asset, "IP")
            if not ip_addr:
                demisto.results({
                    "Type": entryTypes["error"],
                    "ContentsFormat": formats["text"],
                    "Contents": 'No IP was found for asset {0}'.format(str(target_asset))
                })
                sys.exit(0)

            asset_identifier = fetch_asset_id_by_ip(ip_addr)
            if not asset_identifier:
                demisto.results({
                    "Type": entryTypes["error"],
                    "ContentsFormat": formats["text"],
                    "Contents": 'No ID was found for asset {0}'.format(str(target_asset))
                })
                sys.exit(0)

            # Get vulnerabilities for this asset
            asset_vulns = argToList(demisto.get(target_asset, "VULN_INFO_LIST.VULN_INFO"))
            if not isinstance(asset_vulns, list):
                asset_vulns = [asset_vulns]

            # Extract QIDs from asset vulnerabilities
            asset_qids = [demisto.get(vuln, "QID.#text") for vuln in asset_vulns if demisto.get(vuln, "QID.#text")]

            # Intersect with qualifying QIDs
            relevant_qids = list(set(asset_qids) & set(qualifying_qids))

            for qid_code in relevant_qids:
                # Check for existing incidents (excluding closed ones)
                search_resp = demisto.executeCommand(
                    "getIncidents",
                    {"query": "vendorid: {0} and assetid: {1} and --status:Closed".format(qid_code, asset_identifier)}
                )

                if isError(search_resp[0]):
                    demisto.results(search_resp)
                    sys.exit(0)

                total_count = demisto.get(search_resp[0], "Contents.total")
                try:
                    incident_count = int(total_count) if total_count is not None else 0
                except (ValueError, TypeError):
                    demisto.results({
                        "Type": entryTypes["error"],
                        "ContentsFormat": formats["text"],
                        "Contents": 'Error while searching the incident repository'
                    })
                    sys.exit(0)

                if incident_count == 0:
                    # Create new incident
                    demisto.executeCommand("createNewIncident", {
                        "name": "Vulnerability - Asset {0} QID {1} - {2}".format(asset_identifier, qid_code, report_timestamp),
                        "vendorid": str(qid_code),
                        "type": incident_category,
                        "assetid": str(asset_identifier)
                    })

        demisto.results("Done.")
    else:
        demisto.results({
            "Type": entryTypes["error"],
            "ContentsFormat": formats["text"],
            "Contents": 'No data could be read.'
        })

