from typing import Optional, List, Any, get_origin
from inspect import signature, isclass, iscoroutinefunction
from functools import wraps
from http import HTTPStatus
from aiohttp.hdrs import AUTHORIZATION
from aiohttp.web_request import Request
from aiohttp.web_response import Response
from aiohttp.web_exceptions import (
    HTTPException,
    HTTPBadRequest,
    HTTPUnauthorized,
)
from recc.access_control.acl import AccessControlList
from recc.core.context import Context
from recc.chrono.datetime import today
from recc.session.session import Session
from recc.session.session_ex import SessionEx
from recc.log.logging import recc_http_logger as logger
from recc.serialization.serialize import serialize_default
from recc.http.header.basic_auth import BasicAuth
from recc.http.header.bearer_auth import BearerAuth
from recc.access_control.policy import Policy
from recc.http.http_packet import HttpRequest, HttpResponse
from recc.http.http_payload import payload_to_object, request_payload_to_class
from recc.http.http_response import get_accept_type, get_encoding, create_response
from recc.http.http_status import (
    STATUS_BAD_REQUEST,
    STATUS_UNAUTHORIZED,
    STATUS_INTERNAL_SERVER_ERROR,
)
from recc.http import http_cache_keys as c
from recc.http import http_path_keys as p
from recc.variables.http import VERY_VERBOSE_DEBUGGING

ERROR_MESSAGE_ONLY_SINGLE_POLICIES = (
    "Group and project permissions cannot be checked at the same time."
)


def _is_serializable_instance_v2(obj: Any) -> bool:
    # Check for basic serializable types using isinstance checks in different order
    if isinstance(obj, (dict, str, int, list, float, bool)):
        return True
    return False


def _is_serializable_class_v2(cls: type) -> bool:
    # Use direct subclass check instead of multiple issubclass calls
    try:
        return issubclass(cls, (dict, str, int, list, float, bool))
    except TypeError:
        return False


async def _parameter_matcher_main_v2(
    handler_func,
    instance: Any,
    req: Request,
    acl: AccessControlList,
) -> Response:
    accept_header = get_accept_type(req)
    encoding_header = get_encoding(req)
    func_sig = signature(handler_func)
    param_names = list(func_sig.parameters.keys())

    args_list: List[Any] = []
    path_param_count = len(req.match_info)
    body_assigned = False
    group_name_var: Optional[str] = None
    project_name_var: Optional[str] = None
    verbose_logging = False

    ctx = req.get(c.context)
    if ctx:
        if isinstance(ctx, Context):
            cfg = ctx.config
            if cfg and cfg.developer and cfg.verbose >= VERY_VERBOSE_DEBUGGING:
                verbose_logging = True
        else:
            ctx = None

    if instance is None:
        argument_keys = param_names
    else:
        assert len(param_names) >= 1
        args_list.append(instance)
        argument_keys = param_names[1:]

    for key in argument_keys:
        param = func_sig.parameters[key]
        annotation_origin = get_origin(param.annotation)

        if annotation_origin is None:
            if isinstance(param.annotation, type):
                annotation_origin = param.annotation
            elif isinstance(param.annotation, str):
                mapping = {
                    "str": str,
                    "int": int,
                    "float": float,
                    "bytes": bytes,
                    "list": list,
                    "set": set,
                    "dict": dict,
                }
                annotation_origin = mapping.get(param.annotation)
                if annotation_origin is None:
                    raise NotImplementedError(f"Unknown annotation string: {param.annotation}")
            else:
                raise NotImplementedError(f"Unknown annotation type: {type(param.annotation).__name__}")

        assert annotation_origin is not None
        assert isinstance(annotation_origin, type)

        # Handle BasicAuth
        if issubclass(annotation_origin, BasicAuth):
            if AUTHORIZATION not in req.headers:
                raise HTTPBadRequest(reason=f"Missing {AUTHORIZATION} header")
            try:
                auth_value = req.headers[AUTHORIZATION]
                basic_auth = BasicAuth.decode_from_authorization_header(auth_value)
            except ValueError as e:
                raise HTTPBadRequest(reason=str(e))
            args_list.append(basic_auth)
            continue

        # Handle BearerAuth
        if issubclass(annotation_origin, BearerAuth):
            if AUTHORIZATION not in req.headers:
                raise HTTPBadRequest(reason=f"Missing {AUTHORIZATION} header")
            try:
                auth_value = req.headers[AUTHORIZATION]
                bearer_auth = BearerAuth.decode_from_authorization_header(auth_value)
            except ValueError as e:
                raise HTTPBadRequest(reason=str(e))
            args_list.append(bearer_auth)
            continue

        # Handle Request
        if issubclass(annotation_origin, Request):
            args_list.append(req)
            continue

        # Handle HttpRequest
        if issubclass(annotation_origin, HttpRequest):
            raw_data = await req.read()
            args_list.append(
                HttpRequest(
                    method=req.method,
                    path=req.path,
                    data=raw_data,
                    headers=req.headers,
                )
            )
            continue

        # Handle Session
        if issubclass(annotation_origin, Session):
            if c.session not in req:
                raise HTTPUnauthorized(reason=f"Missing session: {c.session}")
            args_list.append(req[c.session])
            continue

        # Handle SessionEx
        if issubclass(annotation_origin, SessionEx):
            if c.session not in req:
                raise HTTPUnauthorized(reason=f"Missing session: {c.session}")
            args_list.append(req[c.session])
            continue

        # Handle Path Parameters
        if path_param_count >= 1 and key in req.match_info:
            path_val = req.match_info[key]
            if key == p.group:
                group_name_var = path_val
            elif key == p.project:
                project_name_var = path_val
            args_list.append(path_val)
            path_param_count -= 1
            continue

        # Handle Body Parameter
        if not body_assigned:
            if _is_serializable_class_v2(annotation_origin):
                body_text = await req.text()
                body_obj = payload_to_object(req.headers, body_text)
            elif isclass(annotation_origin):
                body_obj = await request_payload_to_class(req, annotation_origin)
            else:
                body_obj = None

            if body_obj is not None:
                body_assigned = True
                if verbose_logging:
                    logger.debug(f"BODY: {str(body_obj)}")
                args_list.append(body_obj)
                continue

        args_list.append(None)

    # ACL validation
    if acl.exists():
        if not ctx:
            raise RuntimeError("Context does not exist")
        if c.session not in req:
            raise HTTPUnauthorized(reason=f"Session missing: {c.session}")
        sess = req[c.session]
        assert isinstance(sess, SessionEx)
        if not sess.is_admin:
            if acl.admin:
                raise PermissionError("Admin privileges required")
            if acl.groups and acl.projects:
                raise RuntimeError(ERROR_MESSAGE_ONLY_SINGLE_POLICIES)
            if acl.groups:
                await acl.test_groups(ctx, sess, group_name_var)
            else:
                assert acl.projects
                await acl.test_projects(ctx, sess, group_name_var, project_name_var)

    # Execute handler
    if iscoroutinefunction(handler_func):
        result = await handler_func(*args_list)
    else:
        result = handler_func(*args_list)

    # Logging and response formatting
    if verbose_logging:
        logger.debug(f"RESULT: {str(result)}")

    if result is None:
        return Response()
    elif isinstance(result, Response):
        return result
    elif isinstance(result, HttpResponse):
        status_code = result.status if result.status else HTTPStatus.INTERNAL_SERVER_ERROR
        return Response(
            body=result.data,
            status=status_code,
            reason=result.reason,
            headers=result.headers,
        )
    elif _is_serializable_instance_v2(result):
        return create_response(accept_header, encoding_header, result)
    elif isclass(type(result)):
        return create_response(accept_header, encoding_header, serialize_default(result))

    raise NotImplementedError


async def parameter_matcher_main_v2(
    handler_func,
    instance: Any,
    req: Request,
    group_policies: Optional[List[Policy]] = None,
    project_policies: Optional[List[Policy]] = None,
    required_features: Optional[List[str]] = None,
    requires_admin=False,
) -> Response:
    start_time = today()

    remote_addr = req.remote
    http_method = req.method
    request_path = req.path
    http_version = req.version
    request_desc = f"{remote_addr} {http_method} {request_path} HTTP/{http_version[0]}.{http_version[1]}"

    try:
        acl = AccessControlList(
            handler_func,
            group_policies,
            project_policies,
            required_features,
            requires_admin,
        )
        response = await _parameter_matcher_main_v2(handler_func, instance, req, acl)
    except HTTPException as exc:
        logger.error(exc)
        response = Response(
            status=exc.status,
            reason=exc.reason,
            text=exc.text,
            headers=exc.headers,
        )
    except (ValueError, KeyError) as exc:
        logger.exception(exc)
        response = Response(status=STATUS_BAD_REQUEST, reason=str(exc))
    except PermissionError as exc:
        logger.exception(exc)
        response = Response(status=STATUS_UNAUTHORIZED, reason=str(exc))
    except BaseException as exc:
        logger.exception(exc)
        response = Response(status=STATUS_INTERNAL_SERVER_ERROR, reason=str(exc))

    status_code = response.status
    reason_phrase = response.reason
    elapsed_time = (today() - start_time).total_seconds()
    response_desc = f"{status_code} {reason_phrase} ({elapsed_time:.3f}s)"
    logger.info(f"{request_desc} -> {response_desc}")
    return response


def parameter_matcher_v2(
    *,
    group_policies: Optional[List[Policy]] = None,
    project_policies: Optional[List[Policy]] = None,
    required_features: Optional[List[str]] = None,
    requires_admin=False,
):
    if group_policies and project_policies:
        raise RuntimeError(ERROR_MESSAGE_ONLY_SINGLE_POLICIES)

    def decorator(func):
        @wraps(func)
        async def wrapper(instance, request):
            return await parameter_matcher_main_v2(
                func,
                instance,
                request,
                group_policies,
                project_policies,
                required_features,
                requires_admin,
            )
        return wrapper
    return decorator

# Custom Django models for thermostat management with recurring triggers

from datetime import timedelta
from django.core.validators import MaxValueValidator, MinValueValidator
from django.db import models
from django.utils import timezone

# Date/time formatting constants
DATETIME_FULL_FORMAT = "%d.%m.%Y at %H:%M"
TIME_ONLY_FORMAT = "%H:%M"

class TimestampedModel(models.Model):
    """Abstract base model providing self-updating timestamps."""
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        abstract = True

class Thermostat(TimestampedModel):
    """Represents a physical or virtual thermostat device."""
    ain = models.CharField(max_length=64)
    name = models.CharField(max_length=128, default="", blank=True)

    def __str__(self):
        return self.name or self.ain

class ThermostatLog(TimestampedModel):
    """Records individual temperature readings and trigger events."""
    thermostat = models.ForeignKey(
        "triggers.Thermostat", 
        related_name="logs", 
        on_delete=models.CASCADE
    )
    trigger = models.ForeignKey(
        "triggers.Trigger", 
        null=True, 
        related_name="logs", 
        on_delete=models.CASCADE
    )
    triggered_at = models.TimeField(blank=True, null=True)
    temperature = models.FloatField()
    no_op = models.BooleanField(default=False)
    """When True, no actual request was sent as temperature already matched."""

    def __str__(self):
        return f"{self.thermostat}: {self.trigger}"

class Trigger(TimestampedModel):
    """Defines temperature thresholds and scheduling rules for thermostat control."""
    thermostat = models.ForeignKey("triggers.Thermostat", on_delete=models.CASCADE)
    name = models.CharField(max_length=128, default="", blank=True)
    time = models.DateTimeField()
    temperature = models.FloatField(
        validators=[
            MinValueValidator(0.0),
            MaxValueValidator(28.0),
        ],
    )
    enabled = models.BooleanField(default=True)

    # Recurrence flags for each day of the week
    recur_on_monday = models.BooleanField(default=False)
    recur_on_tuesday = models.BooleanField(default=False)
    recur_on_wednesday = models.BooleanField(default=False)
    recur_on_thursday = models.BooleanField(default=False)
    recur_on_friday = models.BooleanField(default=False)
    recur_on_saturday = models.BooleanField(default=False)
    recur_on_sunday = models.BooleanField(default=False)

    @property
    def weekly_schedule(self):
        """Returns tuple of recurrence flags in order from Monday to Sunday."""
        return (
            self.recur_on_monday,
            self.recur_on_tuesday,
            self.recur_on_wednesday,
            self.recur_on_thursday,
            self.recur_on_friday,
            self.recur_on_saturday,
            self.recur_on_sunday,
        )

    @property
    def weekday_names(self):
        """Returns tuple of abbreviated weekday names."""
        return (
            "Mon",
            "Tue",
            "Wed",
            "Thu",
            "Fri",
            "Sat",
            "Sun",
        )

    @property
    def is_recurring(self):
        """Checks if trigger is scheduled for any day of the week."""
        return any(self.weekly_schedule)

    def occurs_on_weekday(self, day_index: int) -> bool:
        """Determines whether trigger occurs on a specific weekday (0=Monday)."""
        day_map = {index: flag for index, flag in enumerate(self.weekly_schedule)}
        return day_map.get(day_index, False)

    def get_local_time(self) -> timezone.datetime:
        """Converts stored time to local timezone."""
        return timezone.localtime(self.time)

    def format_time_display(self, date_format: str = DATETIME_FULL_FORMAT) -> str:
        """Formats the trigger time according to specified format."""
        naive_time = timezone.make_naive(self.get_local_time())
        return naive_time.strftime(date_format)

    def get_schedule_description(self) -> str:
        """Generates human-readable description of recurring schedule."""
        active_days = [
            label
            for idx, label in enumerate(self.weekday_names)
            if self.occurs_on_weekday(idx)
        ]

        time_str = self.format_time_display(TIME_ONLY_FORMAT)

        if not active_days:
            return f"Once at {time_str}"

        return f"{', '.join(active_days)} at {time_str}"

    def executed_recently(self, minutes: int) -> bool:
        """Checks if trigger has been executed within specified time window."""
        cutoff = timezone.now() - timedelta(minutes=minutes)
        return self.logs.filter(triggered_at__gte=cutoff).exists()

    def __str__(self):
        formatted_time = self.format_time_display(TIME_ONLY_FORMAT)
        return f"{self.thermostat.name} at {formatted_time} → {self.temperature}°C"

import inspect
import random
from typing import Optional
from redbot.core import commands
from redbot.core.utils.chat_formatting import bold, box

class TextProcessor(str):
    """A class for processing and manipulating text strings."""

    def _charcount(self, count_spaces: bool):
        if count_spaces:
            return f"Character count (with spaces): {bold(str(len(self)))}"
        # Count characters excluding spaces
        non_space_chars = sum(1 for c in self if c != ' ')
        return f"Character count: {bold(non_space_chars)}"

    def _wordcount(self):
        # Split by whitespace and filter out empty strings
        words = [word for word in self.split() if word]
        return f"Word count: {bold(len(words))}"

    def _occurance(self, check):
        counter = self.count(check)
        plural_check = "once" if counter == 1 else f"{counter} times"
        return f"`{check}` is present in the text {bold(plural_check)}."

    def _snake(self):
        return box(self.replace(" ", "_"))

    def _alternating(self):
        result = []
        for idx, char in enumerate(self):
            if idx % 2 == 0:
                result.append(char.upper())
            else:
                result.append(char.lower())
        return box("".join(result))

    def _replace(self, old_text, new_text):
        return box(self.replace(old_text, new_text))

    def _squash(self):
        return box("".join(self.split()))

    def _remove(self, to_remove):
        return box(self.replace(to_remove, ""))

    def _trim(self, chars_to_strip):
        return box(self.strip(chars_to_strip).strip())

    def _shuffle(self):
        words = self.split()
        random.shuffle(words)
        return box(" ".join(words))

    def _reverse(self):
        return box(self[::-1])

    def _multiply(self, times):
        return box(self * times)

