import sys

def compute_dot_product(vec1, vec2):
    assert len(vec1) == len(vec2)
    total = 0
    for idx in range(len(vec1)):
        total += vec1[idx] * vec2[idx]
    return total

def get_perpendicular_2d(vector):
    # Returns vector rotated 90 degrees counterclockwise
    return (-vector[1], vector[0])

def check_possible_state(q_vals, p_vals):
    # Check if both upward and downward directions exist
    has_upward = q_vals[1] or p_vals[0]
    has_downward = q_vals[2] or p_vals[1]
    return has_upward and has_downward

def check_impossible_state(q_vals, p_vals):
    # Check if only one vertical direction exists OR no leftward direction
    has_any_up = q_vals[0] or q_vals[1] or p_vals[0]
    has_any_down = q_vals[2] or q_vals[3] or p_vals[1]

    if has_any_up ^ has_any_down:
        return True

    has_left = q_vals[1] or q_vals[2]
    if not has_left:
        return True

    return False

def determine_solution(num_vectors, vector_list):
    # Convert original vectors to displacement vectors
    displacement_vectors = [(v[1] - v[0], v[2] - v[0]) for v in vector_list]

    # Start with first displacement vector as x-axis reference
    current_x_axis = displacement_vectors[0]

    while current_x_axis:
        # Define y-axis as perpendicular to current x-axis
        current_y_axis = get_perpendicular_2d(current_x_axis)

        # Initialize quadrant flags and axis flags
        quadrant_flags = [False] * 4
        axis_flags = [False] * 2
        candidate_vectors = [None] * 2

        # Process each vector in the set
        for vec in displacement_vectors:
            # Project onto current coordinate system
            proj_x = compute_dot_product(vec, current_x_axis)
            proj_y = compute_dot_product(vec, current_y_axis)

            if proj_x == 0:
                # Vector is parallel to y-axis
                if proj_y < 0:
                    axis_flags[1] = True
                elif proj_y > 0:
                    axis_flags[0] = True
            elif proj_x > 0:
                # Vector is in right half-plane
                if proj_y > 0:
                    quadrant_flags[0] = True
                    candidate_vectors[0] = vec
                elif proj_y < 0:
                    quadrant_flags[3] = True
            else:
                # Vector is in left half-plane
                if proj_y > 0:
                    quadrant_flags[1] = True
                    candidate_vectors[1] = vec
                elif proj_y < 0:
                    quadrant_flags[2] = True
                else:
                    # Found opposite vector to x-axis
                    return True

            # Check if solution is already possible
            if check_possible_state(quadrant_flags, axis_flags):
                return True

        # Check if solution is impossible
        if check_impossible_state(quadrant_flags, axis_flags):
            return False

        # Select next x-axis from candidates
        assert candidate_vectors[0] is not None or candidate_vectors[1] is not None

        if candidate_vectors[1] is not None:
            current_x_axis = candidate_vectors[1]
        else:
            current_x_axis = candidate_vectors[0]

    return True

# Test cases from original code
assert determine_solution(4, [[1, 2, 3], [1, 11, 5], [9, 4, 3], [2, 3, 2]])
assert determine_solution(3, [[5, 3, 1], [1, 2, 2], [2, 1, 1]])
assert not determine_solution(4, [[1, 3, 3], [1, 11, 5], [9, 4, 3], [2, 3, 2]])
assert determine_solution(2, [[1, 2, 2], [2, 1, 1]])

# Main input processing
for line in sys.stdin:
    n = int(line.strip())
    if n == 0:
        break
    packages = [list(map(int, next(sys.stdin).split())) for _ in range(n)]
    if determine_solution(n, packages):
        print("Yes")
    else:
        print("No")

import abc
import datetime
import typing
from typing import Any, Callable, Optional, Union
from systemlink.clients import core, tag as tbase
from systemlink.clients.core._internal._timestamp_utilities import TimestampUtilities
from systemlink.clients.tag._core._serialized_tag_with_aggregates import (
    SerializedTagWithAggregates,
)
from typing_extensions import Literal

# Mapping from data types to deserialization functions (renamed and restructured)
_DESERIALIZATION_MAP = {
    tbase.DataType.BOOLEAN: lambda s: {"True": True, "False": False}.get(s),
    tbase.DataType.DATE_TIME: TimestampUtilities.str_to_datetime,
    tbase.DataType.DOUBLE: float,
    tbase.DataType.INT32: int,
    tbase.DataType.UINT64: int,
    tbase.DataType.STRING: str,
}


class _AbstractTagReaderOverloads(abc.ABC):
    """Internal base class for overload definitions used by type checkers.

    This class exposes method overloads for get_tag_reader so that mypy can
    infer correct return types based on the data_type argument. It is hidden
    from documentation tools like Sphinx due to known limitations with overload
    support in those tools.
    """

    @typing.overload
    def acquire_reader(
        self, tag_path: str, dtype: Literal[tbase.DataType.BOOLEAN]
    ) -> "tbase.TagValueReader[bool]":
        ...

    @typing.overload
    def acquire_reader(
        self, tag_path: str, dtype: Literal[tbase.DataType.DATE_TIME]
    ) -> "tbase.TagValueReader[datetime.datetime]":
        ...

    @typing.overload
    def acquire_reader(
        self, tag_path: str, dtype: Literal[tbase.DataType.DOUBLE]
    ) -> "tbase.TagValueReader[float]":
        ...

    @typing.overload
    def acquire_reader(
        self, tag_path: str, dtype: Literal[tbase.DataType.INT32]
    ) -> "tbase.TagValueReader[int]":
        ...

    @typing.overload
    def acquire_reader(
        self, tag_path: str, dtype: Literal[tbase.DataType.UINT64]
    ) -> "tbase.TagValueReader[int]":
        ...

    @typing.overload
    def acquire_reader(
        self, tag_path: str, dtype: Literal[tbase.DataType.STRING]
    ) -> "tbase.TagValueReader[str]":
        ...

    @typing.overload
    def acquire_reader(
        self, tag_path: str, dtype: tbase.DataType
    ) -> "tbase.TagValueReader[Any]":
        ...

    def acquire_reader(
        self, tag_path: str, dtype: tbase.DataType
    ) -> "tbase.TagValueReader":
        """Acquire a reader instance for the specified tag path and data type."""
        return self._create_reader(tag_path, dtype)

    @abc.abstractmethod
    def _create_reader(
        self, tag_path: str, dtype: tbase.DataType
    ) -> "tbase.TagValueReader":
        """Factory method to instantiate a TagValueReader for given parameters."""
        ...


class TagReader(_AbstractTagReaderOverloads):
    """Interface for reading current and aggregate values of SystemLink tags."""

    def fetch_value(
        self,
        tag_path: str,
        *,
        include_time: bool = False,
        include_stats: bool = False
    ) -> Optional[tbase.TagWithAggregates]:
        """Fetch the latest value of a tag by its path.

        Optionally includes timestamp and/or statistical aggregates if configured.
        Raises exceptions on invalid input or server errors.
        """
        raw_data = self._fetch_raw(tag_path, include_time, include_stats)
        if not raw_data or raw_data.value is None:
            return None

        parsed_val = self._convert(raw_data.value, raw_data.data_type)
        if parsed_val is None:
            raise core.ApiException()

        return tbase.TagWithAggregates(
            raw_data.path,
            raw_data.data_type,
            parsed_val,
            raw_data.timestamp,
            raw_data.count,
            self._convert(raw_data.min, raw_data.data_type),
            self._convert(raw_data.max, raw_data.data_type),
            raw_data.mean,
        )

    async def fetch_value_async(
        self,
        tag_path: str,
        *,
        include_time: bool = False,
        include_stats: bool = False
    ) -> Optional[tbase.TagWithAggregates]:
        """Async version of fetch_value."""
        raw_data = await self._fetch_raw_async(tag_path, include_time, include_stats)
        if not raw_data or raw_data.value is None:
            return None

        parsed_val = self._convert(raw_data.value, raw_data.data_type)
        if parsed_val is None:
            raise core.ApiException()

        return tbase.TagWithAggregates(
            raw_data.path,
            raw_data.data_type,
            parsed_val,
            raw_data.timestamp,
            raw_data.count,
            self._convert(raw_data.min, raw_data.data_type),
            self._convert(raw_data.max, raw_data.data_type),
            raw_data.mean,
        )

    @abc.abstractmethod
    def _fetch_raw(
        self, tag_path: str, include_time: bool, include_stats: bool
    ) -> Optional[SerializedTagWithAggregates]:
        """Low-level method to retrieve raw serialized tag data."""
        ...

    @abc.abstractmethod
    async def _fetch_raw_async(
        self, tag_path: str, include_time: bool, include_stats: bool
    ) -> Optional[SerializedTagWithAggregates]:
        """Low-level async method to retrieve raw serialized tag data."""
        ...

    @classmethod
    def _convert(cls, val_str: Optional[str], dtype: tbase.DataType) -> Any:
        """Convert a string representation to the appropriate Python type."""
        if val_str is None:
            return None

        try:
            converter = _DESERIALIZATION_MAP[dtype]
        except KeyError:
            raise ValueError("Unsupported data type")

        try:
            result = converter(val_str)
            # Handle special case where boolean deserializer returns None for unknown strings
            if result is None and dtype == tbase.DataType.BOOLEAN:
                return None
            return result
        except (ValueError, TypeError):
            return None

    def _create_reader(
        self, tag_path: str, dtype: tbase.DataType
    ) -> "tbase.TagValueReader":
        """Create and return a new TagValueReader instance."""
        return tbase.TagValueReader(self, tbase.TagData(tag_path, dtype))

# Calculate the product of oxygen generator rating and CO2 scrubber rating

from typing import List
from aoc.day03_1 import yield_lines

def determine_rating(is_oxygen: bool, candidates: List[List[int]]) -> int:
    bit_position = 1
    while len(candidates) > 1:
        zero_group = []
        one_group = []

        for candidate in candidates:
            if candidate[bit_position] == 0:
                zero_group.append(candidate)
            else:
                one_group.append(candidate)

        if is_oxygen:
            # For oxygen: keep numbers with the most common bit (or 1 if tie)
            candidates = zero_group if len(zero_group) > len(one_group) else one_group
        else:
            # For CO2: keep numbers with the least common bit (or 0 if tie)
            candidates = one_group if len(zero_group) > len(one_group) else zero_group

        bit_position += 1

    # Convert binary list to decimal integer
    return int("".join(map(str, candidates[0])), 2)

def compute_ratings():
    initial_zeroes = []
    initial_ones = []

    # Separate lines based on first bit
    for line in yield_lines():
        if line[0] == 0:
            initial_zeroes.append(line)
        else:
            initial_ones.append(line)

    # Determine starting groups for each rating type
    oxygen_candidates = initial_zeroes if len(initial_zeroes) >= len(initial_ones) else initial_ones
    co2_candidates = initial_ones if oxygen_candidates is initial_zeroes else initial_zeroes

    # Calculate both ratings and multiply
    oxygen_rating = determine_rating(True, oxygen_candidates)
    co2_rating = determine_rating(False, co2_candidates)

    return oxygen_rating * co2_rating

if __name__ == "__main__":
    print(compute_ratings())

"""
Exception classes for UWS error handling, mapping to specific error codes
and HTTP status codes as defined in the SODA standard.
"""
from __future__ import annotations
from typing import Dict, Optional
from .models import ErrorCode, ErrorType, JobError

__all__ = [
    "UWSErrorBase",
    "MultiValueParamIssue",
    "AccessRestriction",
    "BackgroundProcessFailure",
    "FatalProcessIssue",
    "TemporaryProcessIssue",
    "APIUsageMistake",
    "MissingDataset",
    "PhaseMismatch",
    "InvalidParameterValue",
    "NoSuchJob",
]


class UWSErrorBase(Exception):
    """Base exception with associated error code and HTTP status.

    Implements SODA's requirement that errors be formatted as plain text
    starting with an error code. Used throughout the UWS layer for consistent
    error responses.
    """
    def __init__(
        self,
        code: ErrorCode,
        msg: str,
        extra_details: Optional[str] = None,
    ) -> None:
        super().__init__(msg)
        self.code = code
        self.details = extra_details
        self.http_status = 400


class MultiValueParamIssue(UWSErrorBase):
    """Raised when multiple values provided for a single-value parameter."""
    def __init__(self, description: str) -> None:
        super().__init__(ErrorCode.MULTIVALUED_PARAM_NOT_SUPPORTED, description)
        self.http_status = 422


class AccessRestriction(UWSErrorBase):
    """User lacks required permissions for requested operation."""
    def __init__(self, description: str) -> None:
        super().__init__(ErrorCode.AUTHORIZATION_ERROR, description)
        self.http_status = 403


class BackgroundProcessFailure(UWSErrorBase):
    """Generic exception for failures during background task execution."""

    @classmethod
    def reconstruct_from_callback(cls, exc_info: Dict[str, str]) -> BackgroundProcessFailure:
        """Rebuild exception from callback data.

        Notes
        -----
        The dramatiq Callbacks middleware only provides type and message as strings,
        so we parse the structured information from the exception body.
        """
        exc_type = exc_info["type"]
        exc_msg = exc_info["message"]
        detail = None

        if exc_type in ("FatalProcessIssue", "TemporaryProcessIssue"):
            try:
                code_str, remainder = exc_msg.split(None, 1)
                parsed_code = ErrorCode(code_str)
                if "\n" in remainder:
                    short_msg, detail = remainder.split("\n", 1)
                else:
                    short_msg = remainder
            except Exception:
                parsed_code = ErrorCode.ERROR
                short_msg = exc_msg

            if exc_type == "FatalProcessIssue":
                return FatalProcessIssue(parsed_code, short_msg, detail)
            else:
                return TemporaryProcessIssue(parsed_code, short_msg, detail)
        else:
            return cls(
                ErrorType.TRANSIENT,
                ErrorCode.ERROR,
                "Unknown background task failure",
                f"{exc_type}: {exc_msg}",
            )

    def __init__(
        self,
        kind: ErrorType,
        code: ErrorCode,
        description: str,
        extra_details: Optional[str] = None,
    ) -> None:
        super().__init__(code, description, extra_details)
        self.kind = kind

    def to_job_error(self) -> JobError:
        """Convert to standardized job error model."""
        return JobError(
            error_code=self.code,
            error_type=self.kind,
            message=str(self),
            detail=self.details,
        )


class FatalProcessIssue(BackgroundProcessFailure):
    """Critical failure indicating job will never succeed regardless of retry."""
    def __init__(
        self,
        code: ErrorCode,
        description: str,
        extra_details: Optional[str] = None,
    ) -> None:
        super().__init__(ErrorType.FATAL, code, description, extra_details)


class TemporaryProcessIssue(BackgroundProcessFailure):
    """Non-critical failure allowing potential job retry with same parameters."""
    def __init__(
        self,
        code: ErrorCode,
        description: str,
        extra_details: Optional[str] = None,
    ) -> None:
        super().__init__(ErrorType.TRANSIENT, code, description, extra_details)


class APIUsageMistake(UWSErrorBase):
    """Improper use of UWS API endpoints or parameters."""
    def __init__(self, description: str, extra_details: Optional[str] = None) -> None:
        super().__init__(ErrorCode.USAGE_ERROR, description, extra_details)
        self.http_status = 422


class MissingDataset(UWSErrorBase):
    """Requested data resource does not exist for the specified job."""
    def __init__(self, description: str) -> None:
        super().__init__(ErrorCode.USAGE_ERROR, description)
        self.http_status = 404


class PhaseMismatch(APIUsageMistake):
    """Operation attempted on job in inappropriate phase."""


class InvalidParameterValue(APIUsageMistake):
    """Parameter received unsupported value."""


class NoSuchJob(MissingDataset):
    """Specified job identifier not found in system."""
    def __init__(self, job_id: str) -> None:
        super().__init__(f"Job {job_id} not found")
        self.identifier = job_id

import logging
from configparser import DuplicateSectionError, NoSectionError
import api_interface
from api_interface import APIInterface
from config_handler import ConfigHandler
from user_input import get_user_input

# Configure logger
logging.basicConfig(format="%(levelname)s: %(message)s", level=logging.INFO)


class YNAB_API:
    """
    Manages interaction with YNAB API using Personal Access Token from configuration.
    (Note for developers: safeguard your API token!)
    """

    def __init__(self, config_obj: ConfigHandler, transactions=None) -> None:
        self.transactions = []
        self.budget_id = None
        self.config = config_obj
        self.token = self.config.config.get("DEFAULT", "YNAB API Access Token")
        self.user_cfg = ConfigHandler(user_mode=True)
        self.user_cfg_path = self.user_cfg.user_conf_path
        self.debug_mode = False

    def execute(self, tx_data: dict[str, list]) -> None:
        logging.debug(f"Raw transaction data: {tx_data}")
        # Retrieve existing bank-to-account mappings
        current_mappings = self._fetch_existing_mappings(tx_data)

        # Fetch live budget & account info via API
        connector = APIInterface(api_token=self.token)
        budget_metadata = connector.budget_info

        # Filter out obsolete mappings
        cleaned_mappings = self._filter_stale_accounts(
            current_mappings, budget_metadata
        )

        # Prompt user to resolve missing mappings
        self._resolve_missing_accounts(cleaned_mappings, budget_metadata)

        # Persist updated mappings
        self._store_account_mappings(cleaned_mappings)

        # Enrich transactions with budget/account IDs
        enriched_txs = self._enrich_transactions_with_ids(tx_data, cleaned_mappings)

        # Upload per-budget transaction batches
        for bid in budget_metadata:
            try:
                api_interface.post_transactions(
                    api_token=self.token,
                    budget_id=bid,
                    data=enriched_txs[bid]["transactions"],
                )
            except KeyError:
                logging.info(
                    f"No transactions to upload for '{budget_metadata[bid]['name']}'."
                )

    def _fetch_existing_mappings(self, tx_data: dict) -> dict[str, dict[str, str]]:
        bank_map = {}
        for bank in tx_data.keys():
            acc_id = ""
            bud_id = ""
            try:
                parts = self.config.get_config_line_lst(
                    bank, "YNAB Account ID", "||"
                )
                bud_id, acc_id = parts[0], parts[1]
                logging.info(f"Found saved mapping for '{bank}'.")
            except IndexError:
                pass
            except NoSectionError:
                logging.info(f"No prior config found for '{bank}'.")
            bank_map.setdefault(bank, {"account_id": acc_id, "budget_id": bud_id})
        return bank_map

    def _store_account_mappings(self, mappings: dict[str, dict]) -> None:
        for bank in mappings:
            should_save = self.config.get_config_line_boo(
                bank, "Save YNAB Account"
            )
            if should_save:
                self._write_account_selection(
                    bank,
                    mappings[bank]["budget_id"],
                    mappings[bank]["account_id"],
                )
            else:
                logging.info(
                    f"Skipping save for '{bank}' — user disabled auto-save."
                )

    def _write_account_selection(self, bank, budget_id, account_id):
        self.user_cfg.config.read(self.user_cfg_path)
        try:
            self.user_cfg.config.add_section(bank)
            logging.info(f"Saving default mapping for '{bank}'...")
        except DuplicateSectionError:
            pass
        self.user_cfg.config.set(
            bank, "YNAB Account ID", f"{budget_id}||{account_id}"
        )
        with open(self.user_cfg_path, "w", encoding="utf-8") as cfg_file:
            self.user_cfg.config.write(cfg_file)

    def _filter_stale_accounts(
        self, old_map: dict[str, dict[str, str]], api_data: dict[str, dict]
    ) -> dict[str, dict[str, str]]:
        result = dict(old_map)
        for bank in list(old_map):
            bid = old_map[bank]["budget_id"]
            aid = old_map[bank]["account_id"]
            try:
                if bid not in api_data or aid not in api_data[bid]["accounts"]:
                    raise KeyError
            except KeyError:
                result[bank] = {"account_id": "", "budget_id": ""}
        return result

    def _resolve_missing_accounts(
        self, mappings: dict[str, dict[str, str]], budget_info: dict[str, dict]
    ):
        for bank in mappings:
            if not mappings[bank]["account_id"]:
                bud_id, acc_id = self._prompt_for_mapping(bank, budget_info)
                mappings[bank]["budget_id"] = bud_id
                mappings[bank]["account_id"] = acc_id

    def _prompt_for_mapping(self, bank_name: str, budget_info: dict[str, dict]):
        bud_id = acc_id = ""
        prompt_template = "No YNAB {} for {} — please select {}:"
        # Step 1: Choose budget
        msg = prompt_template.format("budget", bank_name, "a budget")
        bud_list = self._build_selection_list(budget_info)
        bud_id = get_user_input(bud_list, msg)

        # Step 2: Choose account within selected budget
        accounts_in_budget = budget_info[bud_id]["accounts"]
        msg = prompt_template.format("account", bank_name, "an account")
        acc_list = self._build_selection_list(accounts_in_budget)
        acc_id = get_user_input(acc_list, msg)

        return bud_id, acc_id

    def _build_selection_list(self, data: dict) -> list[list[str]]:
        return [[data[key]["name"], key] for key in data]

    def _enrich_transactions_with_ids(
        self, tx_data: dict[str, list], mapping: dict[str, dict[str, str]]
    ) -> dict[str, dict[str, list]]:
        logging.info("Attaching budget & account IDs to transactions...")
        final_dict: dict[str, dict[str, list]] = {}

        for bank in tx_data:
            txns = tx_data[bank]
            bud_id = mapping[bank]["budget_id"]
            acc_id = mapping[bank]["account_id"]

            # Augment each transaction
            for txn in txns:
                txn["account_id"] = acc_id

            # Aggregate by budget ID
            if bud_id in final_dict:
                final_dict[bud_id]["transactions"].extend(txns)
            else:
                final_dict[bud_id] = {"transactions": txns.copy()}

        return final_dict

import os
import re
from collections import OrderedDict
import random
from classes.gameitem import GameItem
from fs_helpers import *

def distribute_items(self):
    print("Distributing items...")

    if self.options.get("race_mode"):
        assign_boss_prizes(self)

    if not self.options.get("keylunacy"):
        assign_dungeon_gear(self)

    assign_story_items(self)

    # Assign unique non-story items.
    while self.logic.unassigned_nonstory_items:
        reachable_available_spots = self.logic.get_reachable_remaining_spots()

        item_name = self.rng.choice(self.logic.unassigned_nonstory_items)

        suitable_spots = self.logic.filter_spots_appropriate_for_item(reachable_available_spots, item_name)

        if not suitable_spots:
            raise Exception("No appropriate spots left for non-story items!")

        chosen_spot = self.rng.choice(suitable_spots)
        self.logic.assign_item_to_spot(chosen_spot, item_name)

    reachable_available_spots = self.logic.get_reachable_remaining_spots()
    unreachable_spots = [spot for spot in self.logic.remaining_item_spots if spot not in reachable_available_spots]
    if unreachable_spots:
        print("Unreachable spots:")
        for spot_name in unreachable_spots:
            print(spot_name)

    # Fill remaining unused spots with consumables (Rupees, spoils, and bait).
    spots_for_consumables = self.logic.remaining_item_spots.copy()
    for spot_name in spots_for_consumables:
        viable_items = self.logic.filter_items_suitable_for_spot(self.logic.unassigned_fixed_consumable_items, spot_name)
        if len(viable_items) == 0:
            viable_items = self.logic.filter_items_suitable_for_spot(self.logic.duplicatable_consumable_items, spot_name)
            if len(viable_items) == 0:
                raise Exception("No suitable consumable items for spot %s" % spot_name)

        item_name = self.rng.choice(viable_items)
        self.logic.assign_item_to_spot(spot_name, item_name)

def assign_boss_prizes(self):
    # Attempt to generate dungeon boss prize locations until a valid configuration is found.
    for attempt in range(50):
        if attempt_boss_prize_assignment(self):
            return
    raise Exception("Cannot assign boss prizes! Please try with a different seed.")

def attempt_boss_prize_assignment(self):
    if not self.options.get("progression_dungeons"):
        raise Exception("Cannot assign boss prizes when story items are prohibited in dungeons.")

    prize_items = []
    total_prize_count = int(self.options.get("num_race_mode_dungeons"))

    unassigned_story_items_flat = []
    for item_name in self.logic.unassigned_story_items:
        if item_name in self.logic.story_item_groups:
            unassigned_story_items_flat += self.logic.story_item_groups[item_name]
        else:
            unassigned_story_items_flat.append(item_name)

    # Prioritize Triforce Shards for prizes.
    num_prizes_needed = total_prize_count
    triforce_shards = [
        item_name for item_name in unassigned_story_items_flat
        if item_name.startswith("Triforce Shard ")
    ]
    self.rng.shuffle(triforce_shards)
    prize_items += triforce_shards[0:num_prizes_needed]

    # If more prizes needed, use sword upgrades.
    num_additional_needed = total_prize_count - len(prize_items)
    if num_additional_needed > 0:
        sword_upgrades = [
            item_name for item_name in unassigned_story_items_flat
            if item_name == "Progressive Sword"
        ]
        prize_items += sword_upgrades[0:num_additional_needed]

    # If still need more, use bow upgrades.
    num_additional_needed = total_prize_count - len(prize_items)
    if num_additional_needed > 0:
        bow_upgrades = [
            item_name for item_name in unassigned_story_items_flat
            if item_name == "Progressive Bow"
        ]
        prize_items += bow_upgrades[0:num_additional_needed]

    extra_prizes_options = ["Hookshot", "Progressive Shield", "Boomerang"]

    # Finally, use Hookshot, Mirror Shield, and Boomerang if needed.
    num_additional_needed = total_prize_count - len(prize_items)
    if num_additional_needed > 0:
        extra_prizes = [
            item_name for item_name in unassigned_story_items_flat
            if item_name in extra_prizes_options
        ]
        prize_items += extra_prizes[0:num_additional_needed]

    self.rng.shuffle(prize_items)

    if len(prize_items) != total_prize_count:
        raise Exception("Incorrect number of boss prize items: " + ", ".join(prize_items))

    possible_boss_spots = [
        spot for spot in self.logic.remaining_item_spots
        if self.logic.item_spots[spot]["Original item"] == "Heart Container"
    ]

    if len(possible_boss_spots) != 6:
        raise Exception("Incorrect number of boss item spots: " + ", ".join(possible_boss_spots))

    boss_prize_assignments = OrderedDict()

    # Decide which prize goes in each boss spot.
    for item_name in prize_items:    
        if self.dungeons_only_start and "Dragon Roost Cavern - Gohma Heart Container" in possible_boss_spots:
            spot_name = "Dragon Roost Cavern - Gohma Heart Container"
        elif self.dungeons_only_start and "Forbidden Woods - Kalle Demos Heart Container" in possible_boss_spots:
            spot_name = "Forbidden Woods - Kalle Demos Heart Container"
        else:
            spot_name = self.rng.choice(possible_boss_spots)
        possible_boss_spots.remove(spot_name)
        boss_prize_assignments[spot_name] = item_name

    # Verify boss prize placements allow all prizes to be accessible.
    spots_valid = verify_boss_prize_spots(self, boss_prize_assignments)

    if not spots_valid:
        return False

    # Remove used Triforce Shards from progress groups and add as standalone items.
    for group_name, group_item_names in self.logic.story_item_groups.items():
        items_to_extract = [
            item_name for item_name in group_item_names
            if item_name in prize_items
        ]
        for item_name in items_to_extract:
            self.logic.story_item_groups[group_name].remove(item_name)
        if group_name in self.logic.unassigned_story_items:
            for item_name in items_to_extract:
                self.logic.unassigned_story_items.append(item_name)

        if len(self.logic.story_item_groups[group_name]) == 0:
            if group_name in self.logic.unassigned_story_items:
                self.logic.unassigned_story_items.remove(group_name)

    for spot_name, item_name in boss_prize_assignments.items():
        self.logic.assign_pre_randomized_item_spot(spot_name, item_name)
        self.race_mode_mandatory_spots.append(spot_name)

        dungeon_name, _ = self.logic.split_spot_name_by_zone(spot_name)
        self.race_mode_mandatory_dungeons.append(dungeon_name)

    forbidden_dungeons = []
    for boss_spot_name in possible_boss_spots:
        dungeon_name, _ = self.logic.split_spot_name_by_zone(boss_spot_name)
        forbidden_dungeons.append(dungeon_name)

    for spot_name in self.logic.item_spots:
        zone_name, _ = self.logic.split_spot_name_by_zone(spot_name)
        if self.logic.is_dungeon_spot(spot_name) and zone_name in forbidden_dungeons:
            self.race_mode_prohibited_spots.append(spot_name)
        elif spot_name == "Mailbox - Letter from Orca" and "Forbidden Woods" in forbidden_dungeons:
            self.race_mode_prohibited_spots.append(spot_name)
        elif spot_name == "Mailbox - Letter from Baito" and "Earth Temple" in forbidden_dungeons:
            self.race_mode_prohibited_spots.append(spot_name)
        elif spot_name == "Mailbox - Letter from Aryll" and "Forsaken Fortress" in forbidden_dungeons:
            self.race_mode_prohibited_spots.append(spot_name)
        elif spot_name == "Mailbox - Letter from Tingle" and "Forsaken Fortress" in forbidden_dungeons:
            self.race_mode_prohibited_spots.append(spot_name)

    return True

def verify_boss_prize_spots(self, boss_prize_assignments):
    boss_prize_items = list(boss_prize_assignments.values())

    # Temporarily acquire every item except boss prizes.
    items_to_temporarily_acquire = self.logic.unassigned_story_items.copy()

    for item_name in boss_prize_items:
        if item_name in items_to_temporarily_acquire:
            items_to_temporarily_acquire.remove(item_name)

    for item_name in items_to_temporarily_acquire:
        self.logic.add_acquired_item_or_group(item_name)

    spots_valid = True
    temporary_prize_items = []
    remaining_prize_items = boss_prize_items.copy()
    remaining_boss_spots = list(boss_prize_assignments.keys())

    while remaining_prize_items:
        reachable_available_spots = self.logic.get_reachable_remaining_spots()    
        inaccessible_dungeons = []
        for spot_name in self.logic.remaining_item_spots:
            if self.logic.is_dungeon_spot(spot_name) and spot_name not in reachable_available_spots:
                dungeon_name, _ = self.logic.split_spot_name_by_zone(spot_name)
                inaccessible_dungeons.append(dungeon_name)

        newly_accessible_boss_spots = []
        for boss_spot in remaining_boss_spots:
            dungeon_name, _ = self.logic.split_spot_name_by_zone(boss_spot)

            if dungeon_name not in inaccessible_dungeons:
                newly_accessible_boss_spots.append(boss_spot)

        if not newly_accessible_boss_spots:
            spots_valid = False
            break

        for spot_name in newly_accessible_boss_spots:
            item_name = boss_prize_assignments[spot_name]
            if item_name in self.logic.unassigned_story_items:
                self.logic.add_acquired_item_or_group(item_name)
            temporary_prize_items.append(item_name)
            remaining_prize_items.remove(item_name)
            remaining_boss_spots.remove(spot_name)

    for item_name in items_to_temporarily_acquire:
        self.logic.remove_acquired_item_or_group(item_name)
    for item_name in temporary_prize_items:
        if item_name in self.logic.currently_acquired_items:
            self.logic.remove_acquired_item_or_group(item_name)

    return spots_valid

def assign_dungeon_gear(self):
    # Assign dungeon-specific items first to prevent other items from occupying dungeon locations.

    items_to_temporarily_acquire = [
        item_name for item_name in (self.logic.unassigned_story_items + self.logic.unassigned_nonstory_items)
        if not self.logic.is_dungeon_item(item_name)
    ]
    for item_name in items_to_temporarily_acquire:
        self.logic.add_acquired_item_or_group(item_name)

    if self.dungeons_only_start:
        self.drc_emergency_spot = self.rng.choice([
            "Dragon Roost Cavern - First Room",
            "Dragon Roost Cavern - Alcove With Water Jugs",
            "Dragon Roost Cavern - Boarded Up Chest",
            "Dragon Roost Cavern - Rat Room",
            "Dragon Roost Cavern - Rat Room Boarded Up Chest",
            "Dragon Roost Cavern - Bird's Nest",
        ])

    small_keys = [
        item_name for item_name in (self.logic.unassigned_story_items + self.logic.unassigned_nonstory_items)
        if item_name.endswith(" Small Key")
    ]
    assert len(small_keys) > 0
    for item_name in small_keys:
        place_dungeon_item(self, item_name)
        self.logic.add_acquired_item(item_name)

    big_keys = [
        item_name for item_name in (self.logic.unassigned_story_items + self.logic.unassigned_nonstory_items)
        if item_name.endswith(" Big Key")
    ]
    assert len(big_keys) > 0
    for item_name in big_keys:
        place_dungeon_item(self, item_name)
        self.logic.add_acquired_item(item_name)

    other_dungeon_items = [
        item_name for item_name in (self.logic.unassigned_story_items + self.logic.unassigned_nonstory_items)
        if item_name.endswith(" Dungeon Map") or item_name.endswith(" Compass")
    ]
    for item_name in other_dungeon_items:
        place_dungeon_item(self, item_name)

    for item_name in items_to_temporarily_acquire:
        self.logic.remove_acquired_item_or_group(item_name)
    for item_name in small_keys:
        self.logic.remove_acquired_item(item_name)
    for item_name in big_keys:
        self.logic.remove_acquired_item(item_name)

def place_dungeon_item(self, item_name):
    reachable_available_spots = self.logic.get_reachable_remaining_spots()
    reachable_available_spots = [
        spot for spot in reachable_available_spots
        if spot not in self.logic.pre_randomized_item_spots
    ]
    if not self.options.get("progression_tingle_chests"):
        reachable_available_spots = [
            spot for spot in reachable_available_spots
            if not "Tingle Chest" in self.logic.item_spots[spot]["Types"]
        ]
    suitable_spots = self.logic.filter_spots_appropriate_for_item(reachable_available_spots, item_name)

    if self.dungeons_only_start and item_name == "DRC Small Key":
        suitable_spots = [
            spot for spot in suitable_spots
            if spot not in ["Dragon Roost Cavern - Big Key Chest", "Dragon Roost Cavern - Tingle Statue Chest"]
        ]
    if self.dungeons_only_start and item_name in ["DRC Big Key", "DRC Dungeon Map", "DRC Compass"]:
        suitable_spots = [
            spot for spot in suitable_spots
            if spot != self.drc_emergency_spot
        ]

    if not suitable_spots:
        raise Exception("No appropriate spots left for dungeon items!")

    chosen_spot = self.rng.choice(suitable_spots)
    self.logic.assign_pre_randomized_item_spot(chosen_spot, item_name)

def assign_story_items(self):
    reachable_available_spots = self.logic.get_reachable_remaining_spots(for_story=True)
    if len(reachable_available_spots) == 0:
        raise Exception("No story spots are accessible at the start!")

    spot_weights = {}
    current_weight = 1
    while self.logic.unassigned_story_items:
        reachable_available_spots = self.logic.get_reachable_remaining_spots(for_story=True)

        if not reachable_available_spots:
            raise Exception("No spots left for story items!")

        newly_accessible_predetermined_spots = [
            spot for spot in reachable_available_spots
            if spot in self.logic.pre_randomized_item_spots
        ]
        if newly_accessible_predetermined_spots:
            for predetermined_spot_name in newly_accessible_predetermined_spots:
                predetermined_item_name = self.logic.pre_randomized_item_spots[predetermined_spot_name]
                self.logic.assign_item_to_spot(predetermined_spot_name, predetermined_item_name)

            continue

        for spot in reachable_available_spots:
            if spot not in spot_weights:
                spot_weights[spot] = current_weight
            elif spot_weights[spot] > 1:
                spot_weights[spot] -= 1
        current_weight += 1

        available_items = self.logic.unassigned_story_items.copy()

        unfound_predetermined_spots = [
            spot for spot in self.logic.pre_randomized_item_spots
            if spot in self.logic.remaining_item_spots
        ]
        for spot_name in unfound_predetermined_spots:
            predetermined_item = self.logic.pre_randomized_item_spots[spot_name]
            if predetermined_item not in self.logic.all_story_items:
                continue
            available_items.remove(predetermined_item)

        if len(available_items) == 0:
            raise Exception("Only predetermined items remain at inaccessible spots!")

        available_items = self.logic.filter_items_by_any_valid_spot(available_items, reachable_available_spots)

        if len(available_items) == 0:
            raise Exception("No valid spots left for any unassigned story items!")

        unique_available_items = []
        for item_name in available_items:
            if item_name not in unique_available_items:
                unique_available_items.append(item_name)
        available_items = unique_available_items

        must_place_useful = False
        should_place_useful = True
        if len(reachable_available_spots) == 1 and len(available_items) > 1:
            must_place_useful = True
        elif len(reachable_available_spots) >= 17:
            should_place_useful = False

        possible_groups = [name for name in available_items if name in self.logic.story_item_groups]
        useless_groups = self.logic.get_all_useless_items(possible_groups)
        available_items_without_useless = [name for name in available_items if name not in useless_groups]
        if len(available_items_without_useless) == 0 and len(available_items) > 0:
            available_items_without_useless = available_items

        if must_place_useful or should_place_useful:
            shuffled_list = available_items.copy()
            self.rng.shuffle(shuffled_list)
            item_name = self.logic.get_first_useful_item(shuffled_list)
            if item_name is None:
                if must_place_useful:
                    raise Exception("No useful story items to place!")
                else:
                    item_by_usefulness_ratio = self.logic.get_items_by_usefulness_ratio(available_items_without_useless)

                    min_usefulness = min(item_by_usefulness_ratio.values())
                    items_at_min_usefulness = [
                        item_name for item_name, usefulness in item_by_usefulness_ratio.items()
                        if usefulness == min_usefulness
                    ]

                    item_name = self.rng.choice(items_at_min_usefulness)
        else:
            item_name = self.rng.choice(available_items_without_useless)

        if self.options.get("race_mode"):
            spots_filtered = [
                spot for spot in reachable_available_spots
                if spot not in self.race_mode_prohibited_spots
            ]
            if item_name in self.logic.story_item_groups:
                num_spots_needed = len(self.logic.story_item_groups[item_name])
            else:
                num_spots_needed = 1
            if len(spots_filtered) >= num_spots_needed:
                reachable_available_spots = spots_filtered
            else:
                raise Exception("Failed to prevent story items from appearing in unchosen dungeons for race mode.")

        if item_name in self.logic.story_item_groups:
            group_name = item_name
            possible_spots_for_group = reachable_available_spots.copy()
            self.rng.shuffle(possible_spots_for_group)
            self.logic.assign_multiple_spots_to_group(possible_spots_for_group, group_name)
        else:
            suitable_spots = self.logic.filter_spots_appropriate_for_item(reachable_available_spots, item_name)

            if item_name.startswith("Treasure Chart") or item_name.startswith("Triforce Chart"):
                suitable_spots_without_sunken = [
                    spot for spot in suitable_spots
                    if not "Sunken Treasure" in self.logic.item_spots[spot]["Types"]
                ]
                if suitable_spots_without_sunken:
                    suitable_spots = suitable_spots_without_sunken

            suitable_spots_weighted = []
            for spot_name in suitable_spots:
                weight = spot_weights[spot_name]
                suitable_spots_weighted += [spot_name]*weight

            chosen_spot = self.rng.choice(suitable_spots_weighted)
            self.logic.assign_item_to_spot(chosen_spot, item_name)

    for spot_name in self.logic.pre_randomized_item_spots:
        if spot_name in self.logic.remaining_item_spots:
            dungeon_item_name = self.logic.pre_randomized_item_spots[spot_name]
            self.logic.assign_item_to_spot(spot_name, dungeon_item_name)

    game_beatable = self.logic.check_requirement_met("Can Reach and Defeat Ganondorf")
    if not game_beatable:
        raise Exception("Game is not beatable on this seed! This error shouldn't occur.")

def update_items_in_world(self, world_id: int = 0):
    spots = self.worlds[world_id].spot_entries
    for spot in spots:
        for path in spot.filePaths:
            if spot.current_item.game_item_id == 0xB1:
                spot.current_item.game_item_id = GameItem.random_junk_id(self)
            if spot.current_item.world_id == -1:
                spot.current_item.world_id = world_id
            modify_item(self, path, spot.current_item.game_item_id, (spot.current_item.world_id + 1))

def modify_item(self, path: str, item_id: int, world_id: int = 0):

    rel_match = re.search(r"^(rels/[^.]+\.rel)@([0-9A-F]{4})$", path)
    main_dol_match = re.search(r"^main.dol@(8[0-9A-F]{7})$", path)
    custom_symbol_match = re.search(r"^CustomSymbol:(.+)$", path)
    chest_match = re.search(r"^([^/]+/[^/]+\.arc)(?:/Layer([0-9a-b]))?/Chest([0-9A-F]{3})$", path)
    event_match = re.search(r"^([^/]+/[^/]+\.arc)/Event([0-9A-F]{3}):[^/]+/Actor([0-9A-F]{3})/Action([0-9A-F]{3})$", path)
    scob_match = re.search(r"^([^/]+/[^/]+\.arc)(?:/Layer([0-9a-b]))?/ScalableObject([0-9A-F]{3})$", path)
    actor_match = re.search(r"^([^/]+/[^/]+\.arc)(?:/Layer([0-9a-b]))?/Actor([0-9A-F]{3})$", path)

    if rel_match:
        rel_path = rel_match.group(1)
        offset = int(rel_match.group(2), 16)
        path = os.path.join("files", rel_path)
        modify_hardcoded_item_in_rel(self, path, offset, item_id, world_id)
    elif main_dol_match:
        address = int(main_dol_match.group(1), 16)
        modify_hardcoded_item_in_dol(self, address, item_id, world_id)
    elif custom_symbol_match:
        custom_symbol = custom_symbol_match.group(1)
        found_custom_symbol = False
        for file_path, custom_symbols_for_file in self.custom_symbols.items():
            if custom_symbol in custom_symbols_for_file:
                found_custom_symbol = True
                if file_path == "sys/main.dol":
                    address = custom_symbols_for_file[custom_symbol]
                    modify_hardcoded_item_in_dol(self, address, item_id, world_id)
                else:
                    offset = custom_symbols_for_file[custom_symbol]
                    modify_hardcoded_item_in_rel(self, file_path, offset, item_id, world_id)
                break
        if not found_custom_symbol:
            raise Exception("Invalid custom symbol: %s" % custom_symbol)
    elif chest_match:
        arc_path = "files/res/Stage/" + chest_match.group(1)
        if chest_match.group(2):
            layer = int(chest_match.group(2), 16)
        else:
            layer = None
        chest_index = int(chest_match.group(3), 16)
        modify_chest_item(self, arc_path, chest_index, layer, item_id, world_id)
    elif event_match:
        arc_path = "files/res/Stage/" + event_match.group(1)
        event_index = int(event_match.group(2), 16)
        actor_index = int(event_match.group(3), 16)
        action_index = int(event_match.group(4), 16)
        modify_event_item(self, arc_path, event_index, actor_index, action_index, item_id, world_id)
    elif scob_match:
        arc_path = "files/res/Stage/" + scob_match.group(1)
        if scob_match.group(2):
            layer = int(scob_match.group(2), 16)
        else:
            layer = None
        scob_index = int(scob_match.group(3), 16)
        modify_scob_item(self, arc_path, scob_index, layer, item_id, world_id)
    elif actor_match:
        arc_path = "files/res/Stage/" + actor_match.group(1)
        if actor_match.group(2):
            layer = int(actor_match.group(2), 16)
        else:
            layer = None
        actor_index = int(actor_match.group(3), 16)
        modify_actor_item(self, arc_path, actor_index, layer, item_id, world_id)
    else:
        raise Exception("Invalid item path: " + path)

def modify_hardcoded_item_in_dol(self, address, item_id: int, world_id: int = 0):
    self.dol.write_data(write_u8, address, item_id)

def modify_hardcoded_item_in_rel(self, path, offset, item_id: int, world_id: int = 0):
    rel = self.get_rel(path)
    rel.write_data(write_u8, offset, item_id)

def modify_chest_item(self, arc_path, chest_index, layer, item_id: int, world_id: int = 0):
    if arc_path.endswith("Stage.arc"):
        dzx = self.get_arc(arc_path).get_file("stage.dzs")
    else:
        dzx = self.get_arc(arc_path).get_file("room.dzr")
    chest = dzx.entries_by_type_and_layer("TRES", layer)[chest_index]
    chest.item_id = item_id
    chest.world_id = world_id
    chest.save_changes()

def modify_event_item(self, arc_path, event_index, actor_index, action_index, item_id: int, world_id: int = 0):
    event_list = self.get_arc(arc_path).get_file("event_list.dat")
    action = event_list.events[event_index].actors[actor_index].actions[action_index]

    if 0x6D <= item_id <= 0x72: # Song
        action.name = "059get_dance"
        action.properties[0].value = [item_id-0x6D]
    else:
        action.name = "011get_item"
        action.properties[0].value = [item_id]

def modify_scob_item(self, arc_path, scob_index, layer, item_id: int, world_id: int = 0):
    if arc_path.endswith("Stage.arc"):
        dzx = self.get_arc(arc_path).get_file("stage.dzs")
    else:
        dzx = self.get_arc(arc_path).get_file("room.dzr")
    scob = dzx.entries_by_type_and_layer("SCOB", layer)[scob_index]
    if scob.actor_class_name in ["d_a_salvage", "d_a_tag_kb_item"]:
        scob.item_id = item_id
        scob.world_id = world_id
        scob.save_changes()
    else:
        raise Exception("%s/SCOB%03X is an unknown type of SCOB" % (arc_path, scob_index))

def modify_actor_item(self, arc_path, actor_index, layer, item_id: int, world_id: int = 0):
    if arc_path.endswith("Stage.arc"):
        dzx = self.get_arc(arc_path).get_file("stage.dzs")
    else:
        dzx = self.get_arc(arc_path).get_file("room.dzr")
    actr = dzx.entries_by_type_and_layer("ACTR", layer)[actor_index]
    if actr.actor_class_name in ["d_a_item", "d_a_boss_item"]:
        actr.item_id = item_id
    else:
        raise Exception("%s/ACTR%03X is not an item" % (arc_path, actor_index))

    actr.save_changes()

