from collections.abc import Mapping as _Mapping

class JavaScriptCode(str):
    """Represents BSON's JavaScript code type with optional scope.

    Raises :class:`TypeError` if `code` is not a string or `scope` is neither
    None nor a dictionary-like object.

    The scope can be provided via the `scope` parameter (dictionary) or through
    keyword arguments. Keyword arguments take precedence over values in the 
    `scope` dictionary for overlapping keys.

    :Parameters:
      - `code`: JavaScript code as a string, or another JavaScriptCode instance
        (in which case its scope is inherited).
      - `scope` (optional): Dictionary mapping variable names to values.
        Defaults to ``None``.
      - `**kwargs`: Additional scope variables passed as keyword arguments.
    """
    _type_marker = 13

    def __new__(cls, code, scope=None, **kwargs):
        # Validate input types
        if not isinstance(code, str):
            raise TypeError("code must be an instance of str")

        # Create the string subclass instance
        self = str.__new__(cls, code)

        # Initialize scope from existing Code object if applicable
        try:
            self._scope_dict = code._scope_dict
        except AttributeError:
            self._scope_dict = None

        # Apply provided scope dictionary
        if scope is not None:
            if not isinstance(scope, _Mapping):
                raise TypeError("scope must be an instance of dict")
            if self._scope_dict is not None:
                self._scope_dict.update(scope)
            else:
                self._scope_dict = dict(scope)

        # Apply keyword arguments (overrides scope dict values)
        if kwargs:
            if self._scope_dict is not None:
                self._scope_dict.update(kwargs)
            else:
                self._scope_dict = dict(kwargs)

        return self

    @property
    def scope(self):
        """Returns the scope dictionary associated with this JavaScript code."""
        return self._scope_dict

    def __repr__(self):
        return "JavaScriptCode(%s, %r)" % (str.__repr__(self), self._scope_dict)

    def __eq__(self, other):
        if isinstance(other, JavaScriptCode):
            return (self._scope_dict, str(self)) == (other._scope_dict, str(other))
        return False

    __hash__ = None

    def __ne__(self, other):
        return not self.__eq__(other)

