# Factory pattern implementation for memory optimization strategies

from enum import Enum
from app.core.agent.memory.strategies import MemoryOptimizationStrategy

class StrategyKind(str, Enum):
    """Available memory compression approaches."""
    COMPRESS = "summarize"

class StrategyBuilder:
    """Builder class for instantiating memory optimization components."""

    @classmethod
    def build(cls, strategy: StrategyKind, **config) -> MemoryOptimizationStrategy:
        """Generate a memory optimization strategy object based on specification.

        Args:
            strategy: Requested strategy type
            **config: Configuration parameters for the strategy

        Returns:
            Configured MemoryOptimizationStrategy instance
        """
        strategy_registry = {
            StrategyKind.COMPRESS: cls._build_summarization_component,
        }
        return strategy_registry[strategy](**config)

    @classmethod
    def _build_summarization_component(cls, **settings) -> MemoryOptimizationStrategy:
        from app.core.agent.memory.strategies.summarize import SummarizeStrategy
        return SummarizeStrategy(**settings)

import torch
import numpy as np
from pathlib import Path
from collections import defaultdict
from noether.core.callbacks.periodic import PeriodicCallback
from noether.core.distributed import all_gather_nograd, all_reduce_mean_grad
from noether.core.schemas.callbacks import TrackAdditionalOutputsCallbackConfig
from noether.core.utils.training import UpdateCounter


class OutputTracker(PeriodicCallback):
    """
    Tracks selected outputs after each gradient update step.

    Supports exact key matches and substring pattern matches.
    Outputs can be logged, saved to disk, or reduced (mean/last).
    """

    def __init__(
        self,
        callback_config: TrackAdditionalOutputsCallbackConfig,
        **kwargs,
    ):
        super().__init__(callback_config=callback_config, **kwargs)

        # Input validation
        if not isinstance(callback_config.keys, (list, type(None))) or (
            isinstance(callback_config.keys, list) and not all(isinstance(k, str) for k in callback_config.keys)
        ):
            raise ValueError("keys must be a list of strings or None.")
        if not isinstance(callback_config.patterns, (list, type(None))) or (
            isinstance(callback_config.patterns, list) and not all(isinstance(p, str) for p in callback_config.patterns)
        ):
            raise ValueError("patterns must be a list of strings or None.")

        # Normalize inputs
        self.exact_keys = set(callback_config.keys or [])
        self.patterns = callback_config.patterns or []

        if not (self.exact_keys or self.patterns):
            raise ValueError("At least one key or pattern must be specified.")

        self.verbose_logging = callback_config.verbose
        self.reduction_mode = callback_config.reduce
        self.should_log = callback_config.log_output
        self.should_save = callback_config.save_output

        # Storage for tracked values
        self._collected_data = {}

        # Setup output directory if saving is enabled
        if self.should_save:
            self.output_dir = callback_config.checkpoint_writer.path_provider.run_output_path / "update_outputs"
            self.output_dir.mkdir(parents=True, exist_ok=True)
        else:
            self.output_dir = None

    def _extract_relevant_items(self, raw_dict):
        """Return items matching either exact keys or patterns."""
        result = {}
        # Exact matches
        for key in self.exact_keys:
            if key in raw_dict:
                result[key] = raw_dict[key]
        # Pattern matches
        for pat in self.patterns:
            for k, v in raw_dict.items():
                if pat in k and k not in result:
                    result[k] = v
        return result

    def _process_value(self, val):
        """Detach tensor if needed; otherwise pass through."""
        return val.detach() if torch.is_tensor(val) else val

    def track_after_accumulation_step(self, *, update_counter, update_outputs, **_) -> None:
        """Collect relevant outputs per step."""
        if update_outputs is None:
            return

        # Skip early if reducing to last and not final step in interval
        if self.reduction_mode == "last" and self.updates_till_next_invocation(update_counter) > 1:
            return

        # Filter and collect
        filtered = self._extract_relevant_items(update_outputs)
        for key, value in filtered.items():
            processed_val = self._process_value(value)
            if key not in self._collected_data:
                self._collected_data[key] = []
            self._collected_data[key].append(processed_val)

    def periodic_callback(self, *, update_counter: UpdateCounter, **_) -> None:
        """Process and export collected data at interval boundaries."""
        for key, vals in self._collected_data.items():
            if not vals:
                continue

            # Reduce according to mode
            if self.reduction_mode == "mean":
                if torch.is_tensor(vals[0]):
                    stacked = torch.stack(vals).float()
                    reduced = stacked.mean()
                else:
                    reduced = torch.tensor(np.mean(vals))
                reduced = all_reduce_mean_grad(reduced)
            elif self.reduction_mode == "last":
                if len(vals) != 1:
                    raise RuntimeError(f"Expected exactly one value for '{key}' when using 'last' reduction, got {len(vals)}")
                reduced = all_gather_nograd(vals[0])
            else:
                raise NotImplementedError(f"Unsupported reduction mode: {self.reduction_mode}")

            # Log scalar
            if self.should_log:
                if reduced.numel() != 1:
                    raise ValueError(f"Expected scalar for logging, got shape {reduced.shape}")
                self.writer.add_scalar(
                    key=f"{key}/{self.to_short_interval_string()}",
                    value=reduced.item(),
                    logger=self.logger if self.verbose_logging else None,
                    format_str=".5f",
                )

            # Save tensor
            if self.should_save and self.output_dir is not None:
                filename = f"{key}_{self.to_short_interval_string()}_{update_counter.cur_iteration}.th"
                torch.save(reduced, self.output_dir / filename)

        # Clear buffer
        self._collected_data.clear()

    def __str__(self):
        return (
            f"{type(self).__name__}({self.get_interval_string_verbose()}, "
            f"exact_keys={sorted(self.exact_keys)}, patterns={self.patterns})"
        )

from common.session_manager import SessionManager

class _MockStorage:
    def __init__(self, data):
        self.data = data

class _ConfigWrapper:
    def __init__(self, thread_identifier: str):
        self.settings = {"thread_id": thread_identifier}

    def __hash__(self) -> int:  # pragma: no cover
        return hash(self.settings["thread_id"])

    def __eq__(self, other: object) -> bool:  # pragma: no cover
        return isinstance(other, _ConfigWrapper) and other.settings == self.settings

def test_list_sessions_with_user_filter():
    mock_storage = _MockStorage(
        data={
            _ConfigWrapper("session_alice"): {
                "data_values": {
                    "user_id": "alice",
                    "message": "hello",
                    "path": "direct",
                }
            },
            _ConfigWrapper("session_bob"): {
                "data_values": {
                    "user_id": "bob",
                    "message": "hi",
                    "path": "direct",
                }
            },
        }
    )

    manager = SessionManager(mock_storage)
    result_sessions = manager.list_sessions(max_results=50, user_id="alice")

    assert [s.thread_id for s in result_sessions] == ["session_alice"]

