@pytest.fixture
def approval_hook():
    class ApprovalControl(HookProvider):
        def register_hooks(self, registry):
            registry.add_callback(BeforeToolCallEvent, self._check_approval)

        def _check_approval(self, event):
            tool_name = event.tool_use["name"]
            if tool_name == "time_display":
                return  # Skip interruption for time tool

            interrupt_response = event.interrupt("manual_review", reason="requires user confirmation")
            if interrupt_response != "APPROVE":
                event.cancel_tool = "denied by user"


    return ApprovalControl()


@pytest.fixture
def clock_tool():
    @tool(name="time_display")
    def get_time():
        return "12:00"
    return get_time


@pytest.fixture
def forecast_tool():
    @tool(name="weather_forecast")
    def get_weather():
        return "sunny"
    return get_weather


@pytest.fixture
def smart_agent(approval_hook, clock_tool, forecast_tool):
    return Agent(hooks=[approval_hook], tools=[clock_tool, forecast_tool])


def test_interrupt_and_approve(smart_agent):
    # Initial query triggers two tools; weather_tool should be interrupted
    response = smart_agent("What is the current time and weather?")

    assert response.stop_reason == "interrupt"

    interrupts = response.interrupts
    assert len(interrupts) == 1
    interrupt_obj = interrupts[0]
    assert interrupt_obj.name == "manual_review"
    assert interrupt_obj.reason == "requires user confirmation"

    # Simulate approval via interrupt response
    approval_payload = [{
        "interruptResponse": {
            "interruptId": interrupt_obj.id,
            "response": "APPROVE",
        },
    }]

    final_response = smart_agent(approval_payload)
    assert final_response.stop_reason == "end_turn"

    # Verify both tool results are present in final message
    msg_str = json.dumps(final_response.message).lower()
    assert "12:00" in msg_str and "sunny" in msg_str

    # Check tool result message structure
    tool_result_msg = smart_agent.messages[-2]
    expected_structure = {
        "role": "user",
        "content": [
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [{"text": "sunny"}],
                }
            },
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [{"text": "12:00"}],
                }
            },
        ],
    }
    assert tool_result_msg == expected_structure


def test_interrupt_and_reject(smart_agent):
    # Trigger initial agent run
    first_run = smart_agent("What is the time and weather?")
    assert first_run.stop_reason == "interrupt"

    interrupt_id = first_run.interrupts[0].id

    # Send rejection response
    rejection_payload = [{
        "interruptResponse": {
            "interruptId": interrupt_id,
            "response": "REJECT",
        },
    }]

    second_run = smart_agent(rejection_payload)
    assert second_run.stop_reason == "end_turn"

    # Validate tool result message after rejection
    tool_result_msg = smart_agent.messages[-2]
    expected_rejected = {
        "role": "user",
        "content": [
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "success",
                    "content": [{"text": "sunny"}],
                }
            },
            {
                "toolResult": {
                    "toolUseId": ANY,
                    "status": "error",
                    "content": [{"text": "denied by user"}],
                }
            },
        ],
    }
    assert tool_result_msg == expected_rejected

import math
from typing import Tuple
import jax
from jax.sharding import NamedSharding, PartitionSpec as P

def shard_put(x: jax.Array, sharding_names: Tuple[str, ...] | P,
              mesh: jax.sharding.Mesh) -> jax.Array:
    # Handle single-device case separately to prevent recursive JIT compilation issues
    total_devices = 1
    for size in mesh.axis_sizes:
        total_devices *= size

    if total_devices == 1:
        return jax.device_put(x, mesh.devices.flatten()[0])

    # For multi-device configurations, use NamedSharding
    return jax.device_put(x, NamedSharding(mesh, P(*sharding_names)))

