bp = Blueprint('truststore_v2_alt', __name__)
logger = logging.getLogger(__name__)

def extract_cert_info(pem_data):
    """
    Extract certificate information from PEM data

    Returns dict with subject, issuer, serial number, validity dates, and fingerprints
    """
    try:
        cert_obj = x509.load_pem_x509_certificate(pem_data.encode(), default_backend())

        # Get subject and issuer as strings
        subject_str = cert_obj.subject.rfc4514_string()
        issuer_str = cert_obj.issuer.rfc4514_string()

        # Compute fingerprints using DER encoding
        der_bytes = cert_obj.public_bytes(serialization.Encoding.DER)
        sha256_hash = hashlib.sha256(der_bytes).hexdigest()
        sha1_hash = hashlib.sha1(der_bytes).hexdigest()

        return {
            'subject': subject_str,
            'issuer': issuer_str,
            'serial': format(cert_obj.serial_number, 'X'),
            'valid_from': cert_obj.not_valid_before_utc,
            'valid_until': cert_obj.not_valid_after_utc,
            'sha256_fingerprint': sha256_hash,
            'sha1_fingerprint': sha1_hash,
        }
    except Exception as e:
        raise ValueError(f'Certificate parsing failed: {str(e)}')

def convert_der_to_pem(der_bytes):
    """Convert DER-encoded certificate to PEM format"""
    try:
        cert_obj = x509.load_der_x509_certificate(der_bytes, default_backend())
        pem_bytes = cert_obj.public_bytes(serialization.Encoding.PEM)
        return pem_bytes.decode('utf-8'), extract_cert_info(pem_bytes.decode('utf-8'))
    except Exception as e:
        raise ValueError(f'DER conversion failed: {str(e)}')

