@bp.route('/api/v2/truststore/import', methods=['POST'])
@require_auth(['write:truststore'])
def import_certificate():
    """
    Import a certificate via file upload

    Supports both PEM and DER formats
    """
    if 'file' not in request.files:
        return error_response('No file provided', 400)

    uploaded_file = request.files['file']
    if not uploaded_file.filename:
        return error_response('No file selected', 400)

    from utils.file_validation import validate_upload, CERT_EXTENSIONS
    try:
        file_content, safe_name = validate_upload(uploaded_file, CERT_EXTENSIONS)
    except ValueError as e:
        logger.warning(f'File validation failed: {e}')
        return error_response('Invalid file upload', 400)

    cert_name = request.form.get('name', safe_name.rsplit('.', 1)[0])
    cert_purpose = request.form.get('purpose', 'custom')
    cert_desc = request.form.get('description', '')
    cert_notes = request.form.get('notes', '')

    try:
        # Try PEM format first
        if b'-----BEGIN CERTIFICATE-----' in file_content:
            pem_content = file_content.decode('utf-8')
            cert_info = extract_cert_info(pem_content)
        else:
            # Try DER format
            pem_content, cert_info = convert_der_to_pem(file_content)

        # Check for duplicate by fingerprint
        existing_cert = TrustedCertificate.query.filter_by(
            sha256_fingerprint=cert_info['sha256_fingerprint']
        ).first()

        if existing_cert:
            return error_response(f'Certificate already exists as "{existing_cert.name}"', 409)

        # Create new certificate record
        new_cert = TrustedCertificate(
            name=cert_name,
            description=cert_desc,
            certificate_pem=pem_content,
            sha256_fingerprint=cert_info['sha256_fingerprint'],
            sha1_fingerprint=cert_info['sha1_fingerprint'],
            subject=cert_info['subject'],
            issuer=cert_info['issuer'],
            serial=cert_info['serial'],
            valid_from=cert_info['valid_from'],
            valid_until=cert_info['valid_until'],
            purpose=cert_purpose,
            added_by=g.current_user.username,
            notes=cert_notes
        )

        db.session.add(new_cert)
        db.session.commit()

        AuditService.log_action(
            action='truststore_import',
            resource_type='truststore',
            resource_id=new_cert.id,
            resource_name=new_cert.name,
            details=f'Imported certificate: {new_cert.name}',
            success=True
        )

        return created_response(
            data=new_cert.to_dict(),
            message=f'Certificate "{cert_name}" successfully imported'
        )

    except ValueError as e:
        db.session.rollback()
        logger.error(f'Certificate import validation error: {e}')
        return error_response('Invalid certificate data', 400)
    except Exception as e:
        db.session.rollback()
        logger.error(f'Certificate import failed: {e}')
        return error_response('Import operation failed', 500)

@bp.route('/api/v2/truststore', methods=['GET'])
@require_auth(['read:truststore'])
def list_certificates():
    """
    List all trusted certificates with optional filtering

    Query parameters:
    - purpose: Filter by certificate purpose
    - search: Search across name, subject, and fingerprint
    """
    purpose_filter = request.args.get('purpose')
    search_query = request.args.get('search', '').strip()

    query = TrustedCertificate.query

    if purpose_filter:
        query = query.filter_by(purpose=purpose_filter)

    if search_query:
        pattern = f'%{search_query}%'
        query = query.filter(
            db.or_(
                TrustedCertificate.name.ilike(pattern),
                TrustedCertificate.subject.ilike(pattern),
                TrustedCertificate.sha256_fingerprint.ilike(pattern)
            )
        )

    certs = query.order_by(TrustedCertificate.created_at.desc()).all()

    return success_response(
        data=[cert.to_dict() for cert in certs]
    )

