@bp.route('/api/v2/truststore/sync', methods=['POST'])
@require_auth(['write:truststore'])
def sync_system_cas():
    """
    Synchronize trust store with system CA bundle

    POST /api/v2/truststore/sync
    {
        "source": "system",  # Only "system" source supported currently
        "limit": 50          # Optional limit on number of certs to import
    }
    """
    payload = request.get_json() or {}
    source = payload.get('source', 'system')
    max_imports = payload.get('limit', 50)

    SYSTEM_CA_PATH = '/etc/ssl/certs/ca-certificates.crt'

    if source != 'system':
        return error_response('Only "system" source is currently supported', 400)

    if not os.path.exists(SYSTEM_CA_PATH):
        return error_response(f'System CA bundle not found at {SYSTEM_CA_PATH}', 404)

    try:
        # Read system CA bundle
        with open(SYSTEM_CA_PATH, 'r') as ca_file:
            bundle_text = ca_file.read()

        # Split into individual certificates
        individual_certs = []
        current_cert_lines = []
        in_certificate_block = False

        for line in bundle_text.split('\n'):
            if '-----BEGIN CERTIFICATE-----' in line:
                in_certificate_block = True
                current_cert_lines = [line]
            elif '-----END CERTIFICATE-----' in line:
                current_cert_lines.append(line)
                individual_certs.append('\n'.join(current_cert_lines))
                in_certificate_block = False
                current_cert_lines = []
            elif in_certificate_block:
                current_cert_lines.append(line)

        imported_count = 0
        skipped_count = 0
        failed_count = 0

        for pem_cert in individual_certs[:max_imports]:
            try:
                cert_info = extract_cert_info(pem_cert)

                # Skip if already exists
                if TrustedCertificate.query.filter_by(
                    sha256_fingerprint=cert_info['sha256_fingerprint']
                ).first():
                    skipped_count += 1
                    continue

                # Extract CN for naming
                subject = cert_info['subject']
                common_name = None
                for part in subject.split(','):
                    if part.strip().startswith('CN='):
                        common_name = part.strip()[3:]
                        break

                cert_name = common_name or f"System CA {cert_info['sha256_fingerprint'][:8]}"

                new_cert = TrustedCertificate(
                    name=cert_name,
                    description='Imported from system CA bundle',
                    certificate_pem=pem_cert,
                    sha256_fingerprint=cert_info['sha256_fingerprint'],
                    sha1_fingerprint=cert_info['sha1_fingerprint'],
                    subject=cert_info['subject'],
                    issuer=cert_info['issuer'],
                    serial=cert_info['serial'],
                    valid_from=cert_info['valid_from'],
                    valid_until=cert_info['valid_until'],
                    purpose='system',
                    added_by='system_sync',
                    notes='Auto-imported from /etc/ssl/certs/ca-certificates.crt'
                )

                db.session.add(new_cert)
                imported_count += 1

            except Exception as e:
                failed_count += 1
                continue

        db.session.commit()

        AuditService.log_action(
            action='truststore_sync',
            resource_type='truststore',
            resource_name='System CA Bundle',
            details=f'Synced {imported_count} new certificates from system',
            success=True
        )

        return success_response(
            message=f'Trust store synchronized: {imported_count} new, {skipped_count} duplicates',
            data={
                'source': source,
                'total_found': len(individual_certs),
                'new_count': imported_count,
                'skipped_count': skipped_count,
                'error_count': failed_count
            }
        )

    except Exception as e:
        db.session.rollback()
        logger.error(f'System CA sync failed: {e}')
        return error_response('Failed to synchronize trust store', 500)

@bp.route('/api/v2/truststore/export', methods=['GET'])
@require_auth(['read:truststore'])
def export_trust_bundle():
    """
    Export trust store as a certificate bundle.

    GET /api/v2/truststore/export?format=pem&purpose=root_ca

    Query params:
      - format: pem (default), p7b
      - purpose: root_ca, intermediate_ca, system, all (default)
    """
    output_format = request.args.get('format', 'pem')
    purpose_filter = request.args.get('purpose', 'all')

    if output_format not in ('pem', 'p7b'):
        return error_response('Unsupported format. Valid options: pem, p7b', 400)

    try:
        query = TrustedCertificate.query
        if purpose_filter != 'all':
            query = query.filter_by(purpose=purpose_filter)

        certs = query.order_by(TrustedCertificate.name).all()

        if not certs:
            return error_response('No certificates found matching criteria', 404)

        if output_format == 'pem':
            bundle_lines = []
            for cert in certs:
                bundle_lines.append(f'# {cert.name}')
                bundle_lines.append(cert.certificate_pem.strip())
                bundle_lines.append('')

            bundle_content = '\n'.join(bundle_lines)
            filename = f'truststore-{purpose_filter}-bundle.pem'

            return Response(
                bundle_content,
                mimetype='application/x-pem-file',
                headers={'Content-Disposition': f'attachment; filename="{filename}"'}
            )

        elif output_format == 'p7b':
            from cryptography.hazmat.primitives.serialization import pkcs7

            x509_certs = []
            for cert in certs:
                try:
                    cert_obj = x509.load_pem_x509_certificate(
                        cert.certificate_pem.encode(), default_backend()
                    )
                    x509_certs.append(cert_obj)
                except Exception:
                    continue

            if not x509_certs:
                return error_response('No valid certificates to export', 400)

            p7b_data = pkcs7.serialize_certificates(x509_certs, serialization.Encoding.DER)

            filename = f'truststore-{purpose_filter}-bundle.p7b'
            return Response(
                p7b_data,
                mimetype='application/x-pkcs7-certificates',
                headers={'Content-Disposition': f'attachment; filename="{filename}"'}
            )

    except Exception as e:
        logger.error(f'Export operation failed: {e}')
        return error_response('Failed to export trust bundle', 500)

@bp.route('/api/v2/truststore/expiring', methods=['GET'])
@require_auth(['read:truststore'])
def get_expiring_certificates():
    """
    Get trusted certificates expiring within N days.

    GET /api/v2/truststore/expiring?days=90
    """
    days_threshold = request.args.get('days', 90, type=int)

    try:
        now = datetime.utcnow()
        future_threshold = now + timedelta(days=days_threshold)

        # Certificates expiring soon (within threshold but not yet expired)
        expiring_soon = TrustedCertificate.query.filter(
            db.and_(
                TrustedCertificate.valid_until != None,
                TrustedCertificate.valid_until > now,
                TrustedCertificate.valid_until <= future_threshold
            )
        ).order_by(TrustedCertificate.valid_until.asc()).all()

        # Already expired certificates
        expired_certs = TrustedCertificate.query.filter(
            db.and_(
                TrustedCertificate.valid_until != None,
                TrustedCertificate.valid_until <= now
            )
        ).order_by(TrustedCertificate.valid_until.desc()).all()

        def format_cert_info(c):
            days_remaining = (c.valid_until - now).days if c.valid_until else None
            return {
                'id': c.id,
                'name': c.name,
                'subject': c.subject,
                'purpose': c.purpose,
                'valid_until': c.valid_until.isoformat() if c.valid_until else None,
                'days_remaining': days_remaining,
                'sha256_fingerprint': c.sha256_fingerprint,
            }

        return success_response(data={
            'expiring': [format_cert_info(c) for c in expiring_soon],
            'expired': [format_cert_info(c) for c in expired_certs],
            'expiring_count': len(expiring_soon),
            'expired_count': len(expired_certs),
            'threshold_days': days_threshold,
        })

    except Exception as e:
        logger.error(f'Expiring certificate query failed: {e}')
        return error_response('Failed to retrieve expiring certificates', 500)

@bp.route('/api/v2/truststore/add-from-ca/<string:ca_refid>', methods=['POST'])
@require_auth(['write:truststore'])
def add_ca_certificate(ca_refid):
    """
    Add a managed CA's certificate to the Trust Store.

    POST /api/v2/truststore/add-from-ca/<ca_refid>
    Body (optional): { "purpose": "root_ca", "notes": "..." }
    """
    from models import CA

    ca_record = CA.query.filter_by(refid=ca_refid).first()
    if not ca_record:
        return error_response('CA not found', 404)

    try:
        cert_bytes = base64.b64decode(ca_record.crt)
        pem_content = cert_bytes.decode('utf-8')
    except Exception:
        return error_response('Failed to decode CA certificate', 500)

    # Validate certificate
    cert_info = extract_cert_info(pem_content)
    if not cert_info:
        return error_response('Failed to parse CA certificate', 500)

    # Check for duplicates
    existing = TrustedCertificate.query.filter_by(
        sha256_fingerprint=cert_info['sha256_fingerprint']
    ).first()
    if existing:
        return error_response('This CA is already in the Trust Store', 409)

    # Process request body
    request_body = request.get_json(silent=True) or {}
    cert_purpose = request_body.get('purpose', 'root_ca' if ca_record.is_root else 'intermediate_ca')

    # Determine certificate name
    cert_name = (
        ca_record.common_name or 
        ca_record.descr or 
        cert_info['subject']
    )

    # Create new trust store entry
    new_entry = TrustedCertificate(
        name=cert_name,
        certificate_pem=pem_content,
        subject=cert_info['subject'],
        issuer=cert_info['issuer'],
        serial=cert_info['serial'],
        valid_from=cert_info['valid_from'],
        valid_until=cert_info['valid_until'],
        sha256_fingerprint=cert_info['sha256_fingerprint'],
        sha1_fingerprint=cert_info['sha1_fingerprint'],
        purpose=cert_purpose,
        added_by=g.current_user.username,
        notes=request_body.get('notes', f'Added from managed CA: {ca_record.descr or ca_record.common_name}'),
    )

    db.session.add(new_entry)
    db.session.commit()

    AuditService.log_action(
        action='truststore.add_from_ca',
        resource_type='truststore',
        resource_id=str(new_entry.id),
        resource_name=new_entry.name,
        details=f'Added managed CA "{ca_record.common_name or ca_record.descr}" to Trust Store'
    )

    return created_response(data={
        'id': new_entry.id,
        'name': new_entry.name,
        'sha256_fingerprint': new_entry.sha256_fingerprint,
        'purpose': new_entry.purpose,
    }, message=f'CA "{new_entry.name}" added to Trust Store')

import contextlib
import os
from collections import defaultdict
from enum import Enum
import torch
from torch.autograd.graph import saved_tensors_hooks
from primus.modules.module_utils import log_rank_all

def compute_checksum(tensor):
    with torch.no_grad():
        if tensor.dtype == torch.float16:
            return torch.sum(tensor * tensor).mean().item()
        else:
            return 0

def is_view_of(source, target):
    return (
        source.storage().data_ptr() == target.storage().data_ptr()
        and source.storage_offset() == target.storage_offset()
        and source.numel() == target.numel()
    )

def describe_tensor(tensor):
    return (tensor.shape, tensor.layout, tensor.dtype, tensor.stride())

def capture_rng_states():
    from megatron.core.tensor_parallel.random import get_cuda_rng_tracker
    return torch.get_rng_state(), torch.cuda.get_rng_state(), get_cuda_rng_tracker().get_states()

def restore_rng_states(states):
    from megatron.core.tensor_parallel.random import _set_cuda_rng_state, get_cuda_rng_tracker
    torch.set_rng_state(states[0])
    _set_cuda_rng_state(states[1])
    get_cuda_rng_tracker().set_states(states[2])

class PartialRecompute(saved_tensors_hooks):
    class StorageMode(Enum):
        DIRECT = 1
        RECOMPUTE = 2

    def _capture_tensor(self, tensor):
        if self._pending_recompute is not None and is_view_of(tensor, self._pending_recompute[0]):
            packed = self._pending_recompute[1:]
            self._pending_recompute = None
            return PartialRecompute.StorageMode.RECOMPUTE, packed
        return PartialRecompute.StorageMode.DIRECT, tensor

    def _restore_tensor(self, packed):
        mode, info = packed
        if mode == PartialRecompute.StorageMode.RECOMPUTE:
            parents, function, rng_states = info
            with torch.no_grad():
                if rng_states is not None:
                    current_rng_states = capture_rng_states()
                    restore_rng_states(rng_states)
                result = function(*parents)
                if rng_states is not None:
                    restore_rng_states(current_rng_states)
            return result
        return info

    def __init__(self):
        self._pending_recompute = None
        super().__init__(self._capture_tensor, self._restore_tensor)

    def trigger_recompute(self, tensor, parents, function, rng_states=None):
        assert self._pending_recompute is None
        self._pending_recompute = (tensor, parents, function, rng_states)

partial_recompute_instance = PartialRecompute()

class SynchronizedBarrier:
    previous_event = None
    current_event = None

    @classmethod
    def mark(cls):
        cls.previous_event = cls.current_event
        from megatron.training import get_args
        if not get_args().paired_barrier:
            return
        cls.current_event = torch.cuda.Event(interprocess=True)
        cls.current_event.record()
        cls.ipc_handle = cls.current_event.ipc_handle()

    @classmethod
    def await_peer(cls, peer_rank: int = None):
        from megatron.training import get_args
        if not get_args().paired_barrier:
            return
        if peer_rank is None:
            peer_rank = torch.distributed.get_rank() ^ 1
            if peer_rank >= torch.distributed.get_world_size():
                return
        if cls.current_event is None:
            cls.mark()
        peer_handle = bytearray(len(cls.ipc_handle))
        send_op = torch.distributed.isend(
            tensor=torch.frombuffer(bytearray(cls.ipc_handle), dtype=torch.uint8), dst=peer_rank
        )
        torch.distributed.recv(tensor=torch.frombuffer(peer_handle, dtype=torch.uint8), src=peer_rank)
        send_op.wait()
        cls.previous_event = None
        peer_event = torch.cuda.Event.from_ipc_handle(torch.cuda.current_device(), bytes(peer_handle))
        peer_event.wait()

class DummyStorageManager:
    @classmethod
    def synchronize(cls):
        from megatron.training import get_args
        assert not get_args().offload_overlap_sr
        cls.unload()

    @classmethod
    def reload(cls):
        with torch.cuda.stream(get_offload_h2d_stream()):
            SynchronizedBarrier.await_peer()
        return

    @classmethod
    def unload(cls):
        with torch.cuda.stream(get_offload_d2h_stream()):
            SynchronizedBarrier.await_peer()
        return

class TensorStorage(saved_tensors_hooks):
    @classmethod
    def schedule_recompute(cls, tensor, parents, function, rng_states=None):
        return partial_recompute_instance.trigger_recompute(tensor, parents, function, rng_states)

    def __enter__(self):
        assert (
            not hasattr(TensorStorage, "_active_storage")
            or TensorStorage._active_storage is None
        ), "Nested offloading not supported"
        TensorStorage._active_storage = self
        return super().__enter__()

    def __exit__(self, *args):
        super().__exit__(*args)
        TensorStorage._active_storage = None

    class Lifecycle(Enum):
        INITIAL = 0
        STORING = 1
        OFFLOADED = 2
        OFFLOAD_FREED = 3
        RESUME_READY = 4
        RESUMED = 5
        RESUME_CONSUMED = 6
        RESUME_FREED = 7

    def _transition_state(self, expected, new_state):
        if isinstance(expected, set):
            assert self._current_state in expected
        else:
            assert self._current_state == expected
        self._current_state = new_state

    class StorageStrategy(Enum):
        OFFLOAD = 1
        PASS_THROUGH = 2
        RECOMPUTE = 3
        SHARED_VIEW = 4

    def _handle_tensor_save(self, tensor):
        assert not self._is_offloaded
        self._transition_state(
            {TensorStorage.Lifecycle.INITIAL, TensorStorage.Lifecycle.STORING}, TensorStorage.Lifecycle.STORING
        )
        if isinstance(tensor, torch.nn.parameter.Parameter):
            return TensorStorage.StorageStrategy.PASS_THROUGH, tensor
        if tensor.numel() <= 1024:
            return TensorStorage.StorageStrategy.PASS_THROUGH, tensor
        recompute_result = partial_recompute_instance._capture_tensor(tensor)
        if recompute_result[0] == PartialRecompute.StorageMode.RECOMPUTE:
            (parents, function, rng_states) = recompute_result[1]
            parent_handles = [self._handle_tensor_save(x) for x in parents]
            return TensorStorage.StorageStrategy.RECOMPUTE, (parent_handles, function, rng_states)
        for idx, cached_tensor in enumerate(self._gpu_cache):
            if is_view_of(tensor, cached_tensor):
                offset = tensor.storage_offset() - cached_tensor.storage_offset()
                stride = tensor.stride()
                shape = tensor.shape
                return TensorStorage.StorageStrategy.SHARED_VIEW, (tensor.dtype, idx, shape, stride, offset)
        self._gpu_cache.append(tensor.data)
        if len(self._offload_metadata) < len(self._gpu_cache):
            self._offload_metadata.append(describe_tensor(tensor))
        else:
            assert self._offload_metadata[len(self._gpu_cache) - 1] == describe_tensor(tensor)
        self._save_event.record()
        return (TensorStorage.StorageStrategy.OFFLOAD, len(self._gpu_cache) - 1)

    def _handle_tensor_restore(self, packed, keep_reference=False):
        assert not self._is_offloaded
        strategy, info = packed
        self._transition_state(
            {TensorStorage.Lifecycle.RESUMED, TensorStorage.Lifecycle.RESUME_CONSUMED},
            TensorStorage.Lifecycle.RESUME_CONSUMED,
        )
        if strategy == TensorStorage.StorageStrategy.PASS_THROUGH:
            return info
        if strategy == TensorStorage.StorageStrategy.RECOMPUTE:
            p_infos, function, rng_states = info
            parents = [self._handle_tensor_restore(x, keep_reference=False) for x in p_infos]
            return partial_recompute_instance._restore_tensor(
                (PartialRecompute.StorageMode.RECOMPUTE, (parents, function, rng_states))
            )
        if packed[0] == TensorStorage.StorageStrategy.SHARED_VIEW:
            dtype, index, shape, stride, offset = packed[1]
            self._restore_event.wait()
            bin_id, o = self.index_mapping[index]
            return torch.as_strided(self._continuous_gpu_buffer[dtype][bin_id], shape, stride, o + offset)
        assert strategy == TensorStorage.StorageStrategy.OFFLOAD
        self._restore_event.wait()
        index = info
        ret = self._gpu_cache[index]
        self._gpu_cache[index] = None
        if not keep_reference:
            shape, layout, dtype, stride = self._offload_metadata[index]
            bin_id, offset = self.index_mapping[index]
            all_freed = True
            for i, (b, o) in enumerate(self.index_mapping):
                if self._gpu_cache[i] is not None and b == bin_id and self._offload_metadata[i][2] == dtype:
                    all_freed = False
                    break
            if all_freed:
                self._continuous_gpu_buffer[dtype][bin_id] = None
        return ret

    def __init__(self, h2d_stream=None, d2h_stream=None):
        self._gpu_cache = []
        self._is_offloaded = False
        self._save_event = torch.cuda.Event()
        self._prepare_restore_event = torch.cuda.Event()
        self._restore_event = torch.cuda.Event()
        self._offload_complete_event = torch.cuda.Event()
        self._h2d_stream = h2d_stream
        self._d2h_stream = d2h_stream
        self._continuous_cpu_buffer = None
        self._continuous_gpu_buffer = None
        self._offload_metadata = []
        self._index_mapping = []
        self._index_cpu_buffer = []
        self._current_state = TensorStorage.Lifecycle.INITIAL
        super().__init__(self._handle_tensor_save, self._handle_tensor_restore)

    def _setup_cpu_buffers(self):
        if self._continuous_cpu_buffer is not None:
            return
        alignment = 64
        def calculate_size(shape, stride):
            id_stride = sorted([(i, s) for i, s in enumerate(stride) if shape[i] != 1], key=lambda x: x[1])
            size = 1
            for i, st in id_stride:
                assert size == st, f"stride {stride} size {shape} not continuous"
                size *= shape[i]
            return (size + (alignment - 1)) // alignment * alignment
        self.index_mapping = []
        type_tensors = defaultdict(list)
        for id, (shape, layout, dtype, stride) in enumerate(self._offload_metadata):
            assert layout == torch.strided
            mysize = calculate_size(shape, stride)
            type_tensors[dtype].append((mysize, id))

        def nearest_power_of_2(x):
            return 2 ** (x - 1).bit_length()

        def allocate_bins(tensors, max_split=4):
            total_size = sum([x[0] for x in tensors])
            aligned_size = nearest_power_of_2(total_size)
            bin_sizes = [aligned_size // 2**i for i in range(max_split)]
            bins = [0] * max_split
            tensors = sorted(tensors, key=lambda x: x[0], reverse=True)
            while True:
                bins[-1] += bin_sizes[-1]
                for i in range(max_split - 1, 0, -1):
                    if bins[i] > bin_sizes[i]:
                        bins[i] = 0
                        bins[i - 1] += bin_sizes[i - 1]
                solution_bins = [x for x in bins if x > 0]
                if sum(solution_bins) < total_size:
                    continue
                current_bin = [0] * len(solution_bins)
                solution = {}
                fit = True
                for size, id in tensors:
                    ok = False
                    for i in range(len(solution_bins)):
                        if current_bin[i] + size <= solution_bins[i]:
                            current_bin[i] += size
                            solution[id] = (i, current_bin[i] - size)
                            ok = True
                            break
                    if not ok:
                        fit = False
                        break
                if fit:
                    assert len(solution) == len(tensors)
                    assert all([x > 0 for x in current_bin])
                    return current_bin, solution

        import psutil
        log_rank_all(
            f"rank {torch.distributed.get_rank()} before allocation rss {psutil.Process(os.getpid()).memory_info().rss / 1000000} MB"
        )
        self._continuous_cpu_buffer = {}
        self.index_mapping = [None] * len(self._offload_metadata)
        for dtype, tensors in type_tensors.items():
            from megatron.training import get_args
            if get_args().offload_continuous_buffers:
                bins, solution = allocate_bins(tensors, max_split=8)
            else:
                bins = [t[0] for t in tensors]
                solution = {tensors[i][1]: (i, 0) for i in range(len(tensors))}
            self._continuous_cpu_buffer[dtype] = [
                torch.empty([size], dtype=dtype, pin_memory=True, device="cpu") for size in bins
            ]
            for id, (bin, offset) in solution.items():
                self.index_mapping[id] = (bin, offset)
            log_rank_all(
                f"rank {torch.distributed.get_rank()} after allocation {dtype} {bins} elements rss {psutil.Process(os.getpid()).memory_info().rss / 1000000} MB"
            )
        for dtype, tensors in type_tensors.items():
            total_size = sum([x[0] for x in tensors])
            allocated_size = sum([x.numel() for x in self._continuous_cpu_buffer[dtype]])
            aligned_size = sum([nearest_power_of_2(x.numel()) for x in self._continuous_cpu_buffer[dtype]])
            log_rank_all(
                f"rank {torch.distributed.get_rank()} Allocated {allocated_size / 1000000} M elements for {len(tensors)} tensors of type {dtype} total length {total_size} aligned size {aligned_size}"
            )
        for index, (shape, layout, dtype, stride) in enumerate(self._offload_metadata):
            bin_id, offset = self.index_mapping[index]
            ctensor = torch.as_strided(self._continuous_cpu_buffer[dtype][bin_id], shape, stride, offset)
            self._index_cpu_buffer.append(ctensor)

    @torch.no_grad()
    @torch.cuda.nvtx.range("Offload")
    def offload_data(self):
        self._transition_state(TensorStorage.Lifecycle.STORING, TensorStorage.Lifecycle.OFFLOADED)
        assert not self._is_offloaded
        size = 0
        storage_size = 0
        storages = set()
        with torch.cuda.stream(self._d2h_stream) if self._d2h_stream else contextlib.nullcontext():
            self._save_event.wait()
            self._setup_cpu_buffers()
            SynchronizedBarrier.await_peer()
            for index, tensor in enumerate(self._gpu_cache):
                buffer = self._index_cpu_buffer[index]
                assert buffer.shape == tensor.shape
                buffer.copy_(tensor, non_blocking=True)
                size += tensor.numel()
                if tensor.storage().data_ptr() not in storages:
                    storages.add(tensor.storage().data_ptr())
                    storage_size += tensor.storage().nbytes()
                else:
                    pass
            SynchronizedBarrier.mark()
            self._offload_complete_event.record()
        self._is_offloaded = True

    @torch.no_grad()
    @torch.cuda.nvtx.range("OffloadRelease")
    def release_offload(self):
        self._transition_state(TensorStorage.Lifecycle.OFFLOADED, TensorStorage.Lifecycle.OFFLOAD_FREED)
        assert self._is_offloaded
        if self._d2h_stream is not None:
            self._offload_complete_event.wait()
        self._gpu_cache.clear()

    @torch.no_grad()
    @torch.cuda.nvtx.range("PrepareResume")
    def prepare_resume(self):
        self._transition_state(TensorStorage.Lifecycle.OFFLOAD_FREED, TensorStorage.Lifecycle.RESUME_READY)
        assert self._is_offloaded
        self._continuous_gpu_buffer = {
            dtype: [torch.empty_like(x, device="cuda") for x in bins]
            for dtype, bins in self._continuous_cpu_buffer.items()
        }
        for index, (shape, layout, dtype, stride) in enumerate(self._offload_metadata):
            bin_id, offset = self.index_mapping[index]
            gtensor = torch.as_strided(self._continuous_gpu_buffer[dtype][bin_id], shape, stride, offset)
            self._gpu_cache.append(gtensor)
        self._prepare_restore_event.record()

    @torch.no_grad()
    @torch.cuda.nvtx.range("Resume")
    def resume_data(self):
        self._transition_state(TensorStorage.Lifecycle.RESUME_READY, TensorStorage.Lifecycle.RESUMED)
        assert self._is_offloaded
        torch.cuda.current_stream()
        with torch.cuda.stream(self._h2d_stream) if self._h2d_stream else contextlib.nullcontext():
            self._prepare_restore_event.wait()
            self._offload_complete_event.wait()
            SynchronizedBarrier.await_peer()
            for dtype, bins in self._continuous_cpu_buffer.items():
                for cpu, gpu in zip(bins, self._continuous_gpu_buffer[dtype]):
                    gpu.copy_(cpu, non_blocking=True)
            SynchronizedBarrier.mark()
            self._restore_event.record()
        self._is_offloaded = False

    @torch.no_grad()
    @torch.cuda.nvtx.range("ResumeRelease")
    def release_resume(self):
        self._transition_state(TensorStorage.Lifecycle.RESUME_CONSUMED, TensorStorage.Lifecycle.RESUME_FREED)
        assert all([x is None for x in self._gpu_cache])
        assert all([all([x is None for x in y]) for y in self._continuous_gpu_buffer.values()])
        self._restore_event.wait()
        self._gpu_cache.clear()
        self._continuous_gpu_buffer.clear()

    def reset_state(self):
        self._transition_state(TensorStorage.Lifecycle.RESUME_FREED, TensorStorage.Lifecycle.INITIAL)

offload_stream = None
d2h_stream = None

def get_offload_h2d_stream():
    global offload_stream
    if offload_stream is None:
        offload_stream = torch.cuda.Stream()
    return offload_stream

def get_offload_d2h_stream():
    from megatron.training import get_args
    if not get_args().offload_overlap_sr:
        return get_offload_h2d_stream()
    global d2h_stream
    if d2h_stream is None:
        d2h_stream = torch.cuda.Stream()
    return d2h_stream

class ActivationStorePool:
    def __init__(self) -> None:
        self._pool = []
        self._stage_queues = [[] for _ in range(6)]

    def acquire_for_offload(self) -> TensorStorage:
        if self._pool:
            ret = self._pool.pop(-1)
            ret.reset_state()
        else:
            ret = TensorStorage(get_offload_h2d_stream(), get_offload_d2h_stream())
        self._stage_queues[0].append(ret)
        return ret

    def process_stage(self, stage_idx, func):
        assert self._stage_queues[stage_idx]
        store = self._stage_queues[stage_idx].pop(0)
        ret = func(store)
        self._stage_queues[stage_idx + 1].append(store)
        return ret

    def offload(self):
        return self.process_stage(0, lambda x: x.offload_data())

    def release_offload(self):
        return self.process_stage(1, lambda x: x.release_offload())

    def prepare_resume(self):
        return self.process_stage(2, lambda x: x.prepare_resume())

    def resume(self):
        return self.process_stage(3, lambda x: x.resume_data())

    def release_resume(self, store_deprecated=None):
        self.process_stage(4, lambda x: x.release_resume())
        self._pool.append(self._stage_queues[5].pop(0))

    def is_empty(self):
        return sum([len(x) for x in self._stage_queues]) == 0

import os

def _is_debug_flag_active(flag_name: str, fallback: bool = False) -> bool:
    env_value = os.environ.get(flag_name)
    if env_value is None:
        return fallback
    return env_value.strip().lower() in ("1", "true")

def _should_skip_model_logging() -> bool:
