import logging
from .base import Collector, CollectorResult
from ..speedtest import SpeedtestClient

logger = logging.getLogger("docsis.collector.speedtest")

class SpeedtestDataGatherer(Collector):
    """Collects and caches speed test data from Speedtest Tracker."""
    identifier = "speedtest"

    def __init__(self, config_handler, data_store, web_interface, update_frequency=300):
        super().__init__(update_frequency)
        self._config = config_handler
        self._storage = data_store
        self._web = web_interface
        self._client_instance = None
        self._previous_endpoint = None

    def is_active(self) -> bool:
        return self._config.is_speedtest_enabled()

    def _prepare_client(self):
        """Re-initialize client when the configured tracker URL changes."""
        endpoint = self._config.get("speedtest_tracker_url")
        if endpoint != self._previous_endpoint:
            api_token = self._config.get("speedtest_tracker_token")
            self._client_instance = SpeedtestClient(endpoint, api_token)
            self._previous_endpoint = endpoint
            logger.info("Speedtest Tracker endpoint: %s", endpoint)

    def gather(self) -> CollectorResult:
        self._prepare_client()

        # Fetch latest result for UI display
        latest_results = self._client_instance.fetch_latest(1)
        if latest_results:
            self._web.set_state(speedtest_latest=latest_results[0])

        # Update local cache (non-critical operation)
        try:
            most_recent_id = self._storage.get_latest_speedtest_record_id()
            current_cache_size = self._storage.count_speedtest_records()

            if current_cache_size < 50:
                batch_results = self._client_instance.fetch_all_results(limit=2000)
            else:
                batch_results = self._client_instance.fetch_updates_since(most_recent_id)

            if batch_results:
                self._storage.store_speedtest_data(batch_results)
                logger.info(
                    "Added %d new speedtest entries (cumulative: %d)",
                    len(batch_results),
                    current_cache_size + len(batch_results),
                )
        except Exception as error:
            logger.warning("Failed to update speedtest cache: %s", str(error))

        return CollectorResult(origin=self.identifier)

