class RequestHandler(BaseHTTPRequestHandler):
    """Custom HTTP request handler for mock authentication endpoints."""

    def handle_get_request(self) -> None:
        """Process incoming GET requests based on path routing."""
        route_map = {
            "/.well-known/jwks.json": PUBLIC_KEYS,
            "/tokens": USER_TOKENS,
            "/health": {"status": "ok"}
        }

        if self.path in route_map:
            self._send_json_response(route_map[self.path])
        else:
            self.send_error(404, "Not Found")

    def _send_json_response(self, payload: Dict[str, Any]) -> None:
        """Serialize and send JSON response with proper headers."""
        encoded_body = json.dumps(payload).encode('utf-8')
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", len(encoded_body))
        self.end_headers()
        self.wfile.write(encoded_body)

    def log_message(self, format_string: str, *arguments: Any) -> None:
        """Override to suppress default logging behavior."""
        pass  # Silent logging as per original design

