import logging
import time
from datetime import date, timedelta
from .base import Collector, CollectorResult
from .. import thinkbroadband

log = logging.getLogger("docsis.collector.bqm")

class BQMCollector(Collector):
    """Collects BQM quality metrics daily based on configured time.
    Stores the previous day's data if collection occurs before noon,
    otherwise stores current day's data.
    """
    name = "bqm"

    def __init__(self, config_handler, storage_backend, poll_interval=86400):
        super().__init__(poll_interval)
        self._config_handler = config_handler
        self._storage_backend = storage_backend
        self._collected_date = None

    def is_active(self) -> bool:
        return self._config_handler.is_bqm_enabled()

    def needs_collection(self) -> bool:
        """Determines if collection should proceed today."""
        current_date = time.strftime("%Y-%m-%d")
        if current_date == self._collected_date:
            return False

        scheduled_time = self._config_handler.get("bqm_collect_time") or "02:00"
        current_time = time.strftime("%H:%M")
        return current_time >= scheduled_time

    def execute(self) -> CollectorResult:
        current_date = time.strftime("%Y-%m-%d")
        if current_date == self._collected_date:
            return CollectorResult(source=self.name, data={"skipped": True})

        bqm_url = self._config_handler.get("bqm_url")
        graph_data = thinkbroadband.retrieve_graph(bqm_url)

        if graph_data:
            collection_hour = self._config_handler.get("bqm_collect_time") or "02:00"
            if collection_hour < "12:00":
                effective_date = (date.today() - timedelta(days=1)).isoformat()
            else:
                effective_date = date.today().isoformat()

            self._storage_backend.store_bqm_image(graph_data, date_str=effective_date)
            self._collected_date = current_date
            return CollectorResult(source=self.name)

        return CollectorResult(
            source=self.name, 
            success=False, 
            error="BQM graph retrieval failed"
        )

import gc
import logging
import time

logger = logging.getLogger(__name__)

class PeriodicGarbageCollector:
    """Utility class to trigger garbage collection at regular intervals during execution."""

    def __init__(self, collection_interval: int = 1000):
        if collection_interval <= 0:
            raise ValueError("collection_interval must be a positive integer")

        self.collection_interval = collection_interval
        gc.disable()
        self._perform_collection("Initial garbage collection")

    def check_and_collect(self, current_step: int) -> None:
        """Conditionally perform garbage collection based on step count."""
        if current_step > 0 and current_step % self.collection_interval == 0:
            self._perform_collection(f"Periodic GC triggered at step {current_step}")

    @staticmethod
    def _perform_collection(description: str, gen: int = 1) -> None:
        """Execute garbage collection and log the duration."""
        start_time = time.perf_counter()
        gc.collect(gen)
        elapsed = time.perf_counter() - start_time
        logger.info("[GC] %s completed in %.3f seconds", description, elapsed)

import os
import ray
from ray.util.placement_group import PlacementGroup
from ray.util.scheduling_strategies import PlacementGroupSchedulingStrategy
from miles.ray.utils import NOSET_VISIBLE_DEVICES_ENV_VARS_LIST


class RayTrainingCluster:
    """
    A cluster of Ray actors configured for distributed training.

    Methods prefixed with 'async' return lists of Ray ObjectRefs.

    Args:
        args (Namespace): Configuration arguments passed to actors.
        node_count (int): Number of nodes involved in this training group.
        gpus_per_node (int): Number of GPUs available per node.
        pg_bundle (tuple[PlacementGroup, list[int], list[int]]):
            Predefined placement group and associated indices/GPU IDs.
        gpus_per_actor (float, optional): GPUs allocated per actor; <1 allows sharing.
        role_name (str, optional): Role identifier for actor initialization.
    """

    def __init__(
        self,
        args,
        node_count: int,
        gpus_per_node: int,
        pg_bundle: tuple[PlacementGroup, list[int], list[int]],
        gpus_per_actor: float = 1.0,
        role_name: str = "trainer",
    ) -> None:
        self.config = args
        self.node_count = node_count
        self.gpus_per_node = gpus_per_node
        self.role_name = role_name

        # Reserve GPU resources before instantiating actors
        self._reserve_gpu_resources(pg_bundle, gpus_per_actor)

    def _reserve_gpu_resources(self, pg_bundle, gpus_per_actor):
        total_workers = self.node_count * self.gpus_per_node
        assert pg_bundle is not None, "Placement group must be provided."

        pg, bundle_indices, gpu_ids = pg_bundle

        env_config = self._build_env_vars()
        if self.config.offload_train and self.config.train_backend == "megatron":
            self._inject_memory_saver_env(env_config)

        # Select actor implementation based on backend
        backend = self.config.train_backend
        actor_class = (
            MegatronTrainRayActor
            if backend == "megatron"
            else FSDPTrainRayActor
        )

        # Wrap actor class with Ray remote decorator
        RemoteActor = ray.remote(
            num_gpus=1,
            runtime_env={"env_vars": env_config}
        )(actor_class)

        # Instantiate actors with scheduling constraints
        self.workers = []
        master_address, master_port = None, None

        for idx, worker_rank in enumerate(range(total_workers)):
            actor_options = dict(
                num_cpus=gpus_per_actor,
                num_gpus=gpus_per_actor,
                scheduling_strategy=PlacementGroupSchedulingStrategy(
                    placement_group=pg,
                    placement_group_bundle_index=bundle_indices[idx],
                ),
            )
            worker = RemoteActor.options(**actor_options).remote(
                total_workers, worker_rank, master_address, master_port
            )
            if idx == 0:
                master_address, master_port = ray.get(worker.get_master_addr_and_port.remote())
            self.workers.append(worker)

    def _build_env_vars(self):
        base_env = {
            "NCCL_CUMEM_ENABLE": os.environ.get("NCCL_CUMEM_ENABLE", "0"),
            "NVTE_FP8_BLOCK_SCALING_FP32_SCALES": "1",
        }
        base_env.update({var: "1" for var in NOSET_VISIBLE_DEVICES_ENV_VARS_LIST})
        base_env.update(getattr(self.config, "train_env_vars", {}))
        return base_env

    def _inject_memory_saver_env(self, env_dict):
        import torch_memory_saver
        lib_path = os.path.join(
            os.path.dirname(os.path.dirname(torch_memory_saver.__file__)),
            "torch_memory_saver_hook_mode_preload.abi3.so",
        )
        if not os.path.isfile(lib_path):
            raise FileNotFoundError(f"Required shared library missing: {lib_path}")
        env_dict["LD_PRELOAD"] = lib_path
        env_dict["TMS_INIT_ENABLE"] = "1"
        env_dict["TMS_INIT_ENABLE_CPU_BACKUP"] = "1"

    def async_initialize(self, config, role, include_ref=False):
        """Initialize models, optimizers, and checkpoint state across workers."""
        return [w.init.remote(config, role, with_ref=include_ref) for w in self.workers]

    def async_train_step(self, rollout_id, data_ref):
        """Execute one training step per worker."""
        return [w.train.remote(rollout_id, data_ref) for w in self.workers]

    def persist_model(self, rollout_id, sync_immediately=False):
        """Trigger model saving on all workers and collect results synchronously."""
        return ray.get([w.save_model.remote(rollout_id, force_sync=sync_immediately) for w in self.workers])

    def replicate_weights(self):
        """Broadcast updated weights from rank 0 to all other workers."""
        return ray.get([w.update_weights.remote() for w in self.workers])

    def activate(self):
        """Ensure all workers are active (e.g., load models into GPU memory)."""
        return ray.get([w.wake_up.remote() for w in self.workers])

    def deactivate(self):
        """Offload models from GPU memory."""
        return ray.get([w.sleep.remote() for w in self.workers])

    def flush_memory(self):
        """Explicitly clear cached memory on each worker."""
        return ray.get([w.clear_memory.remote() for w in self.workers])

    def link_with_critic(self, critic_cluster):
        """Establish inter-worker communication between actor and critic clusters."""
        return ray.get([
            actor.link_actor_critic.remote(critic)
            for actor, critic in zip(self.workers, critic_cluster.workers)
        ])

    def assign_rollout_controller(self, controller):
        """Assign rollout manager object to each worker."""
        return ray.get([w.set_rollout_manager.remote(controller) for w in self.workers])

import json
import sys
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from datetime import datetime

PLANNING_FILES = ['task_plan.md', 'progress.md', 'findings.md']

def get_project_dir(project_path: str) -> Path:
    """Convert project path to Claude's storage path format."""
    sanitized = project_path.replace('/', '-')
    if not sanitized.startswith('-'):
        sanitized = '-' + sanitized
    sanitized = sanitized.replace('_', '-')
    return Path.home() / '.claude' / 'projects' / sanitized

def get_sessions_sorted(project_dir: Path) -> List[Path]:
    """Get all session files sorted by modification time (newest first)."""
    sessions = list(project_dir.glob('*.jsonl'))
    main_sessions = [s for s in sessions if not s.name.startswith('agent-')]
    return sorted(main_sessions, key=lambda p: p.stat().st_mtime, reverse=True)

def parse_session_messages(session_file: Path) -> List[Dict]:
    """Parse all messages from a session file, preserving order."""
    messages = []
    with open(session_file, 'r') as f:
        for line_num, line in enumerate(f):
            try:
                data = json.loads(line)
                data['_line_num'] = line_num
                messages.append(data)
            except json.JSONDecodeError:
                pass
    return messages

def find_last_planning_update(messages: List[Dict]) -> Tuple[int, Optional[str]]:
    """
    Find the last time a planning file was written/edited.
    Returns (line_number, filename) or (-1, None) if not found.
    """
    last_update_line = -1
    last_update_file = None
    for msg in messages:
        msg_type = msg.get('type')
        if msg_type == 'assistant':
            content = msg.get('message', {}).get('content', [])
            if isinstance(content, list):
                for item in content:
                    if item.get('type') == 'tool_use':
                        tool_name = item.get('name', '')
                        tool_input = item.get('input', {})
                        if tool_name in ('Write', 'Edit'):
                            file_path = tool_input.get('file_path', '')
                            for pf in PLANNING_FILES:
                                if file_path.endswith(pf):
                                    last_update_line = msg['_line_num']
                                    last_update_file = pf
    return last_update_line, last_update_file

def extract_messages_after(messages: List[Dict], after_line: int) -> List[Dict]:
    """Extract conversation messages after a certain line number."""
    result = []
    for msg in messages:
        if msg['_line_num'] <= after_line:
            continue
        msg_type = msg.get('type')
        is_meta = msg.get('isMeta', False)
        if msg_type == 'user' and not is_meta:
            content = msg.get('message', {}).get('content', '')
            if isinstance(content, list):
                for item in content:
                    if isinstance(item, dict) and item.get('type') == 'text':
                        content = item.get('text', '')
                        break
                else:
                    content = ''
            if content and isinstance(content, str):
                if content.startswith(('<local-command', '<command-', '<task-notification')):
                    continue
                if len(content) > 20:
                    result.append({'role': 'user', 'content': content, 'line': msg['_line_num']})
        elif msg_type == 'assistant':
            msg_content = msg.get('message', {}).get('content', '')
            text_content = ''
            tool_uses = []
            if isinstance(msg_content, str):
                text_content = msg_content
            elif isinstance(msg_content, list):
                for item in msg_content:
                    if item.get('type') == 'text':
                        text_content = item.get('text', '')
                    elif item.get('type') == 'tool_use':
                        tool_name = item.get('name', '')
                        tool_input = item.get('input', {})
                        if tool_name == 'Edit':
                            tool_uses.append(f"Edit: {tool_input.get('file_path', 'unknown')}")
                        elif tool_name == 'Write':
                            tool_uses.append(f"Write: {tool_input.get('file_path', 'unknown')}")
                        elif tool_name == 'Bash':
                            cmd = tool_input.get('command', '')[:80]
                            tool_uses.append(f"Bash: {cmd}")
                        else:
                            tool_uses.append(f"{tool_name}")
            if text_content or tool_uses:
                result.append({
                    'role': 'assistant',
                    'content': text_content[:600] if text_content else '',
                    'tools': tool_uses,
                    'line': msg['_line_num']
                })
    return result

def main():
    project_path = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    project_dir = get_project_dir(project_path)

    # Check if planning files exist (indicates active task)
    has_planning_files = any(
        Path(project_path, f).exists() for f in PLANNING_FILES
    )

    if not project_dir.exists():
        # No previous sessions, nothing to catch up on
        return

    sessions = get_sessions_sorted(project_dir)
    if len(sessions) < 1:
        return

    # Find a substantial previous session
    target_session = None
    for session in sessions:
        if session.stat().st_size > 5000:
            target_session = session
            break
    if not target_session:
        return

    messages = parse_session_messages(target_session)
    last_update_line, last_update_file = find_last_planning_update(messages)

    # Only output if there's unsynced content
    if last_update_line < 0:
        messages_after = extract_messages_after(messages, len(messages) - 30)
    else:
        messages_after = extract_messages_after(messages, last_update_line)

    if not messages_after:
        return

    # Output catchup report
    print("\n[planning-with-files] SESSION CATCHUP DETECTED")
    print(f"Previous session: {target_session.stem}")
    if last_update_line >= 0:
        print(f"Last planning update: {last_update_file} at message #{last_update_line}")
        print(f"Unsynced messages: {len(messages_after)}")
    else:
        print("No planning file updates found in previous session")

    print("\n--- UNSYNCED CONTEXT ---")
    for msg in messages_after[-15:]:  # Last 15 messages
        if msg['role'] == 'user':
            print(f"USER: {msg['content'][:300]}")
        else:
            if msg.get('content'):
                print(f"CLAUDE: {msg['content'][:300]}")
            if msg.get('tools'):
                print(f"  Tools: {', '.join(msg['tools'][:4])}")

    print("\n--- RECOMMENDED ---")
    print("1. Run: git diff --stat")
    print("2. Read: task_plan.md, progress.md, findings.md")
    print("3. Update planning files based on above context")
    print("4. Continue with task")

if __name__ == '__main__':
    main()

# Reimplementation of expert weight mapping logic with altered control flow and variable naming

from typing import Dict, Tuple
import torch
from megatron.bridge.models.conversion.param_mapping import AutoMapping, GatedMLPMapping
from megatron.bridge.models.conversion.utils import get_module_and_param_from_name
from megatron.bridge.utils.common_utils import extract_expert_number_from_param


def _pick_expert_slice(tensor: torch.Tensor, expert_id: int) -> torch.Tensor:
    """Select the slice corresponding to a specific expert index."""
    if tensor.dim() >= 3:
        return tensor[expert_id]
    return tensor


def _match_tensor_to_shape(source: torch.Tensor, expected: torch.Size, param_name: str) -> torch.Tensor:
    """Ensure source tensor matches expected shape via transpose or direct match."""
    src_shape = tuple(source.shape)
    exp_shape = tuple(expected)

    if src_shape == exp_shape:
        return source.contiguous()

    # Try transposed version for 2D tensors
    if source.ndim == 2 and tuple(source.t().shape) == exp_shape:
        return source.t().contiguous()

    raise ValueError(f"Shape mismatch for '{param_name}': got {src_shape}, expected {exp_shape}")


class _FlexibleGatedMLPMapping(GatedMLPMapping):
    """Relaxed version of GatedMLPMapping that skips strict pattern validation."""
    def _check_wildcard_consistency(self, *args, **kwargs):
        # Intentionally left blank — no wildcard count enforcement
        pass


class GLMExpertGateUpProjMapping(AutoMapping):
    """Handles fused gate+up projection weights for experts."""

    def __init__(self, megatron_key: str, hf_key: str, permute_dims=None):
        super().__init__(megatron_key, hf_key, permute_dims)

        self._fused_mapping = _FlexibleGatedMLPMapping(
            megatron_param=self.megatron_param,
            gate=f"{self.hf_param}.gate",
            up=f"{self.hf_param}.up",
        )

    def hf_to_megatron(self, hf_data: torch.Tensor, mcore_module: torch.nn.Module) -> torch.Tensor:
        expert_idx = extract_expert_number_from_param(self.megatron_param)
        selected_weight = _pick_expert_slice(hf_data, expert_idx)
        normalized_name = self._normalize_expert_param_name(self.megatron_param)
        _, target_param = get_module_and_param_from_name(mcore_module, normalized_name)

        full_shape = target_param.shape
        half_dim = full_shape[0] // 2

        if full_shape[0] % 2 != 0:
            raise ValueError(f"Fused dimension must be even for '{self.megatron_param}', got {full_shape[0]}.")

        gate_target_shape = (half_dim, full_shape[1])

        # Handle pre-fused vs separately stored gate/up cases
        if selected_weight.ndim == 3 and selected_weight.shape[0] == 2:
            gate_part = _match_tensor_to_shape(selected_weight[0], gate_target_shape, "gate")
            up_part = _match_tensor_to_shape(selected_weight[1], gate_target_shape, "up")
        else:
            aligned_weight = _match_tensor_to_shape(selected_weight, full_shape, "gate_up")
            gate_part, up_part = torch.chunk(aligned_weight, 2, dim=0)

        return self._fused_mapping.hf_to_megatron({"gate": gate_part, "up": up_part}, mcore_module)

    def megatron_to_hf(
        self, mcore_weights: torch.Tensor, mcore_module: torch.nn.Module
    ) -> Dict[str, torch.Tensor]:
        intermediate = self._fused_mapping.megatron_to_hf(mcore_weights, mcore_module)
        if not intermediate:
            return {}

        fused_result: Dict[str, torch.Tensor] = {}
        for key, value in intermediate.items():
            if not key.endswith(".gate"):
                continue

            base_key = key[:-len(".gate")]
            up_value = intermediate.get(f"{base_key}.up")

            if up_value is None:
                continue

            concat_axis = 0 if value.ndim == 2 else 1
            fused_result[base_key] = torch.cat([value, up_value], dim=concat_axis)

        return fused_result

    def _check_wildcard_consistency(self, *args, **kwargs):
        # Skip wildcard count validation
        pass


class GLMExpertDownProjMapping(AutoMapping):
    """Maps down projection weights for individual experts."""

    def __init__(self, megatron_key: str, hf_key: str, permute_dims=None):
        super().__init__(megatron_key, hf_key, permute_dims)

    def hf_to_megatron(self, hf_data: torch.Tensor, mcore_module: torch.nn.Module) -> torch.Tensor:
        expert_idx = extract_expert_number_from_param(self.megatron_param)
        selected_weight = _pick_expert_slice(hf_data, expert_idx)
        normalized_name = self._normalize_expert_param_name(self.megatron_param)
        _, target_param = get_module_and_param_from_name(mcore_module, normalized_name)

        aligned_weight = _match_tensor_to_shape(selected_weight, target_param.shape, "down_proj")
        return super().hf_to_megatron(aligned_weight, mcore_module)

    def _check_wildcard_consistency(self, *args, **kwargs):
        # Skip wildcard validation for flexibility
        pass

import os
import torch
import torch.distributed as dist

# Replaced logger import with local definition to avoid external dependency
class _DummyLogger:
    def warning(self, msg): pass
logger = _DummyLogger()


def _get_rank():
    return dist.get_rank() if dist.is_initialized() else 0


class TokenBuffer:
    def __init__(self):
        self._read_head = 0
        self._write_head = 0
        self._storage: list[torch.Tensor] = []

    def store(self, indices: torch.Tensor):
        buffer = torch.empty_like(indices, device="cpu", pin_memory=True)
        buffer.copy_(indices)
        self._storage.append(buffer)

    def read_forward(self) -> torch.Tensor:
        if self._read_head >= len(self._storage):
            shapes = [
                t.shape if isinstance(t, torch.Tensor) else f"non-tensor({type(t)})"
                for t in self._storage
            ]
            raise IndexError(
                f"read_forward out of bounds: index={self._read_head}, "
                f"size={len(self._storage)}, shapes={shapes}"
            )
        item = self._storage[self._read_head]
        self._read_head += 1
        return item.to(torch.cuda.current_device())

    def read_backward(self) -> torch.Tensor:
        item = self._storage[self._write_head]
        self._write_head += 1
        return item.to(torch.cuda.current_device())

    def reset_all(self):
        self._read_head = 0
        self._write_head = 0
        self._storage.clear()

    def reset_read(self):
        self._read_head = 0


class BaseReplayController:
    name: str = ""
    filename: str = ""

    def __init__(self):
        self._buffers: list[TokenBuffer] = []
        self._active_buffer: TokenBuffer | None = None
        self._is_active = False
        self._current_phase = "fallthrough"

    def spawn_buffer(self) -> TokenBuffer:
        buf = TokenBuffer()
        self._buffers.append(buf)
        return buf

    def activate_buffer(self, buf: TokenBuffer):
        self._active_buffer = buf

    def get_active(self) -> TokenBuffer | None:
        return self._active_buffer

    def flush_all(self):
        for b in self._buffers:
            b.reset_all()

    def flush_reads(self):
        for b in self._buffers:
            b.reset_read()

    def wrap_topk(self, original_fn, include_probs: bool):
        controller = self

        def _reconstruct_from_replay(retrieved_indices, scores, k, *args, **kwargs):
            assert (
                retrieved_indices.size(0) == scores.size(0)
            ), f"rank {_get_rank()}: replay token count mismatch: {retrieved_indices.size(0)} vs {scores.size(0)}"
            assert (
                retrieved_indices.size(1) == k
            ), f"topk mismatch: expected {k}, got {retrieved_indices.size(1)}"

            if controller._check_enabled:
                controller.validate_replay(original_fn, scores, k, retrieved_indices, *args, **kwargs)

            pad_mask = retrieved_indices == -1
            if pad_mask.any():
                flat_pad_count = pad_mask.sum().item()
                replacement = torch.arange(flat_pad_count, device=retrieved_indices.device, dtype=retrieved_indices.dtype)
                retrieved_indices[pad_mask] = replacement % scores.size(1)

            if include_probs:
                probs = scores.gather(1, retrieved_indices)
                return probs, retrieved_indices
            else:
                return retrieved_indices

        def modified_topk(scores, k, *args, **kwargs):
            if not controller._is_active:
                return original_fn(scores, k, *args, **kwargs)

            phase = controller._current_phase
            active_buf = controller.get_active()

            if phase == "fallthrough":
                return original_fn(scores, k, *args, **kwargs)
            elif phase == "capture":
                result = original_fn(scores, k, *args, **kwargs)
                top_indices = result[1] if isinstance(result, tuple) else result
                active_buf.store(top_indices)
                return result
            elif phase == "restore_fwd":
                return _reconstruct_from_replay(active_buf.read_forward(), scores, k, *args, **kwargs)
            elif phase == "restore_bwd":
                return _reconstruct_from_replay(active_buf.read_backward(), scores, k, *args, **kwargs)
            else:
                return original_fn(scores, k, *args, **kwargs)

        return modified_topk

    def attach_to_module(self, module, attr_name: str):
        if not self._is_active:
            return

        buf = self.spawn_buffer()
        setattr(module, attr_name, buf)

        controller = self

        def pre_hook(*_, **__):
            controller.activate_buffer(buf)

        module.register_forward_pre_hook(pre_hook)

    def validate_replay(self, orig_fn, scores, k, retrieved_indices, *args, **kwargs):
        """
        CI validation for R3. Only active when _check_enabled is True.
        Compares original routing decisions against replayed ones.
        Raises error if mismatch exceeds threshold.
        """
        ground_truth = orig_fn(scores, k, *args, **kwargs)
        if isinstance(ground_truth, tuple):
            _, ground_truth = ground_truth

        # Flatten for per-token comparison
        orig_flat = ground_truth.view(-1, ground_truth.size(-1))   # [N, K_orig]
        replay_flat = retrieved_indices.view(-1, retrieved_indices.size(-1))  # [N, K_rep]

        # Broadcast equality check: [N, K_orig, 1] == [N, 1, K_rep] => [N, K_orig, K_rep]
        overlaps = orig_flat.unsqueeze(2) == replay_flat.unsqueeze(1)
        # Exclude padding (-1) matches
        valid_match = (orig_flat != -1).unsqueeze(2) & (replay_flat != -1).unsqueeze(1)
        overlaps &= valid_match
        has_overlap = overlaps.any(dim=(1, 2))  # [N]
        is_padding_only = (replay_flat == -1).all(dim=1)
        mismatches = ~has_overlap & ~is_padding_only

        total_mismatches = mismatches.sum().item()
        if total_mismatches == 0:
            return

        threshold = float(os.getenv("MILES_TEST_R3_THRESHOLD", self._threshold))
        max_allowed = int(threshold * orig_flat.size(0))

        # Log detailed mismatches
        bad_indices = mismatches.nonzero(as_tuple=False).squeeze(1)
        for idx in bad_indices:
            i = idx.item()
            snippet = []
            start = max(0, i - 3)
            end = min(orig_flat.size(0), i + 4)
            for j in range(start, end):
                marker = " <<<" if j == i else ""
                snippet.append(
                    f"  token {j}: orig={orig_flat[j].tolist()}, replay={replay_flat[j].tolist()}{marker}"
                )
            logger.warning(
                f"R3 validation (rank {_get_rank()}, phase {self._current_phase}): "
                f"token {i} has zero overlap, topk={k}\n" + "\n".join(snippet)
            )

        if total_mismatches > max_allowed:
            raise AssertionError(
                f"R3 mismatch ({total_mismatches}) exceeds limit ({max_allowed})"
            )


