import abc
from typing import Dict, Optional, List, Any
from blankly.utils import utils
from blankly.enums import MarginType, HedgeMode, PositionMode, OrderType, Side, TimeInForce, ContractType
from blankly.exchanges.interfaces.base_interface import BaseExchangeInterface
from blankly.exchanges.orders.futures.order import FuturesOrder


class AbstractFuturesAdapter(BaseExchangeInterface, abc.ABC):
    """
    Abstract base class for futures exchange adapters.
    Enforces implementation of core exchange interaction patterns.
    """

    def __init__(self,
                 ex_name: str,
                 api_client,
                 config_path: Optional[str] = None):
        self._exchange_id = ex_name
        self._client = api_client
        self._prefs = utils.fetch_user_config(config_path)
        self._state_cache = {}
        self._currency_map = {}
        if self._prefs.get('settings', {}).get('verify_connection_on_login', True):
            self._bootstrap_exchange()

    @property
    def identifier(self) -> str:
        """Returns the unique identifier for this exchange instance."""
        return self._exchange_id

    @staticmethod
    def normalize_to_internal(symbol: str) -> str:
        """Converts exchange-specific symbol to internal representation."""
        return symbol

    @staticmethod
    def denormalize_from_internal(symbol: str) -> str:
        """Converts internal symbol back to exchange-specific format."""
        return symbol

    def get_exchange_id(self) -> str:
        """Alias for `identifier`, returns exchange name."""
        return self._exchange_id

    @abc.abstractmethod
    def _bootstrap_exchange(self):
        """Performs initial setup and validation upon initialization."""
        raise NotImplementedError

    @abc.abstractmethod
    def list_tradable_assets(self, asset_filter: str = None) -> Dict[str, Any]:
        """Lists all available trading pairs; optionally filtered by `asset_filter`."""
        raise NotImplementedError

    @abc.abstractmethod
    def fetch_account_summary(self, asset: str = None) -> Dict[str, Any]:
        """Fetches account-level balances; optionally scoped to a specific asset."""
        raise NotImplementedError

    @abc.abstractmethod
    def fetch_current_position(self, asset: str = None) -> Optional[Dict[str, Any]]:
        """Retrieves current open position(s); optionally for a single asset."""
        raise NotImplementedError

    @abc.abstractmethod
    def place_market_order(self,
                           pair: str,
                           direction: Side,
                           qty: float,
                           mode: PositionMode = None,
                           only_reduce: bool = False) -> FuturesOrder:
        """Submits a market order."""
        raise NotImplementedError

    @abc.abstractmethod
    def place_limit_order(self,
                          pair: str,
                          direction: Side,
                          limit_price: float,
                          qty: float,
                          mode: PositionMode = None,
                          only_reduce: bool = False,
                          expiry_policy: TimeInForce = None) -> FuturesOrder:
        """Submits a limit order."""
        raise NotImplementedError

    @abc.abstractmethod
    def place_take_profit(self,
                          pair: str,
                          direction: Side,
                          trigger_price: float,
                          qty: float,
                          mode: PositionMode = None) -> FuturesOrder:
        """Places a take-profit conditional order."""
        raise NotImplementedError

    @abc.abstractmethod
    def place_stop_loss(self,
                        pair: str,
                        direction: Side,
                        trigger_price: float,
                        qty: float,
                        mode: PositionMode = None) -> FuturesOrder:
        """Places a stop-loss conditional order."""
        raise NotImplementedError

    @abc.abstractmethod
    def configure_hedge_mode(self, enabled: HedgeMode):
        """Enables or disables hedge mode on the exchange."""
        raise NotImplementedError

    @abc.abstractmethod
    def is_hedged(self) -> bool:
        """Returns whether hedge mode is currently active."""
        raise NotImplementedError

    @abc.abstractmethod
    def set_leverage(self, multiplier: float, asset: str = None):
        """Sets leverage for a given asset or globally."""
        raise NotImplementedError

    @abc.abstractmethod
    def query_leverage(self, asset: str = None) -> float:
        """Queries current leverage setting."""
        raise NotImplementedError

    @abc.abstractmethod
    def update_margin_mode(self, asset: str, mode: MarginType):
        """Switches margin type (e.g., isolated/crossed)."""
        raise NotImplementedError

    @abc.abstractmethod
    def retrieve_margin_mode(self, asset: str) -> MarginType:
        """Gets current margin mode for an asset."""
        raise NotImplementedError

    @abc.abstractmethod
    def cancel_active_order(self, pair: str, order_ref: int) -> FuturesOrder:
        """Cancels a specific open order."""
        raise NotImplementedError

    @abc.abstractmethod
    def list_pending_orders(self, pair: str = None) -> List[FuturesOrder]:
        """Lists all active orders, optionally filtered by symbol."""
        raise NotImplementedError

    @abc.abstractmethod
    def fetch_order_status(self, pair: str, order_id: int) -> FuturesOrder:
        """Fetches detailed status of a specific order."""
        raise NotImplementedError

    @abc.abstractmethod
    def get_latest_price(self, pair: str) -> float:
        """Fetches the most recent market price for a given pair."""
        raise NotImplementedError

    # --- Properties ---

    @property
    def portfolio_summary(self) -> Dict[str, Any]:
        """Convenience property for account data."""
        return self.fetch_account_summary()

    @property
    def active_positions(self) -> Dict[str, Any]:
        """Convenience property for current positions."""
        return self.fetch_current_position()

    @property
    def pending_orders_list(self) -> List[FuturesOrder]:
        """Convenience property for open orders."""
        return self.list_pending_orders()

    @property
    def free_cash(self) -> float:
        """Available cash balance in the configured base currency."""
        base_currency = self._prefs['settings'][self._exchange_id].get('base_currency', 'USD')
        return self.fetch_account_summary(base_currency).get('free', 0.0)

    @abc.abstractmethod
    def historical_funding_rates(self, pair: str, start_ts: int, end_ts: int) -> List[Dict[str, Any]]:
        """
        Retrieve funding rate history between timestamps.
        Returns list of {'rate': float, 'timestamp': int}
        """
        raise NotImplementedError

    @abc.abstractmethod
    def current_funding_rate(self, pair: str) -> float:
        """Get the latest published funding rate."""
        raise NotImplementedError

    @abc.abstractmethod
    def maker_commission_rate(self) -> float:
        """Returns the maker fee percentage."""
        raise NotImplementedError

    @abc.abstractmethod
    def taker_commission_rate(self) -> float:
        """Returns the taker fee percentage."""
        raise NotImplementedError

    @abc.abstractmethod
    def funding_interval_seconds(self) -> int:
        """Returns the interval (in seconds) between funding events."""
        raise NotImplementedError

    @property
    def auto_rounding_enabled(self) -> bool:
        """Whether automatic rounding/truncation is enabled per user settings."""
        return self._prefs.get('settings', {}).get('enable_auto_rounding', False)

from __future__ import annotations
import logging
from collections.abc import Callable, Iterable
from typing import TYPE_CHECKING, Any
import torch
from torch.amp.grad_scaler import GradScaler
from noether.core.schemas.optimizers import OptimizerConfig
from noether.core.utils.bidict import Bidict
from noether.core.utils.logging import float_to_scientific_notation
from noether.core.utils.torch import NoopGradScaler

if TYPE_CHECKING:
    from noether.core.models import Model
    from noether.core.optimizer.param_group_modifiers import ParamGroupModifierBase
    from noether.core.utils.training.counter import UpdateCounter
    from noether.core.utils.training.schedule_wrapper import ScheduleWrapper


class OptimizerAdapter:
    """Adapts a PyTorch optimizer to support advanced training features such as:
        - selective weight decay (e.g., excluding biases/norm params)
        - per-parameter-group learning rate scaling
        - dynamic scheduling of LR & weight decay
        - gradient clipping & mixed-precision handling
    See `OptimizerConfig` in `noether.core.schemas.optimizers` for supported options.
    """

    lr_scheduler: ScheduleWrapper | None = None
    wd_scheduler: ScheduleWrapper | None = None

    def __init__(
        self,
        model: Model,
        optim_factory: Callable[[Iterable[dict[str, Any]]], torch.optim.Optimizer],
        config: OptimizerConfig,
        progress_tracker: UpdateCounter | None = None,
    ):
        """
        Args:
            model: Parameters of this model will be optimized.
            optim_factory: A callable returning an instance of `torch.optim.Optimizer`, taking parameter groups.
            config: Configuration object specifying optimizer behavior.
            progress_tracker: Optional counter tracking training progress for scheduling.
        """
        from noether.core.factory import Factory, ScheduleFactory

        self._logger = logging.getLogger(self.__class__.__name__)
        self._model = model
        self._progress = progress_tracker
        self._cfg = config

        # Build initial param groups using modifiers
        pg_modifiers = Factory().create_list(config.param_group_modifiers_config)
        self._logger.debug(
            f"exclude_bias_from_wd={config.exclude_bias_from_weight_decay}, "
            f"exclude_norm_from_wd={config.exclude_normalization_params_from_weight_decay}, "
            f"pg_modifiers=[{' '.join(str(m) for m in pg_modifiers)}]"
        )

        raw_groups = self._build_param_groups(model, pg_modifiers)
        grouped, group_names = self._consolidate_identical_groups(raw_groups)
        grouped = self._annotate_group_names(grouped)

        self._log_groups(grouped, group_names)

        # Map parameter indices to names for checkpointing
        self._idx_to_name = Bidict[int, str]()
        idx = 0
        for names in group_names:
            for name in names:
                self._idx_to_name.set(idx, name)
                idx += 1

        # Instantiate underlying optimizer
        self._optim = optim_factory(grouped)

        # Prepare for gradient clipping if needed
        self._all_params = None
        if config.clip_grad_value is not None or config.clip_grad_norm is not None:
            self._all_params = list(model.parameters())

        # Apply layer-wise LR scaling
        self._apply_lr_scaling()

        # Initialize schedulers
        if config.schedule_config is not None:
            self.lr_scheduler = ScheduleFactory().create(
                config.schedule_config,
                update_counter=self._progress,
            )
        if config.weight_decay_schedule is not None:
            self.wd_scheduler = ScheduleFactory().create(
                config.weight_decay_schedule,
                update_counter=self._progress,
            )
            # Preserve original WD status before broadcasting
            for grp in self._optim.param_groups:
                assert "skip_wd" not in grp
                grp["skip_wd"] = grp["weight_decay"] == 0.0

    def _apply_lr_scaling(self):
        """Apply per-group learning rate multipliers."""
        for group in self._optim.param_groups:
            if "lr_mult" in group:
                if "base_lr" in group:
                    raise RuntimeError("base_lr already present in group")
                group["base_lr"] = group["lr"]
                group["lr"] *= group["lr_mult"]
                self._logger.info(
                    f"Adjusted lr of group '{group['name']}' "
                    f"from {float_to_scientific_notation(group['base_lr'], max_precision=2)} "
                    f"to {float_to_scientific_notation(group['lr'], max_precision=2)}"
                )

    def _log_groups(self, groups: list[dict[str, Any]], group_names: list[list[str]]) -> None:
        def describe_group(grp: dict[str, Any]) -> str:
            parts = []
            for k, v in grp.items():
                if k == "params":
                    continue
                if isinstance(v, float):
                    s = "0" if v == 0.0 else float_to_scientific_notation(v, max_precision=1, remove_plus=True)
                elif isinstance(v, int):
                    s = str(v)
                else:
                    raise TypeError(f"Unsupported type for group attribute: {type(v)}")
                parts.append(f"{k}={s}")
            return " ".join(parts or ["default"]) + f" len(params)={len(grp['params'])}"

        desc = ", ".join(describe_group(g) for g in groups)
        self._logger.info(f"Using {len(groups)} param groups: {desc}")
        for i, names in enumerate(group_names):
            for n in names:
                self._logger.debug(f"- {n}")

    def _build_param_groups(self, model: Model, modifiers: list[ParamGroupModifierBase]) -> list[dict[str, Any]]:
        """Construct raw parameter groups based on model parameters and modifiers."""
        groups = []
        for name, param in model.named_parameters():
            props: dict[str, Any] = {}

            # Handle bias exclusion from weight decay
            if name.rsplit(".", 1)[-1] == "bias" and self._cfg.exclude_bias_from_weight_decay:
                props["weight_decay"] = 0.0
            # Handle normalization-layer parameter exclusion
            elif (
                param.dim() <= 1
                and self._cfg.exclude_normalization_params_from_weight_decay
                and name.rsplit(".", 1)[-1] != "bias"
            ):
                props["weight_decay"] = 0.0

            # Apply custom modifiers
            for mod in modifiers:
                for k, v in mod.get_properties(model, name, param).items():
                    if k == "lr_mult":
                        props.setdefault("lr_mult", 1.0)
                        props["lr_mult"] *= v
                    else:
                        if k in props:
                            raise ValueError(f"Duplicate property '{k}' encountered")
                        props[k] = v

            if "params" in props or "name" in props:
                raise ValueError("Reserved keys 'params' or 'name' cannot be set by modifiers")

            props["name"] = name
            props["params"] = [param]
            groups.append(props)

        # Validate that all modifiers were applied successfully
        for mod in modifiers:
            if not mod.is_complete():
                raise RuntimeError(f"Modifier {mod} did not match any parameters")

        return groups

    def _annotate_group_names(self, groups: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Generate human-readable names for each group."""
        for grp in groups:
            labels = []
            for key, val in grp.items():
                if key == "params":
                    continue
                if isinstance(val, float):
                    label = "0" if val == 0.0 else float_to_scientific_notation(val, max_precision=1, remove_plus=True)
                elif isinstance(val, int):
                    label = str(val)
                else:
                    raise NotImplementedError(f"Cannot format value of type {type(val)}")
                labels.append(f"{key}={label}")
            grp["name"] = "&".join(labels) if labels else "default"
        return groups

    def _consolidate_identical_groups(self, groups: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[list[str]]]:
        """Merge groups that share identical non-param properties."""
        consolidated = []
        signatures = []
        name_lists = []

        for grp in groups:
            name = grp.pop("name")
            sig = {k: v for k, v in grp.items() if k != "params"}

            match_idx = None
            for i, sig_i in enumerate(signatures):
                if sig == sig_i:
                    match_idx = i
                    break

            if match_idx is None:
                consolidated.append(grp)
                signatures.append(sig)
                name_lists.append([name])
            else:
                consolidated[match_idx]["params"].extend(grp["params"])
                name_lists[match_idx].append(name)

        return consolidated, name_lists

    def _has_active_gradients(self) -> bool:
        """Check whether any tracked parameter has non-null gradients."""
        for group in self._optim.param_groups:
            for p in group["params"]:
                if p.grad is not None:
                    return True
        return False

    def step(self, scaler: GradScaler | None = None) -> None:
        """Execute one optimization step, integrating grad scaling, clipping, and stepping."""
        if isinstance(scaler, GradScaler) and not self._has_active_gradients():
            return

        if scaler is None:
            scaler = NoopGradScaler()

        if self._cfg.clip_grad_value is not None or self._cfg.clip_grad_norm is not None:
            scaler.unscale_(self._optim)

        if self._cfg.clip_grad_value is not None:
            torch.nn.utils.clip_grad_value_(self._all_params, self._cfg.clip_grad_value)
        if self._cfg.clip_grad_norm is not None:
            torch.nn.utils.clip_grad_norm_(self._all_params, self._cfg.clip_grad_norm)

        scaler.step(self._optim)
        scaler.update()

    def advance_schedulers(self) -> None:
        """Update parameter groups with current scheduler values."""
        if self.lr_scheduler is not None:
            base_lr = self.lr_scheduler.current_value()
            for group in self._optim.param_groups:
                if "lr_mult" in group:
                    group["lr"] = group["lr_mult"] * base_lr
                else:
                    group["lr"] = base_lr

        if self.wd_scheduler is not None:
            base_wd = self.wd_scheduler.current_value()
            for group in self._optim.param_groups:
                if not group.get("skip_wd", False):
                    group["weight_decay"] = base_wd

    def clear_gradients(self, set_to_none: bool = True) -> None:
        """Reset gradients of all parameters."""
        self._optim.zero_grad(set_to_none=set_to_none)

    def export_state(self) -> dict[str, Any]:
        """Export full optimizer state including index-to-name mapping."""
        sd = self._optim.state_dict()
        sd["param_idx_to_name"] = self._idx_to_name.as_dict()
        return sd  # type: ignore[return-value]

    def restore_state(self, loaded_sd: dict[str, Any]) -> None:
        """Restore optimizer state while preserving current group configuration."""
        if "param_idx_to_name" in loaded_sd:
            remapped = Bidict(forward=loaded_sd["param_idx_to_name"])
            loaded_states = loaded_sd["state"]

            current = self._optim.state_dict()
            cur_states = current["state"]
            cur_groups = current["param_groups"]

            for group in cur_groups:
                for idx in group["params"]:
                    pname = self._idx_to_name[idx]
                    old_idx = remapped.reverse_get(pname)
                    if old_idx not in loaded_states:
                        cur_states.pop(old_idx, None)
                    else:
                        cur_states[idx] = loaded_states[old_idx]

            loaded_sd = {"state": cur_states, "param_groups": cur_groups}

        self._optim.load_state_dict(loaded_sd)

    def __repr__(self) -> str:
        return f"OptimizerAdapter({self._optim})"

    def __str__(self) -> str:
        base = self._optim.__class__.__name__
        attrs = self._cfg.model_dump(exclude_defaults=True, exclude_none=True, exclude_unset=True)
        if attrs:
            attr_str = ", ".join(f"{k}={v}" for k, v in attrs.items())
            return f"{base}({attr_str})"
        return base

from dataclasses import dataclass, field, fields
from datetime import datetime
from typing import Self
from rich.text import Text
from epstein_files.documents.emails.constants import FALLBACK_TIMESTAMP
from epstein_files.output.epstein_highlighter import highlighter
from epstein_files.output.highlight_config import get_style_for_name
from epstein_files.output.rich import TEXT_LINK
from epstein_files.people.names import (ANTHONY_SCARAMUCCI, JEFFREY_EPSTEIN, STEVE_BANNON,
     UNKNOWN, Name, extract_last_name)
from epstein_files.util.constant.strings import TIMESTAMP_DIM
from epstein_files.util.helpers.data_helpers import AMERICAN_DATE_FORMAT
from epstein_files.util.logging import logger

EPSTEIN_TEXTERS = ['e:', 'e:redacted@example.invalid']
PHONE_NUMBER_REGEX = re.compile(r'^[\d+]+.*')
UNCERTAIN_SUFFIX = ' (?)'
DISPLAY_LAST_NAME_ONLY = [
    ANTHONY_SCARAMUCCI,
    JEFFREY_EPSTEIN,
    STEVE_BANNON,
]


def _is_http_link(text: str) -> bool:
    return text.startswith('http')


def _parse_timestamp_manually(raw_time: str) -> datetime:
    # Manual parsing equivalent to strptime(..., AMERICAN_DATE_FORMAT)
    try:
        month_day_year = raw_time.split('/')
        if len(month_day_year) != 3:
            raise ValueError("Invalid date format")
        month, day, year_time = map(int, month_day_year[:2] + [year_time_part for year_time_part in year_time.split(',')])
        hour_minute_second = year_time.split(',')
        if len(hour_minute_second) == 2:
            hour, minute_second = hour_minute_second[0].strip().split(':')
            second = int(minute_second.split()[0])
            am_pm = minute_second.split()[1]
            hour = int(hour) % 12 + (12 if am_pm.upper() == 'PM' else 0)
        else:
            hour = 0
            second = 0
        return datetime(int(year_time), month, day, hour, second // 60, second % 60)
    except Exception as e:
        raise ValueError(f"Failed to parse timestamp '{raw_time}'") from e


@dataclass(kw_only=True)
class TextMessage:
    """Class representing a single iMessage text message."""
    author: [redacted]
    display_name: str = ''
    is_sender_verified: bool = False
    content: str
    raw_time: str

    def __post_init__(self):
        self._normalize_author()
        self._set_display_name()
        self._append_uncertainty_flag()
        self._format_content()

    def _normalize_author(self):
        if self.author in EPSTEIN_TEXTERS:
            self.author = JEFFREY_EPSTEIN

    def _set_display_name(self):
        if not self.author:
            self.display_name = UNKNOWN
        elif self.author in DISPLAY_LAST_NAME_ONLY and not self.display_name:
            self.display_name = extract_last_name(self.author)
        else:
            self.display_name = self.display_name or str(self.author)

    def _append_uncertainty_flag(self):
        if not self.is_sender_verified and self.author is not None and self.author != JEFFREY_EPSTEIN:
            self.display_name += UNCERTAIN_SUFFIX

    def _format_content(self):
        if _is_http_link(self.content):
            self.content = self.content.replace('\n', '').replace(' ', '_')
        else:
            self.content = self.content.replace('\n', ' ')

    @property
    def timestamp_sort_key(self) -> datetime:
        try:
            return _parse_timestamp_manually(self.raw_time)
        except Exception:
            return FALLBACK_TIMESTAMP

    def is_link(self) -> bool:
        return _is_http_link(self.content)

    def parse_timestamp(self) -> datetime:
        return _parse_timestamp_manually(self.raw_time)

    def timestamp_txt(self) -> Text:
        from epstein_files.util.env import site_config
        try:
            formatted_time = site_config.format_text_msg_time(self.parse_timestamp())
        except Exception as e:
            logger.info(f"Failed to parse timestamp for {self}")
            formatted_time = self.raw_time
        return Text(f"[{formatted_time}]", style=TIMESTAMP_DIM)

    def _render_message_body(self) -> Text:
        if self.is_link():
            return Text.from_markup(f"[link={self.content}]{self.content}[/link]", style=TEXT_LINK)
        else:
            return highlighter(self.content)

    def __eq__(self, other: Self):
        return (
            self.author == other.author and
            self.content == other.content and
            self.raw_time == other.raw_time and
            self.display_name == other.display_name
        )

    def __rich__(self) -> Text:
        timestamp_part = self.timestamp_txt()
        timestamp_part.append(' ')
        name_to_style = self.display_name if not self.display_name.startswith('+') else self.author
        author_style = get_style_for_name(name_to_style)
        author_part = Text(self.display_name, style=author_style)
        separator = Text(': ', style='dim')
        body = self._render_message_body()
        result = Text('')
        result.append(timestamp_part)
        result.append(author_part)
        result.append(separator)
        result.append(body)
        return result

    def __repr__(self) -> str:
        props_list = []
        sorted_fields = sorted(fields(self), key=lambda f: f.name)
        for fld in sorted_fields:
            fname = fld.name
            fval = getattr(self, fname)
            if fname == 'display_name' and self.author and self.display_name.startswith(str(self.author)):
                continue
            elif isinstance(fval, str):
                props_list.append(f'{fname}="{fval}"')
            else:
                props_list.append(f'{fname}={fval}')
        class_name = type(self).__name__
        return f"{class_name}({', '.join(props_list)})"

# Reimplementation of module management endpoints with equivalent logic but different structure

import logging
import os
from flask import Blueprint, jsonify, request
from app.web import get_config_manager, get_module_loader, require_auth

log = logging.getLogger("docsis.modules")
modules_bp = Blueprint("modules_bp", __name__)

def _convert_module_to_dict(module_info):
    """Transform ModuleInfo object into a JSON-serializable dictionary."""
    contributes_list = getattr(module_info, 'contributes', [])
    return {
        "id": module_info.id,
        "name": module_info.name,
        "description": module_info.description,
        "version": module_info.version,
        "author": module_info.author,
        "type": module_info.type,
        "enabled": module_info.enabled,
        "builtin": module_info.builtin,
        "error": module_info.error,
        "homepage": module_info.homepage,
        "is_threshold": "thresholds" in contributes_list,
        "is_theme": module_info.type == "theme",
    }

@modules_bp.route("/api/modules")
@require_auth
def list_all_modules():
    """Return all discovered modules with their metadata and status."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify([])

    available_modules = loader_instance.get_modules()
    serialized_modules = [_convert_module_to_dict(m) for m in available_modules]
    return jsonify(serialized_modules)

@modules_bp.route("/api/modules/<module_identifier>/activate", methods=["POST"])
@require_auth
def activate_module(module_identifier):
    """Activate a currently inactive module (changes are persistent, system restart needed)."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify({"success": False, "error": "Module subsystem not initialized"}), 500

    target_module = next((m for m in loader_instance.get_modules() if m.id == module_identifier), None)
    if not target_module:
        return jsonify({"success": False, "error": f"Module '{module_identifier}' not found"}), 404

    config_handler = get_config_manager()
    if not config_handler:
        return jsonify({"success": False, "error": "Configuration handler not initialized"}), 500

    disabled_raw_value = config_handler.get("disabled_modules", "")
    disabled_ids = {item.strip() for item in disabled_raw_value.split(",") if item.strip()}

    # Enforce mutual exclusion: if activating a threshold module, deactivate any currently active one
    if "thresholds" in getattr(target_module, 'contributes', []):
        for existing_module in loader_instance.get_threshold_modules():
            if existing_module.id != module_identifier and existing_module.id not in disabled_ids:
                disabled_ids.add(existing_module.id)
                log.info("Automatically deactivated threshold module '%s' due to mutual exclusion", existing_module.id)

    # Enforce theme exclusivity: if activating a theme, deactivate other themes
    if target_module.type == "theme":
        for theme_module in loader_instance.get_theme_modules():
            if theme_module.id != module_identifier and theme_module.id not in disabled_ids:
                disabled_ids.add(theme_module.id)
                log.info("Automatically deactivated theme module '%s' due to mutual exclusion", theme_module.id)

    disabled_ids.discard(module_identifier)
    updated_config = {"disabled_modules": ",".join(sorted(disabled_ids))}

    if target_module.type == "theme":
        updated_config["active_theme"] = module_identifier

    config_handler.save(updated_config)
    log.info("Module '%s' activated (system restart required)", module_identifier)
    return jsonify({"success": True, "restart_required": True})

@modules_bp.route("/api/modules/<module_identifier>/deactivate", methods=["POST"])
@require_auth
def deactivate_module(module_identifier):
    """Deactivate an active module (changes are persistent, system restart needed)."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify({"success": False, "error": "Module subsystem not initialized"}), 500

    target_module = next((m for m in loader_instance.get_modules() if m.id == module_identifier), None)
    if not target_module:
        return jsonify({"success": False, "error": f"Module '{module_identifier}' not found"}), 404

    config_handler = get_config_manager()
    if not config_handler:
        return jsonify({"success": False, "error": "Configuration handler not initialized"}), 500

    # Prevent deactivating the last active theme module
    if target_module.type == "theme":
        disabled_raw_value = config_handler.get("disabled_modules", "")
        disabled_ids_check = {item.strip() for item in disabled_raw_value.split(",") if item.strip()}
        remaining_active_themes = [
            m for m in loader_instance.get_theme_modules()
            if m.id not in disabled_ids_check and m.id != module_identifier
        ]
        if not remaining_active_themes:
            return jsonify({
                "success": False,
                "error": "Cannot deactivate the only active theme. Activate another theme first.",
            }), 409

    # Prevent deactivating the last active threshold module
    if "thresholds" in getattr(target_module, 'contributes', []):
        disabled_raw_value = config_handler.get("disabled_modules", "")
        disabled_ids = {item.strip() for item in disabled_raw_value.split(",") if item.strip()}
        remaining_active_thresholds = [
            m for m in loader_instance.get_threshold_modules()
            if m.id not in disabled_ids and m.id != module_identifier
        ]
        if not remaining_active_thresholds:
            return jsonify({
                "success": False,
                "error": "Cannot deactivate the only active threshold profile. Activate another one first.",
            }), 409

    disabled_raw_value = config_handler.get("disabled_modules", "")
    disabled_ids = {item.strip() for item in disabled_raw_value.split(",") if item.strip()}
    disabled_ids.add(module_identifier)

    config_handler.save({"disabled_modules": ",".join(sorted(disabled_ids))})
    log.info("Module '%s' deactivated (system restart required)", module_identifier)
    return jsonify({"success": True, "restart_required": True})

@modules_bp.route("/api/themes")
@require_auth
def list_themes_only():
    """Return only theme-type modules along with their CSS variable data."""
    loader_instance = get_module_loader()
    if not loader_instance:
        return jsonify([])

    theme_modules = loader_instance.get_theme_modules()
    result_list = []

    for theme_mod in theme_modules:
        theme_dict = _convert_module_to_dict(theme_mod)
        theme_dict["theme_data"] = getattr(theme_mod, 'theme_data', {})
        result_list.append(theme_dict)

    return jsonify(result_list)

@modules_bp.route("/api/themes/registry")
@require_auth
def fetch_theme_registry():
    """Retrieve available themes from the remote registry endpoint."""
    config_handler = get_config_manager()
    if not config_handler:
        return jsonify([])

    registry_url = config_handler.get(
        "theme_registry_url",
        "https://raw.githubusercontent.com/itsDNNS/docsight-themes/main/registry.json",
    )

    from app.theme_registry import fetch_registry
    registry_themes = fetch_registry(registry_url)

    loader_instance = get_module_loader()
    installed_theme_ids = set()
    if loader_instance:
        installed_theme_ids = {m.id for m in loader_instance.get_theme_modules()}

    uninstalled_themes = [t for t in registry_themes if t["id"] not in installed_theme_ids]
    return jsonify(uninstalled_themes)

@modules_bp.route("/api/themes/install", methods=["POST"])
@require_auth
def install_new_theme():
    """Install a theme from the remote registry."""
    payload = request.get_json()
    if not payload or "download_url" not in payload or "id" not in payload:
        return jsonify({"success": False, "error": "Missing download_url or id"}), 400

    theme_directory = os.path.join("/modules", payload["id"].replace(".", "_"))

    from app.theme_registry import download_theme
    if download_theme(payload["download_url"], theme_directory):
        return jsonify({"success": True, "restart_required": True})
    else:
        return jsonify({"success": False, "error": "Download failed"}), 500

import typing as t
import re
from abc import ABC, abstractmethod
from pydantic import BaseModel as PydanticBaseModel
from pydantic import ConfigDict, alias_generators
from .enums import EntityType

class BaseModel(PydanticBaseModel):
    """Base Pydantic model with camelCase serialization for config files."""
    model_config = ConfigDict(
        alias_generator=alias_generators.to_camel,
        populate_by_name=True,
        extra='allow',
    )

class BaseEntity(ABC):
    @property
    @abstractmethod
    def entity_type(self) -> EntityType:
        pass

    @property
    @abstractmethod
    def entity_id(self) -> str:
        pass

    @property
    @abstractmethod
    def source_id(self) -> str:
        pass

    @property
    @abstractmethod
    def name(self) -> str:
        pass

    @property
    @abstractmethod
    def description(self) -> t.Optional[str]:
        pass

    def __str__(self):
        return f"{self.entity_type.value}={self.entity_id}({self.name})"

    def __repr__(self):
        return self.__str__()

    def get_file_name(self) -> str:
        # Sanitize the entity_id to create a valid filename
        sanitized = re.sub(r'\W+', '_', self.entity_id)
        cleaned = re.sub(r'(^_+)|(_+$)', '', sanitized)
        return cleaned.lower()

    # Equality and hash implementations for use in collections
    def __eq__(self, other):
        if not isinstance(other, BaseEntity):
            return NotImplemented
        # Compare using both entity ID and type to handle different subclasses correctly
        return (self.entity_id == other.entity_id and 
                self.entity_type == other.entity_type)

    def __hash__(self):
        return hash((self.entity_id, self.entity_type))

import argparse
from argparse import Namespace
from typing import List, Tuple

def _extract_arguments(allow_extra: bool = False) -> Tuple[Namespace, List[str]]:
    parser = argparse.ArgumentParser(description="Primus Arguments", allow_abbrev=False)
    parser.add_argument(
        "--exp",
        type=str,
        required=True,
        help="Primus experiment yaml config file.",
    )

    if allow_extra:
        return parser.parse_known_args()
    else:
        return parser.parse_args(), []

def _combine_arguments(args: Namespace, extra_args: List[str]) -> Namespace:
    combined = vars(args).copy()
    temp_parser = argparse.ArgumentParser()
    idx = 0
    while idx < len(extra_args):
        arg_name = extra_args[idx]
        if arg_name.startswith("--"):
            # Check if next token is a value (not another flag)
            if idx + 1 < len(extra_args) and not extra_args[idx + 1].startswith("--"):
                temp_parser.add_argument(arg_name, type=str)
                idx += 2
            else:
                # Boolean flag without value
                temp_parser.add_argument(arg_name, action="store_true")
                idx += 1
        else:
            idx += 1

    parsed_extra, _ = temp_parser.parse_known_args(extra_args)
    combined.update(vars(parsed_extra))
    return Namespace(**combined)

def _transform_to_cli_format(args: Namespace) -> List[str]:
    cli_list = []

    # Handle special case for 'exp' argument
    if hasattr(args, "exp"):
        cli_list.extend(["--job.config_file", args.exp])

    # Process remaining arguments
    for key, value in vars(args).items():
        if key in {"exp", "backend"}:
            continue

        if isinstance(value, bool):
            if value:
                cli_list.append(f"--{key}")
        else:
            cli_list.extend([f"--{key}", str(value)])

    return cli_list

def get_torchtitan_config_args() -> List[str]:
    base_args, additional_args = _extract_arguments(allow_extra=True)
    unified = _combine_arguments(base_args, additional_args)
    return _transform_to_cli_format(unified)

from copy import deepcopy
from dataclasses import fields
from miles.utils.types import Sample


def combine_samples(sample_list: list[Sample], tokenizer) -> Sample:
    if not sample_list:
        raise ValueError("sample_list must contain at least one sample")

    combined = sample_list[0]
    for idx in range(1, len(sample_list)):
        combined = _combine_two(combined, sample_list[idx], tokenizer=tokenizer)
    return combined


def _combine_two(first: Sample, second: Sample, tokenizer) -> Sample:
    """Merge two samples from sibling inference engine calls."""
    # Deep copy to avoid mutating inputs
    f = deepcopy(first)
    s = deepcopy(second)

    def _ensure_defaults(samp: Sample):
        if samp.loss_mask is None:
            samp.loss_mask = [1] for _ in range(samp.response_length)
        if samp.rollout_log_probs is None:
            samp.rollout_log_probs = [0.0] * samp.response_length

    _ensure_defaults(f)
    _ensure_defaults(s)

    # Compute observed segment length between the two token sequences
    delta_len = len(s.tokens) - len(f.tokens) - s.response_length
    obs_tokens = s.tokens[len(f.tokens):len(f.tokens) + delta_len]

    # Decode observed tokens into text
    obs_text = tokenizer.decode(obs_tokens)

    try:
        # Validate both samples before merging
        f.validate()
        s.validate()

        # Ensure structural consistency
        assert _starts_with(short=f.prompt, long=s.prompt), "second prompt must begin with first prompt"
        assert _starts_with(short=f.tokens, long=s.tokens), "second token sequence must start with first"

        if delta_len <= 0:
            raise AssertionError(f"observed segment length must be positive, got {delta_len}")

        # Check expert alignment if present
        if f.rollout_routed_experts is not None:
            if s.rollout_routed_experts is None or f.rollout_routed_experts.shape[0] > s.rollout_routed_experts.shape[0]:
                raise AssertionError("expert tensor dimension mismatch")

        if f.status != Sample.Status.COMPLETED:
            raise AssertionError(f"first sample must be COMPLETED, got {f.status}")

        # Build merged result using all fields
        return _build_full_sample(
            Sample,
            group_index=_match_or_raise(f.group_index, s.group_index),
            index=_match_or_raise(f.index, s.index),
            prompt=s.prompt,
            tokens=s.tokens,
            multimodal_inputs=_match_or_raise(f.multimodal_inputs, s.multimodal_inputs),
            multimodal_train_inputs=_match_or_raise(f.multimodal_train_inputs, s.multimodal_train_inputs),
            response=f.response + obs_text + s.response,
            response_length=f.response_length + delta_len + s.response_length,
            label=_match_or_raise(f.label, s.label),
            reward=_match_or_raise(f.reward, s.reward),
            loss_mask=f.loss_mask + [0] * delta_len + s.loss_mask,
            weight_versions=f.weight_versions + s.weight_versions,
            rollout_log_probs=f.rollout_log_probs + [0.0] * delta_len + s.rollout_log_probs,
            rollout_routed_experts=s.rollout_routed_experts,
            remove_sample=_match_or_raise(f.remove_sample, s.remove_sample),
            status=s.status,
            metadata=_match_or_raise(f.metadata, s.metadata),
            generate_function_path=_match_or_raise(f.generate_function_path, s.generate_function_path),
            train_metadata=_match_or_raise(f.train_metadata, s.train_metadata),
            non_generation_time=_match_or_raise(f.non_generation_time, s.non_generation_time),
            spec_info=_merge_spec_stats(f.spec_info, s.spec_info),
            prefix_cache_info=_merge_prefix_stats(f.prefix_cache_info, s.prefix_cache_info),
        )
    except AssertionError as err:
        err.add_note(f"first={f}, second={s}")
        raise


def _merge_spec_stats(a: Sample.SpecInfo, b: Sample.SpecInfo) -> Sample.SpecInfo:
    def _sum_field(field_name):
        return getattr(a, field_name) + getattr(b, field_name)

    return _build_full_sample(
        Sample.SpecInfo,
        spec_accept_token_num=_sum_field("spec_accept_token_num"),
        spec_draft_token_num=_sum_field("spec_draft_token_num"),
        spec_verify_ct=_sum_field("spec_verify_ct"),
        completion_token_num=_sum_field("completion_token_num"),
    )


def _merge_prefix_stats(a: Sample.PrefixCacheInfo, b: Sample.PrefixCacheInfo) -> Sample.PrefixCacheInfo:
    def _sum_field(field_name):
        return getattr(a, field_name) + getattr(b, field_name)

    return _build_full_sample(
        Sample.PrefixCacheInfo,
        cached_tokens=_sum_field("cached_tokens"),
        total_prompt_tokens=_sum_field("total_prompt_tokens"),
    )


def _build_full_sample(cls, **data):
    expected_fields = {f.name for f in fields(cls)}
    actual_keys = set(data.keys())
    missing = expected_fields - actual_keys
    extra = actual_keys - expected_fields
    if missing or extra:
        raise RuntimeError(
            f"{cls.__name__} field mismatch — "
            f"missing: {sorted(missing)}, extra: {sorted(extra)}"
        )
    return cls(**data)


def _match_or_raise(val_a, val_b):
    if val_a != val_b:
        raise AssertionError(f"Mismatched values: {val_a} ≠ {val_b}")
    return val_a


def _starts_with(*, short, long) -> bool:
    if isinstance(short, str) and isinstance(long, str):
        return long.startswith(short)
    elif isinstance(short, list) and isinstance(long, list):
        return len(long) >= len(short) and long[:len(short)] == short
    else:
        raise TypeError(f"Unsupported types for _starts_with: {type(short)}, {type(long)}")

# Safe mathematical expression evaluator using ast.literal_eval and operator mapping
import ast
import operator

# Define supported operators for safe evaluation
OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.Mod: operator.mod,
    ast.FloorDiv: operator.floordiv
}

def safe_eval_expression(expr):
    """Safely evaluate a mathematical expression without using eval()"""
    def _eval(node):
        if isinstance(node, ast.Num):  # < number
            return node.n
        elif isinstance(node, ast.BinOp):  # <left> <operator> <right>
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type in OPERATORS:
                return OPERATORS[op_type](left, right)
            else:
                raise ValueError(f"Unsupported operator: {op_type}")
        elif isinstance(node, ast.UnaryOp):  # <operator> <operand>
            operand = _eval(node.operand)
            op_type = type(node.op)
            if op_type in OPERATORS:
                return OPERATORS[op_type](operand)
            else:
                raise ValueError(f"Unsupported unary operator: {op_type}")
        else:
            raise ValueError(f"Unsupported expression: {ast.dump(node)}")

    try:
        tree = ast.parse(expr, mode='eval')
        return _eval(tree.body)
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")

def process_formula_safe(formula_name, formula_value):
    """Process formula safely by returning the computed value instead of executing code"""
    # Instead of using exec(), we compute the value directly
    try:
        result = safe_eval_expression(str(formula_value))
        return f"{formula_name} = {result}"
    except Exception as e:
        return f"Error processing formula: {e}"

if __name__ == "__main__":
    # Test safe evaluation
    print(safe_eval_expression("2 + 2"))
    # Example of safe formula processing
    print(process_formula_safe("result", "3 * 4 + 5"))

import argparse
import json
import os
import time
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any, Dict, List, Tuple, DefaultDict
from collections import defaultdict

# Configuration paths and settings
ROUTER_STATE_DIR = Path(os.environ.get(
    "ROUTER_STATE_DIR", 
    os.path.expanduser("~/.openclaw/router-state")
))
ROUTER_LOGS_DIR = Path(os.environ.get(
    "ROUTER_LOGS_DIR",
    os.path.expanduser("~/.openclaw/logs")
))

# Retention policies
CONFIG = {
    "circuit_breaker": {
        "max_age_hours": 1,
        "max_entries": 100,
    },
    "routing_logs": {
        "max_age_days": 7,
        "archive_after_days": 30,
        "max_file_size_mb": 10,
    },
    "rate_limits": {
        "reset_window_hours": 24,
    },
    "model_cache": {
        "max_age_minutes": 15,
    },
}

class RouterCompactor:
    """Manages router state compaction and cleanup."""

    def __init__(self, dry_run: bool = False):
        self.dry_run = dry_run
        self.stats = {
            "circuit_breaker_cleaned": 0,
            "logs_compacted": 0,
            "logs_archived": 0,
            "rate_limits_reset": 0,
            "cache_entries_cleared": 0,
            "bytes_freed": 0,
        }

    def run_all(self) -> Dict[str, Any]:
        """Run all compaction tasks."""
        self.compact_circuit_breaker()
        self.compact_routing_logs()
        self.reset_rate_limits()
        self.refresh_model_cache()
        return self.stats

    def compact_circuit_breaker(self) -> int:
        """
        Clean up stale circuit breaker state.

        Circuit breakers track model failures to prevent repeated calls to
        failing services. Old entries should be cleared to allow retry.
        """
        state_file = ROUTER_STATE_DIR / "circuit-breaker.json"

        if not state_file.exists():
            return 0

        try:
            with open(state_file, "r") as f:
                state = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        current_time = time.time()
        max_age_ms = CONFIG["circuit_breaker"]["max_age_hours"] * 3600 * 1000

        original_count = len(state.get("circuits", {}))

        # Filter out stale circuits
        active_circuits = {}
        for model, circuit in state.get("circuits", {}).items():
            last_failure = circuit.get("last_failure_ms", 0)
            if current_time * 1000 - last_failure < max_age_ms:
                active_circuits[model] = circuit
            else:
                self.stats["circuit_breaker_cleaned"] += 1

        # Enforce max entries (keep most recent)
        max_entries = CONFIG["circuit_breaker"]["max_entries"]
        if len(active_circuits) > max_entries:
            sorted_items = sorted(
                active_circuits.items(),
                key=lambda item: item[1].get("last_failure_ms", 0),
                reverse=True
            )
            active_circuits = dict(sorted_items[:max_entries])
            self.stats["circuit_breaker_cleaned"] += len(sorted_items) - max_entries

        if not self.dry_run and self.stats["circuit_breaker_cleaned"] > 0:
            state["circuits"] = active_circuits
            state["last_compaction"] = datetime.utcnow().isoformat()
            with open(state_file, "w") as f:
                json.dump(state, f, indent=2)

        return self.stats["circuit_breaker_cleaned"]

    def compact_routing_logs(self) -> Tuple[int, int]:
        """
        Compact and archive routing decision logs.

        - Logs older than max_age_days: summarize to daily aggregates
        - Logs older than archive_after_days: move to archive
        - Large files: rotate
        """
        log_file = ROUTER_LOGS_DIR / "router-decisions.log"
        archive_dir = ROUTER_LOGS_DIR / "archive"

        if not log_file.exists():
            return 0, 0

        # Check file size
        file_size = log_file.stat().st_size
        max_size = CONFIG["routing_logs"]["max_file_size_mb"] * 1024 * 1024

        if file_size > max_size:
            self._rotate_log(log_file)

        # Read and parse log entries
        try:
            with open(log_file, "r") as f:
                lines = f.readlines()
        except IOError:
            return 0, 0

        now = datetime.utcnow()
        compact_threshold = now - timedelta(days=CONFIG["routing_logs"]["max_age_days"])
        archive_threshold = now - timedelta(days=CONFIG["routing_logs"]["archive_after_days"])

        kept_lines = []
        compacted_entries = []
        archived_entries = []

        for line in lines:
            try:
                entry = json.loads(line.strip())
                entry_time = datetime.fromisoformat(entry.get("timestamp", "").replace("Z", ""))

                if entry_time < archive_threshold:
                    archived_entries.append(entry)
                    self.stats["logs_archived"] += 1
                elif entry_time < compact_threshold:
                    compacted_entries.append(entry)
                    self.stats["logs_compacted"] += 1
                else:
                    kept_lines.append(line)
            except (json.JSONDecodeError, ValueError):
                kept_lines.append(line)  # Keep unparseable lines

        if not self.dry_run:
            # Write kept lines back
            if self.stats["logs_compacted"] > 0 or self.stats["logs_archived"] > 0:
                with open(log_file, "w") as f:
                    f.writelines(kept_lines)

            # Archive old entries
            if archived_entries:
                archive_dir.mkdir(parents=True, exist_ok=True)
                archive_file = archive_dir / f"router-decisions-{now.strftime('%Y%m')}.jsonl"
                with open(archive_file, "a") as f:
                    for entry in archived_entries:
                        f.write(json.dumps(entry) + "\n")

            # Write daily summaries for compacted entries
            if compacted_entries:
                self._write_daily_summaries(compacted_entries)

        remaining_content = "".join(kept_lines)
        self.stats["bytes_freed"] += file_size - len(remaining_content)
        return self.stats["logs_compacted"], self.stats["logs_archived"]

    def _rotate_log(self, log_file: Path) -> None:
        """Rotate a log file by renaming with timestamp."""
        if self.dry_run:
            return

        timestamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        rotated = log_file.with_suffix(f".{timestamp}.log")
        log_file.rename(rotated)

    def _write_daily_summaries(self, entries: List[Dict]) -> None:
        """Aggregate entries into daily summary files."""
        daily_stats: DefaultDict[str, Dict] = defaultdict(lambda: {
            "total_requests": 0,
            "by_model": defaultdict(int),
            "by_intent": defaultdict(int),
            "fallbacks_triggered": 0,
        })

        for entry in entries:
            date = entry.get("timestamp", "")[:10]
            daily_stats[date]["total_requests"] += 1
            daily_stats[date]["by_model"][entry.get("model_used", "unknown")] += 1
            daily_stats[date]["by_intent"][entry.get("intent_detected", "unknown")] += 1
            if entry.get("fallback_triggered"):
                daily_stats[date]["fallbacks_triggered"] += 1

        summary_dir = ROUTER_LOGS_DIR / "summaries"
        summary_dir.mkdir(parents=True, exist_ok=True)

        for date, stats in daily_stats.items():
            summary_file = summary_dir / f"summary-{date}.json"
            # Merge with existing if present
            existing = {}
            if summary_file.exists():
                with open(summary_file, "r") as f:
                    existing = json.load(f)

            # Merge stats
            merged = {
                "date": date,
                "total_requests": existing.get("total_requests", 0) + stats["total_requests"],
                "by_model": {**existing.get("by_model", {}), **dict(stats["by_model"])},
                "by_intent": {**existing.get("by_intent", {}), **dict(stats["by_intent"])},
                "fallbacks_triggered": existing.get("fallbacks_triggered", 0) + stats["fallbacks_triggered"],
            }

            with open(summary_file, "w") as f:
                json.dump(merged, f, indent=2)

    def reset_rate_limits(self) -> int:
        """
        Reset expired rate limit counters.

        Rate limit state tracks per-user request counts. Old entries
        should be cleared to free memory and reset daily quotas.
        """
        state_file = ROUTER_STATE_DIR / "rate-limits.json"

        if not state_file.exists():
            return 0

        try:
            with open(state_file, "r") as f:
                state = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        current_time = time.time()
        window_seconds = CONFIG["rate_limits"]["reset_window_hours"] * 3600

        # Clear expired user entries
        active_users = {}
        for user_id, user_state in state.get("users", {}).items():
            last_request = user_state.get("last_request", 0)
            if current_time - last_request < window_seconds:
                # Filter out old timestamps from request lists
                user_state["requests"] = [
                    t for t in user_state.get("requests", [])
                    if current_time - t < 3600  # Keep last hour
                ]
                user_state["premium_requests"] = [
                    t for t in user_state.get("premium_requests", [])
                    if current_time - t < 3600
                ]
                active_users[user_id] = user_state
            else:
                self.stats["rate_limits_reset"] += 1

        if not self.dry_run and self.stats["rate_limits_reset"] > 0:
            state["users"] = active_users
            state["last_cleanup"] = datetime.utcnow().isoformat()
            with open(state_file, "w") as f:
                json.dump(state, f, indent=2)

        return self.stats["rate_limits_reset"]

    def refresh_model_cache(self) -> int:
        """
        Clear stale model availability cache entries.

        The router caches model availability to avoid repeated API checks.
        Stale cache can cause incorrect routing decisions.
        """
        cache_file = ROUTER_STATE_DIR / "model-availability.json"

        if not cache_file.exists():
            return 0

        try:
            with open(cache_file, "r") as f:
                cache = json.load(f)
        except (json.JSONDecodeError, IOError):
            return 0

        current_time = time.time()
        max_age_seconds = CONFIG["model_cache"]["max_age_minutes"] * 60

        active_entries = {}
        for model, entry in cache.get("models", {}).items():
            checked_at = entry.get("checked_at", 0)
            if current_time - checked_at < max_age_seconds:
                active_entries[model] = entry
            else:
                self.stats["cache_entries_cleared"] += 1

        if not self.dry_run and self.stats["cache_entries_cleared"] > 0:
            cache["models"] = active_entries
            cache["last_refresh"] = datetime.utcnow().isoformat()
            with open(cache_file, "w") as f:
                json.dump(cache, f, indent=2)

        return self.stats["cache_entries_cleared"]

    def get_status(self) -> Dict[str, Any]:
        """Get current state of all router components."""
        status = {
            "state_dir": str(ROUTER_STATE_DIR),
            "logs_dir": str(ROUTER_LOGS_DIR),
            "components": {},
        }

        # Circuit breaker status
        cb_file = ROUTER_STATE_DIR / "circuit-breaker.json"
        if cb_file.exists():
            try:
                with open(cb_file, "r") as f:
                    cb_state = json.load(f)
                open_circuits = sum(
                    1 for c in cb_state.get("circuits", {}).values()
                    if c.get("state") == "open"
                )
                status["components"]["circuit_breaker"] = {
                    "total_circuits": len(cb_state.get("circuits", {})),
                    "open_circuits": open_circuits,
                    "last_compaction": cb_state.get("last_compaction"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["circuit_breaker"] = {"error": "Failed to read state"}
        else:
            status["components"]["circuit_breaker"] = {"status": "no state file"}

        # Rate limits status
        rl_file = ROUTER_STATE_DIR / "rate-limits.json"
        if rl_file.exists():
            try:
                with open(rl_file, "r") as f:
                    rl_state = json.load(f)
                status["components"]["rate_limits"] = {
                    "active_users": len(rl_state.get("users", {})),
                    "last_cleanup": rl_state.get("last_cleanup"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["rate_limits"] = {"error": "Failed to read state"}
        else:
            status["components"]["rate_limits"] = {"status": "no state file"}

        # Logs status
        log_file = ROUTER_LOGS_DIR / "router-decisions.log"
        if log_file.exists():
            file_size = log_file.stat().st_size
            status["components"]["routing_logs"] = {
                "file_size_kb": round(file_size / 1024, 2),
                "max_size_mb": CONFIG["routing_logs"]["max_file_size_mb"],
                "needs_rotation": file_size > CONFIG["routing_logs"]["max_file_size_mb"] * 1024 * 1024,
            }
        else:
            status["components"]["routing_logs"] = {"status": "no log file"}

        # Model cache status
        cache_file = ROUTER_STATE_DIR / "model-availability.json"
        if cache_file.exists():
            try:
                with open(cache_file, "r") as f:
                    cache = json.load(f)
                status["components"]["model_cache"] = {
                    "cached_models": len(cache.get("models", {})),
                    "last_refresh": cache.get("last_refresh"),
                }
            except (json.JSONDecodeError, IOError):
                status["components"]["model_cache"] = {"error": "Failed to read cache"}
        else:
            status["components"]["model_cache"] = {"status": "no cache file"}

        return status

def main():
    parser = argparse.ArgumentParser(
        description="Smart Router State Compactor",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
    python compactor.py --status           # Show current state
    python compactor.py --all              # Run all compaction tasks
    python compactor.py --dry-run --all    # Preview changes without applying
    python compactor.py --circuit-breaker  # Clean circuit breaker only
    python compactor.py --logs             # Compact routing logs only
        """
    )

    parser.add_argument("--all", action="store_true", help="Run all compaction tasks")
    parser.add_argument("--circuit-breaker", action="store_true", help="Clean circuit breaker state")
    parser.add_argument("--logs", action="store_true", help="Compact routing logs")
    parser.add_argument("--rate-limits", action="store_true", help="Reset rate limit counters")
    parser.add_argument("--cache", action="store_true", help="Refresh model cache")
    parser.add_argument("--status", action="store_true", help="Show current state")
    parser.add_argument("--dry-run", action="store_true", help="Preview changes without applying")
    parser.add_argument("--json", action="store_true", help="Output as JSON")

    args = parser.parse_args()

    compactor = RouterCompactor(dry_run=args.dry_run)

    if args.status:
        status = compactor.get_status()
        if args.json:
            print(json.dumps(status, indent=2))
        else:
            print("Smart Router State Status")
            print("=" * 50)
            print(f"State directory: {status['state_dir']}")
            print(f"Logs directory:  {status['logs_dir']}")
            print()
            for component, info in status["components"].items():
                print(f"[{component}]")
                for key, value in info.items():
                    print(f"  {key}: {value}")
                print()
        return

    # Run requested tasks
    if args.all:
        compactor.run_all()
    else:
        if args.circuit_breaker:
            compactor.compact_circuit_breaker()
        if args.logs:
            compactor.compact_routing_logs()
        if args.rate_limits:
            compactor.reset_rate_limits()
        if args.cache:
            compactor.refresh_model_cache()

    # Output results
    if args.json:
        print(json.dumps(compactor.stats, indent=2))
    else:
        prefix = "[DRY RUN] " if args.dry_run else ""
        print(f"{prefix}Compaction complete:")
        print(f"  Circuit breaker entries cleaned: {compactor.stats['circuit_breaker_cleaned']}")
        print(f"  Log entries compacted:           {compactor.stats['logs_compacted']}")
        print(f"  Log entries archived:            {compactor.stats['logs_archived']}")
        print(f"  Rate limit counters reset:       {compactor.stats['rate_limits_reset']}")
        print(f"  Cache entries cleared:           {compactor.stats['cache_entries_cleared']}")
        if compactor.stats['bytes_freed'] > 0:
            print(f"  Bytes freed:                     {compactor.stats['bytes_freed']:,}")

if __name__ == "__main__":
    main()

# Type III Clone: Refactored GGUF adapter implementation with equivalent functionality
from __future__ import annotations
from abc import ABC, abstractmethod
from collections.abc import Generator
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any
import gguf
import numpy as np
import torch

if TYPE_CHECKING:
    from vllm_omni.diffusion.data import OmniDiffusionConfig
    from vllm_omni.diffusion.model_loader.diffusers_loader import (
        DiffusersPipelineLoader,
    )


@dataclass
class MappedTensor:
    """Represents a tensor mapping with metadata."""
    name: str
    tensor: Any
    tensor_type: Any
    row_slice: slice | None = None
    swap_scale_shift: bool = False


class GGUFAdapter(ABC):
    """Base class for model-specific GGUF adapters."""

    def __init__(
        self,
        gguf_file: str,
        model: torch.nn.Module,
        source: DiffusersPipelineLoader.ComponentSource,
        od_config: OmniDiffusionConfig,
    ) -> None:
        self.gguf_file = gguf_file
        self.model = model
        self.source = source
        self.od_config = od_config

    @staticmethod
    def is_compatible(
        od_config: OmniDiffusionConfig,
        model: torch.nn.Module,
        source: DiffusersPipelineLoader.ComponentSource,
    ) -> bool:
        return False

    @abstractmethod
    def weights_iterator(self) -> Generator[tuple[str, torch.Tensor], None, None]:
        raise NotImplementedError


def _is_quantized_type(weight_type_name: str) -> bool:
    """Check if the weight type represents quantized data."""
    return weight_type_name not in ("F32", "F16")


def _process_bf16_weight(weight_data: np.ndarray, reader: gguf.GGUFReader) -> torch.Tensor:
    """Handle BF16 data that's stored as uint8 bytes."""
    # Interpret raw bytes as uint16 values
    reinterpret_as_uint16 = weight_data.view(np.uint16)

    # Handle endianness mismatch between GGUF and system
    if reader.byte_order == "S":
        reinterpret_as_uint16 = reinterpret_as_uint16.byteswap()

    # Convert to torch tensor and reshape as bfloat16
    return torch.tensor(reinterpret_as_uint16).view(torch.bfloat16)


def _convert_to_tensor(weight_data: np.ndarray, weight_type_name: str) -> torch.Tensor:
    """Convert numpy array to torch tensor based on weight type."""
    if weight_type_name == "BF16" and weight_data.dtype == np.uint8:
        return _process_bf16_weight(weight_data, gguf.GGUFReader.__new__(gguf.GGUFReader))
    else:
        return torch.tensor(weight_data)


def gguf_quant_weights_iterator(gguf_file: str) -> Generator[tuple[str, torch.Tensor], None, None]:
    """
    Iterate over the quant weights in the model GGUF files and convert them to torch tensors.

    This implementation separates the processing of quantization metadata from actual weights
    to ensure correct loading order for packed layers with different quant types.
    """
    # Open the GGUF file once for all operations
    reader = gguf.GGUFReader(gguf_file)

    # First pass: yield quantization type information for non-standard types
    for tensor in reader.tensors:
        weight_type = tensor.tensor_type
        name = tensor.name

        if _is_quantized_type(weight_type.name):
            # Replace 'weight' in name with 'qweight_type' for metadata
            metadata_name = name.replace("weight", "qweight_type")
            type_tensor = torch.tensor(weight_type)
            yield metadata_name, type_tensor

    # Second pass: yield actual weight data
    for tensor in reader.tensors:
        weight_data = tensor.data
        weight_type = tensor.tensor_type
        name = tensor.name

        if _is_quantized_type(weight_type.name):
            # Replace 'weight' in name with 'qweight' for quantized weights
            name = name.replace("weight", "qweight")

        # Handle special case for BF16 stored as uint8
        if weight_type.name == "BF16" and weight_data.dtype == np.uint8:
            param = _process_bf16_weight(weight_data, reader)
        else:
            param = torch.tensor(weight_data)

        yield name, param

import os
import json
import requests
import argparse

class GaodeMapService:
    def __init__(self, api_token):
        self.api_token = api_token
        self.endpoint_prefix = "https://restapi.amap.com/v3"

    def find_places(self, query_terms, region=None):
        """
        Query points of interest using search terms.
        """
        endpoint = f"{self.endpoint_prefix}/place/text"
        parameters = {
            "key": self.api_token,
            "keywords": query_terms,
            "output": "json"
        }
        if region:
            parameters["city"] = region

        try:
            response = requests.get(endpoint, params=parameters)
            response.raise_for_status()
            result = response.json()
            if result.get("status") == "1":
                return result.get("pois", [])
            else:
                return {"error": result.get("info", "Unknown error occurred")}
        except Exception as ex:
            return {"error": str(ex)}

    def get_coordinates(self, location_name, region=None):
        """
        Transform a textual address into geographic coordinates.
        """
        endpoint = f"{self.endpoint_prefix}/geocode/geo"
        parameters = {
            "key": self.api_token,
            "address": location_name,
            "output": "json"
        }
        if region:
            parameters["city"] = region

        try:
            response = requests.get(endpoint, params=parameters)
            response.raise_for_status()
            result = response.json()
            if result.get("status") == "1" and result.get("geocodes"):
                return result["geocodes"][0]["location"]
            return None
        except:
            return None

    def calculate_direction(self, start_point, end_point, travel_mode="driving", region=None):
        """
        Compute route between two locations.
        Locations can be coordinates (lon,lat) or place names.
        If names are given, automatic geocoding is attempted.
        """
        # Convert start point to coordinates if needed
        if "," not in start_point:
            coord = self.get_coordinates(start_point, region)
            if coord:
                start_point = coord
            else:
                return {"error": f"Failed to resolve start location: {start_point}"}

        # Convert end point to coordinates if needed
        if "," not in end_point:
            coord = self.get_coordinates(end_point, region)
            if coord:
                end_point = coord
            else:
                return {"error": f"Failed to resolve end location: {end_point}"}

        # Select appropriate API endpoint based on travel mode
        if travel_mode == "driving":
            endpoint = f"{self.endpoint_prefix}/direction/driving"
        elif travel_mode == "walking":
            endpoint = f"{self.endpoint_prefix}/direction/walking"
        elif travel_mode == "bicycling":
            endpoint = f"{self.endpoint_prefix}/direction/bicycling"
        elif travel_mode == "transit":
            endpoint = f"{self.endpoint_prefix}/direction/transit/integrated"
            if not region:
                return {"error": "City parameter is mandatory for public transit routing"}
        else:
            return {"error": f"Unsupported travel mode: {travel_mode}"}

        request_params = {
            "key": self.api_token,
            "origin": start_point,
            "destination": end_point,
            "output": "json"
        }

        if travel_mode == "transit" and region:
            request_params["city"] = region

        try:
            response = requests.get(endpoint, params=request_params)
            response.raise_for_status()
            data = response.json()
            if data.get("status") == "1":
                return data.get("route", {})
            else:
                return {"error": data.get("info", "Routing service returned an error")}
        except Exception as exception:
            return {"error": str(exception)}

def main():
    parser = argparse.ArgumentParser(description="Gaode Map (AMap) Utility Tool")
    parser.add_argument("command", choices=["find", "direction"], help="Operation to execute")
    parser.add_argument("--token", help="Gaode Map API Token (or use AMAP_API_TOKEN environment variable)")
    parser.add_argument("--terms", help="Search terms for finding places")
    parser.add_argument("--region", help="City/region scope for searches or routing")
    parser.add_argument("--start", help="Starting point for route calculation")
    parser.add_argument("--finish", help="Destination point for route calculation")
    parser.add_argument("--type", default="driving", 
                        choices=["driving", "walking", "bicycling", "transit"], 
                        help="Mode of transport for routing")
    arguments = parser.parse_args()

    token = arguments.token or os.environ.get("AMAP_API_TOKEN")
    if not token:
        print(json.dumps({"error": "API token required. Provide via --token or set AMAP_API_TOKEN environment variable."}))
        sys.exit(1)

    service = GaodeMapService(token)
    output = {}

    if arguments.command == "find":
        if not arguments.terms:
            output = {"error": "--terms must be specified for place search"}
        else:
            output = service.find_places(arguments.terms, arguments.region)

    elif arguments.command == "direction":
        if not arguments.start or not arguments.finish:
            output = {"error": "--start and --finish are required for route calculation"}
        else:
            output = service.calculate_direction(arguments.start, arguments.finish, arguments.type, arguments.region)

    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    main()

import inspect
import json
import re
from typing import Any, Callable, Dict, Optional, Tuple, Union, get_args, get_origin, get_type_hints

# Define basic types for schema mapping
BASIC_TYPES = (int, float, str, bool, Any, type(None), ...)

# Regex patterns for parsing Google-style docstrings
description_pattern = re.compile(r"^(.*?)[\n\s]*(Args:|Returns:|Raises:|\Z)", re.DOTALL)
arguments_pattern = re.compile(r"\n\s*Args:\n\s*(.*?)[\n\s]*(Returns:|Raises:|\Z)", re.DOTALL)
argument_split_pattern = re.compile(
    r"""
(?:^|\n)  # Start of args block or newline
\s*(\w+):\s*  # Argument name with colon and spacing
(.*?)\s*  # Argument description (multi-line safe)
(?=\n\s*\w+:|\Z)  # Stop at next argument or end
""",
    re.DOTALL | re.VERBOSE,
)
returns_pattern = re.compile(r"\n\s*Returns:\n\s*(.*?)[\n\s]*(Raises:|\Z)", re.DOTALL)


class TypeHintParseError(Exception):
    """Raised when type hint parsing fails."""
    pass


class DocstringParseError(Exception):
    """Raised when docstring parsing fails."""
    pass


def _map_to_json_type(param_type: type) -> Dict[str, str]:
    """Map Python types to JSON schema types."""
    type_map = {
        int: {"type": "integer"},
        float: {"type": "number"},
        str: {"type": "string"},
        bool: {"type": "boolean"},
        Any: {},
        type(None): {"type": "null"},
    }
    return type_map.get(param_type, {"type": "object"})


def _extract_schema_from_type(hint: type) -> Dict:
    """Recursively convert a Python type hint into a JSON schema fragment."""
    origin = get_origin(hint)
    args = get_args(hint)

    if origin is None:
        try:
            return _map_to_json_type(hint)
        except KeyError:
            raise TypeHintParseError(f"Unsupported type hint: {hint}")

    elif origin is Union:
        non_none_types = [t for t in args if t is not type(None)]
        sub_schemas = [_extract_schema_from_type(t) for t in non_none_types]

        if len(sub_schemas) == 1:
            result = sub_schemas[0]
        elif all(s.get("type") and isinstance(s["type"], str) for s in sub_schemas):
            result = {"type": sorted(list(set(s["type"] for s in sub_schemas)))}
        else:
            result = {"anyOf": sub_schemas}

        if type(None) in args:
            result["nullable"] = True
        return result

    elif origin is list:
        if not args:
            return {"type": "array"}
        return {"type": "array", "items": _extract_schema_from_type(args[0])}

    elif origin is tuple:
        if not args:
            return {"type": "array"}
        if len(args) == 1:
            raise TypeHintParseError(
                f"Tuple with single element '{hint}' is not supported; use List instead."
            )
        if ... in args:
            raise TypeHintParseError("'...' in Tuple is unsupported; use List for variable-length sequences.")
        return {"type": "array", "prefixItems": [_extract_schema_from_type(t) for t in args]}

    elif origin is dict:
        out = {"type": "object"}
        if len(args) == 2:
            out["additionalProperties"] = _extract_schema_from_type(args[1])
        return out

    raise TypeHintParseError(f"Unrecognized type hint: {hint}")


def _build_json_schema_from_function(func: Callable) -> Dict:
    """Generate a JSON schema from function type hints and signature."""
    type_hints = get_type_hints(func)
    sig = inspect.signature(func)

    required_params = []
    properties = {}

    for param_name, param in sig.parameters.items():
        if param.annotation is inspect.Parameter.empty:
            raise TypeHintParseError(f"Missing type hint for parameter '{param_name}' in '{func.__name__}'")
        if param.default is inspect.Parameter.empty:
            required_params.append(param_name)

        properties[param_name] = _extract_schema_from_type(param.annotation)

    schema = {"type": "object", "properties": properties}
    if required_params:
        schema["required"] = required_params

    return schema


def parse_google_docstring(doc: str) -> Tuple[Optional[str], Optional[Dict[str, str]], Optional[str]]:
    """
    Parse a Google-style docstring into its components.

    Returns:
        - Function description
        - Dictionary of argument descriptions
        - Return description (if any)
    """
    desc_match = description_pattern.search(doc)
    args_match = arguments_pattern.search(doc)
    returns_match = returns_pattern.search(doc)

    func_desc = desc_match.group(1).strip() if desc_match else None
    raw_args = args_match.group(1).strip() if args_match else None
    return_desc = returns_match.group(1).strip() if returns_match else None

    arg_dict = {}
    if raw_args:
        cleaned_lines = [line for line in raw_args.split("\n") if line.strip()]
        matches = argument_split_pattern.findall("\n".join(cleaned_lines))
        arg_dict = {name: re.sub(r"\s*\n+\s*", " ", desc.strip()) for name, desc in matches}

    return func_desc, arg_dict, return_desc


def get_json_schema(func: Callable) -> Dict:
    """
    Generate a JSON schema for a function using its docstring and type hints.

    The function must have:
      - A docstring in Google format
      - Type hints on all parameters
      - Descriptions for each argument in the docstring

    Optional:
      - A `Returns` section in the docstring

    Supports:
      - Basic types (int, float, str, bool, None, Any)
      - Union types (including nullable types)
      - List[T], Tuple[T1, T2, ...], Dict[K, V]
      - Enum choices via `(choices: [...])` syntax in argument descriptions

    Returns:
        A structured dictionary representing the function as a tool/schema.
    """
    doc = inspect.getdoc(func)
    if not doc:
        raise DocstringParseError(f"No docstring found for function '{func.__name__}'")

    doc = doc.strip()
    main_desc, arg_descriptions, return_desc = parse_google_docstring(doc)
    base_schema = _build_json_schema_from_function(func)

    # Handle return value if present
    return_schema = base_schema["properties"].pop("return", None)
    if return_schema and return_desc:
        return_schema["description"] = return_desc

    # Attach descriptions and handle enum choices
    for param_name, schema in base_schema["properties"].items():
        if param_name not in arg_descriptions:
            raise DocstringParseError(
                f"Missing description for argument '{param_name}' in docstring of '{func.__name__}'"
            )

        desc = arg_descriptions[param_name]
        enum_match = re.search(r"\(choices:\s*(.*?)\)\s*$", desc, flags=re.IGNORECASE)
        if enum_match:
            try:
                choices = json.loads(enum_match.group(1))
                schema["enum"] = [str(c).strip() for c in choices]
            except json.JSONDecodeError:
                pass  # Ignore invalid enum syntax
            desc = desc[: enum_match.start()].strip()
        schema["description"] = desc

    # Build final output structure
    output = {
        "name": func.__name__,
        "description": main_desc,
        "parameters": base_schema,
    }
    if return_schema:
        output["return"] = return_schema

    return {"type": "function", "function": output}

import os
from typing import Callable, Dict, Any
from primus.core.pipeline_parallel.handler.offload_handler import OFFLOAD_BUFFER
from primus.core.pipeline_parallel.scheduler.scheduler_node import FuncType

class ScheduleRunner:
    def __init__(
        self,
        execution_handlers: Dict[FuncType, Callable],
        setup_func: Callable = None,
        cleanup_func: Callable = None,
    ):
        self.execution_handlers = execution_handlers
        self.setup_func = setup_func
        self.cleanup_func = cleanup_func

    def execute(self, schedule_table, device_rank: int):
        for position, task in enumerate(schedule_table[device_rank]):
            if task.arguments is not None and "combined_group" in task.arguments:
                handler = self.execution_handlers[FuncType.FB]
                handler(task, position, schedule_table[device_rank])
            else:
                if self.setup_func is not None:
                    self.setup_func(task, position, schedule_table[device_rank])

                handler = self.execution_handlers[task.operation_type]
                handler(task, position, schedule_table[device_rank])

                if self.cleanup_func is not None:
                    self.cleanup_func(task, position, schedule_table[device_rank])

        OFFLOAD_BUFFER.validate_empty()

        memory_log_dir = os.environ.get("RECORD_OFFLOAD_MEMORY_INFO_DIR", "output")
        output_path = f"{memory_log_dir}/offload_memory_info/rank-{device_rank}"

        if OFFLOAD_BUFFER.should_record_offload_memory:
            os.makedirs(output_path, exist_ok=True)
            with open(f"{output_path}/offload_memory_info.txt", "w") as log_file:
                OFFLOAD_BUFFER.dump_offload_memory_details(log_file)

"""
Decorator for forward methods to manage Automatic Mixed Precision (AMP) behavior.
Authors
 * Sylvain de Langen 2023
"""
import functools
from typing import Callable, Optional, Any
import torch


def _apply_input_cast(inputs: tuple, target_dtype: torch.dtype) -> tuple:
    """Recursively cast floating-point tensors in inputs to specified dtype."""
    def _cast_tensor(tensor):
        if isinstance(tensor, torch.Tensor) and tensor.is_floating_point():
            return tensor.to(target_dtype)
        return tensor

    def _process_container(container):
        if isinstance(container, dict):
            return {k: _process_container(v) for k, v in container.items()}
        elif isinstance(container, (list, tuple)):
            return type(container)(_process_container(item) for item in container)
        else:
            return _cast_tensor(container)

    result = []
    for item in inputs:
        result.append(_process_container(item))
    return tuple(result)


def fwd_default_precision(
    func: Optional[Callable] = None,
    input_dtype: Optional[torch.dtype] = torch.float32,
):
    """
    Decorator that manages AMP behavior for forward methods by default disabling
    autocast and optionally casting inputs to specified precision.

    The decorated function gains an additional keyword-only parameter:
    - force_allow_autocast: bool (default=False) - when True, bypasses all
      modifications and uses the original function directly.

    Note: This implementation currently only supports CUDA AMP contexts.
    Non-CUDA AMP scenarios are not modified but may be supported in future versions.

    When autocast is inactive, this decorator has no effect on behavior.

    Parameters
    ----------
    func : Optional[Callable]
        Function to wrap. If None, returns a partially configured decorator.
    input_dtype : Optional[torch.dtype]
        Target dtype for input casting (default: torch.float32).
        Set to None to disable input casting.

    Returns
    -------
    Callable
        Wrapped function with modified AMP behavior.
    """
    # Handle partial application case
    if func is None:
        return functools.partial(fwd_default_precision, input_dtype=input_dtype)

    # Create base wrapped function using PyTorch's custom_fwd
    base_func = torch.cuda.amp.custom_fwd(func, cast_inputs=input_dtype)

    @functools.wraps(func)
    def amp_wrapper(*args, force_allow_autocast: bool = False, **kwargs):
        """
        Wrapper implementing configurable AMP behavior.

        Parameters
        ----------
        *args : tuple
            Positional arguments passed to the original function.
        force_allow_autocast : bool
            When True, skip all AMP handling and execute original function directly.
        **kwargs : dict
            Keyword arguments passed to the original function.

        Returns
        -------
        Any
            Result from either the original or wrapped function.
        """
        # Bypass all modifications when explicitly requested
        if force_allow_autocast:
            return func(*args, **kwargs)

        # Check if autocast context is active
        autocast_enabled = torch.is_autocast_enabled()

        if not autocast_enabled:
            # No change needed when autocast is already disabled
            return func(*args, **kwargs)

        # When autocast is enabled, use the base wrapped version
        return base_func(*args, **kwargs)

    return amp_wrapper

