        "handlers": [
            "console_err",
            "console_out",
            "debug_file",
            "error_file"
        ]
    }
}
"""

class ColoredRelPathFormatter(logging.Formatter):
    ANSI_COLORS = {
        logging.CRITICAL: "\033[1;35m",  # bright/bold magenta
        logging.ERROR: "\033[1;31m",     # bright/bold red
        logging.WARNING: "\033[1;33m",   # bright/bold yellow
        logging.INFO: "\033[0;37m",      # white / light gray
        logging.DEBUG: "\033[1;30m",     # bright/bold dark gray
    }
    RESET_SEQUENCE = "\033[0m"

    def __init__(self, use_color=True, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.use_color = use_color
        base_path = pathlib.Path(__file__).resolve()
        self.base_dir = str(base_path.parent.parent.parent)

    def format(self, record, *args, **kwargs):
        if self.use_color and record.levelno in self.ANSI_COLORS:
            record.color_start = self.ANSI_COLORS[record.levelno]
            record.color_end = self.RESET_SEQUENCE
        else:
            record.color_start = ""
            record.color_end = ""

        # Convert absolute path to relative path from project root
        abs_path = getattr(record, 'pathname', '')
        if abs_path:
            try:
                rel_path = os.path.relpath(abs_path, self.base_dir)
                record.pathname = rel_path
            except ValueError:
                pass  # On Windows, relpath can fail for different drives

        return super().format(record, *args, **kwargs)


@lru_cache(maxsize=1)
def setup_logging(run_id=None, config_dict=None):
    """
    Configure the package-wide logger with specified handlers and formatting.

    Note: This function uses caching to ensure it only executes once per process.
    Subsequent calls will not reconfigure logging.

    Parameters:
    - run_id (str or None): Optional identifier used to create a dedicated output directory
    - config_dict (dict or None): Custom logging configuration dictionary; if None,
      uses the built-in DEFAULT_LOGGING_CONFIG
    """
    # Determine output directory based on run_id
    output_directory = ""
    if run_id is not None:
        output_directory = f"./output/{run_id}"

    # Load default config if none provided
    if config_dict is None:
        config_dict = json.loads(DEFAULT_LOGGING_CONFIG)

        # Remove file handlers when no run_id is given
        if run_id is None:
            del config_dict["handlers"]["debug_file"]
            del config_dict["handlers"]["error_file"]
            config_dict["root"]["handlers"] = config_dict["root"]["handlers"][:2]

    # Process handler configurations
    for handler_name, handler_settings in config_dict["handlers"].items():
        for key, value in handler_settings.items():
            if key == "formatter":
                continue
            elif key == "filename":
                # Construct full path for log files
                filename = f"{output_directory}/{run_id}-{value}" if run_id else value
                log_file_path = pathlib.Path(filename)

                # Ensure absolute path handling
                if not log_file_path.is_absolute():
                    shared_working_dir = pathlib.Path(
                        _load_private_conf().get("path_shared_working_dir")
                    )
                    log_file_path = shared_working_dir / log_file_path

                # Create parent directories if needed
                log_file_path.parent.mkdir(parents=True, exist_ok=True)
                handler_settings[key] = str(log_file_path)
            else:
                continue

    # Apply logging configuration
    logging.config.dictConfig(config_dict)

    # Log confirmation message
    if output_directory:
        logging.info(f"Logging initialized. Logs stored at: {output_directory}")
    else:
        logging.info("Logging initialized. No log files were created.")

