    "self_attention.wk.weight",
}

def _extract_layer_info(megatron_name):
    """Extract layer index and remaining path from megatron parameter name."""
    patterns = [
        r"module\.module\.decoder\.layers\.(\d+)\.(.+)",
        r"module\.module\.mtp\.layers\.(\d+)\.(.+)"
    ]
    for pat in patterns:
        match = re.search(pat, megatron_name)
        if match:
            return match.group(1), match.group(2).replace("transformer_layer.", "")
    return None, None

def _is_moe_expert(name):
    """Check if parameter belongs to MoE experts (not shared)."""
    return ".experts." in name

def _should_use_ue8m0_scale(args, name, blk_sz):
    """Determine whether to use ue8m0 scale format."""
    if not should_deepgemm_weight_requant_ue8m0(weight_block_size=blk_sz):
        return False
    if not _is_moe_expert(name):
        return True  # non-MoE always ue8m0 when deepgemm enabled
    # MoE: only ue8m0 for specific backends
    is_deepgemm_backend = args.sglang_moe_runner_backend == "deep_gemm"
    is_auto_deepgemm = (
        args.sglang_moe_runner_backend == "auto" and
        args.sglang_moe_a2a_backend in {"deepep", "mooncake"}
    )
    return is_deepgemm_backend or is_auto_deepgemm

def _quantize_single_weight(weight, blk_sz, use_ue8m0):
    """Quantize a single weight tensor."""
    FP8_MIN = torch.finfo(torch.float8_e4m3fn).min
    FP8_MAX = torch.finfo(torch.float8_e4m3fn).max

    if blk_sz is not None:
        if use_ue8m0:
            qw, sc = quant_weight_ue8m0(weight, weight_block_size=blk_sz)
            sc = transform_scale_ue8m0(sc, mn=qw.shape[-2])
        else:
            qw, sc = blockwise_cast_to_fp8_triton(weight, blk_sz)
        scale_name_suffix = ".weight_scale_inv"
    else:
        # per-tensor quantization
        scale_val = weight.abs().max().clamp(min=1e-12).to(torch.float32) / FP8_MAX
        qw = (weight / scale_val).clamp(min=FP8_MIN, max=FP8_MAX).to(torch.float8_e4m3fn)
        scale_val = scale_val.view(1)
        scale_name_suffix = ".weight_scale"

    return qw, scale_val, scale_name_suffix

def _process_param_quantization(args, param_list, blk_sz, use_ue8m0):
    """Apply quantization to each (name, weight) pair."""
    result = []
    for full_name, wgt in param_list:
        if full_name.endswith("_scale"):
            continue  # skip existing scale params
        q_w, sc, suf = _quantize_single_weight(wgt, blk_sz, use_ue8m0)
        new_name = full_name.replace(".weight", suf)
        result.append((full_name, q_w))
        result.append((new_name, sc))
    return result

def quantize_params_fp8(args, megatron_name, param_list, quant_config):
    assert quant_config["quant_method"] == "fp8"
    assert quant_config["fmt"] == "e4m3"
    assert quant_config["activation_scheme"] == "dynamic"

    blk_sz = quant_config.get("weight_block_size")
    layer_idx, rest_path = _extract_layer_info(megatron_name)

    if layer_idx is None:
        return param_list  # Not a layer weight

    # Handle MoE expert weights
    expert_match = re.search(r"mlp\.experts\.(.+)\.weight(\d+)", rest_path)
    if expert_match:
        rest_part, _ = expert_match.groups()
        if rest_part in MOE_WEIGHT_NAMES:
            use_ue8m0 = _should_use_ue8m0_scale(args, megatron_name, blk_sz)
            return _process_param_quantization(args, param_list, blk_sz, use_ue8m0)

    # Handle shared expert weights
    shared_expert_match = re.search(r"mlp\.shared_experts\.(.+)", rest_path)
    if shared_expert_match:
        rest_part = shared_expert_match.group(1) + ".weight"
        if rest_part in SHARED_EXPERT_WEIGHT_NAMES:
            use_ue8m0 = _should_use_ue8m0_scale(args, megatron_name, blk_sz)
            return _process_param_quantization(args, param_list, blk_sz, use_ue8m0)

    # Handle standard attention/MLP weights
    if rest_path in ATTENTION_WEIGHT_NAMES:
        use_ue8m0 = _should_use_ue8m0_scale(args, megatron_name, blk_sz)
        return _process_param_quantization(args, param_list, blk_sz, use_ue8m0)

    # Default: no quantization
    return param_list

from __future__ import annotations
import torch
