    from robolab.tasks.manager_based.amp.animation_env import AnimationEnv


class AnimationController(ManagerTermBase):
    """Controls animation playback using motion capture data."""

    config: AnimationTermCfg
    _simulation_env: AnimationEnv

    def __init__(self, config: AnimationTermCfg, simulation_env: AnimationEnv):
        super().__init__(config, simulation_env)

        # Determine time step indices based on configuration
        if config.num_steps_to_use > 0:
            self._time_indices = torch.arange(0, config.num_steps_to_use, dtype=torch.long, device=simulation_env.device)
        elif config.num_steps_to_use < 0:
            self._time_indices = torch.arange(config.num_steps_to_use + 1, 1, dtype=torch.long, device=simulation_env.device)
        else:
            raise ValueError("Number of steps must be non-zero.")

        # Retrieve motion data source
        self._motion_source: MotionDataTerm = simulation_env.motion_data_manager.get_term(config.motion_data_term)

        # Initialize buffers for storing fetched motion data
        num_time_steps = len(self._time_indices)
        for component in config.motion_data_components:
            base_shape = (self.num_envs, num_time_steps)
            if component in {"root_pos_w", "root_vel_w", "root_vel_b", "root_ang_vel_w", "root_ang_vel_b"}:
                shape = base_shape + (3,)
            elif component == "root_quat":
                shape = base_shape + (4,)
            elif component in {"dof_pos", "dof_vel"}:
                shape = base_shape + (self._motion_source.num_dofs,)
            elif component == "key_body_pos_b":
                shape = base_shape + (self._motion_source.num_key_bodies, 3)
            else:
                raise ValueError(f"Unsupported motion component: {component}")
            setattr(self, f"{component}_cache", torch.zeros(shape, device=simulation_env.device, dtype=torch.float32))

        # Track active motions per environment
        self._active_motions = torch.zeros(self.num_envs, device=simulation_env.device, dtype=torch.long)
        self._fetch_timestamps = torch.zeros((self.num_envs, num_time_steps), device=simulation_env.device, dtype=torch.float32)
        self._motion_lengths = torch.zeros(self.num_envs, device=simulation_env.device, dtype=torch.float32)

        # Initial setup
        self.reset(torch.arange(self.num_envs))
        self._load_motion_samples()

        # Visualization setup
        if config.enable_visualization:
            self._vis_offset = torch.tensor(config.vis_root_offset, device=simulation_env.device, dtype=torch.float32).unsqueeze(0)

            marker_config = VisualizationMarkersCfg(
                prim_path="/Visuals/KeyBodyVisualizerFromController",
                markers={
                    "blue_sphere": sim_utils.SphereCfg(
                        radius=0.03,
                        visual_material=sim_utils.PreviewSurfaceCfg(diffuse_color=(0.0, 0.0, 1.0))
                    ),
                }
            )
            self._key_body_markers: VisualizationMarkers = VisualizationMarkers(marker_config)

    def reset(self, env_indices: Sequence[int] | None = None):
        if env_indices is None:
            return

        # Sample new motions for specified environments
        self._active_motions[env_indices] = self._motion_source.sample_motions(len(env_indices))
        self._motion_lengths[env_indices] = self._motion_source.get_motion_durations(self._active_motions[env_indices])

        total_duration = len(self._time_indices) * self._simulation_env.step_dt

        if self.config.random_initialize:
            # Random start time within valid range
            if self.config.num_steps_to_use > 0:
                self._fetch_timestamps[env_indices, 0] = self._motion_source.sample_times(
                    self._active_motions[env_indices], truncate_time_end=total_duration
                )
            else:
                self._fetch_timestamps[env_indices, 0] = self._motion_source.sample_times(
                    self._active_motions[env_indices], truncate_time_start=total_duration
                )
        else:
            # Start at beginning of motion
            self._fetch_timestamps[env_indices, 0] = 0.0

        if len(self._time_indices) > 1:
            self._fetch_timestamps[env_indices, 1:] = (
                self._fetch_timestamps[env_indices, 0].unsqueeze(-1) +
                self._time_indices[1:].float() * self._simulation_env.step_dt
            )

        self._load_motion_samples(env_indices)

    def update(self, delta_time: float):
        if self.config.random_fetch:
            duration_limit = len(self._time_indices) * delta_time
            if self.config.num_steps_to_use > 0:
                self._fetch_timestamps[:, 0] = self._motion_source.sample_times(
                    self._active_motions, truncate_time_end=duration_limit
                )
            else:
                self._fetch_timestamps[:, 0] = self._motion_source.sample_times(
                    self._active_motions, truncate_time_start=duration_limit
                )

            if len(self._time_indices) > 1:
                self._fetch_timestamps[:, 1:] = (
                    self._fetch_timestamps[:, 0].unsqueeze(-1) +
                    self._time_indices[1:].float() * delta_time
                )

        self._load_motion_samples()

        # Advance timestamps unless random fetching is enabled
        if not self.config.random_fetch:
            self._fetch_timestamps += delta_time

        if self.config.enable_visualization:
            self._render_visualization()

    def _load_motion_samples(self, env_indices: Sequence[int] | None = None):
        if env_indices is None:
            env_indices = torch.arange(self.num_envs, device=self._simulation_env.device)

        # Prepare flattened query arrays
        batch_size = len(env_indices)
        total_queries = batch_size * len(self._time_indices)
        times_flat = self._fetch_timestamps[env_indices].reshape(-1)
        ids_flat = self._active_motions[env_indices].repeat_interleave(len(self._time_indices))

        # Validate shapes
        assert times_flat.shape[0] == total_queries
        assert ids_flat.shape[0] == total_queries

        # Fetch motion data
        motion_info = self._motion_source.get_motion_state(
            motion_ids=ids_flat,
            motion_times=times_flat
        )

        # Store results in respective buffers
        for component in self.config.motion_data_components:
            if component in motion_info:
                cache_name = f"{component}_cache"
                raw_data = motion_info[component]
                reshaped = raw_data.view(batch_size, len(self._time_indices), *raw_data.shape[1:])
                getattr(self, cache_name)[env_indices, :, :] = reshaped

    def _render_visualization(self):
        try:
            animated_robot: Articulation = self._simulation_env.scene["robot_anim"]
        except KeyError:
            print("[WARNING] AnimationController visualization: 'robot_anim' not found in scene.")
            return

        required_buffers = ["root_pos_w_cache", "root_quat_cache", "dof_pos_cache"]
        if not all(hasattr(self, buf) for buf in required_buffers):
            print("[WARNING] AnimationController visualization: missing required buffers.")
            return

        root_positions = self.root_pos_w_cache[:, 0, :]
        root_orientations = self.root_quat_cache[:, 0, :]
        joint_positions = self.dof_pos_cache[:, 0, :]

        # Update robot state
        current_root_state = animated_robot.data.default_root_state.clone()
        current_root_state[:, :3] = (
            root_positions +
            self._simulation_env.scene.env_origins[:, :3] +
            self._vis_offset
        )
        current_root_state[:, 3:7] = root_orientations
        current_root_state[:, 7:10] = 0.0
        current_root_state[:, 10:13] = 0.0
        animated_robot.write_root_state_to_sim(current_root_state)

        # Set joint positions
        joint_state = animated_robot.data.default_joint_pos.clone()
        joint_state[:] = joint_positions
        joint_velocity = torch.zeros_like(animated_robot.data.default_joint_vel)
        animated_robot.write_joint_state_to_sim(joint_state, joint_velocity)

        # Visualize key body positions
        key_body_local = self.key_body_pos_b_cache[:, 0, :, :]
        num_key_bodies = key_body_local.shape[1]
        key_body_world = (
            current_root_state[:, :3].unsqueeze(1) +
            math_utils.quat_apply(
                root_orientations.unsqueeze(1).expand(-1, num_key_bodies, -1),
                key_body_local
            )
        )
        self._key_body_markers.visualize(translations=key_body_world.reshape(-1, 3))

    # Public accessors for motion data
    def get_root_position(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_pos_w_cache"):
            raise AttributeError("root_pos_w_cache not available.")
        return self.root_pos_w_cache if env_ids is None else self.root_pos_w_cache[env_ids]

    def get_root_orientation(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_quat_cache"):
            raise AttributeError("root_quat_cache not available.")
        return self.root_quat_cache if env_ids is None else self.root_quat_cache[env_ids]

    def get_joint_positions(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "dof_pos_cache"):
            raise AttributeError("dof_pos_cache not available.")
        return self.dof_pos_cache if env_ids is None else self.dof_pos_cache[env_ids]

    def get_joint_velocities(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "dof_vel_cache"):
            raise AttributeError("dof_vel_cache not available.")
        return self.dof_vel_cache if env_ids is None else self.dof_vel_cache[env_ids]

    def get_key_body_positions(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "key_body_pos_b_cache"):
            raise AttributeError("key_body_pos_b_cache not available.")
        return self.key_body_pos_b_cache if env_ids is None else self.key_body_pos_b_cache[env_ids]

    def get_root_linear_velocity(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_vel_w_cache"):
            raise AttributeError("root_vel_w_cache not available.")
        return self.root_vel_w_cache if env_ids is None else self.root_vel_w_cache[env_ids]

    def get_root_angular_velocity(self, env_ids: Sequence[int] = None) -> torch.Tensor:
        if not hasattr(self, "root_ang_vel_w_cache"):
            raise AttributeError("root_ang_vel_w_cache not available.")
        return self.root_ang_vel_w_cache if env_ids is None else self.root_ang_vel_w_cache[env_ids]


class AnimationDirector(ManagerBase):
    """Manages multiple animation controllers."""

    def __init__(self, config: object, simulation_env: AnimationEnv):
        if config is None:
            raise ValueError("AnimationDirector requires a configuration object.")

        self._controllers: dict[str, AnimationController] = {}
        self._controller_configs: dict[str, AnimationTermCfg] = {}

        super().__init__(config, simulation_env)

    def __str__(self) -> str:
        """Returns formatted summary of active animation terms."""
        info = f"<AnimationDirector> manages {len(self._controllers)} active components.\n"

        table = PrettyTable()
        table.title = "Animation Director Components"
        table.field_names = ["ID", "Component Name", "Motion Source", "Steps", "Random Init", "Random Fetch"]
        for idx, (name, cfg) in enumerate(self._controller_configs.items()):
            table.add_row([
                idx,
                name,
                cfg.motion_data_term,
                cfg.num_steps_to_use,
                cfg.random_initialize,
                cfg.random_fetch
            ])
        info += table.get_string()
        info += "\n"

        return info

    def update(self, delta_time: float):
        """Update all registered animation components."""
        for controller in self._controllers.values():
            controller.update(delta_time)

    def reset(self, env_indices: Sequence[int] | None = None) -> dict[str, torch.Tensor]:
        if env_indices is None:
            return {}
        for controller in self._controllers.values():
            controller.reset(env_indices)
        return {}

    @property
    def active_components(self) -> list[str]:
        """List of active component names."""
        return list(self._controllers.keys())

    def get_component(self, name: str) -> AnimationController:
        """Retrieve a specific animation component by name."""
        if name not in self._controllers:
            raise KeyError(f"Animation component '{name}' does not exist.")
        return self._controllers[name]

    def _initialize_components(self):
        # Handle both dict and object-style configs
        if isinstance(self.config, dict):
            items = self.config.items()
        else:
            items = self.config.__dict__.items()

        for name, cfg in items:
            if cfg is None:
                continue
            if not isinstance(cfg, AnimationTermCfg):
                raise TypeError(
                    f"Invalid config type for '{name}'. Expected AnimationTermCfg, got {type(cfg)}."
                )

            controller = AnimationController(cfg, self._simulation_env)
            self._controllers[name] = controller
            self._controller_configs[name] = cfg

