# --- Layout & Array Type Definitions ---
VideoLayoutType = Literal["THWC", "TCHW"]
VideoArrayType = Literal["numpy", "torch"]


def _convert_layout(data: Union[np.ndarray, torch.Tensor], src_layout: str, dst_layout: str) -> Union[np.ndarray, torch.Tensor]:
    """Convert between THWC and TCHW layouts."""
    if src_layout == dst_layout:
        return data
    if isinstance(data, torch.Tensor):
        if src_layout == "THWC" and dst_layout == "TCHW":
            return data.permute(0, 3, 1, 2)
        elif src_layout == "TCHW" and dst_layout == "THWC":
            return data.permute(0, 2, 3, 1)
    else:  # numpy
        if src_layout == "THWC" and dst_layout == "TCHW":
            return np.transpose(data, (0, 3, 1, 2))
        elif src_layout == "TCHW" and dst_layout == "THWC":
            return np.transpose(data, (0, 2, 3, 1))
    raise ValueError(f"Unsupported layout conversion from {src_layout} to {dst_layout}")


def _cast_to_array_type(data: Union[np.ndarray, torch.Tensor], target_type: VideoArrayType) -> Union[np.ndarray, torch.Tensor]:
    """Cast tensor/array to desired output type."""
    if target_type == "torch":
        return torch.as_tensor(data) if not isinstance(data, torch.Tensor) else data
    elif target_type == "numpy":
        return data.numpy() if isinstance(data, torch.Tensor) else data
    raise ValueError(f"Unknown array type: {target_type}")


class BaseVideoBackend(ABC):
    """Base backend interface supporting lazy loading and flexible output formats."""

    def __init__(self, video_path: str, layout: VideoLayoutType = "TCHW", array_type: VideoArrayType = "torch"):
        self._path = Path(video_path)
        self._layout = layout
        self._array_type = array_type
        self._data_loaded = False
        self._fps = None
        self._length = None
        self._raw_data = None
        self._load()

    @abstractmethod
    def _load(self):
        """Load raw video data into internal storage."""
        pass

    def _ensure_loaded(self):
        if not self._data_loaded:
            self._load()
            self._data_loaded = True

    def get_batch(self, frame_indices: Union[np.ndarray, torch.Tensor]) -> Union[np.ndarray, torch.Tensor]:
        self._ensure_loaded()
        batch = self._extract_batch(frame_indices)
        converted = _convert_layout(batch, self._get_internal_layout(), self._layout)
        return _cast_to_array_type(converted, self._array_type)

    @abstractmethod
    def _extract_batch(self, indices: Union[np.ndarray, torch.Tensor]) -> Union[np.ndarray, torch.Tensor]:
        """Extract frames at given indices in internal format."""
        pass

    @abstractmethod
    def _get_internal_layout(self) -> str:
        """Return layout used internally by this backend."""
        pass

    def get_video_fps(self) -> float:
        self._ensure_loaded()
        if self._fps is None:
            self._fps = self._compute_fps()
        return self._fps

    @abstractmethod
    def _compute_fps(self) -> float:
        """Compute FPS from metadata."""
        pass

    def get_len(self) -> int:
        self._ensure_loaded()
        if self._length is None:
            self._length = self._count_frames()
        return self._length

    @abstractmethod
    def _count_frames(self) -> int:
        """Count total number of frames."""
        pass


# --- Decord Backend Implementation ---
