        if DecordInit is None:
            raise RuntimeError("DecordInit not available.")
        if DecordBackend._shared_decoder is None:
            DecordBackend._shared_decoder = DecordInit()
        self._raw_data = DecordBackend._shared_decoder(str(self._path))

    def _extract_batch(self, indices):
        return self._raw_data.get_batch(indices).asnumpy()

    def _get_internal_layout(self):
