# --- Torchvision Backend Implementation ---
class TorchvisionBackend(BaseVideoBackend):
    def _load(self):
        self._raw_data, _, self._metadata = torchvision.io.read_video(
            str(self._path), pts_unit="sec", output_format=self._layout
        )

    def _extract_batch(self, indices):
        return self._raw_data[indices]

    def _get_internal_layout(self):
        return self._layout

    def _compute_fps(self):
        return float(self._metadata.get("video_fps", 0.0))

    def _count_frames(self):
        return len(self._raw_data)


