    def _compute_fps(self):
        return float(self._metadata.get("video_fps", 0.0))

    def _count_frames(self):
        return len(self._raw_data)


# --- Registry Simulation (simplified) ---
class SimpleRegistry:
    _registry = {}

    @classmethod
    def register(cls, cls_to_register):
        name = cls_to_register.__name__.lower().replace('backend', '').replace('video', '')
        cls._registry[name] = cls_to_register
        return cls_to_register

    @classmethod
    def get_class(cls, name):
        if name not in cls._registry:
            raise KeyError(f"Unknown backend: {name}")
        return cls._registry[name]


# Apply registration manually
for backend_cls in [DecordBackend, TorchvisionBackend, AvBackend]:
    SimpleRegistry.register(backend_cls)


# --- Factory Class ---
class VideoReader:
    def __init__(self, backend_name: Optional[str] = None):
        self._backend_cls = SimpleRegistry.get_class(backend_name) if backend_name else None

    def __call__(
        self,
        video_path: Union[str, Path],
        layout: VideoLayoutType = "TCHW",
        array_type: VideoArrayType = "torch"
    ) -> BaseVideoBackend:
        if self._backend_cls is None:
            raise ValueError("No backend specified during VideoReader construction.")
        return self._backend_cls(str(video_path), layout=layout, array_type=array_type)


