def read_video_av(
    filename: str,
    start_pts: Union[float, Fraction] = 0,
    end_pts: Optional[Union[float, Fraction]] = None,
    pts_unit: str = "pts",
    output_format: str = "THWC",
) -> Tuple[torch.Tensor, torch.Tensor, Dict[str, Any]]:
    """
    Reads video/audio using pyav backend with improved modularity and safety.
    """
    output_format = output_format.upper()
    if output_format not in ("THWC", "TCHW"):
        raise ValueError(f"output_format must be 'THWC' or 'TCHW', got '{output_format}'")

    if not os.path.exists(filename):
        raise FileNotFoundError(f"File not found: {filename}")

    if get_video_backend() != "pyav":
        vframes, aframes, info = _video_opt._read_video(filename, start_pts, end_pts, pts_unit)
        return vframes, aframes, info

    _check_av_available()

    if end_pts is None:
        end_pts = float("inf")
    if end_pts < start_pts:
        raise ValueError(f"end_pts ({end_pts}) < start_pts ({start_pts})")

    info: Dict[str, Any] = {}
    video_frames = []
    audio_frames = []
    audio_timebase = Fraction(1, 1000000)  # default timebase

    container = av.open(filename, metadata_errors="ignore")
    try:
        if container.streams.audio:
            audio_timebase = container.streams.audio[0].time_base
        if container.streams.video:
            video_frames = _read_from_stream(
                container,
                start_pts,
                end_pts,
                pts_unit,
                container.streams.video[0],
                {"video": 0}
            )
            avg_rate = container.streams.video[0].average_rate
            if avg_rate:
                info["video_fps"] = float(avg_rate)

        if container.streams.audio:
            audio_frames = _read_from_stream(
                container,
                start_pts,
                end_pts,
                pts_unit,
                container.streams.audio[0],
                {"audio": 0}
            )
            info["audio_fps"] = container.streams.audio[0].rate
    except av.AVError as e:
        raise e
    finally:
        container.close()
        del container
        gc.collect()

    # Process video frames
    if video_frames:
        arr_list = [frame.to_rgb().to_ndarray() for frame in video_frames]
        vframes = torch.from_numpy(np.stack(arr_list))
    else:
        vframes = torch.empty((0, 1, 1, 3), dtype=torch.uint8)

    # Process audio frames
    if audio_frames:
        audio_arrays = [frame.to_ndarray() for frame in audio_frames]
        aframes = np.concatenate(audio_arrays, axis=1) if audio_arrays else np.empty((1, 0))
        aframes = torch.from_numpy(aframes)
        if pts_unit == "sec":
            scale = 1 / audio_timebase
            start_pts = int(math.floor(start_pts * scale))
            if end_pts != float("inf"):
                end_pts = int(math.ceil(end_pts * scale))
        aframes = _align_audio_frames(aframes, audio_frames, start_pts, end_pts)
    else:
        aframes = torch.empty((1, 0), dtype=torch.float32)

    # Final layout adjustment
    if output_format == "TCHW":
        vframes = vframes.permute(0, 3, 1, 2)

    return vframes, aframes, info

