def get_selected_cuda_devices(test_mode=None):
    """Get CUDA devices based on testing mode"""
    if test_mode is None:
        test_mode = DEFAULT_TEST_MODE

    # Handle basic mode
    if test_mode == "basic":
        return [wp.get_device("cuda:0")] if wp.is_cuda_available() else []

    # Get all CUDA devices and select first of each architecture
    cuda_devices = wp.get_cuda_devices()
    selected_by_arch = {}
    for device in cuda_devices:
        if device.arch not in selected_by_arch:
            selected_by_arch[device.arch] = device

    result = list(selected_by_arch.values())

    # For unique_or_2x mode, add one more device if possible
    if test_mode == "unique_or_2x" and len(result) == 1 and len(cuda_devices) > 1:
        for device in cuda_devices:
            if device not in result:
                result.append(device)
                break

    return result

def get_test_devices(mode=None):
    """Get appropriate devices for testing based on mode"""
    if mode is None:
        mode = DEFAULT_TEST_MODE

    devices = []

    # Basic mode: CPU + first GPU
    if mode == "basic":
        if wp.is_cpu_available():
            devices.append(wp.get_device("cpu"))
        if wp.is_cuda_available():
            devices.append(wp.get_device("cuda:0"))
    # Unique modes: CPU + selected GPUs
    elif mode in ("unique", "unique_or_2x"):
        if wp.is_cpu_available():
            devices.append(wp.get_device("cpu"))
        devices.extend(get_selected_cuda_devices(mode))
    # All devices
    elif mode == "all":
        devices = wp.get_devices()
    else:
        raise ValueError(f"Unknown test mode: {mode}")

    return devices

def get_cuda_devices(mode=None):
    """Filter to get only CUDA devices"""
    all_devices = get_test_devices(mode)
    return [d for d in all_devices if d.is_cuda]

class StreamCapture:
    """Base class for capturing stdout/stderr streams"""
    def __init__(self, stream_name):
        self.stream_name = stream_name
        self.original_stream = None
        self.file_descriptor = None
        self.temp_file = None

    def start_capture(self):
        # Flush libc buffers
        if LIBC is not None:
            LIBC.fflush(None)

        # Save original stream and duplicate file descriptor
        self.original_stream = getattr(sys, self.stream_name)
        self.file_descriptor = os.dup(self.original_stream.fileno())

        # Create temporary file for capture
        temp_buffer = tempfile.TemporaryFile(buffering=0)
        self.temp_file = io.TextIOWrapper(
            temp_buffer,
            encoding="utf-8",
            errors="replace",
            newline="",
            write_through=True
        )

        # Redirect stream
        os.dup2(self.temp_file.fileno(), self.original_stream.fileno())
        setattr(sys, self.stream_name, self.temp_file)

    def stop_capture(self):
        # Flush libc buffers
        if LIBC is not None:
            LIBC.fflush(None)

        # Restore original stream
        os.dup2(self.file_descriptor, self.original_stream.fileno())
        os.close(self.file_descriptor)

        # Read captured content
        self.temp_file.seek(0)
        raw_output = self.temp_file.buffer.read()
        self.temp_file.close()

        # Restore original stream object
        setattr(sys, self.stream_name, self.original_stream)

        return raw_output.decode("utf-8")

class StdErrCapture(StreamCapture):
    def __init__(self):
        super().__init__("stderr")

class StdOutCapture(StreamCapture):
    def __init__(self):
        super().__init__("stdout")

class OutputValidator:
    """Context manager to validate test output"""
    def __init__(self, test_case):
        self.test = test_case
        self.capture_manager = None

    def __enter__(self):
        self.capture_manager = StdOutCapture()
        self.capture_manager.start_capture()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        wp.synchronize()
        raw_output = self.capture_manager.stop_capture()

        if raw_output:
            clean_output = raw_output.rstrip()
            print(clean_output)

            # Filter out expected module loading messages
            filtered_lines = [
                line for line in clean_output.splitlines()
                if not (line.startswith("Module") and "load on device" in line)
            ]

            if any(line.strip() for line in filtered_lines):
                self.test.fail(f"Unexpected output:\n'{clean_output}'")

def compare_arrays(result_array, expected_array):
    """Compare two Warp arrays for equality"""
    np.testing.assert_equal(result_array.numpy(), expected_array.numpy())

def compare_numpy_arrays(result_array, expected_array, tolerance=0.0):
    """Compare NumPy arrays with optional tolerance"""
    if tolerance != 0.0:
        np.testing.assert_allclose(
            result_array.flatten(), 
            expected_array.flatten(), 
            atol=tolerance, 
            equal_nan=True
        )
    else:
        np.testing.assert_array_equal(result_array, expected_array)

def check_majority(arr, min_ratio=0.8):
    """Check if most elements in array meet criteria (> 0)"""
    if len(arr) == 0:
        return True
    return (np.sum(arr > 0) / len(arr)) >= min_ratio

def find_nan_fields(obj):
    """Find Warp array fields containing NaN values"""
    nan_fields = []
    if obj is None:
        return nan_fields

    for field_name, attr in obj.__dict__.items():
        if isinstance(attr, wp.array):
            arr_data = attr.numpy()
            # Skip structured arrays
            if hasattr(arr_data.dtype, 'names') and arr_data.dtype.names is not None:
                continue
            if np.isnan(arr_data).any():
                nan_fields.append(field_name)

    return nan_fields

def find_nonfinite_fields(obj):
    """Find Warp array fields containing non-finite values"""
    nonfinite_fields = []
    if obj is None:
        return nonfinite_fields

    for field_name, attr in obj.__dict__.items():
        if isinstance(attr, wp.array):
            arr_data = attr.numpy()
            # Skip structured arrays
            if hasattr(arr_data.dtype, 'names') and arr_data.dtype.names is not None:
                continue
            if not np.isfinite(arr_data).all():
                nonfinite_fields.append(field_name)

    return nonfinite_fields

def create_test_function(func, device, validate_output, **kwargs):
    """Create a test function wrapper"""
    def test_runner(test_instance):
        if validate_output:
            with OutputValidator(test_instance):
                func(test_instance, device, **kwargs)
        else:
            func(test_instance, device, **kwargs)

    # Preserve unittest attributes
    if hasattr(func, "__unittest_expecting_failure__"):
        test_runner.__unittest_expecting_failure__ = func.__unittest_expecting_failure__

    return test_runner

def skip_test_case(self):
    """Skip test when no suitable devices are available"""
    self.skipTest("No suitable devices to run the test.")

def sanitize_test_name(name):
    """Convert string to valid identifier by replacing non-identifier chars"""
    name_str = str(name)
    if name_str.isidentifier():
        return name_str
    return re.sub(r"\W|^(?=\d)", "_", name_str)

def register_function_test(cls, test_name, func, devices=None, validate_output=True, **kwargs):
    """Register function tests for specified devices"""
    if devices is None:
        setattr(cls, test_name, create_test_function(func, None, validate_output, **kwargs))
    elif isinstance(devices, list):
        if not devices:
            setattr(cls, test_name, skip_test_case)
        else:
            for device in devices:
                setattr(
                    cls,
                    f"{test_name}_{sanitize_test_name(device)}",
                    create_test_function(func, device, validate_output, **kwargs)
                )
    else:
        setattr(
            cls,
            f"{test_name}_{sanitize_test_name(devices)}",
            create_test_function(func, devices, validate_output, **kwargs)
        )

def register_kernel_test(cls, kernel, dimensions, test_name=None, expected=None, inputs=None, devices=None):
    """Register kernel tests"""
    def run_kernel_test(test_instance, device):
        args = []
        if inputs:
            args.extend(inputs)
        if expected:
            # Prepare output array
            result = wp.array(expected, dtype=int, device=device)
            output = wp.zeros_like(result)
            args.append(output)

        # Force load kernel
        kernel.module.load(device)

        with OutputValidator(test_instance):
            wp.launch(kernel, dim=dimensions, inputs=args, device=device)

        # Verify results
        if expected:
            compare_arrays(output, result)

    # Set default name
    if test_name is None:
        test_name = kernel.key

    # Get devices if not specified
    if devices is None:
        devices = get_test_devices()

    # Register for each device
    for device in devices:
        def test_wrapper(test_instance, dev=device):
            run_kernel_test(test_instance, dev)
        setattr(cls, f"{test_name}_{sanitize_test_name(device)}", test_wrapper)

def register_function_test_with_kernel_registration(cls, test_name, func, devices=None, **kwargs):
    """Register function tests that require kernel registration"""
    func(None, None, **kwargs, register_kernels=True)
    register_function_test(cls, test_name, func, devices=devices, **kwargs)

def generate_junit_report(output_file, test_results, total_tests, failed_tests, error_tests, skipped_tests, duration):
    """Generate JUnit XML report"""
    root = ET.Element(
        "testsuite",
        name="Warp Tests",
        failures=str(failed_tests),
        errors=str(error_tests),
        skipped=str(skipped_tests),
        tests=str(total_tests),
        time=f"{duration:.3f}"
    )

    for test_data in test_results:
        class_name, method_name, test_duration, status, message, details = test_data

        test_case = ET.SubElement(
            root, "testcase",
            classname=class_name,
            name=method_name,
            time=f"{test_duration:.3f}"
        )

        if status == "FAIL":
            failure_elem = ET.SubElement(test_case, "failure", message=str(message))
            failure_elem.text = str(details)
        elif status == "ERROR":
            error_elem = ET.SubElement(test_case, "error")
            error_elem.text = str(details)
        elif status == "SKIP":
            skip_elem = ET.SubElement(test_case, "skipped")
            skip_elem.set("message", str(message))

    tree = ET.ElementTree(root)
    if hasattr(ET, "indent"):
        ET.indent(root)
    tree.write(output_file, encoding="utf-8", xml_declaration=True)

class ParallelJunitResult(unittest.TextTestResult):
    """JUnit-compatible test result handler for parallel execution"""
    def __init__(self, stream, descriptions, verbosity):
        stream = type(stream)(sys.stderr)
        self.test_records = []
        super().__init__(stream, descriptions, verbosity)

    def startTest(self, test):
        if self.showAll:
            self.stream.writeln(f"{self.getDescription(test)} ...")
            self.stream.flush()
        elif self.dots:
            self.stream.writeln(f"{test} ...")
            self.stream.flush()

        self.start_time = time.perf_counter_ns()
        super(unittest.TextTestResult, self).startTest(test)

    def _report_test_result(self, test, message):
        if self.showAll:
            self.stream.writeln(f"{self.getDescription(test)} ... {message}")
        elif self.dots:
            self.stream.writeln(f"{test} ... {message}")
        self.stream.flush()

    def _record_test_result(self, test, status_code, message=None, details=None):
        start = getattr(self, "start_time", None)
        duration = round((time.perf_counter_ns() - start) * 1e-9, 3) if start is not None else 0.0

        class_name = test.__class__.__name__
        method_name = getattr(test, "_testMethodName", str(test))
        self.test_records.append((class_name, method_name, duration, status_code, message, details))

    def addSuccess(self, test):
        super(unittest.TextTestResult, self).addSuccess(test)
        self._report_test_result(test, "ok")
        self._record_test_result(test, "OK")

    def addError(self, test, error):
        super(unittest.TextTestResult, self).addError(test, error)
        self._report_test_result(test, "ERROR")
        self._record_test_result(test, "ERROR", str(error[1]), self._exc_info_to_string(error, test))

    def addFailure(self, test, error):
        super(unittest.TextTestResult, self).addFailure(test, error)
        self._report_test_result(test, "FAIL")
        self._record_test_result(test, "FAIL", str(error[1]), self._exc_info_to_string(error, test))

    def addSkip(self, test, reason):
        super(unittest.TextTestResult, self).addSkip(test, reason)
        self._report_test_result(test, f"skipped {reason!r}")
        self._record_test_result(test, "SKIP", reason)

    def addExpectedFailure(self, test, error):
        super(unittest.TextTestResult, self).addExpectedFailure(test, error)
        self._report_test_result(test, "expected failure")
        self._record_test_result(test, "OK", "expected failure")

    def addUnexpectedSuccess(self, test):
        super(unittest.TextTestResult, self).addUnexpectedSuccess(test)
        self._report_test_result(test, "unexpected success")
        self._record_test_result(test, "FAIL", "unexpected success")

    def addSubTest(self, test, subtest, error):
        super(unittest.TextTestResult, self).addSubTest(test, subtest, error)
        if error is not None:
            self._report_test_result(test, "ERROR")
            self._record_test_result(test, "FAIL", str(error[1]), self._exc_info_to_string(error, test))

    def printErrors(self):
        pass

