import pytest
import torch
from noether.data.pipeline.sample_processors import MomentNormalizationSampleProcessor
from noether.modeling.functional.logscale import to_logscale

@pytest.fixture
def normalized_precollator():
    # Renamed fixture and adjusted initialization parameters
    return MomentNormalizationSampleProcessor(
        item="pressure", 
        mean=torch.tensor([2.0, 3.0]), 
        std=torch.tensor([1.0, 2.0])
    )

def test_batch_normalization_behavior(normalized_precollator):
    # Test normalization using alternative variable names and structure
    input_data = {
        "pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]]),
        "static_field": torch.tensor([[7.0, 8.0], [9.0, 10.0]]),
    }

    result = normalized_precollator(input_data)

    # Verify pressure normalization matches expected z-score calculation
    expected_normalized = (input_data["pressure"] - normalized_precollator.mean) / normalized_precollator.std
    assert torch.allclose(result["pressure"], expected_normalized)

    # Confirm non-target fields remain untouched
    assert torch.equal(result["static_field"], input_data["static_field"])

def test_missing_key_handling(normalized_precollator):
    # Test KeyError when required key is absent
    incomplete_sample = {"static_field": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}

    with pytest.raises(KeyError):
        normalized_precollator(incomplete_sample)

def test_inverse_normalization_roundtrip(normalized_precollator):
    # Test full normalization -> denormalization cycle
    original = {
        "pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]]),
        "static_field": torch.tensor([[7.0, 8.0], [9.0, 10.0]]),
    }

    # Apply forward normalization
    normalized = normalized_precollator(original)

    # Apply inverse transformation
    recovered = {}
    for field_name, tensor in normalized.items():
        _, restored_tensor = normalized_precollator.inverse(key=field_name, value=tensor)
        recovered[field_name] = restored_tensor

    # Validate recovery of original values
    assert torch.equal(recovered["pressure"], original["pressure"])
    assert torch.equal(recovered["static_field"], original["static_field"])

def test_logscale_transform():
    # Create processor configured for log-space operations
    log_processor = MomentNormalizationSampleProcessor(
        item="pressure",
        logmean=torch.tensor([0.0, 0.0]),
        logstd=torch.tensor([1.0, 1.0]),
        logscale=True,
    )

    sample_input = {"pressure": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}

    # Verify log-scale normalization uses correct transformation
    log_normalized = log_processor(sample_input)
    assert torch.equal(log_normalized["pressure"], to_logscale(sample_input["pressure"]))

    # Test inverse operation on log-scaled data
    recovered = {}
    for field_name, tensor in log_normalized.items():
        _, restored = log_processor.inverse(key=field_name, value=tensor)
        recovered[field_name] = restored

    # Check numerical accuracy in reconstruction
    assert torch.allclose(recovered["pressure"], sample_input["pressure"], atol=1e-6)

def test_inverse_noop_for_unaffected_fields(normalized_precollator):
    # Verify inverse transform leaves non-normalized fields unchanged
    original_untouched = {"static_field": torch.tensor([[3.0, 4.0], [5.0, 6.0]])}

    # Apply inverse directly without prior normalization
    recovered = {}
    for field_name, tensor in original_untouched.items():
        _, restored = normalized_precollator.inverse(key=field_name, value=tensor)
        recovered[field_name] = restored

    # Ensure identity preservation for non-target fields
    assert torch.equal(recovered["static_field"], original_untouched["static_field"])

from typing import Optional
import jax
from flax import nnx
from tpu_inference.layers.jax import JaxModule
from tpu_inference.layers.jax.quantization import QuantizeMethodBase
from tpu_inference.layers.jax.quantization.configs import QuantizationConfig


class JaxTokenEmbedding(JaxModule):
    """Token embedding module for JAX-based models, compatible with HuggingFace naming conventions."""

    def __init__(self,
                 *args,
                 quant_config: Optional[QuantizationConfig] = None,
                 prefix: str = "",
                 **kwargs):
        # Initialize base embedding layer
        super().__init__()
        self._base_embed = nnx.Embed(*args, **kwargs)

        # Expose 'weight' as alias to match HF parameter naming expectations
        self.weight = self._base_embed.embedding
        # Remove original attribute to avoid duplication/conflict
        delattr(self._base_embed, 'embedding')

        # Set sharding metadata if available
        if hasattr(self.weight, "out_sharding"):
            self.weight.set_metadata('sharding', self.weight.out_sharding)

        # Handle quantization setup
        self._quantizer = None
        if quant_config is not None:
            q_method = quant_config.instantiate_quant_method(self, prefix=prefix)
            if q_method is not None:
                self._quantizer = q_method
                assert isinstance(q_method, QuantizeMethodBase), \
                    "Quantization method must inherit from QuantizeMethodBase"
                q_method.setup_weights_jax(self)

    def __getattr__(self, name: str):
        # Allow access to .embedding via .weight for backward compatibility
        if name == "embedding":
            return self.weight
        return super().__getattr__(name)

    def __call__(self, input_ids: jax.Array) -> jax.Array:
        if self._quantizer is None:
            return self._base_embed(input_ids)
        return self._quantizer.forward_jax(self, input_ids)

    def project_back(self, hidden_states: jax.Array) -> jax.Array:
        """Apply transposed weight matrix for decoding (i.e., unembedding)."""
        return jax.numpy.dot(hidden_states, self.weight.value.T)

