# Constants with alternative naming
MEMORY_UNIT = 1073741824  # 1024^3
ALIGNMENT_FACTOR = 128
MINOR_DIMENSION_BLOCK = 8

# Mapping for data type aliases - renamed dictionary and keys
JAX_DTYPE_ALIASES = {
    "fp8": jnp.float8_e4m3fn.dtype,
    "fp8_e4m3": jnp.float8_e4m3fn.dtype,
    "fp8_e5m2": jnp.float8_e5m2.dtype,
    "fp4": jnp.float4_e2m1fn.dtype,
}

def convert_to_jax_type(input_type):
    """Convert various type representations to JAX dtype."""
    if isinstance(input_type, (str, type)):
        if isinstance(input_type, str) and (mapped_dtype := JAX_DTYPE_ALIASES.get(input_type)):
            return mapped_dtype
        return jnp.dtype(input_type)
    elif isinstance(input_type, torch.dtype):
        return t2j_dtype(input_type)
    elif isinstance(input_type, jnp.dtype):
        return input_type
    elif isinstance(input_type, _ScalarMeta):
        return input_type.dtype
    else:
        raise ValueError(f"Unsupported data type: {type(input_type)}")

def convert_to_torch_type(input_type):
    """Convert any supported type to PyTorch dtype via JAX intermediate."""
    jax_type = convert_to_jax_type(input_type)
    return j2t_dtype(jax_type)

# Global state for megacore feature
_megacore_enabled = False
logger = init_logger(__name__)

def round_up(value, multiple):
    """Round up value to nearest multiple."""
    return ((value + multiple - 1) // multiple) * multiple

def activate_megacore():
    """Enable megacore processing mode."""
    global _megacore_enabled
    _megacore_enabled = True

def is_megacore_active():
    """Check if megacore processing is enabled."""
    return _megacore_enabled

def calculate_kv_heads(total_kv: int, tensor_parallel: int) -> int:
    """Determine number of KV heads after tensor parallelization."""
    if tensor_parallel <= total_kv:
        assert total_kv % tensor_parallel == 0
        return total_kv
    else:
        assert tensor_parallel % total_kv == 0
        return tensor_parallel

def get_memory_consumption(devices):
    """Measure HBM memory usage across devices."""
    results = []
    if vllm_envs.VLLM_TPU_USING_PATHWAYS:
        return pathways_memory_stats(devices)

    multihost_backend = envs.TPU_MULTIHOST_BACKEND
    if multihost_backend == "ray":
        # For Ray backend, assume uniform memory distribution
        for dev in devices:
            try:
                stats = dev.memory_stats()
                used = stats["bytes_in_use"]
                limit = stats["bytes_limit"]
                logger.info(
                    "Acquired memory stats from device %s. Assuming uniform usage.",
                    dev)
                results.extend([(used, limit)] * len(devices))
                break
            except Exception as err:
                logger.warning(
                    "Failed to retrieve memory stats for device %s: %s", dev,
                    err)
    else:
        for dev in devices:
            stats = dev.memory_stats()
            used = stats["bytes_in_use"]
            limit = stats["bytes_limit"]
            results.append((used, limit))
    return results

def identify_device_type(device_count=None):
    """Identify TPU device type and version."""
    device_kind = jax.devices()[0].device_kind
    if 'TPU' not in device_kind:
        raise RuntimeError('Expected TPU devices')

    suffix = ''
    if device_kind.endswith(' lite'):
        device_kind = device_kind[:-5]
        suffix = 'e'
    elif device_kind.endswith('e'):
        device_kind = device_kind[:-1]
        suffix = 'e'
    elif device_kind.endswith('p'):
        device_kind = device_kind[:-1]
        suffix = 'p'
    elif device_kind == 'TPU7x':
        device_kind = 'TPU v7'

    assert device_kind[:-1] == 'TPU v', device_kind
    device_kind += suffix

    if device_count is not None:
        device_kind += f'-{device_count}'
    return device_kind

def get_hbm_capacity():
    """Get HBM capacity based on device type."""
    device_type = identify_device_type()
    capacities = {
        ("TPU v5p", "TPU v5"): 95 * MEMORY_UNIT,
        "TPU v5e": 16 * MEMORY_UNIT,
        ("TPU v6e", "TPU v4"): 32 * MEMORY_UNIT,
        "TPU v7": 96 * MEMORY_UNIT,  # Half of 192GB per chip
    }

    for key, value in capacities.items():
        if isinstance(key, tuple):
            if device_type in key:
                return value
        elif device_type == key:
            return value

    raise ValueError(f"Unknown device kind: {device_type}")

def pathways_memory_stats(devices):
    """Calculate memory usage using Pathways live arrays."""
    live_arrays = jax.live_arrays()
    memory_usage = defaultdict(int)
    hbm_limit = get_hbm_capacity()
    seen_buffers = set()

    for array in live_arrays:
        for shard in array.addressable_shards:
            buffer_id = id(shard.data)
            if buffer_id not in seen_buffers:
                seen_buffers.add(buffer_id)
                memory_usage[shard.data.device] += shard.data.nbytes

    return [(memory_usage[dev], hbm_limit) for dev in devices]

def memory_usage_gb(devices):
    """Report memory usage in gigabytes."""
    raw_stats = get_memory_consumption(devices)
    return [(round(used / MEMORY_UNIT, 2), round(limit / MEMORY_UNIT, 2)) 
            for used, limit in raw_stats]

def align_head_dimension(head_size):
    """Align head dimension to optimal size for kernel performance."""
    if head_size == 64:
        return 64  # Special case for optimized kernel
    return round_up(head_size, ALIGNMENT_FACTOR)

def align_num_heads(num_heads, sharding_factor):
    """Adjust number of heads for sharding requirements."""
    if num_heads >= sharding_factor:
        assert num_heads % sharding_factor == 0
    else:
        assert sharding_factor % num_heads == 0
        num_heads = sharding_factor
    return num_heads

def compute_packing_factor(dtype):
    """Calculate data packing factor based on bit width."""
    bits = dtypes.itemsize_bits(dtype)
    return 32 // bits

def construct_optimized_mesh(dimension_sizes, axis_labels, devices=None):
    """Build an optimized device mesh configuration."""
    if devices is None:
        devices = xb.devices()

    # Sort devices by coordinates for consistent ordering
    devices = sorted(devices, key=lambda d: d.coords)

    def is_single_axis(dimensions):
        return sum(1 for d in dimensions if d > 1) == 1

    if is_single_axis(dimension_sizes):
        device_type = devices[0].device_kind
        device_count = len(devices)

        if device_type == "TPU v6 lite":
            ordered_devices = None

            # Handle specific device arrangements for v6e
            if device_count == 8:
                ordered_devices = [
                    devices[0], devices[1], devices[2], devices[3],
                    devices[7], devices[6], devices[5], devices[4]
                ]
            elif device_count == 4:
                ordered_devices = [
                    devices[0], devices[1], devices[3], devices[2]
                ]

            if ordered_devices is not None:
                ordered_devices = np.array(ordered_devices).reshape(dimension_sizes)
                mesh = mesh_lib.Mesh(ordered_devices, axis_labels)
                logger.info("Using custom mesh layout: %s", mesh)
                return mesh

    # Fallback to standard mesh creation
    try:
        return jax.make_mesh(dimension_sizes, axis_labels, devices=devices)
    except (AssertionError, ValueError, RuntimeError) as e:
        logger.warning(
            "Standard mesh creation failed (%s). Using manual arrangement.", e)
        ordered_devices = np.array(devices).reshape(dimension_sizes)
        return mesh_lib.Mesh(ordered_devices, axis_labels)

def create_device_tensor(mesh, *args, sharding=None, **kwargs):
    """Create a JAX array placed on specified devices with given sharding."""
    if sharding is None:
        sharding = NamedSharding(mesh, PartitionSpec(None))
    return jax.device_put(*args, device=sharding, **kwargs)

def resolve_hash_function(name):
    """Select appropriate hash function by name."""
    if name == "builtin":
        return hash
    return utils.hashing.get_hash_fn_by_name(name)

def extract_jax_type_from_string(type_string):
    """Extract JAX dtype from string representation."""
    return convert_to_jax_type(type_string)

def compute_mesh_product(mesh, axes):
    """Compute product of mesh dimensions for specified axes."""
    if axes is None:
        return 1
    if isinstance(axes, str):
        axes = [axes]

    result = 1
    for axis in axes:
        result *= mesh.shape.get(axis, 1)
    return result

def measure_execution_time(func):
    """Decorator to time function execution."""
    @wraps(func)
    def timed_wrapper(*args, **kwargs):
        start = time.perf_counter()
        outcome = func(*args, **kwargs)
        duration = time.perf_counter() - start
        logger.debug(
            f"Function '{func.__name__}' completed in {duration:.4f} seconds."
        )
        return outcome
    return timed_wrapper

