import os
from vllm.utils.argparse_utils import FlexibleArgumentParser
from vllm.engine.arg_utils import AsyncEngineArgs
from lm_eval import tasks, evaluator
from lm_eval.models.vllm_vlms import VLLM_VLM

os.environ["VLLM_SKIP_WARMUP"] = "true"
MAX_IMAGES_LIMIT = 1


def build_base_config(model_path: str, tensor_parallel_size: int):
    return {
        "model_name": model_path,
        "lm_eval_kwargs": {
            "batch_size": "auto"
        },
        "vllm_kwargs": {
            "pretrained": model_path,
            "max_num_seqs": 128,
            "max_model_len": 2048,
            "dtype": "bfloat16",
            "data_parallel_size": 1,
            "tensor_parallel_size": tensor_parallel_size,
            "disable_log_stats": False,
        },
    }


def build_fp8_config(base_cfg, quantization: str, kv_cache_dtype: str):
    vllm_args = base_cfg["vllm_kwargs"].copy()
    vllm_args.update({
        "quantization": quantization,
        "kv_cache_dtype": kv_cache_dtype,
    })
    return {
        **base_cfg,
        "vllm_kwargs": vllm_args,
    }


def build_vision_fp8_config(fp8_cfg):
    vision_cfg = fp8_cfg.copy()
    lm_kwargs = vision_cfg["lm_eval_kwargs"].copy()
    lm_kwargs.update({
        "max_images": MAX_IMAGES_LIMIT,
    })
    vllm_kwargs = vision_cfg["vllm_kwargs"].copy()
    vllm_kwargs.update({
        "max_num_seqs": 32,
        "disable_log_stats": True,
    })
    vision_cfg["lm_eval_kwargs"] = lm_kwargs
    vision_cfg["vllm_kwargs"] = vllm_kwargs
    return vision_cfg


def instantiate_vlm(vision_cfg, enforce_eager: bool, expert_parallel: bool, max_model_len: int):
    vllm_args = vision_cfg["vllm_kwargs"].copy()
    vllm_args.update({
        "pretrained": vision_cfg["model_name"],
        "enforce_eager": enforce_eager,
        "max_model_len": max_model_len,
        "enable_expert_parallel": expert_parallel,
    })
    lm_eval_args = vision_cfg["lm_eval_kwargs"].copy()
    lm_eval_args.update({
        "batch_size": 8,
    })
    return VLLM_VLM(**vllm_args, **lm_eval_args)


def run_evaluation(args):
    # Build configs step-by-step
    base_cfg = build_base_config(
        model_path=args.model_path,
        tensor_parallel_size=args.tensor_parallel_size
    )
    fp8_cfg = build_fp8_config(
        base_cfg,
        quantization=args.quantization,
        kv_cache_dtype=args.kv_cache_dtype
    )
    vision_cfg = build_vision_fp8_config(fp8_cfg)

    # Instantiate model with final overrides
    vlm_model = instantiate_vlm(
        vision_cfg,
        enforce_eager=args.enforce_eager,
        expert_parallel=args.expert_parallel,
        max_model_len=args.max_model_len
    )

    # Setup evaluation
    task_name = "mmmu_val"
    task_manager = tasks.TaskManager(include_path="./meta-configs")
    task_dict = tasks.get_task_dict(task_name, task_manager)

    eval_params = {
        "limit": 1,
        "fewshot_as_multiturn": True,
        "apply_chat_template": True,
    }

    results = evaluator.evaluate(lm=vlm_model, task_dict=task_dict, **eval_params)
    return results


def main(args):
    run_evaluation(args)


if __name__ == "__main__":
    parser = FlexibleArgumentParser(
        description='Demo on using vLLM for offline inference with '
                    'vision language models that support multi-image input for text '
                    'generation'
    )
    parser.add_argument('--model-path', '-p', type=str, default="", help='Huggingface model path')
    parser.add_argument('--expert-parallel', action='store_true', help='Whether to use expert parallel')
    parser = AsyncEngineArgs.add_cli_args(parser)
    args = parser.parse_args()
    main(args)

# Type III Clone: Refactored agent structure analyzer with equivalent functionality

import json
import os
import sys
from collections import Counter

def inspect_agent_directory(agent_path):
    """Inspect and gather structural information from an agent directory."""
    analysis = {
        "path_list": [],
        "module_imports": {},
        "class_list": [],
        "function_list": []
    }

    for dirpath, _, filenames in os.walk(agent_path):
        for filename in filenames:
            if filename.endswith(".py"):
                full_path = os.path.join(dirpath, filename)
                relative_path = os.path.relpath(full_path, agent_path)

                # Record file path
                analysis["path_list"].append(relative_path)

                # Process file contents
                try:
                    with open(full_path, encoding="utf-8") as file_obj:
                        lines = file_obj.read().splitlines()

                        # Track imports per file
                        file_imports = []
                        for line in lines:
                            stripped = line.strip()
                            if stripped.startswith(("import ", "from ")):
                                parts = stripped.split()
                                if len(parts) > 1:
                                    file_imports.append(stripped)
                        if file_imports:
                            analysis["module_imports"][relative_path] = file_imports

                        # Detect top-level classes
                        for line in lines:
                            stripped = line.strip()
                            if stripped.startswith("class "):
                                class_part = stripped.replace("class ", "").split("(")[0].strip()
                                analysis["class_list"].append(f"{relative_path}: {class_part}")

                        # Detect top-level functions (not indented)
                        for line in lines:
                            stripped = line.strip()
                            if stripped.startswith("def ") and not line.startswith("    def"):
                                func_part = stripped.replace("def ", "").split("(")[0].strip()
                                analysis["function_list"].append(f"{relative_path}: {func_part}")
                except Exception:
                    continue

    return analysis

def process_all_agents(root_directory):
    """Process all directories that appear to be agent implementations."""
    agent_data = {}

    for entry in os.listdir(root_directory):
        full_entry_path = os.path.join(root_directory, entry)
        if os.path.isdir(full_entry_path):
            # Check for typical agent files
            required_files = ["agent.py", "config.py", "state.py"]
            has_required = any(
                os.path.isfile(os.path.join(full_entry_path, marker))
                for marker in required_files
            )

            if has_required:
                agent_data[entry] = inspect_agent_directory(full_entry_path)

    return agent_data

def identify_shared_structure(analysis_results):
    """Identify common elements across different agents."""
    shared_paths = set()
    first_iteration = True

    for _, data in analysis_results.items():
        current_paths = set(data["path_list"])

        if first_iteration:
            shared_paths = current_paths
            first_iteration = False
        else:
            shared_paths &= current_paths

    return {
        "shared_paths": sorted(shared_paths),
        "path_occurrence_counts": count_path_occurrences(analysis_results)
    }

def count_path_occurrences(analysis_results):
    """Count how frequently each file appears across agents."""
    counter = Counter()
    for _, data in analysis_results.items():
        counter.update(data["path_list"])

    # Return sorted by frequency descending
    return dict(counter.most_common())

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(1)

    base_dir = sys.argv[1]
    if not os.path.isdir(base_dir):
        sys.exit(1)

    # Analyze agents
    agent_analysis = process_all_agents(base_dir)

    # Find shared patterns
    pattern_info = identify_shared_structure(agent_analysis)

    # Output summary (placeholder logic preserved)
    for path in pattern_info["shared_paths"]:
        pass  # Placeholder for future use

    for path, freq in pattern_info["path_occurrence_counts"][:10]:
        pass  # Placeholder for future use

    # Save detailed results
    with open("agent_inspection.json", "w") as output_file:
        json.dump(agent_analysis, output_file, indent=2)

