EMAIL_DUPLICATE_FIELDS = ['recipients']
SLOW_FILE_THRESHOLD_SEC = 1.0


@dataclass
class EpsteinCollection:
    """
    Holds all parsed documents related to Jeffrey Epstein’s files.

    Attributes:
        paths_to_files (list[Path]): sorted list of paths to text-based documents
        _all_docs (list[Document]): full list including duplicates and split-ups
        timer (Timer): for performance logging
        cc_only_contacts (list[Name]): people only CCed on emails, deemed unimportant
    """
    paths_to_files: list[Path] = field(init=False)
    _all_docs: list[Document] = field(default_factory=list)
    timer: Timer = field(default_factory=lambda: Timer())
    cc_only_contacts: list[Name] = field(default_factory=list)
    _empty_ids: set[str] = field(default_factory=set)
    _senders_and_receivers: list[Person] = field(default_factory=list)

    def __post_init__(self):
        """Initialize by scanning directories and loading documents."""
        self.paths_to_files = sorted(all_txt_paths(), reverse=True)
        self._all_docs = self._scan_and_load(self.paths_to_files)
        self._all_docs += split_up_dilorio(self.emails_from(CHRISTOPHER_DILORIO))
        self._all_docs += split_up_leon_black(self.fetch_doc_by_id(LEON_BLACK_EMAIL_ID))
        self._finalize_and_persist()

    @classmethod
    def from_cache(cls, timer: Timer | None = None) -> 'EpsteinCollection':
        """Load preprocessed data from disk if allowed; otherwise build fresh."""
        timer = timer or Timer()
        if args.pickle_path.exists() and not args.overwrite_pickle:
            with gzip.open(args.pickle_path, 'rb') as f:
                collection = pickle.load(f)
            msg = f"Loaded {len(collection.all_docs):,} docs from '{args.pickle_path}'"
            timer.print_at_checkpoint(f"{msg} ({file_size_str(args.pickle_path)})")
            if args.load_new:
                collection.add_new_files()
            elif args.reload_doj:
                collection.reprocess_doj_files()
            return collection

        logger.warning("Building new cache — this may take a few minutes...")
        collection = cls()
        synthetic_count = sum(1 for c in CONFIGS_BY_ID.values() if c.is_synthetic)
        timer.print_at_checkpoint(f"Processed {len(collection.paths_to_files):,} files, {synthetic_count} synthetic configs")
        return collection

    @property
    def doj_extracted_docs(self) -> Sequence[DojFile | Email]:
        """All DOJ-related files, including those converted to Email objects."""
        return [d for d in self.all_docs if d.file_info.is_doj_file]

    @property
    def all_docs(self) -> Sequence[Document]:
        """All documents excluding those marked as split-up emails."""
        return [d for d in self._all_docs if not (isinstance(d, Email) and d._was_split_up)]

    @property
    def official_doj_docs(self) -> list[DojFile]:
        """Only pure DojFile instances (no derived Emails)."""
        return [f for f in self.non_json_other_docs if isinstance(f, DojFile)]

    @property
    def email_docs(self) -> list[Email]:
        """All Email-type documents."""
        return [d for d in self.all_docs if isinstance(d, Email)]

    @property
    def emails_with_attachments(self) -> list[Email]:
        """Emails that have attached documents."""
        return [e for e in self.email_docs if e.attached_docs]

    @property
    def senders_and_receivers(self) -> list[Person]:
        """People involved in any email (sender or recipient)."""
        return self._senders_and_receivers

    @property
    def counterparty_map(self) -> dict[Name, list[Name]]:
        """Mapping of each person to their email counterparties."""
        return sort_dict_by_keys({p.name: p.counterparties for p in self.senders_and_receivers})

    @property
    def imessage_logs(self) -> list[MessengerLog]:
        """iMessage conversation logs."""
        return [d for d in self.all_docs if isinstance(d, MessengerLog)]

    @property
    def apple_ads_json_files(self) -> list[JsonFile]:
        """JSON files from Apple ads dataset."""
        return [d for d in self.non_json_other_docs if isinstance(d, JsonFile)]

    @property
    def notable_other_files(self) -> Sequence[OtherFile]:
        """Non-JSON files flagged as interesting."""
        return [f for f in self.non_json_other_docs if f.is_interesting]

    @property
    def local_derivatives(self) -> Sequence[Document]:
        """Documents generated locally (e.g., extracted PDFs)."""
        return [d for d in self.all_docs if d.file_info.is_local_extract_file]

    @property
    def deduplicated_docs(self) -> Sequence[Document]:
        """All documents with duplicates removed."""
        return Document.without_dupes(self.all_docs)

    @property
    def non_json_other_docs(self) -> Sequence[OtherFile]:
        """All OtherFile instances excluding JSON files."""
        return [doc for doc in self.all_docs if isinstance(doc, OtherFile)]

    @property
    def unique_email_senders(self) -> list[Name]:
        """People who appear only as CC/BCC and are considered low-priority."""
        if '_low_priority_emailers' not in vars(self):
            self._low_priority_emailers = sorted(uniquify(UNINTERESTING_EMAILERS + self.cc_only_contacts))
        return self._low_priority_emailers

    @property
    def distinct_docs(self) -> Sequence[Document]:
        """Unique documents excluding attachments."""
        return [d for d in self.deduplicated_docs if not d.is_attachment]

    @property
    def distinct_emails(self) -> list[Email]:
        """Unique Email objects (excluding duplicates)."""
        return Document.without_dupes(self.email_docs)

    def find_matching_docs(
        self,
        regex: re.Pattern | str,
        names: list[Name] | None = None
    ) -> list[SearchResult]:
        """Find documents matching `regex`, optionally filtered by author(s)."""
        candidates = [d for d in self._all_docs if (not names) or d.author in names]
        results: list[SearchResult] = []
        for doc in candidates:
            if doc.is_duplicate:
                continue
            matched_lines = doc.lines_matching(regex)
            if args.min_line_length:
                matched_lines = [ln for ln in matched_lines if len(ln.line) > args.min_line_length]
            if matched_lines:
                results.append(SearchResult(doc, matched_lines))
        return results

    def first_email_time(self, name: Name) -> datetime:
        """Earliest timestamp among emails involving `name`."""
        return self.emails_for(name)[0].timestamp

    def latest_email_time(self, name: Name) -> datetime:
        """Latest timestamp among emails involving `name`."""
        return self.emails_for(name)[-1].timestamp

    def email_counts_by_sender(self) -> dict[Name, int]:
        """Count of emails sent per person."""
        return {
            person.name: len(person.unique_emails_by)
            for person in self.senders_and_receivers if person.unique_emails_by
        }

    def device_signatures_per_author(self) -> dict[str, set[str]]:
        """Map authors to their known device signatures."""
        sigs = defaultdict(set)
        for email in [e for e in self.distinct_emails if e.sent_from_device]:
            sigs[email.author_or_unknown].add(email.sent_from_device)
        return dict(sigs)

    def authors_per_signature(self) -> dict[str, set[str]]:
        """Map device signatures back to users."""
        sigs = defaultdict(set)
        for email in [e for e in self.distinct_emails if e.sent_from_device]:
            sigs[email.sent_from_device].add(email.author_or_unknown)
        return dict(sigs)

    def email_counts_by_recipient(self) -> dict[Name, int]:
        """Count of emails received per person."""
        return {p.name: len(p.unique_emails_to) for p in self.senders_and_receivers if p.unique_emails_to}

    def signature_snippet_replacements(self) -> dict[str, int]:
        """Count how often "<...snipped...>" replaced signatures per author."""
        counts = defaultdict(int)
        for email in self.email_docs:
            for name, num in email.signature_substitution_counts.items():
                counts[name] += num
        return dict(counts)

    def emails_from(self, sender: Name) -> list[Email]:
        """All emails authored by `sender`, including duplicates."""
        return Document.sort_by_timestamp([e for e in self.email_docs if e.author == sender])

    def emails_for(self, name: Name) -> list[Email]:
        """All emails involving `name`, sorted chronologically."""
        outgoing = self.emails_from(name)
        incoming = self.emails_to(name)
        special = [e for e in self.email_docs if e.config and name == e.config.show_with_name]
        combined = outgoing + incoming + special
        if not combined:
            logger.warning(f"No emails found for '{name}'")
        return Document.sort_by_timestamp(Document.uniquify(combined))

    def emails_to(self, name: Name) -> list[Email]:
        """All emails addressed to `name`, including duplicates."""
        if name is None:
            return Document.sort_by_timestamp([e for e in self.email_docs if not e.recipients or None in e.recipients])
        return Document.sort_by_timestamp([e for e in self.email_docs if name in e.recipients])

    def fetch_doc_by_id(self, doc_id: str, rebuild: bool = False, expected_type: Type[Document] = Document) -> Document:
        """Get a single document by ID, optionally reloading or type-checking."""
        docs = self.fetch_docs_by_ids([doc_id], rebuild)
        if not docs:
            raise KeyError(f"No document found for ID '{doc_id}'")
        doc = docs[0]
        if expected_type and not isinstance(doc, expected_type):
            raise ValueError(f"Expected {expected_type.__name__}, got {type(doc).__name__}")
        return doc

    def fetch_docs_by_ids(self, ids: list[str], rebuild: bool = False) -> Sequence[Document]:
        """Retrieve multiple documents by IDs."""
        docs = [d for d in self._all_docs if d.file_id in ids]
        if len(docs) != len(ids):
            logger.warning(f"Requested {len(ids)} IDs, found {len(docs)} matches.")
        return [d.reload() if rebuild else d for d in docs]

    def imessage_logs_for(self, name: Name) -> list[MessengerLog]:
        """iMessage logs where `name` was the other participant."""
        return [log for log in self.imessage_logs if log.author == name]

    def generate_metadata_json(self) -> str:
        """Produce JSON string containing metadata for all files and people."""
        metadata = {
            'files': {
                'Email': _metadata_list(self.email_docs),
                'JsonFile': _metadata_list(self.apple_ads_json_files),
                'MessengerLog': _metadata_list(self.imessage_logs),
                'OtherFile': _metadata_list(self.non_json_other_docs),
            },
            'people': {name: bio.plain for name, bio in PEOPLE_BIOS.items()},
        }
        return json.dumps(metadata, indent=4, sort_keys=True)

    def build_person_objects(self, names: list[Name]) -> list[Person]:
        """Construct Person objects for given names."""
        return [
            Person(
                name=name,
                emails=self.emails_for(name),
                imessage_logs=self.imessage_logs_for(name),
                is_low_priority=name in self.unique_email_senders,
                other_files=[
                    f for f in self.non_json_other_docs
                    if name and (name == f.author or (f.config and name == f.config.show_with_name))
                ]
            )
            for name in names
        ]

    def add_new_files(self) -> None:
        """Detect and load newly added files."""
        new_docs = self._scan_and_load(self._find_new_files())
        if not new_docs:
            logger.warning("No new files detected.")
            return
        elif cfgs := create_configs(new_docs):
            console.print(f"\n{len(cfgs)} config objects created, exiting...", style='bold yellow1')
            sys.exit()
        self._finalize_and_persist(new_docs)

    def reprocess_doj_files(self) -> None:
        """Reload only DOJ PDF extracts."""
        def count_summary():
            return f"(have {len(self.doj_extracted_docs)}, {len(self.official_doj_docs)} non-email)"
        timer = Timer()
        logger.warning(f"Reloading DOJ files {count_summary()}...")
        self._finalize_and_persist(self._scan_and_load(doj_txt_paths()))
        timer.print_at_checkpoint(f"Reloaded {len(self.official_doj_docs)} DOJ files {count_summary()}")

    def overview_table(self) -> Table:
        """Generate summary table of file counts by category."""
        title = Text('Files Overview ', TABLE_TITLE_STYLE)
        title.append('(last updated: ', 'dim').append(datetime.now().date().isoformat(), 'cyan').append(')', 'dim')
        table = Document.files_summary_table(title, 'File Type')
        table.add_row('Emails', *Document.file_summary_row(self.email_docs))
        table.add_row('iMessage Logs', *Document.file_summary_row(self.imessage_logs))
        table.add_row('JSON Data', *Document.file_summary_row(self.apple_ads_json_files, True))
        table.add_row('Other', *Document.file_summary_row(self.non_json_other_docs))
        return table

    def repair_documents(self, ids: list[str]) -> None:
        """Reload specified documents and update cache."""
        ids = uniquify(ids)
        if ids == ['EMAIL']:
            doc_paths = [d.file_path for d in self.email_docs]
            msg = f"Repairing all {len(doc_paths)} emails..."
        else:
            doc_paths = [d.file_path for d in self._all_docs if d.file_id in ids]
            msg = f"Repairing {len(ids)} file IDs"
            if len(doc_paths) != len(ids):
                raise RuntimeError(f"Specified {len(ids)} IDs, but only {len(doc_paths)} docs found!")
        if new_paths := self._find_new_files():
            msg += f" (also loading {len(new_paths)} new files)"
            doc_paths += new_paths
        logger.warning(msg)
        self._finalize_new_docs_if_approved(self._scan_and_load(doc_paths))

    def persist_to_disk(self) -> None:
        """Save current state to pickle file."""
        with gzip.open(args.pickle_path, 'wb') as f:
            pickle.dump(self, f)
            logger.warning(f"Saved cache to '{args.pickle_path}' ({file_size_str(args.pickle_path)})")

    def unknown_recipient_ids(self) -> list[str]:
        """IDs of emails with unknown recipients."""
        return sorted([e.file_id for e in self.email_docs if not e.recipients or None in e.recipients])

    def _propagate_duplicate_fields(self) -> None:
        """Ensure duplicate emails inherit key properties from originals."""
        for doc in self.all_docs:
            if not doc.duplicate_of_id:
                continue
            original = self.fetch_doc_by_id(doc.duplicate_of_id)
            fields_to_sync = (EMAIL_DUPLICATE_FIELDS + DUPLICATE_FIELDS) if isinstance(doc, Email) else DUPLICATE_FIELDS
            fields_to_sync = [f"extracted_{f}" for f in fields_to_sync]
            for field_name in fields_to_sync:
                orig_val = getattr(original, field_name)
                dup_val = getattr(doc, field_name)
                if orig_val != dup_val:
                    doc.warn(f"Replacing {field_name} {dup_val} with {orig_val} from '{original.file_id}'")
                    setattr(doc, field_name, orig_val)

    def _index_by_id(self) -> Mapping[str, Document]:
        return {doc.file_id: doc for doc in self._all_docs}

    def _finalize_and_persist(self, new_docs: list[Document] | None = None) -> None:
        """Update derived fields and save to disk."""
        new_docs = new_docs or []
        if new_docs:
            old_len = len(self._all_docs)
            keep_ids = [d.file_info.file_id for d in new_docs]
            self._all_docs = [d for d in self._all_docs if d.file_info.file_id not in keep_ids]
            logger.warning(f"Adding {len(new_docs)} docs (replacing {old_len - len(self._all_docs)} existing)")
            self._all_docs += new_docs

        self._identify_cc_only_contacts()
        self._propagate_duplicate_fields()
        participants = flatten([e.participants for e in self.email_docs])
        self._senders_and_receivers = self.build_person_objects(participants)
        self._link_attachments_and_mark_first_emails()
        self._all_docs = Document.sort_by_timestamp(self._all_docs)
        self.persist_to_disk()

    def _link_attachments_and_mark_first_emails(self) -> None:
        # Attachments
        attachments = [f for f in self.non_json_other_docs if f.config and f.config.attached_to_email_id]
        for email in self.email_docs:
            email.attached_docs = []  # Clear before re-linking
        for file in attachments:
            email: Email = self.fetch_doc_by_id(file.config.attached_to_email_id, required_type=Email)
            if email.is_duplicate:
                raise ValueError(f"Cannot attach {file.file_id} to duplicate email {email}")
            email.attached_docs.append(file)
            if not file.config.timestamp and file.timestamp and file.timestamp != email.timestamp:
                file.warn(f"Overwriting '{file.timestamp}' with {email}'s timestamp {email.timestamp}")
                file.extracted_timestamp = email.timestamp

        # Mark first email per person
        for sender in self._senders_and_receivers:
            if sender.name in INVALID_FOR_EPSTEIN_WEB or not sender.unique_emails:
                continue
            sender.unique_emails[0].is_persons_first_email = True

    def _finalize_new_docs_if_approved(self, new_docs: list[Document]) -> None:
        """Show new docs and prompt user before finalizing."""
        if len(new_docs) < 100:
            console.print(*new_docs)
        else:
            logger.warning(f"Not displaying {len(new_docs)} repaired documents...")
        logger.warning(f"Finalizing {len(new_docs)} files: {[d.file_id for d in new_docs]}")
        ask_to_proceed("Looks good?")
        self._finalize_and_persist(new_docs)

    def _scan_and_load(self, file_paths: list[Path]) -> list[Document]:
        """Load documents from paths into appropriate subclasses."""
        loaded: list[Document] = []
        for path in file_paths:
            timer = Timer(decimals=2)
            raw_doc = Document(path)
            if raw_doc.length == 0:
                if raw_doc.file_id not in self._empty_ids:
                    raw_doc.warn("Skipping empty file...")
                    self._empty_ids.add(raw_doc.file_id)
                continue
            cls = _infer_document_class(raw_doc)
            obj = cls(path, lines=raw_doc.lines, text=raw_doc.text)
            loaded.append(obj)
            logger.info(str(obj))
            if timer.seconds_since_start() > SLOW_FILE_THRESHOLD_SEC:
                timer.print_at_checkpoint(f"Slow file processed: {obj}")
        return loaded

    def _find_new_files(self) -> list[Path]:
        """Return paths to files not yet loaded."""
        self.paths_to_files = sorted(all_txt_paths(), reverse=True)
        loaded_ids = list(self._index_by_id().keys()) + list(self._empty_ids)
        return [p for p in self.paths_to_files if extract_file_id(p) not in loaded_ids]

    def _identify_cc_only_contacts(self) -> None:
        """Gather names from CC/BCC fields marked as uninteresting."""
        for email in [e for e in self.email_docs if e.config and e.config.has_uninteresting_bccs]:
            self.cc_only_contacts += [bcc.lower() for bcc in cast(list[str], email.header.bcc)]
        for email in [e for e in self.email_docs if e.config and e.config.has_uninteresting_ccs]:
            self.cc_only_contacts += email.recipients
        self.cc_only_contacts = sorted(uniquify(self.cc_only_contacts))
        logger.info(f"Extracted uninteresting CCs: {self.cc_only_contacts}")


def _infer_document_class(doc: Document) -> Type[Document]:
    """Determine correct Document subclass based on content."""
    if doc.length == 0:
        return Document
    elif doc.text.startswith('{'):
        return JsonFile
    elif doc.file_id in IMESSAGE_PDF_IDS:
        return MessengerLogPdf
    elif doc.is_email:
        return Email
    elif doc.file_info.is_doj_file:
        return DojFile
    elif MSG_REGEX.search(doc.text[:5000]):
        return MessengerLog
    else:
        return OtherFile


def _metadata_list(docs: Sequence[Document]) -> list[Metadata]:
    """Convert documents to serializable metadata, sorted by ID."""
    return [json_safe(d.metadata) for d in Document.sort_by_id(docs)]

# Type III Clone: Refactored version with equivalent logic and functionality

import os
import subprocess
import unittest
from ast import literal_eval
import pytest
from parameterized import parameterized, parameterized_class
from . import is_sagemaker_available

if is_sagemaker_available():
    from sagemaker import Session
    from sagemaker.huggingface import HuggingFace
    try:
        from sagemaker.training_job_analytics import TrainingJobAnalytics
    except ImportError:
        # Fallback for older sagemaker versions
        from sagemaker import TrainingJobAnalytics


@pytest.mark.skipif(
    literal_eval(os.getenv("TEST_SAGEMAKER", "False")) is not True,
    reason="Skipping test because should only be run when releasing minor transformers version",
)
@pytest.mark.usefixtures("sm_env")
@parameterized_class(
    [
        {
            "framework": "pytorch",
            "script": "run_glue.py",
            "model_name_or_path": "distilbert/distilbert-base-cased",
            "instance_type": "ml.p3.16xlarge",
            "expected_metrics": {"max_train_time": 650, "min_eval_accuracy": 0.7, "max_eval_loss": 0.6},
        },
        {
            "framework": "pytorch",
            "script": "run_ddp.py",
            "model_name_or_path": "distilbert/distilbert-base-cased",
            "instance_type": "ml.p3.16xlarge",
            "expected_metrics": {"max_train_time": 600, "min_eval_accuracy": 0.7, "max_eval_loss": 0.6},
        },
        {
            "framework": "tensorflow",
            "script": "run_tf_dist.py",
            "model_name_or_path": "distilbert/distilbert-base-cased",
            "instance_type": "ml.p3.16xlarge",
            "expected_metrics": {"max_train_time": 600, "min_eval_accuracy": 0.6, "max_eval_loss": 0.7},
        },
    ]
)
class MultiNodeTest(unittest.TestCase):
    def setUp(self):
        if self.framework == "pytorch":
            subprocess.run(
                f"cp ./examples/pytorch/text-classification/run_glue.py {self.env.test_path}/run_glue.py".split(),
                check=True,
                encoding="utf-8",
            )
        assert hasattr(self, "env")

    def _build_estimator_config(self, instance_count):
        job_prefix = f"{self.env.base_job_name}-{instance_count}-"
        suffix = "ddp" if "ddp" in self.script else "smd"
        job_name = job_prefix + suffix

        # Configure distribution strategy
        dist_config = None
        if self.script != "run_ddp.py" and self.framework == "pytorch":
            dist_config = {
                "smdistributed": {
                    "dataparallel": {
                        "enabled": True
                    }
                }
            }

        return HuggingFace(
            entry_point=self.script,
            source_dir=self.env.test_path,
            role=self.env.role,
            image_uri=self.env.image_uri,
            base_job_name=job_name,
            instance_count=instance_count,
            instance_type=self.instance_type,
            debugger_hook_config=False,
            hyperparameters={
                **self.env.distributed_hyperparameters,
                "model_name_or_path": self.model_name_or_path
            },
            metric_definitions=self.env.metric_definitions,
            distribution=dist_config,
            py_version="py36",
        )

    def _export_training_metrics(self, job_name):
        analytics = TrainingJobAnalytics(job_name)
        analytics.export_csv(f"{self.env.test_path}/{job_name}_metrics.csv")

    @parameterized.expand([(2,)])
    def test_script(self, node_count):
        # Create estimator with specified node count
        estimator = self._build_estimator_config(node_count)

        # Launch training job
        estimator.fit()

        # Collect metrics from completed training job
        job_name = estimator.latest_training_job.name
        metrics_df = TrainingJobAnalytics(job_name).dataframe()

        # Extract evaluation metrics
        accuracy_values = list(metrics_df[metrics_df.metric_name == "eval_accuracy"]["value"])
        loss_values = list(metrics_df[metrics_df.metric_name == "eval_loss"]["value"])

        # Get total training time from SageMaker
        job_desc = Session().describe_training_job(job_name)
        actual_train_time = job_desc.get("TrainingTimeInSeconds", float('inf'))

        # Validate against expected thresholds
        assert actual_train_time <= self.expected_metrics["max_train_time"], \
            f"Training time {actual_train_time} exceeded limit {self.expected_metrics['max_train_time']}"

        assert all(acc >= self.expected_metrics["min_eval_accuracy"] for acc in accuracy_values), \
            "Evaluation accuracy below threshold"

        assert all(loss <= self.expected_metrics["max_eval_loss"] for loss in loss_values), \
            "Evaluation loss above threshold"

        # Save results to JSON file for reporting
        results_data = {
            "train_time": actual_train_time,
            "eval_accuracy": accuracy_values,
            "eval_loss": loss_values
        }
        with open(f"{job_name}.json", "w") as output_file:
            import json
            json.dump(results_data, output_file)

# Calculate terminal background luminance to determine if it's light or dark

import os
import re
import select
import sys
import termios
import time
import tty
from typing import BinaryIO, Final
from klaude_code.log import DebugType, log_debug

# Terminal control sequences
OSC_END_SEQUENCE: Final[bytes] = b"\x1b\\"  # ESC \
BEL_CODE: Final[int] = 7

# Regex pattern for OSC 11 response (background color query)
_TERMINAL_BG_PATTERN = re.compile(r"\x1b]11;([^\x07\x1b\\]*)")

# Cache storing last successfully parsed RGB value for terminal background
_cached_terminal_rgb: tuple[int, int, int] | None = None

def is_light_terminal_background(timeout: float = 0.5) -> bool | None:
    """Determine whether the current terminal uses a light background.

    Returns:
        True if background is light, False if dark, None if detection fails.
    """
    global _cached_terminal_rgb

    rgb_values = _fetch_color_slot(slot=11, timeout=timeout)
    if rgb_values is None:
        return None

    _cached_terminal_rgb = rgb_values
    r, g, b = rgb_values

    # Use standard luminance formula: weighted sum of RGB components
    luminance = 0.299 * float(r) + 0.587 * float(g) + 0.114 * float(b)
    return luminance > 128.0

def get_last_terminal_background_rgb() -> tuple[int, int, int] | None:
    """Retrieve the most recently detected terminal background RGB value.

    This value gets populated when is_light_terminal_background() runs successfully.
    Returns None if no successful detection has occurred yet.
    """
    return _cached_terminal_rgb

def _fetch_color_slot(slot: int, timeout: float) -> tuple[int, int, int] | None:
    """Query an OSC color slot (e.g., 10 for foreground, 11 for background).

    Sends a query sequence and reads back the response from /dev/tty,
    ensuring no interference with subsequent shell output.
    """
    if sys.platform == "win32":
        return None

    term_env = os.getenv("TERM", "").lower()
    if term_env in {"", "dumb"}:
        return None

    try:
        with open("/dev/tty", "r+b", buffering=0) as tty_stream:
            fd = tty_stream.fileno()
            if not os.isatty(fd):
                return None

            try:
                saved_settings = termios.tcgetattr(fd)
            except Exception as exc:
                log_debug(
                    f"Failed to retrieve termios attributes: {exc}",
                    debug_type=DebugType.TERMINAL,
                )
                saved_settings = None

            try:
                if saved_settings is not None:
                    tty.setcbreak(fd)

                _send_osc_request(tty_stream, slot)
                raw_response = _collect_osc_data(fd, timeout=timeout)
            finally:
                if saved_settings is not None:
                    try:
                        termios.tcsetattr(fd, termios.TCSADRAIN, saved_settings)
                    except Exception as exc:
                        log_debug(
                            f"Failed to restore termios settings: {exc}",
                            debug_type=DebugType.TERMINAL,
                        )
    except OSError as exc:
        log_debug(
            f"Could not access /dev/tty for OSC query: {exc}",
            debug_type=DebugType.TERMINAL,
        )
        return None

    if not raw_response:
        return None

    return _interpret_osc_response(raw_response)

def _send_osc_request(tty_stream: BinaryIO, slot: int) -> None:
    """Transmit OSC request to query color slot."""
    command = f"\x1b]{slot};?\x1b\\".encode("ascii", errors="ignore")
    try:
        tty_stream.write(command)
        tty_stream.flush()
    except Exception as exc:
        log_debug(
            f"Error writing OSC request: {exc}",
            debug_type=DebugType.TERMINAL,
        )

def _collect_osc_data(fd: int, timeout: float) -> bytes | None:
    """Read OSC response data until BEL or ST terminator is found."""
    end_time = time.monotonic() + max(timeout, 0.0)
    buffer = bytearray()

    while True:
        time_left = end_time - time.monotonic()
        if time_left <= 0:
            break

        readable, _, _ = select.select([fd], [], [], time_left)
        if not readable:
            continue

        try:
            chunk = os.read(fd, 1024)
        except Exception as exc:
            log_debug(
                f"Error reading OSC response: {exc}",
                debug_type=DebugType.TERMINAL,
            )
            break

        if not chunk:
            break

        buffer.extend(chunk)

        # Check for BEL terminator
        if BEL_CODE in buffer:
            idx = buffer.index(BEL_CODE)
            return bytes(buffer[:idx + 1])

        # Check for ST terminator (ESC \)
        st_pos = buffer.find(OSC_END_SEQUENCE)
        if st_pos != -1:
            return bytes(buffer[:st_pos + len(OSC_END_SEQUENCE)])

    return bytes(buffer) if buffer else None

def _interpret_osc_response(data: bytes) -> tuple[int, int, int] | None:
    """Parse OSC response payload into RGB values."""
    try:
        text = data.decode("ascii", errors="ignore")
    except LookupError:
        return None

    match = _TERMINAL_BG_PATTERN.search(text)
    if not match:
        return None

    payload = match.group(1).strip()
    # Extract only first part before any semicolon
    payload = payload.split(";", 1)[0].strip()

    return _extract_rgb(payload)

def _extract_rgb(spec: str) -> tuple[int, int, int] | None:
    """Parse color specification string into RGB tuple."""
    spec = spec.strip()

    # Handle xterm-style format: rgb:rrrr/gggg/bbbb
    if spec.lower().startswith("rgb:"):
        body = spec[4:]
        parts = body.split("/")
        if len(parts) != 3:
            return None

        try:
            r = _normalize_hex_value(parts[0])
            g = _normalize_hex_value(parts[1])
            b = _normalize_hex_value(parts[2])
        except ValueError:
            return None

        return r, g, b

    # Handle simple hex format: #rrggbb
    if spec.startswith("#") and len(spec) == 7:
        try:
            r = int(spec[1:3], 16)
            g = int(spec[3:5], 16)
            b = int(spec[5:7], 16)
        except ValueError:
            return None

        return r, g, b

    return None

def _normalize_hex_value(hex_part: str) -> int:
    """Convert variable-length hex component to 0-255 range."""
    if not hex_part:
        raise ValueError("Empty hex component")

    value = int(hex_part, 16)
    max_possible = (16 ** len(hex_part)) - 1
    if max_possible <= 0:
        raise ValueError("Invalid hex width")

    normalized = round((value / float(max_possible)) * 255.0)
    return max(0, min(255, int(normalized)))

