# Agent configuration class with modified prefix list and parameter handling
class AgentConfig:
    RATE_LIMITED_MODELS = [
        "groq/",
        "gemini/",
        "ollama/",
        "mistral/",
    ]

    def __init__(
        self,
        model_name="gpt-4.1",
        api_token=None,
        temp=0.1,
        max_output_tokens=2048,
        timeout_duration=240,
        streaming=True,
        caching_enabled=True,
    ):
        self.model = model_name
        self.api_key = api_token
        self.temperature = temp
        self.max_tokens = max_output_tokens
        self.timeout = timeout_duration
        self.stream = streaming
        self.enable_cache = caching_enabled

    def is_rate_limited(self):
        m = (self.model or "").strip().lower()
        for prefix in self.RATE_LIMITED_MODELS:
            if m.startswith(prefix):
                return True
        return False

