        Interrupt(id=ANY, name="weather_approval_needed", reason="requires confirmation"),
    ]
    assert len(sorted_interrupts) == 2
    assert [i.name for i in sorted_interrupts] == [e.name for e in expected_interrupts]

    approvals = [
        {
            "interruptResponse": {
                "interruptId": intr.id,
                "response": "APPROVE",
            },
        }
        for intr in sorted_interrupts
    ]
    completed_res = workflow_graph(approvals)
    assert completed_res.status == Status.COMPLETED
    assert workflow_graph.state.status == Status.COMPLETED
    assert len(completed_res.results) == 4

    day_out = json.dumps(completed_res.results["day"].result.message).lower()
    time_out = json.dumps(completed_res.results["time"].result.message).lower()
    weather_out = json.dumps(completed_res.results["weather"].result.message).lower()

    assert "monday" in day_out
    assert "12:01" in time_out
    assert "sunny" in weather_out


@pytest.mark.asyncio
async def test_graph_partial_rejection(workflow_graph):
    res = workflow_graph("What is the day, time, and weather?")
    assert res.status == Status.INTERRUPTED
    assert workflow_graph.state.status == Status.INTERRUPTED

    sorted_ints = sorted(res.interrupts, key=lambda x: x.name)
    assert len(sorted_ints) == 2

    mixed_responses = [
        {
            "interruptResponse": {
                "interruptId": sorted_ints[0].id,
                "response": "APPROVE",
            },
        },
        {
            "interruptResponse": {
                "interruptId": sorted_ints[1].id,
                "response": "REJECT",
            },
        },
    ]

    cancel_id = None
    try:
        async for event in workflow_graph.stream_async(mixed_responses):
            if event.get("type") == "multiagent_node_cancel":
                cancel_id = event["node_id"]
    except RuntimeError as err:
        assert "node denied" in str(err)

    assert cancel_id == "weather"
    assert workflow_graph.state.status == Status.FAILED

from __future__ import annotations
from typing import Any, Callable
import numpy as np
from noether.data.base import Dataset, DatasetWrapper


class PropertySubsetWrapper(DatasetWrapper):
    """
    A wrapper that selectively loads only specified properties from a base dataset.

    When accessing an item via __getitem__, it fetches only those attributes defined in `selected_items`,
    avoiding unnecessary computation or I/O. Useful for scenarios like training vs validation where
    different subsets of data are needed.

    Example:
        >>> ds = DummyDataset()
        >>> wrapped = PropertySubsetWrapper.from_included_excluded(ds, included_properties={'x', 'y'})
        >>> sample = wrapped[0]  # Only calls getitem_x(0) and getitem_y(0)
    """

    def __init__(self, base: Dataset | DatasetWrapper, selected_items: set[str]):
        super().__init__(dataset=base)

        if not isinstance(selected_items, set):
            raise TypeError("Selected items must be provided as a set.")
        if not selected_items:
            raise ValueError("At least one property must be selected.")

        self.selected_items = selected_items
        self._fetchers: dict[str, Callable[[int], Any]] = {}

        for item in selected_items:
            if item == "index":
                self._fetchers[item] = self._fetch_index
            else:
                method_name = f"getitem_{item}"
                if not hasattr(base, method_name):
                    raise AttributeError(
                        f"{type(base).__name__} lacks '{method_name}' method. "
                        "Ensure all requested properties have corresponding getitem_<prop> methods."
                    )
                self._fetchers[item] = getattr(base, method_name)

    @staticmethod
    def _fetch_index(position: int) -> int:
        """Returns the index unchanged."""
        return position

    def __getitem__(self, idx: int) -> dict[str, Any]:
        """Fetches selected properties for the given index."""
        if not isinstance(idx, (int, np.integer)):
            raise TypeError(f"Index must be integer-like, got {type(idx)}")
        if idx < 0:
            raise ValueError(f"Index must be non-negative, got {idx}")
        if idx >= len(self.dataset):
            raise IndexError(f"Index {idx} out of range [0, {len(self.dataset)})")

        result = {}
        for key, fetcher in self._fetchers.items():
            result[key] = fetcher(idx)
        return result

    def __getattr__(self, name: str) -> Any:
        """Delegates attribute access to underlying dataset unless explicitly overridden."""
        if name == "dataset":
            return super().__getattribute__("dataset")
        if name == "selected_items":
            return super().__getattribute__("selected_items")
        if name == "__getitems__":
            # Prevent Torch DataLoader from using batched retrieval
            return None
        return getattr(self.dataset, name)

    def __str__(self) -> str:
        base_name = type(self.dataset).__name__
        if hasattr(self.dataset, "__str__") and self.dataset.__str__.__qualname__ != "object.__str__":
            base_name = str(self.dataset)
        return f"{base_name} (properties={','.join(sorted(self.selected_items))})"

    @classmethod
    def create_from_filtering(cls,
                              base_dataset: Dataset,
                              include: set[str] | None = None,
                              exclude: set[str] | None = None) -> Dataset | PropertySubsetWrapper:
        """Constructs a filtered view over the dataset based on inclusion/exclusion rules."""
        # Discover available properties by scanning getitem_* methods
        candidates = {
            attr[len("getitem_"):]
            for attr in dir(base_dataset)
            if attr.startswith("getitem_") and callable(getattr(base_dataset, attr))
        }
        candidates.add("index")  # Always valid

        # Apply filters
        if include is not None and exclude is not None:
            final_set = include.difference(exclude)
        elif include is not None:
            final_set = include.copy()
        elif exclude is not None:
            final_set = candidates.difference(exclude)
        else:
            return base_dataset  # No filtering required

        if not final_set:
            raise ValueError("No valid properties remain after applying filters.")

        return cls(dataset=base_dataset, selected_items=final_set)

