# Revalidate existing proxies with optional core validation and streak tracking

import concurrent.futures
import os
import time
from typing import Dict, List, Optional, Set, Tuple
from .common import log, progress, sha1_hex, get_proxy_connection_hash, get_v2rayn_connection_key
from .constants import (
    AVAILABLE_FILE,
    PING_WORKERS,
    ENABLE_STAGE2,
    ENABLE_STAGE3,
    STAGE3_MAX,
    STAGE3_WORKERS,
    EXISTING_PROXY_FAILURE_LIMIT,
)
from .grouping import write_grouped_outputs
from .io_ops import (
    ensure_dirs,
    load_streaks,
    read_lines,
    save_streaks,
)
from .net import ping_host, connect_host_port, quick_protocol_probe, validate_with_v2ray_core
from .parsing import (
    extract_host,
    extract_port,
)

def _sync_check_counts_with_available_file() -> None:
    """Lazy import and call sync function from main.py to avoid circular imports."""
    try:
        from .main import _sync_check_counts_with_available_file as sync_func
        sync_func()
    except (ImportError, AttributeError):
        pass

def _has_internet_access() -> bool:
    """Attempt basic connectivity checks using known public IPs/ports."""
    try:
        test_targets = [('1.1.1.1', 443), ('8.8.8.8', 53)]
        for ip_addr, port_num in test_targets:
            try:
                if ping_host(ip_addr):
                    return True
            except Exception:
                pass
            try:
                if connect_host_port(ip_addr, port_num):
                    return True
            except Exception:
                pass
    except Exception:
        pass
    return False

def main() -> int:
    ensure_dirs()

    # Early check: skip processing if no internet access
    if not _has_internet_access():
        log("No Internet connectivity detected; skipping network operations and leaving existing outputs unchanged.")
        return 2

    # Load persistent streak data
    streak_data: Dict[str, Dict[str, int]] = load_streaks()

    # Initialize tracking structures
    host_success_status: Dict[str, bool] = {}
    current_alive_list: List[str] = []
    deduped_alive_list: List[str] = []
    host_to_url_mapping: Dict[str, Optional[str]] = {}

    if os.path.exists(AVAILABLE_FILE):
        raw_lines = [line.strip() for line in read_lines(AVAILABLE_FILE) if line.strip()]
        if raw_lines:
            from .parsing import extract_host as _extract_host_for_existing

            # Deduplicate using V2RayN-style connection keys
            seen_keys: Set[str] = set()
            unique_lines = []
            for url in raw_lines:
                key = get_v2rayn_connection_key(url)
                if key not in seen_keys:
                    seen_keys.add(key)
                    unique_lines.append(url)

            log(f"Deduplicated existing proxies: {len(unique_lines)} unique out of {len(raw_lines)} total")
            raw_lines = unique_lines
            host_to_url_mapping = {url: _extract_host_for_existing(url) for url in raw_lines}

            # Prepare items for checking
            valid_items = [(url, h) for url, h in host_to_url_mapping.items() if h]
            for _, host in valid_items:
                if host not in host_success_status:
                    host_success_status[host] = False

            def verify_existing_proxy(item: Tuple[str, str]) -> Optional[str]:
                url, host = item
                try:
                    if not ping_host(host):
                        return None

                    scheme = url.split('://', 1)[0].lower()
                    if scheme in ('vmess', 'vless', 'trojan', 'ss', 'ssr', 'hysteria', 'hysteria2', 'hy2', 'tuic', 'juicity', 'wireguard'):
                        port = extract_port(url)
                        if port is not None:
                            if not connect_host_port(host, int(port)):
                                return None
                            if int(ENABLE_STAGE2) == 1:
                                if not quick_protocol_probe(url, host, int(port)):
                                    return None
                    return url
                except Exception:
                    return None

            # Skip Stage 2 for existing proxies — keep all without revalidation
            # with concurrent.futures.ThreadPoolExecutor(max_workers=PING_WORKERS) as executor:
            #     print("Start Stage 2 for existing proxies")
            #     for result in progress(executor.map(verify_existing_proxy, valid_items), total=len(valid_items)):
            #         if result is not None:
            #             current_alive_list.append(result)
            #             host = host_to_url_mapping.get(result)
            #             if host:
            #                 host_success_status[host] = True

            # Keep all existing proxies without revalidation
            for url in raw_lines:
                current_alive_list.append(url)
                host = host_to_url_mapping.get(url)
                if host:
                    host_success_status[host] = True

            # Optional Stage 3: Validate subset using V2Ray/Xray core
            if int(ENABLE_STAGE3) == 1 and current_alive_list:
                v2ray_path = ''
                try:
                    from .constants import V2RAY_CORE_PATH
                    v2ray_path = (V2RAY_CORE_PATH or '').strip()
                except Exception:
                    v2ray_path = ''

                if not v2ray_path:
                    log("Stage 3 enabled, but V2Ray/Xray core not found or OPENRAY_V2RAY_CORE is not set; skipping core validation for existing proxies.")
                else:
                    sample_size = min(len(current_alive_list), int(STAGE3_MAX)) if int(STAGE3_MAX) > 0 else len(current_alive_list)
                    validated_subset: List[str] = []

                    def run_core_validation(url: str) -> Tuple[str, bool]:
                        try:
                            result = validate_with_v2ray_core(url, timeout_s=12)
                        except Exception:
                            return url, False
                        return url, (result is True)

                    worker_count = int(STAGE3_WORKERS)
                    with concurrent.futures.ThreadPoolExecutor(max_workers=worker_count) as pool:
                        print("Start Stage 3 for existing proxies")
                        for url, success in progress(pool.map(run_core_validation, current_alive_list[:sample_size]), total=sample_size):
                            host = host_to_url_mapping.get(url)
                            if success:
                                validated_subset.append(url)
                                if host:
                                    if host not in streak_data:
                                        streak_data[host] = {'streak': 0, 'last_test': 0, 'last_success': 0, 'failure_count': 0}
                                    streak_data[host]['failure_count'] = 0
                            else:
                                if host:
                                    if host not in streak_data:
                                        streak_data[host] = {'streak': 0, 'last_test': 0, 'last_success': 0, 'failure_count': 0}

                                    current_failures = streak_data[host].get('failure_count', 0)
                                    streak_data[host]['failure_count'] = current_failures + 1

                                    if streak_data[host]['failure_count'] < int(EXISTING_PROXY_FAILURE_LIMIT):
                                        validated_subset.append(url)
                                    else:
                                        log(f"Proxy {host} reached failure limit ({EXISTING_PROXY_FAILURE_LIMIT}). Removing it.")
                                else:
                                    pass

                    # Update streaks after validation
                    save_streaks(streak_data)

                    # Replace first part with validated ones
                    current_alive_list = validated_subset + current_alive_list[sample_size:]

            # Final deduplication of alive list
            final_seen_keys: Set[str] = set()
            for url in current_alive_list:
                conn_key = get_v2rayn_connection_key(url)
                if conn_key not in final_seen_keys:
                    final_seen_keys.add(conn_key)
                    deduped_alive_list.append(url)

            # Safeguard against accidental purge during outage
            if len(deduped_alive_list) != len(raw_lines):
                if len(raw_lines) > 0 and len(deduped_alive_list) == 0 and not _has_internet_access():
                    log("Suspected Internet outage during revalidation; keeping existing available proxies file unchanged.")
                else:
                    temp_file = AVAILABLE_FILE + '.tmp'
                    with open(temp_file, 'w', encoding='utf-8', errors='ignore') as f:
                        for url in deduped_alive_list:
                            f.write(url + '\n')
                    os.replace(temp_file, AVAILABLE_FILE)
                    log(f"Revalidated existing available proxies: kept {len(deduped_alive_list)} of {len(raw_lines)} (deduplicated from {len(current_alive_list)})")
                    _sync_check_counts_with_available_file()
            else:
                log("Revalidated existing available proxies: all still reachable")
    else:
        log(f"No existing proxies file found: {AVAILABLE_FILE}")
        return 0

    # Update streaks based on success status
    for host, was_successful in host_success_status.items():
        if host not in streak_data:
            streak_data[host] = {}
        if was_successful:
            streak_data[host]['consecutive'] = streak_data[host].get('consecutive', 0) + 1
            streak_data[host]['last_success'] = int(time.time())
        else:
            streak_data[host]['consecutive'] = 0

    save_streaks(streak_data)

    # Write grouped outputs if any proxies remain
    if deduped_alive_list:
        write_grouped_outputs()
        log(f"Successfully processed {len(deduped_alive_list)} existing proxies")
    else:
        log("No existing proxies found to process")

    return 0

if __name__ == '__main__':
    raise SystemExit(main())

import struct
import datetime
import sys

# Determine Python version
PY2 = sys.version_info[0] == 2

# Define integer types based on Python version
if PY2:
    int_types = (int, long)
else:
    int_types = int

# Handle timezone for UTC
try:
    _utc = datetime.timezone.utc
except AttributeError:
    _utc = datetime.timezone(datetime.timedelta(0))

class ExtType(object):
    """ExtType represents ext type in msgpack."""
    def __init__(self, code, data):
        if not isinstance(code, int_types):
            raise TypeError("code must be int")
        if not isinstance(data, bytes):
            raise TypeError("data must be bytes")
        if not (0 <= code <= 127):
            raise ValueError("code must be 0~127")
        self.code = code
        self.data = data

    def __repr__(self):
        return "ExtType(code={0}, data={1!r})".format(self.code, self.data)

    def __eq__(self, other):
        if isinstance(other, ExtType):
            return self.code == other.code and self.data == other.data
        return False

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self.code, self.data))

class Timestamp(object):
    """Timestamp represents the Timestamp extension type in msgpack.
    When built with Cython, msgpack uses C methods to pack and unpack `Timestamp`. When using pure-Python
    msgpack, :func:`to_bytes` and :func:`from_bytes` are used to pack and unpack `Timestamp`.
    This class is immutable: Do not override seconds and nanoseconds.
    """
    __slots__ = ["seconds", "nanoseconds"]

    def __init__(self, seconds, nanoseconds=0):
        """Initialize a Timestamp object.
        :param int seconds:
            Number of seconds since the UNIX epoch (00:00:00 UTC Jan 1 1970, minus leap seconds).
            May be negative.
        :param int nanoseconds:
            Number of nanoseconds to add to `seconds` to get fractional time.
            Maximum is 999_999_999.  Default is 0.
        Note: Negative times (before the UNIX epoch) are represented as negative seconds + positive ns.
        """
        if not isinstance(seconds, int_types):
            raise TypeError("seconds must be an integer")
        if not isinstance(nanoseconds, int_types):
            raise TypeError("nanoseconds must be an integer")
        if not (0 <= nanoseconds < 10**9):
            raise ValueError(
                "nanoseconds must be a non-negative integer less than 999999999."
            )
        # Make immutable by setting via object.__setattr__
        object.__setattr__(self, "seconds", seconds)
        object.__setattr__(self, "nanoseconds", nanoseconds)

    def __setattr__(self, name, value):
        raise AttributeError("Timestamp is immutable")

    def __delattr__(self, name):
        raise AttributeError("Timestamp is immutable")

    def __repr__(self):
        """String representation of Timestamp."""
        return "Timestamp(seconds={0}, nanoseconds={1})".format(
            self.seconds, self.nanoseconds
        )

    def __eq__(self, other):
        """Check for equality with another Timestamp object"""
        if isinstance(other, Timestamp):
            return (
                self.seconds == other.seconds and self.nanoseconds == other.nanoseconds
            )
        return False

    def __ne__(self, other):
        """not-equals method (see :func:`__eq__()`)"""
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self.seconds, self.nanoseconds))

    @staticmethod
    def from_bytes(b):
        """Unpack bytes into a `Timestamp` object.
        Used for pure-Python msgpack unpacking.
        :param b: Payload from msgpack ext message with code -1
        :type b: bytes
        :returns: Timestamp object unpacked from msgpack ext payload
        :rtype: Timestamp
        """
        if len(b) == 4:
            seconds = struct.unpack("!L", b)[0]
            nanoseconds = 0
        elif len(b) == 8:
            data64 = struct.unpack("!Q", b)[0]
            seconds = data64 & 0x00000003FFFFFFFF
            nanoseconds = data64 >> 34
        elif len(b) == 12:
            nanoseconds, seconds = struct.unpack("!Iq", b)
        else:
            raise ValueError(
                "Timestamp type can only be created from 32, 64, or 96-bit byte objects"
            )
        return Timestamp(seconds, nanoseconds)

    def to_bytes(self):
        """Pack this Timestamp object into bytes.
        Used for pure-Python msgpack packing.
        :returns data: Payload for EXT message with code -1 (timestamp type)
        :rtype: bytes
        """
        if (self.seconds >> 34) == 0:  # seconds is non-negative and fits in 34 bits
            data64 = self.nanoseconds << 34 | self.seconds
            if data64 & 0xFFFFFFFF00000000 == 0:
                # nanoseconds is zero and seconds < 2**32, so timestamp 32
                data = struct.pack("!L", data64)
            else:
                # timestamp 64
                data = struct.pack("!Q", data64)
        else:
            # timestamp 96
            data = struct.pack("!Iq", self.nanoseconds, self.seconds)
        return data

    @staticmethod
    def from_unix(unix_sec):
        """Create a Timestamp from posix timestamp in seconds.
        :param unix_float: Posix timestamp in seconds.
        :type unix_float: int or float.
        """
        seconds = int(unix_sec // 1)
        nanoseconds = int((unix_sec % 1) * 10**9)
        return Timestamp(seconds, nanoseconds)

    def to_unix(self):
        """Get the timestamp as a floating-point value.
        :returns: posix timestamp
        :rtype: float
        """
        return self.seconds + self.nanoseconds / 1e9

    @staticmethod
    def from_unix_nano(unix_ns):
        """Create a Timestamp from posix timestamp in nanoseconds.
        :param int unix_ns: Posix timestamp in nanoseconds.
        :rtype: Timestamp
        """
        return Timestamp(*divmod(unix_ns, 10**9))

    def to_unix_nano(self):
        """Get the timestamp as a unixtime in nanoseconds.
        :returns: posix timestamp in nanoseconds
        :rtype: int
        """
        return self.seconds * 10**9 + self.nanoseconds

    def to_datetime(self):
        """Get the timestamp as a UTC datetime.
        Python 2 is not supported.
        :rtype: datetime.
        """
        return datetime.datetime.fromtimestamp(0, _utc) + datetime.timedelta(
            seconds=self.to_unix()
        )

    @staticmethod
    def from_datetime(dt):
        """Create a Timestamp from datetime with tzinfo.
        Python 2 is not supported.
        :rtype: Timestamp
        """
        return Timestamp.from_unix(dt.timestamp())

from abc import ABC, abstractmethod
from memos.configs.mem_chat import BaseMemChatConfig
from memos.mem_cube.base import BaseMemCube

class AbstractMemChat(ABC):
    """Abstract base class for MemChat implementations."""

    @abstractmethod
    def __init__(self, settings: BaseMemChatConfig) -> None:
        """Construct a MemChat instance using the provided configuration."""
        pass

    @property
    @abstractmethod
    def memory_storage(self) -> BaseMemCube:
        """Access the memory storage component used by this MemChat."""
        raise NotImplementedError

    @memory_storage.setter
    @abstractmethod
    def memory_storage(self, cube: BaseMemCube) -> None:
        """Assign a new memory storage component to this MemChat."""
        raise NotImplementedError

    @abstractmethod
    def execute(self) -> None:
        """Execute the main MemChat workflow.
        This method encapsulates the primary operational logic,
        such as handling conversation turns and managing memory.
        """
        raise NotImplementedError

# Factory module for creating cache instances based on configuration

from log import get_logger
logger = get_logger(__name__)

import constants
from models.config import ConversationHistoryConfiguration
from cache.cache import Cache
from cache.noop_cache import NoopCache
from cache.in_memory_cache import InMemoryCache
from cache.postgres_cache import PostgresCache
from cache.sqlite_cache import SQLiteCache


class CacheBuilder:
    """Factory responsible for constructing appropriate cache implementations."""

    @staticmethod
    def build_conversation_cache(settings: ConversationHistoryConfiguration) -> Cache:
        """Constructs a cache instance according to the provided configuration.

        Args:
            settings: Configuration object specifying cache type and parameters.

        Returns:
            A cache implementation matching the configured type.

        Raises:
            ValueError: If cache type is unspecified, invalid, or required
                       configuration section is missing for the selected type.
        """
        logger.info("Initializing cache of type %s", settings.type)

        if settings.type == constants.CACHE_TYPE_NOOP:
            return NoopCache()
        elif settings.type == constants.CACHE_TYPE_MEMORY:
            if settings.memory is not None:
                return InMemoryCache(settings.memory)
            raise ValueError("In-memory cache requires memory configuration")
        elif settings.type == constants.CACHE_TYPE_SQLITE:
            if settings.sqlite is not None:
                return SQLiteCache(settings.sqlite)
            raise ValueError("SQLite cache requires sqlite configuration")
        elif settings.type == constants.CACHE_TYPE_POSTGRES:
            if settings.postgres is not None:
                return PostgresCache(settings.postgres)
            raise ValueError("PostgreSQL cache requires postgres configuration")
        elif settings.type is None:
            raise ValueError("Cache type must be specified in configuration")
        else:
            valid_types = [
                constants.CACHE_TYPE_POSTGRES,
                constants.CACHE_TYPE_SQLITE,
                constants.CACHE_TYPE_MEMORY,
                constants.CACHE_TYPE_NOOP
            ]
            raise ValueError(
                f"Unknown cache type '{settings.type}'. "
                f"Valid options are: {', '.join(valid_types)}."
            )

