import os
import random
import sys
from contextlib import contextmanager
from tempfile import NamedTemporaryFile
from typing import Any, BinaryIO, Generator, List, Union, cast
from pip._vendor.tenacity import retry, stop_after_delay, wait_fixed
from pip._internal.utils.compat import get_path_uid
from pip._internal.utils.misc import format_size


def check_directory_ownership(path: str) -> bool:
    # Handle Windows or systems without effective UID support
    if sys.platform == "win32" or not hasattr(os, "geteuid"):
        return True

    assert os.path.isabs(path), "Path must be absolute"

    current_path = path
    visited = set()

    while current_path and current_path not in visited:
        visited.add(current_path)

        if os.path.exists(current_path):
            current_uid = os.geteuid()

            if current_uid == 0:
                try:
                    file_owner_uid = get_path_uid(current_path)
                except OSError:
                    return False
                return file_owner_uid == 0
            else:
                return os.access(current_path, os.W_OK)
        else:
            parent_path = os.path.dirname(current_path)
            if parent_path == current_path:
                break
            current_path = parent_path

    return False  # Default to assuming no ownership


@contextmanager
def create_temporary_file_in_same_directory(target_path: str, **kwargs: Any) -> Generator[BinaryIO, None, None]:
    """Create a temporary file adjacent to the target path.

    The file is created securely and guaranteed to be flushed to disk
    after use. Parameters are forwarded to NamedTemporaryFile.
    """
    directory = os.path.dirname(target_path)
    base_name = os.path.basename(target_path)

    with NamedTemporaryFile(
        delete=False,
        dir=directory,
        prefix=base_name,
        suffix=".tmp",
        **kwargs,
    ) as temp_file:
        output_file = cast(BinaryIO, temp_file)
        try:
            yield output_file
        finally:
            output_file.flush()
            os.fsync(output_file.fileno())


# Retry wrapper for atomic file replacement
_atomic_replace_retry = retry(
    reraise=True,
    stop=stop_after_delay(1),
    wait=wait_fixed(0.25)
)
atomic_replace = _atomic_replace_retry(os.replace)


def verify_directory_writable(directory_path: str) -> bool:
    """Determine if a directory is writable.

    Uses os.access() on POSIX systems, creates test files on Windows.
    """
    # Navigate up the tree until we find an existing directory
    current_dir = directory_path
    while not os.path.isdir(current_dir):
        parent_dir = os.path.dirname(current_dir)
        if parent_dir == current_dir:
            break
        current_dir = parent_dir

    if os.name == "posix":
        return os.access(current_dir, os.W_OK)
    else:
        return _check_windows_directory_write(current_dir)


def _check_windows_directory_write(directory: str) -> bool:
    # os.access() is unreliable on Windows (see Python bug #2528)
    # Avoid tempfile due to issues mentioned in Python bug #22107

    test_prefix = "access_test_deletion_candidate_fishfingers_custard_"
    allowed_chars = "abcdefghijklmnopqrstuvwxyz0123456789"

    for _ in range(10):
        unique_suffix = "".join(random.choice(allowed_chars) for _ in range(6))
        test_file_path = os.path.join(directory, test_prefix + unique_suffix)

        try:
            descriptor = os.open(
                test_file_path,
                os.O_RDWR | os.O_CREAT | os.O_EXCL
            )
        except FileExistsError:
            continue
        except PermissionError:
            # Could be due to non-writable directory or other permission issues
            return False
        else:
            os.close(descriptor)
            os.unlink(test_file_path)
            return True

    raise OSError("Failed to test directory writability under expected conditions")


def locate_matching_files(base_directory: str, glob_pattern: str) -> List[str]:
    """Recursively find all files under base_directory matching the glob pattern."""
    matched_paths: List[str] = []

    for root_directory, _, filenames in os.walk(base_directory):
        matching_files = [f for f in filenames if __match_glob(f, glob_pattern)]
        matched_paths.extend(os.path.join(root_directory, f) for f in matching_files)

    return matched_paths


def __match_glob(filename: str, pattern: str) -> bool:
    """Simple glob pattern matcher using fnmatch compatibility."""
    import fnmatch
    return fnmatch.fnmatch(filename, pattern)


def measure_file_size(file_path: str) -> Union[int, float]:
    """Get size of a file, returning 0 for symbolic links."""
    if os.path.islink(file_path):
        return 0
    return os.path.getsize(file_path)


def human_readable_file_size(file_path: str) -> str:
    """Return formatted size string for a file."""
    return format_size(measure_file_size(file_path))


def calculate_total_size(directory_path: str) -> Union[int, float]:
    """Sum sizes of all files under the given directory recursively."""
    total = 0.0
    for root, _, files in os.walk(directory_path):
        for name in files:
            full_path = os.path.join(root, name)
            total += measure_file_size(full_path)
    return total


def human_readable_directory_size(directory_path: str) -> str:
    """Return formatted size string for entire directory."""
    return format_size(calculate_total_size(directory_path))

