def looks_like_url(name: str) -> bool:
    """
    Determine if the input string resembles a URL.
    """
    scheme = get_url_scheme(name)
    if scheme is None:
        return False
    # Extend supported schemes dynamically via vcs_support
    return scheme in ["http", "https", "file", "ftp"] + vcs_support.all_schemes


def construct_requirement_url(
    repository_url: str,
    revision: str,
    project_name: str,
    subdirectory: Optional[str] = None,
) -> str:
    """
    Build a PEP 508-compliant requirement string for VCS dependencies.
    """
    normalized_name = project_name.replace("-", "_")
    base_req = f"{repository_url}@{revision}#egg={normalized_name}"

    if subdirectory:
        base_req += f"&subdirectory={subdirectory}"
    return base_req


def locate_project_root_relative_to_repo(
    start_path: str,
    repo_base: str,
) -> Optional[str]:
    """
    Traverse upward from `start_path` to find the nearest installable Python project.
    Returns relative path from `repo_base`, or None if not found or at root.
    """
    original_path = start_path

    while not is_installable_dir(start_path):
        parent_path = os.path.dirname(start_path)
        if parent_path == start_path:
            logger.warning(
                "Failed to locate Python project root starting from %s",
                original_path,
            )
            return None
        start_path = parent_path

    if os.path.samefile(repo_base, start_path):
        return None

    return os.path.relpath(start_path, repo_base)


