class RevisionSpec:
    """
    Immutable specification of a revision and associated options for VCS operations.
    """

    def __init__(
        self,
        vcs_backend: Type["VersionControlSystem"],
        rev: Optional[str] = None,
        additional_args: Optional[CommandArgs] = None,
    ):
        self._backend = vcs_backend
        self._rev = rev
        self._extra_args = list(additional_args) if additional_args else []
        self._branch_name: Optional[str] = None

    def __repr__(self) -> str:
        return f"<RevisionSpec {self._backend.name}: rev={self._rev!r}>"

    @property
    def revision_identifier(self) -> Optional[str]:
        return self._rev or self._backend.default_revision_arg

    def to_command_args(self) -> CommandArgs:
        args: CommandArgs = []
        rev = self.revision_identifier
        if rev is not None:
            args.extend(self._backend.revision_argument_list(rev))
        args.extend(self._extra_args)
        return args

    def to_string(self) -> str:
        return f" (to revision {self._rev})" if self._rev else ""

    def clone_with_new_rev(self, new_rev: str) -> "RevisionSpec":
        return self._backend.create_revision_spec(new_rev, extra_args=self._extra_args)


class VersionControlSystemRegistry:
    _backends: Dict[str, "VersionControlSystem"] = {}
    known_schemes = ["ssh", "git", "hg", "bzr", "sftp", "svn"]

    def __init__(self):
        urllib.parse.uses_netloc.extend(self.known_schemes)

    def __iter__(self) -> Iterator[str]:
        return iter(self._backends)

    @property
    def active_backends(self) -> List["VersionControlSystem"]:
        return list(self._backends.values())

    @property
    def directory_markers(self) -> List[str]:
        return [b.directory_marker for b in self.active_backends]

    @property
    def all_supported_schemes(self) -> List[str]:
        schemes: List[str] = []
        for backend in self.active_backends:
            schemes.extend(backend.supported_schemes)
        return schemes

    def register(self, cls: Type["VersionControlSystem"]) -> None:
        if not hasattr(cls, "identifier"):
            logger.warning("Skipping registration of %s - missing identifier", cls.__name__)
            return

        name = cls.identifier.lower()
        if name not in self._backends:
            self._backends[name] = cls()
            logger.debug("Registered VCS backend: %s", name)

    def deregister(self, name: str) -> None:
        if name in self._backends:
            del self._backends[name]

    def detect_backend_from_directory(self, path: str) -> Optional["VersionControlSystem"]:
        candidates = {}
        for backend in self._backends.values():
            root = backend.find_repository_root(path)
            if not root:
                continue
            logger.debug("Detected %s in %s", backend.identifier, path)
            candidates[root] = backend

        if not candidates:
            return None

        # Prefer innermost repository (longest path)
        deepest_path = max(candidates, key=len)
        return candidates[deepest_path]

    def detect_backend_by_scheme(self, scheme: str) -> Optional["VersionControlSystem"]:
        for backend in self._backends.values():
            if scheme in backend.supported_schemes:
                return backend
        return None

    def get_backend(self, name: str) -> Optional["VersionControlSystem"]:
        return self._backends.get(name.lower())


vcs_support = VersionControlSystemRegistry()


class VersionControlSystem:
    identifier = ""
    directory_marker = ""
