    def generate_src_requirement(cls, repo_path: str, project_name: str) -> str:
        """Generate requirement string for source installation."""
        remote_url = cls.get_remote_url(repo_path)
        if cls.needs_vcs_prefix(remote_url):
            remote_url = f"{cls.identifier}+{remote_url}"

        rev = cls.get_revision_for_requirement(repo_path)
        subdir = cls.extract_subdir(repo_path)

        return construct_requirement_url(remote_url, rev, project_name, subdir=subdirectory=subdir)

