        raise NotImplementedError

    def is_reproducible_checkout(self, url: str, destination: str) -> bool:
        """Check if current commit matches requested revision (when possible)."""
        return False

    @classmethod
    def create_revision_spec(
        cls, rev: Optional[str] = None, extra_args: Optional[CommandArgs] = None
    ) -> RevisionSpec:
        return RevisionSpec(cls, rev, extra_args=extra_args)

    @staticmethod
    def _is_local_path(repo: str) -> bool:
        drive, tail = os.path.splitdrive(repo)
        return repo.startswith(os.sep) or bool(drive)

    @classmethod
    def parse_auth_info(
        cls, netloc: str, protocol: str
    ) -> Tuple[str, Credentials]:
        """Extract authentication info from URL netloc."""
        return netloc, (None, None)

    @classmethod
    def split_url_components(cls, url: str) -> Tuple[str, Optional[str], Credentials]:
        """Parse VCS URL into base URL, revision, and credentials."""
        parsed = urllib.parse.urlsplit(url)

        if "+" not in parsed.scheme:
            raise ValueError(
                f"Invalid VCS URL format: {url!r}. Expected <vcs>+<scheme>://..."
            )

        # Strip VCS prefix
        actual_scheme = parsed.scheme.split("+", 1)[1]

        # Handle auth
        netloc, credentials = cls.parse_auth_info(parsed.netloc, actual_scheme)

        # Extract revision from path
        rev = None
        if "@" in parsed.path:
            path_part, rev = parsed.path.rsplit("@", 1)
            if not rev:
                raise InstallationError(
                    f"Empty revision in URL {url!r} is not allowed."
                )
        else:
            path_part = parsed.path

        reconstructed_url = urllib.parse.urlunsplit(
            (actual_scheme, netloc, path_part, parsed.query, "")
        )
        return reconstructed_url, rev, credentials

    @staticmethod
    def prepare_extra_args(
        username: Optional[str], password: Optional[HiddenText]
    ) -> CommandArgs:
        return []

    def extract_url_and_spec(self, url: HiddenText) -> Tuple[HiddenText, RevisionSpec]:
        secret_url, rev, creds = self.split_url_components(url.secret)
        user, secret_pass = creds

        password_token: Optional[HiddenText] = None
        if secret_pass:
            password_token = hide_value(secret_pass)

        extra = self.prepare_extra_args(user, password_token)
        spec = self.create_revision_spec(rev, extra_args=extra)

        return hide_url(secret_url), spec

    @staticmethod
    def standardize_url(url: str) -> str:
        """Normalize URLs by unquoting and removing trailing slashes."""
        return urllib.parse.unquote(url).rstrip("/")

    @classmethod
    def urls_match(cls, url1: str, url2: str) -> bool:
        """Compare two URLs ignoring formatting differences."""
        return cls.standardize_url(url1) == cls.standardize_url(url2)

    def fetch_new_version(
        self,
        target_dir: str,
        repo_url: HiddenText,
        spec: RevisionSpec,
        verbosity: int,
    ) -> None:
        raise NotImplementedError

    def switch_repository(
        self,
        target_dir: str,
        repo_url: HiddenText,
        spec: RevisionSpec,
    ) -> None:
        raise NotImplementedError

    def update_repository(
        self,
        target_dir: str,
        repo_url: HiddenText,
        spec: RevisionSpec,
    ) -> None:
        raise NotImplementedError

    @classmethod
    def commits_match(cls, repo_path: str, expected_id: Optional[str]) -> bool:
        raise NotImplementedError

    def install_or_update(
        self,
        target_dir: str,
        repo_url: HiddenText,
        verbosity: int,
    ) -> None:
        url, spec = self.extract_url_and_spec(repo_url)

        if not os.path.exists(target_dir):
            self.fetch_new_version(target_dir, url, spec, verbosity)
            return

        rev_desc = spec.to_string()

        if self.is_repository_location(target_dir):
            current_url = self.get_remote_url(target_dir)

            if self.urls_match(current_url, url.secret):
                logger.debug(
                    "%s already exists at %s with correct URL (%s)",
                    self.repo_display_name,
                    display_path(target_dir),
                    url,
                )

                if not self.commits_match(target_dir, spec.revision_identifier):
                    logger.info(
                        "Updating %s %s%s",
                        display_path(target_dir),
                        self.repo_display_name,
                        rev_desc,
                    )
                    self.update_repository(target_dir, url, spec)
                else:
                    logger.info("Already up-to-date.")
                return

            logger.warning(
                "%s %s at %s has different URL: %s",
                self.identifier,
                self.repo_display_name,
                display_path(target_dir),
                current_url,
            )
            choices = ("(s)witch, (i)gnore, (w)ipe, (b)ackup ", ("s", "i", "w", "b"))
        else:
            logger.warning(
                "Directory %s exists but is not a %s %s.",
                target_dir,
                self.identifier,
                self.repo_display_name,
            )
            choices = ("(i)gnore, (w)ipe, (b)ackup ", ("i", "w", "b"))  # type: ignore

        logger.warning(
            "Will attempt to install %s repository %s",
            self.identifier,
            url,
        )

        response = ask_path_exists(f"Action? {choices[0]}", choices[1])

        if response == "a":
            sys.exit(-1)

        if response == "w":
            logger.warning("Removing %s", display_path(target_dir))
            rmtree(target_dir)
            self.fetch_new_version(target_dir, url, spec, verbosity)
            return

        if response == "b":
            backup_path = backup_dir(target_dir)
            logger.warning("Backing up %s to %s", display_path(target_dir), backup_path)
            shutil.move(target_dir, backup_path)
            self.fetch_new_version(target_dir, url, spec, verbosity)
            return

        if response == "s":
            logger.info(
                "Switching %s %s to %s%s",
                self.repo_display_name,
                display_path(target_dir),
                url,
                rev_desc,
            )
            self.switch_repository(target_dir, url, spec)

    def extract_to_location(
        self,
        target_path: str,
        repo_url: HiddenText,
        verbosity: int,
    ) -> None:
        if os.path.exists(target_path):
            rmtree(target_path)
        self.install_or_update(target_path, repo_url, verbosity)

    @classmethod
    def get_remote_url(cls, location: str) -> str:
        raise RepositoryLookupError(
            f"No remote URL configured for {location}"
        )

    @classmethod
    def get_current_commit_hash(cls, location: str) -> str:
        raise NotImplementedError

    @classmethod
    def execute_command(
        cls,
        cmd: Union[List[str], CommandArgs],
        show_output: bool = True,
        working_dir: Optional[str] = None,
        on_failure: 'Literal["raise", "warn", "ignore"]' = "raise",
        acceptable_codes: Optional[Iterable[int]] = None,
        description: Optional[str] = None,
        env_overrides: Optional[Mapping[str, Any]] = None,
        spinner: Optional[SpinnerInterface] = None,
        log_errors: bool = True,
        capture_only: bool = False,
    ) -> str:
        full_cmd = make_command(cls.identifier, *cmd)
        if description is None:
            description = format_command_args(full_cmd)

        try:
            return call_subprocess(
                full_cmd,
                show_output,
                working_dir,
                on_returncode=on_failure,
                extra_ok_returncodes=acceptable_codes,
                command_desc=description,
                extra_environ=env_overrides,
                unset_environ=cls.env_vars_to_unset,
                spinner=spinner,
                log_failed_cmd=log_errors,
                stdout_only=capture_only,
            )
        except FileNotFoundError:
            raise BadCommand(
                f"Executable '{cls.identifier}' not found. Is it installed and in PATH?"
            )
        except PermissionError:
            raise BadCommand(
                f"Permission denied executing '{cls.identifier}'. "
                "Install locally or check permissions."
            )

    @classmethod
    def is_repository_location(cls, path: str) -> bool:
        marker = os.path.join(path, cls.directory_marker)
        logger.debug("Checking for %s (%s) in %s...", cls.directory_marker, cls.identifier, path)
        return os.path.exists(marker)

    @classmethod
    def find_repository_root(cls, location: str) -> Optional[str]:
        if cls.is_repository_location(location):
            return location
        return None

from dataclasses import dataclass, field
from typing import Optional, Dict, List, Any
from functools import cached_property
import logging

logger = logging.getLogger(__name__)

@dataclass
class MacElementNode:
    """Represents a macOS UI element with enhanced accessibility metadata."""
    # Core attributes
    role: str
    identifier: str
    meta: Dict[str, Any]
    visible: bool
    pid: int
    displayed: bool

    # Structural & behavioral fields
    subnodes: List['MacElementNode'] = field(default_factory=list)
    superior: Optional['MacElementNode'] = None
    clickable: bool = False
    marker: Optional[int] = None
    _raw_ax_obj = None  # Retain AX element reference

    # --- Property-based accessors ---
    @property
    def commands(self) -> List[str]:
        """Retrieve supported actions for this element."""
        return self.meta.get('actions', [])

    @property
    def active(self) -> bool:
        """Determine if the element is currently enabled."""
        return self.meta.get('enabled', True)

    @property
    def origin(self) -> Optional[tuple]:
        """Return top-left coordinate."""
        return self.meta.get('position')

    @property
    def dimensions(self) -> Optional[tuple]:
        """Return width and height."""
        return self.meta.get('size')

    def __str__(self) -> str:
        """Human-readable string representation."""
        base = f'<{self.role}'
        key_attrs = ['title', 'value', 'description', 'enabled']
        for attr in key_attrs:
            if attr in self.meta:
                base += f' {attr}="{self.meta[attr]}"'
        if self.origin:
            base += f' at={self.origin}'
        if self.dimensions:
            base += f' dims={self.dimensions}'
        base += '>'

        extras = []
        if self.clickable:
            extras.append('click')
            if self.commands:
                extras.append(f'cmd={self.commands}')
        if self.marker is not None:
            extras.append(f'marker:{self.marker}')
        if not self.active:
            extras.append('inactive')
        if extras:
            base += f' [{", ".join(extras)}]'
        return base

    # Short-form representation (used internally)
    def _compact_repr(self) -> str:
        """
        Compact summary format:
         - prefix: marker or '_'
         - role
         - title/description if present
         - position/size if available
         - interactivity info
        """
        prefix = str(self.marker) if self.marker is not None else '_'
        role_part = f'<{self.role}'
        if 'title' in self.meta:
            role_part += f' title="{self.meta["title"]}"'
        if 'description' in self.meta:
            role_part += f' desc="{self.meta["description"]}"'
        pos = self.meta.get('position')
        dim = self.meta.get('size')
        if pos and dim:
            role_part += f' pos={pos} size={dim}'
        role_part += '>'

        notes = []
        if self.clickable:
            notes.append('click')
            if self.commands:
                notes.append(f'cmd={self.commands}')
        if notes:
            role_part += f' [{", ".join(note for note in notes)}]'
        return f'{prefix}[:]{role_part}'

    # Full-detail tree serialization
    def _build_tree_verbose(self) -> str:
        """Generate verbose tree view focusing on interactive/context elements."""
        lines = []

        def traverse(node: 'MacElementNode') -> None:
            if node.marker is None or not node.displayed:
                return
            if node.role in {'AXStaticText', 'AXGroup', 'AXImage'}:
                return

            details = ''
            keys = ['title', 'value', 'description', 'position', 'size']
            for k in keys:
                if k in node.meta:
                    if k == 'position':
                        details += f' Top left: "{node.meta[k]}"'
                    else:
                        details += f'(w,h): "{node.meta[k]}"'
            if details:
                lines.append(f'{node.marker}[:]<{node.role}{details}>')

            for child in node.subnodes:
                traverse(child)

        traverse(self)
        return '\n'.join(lines)

    # Condensed tree serialization
    def _build_tree_compact(self) -> str:
        """
        Optimized tree view:
         - Deduplicates by (role, description)
         - Uses compact representation
        """
        lines = []
        seen = set()

        def traverse(node: 'MacElementNode') -> None:
            if node.marker is None or not node.displayed:
                return

            details = ''
            keys = ['title', 'value', 'description', 'enabled', 'position', 'size']
            for k in keys:
                if k in node.meta:
                    if k == 'position':
                        details += f' Top left: "{node.meta[k]}"'
                    else:
                        details += f'(w,h): "{node.meta[k]}"'

            line = f'{node.marker}[:]<{node.role}{details}> [interactive]'
            lines.append(line)

            # Contextual text elements (non-interactive)
            key_roles = {'AXStaticText', 'AXTextField'}
            if (node.role in key_roles and
                not node.clickable and
                (node.superior is None or
                 node.superior.role == 'AXWindow' or
                 node.superior.clickable)):
                context_line = f'_[:]<{node.role}{details}> [context]'
                if context_line not in seen:
                    seen.add(context_line)
                    lines.append(context_line)

            for child in node.subnodes:
                traverse(child)

        traverse(self)
        return '\n'.join(lines)

    def build_tree(self) -> str:
        """Select appropriate tree view based on token budget."""
        def estimate_tokens(text: str, factor: int = 3) -> int:
            return len(text) // factor

        original = self._build_tree_compact()
        tokens = estimate_tokens(original)
        if tokens > 10000:
            logger.debug("Token limit exceeded; skipping UI rendering.")
            return ''
        else:
            logger.debug(f"Using verbose mode ({tokens} tokens).")
            return self._build_tree_verbose()

    def describe_full(self) -> str:
        """Comprehensive attribute listing."""
        parts = [
            f"Role: {self.role}",
            f"ID: {self.identifier}",
            f"Click: {self.clickable}",
            f"Active: {self.active}",
            f"Visible: {self.visible}"
        ]
        if self.commands:
            parts.append(f"Commands: {self.commands}")
        if self.origin:
            parts.append(f"Origin: {self.origin}")
        if self.dimensions:
            parts.append(f"Dimensions: {self.dimensions}")
        for k, v in self.meta.items():
            if k not in {'actions', 'enabled', 'position', 'size'}:
                parts.append(f"{k}: {v}")
        return ", ".join(parts)

    def describe_recursive(self, level: int = 0) -> str:
        """Recursive detailed description."""
        indent = "  " * level
        output = f"{indent}{self}\n{indent}Details: {self.describe_full()}"
        for child in self.subnodes:
            output += "\n" + child.describe_recursive(level + 1)
        return output

    @cached_property
    def path(self) -> str:
        """Construct unique accessibility path from root."""
        segments = []
        current = self
        while current.superior:
            role = current.role
            identifiers = []
            if 'title' in current.meta:
                identifiers.append(f"title={current.meta['title']}")
            if 'description' in current.meta:
                identifiers.append(f"desc={current.meta['description']}")

            siblings = [s for s in current.superior.subnodes if s.role == role]
            if len(siblings) > 1:
                idx = siblings.index(current) + 1
                seg = f"{role}[{idx}]"
            else:
                seg = role

            if identifiers:
                seg += f"({','.join(identifiers)})"
            segments.append(seg)
            current = current.superior

        segments.reverse()
        return '/' + '/'.join(segments)

    def locate_by_path(self, target_path: str) -> Optional['MacElementNode']:
        """Find element matching given accessibility path."""
        if self.path == target_path:
            return self
        for child in self.subnodes:
            found = child.locate_by_path(target_path)
            if found:
                return found
        return None

    def locate_by_command(self, action: str) -> List['MacElementNode']:
        """Collect all elements supporting specified action."""
        results = []
        if action in self.commands:
            results.append(self)
        for child in self.subnodes:
            results.extend(child.locate_by_command(action))
        return results

