def _sync_if_cuda(device):
    """Return a synchronization function for CUDA devices."""
    def sync():
        if device == "cuda" and torch.cuda.is_available():
            torch.cuda.synchronize()
    return sync


def _run_benchmarked_call(func, *args, device="cpu"):
    """Execute function with optional CUDA sync after execution."""
    result = func(*args)
    _sync_if_cuda(device)()
    return result


