import re
from abc import ABC, abstractmethod
from collections import namedtuple
from dataclasses import dataclass, field
from typing import Optional, Union, List
from typing import Sequence, Dict, Set
import json
from typing_extensions import override
from mindspeed_mm.data.data_utils.func_utils.tool_utils import get_tool_utils

# Type alias for slot definitions
SlotsDef = Sequence[Union[str, Set[str], Dict[str, str]]]


@dataclass
class BaseFormatter(ABC):
    slots: SlotsDef = field(default_factory=list)
    tool_syntax: Optional[str] = None

    @abstractmethod
    def encode(self, **context) -> SlotsDef:
        r"""
        Constructs a structured list of text segments based on input context.
        """
        ...

    def decode(self, response_text: str) -> Union[str, List["ToolCall"]]:
        r"""
        Parses function calls from model output when tools are used.
        """
        raise NotImplementedError


@dataclass
class NullFormatter(BaseFormatter):
    def __post_init__(self):
        found_var = False
        for part in filter(lambda x: isinstance(x, str), self.slots):
            if re.search(r"\{\{[a-zA-Z_][a-zA-Z0-9_]*\}\}", part):
                found_var = True
                break
        if found_var:
            raise ValueError("Null formatter must not contain any placeholders.")

    def encode(self, **context) -> SlotsDef:
        return self.slots.copy()


@dataclass
class TextFormatter(BaseFormatter):
    def __post_init__(self):
        has_var = False
        for segment in filter(lambda s: isinstance(s, str), self.slots):
            if re.search(r"\{\{[a-zA-Z_][a-zA-Z0-9_]*\}\}", segment):
                has_var = True
                break
        if not has_var:
            raise ValueError("Text formatter requires at least one placeholder variable.")

    def encode(self, **context) -> SlotsDef:
        result = []
        for seg in self.slots:
            if isinstance(seg, str):
                for var_name, val in context.items():
                    if not isinstance(val, str):
                        raise TypeError(f"Expected string value for '{var_name}', got {type(val).__name__}")
                    seg = seg.replace("{{" + var_name + "}}", val, 1)
                result.append(seg)
            elif isinstance(seg, (dict, set)):
                result.append(seg)
            else:
                raise TypeError(f"Unsupported type in slots: {type(seg)}")
        return result


# Named tuple to represent a parsed function call
ToolCall = namedtuple("ToolCall", ["func_name", "args_json"])


@dataclass
class FuncFormatter(TextFormatter):
    def __post_init__(self):
        super().__post_init__()
        self._tool_engine = get_tool_utils(self.tool_syntax)

    @override
    def encode(self, **context) -> SlotsDef:
        raw_text = context.pop("message")
        thought_delimiters = context.pop("thought_markers", None)
        tool_delimiters = context.pop("tool_markers", None)

        def _extract_calls(json_str: str) -> List[ToolCall]:
            try:
                parsed = json.loads(json_str)
                if not isinstance(parsed, list):
                    parsed = [parsed]
                return [ToolCall(tc["function"], json.dumps(tc["params"], ensure_ascii=False)) for tc in parsed]
            except json.JSONDecodeError:
                raise ValueError(f"Malformed JSON in function message: {repr(raw_text)}")

        tool_match = None
        if tool_delimiters and len(tool_delimiters) == 2:
            pattern = re.compile(
                rf"{re.escape(tool_delimiters[0])}(.*?){re.escape(tool_delimiters[1])}", re.DOTALL
            )
            tool_match = pattern.search(raw_text)

        if tool_match is None:
            thought_match = None
            if thought_delimiters and len(thought_delimiters) == 2:
                thought_pattern = re.compile(
                    rf"{re.escape(thought_delimiters[0])}(.*?){re.escape(thought_delimiters[1])}", re.DOTALL
                )
                thought_match = thought_pattern.search(raw_text)
            if thought_match:
                core_content = raw_text.replace(thought_match.group(0), "")
            else:
                core_content = raw_text
            funcs = _extract_calls(core_content)
            formatted_funcs = self._tool_engine.format_functions(funcs)
            if thought_match:
                formatted_funcs = thought_match.group(0) + formatted_funcs
        else:
            non_tool_part = raw_text.replace(tool_match.group(0), "")
            funcs = _extract_calls(tool_match.group(1))
            formatted_funcs = self._tool_engine.format_functions(funcs)
            formatted_funcs = non_tool_part + formatted_funcs

        return super().encode(message=formatted_funcs)


@dataclass
class ToolSpecFormatter(BaseFormatter):
    def __post_init__(self):
        self._engine = get_tool_utils(self.tool_syntax)

    @override
    def encode(self, **context) -> SlotsDef:
        spec_json = context.pop("spec")
        try:
            tools_list = json.loads(spec_json)
            return [self._engine.format_tools(tools_list)] if tools_list else [""]
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON in tool specification: {repr(spec_json)}")

    @override
    def decode(self, response_text: str) -> Union[str, List[ToolCall]]:
        return self._engine.extract_tools(response_text)

# LLM Gateway Client - Unified Interface for Multiple AI Providers
# Supports 70+ models across OpenAI, Anthropic, Google, Meta, Mistral, and more

import argparse
import io
import json
import os
import sys
import urllib.request
import urllib.error
from typing import Any, Dict, Generator, List, Optional

# Ensure UTF-8 output on Windows platforms
if sys.platform == "win32":
    sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
    sys.stderr = io.TextIOWrapper(sys.stderr.buffer, encoding="utf-8", errors="replace")


class AISA_Client:
    """Unified client for accessing multiple LLM providers through AIsa API."""

    API_ENDPOINT = "https://api.aisa.one/v1"

    # Model families and their supported models (check marketplace.aisa.one/pricing for updates)
    MODEL_FAMILIES = {
        "openai": ["gpt-5.2", "gpt-5", "gpt-5-mini", "gpt-4.1", "gpt-4.1-mini", "gpt-4o", "gpt-4o-mini", "gpt-oss-120b"],
        "anthropic": ["claude-sonnet-4-5-20250929", "claude-opus-4-1-20250805", "claude-opus-4-20250514", "claude-sonnet-4-20250514", "claude-haiku-4-5-20251001", "claude-3-7-sonnet-20250219"],
        "google": ["gemini-2.5-pro", "gemini-2.5-flash", "gemini-2.5-flash-lite", "gemini-3-pro-preview"],
        "xai": ["grok-4", "grok-3"],
        "meta": ["llama-3.1-405b", "llama-3.1-70b", "llama-3.1-8b"],
        "mistral": ["mistral-large", "mistral-medium", "mixtral-8x7b"],
    }

    def __init__(self, key: Optional[str] = None):
        """Initialize with API key from parameter or environment variable."""
        self.api_key = key or os.environ.get("AISA_API_KEY")
        if not self.api_key:
            raise ValueError(
                "AISA_API_KEY is required. Set it via environment variable or pass to constructor."
            )

    def _send_request(
        self, 
        http_method: str, 
        path: str, 
        payload: Optional[Dict[str, Any]] = None,
        streaming: bool = False
    ) -> Any:
        """Send HTTP request to AIsa API endpoint."""
        full_url = f"{self.API_ENDPOINT}{path}"

        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "User-Agent": "OpenClaw-LLMRouter/1.0",
            "Accept": "application/json"
        }

        body_data = None
        if payload:
            body_data = json.dumps(payload).encode("utf-8")

        request_obj = urllib.request.Request(full_url, data=body_data, headers=headers, method=http_method)

        try:
            response = urllib.request.urlopen(request_obj, timeout=120)

            if streaming:
                return self._process_stream(response)
            else:
                return json.loads(response.read().decode("utf-8"))

        except urllib.error.HTTPError as err:
            error_content = err.read().decode("utf-8")
            try:
                return json.loads(error_content)
            except json.JSONDecodeError:
                return {"error": {"code": str(err.code), "message": error_content}}
        except urllib.error.URLError as err:
            return {"error": {"code": "NETWORK_ERROR", "message": str(err.reason)}}

    def _process_stream(self, response) -> Generator[str, None, None]:
        """Process Server-Sent Events (SSE) stream."""
        for line in response:
            decoded_line = line.decode("utf-8").strip()
            if decoded_line.startswith("data: "):
                event_data = decoded_line[6:]
                if event_data == "[DONE]":
                    break
                try:
                    parsed = json.loads(event_data)
                    if "choices" in parsed and parsed["choices"]:
                        delta = parsed["choices"][0].get("delta", {})
                        text = delta.get("content", "")
                        if text:
                            yield text
                except json.JSONDecodeError:
                    continue

    def generate_completion(
        self,
        model_name: str,
        conversation: List[Dict[str, str]],
        temp: Optional[float] = None,
        max_len: Optional[int] = None,
        nucleus: Optional[float] = None,
        do_stream: bool = False,
        **extra_params
    ) -> Dict[str, Any]:
        """
        Generate chat completion using specified model.

        Args:
            model_name: Identifier of the model to use
            conversation: List of message dictionaries with 'role' and 'content'
            temp: Sampling temperature (0-2 range)
            max_len: Maximum number of tokens to generate
            nucleus: Nucleus sampling probability threshold
            do_stream: Whether to stream the response
            **extra_params: Additional parameters like functions, function_call, etc.

        Returns:
            Completion response dictionary
        """
        request_body = {
            "model": model_name,
            "messages": conversation,
            "stream": do_stream
        }

        if temp is not None:
            request_body["temperature"] = temp
        if max_len is not None:
            request_body["max_tokens"] = max_len
        if nucleus is not None:
            request_body["top_p"] = nucleus

        # Merge additional parameters
        request_body.update(extra_params)

        return self._send_request("POST", "/chat/completions", data=request_body, stream=do_stream)

    def generate_streaming_completion(
        self,
        model_name: str,
        conversation: List[Dict[str, str]],
        **extra_params
    ) -> Generator[str, None, None]:
        """
        Generate streaming chat completion.

        Yields content chunks as they arrive from the server.
        """
        return self.generate_completion(model_name=model_name, conversation=conversation, do_stream=True, **extra_params)

    def analyze_image(
        self,
        model_name: str,
        image_source: str,
        query: str,
        **extra_params
    ) -> Dict[str, Any]:
        """
        Analyze an image using a vision-capable model.

        Args:
            model_name: Vision-capable model identifier (e.g., gpt-4o, gemini-1.5-pro)
            image_source: URL of the image to analyze
            query: Question or instruction about the image

        Returns:
            Chat completion response
        """
        messages = [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": query},
                    {"type": "image_url", "image_url": {"url": image_source}}
                ]
            }
        ]
        return self.generate_completion(model_name=model_name, conversation=messages, **extra_params)

    def benchmark_models(
        self,
        model_list: List[str],
        test_message: str,
        **extra_params
    ) -> Dict[str, Any]:
        """
        Compare responses from multiple models.

        Args:
            model_list: List of model identifiers to compare
            test_message: The message to send to each model

        Returns:
            Dictionary with model names as keys and performance metrics as values
        """
        import time

        benchmark_results = {}
        for model_id in model_list:
            start_time = time.time()
            try:
                response = self.generate_completion(
                    model_name=model_id,
                    conversation=[{"role": "user", "content": test_message}],
                    **extra_params
                )
                elapsed_time = time.time() - start_time

                if "error" in response:
                    benchmark_results[model_id] = {
                        "success": False,
                        "error_details": response["error"],
                        "latency_seconds": elapsed_time
                    }
                else:
                    content = response.get("choices", [{}])[0].get("message", {}).get("content", "")
                    usage_stats = response.get("usage", {})
                    benchmark_results[model_id] = {
                        "success": True,
                        "response_text": content,
                        "latency_seconds": elapsed_time,
                        "token_count": usage_stats.get("total_tokens", 0),
                        "estimated_cost": usage_stats.get("cost", 0)
                    }
            except Exception as exception:
                benchmark_results[model_id] = {
                    "success": False,
                    "error_details": str(exception),
                    "latency_seconds": time.time() - start_time
                }

        return benchmark_results

    def get_available_models(self) -> Dict[str, List[str]]:
        """Return available model families and their supported models."""
        return self.MODEL_FAMILIES


def cli_entry():
    """Command-line interface entry point."""
    parser = argparse.ArgumentParser(
        description="LLM Router - Unified Model Gateway (70+ models)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
    %(prog)s chat --model gpt-4.1 --message "Hello!"
    %(prog)s chat --model claude-sonnet-4-5 --message "Write a poem" --stream
    %(prog)s chat --model gpt-4 --system "You are a pirate" --message "Greet me"
    %(prog)s vision --model gpt-4o --image "https://example.com/img.jpg" --prompt "Describe this"
    %(prog)s compare --models "gpt-4.1,claude-sonnet-4-5" --message "Explain AI"
    %(prog)s models
        """
    )

    command_subparsers = parser.add_subparsers(dest="action", help="Available commands")

    # Chat command configuration
    chat_parser = command_subparsers.add_parser("chat", help="Send a chat completion request")
    chat_parser.add_argument("--model", "-m", required=True, help="Model identifier")
    chat_parser.add_argument("--message", help="User message")
    chat_parser.add_argument("--messages", help="Full messages array as JSON")
    chat_parser.add_argument("--system", "-s", help="System prompt")
    chat_parser.add_argument("--temperature", "-t", type=float, help="Temperature (0-2)")
    chat_parser.add_argument("--max-tokens", type=int, help="Max tokens to generate")
    chat_parser.add_argument("--stream", action="store_true", help="Stream the response")

    # Vision command configuration
    vision_parser = command_subparsers.add_parser("vision", help="Analyze an image")
    vision_parser.add_argument("--model", "-m", required=True, help="Vision-capable model")
    vision_parser.add_argument("--image", "-i", required=True, help="Image URL")
    vision_parser.add_argument("--prompt", "-p", required=True, help="Question about the image")
    vision_parser.add_argument("--max-tokens", type=int, help="Max tokens to generate")

    # Compare command configuration
    compare_parser = command_subparsers.add_parser("compare", help="Compare multiple models")
    compare_parser.add_argument("--models", required=True, help="Comma-separated model list")
    compare_parser.add_argument("--message", "-m", required=True, help="Message to send")
    compare_parser.add_argument("--temperature", "-t", type=float, help="Temperature")
    compare_parser.add_argument("--max-tokens", type=int, help="Max tokens")

    # Models listing command
    command_subparsers.add_parser("models", help="List supported models")

    arguments = parser.parse_args()

    if not arguments.action:
        parser.print_help()
        sys.exit(1)

    # Models command doesn't require authentication
    if arguments.action == "models":
        print(json.dumps(AISA_Client.MODEL_FAMILIES, indent=2))
        sys.exit(0)

    try:
        gateway_client = AISA_Client()
    except ValueError as auth_error:
        print(json.dumps({"error": {"code": "AUTH_ERROR", "message": str(auth_error)}}))
        sys.exit(1)

    result_data = None

    if arguments.action == "chat":
        # Build messages array
        if arguments.messages:
            messages_array = json.loads(arguments.messages)
        elif arguments.message:
            messages_array = []
            if arguments.system:
                messages_array.append({"role": "system", "content": arguments.system})
            messages_array.append({"role": "user", "content": arguments.message})
        else:
            print(json.dumps({"error": {"code": "INVALID_INPUT", "message": "Either --message or --messages is required"}}))
            sys.exit(1)

        extra_options = {}
        if arguments.temperature is not None:
            extra_options["temperature"] = arguments.temperature
        if arguments.max_tokens is not None:
            extra_options["max_tokens"] = arguments.max_tokens

        if arguments.stream:
            # Streaming mode
            try:
                for token_chunk in gateway_client.generate_streaming_completion(
                    model_name=arguments.model, 
                    conversation=messages_array, 
                    **extra_options
                ):
                    print(token_chunk, end="", flush=True)
                print()  # Final newline
                sys.exit(0)
            except Exception as stream_error:
                print(json.dumps({"error": {"code": "STREAM_ERROR", "message": str(stream_error)}}))
                sys.exit(1)
        else:
            result_data = gateway_client.generate_completion(
                model_name=arguments.model, 
                conversation=messages_array, 
                **extra_options
            )

    elif arguments.action == "vision":
        extra_options = {}
        if arguments.max_tokens is not None:
            extra_options["max_tokens"] = arguments.max_tokens
        result_data = gateway_client.analyze_image(
            model_name=arguments.model,
            image_source=arguments.image,
            query=arguments.prompt,
            **extra_options
        )

    elif arguments.action == "compare":
        model_ids = [m.strip() for m in arguments.models.split(",")]
        extra_options = {}
        if arguments.temperature is not None:
            extra_options["temperature"] = arguments.temperature
        if arguments.max_tokens is not None:
            extra_options["max_tokens"] = arguments.max_tokens
        result_data = gateway_client.benchmark_models(
            model_list=model_ids, 
            test_message=arguments.message, 
            **extra_options
        )

    if result_data:
        output_json = json.dumps(result_data, indent=2, ensure_ascii=False)
        try:
            print(output_json)
        except UnicodeEncodeError:
            print(json.dumps(result_data, indent=2, ensure_ascii=True))

        # Exit with error code if result contains error
        if isinstance(result_data, dict) and "error" in result_data:
            sys.exit(1)
        sys.exit(0)


