def _fetch_fused_mapping(model_type: str) -> dict[str, list[str]]:
    """Retrieve fused module mapping for a given model type."""
    return FUSED_MODULE_MAP.get(model_type, {})


def _fetch_prefix_remap(model_type: str) -> dict[str, str]:
    """Get prefix remapping for a given model type."""
    return PREFIX_REMAP_RULES.get(model_type, {})


def _determine_layer_precision(
    desc: dict[str, Any],
    layer_prefix: str,
    fused_map: dict[str, list[str]],
) -> str | None:
    """Determine quantization precision for a linear layer."""
    proj_name = layer_prefix.split(".")[-1]
    if proj_name in fused_map:
        shard_names = [layer_prefix.replace(proj_name, s) for s in fused_map[proj_name]]
        precisions = {desc[s + ".weight"] for s in shard_names}
        if len(precisions) > 1:
            raise ValueError(f"Shards of {layer_prefix} have inconsistent precisions: {precisions}")
        return next(iter(precisions)) if precisions else None
    return desc.get(layer_prefix + ".weight")


def _get_quant_precision_for(
    desc: dict[str, Any],
    layer_prefix: str,
    layer_kind: str,
    fused_map: dict[str, list[str]] | None = None,
) -> str | None:
    """Get quantization type based on layer kind."""
    fused_map = fused_map or {}
    if layer_kind == "attention" and "fa_quant_type" in desc:
        return desc["fa_quant_type"]
    return _determine_layer_precision(desc, layer_prefix, fused_map)


def _instantiate_scheme(
    desc: dict[str, Any],
    layer_prefix: str,
    layer_kind: str,
    fused_map: dict[str, list[str]] | None = None,
):
    """Create a quantization scheme instance for a layer."""
    logger.info_once("Using the vLLM Ascend modelslim Quantization now!")
    qtype = _get_quant_precision_for(desc, layer_prefix, layer_kind, fused_map)
    if qtype is None:
        raise ValueError(f"Could not determine quantization type for layer {layer_prefix}.")
    cls = get_scheme_class(qtype, layer_kind)
    if cls is not None:
        return cls()
    raise NotImplementedError(f"vLLM Ascend does not support {qtype} for {layer_kind}.")


@register_quantization_config(ASCEND_QUANTIZATION_METHOD)
class AscendModelSlimConfig(QuantizationConfig):
    """Configuration class for Ascend ModelSlim quantization."""

    def __init__(self, config_data: dict[str, Any] | None = None):
        super().__init__()
        self._quant_desc = config_data or {}
        self._apply_adaptations()

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}:\n{super().__repr__()}"

    @classmethod
    def get_name(cls) -> str:
        return ASCEND_QUANTIZATION_METHOD

    @classmethod
    def get_supported_act_dtypes(cls) -> list[torch.dtype]:
        return [torch.int8, torch.float16, torch.bfloat16]

    @classmethod
    def get_min_capability(cls) -> int:
        raise NotImplementedError('Ascend hardware does not support "get_min_capability".')

    @classmethod
    def get_config_filenames(cls) -> list[str]:
        return []

    @classmethod
    def from_config(cls, cfg: dict[str, Any]) -> "AscendModelSlimConfig":
        return cls(cfg)

    @classmethod
    def override_quantization_method(cls, hf_cfg, user_cfg) -> str | None:
        if hf_cfg is not None:
            method = hf_cfg.get("quant_method")
            if not method and torch.npu.is_available():
                return ASCEND_QUANTIZATION_METHOD
        return None

    def _remap_prefix(self, model_type: str, prefix: str) -> str:
        """Apply prefix remapping if available."""
        rule = _fetch_prefix_remap(model_type)
        if rule:
            mapper = WeightsMapper(orig_to_new_prefix=rule)
            return mapper._map_name(prefix)
        return prefix

    def _is_skipped(self, prefix: str, fused_map: Mapping[str, list[str]]) -> bool:
        """Check whether a layer should be skipped (i.e., unquantized)."""
        proj = prefix.split(".")[-1]
        if proj in fused_map:
            shards = [prefix.replace(proj, s) for s in fused_map[proj]]
            flags = [self._quant_desc[s + ".weight"] == "FLOAT" for s in shards]
            if len(set(flags)) > 1:
                raise ValueError(f"Inconsistent skip status for shards of {prefix}")
            return any(flags)
        return any(
            k.startswith(prefix) and k.endswith(".weight") and v == "FLOAT"
            for k, v in self._quant_desc.items()
        )

    def _apply_adaptations(self) -> None:
        """Apply known key adaptations to quantization description."""
        adapted = {}
        for key, val in self._quant_desc.items():
            if "shared_head" in key:
                new_key = key.replace(".shared_head.", ".")
                adapted[new_key] = val
            if "weight_packed" in key:
                new_key = key.replace("weight_packed", "weight")
                adapted[new_key] = val
        self._quant_desc.update(adapted)

    def get_scaled_act_names(self) -> list[str]:
        return []

    def get_quant_method(self, layer: torch.nn.Module, prefix: str) -> Optional["QuantizeMethodBase"]:
        from .method_adapters import (
            AscendEmbeddingMethod,
            AscendFusedMoEMethod,
            AscendKVCacheMethod,
            AscendLinearMethod,
        )
        vllm_cfg = get_current_vllm_config()
        model_type = vllm_cfg.model_config.hf_config.model_type

        # Special handling for Minimax models
        if model_type in ("minimax", "minimax_m2"):
            prefix = prefix.replace("mlp", "block_sparse_moe")
            parts = prefix.split(".")
            if "experts" in parts and len(parts) > 2:
                idx = parts.index("experts")
                if idx + 1 < len(parts) and parts[idx + 1].isdigit():
                    prefix = ".".join(parts[: idx + 2])

        fused_map = _fetch_fused_mapping(model_type)
        prefix = self._remap_prefix(model_type, prefix)

        # Adjust prefixes for certain models
        if model_type != "kimi_k2" and prefix.startswith("language_model"):
            prefix = prefix.split(".", 1)[-1]

        if isinstance(layer, LinearBase):
            if self._is_skipped(prefix, fused_map):
                from vllm_ascend.ops.linear import AscendUnquantizedLinearMethod
                return AscendUnquantizedLinearMethod()
            scheme = _instantiate_scheme(self._quant_desc, prefix, "linear", fused_map)
            return AscendLinearMethod(scheme)

        elif isinstance(layer, FusedMoE):
            if self._is_skipped(prefix, fused_map):
                from vllm_ascend.ops.fused_moe.fused_moe import AscendUnquantizedFusedMoEMethod
                return AscendUnquantizedFusedMoEMethod(layer.moe_config)
            scheme = _instantiate_scheme(self._quant_desc, prefix, "moe", fused_map)
            return AscendFusedMoEMethod(scheme, layer.moe_config)

        elif isinstance(layer, VocabParallelEmbedding):
            if self._is_skipped(prefix, fused_map):
                return UnquantizedEmbeddingMethod()
            scheme = _instantiate_scheme(self._quant_desc, prefix, "linear", fused_map)
            return AscendEmbeddingMethod(scheme)

        elif isinstance(layer, torch.nn.MultiheadAttention) and "fa_quant_type" in self._quant_desc:
            scheme = _instantiate_scheme(self._quant_desc, prefix, "attention", fused_map)
            return AscendKVCacheMethod(scheme)

        return None

    def maybe_update_config(self, model_path: str) -> None:
        """Load quantization config from disk if needed."""
        if self._quant_desc:
            return

        if os.path.isdir(model_path):
            full_path = os.path.join(model_path, QUANT_DESC_FILE)
            if os.path.isfile(full_path):
                with open(full_path) as fp:
                    self._quant_desc = json.load(fp)
                self._apply_adaptations()
                return

            json_files = glob.glob(os.path.join(model_path, "*.json"))
            found_jsons = [os.path.basename(f) for f in json_files]
        else:
            found_jsons = []

        msg = (
            "\n"
            + "=" * 80 + "\n"
            + "ERROR: ModelSlim Quantization Config Not Found\n"
            + "=" * 80 + "\n\n"
            + f"You enabled '--quantization {ASCEND_QUANTIZATION_METHOD}'\n"
            + f"but '{model_path}' lacks '{QUANT_DESC_FILE}'.\n\n"
            + "This usually means the model weights are NOT quantized.\n\n"
            + "Solutions:\n"
            + "  1. Remove '--quantization' flag for unquantized models\n"
            + f"     Example: vllm serve {model_path}\n\n"
            + "  2. Quantize your model using ModelSlim first\n"
            + "     See: https://gitee.com/ascend/msit/tree/master/msmodelslim\n"
            + (f"  (Found JSON files: {found_jsons})\n" if found_jsons else "")
            + "=" * 80
        )
        raise ValueError(msg)

# UTF-8 encoding detection prober implementation

from typing import Union
from .charsetprober import CharSetProber
from .codingstatemachine import CodingStateMachine
from .enums import MachineState, ProbingState
from .mbcssm import UTF8_SM_MODEL

class UTF8Prober(CharSetProber):
    # Probability factor for single multi-byte character detection
    SINGLE_CHAR_CONFIDENCE = 0.5

    def __init__(self) -> None:
        super().__init__()
        self.state_machine = CodingStateMachine(UTF8_SM_MODEL)
        self.multi_byte_count = 0
        self.reset()

    def reset(self) -> None:
        super().reset()
        self.state_machine.reset()
        self.multi_byte_count = 0

    @property
    def charset_name(self) -> str:
        return "utf-8"

    @property
    def language(self) -> str:
        return ""

    def feed(self, data: Union[bytes, bytearray]) -> ProbingState:
        for byte in data:
            state_result = self.state_machine.next_state(byte)

            if state_result == MachineState.ERROR:
                self._state = ProbingState.NOT_ME
                break
            elif state_result == MachineState.ITS_ME:
                self._state = ProbingState.FOUND_IT
                break
            elif state_result == MachineState.START:
                if self.state_machine.get_current_charlen() >= 2:
                    self.multi_byte_count += 1

        if self.state == ProbingState.DETECTING:
            if self.get_confidence() > self.SHORTCUT_THRESHOLD:
                self._state = ProbingState.FOUND_IT

        return self.state

    def get_confidence(self) -> float:
        disbelief = 0.99

        if self.multi_byte_count < 6:
            disbelief *= (self.SINGLE_CHAR_CONFIDENCE ** self.multi_byte_count)
            return 1.0 - disbelief

        return disbelief

from typing import List, Dict, Any
from ..scheduler_node import FuncType, SchedulerNode
from .base import VFoldScheduleAlgo

__all__ = ["ScheduleZBVGreedy"]

class ScheduleZBVGreedy(VFoldScheduleAlgo):
    """ZBV Greedy Pipeline Schedule - Alternative Implementation"""

    def __init__(self, pp_size: int, vpp_size: int, micro_batches: int, memory_config: str, offload: bool = False):
        assert vpp_size == 2, "ZBV Greedy requires vpp_size == 2"
        assert memory_config in ["min", "half"], "Memory config must be 'min' or 'half'"
        super().__init__(pp_size, vpp_size, micro_batches)
        self.pp_group_size = pp_size
        self.mem_config = memory_config

        # Memory delta mapping for function types
        self.memory_delta_map = {
            FuncType.F: 1,
            FuncType.B: 0,
            FuncType.W: -1,
        }

        self.offload_flag = offload

    def generate_stable_pattern_half(self) -> List[List[tuple]]:
        """Generate stable pattern for 'half' memory configuration"""
        interval_val = 3 if self.pp_size % 2 == 0 else 0
        schedule_list = []

        for stage_id in range(self.pp_size):
            # Define operations as (function_type, chunk_id, start_time)
            ops_sequence = [
                (FuncType.F, 0, stage_id * 2),
                (FuncType.F, 1, self.pp_size * 3 - stage_id - 2),
                (FuncType.B, 1, self.pp_size * 3 + interval_val + stage_id * 2 - 1),
                (FuncType.B, 0, self.pp_size * 6 + interval_val - stage_id - 2),
            ]
            schedule_list.append(ops_sequence)

        return schedule_list

    def generate_stable_pattern_min(self) -> List[List[tuple]]:
        """Generate stable pattern for 'min' memory configuration"""
        interval_val = 2 if self.pp_size % 3 == 0 else 0
        schedule_list = []

        for rank_id in range(self.pp_size):
            # Define operations as (function_type, chunk_id, start_time)
            ops_sequence = [
                (FuncType.F, 0, rank_id),
                (FuncType.F, 1, self.pp_size * 2 - rank_id - 1),
                (FuncType.B, 1, self.pp_size * 2 + interval_val + rank_id),
                (FuncType.B, 0, self.pp_size * 4 + interval_val - rank_id - 1),
            ]
            schedule_list.append(ops_sequence)

        return schedule_list

    def insert_w_nodes(self, exec_time_map: List[Dict], time_step_map: List[Dict]) -> tuple:
        """Insert W nodes into the schedule using a queue-based approach"""
        mem_usage = [None] * self.pp_size

        for rank_idx in range(self.pp_size):
            exec_time_map[rank_idx][FuncType.W] = [
                [[0 for _ in range(self.micro_batches)] for _ in range(2)]
            ]
            w_queue = []
            max_time = max(time_step_map[rank_idx].keys()) + 2
            mem_usage[rank_idx] = [0] * (max_time + 1)
            current_phase = "WARMUP"

            for t in range(max_time + 1):
                if t > 0:
                    mem_usage[rank_idx][t] = mem_usage[rank_idx][t - 1]

                if t in time_step_map[rank_idx]:
                    node = time_step_map[rank_idx][t]
                    if not hasattr(node, 'args') or node.args is None:
                        node.args = {}
                    node.args["phase"] = current_phase

                    if node.func_type == FuncType.B:
                        w_queue.append(node)

                    assert node.func_type in [FuncType.F, FuncType.B]
                    mem_usage[rank_idx][t] += self.memory_delta_map[node.func_type]

                    if node.mini_batch == 0 and node.func_type == FuncType.B and node.chunk == 0:
                        current_phase = "STEADY"
                    elif (
                        node.mini_batch == self.micro_batches - 1
                        and node.func_type == FuncType.F
                        and node.chunk == 1
                    ):
                        current_phase = "COOLDOWN"
                elif len(w_queue) > 0:
                    base_node = w_queue.pop(0)
                    w_node = SchedulerNode(
                        func_type=FuncType.W,
                        mini_batch=base_node.mini_batch,
                        chunk=base_node.chunk,
                        args={"phase": current_phase},
                    )
                    exec_time_map[rank_idx][FuncType.W][w_node.chunk][w_node.mini_batch] = t
                    time_step_map[rank_idx][t] = w_node
                    mem_usage[rank_idx][t] += self.memory_delta_map[FuncType.W]

        return exec_time_map, time_step_map, mem_usage

    def compute_earliest_time(self, rank: int, exec_time_map: List[Dict], node: SchedulerNode) -> int:
        """Calculate earliest possible execution time for a node"""
        earliest = 0

        if node.mini_batch > 0:
            prev_time = exec_time_map[rank][node.func_type][node.chunk][node.mini_batch - 1]
            earliest = max(earliest, prev_time)

        if node.func_type == FuncType.W:
            b_time = exec_time_map[rank][FuncType.B][node.chunk][node.mini_batch]
            earliest = max(earliest, b_time)
            return earliest

        direction_info = self.direction_map(rank, node.chunk, node.func_type)
        prev_rank = direction_info["prev"][0]
        prev_chunk = direction_info["recv_from_chunk"]

        if prev_rank is not None:
            prev_time = exec_time_map[prev_rank][node.func_type][prev_chunk][node.mini_batch]
            earliest = max(earliest, prev_time)
        elif node.func_type == FuncType.B:
            f_time = exec_time_map[rank][FuncType.F][node.chunk][node.mini_batch]
            earliest = max(earliest, f_time)

        return earliest + 1

    def optimize_schedule(self, exec_time_map: List[Dict], time_step_map: List[Dict], 
                         mem_usage: List[List[int]], reorder_cooldown: bool = False) -> tuple:
        """Optimize schedule by reordering operations within constraints"""
        peak_memory = max([max(mem_usage[r]) for r in range(self.pp_size)])
        max_time = max([max(time_step_map[r].keys()) for r in range(self.pp_size)])

        pending_w_nodes = [[] for _ in range(self.pp_size)]

        def try_insert(rank: int, node: SchedulerNode, target_time: int, min_time: int) -> int:
            for slot in range(min_time, target_time + 1):
                if slot not in time_step_map[rank]:  # Available slot
                    if not reorder_cooldown:
                        can_insert = True
                        for j in range(slot, target_time):
                            if mem_usage[rank][j] + self.memory_delta_map[node.func_type] > peak_memory:
                                can_insert = False
                                break
                        if not can_insert:
                            continue
                        else:
                            for j in range(slot, target_time):
                                mem_usage[rank][j] += self.memory_delta_map[node.func_type]
                            return slot
                    else:
                        return slot
            return target_time

        # Process all time steps
        for t in range(max_time + 1):
            for r in range(self.pp_size):
                if t in time_step_map[r]:
                    current_node = time_step_map[r][t]

                    if reorder_cooldown and current_node.args.get("phase") != "COOLDOWN":
                        continue

                    if current_node.func_type == FuncType.W and reorder_cooldown:
                        pending_w_nodes[r].append(current_node)
                        del time_step_map[r][t]
                        continue

                    min_time = self.compute_earliest_time(r, exec_time_map, current_node)
                    new_time = try_insert(r, current_node, t, min_time)

                    time_step_map[r][new_time] = current_node
                    exec_time_map[r][current_node.func_type][current_node.chunk][current_node.mini_batch] = new_time

                    if t != new_time:
                        del time_step_map[r][t]

        # Handle remaining W nodes
        for r in range(self.pp_size):
            for node in pending_w_nodes[r]:
                min_time = self.compute_earliest_time(r, exec_time_map, node)
                for slot in range(min_time, max_time + 1):
                    if slot not in time_step_map[r]:
                        time_step_map[r][slot] = node
                        exec_time_map[r][node.func_type][node.chunk][node.mini_batch] = slot
                        break

        return exec_time_map, time_step_map

    def build_schedule_from_pattern(self, pattern: List[List[tuple]], num_microbatches: int) -> List[Dict]:
        """Build initial schedule from pattern definition"""
        exec_time_map = [dict() for _ in range(self.pp_size)]
        time_step_map = [dict() for _ in range(self.pp_size)]

        for rank in range(self.pp_size):
            for mb in range(num_microbatches):
                for func_type, chunk, start_time in pattern[rank]:
                    if func_type not in exec_time_map[rank]:
                        exec_time_map[rank][func_type] = [
                            [0 for _ in range(num_microbatches)] for _ in range(2)
                        ]

                    actual_time = start_time + 6 * mb
                    exec_time_map[rank][func_type][chunk][mb] = actual_time

                    assert actual_time not in time_step_map[rank], \
                        f"Time conflict at step {actual_time} for rank {rank}"

                    time_step_map[rank][actual_time] = SchedulerNode(
                        func_type=func_type, mini_batch=mb, chunk=chunk, args=None
                    )

        # Insert W nodes and optimize
        exec_time_map, time_step_map, mem_usage = self.insert_w_nodes(exec_time_map, time_step_map)
        exec_time_map, time_step_map = self.optimize_schedule(exec_time_map, time_step_map, mem_usage)
        exec_time_map, time_step_map = self.optimize_schedule(exec_time_map, time_step_map, mem_usage, True)

        return time_step_map

    def create_schedule(self) -> List[Dict]:
        """Main method to generate full schedule table"""
        pattern_generators = {
            "min": self.generate_stable_pattern_min,
            "half": self.generate_stable_pattern_half,
        }

        generator_func = pattern_generators[self.mem_config]
        time_step_map = self.build_schedule_from_pattern(generator_func(), self.micro_batches)

        # Build final schedule representation
        self.time_step_nodes = [dict() for _ in range(self.pp_size)]
        for rank in range(self.pp_size):
            for time_step in sorted(time_step_map[rank].keys()):
                node = time_step_map[rank][time_step]
                self._insert_compute_node(
                    rank, node.mini_batch, node.chunk, node.func_type, time_step
                )

        schedule_table = self._calculate_schedule_table_by_time_step_nodes()

        if self.offload_flag:
            schedule_table = self.add_offload_nodes_to_schedule_table(schedule_table)

        return schedule_table

import torch
import torch.nn as nn
from functools import partial
from typing import Any, Callable, Dict, List, Type, TypeVar, Union, overload

T = TypeVar("T")

def add(m1: torch.Tensor, m2: torch.Tensor, inplace: bool) -> torch.Tensor:
    # Alternative implementation using torch.add instead of operators
    if not inplace:
        return torch.add(m1, m2)
    else:
        m1.add_(m2)
        return m1

def permute_final_dims(tensor: torch.Tensor, dims_to_move: List[int]) -> torch.Tensor:
    # Use negative indexing consistently and build permutation list differently
    original_shape = tensor.shape
    n_dims = len(original_shape)
    move_indices = [n_dims + i for i in dims_to_move]  # Convert negative indices
    keep_indices = [i for i in range(n_dims - len(dims_to_move))]
    permutation = keep_indices + move_indices
    return tensor.permute(permutation)

def flatten_final_dims(t: torch.Tensor, num_dims: int) -> torch.Tensor:
    # Use prod() to calculate new shape instead of tuple concatenation
    if num_dims == 0:
        return t
    original_shape = t.shape
    flattened_size = 1
    for i in range(1, num_dims + 1):
        flattened_size *= original_shape[-i]
    new_shape = original_shape[:-num_dims] + (flattened_size,)
    return t.reshape(new_shape)

def masked_mean(mask: torch.Tensor, value: torch.Tensor, dim: int, eps: float = 1e-4) -> torch.Tensor:
    # Expand mask only where needed and use clamp for numerical stability
    expanded_mask = mask.unsqueeze(dim).expand_as(value) if mask.dim() < value.dim() else mask
    numerator = torch.sum(expanded_mask * value, dim=dim)
    denominator = torch.clamp(torch.sum(expanded_mask, dim=dim), min=eps)
    return numerator / denominator

def pts_to_distogram(
    pts: torch.Tensor, 
    min_bin: torch.types.Number = 2.3125, 
    max_bin: torch.types.Number = 21.6875, 
    no_bins: int = 64
) -> torch.Tensor:
    # Create boundaries with explicit device handling and use torch.searchsorted
    boundaries = torch.linspace(min_bin, max_bin, no_bins - 1, device=pts.device)
    # Compute pairwise distances more efficiently
    diff = pts.unsqueeze(-2) - pts.unsqueeze(-3)
    dists = torch.sqrt(torch.sum(diff * diff, dim=-1))
    # Use searchsorted instead of bucketize for clearer semantics
    return torch.searchsorted(boundaries, dists, right=True)

def dict_multimap(fn: Callable[[list], Any], dicts: List[dict]) -> dict:
    # Use dictionary comprehension and handle empty list case
    if not dicts:
        return {}

    result = {}
    keys = dicts[0].keys()
    for key in keys:
        values_list = [d[key] for d in dicts]
        if isinstance(dicts[0][key], dict):
            result[key] = dict_multimap(fn, values_list)
        else:
            result[key] = fn(values_list)
    return result

def one_hot(x: torch.Tensor, v_bins: torch.Tensor) -> torch.Tensor:
    # Reshape bins using expand_dims pattern instead of view
    expansion_pattern = (1,) * len(x.shape) + (-1,)
    reshaped_bins = v_bins.view(expansion_pattern)

    # Compute differences and find closest bin using abs
    diffs = x.unsqueeze(-1) - reshaped_bins
    indices = torch.argmin(torch.abs(diffs), dim=-1)

    # Use F.one_hot with proper dtype conversion
    return nn.functional.one_hot(indices, num_classes=v_bins.shape[0]).float()

def batched_gather(data: torch.Tensor, inds: torch.Tensor, dim: int = 0, no_batch_dims: int = 0) -> torch.Tensor:
    # Build index tensors using broadcasting instead of manual reshaping
    data_shape = data.shape
    indices_shape = inds.shape

    # Create base indices for non-batched dimensions
    base_indices = []
    for i in range(no_batch_dims):
        idx_shape = (*((1,) * i), data_shape[i], *((1,) * (len(indices_shape) - i - 1)))
        r = torch.arange(data_shape[i], device=data.device).view(idx_shape)
        base_indices.append(r)

    # Handle remaining dimensions
    slice_indices = [slice(None)] * (len(data_shape) - no_batch_dims)
    adjusted_dim = dim - no_batch_dims if dim >= 0 else dim
    slice_indices[adjusted_dim] = inds

    # Combine all index components
    full_indices = base_indices + slice_indices
    return data[tuple(full_indices)]

# Recursive tree mapping functions
def dict_map(
    fn: Callable[[T], Any], 
    dic: Dict[Any, Union[dict, list, tuple, T]], 
    leaf_type: Type[T]
) -> Dict[Any, Union[dict, list, tuple, Any]]:
    result = {}
    for k, v in dic.items():
        if isinstance(v, dict):
            result[k] = dict_map(fn, v, leaf_type)
        elif isinstance(v, (list, tuple)):
            result[k] = tree_map(fn, v, leaf_type)
        else:
            result[k] = fn(v) if isinstance(v, leaf_type) else v
    return result

@overload
def tree_map(fn: Callable[[T], Any], tree: T, leaf_type: Type[T]) -> Any: ...
@overload
def tree_map(fn: Callable[[T], Any], tree: dict, leaf_type: Type[T]) -> dict: ...
@overload
def tree_map(fn: Callable[[T], Any], tree: list, leaf_type: Type[T]) -> list: ...
@overload
def tree_map(fn: Callable[[T], Any], tree: tuple, leaf_type: Type[T]) -> tuple: ...

def tree_map(fn, tree, leaf_type):
    if isinstance(tree, dict):
        return dict_map(fn, tree, leaf_type)
    elif isinstance(tree, list):
        return [tree_map(fn, item, leaf_type) for item in tree]
    elif isinstance(tree, tuple):
        return tuple(tree_map(fn, item, leaf_type) for item in tree)
    elif isinstance(tree, leaf_type):
        return fn(tree)
    else:
        raise TypeError(f"Unsupported type {type(tree)} in tree_map")

# Create tensor-specific version
tensor_tree_map = partial(tree_map, leaf_type=torch.Tensor)

