from typing import Tuple, Union, Dict
from .big5freq import (
    BIG5_CHAR_TO_FREQ_ORDER,
    BIG5_TABLE_SIZE,
    BIG5_TYPICAL_DISTRIBUTION_RATIO,
)
from .euckrfreq import (
    EUCKR_CHAR_TO_FREQ_ORDER,
    EUCKR_TABLE_SIZE,
    EUCKR_TYPICAL_DISTRIBUTION_RATIO,
)
from .euctwfreq import (
    EUCTW_CHAR_TO_FREQ_ORDER,
    EUCTW_TABLE_SIZE,
    EUCTW_TYPICAL_DISTRIBUTION_RATIO,
)
from .gb2312freq import (
    GB2312_CHAR_TO_FREQ_ORDER,
    GB2312_TABLE_SIZE,
    GB2312_TYPICAL_DISTRIBUTION_RATIO,
)
from .jisfreq import (
    JIS_CHAR_TO_FREQ_ORDER,
    JIS_TABLE_SIZE,
    JIS_TYPICAL_DISTRIBUTION_RATIO,
)
from .johabfreq import JOHAB_TO_EUCKR_ORDER_TABLE


class CharDistributionAnalyzer:
    # Constants for detection thresholds and confidence levels
    DATA_THRESHOLD = 1024
    HIGH_CONFIDENCE = 0.99
    LOW_CONFIDENCE = 0.01
    MIN_SAMPLE_COUNT = 3

    def __init__(self) -> None:
        # Frequency mapping table (order index -> frequency rank)
        self._freq_map: Tuple[int, ...] = tuple()
        self._table_capacity = 0
        # Language-specific distribution parameter
        self._dist_ratio = 0.0
        self._analyzed = False
        self._char_count = 0
        self._high_freq_chars = 0
        self.reset()

    def reset(self) -> None:
        """Reset internal state"""
        self._analyzed = False
        self._char_count = 0
        self._high_freq_chars = 0

    def process_byte_sequence(self, data: Union[bytes, bytearray], length: int) -> None:
        """Process a character of specified byte length"""
        if length == 2:
            idx = self._get_index(data)
        else:
            idx = -1

        if idx >= 0:
            self._char_count += 1
            if idx < self._table_capacity and self._freq_map[idx] < 512:
                self._high_freq_chars += 1

    def calculate_confidence(self) -> float:
        """Calculate confidence score based on collected statistics"""
        if self._char_count <= 0 or self._high_freq_chars <= self.MIN_SAMPLE_COUNT:
            return self.LOW_CONFIDENCE

        if self._char_count != self._high_freq_chars:
            ratio = self._high_freq_chars / (
                (self._char_count - self._high_freq_chars) * self._dist_ratio
            )
            if ratio < self.HIGH_CONFIDENCE:
                return ratio

        return self.HIGH_CONFIDENCE

    def has_sufficient_data(self) -> bool:
        """Check if enough data has been processed for reliable analysis"""
        return self._char_count > self.DATA_THRESHOLD

    def _get_index(self, _: Union[bytes, bytearray]) -> int:
        """Convert byte sequence to order index (to be implemented by subclasses)"""
        return -1


class EUCTWDistributionAnalyzer(CharDistributionAnalyzer):
    def __init__(self) -> None:
        super().__init__()
        self._freq_map = EUCTW_CHAR_TO_FREQ_ORDER
        self._table_capacity = EUCTW_TABLE_SIZE
        self._dist_ratio = EUCTW_TYPICAL_DISTRIBUTION_RATIO

    def _get_index(self, byte_seq: Union[bytes, bytearray]) -> int:
        first = byte_seq[0]
        if first >= 0xC4:
            return 94 * (first - 0xC4) + byte_seq[1] - 0xA1
        return -1


class EUCKRDistributionAnalyzer(CharDistributionAnalyzer):
    def __init__(self) -> None:
        super().__init__()
        self._freq_map = EUCKR_CHAR_TO_FREQ_ORDER
        self._table_capacity = EUCKR_TABLE_SIZE
        self._dist_ratio = EUCKR_TYPICAL_DISTRIBUTION_RATIO

    def _get_index(self, byte_seq: Union[bytes, bytearray]) -> int:
        first = byte_seq[0]
        if first >= 0xB0:
            return 94 * (first - 0xB0) + byte_seq[1] - 0xA1
        return -1


class JOHABDistributionAnalyzer(CharDistributionAnalyzer):
    def __init__(self) -> None:
        super().__init__()
        self._freq_map = EUCKR_CHAR_TO_FREQ_ORDER
        self._table_capacity = EUCKR_TABLE_SIZE
        self._dist_ratio = EUCKR_TYPICAL_DISTRIBUTION_RATIO

    def _get_index(self, byte_seq: Union[bytes, bytearray]) -> int:
        first = byte_seq[0]
        if 0x88 <= first < 0xD4:
            code = (first << 8) | byte_seq[1]
            return JOHAB_TO_EUCKR_ORDER_TABLE.get(code, -1)
        return -1


class GB2312DistributionAnalyzer(CharDistributionAnalyzer):
    def __init__(self) -> None:
        super().__init__()
        self._freq_map = GB2312_CHAR_TO_FREQ_ORDER
        self._table_capacity = GB2312_TABLE_SIZE
        self._dist_ratio = GB2312_TYPICAL_DISTRIBUTION_RATIO

    def _get_index(self, byte_seq: Union[bytes, bytearray]) -> int:
        first, second = byte_seq[0], byte_seq[1]
        if first >= 0xB0 and second >= 0xA1:
            return 94 * (first - 0xB0) + second - 0xA1
        return -1


class Big5DistributionAnalyzer(CharDistributionAnalyzer):
    def __init__(self) -> None:
        super().__init__()
        self._freq_map = BIG5_CHAR_TO_FREQ_ORDER
        self._table_capacity = BIG5_TABLE_SIZE
        self._dist_ratio = BIG5_TYPICAL_DISTRIBUTION_RATIO

    def _get_index(self, byte_seq: Union[bytes, bytearray]) -> int:
        first, second = byte_seq[0], byte_seq[1]
        if first >= 0xA4:
            if second >= 0xA1:
                return 157 * (first - 0xA4) + second - 0xA1 + 63
            return 157 * (first - 0xA4) + second - 0x40
        return -1


class SJISDistributionAnalyzer(CharDistributionAnalyzer):
    def __init__(self) -> None:
        super().__init__()
        self._freq_map = JIS_CHAR_TO_FREQ_ORDER
        self._table_capacity = JIS_TABLE_SIZE
        self._dist_ratio = JIS_TYPICAL_DISTRIBUTION_RATIO

    def _get_index(self, byte_seq: Union[bytes, bytearray]) -> int:
        first, second = byte_seq[0], byte_seq[1]
        if 0x81 <= first <= 0x9F:
            base = 188 * (first - 0x81)
        elif 0xE0 <= first <= 0xEF:
            base = 188 * (first - 0xE0 + 31)
        else:
            return -1

        offset = second - 0x40
        if second > 0x7F:
            return -1
        return base + offset


class EUCJPDistributionAnalyzer(CharDistributionAnalyzer):
    def __init__(self) -> None:
        super().__init__()
        self._freq_map = JIS_CHAR_TO_FREQ_ORDER
        self._table_capacity = JIS_TABLE_SIZE
        self._dist_ratio = JIS_TYPICAL_DISTRIBUTION_RATIO

    def _get_index(self, byte_seq: Union[bytes, bytearray]) -> int:
        char = byte_seq[0]
        if char >= 0xA0:
            return 94 * (char - 0xA1) + byte_seq[1] - 0xA1
        return -1

