class EnsembleDistillStructure(MultiModelStruct):
    def __init__(self, models, cfg, switch_point=2):
        self.models = models  # [high_noise, low_noise]
        assert len(self.models) == 2, "Only two models supported in ensemble."
        self.cfg = cfg
        self.switch_point = switch_point
        self.active_idx = -1
        logger.info(f"Switch point at step index: {self.switch_point}")

    @ProfilingContext4DebugL2("Model switching overhead")
    def _decide_active_model(self):
        current_step = self.scheduler.step_index
        target_idx = 0 if current_step < self.switch_point else 1

        if target_idx != self.active_idx:
            high_log = f"using - {'HIGH' if target_idx == 0 else 'LOW'} - noise model at step {current_step + 1}"
            logger.info(high_log)

            offload_granularity = self.cfg.get("offload_granularity", "block")
            cpu_offload = self.cfg.get("cpu_offload", False)

            if cpu_offload and offload_granularity == "model":
                if self.active_idx == -1:
                    self.to_cuda(model_index=target_idx)
                elif self.active_idx != target_idx:
                    self.offload_cpu(model_index=self.active_idx)
                    self.to_cuda(model_index=target_idx)

            self.active_idx = target_idx

    def infer(self, inputs):
        self._decide_active_model()
        active_model = self.models[self.active_idx]

        lazy_load = self.cfg.get("lazy_load", False)
        unload_modules = self.cfg.get("unload_modules", False)

        if not lazy_load and not unload_modules:
            active_model.infer(inputs)
        else:
            if active_model is None:
                idx = self.active_idx
                lora_cfgs = self.cfg.get("lora_configs")
                base_kwargs = {
                    "config": self.cfg,
                    "device": self.init_device,
                    "model_type": f"wan2.2_moe_{'high' if idx == 0 else 'low'}_noise",
                }

                if idx == 0:
                    base_kwargs["model_path"] = self.high_noise_model_path
                    model_cls = WanDistillModel
                    if lora_cfgs:
                        assert self.cfg.get("lora_dynamic_apply", False)
                        model_cls = lambda **kw: build_wan_model_with_lora(
                            WanModel, self.cfg, kw, lora_cfgs, model_type="high_noise_model"
                        )
                else:
                    base_kwargs["model_path"] = self.low_noise_model_path
                    model_cls = WanDistillModel
                    if lora_cfgs:
                        assert self.cfg.get("lora_dynamic_apply", False)
                        model_cls = lambda **kw: build_wan_model_with_lora(
                            WanModel, self.cfg, kw, lora_cfgs, model_type="low_noise_model"
                        )

                new_model = model_cls(**base_kwargs)
                new_model.set_scheduler(self.scheduler)
                self.models[idx] = new_model
                new_model.infer(inputs)
            else:
                active_model.infer(inputs)


@RUNNER_REGISTER("wan2.2_moe_distill")
class MoEDistillRunner(DistillPipelineRunner):
    def __init__(self, cfg):
        super().__init__(cfg)
        self._resolve_model_paths()

    def _resolve_model_paths(self):
        cfg = self.config
        dit_quantized = cfg.get("dit_quantized", False)

        # High noise model path
        if dit_quantized and cfg.get("high_noise_quantized_ckpt"):
            self.high_noise_model_path = cfg["high_noise_quantized_ckpt"]
        elif cfg.get("high_noise_original_ckpt"):
            self.high_noise_model_path = cfg["high_noise_original_ckpt"]
        else:
            self.high_noise_model_path = os.path.join(cfg["model_path"], "high_noise_model")
            if not os.path.isdir(self.high_noise_model_path):
                raise FileNotFoundError("High noise model directory missing.")

        # Low noise model path
        if dit_quantized and cfg.get("low_noise_quantized_ckpt"):
            self.low_noise_model_path = cfg["low_noise_quantized_ckpt"]
        elif not dit_quantized and cfg.get("low_noise_original_ckpt"):
            self.low_noise_model_path = cfg["low_noise_original_ckpt"]
        else:
            self.low_noise_model_path = os.path.join(cfg["model_path"], "low_noise_model")
            if not os.path.isdir(self.low_noise_model_path):
                raise FileNotFoundError("Low noise model directory missing.")

    def load_transformer(self):
        lazy = self.config.get("lazy_load", False)
        unload = self.config.get("unload_modules", False)

        if not lazy and not unload:
            lora_cfgs = self.config.get("lora_configs")
            kwargs_high = {
                "model_path": self.high_noise_model_path,
                "config": self.config,
                "device": self.init_device,
                "model_type": "wan2.2_moe_high_noise",
            }
            kwargs_low = {
                "model_path": self.low_noise_model_path,
                "config": self.config,
                "device": self.init_device,
                "model_type": "wan2.2_moe_low_noise",
            }

            factory = WanDistillModel if not lora_cfgs else lambda **kw: build_wan_model_with_lora(
                WanModel, self.config, kw, lora_cfgs, model_type=""
            )

            high_model = factory(**kwargs_high)
            low_model = factory(**kwargs_low)

            return EnsembleDistillStructure([high_model, low_model], self.config, self.config["boundary_step_index"])
        else:
            struct = EnsembleDistillStructure([None, None], self.config, self.config["boundary_step_index"])
            struct.high_noise_model_path = self.high_noise_model_path
            struct.low_noise_model_path = self.low_noise_model_path
            struct.init_device = self.init_device
            return struct

    def init_scheduler(self):
        caching_mode = self.config["feature_caching"]
        if caching_mode == "NoCaching":
            self.scheduler = Wan22StepDistillScheduler(self.config)
        else:
            raise NotImplementedError(f"Unsupported caching mode: {caching_mode}")

    def switch_lora(
        self,
        high_lora_path: str = None,
        high_lora_strength: float = 1.0,
        low_lora_path: str = None,
        low_lora_strength: float = 1.0,
    ):
        """
        Dynamically update LoRA adapters for both high and low noise models.
        """
        if not hasattr(self, "model") or self.model is None:
            logger.error("Model not loaded. Cannot switch LoRA.")
            return False

        success_flags = []

        if high_lora_path is not None:
            high_model = self.model.models[0]
            if high_model and hasattr(high_model, "_update_lora"):
                logger.info(f"Applying high-noise LoRA: {high_lora_path} (scale={high_lora_strength})")
                high_model._update_lora(high_lora_path, high_lora_strength)
                success_flags.append(True)
            else:
                success_flags.append(False)

        if low_lora_path is not None:
            low_model = self.model.models[1]
            if low_model and hasattr(low_model, "_update_lora"):
                logger.info(f"Applying low-noise LoRA: {low_lora_path} (scale={low_lora_strength})")
                low_model._update_lora(low_lora_path, low_lora_strength)
                success_flags.append(True)
            else:
                success_flags.append(False)

        if any(success_flags):
            logger.info("LoRA update completed successfully.")
            return True
        else:
            logger.warning("No LoRA updates were applied.")
            return False

# Find all positions of x in the 2D list and sort each row's positions by column in descending order
result = []
for row_num, current_row in enumerate(lst):
    matching_cols = []
    for col_num, element in enumerate(current_row):
        if element == x:
            matching_cols.append(col_num)

    # Create coordinate pairs sorted by column index in reverse order
    for col in sorted(matching_cols, reverse=True):
        result.append((row_num, col))

return result

from typing import Any, Callable, Dict, List, Literal, Optional, TypeVar, Union, get_type_hints, get_origin, get_args
import logging
from functools import wraps
from mindspeed.fsdp.utils.log import print_rank

logger = logging.getLogger(__name__)

def _is_dataclass_instance(obj: Any) -> bool:
    """Check if object is a dataclass instance by verifying presence of __dataclass_fields__."""
    return hasattr(obj, '__dataclass_fields__')

def _collect_field_names(cls: type) -> set:
    """Extract field names from a dataclass using its __dataclass_fields__ attribute."""
    if not _is_dataclass_instance(cls):
        return set()
    return {field_name for field_name in cls.__dataclass_fields__.keys()}

def _build_nested_class(name: str, mapping: Dict[str, Any]) -> type:
    """Recursively construct a dynamic dataclass from a dictionary."""
    fields_dict = {}
    annotations = {}

    for key, val in mapping.items():
        if isinstance(val, dict):
            sub_cls = _build_nested_class(f"{name}_{key}", val)
            fields_dict[key] = None  # placeholder; will be replaced below
            annotations[key] = sub_cls
        else:
            typ = type(val) if val is not None else Any
            if typ in (list, set):
                fields_dict[key] = []
            else:
                fields_dict[key] = val
            annotations[key] = typ

    # Create class dynamically
    cls = type(name, (), fields_dict)
    cls.__annotations__ = annotations

    # Apply dataclass decorator only after setting up fields
    from dataclasses import dataclass, field
    for k, v in annotations.items():
        if isinstance(mapping[k], dict):
            cls.__dict__[k] = field(default_factory=v)
        elif isinstance(mapping[k], (list, set)):
            cls.__dict__[k] = field(default_factory=type(mapping[k]))
        else:
            cls.__dict__[k] = field(default=mapping[k])

    return dataclass(cls)

def _attach_nested_field(parent_cls: type, field_name: str, nested_data: Dict[str, Any]) -> None:
    """Dynamically attach a nested dataclass field to a parent class."""
    nested_cls = _build_nested_class(field_name.capitalize(), nested_data)
    setattr(parent_cls, field_name, nested_cls())
    if '__annotations__' not in parent_cls.__dict__:
        parent_cls.__annotations__ = {}
    parent_cls.__annotations__[field_name] = nested_cls

def allow_extra_fields(cls):
    """
    Decorator: Enables a dataclass to accept extra keyword arguments beyond its defined fields.

    This wrapper intercepts initialization to:
    - Distinguish between known and unknown fields
    - Log warnings for unknown fields
    - Attach unknown fields as attributes (including nested dicts as new dataclasses)
    - Preserve original __post_init__ behavior if present

    Args:
        cls: A dataclass to enhance

    Returns:
        Modified class with extended __init__
    """
    orig_init = cls.__init__

    @wraps(orig_init)
    def wrapped_init(self, *args, **kwargs):
        known_fields = _collect_field_names(cls)
        known_vals = {}
        unknown_vals = {}

        for k, v in kwargs.items():
            if k in known_fields:
                known_vals[k] = v
            else:
                unknown_vals[k] = v
                print_rank(logger.warning,
                    f"Field '{k}' not declared in {cls.__name__}. Storing as dynamic attribute."
                )

        # Initialize with only known fields
        orig_init(self, *args, **known_vals)

        # Ensure _extra_fields exists
        if not hasattr(self, '_extra_fields'):
            self._extra_fields = {}

        def _apply_to_nested(target_obj: Any, data: Dict[str, Any]) -> None:
            for name, content in data.items():
                if isinstance(content, dict):
                    inner_obj = getattr(target_obj, name, None)
                    if inner_obj is not None:
                        _apply_to_nested(inner_obj, content)
                else:
                    setattr(target_obj, name, content)

        for name, value in unknown_vals.items():
            if isinstance(value, dict):
                _attach_nested_field(self, name, value)
                nested_type = get_type_hints(self).get(name)
                if nested_type:
                    nested_inst = nested_type()
                    _apply_to_nested(nested_inst, value)
                    setattr(self, name, nested_inst)
            else:
                setattr(self, name, value)
            self._extra_fields[name] = value

    cls.__init__ = wrapped_init
    return cls


def instantiate_from_dict(dataclass_type: type, payload: Dict[str, Any]) -> Any:
    """
    Recursively builds an instance of a dataclass from a dictionary.

    Handles both primitive types and nested dataclasses. Unknown keys are preserved
    via the @allow_extra_fields mechanism.

    Args:
        dataclass_type: Target dataclass type
        payload: Dictionary containing initialization data

    Returns:
        Instantiated object of the given dataclass type
    """
    if not _is_dataclass_instance(dataclass_type):
        return payload

    try:
        type_hints = get_type_hints(dataclass_type)
    except Exception as e:
        raise RuntimeError(f"Could not resolve type hints for {dataclass_type}: {e}") from e

    init_kwargs = {}
    extra_kwargs = {}

    known_names = _collect_field_names(dataclass_type)

    for key, val in payload.items():
        if key in known_names:
            target_type = type_hints[key]
            if _is_dataclass_instance(target_type) and isinstance(val, dict):
                init_kwargs[key] = instantiate_from_dict(target_type, val)
            else:
                init_kwargs[key] = val
        else:
            extra_kwargs[key] = val

    combined = {**init_kwargs, **extra_kwargs}
    return dataclass_type(**combined)

import logging
import warnings
import astropy_healpix as hp
import numpy as np
import omegaconf
import torch
from numpy.typing import NDArray
from weathergen.datasets.batch import SampleMetaData
from weathergen.train.utils import Stage
from weathergen.utils.utils import is_stream_diagnostic, is_stream_forcing

logger = logging.getLogger(__name__)


class MaskData:
    def __init__(self):
        self._masks = []
        self._metadata = []

    def __len__(self):
        return len(self._masks)

    def append_mask(self, mask, params, cfg, losses, idx, corr, rel):
        self._masks.append(mask)
        self._metadata.append(
            SampleMetaData(
                params={**cfg, **params},
                mask=mask,
                global_params={
                    "idx": idx,
                    "correspondence": corr,
                    "loss": losses,
                    "relationship": rel,
                },
            )
        )

    def get_item(self, index: int) -> np.typing.NDArray:
        return self._masks[index]


def count_samples_per_source(config_dict) -> np.ndarray:
    """Return array of num_samples per source/target config."""
    return np.array([scfg.get("num_samples", 1) for _, scfg in config_dict.items()])


def validate_correspondence_mode(mode, targets, sources):
    n_targets = sum(t.get("num_samples", 1) for t in targets)
    n_sources = sum(s.get("num_samples", 1) for s in sources)

    if mode == "one-to-one":
        assert len(targets) == len(sources), (
            "For 'one-to-one', number of target/source strategies must match."
        )
        assert n_targets == n_sources, (
            "For 'one-to-one', total samples in target/source must match."
        )
    elif mode == "equal-split-all":
        assert n_sources % n_targets == 0, (
            "For 'equal-split-all', source samples must be divisible by target samples."
        )


def to_bool_tensor(arr):
    return torch.from_numpy(np.asarray(arr)).to(torch.bool)


class Masker:
    def __init__(self, healpix_level: int, stage: Stage):
        self.rng = None
        self.mask_value = 0.0
        self.time_enc_dim = 6
        self.level_data = healpix_level
        self.num_cells_total = 12 * (4**healpix_level)
        self.stage_name = stage

    def seed_rng(self, rng_obj):
        self.rng = rng_obj

    def _sample_rate(self, cfg):
        rate = cfg.get("rate")
        if rate is None:
            raise ValueError('Missing required key "rate" in sampling config.')
        if cfg.get("rate_sampling", False):
            rate = np.clip(
                np.abs(self.rng.normal(loc=rate, scale=1.0 / (2.5 * np.pi))),
                0.01,
                0.99,
            )
        if not (0.0 <= rate <= 1.0):
            raise ValueError(f"Sampling rate out of bounds: {rate}")
        return rate

    def _extract_target_relationship(self, masks_data, masking_cfg):
        rel_map = masking_cfg.get("target_relationship", {"independent": None})
        assert len(rel_map) == 1, "Only one target relationship allowed."
        strategy = list(rel_map.keys())[0]
        idx = list(rel_map.values())[0]
        return (strategy, masks_data.get_item(idx)), idx

    def _resolve_correspondences(self, loss_terms, target_confs, source_confs):
        # Collect all correspondence specs across loss terms
        all_corrs = []
        for _, loss_term in loss_terms.items():
            for name, fct in loss_term.loss_fcts.items():
                spec = fct.get("target_source_correspondence")
                if spec is None:
                    assert len(target_confs) == len(source_confs), (
                        "No explicit correspondence given; configs must match in count."
                    )
                    spec = {i: i for i in range(len(target_confs))}
                parsed_corr = {}
                for tgt_idx, src_spec in spec.items():
                    tgt_idx = int(tgt_idx)
                    if isinstance(src_spec, omegaconf.DictConfig):
                        parsed_corr[tgt_idx] = {
                            int(k): (v, name) for k, v in src_spec.items()
                        }
                    elif isinstance(src_spec, omegaconf.ListConfig):
                        parsed_corr[tgt_idx] = {int(v): (None, name) for v in src_spec}
                    elif isinstance(src_spec, int):
                        parsed_corr[tgt_idx] = {src_spec: (None, name)}
                    else:
                        raise TypeError("Invalid correspondence format.")
                all_corrs.append(parsed_corr)

        # Validate indices are integers
        valid_indices = all(
            type(k) is int and type(next(iter(v.keys()))) is int
            for corr in all_corrs
            for k, v in corr.items()
        )
        assert valid_indices, "All indices in correspondences must be integers."

        # Merge correspondences
        merged = {}
        for t_idx in range(len(target_confs)):
            candidates = [c.get(t_idx) for c in all_corrs if c.get(t_idx)]
            unique_sources = set(kk for cand in candidates for kk in cand.keys())
            for s_idx in unique_sources:
                rels = [cand[s_idx] for cand in candidates if s_idx in cand]
                if not rels:
                    continue
                rel_types = [r[0] for r in rels]
                assert len(set(rel_types)) == 1, "Inconsistent relationships for same pair."
                losses = [r[1] for r in rels]
                if s_idx >= len(source_confs):
                    logger.warning(f"Correspondence references non-existent source {s_idx}.")
                    continue
                if t_idx >= len(target_confs):
                    logger.warning(f"Correspondence references non-existent target {t_idx}.")
                    continue
                assert merged.get(s_idx) is None, "Each source maps to only one target."
                merged[s_idx] = (t_idx, (rel_types[0], losses))
        return merged

    def _build_stream_samples(
        self,
        train_mode: str,
        num_cells: int,
        stage_config: dict,
        stream_config: dict,
    ) -> tuple:
        target_confs = stage_config.get("target_input", [])
        source_confs = stage_config.get("model_input", [])

        if not target_confs:
            import copy
            target_confs = copy.deepcopy(source_confs)

        loss_defs = stage_config.losses
        mapping = self._resolve_correspondences(loss_defs, target_confs, source_confs)

        # Build target masks
        target_masks = MaskData()
        target_count = 0
        for cfg_idx, (_, t_cfg) in enumerate(target_confs.items()):
            for _ in range(t_cfg.get("num_samples", 1)):
                if is_stream_forcing(stream_config, self.stage_name):
                    mask_t = torch.zeros(num_cells, dtype=torch.bool)
                    meta_t = {}
                else:
                    mask_t, meta_t = self._create_cell_mask(
                        num_cells=num_cells,
                        strategy=t_cfg.get("masking_strategy"),
                        config=t_cfg.get("masking_strategy_config", {}),
                        rel_mask=("independent", None),
                    )
                losses_list = [
                    v[1][1]
                    for _, v in mapping.items()
                    if v and v[0] == cfg_idx
                ]
                losses_flat = [l for lt in losses_list for l in lt]
                sources_used = [k for k, v in mapping.items() if v and v[0] == cfg_idx]

                if not sources_used:
                    continue

                target_masks.append_mask(
                    mask_t, meta_t, t_cfg, losses_flat, target_count, sources_used, None
                )
                target_count += 1

        # Build source masks
        source_masks = MaskData()
        mapping_targets = []
        sample_counts = count_samples_per_source(target_confs)
        source_idx = 0

        for src_id, (_, s_cfg) in enumerate(source_confs.items()):
            if src_id not in mapping:
                continue
            for _ in range(s_cfg.get("num_samples", 1)):
                cfg_src = s_cfg.get("masking_strategy_config", {})
                tgt_id, rel_info = mapping[src_id]
                rel_type, losses = rel_info

                if rel_type is None:
                    if s_cfg.get("masking_strategy") == "random":
                        rel_type = "complement"
                    else:
                        rel_type = "independent"

                base_tgt = sample_counts[:tgt_id].sum()
                offset = source_idx % int(sample_counts[tgt_id])
                actual_tgt = int(base_tgt + offset)

                if is_stream_diagnostic(stream_config, self.stage_name):
                    mask_s = torch.zeros(num_cells, dtype=torch.bool)
                    meta_s = {}
                else:
                    mask_s, meta_s = self._create_cell_mask(
                        num_cells=num_cells,
                        strategy=s_cfg.get("masking_strategy"),
                        config=cfg_src,
                        rel_mask=(rel_type, target_masks.get_item(actual_tgt)),
                    )

                source_masks.append_mask(
                    mask_s, meta_s, s_cfg, losses, source_idx, actual_tgt, rel_type
                )
                mapping_targets.append(actual_tgt)
                source_idx += 1

        return target_masks, source_masks, np.array(mapping_targets, dtype=np.int32)

    def _create_cell_mask(
        self,
        num_cells: int,
        strategy: str,
        cfg: dict,
        rel_mask: tuple,
    ) -> tuple:
        rel, tgt_mask = rel_mask

        if strategy == "forecast":
            assert rel == "independent", "Forecast requires independent relationship."

        if rel == "complement":
            assert tgt_mask is not None, "Complement needs target mask."
            return (~tgt_mask), {}
        elif rel == "identity":
            assert tgt_mask is not None, "Identity needs target mask."
            return tgt_mask, {}

        base_mask, params = self._produce_base_mask(num_cells, strategy, cfg)

        if rel == "subset":
            assert tgt_mask is not None, "Subset needs target mask."
            return base_mask & tgt_mask, params
        elif rel == "disjoint":
            assert tgt_mask is not None, "Disjoint needs target mask."
            return base_mask & (~tgt_mask), params

        return base_mask, params

    def _produce_base_mask(self, num_cells: int, strategy: str, cfg: dict):
        params = {}
        assert num_cells == self.num_cells_total, "Mismatch in HEALPix level."

        if strategy == "random":
            keep_prob = self._sample_rate(cfg)
            mask = self.rng.uniform(0, 1, num_cells) < keep_prob
        elif "forecast" in strategy or strategy == "causal":
            mask = np.ones(num_cells, dtype=bool)
            if "diffusion_rn" in cfg:
                params["noise_level_rn"] = self.rng.normal(0.0, 1.0)
        elif strategy == "healpix":
            keep_prob = self._sample_rate(cfg)
            hl, n_parents, children_per_parent, n_to_keep = self._setup_healpix_masking(cfg, keep_prob)
            if n_to_keep == 0:
                mask = np.zeros(num_cells, dtype=bool)
            else:
                parents = self.rng.choice(n_parents, n_to_keep, replace=False)
                offsets = np.arange(children_per_parent)
                indices = (parents[:, None] * children_per_parent + offsets).flatten()
                mask = np.zeros(num_cells, dtype=bool)
                mask[indices] = True
        elif strategy == "cropping_healpix":
            keep_prob = self._sample_rate(cfg)
            hl, n_parents, children_per_parent, n_to_keep = self._setup_healpix_masking(cfg, keep_prob)
            if n_to_keep == 0:
                mask = np.zeros(num_cells, dtype=bool)
            else:
                method = cfg.get("method", "geodesic_disk")
                selected = self._find_contiguous_region(
                    healpix_level=hl,
                    total=num_cells,
                    count=n_to_keep,
                    children_per_parent=children_per_parent,
                    method=method,
                )
                parent_ids = np.array(sorted(selected))
                child_offsets = np.arange(children_per_parent)
                indices = (parent_ids[:, None] * children_per_parent + child_offsets).flatten()
                mask = np.zeros(num_cells, dtype=bool)
                mask[indices] = True
        else:
            raise NotImplementedError(f"Unknown strategy: {strategy}")

        return to_bool_tensor(mask), params

    def _find_contiguous_region(
        self,
        healpix_level: int,
        total: int,
        count: int,
        children_per_parent: int,
        center=None,
        method="geodesic_disk",
    ):
        nside = 2**healpix_level
        total_cells = 12 * (4**healpix_level)
        assert count <= total_cells

        center_cell = self.rng.integers(0, total_cells) if center is None else center

        if method == "disk":
            region = self._grow_disk(center_cell, count, nside)
        elif method == "random_walk":
            region = self._walk_randomly(center_cell, count, nside)
        elif method == "geodesic_disk":
            region = self._select_circular(center_cell, count, nside, total_cells)
        else:
            raise ValueError(f"Unsupported method: {method}")

        return region

    def _grow_disk(self, start, target, nside):
        selected = {start}
        frontier = {start}
        while len(selected) < target and frontier:
            next_frontier = set()
            for cell in frontier:
                try:
                    neighbors = hp.neighbours(cell, nside, order="nested")
                except Exception:
                    neighbors = [-1] * 8
                valid = [n for n in neighbors if n != -1 and n not in selected]
                next_frontier.update(valid)
            if not next_frontier:
                break
            candidates = list(next_frontier)
            self.rng.shuffle(candidates)
            needed = target - len(selected)
            added = candidates[:needed]
            selected.update(added)
            frontier = set(added)
        return selected

    def _walk_randomly(self, start, target, nside):
        selected = {start}
        current = {start}
        while len(selected) < target:
            neighbors = set()
            for cell in current:
                try:
                    nbors = hp.neighbours(cell, nside, order="nested")
                except Exception:
                    nbors = [-1] * 8
                valid = [n for n in nbors if n != -1 and n not in selected]
                neighbors.update(valid)
            if not neighbors:
                break
            next_step = self.rng.choice(list(neighbors))
            selected.add(next_step)
            current = {next_step}
        return selected

    def _select_circular(self, center, target, nside, total):
        def xyz(lon, lat):
            return np.array([np.cos(lat) * np.cos(lon), np.cos(lat) * np.sin(lon), np.sin(lat)])

        lonlat = hp.healpix_to_lonlat(center, nside, order="nested")
        lon = float(lonlat[0].value)
        lat = float(lonlat[1].value)
        center_xyz = xyz(lon, lat)

        indices = np.arange(total)
        lons, lats = hp.healpix_to_lonlat(indices, nside, order="nested")
        lons = np.array([float(x.value) for x in lons])
        lats = np.array([float(x.value) for x in lats])

        points = np.column_stack([
            np.cos(lats) * np.cos(lons),
            np.cos(lats) * np.sin(lons),
            np.sin(lats),
        ])
        dots = np.clip(np.dot(points, center_xyz), -1.0, 1.0)
        angles = np.arccos(dots)
        chosen = np.argsort(angles)[:target]
        return set(chosen)

    def _setup_healpix_masking(self, cfg, keep_rate):
        hl_data = self.level_data
        hl_mask = cfg.get("hl_mask")
        assert hl_mask is not None and hl_mask < hl_data, (
            "HEALPix mask level must be specified and less than data level."
        )
        n_parents = 12 * (4**hl_mask)
        diff = hl_data - hl_mask
        children_per_parent = 4**diff
        n_to_keep = int(round(keep_rate * n_parents))
        return hl_mask, n_parents, children_per_parent, n_to_keep

#!/usr/bin/env python3
"""
OpenAlexandria CLI — A modernized, refactored version of the original protocol client.
"""

import argparse
import json
import os
import sys
from urllib.parse import quote as url_encode, urlencode

# Optional: prefer httpx if available; fall back to urllib if not
try:
    import httpx
    _USE_HTTPX = True
except ImportError:
    import urllib.request
    import urllib.error
    _USE_HTTPX = False


# Configuration defaults
DEFAULT_BASE_URL = "https://openalexandria.vercel.app"
API_KEY_ENV_VAR = "OPENALEXANDRIA_API_KEY"


def get_base_url() -> str:
    """Retrieve base URL from environment or use default."""
    raw = os.environ.get("OPENALEXANDRIA_BASE_URL", DEFAULT_BASE_URL)
    return raw.rstrip("/")


def get_api_key(cli_key: str | None) -> str:
    """Resolve API key: CLI arg > env var > raise."""
    key = cli_key or os.environ.get(API_KEY_ENV_VAR)
    if not key:
        raise SystemExit(f"Missing API key. Set {API_KEY_ENV_VAR} or pass --api-key.")
    return key


def make_headers(api_key: str | None = None) -> dict:
    """Build standard HTTP headers."""
    hdrs = {"Accept": "application/json"}
    if api_key:
        hdrs["Authorization"] = f"Bearer {api_key}"
    return hdrs


def post_json(url: str, payload: dict, api_key: str | None = None) -> dict:
    """POST JSON data to endpoint."""
    headers = make_headers(api_key)
    headers["Content-Type"] = "application/json"

    if _USE_HTTPX:
        resp = httpx.post(url, json=payload, headers=headers, timeout=30.0)
        resp.raise_for_status()
        body = resp.text.strip()
        return {} if not body else json.loads(body)
    else:
        req = urllib.request.Request(url, data=json.dumps(payload).encode(), method="POST", headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read().decode().strip()
                return {} if not body else json.loads(body)
        except urllib.error.HTTPError as e:
            err_body = ""
            try:
                err_body = e.read().decode()
            except Exception:
                pass
            raise RuntimeError(f"HTTP {e.code} {e.reason}: {err_body}".strip())


def get_json(url: str, api_key: str | None = None) -> dict:
    """GET JSON from endpoint."""
    headers = make_headers(api_key)

    if _USE_HTTPX:
        resp = httpx.get(url, headers=headers, timeout=30.0)
        resp.raise_for_status()
        body = resp.text.strip()
        return {} if not body else json.loads(body)
    else:
        req = urllib.request.Request(url, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read().decode().strip()
                return {} if not body else json.loads(body)
        except urllib.error.HTTPError as e:
            err_body = ""
            try:
                err_body = e.read().decode()
            except Exception:
                pass
            raise RuntimeError(f"HTTP {e.code} {e.reason}: {err_body}".strip())


# Command handlers — each returns a dict to be JSON-printed later

def handle_wellknown(_args) -> dict:
    return get_json(f"{get_base_url()}/.well-known/openalexandria.json")


def handle_query(args) -> dict:
    params = {"q": args.q, "k": str(args.k)}
    url = f"{get_base_url()}/v1/query?{urlencode(params)}"
    return get_json(url)


def handle_entry(args) -> dict:
    eid = url_encode(args.id, safe="")
    url = f"{get_base_url()}/v1/entry/{eid}"
    return get_json(url)


def handle_feed(args) -> dict:
    params = {}
    if args.since:
        params["since"] = args.since
    suffix = f"?{urlencode(params)}" if params else ""
    url = f"{get_base_url()}/v1/feed{suffix}"
    return get_json(url)


def handle_whoami(args) -> dict:
    key = get_api_key(args.api_key)
    url = f"{get_base_url()}/v1/whoami"
    return get_json(url, api_key=key)


def handle_submission(args) -> dict:
    sid = url_encode(args.id, safe="")
    url = f"{get_base_url()}/v1/submission/{sid}"
    key = get_api_key(args.api_key)
    return get_json(url, api_key=key)


def handle_submit(args) -> dict:
    key = get_api_key(args.api_key)
    if args.file:
        with open(args.file, encoding="utf-8") as f:
            payload = json.load(f)
    else:
        payload = json.load(sys.stdin)
    url = f"{get_base_url()}/v1/submit"
    return post_json(url, payload, api_key=key)


# Dispatch map: maps command name → handler function
COMMAND_DISPATCH = {
    "wellknown": handle_wellknown,
    "query": handle_query,
    "entry": handle_entry,
    "feed": handle_feed,
    "whoami": handle_whoami,
    "submission": handle_submission,
    "submit": handle_submit,
}


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="openalexandria-cli",
        description="CLI for OpenAlexandria Protocol",
    )
    subs = parser.add_subparsers(dest="command", required=True)

    # wellknown
    w_parser = subs.add_parser("wellknown", help="Fetch node discovery document")
    w_parser.set_defaults(handler=handle_wellknown)

    # query
    q_parser = subs.add_parser("query", help="Search entries")
    q_parser.add_argument("q", help="Query string")
    q_parser.add_argument("--k", type=int, default=5, help="Max results (default: 5)")
    q_parser.set_defaults(handler=handle_query)

    # entry
    e_parser = subs.add_parser("entry", help="Get entry by ID")
    e_parser.add_argument("id", help="Entry identifier")
    e_parser.set_defaults(handler=handle_entry)

    # feed
    f_parser = subs.add_parser("feed", help="Get recent activity feed")
    f_parser.add_argument("--since", help="Cursor from previous response", default=None)
    f_parser.set_defaults(handler=handle_feed)

    # whoami
    wm_parser = subs.add_parser("whoami", help="Check API key status")
    wm_parser.add_argument("--api-key", dest="api_key", default=None)
    wm_parser.set_defaults(handler=handle_whoami)

    # submission
    s_parser = subs.add_parser("submission", help="Check submission status")
    s_parser.add_argument("id", help="Submission ID (sub_...)")
    s_parser.add_argument("--api-key", dest="api_key", default=None)
    s_parser.set_defaults(handler=handle_submission)

    # submit
    sb_parser = subs.add_parser("submit", help="Submit a bundle")
    sb_parser.add_argument("--file", help="JSON file (stdin if omitted)", default=None)
    sb_parser.add_argument("--api-key", dest="api_key", default=None)
    sb_parser.set_defaults(handler=handle_submit)

    return parser


def main():
    parser = build_parser()
    args = parser.parse_args()

    # Execute handler
    handler = getattr(args, "handler", None)
    if not handler:
        parser.error("No command specified")

    result = handler(args)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

