import copy
from typing import Dict, List

# Transform a tool message into a user message using chat template logic
def transform_tool_to_user_message(tool_msg, tokenizer, mode="qwen"):
    assert mode == "qwen"
    if tool_msg["role"] == "user":
        return tool_msg
    elif tool_msg["role"] == "tool" and len(tool_msg.get("tool_calls", [])) > 0:
        assert len(tool_msg["tool_calls"]) == 1
        return {
            "role": "user",
            "content": str(tool_msg["tool_calls"][0]["result"]),
        }

# Remove specified keys from a dictionary (deep copy to avoid mutation)
def strip_fields(data: Dict, keys_to_remove: List[str]) -> Dict:
    data_copy = copy.deepcopy(data)
    for key in keys_to_remove:
        data_copy.pop(key.strip(), None)
    return data_copy

# Validate memory pipeline execution status

import json
import sys
import os
import glob
from datetime import datetime, date, timedelta, timezone


def is_file_newer_than(filepath, reference_time):
    """Determine if file's modification time is after the reference time."""
    if not os.path.isfile(filepath):
        return False
    mod_time = datetime.fromtimestamp(os.path.getmtime(filepath), tz=timezone.utc)
    return mod_time > reference_time


def get_modification_timestamp(filepath):
    """Return ISO-formatted last modification time or 'NOT FOUND'."""
    if not os.path.exists(filepath):
        return 'NOT FOUND'
    mod_time = datetime.fromtimestamp(os.path.getmtime(filepath), tz=timezone.utc)
    return mod_time.isoformat()


def tally_by_significance(jsonl_filepath, target_sig):
    """Count entries in JSONL file matching a specific significance level."""
    tally = 0
    if not os.path.isfile(jsonl_filepath):
        return 0
    with open(jsonl_filepath, encoding='utf-8', errors='ignore') as stream:
        for record in stream:
            record = record.strip()
            if not record:
                continue
            try:
                data = json.loads(record)
                if data.get('significance') == target_sig:
                    tally += 1
            except json.JSONDecodeError:
                continue
    return tally


def tally_unprocessed(jsonl_filepath):
    """Count entries where 'reflected' is explicitly false."""
    tally = 0
    if not os.path.isfile(jsonl_filepath):
        return 0
    with open(jsonl_filepath, encoding='utf-8', errors='ignore') as stream:
        for record in stream:
            record = record.strip()
            if not record:
                continue
            try:
                data = json.loads(record)
                if data.get('reflected') is False:
                    tally += 1
            except json.JSONDecodeError:
                continue
    return tally


def assess_pipeline(memory_path, minutes_threshold=30):
    problems = []
    alerts = []
    observations = {}

    current_time = datetime.now(timezone.utc)
    threshold_time = current_time - timedelta(minutes=minutes_threshold)
    today_iso = date.today().isoformat()

    # ========================================
    # 1. Verify daily experience log exists and has recent activity
    # ========================================
    experiences_folder = os.path.join(memory_path, 'experiences')
    daily_log = os.path.join(experiences_folder, f'{today_iso}.jsonl')

    if not os.path.isfile(daily_log):
        problems.append({
            'type': 'experience_log',
            'description': f"Today's experience log missing: {daily_log}. "
                           f"Expected after agent heartbeat."
        })
        observations['experience_log'] = 'MISSING'
    else:
        observations['experience_log'] = get_modification_timestamp(daily_log)
        if not is_file_newer_than(daily_log, threshold_time):
            alerts.append({
                'type': 'experience_log',
                'description': f"Experience log unchanged for past {minutes_threshold} minutes. "
                               f"Last update: {get_modification_timestamp(daily_log)}"
            })

    # ========================================
    # 2. Ensure notable/pivotal entries are promoted to significant log
    # ========================================
    significant_log = os.path.join(memory_path, 'significant', 'significant.jsonl')
    notable_today = tally_by_significance(daily_log, 'notable') if os.path.isfile(daily_log) else 0
    pivotal_today = tally_by_significance(daily_log, 'pivotal') if os.path.isfile(daily_log) else 0
    observations['notable_count'] = notable_today
    observations['pivotal_count'] = pivotal_today

    if (notable_today + pivotal_today) > 0 and not os.path.isfile(significant_log):
        problems.append({
            'type': 'promotion_check',
            'description': f"{notable_today} notable + {pivotal_today} pivotal entries found today, "
                           f"but significant.jsonl is absent. Promotion required."
        })

    # ========================================
    # 3. Check reflection status across all experience logs
    # ========================================
    reflections_folder = os.path.join(memory_path, 'reflections')
    unprocessed_notable = 0
    unprocessed_pivotal = 0

    if os.path.isdir(experiences_folder):
        for log_file in glob.glob(os.path.join(experiences_folder, '*.jsonl')):
            if os.path.isfile(log_file):
                with open(log_file, encoding='utf-8', errors='ignore') as stream:
                    for entry_line in stream:
                        entry_line = entry_line.strip()
                        if not entry_line:
                            continue
                        try:
                            item = json.loads(entry_line)
                            if item.get('reflected') is False:
                                sig_val = item.get('significance', '')
                                if sig_val == 'notable':
                                    unprocessed_notable += 1
                                elif sig_val == 'pivotal':
                                    unprocessed_pivotal += 1
                        except json.JSONDecodeError:
                            continue

    observations['unprocessed_notable'] = unprocessed_notable
    observations['unprocessed_pivotal'] = unprocessed_pivotal

    if unprocessed_pivotal > 0:
        problems.append({
            'type': 'pivotal_reflection',
            'description': f"{unprocessed_pivotal} pivotal experience(s) lack reflection. "
                           f"Immediate attention required."
        })

    # Count reflection files
    if os.path.isdir(reflections_folder):
        reflection_files = glob.glob(os.path.join(reflections_folder, 'REF-*.json'))
        observations['reflection_total'] = len(reflection_files)
        active_refs = [f for f in reflection_files if is_file_newer_than(f, threshold_time)]
        observations['recent_reflections'] = len(active_refs)
    else:
        observations['reflection_total'] = 0
        observations['recent_reflections'] = 0
        if (notable_today + pivotal_today) > 0:
            alerts.append({
                'type': 'reflection_dir',
                'description': 'Reflections directory missing despite notable/pivotal entries.'
            })

    # ========================================
    # 4. Confirm state file exists and is updated
    # ========================================
    state_file = os.path.join(memory_path, 'evoclaw-state.json')
    if not os.path.isfile(state_file):
        problems.append({
            'type': 'state_file',
            'description': f"State file absent: {state_file}. Pipeline must update it per heartbeat."
        })
        observations['state_file'] = 'MISSING'
    else:
        observations['state_file'] = get_modification_timestamp(state_file)
        if not is_file_newer_than(state_file, threshold_time):
            alerts.append({
                'type': 'state_file',
                'description': f"State file stale for {minutes_threshold} minutes. "
                               f"Last update: {get_modification_timestamp(state_file)}"
            })

    # ========================================
    # 5. Validate pending proposals consistency
    # ========================================
    if os.path.isfile(state_file):
        try:
            with open(state_file) as source:
                system_state = json.load(source)
            pending_proposals = system_state.get('pending_proposals_count', 0)
            if pending_proposals > 0:
                pending_file = os.path.join(memory_path, 'proposals', 'pending.jsonl')
                if not os.path.isfile(pending_file):
                    problems.append({
                        'type': 'pending_proposals',
                        'description': f"State reports {pending_proposals} pending proposals, "
                                       f"but pending.jsonl is missing."
                    })
            observations['reported_pending'] = pending_proposals
        except (json.JSONDecodeError, OSError):
            pass

    # ========================================
    # Final evaluation
    # ========================================
    outcome = 'FAILURE' if problems else 'SUCCESS'
    return {
        'result': outcome,
        'directory': memory_path,
        'timestamp': current_time.isoformat(),
        'lookback_minutes': minutes_threshold,
        'issues': problems,
        'alerts': alerts,
        'metrics': observations
    }


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: check_pipeline_ran.py <memory_dir> [--since-minutes 30]', file=sys.stderr)
        sys.exit(2)

    memory_path = sys.argv[1]
    lookback = 30

    if '--since-minutes' in sys.argv:
        position = sys.argv.index('--since-minutes')
        if position + 1 < len(sys.argv):
            try:
                lookback = int(sys.argv[position + 1])
            except ValueError:
                lookback = 30

    output = assess_pipeline(memory_path, lookback)
    print(json.dumps(output, indent=2))
    sys.exit(0 if output['result'] == 'SUCCESS' else 1)

import os
import platform
import shutil
import subprocess
from collections import defaultdict
import psutil
from vllm.logger import logger
from vllm_ascend.utils import AscendDeviceType, get_ascend_device_type

# Constants
CPU_MASK_WIDTH = 32  # bits per mask group
MIN_CPU_PER_NPU = 5  # IRQ(2) + main(1+) + acl(1) + release(1)
STATUS_PATH = "/proc/self/status"
VISIBLE_DEVICES_ENV = os.getenv("ASCEND_RT_VISIBLE_DEVICES")

BINDING_MODES = {
    "topo_affinity": "topo_affinity",
    "global_slice": "global_slice",
}
DEVICE_POLICY = {
    AscendDeviceType.A2: BINDING_MODES["topo_affinity"],
    AscendDeviceType.A3: BINDING_MODES["global_slice"],
    AscendDeviceType._310P: BINDING_MODES["topo_affinity"],
}


def detect_arm_architecture() -> bool:
    cpu_arch = platform.machine().lower()
    if cpu_arch in {"x86_64", "amd64", "i386", "i686"}:
        return False
    elif cpu_arch in {"aarch64", "arm64"} or cpu_arch.startswith("arm"):
        return True
    else:
        logger.warning(f"Unrecognized CPU architecture '{cpu_arch}'. CPU binding will be skipped.")
        return False


def run_subprocess(cmd_args: list[str]) -> tuple[str, int]:
    proc = subprocess.Popen(cmd_args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=False)
    try:
        stdout_data, _ = proc.communicate(timeout=1000)
    except Exception as e:
        logger.error(f"Subprocess failed: {e}")
        return "", -1
    return stdout_data.decode(), proc.returncode


class HardwareInfo:
    def __init__(self):
        self.npu_topology_map: dict[str, dict[str, str]] = self.fetch_npu_topology()
        self.permitted_cpus: list[int] = self.extract_cpu_affinity()
        self.active_npus: list[int] = self.identify_active_npus()
        self.cpu_affinity_per_npu: dict[int, list[int]] = self.parse_cpu_affinity_from_topo()
        self.all_logical_npus: list[int] = self.collect_all_logic_ids()
        self.total_logical_npus: int = len(self.all_logical_npus)

    @staticmethod
    def parse_cpu_ranges(range_str: str) -> list[int]:
        result = []
        for segment in range_str.split(","):
            if "-" in segment:
                low, high = map(int, segment.split("-"))
                result.extend(range(low, high + 1))
            else:
                result.append(int(segment))
        return result

    def collect_all_logic_ids(self) -> list[int]:
        ids_set = set()
        for _, chip_dict in self.npu_topology_map.items():
            for _, logical_id_str in chip_dict.items():
                if logical_id_str.isdigit():
                    ids_set.add(int(logical_id_str))
        return sorted(ids_set)

    @staticmethod
    def fetch_npu_topology() -> dict[str, dict[str, str]]:
        topology_output, _ = run_subprocess(["npu-smi", "info", "-m"])
        lines = topology_output.strip().split("\n")[1:]
        npu_topology: dict[str, dict[str, str]] = {}
        for line in lines:
            parts = line.strip().split()
            if len(parts) < 3:
                continue
            board_id, chip_id, logic_id = parts[:3]
            if not logic_id.isdigit():
                continue
            if board_id not in npu_topology:
                npu_topology[board_id] = {}
            npu_topology[board_id][chip_id] = logic_id
        return npu_topology

    def identify_active_npus(self) -> list[int]:
        status_output, _ = run_subprocess(["npu-smi", "info"])
        in_process_section = False
        active_set = set()

        for line in status_output.splitlines():
            stripped = line.strip()
            if "Process id" in stripped and stripped.startswith("| NPU"):
                in_process_section = True
                continue
            if not in_process_section:
                continue
            if stripped.startswith("| "):
                tokens = [t.strip() for t in stripped.strip("|").split("|")]
                if len(tokens) < 2:
                    continue
                parts = tokens[0].split()
                if len(parts) < 2:
                    continue
                board_num, chip_num = parts[0], parts[1]
                if not board_num.isdigit() or not chip_num.isdigit():
                    continue
                logic_val = self.npu_topology_map.get(board_num, {}).get(chip_num)
                if not logic_val or not logic_val.isdigit():
                    raise RuntimeError("Failed to retrieve valid logical NPU ID from 'npu-smi info -m'.")
                active_set.add(int(logic_val))

        if VISIBLE_DEVICES_ENV:
            visible_list = [int(x) for x in VISIBLE_DEVICES_ENV.split(",")]
            active_set &= set(visible_list)

        if not active_set:
            raise RuntimeError("Unable to determine active NPUs.")

        return sorted(active_set)

    def extract_cpu_affinity(self) -> list[int]:
        if not os.path.isfile(STATUS_PATH):
            return []
        with open(STATUS_PATH) as f:
            for row in f:
                if row.startswith("Cpus_allowed_list"):
                    affinity_str = row.split()[1]
                    return self.parse_cpu_ranges(affinity_str)
        raise RuntimeError("Could not find 'Cpus_allowed_list' in /proc/self/status.")

    def parse_cpu_affinity_from_topo(self) -> dict[int, list[int]]:
        topo_output, _ = run_subprocess(["npu-smi", "info", "-t", "topo"])
        affinity_map: dict[int, list[int]] = {}
        npu_counter = 0
        for line in topo_output.splitlines():
            if line.startswith("NPU"):
                tokens = line.split()
                last_token = tokens[-1]
                if last_token != "Affinity":
                    affinity_map[npu_counter] = self.parse_cpu_ranges(last_token)
                npu_counter += 1
        return affinity_map


class CpuScheduler:
    def __init__(self, local_rank: int):
        self.local_rank = local_rank
        self.hardware: HardwareInfo = HardwareInfo()
        self.cpu_to_numa: dict[int, int] = {}
        self.numa_to_cpu: dict[int, list[int]] = defaultdict(list)
        self.cpu_pool_per_npu: dict[int, list[int]] = {}
        self.main_threads: dict[int, list[int]] = {}
        self.acl_threads: dict[int, list[int]] = {}
        self.release_threads: dict[int, list[int]] = {}

    @staticmethod
    def encode_cpu_mask(cpu_index: int) -> str:
        group_index = cpu_index // CPU_MASK_WIDTH
        bit_offset = cpu_index % CPU_MASK_WIDTH
        value = 1 << bit_offset
        hex_part = f"{value:08x}"
        suffix = "," + ",".join(["0" * (CPU_MASK_WIDTH // 4)] * group_index)
        return hex_part + suffix

    @staticmethod
    def build_thread_registry(thread_info: str) -> dict[str, dict[str, list[str]]]:
        registry: dict[str, dict[str, list[str]]] = {}
        for line in thread_info.splitlines():
            tokens = line.split()
            if len(tokens) < 2:
                continue
            parent_pid, child_pid = tokens[0], tokens[1]
            if "acl_thread" in line:
                thread_type = "acl_thread"
            elif "release_thread" in line:
                thread_type = "release_thread"
            else:
                continue
            if parent_pid not in registry:
                registry[parent_pid] = {"acl_thread": [], "release_thread": []}
            registry[parent_pid][thread_type].append(child_pid)
        return registry

    @staticmethod
    def apply_binding(pid: str, cpus: list[int], include_subthreads: bool) -> None:
        if cpus:
            cpu_str = ",".join(map(str, cpus))
            cmd = ["taskset", "-acp", cpu_str, pid] if include_subthreads else ["taskset", "-cp", cpu_str, pid]
            output, code = run_subprocess(cmd)
            if code != 0:
                raise RuntimeError(f"Binding PID {pid} to CPUs {cpu_str} failed.")

    def evenly_distribute(self, groups: dict[str, list[int]]) -> dict[int, list[int]]:
        distribution: dict[int, list[int]] = {}
        for key, npu_group in groups.items():
            base_pool = sorted(self.cpu_pool_per_npu[npu_group[0]])
            slice_size = len(base_pool) // len(npu_group)
            for idx, npu in enumerate(npu_group):
                start = idx * slice_size
                end = (idx + 1) * slice_size if idx < len(npu_group) - 1 else len(base_pool)
                distribution[npu] = base_pool[start:end]
        return distribution

    def extend_to_next_numa(self, cpu_list: list[int]) -> list[int]:
        if not cpu_list:
            return []
        current_nodes = {self.cpu_to_numa[c] for c in cpu_list}
        if len(current_nodes) != 1:
            return cpu_list
        node = list(current_nodes)[0]
        next_node = (node + 1) % len(self.numa_to_cpu)
        extended = cpu_list[:]
        for candidate in self.numa_to_cpu[next_node]:
            if candidate in self.hardware.permitted_cpus:
                extended.append(candidate)
        return sorted(set(extended))

    def map_cpu_to_numa(self) -> None:
        numa_info, _ = run_subprocess(["lscpu", "-e=CPU,NODE"])
        for entry in numa_info.splitlines():
            entry = entry.strip()
            if not entry or not entry[0].isdigit():
                continue
            cpu_id, node_id = map(int, entry.split())
            self.cpu_to_numa[cpu_id] = node_id
            self.numa_to_cpu[node_id].append(cpu_id)
        if not self.numa_to_cpu:
            raise RuntimeError("lscpu returned no NUMA nodes. Please verify system configuration.")

    def construct_global_slice_pools(self) -> None:
        active_npus = list(self.hardware.active_npus)
        if not active_npus:
            return
        allowed = sorted(set(self.hardware.permitted_cpus))
        total_cpus = len(allowed)
        if total_cpus == 0:
            return

        # Determine total number of logical NPUs
        if self.hardware.total_logical_npus > 0:
            total_npus = self.hardware.total_logical_npus
        elif self.hardware.cpu_affinity_per_npu:
            total_npus = len(self.hardware.cpu_affinity_per_npu)
        else:
            total_npus = len(active_npus)

        if total_npus <= 0:
            return

        base = total_cpus // total_npus
        remainder = total_cpus % total_npus

        logger.debug(
            f"[cpu_global_slice] rank:{self.local_rank} ASCEND_RT_VISIBLE_DEVICES={VISIBLE_DEVICES_ENV} "
            f"active_npus:{active_npus} total_npus:{total_npus} total_cpus:{total_cpus} "
            f"base:{base} remainder:{remainder} head:{allowed[:16]} tail:{allowed[-16:]}"
        )

        if base < MIN_CPU_PER_NPU:
            raise RuntimeError(
                f"Not enough CPUs for proper allocation: {total_cpus} CPUs shared across {total_npus} NPUs "
                f"(minimum required: {total_npus * MIN_CPU_PER_NPU})."
            )

        def compute_slice(global_id: int) -> list[int]:
            offset = global_id * base + min(global_id, remainder)
            take = base + (1 if global_id < remainder else 0)
            return allowed[offset:offset + take]

        for npu_id in active_npus:
            if npu_id < 0 or npu_id >= total_npus:
                raise RuntimeError(f"Invalid NPU ID {npu_id}, expected 0..{total_npus - 1}.")
            cpus = compute_slice(npu_id)
            if len(cpus) < MIN_CPU_PER_NPU:
                raise RuntimeError(
                    f"NPU{npu_id} received insufficient CPUs ({len(cpus)} < {MIN_CPU_PER_NPU})."
                )
            self.cpu_pool_per_npu[npu_id] = cpus

    @staticmethod
    def determine_binding_strategy() -> str:
        device_type = get_ascend_device_type()
        return DEVICE_POLICY.get(device_type, BINDING_MODES["topo_affinity"])

    def build_cpu_resource_pools(self) -> None:
        self.map_cpu_to_numa()
        strategy = self.determine_binding_strategy()
        logger.info(f"[cpu_bind_mode] mode={strategy} rank={self.local_rank} visible_npus={self.hardware.active_npus}")

        if strategy == BINDING_MODES["global_slice"]:
            self.construct_global_slice_pools()
            return

        # Fallback to topo-based method
        if not self.hardware.cpu_affinity_per_npu:
            logger.warning("No topology affinity data; falling back to global slicing.")
            self.construct_global_slice_pools()
            return

        for npu in self.hardware.active_npus:
            raw_list = [
                cpu for cpu in self.hardware.cpu_affinity_per_npu.get(npu, [])
                if cpu in self.hardware.permitted_cpus
            ]
            if not raw_list:
                raise RuntimeError("CPUs from affinity conflict with allowed list.")
            extended = self.extend_to_next_numa(raw_list)
            self.cpu_pool_per_npu[npu] = extended

        # Group identical pools and redistribute evenly
        grouped: dict[str, list[int]] = defaultdict(list)
        for npu_id, pool in self.cpu_pool_per_npu.items():
            grouped[str(pool)].append(npu_id)

        final: dict[int, list[int]] = {}
        for pool_key, npu_list in grouped.items():
            if len(npu_list) == 1:
                final[npu_list[0]] = self.cpu_pool_per_npu[npu_list[0]]
            else:
                final.update(self.evenly_distribute({pool_key: npu_list}))
        self.cpu_pool_per_npu = final

    def assign_resources(self) -> None:
        for npu_id, pool in self.cpu_pool_per_npu.items():
            if len(pool) >= MIN_CPU_PER_NPU:
                self.main_threads[npu_id] = pool[2:-2]
                self.acl_threads[npu_id] = [pool[-2]]
                self.release_threads[npu_id] = [pool[-1]]
            else:
                raise RuntimeError(
                    f"Insufficient CPUs for NPU{npu_id}: need at least {MIN_CPU_PER_NPU}, got {len(pool)}."
                )

    def log_allocation(self) -> None:
        logger.info("CPU allocation plan:")
        target_npu = self.hardware.active_npus[self.local_rank]
        main_str = " ".join(map(str, self.main_threads[target_npu]))
        acl_str = " ".join(map(str, self.acl_threads[target_npu]))
        rel_str = str(self.release_threads[target_npu]) if self.release_threads[target_npu] else ""
        logger.info(f"NPU{target_npu}: main=[{main_str}]  acl=[{acl_str}]  release=[{rel_str}]")

    def bind_memory_to_numa(self, pid: str, npu_id: int) -> None:
        def locate_numa_for_npu(npu: int) -> int | None:
            pool = self.cpu_pool_per_npu.get(npu, [])
            if not pool:
                return None
            anchor = pool[0]
            return self.cpu_to_numa.get(anchor)

        if not shutil.which("migratepages"):
            logger.info("'migratepages' not found; skipping memory binding.")
            return

        target_node = locate_numa_for_npu(npu_id)
        if target_node is None:
            logger.warning(f"[migrate] rank:{self.local_rank} -> NPU{npu_id} has no CPU pool.")
            return

        all_nodes = sorted(self.numa_to_cpu.keys())
        if target_node not in all_nodes:
            logger.warning(f"[migrate] NPU{npu_id} -> NUMA {target_node} unavailable.")
            return

        logger.info(f"[migrate] NPU{npu_id} -> NUMA [{target_node}]")
        run_subprocess([
            "migratepages",
            pid,
            ",".join(map(str, all_nodes)),
            str(target_node),
        ])

    def bind_subprocess_threads(self) -> None:
        thread_dump, _ = run_subprocess(["ps", "-Te"])
        thread_registry = self.build_thread_registry(thread_dump)
        main_pid = str(psutil.Process().pid)
        target_npu = self.hardware.active_npus[self.local_rank]

        self.apply_binding(main_pid, self.main_threads[target_npu], True)

        for sub_pid in thread_registry.get(main_pid, {}).get("acl_thread", []):
            self.apply_binding(sub_pid, self.acl_threads[target_npu], False)
            self.bind_memory_to_numa(sub_pid, target_npu)

        for sub_pid in thread_registry.get(main_pid, {}).get("release_thread", []):
            self.apply_binding(sub_pid, self.release_threads[target_npu], False)

    def bind_interrupts(self) -> None:
        if not os.access("/proc/irq", os.W_OK):
            return

        target_npu = self.hardware.active_npus[self.local_rank]
        if target_npu not in self.cpu_pool_per_npu:
            logger.warning(f"[irq] rank:{self.local_rank} -> NPU{target_npu} lacks CPU pool.")
            return

        # Stop irqbalance if running
        if shutil.which("systemctl"):
            systemctl_status, _ = run_subprocess(["systemctl", "list-unit-files"])
            if "irqbalance.service" in systemctl_status:
                _, rc = run_subprocess(["systemctl", "is-active", "--quiet", "irqbalance"])
                if rc == 0:
                    logger.warning("Stopping irqbalance service...")
                    run_subprocess(["systemctl", "stop", "irqbalance"])

        # Collect SQ IRQs
        sq_irqs = []
        with open("/proc/interrupts") as f:
            for line in f:
                if "sq_send_trigger_irq" in line:
                    irq_id = line.split(":")[0].strip()
                    sq_irqs.append(irq_id)

        pool = self.cpu_pool_per_npu[target_npu]
        if len(pool) < 2:
            logger.warning(f"[irq] NPU{target_npu} pool too small (<2), skipping IRQ binding.")
            return

        sq_cpu, cq_cpu = pool[0], pool[1]
        pci_address = ""

        device_type = get_ascend_device_type()
        if device_type == AscendDeviceType.A3:
            card_id = target_npu // 2
            chip_id = target_npu % 2
            board_info, _ = run_subprocess(["npu-smi", "info", "-t", "board", "-i", str(card_id), "-c", str(chip_id)])
        else:
            board_info, _ = run_subprocess(["npu-smi", "info", "-t", "board", "-i", str(target_npu)])

        for line in board_info.splitlines():
            if "PCIe Bus Info" in line:
                pci_address = line.split()[-1].lower()
                break

        if not pci_address:
            logger.warning(f"Could not determine PCIe address for NPU{target_npu}.")
            return

        try:
            msi_irqs = sorted(os.listdir(f"/sys/bus/pci/devices/{pci_address}/msi_irqs/"), key=lambda x: int(x))
        except FileNotFoundError:
            logger.warning(f"MSI IRQ directory missing for PCI {pci_address}.")
            return

        sq_irq, cq_irq = "", ""
        for irq in sq_irqs:
            if irq in msi_irqs:
                sq_irq = irq
                cq_irq = str(int(irq) + 1)
                break

        if not sq_irq:
            logger.warning(f"Could not locate SQ IRQ for NPU{target_npu}.")
            return

        logger.info(
            f"NPU{target_npu}(PCI {pci_address}): SQ IRQ {sq_irq} → CPU{sq_cpu}, "
            f"CQ IRQ {cq_irq} → CPU{cq_cpu}"
        )

        with open(f"/proc/irq/{sq_irq}/smp_affinity", "w") as f:
            f.write(self.encode_cpu_mask(sq_cpu))
        with open(f"/proc/irq/{cq_irq}/smp_affinity", "w") as f:
            f.write(self.encode_cpu_mask(cq_cpu))

    def execute_full_binding(self) -> None:
        self.build_cpu_resource_pools()
        self.assign_resources()
        self.log_allocation()
        self.bind_subprocess_threads()
        self.bind_interrupts()


def perform_cpu_binding(rank_id: int) -> None:
    if not detect_arm_architecture():
        logger.info("Skipping CPU binding: non-ARM CPU detected.")
        return
    scheduler = CpuScheduler(rank_id)
    scheduler.execute_full_binding()

# Type III Clone: Refactored constraint handling with equivalent logic and behavior

from abc import ABC, abstractmethod
from typing import List, Optional, Union

class BaseConstraint(ABC):
    r"""
    Abstract base class for constraints in generation processes.
    Ensures that all derived classes implement methods to advance, update, and reset state.
    """
    def __init__(self):
        self._validate_implementation()

    def _validate_implementation(self):
        """Internal validation to ensure the constraint behaves correctly."""
        steps = 0
        finished = False
        while not finished:
            if steps == 1:
                self.restart()
            next_step = self.propose_next()
            if not self.confirms_progress(next_step):
                raise ValueError(
                    "Custom Constraint implementation is invalid. self.confirms_progress(self.propose_next()) must be true."
                )
            progress_made, finished, reset_occurred = self.apply_step(next_step)
            steps += 1
            if steps > 10000:
                raise ValueError("apply_step() does not terminate properly.")
        if self.steps_remaining() != 0:
            raise ValueError("Custom Constraint is not properly defined.")

    @abstractmethod
    def propose_next(self):
        """Returns the token(s) needed to make one step toward completion."""
        raise NotImplementedError

    @abstractmethod
    def confirms_progress(self, token):
        """Checks whether a given token contributes to progress."""
        raise NotImplementedError

    @abstractmethod
    def apply_step(self, token):
        """Updates internal state based on a token and returns status flags."""
        raise NotImplementedError

    @abstractmethod
    def restart(self):
        """Resets the constraint's internal state."""
        raise NotImplementedError

    @abstractmethod
    def steps_remaining(self):
        """Returns how many more steps are needed to complete this constraint."""
        raise NotImplementedError

    @abstractmethod
    def clone(self, preserve_state=False):
        """Creates a new instance of this constraint, optionally preserving current state."""
        raise NotImplementedError


class SequentialConstraint(BaseConstraint):
    r"""
    Enforces that a specific ordered sequence of tokens appears in the output.
    """
    def __init__(self, token_sequence: List[int]):
        super().__init__()
        if not isinstance(token_sequence, list) or len(token_sequence) == 0:
            raise ValueError(f"`token_sequence` must be a non-empty list, got {token_sequence}")
        if any(not isinstance(t, int) or t < 0 for t in token_sequence):
            raise ValueError(f"All tokens in `token_sequence` must be non-negative integers, got {token_sequence}")

        self.token_sequence = token_sequence
        self.total_length = len(token_sequence)
        self.fulfilled_index = -1
        self.is_complete = False

    def propose_next(self):
        if self.is_complete:
            return None
        return self.token_sequence[self.fulfilled_index + 1]

    def confirms_progress(self, token):
        if not isinstance(token, int):
            raise TypeError(f"`token` must be an integer, got {type(token)}")
        if self.is_complete:
            return False
        return token == self.token_sequence[self.fulfilled_index + 1]

    def apply_step(self, token):
        if not isinstance(token, int):
            raise TypeError(f"`token` must be an integer, got {type(token)}")

        made_progress = False
        completed = False
        reset_flag = False

        if self.confirms_progress(token):
            self.fulfilled_index += 1
            made_progress = True
            if self.fulfilled_index == self.total_length - 1:
                completed = True
            self.is_complete = completed
        else:
            reset_flag = True
            self.restart()

        return made_progress, completed, reset_flag

    def restart(self):
        self.is_complete = False
        self.fulfilled_index = -1

    def steps_remaining(self):
        return self.total_length - (self.fulfilled_index + 1)

    def clone(self, preserve_state=False):
        new_constraint = SequentialConstraint(self.token_sequence)
        if preserve_state:
            new_constraint.total_length = self.total_length
            new_constraint.fulfilled_index = self.fulfilled_index
            new_constraint.is_complete = self.is_complete
        return new_constraint


class TrieStructure:
    def __init__(self, token_lists: List[List[int]], enforce_no_subsets=True):
        """Builds a trie from multiple token sequences."""
        self.max_depth = max(len(seq) for seq in token_lists) if token_lists else 0

        root = {}
        for tokens in token_lists:
            current_level = root
            for token in tokens:
                if token not in current_level:
                    current_level[token] = {}
                current_level = current_level[token]

        if enforce_no_subsets and self.contains_subset_patterns(root, token_lists):
            raise ValueError(
                "Token sequences cannot contain subsets of other sequences, "
                f"but received {token_lists}"
            )

        self.trie = root

    def possible_next_tokens(self, current_path):
        """Get the set of valid next tokens given the current path."""
        node = self.trie
        for token in current_path:
            node = node[token]
        return list(node.keys())

    def at_leaf_node(self, current_path):
        return len(self.possible_next_tokens(current_path)) == 0

    def count_terminal_nodes(self, node):
        children = list(node.values())
        if not children:
            return 1
        return sum(self.count_terminal_nodes(child) for child in children)

    def contains_subset_patterns(self, trie_root, token_lists):
        leaf_count = self.count_terminal_nodes(trie_root)
        return len(token_lists) != leaf_count


class AlternativeConstraint(BaseConstraint):
    r"""
    A constraint that is satisfied when *any one* of several possible token sequences is generated.
    """
    def __init__(self, alternatives: List[List[int]]):
        super().__init__()
        if not isinstance(alternatives, list) or len(alternatives) == 0:
            raise ValueError(f"`alternatives` must be a non-empty list, got {alternatives}")
        if any(not isinstance(seq, list) for seq in alternatives):
            raise ValueError(f"`alternatives` must be a list of lists, got {alternatives}")
        if any(
            any(not isinstance(token, int) or token < 0 for token in seq)
            for seq in alternatives
        ):
            raise ValueError(
                f"All tokens in `alternatives` must be non-negative integers, got {alternatives}"
            )

        self.trie = TrieStructure(alternatives)
        self.alternatives = alternatives
        self.max_depth = self.trie.max_depth
        self.current_path = []
        self.is_complete = False

    def propose_next(self):
        candidates = self.trie.possible_next_tokens(self.current_path)
        return candidates if candidates else None

    def confirms_progress(self, token):
        if not isinstance(token, int):
            raise TypeError(f"`token` must be an integer, got {type(token)}")
        return token in self.trie.possible_next_tokens(self.current_path)

    def apply_step(self, token):
        if not isinstance(token, int):
            raise TypeError(f"`token` must be an integer, got {type(token)}")

        made_progress = False
        completed = False
        reset_flag = False

        if self.confirms_progress(token):
            self.current_path.append(token)
            made_progress = True
        else:
            reset_flag = True
            self.restart()

        completed = self.trie.at_leaf_node(self.current_path)
        self.is_complete = completed

        return made_progress, completed, reset_flag

    def restart(self):
        self.is_complete = False
        self.current_path = []

    def steps_remaining(self):
        if self.is_complete:
            return 0
        return self.max_depth - len(self.current_path)

    def clone(self, preserve_state=False):
        new_constraint = AlternativeConstraint(self.alternatives)
        if preserve_state:
            new_constraint.max_depth = self.max_depth
            new_constraint.current_path = self.current_path.copy()
            new_constraint.is_complete = self.is_complete
        return new_constraint


class ConstraintManager:
    r"""
    Manages a collection of constraints during generation.
    Tracks which constraints are pending, in-progress, or completed.
    """
    def __init__(self, constraints: List[BaseConstraint]):
        self.constraints = constraints
        self.max_steps_needed = max(c.steps_remaining() for c in constraints) if constraints else 0
        self.total_constraints = len(constraints)
        self.is_fully_satisfied = False
        self.reset_state()

    def reset_state(self):
        self.completed_constraints = []
        self.active_constraint = None
        self.pending_constraints = [c.clone(preserve_state=False) for c in self.constraints]

    def calculate_score(self):
        score = 0
        if self.active_constraint:
            score += self.max_steps_needed - self.active_constraint.steps_remaining()
        return (len(self.completed_constraints) * self.max_steps_needed) + score

    def suggest_tokens(self):
        """Returns tokens that would make progress toward satisfying any constraint."""
        candidates = []
        if self.active_constraint is None:
            for constraint in self.pending_constraints:
                next_token = constraint.propose_next()
                if isinstance(next_token, int):
                    candidates.append(next_token)
                elif isinstance(next_token, list):
                    candidates.extend(next_token)
        else:
            next_token = self.active_constraint.propose_next()
            if isinstance(next_token, int):
                candidates.append(next_token)
            elif isinstance(next_token, list):
                candidates.extend(next_token)
        return candidates if candidates else None

    def restore_from_history(self, history_tokens: Optional[List[int]]):
        """Resets state and applies tokens from a generation history."""
        self.reset_state()
        if history_tokens:
            for token in history_tokens:
                _, _ = self.process_token(token)
                if self.is_fully_satisfied:
                    break

    def process_token(self, token):
        if not isinstance(token, int):
            raise TypeError(f"`token` must be an integer, got {type(token)}")

        completed = False
        made_progress = False

        if self.is_fully_satisfied:
            completed = True
            return completed, made_progress

        if self.active_constraint is not None:
            made_progress, completed, reset_happened = self.active_constraint.apply_step(token)

            if reset_happened:
                self.pending_constraints.append(self.active_constraint.clone(preserve_state=False))
                self.active_constraint = None

            if completed:
                self.completed_constraints.append(self.active_constraint)
                self.active_constraint = None
                if not self.pending_constraints:
                    self.is_fully_satisfied = True
        else:
            for idx, pending in enumerate(self.pending_constraints):
                if pending.confirms_progress(token):
                    made_progress, completed, reset_happened = pending.apply_step(token)

                    if not made_progress:
                        raise ValueError(
                            "Constraint reported progress but apply_step() did not reflect it."
                        )

                    if completed:
                        self.completed_constraints.append(pending)
                        self.active_constraint = None
                    elif made_progress:
                        self.active_constraint = pending

                    if completed or made_progress:
                        self.pending_constraints = (
                            self.pending_constraints[:idx] + self.pending_constraints[idx+1:]
                        )
                        if not self.pending_constraints and self.active_constraint is None:
                            self.is_fully_satisfied = True
                        break

        return completed, made_progress

    def duplicate(self, preserve_states=True):
        new_manager = ConstraintManager(self.constraints)
        if preserve_states:
            new_manager.completed_constraints = [
                c.clone(preserve_state=True) for c in self.completed_constraints
            ]
            if self.active_constraint is not None:
                new_manager.active_constraint = self.active_constraint.clone(preserve_state=True)
            new_manager.pending_constraints = [
                c.clone(preserve_state=False) for c in self.pending_constraints
            ]
        return new_manager

import contextlib
import itertools
import logging
import sys
import time
from typing import IO, Generator, Optional
from pip._internal.utils.compat import WINDOWS
from pip._internal.utils.logging import get_indentation

logger = logging.getLogger(__name__)

class SpinnerBase:
    def spin(self) -> None:
        raise NotImplementedError()

    def finish(self, status: str) -> None:
        raise NotImplementedError()

class AnimatedSpinner(SpinnerBase):
    def __init__(
        self,
        text: str,
        stream: Optional[IO[str]] = None,
        symbols: str = "-\\|/",
        # Update every 125ms for smooth animation
        delay_seconds: float = 0.125,
    ):
        self._text = text
        self._stream = stream if stream is not None else sys.stdout
        self._timer = Timer(delay_seconds)
        self._done = False
        self._rotator = itertools.cycle(symbols)
        indent = " " * get_indentation()
        self._stream.write(f"{indent}{self._text} ... ")
        self._last_len = 0

    def _render(self, content: str) -> None:
        assert not self._done
        # Clear previous output using backspaces and spaces
        clear_seq = "\b" * self._last_len
        self._stream.write(clear_seq + " " * self._last_len + clear_seq)
        # Write new status
        self._stream.write(content)
        self._last_len = len(content)
        self._stream.flush()
        self._timer.mark()

    def spin(self) -> None:
        if self._done or not self._timer.should_update():
            return
        self._render(next(self._rotator))

    def finish(self, status: str) -> None:
        if self._done:
            return
        self._render(status)
        self._stream.write("\n")
        self._stream.flush()
        self._done = True

class PassiveSpinner(SpinnerBase):
    def __init__(self, label: str, check_interval: float = 60.0) -> None:
        self._label = label
        self._completed = False
        self._timer = Timer(check_interval)
        self._log("initializing")

    def _log(self, message: str) -> None:
        assert not self._completed
        self._timer.mark()
        logger.info("%s: %s", self._label, message)

    def spin(self) -> None:
        if self._completed or not self._timer.should_update():
            return
        self._log("still processing...")

    def finish(self, result: str) -> None:
        if self._completed:
            return
        self._log(f"completed with status '{result}'")
        self._completed = True

class Timer:
    def __init__(self, min_delay: float) -> None:
        self._min_delay = min_delay
        self._last_time = 0.0

    def should_update(self) -> bool:
        current = time.time()
        return (current - self._last_time) >= self._min_delay

    def mark(self) -> None:
        self._last_time = time.time()

@contextlib.contextmanager
def progress_indicator(message: str) -> Generator[SpinnerBase, None, None]:
    # Choose spinner based on terminal capability and log level
    if sys.stdout.isatty() and logger.getEffectiveLevel() <= logging.INFO:
        spinner_obj: SpinnerBase = AnimatedSpinner(message)
    else:
        spinner_obj = PassiveSpinner(message)

    try:
        with cursor_control(sys.stdout):
            yield spinner_obj
    except KeyboardInterrupt:
        spinner_obj.finish("interrupted")
        raise
    except Exception:
        spinner_obj.finish("failed")
        raise
    else:
        spinner_obj.finish("success")

HIDE_CURSOR_CODE = "\x1b[?25l"
SHOW_CURSOR_CODE = "\x1b[?25h"

@contextlib.contextmanager
def cursor_control(output_stream: IO[str]) -> Generator[None, None, None]:
    # Skip cursor control on Windows and non-TTY outputs
    if WINDOWS:
        yield
    elif not output_stream.isatty() or logger.getEffectiveLevel() > logging.INFO:
        yield
    else:
        output_stream.write(HIDE_CURSOR_CODE)
        try:
            yield
        finally:
            output_stream.write(SHOW_CURSOR_CODE)

# Type III Clone: Reshape module with equivalent functionality but different implementation logic

import jax.numpy as np
from beartype import beartype
from jaxtyping import jaxtyped
from ..tree_util import is_shape_leaf
from ..typing import (
    Any,
    ArrayData,
    ArrayDataShape,
    Data,
    DataShape,
    HyperParams,
    ModuleCallable,
    Params,
    State,
    Tuple,
)
from .basemodule import BaseModule

class Reshape(BaseModule):
    """
    Module that reshapes the input array to a specified shape. Ignores the
    batch dimension.
    """
    __version__: str = "0.0.0"

    def __init__(self, target_dims: DataShape = None) -> None:
        """
        Initialize a ``Reshape`` module.
        Parameters
        ----------
        target_dims
            The target dimensions to reshape the input to, by default None.
            If None, the input shape will remain unchanged.
            Does not include the batch dimension. If the input to the module is
            a PyTree, then ``target_dims`` should be a PyTree of matching structure.
            Any ``None`` values in the PyTree will leave the corresponding leaf
            arrays unchanged.
        Examples
        --------
        .. code-block:: python
            # Prepare to accept only bare array data (no PyTrees) and reshape
            # to (2, 3)
            reshape_module = Reshape(target_dims=(2, 3))
            # Prepare to accept a PyTree of arrays with structure [*, (*, *)]
            # and reshape the first leaf to (2, 3), leave the second leaf
            # unchanged, and flatten the final leaf
            reshape_module = Reshape(target_dims=[(2, 3), (None, (-1,))])
        """
        # Validate target_dims structure
        if target_dims is None:
            self.target_dims = target_dims
            return

        # Check if target_dims is iterable
        try:
            len(target_dims)
        except TypeError:
            raise AssertionError(
                "Target dimensions must be a tuple, list, or PyTree of dimensions."
            )

        # Handle special case where all elements are integers
        if all(isinstance(d, int) for d in target_dims):
            pass
        elif any(isinstance(d, int) for d in target_dims):
            # Mixed types - some integers, some not - invalid configuration
            raise TypeError(
                "If target_dims is a PyTree, all leaves must be dimension "
                "(iterables of ints) or None."
            )

        self.target_dims = target_dims

    @property
    def name(self) -> str:
        return f"Reshape(target_dims={self.target_dims})"

    def is_ready(self) -> bool:
        return True

    def get_num_trainable_floats(self) -> int | None:
        return 0

    def _get_callable(
        self,
    ) -> ModuleCallable:
        @jaxtyped(typechecker=beartype)
        def apply_reshape(
            tensor: ArrayData,
            dims: ArrayDataShape | None,
        ) -> ArrayData:
            batch_size = tensor.shape[0]
            if dims is None:
                return tensor
            else:
                return np.reshape(tensor, (batch_size, *dims))

        @jaxtyped(typechecker=beartype)
        def reshape_forward(
            parameters: Params,
            inputs: Data,
            is_training: bool,
            internal_state: State,
            random_key: Any,
        ) -> Tuple[Data, State]:
            if self.target_dims is None:
                return inputs, internal_state
            else:
                transformed_data = jax.tree.map(
                    apply_reshape,
                    inputs,
                    self.target_dims,
                )
                return transformed_data, internal_state

        return reshape_forward

    def validate_and_concretify_dims(
        self, input_dims: DataShape
    ) -> DataShape:
        # Verify compatibility between input_dims and target_dims
        if self.target_dims is None:
            return input_dims

        assert input_dims is not None, "Input dimensions must not be None."
        assert not (None in input_dims), "Input dimensions must not contain None."

        try:
            len(input_dims)
        except TypeError:
            raise TypeError(
                "Input dimensions must be a tuple, list, or PyTree of dimensions."
            )

        was_promoted = False

        # Promote scalar shape to tuple for consistency
        if all(isinstance(d, int) for d in input_dims):
            input_dims = (input_dims,)
            was_promoted = True

        # Same promotion for target_dims
        if all(isinstance(d, int) for d in self.target_dims):
            target_dims_local = (self.target_dims,)
        else:
            target_dims_local = self.target_dims

        # Verify tree structures match
        input_tree = jax.tree.structure(input_dims, is_leaf=is_shape_leaf)
        target_tree = jax.tree.structure(target_dims_local, is_leaf=is_shape_leaf)
        assert input_tree == target_tree, (
            f"Input dimensions structure {input_tree} does not match target "
            f"dimensions structure {target_tree}"
        )

        def verify_and_resolve_dims(
            actual_dim: ArrayDataShape,
            desired_dim: ArrayDataShape | None,
        ) -> ArrayDataShape:
            if desired_dim is None:
                return actual_dim

            current_volume = np.prod(np.array(actual_dim)).item()

            if -1 in desired_dim:
                # Ensure exactly one -1 exists
                assert (
                    desired_dim.count(-1) == 1
                ), "Target dimension can only contain one -1 position"

                # Calculate inferred dimension
                fixed_product = 1
                for dim in desired_dim:
                    if dim != -1:
                        fixed_product *= dim

                resolved_dim = current_volume // fixed_product
                final_volume = fixed_product * resolved_dim
            else:
                final_volume = np.prod(np.array(desired_dim)).item()

            assert current_volume == final_volume, (
                f"Input dimensions {actual_dim} incompatible with target "
                f"dimensions {desired_dim}"
            )

            if -1 in desired_dim:
                return tuple(
                    resolved_dim if d == -1 else d for d in desired_dim
                )
            else:
                return desired_dim

        concrete_dims = jax.tree.map(
            verify_and_resolve_dims,
            input_dims,
            target_dims_local,
            is_leaf=is_shape_leaf,
        )

        if was_promoted:
            return concrete_dims[0]
        else:
            return concrete_dims

    def compile(self, rng: Any, input_dims: DataShape) -> None:
        self.validate_and_concretify_dims(input_dims)

    def get_output_dims(self, input_dims: DataShape) -> DataShape:
        return self.validate_and_concretify_dims(input_dims)

    def get_hyperparameters(self) -> HyperParams:
        return {
            "target_dims": self.target_dims,
        }

    def get_params(self) -> Params:
        return ()

    def set_params(self, params: Params) -> None:
        pass
